class _LazyModule:
    """Import a route-specific module only when one of its helpers is used."""

    __slots__ = ("_name", "_module")

    def __init__(self, name):
        self._name = name
        self._module = None

    def _load(self):
        module = self._module
        if module is None:
            # ``fromlist`` makes dotted stdlib names (notably urllib.parse)
            # resolve to the requested leaf module instead of their package.
            module = __import__(self._name, fromlist=("*",))
            bind_runtime = getattr(module, "_bind_runtime", None)
            if bind_runtime is not None:
                # Resolve shared Worker/D1 primitives on first route use.
                bind_runtime(globals())
            self._module = module
        return module

    def __getattr__(self, name):
        return getattr(self._load(), name)

    def export(self, name):
        """Return one lazily resolved module binding."""
        return _LazyExport(self, name)


class _LazyExport:
    """Transparent callable/attribute proxy for a lazily imported symbol."""

    __slots__ = ("_module", "_name")

    def __init__(self, module, name):
        self._module = module
        self._name = name

    def _load(self):
        return getattr(self._module, self._name)

    def __call__(self, *args, **kwargs):
        return self._load()(*args, **kwargs)

    def __getattr__(self, name):
        return getattr(self._load(), name)

    def __bool__(self):
        return bool(self._load())

    def __iter__(self):
        return iter(self._load())

    def __len__(self):
        return len(self._load())

    def __getitem__(self, key):
        return self._load()[key]

    def __contains__(self, item):
        return item in self._load()

    def __eq__(self, other):
        return self._load() == other

    def __hash__(self):
        return hash(self._load())

    def __repr__(self):
        return repr(self._load())

    def __str__(self):
        return str(self._load())


