# Largest git-req-chunk (push pack fragment) forwarded to the host in one WS
# message; matches the host's 256 KiB git-chunk ceiling so neither side trips
# the relay's ~1 MiB message cap.
GIT_REQ_CHUNK = 256 * 1024
TUNNEL_TIMEOUT_MS = 20000
HOST_COUNT_TIMEOUT_MS = 5000
GIT_ADVERTISE_TIMEOUT_MS = 15000
GIT_ADVERTISE_ROUTE_TIMEOUT_MS = 20000
# Most files one /blobs batch may read. One batched request replaces the
# website's per-record /blob fan-out (50+ parallel HTTP calls per page view,
# which tripped the per-repo rate limit); the DO spreads the reads over the
# live tunnel concurrently instead.
MAX_BLOB_BATCH = 60
# Aggregate homepage/network stats. Cached at the edge so a burst of visitors
# costs one computation per colo per TTL instead of a Durable Object fan-out per
# visit. The flagship room whose live client count the homepage shows.
# Seconds the /api/network/stats response is cached at the edge. The desktop
# Nodes rail polls it every 60s and the homepage every 5 min, so one origin
# rebuild per colo per minute is the most any client can observe; at 20s a
# handful of desktops in one colo rebuilt it (and its COUNT(*) scan) three
# times a minute.
NETWORK_STATS_TTL = 60
# The leaderboards and online-history boards change only when the ten-minute
# online-sample phase writes, and the five-minute snapshot-network rebuild
# already purges and republishes them; their edge copies may live 5 minutes.
NETWORK_LEADERBOARDS_TTL = 300
ONLINE_HISTORY_TTL = 300
FLAGSHIP_ROOM_KEY = "repo:mainnode/forkmesh:room:general"
PUBLIC_WORLD_GENERAL_ROOM = "world-general"
PUBLIC_WORLD_GENERAL_ROOM_KEY = (
    "repo:mainnode/forkmesh:room:" + PUBLIC_WORLD_GENERAL_ROOM
)
# A host counts as "online" if it has been active within this window. The window
# self-heals presence rows orphaned by a host that vanished without a clean close;
# active hosts refresh their row at most once per HOST_PRESENCE_REFRESH_MS.
HOST_PRESENCE_STALE_MS = 10 * 60 * 1000
HOST_PRESENCE_REFRESH_MS = 60 * 1000
# Public Git availability is now proven by signed, server-observed direct HTTPS
# endpoint checks. This window intentionally matches the old presence headline
# so the status page's semantics remain stable while its evidence gets stronger.
HTTPS_MIRROR_STATUS_FRESH_MS = 10 * 60 * 1000
# Registered desktop/headless node accounts older than this are no longer
# considered live. Liveness is transient routing evidence, not a catalog
# retention policy: owner-signed repository rows remain visible as offline.
# Housekeeping may remove an old physical node row only when it has neither a
# repository catalog row nor a registered direct-HTTPS endpoint.
REGISTERED_NODE_ACTIVE_MS = 60 * 60 * 1000
STALE_NODE_PURGE_INTERVAL_MS = 60 * 1000
STALE_NODE_PURGE_BATCH = 10
# Reinstalling or rotating a desktop node's key mints a NEW account_devices row
# (device_bi is keyed on the pubkey), so one account slowly accretes a row per
# historical key — the DB side of the "one person, many identities" sprawl. A
# device untouched for this long is pruned, but only when the account still has a
# newer key to sign with, so a node's live/most-recent key (the one the drain
# gate now reuses; see _owner_signing_pubkeys) is never removed.
STALE_DEVICE_RETAIN_MS = 60 * 24 * 60 * 60 * 1000  # 60 days
STALE_DEVICE_PURGE_BATCH = 12
# How long a downed repo's clone traffic stays pinned to one chosen mirror (see
# clone_sticky). Long enough that a clone's info/refs and upload-pack POST land
# on the same node; short enough that the load still rotates across mirrors.
CLONE_STICKY_MS = 5 * 60 * 1000


# Public node name = username = a single DNS-like label: lowercase letters,
# digits, and hyphens; must start with a letter and end with a letter or digit;
# no underscores, no spaces, <= 63 chars. This is the user's public handle and
# their repo namespace, so it is validated identically in the web and desktop
# clients.
NODE_NAME_RE = re.compile(r"^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$")
MENTION_RE = re.compile(r"(?<![A-Za-z0-9._%+-])@([a-z](?:[a-z0-9-]{0,61}[a-z0-9])?)\b")
DOMAIN_NAME_RE = re.compile(
    r"^(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$")
ACCOUNT_EMAIL_LOCAL_RE = re.compile(r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+$")
MASTODON_HANDLE_RE = re.compile(
    r"^@?[A-Za-z0-9_](?:[A-Za-z0-9_.-]{0,62}[A-Za-z0-9_])?@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$")
MAX_NODE_NAME = 63

# A node's Ed25519 public key (raw 32 bytes, base64url, unpadded) — the value
# the desktop app's profile card itself labels "Node ID". The claim-node flow
# (issue #351) accepts this as an alternative to the account's chosen name,
# since that's what users copy when the app tells them their "node ID".
NODE_PUBKEY_RE = re.compile(r"^[A-Za-z0-9_-]{43}$")
# ACCOUNTS_RE is imported from urls.py with the rest of the route table.
LOGIN_MAX_SKEW_MS = 5 * 60 * 1000
# Login brute-force throttle: after LOGIN_MAX_FAILS failures (counted within a
# rolling window) the identifier is locked out for LOGIN_LOCKOUT_MS.
LOGIN_MAX_FAILS = 10
LOGIN_FAIL_WINDOW_MS = 15 * 60 * 1000
LOGIN_LOCKOUT_MS = 15 * 60 * 1000
# Per-source-IP account-creation throttle: at most SIGNUP_MAX_PER_IP new accounts
# from one IP per rolling SIGNUP_RATE_WINDOW_MS, to blunt mass signup / name
# squatting. Login has its own lockout; catalog writes have their own cooldown.
SIGNUP_RATE_WINDOW_MS = 60 * 60 * 1000
SIGNUP_MAX_PER_IP = 5
SIGNUP_BACKUP_MAX_PER_IP = 10
SIGNUP_BACKUP_MAX_PER_WINDOW = 60
SIGNUP_BACKUP_RATE_KEY = "signup-backup-v1"
ADMIN_SESSION_TTL_MS = 12 * 60 * 60 * 1000
# How long a password-reset link stays valid after it is emailed.
PASSWORD_RESET_TTL_MS = 60 * 60 * 1000
PASSWORD_RESET_ACCOUNT_COOLDOWN_MS = 10 * 60 * 1000
PASSWORD_RESET_ACCOUNT_WINDOW_MS = 24 * 60 * 60 * 1000
PASSWORD_RESET_ACCOUNT_WINDOW_LIMIT = 5
PASSWORD_RESET_REQUESTER_WINDOW_MS = 60 * 60 * 1000
PASSWORD_RESET_REQUESTER_WINDOW_LIMIT = 10
# An IPv6 requester spends its budget per /64, not per address. A /64 is the
# smallest block a provider routes to one customer, so an attacker there mints
# fresh per-address budgets for free and the requester limit would only ever
# bind on IPv4 (issue #624).
PASSWORD_RESET_REQUESTER_V6_PREFIX = 64
PASSWORD_RESET_BACKUP_RATE_KEY = "password-reset-backup-v1"
PASSWORD_RESET_BACKUP_MAX_PER_IP = 10
PASSWORD_RESET_BACKUP_MAX_PER_WINDOW = 60
PASSWORD_RESET_BACKUP_CDATA_TTL_MS = 30 * 60 * 1000
# Users-vs-nodes linking (adhoc #53). A website claim's confirmation code (shown
# on the node, typed into the site) lives this long; an installer link code
# (shown by install.sh, typed into the installing desktop app) lives longer
# because the fresh node still has to build/launch/register before it can
# present the code.
CLAIM_CODE_TTL_MS = 10 * 60 * 1000
CLAIM_CODE_MAX_ATTEMPTS = 5
# An admin-initiated ownership takeover (adhoc #141) rides back to the target
# node on its own heartbeat, same as a claim code, but the node may be offline
# for a while before it's seen and approved/denied, so it gets a long window.
OWNERSHIP_TRANSFER_TTL_MS = 24 * 60 * 60 * 1000
LINK_CODE_TTL_MS = 30 * 60 * 1000
LINK_CODE_RE = re.compile(r"^[0-9]{6}$")
LINK_INSTALL_COOLDOWN_MS = 10 * 1000
LINK_GRANT_MAX_AGE_MS = 5 * 60 * 1000
LINK_GRANT_MAX_FUTURE_MS = 60 * 1000
LINK_GRANT_NONCE_RE = re.compile(r"^[A-Za-z0-9_-]{16,64}$")
MAX_AVATAR_BYTES = 256 * 1024
MAX_AVATAR_B64 = 4 * ((MAX_AVATAR_BYTES + 2) // 3)
# A stored avatar was validated as base64 PNG on the way in, but anything that
# ends up inside an ``<img src="data:...">`` attribute is re-checked against
# the base64 alphabet at render time: that is the one place a malformed record
# could otherwise close the attribute and inject markup.
AVATAR_B64_RE = re.compile(r"^[A-Za-z0-9+/]+={0,2}$")
PNG_HEADER = b"\x89PNG\r\n\x1a\n"
# Repo branding (fediverse actor avatar/header). Each image lives in its own
# encrypted repo_media row, so the caps only need to keep ONE image (b64 +
# AES-GCM + b64 again ≈ 1.8x raw) under D1's 2 MB per-value limit.
MAX_REPO_LOGO_BYTES = 256 * 1024
MAX_REPO_BANNER_BYTES = 1024 * 1024


def valid_node_name(value):
    value = (value or "").strip()
    return (bool(value) and len(value) <= MAX_NODE_NAME and
            bool(NODE_NAME_RE.match(value)))


def valid_account_email(value):
    """Validate the practical mailbox form accepted for account email."""
    if not isinstance(value, str) or not value or len(value) > 254:
        return False
    local, separator, domain = value.rpartition("@")
    return (bool(separator) and "@" not in local and len(local) <= 64 and
            not local.startswith(".") and not local.endswith(".") and
            ".." not in local and bool(ACCOUNT_EMAIL_LOCAL_RE.match(local)) and
            bool(DOMAIN_NAME_RE.match(domain)))


def _moderation_forms(value):
    """Canonical lookup forms without retaining the source vocabulary."""
    value = str(value or "").strip().lower()
    leet = value.translate(str.maketrans({
        "0": "o", "1": "i", "3": "e", "4": "a", "5": "s",
        "7": "t", "8": "b", "9": "g",
    }))
    pieces = [piece for piece in re.split(r"[^a-z]+", leet) if piece]
    forms = set(pieces)
    if pieces:
        forms.add("".join(pieces))
    for form in tuple(forms):
        forms.add(re.sub(r"(.)\1+", r"\1", form))
    return {form for form in forms if len(form) in BLOCKED_TERM_LENGTHS}


def username_has_blocked_term(value):
    return any(
        hashlib.sha256(form.encode("utf-8")).hexdigest()
        in BLOCKED_TERM_HASHES
        for form in _moderation_forms(value)
    )


async def _username_ai_blocked(env, username, system_prompt="", model=""):
    """Return True/False from Workers AI, or None when AI is unavailable.

    Exact local hashes remain effective during a provider outage.  AI is a
    supplemental variant detector, so an outage does not turn account signup
    into a platform-wide availability incident.
    """
    ai = getattr(env, "AI", None)
    if ai is None or js_nullish(ai) or not hasattr(ai, "run"):
        return None
    model = clean_string(model, 120) or clean_string(
        getattr(env, "USERNAME_MODERATION_AI_MODEL", ""), 120
    ) or USERNAME_MODERATION_AI_DEFAULT_MODEL
    schema = {
        "type": "object",
        "properties": {"allowed": {"type": "boolean"}},
        "required": ["allowed"],
        "additionalProperties": False,
    }
    payload = {
        "messages": [
            {
                "role": "system",
                "content": system_prompt or USERNAME_MODERATION_SYSTEM_PROMPT,
            },
            {
                "role": "user",
                "content": "Classify this username: <username>" + username
                + "</username>",
            },
        ],
        "max_tokens": 32,
        "response_format": {
            "type": "json_schema",
            "json_schema": schema,
        },
    }
    try:
        result = await ai.run(model, to_js(payload))
        if hasattr(result, "to_py"):
            result = result.to_py()
        if isinstance(result, dict) and "response" in result:
            result = result.get("response")
        if isinstance(result, str):
            result = json.loads(result)
        if isinstance(result, dict) and isinstance(result.get("allowed"), bool):
            return not result["allowed"]
    except Exception as error:
        await log_error(
            env, 500, "AI", "username/moderation",
            "Username moderation AI call failed (%s): %s"
            % (model, _safe_error_text(error)[:300]))
    return None


async def _username_ai_rejects(env, username):
    """True only when two Workers AI passes agree the username is offensive.

    The confirm pass runs a false-positive-averse prompt on a second, stronger
    model, and only on a name the first pass already flagged, so an ordinary
    signup still costs one small call. An unavailable or undecided second
    opinion (None) is not agreement: the local digest filter stays the layer
    that refuses names on its own.
    """
    if await _username_ai_blocked(env, username) is not True:
        return False
    confirm_model = clean_string(
        getattr(env, "USERNAME_MODERATION_CONFIRM_AI_MODEL", ""), 120
    ) or USERNAME_MODERATION_CONFIRM_AI_DEFAULT_MODEL
    confirmed = await _username_ai_blocked(
        env, username, USERNAME_MODERATION_CONFIRM_PROMPT, confirm_model)
    return confirmed is True


def established_username_moderation_error(username):
    """Deterministic-only check for a name its owner is re-presenting.

    Reserve and finalize are replayed for the life of an install, and a rename
    to the same name is a no-op, so these names were already moderated when
    they were first claimed. Re-running the AI classifier on them lets one
    flipped verdict lock an established owner out of their own node midway
    through a setup they cannot restart under a different name. The digest
    filter is deterministic, so it costs nothing to keep applying.
    """
    if username_has_blocked_term(username):
        return "inappropriate_node_name"
    return ""


async def username_moderation_error(env, username):
    """Full check for a name being claimed for the first time."""
    if username_has_blocked_term(username):
        return "inappropriate_node_name"
    if await _username_ai_rejects(env, username):
        return "inappropriate_node_name"
    return ""


def valid_node_pubkey(value):
    return bool(NODE_PUBKEY_RE.match((value or "").strip()))


def notification_mentions(*parts):
    found = set()
    for part in parts:
        if not part:
            continue
        for match in MENTION_RE.finditer(str(part).lower()):
            name = match.group(1)
            if name and len(name) <= MAX_NODE_NAME and NODE_NAME_RE.match(name):
                found.add(name)
    return sorted(found)


# A ping's body is the message itself — the comment, the issue text — and it
# is what a phone banner shows once pulled open (PUSH_ALERT_BODY_MAX), so it
# keeps as much as the banner can draw rather than a teaser.
NOTIFICATION_BODY_MAX = 900
SECURITY_ALERT_BODY_MAX = 6000


def notification_payload(kind, title, body="", repo="", href="", actor="",
                         source="", ts=0, meta=None):
    kind = kind if kind in NOTIFICATION_KINDS else "pending_inbox"
    return {
        "kind": kind,
        "title": clean_string(title, 160),
        "body": clean_string(body, SECURITY_ALERT_BODY_MAX
                             if kind == "security_alert"
                             else NOTIFICATION_BODY_MAX),
        "repo": clean_string(repo, 180),
        "href": clean_string(href, 512),
        "actor": clean_string(actor, 120),
        "source": clean_string(source, 80),
        "ts": int(ts or 0),
        "readAt": 0,
        "meta": meta if isinstance(meta, dict) else {},
    }


# Organization task activity, in ping copy. The board itself is private to the
# organization, so the ping is the only place most members read the event: it
# has to answer who did it, what they did it to, which organization it belongs
# to and where the task sits, rather than the bare "Organization task activity"
# line it used to carry (adhoc #147).
ORGANIZATION_TASK_ACTION_COPY = {
    "created": "created",
    "started": "started",
    "stopped": "stopped",
    "completed": "completed",
    "returned": "returned",
    "qa requested": "sent to QA",
    "deleted": "deleted",
    "commented": "commented on",
    "checked in going well": "checked in on",
    "checked in blocked": "checked in on",
    "checked in needs help": "checked in on",
}
# "checked in blocked" has to read as a check-in whose state is "blocked", not
# as "blocked on <task>". The state is therefore lifted out of the verb and
# carried as its own detail in the body.
ORGANIZATION_TASK_CHECKIN_COPY = {
    "checked in going well": "check-in: going well",
    "checked in blocked": "check-in: blocked",
    "checked in needs help": "check-in: needs help",
}
ORGANIZATION_TASK_STATUS_COPY = {
    "idle": "not started",
    "active": "in progress",
    "done": "done",
}


def organization_task_ping_copy(org, actor, action, task):
    """Title/body/meta for one organization task activity ping."""
    task = task if isinstance(task, dict) else {}
    org_name = clean_string(org, MAX_NODE_NAME).strip().lower()
    actor_name = clean_string(actor or "", MAX_NODE_NAME).strip().lower()
    who = ("@" + actor_name) if actor_name else "a team member"
    action_slug = clean_string(
        action or "", 32).strip().lower().replace("_", " ")
    verb = ORGANIZATION_TASK_ACTION_COPY.get(
        action_slug, action_slug or "updated")
    task_title = clean_string(
        task.get("title") or "", 160).strip() or "Organization task"
    department = clean_string(
        task.get("department") or "", 64).strip().lower()
    team = clean_string(task.get("team") or "", 64).strip().lower()
    status = clean_string(task.get("status") or "", 32).strip().lower()
    assignee_kind = clean_string(
        task.get("assigneeKind") or "", 32).strip().lower()
    assignee = clean_string(task.get("assignee") or "", 64).strip().lower()
    repository = clean_string(task.get("repository") or "", 201).strip()
    task_id = clean_string(str(task.get("id") or ""), 80)
    try:
        priority = int(task.get("priority"))
    except (TypeError, ValueError):
        priority = 0

    where = (" in " + org_name) if org_name else ""
    # The task name is the only part of the title that can run long, so it is
    # the part trimmed to keep who/what/which-org inside the 160-char cap
    # notification_payload() enforces.
    room = 160 - len("%s %s \"\"%s" % (who, verb, where))
    short_title = (
        task_title if len(task_title) <= max(8, room)
        else task_title[:max(8, room) - 1].rstrip() + "…")
    title = "%s %s \"%s\"%s" % (who, verb, short_title, where)
    lead = (
        "%s %s \"%s\" in the %s organization" % (who, verb, task_title, org_name)
        if org_name
        else "%s %s \"%s\" in your organization" % (who, verb, task_title))
    details = [lead]
    checkin_state = ORGANIZATION_TASK_CHECKIN_COPY.get(action_slug, "")
    if checkin_state:
        details.append(checkin_state)
    placement = " / ".join(
        [part for part in (department, team) if part])
    if placement:
        details.append(placement)
    if priority > 0:
        details.append("priority %d" % priority)
    if assignee_kind == "agent":
        details.append("assigned to an agent")
    elif assignee:
        details.append("assigned to @" + assignee)
    elif assignee_kind == "unassigned":
        details.append("unassigned")
    if status:
        details.append(
            "status " + ORGANIZATION_TASK_STATUS_COPY.get(status, status))
    if repository:
        details.append("repo " + repository)
    return {
        "title": title,
        "body": " · ".join(details),
        "meta": {
            "organization": org_name,
            "actor": actor_name,
            "action": action_slug,
            "taskId": task_id,
            "taskTitle": task_title,
            "department": department,
            "team": team,
            "priority": priority,
            "status": status,
            "assignee": "agent" if assignee_kind == "agent" else assignee,
            "assigneeKind": assignee_kind,
            "repository": repository,
        },
    }


# An @mention is addressed at one person, so its ping says what they were
# named in and quotes enough of the copy to answer "do I need to open this?".
ORGANIZATION_TASK_MENTION_CONTEXT_COPY = {
    "comment": "a comment on",
    "check-in": "a check-in on",
    "task": "the task",
}


def organization_task_mention_copy(org, actor, context, task, excerpt):
    """Title/body/meta for one "you were @mentioned on a task" ping."""
    base = organization_task_ping_copy(org, actor, "mentioned", task)
    org_name = clean_string(org, MAX_NODE_NAME).strip().lower()
    actor_name = clean_string(actor or "", MAX_NODE_NAME).strip().lower()
    who = ("@" + actor_name) if actor_name else "A team member"
    where = ORGANIZATION_TASK_MENTION_CONTEXT_COPY.get(
        clean_string(context or "", 32).strip().lower(), "the task")
    task_title = base["meta"]["taskTitle"]
    room = 160 - len("%s mentioned you in %s \"\"%s" % (
        who, where, (" in " + org_name) if org_name else ""))
    short_title = (
        task_title if len(task_title) <= max(8, room)
        else task_title[:max(8, room) - 1].rstrip() + "…")
    title = "%s mentioned you in %s \"%s\"%s" % (
        who, where, short_title, (" in " + org_name) if org_name else "")
    quote = clean_string(excerpt or "", 240).strip()
    details = [
        "%s mentioned you in %s \"%s\"%s" % (
            who, where, task_title,
            (" in the %s organization" % org_name) if org_name else ""),
    ]
    if quote:
        details.append("“%s”" % quote)
    meta = dict(base["meta"])
    # notification_payload() clamps the body anyway; clamping here keeps the
    # quote from being what silently disappears when a task title runs long.
    body = clean_string(" · ".join(details), 500)
    meta["action"] = "mentioned"
    meta["context"] = clean_string(context or "", 32).strip().lower()
    return {
        "title": title,
        "body": body,
        "meta": meta,
    }


def organization_task_reminder_copy(org, actor, task, note):
    base = organization_task_ping_copy(org, actor, "reminded", task)
    org_name = clean_string(org, MAX_NODE_NAME).strip().lower()
    actor_name = clean_string(actor or "", MAX_NODE_NAME).strip().lower()
    who = ("@" + actor_name) if actor_name else "A team member"
    where = (" in " + org_name) if org_name else ""
    task_title = base["meta"]["taskTitle"]
    room = 160 - len("%s asked you for a check-in on \"\"%s" % (who, where))
    short_title = (
        task_title if len(task_title) <= max(8, room)
        else task_title[:max(8, room) - 1].rstrip() + "…")
    title = "%s asked you for a check-in on \"%s\"%s" % (
        who, short_title, where)
    details = [
        "%s asked how \"%s\" is going%s" % (
            who, task_title,
            (" in the %s organization" % org_name) if org_name else ""),
    ]
    quote = clean_string(note or "", 240).strip()
    if quote:
        details.append("“%s”" % quote)
    details.append("Open the task and check in")
    meta = dict(base["meta"])
    meta["action"] = "reminded"
    meta["context"] = "reminder"
    return {
        "title": title,
        "body": clean_string(" · ".join(details), 500),
        "meta": meta,
    }


def organization_task_persistent_reminder_copy(org, task, every_minutes):
    base = organization_task_ping_copy(org, "", "reminded", task)
    org_name = clean_string(org, MAX_NODE_NAME).strip().lower()
    task_title = base["meta"]["taskTitle"]
    room = 160 - len("Reminder: \"\"")
    short_title = (
        task_title if len(task_title) <= room
        else task_title[:room - 1].rstrip() + "…")
    minutes = max(0, int(every_minutes or 0))
    if minutes and minutes % 1440 == 0:
        cadence = "%d day%s" % (minutes // 1440, "" if minutes == 1440 else "s")
    elif minutes and minutes % 60 == 0:
        cadence = "%d hour%s" % (minutes // 60, "" if minutes == 60 else "s")
    else:
        cadence = "%d minutes" % minutes
    details = [
        "\"%s\" is still open%s" % (
            task_title,
            (" in the %s organization" % org_name) if org_name else ""),
        "This reminder repeats every %s until the task is done "
        "or the reminder is turned off" % cadence,
    ]
    meta = dict(base["meta"])
    meta["action"] = "reminded"
    meta["context"] = "reminder"
    meta["persistent"] = True
    return {
        "title": "Reminder: \"%s\"" % short_title,
        "body": clean_string(" · ".join(details), 500),
        "meta": meta,
    }


def notification_email_preferences(rec):
    prefs = dict(NOTIFICATION_EMAIL_DEFAULTS)
    raw = rec.get("notification_preferences") if isinstance(rec, dict) else {}
    if isinstance(raw, dict):
        for key in NOTIFICATION_EMAIL_KINDS:
            if key in raw:
                prefs[key] = bool(raw.get(key))
    return prefs


def notification_email_enabled(rec, kind):
    kind = clean_string(kind, 40)
    if kind not in NOTIFICATION_EMAIL_DEFAULTS:
        return False
    return bool(notification_email_preferences(rec).get(kind))


def _clean_notification_preferences(raw, rec=None):
    prefs = notification_email_preferences(rec or {})
    if not isinstance(raw, dict):
        return prefs
    for key in NOTIFICATION_EMAIL_KINDS:
        if key in raw:
            prefs[key] = bool(raw.get(key))
    return prefs


def notification_delivery_mode(rec):
    """How this account wants its notification email paced.

    "digest" rolls the unread ones into one message per interval; "instant"
    sends each notification on its own as soon as the cron sees it. The default
    is stored as an absent key, the same shape as email_notifications, so an
    untouched record keeps digesting.
    """
    raw = rec.get("notification_delivery") if isinstance(rec, dict) else ""
    mode = clean_string(raw or "", 20).strip().lower()
    return (mode if mode in NOTIFICATION_DELIVERY_MODES
            else NOTIFICATION_DELIVERY_DEFAULT)


def notification_email_immediate(payload):
    payload = payload if isinstance(payload, dict) else {}
    kind = clean_string(payload.get("kind", ""), 40)
    source = clean_string(payload.get("source", ""), 80)
    meta = payload.get("meta")
    context = clean_string(
        meta.get("context", "") if isinstance(meta, dict) else "", 32)
    return (kind in NOTIFICATION_IMMEDIATE_KINDS
            or source in NOTIFICATION_IMMEDIATE_SOURCES
            or context in NOTIFICATION_IMMEDIATE_CONTEXTS)


def _notification_immediate_watermark(rec):
    stored = rec.get("last_immediate_ts")
    if stored is None:
        stored = rec.get("last_digest_ts", 0)
    return int(stored or 0)


def _apply_notification_delivery(rec, raw):
    """Store a requested delivery mode; True when the record actually changed."""
    mode = clean_string(raw or "", 20).strip().lower()
    if mode not in NOTIFICATION_DELIVERY_MODES:
        mode = NOTIFICATION_DELIVERY_DEFAULT
    if notification_delivery_mode(rec) == mode:
        return False
    if mode == NOTIFICATION_DELIVERY_DEFAULT:
        rec.pop("notification_delivery", None)
    else:
        rec["notification_delivery"] = mode
    return True


def ping_pause_until(rec):
    """Millisecond deadline this account's pings are paused to, else 0.

    "Pause notifications" is a snooze, not an opt-out: while the deadline is
    in the future the relay still files every ping, so the inbox and bell badge
    carry them, but no email or desktop notification card is raised. An absent
    key is the untouched default, the same shape as
    email_notifications and notification_delivery.
    """
    try:
        until = int((rec or {}).get("notification_pause_until") or 0)
    except (TypeError, ValueError):
        return 0
    return until if until > 0 else 0


def pings_paused(rec, now=0):
    """True while this account is inside its pause window or quiet hours."""
    now = int(now or Date.now())
    if ping_pause_until(rec) > now:
        return True
    quiet_until = globals().get("ping_quiet_until")
    return bool(callable(quiet_until) and quiet_until(rec, now))


def _apply_ping_pause(rec, raw):
    """Store a requested pause deadline; True when the record actually changed.

    A deadline at or before now is how every client says "resume" — there is no
    separate verb — so it stores absence rather than a stale timestamp. The cap
    keeps a mistyped or hostile deadline from muting an account's email
    indefinitely; a pause is meant to be waited out, and the longest offered
    preset is a week.
    """
    try:
        until = int(raw or 0)
    except (TypeError, ValueError):
        return False
    now = int(Date.now())
    until = 0 if until <= now else min(until, now + PING_PAUSE_MAX_MS)
    if ping_pause_until(rec) == until:
        return False
    if until:
        rec["notification_pause_until"] = until
    else:
        rec.pop("notification_pause_until", None)
    return True



def repo_web_href(owner, repo):
    # Clean, shareable repo link (/owner/repo) for notification "Open context"
    # buttons. 404.html bounces this to the dashboard's repo view and dashboard.js
    # keeps the clean path in the address bar, so links read forkmesh.com/owner/repo
    # rather than the old forkmesh.com/dashboard?repo=owner/repo form.
    return "/" + quote(owner) + "/" + quote(repo)


# The signed-event crypto + canonical-content helpers (b64url_decode,
# ed25519_verify, sha256_hex, the verify_* verifiers and *_content
# canonicalizers) were extracted into events.py (adhoc #279); imported above.


def git_bytes_response(data, content_type):
    return JsResponse.new(
        # Copy into a JS-owned buffer: a bare _to_js(bytes) is a view into
        # Python's WASM memory, and the client streams this body AFTER the
        # handler returns and the GIL is released — reading the view then is a
        # runtime crash ("PyProxy when Python GIL not held"), not an exception,
        # and it poisons the isolate for every later invocation (incl. cron).
        Uint8Array.new(_to_js(bytes(data))),
        to_js(
            {
                "status": 200,
                "headers": {
                    "content-type": content_type,
                    "cache-control": "no-cache, max-age=0, must-revalidate",
                },
            }
        ),
    )


def to_js(value):
    return _to_js(value, dict_converter=Object.fromEntries)


async def js_fetch_with_timeout(resource, init, timeout_seconds):
    """Fetch with a Workers-native timeout and no nested Pyodide task."""
    options = dict(init or {})
    options["signal"] = JsAbortSignal.timeout(
        max(1, int(float(timeout_seconds) * 1000)))
    return await js_fetch(resource, to_js(options))


async def js_fetch_until_response(resource, init, timeout_seconds):
    """Bound response headers without putting the same deadline on its body.

    ``AbortSignal.timeout`` remains attached for the lifetime of a fetch. That
    is desirable for small buffered responses, but it truncates a Git pack
    after the header timeout even when the mirror is still producing bytes or
    Cloudflare is applying downstream backpressure. A cancellable native timer
    keeps the no-concurrent-Pyodide-task guarantee while limiting only the wait
    for response headers. Established pack-stream inactivity is guarded at the
    mirror process, where host progress can be distinguished from a blocked
    downstream socket.
    """
    options = dict(init or {})
    controller = JsAbortController.new()
    options["signal"] = controller.signal
    timer = js_set_timeout(
        controller.abort.bind(controller),
        max(1, int(float(timeout_seconds) * 1000)),
    )
    try:
        return await js_fetch(resource, to_js(options))
    finally:
        js_clear_timeout(timer)


async def js_fetch(resource, init=None):
    """Count every external fetch made by a bounded maintenance phase."""
    _cron_subrequest_charge()
    if init is None:
        return await _js_fetch(resource)
    return await _js_fetch(resource, init)


async def _discard_response_body(response):
    try:
        body = getattr(response, "body", None)
        if body is None or js_nullish(body):
            return
        await body.cancel()
    except Exception:
        pass


def new_socket_id():
    # Stable per-socket id stored in the hibernation attachment, so we can skip
    # the sender on broadcast without relying on object identity (which does not
    # survive a Durable Object eviction).
    rnd = js_crypto.getRandomValues(Uint8Array.new(4))
    return "%d-%d" % (int(Date.now()),
                      (rnd[0] << 24) | (rnd[1] << 16) | (rnd[2] << 8) | rnd[3])


def new_world_peer_id():
    # World ids are random per connection and deliberately contain no account,
    # node, address, timestamp, or device identifier. Use the full 128-bit
    # peer-id allowance so even a long-lived room cannot plausibly collide two
    # controllers and merge their movement streams.
    rnd = js_crypto.getRandomValues(Uint8Array.new(16))
    return "".join("%02x" % int(rnd[index]) for index in range(16))


def _ws_attachment(ws):
    try:
        return ws.deserializeAttachment()
    except Exception:
        return None


def _ws_attr(ws, name, default=None):
    att = _ws_attachment(ws)
    if att is None:
        return default
    value = getattr(att, name, default)
    return default if value is None else value


def json_response(data, status=200, cache_seconds=None, cache_control=None,
                  extra_headers=None):
    headers = {"content-type": "application/json; charset=utf-8"}
    if cache_control is not None:
        headers["cache-control"] = cache_control
    elif cache_seconds is not None:
        # Lets both the Cloudflare edge cache (via the Cache API) and the browser
        # reuse this response for cache_seconds, collapsing repeated polls.
        headers["cache-control"] = "public, max-age=%d" % cache_seconds
    if extra_headers:
        headers.update(extra_headers)
    # Compact separators: pretty-printing every API reply cost measurable
    # Pyodide CPU and bytes on hot paths (/api/sync, catalog) — a real factor
    # in the 2026-07-11 free-plan 1102 overload.
    return Response(json.dumps(data, separators=(",", ":")),
                    status=status, headers=headers)


class RequestBodyTooLarge(BaseException):
    """Control-flow signal that bypasses route-local invalid-JSON handlers."""


_request_bodies = _LazyModule("request_bodies")
bounded_request_text = _request_bodies.export("bounded_request_text")
bounded_json_request = _request_bodies.export("bounded_json_request")
_json_request_limit = _request_bodies.export("_json_request_limit")


def _legacy_custody_not_ready_response():
    """Public, identity-free readiness failure for an upgraded legacy D1."""
    return json_response({
        "ok": False,
        "status": "not_ready",
        "error": "legacy_custody_migration_required",
        "custody": "offline-reconciliation-required",
        "notice": (
            "This upgraded instance cannot enable its D1-backed API while "
            "historical wallet material remains. The operator must use the "
            "documented offline export, finalized zero-balance reconciliation "
            "and explicit scrub; this response exposes no key, address, "
            "account, repository or balance."
        ),
    }, status=503, cache_control="no-store, max-age=0, must-revalidate")


# --- Edge cache (Cache API) helpers -----------------------------------------
# Dynamic Worker responses are not edge-cached automatically; we cache the few
# read-heavy aggregate endpoints explicitly so a burst of visitors collapses to
# one origin computation per colo per TTL. Keys are synthetic absolute URLs.

async def edge_cache_match(cache_key):
    try:
        _cron_subrequest_charge()
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    return Response(hit) if hit is not None else None


async def edge_cache_put(cache_key, response):
    # cache.put consumes the body it is handed, so store a clone and return the
    # original to the caller. Accepts both the workers.Response wrapper and a
    # raw JS Response (the binary media endpoints build the latter).
    # Best-effort: a cache failure must not fail the read.
    try:
        js_resp = getattr(response, "js_object", None) or response
        _cron_subrequest_charge()
        await js_caches.default.put(cache_key, js_resp.clone())
    except Exception:
        pass


def uncached_status_response(response, snapshot_state=None):
    """Prevent the public status body from outliving its minute evidence.

    The synthetic Cache API entry remains reusable inside the Worker while its
    published status evidence is useful. Only the response leaving the Worker
    is rewritten. The explicit Cloudflare header is intentional: a legacy
    cache-everything rule can turn ``max-age=0`` into a four-hour edge object
    unless the CDN is told not to store it. A caller may relabel an older cache
    hit as emergency-stale without mutating the stored response.
    """
    try:
        excluded = {
            "cache-control", "cdn-cache-control",
            "cloudflare-cdn-cache-control",
        }
        if snapshot_state is not None:
            excluded.update(("x-forkmesh-public-snapshot", "warning"))
        headers = [
            (str(name).lower(), value)
            for name, value in response.headers.items()
            if str(name).lower() not in excluded
        ]
        headers.extend((
            ("cache-control", "no-store, max-age=0, must-revalidate"),
            ("cdn-cache-control", "no-store"),
            ("cloudflare-cdn-cache-control", "no-store"),
        ))
        if snapshot_state is not None:
            headers.append(("x-forkmesh-public-snapshot", snapshot_state))
            if snapshot_state != "fresh":
                headers.append((
                    "warning",
                    '110 - "Serving last known status while live sampling '
                    'recovers"',
                ))
        return Response(
            response.body,
            status=int(getattr(response, "status", 200) or 200),
            status_text=str(getattr(response, "status_text", "") or ""),
            headers=headers,
        )
    except BaseException:
        # Tests and internal projections may use an already-decoded mapping.
        # It has no HTTP cache metadata and is safe to return unchanged.
        return response


async def edge_cache_match_media(cache_key, fallback_type):
    # Binary edge-cache read for the media endpoints, which respond with raw
    # JS Responses rather than the workers.Response wrapper the JSON helpers
    # return. Rebuilt like git_advert_cache_get so the body streams cleanly.
    try:
        _cron_subrequest_charge()
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    if hit is None:
        return None
    try:
        ctype = hit.headers.get("content-type")
        ccontrol = hit.headers.get("cache-control")
    except Exception:
        ctype, ccontrol = None, None
    return JsResponse.new(hit.body, to_js({
        "status": 200,
        "headers": {
            "content-type": ctype or fallback_type,
            "cache-control": ccontrol or "public, max-age=86400",
        },
    }))


EDGE_CACHE_EPOCHS = {}


def edge_cache_epoch(cache_key):
    return EDGE_CACHE_EPOCHS.get(cache_key, 0)


def _host_background(env, key, factory):
    schedule = getattr(env, "HOST_BACKGROUND", None)
    if schedule is None:
        return False
    try:
        return bool(schedule(key, factory))
    except Exception:
        return False


def _host_single_flight(env):
    schedule = getattr(env, "HOST_BACKGROUND", None)
    return getattr(schedule, "join", None) if schedule is not None else None


async def edge_cache_delete(cache_key):
    EDGE_CACHE_EPOCHS[cache_key] = EDGE_CACHE_EPOCHS.get(cache_key, 0) + 1
    try:
        _cron_subrequest_charge()
        await js_caches.default.delete(cache_key)
    except Exception:
        pass


# Seconds a clone ref-advertisement (info/refs) is held in the colo edge cache.
# The cache key already carries the repo's attested state hash, so an entry
# self-invalidates the instant the refs change (its key stops being requested);
# this TTL is only a backstop that lets a colo re-fetch if a state-hash update is
# ever missed. See git_advert_cache_key and Default._clone_advert_cache_key.
GIT_ADVERT_CACHE_TTL = 300
# Repository-page JSON is persisted in Workers KV and cached at the edge under
# an owner-attested refs digest. The digest changes whenever any published ref
# changes, so these immutable values never need a time-based expiry: a new
# commit produces a new key and the prior generation becomes unreachable.
REPOSITORY_METADATA_CACHE_TTL = 365 * 24 * 60 * 60
# A named ref ("forkmesh/pulls", "main", or none) moves without changing the
# attested pins whenever the pins themselves stop advancing: the flagship
# source has not published its own refs state since 2026-08-12, and when the
# mirror quorum stalls the pin set freezes while the mirrors keep syncing. The
# pull ledger's tree was then served from a September 13 entry for a day, so
# the website listed yesterday's pulls. Entries addressed by a named ref are
# therefore also bucketed by time; commit-addressed reads stay immutable.
REPOSITORY_METADATA_NAMED_REF_WINDOW_MS = 60 * 1000
REPOSITORY_METADATA_CACHE_MAX_BYTES = 8 * 1024 * 1024
REPOSITORY_METADATA_CACHE_PREFIX = (
    "https://forkmesh.internal/repository-metadata/v3/"
)
REPOSITORY_METADATA_FALLBACK_PREFIX = (
    "https://forkmesh.internal/repository-metadata-fallback/v1/"
)


async def git_advert_cache_get(cache_key):
    # Return a cached clone advertisement as a fresh no-cache response. git must
    # re-validate info/refs on every fetch, so the bytes handed to the client
    # keep git's own no-store semantics even though the edge copy is reused.
    try:
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    if hit is None:
        return None
    try:
        ctype = hit.headers.get("content-type")
    except Exception:
        ctype = None
    return JsResponse.new(hit.body, to_js({
        "status": 200,
        "headers": {
            "content-type": ctype or "application/x-git-upload-pack-advertisement",
            "cache-control": "no-cache, max-age=0, must-revalidate",
        },
    }))


async def git_advert_cache_put(cache_key, response, ttl=GIT_ADVERT_CACHE_TTL):
    # Store a cacheable clone of the advertisement. The live response carries
    # git's "no-cache, max-age=0" headers, which the Cache API refuses to store,
    # so the stored copy is rebuilt with a public max-age; the original response
    # is returned to the client untouched. Best-effort — a cache failure must not
    # fail the clone.
    try:
        js_resp = getattr(response, "js_object", None) or response
        clone = js_resp.clone()
        try:
            ctype = clone.headers.get("content-type")
        except Exception:
            ctype = None
        cacheable = JsResponse.new(clone.body, to_js({
            "status": 200,
            "headers": {
                "content-type": ctype
                or "application/x-git-upload-pack-advertisement",
                "cache-control": "public, max-age=%d" % ttl,
            },
        }))
        await js_caches.default.put(cache_key, cacheable)
    except Exception:
        pass


def repository_metadata_cache_key(
        context, operation, query, fallback=False, now=None):
    """Key public repo-page JSON by the current owner-attested refs state.

    This deliberately admits only the repository overview and collaboration
    records rendered by the web UI. Arbitrary source files, raw downloads,
    private routes, and write operations never enter KV. Named branches are
    safe here because ``currentPins`` authenticates the complete refs set and
    therefore changes the key before a moved branch can reuse old content.
    """
    if not isinstance(context, dict) or not isinstance(query, dict):
        return ""
    pins = sorted({
        str(pin).lower()
        for pin in context.get("currentPins", set())
        if re.fullmatch(r"[0-9a-f]{64}", str(pin).lower())
    })
    repo_bi = str(context.get("repoBi") or "")
    if not pins or not repo_bi:
        return ""
    # Git refs are case-sensitive; preserve their spelling in the key.
    ref = str(query.get("ref") or "").strip()
    if (
        ref
        and (
            len(ref) > 200
            or ref.startswith("-")
            or ".." in ref
            or "@{" in ref
            or ref.endswith(".")
            or not re.fullmatch(r"[A-Za-z0-9._/-]+", ref)
        )
    ):
        return ""

    def cacheable_tree_path(path):
        return path in {
            "", ".forkmesh/pulls", ".forkmesh/issues",
            ".forkmesh/issues/open", ".forkmesh/issues/closed",
            ".forkmesh/discussions", ".forkmesh/releases",
        } or bool(re.fullmatch(
            r"\.forkmesh/(?:pulls|discussions)/[1-9][0-9]{0,8}",
            path,
        ))

    def cacheable_blob_path(path):
        return bool(
            re.fullmatch(r"(?i:readme(?:\.(?:md|txt|rst))?)", path)
            or path == ".forkmesh/info.json"
            or re.fullmatch(
                r"\.forkmesh/issues/(?:open/|closed/)?"
                r"[1-9][0-9]{0,8}/issue-[1-9][0-9]{0,8}\.json",
                path,
            )
            or re.fullmatch(
                r"\.forkmesh/discussions/[1-9][0-9]{0,8}/"
                r"(?:discussion\.md|[0-9]{1,12}-comment\.md)",
                path,
            )
            or re.fullmatch(
                r"\.forkmesh/pulls/[1-9][0-9]{0,8}/"
                r"(?:pull\.md|changes\.patch|[0-9]{1,12}-[^/]{1,180})",
                path,
            )
            or re.fullmatch(
                r"\.forkmesh/releases/[A-Za-z0-9._-]{1,100}/release\.json",
                path,
            )
        )

    canonical_query = {}
    if operation == "branches" and not query:
        pass
    elif operation == "tree":
        path = str(query.get("path") or "")
        if not cacheable_tree_path(path):
            return ""
        canonical_query = {"path": path, "ref": ref}
    elif operation == "history" and query.get("path"):
        return ""
    elif operation in {"sizes", "stats", "history"} and ref:
        canonical_query = {"ref": ref}
    elif operation == "blob" and ref:
        path = str(query.get("path") or "")
        if not cacheable_blob_path(path):
            return ""
        canonical_query = {"path": path, "ref": ref}
    elif operation == "blobs" and ref:
        paths = query.get("path")
        if not isinstance(paths, list) or not 1 <= len(paths) <= MAX_BLOB_BATCH:
            return ""
        normalized_paths = sorted(set(str(path) for path in paths))
        if (
            len(normalized_paths) != len(paths)
            or any(not cacheable_blob_path(path) for path in normalized_paths)
        ):
            return ""
        canonical_query = {"path": normalized_paths, "ref": ref}
    else:
        return ""
    # Only a full commit id names immutable bytes. Any other spelling (a branch,
    # the default branch, or the branch list itself) is resolved at read time,
    # so its entry expires with the window. The outage fallback keeps no
    # window: it exists to serve the last attested view while mirrors fail.
    window = None
    if (
        not fallback
        and now is not None
        and not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", ref)
    ):
        window = int(now) // REPOSITORY_METADATA_NAMED_REF_WINDOW_MS
    digest = hashlib.sha256(json.dumps(
        {
            "repoBi": repo_bi,
            **({"window": window} if window is not None else {}),
            # The normal key changes with every signed refs generation. The
            # fallback alias deliberately does not: it is never read on the
            # healthy path, only after current mirrors fail, and the public
            # routing context plus an authoritative 404 still gate it.
            "pins": [] if fallback else pins,
            "operation": operation,
            "query": canonical_query,
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")).hexdigest()
    return (
        REPOSITORY_METADATA_FALLBACK_PREFIX
        if fallback else REPOSITORY_METADATA_CACHE_PREFIX
    ) + digest


async def repository_metadata_cache_get(env, cache_key):
    """Return immutable public metadata from the edge, then global KV."""
    if not cache_key:
        return None
    try:
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    if hit is not None:
        try:
            content_type = hit.headers.get("content-type")
        except Exception:
            content_type = None
        return JsResponse.new(hit.body, to_js({
            "status": 200,
            "headers": {
                "content-type": (
                    content_type or "application/json; charset=utf-8"
                ),
                "cache-control": "no-store, max-age=0, must-revalidate",
            },
        }))
    namespace = getattr(env, "REPOSITORY_METADATA", None)
    if namespace is None:
        return None
    try:
        raw = await namespace.get(cache_key)
    except Exception:
        raw = None
    if raw is None:
        return None
    raw = str(raw)
    try:
        json.loads(raw)
    except Exception:
        return None
    # Refill this colo's fastest cache from the persistent global copy. Both
    # layers use the same state-addressed key and may therefore live forever.
    try:
        cacheable = JsResponse.new(raw, to_js({
            "status": 200,
            "headers": {
                "content-type": "application/json; charset=utf-8",
                "cache-control": (
                    "public, max-age=%d, immutable"
                    % REPOSITORY_METADATA_CACHE_TTL
                ),
            },
        }))
        await js_caches.default.put(cache_key, cacheable)
    except Exception:
        pass
    return Response(
        raw,
        status=200,
        headers={
            "content-type": "application/json; charset=utf-8",
            "cache-control": "no-store, max-age=0, must-revalidate",
        },
    )


async def repository_metadata_cache_put(env, cache_key, response, status):
    """Persist one bounded state-addressed JSON response in KV and the edge."""
    if not cache_key or int(status or 0) != 200:
        return
    try:
        # A live dashboard read bypasses the cache so mirror selection and its
        # public provenance stay observable, but it may still offer that
        # successful immutable response to the outage fallback below. Avoid a
        # duplicate global KV write when this colo already holds the same
        # state-addressed key.
        try:
            existing = await js_caches.default.match(cache_key)
        except Exception:
            existing = None
        if existing is not None:
            return
        js_resp = getattr(response, "js_object", None) or response
        clone = js_resp.clone()
        content_type = clone.headers.get("content-type")
        if not str(content_type or "").lower().startswith("application/json"):
            return
        raw = str(await clone.text())
        content_length = len(raw.encode("utf-8"))
        if (
            content_length <= 0
            or content_length > REPOSITORY_METADATA_CACHE_MAX_BYTES
        ):
            return
        # Validate before a mirror response can become a durable shared value.
        json.loads(raw)
        cacheable = JsResponse.new(raw, to_js({
            "status": 200,
            "headers": {
                "content-type": content_type,
                "cache-control": (
                    "public, max-age=%d, immutable"
                    % REPOSITORY_METADATA_CACHE_TTL
                ),
            },
        }))
        namespace = getattr(env, "REPOSITORY_METADATA", None)
        # Sequential on purpose — see the no-concurrent-tasks rule at the top
        # of this module. Two awaits of single-digit milliseconds on the
        # repository-read hot path, versus a gather that can wedge the isolate.
        try:
            await js_caches.default.put(cache_key, cacheable)
        except Exception:
            pass
        if namespace is not None:
            # No expiration: commit/ref changes address a brand-new key.
            try:
                await namespace.put(cache_key, raw)
            except Exception:
                pass
    except Exception:
        pass


def request_bypasses_repository_metadata_cache(request):
    """Honor explicit live-read semantics before mirror selection.

    Dashboard repository reads use ``fetch(..., cache="no-store")`` and also
    send ``Cache-Control: no-cache``.  Those requests must reach a healthy
    mirror so the round-robin cursor advances and the Mirrors view records the
    node that actually served the request.  Immutable state-addressed cache
    entries remain available to ordinary clients that do not request a live
    read.
    """
    try:
        cache_control = str(
            request.headers.get("cache-control") or ""
        ).lower()
        pragma = str(request.headers.get("pragma") or "").lower()
    except Exception:
        return False
    directives = {
        part.split("=", 1)[0].strip()
        for part in cache_control.split(",")
        if part.strip()
    }
    return bool(
        directives.intersection({"no-cache", "no-store"})
        or "no-cache" in {
            part.strip() for part in pragma.split(",") if part.strip()
        }
    )


async def purge_catalog_related_caches():
    # Repository routing resolves the same signed catalog/pin context before
    # every tree/blob operation. Invalidate that short-lived in-isolate memo
    # synchronously with the edge caches so an accepted catalog/privacy change
    # can never keep serving its prior membership for the remainder of the TTL.
    _https_mirror_public_context_cache_clear()
    # ...and this isolate's catalog rows were read before the mutation.
    _catalog_memos_mark_stale()
    # Sequential on purpose. This runs on every catalog publish (each mirror
    # node, every 30s), and gathering the deletes was the wedge site of the
    # 2026-08-05/06 outage: the Pyodide runtime re-entered a concurrently
    # scheduled task mid-`caches.delete` ("Cannot enter into task ...",
    # issue #555), permanently poisoning the isolate. Four sequential cache
    # deletes cost single-digit ms; a wedged isolate 500s until recycled.
    for key in (
            CATALOG_CACHE_KEY,
            NETWORK_STATS_CACHE_KEY,
            NETWORK_LEADERBOARDS_CACHE_KEY,
            NETWORK_OVERVIEW_CACHE_KEY,
    ):
        await edge_cache_delete(key)


async def _is_flagship_snapshot_target(env, owner, repo):
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    # The flagship group contains the canonical record plus mirror-node owners;
    # every affected repository named forkmesh can therefore change the group.
    return repo == "forkmesh"


async def _account_has_flagship_catalog_repo(env, owner_bi):
    rows = await d1_all(
        env, "SELECT data FROM repositories WHERE owner_bi=?", owner_bi)
    for row in rows or []:
        record = await decrypt_row(env, row.get("data", "")) or {}
        if clean_string(
                record.get("name", ""), MAX_REPO_SEGMENT
        ).strip().lower() == "forkmesh":
            return True
    return False


async def _public_catalog_snapshot_paths(
        env, affected_owner="", affected_repo="", include_flagship=False):
    paths = [
        "/api/repositories",
        "/api/network/overview",
    ]
    if include_flagship or await _is_flagship_snapshot_target(
            env, affected_owner, affected_repo):
        paths.append("/api/repo/forkmesh/forkmesh/mirrors")
    return paths


def _public_snapshot_database(env):
    """Return the main D1 binding that owns public snapshot rows."""
    database = getattr(env, "DB", None)
    if database is None or js_nullish(database):
        raise RuntimeError("DB binding is unavailable")
    return database


async def invalidate_public_catalog_snapshots(
        env, affected_owner="", affected_repo="", include_flagship=False):
    """Persist fail-closed rows before public data becomes private/disappears.

    The two-minute guard also closes the race where a cron generation that
    started just before the transition tries to publish its old public view
    just after this function returns. Normal UPSERTs cannot replace this row
    until its deadline; the next safe generation then heals it automatically.
    """
    _d1_write_guard(env, PUBLIC_SNAPSHOT_TOMBSTONE_UPSERT_SQL)
    database = _public_snapshot_database(env)
    now = int(Date.now())
    # Coalesce authenticated privacy mutations into fixed two-minute buckets.
    # The deadline is always at least two minutes ahead (and less than four),
    # so repeated toggles in one bucket require no additional D1 row writes.
    bucket_ms = public_snapshots.SNAPSHOT_TOMBSTONE_MS
    blocked_until = ((now // bucket_ms) + 2) * bucket_ms
    fingerprint = str(getattr(env, "DEPLOY_FINGERPRINT", "") or "")
    paths = await _public_catalog_snapshot_paths(
        env, affected_owner, affected_repo, include_flagship)
    statements = []
    for path in paths:
        statements.append(
            database.prepare(PUBLIC_SNAPSHOT_TOMBSTONE_UPSERT_SQL).bind(
                path,
                public_snapshots.SNAPSHOT_SCHEMA_VERSION,
                public_snapshots.SNAPSHOT_TOMBSTONE_KIND,
                now,
                blocked_until,
                blocked_until,
                fingerprint,
                2,
                "{}",
            )
        )
    _cron_d1_query_charge(len(statements))
    _log_d1_query(PUBLIC_SNAPSHOT_TOMBSTONE_UPSERT_SQL, (),
                  "batch of %d" % len(statements))
    await database.batch(statements)


async def schedule_public_catalog_republish(
        env, affected_owner="", affected_repo="", include_flagship=False):
    """Ring the republish doorbell after a mutation that feeds a snapshot.

    The counterpart of invalidate_public_catalog_snapshots: that one runs
    BEFORE a public->private transition and fails closed; this one runs AFTER
    any successful catalog mutation (publish, delete, About edit, rename,
    purge, ...) and asks the snapshot-republish object to rebuild the affected
    anonymous projections. The rebuild happens in that object's alarm, so the
    mutating request neither waits for a catalog scan nor spends its own
    subrequest budget on it, and no detached Python task is ever created (the
    no-concurrent-tasks rule at the top of this module).

    Best-effort by design: a lost doorbell only means the change waits for the
    Cron cadence, exactly as before. Returns True when the doorbell was
    accepted. Never raises.
    """
    # Every caller has just mutated the catalog. Advance catalog_rev before
    # ringing so the rev-keyed catalog/count memos on OTHER isolates rescan on
    # their next probe (purge_catalog_related_caches already emptied this
    # isolate's). One indexed write, best-effort like the doorbell itself.
    try:
        await _bump_catalog_rev(env)
    except BaseException:
        pass
    try:
        paths = await _public_catalog_snapshot_paths(
            env, affected_owner, affected_repo, include_flagship)
    except BaseException:
        return False
    return await schedule_public_snapshot_republish(env, paths)


async def schedule_public_snapshot_republish(env, paths):
    """Coalesce an immediate rebuild of an exact public snapshot group."""
    try:
        allowed = set(public_snapshots.SNAPSHOT_PATHS)
        requested = tuple(dict.fromkeys(str(path) for path in (paths or ())))
        if not requested or any(path not in allowed for path in requested):
            return False
        binding = getattr(env, "FORKMESH_CRON_RUNNER", None)
        if binding is None or js_nullish(binding):
            return False
        request = JsRequest.new(
            "https://forkmesh.internal" + SNAPSHOT_REPUBLISH_PATH
            + "?paths=" + quote(",".join(requested), safe=""),
            to_js({
                "method": "POST",
                "signal": JsAbortSignal.timeout(
                    SNAPSHOT_REPUBLISH_DOORBELL_TIMEOUT_MS),
            }),
        )
        # A Cron phase (blocked-catalog, stale-nodes) rings this too, so the
        # DO call is charged against that phase's bounded subrequest budget.
        _cron_d1_query_charge()
        doorbell = binding.get(binding.idFromName(SNAPSHOT_REPUBLISH_NAME))
        response = await doorbell.fetch(request)
        return 200 <= int(getattr(response, "status", 0) or 0) < 300
    except BaseException:
        return False


_node_events_runtime = _LazyModule("node_events_runtime")
schedule_repo_mirror_wake = _node_events_runtime.export("schedule_repo_mirror_wake")
_node_events_do_name = _node_events_runtime.export("_node_events_do_name")
_repo_watch_do_name = _node_events_runtime.export("_repo_watch_do_name")
notify_repo_watchers = _node_events_runtime.export("notify_repo_watchers")
notify_repo_host = _node_events_runtime.export("notify_repo_host")
notify_repo_mirrors = _node_events_runtime.export("notify_repo_mirrors")
