# Versioned so neither the fail-closed visibility contract nor signed-endpoint
# availability reuses an edge entry produced by the historical plaintext flag /
# host_presence catalog.
CATALOG_CACHE_KEY = (
    "https://forkmesh.internal/api/repositories"
    "?privacy=v2&availability=signed-v1&terms=v1"
)
# Guest (viewer-less) GET /api/accounts/<name> payloads, keyed by name.
ACCOUNT_LOOKUP_CACHE_PREFIX = "https://forkmesh.internal/api/accounts/"
PROFILE_CONTRIBUTION_CACHE_PREFIX = (
    "https://forkmesh.internal/api/profile-contributions/"
)
PROFILE_CONTRIBUTION_CACHE_TTL = 30
NETWORK_STATS_CACHE_KEY = "https://forkmesh.internal/api/network/stats"
NETWORK_LEADERBOARDS_CACHE_KEY = "https://forkmesh.internal/api/network/leaderboards"
NETWORK_OVERVIEW_CACHE_KEY = "https://forkmesh.internal/api/network/overview"
# Seconds the repositories list is cached at the edge. Every write path calls
# purge_catalog_related_caches, so a longer TTL only delays third-party edits;
# 10s meant a full (purge + multi-table) rebuild every 10s per colo under load.
CATALOG_TTL = 30


async def repo_live_host_count(env, owner, repo):
    owner = safe_segment(owner)
    repo = safe_segment(repo)
    if not owner or not repo:
        return None
    try:
        await ensure_schema(env)
        now = int(Date.now())
        row = await d1_first(
            env,
            "SELECT COUNT(*) AS total FROM mirror_https_endpoints "
            "WHERE lower(node_name)=lower(?) AND healthy=1 "
            "AND abuse_blocked=0 AND integrity='ok' "
            "AND checked_at>=?",
            owner,
            now - HOST_PRESENCE_STALE_MS,
        )
        return max(0, int((row or {}).get("total") or 0))
    except Exception:
        return None






# Per-isolate coalescing window for account event pushes. One write path
# routinely enqueues several notifications for the same person in the same
# request (an @mention plus a thread subscription, say), and every one of them
# is answered by the same single signed read on the client. Collapsing the
# duplicates costs the user nothing and keeps a fan-out inside the Worker's
# subrequest budget.
_ACCOUNT_EVENT_PUSH_MEMO = {}
ACCOUNT_EVENT_PUSH_COALESCE_MS = 2000
ACCOUNT_EVENT_PUSH_MEMO_MAX = 512
# Topics whose phone alert is never coalesced. The socket frame only means
# "re-read your inbox", so one frame answers any number of rows; a banner is
# the notification itself, and a second ping inside the window that produced
# no banner is a ping the phone never heard about.
ACCOUNT_EVENT_PUSH_EVERY_TOPICS = ("pings", "direct-messages")
ACCOUNT_EVENT_SOCKET_EVERY_TOPICS = ("chat-read", "direct-messages")


def _account_event_query(topic, push_alert):
    if topic != "direct-messages" or not isinstance(push_alert, dict):
        return ""
    conversation = str(push_alert.get("conversation") or "")
    if not re.fullmatch(r"direct:[0-9a-f]{32}", conversation):
        return ""
    query = "&conversation=" + quote(conversation)
    ref = str(push_alert.get("ref") or "")
    if re.fullmatch(r"[0-9a-f]{40}", ref):
        query += "&ref=" + ref
    key_version = push_alert.get("keyVersion")
    if (isinstance(key_version, int) and not isinstance(key_version, bool)
            and key_version > 0):
        query += "&keyVersion=" + str(key_version)
    return query


async def notify_account_event(env, owner, topic, push_alert=None):
    """Best-effort payload-free account-state notification.

    `push_alert` is what the phone banner says about this event: the stored
    notification record for "pings" (rendered by _push_alert_item), or a
    ready {title, body} for a direct message. The socket frame never carries
    it; only the APNs alert does.
    """
    owner = safe_segment(owner)
    topic = clean_string(topic or "", 40)
    if not owner or not topic:
        return
    now = int(Date.now())
    memo_key = owner + "\n" + topic
    last = _ACCOUNT_EVENT_PUSH_MEMO.get(memo_key, 0)
    coalesced = bool(
        last and now - last < ACCOUNT_EVENT_PUSH_COALESCE_MS
        and topic not in ACCOUNT_EVENT_SOCKET_EVERY_TOPICS)
    if coalesced and topic not in ACCOUNT_EVENT_PUSH_EVERY_TOPICS:
        return
    if not coalesced:
        _ACCOUNT_EVENT_PUSH_MEMO[memo_key] = now
        if len(_ACCOUNT_EVENT_PUSH_MEMO) > ACCOUNT_EVENT_PUSH_MEMO_MAX:
            cutoff = now - ACCOUNT_EVENT_PUSH_COALESCE_MS
            for stale in [key for key, ts in _ACCOUNT_EVENT_PUSH_MEMO.items()
                          if ts < cutoff]:
                _ACCOUNT_EVENT_PUSH_MEMO.pop(stale, None)
        try:
            node_id = env.FORKMESH_NODES.idFromName(_node_events_do_name(owner))
            node_object = env.FORKMESH_NODES.get(node_id)
            # Awaited directly — see notify_repo_host above for why this must
            # not be wrapped in asyncio.wait_for.
            _cron_subrequest_charge()
            await node_object.fetch(
                "https://forkmesh.internal/api/nodes/notify"
                "?topic=" + quote(topic)
                + _account_event_query(topic, push_alert)
            )
        except Exception:
            pass
    # The socket above only reaches clients that are running. A suspended phone
    # has none, so the same event also goes out over APNs — the one transport
    # that reaches a device whose app is not alive. Bounded and best-effort:
    # push_account_apns never raises, and ignores topics that are only a
    # refresh hint (issues, catalog). Direct messages share the socket's
    # coalescing window; every ping is pushed on its own.
    try:
        return await push_account_apns(env, owner, topic, push_alert)
    except Exception:
        return 0


def _account_event_direct_fields(query):
    fields = {}
    conversation = str((query.get("conversation") or [""])[0])
    if not re.fullmatch(r"direct:[0-9a-f]{32}", conversation):
        return fields
    fields["conversation"] = conversation
    ref = str((query.get("ref") or [""])[0])
    if re.fullmatch(r"[0-9a-f]{40}", ref):
        fields["ref"] = ref
    key_version = str((query.get("keyVersion") or [""])[0])
    if re.fullmatch(r"[1-9][0-9]{0,8}", key_version):
        fields["keyVersion"] = int(key_version)
    return fields


def _apns_module():
    # Reachable only from the push fan-out and the device-registration route.
    # Loading it lazily keeps its module globals out of ordinary request
    # startup, like the other optional policy modules above.
    import apns
    return apns


async def _apns_account_tokens(env, owner):
    """Live push tokens for an account, most recently seen first."""
    apns = _apns_module()
    # Registration lowercases the account before blind-indexing it (see
    # register_apns_device_token), so the lookup has to as well or an owner
    # name that arrives in another case reads an empty set and the phone is
    # silently never woken. Same normalisation as _node_events_do_name.
    owner = str(owner or "").strip().lower()
    if not valid_node_name(owner):
        return []
    rows = await d1_all(
        env,
        "SELECT token_bi, environment, bundle_id, data "
        "FROM apns_device_tokens "
        "WHERE account_bi=? ORDER BY last_seen DESC LIMIT ?",
        await blind_index(env, owner),
        apns.APNS_MAX_DEVICES_PER_PUSH,
    )
    return await _apns_tokens_from_rows(env, rows)


async def _apns_tokens_from_rows(env, rows):
    tokens = []
    for row in rows or []:
        record = await decrypt_row(env, row.get("data", ""))
        if not isinstance(record, dict):
            continue
        token = clean_string(record.get("token", ""), 200).strip()
        if not token:
            continue
        tokens.append({
            "token_bi": str(row.get("token_bi") or ""),
            "account_bi": str(row.get("account_bi") or ""),
            "token": token,
            "environment": str(row.get("environment") or "production"),
            # The app that minted the token, which is the apns-topic Apple
            # accepts it under; "" for an older build that never said.
            "bundle_id": str(row.get("bundle_id") or ""),
        })
    return tokens


async def _apns_prune_token(env, token_bi):
    """Forget a token APNs reported as permanently dead (410 / BadDeviceToken).

    The app re-registers on every launch, so a token dropped in error costs one
    missed push and repairs itself; keeping a dead one costs a wasted gateway
    round trip on every single event forever.
    """
    if not token_bi:
        return
    try:
        await d1_run(
            env, "DELETE FROM apns_device_tokens WHERE token_bi=?", token_bi)
    except Exception:
        pass


async def push_account_apns(env, owner, topic, push_alert=None):
    """Best-effort APNs fan-out for one account event.

    Sits behind the same coalescing window as the socket push in
    notify_account_event, so a write path that enqueues several notifications
    in one request buzzes the phone once rather than once per row. Never
    raises and never blocks indefinitely: the notification row this decorates
    is already committed, and a slow or unreachable gateway must not fail — or
    even noticeably delay — the request that triggered it.

    Every banner names its event. A ping with no record to describe is not
    pushed at all rather than sent as a vague "new activity" alert.
    """
    apns = _apns_module()
    if topic not in apns.APNS_PUSH_TOPICS or not apns.apns_configured(env):
        return 0
    if topic == "pings" and not isinstance(push_alert, dict):
        return 0
    try:
        tokens = await _apns_account_tokens(env, owner)
    except Exception:
        return 0
    if not tokens:
        return 0
    if topic == "pings":
        alert = await _apns_ping_alert(env, push_alert)
        if push_alert.get("kind") == "code_push":
            # Still a ping (no collapse id, every one its own banner), but
            # marked so the phone can tell a code push from an inbox ping.
            topic = apns.APNS_CODE_PUSH_TOPIC
    elif topic == "direct-messages":
        alert = (push_alert if isinstance(push_alert, dict)
                 else apns.direct_message_alert())
    else:
        alert = push_alert
    if not isinstance(alert, dict) or not alert.get("title"):
        return 0
    return await _apns_send_tokens(env, tokens, topic, alert)


async def _apns_ping_alert(env, record):
    """The lock-screen text for one just-written notification row.

    Rendered by _push_alert_item, the same composition GET /api/push/alert and
    the digest email use, so the banner, the mail and the inbox describe the
    event identically. The portrait is left to the notification service
    extension: it would not fit Apple's 4 KB payload.
    """
    repos = {}
    slug = clean_string(record.get("repo", ""), 180).lower().strip()
    if slug:
        try:
            repos[slug] = await _notification_public_repo(env, slug)
        except Exception:
            repos[slug] = ""
    item = _push_alert_item(record, repos, {})
    alert = {
        "title": item["title"],
        "subtitle": item["subtitle"],
        "body": item["body"],
        "threadId": item["threadId"],
        "alertId": item["id"],
        "href": item["href"],
    }
    meta = record.get("meta")
    if record.get("kind") == "desktop_ping" and isinstance(meta, dict):
        alert["category"] = clean_string(meta.get("category", ""), 40)
        alert["sessionId"] = clean_string(meta.get("sessionId", ""), 12)
        alert["runId"] = clean_string(meta.get("runId", ""), 12)
        alert["alarm"] = clean_string(meta.get("alarm", ""), 20)
    return alert


async def _apns_send_tokens(env, tokens, topic, alert):
    """One alert to each token, inside the inline push budget."""
    apns = _apns_module()
    try:
        jwt = await apns.provider_token(env)
    except Exception:
        # A malformed or rotated key must not take the write path down with it.
        return 0
    started = int(Date.now())
    delivered = 0
    for entry in tokens:
        if int(Date.now()) - started > apns.APNS_PUSH_BUDGET_MS:
            # Out of budget. The remaining devices pick the change up from
            # their own read on next open rather than holding this request.
            break
        try:
            ok, dead, _status, _reason = await apns.send_one(
                env, js_fetch_with_timeout, jwt,
                entry["token"], entry["environment"], alert,
                collapse_id=apns.collapse_id_for(
                    topic, alert.get("conversation", "")), topic=topic,
                bundle_id=entry.get("bundle_id", ""))
        except Exception:
            continue
        if ok:
            delivered += 1
        elif dead:
            await _apns_prune_token(env, entry["token_bi"])
            _APNS_BROADCAST_MEMO.clear()
    print("apns: topic %s delivered %d of %d" % (
        topic, delivered, len(tokens)))
    return delivered


# Every registered phone, memoized per isolate. A public room relays one frame
# per chat message, and re-reading and decrypting the whole device table for
# each of them would cost more than the pushes themselves.
_APNS_BROADCAST_MEMO = {}
APNS_BROADCAST_MEMO_MS = 60 * 1000
# Per-isolate coalescing for chat pushes, keyed by room: a conversation in
# full flow buzzes a phone once per window, not once per frame.
_CHAT_ROOM_PUSH_MEMO = {}
CHAT_ROOM_PUSH_COALESCE_MS = 2000
CHAT_ROOM_PUSH_MEMO_MAX = 256


async def _apns_broadcast_tokens(env):
    apns = _apns_module()
    now = int(Date.now())
    cached = _APNS_BROADCAST_MEMO.get("tokens")
    if (cached is not None
            and now - int(_APNS_BROADCAST_MEMO.get("at", 0))
            < APNS_BROADCAST_MEMO_MS):
        return cached
    rows = await d1_all(
        env,
        "SELECT token_bi, account_bi, environment, bundle_id, data "
        "FROM apns_device_tokens ORDER BY last_seen DESC LIMIT ?",
        apns.APNS_MAX_DEVICES_PER_BROADCAST,
    )
    tokens = await _apns_tokens_from_rows(env, rows)
    _APNS_BROADCAST_MEMO["tokens"] = tokens
    _APNS_BROADCAST_MEMO["at"] = now
    return tokens


async def _chat_channel_push_accounts(env, channel_id):
    """(audience, channel name) for a channel's push.

    The audience is the blind indexes allowed to hear a private channel, or
    None for public. A private channel's audience is its creator plus its
    member rows; a public channel has no membership rows and is heard by every
    registered phone. The name is what the banner says the message is in.
    """
    channel = await d1_first(
        env,
        "SELECT data, created_by_bi FROM chat_channels WHERE channel_id=?",
        channel_id,
    )
    if not channel:
        return set(), ""
    record = await decrypt_row(env, channel.get("data", ""))
    if not isinstance(record, dict):
        return set(), ""
    name = clean_string(record.get("name", ""), 80).strip()
    if record.get("visibility") == "public":
        return None, name
    audience = {str(channel.get("created_by_bi") or "")}
    members = await d1_all(
        env,
        "SELECT member_bi FROM chat_channel_members WHERE channel_id=?",
        channel_id,
    )
    for member in members or []:
        audience.add(str(member.get("member_bi") or ""))
    audience.discard("")
    return audience, name


async def push_chat_room_apns(env, room_key, channel_id="", sender_bi="",
                              ref="", key_version=0):
    """Best-effort APNs fan-out for one retained chat message.

    Direct messages have a named recipient and go through
    notify_account_event. A channel or public room does not: the relay only
    ever sees ciphertext, so the audience is derived from the room instead —
    a private channel's members, or every registered phone for a public
    channel or room. The sender's own phones are skipped whenever the relay
    knows who sent the frame, which a public room's anonymous socket does not
    say; the app keeps that banner off screen while it is open instead.
    """
    apns = _apns_module()
    if not room_key or not apns.apns_configured(env):
        return 0
    now = int(Date.now())
    last = _CHAT_ROOM_PUSH_MEMO.get(room_key, 0)
    if last and now - last < CHAT_ROOM_PUSH_COALESCE_MS:
        return 0
    if len(_CHAT_ROOM_PUSH_MEMO) >= CHAT_ROOM_PUSH_MEMO_MAX:
        _CHAT_ROOM_PUSH_MEMO.clear()
    _CHAT_ROOM_PUSH_MEMO[room_key] = now
    try:
        audience = None
        if channel_id:
            audience, _channel_name = await _chat_channel_push_accounts(
                env, channel_id)
        tokens = [
            entry for entry in await _apns_broadcast_tokens(env)
            if entry["account_bi"] != sender_bi
            and (audience is None or entry["account_bi"] in audience)
        ]
    except Exception:
        return 0
    if not tokens:
        return 0
    return await _apns_send_tokens(
        env, tokens, apns.APNS_CHAT_TOPIC,
        apns.chat_message_alert(
            channel_id=channel_id, ref=ref, key_version=key_version))


async def register_apns_device_token(env, account, token, environment,
                                     device_bi="", bundle_id=""):
    """Upsert one phone's push token for an account.

    Keyed on a blind index of the token itself, so a phone that re-registers
    the same token updates its row in place instead of accumulating duplicates,
    and a token that moves to a different account is re-pointed rather than
    left able to receive the previous owner's pushes.

    `bundle_id` is the app that minted the token (the native iOS app sends
    it; older builds never did). It becomes that token's apns-topic, so it
    is allowlisted (apns.normalize_bundle_id) and "" means the App Store app.
    """
    apns = _apns_module()
    account = clean_string(account, MAX_NODE_NAME).lower()
    token = clean_string(token, 200).strip()
    if not valid_node_name(account) or not token:
        return False
    # APNs tokens are lowercase hex; reject anything else rather than storing a
    # value the gateway will only ever answer BadDeviceToken for.
    if len(token) < 32 or not all(c in "0123456789abcdefABCDEF" for c in token):
        return False
    token = token.lower()
    environment = (
        "development"
        if str(environment or "").strip().lower() == "development"
        else "production")
    bundle_id = apns.normalize_bundle_id(bundle_id)
    now = int(Date.now())
    account_bi = await blind_index(env, account)
    token_bi = await blind_index(env, "apns:" + token)
    await ensure_schema(env)
    await d1_run(
        env,
        """INSERT INTO apns_device_tokens
             (token_bi, account_bi, device_bi, environment, bundle_id, data,
              created_at, last_seen)
           VALUES (?,?,?,?,?,?,?,?)
           ON CONFLICT(token_bi) DO UPDATE SET
             account_bi=excluded.account_bi,
             device_bi=excluded.device_bi,
             environment=excluded.environment,
             bundle_id=excluded.bundle_id,
             data=excluded.data,
             last_seen=excluded.last_seen""",
        token_bi, account_bi, clean_string(device_bi or "", 128),
        environment, bundle_id, await encrypt_row(env, {"token": token}),
        now, now,
    )
    # Retire installs that stopped checking in long ago. The app registers on
    # every launch, so a live phone always refreshes its own row.
    await d1_run(
        env,
        "DELETE FROM apns_device_tokens WHERE account_bi=? AND last_seen<?",
        account_bi, now - apns.APNS_TOKEN_STALE_MS,
    )
    # Bound even a deliberately churned set of fresh tokens. Registration is
    # account-authenticated, but without this trim one account could grow the
    # encrypted table indefinitely while only the newest devices are read.
    await d1_run(
        env,
        """DELETE FROM apns_device_tokens
           WHERE account_bi=? AND token_bi NOT IN (
             SELECT token_bi FROM apns_device_tokens
             WHERE account_bi=? ORDER BY last_seen DESC
             LIMIT ?
           )""",
        account_bi, account_bi, apns.APNS_MAX_TOKENS_PER_ACCOUNT,
    )
    return True


async def unregister_apns_device_token(env, account, token):
    """Drop one token — sign-out, or the app reporting its own revocation."""
    account = clean_string(account, MAX_NODE_NAME).lower()
    token = clean_string(token, 200).strip().lower()
    if not valid_node_name(account) or not token:
        return False
    account_bi = await blind_index(env, account)
    await d1_run(
        env,
        "DELETE FROM apns_device_tokens WHERE token_bi=? AND account_bi=?",
        await blind_index(env, "apns:" + token), account_bi)
    return True


async def register_device_handler(env, request):
    """POST /api/accounts/register-device — bind this phone's APNs token.

    The account comes from the session, never from the body: a self-asserted
    account name here would let any caller point their own handset at somebody
    else's notifications. DELETE removes the token on sign-out.
    """
    method = method_name(request)
    if method not in ("POST", "DELETE"):
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "POST, DELETE"})
    try:
        data = await bounded_json_request(request, max_bytes=4 * 1024)
    except Exception:
        return json_response(
            {"error": "invalid_json"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    if not isinstance(data, dict):
        data = {}
    account = safe_segment(await _authed_account_name(env, request, data))
    if not account:
        return json_response(
            {"error": "unauthorized"}, status=401,
            cache_control="no-store, max-age=0, must-revalidate")
    token = clean_string(data.get("deviceToken", ""), 200).strip()
    if method == "DELETE":
        await unregister_apns_device_token(env, account, token)
        return json_response(
            {"ok": True, "registered": False},
            cache_control="no-store, max-age=0, must-revalidate")
    ok = await register_apns_device_token(
        env, account, token,
        data.get("environment", ""),
        device_bi=clean_string(data.get("deviceBi", ""), 128),
        # The app that minted the token (its apns-topic). Absent from older
        # builds, which then keep the App Store id.
        bundle_id=clean_string(data.get("bundleId", ""), 128),
    )
    if not ok:
        return json_response(
            {"error": "invalid_device_token"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    # A row is only half the story: push_account_apns is a silent no-op on a
    # relay that has no provider credentials, and the phone has no other way
    # to learn that. Reporting it here lets the settings screen say so instead
    # of "registered" meaning nothing will ever arrive.
    problem = _apns_module().apns_config_problem(env)
    return json_response(
        {"ok": True, "registered": True,
         "pushConfigured": not problem,
         # "" when usable; otherwise which secret is missing or malformed.
         "configProblem": problem},
        cache_control="no-store, max-age=0, must-revalidate")


# A self-test is one real buzz on the caller's own handsets, with the APNs
# round trips running inline on this request (no waitUntil here), so it is
# capped per account. Ten seconds is comfortably above Apple's own
# TooManyRequests window for one device and short enough to retry from the
# settings screen without waiting.
APNS_PUSH_TEST_MIN_INTERVAL_MS = 10 * 1000
_APNS_PUSH_TEST_MEMO = {}
_APNS_PUSH_TEST_MEMO_MAX = 256


async def push_test_handler(env, request):
    """POST /api/accounts/push-test — one generic alert to this account now.

    The only way to prove the whole chain from a phone: entitlement, token,
    registration, provider key, and the sandbox-versus-production gateway
    choice all have to line up before a banner appears, and every link fails
    silently by design elsewhere in this file. The settings screen calls this
    and shows Apple's answer per device.

    Same rules as a real event: the target is whoever the session proves,
    never a name in the body, and the alert is the fixed test text
    (APNS_TEST_ALERT), never anything from the request.
    """
    method = method_name(request)
    if method != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "POST"})
    try:
        data = await bounded_json_request(request, max_bytes=4 * 1024)
    except Exception:
        # The session usually rides in the Authorization header; an empty or
        # non-JSON body is fine.
        data = {}
    if not isinstance(data, dict):
        data = {}
    account = safe_segment(await _authed_account_name(env, request, data))
    if not account:
        return json_response(
            {"error": "unauthorized"}, status=401,
            cache_control="no-store, max-age=0, must-revalidate")
    now = int(Date.now())
    last = int(_APNS_PUSH_TEST_MEMO.get(account, 0))
    if last and now - last < APNS_PUSH_TEST_MIN_INTERVAL_MS:
        return json_response(
            {"error": "too_many_requests",
             "retryAfterMs": APNS_PUSH_TEST_MIN_INTERVAL_MS - (now - last)},
            status=429,
            cache_control="no-store, max-age=0, must-revalidate")
    if len(_APNS_PUSH_TEST_MEMO) >= _APNS_PUSH_TEST_MEMO_MAX:
        _APNS_PUSH_TEST_MEMO.clear()
    _APNS_PUSH_TEST_MEMO[account] = now

    apns = _apns_module()
    result = {
        "ok": True,
        # False means APNS_AUTH_KEY / APNS_KEY_ID / APNS_TEAM_ID are not all
        # set on this Worker: nothing can be sent, whatever the phone does.
        "configured": apns.apns_configured(env),
        # Why not: "missing_secrets", "key_id_malformed" or
        # "team_id_malformed". Apple's Key ID and Team ID are both exactly ten
        # characters of A-Z0-9; anything else is refused on every push.
        "configProblem": apns.apns_config_problem(env),
        "devices": 0,
        "delivered": 0,
        # One entry per registered device: {environment, delivered, status,
        # reason}. A status of 0 means Apple's gateway was never reached.
        "results": [],
    }
    try:
        tokens = await _apns_account_tokens(env, account)
    except Exception:
        result["ok"] = False
        result["error"] = "device_lookup_failed"
        return json_response(
            result, status=502,
            cache_control="no-store, max-age=0, must-revalidate")
    result["devices"] = len(tokens)
    if not result["configured"] or not tokens:
        return json_response(
            result, cache_control="no-store, max-age=0, must-revalidate")
    try:
        jwt = await apns.provider_token(env)
    except Exception:
        # The key is present but will not import or sign: a pasted .p8 with
        # its armour mangled, or a key id that does not match it.
        result["ok"] = False
        result["error"] = "apns_provider_key"
        return json_response(
            result, status=502,
            cache_control="no-store, max-age=0, must-revalidate")
    for entry in tokens:
        try:
            ok, dead, status, reason = await apns.send_one(
                env, js_fetch_with_timeout, jwt,
                entry["token"], entry["environment"],
                apns.APNS_TEST_ALERT, collapse_id="push-test",
                bundle_id=entry.get("bundle_id", ""))
        except Exception:
            ok, dead, status, reason = False, False, 0, ""
        result["results"].append({
            "environment": entry["environment"],
            # The apns-topic this device was addressed under, so a
            # DeviceTokenNotForTopic names the app it was sent as.
            "topic": apns.apns_topic_for(entry.get("bundle_id", "")),
            "delivered": bool(ok),
            "status": int(status),
            "reason": str(reason or ""),
        })
        if ok:
            result["delivered"] += 1
        elif dead:
            await _apns_prune_token(env, entry["token_bi"])
    return json_response(
        result, cache_control="no-store, max-age=0, must-revalidate")




async def push_alert_handler(env, request):
    """GET /api/push/alert — the portrait and badge behind one push.

    The alert this Worker hands Apple already carries the event's text (see
    _apns_ping_alert), but not the actor's portrait, which would not fit a
    4 KB payload, nor the unread count. The phone's notification service
    extension calls this the moment one lands, with the same session the app
    itself uses, and adds both to the banner for the row the push names
    (`alertId`) before it is drawn. A push from an older relay names no row;
    for those the extension still takes the newest unread one.

    Authorised exactly like reading the inbox — this *is* the inbox, rendered
    for a lock screen — so the same gate answers both: a session bearer token
    or an account-key signature, and only for the caller's own account.

    Unread and recent only, newest first. A notification the user has already
    dealt with must never come back as a banner, and the extension needs a
    short run rather than one row so a burst of events does not draw the
    newest ping several times over.

    The time bound keeps the older-relay inference honest: a push that names
    no row makes the phone assume the newest unread row is the one. Outside
    PUSH_ALERT_FRESH_MS this answers with no alerts at all and the banner
    keeps the text it arrived with.
    """
    await ensure_schema(env)
    no_store = "no-store, max-age=0, must-revalidate"
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control=no_store, extra_headers={"allow": "GET"})
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    if not valid_node_name(node):
        return json_response(
            {"error": "node_required"}, status=400, cache_control=no_store)
    if await _alert_inbox_account_name(env, request) != node:
        return json_response(
            {"error": "unauthorized"}, status=401, cache_control=no_store)
    try:
        limit = int(params.get("limit", [str(PUSH_ALERT_DEFAULT_ITEMS)])[0])
    except (TypeError, ValueError):
        limit = PUSH_ALERT_DEFAULT_ITEMS
    limit = max(1, min(limit, PUSH_ALERT_MAX_ITEMS))
    recipient_bi = await blind_index(env, node)
    rows = await d1_all(
        env,
        """SELECT dedupe_bi, ts, data FROM notifications
           WHERE recipient_bi=? AND read_at=0 AND ts>=?
           ORDER BY ts DESC, dedupe_bi DESC LIMIT ?""",
        recipient_bi, int(Date.now()) - PUSH_ALERT_FRESH_MS, limit,
    )
    unread_row = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM notifications "
        "WHERE recipient_bi=? AND read_at=0",
        recipient_bi,
    )
    items = []
    # One key derivation for the whole page, as the inbox read does: each one
    # is its own WebCrypto round trip and the extension is on a stopwatch.
    row_key = await _data_key(env) if rows else None
    for row in rows:
        rec = await decrypt_row(env, row.get("data", ""), key=row_key)
        if not rec:
            continue
        rec["id"] = row.get("dedupe_bi", "")
        rec["ts"] = int(row.get("ts") or rec.get("ts") or 0)
        items.append(rec)
    identity = await _notification_digest_identity(
        env, items, avatar_max_b64=PUSH_ALERT_AVATAR_MAX_B64)
    return json_response(
        {"ok": True,
         # Drives the app icon badge, which the extension is the only thing
         # able to set while the app is suspended.
         "unread": int((unread_row or {}).get("n") or 0),
         "alerts": [
             _push_alert_item(it, identity["repos"], identity["avatars"])
             for it in items
         ]},
        cache_control=no_store)


# A browser cannot set headers on a WebSocket upgrade, so it proves its
# account the way the World already does: exchange the session for a
# short-lived, HMAC-signed ticket over ordinary authenticated HTTPS and put
# only that in the upgrade URL. A leaked ticket buys sixty seconds of
# payload-free "something changed" frames for one account — never the session
# token, and never any content.
ACCOUNT_EVENT_TICKET_TTL_MS = 60 * 1000


def _account_event_ticket_signature(env, payload):
    return hmac.new(
        _account_session_secret(env),
        b"forkmesh-account-events-ticket-v1\n" + payload.encode(),
        "sha256",
    ).hexdigest()


def _account_event_ticket_encode(env, claim):
    payload = base64.urlsafe_b64encode(
        json.dumps(claim, separators=(",", ":"), sort_keys=True).encode()
    ).decode().rstrip("=")
    return payload + "." + _account_event_ticket_signature(env, payload)


def _account_event_ticket_owner(env, ticket):
    """The account name proven by an unexpired event ticket, else ""."""
    value = clean_string(ticket or "", 1024).strip()
    if "." not in value:
        return ""
    payload, signature = value.rsplit(".", 1)
    if not payload or not re.fullmatch(r"[A-Za-z0-9_-]+", payload):
        return ""
    if not hmac.compare_digest(
            signature, _account_event_ticket_signature(env, payload)):
        return ""
    try:
        padded = payload + "=" * ((4 - len(payload) % 4) % 4)
        claim = json.loads(base64.urlsafe_b64decode(padded).decode())
    except Exception:
        return ""
    if not isinstance(claim, dict):
        return ""
    now = int(Date.now())
    try:
        issued = int(claim.get("issuedAt", 0) or 0)
        expires = int(claim.get("expiresAt", 0) or 0)
    except (TypeError, ValueError):
        return ""
    if issued <= 0 or expires <= now or issued > now + 5000:
        return ""
    if expires - issued > ACCOUNT_EVENT_TICKET_TTL_MS:
        return ""
    return safe_segment(clean_string(claim.get("name", ""), MAX_NODE_NAME))


async def account_event_ticket_handler(env, request):
    """GET /api/accounts/event-ticket — session -> account event ticket."""
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET"})
    name = safe_segment(await _authed_account_name(env, request))
    if not name:
        return json_response(
            {"ok": True, "authenticated": False, "ticket": "", "expiresAt": 0},
            cache_control="no-store, max-age=0, must-revalidate")
    now = int(Date.now())
    expires = now + ACCOUNT_EVENT_TICKET_TTL_MS
    return json_response(
        {
            "ok": True,
            "authenticated": True,
            "name": name,
            "expiresAt": expires,
            "ticket": _account_event_ticket_encode(
                env, {"name": name, "issuedAt": now, "expiresAt": expires}),
        },
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"})


async def _node_events_object_holds_node(env, name):
    """True when `name`'s own object currently holds a node-side socket.

    Asked of the machine's object before a browser is accepted onto it, so the
    answer has to count the node side only: a tab streaming a terminal also
    holds a socket there, and the role-blind total would make an object that
    contains nothing but browsers look like a live machine.
    """
    try:
        object_id = env.FORKMESH_NODES.idFromName(_node_events_do_name(name))
        _cron_subrequest_charge()
        response = await env.FORKMESH_NODES.get(object_id).fetch(
            "https://forkmesh.internal/api/nodes/state")
        data = await response.json()
        # Response.json() crosses the Python/JS boundary as a native dict or a
        # JsProxy depending on where it was built (see _flagship_client_count).
        agents = (data.get("agents", 0) if isinstance(data, dict)
                  else getattr(data, "agents", 0))
        return int(agents or 0) > 0
    except Exception:
        return False


async def _node_events_watch_object(env, request):
    params = parse_qs(urlparse(request.url).query)
    if "watch" not in params:
        return "", None
    if (request.headers.get("upgrade") or "").lower() != "websocket":
        return "", json_response({"error": "upgrade_required"}, status=426)
    owner, _, repo = str(params.get("watch", [""])[0] or "").partition("/")
    owner = (safe_segment(owner) or "").lower()
    repo = (safe_segment(repo) or "").lower()
    if not valid_node_name(owner) or not repo:
        return "", json_response({"error": "invalid_watch"}, status=400)
    owner = (await _org_repo_node(env, owner, repo) or owner).lower()
    try:
        context = await _https_mirror_public_context(env, owner, repo)
    except Exception:
        return "", json_response(
            {"error": "unavailable"}, status=503,
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    if not context:
        return "", json_response({"error": "not_found"}, status=404)
    return _repo_watch_do_name(owner, repo), None


async def _node_events_object(env, request):
    watch_object, rejection = await _node_events_watch_object(env, request)
    if rejection is not None or watch_object:
        return watch_object, rejection
    owner, rejection = await _node_events_authorization(env, request)
    if rejection is not None:
        return "", rejection
    return _node_events_do_name(owner), None


async def _node_events_authorization(env, request):
    """Authorize one node socket before selecting its owner-named object."""
    upgrade = (request.headers.get("upgrade") or "").lower()
    if upgrade != "websocket":
        return "", json_response({"error": "upgrade_required"}, status=426)
    params = parse_qs(urlparse(request.url).query)
    ticket = params.get("ticket", [""])[0]
    if ticket:
        owner = _account_event_ticket_owner(env, ticket)
        if not owner:
            return "", json_response({"error": "unauthorized"}, status=401)
        # A streamed sign-in terminal has to reach the SAME object its machine
        # holds, and the two halves do not agree on which object that is. A
        # desktop node signs its drain token as the account, so it sits on
        # nodes:<account> while calling itself <hostname>; a managed mirror is
        # its own node account and sits on nodes:<mirror>. notify_repo_mirrors
        # already pays for that asymmetry by waking both identities, but a
        # stream cannot be fanned out the way a payload-free doorbell can. So
        # the browser names the machine it wants and the relay joins it to
        # whichever of the two objects that machine is actually attached to —
        # after proving the account owns it, which is the same check the agent
        # target list is built from. Nothing else on this socket changes: the
        # account channel never sends ?node=, and a machine that is simply
        # offline falls back to the account's own object and times out in the
        # page exactly as it did before.
        requested = safe_segment(params.get("node", [""])[0]) or ""
        if requested and requested.lower() != owner.lower():
            if not await _account_owns_node(env, owner, requested):
                return "", json_response({"error": "forbidden"}, status=403)
            if await _node_events_object_holds_node(env, requested):
                owner = requested
    else:
        owner = safe_segment(params.get("owner", [""])[0])
        if not owner or not await _authorize_owner(env, request, owner):
            return "", json_response({"error": "unauthorized"}, status=401)
    return owner, None


async def node_events_handler(env, request):
    # GET /api/nodes/events?owner=&ts=&sig= (WebSocket upgrade only) — a
    # desktop/headless node's live event channel. Auth reuses the same signed
    # forkmesh-issues-pull-v1 drain token as GET /api/sync (_authorize_owner),
    # checked here BEFORE any Durable Object is selected. A browser instead
    # presents ?ticket= from /api/accounts/event-ticket, which proves the same
    # account from an ordinary session. Unsolicited relay pushes are always
    # payload-free {"type":"event","topic"} frames. The socket also carries
    # the independently signed writes advertised in its hello plus correlated
    # replies from those same handlers; holding it grants no write authority,
    # and no repository bytes use this transport (the retired-tunnel contracts
    # in test_https_mirror_routing_integration.py are unaffected).
    object_name, rejection = await _node_events_object(env, request)
    if rejection is not None:
        return rejection
    node_id = env.FORKMESH_NODES.idFromName(object_name)
    # Same retry-twice guard as the chat room router: a platform abort of the
    # DO is transient, and the upgrade request carries no body so re-driving
    # durable_object_request is safe.
    last_error = None
    for _attempt in range(2):
        node_object = env.FORKMESH_NODES.get(node_id)
        try:
            return await node_object.fetch(
                await durable_object_request(request))
        except Exception as error:
            last_error = error
    await log_durable_object_abort(
        env, request, urlparse(request.url).path, last_error)
    return json_response(
        {"error": "unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS)


# Per-isolate memo of recent DO live-host probes: key_bi -> {"ts", "hosts"}
# ("hosts" is None when the probe failed/timed out). hydrate_repo_group_live_
# hosts used to await one Durable Object probe PER stale group member
# SEQUENTIALLY (up to HOST_COUNT_TIMEOUT_MS each) on every public info/refs,
# browse and /mirrors request. A logical repo group with many offline mirrors
# (a fleet die-off purges their host_presence rows, so every member stays
# "stale" forever) turned each request into minutes of awaiting dead tunnels —
# the Workers runtime then canceled the request as hung, surfacing the Pyodide
# "Cannot enter into task" error on git-upload-pack info/refs (adhoc #167, the
# same info/refs-hang family as adhoc #144/#153). Probes now run concurrently,
# are capped per request (also protecting the per-request subrequest budget),
# and every completed probe — including a failed one — is memoized briefly so
# a clone burst doesn't re-probe the same dead mirrors on every request.
_LIVE_HOST_PROBE_MEMO = {}
LIVE_HOST_PROBE_MEMO_TTL_MS = 30 * 1000
HYDRATE_PROBE_MAX = 8
# The probes run one after another (never gathered), so the count cap is not
# on its own a latency bound: eight dead mirrors would cost eight
# HOST_COUNT_TIMEOUT_MS waits. Stop the pass once it has spent this long and
# let the next request continue from the memo.
HYDRATE_PROBE_BUDGET_MS = 1500


async def hydrate_repo_group_live_hosts(env, owner, repo, catalog_rows,
                                        presence, now):
    # host_presence is an eventually-refreshed D1 cache. For routing and the
    # public mirror list, the DO's connected host count is the ground truth. Probe
    # only the logical repo group for this request and patch the in-memory
    # presence map before candidate selection.
    owner_l = str(owner or "").strip().lower()
    repo_l = str(repo or "").strip().lower()
    if not owner_l or not repo_l:
        return presence
    target = None
    for row in catalog_rows or []:
        rec = row.get("data") or {}
        if (str(rec.get("owner") or "").strip().lower() == owner_l and
                str(rec.get("name") or "").strip().lower() == repo_l):
            target = rec
            break
    if target is None:
        # Fallback mirrors can still be selected by name when the named source
        # has no catalog row yet.
        target = {"owner": owner, "name": repo, "rootCommit": ""}
    stale = []
    for row in catalog_rows or []:
        rec = row.get("data") or {}
        key = str(row.get("key_bi") or "")
        if not key or not repo_mirror_same_group(target, rec):
            continue
        # Fresh D1 presence (heartbeat within the last 30s) is trustworthy —
        # skip the per-mirror Durable Object probe subrequest for those. Only
        # stale/missing entries get the ground-truth DO check; this bounded
        # the N-subrequest fan-out that ran on every /mirrors request.
        if now - int(presence.get(key, 0) or 0) < 30 * 1000:
            continue
        memo = _LIVE_HOST_PROBE_MEMO.get(key)
        if memo and now - memo["ts"] < LIVE_HOST_PROBE_MEMO_TTL_MS:
            hosts = memo["hosts"]
            if hosts is not None:
                if hosts > 0:
                    presence[key] = now
                else:
                    presence.pop(key, None)
            continue
        stale.append((key, rec))
    # Probe SEQUENTIALLY, capped per request and under a wall-clock budget.
    # These were gathered until the Pyodide task-reentrancy wedge (see the
    # no-concurrent-tasks rule at the top of this module) — a fan-out of
    # Durable Object subrequests on the /mirrors and catalog paths is exactly
    # the shape that leaves an isolate answering 1101 forever. Serialized, the
    # cap alone is worth HYDRATE_PROBE_MAX × HOST_COUNT_TIMEOUT_MS in the
    # worst case, so HYDRATE_PROBE_BUDGET_MS stops the loop early instead.
    # Members left unprobed simply keep their stale presence this request;
    # because probed members land in the memo, the next request's stale list
    # starts where this one stopped, so a large group is covered across a few
    # requests instead of hanging any single one.
    probes = stale[:HYDRATE_PROBE_MAX]
    probe_deadline = int(Date.now()) + HYDRATE_PROBE_BUDGET_MS
    for key, rec in probes:
        try:
            hosts = await repo_live_host_count(
                env, rec.get("owner"), rec.get("name"))
        except Exception:
            hosts = None
        if not isinstance(hosts, int):
            hosts = None  # failed/timed-out probe: memoized, presence untouched
        _LIVE_HOST_PROBE_MEMO[key] = {"ts": now, "hosts": hosts}
        if hosts is not None:
            if hosts > 0:
                presence[key] = now
            else:
                presence.pop(key, None)
        if int(Date.now()) >= probe_deadline:
            break
    return presence


async def next_clone_rotation(env, repo_bi):
    # Advance and read back this repo's round-robin cursor so consecutive clone
    # fallbacks rotate across its mirrors instead of all hitting the freshest one.
    # Best-effort: any failure yields 0 (the freshest-first pick), so a flaky
    # counter never blocks a redirect.
    try:
        await ensure_schema(env)
        await d1_run(
            env,
            "INSERT INTO clone_rr (repo_bi, n) VALUES (?, 1) "
            "ON CONFLICT(repo_bi) DO UPDATE SET n = n + 1",
            repo_bi,
        )
        row = await d1_first(env, "SELECT n FROM clone_rr WHERE repo_bi=?", repo_bi)
        return int((row or {}).get("n") or 0)
    except Exception:
        return 0


async def _flagship_client_count(env):
    # One internal request to the flagship room's count endpoint (not a WebSocket).
    try:
        room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(FLAGSHIP_ROOM_KEY)
        room = env.FORKMESH_MAINNODE_ROOM.get(room_id)
        _cron_subrequest_charge()
        resp = await room.fetch(
            "https://forkmesh.internal/api/repo/mainnode/forkmesh/rooms/general/clients"
        )
        data = await resp.json()
        # workers.Response.json() may cross the Python/JS boundary as either a
        # native dict or a JsProxy depending on where the response was created;
        # accept both shapes (see the host-count read in select_install_source).
        clients = (data.get("clients", 0) if isinstance(data, dict)
                   else getattr(data, "clients", 0))
        return int(clients or 0)
    except Exception:
        return 0


async def network_stats(env, include_payouts=False, maintain_presence=True,
                        refresh=False):
    # Aggregate homepage stats: repo count (D1), live host count (presence table),
    # and flagship-room client count (one internal request). Cached at the edge.
    cache_key = NETWORK_STATS_CACHE_KEY + ("?payouts=1" if include_payouts else "")
    # A refresh press must reach the balance code, so it skips the edge copy —
    # what bounds its cost is SOLANA_DISPLAY_BALANCE_FORCE_MIN_MS, not this.
    cached = None if refresh else await edge_cache_match(cache_key)
    if cached is not None:
        return cached

    await ensure_schema(env)
    now = int(Date.now())
    repos = await _repositories_count(env, now)

    cutoff = now - HOST_PRESENCE_STALE_MS
    if maintain_presence and not _read_only(env):
        try:
            stale_repos = await notify_stale_hosts_offline(env, cutoff)
            for repo_bi in stale_repos:
                await d1_run(
                    env,
                    "DELETE FROM host_presence WHERE repo_bi=? AND ts < ?",
                    repo_bi, cutoff,
                )
        except Exception:
            pass

    # Named list of the nodes that are actually online right now (same signal the
    # uptime cron samples), so the dashboard rail can show *who* is live instead of
    # painting the 48h uptime leaderboard green — a node offline now must not look
    # active, and a node that just came up must appear even with no accrued minutes.
    #
    # The headline "Nodes" count is the size of THIS set — the distinct, publicly
    # known nodes (a catalog record or a registered account) that are live — rather
    # than a raw COUNT of host_presence rows. A plain row count over-reports: one
    # node hosting several repos counts many times, and an ad-hoc/private tunnel
    # with no public catalog record inflates the total with a node we never name.
    # Deriving the count from the named set is what makes the Network panel agree
    # with the Mirror nodes list on who is online (adhoc #93).
    try:
        online_nodes = sorted(
            {label for label in (await _live_online_nodes(env, now)).values() if label}
        )
        hosts = len(online_nodes)
    except Exception:
        online_nodes = []
        host_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM host_presence WHERE ts >= ?", cutoff
        )
        hosts = int((host_row or {}).get("n", 0) or 0)

    clients = await _flagship_client_count(env)
    payout_nodes = (
        await _network_payout_nodes(env, refresh=refresh)
        if include_payouts else None)

    resp = json_response(
        {"ok": True, "repos": repos, "hosts": hosts, "clients": clients,
         "onlineNodes": online_nodes,
         **({
             "payoutNodes": payout_nodes,
             "payoutCustody": "external-self-custodial-addresses",
             "payoutFundStates": {
                 "userOwnedFunds": (
                     "Balances belong to each external wallet owner."
                 ),
                 "communityFundedPool": (
                     "Separate public pool metadata is available from "
                     "/api/rewards/pool."
                 ),
                 "pendingRewards": (
                     "Ledger allocations only; funds remain in the external "
                     "source wallet."
                 ),
                 "completedOnChainTransfers": (
                     "Complete only after a finalized public signature."
                 ),
             },
             "payoutNotice": (
                 "Non-custodial: payout nodes publish public addresses only. "
                 "ForkMesh does not hold their funds or wallet keys, and a "
                 "listed balance or eligible state does not guarantee payment."
             ),
         } if include_payouts else {})},
        cache_seconds=NETWORK_STATS_TTL,
    )
    await edge_cache_put(cache_key, resp)
    return resp


async def _network_payout_nodes(env, refresh=False):
    cutoff = int(Date.now()) - ACCOUNT_PRESENCE_STALE_MS
    try:
        await d1_run(env, "DELETE FROM account_presence WHERE ts < ?", cutoff)
    except Exception:
        pass
    # One read of the shared hourly cache prices the whole table. Before this,
    # every 20s rebuild spent one public-RPC subrequest per listed wallet.
    stored = await _stored_wallet_balances(env)
    budget = {"left": SOLANA_DISPLAY_REFRESH_MAX_PER_REQUEST}
    rows = await d1_all(
        env,
        """SELECT n.node_bi AS name_bi, n.name, n.data, ap.ts AS online_ts
             FROM nodes n
             LEFT JOIN account_presence ap
               ON ap.name_bi = n.node_bi AND ap.ts >= ?
             ORDER BY COALESCE(ap.ts, 0) DESC, n.name ASC""",
        cutoff,
    )
    mirroring = await _mirroring_owners(env)
    nodes = []
    seen_wallets = set()
    for row in rows:
        rec = await decrypt_row(env, row.get("data"))
        if not rec or rec.get("status") != "active":
            continue
        name = clean_string(row.get("name") or rec.get("name", ""), MAX_NODE_NAME)
        wallet = (rec.get("solana") or "").strip()
        has_wallet = bool(wallet and SOLANA_RE.match(wallet))
        online = bool(row.get("online_ts"))
        first_wallet = has_wallet and wallet not in seen_wallets
        # Balance is public display metadata only. Funding a payout address is
        # never an eligibility or wallet-verification requirement — so it is
        # read from the hourly cache, and only the refresh button forces one.
        balance, checked_at = (
            await _display_balance_lamports(
                env, wallet, force=refresh, stored=stored, name=name,
                budget=budget)
            if has_wallet else (None, 0))
        # A node only shares the split if it mirrors a repo for another node, so
        # its eligibility on /network/ must reflect that too (issue #94).
        mirrors_repo = mirroring is None or bool(name and name.lower() in mirroring)
        eligible = bool(online and first_wallet and mirrors_repo)
        if has_wallet:
            seen_wallets.add(wallet)
        reason = "eligible"
        if not online:
            reason = "offline"
        elif not has_wallet:
            reason = "missing_wallet"
        elif not first_wallet:
            reason = "duplicate_wallet"
        elif not mirrors_repo:
            reason = "no_mirrors"
        nodes.append({
            "name": name or _short_presence_label("node", row.get("name_bi")),
            "wallet": wallet if has_wallet else "",
            "balanceLamports": balance,
            "balanceSol": _amount_sol(balance) if balance is not None else "",
            "balanceCheckedAt": checked_at,
            "online": online,
            "payoutEligible": eligible,
            "eligibilityReason": reason,
        })
    # Main relay: surface only federated candidates whose original node-signed
    # evidence still verifies and is fresh. Historical wallet-only rows never
    # appear payout-eligible.
    if _is_main_relay(env):
        try:
            now = int(Date.now())
            freshness = _reward_config(env)["healthFreshMs"]
            expected_refs = await _https_mirror_expected_forkmesh_refs(env)
            fed = await d1_all(
                env,
                "SELECT fp.*, r.label AS label "
                "FROM federated_presence fp "
                "JOIN relays r ON r.relay_bi = fp.relay_bi "
                "WHERE fp.ts >= ? AND r.status = 'approved' "
                "AND fp.checked_at>=? AND fp.forkmesh_verified_at>=? "
                "ORDER BY fp.ts DESC",
                cutoff,
                now - freshness,
                now - freshness,
            )
            for r in (fed or []):
                attested = await _verified_federated_reward_attestation(
                    env,
                    {
                        "name": r.get("name"),
                        "operator": r.get("name"),
                        "wallet": r.get("wallet"),
                        "publicKey": r.get("public_key"),
                        "baseUrl": r.get("base_url"),
                        "registrationSignature": r.get("registration_sig"),
                        "registrationIssuedAt": r.get(
                            "registration_issued_at"),
                        "healthMessage": r.get("health_message"),
                        "healthSignature": r.get("health_sig"),
                        "checkedAt": r.get("checked_at"),
                        "healthy": bool(int(r.get("healthy") or 0)),
                        "integrity": r.get("integrity"),
                        "mirrorsForkMesh": bool(
                            int(r.get("forkmesh_active") or 0)),
                        "forkmeshVerifiedAt": r.get(
                            "forkmesh_verified_at"),
                        "refsSha256": r.get("forkmesh_refs_sha256"),
                        "operationsSha256": r.get(
                            "forkmesh_operations_sha256"),
                        "requiredOperationsVerified": True,
                        "abuseFlagged": bool(
                            int(r.get("abuse_blocked") or 0)),
                    },
                    now,
                    expected_refs,
                    freshness,
                )
                if not attested:
                    continue
                wallet = attested["wallet"]
                eligible = wallet not in seen_wallets
                seen_wallets.add(wallet)
                relay_label = clean_string(r.get("label", ""), 80) or "relay"
                nodes.append({
                    "name": clean_string(r.get("name", ""), MAX_NODE_NAME) or "node",
                    "wallet": wallet,
                    "balanceLamports": None, "balanceSol": "",
                    "balanceCheckedAt": 0,
                    "online": True, "payoutEligible": eligible,
                    "eligibilityReason": "eligible" if eligible else "duplicate_wallet",
                    "relay": relay_label,
                    "attestation": "signed-fresh-forkmesh-mirror",
                })
        except Exception:
            pass
    return nodes


# --- Online-activity history (24h graph on /network/) -----------------------
# One weighted sample per ten-minute UTC bucket records node-minutes into the
# current hour. This preserves the graph's unit while cutting steady D1 writes
# by 90%; the ten-minute presence window matches the sampling interval. The
# live network headline still reads current presence directly; only the
# historical hourly graph accepts this bounded sampling resolution.

ONLINE_SAMPLE_CADENCE_MINUTES = 10
ONLINE_SAMPLE_WEIGHT_MINUTES = 10
ONLINE_SAMPLE_WINDOW_MS = ONLINE_SAMPLE_CADENCE_MINUTES * 60 * 1000
ONLINE_HISTORY_RETAIN_MS = 48 * 60 * 60 * 1000
ONLINE_HISTORY_MAX_NODES = 50


def _short_presence_label(prefix, key):
    return prefix + " " + str(key or "")[:8]


async def _live_online_nodes(env, now):
    nodes = {}
    host_rows = await d1_all(
        env,
        """SELECT hp.repo_bi, r.owner_bi, r.is_private, r.data
             FROM host_presence hp
             LEFT JOIN repositories r ON r.key_bi = hp.repo_bi
             WHERE hp.ts >= ?""",
        now - HOST_PRESENCE_STALE_MS,
    )
    for row in host_rows:
        # A host_presence row is written for ANY owner/repo URL that gets served
        # (touch_host_presence keys on a blind index of the path), so it includes
        # repos that were never published to the catalog — ad-hoc hosts. Those
        # rows don't join to a repository, and the public /network/ graph used to
        # surface them as anonymous "repo <hash>" phantom nodes. Only count hosts
        # serving a published, public, non-blocked repo, keyed by owner — the same
        # filtering the catalog and leaderboards apply.
        owner_bi = row.get("owner_bi")
        if not owner_bi or not row.get("data") or int(row.get("is_private") or 0):
            continue
        rec = await decrypt_row(env, row["data"])
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        label = clean_string(rec.get("owner", ""), MAX_NODE_NAME)
        if not label:
            continue
        nodes[owner_bi] = label

    endpoint_rows = await d1_all(
        env,
        """SELECT n.node_bi, n.name
             FROM mirror_https_endpoints e
             JOIN nodes n ON n.node_bi=e.node_bi
            WHERE e.healthy=1 AND e.abuse_blocked=0
              AND e.integrity='ok' AND e.checked_at>=?""",
        now - ONLINE_SAMPLE_WINDOW_MS,
    )
    for row in endpoint_rows:
        node_key = str(row.get("node_bi") or "")
        label = clean_string(row.get("name", ""), MAX_NODE_NAME)
        if node_key and label:
            nodes[node_key] = label

    acct_rows = await d1_all(
        env,
        """SELECT ap.name_bi, n.name, n.data
             FROM account_presence ap
             LEFT JOIN nodes n ON n.node_bi = ap.name_bi
             WHERE ap.ts >= ?""",
        now - ONLINE_SAMPLE_WINDOW_MS,
    )
    for row in acct_rows:
        node_key = row.get("name_bi")
        if not node_key:
            continue
        label = clean_string(row.get("name", ""), MAX_NODE_NAME)
        if not label and row.get("data"):
            rec = await decrypt_row(env, row["data"])
            if rec:
                label = clean_string(rec.get("name", ""), MAX_NODE_NAME)
        nodes[node_key] = label or nodes.get(node_key) or _short_presence_label("node", node_key)
    return nodes


NODE_UPTIME_MAX_KEYS = 2000


async def _credit_node_uptime(env, node_keys, now):
    keys = sorted({str(key) for key in node_keys or () if key})
    keys = keys[:NODE_UPTIME_MAX_KEYS]
    for offset in range(0, len(keys), 50):
        chunk = keys[offset:offset + 50]
        args = []
        for key in chunk:
            args.extend([key, ONLINE_SAMPLE_WEIGHT_MINUTES, now])
        try:
            await d1_run(
                env,
                "INSERT INTO node_uptime_totals (node_key, minutes, "
                "updated_at) VALUES " + ", ".join(["(?, ?, ?)"] * len(chunk)) +
                " ON CONFLICT(node_key) DO UPDATE SET "
                "minutes=minutes+excluded.minutes, "
                "updated_at=excluded.updated_at",
                *args)
        except Exception as error:
            print("node uptime credit failed: %s" %
                  _safe_error_text(error)[:160])
            return


async def record_online_sample(env):
    # Only aligned ten-minute buckets do the decrypt/query/write work. Keep the
    # guard for direct/self-hosted callers as well as the edge phase schedule.
    now = int(Date.now())
    minute = now // (60 * 1000)
    if minute % ONLINE_SAMPLE_CADENCE_MINUTES:
        return False
    await ensure_schema(env)
    nodes = await _live_online_nodes(env, now)
    online = len(nodes)
    await _credit_node_uptime(env, list(nodes), now)
    # The public history exposes at most fifty node series. Bound persistence
    # to the same deterministic roster so a presence spike cannot turn one
    # ten-minute sample into an unbounded Free-plan write burst.
    nodes = dict(sorted(nodes.items())[:ONLINE_HISTORY_MAX_NODES])
    hour_ts = (now // 3600000) * 3600000
    await d1_run(
        env,
        "INSERT INTO online_hourly (hour_ts, node_minutes) VALUES (?, ?) "
        "ON CONFLICT(hour_ts) DO UPDATE SET node_minutes = node_minutes + ?",
        hour_ts,
        online * ONLINE_SAMPLE_WEIGHT_MINUTES,
        online * ONLINE_SAMPLE_WEIGHT_MINUTES,
    )
    if nodes:
        # Four binds per node; chunks of twenty stay below D1's ~100-bind cap
        # even at the public 50-node roster maximum.
        node_items = list(nodes.items())
        for offset in range(0, len(node_items), 20):
            chunk = node_items[offset:offset + 20]
            node_args = []
            for node_key, label in chunk:
                node_args.extend([
                    hour_ts, node_key, label, ONLINE_SAMPLE_WEIGHT_MINUTES])
            await d1_run(
                env,
                "INSERT INTO online_hourly_nodes "
                "(hour_ts, node_key, label, node_minutes) VALUES " +
                ", ".join(["(?, ?, ?, ?)"] * len(chunk)) + " "
                "ON CONFLICT(hour_ts, node_key) DO UPDATE SET "
                "node_minutes = node_minutes + excluded.node_minutes, "
                "label = excluded.label",
                *node_args,
            )
    # Retention prunes only need to run occasionally: first sample of each hour.
    if now - hour_ts < 60 * 1000:
        await d1_run(
            env, "DELETE FROM online_hourly WHERE hour_ts < ?",
            hour_ts - ONLINE_HISTORY_RETAIN_MS,
        )
        await d1_run(
            env, "DELETE FROM online_hourly_nodes WHERE hour_ts < ?",
            hour_ts - ONLINE_HISTORY_RETAIN_MS,
        )
    return True


ONLINE_HISTORY_CACHE_KEY = "https://forkmesh.internal/api/network/online-history"


# One per-isolate copy of the per-node hourly minutes. The table only changes
# when the ten-minute online-sample phase writes, yet network_leaderboards
# (48h window) and online_history (24h window) each scanned it inside the same
# network-overview rebuild — the fifth- and sixth-largest D1 reads of
# 2026-09-11. One read of the widest window requested serves both.
_ONLINE_HOURLY_NODES_MEMO = {"ts": 0, "start": 0, "rows": None}
ONLINE_HOURLY_NODES_MEMO_TTL_MS = 5 * 60 * 1000


async def _online_hourly_node_rows(env, start, now):
    """Rows of online_hourly_nodes with hour_ts >= start, memoized per isolate."""
    start = int(start)
    now = int(now)
    memo = _ONLINE_HOURLY_NODES_MEMO
    if (
        memo["rows"] is not None
        and int(memo["start"]) <= start
        and 0 <= now - int(memo["ts"]) < ONLINE_HOURLY_NODES_MEMO_TTL_MS
    ):
        return [
            row for row in memo["rows"]
            if int(row.get("hour_ts") or 0) >= start
        ]
    rows = list(await d1_all(
        env,
        "SELECT node_key, label, hour_ts, node_minutes FROM online_hourly_nodes "
        "WHERE hour_ts >= ?",
        start,
    ) or [])
    memo["rows"] = rows
    memo["start"] = start
    memo["ts"] = now
    return list(rows)


async def online_history(env):
    # network.html polls this every five minutes per open tab (alongside the
    # already-cached leaderboards); serve the burst from the colo edge like
    # its siblings. The data is ten-minute samples in hourly buckets, so
    # five minutes of staleness is free.
    cached = await edge_cache_match(ONLINE_HISTORY_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    now = int(Date.now())
    cur_hour = (now // 3600000) * 3600000
    start = cur_hour - 23 * 3600000  # last 24 hourly buckets, oldest first
    rows = await d1_all(
        env,
        "SELECT hour_ts, node_minutes FROM online_hourly WHERE hour_ts >= ? "
        "ORDER BY hour_ts",
        start,
    )
    by_hour = {int(r["hour_ts"]): int(r["node_minutes"]) for r in rows}
    series = [{"hourTs": start + i * 3600000,
               "nodeMinutes": by_hour.get(start + i * 3600000, 0)}
              for i in range(24)]
    # Shared with network_leaderboards (which needs the wider 48h window).
    # ORDER BY node_key, hour_ts is reproduced here so the latest labelled
    # hour still wins below.
    node_rows = sorted(
        await _online_hourly_node_rows(env, start, now),
        key=lambda row: (
            str(row.get("node_key") or ""), int(row.get("hour_ts") or 0)),
    )
    grouped = {}
    for row in node_rows:
        node_key = str(row.get("node_key") or "")
        if not node_key:
            continue
        item = grouped.setdefault(node_key, {
            "label": clean_string(row.get("label", ""), MAX_NODE_NAME) or
                     _short_presence_label("node", node_key),
            "hours": {},
            "total": 0,
        })
        minutes = int(row.get("node_minutes") or 0)
        hour_ts = int(row.get("hour_ts") or 0)
        item["hours"][hour_ts] = minutes
        item["total"] += minutes
        if row.get("label"):
            item["label"] = clean_string(row.get("label", ""), MAX_NODE_NAME)
    nodes = []
    for node_key, item in grouped.items():
        nodes.append({
            "id": node_key[:12],
            "label": item["label"],
            "totalMinutes": item["total"],
            "hours": [
                {"hourTs": start + i * 3600000,
                 "minutes": item["hours"].get(start + i * 3600000, 0)}
                for i in range(24)
            ],
        })
    nodes.sort(key=lambda n: (-int(n["totalMinutes"]), str(n["label"])))
    resp = json_response(
        {"ok": True, "hours": series, "nodes": nodes[:ONLINE_HISTORY_MAX_NODES]},
        cache_seconds=ONLINE_HISTORY_TTL,
    )
    await edge_cache_put(ONLINE_HISTORY_CACHE_KEY, resp)
    return resp


async def _response_json(response):
    try:
        data = await response.json()
        return data if isinstance(data, dict) else dict(data)
    except Exception:
        return {}


async def network_overview(env, maintain_presence=True):
    cached = await edge_cache_match(NETWORK_OVERVIEW_CACHE_KEY)
    if cached is not None:
        return cached

    stats = await _response_json(await network_stats(
        env, maintain_presence=maintain_presence))
    leaderboards = await _response_json(await network_leaderboards(env))
    history = await _response_json(await online_history(env))
    resp = json_response(
        {
            "ok": True,
            "stats": stats,
            "leaderboards": leaderboards,
            "history": history,
        },
        cache_seconds=NETWORK_STATS_TTL,
    )
    await edge_cache_put(NETWORK_OVERVIEW_CACHE_KEY, resp)
    return resp


# --- System status page (/status) -------------------------------------------
# A per-minute cron folds one health check per system into today's UTC-day
# bucket, so the public /status page can show a 30-day history per system
# (statuspage.io style) without any extra always-on monitoring infra. Every
# system reuses a signal the relay already tracks:
#   - database: a trivial D1 round trip.
#   - git_hosting: at least one identity-bound direct HTTPS mirror has a fresh,
#     signed ForkMesh repository integrity proof.
#   - website / api / realtime: unhandled/5xx errors logged this minute
#     (log_error, see Default.fetch) bucketed by the path they hit, so an
#     incident in one area doesn't paint the whole site down.
#   - world_mobile: the production World's mobile bootstrap asset graph.
#   - durable_objects: room requests aborted by the Durable Objects platform
#     (log_durable_object_abort), tracked separately from the rest of
#     "realtime" without adding one actionable Worker-error row per reconnect.
STATUS_SYSTEMS = [
    ("website", "Website"),
    ("world_mobile", "World mobile startup"),
    ("status_page", "Status page API"),
    ("api", "API"),
    ("errors", "Worker errors"),
    ("database", "Database"),
    ("email", "Email delivery"),
    ("flagship_repository", "forkmesh/forkmesh repository page"),
    ("release_linux", "Linux latest version"),
    ("release_android", "Android latest version"),
    ("release_windows", "Windows latest version"),
    ("release_macos", "macOS latest version"),
    ("git_hosting", "Git hosting network"),
    ("realtime", "Realtime sync (chat & tunnels)"),
    ("durable_objects", "Durable Objects (platform aborts)"),
]
