STATUS_HISTORY_DAYS = 30
STATUS_HISTORY_RETAIN_MS = STATUS_HISTORY_DAYS * 24 * 60 * 60 * 1000
STATUS_SAMPLE_WINDOW_MS = 60 * 1000  # one cron tick
STATUS_HOUR_MS = 60 * 60 * 1000
STATUS_DAY_MS = 24 * STATUS_HOUR_MS
STATUS_MINUTES_SHOWN = 60  # width of the per-minute strip on /status
STATUS_BATCH_SCHEMA_VERSION = 1
STATUS_BATCH_MAX_BYTES = {
    "minute": 128 * 1024,
    "hour": 128 * 1024,
    "day": 64 * 1024,
}
# Rebuild a completed hour/day during its first five minutes. Absolute batch
# bodies plus a WHERE-different UPSERT make retries write-free, while catching
# a delayed final minute at a deploy/alarm boundary.
STATUS_COMPACTION_RETRY_MS = 5 * 60 * 1000
# A Cache-Control header alone does not cache a response generated by a Worker.
# Keep both compatibility projections in the Cache API as well. The cron's
# public snapshot build refreshes and populates the full key once after the
# minute sample; browsers and the World now share that exact canonical body.
# Cron replaces these entries after each atomic three-minute publication. Keep
# the last known body long enough to bridge two delayed ticks or a short DO
# incident; outgoing responses remain explicitly no-store and are relabelled
# emergency-stale once their four-minute snapshot evidence is no longer fresh.
# Keep the internal, validated status snapshot available for a full day. Public
# responses are still no-store and the minute publisher deletes/replaces these
# keys after each successful D1 commit, so this is a recovery window rather
# than user-visible staleness. A short ten-minute TTL made /api/status depend on
# the shared Durable Object allowance precisely when that allowance was down.
STATUS_EDGE_CACHE_TTL = 24 * 60 * 60
STATUS_EDGE_CACHE_KEYS = {
    "full": "https://forkmesh.internal/api/status/full-v1",
    "world": "https://forkmesh.internal/api/status/world-v1",
}
# Bound every static-asset status probe independently. These fetches used to
# be the one unbounded await in the minute sampler; one poisoned asset promise
# could retain the whole scheduled event indefinitely.
STATUS_ASSET_FETCH_TIMEOUT_MS = 5_000
# Keep thirty hours of roster-independent minute batches. Public reads still
# query exactly sixty minutes, while the bounded compactor can reconstruct a
# missed hour during the following day's oldest-first catch-up pass.
STATUS_MINUTE_RETAIN_MS = 30 * STATUS_HOUR_MS
STATUS_MIRROR_PREFIX = "mirror:"
STATUS_MIRROR_MAX = 50
STATUS_MIRROR_ROSTER_FRESH_MS = 24 * 60 * 60 * 1000
STATUS_CORE_PREFIX = "core:"
