STATUS_CORE_ROSTER_FRESH_MS = 24 * 60 * 60 * 1000
STATUS_CORE_HEARTBEAT_FRESH_MS = 30 * 1000
STATUS_CORE_VOTE_FRESH_MS = 90 * 1000
STATUS_CORE_IDS_FRESH_MS = 180 * 1000
STATUS_RUNNER_PREFIX = "runner:"
STATUS_RUNNER_MAX = 32
