def _flagship_monitor_duration(milliseconds):
    seconds = max(0, int(milliseconds or 0) // 1000)
    if seconds < 60:
        return "%d second%s" % (seconds, "" if seconds == 1 else "s")
    minutes = seconds // 60
    if minutes < 60:
        return "%d minute%s" % (minutes, "" if minutes == 1 else "s")
    hours = minutes // 60
    remainder = minutes % 60
    return "%d hour%s%s" % (
        hours,
        "" if hours == 1 else "s",
        (" %d minute%s" % (
            remainder, "" if remainder == 1 else "s")) if remainder else "",
    )


def _deployment_status_grace_active(env, now):
    try:
        deployed_at = int(getattr(env, "DEPLOYED_AT_MS", 0) or 0)
    except (TypeError, ValueError):
        return False
    age = int(now) - deployed_at
    return deployed_at > 0 and 0 <= age < STATUS_DEPLOY_GRACE_MS


async def _routed_repository_read(
        env, url, operation, release_sha="", bypass_cache=False,
        monitoring=False, context_cache=None, retry_failed_proofs=False,
        method="GET"):
    request = (JsRequest.new(url) if method == "GET"
               else JsRequest.new(url, to_js({"method": method})))
    route_url = urlparse(request.url)
    aliased = await org_alias_rewrite(env, request, route_url)
    if aliased is not None:
        request, route_url = aliased
    route = (
        RELEASE_BLOB_RE.match(route_url.path)
        if operation == "release-blob"
        else GIT_INFO_RE.match(route_url.path)
        if operation == "git-info-refs"
        else REPO_HOST_RE.match(route_url.path)
    )
    if not route:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    return await _https_mirror_proxy(
        env, request, safe_segment(route.group(1)),
        safe_segment(route.group(2)), operation,
        release_sha=release_sha, bypass_cache=bypass_cache,
        monitoring=monitoring, context_cache=context_cache,
        retry_failed_proofs=retry_failed_proofs)


async def _flagship_repository_status(
        env, now, allow_probe=True, force_probe=False,
        force_failed_probe=False):
    row = await d1_first(
        env,
        "SELECT is_up,reason,changed_at,checked_at "
        "FROM repository_monitor_state "
        "WHERE monitor_id=?",
        FLAGSHIP_DEEP_MONITOR_ID,
    )
    if row:
        checked_at = max(0, int(row.get("checked_at") or 0))
        changed_at = max(0, int(row.get("changed_at") or 0))
        is_up = int(row.get("is_up") or 0) == 1
        # A failed probe is eligible for an eager retry, but the minute sampler
        # cannot perform that routed work: isolated full/retry phases own it.
        # Keep any completed result valid for the full monitoring interval when
        # probes are disabled so the sampler preserves the actionable failure
        # reason instead of manufacturing "did not complete" rows between
        # scheduled retries. Probe-capable callers still use the shorter
        # failed-result cadence.
        if not allow_probe:
            interval = FLAGSHIP_RESULT_STALE_MS
        elif is_up:
            interval = FLAGSHIP_CHECK_INTERVAL_MS
        else:
            interval = FLAGSHIP_FAILED_RETRY_MS
        if (
            not force_probe
            and checked_at
            and 0 <= int(now) - checked_at < interval
            and not (force_failed_probe and not is_up)
        ):
            if (
                not allow_probe
                and not is_up
                and changed_at
                and 0 <= int(now) - changed_at < FLAGSHIP_FAILURE_CONFIRM_MS
            ):
                # The retry phase owns confirmation. The sampler stays
                # read-only and keeps the last public state green during this
                # short window; real visitor 5xx evidence is folded in after
                # this call and still fails the same minute.
                return True, ""
            return is_up, str(row.get("reason") or "")
    if not allow_probe:
        if row and int(row.get("checked_at") or 0) > 0:
            return False, (
                "The forkmesh/forkmesh deep probe did not complete within "
                "its monitoring interval")
        return False, "The forkmesh/forkmesh deep probe has not completed"
    is_up, reason = await _flagship_repository_probe(env)
    await d1_run(
        env,
        """INSERT INTO repository_monitor_state
             (monitor_id,is_up,changed_at,outage_started_at,checked_at,reason,
              notified_state,pinged_state)
           VALUES (?,?,?,?,?,?,?,?)
           ON CONFLICT(monitor_id) DO UPDATE SET
             is_up=excluded.is_up,
             changed_at=CASE
               WHEN repository_monitor_state.is_up!=excluded.is_up
               THEN excluded.checked_at
               ELSE repository_monitor_state.changed_at END,
             outage_started_at=CASE
               WHEN excluded.is_up=1 THEN 0
               WHEN repository_monitor_state.is_up!=excluded.is_up
               THEN excluded.checked_at
               ELSE repository_monitor_state.outage_started_at END,
             checked_at=excluded.checked_at,reason=excluded.reason""",
        FLAGSHIP_DEEP_MONITOR_ID, 1 if is_up else 0, int(now),
        0 if is_up else int(now), int(now),
        clean_string(reason or "", 240), "", "",
    )
    return bool(is_up), str(reason or "")


async def _flagship_repository_probe(env):
    """Exercise the same shell, Git, and mirror reads the public URL renders."""
    routing_contexts = {}

    async def bounded_response(response, maximum):
        status = int(getattr(response, "status", 0) or 0)
        try:
            announced = int(response.headers.get("content-length") or 0)
        except Exception:
            announced = 0
        if announced > maximum:
            await _discard_response_body(response)
            return status, "", ""
        body = str(await response.text())
        try:
            served_by = clean_string(
                response.headers.get("X-ForkMesh-Served-By") or "",
                MAX_NODE_NAME,
            ).strip().lower()
        except Exception:
            served_by = ""
        return (
            (status, body, served_by)
            if len(body.encode("utf-8")) <= maximum
            else (status, "", served_by)
        )

    async def routed_json(label, url, operation, maximum=2 * 1024 * 1024):
        async def read(context_cache, retry_failed_proofs=False):
            response = await _routed_repository_read(
                env, url, operation, bypass_cache=True, monitoring=True,
                context_cache=context_cache,
                retry_failed_proofs=retry_failed_proofs)
            return await bounded_response(response, maximum)

        status, text, served_by = await read(routing_contexts)
        if status == 404:
            # Endpoint health and proof caches can turn over between the
            # minute health phase and this deep read. A fresh public request
            # succeeding immediately afterward means the repository was not
            # down. A 404 is retryable here: during a revision handoff one
            # reachable mirror can answer absent while other candidates' proof
            # refreshes are still pending. Repeat one non-success through a new
            # candidate set and bypass only the failed-proof memo from the
            # first attempt. Do not immediately replay a 5xx: the router already
            # exhausted its eligible candidates, so a second sweep only doubles
            # upstream errors and subrequests. Live visitor 5xx evidence still
            # marks the row red at the next minute sample.
            status, text, served_by = await read(
                {}, retry_failed_proofs=True)
        if status != 200:
            return None, "%s failed (HTTP %d)" % (label, status)
        if not served_by:
            return None, "%s was not served by an eligible mirror" % label
        try:
            data = json.loads(text)
        except Exception:
            data = {}
        if not isinstance(data, dict):
            data = {}
        return data, "" if data else "%s returned an invalid response" % label

    def numbered_tree(entries):
        return next((
            item for item in (entries if isinstance(entries, list) else [])
            if isinstance(item, dict)
            and str(item.get("type") or "").lower() == "tree"
            and re.fullmatch(r"[1-9][0-9]*", str(item.get("name") or ""))
        ), None)

    async def readable_blob(label, path, ref="", json_record=False):
        suffix = "?path=" + quote(path)
        if ref:
            suffix += "&ref=" + quote(ref)
        data, error = await routed_json(
            label,
            "https://forkmesh.internal/api/repo/forkmesh/forkmesh/blob" + suffix,
            "blob",
            1024 * 1024,
        )
        content = str((data or {}).get("content") or "")
        if error:
            return error
        if (data or {}).get("ok") is not True or not content.strip():
            return "%s body did not load" % label
        if json_record:
            try:
                record = json.loads(content)
            except Exception:
                record = None
            if not isinstance(record, dict) or not record:
                return "%s body was not valid JSON" % label
        return ""

    async def readable_record(label, path, ref="", json_record=False):
        suffix = "?path=" + quote(path)
        if ref:
            suffix += "&ref=" + quote(ref)
        data, error = await routed_json(
            label,
            "https://forkmesh.internal/api/repo/forkmesh/forkmesh/blobs" + suffix,
            "blobs",
            1024 * 1024,
        )
        if error:
            return error
        blobs = (data or {}).get("blobs")
        blob = blobs.get(path) if isinstance(blobs, dict) else None
        content = str(blob.get("content") or "") if isinstance(blob, dict) else ""
        if not content.strip():
            return "%s body did not load" % label
        if json_record:
            try:
                record = json.loads(content)
            except Exception:
                record = None
            if not isinstance(record, dict) or not record:
                return "%s body was not valid JSON" % label
        return ""

    # The repository page's browse reads can remain healthy while Git smart
    # HTTP is unavailable. Exercise the clone advertisement explicitly: it is
    # the first request made by every Git client and must not be inferred from
    # a successful tree/blob response.
    git_response = await _routed_repository_read(
        env,
        "https://forkmesh.internal/forkmesh/forkmesh/info/refs"
        "?service=git-upload-pack",
        "git-info-refs",
        bypass_cache=True,
        monitoring=True,
        context_cache=routing_contexts,
    )
    git_status = int(getattr(git_response, "status", 0) or 0)
    try:
        git_served_by = clean_string(
            git_response.headers.get("X-ForkMesh-Served-By") or "",
            MAX_NODE_NAME,
        ).strip().lower()
    except Exception:
        git_served_by = ""
    await _discard_response_body(git_response)
    if git_status != 200:
        return False, "Git clone advertisement failed (HTTP %d)" % git_status
    if not git_served_by:
        return False, "Git clone advertisement was not served by an eligible mirror"

    # Scheduled Workers cannot hairpin through their own public hostname
    # reliably (Cloudflare returns a synthetic 404/52x before the request
    # reaches the Worker). Read the same static shell from the bound asset
    # service and invoke the same authenticated mirror router used by the
    # public tree/blob endpoints. Repository bytes still come from active
    # nodes; none are substituted from D1 or a Worker-side copy.
    _cron_subrequest_charge()
    shell_response = await env.ASSETS.fetch(JsRequest.new(
        "https://forkmesh.internal/dashboard/repo.html"))
    shell_status, shell_text, _shell_served_by = await bounded_response(
        shell_response, 512 * 1024)
    if shell_status != 200 or 'data-page="repo"' not in shell_text:
        return False, "Repository page shell did not load (HTTP %d)" % shell_status

    tree_data, tree_error = await routed_json(
        "Root repository tree",
        "https://forkmesh.internal/api/repo/forkmesh/forkmesh/tree?path=",
        "tree",
    )
    if tree_error:
        return False, tree_error
    entries = tree_data.get("entries") if isinstance(tree_data, dict) else []
    has_readme = any(
        isinstance(item, dict)
        and str(item.get("name") or "").lower() == "readme.md"
        and str(item.get("type") or "").lower() == "blob"
        for item in (entries if isinstance(entries, list) else [])
    )
    if tree_data.get("ok") is not True:
        return False, "Root repository tree returned an invalid response"
    if not has_readme:
        names = ",".join(
            clean_string(item.get("name", ""), 40)
            for item in entries[:8] if isinstance(item, dict))
        return False, (
            "Root repository tree did not contain README.md"
            + (": " + names if names else ""))

    # The default branch can advance while this multi-read suite is running.
    # Anchor every remaining default-branch read to the exact commit returned
    # by the root tree so a healthy rollout cannot mix two repository
    # generations and manufacture a transient 404.
    snapshot_ref = clean_string(tree_data.get("commit") or "", 64).lower()
    if not re.fullmatch(r"[0-9a-f]{40}", snapshot_ref):
        return False, "Root repository tree did not identify its commit"

    error = await readable_blob("README.md", "README.md", snapshot_ref)
    if error:
        return False, error

    # Issues use a split open/closed layout, with a legacy numbered-root
    # fallback. Exercise the same tree and JSON blob reads as the Issues tab.
    issues, error = await routed_json(
        "Issues collection",
        "https://forkmesh.internal/api/repo/forkmesh/forkmesh/"
        "tree?path=.forkmesh/issues&ref=" + quote(snapshot_ref),
        "tree",
    )
    if error:
        return False, error
    issue = numbered_tree(issues.get("entries"))
    issue_base = ".forkmesh/issues"
    if issue is None:
        status_dirs = [
            item for item in (issues.get("entries") or [])
            if isinstance(item, dict)
            and str(item.get("type") or "").lower() == "tree"
            and str(item.get("name") or "").lower() in ("open", "closed")
        ]
        status_dirs.sort(
            key=lambda item: 0 if str(item.get("name")).lower() == "open" else 1)
        for status_dir in status_dirs:
            issue_base = str(status_dir.get("path") or "")
            issue_tree, error = await routed_json(
                "Issues %s collection" % str(status_dir.get("name") or ""),
                "https://forkmesh.internal/api/repo/forkmesh/forkmesh/"
                "tree?path=" + quote(issue_base)
                + "&ref=" + quote(snapshot_ref),
                "tree",
            )
            if error:
                return False, error
            issue = numbered_tree(issue_tree.get("entries"))
            if issue is not None:
                break
    if issue is None:
        return False, "Issues collection did not contain a readable issue"
    issue_number = str(issue.get("name") or "")
    error = await readable_record(
        "Issue #%s" % issue_number,
        "%s/%s/issue-%s.json" % (issue_base, issue_number, issue_number),
        ref=snapshot_ref,
        json_record=True,
    )
    if error:
        return False, error

    discussions, error = await routed_json(
        "Discussions collection",
        "https://forkmesh.internal/api/repo/forkmesh/forkmesh/"
        "tree?path=.forkmesh/discussions&ref=" + quote(snapshot_ref),
        "tree",
    )
    if error:
        return False, error
    discussion = numbered_tree(discussions.get("entries"))
    if discussion is None:
        return False, "Discussions collection did not contain a readable discussion"
    discussion_number = str(discussion.get("name") or "")
    error = await readable_record(
        "Discussion #%s" % discussion_number,
        ".forkmesh/discussions/%s/discussion.md" % discussion_number,
        ref=snapshot_ref,
    )
    if error:
        return False, error

    # The Pull requests tab resolves the metadata branch, pins its immutable
    # OID, then reads both the collection and record from that exact revision.
    branches, error = await routed_json(
        "Pull request branch list",
        "https://forkmesh.internal/api/repo/forkmesh/forkmesh/branches",
        "branches",
    )
    if error:
        return False, error
    pulls_ref = next((
        str(branch.get("commit") or "").lower()
        for branch in (branches.get("branches") or [])
        if isinstance(branch, dict)
        and branch.get("name") == "forkmesh/pulls"
        and re.fullmatch(
            r"(?:[0-9a-f]{40}|[0-9a-f]{64})",
            str(branch.get("commit") or "").lower(),
        )
    ), "")
    # An empty pull ledger is a valid repository state, not an outage. The tab
    # itself renders zero rows for it: loadRepoRecordsFromMirror() treats both
    # an absent ledger branch and an absent .forkmesh/pulls folder as "no pull
    # requests", and never falls back to main's stale copy. This probe asserts
    # that the page renders what the site would render, so it has to agree.
    if not pulls_ref:
        return True, ""
    # Decide emptiness from the parent tree, which a healthy mirror answers
    # with 200. Requesting the absent folder itself cannot distinguish "not in
    # this revision" from "no mirror served it": the router only downgrades to
    # 404 when every endpoint it reached agreed the path was absent, so one
    # endpoint failing for any other reason answers 503 mirror_unavailable.
    metadata_root, error = await routed_json(
        "Pull request metadata tree",
        "https://forkmesh.internal/api/repo/forkmesh/forkmesh/"
        "tree?path=.forkmesh&ref=" + quote(pulls_ref),
        "tree",
    )
    if error:
        return False, error
    metadata_entries = metadata_root.get("entries")
    has_pull_ledger = any(
        isinstance(item, dict)
        and str(item.get("type") or "").lower() == "tree"
        and str(item.get("name") or "") == "pulls"
        for item in (
            metadata_entries if isinstance(metadata_entries, list) else [])
    )
    if not has_pull_ledger:
        return True, ""
    pulls, error = await routed_json(
        "Pull requests collection",
        "https://forkmesh.internal/api/repo/forkmesh/forkmesh/"
        "tree?path=.forkmesh%2Fpulls&ref=" + quote(pulls_ref),
        "tree",
    )
    if error:
        return False, error
    pull = numbered_tree(pulls.get("entries"))
    if pull is None:
        # The ledger folder survives its last numbered record being deleted
        # only until git prunes the empty tree, so both shapes mean "no pull
        # requests" and both must read the same as the rendered tab.
        return True, ""
    pull_number = str(pull.get("name") or "")
    error = await readable_record(
        "Pull request #%s" % pull_number,
        ".forkmesh/pulls/%s/pull.md" % pull_number,
        ref=pulls_ref,
    )
    if error:
        return False, error
    return True, ""


# Platform operational-alert state. It uses the flagship repository identity
# as a stable storage key, but only the is_admin console may mutate it.
# Inbox pings are on by default so a fresh deployment has visible operational
# feedback without requiring mail credentials. Email remains an explicit opt-in.
REPO_ALERT_SETTING_DEFAULTS = {
    # "[ForkMesh outage]" / "[ForkMesh recovered]" mail for the systems on
    # /status and the independent cron watchdog. One switch covers both
    # directions: a recovery notice only makes sense to whoever got the outage.
    "statusEmails": False,
    "statusPings": True,
    # Per-monitor overrides back the admin-only alert-settings page. The old
    # global switches remain for stored-row compatibility and as defaults for
    # a newly discovered mirror row. Homepage continual paging is deliberately
    # selected out of the box: a persistent public outage must not disappear
    # behind one notification that was missed or trimmed from the inbox.
    "statusMonitors": {},
}

STATUS_ALERT_CONTINUAL_INTERVAL_MS = 5 * 60 * 1000
STATUS_ALERT_ADMIN_BATCH = 4
STATUS_ALERT_ADMIN_SYSTEMS = list(STATUS_SYSTEMS) + [
    ("mirror:*", "All mirror nodes"),
    ("core:*", "All core nodes"),
    ("runner:*", "All runners"),
]


def _status_monitor_alert_setting(settings, system_id, channel):
    settings = settings if isinstance(settings, dict) else {}
    monitors = settings.get("statusMonitors")
    monitors = monitors if isinstance(monitors, dict) else {}
    monitor = monitors.get(system_id)
    if not isinstance(monitor, dict) and system_id.startswith(STATUS_MIRROR_PREFIX):
        monitor = monitors.get("mirror:*")
    if not isinstance(monitor, dict) and system_id.startswith(STATUS_CORE_PREFIX):
        monitor = monitors.get("core:*")
    if not isinstance(monitor, dict) and system_id.startswith(
            STATUS_RUNNER_PREFIX):
        monitor = monitors.get("runner:*")
    monitor = monitor if isinstance(monitor, dict) else {}
    if channel in monitor:
        return bool(monitor[channel])
    if channel == "emails":
        return bool(settings.get("statusEmails", False))
    if channel == "pings":
        return bool(settings.get("statusPings", True))
    # The public status page is the operator's visibility into every other
    # monitor. Its outage must keep paging by default even when all of those
    # individual checks remain green.
    if channel != "continual":
        return False
    return (system_id in ("website", "status_page")
            or system_id.startswith(STATUS_CORE_PREFIX))


async def _repo_alert_settings_bi(env, owner, repo):
    # Same keying rules as _ap_repo_settings_bi (distinct namespace, both
    # halves lowercased, org aliases resolved to the backing node) so the row
    # an admin writes under the org name is the row the send path reads.
    alias_owner = globals().get("_ap_org_alias_owner")
    if callable(alias_owner):
        owner = await alias_owner(env, owner, repo)
    return await blind_index(
        env, "repo-alert-settings:%s/%s" % (
            str(owner or "").strip().lower(),
            str(repo or "").strip().lower()))


async def _repo_alert_settings_get(env, owner, repo):
    settings = dict(REPO_ALERT_SETTING_DEFAULTS)
    try:
        row = await d1_first(
            env, "SELECT data FROM repo_alert_settings WHERE repo_bi=?",
            await _repo_alert_settings_bi(env, owner, repo))
    except BaseException:
        # A lazily-ensured DB without the table reads as "all off", which is
        # the safe direction: no mail rather than unsuppressable mail.
        return settings
    if row:
        try:
            stored = json.loads(row.get("data") or "{}")
        except Exception:
            stored = {}
        if isinstance(stored, dict):
            for key in REPO_ALERT_SETTING_DEFAULTS:
                if key in stored:
                    if key == "statusMonitors" and isinstance(stored[key], dict):
                        settings[key] = stored[key]
                    elif key != "statusMonitors":
                        settings[key] = bool(stored[key])
    return settings


STATUS_ALERT_MANAGE_URL = (
    "https://forkmesh.com/dashboard/settings/notifications#admin-alerts")


async def _status_alert_emails_enabled(env, system_id=None):
    """Has a platform is_admin opted into outage mail?

    The /status systems and the cron watchdog are properties of the whole
    deployment, so they hang off the flagship repository's stable storage key.
    """
    owner, _, repo = FLAGSHIP_MONITOR_ID.partition("/")
    settings = await _repo_alert_settings_get(env, owner, repo)
    if system_id:
        return _status_monitor_alert_setting(settings, system_id, "emails")
    return bool(settings["statusEmails"])


async def _status_alert_pings_enabled(env, system_id=None):
    """Should outage and recovery transitions enter administrators' Pings?"""
    owner, _, repo = FLAGSHIP_MONITOR_ID.partition("/")
    settings = await _repo_alert_settings_get(env, owner, repo)
    if system_id:
        return _status_monitor_alert_setting(settings, system_id, "pings")
    return bool(settings["statusPings"])


def _status_recovery_ping_body(alert, now):
    """Recovery copy that still names the outage it closes.

    A bare "green again" line reads the same whether the system blinked for a
    minute or was down for an hour, and it is the only ping an administrator
    sees when the outage ping could not be delivered.
    """
    # Only the sample that actually flipped green knows an outage window. A
    # re-send of an undelivered recovery ping must not describe the time since
    # the recovery as downtime.
    started = int(alert.get("recovered_outage_started_at") or 0)
    minutes = int((int(now) - started) // 60000) if started else 0
    if started and minutes >= 0:
        duration = (
            "under a minute" if minutes < 1 else
            "1 minute" if minutes == 1 else
            "%d minutes" % minutes)
        reason = clean_string(alert.get("prior_reason", ""), 200)
        return (
            "Down for %s. The current /status probe is green again.%s" % (
                duration, (" Last failure: " + reason) if reason else ""))
    return "The current /status probe is green again."


async def _enqueue_operational_alert_pings(env, alerts, now):
    """Best-effort, deduplicated operational alerts for every platform admin."""
    if not alerts:
        return False
    owner, _, repo = FLAGSHIP_MONITOR_ID.partition("/")
    alert_settings = await _repo_alert_settings_get(env, owner, repo)
    rows = await d1_all(
        env, "SELECT data FROM users WHERE is_admin=1 "
        "ORDER BY user_bi LIMIT ?", STATUS_ALERT_ADMIN_BATCH)
    delivered = False
    for row in rows or []:
        try:
            record = await decrypt_row(env, row.get("data", "")) or {}
        except Exception:
            continue
        admin = clean_string(
            record.get("name", ""), MAX_NODE_NAME).strip().lower()
        if not valid_node_name(admin):
            continue
        for alert in alerts:
            recovered = bool(alert.get("is_up"))
            system_id = clean_string(alert.get("system", ""), 120)
            if not _status_monitor_alert_setting(
                    alert_settings, system_id, "pings"):
                continue
            label = clean_string(alert.get("label", ""), 160)
            # One ping per transition, not per sample: the stamp must identify
            # the transition itself. outage_started_at is 0 once a system is
            # green, so a recovery keys off the change stamp instead.
            stamp = int(
                (int(now) // STATUS_ALERT_CONTINUAL_INTERVAL_MS)
                * STATUS_ALERT_CONTINUAL_INTERVAL_MS
                if alert.get("continual") and not recovered else
                alert.get("changed_at")
                or alert.get("outage_started_at")
                or now)
            title = (
                label + " recovered" if recovered else
                label + " needs attention")
            body = (
                _status_recovery_ping_body(alert, now) if recovered else
                clean_string(alert.get("reason", ""), 240)
                or "The current /status health check failed.")
            await enqueue_notification(
                env, admin, "operational_alert", title, body=body,
                href="/status", source="operational-status",
                dedupe="operational-status:%s:%s:%s" % (
                    system_id, "up" if recovered else "down", stamp),
                ts=now,
                meta={"system": system_id,
                      "state": "up" if recovered else "down"},
            )
            alert["_ping_delivered"] = True
            delivered = True
    return delivered


async def _record_operational_alert_pings_sent(env, alerts):
    """Mark delivered ping transitions so the next sample stays quiet."""
    for alert in alerts:
        # _enqueue_operational_alert_pings may receive a mixed batch whose
        # per-monitor page settings disable some rows. Do not mark a skipped
        # row as delivered merely because another row in the batch was sent.
        if not alert.get("_ping_delivered"):
            continue
        system_id = clean_string(alert.get("system", ""), 120)
        if not system_id:
            continue
        # is_up guards the write against a sample that flipped underneath this
        # send, exactly like the mail path's notified_state update.
        await d1_run(
            env,
            "UPDATE repository_monitor_state SET pinged_state=? "
            "WHERE monitor_id=? AND is_up=?",
            "up" if alert.get("is_up") else "down", "status:" + system_id,
            1 if alert.get("is_up") else 0,
        )


