async def _admin_self_deploys(env, request):
    _, record = await _account_session_record(env, request)
    actor = clean_string(
        (record or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401,
                             cache_control="no-store")
    if not await _is_admin(env, actor):
        return json_response({"error": "forbidden"}, status=403,
                             cache_control="no-store")
    return json_response(
        {"ok": True, "deploys": await _deploy_approvals.recent(env)},
        cache_control="no-store")


async def _admin_cron_report(env, request):
    # Admin-signed, read-only account of the maintenance loop: the declared
    # schedule, the retained per-tick history the dispatcher writes, and the
    # runtime switches that decide what a tick delivers. Read-only, and it
    # costs two D1 reads rather than waking a single maintenance object.
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    canonical = (
        "forkmesh-admin-cron-report-v1\n" + node + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    await ensure_schema(env)
    settings = await _repo_alert_settings_get(
        env, *FLAGSHIP_MONITOR_ID.split("/", 1))
    try:
        payload = await cron_activity_report(
            env, int(Date.now()), CRON_TICK_REPORT_LIMIT, settings)
    except BaseException as error:
        # A database that has not yet applied the tick table must still render
        # the schedule and settings rather than an empty tab.
        payload = {
            "ok": True, "sampledAt": int(Date.now()),
            "error": "history_unavailable",
            "detail": _safe_error_text(error)[:160],
            "phases": [], "ticks": [],
            "settings": cron_settings_rows(settings),
        }
    return json_response(
        payload, cache_control="no-store, max-age=0, must-revalidate")


async def _repository_monitor_admin_emails(env):
    recipients = {
        value.strip().lower()
        for value in str(
            getattr(env, "ADMIN_ALERT_EMAILS", "") or ""
        ).split(",")
        if "@" in value
    }
    rows = await d1_all(
        env, "SELECT data FROM users WHERE is_admin=1 "
        "ORDER BY user_bi LIMIT ?", STATUS_ALERT_ADMIN_BATCH)
    for row in rows or []:
        try:
            record = await decrypt_row(env, row.get("data", "")) or {}
            if record.get("service_account") is True:
                continue
            email = clean_string(record.get("email", ""), 254).strip().lower()
            if email and "@" in email and record.get("email_verified") is True:
                recipients.add(email)
        except Exception:
            continue
    return sorted(
        address for address in recipients
        if mail_budget.deliverable(address, env))[:STATUS_ALERT_ADMIN_BATCH]


def _sanitize_attention_log_text(value, maximum=600):
    """Bound and redact an operator-only log excerpt before it enters email."""
    if isinstance(value, (dict, list)):
        try:
            value = json.dumps(
                value, sort_keys=True, separators=(",", ":"))
        except Exception:
            value = ""
    text = "".join(
        character if character.isprintable() else " "
        for character in str(value or ""))
    # URLs retain the useful route but never a query/fragment carrying a token.
    text = re.sub(r"(https?://[^\s?#]+)[?#][^\s]*", r"\1?[redacted]", text)
    text = re.sub(
        r"(?i)\b(bearer)\s+[A-Za-z0-9._~+/=-]+",
        r"\1 [redacted]",
        text,
    )
    text = re.sub(
        r"(?i)\b(authorization|cookie|set-cookie|password|passwd|secret|"
        r"api[_ -]?key|access[_ -]?token|refresh[_ -]?token)"
        r"\s*[:=]\s*[^\s,;]+",
        r"\1=[redacted]",
        text,
    )
    return " ".join(text.split()).strip()[:max(0, int(maximum))]


async def _cloudflare_attention_log_tail(env, now):
    """Return a safe two-minute Workers Logs excerpt or a useful placeholder."""
    account_id = clean_string(
        getattr(env, "WORKERS_OBSERVABILITY_ACCOUNT_ID", ""), 64).strip()
    token = clean_string(
        getattr(env, "WORKERS_OBSERVABILITY_API_TOKEN", ""), 512).strip()
    service = clean_string(
        getattr(env, "WORKERS_OBSERVABILITY_SERVICE", "")
        or "forkmesh-app", 128).strip()
    if not account_id or not token:
        return (
            "Cloudflare logs unavailable: configure the separately scoped "
            "Workers Observability credentials.")
    end = max(0, int(now))
    start = max(0, end - CLOUDFLARE_ATTENTION_LOG_WINDOW_MS)
    url = (
        "https://api.cloudflare.com/client/v4/accounts/" +
        quote(account_id, safe="") +
        "/workers/observability/telemetry/query")
    query = {
        "queryId": "forkmesh-attention-email",
        "timeframe": {"from": start, "to": end},
        "view": "events",
        "limit": CLOUDFLARE_ATTENTION_LOG_LIMIT,
        "dry": True,
        "parameters": {
            "datasets": ["cloudflare-workers"],
            "filterCombination": "and",
            "filters": [{
                "kind": "filter",
                "key": "$metadata.service",
                "operation": "eq",
                "type": "string",
                "value": service,
            }],
            "limit": CLOUDFLARE_ATTENTION_LOG_LIMIT,
        },
    }
    try:
        response = await js_fetch_with_timeout(
            url,
            {
                "method": "POST",
                "headers": {
                    "accept": "application/json",
                    "authorization": "Bearer " + token,
                    "content-type": "application/json",
                },
                "body": json.dumps(query, separators=(",", ":")),
                "redirect": "error",
            },
            8,
        )
        if int(getattr(response, "status", 0) or 0) != 200:
            raise RuntimeError("observability query failed")
        payload = json.loads(await response.text())
        result = payload.get("result") if isinstance(payload, dict) else {}
        event_result = result.get("events") if isinstance(result, dict) else {}
        events = (
            event_result.get("events")
            if isinstance(event_result, dict) else [])
        if not isinstance(events, list):
            events = []
    except BaseException:
        return (
            "Cloudflare logs unavailable: the bounded Observability query "
            "did not complete. The health alert was still delivered.")

    rows = []
    for event in events[:CLOUDFLARE_ATTENTION_LOG_LIMIT]:
        if not isinstance(event, dict):
            continue
        metadata = (
            event.get("$metadata")
            if isinstance(event.get("$metadata"), dict) else {})
        workers = (
            event.get("$workers")
            if isinstance(event.get("$workers"), dict) else {})
        timestamp = max(0, int(event.get("timestamp") or 0))
        level = _sanitize_attention_log_text(
            metadata.get("level") or "log", 16).upper()
        origin = _sanitize_attention_log_text(
            metadata.get("origin") or workers.get("eventType") or "", 32)
        message = _sanitize_attention_log_text(
            metadata.get("message")
            or metadata.get("error")
            or workers.get("outcome")
            or event.get("source"),
            600,
        )
        if not message:
            continue
        rows.append((timestamp, "[%d] %s%s %s" % (
            timestamp,
            level or "LOG",
            (" " + origin) if origin else "",
            message,
        )))
    rows.sort(key=lambda item: item[0])
    if not rows:
        return (
            "No sampled Cloudflare Worker log events were returned for the "
            "two minutes preceding this alert.")
    output = "\n".join(row[1] for row in rows)
    return output[:CLOUDFLARE_ATTENTION_LOG_MAX_CHARS]


def _attention_email_with_logs(text, html, log_tail):
    heading = "Cloudflare logs · prior 2 minutes"
    safe_tail = str(log_tail or "No log excerpt was available.")
    log_html = (
        "<div class=\"fm-item\" style=\"border:1px solid #d4d4d8;"
        "border-radius:8px;background:#fafafa;padding:14px;"
        "margin:0 0 18px\"><p class=\"fm-item-title\" style=\"margin:0 0 8px;"
        "color:#18181b;font-size:14px;font-weight:800\">" +
        _html_escape(heading) +
        "</p><pre style=\"margin:0;white-space:pre-wrap;overflow-wrap:anywhere;"
        "color:#3f3f46;font:12px/1.45 ui-monospace,monospace\">" +
        _html_escape(safe_tail) + "</pre></div>"
    )
    closing = "</div></div></body></html>"
    rendered_html = (
        html.replace(closing, log_html + closing, 1)
        if closing in html else html + log_html)
    return text + "\n\n" + heading + "\n" + safe_tail, rendered_html


def _status_alert_manage_url(env, system_id=""):
    # Alert delivery lives on the Pings settings page (#347), in the
    # administrator-only group; the Worker refuses its writes from anyone else.
    return STATUS_ALERT_MANAGE_URL


def _email_with_status_alert_manage_link(env, text, html, system_id=""):
    manage_url = _status_alert_manage_url(env, system_id)
    manage_text = "\n\nManage this alert: " + manage_url
    manage_html = (
        "<p class=\"fm-actions\" style=\"margin:20px 0 0\">"
        "<a class=\"fm-button\" style=\"display:inline-block;"
        "border-radius:7px;background:#15803d;color:#fff;"
        "font-size:14px;font-weight:800;padding:10px 14px;"
        "text-decoration:none\" href=\"" +
        _html_escape(manage_url) + "\">Manage this alert</a></p>"
    )
    closing = "</div></div></body></html>"
    rendered_html = (
        html.replace(closing, manage_html + closing, 1)
        if closing in html else html + manage_html
    )
    return text + manage_text, rendered_html


def _cron_watchdog_email_content(env, recovered, outage_started_at, now):
    duration = _flagship_monitor_duration(
        max(0, int(now) - int(outage_started_at or now)))
    if recovered:
        subject = "[ForkMesh recovered] Scheduled jobs are completing again"
        lead = (
            "The every-minute ForkMesh cron completed successfully again "
            "after " + duration + ".")
        text = (
            lead + "\n\nThe independent cron watchdog received a new "
            "completion heartbeat. Scheduled maintenance and status sampling "
            "have recovered.\n\nStatus: https://forkmesh.com/status")
        heading = "Scheduled jobs recovered"
        body = (
            "<div class=\"fm-item\" style=\"border:1px solid #d4d4d8;"
            "border-radius:8px;background:#fafafa;padding:14px;"
            "margin:0 0 18px\"><p class=\"fm-item-title\" style=\"margin:0;"
            "color:#18181b;font-size:14px;font-weight:800\">Interruption "
            "duration</p><p class=\"fm-item-body\" style=\"margin:6px 0 0;"
            "color:#3f3f46;font-size:14px\">" +
            _html_escape(duration) + "</p></div>")
    else:
        subject = "[ForkMesh outage] Scheduled jobs stopped completing"
        lead = (
            "The every-minute ForkMesh cron has missed its completion "
            "heartbeat for " + duration + ".")
        text = (
            lead + "\n\nObserved: no successful cron completion heartbeat was "
            "received within the three-minute watchdog window.\n\nLook here: "
            "Cloudflare Worker Cron Trigger and Python Worker exception logs."
            "\n\nSuggested first step: inspect the latest scheduled invocation "
            "for a Pyodide/asyncio exception or an invocation limit, then "
            "confirm status samples resume.\n\nA recovery email will be sent "
            "after the next completed tick.\n\nStatus: "
            "https://forkmesh.com/status")
        heading = "Scheduled jobs need attention"
        body = (
            "<div class=\"fm-item\" style=\"border:1px solid #d4d4d8;"
            "border-radius:8px;background:#fafafa;padding:14px;"
            "margin:0 0 12px\"><p class=\"fm-item-title\" style=\"margin:0;"
            "color:#18181b;font-size:14px;font-weight:800\">Observed</p>"
            "<p class=\"fm-item-body\" style=\"margin:6px 0 0;color:#3f3f46;"
            "font-size:14px\">No completed cron tick arrived within the "
            "three-minute watchdog window.</p></div>"
            "<p class=\"fm-text\" style=\"margin:0 0 18px;color:#3f3f46;"
            "font-size:14px\"><strong>Suggested first step:</strong> Inspect "
            "the Cloudflare scheduled-invocation logs, then confirm status "
            "samples resume.</p>")
    html = _forkmesh_email_card_html(
        _html_escape(heading), _html_escape(lead), body,
        "<p class=\"fm-muted\" style=\"margin:20px 0 0;color:#71717a;"
        "font-size:12px\"><a class=\"fm-link\" style=\"color:#15803d\" "
        "href=\"https://forkmesh.com/status\">Open ForkMesh status</a>"
        "</p>")
    text, html = _email_with_status_alert_manage_link(
        env, text, html, "scheduled-jobs")
    return subject, text, html


async def _send_cron_watchdog_email(
        env, recovered, outage_started_at, now):
    # Suppressed reports delivered: the caller must record the transition and
    # stop re-arming its retry alarm, otherwise turning the setting off would
    # leave the watchdog retrying a send it will never make.
    alert = {
        "system": "scheduled-jobs",
        "label": "Scheduled jobs",
        "is_up": bool(recovered),
        "reason": (
            "Scheduled jobs are completing again." if recovered else
            "No successful cron completion heartbeat arrived within the "
            "three-minute watchdog window."),
        "outage_started_at": int(outage_started_at or now),
    }
    try:
        await _enqueue_operational_alert_pings(env, [alert], now)
    except BaseException:
        pass
    try:
        if not await _status_alert_emails_enabled(env):
            return True
    except BaseException:
        return True
    try:
        recipients = await _repository_monitor_admin_emails(env)
    except BaseException:
        return False
    if not recipients:
        return False
    subject, text, html = _cron_watchdog_email_content(
        env, recovered, outage_started_at, now)
    if not recovered:
        log_tail = await _cloudflare_attention_log_tail(env, now)
        text, html = _attention_email_with_logs(text, html, log_tail)
    delivered = True
    for email in recipients:
        try:
            sent = bool(await _send_email(
                env, email, subject, text, html,
                email_kind="cron_watchdog"))
        except BaseException:
            sent = False
        delivered = sent and delivered
    return delivered


async def _cron_watchdog_completion(env):
    """Best-effort completion heartbeat to the independent alarm watchdog."""
    watchdog_id = env.FORKMESH_CRON_WATCHDOG.idFromName(CRON_WATCHDOG_NAME)
    watchdog = env.FORKMESH_CRON_WATCHDOG.get(watchdog_id)
    _cron_subrequest_charge()
    response = await watchdog.fetch(
        "https://forkmesh.internal/cron-watchdog/completed")
    if int(getattr(response, "status", 0) or 0) != 200:
        raise RuntimeError("cron watchdog rejected completion heartbeat")


