def _status_expected_checks_for_hour(hour_ts, now):
    """How many minute samples should exist for an elapsed hourly bucket.

    The current in-progress minute is not expected yet. This prevents the public
    page from flashing degraded between the page load and the next cron tick.
    Missing completed minutes/hours remain visible as monitoring gaps, but are
    never evidence that the checked service was down.
    """
    hour_ts = int(hour_ts)
    now = int(now)
    if hour_ts > now:
        return 0
    if now >= hour_ts + STATUS_HOUR_MS:
        return 60
    return max(0, int((now - hour_ts) // STATUS_SAMPLE_WINDOW_MS))


def _status_effective_hour(hour_ts, now, row):
    """Fold one hourly bucket into what the /status page shows.

    Recorded samples decide service failures. A missing sample means the
    sampling cron itself did not run, not that every monitored service failed
    at once. Report the gap through missingChecks / monitoringState and keep it
    out of the service failure count and state, but include it in the displayed
    availability denominator so a non-green history bucket cannot claim 100%.
    The page renders these no-evidence buckets with a distinct monitoring
    shade while a single global warning explains the shared sampling delay.
    """
    checks, failures, reason = row or (0, 0, None)
    checks = max(0, int(checks or 0))
    failures = max(0, min(int(failures or 0), checks))
    expected = max(_status_expected_checks_for_hour(hour_ts, now), checks)
    if expected <= 0:
        return {
            "hourTs": hour_ts, "status": "future", "checks": checks,
            "failures": failures, "expectedChecks": 0, "missingChecks": 0,
            "reason": None, "monitoringState": None,
        }
    missing = max(0, expected - checks)
    if checks <= 0:
        status = "unknown"
    elif failures <= 0:
        status = "operational"
    elif failures >= checks:
        status = "down"
    else:
        status = "degraded"
    if checks <= 0:
        hour_reason = (
            "Monitoring failed: no health samples were recorded for this "
            "elapsed hour.")
    elif status == "operational":
        hour_reason = None
    else:
        hour_reason = reason
    return {
        "hourTs": hour_ts, "status": status,
        "checks": checks, "failures": failures,
        "expectedChecks": expected, "missingChecks": missing,
        "reason": hour_reason,
        "monitoringState": (
            "empty" if checks <= 0
            else "missing" if missing > 0 and failures <= 0
            else None),
    }


def _status_minute(minute_ts, current_minute_ts, row):
    """Status of a single 60-second bucket for the /status minute strip.

    Unlike an hour, a minute has no finer subdivision to average over: it's
    either sampled ok, sampled failing, missing because monitoring did not run,
    or (if it is the in-progress minute) not sampled yet. Missing elapsed data
    has no service-health evidence, so it is neutral rather than fabricated
    downtime; no "degraded" state is possible at this granularity.
    """
    minute_ts = int(minute_ts)
    if minute_ts >= current_minute_ts and row is None:
        # This minute's cron tick hasn't landed yet (the common case for the
        # newest bucket) — not evidence of an outage, just not elapsed.
        return {
            "minuteTs": minute_ts, "status": "future", "reason": None,
            "monitoringState": None,
        }
    if row is None:
        return {
            "minuteTs": minute_ts, "status": "unknown",
            "reason": "Monitoring failed: no health sample was recorded for "
                      "this elapsed minute.",
            "monitoringState": "missing",
        }
    ok = bool(row.get("ok"))
    return {
        "minuteTs": minute_ts,
        "status": "operational" if ok else "down",
        "reason": None if ok else (row.get("reason") or None),
        "monitoringState": None,
    }


async def _status_deploy_semaphore_active(env, now=None):
    """Suppress alerts during a bounded deploy and its activation grace.

    D1 is shared by the retiring and newly activated Workers, unlike a build
    timestamp environment variable. That makes this lifecycle the authority
    for every health monitor during the rollout handoff.
    """
    try:
        row = await d1_first(
            env,
            "SELECT state,started_at,finished_at "
            "FROM world_deploy_status WHERE singleton=1",
        )
    except Exception:
        return False
    if not row:
        return False
    if now is None:
        now = int(Date.now())
    try:
        now = int(now)
        started_at = int(row.get("started_at") or 0)
        finished_at = int(row.get("finished_at") or 0)
    except (TypeError, ValueError):
        return False
    state = str(row.get("state") or "")
    if state == "deploying":
        age = now - started_at
        return started_at > 0 and 0 <= age < STATUS_DEPLOY_MAX_MS
    if state == "ready":
        age = now - finished_at
        return finished_at > 0 and 0 <= age < STATUS_DEPLOY_GRACE_MS
    return False


# The deploy-window status minute (_record_status_deploy_sample) lives in
# status_monitoring.py beside its only caller, record_status_sample.


async def _claim_status_sample_minute(env, now, source="runner"):
    """Claim an unfinished minute, while allowing a failed owner takeover.

    The completed minute batch is an absolute UPSERT, so a rare overlap is
    safe. Treat it as the durable completion receipt: once present, later
    callers lose; while absent, a fallback caller may replace an abandoned
    token left by an interrupted direct or Durable Object attempt.
    """
    minute_ts = (int(now) // STATUS_SAMPLE_WINDOW_MS) * STATUS_SAMPLE_WINDOW_MS
    try:
        rnd = js_crypto.getRandomValues(Uint8Array.new(16))
        claim = "".join("%02x" % int(rnd[i]) for i in range(16))
    except Exception:
        claim = ("%032x" % int(Date.now()))[-32:]
    claim = str(source or "trigger") + "-" + claim
    try:
        await d1_run(
            env,
            "INSERT INTO system_status_sample_claim "
            "(minute_ts, claim, claimed_at) VALUES (?, ?, ?) "
            "ON CONFLICT(minute_ts) DO UPDATE SET "
            "claim=excluded.claim, claimed_at=excluded.claimed_at "
            "WHERE NOT EXISTS ("
            "SELECT 1 FROM system_status_minute_batch WHERE minute_ts=?"
            ")",
            minute_ts, claim, int(now), minute_ts,
        )
        row = await d1_first(
            env,
            "SELECT claim FROM system_status_sample_claim WHERE minute_ts=?",
            minute_ts,
        )
    except Exception:
        return True
    winner = str((row or {}).get("claim") or "")
    return (not winner) or winner == claim


async def _homepage_status_probe(env):
    """Load the exact static document streamed by ``_serve_homepage``.

    A scheduled Worker cannot reliably hairpin through its own public hostname,
    so the bound asset service is the authoritative no-cache origin probe. This
    is materially stronger than the old error-log inference: missing/broken
    homepage assets now fail even when no visitor happened to request ``/``.
    """
    _cron_subrequest_charge()
    response = await env.ASSETS.fetch(JsRequest.new(
        "https://forkmesh.internal/index.html",
        to_js({
            "headers": {"cache-control": "no-cache"},
            "signal": JsAbortSignal.timeout(STATUS_ASSET_FETCH_TIMEOUT_MS),
        }),
    ))
    status = int(getattr(response, "status", 0) or 0)
    if status != 200:
        return False, "Homepage returned HTTP %d" % status
    try:
        announced = int(response.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > 1024 * 1024:
        return False, "Homepage document exceeded the 1 MiB safety limit"
    body = str(await response.text())
    if len(body.encode("utf-8")) > 1024 * 1024:
        return False, "Homepage document exceeded the 1 MiB safety limit"
    lowered = body.lower()
    if "<!doctype html" not in lowered or "forkmesh" not in lowered:
        return False, "Homepage returned an invalid index document"
    return True, ""


async def _mobile_world_status_probe(env):
    """Validate the production mobile World bootstrap through its own Worker."""
    origin = _normalized_http_origin(getattr(env, "WORLD_ORIGIN", ""))
    if not origin:
        return False, "World origin is not configured"
    _cron_subrequest_charge()
    response = await js_fetch_with_timeout(
        origin + MOBILE_WORLD_HEALTH_PATH,
        {
            "method": "GET",
            # Workers only implements follow/manual. Manual preserves the
            # probe's fail-closed behavior because every redirect remains a
            # non-200 response and is rejected below.
            "redirect": "manual",
            "headers": {
                "accept": "application/json",
                "cache-control": "no-cache",
                "user-agent": MOBILE_WORLD_STATUS_USER_AGENT,
                "x-forkmesh-probe-profile": "mobile",
            },
        },
        CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
    )
    status = int(getattr(response, "status", 0) or 0)
    try:
        announced = int(response.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > MOBILE_WORLD_HEALTH_MAX_BYTES:
        return False, "Mobile World health response exceeded the safety limit"
    body = str(await response.text())
    if len(body.encode("utf-8")) > MOBILE_WORLD_HEALTH_MAX_BYTES:
        return False, "Mobile World health response exceeded the safety limit"
    try:
        payload = json.loads(body)
    except Exception:
        payload = None
    if status != 200:
        detail = ""
        if isinstance(payload, dict):
            detail = clean_string(payload.get("reason") or "", 160).strip()
        suffix = ": " + detail if detail else ""
        return False, "Mobile World health returned HTTP %d%s" % (
            status, suffix)
    if payload is None:
        return False, "Mobile World health endpoint returned invalid JSON"
    if str(response.headers.get("x-forkmesh-worker") or "").lower() != "world":
        return False, "Mobile World health did not reach the World Worker"
    if not isinstance(payload, dict) or payload.get("ok") is not True:
        return False, "Mobile World startup graph was not healthy"
    if (
        payload.get("check") != "mobile-world-startup"
        or payload.get("profile") != "mobile"
        or payload.get("sameOriginRuntime") is not True
        or str(payload.get("threeRevision") or "") != "184"
    ):
        return False, "Mobile World health returned an invalid contract"
    assets = payload.get("assets")
    if not isinstance(assets, list) or any(
        not isinstance(item, dict) or item.get("ok") is not True
        for item in assets
    ):
        return False, "Mobile World health returned invalid asset results"
    paths = {str(item.get("path") or "") for item in assets}
    if (
        len(assets) != len(MOBILE_WORLD_HEALTH_ASSETS)
        or paths != set(MOBILE_WORLD_HEALTH_ASSETS)
    ):
        return False, "Mobile World health did not check the complete asset graph"
    return True, ""


async def _status_page_static_assets_probe(env):
    """Load and recognize every critical static artifact used by /status."""
    try:
        for path, maximum, markers in STATUS_PAGE_ASSETS:
            _cron_subrequest_charge()
            response = await env.ASSETS.fetch(JsRequest.new(
                "https://forkmesh.internal" + path,
                to_js({
                    "headers": {"cache-control": "no-cache"},
                    "signal": JsAbortSignal.timeout(
                        STATUS_ASSET_FETCH_TIMEOUT_MS),
                }),
            ))
            status = int(getattr(response, "status", 0) or 0)
            if status != 200:
                raise RuntimeError(
                    "Status page artifact %s returned HTTP %d" % (path, status))
            try:
                announced = int(response.headers.get("content-length") or 0)
            except Exception:
                announced = 0
            if announced > maximum:
                raise RuntimeError(
                    "Status page artifact %s exceeded its safety limit" % path)
            body = str(await response.text())
            if len(body.encode("utf-8")) > maximum:
                raise RuntimeError(
                    "Status page artifact %s exceeded its safety limit" % path)
            if any(marker not in body for marker in markers):
                raise RuntimeError(
                    "Status page artifact %s failed its content check" % path)
    except BaseException as error:
        return False, _safe_error_text(error)[:200]
    return True, ""


async def _status_page_api_probe(env):
    """Validate deployed page artifacts and the prior dedicated API row.

    The one snapshot publication immediately after this sample owns the full
    projection and warms its Cache API key. Building here too doubled D1 reads
    on every alarm tick and could exceed the Free daily row-read allowance.
    """
    assets_ok, assets_reason = await _status_page_static_assets_probe(env)
    if (
        not assets_ok
        and not await _status_deploy_semaphore_active(env, int(Date.now()))
    ):
        return False, assets_reason

    # The public route serves the main-D1 snapshot row, so the live
    # projection alone is not enough: validate the previously published row.
    # Public hairpin requests are unreliable inside a scheduled Worker; this
    # fixed primary-key read exercises the same main-D1 snapshot boundary
    # and row contract the App's public snapshot path uses. Route activation
    # itself stays covered by deploy verification.
    try:
        row = await _public_snapshot_row(env, "/api/status")
        # Missing, expired, and rollout-mismatched normal rows deliberately
        # fall back to the authoritative App. Same-deploy corruption still
        # fails closed and marks this system unhealthy.
        if row is not None:
            _validated_public_snapshot_row(
                row, "/api/status", int(Date.now()),
                str(getattr(env, "DEPLOY_FINGERPRINT", "") or ""),
                allow_authoritative_fallback=True,
            )
    except BaseException as error:
        if not await _status_deploy_semaphore_active(env, int(Date.now())):
            return False, (
                "Published status API snapshot is unavailable: "
                + _safe_error_text(error)[:180]
            )
    return True, ""




async def cached_status_history(env, view="full", force_refresh=False):
    """Serve the expensive public status projection from the App cache."""
    normalized_view = "world" if view == "world" else "full"
    cache_key = STATUS_EDGE_CACHE_KEYS[normalized_view]
    if not force_refresh:
        cached = await edge_cache_match(cache_key)
        if cached is not None:
            return cached
    if normalized_view == "world":
        # The World projection must never launch a second status-history query.
        # Reuse (or build once and warm) the canonical full response, then
        # project only the fields its canvas consumes.
        full_response = await cached_status_history(
            env, "full", force_refresh=force_refresh)
        full_payload = (
            full_response
            if isinstance(full_response, dict)
            else await _response_json(full_response)
        )
        response = json_response(
            public_snapshots.project_world_status_payload(full_payload),
            cache_seconds=STATUS_EDGE_CACHE_TTL,
        )
    else:
        response = await status_history(env, "full")
    await edge_cache_put(cache_key, response)
    if force_refresh and normalized_view == "full":
        # A freshly rebuilt full projection invalidates the smaller World
        # projection derived from its previous generation.
        await edge_cache_delete(STATUS_EDGE_CACHE_KEYS["world"])
    return response


PUBLIC_SNAPSHOT_SELECT_SQL = (
    "SELECT path,schema_version,kind,generated_at,fresh_until,stale_until,"
    "deploy_fingerprint,content_length,payload,"
    "json_valid(payload) AS payload_json_valid,"
    "length(CAST(payload AS BLOB)) AS payload_bytes "
    "FROM public_api_snapshots "
    "WHERE path=?"
)
PUBLIC_SNAPSHOT_UPSERT_SQL = (
    "INSERT INTO public_api_snapshots "
    "(path,schema_version,kind,generated_at,fresh_until,stale_until,"
    "deploy_fingerprint,content_length,payload) VALUES (?,?,?,?,?,?,?,?,?) "
    "ON CONFLICT(path) DO UPDATE SET "
    "schema_version=excluded.schema_version,kind=excluded.kind,"
    "generated_at=excluded.generated_at,fresh_until=excluded.fresh_until,"
    "stale_until=excluded.stale_until,"
    "deploy_fingerprint=excluded.deploy_fingerprint,"
    "content_length=excluded.content_length,payload=excluded.payload "
    "WHERE public_api_snapshots.generated_at<=excluded.generated_at AND ("
    "public_api_snapshots.kind!='forkmesh-public-api-snapshot-tombstone' "
    "OR public_api_snapshots.stale_until<=excluded.generated_at)"
)
PUBLIC_SNAPSHOT_TOMBSTONE_UPSERT_SQL = (
    "INSERT INTO public_api_snapshots "
    "(path,schema_version,kind,generated_at,fresh_until,stale_until,"
    "deploy_fingerprint,content_length,payload) VALUES (?,?,?,?,?,?,?,?,?) "
    "ON CONFLICT(path) DO UPDATE SET "
    "schema_version=excluded.schema_version,kind=excluded.kind,"
    "generated_at=excluded.generated_at,fresh_until=excluded.fresh_until,"
    "stale_until=excluded.stale_until,"
    "deploy_fingerprint=excluded.deploy_fingerprint,"
    "content_length=excluded.content_length,payload=excluded.payload "
    "WHERE public_api_snapshots.kind!='forkmesh-public-api-snapshot-tombstone' "
    "OR public_api_snapshots.stale_until<excluded.stale_until"
)
PUBLIC_SNAPSHOT_DELETE_ABSENT_SQL = (
    "DELETE FROM public_api_snapshots WHERE path=? "
    "AND (kind='forkmesh-public-api-snapshot' OR ("
    "kind='forkmesh-public-api-snapshot-tombstone' AND stale_until<=?))"
)


async def _public_snapshot_row(env, path):
    database = _public_snapshot_database(env)
    _cron_d1_query_charge()
    _log_d1_query(PUBLIC_SNAPSHOT_SELECT_SQL, (path,))
    statement = database.prepare(PUBLIC_SNAPSHOT_SELECT_SQL).bind(path)
    return d1_row_to_dict(await statement.first())


async def _mirror_replica_source_payload(env, request):
    """Build one public, validated document bundle for independent mirrors.

    A node used to fetch every projection separately on every sync cycle. One
    payload lets a WebSocket invalidation cost one controller request while the
    mirror retains its last-good bundle indefinitely during an outage.
    """
    now = int(Date.now())
    snapshot_paths = tuple(public_snapshots.SNAPSHOT_PATHS)
    placeholders = ",".join("?" for _path in snapshot_paths)
    rows = await d1_all(
        env,
        "SELECT path,schema_version,kind,generated_at,fresh_until,"
        "stale_until,deploy_fingerprint,content_length,payload,"
        "json_valid(payload) AS payload_json_valid "
        "FROM public_api_snapshots WHERE path IN (" + placeholders + ")",
        *snapshot_paths,
    )
    by_path = {
        str(row.get("path") or ""): row for row in rows or []
        if isinstance(row, dict)
    }
    # Snapshot payloads were schema-validated immediately before their atomic
    # D1 publication. Re-parsing and recursively validating all five (often
    # hundreds of KiB) in Pyodide on every mirror pull intermittently exceeded
    # the Worker CPU ceiling. Keep the read-side trust boundary strict but
    # cheap: exact metadata/fingerprint/length checks happen here and SQLite's
    # native json_valid() proves the stored body is still one JSON value. The
    # body is then embedded verbatim, avoiding a Python parse + second encode.
    # A tombstone, stale row, or mixed-deploy row is omitted independently;
    # mirror clients merge partial responses with their validated last-good
    # bundle, so one privacy transition no longer turns every document into a
    # 503.
    documents = {}
    fingerprint = str(getattr(env, "DEPLOY_FINGERPRINT", "") or "")
    for path in snapshot_paths:
        try:
            documents[path] = _validated_public_snapshot_text(
                by_path.get(path), path, now, fingerprint)
        except RuntimeError:
            continue

    # Repository star/fork/About documents are intentionally not recomputed
    # here. About alone can scan and decrypt the repository/follower view; a
    # burst of mirror pulls used to run all three handlers inside each bundle,
    # exhaust this event's CPU, and poison later Python requests. The portable
    # client already merges partial source documents with its last-good file;
    # updated clients fetch only these three missing projections through their
    # normal independently serialized routes.
    if not documents:
        raise RuntimeError("mirror replica has no current public documents")
    pairs = [
        json.dumps(path, ensure_ascii=True) + ":" + body
        for path, body in documents.items()
    ]
    return (
        '{"ok":true,"schemaVersion":1,"type":'
        + json.dumps(MIRROR_REPLICA_SOURCE_KIND, ensure_ascii=True)
        + ',"generatedAt":' + str(now)
        + ',"documents":{' + ",".join(pairs) + "}}"
    )


async def mirror_replica_source_handler(env, request):
    """Serve every independent-dashboard projection in one HTTP response."""
    if method_name(request) not in ("GET", "HEAD"):
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            extra_headers={"allow": "GET, HEAD"})
    try:
        body = await _mirror_replica_source_payload(env, request)
    except BaseException as error:
        # Keep the public response generic, but retain one bounded diagnostic
        # in Worker logs. Without this event a bad projection and a transient
        # D1 failure are indistinguishable from the mirror's 503 response.
        print(json.dumps({
            "event": "mirror_replica_unavailable",
            "detail": _safe_error_text(error)[:200],
        }, ensure_ascii=True, separators=(",", ":")))
        return json_response(
            {"error": "mirror_replica_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers={"retry-after": "60", **EXPECTED_DEGRADED_HEADERS})
    encoded = body.encode("utf-8")
    if len(encoded) > MIRROR_REPLICA_SOURCE_MAX_BYTES:
        return json_response(
            {"error": "mirror_replica_too_large"}, status=503,
            cache_control="no-store", extra_headers=EXPECTED_DEGRADED_HEADERS)
    etag = '"' + hashlib.sha256(encoded).hexdigest() + '"'
    headers = {
        "cache-control": (
            "public, max-age=15, stale-while-revalidate=300, "
            "stale-if-error=86400"),
        "content-type": "application/json; charset=utf-8",
        "content-length": str(len(encoded)),
        "etag": etag,
        "vary": "Cookie, Authorization",
        "x-content-type-options": "nosniff",
    }
    if str(request.headers.get("if-none-match") or "") == etag:
        headers.pop("content-length", None)
        return Response(None, status=304, headers=headers)
    return Response(
        None if method_name(request) == "HEAD" else body,
        status=200, headers=headers)


def _exact_public_snapshot_integer(value):
    """Match JavaScript Number.isSafeInteger for a bridged D1 numeric value."""
    if isinstance(value, bool):
        raise TypeError("boolean is not a snapshot integer")
    if isinstance(value, int):
        result = value
    elif isinstance(value, float) and value.is_integer():
        result = int(value)
    else:
        raise TypeError("invalid snapshot integer")
    if result < 0 or result > 9_007_199_254_740_991:
        raise ValueError("snapshot integer is outside the safe range")
    return result


def _validated_public_snapshot_text(
        row, path, now, deploy_fingerprint=""):
    """Return one publisher-validated JSON body without parsing it again."""
    if not isinstance(row, dict) or row.get("path") != path:
        raise RuntimeError("snapshot row is missing")
    try:
        schema_version = _exact_public_snapshot_integer(
            row.get("schema_version"))
        generated_at = _exact_public_snapshot_integer(row.get("generated_at"))
        fresh_until = _exact_public_snapshot_integer(row.get("fresh_until"))
        stale_until = _exact_public_snapshot_integer(row.get("stale_until"))
        length = _exact_public_snapshot_integer(row.get("content_length"))
        json_valid = _exact_public_snapshot_integer(
            row.get("payload_json_valid"))
    except (TypeError, ValueError, OverflowError) as error:
        raise RuntimeError("snapshot row numeric fields are invalid") from error
    if (
        schema_version != public_snapshots.SNAPSHOT_SCHEMA_VERSION
        or str(row.get("kind") or "") != public_snapshots.SNAPSHOT_KIND
    ):
        raise RuntimeError("snapshot row schema is invalid")
    if (
        generated_at <= 0
        or generated_at > int(now) + 30_000
        or fresh_until < generated_at
        or stale_until != fresh_until
        or int(now) >= fresh_until
    ):
        raise RuntimeError("snapshot row is expired or future-dated")
    body = row.get("payload")
    if not isinstance(body, str) or json_valid != 1:
        raise RuntimeError("snapshot row JSON is invalid")
    if (
        length != len(body.encode("utf-8"))
        or length <= 1
        or length > public_snapshots.SNAPSHOT_PATH_MAX_BYTES[path]
    ):
        raise RuntimeError("snapshot row length is invalid")
    expected_fingerprint = str(deploy_fingerprint or "")
    row_fingerprint = str(row.get("deploy_fingerprint") or "")
    if expected_fingerprint and not hmac.compare_digest(
            row_fingerprint, expected_fingerprint):
        # Outage recovery deliberately activates the replacement before its
        # cron projections are ready. A still-fresh row from the immediately
        # preceding build remains publisher-validated public data, and the
        # portable client repeats the current path schema validation before
        # writing it. Accept only canonical fingerprints here; normal public
        # HTTP routes retain their exact-current-fingerprint admission rule.
        if not (
            re.fullmatch(r"[0-9a-f]{64}", row_fingerprint)
            and re.fullmatch(r"[0-9a-f]{64}", expected_fingerprint)
        ):
            raise RuntimeError("snapshot row belongs to another deployment")
    return body


def _strict_public_snapshot_json(body):
    def reject_constant(value):
        raise ValueError("invalid JSON constant: " + str(value))

    return json.loads(body, parse_constant=reject_constant)


def _validated_public_snapshot_row(
        row, path, now, deploy_fingerprint="",
        allow_authoritative_fallback=False):
    if not isinstance(row, dict) or row.get("path") != path:
        raise RuntimeError("snapshot row is missing")
    try:
        schema_version = _exact_public_snapshot_integer(
            row.get("schema_version"))
        generated_at = _exact_public_snapshot_integer(row.get("generated_at"))
        fresh_until = _exact_public_snapshot_integer(row.get("fresh_until"))
        stale_until = _exact_public_snapshot_integer(row.get("stale_until"))
        length = _exact_public_snapshot_integer(row.get("content_length"))
    except (TypeError, ValueError, OverflowError) as error:
        raise RuntimeError("snapshot row numeric fields are invalid") from error
    if (
        schema_version != public_snapshots.SNAPSHOT_SCHEMA_VERSION
        or str(row.get("kind") or "") != public_snapshots.SNAPSHOT_KIND
    ):
        raise RuntimeError("snapshot row schema is invalid")
    if (
        generated_at <= 0
        or generated_at > int(now) + 30_000
        or fresh_until < generated_at
        or stale_until != fresh_until
    ):
        raise RuntimeError("snapshot row is expired or future-dated")
    body = row.get("payload")
    if not isinstance(body, str):
        raise RuntimeError("snapshot row payload is invalid")
    if (
        length != len(body.encode("utf-8"))
        or length <= 1
        or length > public_snapshots.SNAPSHOT_PATH_MAX_BYTES[path]
    ):
        raise RuntimeError("snapshot row length is invalid")
    expected_fingerprint = str(deploy_fingerprint or "")
    row_fingerprint = str(row.get("deploy_fingerprint") or "")
    if expected_fingerprint and not hmac.compare_digest(
            row_fingerprint, expected_fingerprint):
        if (
                allow_authoritative_fallback
                and re.fullmatch(r"[0-9a-f]{64}", row_fingerprint)
                and re.fullmatch(r"[0-9a-f]{64}", expected_fingerprint)):
            return None
        raise RuntimeError("snapshot row belongs to another deployment")
    try:
        payload = _strict_public_snapshot_json(body)
    except Exception as error:
        raise RuntimeError("snapshot row JSON is invalid") from error
    if not public_snapshots.validate_snapshot_payload(
        path, payload, generated_at
    ):
        raise RuntimeError("snapshot row payload is invalid")
    if int(now) >= fresh_until:
        if allow_authoritative_fallback:
            return None
        raise RuntimeError("snapshot row is expired")
    return payload


async def _public_snapshot_handler_response(env, path):
    request_url = "https://app.forkmesh.internal" + path
    if path == "/api/repositories":
        # Force the handler's established anonymous/no-store bypass so an old
        # Cache API entry is never relabelled with a new generation timestamp.
        request = JsRequest.new(
            request_url + "?fresh=1",
            to_js({
                "method": "GET",
                "headers": {
                    "accept": "application/json",
                    "cache-control": "no-store",
                },
            }),
        )
        return await catalog_handler(env, request)
    request = JsRequest.new(
        request_url,
        to_js({
            "method": "GET",
            "headers": {"accept": "application/json"},
        }),
    )
    if path == "/api/network/overview":
        # Its children are also edge-cached; clear all four before rebuilding
        # so generated_at describes the data rather than merely this wrapper.
        for cache_key in (
            NETWORK_STATS_CACHE_KEY,
            NETWORK_LEADERBOARDS_CACHE_KEY,
            NETWORK_OVERVIEW_CACHE_KEY,
            ONLINE_HISTORY_CACHE_KEY,
        ):
            await edge_cache_delete(cache_key)
        return await network_overview(env, maintain_presence=False)
    if path == "/api/status":
        # This is the tick's one authoritative status build. Expire the prior
        # Cache API body after recording the sample, then publish and warm the
        # exact same full response used by live fallback/page traffic.
        await edge_cache_delete(STATUS_EDGE_CACHE_KEYS["full"])
        return await cached_status_history(env, "full")
    if path == "/api/repo/forkmesh/forkmesh/mirrors":
        canonical_owner = (
            await _org_repo_node(env, "forkmesh", "forkmesh") or "forkmesh"
        )
        cache_key = (
            "https://forkmesh.internal/api/repo/forkmesh/forkmesh/mirrors"
        )
        await edge_cache_delete(cache_key)
        return await repo_mirrors_handler(
            env, request, canonical_owner, "forkmesh")
    raise RuntimeError("unsupported public snapshot path")


async def _build_public_snapshot_payload(env, path):
    response = await _public_snapshot_handler_response(env, path)
    status = int(getattr(response, "status", 0) or 0)
    if (
            status == 404
            and path == "/api/repo/forkmesh/forkmesh/mirrors"):
        # A fresh self-host legitimately has no flagship group yet. Absence is
        # readiness state, not a cron fault; the edge delegates its live 404.
        return None
    if status != 200:
        raise RuntimeError("handler returned HTTP %d" % status)
    try:
        content_type = str(response.headers.get("content-type") or "")
    except Exception:
        content_type = ""
    if content_type.split(";", 1)[0].strip().lower() != "application/json":
        raise RuntimeError("handler returned a non-JSON content type")
    raw = str(await response.text())
    raw_length = len(raw.encode("utf-8"))
    if raw_length > public_snapshots.SNAPSHOT_PATH_MAX_BYTES[path]:
        raise RuntimeError(
            "handler response exceeded the snapshot cap (%d bytes)"
            % raw_length)
    try:
        payload = _strict_public_snapshot_json(raw)
    except Exception as error:
        raise RuntimeError("handler returned invalid JSON") from error
    if not public_snapshots.validate_snapshot_payload(
        path, payload, int(Date.now())
    ):
        raise RuntimeError("handler returned an unsafe public payload")
    return payload


async def _publish_public_snapshot_group(env, paths, generated_at):
    payloads = {}
    failures = []
    for path in paths:
        try:
            if path == "/api/status/world":
                full = payloads.get("/api/status")
                if full is None:
                    raise RuntimeError(
                        "compact status must share the full status build")
                projected = public_snapshots.project_world_status_payload(full)
                if not public_snapshots.validate_snapshot_payload(
                    path, projected, generated_at
                ):
                    raise RuntimeError("compact status projection is invalid")
                payloads[path] = projected
            else:
                payloads[path] = await _build_public_snapshot_payload(env, path)
        except BaseException as error:
            failures.append((path, error))
    if failures:
        path, error = failures[0]
        raise RuntimeError(
            "%s failed: %s" % (path, _safe_error_text(error)[:500]))
    absent = [path for path, payload in payloads.items() if payload is None]
    if absent:
        _d1_write_guard(env, PUBLIC_SNAPSHOT_DELETE_ABSENT_SQL)
        database = _public_snapshot_database(env)
        # Delete only an obsolete normal row. A privacy-transition tombstone
        # remains authoritative until its deadline.
        statements = [
            database.prepare(PUBLIC_SNAPSHOT_DELETE_ABSENT_SQL).bind(
                path, generated_at)
            for path in absent
        ]
        _cron_d1_query_charge(len(statements))
        _log_d1_query(PUBLIC_SNAPSHOT_DELETE_ABSENT_SQL, (),
                      "batch of %d" % len(statements))
        await database.batch(statements)
        payloads = {
            path: payload for path, payload in payloads.items()
            if payload is not None
        }
        if not payloads:
            return
    rows = public_snapshots.build_snapshot_rows(
        payloads,
        generated_at,
        str(getattr(env, "DEPLOY_FINGERPRINT", "") or ""),
    )
    _d1_write_guard(env, PUBLIC_SNAPSHOT_UPSERT_SQL)
    database = _public_snapshot_database(env)
    statements = []
    for row in rows:
        statements.append(database.prepare(PUBLIC_SNAPSHOT_UPSERT_SQL).bind(
            row["path"], row["schemaVersion"], row["kind"],
            row["generatedAt"], row["freshUntil"], row["staleUntil"],
            row["deployFingerprint"], row["contentLength"], row["payload"],
        ))
    # D1 batch is transactional: a failed group preserves every prior
    # last-good row rather than publishing a mixed generation.
    _cron_d1_query_charge(len(statements))
    _log_d1_query(PUBLIC_SNAPSHOT_UPSERT_SQL, (),
                  "batch of %d" % len(statements))
    await database.batch(statements)
    if tuple(paths) == tuple(public_snapshots.SNAPSHOT_STATUS_PATHS):
        # Cache only after the atomic D1 commit. The outer Worker accepts a hit
        # only when these generation/fingerprint headers match this release,
        # so a rollout can never relabel an older deployment's body as fresh.
        cache_headers = {
            "x-forkmesh-worker": "app",
            "x-forkmesh-public-snapshot": "fresh",
            "x-forkmesh-snapshot-generated-at": str(generated_at),
            "x-forkmesh-snapshot-fingerprint": str(
                getattr(env, "DEPLOY_FINGERPRINT", "") or ""),
        }
        for status_path, view in (
                ("/api/status", "full"),
                ("/api/status/world", "world")):
            await edge_cache_put(
                STATUS_EDGE_CACHE_KEYS[view],
                json_response(
                    payloads[status_path],
                    cache_seconds=STATUS_EDGE_CACHE_TTL,
                    extra_headers=cache_headers,
                ),
            )
    # Independent mirrors keep this whole public projection bundle in memory.
    # One payload-free WebSocket doorbell makes them pull the new atomic bundle
    # once; the thirty-minute safety read is only for a dropped frame.
    try:
        await notify_repo_mirrors(
            env, "forkmesh", "forkmesh", "replica")
    except BaseException:
        pass
    if tuple(paths) == tuple(public_snapshots.SNAPSHOT_STATUS_PATHS):
        # Publishing is authoritative even if the best-effort doorbell is
        # temporarily unavailable. Reconnecting clients perform one catch-up
        # read, so a relay failure must not turn a good snapshot phase red.
        try:
            await _world_broadcast_status_update(env, generated_at)
        except BaseException:
            pass


async def refresh_public_api_snapshots(env, minute, failures=None):
    """Compatibility publisher; named Cron phases own the live cadence."""
    generated_at = int(Date.now())
    # Each endpoint is its own atomic transaction. A brand-new self-host may
    # legitimately have no forkmesh/forkmesh group yet; that must not prevent
    # status or catalog snapshots from becoming available.
    groups = [public_snapshots.SNAPSHOT_STATUS_PATHS]
    groups.extend(
        (path,) for path in public_snapshots.SNAPSHOT_FREQUENT_PATHS
        if path not in public_snapshots.SNAPSHOT_STATUS_PATHS
    )
    if int(minute) % public_snapshots.SNAPSHOT_SLOW_CADENCE_MINUTES == 0:
        groups.extend((path,) for path in public_snapshots.SNAPSHOT_SLOW_PATHS)
    for paths in groups:
        try:
            await _publish_public_snapshot_group(env, paths, generated_at)
        except BaseException as error:
            label = paths[0].strip("/").replace("/", "-")
            await log_cron_error(
                env,
                "/cron/public-api-snapshots/" + label,
                "public API snapshot %s failed: %s"
                % (label, _safe_error_text(error)),
                error=error,
                failures=failures,
            )


def _republish_ready_at(requested_at, published_at, path=""):
    """Earliest instant a pending doorbell may rebuild its path.

    Leading edge: SNAPSHOT_REPUBLISH_LEAD_MS after the doorbell, so one
    request's cascade of writes lands in a single build. Catalog trailing
    edge: never sooner than SNAPSHOT_REPUBLISH_MIN_INTERVAL_MS after the
    previous event-driven build of the same path, so a burst of edits costs
    one rebuild per bucket instead of one per edit. Status transitions are
    rare and bypass the trailing bucket so recovery is visible immediately.
    """
    leading_edge = int(requested_at) + SNAPSHOT_REPUBLISH_LEAD_MS
    if path in SNAPSHOT_REPUBLISH_STATUS_PATHS:
        return leading_edge
    return max(
        leading_edge,
        int(published_at or 0) + SNAPSHOT_REPUBLISH_MIN_INTERVAL_MS,
    )


def _republish_group(path):
    """Return the atomic snapshot group one doorbell path rebuilds."""
    if path in SNAPSHOT_REPUBLISH_STATUS_PATHS:
        return SNAPSHOT_REPUBLISH_STATUS_PATHS
    return (path,)


async def _republish_row_verdict(env, path, requested_at, now):
    """Consult the served row before spending a rebuild on a doorbell.

    Returns ("build", 0), ("reflected", generated_at) when a generation that
    started after the mutation committed is already published (a Cron phase
    got there first), or ("tombstone", deadline) while a privacy-transition
    barrier is authoritative: the UPSERT guard would reject the row anyway, so
    the alarm waits for the deadline and heals the barrier right after it
    instead of leaving that to the next Cron slot. One bounded D1 read; any
    read failure falls through to a normal build.
    """
    try:
        row = await _public_snapshot_row(env, path)
    except BaseException:
        return "build", 0
    if not isinstance(row, dict) or row.get("path") != path:
        return "build", 0
    try:
        generated_at = _exact_public_snapshot_integer(row.get("generated_at"))
        stale_until = _exact_public_snapshot_integer(row.get("stale_until"))
    except (TypeError, ValueError, OverflowError):
        return "build", 0
    kind = str(row.get("kind") or "")
    if kind == public_snapshots.SNAPSHOT_TOMBSTONE_KIND:
        if stale_until > int(now):
            return "tombstone", stale_until
        return "build", 0
    if (
        kind == public_snapshots.SNAPSHOT_KIND
        and generated_at > int(requested_at)
    ):
        return "reflected", generated_at
    return "build", 0


async def _republish_publish_path(env, path, generated_at):
    """Publish one snapshot group outside any Cron slot.

    Same publisher, same validation, same atomic D1 batch and the same
    per-invocation subrequest budget as the staggered Cron phase for that
    path. Returns True on success; a failure is logged once under the Cron
    error path and left to the next Cron slot rather than retried in a loop.
    """
    variable, token, budget = _cron_d1_budget_start()
    error = None
    try:
        await _publish_public_snapshot_group(
            env, _republish_group(path), generated_at)
        if budget.get("exhausted"):
            raise RuntimeError("republish subrequest budget exhausted")
    except BaseException as caught:
        error = caught
    finally:
        _cron_d1_budget_stop(variable, token)
    if error is None:
        return True
    label = path.strip("/").replace("/", "-")
    try:
        # error_log groups (and pings admins) on the exact message text, so
        # collapse volatile byte counts / platform reference ids: a persistent
        # failure is one group, not one ping per throttled attempt. Sentry
        # still receives the exact exception through error=.
        detail = re.sub(
            r"\b(?=[0-9a-f]*\d)[0-9a-f]{8,}\b|\d{4,}", "#",
            _safe_error_text(error)[:400])
        await log_cron_error(
            env,
            "/cron/public-api-snapshots/" + label,
            "public API snapshot %s republish failed: %s"
            % (label, detail[:240]),
            error=error,
        )
    except BaseException:
        pass
    return False


# --- Public leaderboards (/network/) ---------------------------------------

LEADERBOARD_LIMIT = 10  # rows returned per board

ISSUE_REPORTER_TRACKER_OWNER = "forkmesh"
ISSUE_REPORTER_TRACKER_REPO = "forkmesh"
ISSUE_REPORTER_TRACKER_CACHE_KEY = (
    "https://forkmesh.internal/tracker/issue-reporter-summary"
)
ISSUE_REPORTER_TRACKER_TTL = 60


def _issue_reporter_open_event(record):
    events = record.get("events") if isinstance(record, dict) else None
    if not isinstance(events, list):
        return {}
    return next(
        (event for event in events
         if isinstance(event, dict) and event.get("type") == "open"),
        {},
    )


def _issue_reporter_name(record, opened):
    for value in (
            record.get("authorName"), opened.get("authorName"),
            record.get("author")):
        name = str(value or "").strip()
        if name:
            return name.lower()
    return "unknown"


def _issue_reporter_day(record, opened):
    try:
        timestamp = int(record.get("createdAt") or opened.get("ts") or 0)
        if timestamp <= 0:
            raise ValueError
        return time.strftime("%Y-%m-%d", time.gmtime(timestamp / 1000))
    except (OverflowError, OSError, TypeError, ValueError):
        raise ValueError("issue has no valid UTC creation timestamp")


def _issue_reporter_tracker_fold(records):
    """Fold signed tracker JSON into the public reporter projection."""
    counts = {}
    activity = {}
    seen_numbers = set()
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("issue record is not an object")
        try:
            number = int(record.get("number") or 0)
        except (TypeError, ValueError):
            number = 0
        if number <= 0 or number in seen_numbers:
            raise ValueError("issue has a duplicate or invalid number")
        seen_numbers.add(number)
        opened = _issue_reporter_open_event(record)
        signer = str(opened.get("author") or record.get("author") or "").strip()
        if not signer:
            raise ValueError("issue has no signed author")
        reporter = _issue_reporter_name(record, opened)
        day = _issue_reporter_day(record, opened)
        counts[reporter] = counts.get(reporter, 0) + 1
        key = (reporter, day, signer)
        activity[key] = activity.get(key, 0) + 1
    ordered_counts = dict(sorted(
        counts.items(), key=lambda item: (-item[1], item[0])))
    activity_rows = [
        [reporter, day, signer, count]
        for (reporter, day, signer), count in sorted(activity.items())
    ]
    revision = hashlib.sha256(json.dumps(
        activity_rows, separators=(",", ":")).encode()).hexdigest()
    return {
        "ok": True,
        "counts": ordered_counts,
        "activity": activity_rows,
        "revision": revision,
    }


def _issue_reporter_tracker_summary_valid(data):
    if not isinstance(data, dict) or data.get("ok") is not True:
        return None
    if not isinstance(data.get("counts"), dict):
        return None
    if not isinstance(data.get("activity"), list):
        return None
    revision = str(data.get("revision") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", revision):
        return None
    return data


async def _issue_reporter_tracker_summary(env):
    """Build reporter credit from the live tracker, never a generated file."""
    cached = await edge_cache_match(ISSUE_REPORTER_TRACKER_CACHE_KEY)
    if cached is not None:
        summary = _issue_reporter_tracker_summary_valid(
            await _response_json(cached))
        if summary is not None:
            return summary
    try:
        records = await _forkbot_all_issue_records(
            env, ISSUE_REPORTER_TRACKER_OWNER, ISSUE_REPORTER_TRACKER_REPO)
        summary = (
            _issue_reporter_tracker_fold(records)
            if records is not None else None)
    except Exception:
        summary = None
    if summary is None:
        return None
    response = json_response(summary, cache_seconds=ISSUE_REPORTER_TRACKER_TTL)
    await edge_cache_put(ISSUE_REPORTER_TRACKER_CACHE_KEY, response)
    return summary


async def issue_reporter_leaderboard(env):
    """Return live tracker reporter counts for the leaderboard hub."""
    summary = await _issue_reporter_tracker_summary(env)
    if summary is None:
        raise RuntimeError("canonical issue tracker is unavailable")
    return json_response(
        {"ok": True, "counts": summary["counts"]},
        cache_seconds=ISSUE_REPORTER_TRACKER_TTL,
    )


async def _record_contributor(env, author, kind, display_name=""):
    author_key = clean_string(author or "", 120)
    name = clean_string(display_name or author_key, MAX_NODE_NAME)
    if (not author_key or not name
            or kind not in ("issues", "pulls", "commits", "discussions")):
        return
    try:
        author_bi = await blind_index(env, author_key.lower())
        await d1_run(
            env,
            f"""INSERT INTO contributor_activity
                  (author_bi, name, {kind}, total, last_ts)
                VALUES (?, ?, 1, 1, ?)
                ON CONFLICT(author_bi) DO UPDATE SET
                  {kind} = {kind} + 1, total = total + 1,
                  name = excluded.name, last_ts = excluded.last_ts""",
            author_bi, name, int(Date.now()),
        )
        await _award_contributor_badge(env, author_key, kind)
    except Exception:
        pass


async def _record_funds_received(env, scope, key, name, lamports):
    # Accumulate disbursed lamports per recipient for the funds-received boards.
    # Best-effort: never let a bookkeeping failure abort a money transfer.
    if not key or int(lamports or 0) <= 0:
        return
    try:
        await d1_run(
            env,
            """INSERT INTO funds_received (scope, key, name, lamports, last_ts)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(scope, key) DO UPDATE SET
                 lamports = lamports + excluded.lamports,
                 name = COALESCE(excluded.name, funds_received.name),
                 last_ts = excluded.last_ts""",
            scope, key, name or None, int(lamports), int(Date.now()),
        )
    except Exception:
        pass


def _catalog_updated_ms(rec):
    # Best-effort parse of a catalog record's free-form updatedAt string, so we
    # can tell which of a node's several repo mirrors last reported in (used to
    # pick the "latest" commit/platform/version for the node as a whole). Any
    # unparseable value sorts last rather than raising.
    raw = rec.get("updatedAt")
    if isinstance(raw, bool):
        return -1
    if isinstance(raw, (int, float)) or (
            isinstance(raw, str) and raw.strip().isdigit()):
        try:
            ms = float(raw)
        except (TypeError, ValueError, OverflowError):
            return -1
        return ms if ms == ms and ms >= 0 else -1
    try:
        ms = float(Date.parse(str(raw or "")))
        return ms if ms == ms else -1  # NaN check (NaN != NaN)
    except Exception:
        return -1


async def network_leaderboards(env):
    cached = await edge_cache_match(NETWORK_LEADERBOARDS_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    now = int(Date.now())

    # --- Uptime: rank nodes by total minutes online over the retained window.
    # online_hourly_nodes is pruned to ONLINE_HISTORY_RETAIN_MS, so this is
    # inherently a "last 48h" board. label is plaintext (the node's own name).
    window_start = now - ONLINE_HISTORY_RETAIN_MS
    uptime_rows = await _online_hourly_node_rows(env, window_start, now)
    uptime = {}
    for row in uptime_rows:
        key = str(row.get("node_key") or "")
        if not key:
            continue
        item = uptime.setdefault(key, {"label": "", "minutes": 0})
        item["minutes"] += int(row.get("node_minutes") or 0)
        if row.get("label"):
            item["label"] = clean_string(row.get("label", ""), MAX_NODE_NAME)
    uptime_board = [
        {"name": v["label"] or _short_presence_label("node", k),
         "minutes": v["minutes"]}
        for k, v in uptime.items() if v["minutes"] > 0
    ]
    uptime_board.sort(key=lambda n: (-n["minutes"], n["name"]))

    # --- Repos / mirrors / longest-hosted: one pass over the public catalog
    # (public only, blocked identities excluded). counts -> repos-per-owner;
    # mirror_owners -> distinct owners hosting a repo of a given name (a repo
    # mirrored by many nodes shows up under many owners); first-hosted timestamps
    # come from repo_first_hosted joined on key_bi.
    first_rows = await d1_all(env, "SELECT repo_bi, ts FROM repo_first_hosted")
    first_hosted = {str(r.get("repo_bi")): int(r.get("ts") or 0)
                    for r in first_rows if r.get("repo_bi")}
    # The per-isolate catalog memo already holds every decrypted public
    # record; a second scan (and re-decrypt) of the table on each rebuild was
    # among the largest repositories reads of 2026-09-11.
    repo_rows = await _decrypted_public_catalog(env, now)
    try:
        active_nodes = await active_registered_node_bis(env, now)
    except Exception:
        active_nodes = None
    counts = {}
    mirror_owners = {}
    hosted_board = []
    largest_board = []          # per owner/repo, by reported mirror size
    bytes_by_owner = {}         # owner -> total bytes hosted across their repos
    # Per-node detail card for the Network page's "Connected nodes" list: sums
    # the per-repo counters a node reports (adhoc #56's commit/issues/platform/
    # version/id fields) across every repo it mirrors, and keeps the commit/
    # branch/platform/version/sync-time from whichever of its repos reported in
    # most recently — so a multi-repo node shows one coherent "latest" state.
    node_details = {}
    counter_fields = (
        "issueCount", "commitCount", "branchCount", "pullCount",
        "discussionCount", "artifactCount", "worktreeCount",
        "clonesServed", "websiteServed",
    )
    for row in repo_rows:
        if active_nodes is not None and str(row.get("owner_bi") or "") not in active_nodes:
            continue
        rec = row.get("data") or {}
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME)
        name = clean_string(rec.get("name", ""), 120)
        if not owner:
            continue
        counts[owner] = counts.get(owner, 0) + 1
        try:
            size_bytes = max(0, int(rec.get("sizeBytes", 0) or 0))
        except (TypeError, ValueError):
            size_bytes = 0
        if size_bytes > 0:
            bytes_by_owner[owner] = bytes_by_owner.get(owner, 0) + size_bytes
        detail = node_details.setdefault(owner.lower(), {
            "name": owner, "machineName": "", "sizeBytes": 0,
            "commit": "", "branch": "", "lastSync": "",
            "platform": "", "version": "", "nodeId": "", "_updatedMs": -1,
            "_recordCount": 0,
            "_reportedCounterCounts": {},
            "cloneServedAt": None, "cloneServedAgent": None,
            "websiteServedAt": None, "websiteServedAgent": None,
        })
        detail["_recordCount"] += 1
        detail["sizeBytes"] += size_bytes
        for field in counter_fields:
            raw_value = rec.get(field)
            if raw_value is None or raw_value == "" or isinstance(
                    raw_value, bool):
                continue
            try:
                counter = int(raw_value)
            except (TypeError, ValueError):
                continue
            if counter < 0:
                continue
            detail[field] = int(detail.get(field) or 0) + counter
            reported_counts = detail["_reportedCounterCounts"]
            reported_counts[field] = int(reported_counts.get(field) or 0) + 1
        # When this node last served a clone / website read, across all of its
        # repositories, with the client class reported alongside that serve.
        # A point in time is carried as the newest one, never summed.
        for stamp_field, agent_field in (
            ("cloneServedAt", "cloneServedAgent"),
            ("websiteServedAt", "websiteServedAgent"),
        ):
            raw_stamp = rec.get(stamp_field)
            if raw_stamp is None or isinstance(raw_stamp, bool):
                continue
            try:
                stamp = int(raw_stamp)
            except (TypeError, ValueError):
                continue
            if stamp > 0 and stamp > int(detail.get(stamp_field) or 0):
                detail[stamp_field] = stamp
                detail[agent_field] = clean_string(
                    rec.get(agent_field, ""), 16) or None
        updated_ms = _catalog_updated_ms(rec)
        if updated_ms > detail["_updatedMs"]:
            detail["_updatedMs"] = updated_ms
            detail["machineName"] = clean_string(
                rec.get("machineName", ""), MAX_NODE_NAME)
            detail["commit"] = clean_string(rec.get("commit", ""), 64)
            detail["branch"] = clean_string(rec.get("branch", ""), 120)
            detail["lastSync"] = clean_string(rec.get("lastSync", ""), 32)
            detail["platform"] = clean_string(rec.get("platform", ""), 16)
            detail["version"] = clean_string(rec.get("version", ""), 32)
            detail["nodeId"] = clean_string(rec.get("nodeId", ""), 64)
        if name:
            mirror_owners.setdefault(name, set()).add(owner.lower())
            if size_bytes > 0:
                largest_board.append(
                    {"name": owner + "/" + name, "bytes": size_bytes})
            ts = first_hosted.get(str(row.get("key_bi")))
            if ts:
                hosted_board.append(
                    {"name": owner + "/" + name, "since": ts,
                     "ageMs": max(0, now - ts)})
    node_board = []
    for detail in node_details.values():
        record_count = int(detail.get("_recordCount") or 0)
        reported_counts = detail.get("_reportedCounterCounts", {})
        public_detail = {
            k: v for k, v in detail.items()
            if k not in (
                "_updatedMs", "_recordCount", "_reportedCounterCounts")
        }
        # The desktop Mirror nodes table reports how many repositories a node
        # advertises.  Keep that same exact count in the public per-node
        # aggregate so World cabinets do not have to mistake the one flagship
        # catalog currently loaded by the scene for the machine's whole
        # inventory.
        public_detail["repositoryCount"] = record_count
        # Unknown stays JSON null instead of becoming a misleading aggregate
        # zero. A total is known only when every included repository reported
        # that field; otherwise a partial sum would understate the node total.
        # A real zero reported by every repository remains zero.
        for field in counter_fields:
            if int(reported_counts.get(field) or 0) != record_count:
                public_detail[field] = None
        node_board.append(public_detail)
    node_board.sort(key=lambda n: (-n["sizeBytes"], n["name"]))

    repo_board = [{"name": o, "repos": c} for o, c in counts.items()]
    repo_board.sort(key=lambda n: (-n["repos"], n["name"]))

    # --- Most mirrored: repo names hosted under more than one owner.
    mirror_board = [{"name": nm, "mirrors": len(owners)}
                    for nm, owners in mirror_owners.items() if len(owners) > 1]
    mirror_board.sort(key=lambda n: (-n["mirrors"], n["name"]))

    # --- Longest hosted: oldest first-hosted timestamp wins.
    hosted_board.sort(key=lambda n: (-n["ageMs"], n["name"]))

    # --- Largest repos / most data hosted: from the size each node reports for
    # its mirror. largest_board ranks individual repos; data_board sums per owner.
    largest_board.sort(key=lambda n: (-n["bytes"], n["name"]))
    data_board = [{"name": o, "bytes": b} for o, b in bytes_by_owner.items()]
    data_board.sort(key=lambda n: (-n["bytes"], n["name"]))

    # A full contributor_activity join per rebuild; one colo-wide copy
    # outlives this endpoint's five-minute edge TTL.
    contrib_scan = lambda: d1_all(
        env,
        "WITH resolved AS (SELECT c.issues,c.pulls,c.commits,c.total,"
        "COALESCE("
        "(SELECT u.username FROM users u WHERE u.user_bi=c.author_bi "
        " AND COALESCE(u.username,'')<>'' LIMIT 1),"
        "(SELECT u.username FROM nodes n JOIN users u ON u.user_bi=n.user_bi "
        " WHERE n.pubkey=c.name AND COALESCE(u.username,'')<>'' LIMIT 1),"
        "(SELECT u.username FROM account_devices d "
        " JOIN users u ON u.user_bi=d.account_bi "
        " WHERE d.pubkey=c.name AND d.enabled=1 AND d.revoked_at=0 "
        " AND COALESCE(u.username,'')<>'' LIMIT 1),c.name) AS display_name "
        "FROM contributor_activity c WHERE c.total > 0),labeled AS ("
        "SELECT CASE WHEN length(display_name)=43 THEN 'Unlinked contributor' "
        "ELSE display_name END AS display_name,issues,pulls,commits,total "
        "FROM resolved) "
        "SELECT display_name,SUM(issues) AS issues,SUM(pulls) AS pulls,"
        "SUM(commits) AS commits,SUM(total) AS total FROM labeled "
        "GROUP BY display_name ORDER BY total DESC LIMIT ?",
        LEADERBOARD_LIMIT,
    )
    shared = globals().get("d1_shared_read")
    contrib_rows = await (shared(env, "contributor-board", contrib_scan)
                          if shared else contrib_scan())
    contrib_board = [
        {"name": clean_string(
             r.get("display_name", ""), MAX_NODE_NAME) or "contributor",
         "total": int(r.get("total") or 0),
         "issues": int(r.get("issues") or 0),
         "pulls": int(r.get("pulls") or 0),
         "commits": int(r.get("commits") or 0)}
        for r in contrib_rows if int(r.get("total") or 0) > 0
    ]

    funds = await _funds_received_boards(env)
    short_board = globals().get("_short_repo_board")

    resp = json_response(
        {"ok": True,
         "windowHours": ONLINE_HISTORY_RETAIN_MS // 3600000,
         "uptime": uptime_board[:LEADERBOARD_LIMIT],
         "nodes": node_board,
         "repos": repo_board[:LEADERBOARD_LIMIT],
         "mirrors": mirror_board[:LEADERBOARD_LIMIT],
         "hosted": hosted_board[:LEADERBOARD_LIMIT],
         "largest": await short_board(env, largest_board[:LEADERBOARD_LIMIT])
         if short_board else largest_board[:LEADERBOARD_LIMIT],
         "dataHosted": data_board[:LEADERBOARD_LIMIT],
         "contributors": contrib_board,
         "fundsMainnodes": funds["mainnode"][:LEADERBOARD_LIMIT],
         "fundsContributors": funds["contributor"][:LEADERBOARD_LIMIT],
         "fundsProjects": funds["project"][:LEADERBOARD_LIMIT],
         "fundsState": "historical-reporting-aggregate",
         "fundsCustody": "no-wallet-custody",
         "fundsNotice": (
             "These are reporting aggregates, not wallet balances or proof of "
             "payment. ForkMesh holds no recipient key or funds; only a "
             "finalized public transaction signature establishes a completed "
             "on-chain transfer."
         )},
        cache_seconds=NETWORK_LEADERBOARDS_TTL,
    )
    await edge_cache_put(NETWORK_LEADERBOARDS_CACHE_KEY, resp)
    return resp


# --- Referral program ---------------------------------------------------------
# Every registered user account owns the share link /r/<name>. A click on the
# link bumps that account's counter and bounces to /signup?ref=<name>; a
# independently active member carrying that ref may bump the signup counter.
# Public rankings expose accepted account-name relationships; raw signup and
# anti-gaming evidence remains encrypted and available only to administrators.
REFERRAL_LEADERBOARD_CACHE_KEY = (
    "https://forkmesh.internal/api/referrals/leaderboard"
)
REFERRAL_LEADERBOARD_TTL = 30  # seconds per colo; counters tolerate the lag


# Resolve a raw referral code to (name, blind index) — only active, real user
# accounts participate, so junk /r/ paths and node accounts count nothing.
async def _referral_account(env, raw_name):
    name = clean_string(raw_name or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name):
        return "", ""
    name_bi, rec = await _account_row(env, name)
    if (not rec or rec.get("status") != "active" or
            _account_kind(rec) != "user"):
        return "", ""
    return name, name_bi


async def _referral_bump(env, name, name_bi, column):
    await d1_run(
        env,
        "INSERT INTO referral_stats (referrer_bi, name, %s, last_ts) "
        "VALUES (?,?,1,?) "
        "ON CONFLICT(referrer_bi) DO UPDATE SET %s=%s+1, "
        "name=excluded.name, last_ts=excluded.last_ts"
        % (column, column, column),
        name_bi, name, int(Date.now()))


async def _referral_counts(env, name_bi):
    """Live (clicks, signups, last activity ms) for one referrer."""
    row = await d1_first(
        env,
        "SELECT COALESCE(s.clicks,0) AS clicks,"
        "COUNT(CASE WHEN r.decision='credited' THEN 1 END) AS signups,"
        "COALESCE(s.last_ts,0) AS last_ts FROM (SELECT ? AS referrer_bi) q "
        "LEFT JOIN referral_stats s ON s.referrer_bi=q.referrer_bi "
        "LEFT JOIN referral_attributions r ON r.referrer_bi=q.referrer_bi",
        name_bi)
    rec = row or {}
    try:
        return (int(rec.get("clicks") or 0), int(rec.get("signups") or 0),
                int(rec.get("last_ts") or 0))
    except (TypeError, ValueError):
        return 0, 0, 0


async def _refresh_referral_signup_count(env, name, name_bi):
    """Make the accepted attribution ledger authoritative for signup totals."""
    await d1_run(
        env,
        "INSERT INTO referral_stats (referrer_bi,name,signups,last_ts) "
        "VALUES (?,?,(SELECT COUNT(*) FROM referral_attributions "
        "WHERE referrer_bi=? AND decision='credited'),?) "
        "ON CONFLICT(referrer_bi) DO UPDATE SET name=excluded.name,"
        "signups=excluded.signups,last_ts=excluded.last_ts",
        name_bi, name, name_bi, int(Date.now()))


# Link-preview crawlers: when a share link is posted to Mastodon, every server
# that sees the post fetches the URL, and Slack/Discord/Twitter do the same.
# They get the preview page below instead of the 302 - and they never move the
# counters, because a boost fanning a post out to 200 servers is not 200
# clicks. Deliberately coarse: a false positive costs one uncounted click.
REFERRAL_PREVIEW_AGENTS = (
    "bot", "crawler", "spider", "preview", "mastodon", "pleroma", "akkoma",
    "misskey", "friendica", "lemmy", "activitypub", "facebookexternalhit",
    "whatsapp", "embedly", "iframely", "opengraph", "quora link", "curl/",
    "wget/",
)


def _is_link_preview_agent(request):
    try:
        ua = str(request.headers.get("user-agent") or "").lower()[:512]
    except Exception:
        return False
    return any(marker in ua for marker in REFERRAL_PREVIEW_AGENTS)


def _referral_preview_page(origin, name, clicks, signups):
    # Minimal HTML whose only job is to carry the OpenGraph tags; the card PNG
    # they point at is rendered per request from the same counters, so the
    # unfurl shows how far this link has actually travelled instead of the
    # generic "Create account - ForkMesh" signup preview (adhoc #313). Humans
    # who trip the crawler heuristic still land on signup via the refresh.
    target = "/signup?ref=" + quote(name)
    summary = "%s click%s and %s signup%s so far." % (
        clicks, "" if clicks == 1 else "s",
        signups, "" if signups == 1 else "s")
    title = "Join ForkMesh with @%s" % name
    description = (
        "%s invites you to ForkMesh - distributed Git hosting on a mesh of "
        "desktop nodes. %s" % ("@" + name, summary))
    card = "%s/api/referrals/%s/card.png" % (origin, quote(name))
    share = "%s/r/%s" % (origin, quote(name))
    return (
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width, "
        "initial-scale=1\">"
        "<title>%s</title>"
        "<meta name=\"description\" content=\"%s\">"
        "<link rel=\"canonical\" href=\"%s\">"
        "<meta property=\"og:type\" content=\"website\">"
        "<meta property=\"og:site_name\" content=\"ForkMesh\">"
        "<meta property=\"og:url\" content=\"%s\">"
        "<meta property=\"og:title\" content=\"%s\">"
        "<meta property=\"og:description\" content=\"%s\">"
        "<meta property=\"og:image\" content=\"%s\">"
        "<meta property=\"og:image:width\" content=\"%d\">"
        "<meta property=\"og:image:height\" content=\"%d\">"
        "<meta property=\"og:image:alt\" content=\"%s\">"
        "<meta name=\"twitter:card\" content=\"summary_large_image\">"
        "<meta name=\"twitter:title\" content=\"%s\">"
        "<meta name=\"twitter:description\" content=\"%s\">"
        "<meta name=\"twitter:image\" content=\"%s\">"
        "<meta http-equiv=\"refresh\" content=\"0; url=%s\">"
        "</head><body><p><a href=\"%s\">%s</a></p><p>%s</p></body></html>"
        % (_html_escape(title), _html_escape(description), share,
           share, _html_escape(title), _html_escape(description), card,
           og_card.CARD_W, og_card.CARD_H,
           _html_escape("%s: %s" % (title, summary)),
           _html_escape(title), _html_escape(description), card,
           _html_escape(target), _html_escape(target), _html_escape(title),
           _html_escape(summary)))


REFERRAL_CLICK_WINDOW_MS = 24 * 60 * 60 * 1000
REFERRAL_CLICK_RETENTION_MS = 35 * 24 * 60 * 60 * 1000
REFERRAL_CLICK_AUDIT_RETENTION_MS = 180 * 24 * 60 * 60 * 1000
_record_unique_referral_click = _account_users.export(
    "_record_unique_referral_click")
_issue_referral_click_token = _account_users.export(
    "_issue_referral_click_token")


# GET /r/<name>: count the click, then land on signup with the ref attached so
# the eventual account creation can credit the referrer. Link-preview crawlers
# get an OpenGraph page carrying this referrer's live counters instead.
async def referral_click(env, raw_name, request=None):
    await ensure_schema(env)
    name = ""
    referral_token = ""
    try:
        name, name_bi = await _referral_account(env, raw_name)
        if name_bi and request is not None and _is_link_preview_agent(request):
            clicks, signups, _last_ts = await _referral_counts(env, name_bi)
            return Response(
                _referral_preview_page(
                    _ap_origin(env, request), name, clicks, signups),
                status=200, headers={
                    "content-type": "text/html; charset=utf-8",
                    # Counters are live: never let a shared cache freeze the
                    # numbers a re-crawl is supposed to refresh.
                    "cache-control": "no-store, max-age=0, must-revalidate",
                })
        click_decision = (
            await _record_unique_referral_click(env, name_bi, request)
            if name_bi and request is not None else False)
        if click_decision:
            if click_decision == "accepted":
                await _referral_bump(env, name, name_bi, "clicks")
            referral_token = await _issue_referral_click_token(env, name_bi)
    except Exception:
        pass  # a broken counter must never break the signup funnel
    target = "/signup"
    if name and referral_token:
        target += "?ref=" + quote(name) + "&rid=" + quote(referral_token)
    return Response("", status=302, headers={
        "location": target,
        "cache-control": "no-store, max-age=0, must-revalidate",
    })


REFERRAL_CARD_TTL = 60  # seconds per colo; short so re-unfurls look live


# GET /api/referrals/<name>/card.png: the og:image of the preview page above -
# the referrer's handle plus their live click/signup counters, rendered the
# same way as the repo info card (see og_card.py).
async def referral_card_handler(env, request, raw_name):
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    name, name_bi = await _referral_account(env, raw_name)
    if not name_bi:
        return json_response({"error": "not_found"}, status=404)
    origin = _ap_origin(env, request)
    cache_key = "%s/api/referrals/%s/card.png" % (origin, quote(name))
    cached = await edge_cache_match_media(cache_key, "image/png")
    if cached is not None:
        return cached
    clicks, signups, last_ts = await _referral_counts(env, name_bi)
    png = og_card.render_referral_card({
        "name": name,
        "host": urlparse(origin).netloc or "forkmesh.com",
        "clicks": clicks,
        "signups": signups,
        "lastTs": last_ts,
    }, time.time())
    # Uint8Array.new copies into a JS-owned buffer: a bare _to_js(bytes) view
    # into WASM memory read off the GIL crashes the isolate (see
    # repo_card_handler).
    resp = JsResponse.new(Uint8Array.new(_to_js(bytes(png))), to_js({
        "status": 200,
        "headers": {
            "content-type": "image/png",
            "cache-control": "public, max-age=%d" % REFERRAL_CARD_TTL,
        },
    }))
    await edge_cache_put(cache_key, resp)
    return resp


