_referral_user_agent = _account_users.export("_referral_user_agent")
_referral_flags = _account_users.export("_referral_flags")
_referral_join_chronology_flags = _account_users.export(
    "_referral_join_chronology_flags")
_capture_referral_source = _account_users.export("_capture_referral_source")
_record_referral_signup = _account_users.export("_record_referral_signup")
_finalize_referral_signup = _account_users.export("_finalize_referral_signup")


REFERRAL_LEADERBOARD_LIMIT = 10


referral_leaderboard = _account_users.export("referral_leaderboard")


# --- Inbound website referrals ------------------------------------------------
# Which other websites link people here. Counted from the Referer header of
# ordinary page loads as one aggregate row per hostname. The latest bounded
# referring URL is retained for the public board, with credentials/fragments
# removed and sensitive query values redacted. No visitor record, IP, user
# agent, or ForkMesh landing path is retained.
SITE_REFERRER_LEADERBOARD_CACHE_KEY = (
    "https://forkmesh.internal/api/referrals/sites"
)
SITE_REFERRER_LEADERBOARD_TTL = 60  # seconds per colo; counters tolerate lag
SITE_REFERRER_LEADERBOARD_LIMIT = 25
# Referer is attacker-controlled (classic analytics referrer spam), so the
# table is capped: the hourly prune keeps the busiest hosts and drops the long
# tail a spammer would grow. Existing hosts keep counting either way.
SITE_REFERRER_RETAIN_HOSTS = 500
MAX_SITE_REFERRER_HOST = 100
MAX_SITE_REFERRER_URL = 1024
SITE_REFERRER_REDACTED_QUERY_KEYS = frozenset({
    "access_token", "api_key", "apikey", "auth", "authorization", "code",
    "credential", "email", "key", "password", "secret", "session",
    "sessionid", "sig", "signature", "token",
})

_SITE_REFERRER_HOST_RE = re.compile(
    r"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?"
    r"(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$")

# Names that are this instance itself, a sibling service, or a dev host: an
# internal hop is not another website sending us a visitor.
SITE_REFERRER_SELF_HOSTS = frozenset({
    "forkmesh.com", "b.forkmesh.com", "forkmesh.internal", "localhost",
})


def _site_referrer_host(referer, self_host=""):
    """Referring hostname to count for one request, or "" to count nothing.

    Deliberately strict: only http(s) URLs with a real multi-label hostname
    count, so IP literals, intranet names, and junk headers never reach the
    board. ``www.`` is folded away so one site is one row.
    """
    raw = str(referer or "").strip()[:512]
    if "://" not in raw:
        return ""
    try:
        parsed = urlparse(raw)
        host = str(parsed.hostname or "")
    except Exception:
        return ""
    if parsed.scheme not in ("http", "https"):
        return ""
    host = host.strip().lower().rstrip(".")
    if host.startswith("www."):
        host = host[4:]
    if not host or len(host) > MAX_SITE_REFERRER_HOST:
        return ""
    if not _SITE_REFERRER_HOST_RE.match(host):
        return ""  # single-label names, IPv6 literals, credentials, junk
    if host.replace(".", "").isdigit():
        return ""  # bare IPv4 literal
    if host.endswith(".local") or host.endswith(".internal"):
        return ""
    if host in SITE_REFERRER_SELF_HOSTS:
        return ""
    own = str(self_host or "").strip().lower().rstrip(".")
    if own.startswith("www."):
        own = own[4:]
    if own and (host == own or host.endswith("." + own)
                or own.endswith("." + host)):
        return ""  # this deployment, a sibling subdomain, or its parent zone
    return host


def _site_referrer_url(referer, expected_host):
    """A bounded public referring URL for ``expected_host``, or ``""``.

    Referer is attacker-controlled and can contain secrets in query values.
    Preserve the real page path and ordinary query values, but remove
    credentials/fragments and replace common secret-bearing values before
    anything reaches D1 or the public API.
    """
    raw = str(referer or "").strip()[:MAX_SITE_REFERRER_URL * 2]
    host = str(expected_host or "").strip().lower()
    try:
        parsed = urlparse(raw)
        candidate_host = str(parsed.hostname or "").lower().rstrip(".")
        if candidate_host.startswith("www."):
            candidate_host = candidate_host[4:]
        if (
            parsed.scheme not in ("http", "https")
            or candidate_host != host
            or parsed.username
            or parsed.password
        ):
            return ""
        # Non-default ports make an origin materially different and are not
        # accepted by the public hostname board.
        port = parsed.port
        if port is not None and not (
            (parsed.scheme == "https" and port == 443)
            or (parsed.scheme == "http" and port == 80)
        ):
            return ""
        safe_query = urlencode([
            (
                str(key)[:120],
                "[redacted]"
                if str(key).lower() in SITE_REFERRER_REDACTED_QUERY_KEYS
                else str(value)[:300],
            )
            for key, value in parse_qsl(
                parsed.query, keep_blank_values=True, max_num_fields=40)
        ], doseq=True)
        value = urlunparse((
            parsed.scheme,
            host,
            parsed.path or "/",
            parsed.params,
            safe_query,
            "",  # fragments are client-local and never needed on this board
        ))
        return value[:MAX_SITE_REFERRER_URL]
    except Exception:
        return ""


def _is_page_navigation(request):
    """True for a top-level HTML page load, not an asset or subresource."""
    try:
        headers = request.headers
        dest = str(headers.get("sec-fetch-dest") or "").strip().lower()
        mode = str(headers.get("sec-fetch-mode") or "").strip().lower()
        accept = str(headers.get("accept") or "").lower()
    except Exception:
        return False
    # The Sec-Fetch-* pair is absent on older browsers; Accept alone then
    # decides, which is the same signal the rest of the site uses.
    if dest and dest != "document":
        return False
    if mode and mode != "navigate":
        return False
    return "text/html" in accept


async def record_site_referral(env, request, url, status):
    """Count one visit that another website sent us. Best-effort: never
    raises, because a counter must not break or fail a page load."""
    try:
        if int(status or 0) != 200 or method_name(request) != "GET":
            return
        if not _is_page_navigation(request):
            return
        if _is_link_preview_agent(request):
            return  # unfurlers re-fetch shared links; that is not a visit
        host = _site_referrer_host(
            request.headers.get("referer"), getattr(url, "hostname", "") or "")
        if not host:
            return
        referrer_url = _site_referrer_url(
            request.headers.get("referer"), host)
        if not referrer_url:
            return
        await ensure_schema(env)
        now = int(Date.now())
        await d1_run(
            env,
            "INSERT INTO site_referrers "
            "(host, visits, first_ts, last_ts, last_url) "
            "VALUES (?,1,?,?,?) "
            "ON CONFLICT(host) DO UPDATE SET visits=visits+1, "
            "last_ts=excluded.last_ts,last_url=excluded.last_url",
            host, now, now, referrer_url)
    except Exception:
        pass


async def site_referrer_leaderboard(env):
    cached = await edge_cache_match(SITE_REFERRER_LEADERBOARD_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT host, visits, last_ts, last_url FROM site_referrers "
        "WHERE visits > 0 "
        "ORDER BY visits DESC, last_ts DESC, host LIMIT ?",
        SITE_REFERRER_LEADERBOARD_LIMIT)
    board = [
        {"host": clean_string(r.get("host", ""), MAX_SITE_REFERRER_HOST),
         "url": clean_string(r.get("last_url", ""), MAX_SITE_REFERRER_URL),
         "visits": int(r.get("visits") or 0),
         "lastTs": int(r.get("last_ts") or 0)}
        for r in rows if r.get("host")
    ]
    totals = await d1_first(
        env,
        "SELECT COUNT(*) AS hosts, SUM(visits) AS visits FROM site_referrers "
        "WHERE visits > 0") or {}
    resp = json_response(
        {"ok": True, "board": board,
         "sites": int(totals.get("hosts") or 0),
         "visits": int(totals.get("visits") or 0)},
        cache_seconds=SITE_REFERRER_LEADERBOARD_TTL)
    await edge_cache_put(SITE_REFERRER_LEADERBOARD_CACHE_KEY, resp)
    return resp


# --- Top tip recipients -------------------------------------------------------
# The public ledger's member-tip receipts, folded per recipient. A tip is a SOL
# transfer the sender's own desktop signs with a key that never leaves its local
# vault and broadcasts straight to a Solana RPC; the relay only ever sees the
# public receipt afterwards, and /api/ledger already publishes both @names
# beside the chain signature. So this board is a projection of records that are
# public already, not a new disclosure. Two things it deliberately is not: a
# verified figure, because the amount is what the sender reported and the linked
# transaction is authoritative, and a balance, because the funds went to the
# recipient's own address and ForkMesh never held them.
TIP_RECIPIENT_LEADERBOARD_CACHE_KEY = (
    "https://forkmesh.internal/api/leaderboards/tip-recipients"
)
TIP_RECIPIENT_LEADERBOARD_TTL = 300  # seconds per colo
TIP_RECIPIENT_LEADERBOARD_LIMIT = 10
# SQL ranks before a decrypted profile can drop a recipient who has since gone
# private, closed the account, or is a node rather than a member, so scan past
# the board's own depth and trim after the gate.
TIP_RECIPIENT_SCAN_LIMIT = 60


async def tip_recipient_leaderboard(env):
    cached = await edge_cache_match(TIP_RECIPIENT_LEADERBOARD_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    # Mainnet only. A devnet or testnet lamport is free to mint, so counting one
    # here would let a faucet airdrop outrank every real tip on the network.
    # tip_notice.to_bi is the blind index of the recipient account, which is
    # exactly users.user_bi, so this join is one row per group.
    rows = await d1_all(
        env,
        "SELECT u.data AS data,SUM(t.lamports) AS lamports,"
        "COUNT(*) AS tips,COUNT(DISTINCT t.from_bi) AS senders,"
        "MAX(t.ts) AS last_ts FROM tip_notice AS t "
        "JOIN users AS u ON u.user_bi=t.to_bi "
        # Keep the definition aligned with the ledger's ``member-tip`` rows:
        # a contributor reward writes a notice too so its recipient is emailed,
        # but the reward record is the public ledger's canonical entry.
        "WHERE t.network='mainnet' AND NOT EXISTS ("
        "SELECT 1 FROM contributor_reward_estimates "
        "WHERE tx_signature=t.signature AND status<>'cancelled') "
        "GROUP BY t.to_bi "
        "ORDER BY SUM(t.lamports) DESC,MAX(t.ts) DESC,t.to_bi LIMIT ?",
        TIP_RECIPIENT_SCAN_LIMIT)
    board = []
    seen = set()
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data", ""))
        # The same predicate every other member-facing figure uses, so this
        # board cannot disagree with the accounts directory about who is public.
        if not _is_public_roster_member(rec):
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        if not name or name in seen:
            continue
        seen.add(name)
        lamports = int(row.get("lamports") or 0)
        board.append({
            "name": name,
            "lamports": lamports,
            "sol": lamports / LAMPORTS_PER_SOL,
            "tips": int(row.get("tips") or 0),
            "senders": int(row.get("senders") or 0),
            "lastTs": int(row.get("last_ts") or 0),
        })
    resp = json_response(
        {"ok": True,
         "board": board[:TIP_RECIPIENT_LEADERBOARD_LIMIT],
         # Public recipients the scan found, so a board showing ten out of a
         # longer tail reads as a top ten rather than as everyone who was ever
         # tipped.
         "recipients": len(board),
         "custody": "none-peer-to-peer-self-custodial",
         "notice": (
             "Member-to-member tips as reported to the public ledger. Each "
             "amount is the sender's own reported figure and the linked "
             "Solana transaction is authoritative. ForkMesh held neither the "
             "funds nor the keys, and a place here is not a payout or a "
             "promise of one."
         )},
        cache_seconds=TIP_RECIPIENT_LEADERBOARD_TTL)
    await edge_cache_put(TIP_RECIPIENT_LEADERBOARD_CACHE_KEY, resp)
    return resp


# --- Member SOL wallets -------------------------------------------------------
# Members who publish an optional self-custodial payout address, ranked by the
# public balance of that address. Both halves are already public: the address is
# public profile data (_account_public_payload exposes it), and the amount is a
# plain getBalance any block explorer answers identically for that address.
# Private profiles are excluded, no key or transaction is involved, and a
# position here is neither a payout nor a promise of one.
WALLET_LEADERBOARD_CACHE_KEY = (
    "https://forkmesh.internal/api/leaderboards/wallets"
)
WALLET_LEADERBOARD_TTL = 300  # seconds per colo; balances move slower than this
WALLET_LEADERBOARD_LIMIT = 10
# Each balance can cost a public-RPC subrequest, so a rebuild considers only the
# least-recently-checked slice and ranks everyone else from their stored read.
# Rotation means every published wallet is reached within a few rebuilds instead
# of a fixed head of the directory being the only one ever priced — and the
# slice is then filtered again by the shared hourly cache
# (SOLANA_DISPLAY_BALANCE_TTL_MS), so a warm board rebuilds for free.
WALLET_BALANCE_REFRESH_PER_REBUILD = 6
WALLET_BALANCE_RETAIN_ROWS = 500


async def wallet_leaderboard(env, refresh=False):
    cached = None if refresh else await edge_cache_match(
        WALLET_LEADERBOARD_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT data FROM users ORDER BY username COLLATE NOCASE LIMIT ?",
        1000)
    members = []
    seen = set()
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data", ""))
        if (not rec or _account_kind(rec) != "user"
                or rec.get("status") != "active"
                or rec.get("profile_private")):
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        wallet = (rec.get("solana") or "").strip()
        if not name or name in seen or not SOLANA_RE.match(wallet):
            continue
        seen.add(name)
        members.append({"name": name, "wallet": wallet})

    stored = await _stored_wallet_balances(env)

    # Oldest reading first, so the rotation always spends its subrequests on the
    # least fresh members (an unseen wallet sorts at 0 and goes first).
    members.sort(key=lambda m: (stored.get(m["wallet"], (0, 0))[1], m["name"]))
    # A background rebuild considers only the least-fresh slice. A refresh press
    # considers everyone the board can actually show, with `budget` bounding
    # what that press is allowed to spend.
    slice_ = members[:WALLET_LEADERBOARD_LIMIT if refresh
                     else WALLET_BALANCE_REFRESH_PER_REBUILD]
    # Sequential reads (each already bounded by SOLANA_RPC_TIMEOUT_MS via a
    # native AbortSignal): WALLET_BALANCE_REFRESH_PER_REBUILD is small, and a
    # gather here is the concurrency the runtime cannot survive — see the
    # no-concurrent-tasks rule at the top of this module.
    #
    # _display_balance_lamports is what makes the rotation cheap: a member whose
    # stored reading is under an hour old costs nothing, so once the board is
    # warm a rebuild spends no subrequests at all. A failed RPC keeps the last
    # stored reading rather than publishing an unchecked address as zero.
    refreshed = 0
    budget = {"left": SOLANA_DISPLAY_REFRESH_MAX_PER_REQUEST}
    for member in slice_:
        was = stored.get(member["wallet"], (0, 0))[1]
        _, checked_at = await _display_balance_lamports(
            env, member["wallet"], force=refresh, stored=stored,
            name=member["name"], budget=budget)
        if checked_at > was:
            refreshed += 1
    # An address a member has since removed or replaced leaves a row nothing
    # reads, so bound the table the way the referrer board does — only once it
    # actually needs bounding, since every rebuild would otherwise pay a write.
    if len(stored) > WALLET_BALANCE_RETAIN_ROWS:
        await d1_run(
            env,
            "DELETE FROM wallet_balances WHERE wallet NOT IN ("
            "SELECT wallet FROM wallet_balances "
            "ORDER BY checked_at DESC LIMIT ?)",
            WALLET_BALANCE_RETAIN_ROWS)

    board = []
    for member in members:
        lamports, checked_at = stored.get(member["wallet"], (0, 0))
        if not checked_at:
            continue
        board.append({
            "name": member["name"],
            "wallet": member["wallet"],
            "lamports": lamports,
            "sol": lamports / LAMPORTS_PER_SOL,
            "checkedAt": checked_at,
        })
    board.sort(key=lambda entry: (-entry["lamports"], entry["name"]))
    resp = json_response(
        {"ok": True,
         "board": board[:WALLET_LEADERBOARD_LIMIT],
         # Members publishing an address, and how many of them this rebuild
         # re-priced, so a rotation behind the full set is visible rather than
         # looking like complete coverage.
         "members": len(members),
         "refreshed": refreshed,
         "custody": "external-self-custodial-public-address",
         "notice": (
             "Public payout addresses and their public on-chain balances. "
             "ForkMesh holds no member funds or keys, and a place on this "
             "board is not a reward, payout, or promise of one."
         )},
        cache_seconds=WALLET_LEADERBOARD_TTL)
    await edge_cache_put(WALLET_LEADERBOARD_CACHE_KEY, resp)
    return resp


async def leaderboards_overview(env):
    """One public leaderboard model shared by the website and World.

    Source endpoints keep their own cache and privacy boundaries. This view
    only normalizes their already-public rows so clients cannot drift on which
    boards exist, how they are titled, or which value each board ranks.
    """
    # These seven public source calls are independent and read one after
    # another — deliberately not gathered. Concurrent tasks (one of them the
    # users directory's row-decrypt scan) are exactly the fan-out that trips
    # the Pyodide task-reentrancy wedge and leaves the isolate answering 1101
    # for every later request; see the no-concurrent-tasks rule at the top of
    # this module. Each source keeps its own edge cache/memo and this endpoint
    # is itself cached, so the sum-instead-of-max latency is paid rarely.
    # Late-bound so an unread source is never left as an orphan coroutine.
    sources = (
        ("network", lambda: network_leaderboards(env)),
        ("referrals", lambda: referral_leaderboard(env)),
        ("sites", lambda: site_referrer_leaderboard(env)),
        ("users", lambda: _account_users_directory(env, None)),
        ("issue-reporters", lambda: issue_reporter_leaderboard(env)),
        ("wallets", lambda: wallet_leaderboard(env)),
        ("tips", lambda: tip_recipient_leaderboard(env)),
    )
    # Per-source isolation, which return_exceptions=True used to provide: one
    # broken source used to 500 the whole hub — the website grid and the World
    # island both went dark over a board neither of them needed. adhoc #225 did
    # exactly that from a call-arity mismatch deep inside the users directory,
    # and the same 500 was logged again here under /api/leaderboards. A source
    # that fails now costs only the boards that need it.
    payloads = []
    degraded = []
    for name, source in sources:
        try:
            result = await source()
        except Exception as error:
            degraded.append(name)
            payloads.append({})
            # Workers Logs stays off, so a degraded board would otherwise be
            # invisible: report it best-effort, and never let telemetry sink
            # the response the surviving boards are still being served in.
            try:
                await capture_sentry_error(
                    env, 500, "GET", "/api/leaderboards",
                    "leaderboards source failed: " + name + ": "
                    + _safe_error_text(error), error=error)
            except BaseException:
                pass
            continue
        payloads.append(await _response_json(result))
    network, referrals, sites, users, reporters, wallets, tips = payloads
    activity_rows = []
    for user in users.get("users", []):
        if not isinstance(user, dict):
            continue
        name = clean_string(user.get("name", ""), MAX_NODE_NAME)
        total_active_ms = _world_public_total_active_ms(
            user.get("totalActiveMs", 0))
        if not name or total_active_ms <= 0:
            continue
        activity_rows.append({
            "name": name,
            "totalActiveMs": total_active_ms,
            "activityBucket": clean_string(
                user.get("activityBucket", ""), 24),
        })
    activity_rows.sort(
        key=lambda row: (-row["totalActiveMs"], row["name"].lower()))
    activity_rows = activity_rows[:LEADERBOARD_LIMIT]

    # The live canonical tracker is folded from both open and closed records.
    # Its reviewed display reporter can differ from the immutable signed
    # opening author. Only current public user accounts enter this board;
    # bot/node/external identities remain available to profile credit but are
    # not presented as ForkMesh users.
    reporter_counts = reporters.get("counts")
    reporter_counts = reporter_counts if isinstance(reporter_counts, dict) else {}
    reporter_rows = []
    profile_origin = _ap_origin(env)
    # Fediverse handles resolved in this one pass: the reporter board and the
    # tip board both link them, and walking the thousand-record directory a
    # second time per board would cost more than the dict does.
    mastodon_by_name = {}

    def link_profile(row):
        """Give a member row the profile links every community board carries."""
        name = str(row.get("name") or "")
        row["profileUrl"] = profile_origin + "/@" + quote(name)
        handle = mastodon_by_name.get(name)
        if handle:
            row["mastodon"], row["mastodonUrl"] = handle
        return row

    for user in users.get("users", []):
        if not isinstance(user, dict):
            continue
        name = clean_string(user.get("name", ""), MAX_NODE_NAME).lower()
        if not name:
            continue
        mastodon = _clean_mastodon_handle(user.get("mastodon", ""))
        mastodon_url = _mastodon_url(mastodon)
        if mastodon and mastodon_url:
            mastodon_by_name[name] = (mastodon, mastodon_url)
        issues_reported = int(reporter_counts.get(name, 0) or 0)
        if issues_reported <= 0:
            continue
        reporter_rows.append(link_profile({
            "name": name,
            "issues": issues_reported,
        }))
    reporter_rows.sort(key=lambda row: (-row["issues"], row["name"]))
    reporter_rows = reporter_rows[:LEADERBOARD_LIMIT]

    # The tip source already applied the public-roster gate and ranked by
    # lamports, so this only adds the profile links. Copied rather than mutated
    # in place because the source response is edge-cached and shared.
    tip_rows = tips.get("board")
    tip_rows = [
        link_profile(dict(row))
        for row in (tip_rows if isinstance(tip_rows, list) else [])
        if isinstance(row, dict) and row.get("name")
    ][:LEADERBOARD_LIMIT]
    site_rows = sites.get("board")
    site_rows = (site_rows[:LEADERBOARD_LIMIT]
                 if isinstance(site_rows, list) else [])

    def board(board_id, title, subtitle, value_kind, rows, category,
              source="network"):
        source_names = (
            source if isinstance(source, (tuple, list, set)) else (source,))
        return {
            "id": board_id,
            "title": title,
            "subtitle": subtitle,
            "valueKind": value_kind,
            "category": category,
            "rows": rows if isinstance(rows, list) else [],
            # An empty board that failed to load reads exactly like one nobody
            # has entered yet. Name the source per board so a client can say
            # which of the two it is showing.
            "degraded": any(name in degraded for name in source_names),
        }

    window_hours = int(network.get("windowHours") or 48)
    boards = [
        board(
            "activity", "World activity",
            "Registered members by total public active time",
            "duration", activity_rows, "community", "users"),
        board(
            "uptime", "Mainnode uptime",
            "Most minutes online · last %dh" % window_hours,
            "minutes", network.get("uptime"), "network"),
        board(
            "node-storage", "Node storage",
            "Public mirror bytes reported by each connected node",
            "bytes", network.get("nodes"), "network"),
        board(
            "repos", "Top owners", "Most public repositories",
            "repos", network.get("repos"), "repositories"),
        board(
            "mirrors", "Most mirrored",
            "Repositories hosted under the most owners",
            "mirrors", network.get("mirrors"), "repositories"),
        board(
            "hosted", "Longest hosted", "Repositories online the longest",
            "age", network.get("hosted"), "repositories"),
        board(
            "largest", "Largest repositories",
            "Most mirror data per repository",
            "bytes", network.get("largest"), "repositories"),
        board(
            "data-hosted", "Most data hosted",
            "Public mirror data hosted per owner",
            "bytes", network.get("dataHosted"), "network"),
        board(
            "contributors", "Contributor activity",
            "Issues + pull requests + commits",
            "contributions", network.get("contributors"), "community"),
        board(
            "issue-reporters", "Issue reporters",
            "Users who have reported the most tracker issues",
            "issues", reporter_rows, "community",
            ("issue-reporters", "users")),
        board(
            "referrals", "Member referrals",
            "Signups first; clicks break ties",
            "referrals", referrals.get("board"), "community", "referrals"),
        board(
            "referring-sites", "Referring websites",
            "External sites sending visits to ForkMesh",
            "visits", site_rows, "community", "sites"),
        board(
            "wallets", "Member SOL wallets",
            "Published payout addresses by public on-chain balance",
            "sol", wallets.get("board"), "community", "wallets"),
        board(
            "tip-recipients", "Top tip recipients",
            "Member-to-member tips recorded in the public ledger",
            "sol", tip_rows, "community", "tips"),
        board(
            "funds-mainnodes", "Legacy funds · mainnodes",
            "Historical reporting aggregate; not a balance",
            "sol", network.get("fundsMainnodes"), "historical"),
        board(
            "funds-contributors", "Legacy funds · contributors",
            "Historical reporting aggregate; not pending funds",
            "sol", network.get("fundsContributors"), "historical"),
        board(
            "funds-projects", "Legacy funds · projects",
            "Historical migration records; not current funding",
            "sol", network.get("fundsProjects"), "historical"),
    ]
    return json_response(
        {
            "ok": True,
            "observedAt": int(Date.now()),
            # Which sources could not be read for this rebuild. Their boards
            # are present but empty, so without this an outage behind one of
            # them reads as "nobody has ranked yet" rather than a gap.
            "degraded": degraded,
            "boards": boards,
            "network": network,
            "activity": {"board": activity_rows},
            "referrals": referrals,
            "sites": sites,
            "wallets": wallets,
            "tips": tips,
            "fundsNotice": network.get("fundsNotice", ""),
            "fundsState": network.get("fundsState", ""),
            "fundsCustody": network.get("fundsCustody", ""),
        },
        cache_seconds=NETWORK_STATS_TTL,
    )


async def prune_site_referrers(env):
    """Keep the board bounded: the busiest hosts stay, the long tail goes."""
    await ensure_schema(env)
    await d1_run(
        env,
        "DELETE FROM site_referrers WHERE host NOT IN ("
        "SELECT host FROM site_referrers "
        "ORDER BY visits DESC, last_ts DESC LIMIT ?)",
        SITE_REFERRER_RETAIN_HOSTS)


async def prune_blog_post_view_seen(env):
    """Drop read-dedupe rows no live window can still reference.

    The rows exist only so a reload is not counted twice; once they are older
    than the retention there is nothing left to deduplicate against, and the
    blinded key stops being stored at all.
    """
    await ensure_schema(env)
    await d1_run(
        env,
        "DELETE FROM blog_post_view_seen WHERE last_at < ?",
        int(Date.now()) - BLOG_POST_VIEW_SEEN_TTL_MS)


# Per-post blog reach stays aggregate-only. A 64-register HLL is enough for a
# readable approximate count while fixing each post's uniqueness footprint at
# 64 rows. The transient edge address/coarse client category is HMACed with a
# slug-specific domain; neither input nor digest is retained.
BLOG_POST_PATH_RE = re.compile(r"^/blog/([a-z0-9][a-z0-9-]{0,79})/?$")
BLOG_POST_SLUG_RE = re.compile(r"[a-z0-9][a-z0-9-]{0,79}")
BLOG_POST_UNIQUE_PRECISION = 6
BLOG_POST_REFERRER_LIMIT = 10
# The board shows the top ten sources; announce-network detection reads
# further down the same ranking, because the instance a post was announced on
# is usually a small referrer rather than a top one.
BLOG_POST_REFERRER_SCAN_LIMIT = 50
# The networks a post can be announced on, in the order the post page lists
# them. Both the stored permalinks and the share drafts follow this order.
BLOG_POST_NETWORKS = ("reddit", "mastodon", "twitter")
BLOG_POST_LINK_MAX = 512
BLOG_VIEW_BEACON_MAX_BYTES = 2048
# A reload is not another reader. A view counts once per reader per post
# inside this window, so "views" is a reach number rather than a page-load
# counter; a genuine return read the next day counts again. The dedupe rows
# themselves are dropped once no window can still reference them.
BLOG_POST_VIEW_WINDOW_MS = 24 * 60 * 60 * 1000
BLOG_POST_VIEW_SEEN_TTL_MS = 30 * 24 * 60 * 60 * 1000

# Referring hosts that identify one of the announce networks. Readers arrive
# from an instance long before anyone pastes the permalink into the "Posted
# on" slots, so a detected source fills the slot instead of leaving a post
# that demonstrably was announced reading as unannounced. Mastodon is a fleet
# of instances, so the well-known ones are listed and the usual instance
# naming patterns are matched too.
BLOG_POST_NETWORK_HOSTS = (
    ("reddit", ("reddit.com", "redd.it")),
    ("twitter", ("twitter.com", "x.com", "t.co")),
    ("mastodon", (
        "mastodon.social", "mastodon.online", "mastodon.world",
        "mstdn.social", "fosstodon.org", "hachyderm.io", "infosec.exchange",
        "techhub.social", "floss.social", "indieweb.social", "mas.to",
        "toot.community", "chaos.social", "tech.lgbt", "ioc.exchange",
    )),
)
BLOG_POST_MASTODON_HOST_MARKERS = ("mastodon", "mstdn")


def _blog_post_slug(value):
    slug = str(value or "").strip().lower()
    return slug if BLOG_POST_SLUG_RE.fullmatch(slug) else ""


def _blog_post_network_for_host(host):
    """The announce network a referring host belongs to, or ""."""
    host = str(host or "").strip().lower().rstrip(".")
    if host.startswith("www."):
        host = host[4:]
    if not host:
        return ""
    for network, hosts in BLOG_POST_NETWORK_HOSTS:
        for known in hosts:
            if host == known or host.endswith("." + known):
                return network
    if any(marker in host for marker in BLOG_POST_MASTODON_HOST_MARKERS):
        return "mastodon"
    return ""


async def _fold_blog_post_view(env, request, slug, referer, self_host):
    """Fold one served view of ``slug`` into the aggregate counters.

    Shared by the app-served navigation and the beacon a www-served post
    reports, so both paths store exactly the same aggregate fields: a total,
    one 64-register HLL projection, and per-referring-host counters.

    A reader is folded at most once per :data:`BLOG_POST_VIEW_WINDOW_MS`, so
    reloading a post no longer walks its counter up. The dedupe key is the
    same blinded per-slug digest the HLL folds, held in ``blog_post_view_seen``
    only long enough for the window to mean something.
    """
    now = int(Date.now())
    await ensure_schema(env)

    address = world_visitor_metrics.canonical_edge_address(
        request.headers.get("cf-connecting-ip") or "")
    category = world_visitor_metrics.generalized_user_agent(
        str(request.headers.get("user-agent") or "")[:2048])
    host = _site_referrer_host(referer, self_host)
    token = ""
    if address:
        token = await blind_index(
            env,
            "blog-post-unique-v1:%s\n%s\n%s"
            % (slug, address, category))

    # With no edge address there is nobody to deduplicate against (local
    # development, a stripped proxy); the view counts, as it always did.
    counted, count_referrer = True, bool(host)
    if token:
        seen = await d1_first(
            env,
            "SELECT counted_at,referrer_host FROM blog_post_view_seen "
            "WHERE slug=? AND viewer_key=?",
            slug, token)
        if seen:
            # Measured from the last read that counted, never from the last
            # hit: a reader who reloads every few hours would otherwise keep
            # pushing the window ahead of themselves and never count again.
            counted = (now - int(seen.get("counted_at") or 0)
                       >= BLOG_POST_VIEW_WINDOW_MS)
            # Browsers keep document.referrer across a reload, so a source
            # only counts again when this reader arrives from a new one.
            if not counted:
                count_referrer = bool(host) and host != str(
                    seen.get("referrer_host") or "")
        await d1_run(
            env,
            "INSERT INTO blog_post_view_seen "
            "(slug,viewer_key,first_at,last_at,counted_at,hits,referrer_host) "
            "VALUES (?,?,?,?,?,1,?) "
            "ON CONFLICT(slug,viewer_key) DO UPDATE SET "
            "last_at=excluded.last_at,hits=blog_post_view_seen.hits+1,"
            "counted_at=MAX(blog_post_view_seen.counted_at,"
            "excluded.counted_at),"
            "referrer_host=CASE WHEN excluded.referrer_host<>'' "
            "THEN excluded.referrer_host "
            "ELSE blog_post_view_seen.referrer_host END",
            slug, token, now, now, now if counted else 0, host)

    if counted:
        await d1_run(
            env,
            "INSERT INTO blog_post_metrics (slug,views,updated_at) "
            "VALUES (?,1,?) ON CONFLICT(slug) DO UPDATE SET "
            "views=views+1,updated_at=excluded.updated_at",
            slug, now)
        if token:
            register_id, rank = world_visitor_metrics.hll_register(
                token, precision=BLOG_POST_UNIQUE_PRECISION)
            await d1_run(
                env,
                "INSERT INTO blog_post_unique_hll "
                "(slug,register_id,rank) VALUES (?,?,?) "
                "ON CONFLICT(slug,register_id) DO UPDATE SET "
                "rank=MAX(blog_post_unique_hll.rank,excluded.rank)",
                slug, register_id, rank)

    if count_referrer:
        await d1_run(
            env,
            "INSERT INTO blog_post_referrers "
            "(slug,host,visits,last_ts) VALUES (?,?,1,?) "
            "ON CONFLICT(slug,host) DO UPDATE SET "
            "visits=visits+1,last_ts=excluded.last_ts",
            slug, host, now)


async def record_blog_visit(env, request, url, status):
    try:
        if int(status or 0) != 200 or method_name(request) != "GET":
            return
        match = BLOG_POST_PATH_RE.match(str(getattr(url, "path", "") or ""))
        if not match or not _is_page_navigation(request):
            return
        if _is_link_preview_agent(request):
            return
        await _fold_blog_post_view(
            env, request, match.group(1),
            request.headers.get("referer"),
            getattr(url, "hostname", "") or "")
    except Exception:
        # Reach counters are never allowed to delay or break a blog response.
        pass


async def blog_post_view_beacon(env, request, slug):
    """POST /api/blog/metrics/<slug> — a post reports its own view.

    The blog lives on the www worker as static assets, so the navigation that
    ``record_blog_visit`` folds in never reaches this worker and every post
    read 0 views. The rendered page reports the view instead, carrying the
    referrer the document actually arrived with (the Referer header on this
    request is the post itself). Gated to a browser request from an allowed
    site origin, so it is no more reachable than the page that sends it.
    """
    slug = _blog_post_slug(slug)
    if not slug:
        return json_response({"error": "not_found"}, status=404)
    if not _request_origin_allowed(env, request):
        return json_response(
            {"error": "origin_not_allowed"}, status=403,
            cache_control="no-store, max-age=0")
    if not _is_link_preview_agent(request):
        try:
            payload = await bounded_json_request(
                request, max_bytes=BLOG_VIEW_BEACON_MAX_BYTES)
        except RequestBodyTooLarge:
            raise
        except Exception:
            payload = {}
        referrer = clean_string(
            (payload or {}).get("referrer", "") if isinstance(payload, dict)
            else "", 512)
        try:
            await _fold_blog_post_view(
                env, request, slug, referrer,
                urlparse(_request_origin(request)).hostname or "")
        except Exception:
            # A counter must never turn a served page into a failed request.
            pass
    return await blog_post_metrics(env, slug)


def _blog_post_permalink(value):
    """A public https permalink, or "" — nothing else is stored or served."""
    url = clean_string(value, BLOG_POST_LINK_MAX).strip()
    if not url:
        return ""
    try:
        parsed = urlparse(url)
    except Exception:
        return ""
    if parsed.scheme != "https" or not parsed.hostname:
        return ""
    return url


async def blog_post_links(env, slug):
    """Stored announcement permalinks for one post, keyed by network."""
    rows = await d1_all(
        env, "SELECT network,url FROM blog_post_links WHERE slug=?", slug)
    links = {}
    for row in rows or []:
        network = str(row.get("network") or "")
        url = _blog_post_permalink(row.get("url", ""))
        if network in BLOG_POST_NETWORKS and url:
            links[network] = url
    return links


async def blog_post_links_handler(env, request, slug):
    """GET the announcement permalinks; PUT replaces them (admins only).

    A permalink used to live only in the post's ``data-*`` attributes, so
    announcing a post meant a deploy. The same three slots are now backed by
    D1 and editable from the rendered page — writable only by an account whose
    session proves ``is_admin``, readable by everyone, exactly like the links
    themselves.
    """
    slug = _blog_post_slug(slug)
    if not slug:
        return json_response({"error": "not_found"}, status=404)
    await ensure_schema(env)
    method = method_name(request)
    if method in ("GET", "HEAD"):
        return json_response(
            {"ok": True, "slug": slug, "links": await blog_post_links(env, slug)},
            cache_control="no-store, max-age=0")
    if method != "PUT":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0",
            extra_headers={"allow": "GET, PUT"})
    try:
        data = await bounded_json_request(request, max_bytes=8 * 1024)
    except Exception:
        return json_response(
            {"error": "invalid_json"}, status=400,
            cache_control="no-store, max-age=0")
    if not isinstance(data, dict):
        data = {}
    actor = await _authed_account_name(env, request, data)
    if not actor or not await _is_admin(env, actor):
        return json_response(
            {"error": "not_admin"}, status=403,
            cache_control="no-store, max-age=0")
    submitted = data.get("links")
    if not isinstance(submitted, dict):
        submitted = data
    actor_bi = await blind_index(env, actor)
    now = int(Date.now())
    for network in BLOG_POST_NETWORKS:
        if network not in submitted:
            continue
        raw = clean_string(submitted.get(network) or "", BLOG_POST_LINK_MAX)
        url = _blog_post_permalink(raw)
        if raw.strip() and not url:
            return json_response(
                {"error": "invalid_permalink", "network": network}, status=400,
                cache_control="no-store, max-age=0")
        if not url:
            await d1_run(
                env,
                "DELETE FROM blog_post_links WHERE slug=? AND network=?",
                slug, network)
            continue
        await d1_run(
            env,
            "INSERT INTO blog_post_links "
            "(slug,network,url,updated_at,updated_by_bi) VALUES (?,?,?,?,?) "
            "ON CONFLICT(slug,network) DO UPDATE SET url=excluded.url,"
            "updated_at=excluded.updated_at,"
            "updated_by_bi=excluded.updated_by_bi",
            slug, network, url, now, actor_bi)
    return json_response(
        {"ok": True, "slug": slug, "links": await blog_post_links(env, slug)},
        cache_control="no-store, max-age=0")


async def blog_post_metrics(env, slug):
    slug = _blog_post_slug(slug)
    if not slug:
        return json_response({"error": "not_found"}, status=404)
    await ensure_schema(env)
    totals = await d1_first(
        env,
        "SELECT views FROM blog_post_metrics WHERE slug=?",
        slug) or {}
    registers = await d1_all(
        env,
        "SELECT register_id,rank FROM blog_post_unique_hll WHERE slug=?",
        slug)
    referrers = await d1_all(
        env,
        "SELECT host,visits,last_ts FROM blog_post_referrers "
        "WHERE slug=? AND visits>0 "
        "ORDER BY visits DESC,last_ts DESC,host LIMIT ?",
        slug, BLOG_POST_REFERRER_SCAN_LIMIT)
    ranked = [
        {
            "host": clean_string(row.get("host", ""), MAX_SITE_REFERRER_HOST),
            "url": "https://" + clean_string(
                row.get("host", ""), MAX_SITE_REFERRER_HOST) + "/",
            "visits": int(row.get("visits") or 0),
            "lastTs": int(row.get("last_ts") or 0),
        }
        for row in referrers if row.get("host")
    ]
    board = ranked[:BLOG_POST_REFERRER_LIMIT]
    links = await blog_post_links(env, slug)
    # A network nobody has pasted a permalink for, but which is demonstrably
    # sending readers, is reported as detected: the slot names the source
    # instead of claiming the post was never announced there. Kept apart from
    # ``links`` — an instance root is evidence of an announcement, not the
    # permalink itself, so it never becomes a saved value. Scanned over the
    # wider ranked set rather than the ten rows the board shows: the instance
    # a post was announced on often sends a handful of readers, and a slot
    # that flipped back to "not posted" as soon as busier sources crowded the
    # board out would be worse than never filling it.
    detected = {}
    for row in ranked:
        network = _blog_post_network_for_host(row["host"])
        if not network or network in links or network in detected:
            continue
        detected[network] = {
            "network": network,
            "host": row["host"],
            "url": row["url"],
            "visits": row["visits"],
        }
    return json_response(
        {
            "ok": True,
            "slug": slug,
            "views": int(totals.get("views") or 0),
            "uniqueViews": world_visitor_metrics.hll_estimate(
                registers, precision=BLOG_POST_UNIQUE_PRECISION),
            "approximateUnique": True,
            "referrers": board,
            # The rendered page draws its "Posted on" slots from here, so one
            # read serves both the reach numbers and the permalinks.
            "links": links,
            "detected": detected,
        },
        cache_control="no-store, max-age=0")


def _short_wallet(addr):
    addr = (addr or "").strip()
    if len(addr) <= 10:
        return addr or "node"
    return addr[:4] + "…" + addr[-4:]


async def _wallet_name_map(env):
    # Build wallet -> friendly node name from local nodes and federated
    # presence, so funds-received boards can label payout wallets. Best-effort.
    mapping = {}
    try:
        rows = await d1_all(env, "SELECT name, data FROM nodes")
        for row in rows:
            rec = await decrypt_row(env, row.get("data"))
            if not rec:
                continue
            wallet = (rec.get("solana") or "").strip()
            if not wallet:
                continue
            name = clean_string(row.get("name") or rec.get("name", ""), MAX_NODE_NAME)
            if name:
                mapping.setdefault(wallet, name)
    except Exception:
        pass
    try:
        fed = await d1_all(env, "SELECT wallet, name FROM federated_presence")
        for row in fed:
            wallet = (row.get("wallet") or "").strip()
            name = clean_string(row.get("name", ""), MAX_NODE_NAME)
            if wallet and name:
                mapping.setdefault(wallet, name)
    except Exception:
        pass
    return mapping


async def _funds_received_boards(env):
    out = {"mainnode": [], "contributor": [], "project": []}
    try:
        rows = await d1_all(
            env, "SELECT scope, key, name, lamports FROM funds_received "
                 "WHERE lamports > 0")
    except Exception:
        return out
    wallet_names = None
    for row in rows:
        scope = row.get("scope")
        if scope not in out:
            continue
        lamports = int(row.get("lamports") or 0)
        if lamports <= 0:
            continue
        key = row.get("key") or ""
        name = clean_string(row.get("name") or "", 120)
        if scope in ("mainnode", "contributor") and not name:
            if wallet_names is None:
                wallet_names = await _wallet_name_map(env)
            name = wallet_names.get(key) or _short_wallet(key)
        out[scope].append({"name": name or _short_wallet(key),
                           "lamports": lamports, "sol": _amount_sol(lamports)})
    for scope in out:
        out[scope].sort(key=lambda n: (-n["lamports"], n["name"]))
    return out


async def install_source(env):
    await ensure_schema(env)
    now = int(Date.now())
    # Install candidates must be able to serve the flagship over the same
    # direct-HTTPS path the clone will actually use. A control/presence socket
    # says nothing about repository-byte availability, so require a fresh,
    # signed forkmesh/forkmesh proof from a healthy non-abuse-blocked endpoint.
    endpoint_rows = await d1_all(
        env,
        """SELECT node_bi,node_name,checked_at,latency_ms
             FROM mirror_https_endpoints
            WHERE healthy=1 AND integrity='ok' AND abuse_blocked=0
              AND forkmesh_active=1 AND checked_at>=?
              AND forkmesh_verified_at>=?""",
        now - https_routing.ENDPOINT_STALE_MS,
        now - https_routing.ENDPOINT_STALE_MS,
    )
    endpoints = {
        clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower(): row
        for row in endpoint_rows or []
        if valid_node_name(
            clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower())
    }
    rows = await d1_all(
        env,
        "SELECT owner_bi, data FROM repositories",
    )

    candidates = {}
    for row in rows:
        rec = await decrypt_row(env, row.get("data"))
        if (
            not rec
            or rec.get("visibility") != "public"
            or safe_segment(rec.get("name", "")) != "forkmesh"
        ):
            continue
        owner = safe_segment(rec.get("owner", ""))
        owner_bi = row.get("owner_bi")
        endpoint = endpoints.get(owner)
        if not owner or not owner_bi or not endpoint:
            continue
        source_kind = str(rec.get("source") or "local-node").strip()
        try:
            last_sync = int(rec.get("lastSync") or 0)
        except (TypeError, ValueError):
            last_sync = 0
        priority = 2
        if source_kind == "local-node":
            priority = 0 if owner == "forkmesh" else 1
        candidates[owner_bi] = {
            "node": owner,
            "priority": priority,
            "lastSync": last_sync,
            "latencyMs": int(endpoint.get("latency_ms") or 60_000),
        }

    if not candidates:
        return json_response({"ok": False, "error": "no_online_install_source"},
                             status=503,
                             cache_control="no-store, max-age=0, must-revalidate",
                             extra_headers=EXPECTED_DEGRADED_HEADERS)

    start = now - ONLINE_HISTORY_RETAIN_MS
    uptime_rows = await d1_all(
        env,
        """SELECT node_key, SUM(node_minutes) AS total_minutes
             FROM online_hourly_nodes
             WHERE hour_ts >= ?
             GROUP BY node_key""",
        start,
    )
    totals = {r.get("node_key"): int(r.get("total_minutes") or 0)
              for r in uptime_rows}
    ranked = sorted(
        (
            {**item, "totalMinutes": totals.get(node_key, 0)}
            for node_key, item in candidates.items()
        ),
        key=lambda item: (
            item["priority"], -item["lastSync"],
            item["latencyMs"], -item["totalMinutes"], item["node"]),
    )
    best = ranked[0]
    # Health can change after selection, so hand the installer a bounded
    # failover list. "node" stays for older installers that read one value.
    node_list = [item["node"] for item in ranked[:8]]
    return json_response(
        {"ok": True, "node": best["node"], "nodes": node_list,
         "repo": "forkmesh", "totalMinutes": best["totalMinutes"]},
        cache_control="no-store, max-age=0, must-revalidate",
    )


def method_name(request):
    method = getattr(request, "method", "GET")
    return str(method).upper()


async def durable_object_request(request, target_url=None, include_body=False,
                                 body=None):
    # DurableObject.fetch may outlive the Python call frame. Passing the Python
    # Request proxy directly across that JS boundary can trip Pyodide's
    # "PyProxy when Python GIL not held" crash under load. Rebuild a JS-owned
    # Request from primitive strings/bytes for control/no-body paths, including
    # WebSocket upgrades. Repository payloads do not use Durable Objects.
    headers = {}
    for name in (
        "upgrade", "connection", "sec-websocket-version", "sec-websocket-key",
        "sec-websocket-protocol", "content-type", "content-encoding",
        "authorization", "accept", "user-agent",
    ):
        try:
            value = request.headers.get(name)
        except Exception:
            value = None
        if value:
            headers[name] = value
    init = {"method": method_name(request), "headers": headers}
    if include_body:
        # A caller that buffered the single-use body stream (to replay the
        # request on another node) passes the bytes; otherwise read them here.
        payload = bytes(await request.bytes()) if body is None else bytes(body)
        init["body"] = Uint8Array.new(_to_js(payload))
    return JsRequest.new(str(target_url or request.url), to_js(init))


# A Durable Object binding name as wrangler.toml declares it. The same grammar
# gates both discovery (which env properties may be reported) and accounting
# (which binding names may reach D1).
DURABLE_OBJECT_BINDING_RE = re.compile(r"[A-Z][A-Z0-9_]{0,63}")
# Content-free relay accounting behind the System Capacity card. A Durable
# Object counts the bytes it relays in the live instance and folds them into
# one small D1 row per binding: once on the first frame after a wake-up (an
# idle object may hibernate again immediately, losing in-memory counters),
# then at most once every five minutes or once a batch of bytes has gone by. Even a busy
# room therefore costs a handful of writes an hour.
DURABLE_OBJECT_TRAFFIC_FLUSH_MS = 5 * 60 * 1000
DURABLE_OBJECT_TRAFFIC_FLUSH_BYTES = 262_144
DURABLE_OBJECT_TRAFFIC_MAX = 9_007_199_254_740_991


def durable_object_bindings(env):
    """Every Durable Object namespace bound to this Worker, discovered live.

    The System Capacity display must not carry a hand-maintained list: a class
    bound in wrangler.toml appears here on the next deploy. Namespaces are
    duck-typed — `idFromName` plus `newUniqueId` is unique to a
    DurableObjectNamespace among D1, KV, R2, AI, and assets bindings.

    Key discovery is deliberately redundant. `Object.keys` only sees own
    enumerable properties of a JavaScript environment, so a runtime that hides
    its bindings behind a prototype, a non-enumerable descriptor, or a Python
    wrapper reported *no* Durable Objects at all and the world fell back to the
    two connections the browser can see for itself. Every source is merged and
    each candidate is still duck-typed, so a wider sweep cannot invent one.
    """
    keys = []
    for source in (
        lambda: Object.keys(env),
        lambda: Object.getOwnPropertyNames(env),
        lambda: dir(env),
    ):
        try:
            keys.extend(str(key) for key in source())
        except Exception:
            continue
    bindings = []
    for name in sorted(set(keys)):
        if not DURABLE_OBJECT_BINDING_RE.fullmatch(name):
            continue
        try:
            namespace = getattr(env, name, None)
        except Exception:
            continue
        if namespace is None:
            continue
        if not (
            hasattr(namespace, "idFromName")
            and hasattr(namespace, "newUniqueId")
        ):
            continue
        bindings.append(name)
    return bindings


def durable_object_label(binding):
    """Human display name for an auto-discovered binding (no hardcoding)."""
    words = [
        word for word in str(binding or "").split("_")
        if word and word != "FORKMESH"
    ]
    if not words:
        return str(binding or "")
    return " ".join(words).capitalize()


def durable_object_traffic_note(do, bytes_in=0, bytes_out=0, messages=0):
    """Record relayed bytes for one frame in this live Durable Object."""
    state = getattr(do, "_traffic", None)
    if not isinstance(state, dict):
        state = {
            "bytes_in": 0, "bytes_out": 0, "messages": 0, "flushed_at": 0}
        try:
            do._traffic = state
        except Exception:
            return None
    try:
        state["bytes_in"] += max(0, int(bytes_in or 0))
        state["bytes_out"] += max(0, int(bytes_out or 0))
        state["messages"] += max(0, int(messages or 0))
    except (TypeError, ValueError):
        return state
    return state


async def durable_object_traffic_flush(do, force=False):
    """Fold the pending byte counts into this binding's single D1 row."""
    if _read_only(getattr(do, "env", None)):
        return False
    state = getattr(do, "_traffic", None)
    if not isinstance(state, dict):
        return False
    pending = (
        int(state.get("bytes_in") or 0) + int(state.get("bytes_out") or 0))
    if pending <= 0 and not int(state.get("messages") or 0):
        return False
    binding = str(getattr(do, "traffic_binding", "") or "")
    if not DURABLE_OBJECT_BINDING_RE.fullmatch(binding):
        return False
    now = int(Date.now())
    if (
        not force
        and pending < DURABLE_OBJECT_TRAFFIC_FLUSH_BYTES
        and now - int(state.get("flushed_at") or 0)
            < DURABLE_OBJECT_TRAFFIC_FLUSH_MS
    ):
        return False
    bytes_in = int(state.get("bytes_in") or 0)
    bytes_out = int(state.get("bytes_out") or 0)
    messages = int(state.get("messages") or 0)
    state["bytes_in"] = 0
    state["bytes_out"] = 0
    state["messages"] = 0
    state["flushed_at"] = now
    try:
        await d1_run(
            do.env,
            "INSERT INTO durable_object_traffic "
            "(binding, bytes_in, bytes_out, messages, updated_at) "
            "VALUES (?,?,?,?,?) ON CONFLICT(binding) DO UPDATE SET "
            "bytes_in=MIN("
            "durable_object_traffic.bytes_in+excluded.bytes_in,?), "
            "bytes_out=MIN("
            "durable_object_traffic.bytes_out+excluded.bytes_out,?), "
            "messages=MIN("
            "durable_object_traffic.messages+excluded.messages,?), "
            "updated_at=excluded.updated_at",
            binding, bytes_in, bytes_out, messages, now,
            DURABLE_OBJECT_TRAFFIC_MAX,
            DURABLE_OBJECT_TRAFFIC_MAX,
            DURABLE_OBJECT_TRAFFIC_MAX,
        )
    except Exception:
        # Capacity counters are optional telemetry. A migrating or overloaded
        # database must never break a live relay; the window is simply lost.
        return False
    return True


def world_request_country(request):
    """Trusted coarse country from request.cf, with a local-dev fallback."""
    try:
        cf = getattr(request, "cf", None)
    except Exception:
        cf = None
    if cf is not None:
        raw_country = None
        if isinstance(cf, dict):
            raw_country = cf.get("country")
        else:
            try:
                raw_country = getattr(cf, "country", None)
            except Exception:
                raw_country = None
            if raw_country is None:
                try:
                    raw_country = cf.get("country")
                except Exception:
                    raw_country = None
        if raw_country is not None:
            return world_protocol.approximate_country_code(raw_country)
    # pywrangler/local test requests may not expose request.cf. Cloudflare
    # overwrites CF-IPCountry at the edge when IP Geolocation is enabled.
    try:
        raw_country = request.headers.get("cf-ipcountry") or ""
    except Exception:
        raw_country = ""
    return world_protocol.approximate_country_code(raw_country)


def world_websocket_origin_allowed(request, env=None):
    if env is not None:
        return _request_origin_allowed(env, request)
    try:
        request_url = urlparse(request.url)
        origin_url = urlparse(request.headers.get("origin") or "")
        request_port = request_url.port or (
            443 if request_url.scheme == "https" else 80)
        origin_port = origin_url.port or (
            443 if origin_url.scheme == "https" else 80)
    except Exception:
        return False
    return bool(
        origin_url.scheme in ("http", "https")
        and origin_url.username is None
        and origin_url.password is None
        and origin_url.path in ("", "/")
        and not origin_url.query
        and not origin_url.fragment
        and origin_url.scheme == request_url.scheme
        and str(origin_url.hostname or "").lower().rstrip(".")
            == str(request_url.hostname or "").lower().rstrip(".")
        and origin_port == request_port
    )


WORLD_TICKET_TTL_MS = 60 * 1000
