BLOG_RSS_CACHE_KEY = "https://forkmesh.internal/blog/rss.xml"
# The blog index is a build artifact, so the feed only changes on deploy; half
# an hour at the edge keeps subscriber polling (and the world banner's own
# ten-minute refresh) off the origin without making a new post wait.
BLOG_RSS_TTL = 1800


async def _blog_feed_document(env, request):
    """Build the blog's RSS document from our own static index.

    Reads blog.html through env.ASSETS (no external fetch, no D1) and returns
    "" when the asset is missing or parses to nothing, so callers can fall
    back instead of publishing an empty feed.
    """
    origin = urlparse(request.url)
    resp = await env.ASSETS.fetch(
        origin.scheme + "://" + origin.netloc + "/"
        + blog_feed.BLOG_INDEX_ASSET)
    if int(getattr(resp, "status", 0)) != 200:
        return ""
    return blog_feed.build_feed(str(await resp.text()), int(Date.now()))


async def _blog_feed_published_document(env, request):
    """The feed as published, reusing the edge-cached copy while it is warm.

    The world banner reads the same document subscribers get, so a warm cache
    spares it the parse-and-render pass entirely.
    """
    cached = await edge_cache_match(BLOG_RSS_CACHE_KEY)
    if cached is not None:
        try:
            document = str(await cached.text())
        except Exception:
            document = ""
        if document:
            return document
    return await _blog_feed_document(env, request)


async def _blog_post_distribution(env, request, post):
    """Read one same-origin post's social permalink slots.

    The checked-in ``data-*`` attributes are the default; a permalink an
    administrator saved from the rendered page wins over them, exactly as it
    does on the post itself. Without that overlay a post announced after the
    deploy still read as unannounced here.
    """
    try:
        path = urlparse(str((post or {}).get("url") or "")).path
        match = re.fullmatch(r"/blog/([a-z0-9-]{1,100})/?", path)
        if not match:
            return {"known": False, "networks": []}
        slug = match.group(1)
        origin = urlparse(request.url)
        asset_url = (
            origin.scheme + "://" + origin.netloc + "/blog/"
            + slug + "/index.html"
        )
        response = await env.ASSETS.fetch(asset_url)
        distribution = (
            world_social_feeds.normalize_blog_distribution(
                str(await response.text()))
            if int(getattr(response, "status", 0)) == 200
            else {"known": False, "networks": []}
        )
        try:
            stored = await blog_post_links(env, slug)
        except Exception:
            stored = {}
        return world_social_feeds.apply_blog_distribution_overrides(
            distribution, stored)
    except Exception:
        return {"known": False, "networks": []}


async def _blog_post_reach_summary(env, post):
    """Aggregate reach fields already available on each public blog post."""
    try:
        path = urlparse(str((post or {}).get("url") or "")).path
        match = re.fullmatch(r"/blog/([a-z0-9-]{1,100})/?", path)
        if not match:
            return {}
        slug = match.group(1)
        totals = await d1_first(
            env,
            "SELECT views FROM blog_post_metrics WHERE slug=?",
            slug) or {}
        registers = await d1_all(
            env,
            "SELECT register_id,rank FROM blog_post_unique_hll WHERE slug=?",
            slug)
        referrers = await d1_first(
            env,
            "SELECT COUNT(*) AS sites,SUM(visits) AS visits "
            "FROM blog_post_referrers WHERE slug=? AND visits>0",
            slug) or {}
        return {
            "views": int(totals.get("views") or 0),
            "uniqueViews": world_visitor_metrics.hll_estimate(
                registers, precision=BLOG_POST_UNIQUE_PRECISION),
            "approximateUnique": True,
            "referrerSites": int(referrers.get("sites") or 0),
            "referrerVisits": int(referrers.get("visits") or 0),
        }
    except Exception:
        return {}


async def blog_rss_handler(env, request):
    """GET /blog/rss.xml — the public feed for the blog.

    Worker-owned (see run_worker_first in wrangler.toml) because the assets
    router would otherwise treat rss.xml as a post slug and redirect it.
    """
    if method_name(request) not in ("GET", "HEAD"):
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            extra_headers={"allow": "GET, HEAD"})
    cached = await edge_cache_match(BLOG_RSS_CACHE_KEY)
    if cached is not None:
        return cached
    try:
        document = await _blog_feed_document(env, request)
    except Exception:
        document = ""
    if not document:
        return json_response({"error": "blog_feed_unavailable"}, status=503)
    resp = Response(document, status=200, headers={
        "content-type": "application/rss+xml; charset=utf-8",
        "cache-control": "public, max-age=%d" % BLOG_RSS_TTL,
    })
    await edge_cache_put(BLOG_RSS_CACHE_KEY, resp)
    return resp


def _world_satellite_refresh_error_code(value, fallback="refresh_failed"):
    code = str(getattr(value, "code", "") or value or fallback).lower()
    code = re.sub(r"[^a-z0-9_:-]+", "_", code).strip("_")
    return (code or fallback)[:80]


async def _world_satellite_refresh_failure(env, now, status, error):
    """Record one bounded refresh outcome without touching last-good data."""
    try:
        safe_status = max(0, min(599, int(status or 0)))
    except (TypeError, ValueError, OverflowError):
        safe_status = 0
    code = _world_satellite_refresh_error_code(error)
    try:
        await d1_run(
            env,
            """UPDATE world_satellite_snapshot
                  SET last_attempt_at=?,last_status=?,last_error=?
                WHERE snapshot_id=1""",
            int(now), safe_status, code,
        )
    except Exception:
        # An absent row is normal before the first successful refresh. A D1
        # bookkeeping failure must not turn an upstream outage into a cron
        # exception storm.
        pass
    return {
        "ok": False,
        "status": "upstream_error",
        "upstreamStatus": safe_status,
        "error": code,
    }


async def refresh_world_satellite_snapshot(env, now_ms=None):
    """Cron-only fixed-source refresh of the public VISUAL OMM snapshot.

    The caller owns the three-hour schedule; the additional two-hour D1 gate
    protects manual retries or overlapping scheduled invocations from violating
    CelesTrak's once-per-update usage policy.
    """
    await ensure_schema(env)
    now = int(now_ms if now_ms is not None else Date.now())
    row = await d1_first(
        env,
        """SELECT fetched_at,last_attempt_at
             FROM world_satellite_snapshot WHERE snapshot_id=1""",
    )
    last_attempt = int((row or {}).get("last_attempt_at") or 0)
    if last_attempt and now - last_attempt < WORLD_SATELLITE_REFRESH_MIN_MS:
        return {
            "ok": True,
            "status": "fresh",
            "fetchedAt": int((row or {}).get("fetched_at") or 0),
        }

    # Keep the valid data/digest untouched while the request is in flight.
    if row:
        await d1_run(
            env,
            """UPDATE world_satellite_snapshot
                  SET last_attempt_at=?,last_status=0,last_error=''
                WHERE snapshot_id=1""",
            now,
        )
    try:
        upstream = await js_fetch_with_timeout(
            world_satellites.CELESTRAK_VISUAL_OMM_URL,
            {
                "method": "GET",
                "headers": {"accept": "application/json"},
                # CelesTrak asks machine clients to stop on a 301 rather than
                # silently following an obsolete or incorrect URL.
                "redirect": "manual",
            },
            WORLD_SATELLITE_FETCH_TIMEOUT_SECONDS,
        )
    except Exception:
        return await _world_satellite_refresh_failure(
            env, now, 0, "fetch_failed")

    try:
        status = int(getattr(upstream, "status", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        status = 0
    if status != 200:
        return await _world_satellite_refresh_failure(
            env, now, status, "upstream_http_status")

    try:
        announced = int(upstream.headers.get("content-length") or 0)
    except (AttributeError, TypeError, ValueError, OverflowError):
        announced = 0
    if announced > world_satellites.MAX_CELESTRAK_RESPONSE_BYTES:
        return await _world_satellite_refresh_failure(
            env, now, 502, "celestrak_body_too_large")
    try:
        raw = str(await upstream.text())
        payload = world_satellites.build_snapshot_from_json(raw, now)
        document, digest = world_satellites.serialize_snapshot_payload(
            payload)
    except world_satellites.SatelliteDataError as error:
        return await _world_satellite_refresh_failure(
            env, now, 502, error)
    except Exception:
        return await _world_satellite_refresh_failure(
            env, now, 502, "upstream_read_failed")

    await d1_run(
        env,
        """INSERT INTO world_satellite_snapshot
               (snapshot_id,data,digest,fetched_at,source_epoch,
                last_attempt_at,last_status,last_error)
             VALUES (1,?,?,?,?,?,200,'')
             ON CONFLICT(snapshot_id) DO UPDATE SET
               data=excluded.data,
               digest=excluded.digest,
               fetched_at=excluded.fetched_at,
               source_epoch=excluded.source_epoch,
               last_attempt_at=excluded.last_attempt_at,
               last_status=200,
               last_error=''""",
        document,
        digest,
        now,
        payload["sourceEpoch"],
        now,
    )
    await edge_cache_delete(WORLD_SATELLITE_CACHE_KEY)
    return {
        "ok": True,
        "status": "updated",
        "fetchedAt": now,
        "recordCount": payload["recordCount"],
        "digest": digest,
    }


async def _chat_channel_passphrase(env, channel_id, key_version):
    secret = (
        _require_data_secret(env)
        + ":private-chat-channel-v1:"
        + str(channel_id)
        + ":"
        + str(int(key_version))
    )
    digest = await js_crypto.subtle.digest(
        "SHA-256", Uint8Array.new(_to_js(bytes(secret.encode()))))
    return bytes(Uint8Array.new(digest).to_py()).hex()


async def _chat_encrypted_envelope(room, passphrase, plain):
    """Encrypt one relay-originated message with the normal room format."""
    salt_digest = await js_crypto.subtle.digest(
        "SHA-256", Uint8Array.new(_to_js(bytes(
            ("ForkMesh room:" + room).encode()))))
    salt = bytes(Uint8Array.new(salt_digest).to_py())[:16]
    base_key = await js_crypto.subtle.importKey(
        "raw",
        Uint8Array.new(_to_js(bytes(passphrase.encode()))),
        to_js({"name": "PBKDF2"}),
        False,
        _to_js(["deriveKey"]),
    )
    key = await js_crypto.subtle.deriveKey(
        to_js({
            "name": "PBKDF2",
            "salt": Uint8Array.new(_to_js(bytes(salt))),
            "iterations": 210000,
            "hash": "SHA-256",
        }),
        base_key,
        to_js({"name": "AES-GCM", "length": 256}),
        False,
        _to_js(["encrypt"]),
    )
    nonce = js_crypto.getRandomValues(Uint8Array.new(12))
    plaintext = json.dumps(
        plain, separators=(",", ":"), ensure_ascii=False).encode()
    encrypted = await js_crypto.subtle.encrypt(
        to_js({"name": "AES-GCM", "iv": nonce, "tagLength": 128}),
        key,
        Uint8Array.new(_to_js(bytes(plaintext))),
    )
    combined = bytes(Uint8Array.new(encrypted).to_py())
    return {
        "kind": "cipher",
        "v": 1,
        "nonce": base64.b64encode(bytes(nonce.to_py())).decode(),
        "tag": base64.b64encode(combined[-16:]).decode(),
        "body": base64.b64encode(combined[:-16]).decode(),
        "persist": True,
    }


async def _chat_channel_webhook_envelope(
        env, channel_id, key_version, plain):
    """Encrypt one relay-originated webhook with the browser room format."""
    room = (
        "chat-channel:" + str(channel_id) + ":v" + str(int(key_version)))
    passphrase = await _chat_channel_passphrase(
        env, channel_id, key_version)
    return await _chat_encrypted_envelope(room, passphrase, plain)


async def _chat_direct_passphrase(env, conversation_id, key_version):
    secret = (
        _require_data_secret(env)
        + ":chat-direct-passphrase-v1:"
        + str(conversation_id)
        + ":v"
        + str(int(key_version))
    )
    digest = await js_crypto.subtle.digest(
        "SHA-256", Uint8Array.new(_to_js(bytes(secret.encode()))))
    return bytes(Uint8Array.new(digest).to_py()).hex()


async def _chat_direct_message_retained(
        env, conversation_id, account_bi, retained_at, ref="",
        key_version=0, frame=""):
    await _contribution_run_batch(env, [
        (
            "UPDATE chat_direct_conversations "
            "SET updated_at=?,message_count=message_count+1 "
            "WHERE conversation_id=?",
            (retained_at, conversation_id),
        ),
        (
            "UPDATE chat_direct_participants "
            "SET last_read_count=(SELECT message_count "
            "FROM chat_direct_conversations WHERE conversation_id=?) "
            "WHERE conversation_id=? AND participant_bi=?",
            (conversation_id, conversation_id, account_bi),
        ),
    ])
    # That first UPDATE is exactly what raises the other participant's
    # unreadCount, so push them a hint now. Their conversation list is read
    # once when the chat page opens and never on a timer, so a reader who is
    # not sitting in this particular conversation would otherwise not see the
    # count move until they reloaded. (A reader who *is* sitting in it already
    # got the message over this room's socket; the push is then redundant, and
    # notify_account_event's coalescing window absorbs it.)
    recipient = await _chat_direct_message_recipient(
        env, conversation_id, account_bi)
    if recipient:
        await notify_account_event(
            env, recipient, "direct-messages",
            _apns_module().direct_message_alert(
                conversation_id=conversation_id, ref=ref,
                key_version=key_version, frame=frame))


# conversation_id -> {sender account_bi: (peer name, sender name)}. A direct
# conversation has
# exactly two participants and they never change, so this is immutable for the
# life of the row and worth memoizing per isolate: the alternative is a D1 read
# plus a row decrypt plus two blind indexes on every retained message.
_CHAT_DIRECT_PEER_MEMO = {}
CHAT_DIRECT_PEER_MEMO_MAX = 256


async def _chat_direct_message_recipient(env, conversation_id, sender_bi):
    """The participant of a direct conversation who is not the sender."""
    peer, _sender = await _chat_direct_message_parties(
        env, conversation_id, sender_bi)
    return peer


async def _chat_direct_message_parties(env, conversation_id, sender_bi):
    """(recipient, sender) names of a direct conversation, "" when unknown."""
    memo_key = str(conversation_id) + "\n" + str(sender_bi)
    if memo_key in _CHAT_DIRECT_PEER_MEMO:
        return _CHAT_DIRECT_PEER_MEMO[memo_key]
    peer = ""
    sender = ""
    try:
        row = await d1_first(
            env,
            "SELECT data FROM chat_direct_conversations "
            "WHERE conversation_id=?",
            conversation_id,
        )
        record = await decrypt_row(env, (row or {}).get("data", ""))
        participants = (record or {}).get("participants")
        if not isinstance(participants, list):
            return "", ""
        for value in participants:
            name = clean_string(value, MAX_NODE_NAME).strip().lower()
            if not valid_node_name(name):
                continue
            if await blind_index(env, name) != sender_bi:
                peer = peer or name
            else:
                sender = sender or name
    except Exception:
        # A transient read failure must not be memoized as "no recipient".
        return "", ""
    if len(_CHAT_DIRECT_PEER_MEMO) >= CHAT_DIRECT_PEER_MEMO_MAX:
        _CHAT_DIRECT_PEER_MEMO.clear()
    _CHAT_DIRECT_PEER_MEMO[memo_key] = (peer, sender)
    return peer, sender


def _desktop_office_session_id(account_bi, actor):
    """Stable opaque Office session id for an authenticated desktop key."""
    material = (
        "forkmesh-desktop-office-session-v1\n"
        + str(account_bi or "")
        + "\n"
        + str(actor or "").strip().lower()
    ).encode()
    return "desktop_" + hashlib.sha256(material).hexdigest()[:32]


def _chat_channel_ticket(env, channel_id, key_version, account_bi):
    expires = int(Date.now()) + CHAT_CHANNEL_TICKET_TTL_MS
    canonical = ".".join((
        "v1",
        str(channel_id),
        str(int(key_version)),
        str(account_bi),
        str(expires),
    ))
    signature = hmac.new(
        (_require_data_secret(env) + ":chat-channel-ticket-v1").encode(),
        canonical.encode(),
        "sha256",
    ).hexdigest()
    return canonical + "." + signature


def _chat_channel_ticket_claims(env, token):
    parts = str(token or "").split(".")
    if len(parts) != 6:
        return None
    version_tag, channel_id, version_raw, account_bi, expires_raw, signature = (
        parts
    )
    if version_tag != "v1" or not re.fullmatch(r"[0-9a-f]{32}", channel_id):
        return None
    if not re.fullmatch(r"[0-9a-f]{64}", account_bi):
        return None
    try:
        key_version = int(version_raw)
        expires = int(expires_raw)
    except (TypeError, ValueError):
        return None
    now = int(Date.now())
    if (
        key_version < 1
        or expires <= now
        or expires - now > CHAT_CHANNEL_TICKET_TTL_MS
    ):
        return None
    canonical = ".".join(parts[:5])
    expected = hmac.new(
        (_require_data_secret(env) + ":chat-channel-ticket-v1").encode(),
        canonical.encode(),
        "sha256",
    ).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return None
    return {
        "channel_id": channel_id,
        "key_version": key_version,
        "account_bi": account_bi,
    }


async def _chat_channel_socket_handler(env, request, channel_id):
    if (
        method_name(request) != "GET"
        or (request.headers.get("upgrade") or "").lower() != "websocket"
    ):
        return _private_replica_not_found()
    url = urlparse(request.url)
    ticket_values = parse_qs(
        url.query, keep_blank_values=False).get("ticket") or []
    claims = (
        _chat_channel_ticket_claims(env, ticket_values[0])
        if len(ticket_values) == 1 else None
    )
    if not claims or claims["channel_id"] != channel_id:
        return _private_replica_not_found()
    try:
        await ensure_schema(env)
        channel = await d1_first(
            env,
            "SELECT data,created_by_bi,key_version FROM chat_channels "
            "WHERE channel_id=?",
            channel_id,
        )
        if (
            not channel
            or int(channel.get("key_version") or 0)
                != int(claims["key_version"])
        ):
            return _private_replica_not_found()
        channel_record = await decrypt_row(env, channel.get("data"))
        if not isinstance(channel_record, dict):
            return _private_replica_not_found()
        visibility = (
            "public"
            if channel_record.get("visibility") == "public"
            else "private"
        )
        account = await d1_first(
            env,
            "SELECT data FROM users WHERE user_bi=?",
            claims["account_bi"],
        )
        if not account:
            return _private_replica_not_found()
        account_record = await decrypt_row(env, account.get("data"))
        if (
            not account_record
            or account_record.get("status") != "active"
            or _account_kind(account_record) != "user"
        ):
            return _private_replica_not_found()
        is_creator = hmac.compare_digest(
            str(channel.get("created_by_bi") or ""),
            str(claims["account_bi"]),
        )
        if channel_record.get("kind") == "notices" and not is_creator:
            return _private_replica_not_found()
        if not is_creator and visibility != "public":
            membership = await d1_first(
                env,
                "SELECT 1 AS allowed FROM chat_channel_members "
                "WHERE channel_id=? AND member_bi=?",
                channel_id,
                claims["account_bi"],
            )
            if not membership:
                return _private_replica_not_found()
    except Exception:
        return _private_replica_not_found()

    room_name = (
        "chat-channel:" + channel_id + ":v" + str(claims["key_version"])
    )
    room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(room_name)
    target_url = (
        url.scheme + "://" + url.netloc + "/api/chat/channels/"
        + channel_id + "/v" + str(claims["key_version"])
        + "/ws?account=" + quote(claims["account_bi"], safe="")
    )
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_MAINNODE_ROOM.get(room_id)
        try:
            return await room_object.fetch(
                await durable_object_request(request, target_url=target_url))
        except Exception as error:
            last_error = error
    await log_durable_object_abort(env, request, url.path, last_error)
    return json_response(
        {"error": "unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS)


