async def _org_floor_team_rows(env, org_bi, floor_id, member_bi=""):
    """Org members sitting on any team this office maps to ``floor_id``.

    One definition of "the right team" for every surface behind a floor. The
    elevator already admits an org whose Engineering team is called "platform"
    or "developers" (OFFICE_FLOOR_TEAM_ALIASES), so the work behind that floor —
    the agent workspace and the private task pings — must admit exactly the same
    people. Gates that matched the single slug ``engineering`` instead refused
    members who were demonstrably on the right team (adhoc #1668).

    Pass ``member_bi`` to ask about one account; omit it for the whole floor's
    roster. Membership is re-checked here, so a stale team row for someone the
    org has since removed never counts.
    """
    aliases = OFFICE_FLOOR_TEAM_ALIASES.get(str(floor_id or ""))
    if not aliases:
        return []
    arguments = [str(org_bi or "")]
    member_clause = ""
    if member_bi:
        member_clause = "AND tm.member_bi=? "
        arguments.append(str(member_bi))
    rows = await d1_all(
        env,
        "SELECT DISTINCT tm.name AS name,tm.team AS team "
        "FROM org_team_members tm "
        "INNER JOIN org_members om "
        "ON om.org_bi=tm.org_bi AND om.member_bi=tm.member_bi "
        "WHERE tm.org_bi=? " + member_clause
        + "AND om.role IN ('owner','admin','maintainer','member','auditor') "
        "ORDER BY tm.name COLLATE NOCASE LIMIT 1000",
        *arguments)
    return [
        row for row in rows or []
        if _office_team_slug((row or {}).get("team")) in aliases
    ]


async def _forward_office_socket(env, request, claims, room_name, path):
    room_id = env.FORKMESH_OFFICE_ROOM.idFromName(room_name)
    source_url = urlparse(request.url)
    target_url = source_url.scheme + "://" + source_url.netloc + path
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_OFFICE_ROOM.get(room_id)
        try:
            return await room_object.fetch(
                await office_durable_object_request(
                    request, claims, target_url=target_url))
        except Exception as error:
            last_error = error
    await log_durable_object_abort(
        env, request, urlparse(request.url).path, last_error)
    return json_response(
        {"error": "unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS)


async def _revoke_chat_channel_room(env, channel_id, key_version):
    room_name = (
        "chat-channel:" + str(channel_id) + ":v" + str(int(key_version))
    )
    room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(room_name)
    target_url = (
        "https://forkmesh.internal/api/chat/channels/" + str(channel_id)
        + "/v" + str(int(key_version)) + "/revoke"
    )
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_MAINNODE_ROOM.get(room_id)
        try:
            request = JsRequest.new(
                target_url, to_js({"method": "POST"}))
            response = await room_object.fetch(request)
            if int(getattr(response, "status", 200) or 200) < 400:
                return
        except Exception as error:
            last_error = error
    if last_error is not None:
        raise last_error
    raise RuntimeError("chat_channel_revoke_failed")


