class _WorldCommunityRuntime:
    """Narrow adapter from isolated world APIs to established Worker helpers."""

    def __init__(self, env, request=None):
        self.env = env
        self.request = request

    def method(self):
        return method_name(self.request) if self.request is not None else "GET"

    async def search_accounts(self, query, limit):
        value = clean_string(query or "", MAX_NODE_NAME).strip().lower()
        if not value:
            return []
        escaped = (
            value.replace("\\", "\\\\")
            .replace("%", "\\%")
            .replace("_", "\\_")
        )
        prefix = escaped + "%"
        contains = "%" + escaped + "%"
        rows = await d1_all(
            self.env,
            "SELECT data,username FROM users "
            "WHERE username LIKE ? ESCAPE '\\' "
            "ORDER BY CASE WHEN username=? THEN 0 "
            "WHEN username LIKE ? ESCAPE '\\' THEN 1 ELSE 2 END,"
            "username COLLATE NOCASE LIMIT ?",
            contains,
            value,
            prefix,
            max(int(limit) * 5, int(limit)),
        )
        names = []
        for row in rows or []:
            try:
                record = await decrypt_row(self.env, row.get("data"))
            except Exception:
                record = None
            name = clean_string(
                (record or {}).get("name") or row.get("username") or "",
                MAX_NODE_NAME,
            ).strip().lower()
            if (
                record
                and record.get("status") == "active"
                and _account_kind(record) == "user"
                and valid_node_name(name)
                and name not in names
            ):
                names.append(name)
                if len(names) >= int(limit):
                    break
        return names

    def same_origin(self):
        return bool(
            self.request is not None
            and _request_origin_allowed(self.env, self.request)
        )

    def country(self):
        """Approximate two-letter country for this request, or "" if unknown.

        The same coarse edge value a member's world flag uses: no address,
        city, coordinate, or header text reaches the caller, and a cron run
        with no request simply has no country.
        """
        if self.request is None:
            return ""
        return world_request_country(self.request)

    def now(self):
        return int(Date.now())

    async def notify_account(self, owner, topic, started_by=""):
        """Tell one account's clients that something of theirs changed.

        Payload-free, best-effort; see notify_account_event. Chat surfaces read
        their channel and conversation lists once when the page opens, so this
        is how a list that changed for somebody else's reason reaches them.
        `started_by` is who opened a new direct conversation; the phone banner
        does not name them (docs/app/chat-protocol-v3.md, "Push
        notifications").
        """
        push_alert = None
        if topic == "direct-messages":
            push_alert = _apns_module().direct_message_alert(started=True)
        await notify_account_event(self.env, owner, topic, push_alert)

    def new_id(self):
        # The random id contains no account, address, time, path, or provider
        # information and is safe to use as the public resource identifier.
        return _ap_uuid()

    def instance_id(self):
        """Stable public instance identifier with no account/device material."""
        base = str(getattr(self.env, "PUBLIC_BASE_URL", "") or "").strip()
        try:
            host = str(urlparse(base).hostname or "").strip().lower()
        except Exception:
            host = ""
        if host:
            return host[:253]
        label = clean_string(
            getattr(self.env, "NODE_NAME", "") or "", MAX_NODE_NAME
        ).strip().lower()
        return label or "forkmesh.com"

    def public_origin(self):
        if self.request is not None:
            return _ap_origin(self.env, self.request)
        configured = str(
            getattr(self.env, "PUBLIC_BASE_URL", "") or ""
        ).strip().rstrip("/")
        return configured or "https://forkmesh.com"

    def query_params(self):
        if self.request is None:
            return {}
        values = parse_qs(urlparse(self.request.url).query)
        return {
            str(key): str(items[0])
            for key, items in values.items()
            if isinstance(items, list) and items
        }

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        return json_response(
            data,
            status=status,
            cache_control=cache_control,
            extra_headers=extra_headers,
        )

    async def ensure_schema(self):
        await ensure_schema(self.env)

    async def json_body(self, limit):
        """Read one bounded JSON object; an empty mutation body becomes {}."""
        if self.request is None:
            return None, "invalid_json"
        try:
            raw_length = self.request.headers.get("content-length") or ""
            if raw_length and int(raw_length) > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = await self.request.text()
        except Exception:
            return None, "invalid_json"
        if len(str(raw or "").encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        if not str(raw or "").strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        return await _account_session_record(
            self.env, self.request, data if isinstance(data, dict) else {})

    async def is_admin(self, name):
        return await _is_admin(self.env, name)

    async def account(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return "", ""
        account_bi, rec = await _account_row(self.env, name)
        if (
            not rec
            or rec.get("status") != "active"
            or _account_kind(rec) != "user"
        ):
            return "", ""
        return account_bi, clean_string(
            rec.get("name") or name, MAX_NODE_NAME).strip().lower()

    async def blind(self, value):
        return await blind_index(self.env, str(value or ""))

    async def seal(self, value):
        return await encrypt_row(self.env, value)

    async def open(self, value):
        return await decrypt_row(self.env, value)

    async def repository_access(self, owner, repo, _actor):
        # Named public repository reads are available to signed-in
        # accounts. Private/missing names fail closed and require the same
        # owner-session authorization as every other named owner surface.
        _repo_bi, row = await _security_scan_repository_row(
            self.env, owner, repo)
        if not row:
            return False
        if not await _repo_is_private(self.env, owner, repo):
            return True
        ok, _response = await _authorize_owner_account(
            self.env, owner, {}, self.request, allow_admin=False)
        return bool(ok)

    async def authorize_repository_owner(self, owner, data=None):
        account_bi, rec = await _account_session_record(
            self.env,
            self.request,
            data if isinstance(data, dict) else {},
        )
        actor = clean_string(
            (rec or {}).get("name") or "", MAX_NODE_NAME
        ).strip().lower()
        if (
            not account_bi
            or not actor
            or not await _account_owns_node(self.env, actor, owner)
        ):
            return "", ""
        return account_bi, actor

    async def authorize_owner_node(self, owner):
        return bool(
            self.request is not None
            and await _authorize_owner(self.env, self.request, owner)
        )

    async def enqueue_issue(
        self, owner, repo, title, body, requester, mention_id, remote_url
    ):
        provenance = (
            "\n\nReviewed public fediverse source: " + str(remote_url)
            if remote_url else ""
        )
        return await _forkbot_enqueue_issue(
            self.env,
            owner,
            repo,
            title,
            str(body).rstrip() + provenance,
            requester,
            source="fediverse-review",
            labels=["fediverse", "manually-reviewed"],
            federated_mention_id=mention_id,
            federated_remote_url=remote_url,
        )

    async def publish_followup(self, mention_id, record, message, number):
        remote = {
            "actor_id": record.get("actorUrl", ""),
            "url": record.get("actorUrl", ""),
            "handle": record.get("author", ""),
            "inbox": record.get("inbox", ""),
            "shared_inbox": record.get("sharedInbox", ""),
        }
        note = {
            "id": record.get("remoteId", ""),
            "url": record.get("remoteUrl", ""),
        }
        return bool(await _ap_send_mention_reply(
            self.env,
            self.request,
            record.get("actorOwner", ""),
            record.get("repo", ""),
            remote,
            note,
            message,
            number,
            dedupe_id=mention_id,
            object_uuid=mention_id,
        ))

    async def audit(self, actor, action, target_type="", target="",
                    outcome="success", details=None):
        await _audit_sensitive_action(
            self.env,
            actor,
            action,
            target_type,
            target,
            outcome=outcome,
            details=details,
        )

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)

    async def batch(self, statements):
        return await _contribution_run_batch(self.env, statements)


async def _chat_channel_deliver(env, channel_id, key_version, plain):
    envelope = await _chat_channel_webhook_envelope(
        env, channel_id, key_version, plain)
    body = json.dumps(envelope, separators=(",", ":"))
    signature = hmac.new(
        (_require_data_secret(env)
         + ":chat-webhook-delivery-v1").encode(),
        body.encode(),
        "sha256",
    ).hexdigest()
    room_name = (
        "chat-channel:" + str(channel_id)
        + ":v" + str(int(key_version)))
    room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(room_name)
    target_url = (
        "https://forkmesh.internal/api/chat/channels/"
        + str(channel_id) + "/v" + str(int(key_version)) + "/webhook")
    request = JsRequest.new(target_url, to_js({
        "method": "POST",
        "headers": {
            "content-type": "application/json",
            "x-forkmesh-chat-webhook": signature,
        },
        "body": body,
    }))
    response = await env.FORKMESH_MAINNODE_ROOM.get(room_id).fetch(request)
    if int(getattr(response, "status", 500) or 500) >= 400:
        raise RuntimeError("chat_webhook_delivery_failed")


class _ChatChannelsRuntime(_WorldCommunityRuntime):
    async def ensure_schema(self):
        await super().ensure_schema()
        await chat_channels_api.ensure_everyone_channels(self)

    async def everyone_member_count(self):
        return await _public_member_count(self.env)

    async def everyone_members(self):
        payload = await _users_directory_public_payload(self.env)
        members = []
        seen = set()
        for user in (payload or {}).get("users") or []:
            name = clean_string(
                (user or {}).get("name") or "", MAX_NODE_NAME).strip().lower()
            if not valid_node_name(name) or name in seen:
                continue
            seen.add(name)
            members.append({
                "username": name,
                "joinedAt": int((user or {}).get("createdAt") or 0),
            })
        members.sort(key=lambda member: member["username"])
        return members

    def new_webhook_token(self):
        return bytes(
            js_crypto.getRandomValues(Uint8Array.new(32)).to_py()).hex()

    def webhook_url(self, token):
        return self.public_origin() + "/api/chat/webhooks/" + str(token)

    def invite_url(self, token):
        return self.public_origin() + "/chat#invite=" + str(token)

    async def session(self, data=None):
        account_bi, record = await super().session(data)
        if account_bi and record:
            return account_bi, record
        # Desktop clients authenticate with their account key, not a session
        # token, so the World office's channel API also accepts exact signed
        # Qt proofs for its reads and manager-authorized topic mutation.
        return await _chat_channel_signed_session(
            self.env, self.request, data if isinstance(data, dict) else None)

    async def room_access(self, channel_id, key_version, account_bi, actor):
        room = (
            "chat-channel:" + str(channel_id) + ":v" + str(int(key_version))
        )
        ticket = _chat_channel_ticket(
            self.env, channel_id, key_version, account_bi)
        # Browser requests carry a revocable account-session id. The desktop
        # client authenticates this read with its account key instead, so give
        # that already-authorized path a stable opaque session id rather than
        # passing an empty value into _office_meeting_ticket (which rejects it
        # and previously escaped as Cloudflare Error 1101).
        session_id = (
            _request_account_session_id(self.request)
            or _desktop_office_session_id(account_bi, actor)
        )
        meeting_ticket = _office_meeting_ticket(
            self.env, channel_id, key_version, account_bi, actor, session_id)
        return {
            "room": room,
            "passphrase": await _chat_channel_passphrase(
                self.env, channel_id, key_version),
            "webSocketUrl": (
                "/api/chat/channels/" + str(channel_id) + "/ws?ticket="
                + quote(ticket, safe="")
            ),
            "meetingWebSocketUrl": (
                "/api/world/office/channels/" + str(channel_id)
                + "/ws?ticket=" + quote(meeting_ticket, safe="")
            ),
        }

    async def revoke_room(self, channel_id, key_version):
        await _revoke_chat_channel_room(
            self.env, channel_id, key_version)
        await _revoke_office_channel_room(
            self.env, channel_id, key_version)

    async def channel_passphrase(self, channel_id, key_version):
        return await _chat_channel_passphrase(
            self.env, channel_id, key_version)

    async def history(self, channel_id, key_version, since_ts=0):
        return await chat_history_since(
            self.env,
            "chat-channel:" + str(channel_id) + ":v" + str(int(key_version)),
            since_ts,
        )

    async def deliver_webhook(self, channel_id, key_version, plain):
        await _chat_channel_deliver(self.env, channel_id, key_version, plain)

    async def notify_webhook(self, recipient, channel, webhook, text,
                             channel_id, message_id):
        try:
            await enqueue_notification(
                self.env,
                recipient,
                "chat_webhook",
                str(webhook) + " posted in #" + str(channel),
                body=str(text),
                href="/chat",
                source="chat_webhook",
                dedupe=(
                    "chat-webhook:" + str(channel_id) + ":"
                    + str(message_id)),
                meta={"channelId": str(channel_id)},
            )
        except Exception:
            # The accepted chat message is durable. A bell write is useful but
            # must not invite webhook senders to retry and duplicate it.
            pass

    async def public_webhook_recipients(self):
        # A public channel is discoverable by every active user and has no
        # membership rows, so its notification audience is the active user
        # directory. Bound the scan to the same audience ceiling as a private
        # channel to keep one incoming request's fan-out finite.
        rows = await d1_all(
            self.env,
            "SELECT data,username FROM users ORDER BY username LIMIT ?",
            chat_channels_api.MAX_CHANNEL_MEMBERS,
        )
        recipients = []
        for row in rows or []:
            record = await decrypt_row(self.env, row.get("data"))
            name = clean_string(
                (record or {}).get("name") or row.get("username") or "",
                MAX_NODE_NAME,
            ).strip().lower()
            if (
                record
                and record.get("status") == "active"
                and _account_kind(record) == "user"
                and valid_node_name(name)
            ):
                recipients.append(name)
        return recipients


