async def organization_tasks_handler(env, request, path):
    bot_context = None
    authorization = str(
        request.headers.get("authorization") or ""
    ).strip()
    if authorization.lower().startswith("bearer fmbot_"):
        await ensure_schema(env)
        bot_context = await _org_bot_token_context(env, request, touch=True)
        if not bot_context:
            return json_response(
                {"error": "invalid_bot_token"},
                status=401,
                cache_control="no-store",
            )
        required_scope = (
            "organization.tasks.read"
            if method_name(request) == "GET"
            else "organization.tasks.write"
        )
        if required_scope not in set(bot_context.get("scopes") or []):
            return json_response(
                {
                    "error": "permission_denied",
                    "requiredScope": required_scope,
                },
                status=403,
                cache_control="no-store",
            )
    return await world_office_tasks.handle(
        _OfficeMarketingTasksRuntime(env, request, bot_context), path)


world_office_marketing_tasks_handler = organization_tasks_handler


NOTES_REQUEST_PROOF = "forkmesh-notes-request-v1"


class _NotesRuntime(_WorldCommunityRuntime):
    """Runtime boundary for encrypted notes and their transient live room."""

    def same_origin(self):
        authorization = str(
            self.request.headers.get("authorization") or "").strip().lower()
        signed = bool(parse_qs(urlparse(self.request.url).query).get("sig"))
        return (super().same_origin() or signed
                or authorization.startswith("bearer "))

    async def json_body(self, limit):
        try:
            announced = int(self.request.headers.get("content-length") or 0)
            if announced < 0 or announced > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = str(await self.request.text() or "")
        except Exception:
            return None, "invalid_json"
        if len(raw.encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        self._notes_body_digest = await sha256_hex(raw)
        if not raw.strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        account_bi, record = await _account_session_record(
            self.env, self.request, data if isinstance(data, dict) else {})
        if account_bi and record:
            return account_bi, record
        return await _plugin_scope_signed_session(
            self.env, self.request, getattr(self, "_notes_body_digest", ""),
            NOTES_REQUEST_PROOF, "/api/notes")

    async def principal(self, kind, name):
        if kind == "user":
            account_bi, record = await _account_row(self.env, name)
            if (
                account_bi and record
                and record.get("status") == "active"
                and _account_kind(record) == "user"
            ):
                return str(account_bi), clean_string(
                    record.get("name") or name, MAX_NODE_NAME).lower()
            return "", ""
        org_bi, record = await _org_row(self.env, name)
        return ((str(org_bi), clean_string(
            (record or {}).get("name") or name, MAX_NODE_NAME).lower())
                if org_bi and record else ("", ""))

    async def member_organizations(self, account_bi):
        rows = await d1_all(
            self.env,
            "SELECT o.name AS name FROM org_members m "
            "JOIN orgs o ON o.org_bi=m.org_bi "
            "WHERE m.member_bi=? ORDER BY o.name LIMIT ?",
            str(account_bi or ""), 200,
        )
        return [clean_string(row.get("name"), MAX_NODE_NAME).strip().lower()
                for row in rows or []]

    async def repository_access(self, owner, repo, actor):
        return bool(await _repository_access_context(
            self.env, self.request, owner, repo, viewer=actor))

    async def account_name(self, account_bi):
        record = await _account_identity_rec_by_bi(self.env, account_bi)
        return clean_string(
            (record or {}).get("name") or "", MAX_NODE_NAME).lower()

    async def viewer(self, note_id):
        """Blind per-note reader key behind a published note's view count.

        Same discipline as the World visitor counter: only Cloudflare's edge
        header is trusted, the user agent is reduced to a category, and
        neither survives the request. What reaches D1 is an HMAC that cannot
        be reversed and — because the note id is inside the digest — cannot
        be correlated across notes either.
        """
        try:
            headers = self.request.headers
            address = world_visitor_metrics.canonical_edge_address(
                headers.get("cf-connecting-ip") or "")
            agent = str(headers.get("user-agent") or "")[:2048]
        except Exception:
            return ""
        if not address:
            # A non-edge request cannot be deduplicated; skip it rather than
            # collapsing every address-less reader into one counted visitor.
            return ""
        digest = await blind_index(self.env, "note-view-v1\n%s\n%s\n%s" % (
            str(note_id), address, world_visitor_metrics
            .generalized_user_agent(agent)))
        return str(digest)[:64]

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)

    @staticmethod
    def changes(result):
        try:
            return int(result.meta.changes)
        except Exception:
            try:
                converted = result.to_py() if hasattr(result, "to_py") else result
                return int((converted.get("meta") or {}).get("changes") or 0)
            except Exception:
                return 0

    async def seal(self, value):
        return await encrypt_row(self.env, value)

    async def open(self, value):
        return await decrypt_row(self.env, value)

    async def audit(self, actor, action, target_type="", target=""):
        await _audit_sensitive_action(
            self.env, actor, action, target_type, target)

    async def realtime(self, note_id, _account_bi, actor, role):
        room_id = self.env.FORKMESH_NOTE_ROOM.idFromName(
            "note:" + str(note_id))
        target = (
            "https://forkmesh.internal/api/notes/" + str(note_id)
            + "/ws?role=" + quote(str(role), safe="")
            + "&actor=" + quote(str(actor), safe="")
        )
        forwarded = await durable_object_request(
            self.request, target_url=target)
        return await self.env.FORKMESH_NOTE_ROOM.get(room_id).fetch(forwarded)

    async def broadcast(self, note_id, frame):
        room_id = self.env.FORKMESH_NOTE_ROOM.idFromName(
            "note:" + str(note_id))
        request = JsRequest.new(
            "https://forkmesh.internal/api/notes/" + str(note_id) + "/event",
            to_js({
                "method": "POST",
                "headers": {"content-type": "application/json"},
                "body": json.dumps(frame, separators=(",", ":")),
            }),
        )
        await self.env.FORKMESH_NOTE_ROOM.get(room_id).fetch(request)


async def notes_handler(env, request, path):
    return await notes.handle(_NotesRuntime(env, request), path)


CALENDAR_LIST_PROOF = "forkmesh-calendar-list-v1"
CALENDAR_CREATE_PROOF = "forkmesh-calendar-create-v1"
CALENDAR_READ_PROOF = "forkmesh-calendar-read-v1"
CALENDAR_UPDATE_PROOF = "forkmesh-calendar-update-v1"
CALENDAR_DELETE_PROOF = "forkmesh-calendar-delete-v1"
CALENDAR_RSVP_PROOF = "forkmesh-calendar-rsvp-v1"
CALENDAR_COLLECTION_RE = re.compile(r"^/api/calendar/?$")
CALENDAR_ITEM_RE = re.compile(r"^/api/calendar/([a-f0-9]{32})/?$")
CALENDAR_RSVP_RE = re.compile(r"^/api/calendar/([a-f0-9]{32})/rsvp/?$")


async def _calendar_signed_session(env, request, body_digest=""):
    """Resolve a normal key-authenticated desktop calendar request.

    The desktop's silent login proves its durable account key but intentionally
    creates no password session. Each calendar operation therefore has its own
    short-lived proof; event operations name the exact event, mutations bind
    the exact request body, and the calendar API still applies all owner,
    attendee, and organization gates.
    """
    method = method_name(request)
    if method not in ("GET", "POST", "PATCH", "DELETE"):
        return "", None
    url = urlparse(request.url)
    params = parse_qs(url.query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    if not node or not sig or not _ts_ok(ts):
        return "", None
    collection = CALENDAR_COLLECTION_RE.match(url.path)
    item = CALENDAR_ITEM_RE.match(url.path)
    rsvp = CALENDAR_RSVP_RE.match(url.path)
    proof = ""
    resource = ""
    if collection and method == "GET":
        proof = CALENDAR_LIST_PROOF
    elif collection and method == "POST":
        proof, resource = CALENDAR_CREATE_PROOF, body_digest
    elif item and method == "GET":
        proof, resource = CALENDAR_READ_PROOF, item.group(1)
    elif item and method == "PATCH":
        proof, resource = (
            CALENDAR_UPDATE_PROOF, item.group(1) + "\n" + body_digest)
    elif item and method == "DELETE":
        proof, resource = CALENDAR_DELETE_PROOF, item.group(1)
    elif rsvp and method == "POST":
        proof, resource = (
            CALENDAR_RSVP_PROOF, rsvp.group(1) + "\n" + body_digest)
    else:
        return "", None
    if method in ("POST", "PATCH") and not re.fullmatch(
            r"[0-9a-f]{64}", body_digest):
        return "", None
    canonical = proof + "\n" + node + "\n"
    if resource:
        canonical += resource + "\n"
    canonical = (canonical + str(ts)).encode()
    return await _signed_account_session(env, node, sig, canonical)


class _CalendarRuntime(_WorldCommunityRuntime):
    """Runtime boundary for encrypted personal and organization calendars."""

    async def session(self, data=None):
        account_bi, record = await _account_session_record(
            self.env, self.request, data if isinstance(data, dict) else {})
        if account_bi and record:
            return account_bi, record
        return await _calendar_signed_session(
            self.env, self.request,
            getattr(self, "_calendar_body_digest", ""))

    async def json(self):
        limit = _json_request_limit(self.request)
        announced = int(self.request.headers.get("content-length") or 0)
        if announced < 0 or announced > limit:
            raise RequestBodyTooLarge()
        raw = str(await self.request.text())
        if len(raw.encode("utf-8")) > limit:
            raise RequestBodyTooLarge()
        self._calendar_body_digest = await sha256_hex(raw)
        return json.loads(raw or "{}")

    def query(self, name):
        if self.request is None:
            return ""
        try:
            return URL(self.request.url).searchParams.get(str(name)) or ""
        except Exception:
            return ""

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)

    @staticmethod
    def changes(result):
        try:
            return int(result.meta.changes)
        except Exception:
            try:
                converted = result.to_py() if hasattr(result, "to_py") else result
                return int((converted.get("meta") or {}).get("changes") or 0)
            except Exception:
                return 0

    async def seal(self, value):
        return await encrypt_row(self.env, value)

    async def open(self, value):
        return await decrypt_row(self.env, value)

    async def account(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return ""
        account_bi, record = await _account_row(self.env, name)
        if (
            not record
            or record.get("status") != "active"
            or _account_kind(record) != "user"
        ):
            return ""
        return str(account_bi or "")

    async def org(self, name, actor):
        org_bi, record = await _org_row(self.env, name)
        if not record:
            return "", ""
        return await _org_role(self.env, org_bi, actor), str(org_bi)

    async def org_role(self, name, actor):
        org_bi, record = await _org_row(self.env, name)
        return await _org_role(self.env, org_bi, actor) if record else ""

    async def notify(self, recipient, kind, title, **kwargs):
        return await enqueue_notification(
            self.env, recipient, kind, title, **kwargs)

    async def audit(self, actor, action, target_type="", target=""):
        await _audit_sensitive_action(
            self.env, actor, action, target_type, target)


