PLUGIN_REQUEST_PROOF = "forkmesh-plugin-request-v1"


async def _plugin_scope_signed_session(env, request, body_digest, proof, prefix):
    """Resolve one exact account-key-signed plugin API request."""
    method = method_name(request)
    if method not in ("GET", "POST", "PATCH", "PUT", "DELETE"):
        return "", None
    url = urlparse(request.url)
    if not (url.path == prefix or url.path.startswith(prefix + "/")):
        return "", None
    params = parse_qs(url.query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    if not node or not sig or not _ts_ok(ts):
        return "", None
    resource = method + "\n" + url.path
    if method != "GET":
        if not re.fullmatch(r"[0-9a-f]{64}", str(body_digest or "")):
            return "", None
        resource += "\n" + str(body_digest)
    canonical = (
        proof + "\n" + node + "\n" + resource + "\n" + str(ts)
    ).encode()
    return await _signed_account_session(env, node, sig, canonical)


async def _plugin_lifecycle_signed_session(env, request, body_digest=""):
    return await _plugin_scope_signed_session(
        env, request, body_digest, PLUGIN_REQUEST_PROOF, "/api/plugins")


# Vision-capable Workers AI models a package may aim an image at, in the
# order they are billed. Text-only package prompts use the ForkBot allowlist.
# PLUGIN_AI_VISION_MODEL overrides the first pick per deployment.
PLUGIN_AI_VISION_MODELS = (
    "@cf/meta/llama-4-scout-17b-16e-instruct",
    "@cf/meta/llama-3.2-11b-vision-instruct",
)
PLUGIN_AI_MAX_IMAGE_DATA_URL = 1_600_000
PLUGIN_AI_MAX_TOKENS = 1200
PLUGIN_AI_RATE_SUFFIX = ":plugin-ai"
PLUGIN_AI_ABSENT_ERRORS = frozenset({"missing_binding", "ai_unavailable"})


def _plugin_ai_text(result):
    """The answer text or parsed object inside one Workers AI result."""
    try:
        if hasattr(result, "to_py"):
            result = result.to_py()
    except Exception:
        pass
    if isinstance(result, str):
        return result
    if not isinstance(result, dict):
        return None
    for key in ("response", "text", "output"):
        value = result.get(key)
        if isinstance(value, (str, dict)):
            return value
    for choice in result.get("choices") or []:
        if not isinstance(choice, dict):
            continue
        message = choice.get("message")
        content = message.get("content") if isinstance(message, dict) else choice.get("text")
        if isinstance(content, str) and content.strip():
            return content
        if isinstance(content, list):
            joined = "".join(
                part if isinstance(part, str) else str((part or {}).get("text") or "")
                for part in content if isinstance(part, (str, dict)))
            if joined.strip():
                return joined
    return result


async def _plugin_ai_json(env, account_bi, system_prompt, user_prompt, schema,
                          image_data_url="", max_tokens=700):
    image = str(image_data_url or "")
    if image and (len(image) > PLUGIN_AI_MAX_IMAGE_DATA_URL
                  or not re.fullmatch(
                      r"data:image/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+",
                      image)):
        return {"ok": False, "error": "invalid_image"}
    limited = await _ai_ask_rate_check(
        env, str(account_bi or "") + PLUGIN_AI_RATE_SUFFIX)
    if limited is not None:
        try:
            retry = int(json.loads(str(await limited.text())).get("retryAfterMs") or 0)
        except Exception:
            retry = 0
        return {"ok": False, "error": "rate_limited", "retryAfterMs": retry}
    ai = getattr(env, "AI", None)
    if ai is None or js_nullish(ai) or not hasattr(ai, "run"):
        return {"ok": False, "error": "missing_binding"}
    if image:
        preferred = clean_string(
            getattr(env, "PLUGIN_AI_VISION_MODEL", "") or "", 120).strip()
        candidates = [preferred] if preferred else []
        candidates += [m for m in PLUGIN_AI_VISION_MODELS if m not in candidates]
        content = [
            {"type": "text", "text": str(user_prompt)},
            {"type": "image_url", "image_url": {"url": image}},
        ]
    else:
        candidates = list(_forkbot_ai_fallback_models(env))
        content = str(user_prompt)
    base = {
        "messages": [
            {"role": "system", "content": str(system_prompt)},
            {"role": "user", "content": content},
        ],
        "max_tokens": max(64, min(PLUGIN_AI_MAX_TOKENS, int(max_tokens or 700))),
    }
    attempts = [base]
    if schema:
        strict = dict(base)
        strict["response_format"] = {"type": "json_schema", "json_schema": schema}
        attempts.insert(0, strict)
    last_error = None
    for candidate in candidates:
        for payload in attempts:
            try:
                result = await ai.run(candidate, to_js(payload))
            except Exception as error:
                last_error = error
                if _forkbot_ai_model_not_found_error(error):
                    break
                continue
            text = _plugin_ai_text(result)
            parsed = text if isinstance(text, dict) else _forkbot_json_object_from_text(text)
            if isinstance(parsed, dict):
                return {"ok": True, "data": parsed, "model": candidate}
            last_error = None
    await log_error(env, 500, "AI", "plugin/ai",
                    "Package AI call failed: " + (
                        _safe_error_text(last_error)[:300] if last_error
                        else "no usable JSON answer"))
    return {"ok": False, "error": "provider_error" if last_error else "unusable_response"}


class _PluginApiRuntime(_WorldCommunityRuntime):
    """Least-privilege adapter for a package-owned Worker API."""

    _FOLLOWED_REDIRECTS = frozenset((301, 302, 303, 307, 308))
    _MAX_REDIRECTS = 3

    def __init__(self, env, request, module=None, outbound_origins=(), plugin=""):
        super().__init__(env, request)
        self._module = module
        self._plugin = plugin
        self._outbound_origins = frozenset(
            str(value or "").rstrip("/").lower()
            for value in outbound_origins if value)

    def _signed_query(self):
        try:
            values = parse_qs(urlparse(self.request.url).query)
            return all(values.get(key, [""])[0] for key in ("node", "ts", "sig"))
        except Exception:
            return False

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        if (int(status or 200) >= 500 and isinstance(data, dict)
                and data.get("error") in PLUGIN_AI_ABSENT_ERRORS):
            extra_headers = {**(extra_headers or {}),
                             **EXPECTED_DEGRADED_HEADERS}
        return super().response(
            data, status=status, cache_control=cache_control,
            extra_headers=extra_headers)

    def same_origin(self):
        authorization = str(
            self.request.headers.get("authorization") or "").strip().lower()
        return (self._signed_query() or authorization.startswith("bearer ")
                or super().same_origin())

    async def json_body(self, limit):
        try:
            announced = int(self.request.headers.get("content-length") or 0)
            if announced < 0 or announced > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = str(await self.request.text())
        except Exception:
            return None, "invalid_json"
        if len(raw.encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        self._plugin_body_digest = await sha256_hex(raw)
        if not raw.strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        if self._module is not None and self._signed_query():
            return await _plugin_scope_signed_session(
                self.env, self.request, getattr(self, "_plugin_body_digest", ""),
                self._module.REQUEST_PROOF, self._module.PREFIX)
        return await _WorldCommunityRuntime.session(self, data)

    def request_origin(self):
        """The caller's normalized Origin, or "" (cron, non-browser caller).

        A package with a public ingest route scopes its write keys to the
        sites allowed to use them; it never sees any other header.
        """
        return _request_origin(self.request) if self.request is not None else ""

    def request_visitor(self):
        if self.request is None:
            return {"ip": "", "agent": ""}
        headers = self.request.headers
        return {"ip": str(headers.get("cf-connecting-ip") or "").strip()[:64],
                "agent": str(headers.get("user-agent") or "")[:512]}

    async def organization(self, name, account_bi):
        org_bi, record = await _org_row(self.env, name)
        if not org_bi or not record:
            return "", ""
        member = await d1_first(
            self.env,
            "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
            org_bi, account_bi)
        return str(org_bi), str((member or {}).get("role") or "")

    async def plugin_installed(self, org_bi, plugin):
        row = await d1_first(
            self.env,
            "SELECT plugin FROM org_plugin_installs WHERE org_bi=? AND plugin=?",
            org_bi, plugin)
        return bool(row)

    async def account_plugin_installed(self, account_bi):
        return await plugin_data.account_package_installed(
            self, str(account_bi or ""), self._plugin)

    async def account_created_at(self, account_bi):
        rec = await _account_identity_rec_by_bi(self.env, str(account_bi or ""))
        return int((rec or {}).get("created_at") or 0)

    async def notify(self, recipient, kind, title, body="", href="",
                     dedupe="", meta=None, push=True):
        """Queue one ping of a package-owned kind; core kinds stay the core's."""
        if kind not in PLUGIN_NOTIFICATION_KINDS:
            return False
        return await enqueue_notification(
            self.env, recipient, kind, title, body=body, href=href,
            source="plugin", dedupe=dedupe, meta=meta, push=bool(push))

    def new_secret(self):
        """Fresh 256-bit key material for a package's own row encryption.

        A package that wants per-account (rather than instance-wide) keys
        mints one of these per account, stores it only under ``seal`` — i.e.
        encrypted with DATA_KEY — and passes it back to ``seal_with`` /
        ``open_with`` for every row that belongs to that account.
        """
        return _ap_uuid() + _ap_uuid()

    async def seal_with(self, secret, value):
        """Encrypt one row under caller-supplied key material, not DATA_KEY."""
        return await encrypt_row(
            self.env, value, key=await _scoped_key(secret))

    async def open_with(self, secret, value):
        """Decrypt a ``seal_with`` row; None when the material does not fit."""
        try:
            key = await _scoped_key(secret)
        except RuntimeError:
            return None
        return await decrypt_row(self.env, value, key=key)

    async def account_exists(self, name):
        """True when ``name`` is an active user account a package may share
        organization records with. Only the yes/no leaves the host."""
        clean = str(name or "").strip().lower()
        if not valid_node_name(clean):
            return False
        account_bi, record = await _account_row(self.env, clean)
        return bool(
            account_bi and record
            and record.get("status") == "active"
            and _account_kind(record) == "user")

    async def account_evidence(self, actor, emails):
        if (PLUGIN_ACCOUNT_EVIDENCE_PERMISSION not in plugin_data.permissions(self._plugin)
                or not await _is_admin(self.env, actor)):
            return None
        wanted = {}
        for email in list(emails or [])[:PLUGIN_ACCOUNT_EVIDENCE_LIMIT]:
            clean = str(email or "").strip().lower()
            if "@" in clean and len(clean) <= 254 and clean not in wanted.values():
                wanted[await blind_index(self.env, clean)] = clean
        if not wanted:
            return {}
        rows = await d1_all(
            self.env,
            "SELECT user_bi,username,email_bi,data FROM users "
            "WHERE email_bi IN (SELECT value FROM json_each(?))",
            json.dumps(list(wanted)))
        accounts = {}
        for row in rows or []:
            rec = await decrypt_row(self.env, row.get("data")) or {}
            if rec.get("status") != "active" or _account_kind(rec) != "user":
                continue
            accounts[str(row.get("user_bi") or "")] = {
                "email": wanted.get(str(row.get("email_bi") or ""), ""),
                "account": str(row.get("username") or ""),
                "signedUpAt": int(rec.get("created_at") or 0),
                "paid": None, "promotion": None, "trial": None,
            }
        if not accounts:
            return {}
        ids = json.dumps(list(accounts))
        grants = await d1_all(
            self.env,
            "SELECT account_bi,role,scope_type,granted_at,expires_at FROM role_grants "
            "WHERE account_bi IN (SELECT value FROM json_each(?)) AND revoked_at=0 "
            "AND role IN ('pro_member','supporting_member') "
            "AND scope_type IN ('platform','promotion')", ids)
        now = int(Date.now())
        for grant in grants or []:
            account = accounts.get(str(grant.get("account_bi") or ""))
            if account is None:
                continue
            key = "paid" if grant.get("scope_type") == "platform" else "promotion"
            window = {"tier": PLUGIN_MEMBER_ROLES.get(str(grant.get("role") or ""), ""),
                      "since": int(grant.get("granted_at") or 0),
                      "until": int(grant.get("expires_at") or 0)}
            window["active"] = window["until"] > now
            current = account[key]
            rank = (window["active"], window["tier"] == "pro", window["until"])
            if current is None or rank > (current["active"], current["tier"] == "pro",
                                          current["until"]):
                account[key] = window
        trials = await d1_all(
            self.env,
            "SELECT account_bi,started_at,ends_at FROM plan_trials "
            "WHERE account_bi IN (SELECT value FROM json_each(?))", ids)
        for trial in trials or []:
            account = accounts.get(str(trial.get("account_bi") or ""))
            if account is not None:
                ends_at = int(trial.get("ends_at") or 0)
                account["trial"] = {"startedAt": int(trial.get("started_at") or 0),
                                    "endsAt": ends_at, "active": ends_at > now}
        return {account.pop("email"): account for account in accounts.values()}

    async def organization_member_emails(self, org_bi, account_bi):
        if (PLUGIN_MEMBER_EMAILS_PERMISSION not in plugin_data.permissions(self._plugin)
                or not await self.plugin_installed(org_bi, self._plugin)):
            return []
        member = await d1_first(
            self.env,
            "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
            org_bi, account_bi)
        if not member:
            return []
        rows = await d1_all(
            self.env,
            "SELECT u.data FROM org_members m JOIN users u ON u.user_bi=m.member_bi "
            "WHERE m.org_bi=? AND m.member_bi<>? ORDER BY m.name COLLATE NOCASE LIMIT ?",
            org_bi, account_bi, PLUGIN_MEMBER_EMAILS_LIMIT)
        emails = []
        for row in rows or []:
            rec = await decrypt_row(self.env, row.get("data")) or {}
            if (rec.get("status") != "active" or _account_kind(rec) != "user"
                    or not rec.get("email_verified")):
                continue
            email = clean_string(rec.get("email", ""), 254).strip().lower()
            if valid_account_email(email) and email not in emails:
                emails.append(email)
        return emails

