def _repo_identity_from_clone_url(value):
    raw = clean_string(value, 2048).strip()
    if not raw:
        return "", ""
    path = raw
    try:
        if re.match(r"^[a-z][a-z0-9+.-]*://", raw, re.I):
            path = urlparse(raw).path
        elif raw.startswith("git@") and ":" in raw:
            path = raw.split(":", 1)[1]
    except Exception:
        path = raw
    path = path.split("?", 1)[0].split("#", 1)[0].strip("/")
    parts = [p for p in path.split("/") if p]
    if len(parts) < 2:
        return "", ""
    owner = safe_segment(unquote(parts[-2]))
    name = safe_segment(unquote(parts[-1]))
    if name.lower().endswith(".git"):
        name = safe_segment(name[:-4])
    return owner, name


def _catalog_record_matches_identity(record, owner, repo):
    if not record:
        return False
    owner_l = str(owner or "").lower()
    repo_l = str(repo or "").lower()
    if (str(record.get("owner", "")).lower() == owner_l and
            str(record.get("name", "")).lower() == repo_l):
        return True
    clone_owner, clone_repo = _repo_identity_from_clone_url(record.get("cloneUrl", ""))
    return clone_owner.lower() == owner_l and clone_repo.lower() == repo_l


def _native_repository_logo_id(owner, repo):
    canonical = (
        "forkmesh-native-repository-logo-v1\n"
        + str(owner or "").strip().lower() + "\n"
        + str(repo or "").strip().lower()
    ).encode()
    return "native_" + hashlib.sha256(canonical).hexdigest()[:24]


def _native_repository_logo_record(record, owner, repo):
    source = record if isinstance(record, dict) else {}
    metadata = source.get("logoMetadata")
    metadata = dict(metadata) if isinstance(metadata, dict) else {}
    metadata["description"] = clean_string(
        source.get("description", ""), 500)
    topics = source.get("topics")
    if isinstance(topics, list) and "topics" not in metadata:
        metadata["topics"] = topics
    return {
        "id": _native_repository_logo_id(owner, repo),
        "provider": "forkmesh",
        "providerOwner": str(owner or "").lower(),
        "name": str(repo or ""),
        "fullName": str(owner or "") + "/" + str(repo or ""),
        "metadata": metadata,
        # Missing or malformed visibility stays private/fail-closed.
        "isPrivate": source.get("visibility") != "public",
        "commit": clean_string(source.get("commit", ""), 64).lower(),
    }


def _committed_repository_logo_url(record, owner, repo):
    """Return the immutable raw URL for a conventional root project logo."""
    source = record if isinstance(record, dict) else {}
    if source.get("isPrivate", source.get("visibility") != "public"):
        return ""
    commit = clean_string(source.get("commit", ""), 64).strip().lower()
    if not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit):
        return ""
    metadata = source.get("metadata")
    if not isinstance(metadata, dict):
        metadata = source.get("logoMetadata")
    file_structure = (
        metadata.get("fileStructure")
        if isinstance(metadata, dict) else None
    )
    listed = file_structure if isinstance(file_structure, list) else []
    if listed:
        files = {
            str(path or "").strip().lower(): str(path or "").strip()
            for path in listed
            if (
                isinstance(path, str)
                and "/" not in path.strip().rstrip("/")
            )
        }
        path = next(
            (
                files[name]
                for name in ("logo.png", "logo.webp", "logo.jpg", "logo.jpeg")
                if name in files
            ),
            "",
        )
        if not path and "logo.svg" in files:
            return _committed_svg_logo_url(owner, repo, commit)
        if not path:
            return ""
    else:
        path = "logo.png"
    return (
        "/api/repo/%s/%s/raw?path=%s&ref=%s"
        % (quote(owner), quote(repo), quote(path), quote(commit))
    )


def _committed_svg_logo_url(owner, repo, commit):
    return (
        "/api/repo/%s/%s/dir-logo?path=&ref=%s"
        % (quote(owner), quote(repo), quote(commit))
    )


_COMMITTED_LOGO_PROBES = {}
_COMMITTED_LOGO_PROBE_LIMIT = 512


def _repository_root_listing(record):
    source = record if isinstance(record, dict) else {}
    metadata = source.get("metadata")
    if not isinstance(metadata, dict):
        metadata = source.get("logoMetadata")
    listed = metadata.get("fileStructure") if isinstance(
        metadata, dict) else None
    return listed if isinstance(listed, list) else []


async def _verified_committed_logo_url(env, request, record, owner, repo,
                                       url):
    if not url or _repository_root_listing(record):
        return url
    commit = clean_string((record or {}).get("commit", ""), 64).lower()
    key = (str(owner or "").lower(), str(repo or "").lower(), commit)
    svg_url = url.split("/raw?", 1)[0] + "/dir-logo?path=&ref=" + commit
    found_urls = {"png": url, "svg": svg_url}
    if key in _COMMITTED_LOGO_PROBES:
        return found_urls.get(_COMMITTED_LOGO_PROBES[key], "")
    try:
        import directory_about
        directory_about._bind_runtime(globals())
        status, data = await directory_about.read_blobs(
            env, request, owner, repo, ["logo.png", "logo.svg"], commit,
            False)
    except Exception:
        return url
    if status == 200:
        blobs = (data or {}).get("blobs") or {}
        found = ""
        if isinstance(blobs.get("logo.png"), dict):
            found = "png"
        elif isinstance(blobs.get("logo.svg"), dict):
            try:
                raw = directory_about.blob_bytes(blobs["logo.svg"])
                if directory_about.logo_type("logo.svg", raw):
                    found = "svg"
            except Exception:
                found = ""
    elif status == 404:
        found = ""
    else:
        return url
    while len(_COMMITTED_LOGO_PROBES) >= _COMMITTED_LOGO_PROBE_LIMIT:
        del _COMMITTED_LOGO_PROBES[next(iter(_COMMITTED_LOGO_PROBES))]
    _COMMITTED_LOGO_PROBES[key] = found
    return found_urls.get(found, "")


# A repository's social header belongs to the repository, so it ships inside
# it: `.forkmesh/banner.png`, alongside the rest of a project's ForkMesh
# metadata. Nothing here falls back to the ForkMesh brand banner — that image
# is this instance's own identity, and painting it across unrelated
# repositories advertised somebody else's project as ForkMesh. A repo without
# committed artwork simply has no header.
# Exactly one name, not a list of candidate extensions: catalog metadata never
# reveals what is inside a directory, so the server can only ever name one path
# and let the fetch decide. A convention readers can state exactly beats one
# they have to probe four times.
COMMITTED_BANNER_DIR = ".forkmesh"
COMMITTED_BANNER_NAME = "banner.png"


def _committed_repository_banner_url(record, owner, repo):
    """Return the immutable raw URL for a repo's own committed banner."""
    source = record if isinstance(record, dict) else {}
    if source.get("isPrivate", source.get("visibility") != "public"):
        return ""
    commit = clean_string(source.get("commit", ""), 64).strip().lower()
    if not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit):
        return ""
    metadata = source.get("metadata")
    if not isinstance(metadata, dict):
        metadata = source.get("logoMetadata")
    file_structure = (
        metadata.get("fileStructure")
        if isinstance(metadata, dict) else None
    )
    if isinstance(file_structure, list) and file_structure:
        # Catalog metadata only records TOP-LEVEL names, so it can rule the
        # banner out (the repo has no .forkmesh directory at all) but never
        # confirm the file inside it. Readers treat the URL as a candidate:
        # a 404 from the mirror means "no banner", same as an empty string.
        top_level = {
            str(entry or "").strip().strip("/").lower()
            for entry in file_structure
            if isinstance(entry, str)
        }
        if COMMITTED_BANNER_DIR not in top_level:
            return ""
    path = COMMITTED_BANNER_DIR + "/" + COMMITTED_BANNER_NAME
    return (
        "/api/repo/%s/%s/raw?path=%s&ref=%s"
        % (quote(owner), quote(repo), quote(path, safe=""), quote(commit))
    )


async def _uploaded_repository_logo_url(env, record, owner, repo):
    if record.get("isPrivate", True):
        return ""
    row = await d1_first(
        env,
        "SELECT updated_at FROM repo_media WHERE repo_bi=? AND kind='logo'",
        await blind_index(env, owner + "/" + repo))
    if not row:
        return ""
    return "/api/repo/%s/%s/media/logo.png?v=%d" % (
        quote(owner), quote(repo), int(row.get("updated_at") or 0))


async def _freshest_public_repository_group_record(env, source):
    """Use the newest signed catalog copy for immutable repository media.

    An organization alias retains one durable backing record for settings and
    ownership, while its independent mirrors keep publishing newer commits.
    About-card media must follow that repository group: pinning the backing
    record's old commit makes a banner added later a permanent browser 404.
    The decrypted catalog is already isolate-memoized, so this selection adds
    no mirror fetch and no per-request network fan-out.
    """
    if not isinstance(source, dict):
        return source

    def freshness(record):
        values = []
        for key in ("updatedAt", "lastSync", "publishedAt"):
            try:
                values.append(max(0, int(record.get(key) or 0)))
            except (TypeError, ValueError):
                continue
        return max(values or [0])

    best = source
    best_freshness = freshness(source)
    try:
        rows = await _decrypted_public_catalog(env, int(Date.now()))
    except Exception:
        return best
    for row in rows or []:
        candidate = (row or {}).get("data") or {}
        commit = clean_string(candidate.get("commit", ""), 64).lower()
        if (
            (row or {}).get("is_private")
            or candidate.get("visibility") != "public"
            or not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit)
            or not repo_mirror_same_group(source, candidate)
        ):
            continue
        candidate_freshness = freshness(candidate)
        if candidate_freshness > best_freshness:
            best = candidate
            best_freshness = candidate_freshness
    return best


async def _public_repository_owner(env, request, owner, repo):
    """The organization name the caller addressed, for public byte URLs.

    org_alias_rewrite (issue #388) hands handlers the backing node so catalog
    reads, privacy gates and blind indexes stay canonical, but the two names
    are not interchangeable inside a URL handed back to a client:
    /api/repo/<node>/<repo>/raw pins the read to that one node and answers
    mirror_unavailable whenever it is offline, while the organization URL
    routes across the whole mirror group. Public documents therefore keep the
    organization name (the same rule _repo_about_public follows).
    """
    try:
        match = REPO_API_PREFIX_RE.match(
            urlparse(str(getattr(request, "url", "") or "")).path)
        candidate_owner = safe_segment(match.group(1)) if match else ""
        candidate_repo = safe_segment(match.group(2)) if match else ""
        if (
            candidate_owner
            and candidate_repo == repo
            and candidate_owner != owner
            and await _org_repo_node(
                env, candidate_owner, candidate_repo) == owner
        ):
            return candidate_owner
    except Exception:
        pass
    return owner


async def _native_repository_logo_context(env, request, owner, repo):
    # Reuse the normal repository read boundary so logo GETs have exactly the
    # same owner/share behavior as repository content. The shared gate rejects
    # plaintext-private rows before decryption, treats the encrypted signed
    # visibility as authoritative, and normalizes missing and unauthorized
    # names to the same empty result.
    context = await _repository_access_context(
        env, request, owner, repo)
    if not isinstance(context, dict):
        return None, "", ""
    record = context.get("record")
    actor = clean_string(context.get("viewer"), MAX_NODE_NAME).lower()
    return (
        _native_repository_logo_record(record, owner, repo),
        _native_repository_logo_id(owner, repo),
        actor,
    )


async def native_repository_logo_handler(
        env, request, owner, repo, suggestions=False):
    await ensure_schema(env)
    record, repository_id, actor = await _native_repository_logo_context(
        env, request, owner, repo)
    if not record:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    service = _repository_import_service()
    if not suggestions:
        if method_name(request) != "GET":
            return json_response({"error": "method_not_allowed"}, status=405)
        logo_url = await _uploaded_repository_logo_url(
            env, record, owner, repo)
        # The committed URL leaves this worker — a fediverse actor icon, a
        # repository card — so it names the organization the caller asked for.
        # Built from the rewritten backing node instead, it pointed a repo
        # avatar at one node's row and served mirror_unavailable to every
        # Mastodon instance whenever that node was offline, which is how the
        # flagship repo lost its profile picture (adhoc #122).
        committed_logo_url = (
            "" if logo_url
            else await _verified_committed_logo_url(
                env, request, record, owner, repo,
                _committed_repository_logo_url(
                    record,
                    await _public_repository_owner(
                        env, request, owner, repo),
                    repo)))
        params = parse_qs(urlparse(request.url).query)
        if params.get("image", [""])[0] == "1":
            if logo_url or committed_logo_url:
                return Response("", status=302, headers={
                    "location": logo_url or committed_logo_url,
                    "cache-control": "public, max-age=300",
                })
            logo = await service._official_logo(env, repository_id)
            if logo:
                return _repository_logo_image_response(
                    logo, public=not bool(record.get("isPrivate")))
            return Response("", status=302, headers={
                "location": AP_AVATAR_PATH,
                "cache-control": "public, max-age=300",
            })
        if logo_url:
            return json_response({
                "ok": True,
                "repositoryId": repository_id,
                "logo": {
                    "dataUrl": logo_url,
                    "source": "owner",
                    "fallbackDataUrl": "",
                },
            }, cache_control="no-store")
        if committed_logo_url:
            # The committed URL is streamed by a mirror, so it can fail while
            # the rest of the card renders (offline or lagging host). Ship the
            # approved artwork with it so a client can swap in place instead of
            # leaving a broken image where the logo belongs.
            fallback = await service._official_logo(env, repository_id)
            return json_response({
                "ok": True,
                "repositoryId": repository_id,
                "logo": {
                    "dataUrl": committed_logo_url,
                    "source": "repository",
                    "fallbackDataUrl": str(
                        (fallback or {}).get("dataUrl") or ""),
                },
            }, cache_control="no-store")
        return await service.logo_for_record(env, repository_id)

    async def can_admin(candidate):
        candidate = str(candidate or actor or "").strip().lower()
        return bool(
            candidate
            and (
                await _repository_import_moderator(env, candidate)
                or await _repo_admin_allowed(env, candidate, owner, repo)
            )
        )

    return await service.native_logo_suggestions(
        env, request, repository_id, record, can_admin)


def _repository_logo_image_response(logo, public=True):
    """Serve one validated native logo as image bytes for social clients."""
    data_url = str(
        (logo or {}).get("dataUrl", "")
        if isinstance(logo, dict) else "")
    if not data_url.startswith("data:image/") or "," not in data_url:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    header, encoded = data_url.split(",", 1)
    media_type = header[5:].split(";", 1)[0].strip().lower()
    if media_type not in (
        "image/svg+xml", "image/png", "image/jpeg", "image/webp"
    ):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    try:
        if ";base64" in header.lower():
            raw = base64.b64decode(encoded, validate=True)
        elif media_type == "image/svg+xml":
            raw = unquote(encoded).encode("utf-8")
        else:
            raw = b""
    except Exception:
        raw = b""
    if not raw or len(raw) > 2 * 1024 * 1024:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    return JsResponse.new(Uint8Array.new(_to_js(bytes(raw))), to_js({
        "status": 200,
        "headers": {
            "content-type": media_type,
            "cache-control": (
                "public, max-age=300"
                if public
                else "private, no-store, max-age=0, must-revalidate"
            ),
            "x-content-type-options": "nosniff",
        },
    }))


async def _repo_catalog_record(env, owner, repo):
    key_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
    if not row:
        return None
    try:
        return await decrypt_row(env, row.get("data"))
    except Exception:
        return None


async def _read_only_mirror_fields(env, owner, repo, record=None):
    if record is None:
        record = await _repo_catalog_record(env, owner, repo)
    return _read_only_mirrors.mirror_fields(
        record, str(getattr(env, "INSTANCE_UPSTREAM", "") or ""),
        _instance_solo_flagship_node(env), owner, repo)


async def read_only_mirror_refusal(env, request, owner, repo, path):
    if not owner or not repo or not _read_only_mirrors.is_write_request(
            method_name(request), path):
        return None
    fields = await _read_only_mirror_fields(env, owner, repo)
    if not fields["readOnly"]:
        return None
    return json_response(
        _read_only_mirrors.refusal_body(fields["mirrorOf"]), status=403,
        cache_control="no-store")


async def read_only_mirror_push_refusal(env, owner, repo):
    if not owner or not repo:
        return None
    fields = await _read_only_mirror_fields(env, owner, repo)
    if not fields["readOnly"]:
        return None
    return Response(
        _read_only_mirrors.refusal_message(fields["mirrorOf"]) + "\n",
        status=403, headers={"content-type": "text/plain; charset=utf-8",
                             "cache-control": "no-store"})


async def _repo_about_public(env, request, owner, repo):
    # Public About/branding card + fediverse stats: the repo page's social
    # badge header and Watch button read this. No auth — same visibility as
    # the catalog entry itself.
    # Organization API paths are internally rewritten to the backing node
    # before this handler runs. Recover the public owner from the untouched
    # Request URL, but only when the durable org link still resolves to the
    # canonical owner passed by the router. Catalog/privacy/settings reads
    # continue to use the backing owner; the actor identity and public media
    # URLs must keep the organization name.
    display_owner = owner
    try:
        public_path = urlparse(request.url).path
        public_match = REPO_ABOUT_RE.match(public_path)
    except Exception:
        public_match = None
    if public_match:
        candidate_owner = safe_segment(public_match.group(1))
        candidate_repo = safe_segment(public_match.group(2))
        if candidate_owner and candidate_repo == repo:
            if candidate_owner == owner:
                display_owner = candidate_owner
            elif await _org_repo_node(
                    env, candidate_owner, candidate_repo) == owner:
                display_owner = candidate_owner
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    key_bi = await blind_index(env, owner + "/" + repo)
    repo_row = await d1_first(
        env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
    if not repo_row:
        return json_response({"error": "not_found"}, status=404)
    rec = await decrypt_row(env, repo_row.get("data"))
    group_record_resolver = globals().get(
        "_freshest_public_repository_group_record")
    media_record = (
        await group_record_resolver(env, rec)
        if callable(group_record_resolver) else rec
    )
    origin = _ap_origin(env, request)
    handle = ap.repo_handle(str(display_owner).lower(), str(repo).lower())
    logo_url = ""
    banner_url = ""
    media_rows = await d1_all(
        env, "SELECT kind, updated_at FROM repo_media WHERE repo_bi=?", key_bi)
    for media in media_rows or []:
        media_url = "/api/repo/%s/%s/media/%s.png?v=%d" % (
            quote(display_owner), quote(repo), media.get("kind", ""),
            int(media.get("updated_at") or 0))
        if media.get("kind") == "logo":
            logo_url = media_url
        elif media.get("kind") == "banner":
            banner_url = media_url
    resolved_logo = {}
    logo_record_builder = globals().get("_native_repository_logo_record")
    logo_service_factory = globals().get("_repository_import_service")
    if callable(logo_record_builder) and callable(logo_service_factory):
        logo_record = logo_record_builder(rec, owner, repo)
        logo_service = logo_service_factory()
        resolved_logo = await logo_service._official_logo(
            env, logo_record["id"]) or {}
    if not logo_url:
        committed_logo_resolver = globals().get(
            "_committed_repository_logo_url")
        logo_url = (
            committed_logo_resolver(media_record, display_owner, repo)
            if callable(committed_logo_resolver) else ""
        ) or str(resolved_logo.get("dataUrl") or "")
    if not banner_url:
        # The repo's own committed .forkmesh/banner.png. There is deliberately
        # no default: an unbranded repository reports no banner and the card
        # drops the header strip instead of flying ForkMesh's colours.
        committed_banner_resolver = globals().get(
            "_committed_repository_banner_url")
        banner_url = (
            committed_banner_resolver(media_record, display_owner, repo)
            if callable(committed_banner_resolver) else ""
        )
    followers = 0
    followers_list = []
    fedi_enabled = await _ap_enabled(env)
    ap_settings = await _ap_repo_settings_get(env, owner, repo)
    if fedi_enabled:
        actor_bi = await _ap_actor_bi(env, AP_ACTOR_REPO, handle)
        row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        followers = (row or {}).get("c", 0) or 0
        # The newest followers, so the repo page can show WHO is watching —
        # follower_id/handle are public fediverse identifiers (the remote
        # server publishes the same follow), capped so a popular repo never
        # ships thousands of rows in an About card. The cached remote actor
        # document (LEFT JOIN: absent until that actor is first fetched) adds
        # the presentation every fediverse client already shows for them —
        # display name, avatar, bio, profile URL.
        rows = await d1_all(
            env,
            "SELECT follower_id, follower_handle, created_at, display_name,"
            " avatar_url, summary, url FROM ap_followers"
            " LEFT JOIN ap_remote_actors ON actor_id = follower_id"
            " WHERE actor_bi=? ORDER BY created_at DESC LIMIT 50",
            actor_bi)
        for follower in rows or []:
            follower_url = str(follower.get("follower_id") or "")
            follower_handle = str(follower.get("follower_handle") or "")
            parsed = urlparse(follower_url)
            if not follower_handle and follower_url:
                # Older rows may lack the resolved handle; a readable
                # fallback beats a bare URL in the UI.
                name = parsed.path.rstrip("/").rpartition("/")[2]
                if name and parsed.hostname:
                    follower_handle = "@%s@%s" % (
                        name.lstrip("@"), parsed.hostname)
            if follower_handle or follower_url:
                followers_list.append({
                    "handle": follower_handle,
                    "url": follower_url,
                    "name": clean_string(
                        follower.get("display_name") or "", 80),
                    "avatarUrl": ap.public_media_url(
                        follower.get("avatar_url") or ""),
                    "about": ap_threads.sanitize_remote_content(
                        follower.get("summary") or "", 240),
                    "instance": str(parsed.hostname or "").lower(),
                    "profileUrl": ap.public_media_url(
                        follower.get("url") or "") or follower_url,
                    "followedAt": int(follower.get("created_at") or 0),
                })
    return json_response({
        "ok": True,
        "description": clean_string(
            (rec or {}).get("description", "") or "", 240),
        "website": clean_string((rec or {}).get("website", "") or "", 240),
        "logoUrl": logo_url,
        "logo": resolved_logo,
        "bannerUrl": banner_url,
        "defaultLogoUrl": AP_AVATAR_PATH,
        # No defaultBannerUrl: the brand banner is the instance's identity, not
        # a stand-in for every repository's header (see bannerUrl above).
        "fediverse": {
            # enabled = "this repo currently federates": the instance switch
            # AND the owner's per-repo switch.
            "enabled": fedi_enabled and ap_settings["federate"],
            "handle": "@%s@%s" % (handle, _ap_domain_of(origin)),
            "actorUrl": _ap_actor_url(origin, AP_ACTOR_REPO, handle),
            "followers": followers,
            "followersList": followers_list,
            "settings": ap_settings,
        },
        **_read_only_mirrors.about_fields(
            await _repo_features_get(env, owner, repo),
            await _read_only_mirror_fields(env, owner, repo, rec or {})),
    }, cache_control="public, max-age=600")


async def repo_about_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) == "GET":
        return await _repo_about_public(env, request, owner, repo)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    # Only the repo owner (proven by their session token, not a self-asserted
    # ownerAccount string) may edit repo metadata. A platform role is not a
    # decryption/content-management grant. The Qt
    # desktop has no browser session; it proves the owner account's registered
    # Ed25519 key instead (same trust gate as ap-publish / the inbox drains,
    # with a distinct canonical so its tokens can't be replayed elsewhere).
    actor = await _authed_account_name(env, request, data)
    owner_key_authed = False
    if not actor and data.get("ownerSig") and data.get("ts"):
        ts = str(data.get("ts", "") or "")
        owner_pub = await _owner_pubkey(env, owner)
        canonical = ("forkmesh-repo-about-v1\n" + owner + "\n" + repo +
                     "\n" + ts).encode()
        if owner_pub and _ts_ok(ts) and await ed25519_verify(
                owner_pub, str(data.get("ownerSig", "") or ""), canonical):
            actor = str(owner).lower()
            owner_key_authed = True
    if not actor or (
            not owner_key_authed
            and not await _repo_admin_allowed(env, actor, owner, repo)):
        return json_response({"error": "not_authorized"}, status=403)
    if not await _owner_pubkey(env, owner) and not (
            await _branch_protection.settings_only(env, data, owner, repo)):
        return json_response({"error": "account_required"}, status=403)

    # Absent = unchanged, so a settings-only save (Qt fediverse switches)
    # never blanks the description.
    description_provided = "description" in data
    description = clean_string(data.get("description", ""), 240)
    # Optional project website shown under the description (and written into
    # the repo's .forkmesh/info.json by the owner's node). Absent = unchanged;
    # empty string = remove. Only http(s) URLs are accepted.
    website_provided = "website" in data
    website = clean_string(data.get("website", ""), 240).strip()
    if website_provided and website and not re.match(
            r"^https?://[^\s]+$", website):
        return json_response({"error": "invalid_website"}, status=400)
    # Optional repo branding for the fediverse actor (and anything else that
    # wants it): PNG logo (avatar) + banner (profile header). Absent field =
    # leave unchanged; empty string = remove. Validated before any write so a
    # bad image never half-applies the About edit.
    media_updates = {}
    for field, kind, cap in (("logoPng", "logo", MAX_REPO_LOGO_BYTES),
                             ("bannerPng", "banner", MAX_REPO_BANNER_BYTES)):
        if field not in data:
            continue
        png_b64, media_error = clean_media_png(data.get(field), cap)
        if media_error:
            return json_response({"error": media_error, "field": field},
                                 status=400)
        media_updates[kind] = png_b64
    rows = await d1_all(
        env, "SELECT key_bi, data, is_private FROM repositories")
    updated = 0
    text_changed = False
    first = None
    for row in rows:
        record = await decrypt_row(env, row.get("data"))
        if not _catalog_record_matches_identity(record, owner, repo):
            continue
        updated += 1
        if first is None:
            first = record
        # Re-saving the About dialog with unchanged values must be a no-op:
        # every write here cascades into a catalog cache purge, an about_inbox
        # round-trip through the owner's desktop, and an Update(Group)
        # broadcast to every fediverse follower.
        if ((not description_provided or
             str(record.get("description") or "") == description) and
                (not website_provided or
                 str(record.get("website") or "") == website)):
            continue
        if description_provided:
            record["description"] = description
        if website_provided:
            record["website"] = website
        enc = await encrypt_row(env, record)
        await d1_run(
            env,
            "UPDATE repositories SET data=?, is_private=? WHERE key_bi=?",
            enc,
            1 if record.get("visibility") == "private" else 0,
            row.get("key_bi"),
        )
        text_changed = True
    if not updated:
        return json_response({"error": "not_found"}, status=404)
    media_bi = await blind_index(env, str(owner).lower() + "/" + repo)
    media_changed = False
    for kind, png_b64 in media_updates.items():
        existing = await d1_first(
            env, "SELECT data FROM repo_media WHERE repo_bi=? AND kind=?",
            media_bi, kind)
        if not png_b64:
            if existing:
                await d1_run(
                    env, "DELETE FROM repo_media WHERE repo_bi=? AND kind=?",
                    media_bi, kind)
                media_changed = True
            continue
        # Identical bytes keep the stored updated_at: bumping it would rotate
        # the ?v= cache-buster in the actor doc and make every follower server
        # re-download an image that did not change.
        stored = await decrypt_row(env, existing.get("data")) if existing \
            else None
        if stored and stored.get("png") == png_b64:
            continue
        await d1_run(
            env,
            "INSERT INTO repo_media (repo_bi, kind, data, updated_at)"
            " VALUES (?,?,?,?)"
            " ON CONFLICT(repo_bi, kind) DO UPDATE SET data=excluded.data,"
            " updated_at=excluded.updated_at",
            media_bi, kind, await encrypt_row(env, {"png": png_b64}),
            int(Date.now()))
        media_changed = True
    # Per-repo fediverse switches ride the same About save (web gear form and
    # the Qt dialog both send a `fediverse` object). Absent = unchanged; an
    # unchanged value writes nothing, so a plain description re-save never
    # touches the AP tables or the edge cache.
    ap_settings = None
    settings_changed = False
    fedi_data = data.get("fediverse")
    if isinstance(fedi_data, dict):
        current_settings = await _ap_repo_settings_get(env, owner, repo)
        ap_settings = dict(current_settings)
        for key in AP_REPO_SETTING_DEFAULTS:
            if key in fedi_data:
                ap_settings[key] = bool(fedi_data.get(key))
        if ap_settings != current_settings:
            settings_changed = True
            await d1_run(
                env,
                "INSERT INTO ap_repo_settings (repo_bi, data, updated_at)"
                " VALUES (?,?,?) ON CONFLICT(repo_bi) DO UPDATE SET"
                " data=excluded.data, updated_at=excluded.updated_at",
                await _ap_repo_settings_bi(env, owner, repo),
                json.dumps(ap_settings), int(Date.now()))
            # The actor doc, its collections and the webfinger lookup are
            # edge-cached (and misses park a 404): drop them so a federation
            # switch takes effect now, not after the TTL.
            origin = _ap_origin(env, request)
            ap_handle = ap.repo_handle(
                str(owner).lower(), str(repo).lower())
            actor_url = _ap_actor_url(origin, AP_ACTOR_REPO, ap_handle)
            for cache_key in (
                    actor_url, actor_url + "/followers",
                    actor_url + "/following", actor_url + "/outbox",
                    "%s/.well-known/webfinger?resource=acct:%s@%s"
                    % (origin, ap_handle, _ap_domain_of(origin))):
                await edge_cache_delete(cache_key)
            if not (ap_settings["federate"]
                    and ap_settings["broadcastEvents"]):
                # Opt-out is immediate and destructive: queued public metadata
                # cannot later leak in a stale digest after settings change.
                purge_digests = globals().get(
                    "_ap_purge_repo_digest_queues")
                if callable(purge_digests):
                    await purge_digests(env, owner, repo)
    features = None
    feature_data = data.get("features")
    if isinstance(feature_data, dict):
        current_features = await _repo_features_get(env, owner, repo)
        features = dict(current_features)
        for key in REPO_FEATURE_DEFAULTS:
            if key in feature_data:
                features[key] = bool(feature_data.get(key))
        guarded = [key for key in _branch_protection.CONFIG_KEYS
                   if features.get(key) != current_features.get(key)]
        if guarded and not await _branch_protection.may_configure(
                env, actor, owner, repo):
            return json_response(
                {"error": "not_authorized", "features": guarded},
                status=403)
        if guarded:
            await _audit_sensitive_action(
                env, actor, "repository.protection_settings", "repository",
                str(owner).lower() + "/" + str(repo),
                "success", {key: features.get(key) for key in guarded})
        if features != current_features:
            await d1_run(
                env,
                "INSERT INTO repo_feature_settings (repo_bi, data, updated_at)"
                " VALUES (?,?,?) ON CONFLICT(repo_bi) DO UPDATE SET"
                " data=excluded.data, updated_at=excluded.updated_at",
                await _repo_features_bi(env, owner, repo),
                json.dumps(features, sort_keys=True), int(Date.now()))
    if text_changed:
        # Queue the edit for the owner's desktop node, which writes it into the
        # repo's committed .forkmesh/info.json (the same file the desktop app's
        # own About editor maintains) on its next sync. Latest edit wins.
        about_update = {
            "about": description if description_provided
            else clean_string((first or {}).get("description", "") or "", 240),
            "website": website if website_provided
            else clean_string((first or {}).get("website", "") or "", 240),
            "ts": int(Date.now()),
            "editor": actor,
            "source": "web",
        }
        await d1_run(
            env,
            "INSERT INTO about_inbox (repo_bi, data, queued_at) VALUES (?,?,?)"
            " ON CONFLICT(repo_bi) DO UPDATE SET data=excluded.data,"
            " queued_at=excluded.queued_at",
            media_bi, await encrypt_row(env, about_update), about_update["ts"])
        await _best_effort_inbox_side_effect(
            notify_repo_host(env, owner, repo, "about"))
        await purge_catalog_related_caches()
        await schedule_public_catalog_republish(env, owner, repo)
    if text_changed or media_changed:
        # Tell existing fediverse followers the profile changed (Update
        # activity), so the new logo/banner/description shows up on remote
        # servers now, not whenever their actor cache happens to expire.
        await _best_effort_inbox_side_effect(_ap_broadcast_actor_update(
            env, request, AP_ACTOR_REPO,
            ap.repo_handle(str(owner).lower(), str(repo).lower())))
    if (
        (text_changed or media_changed or settings_changed)
        and str(owner).lower() == "forkmesh"
        and str(repo).lower() == "forkmesh"
    ):
        # These fields are part of the independent dashboard's atomic public
        # replica bundle but not every edit rebuilds a catalog snapshot. Ring
        # the same socket doorbell used by snapshot and star changes.
        try:
            await notify_repo_mirrors(env, "forkmesh", "forkmesh", "replica")
        except BaseException:
            pass
    # Return only the fields the caller just set — never the full decrypted
    # catalog record (which carries private-repo cloneUrl/visibility/stateHash).
    media_rows = await d1_all(
        env, "SELECT kind FROM repo_media WHERE repo_bi=?", media_bi)
    media_kinds = {r.get("kind") for r in (media_rows or [])}
    result = {
        "ok": True,
        "description": description if description_provided
        else clean_string((first or {}).get("description", "") or "", 240),
        "updated": updated,
        "hasLogo": "logo" in media_kinds,
        "hasBanner": "banner" in media_kinds,
        "isPrivate": bool(first and first.get("visibility") == "private"),
    }
    if ap_settings is not None:
        result["fediverse"] = {"settings": ap_settings}
    if features is not None:
        result["features"] = features
    return json_response(result)


# node name -> (resolved human owner, ts). Resolving the account behind a
# headless mirror costs a blind_index plus up to two D1 reads and a decrypt,
# and the /mirrors payload needs it for EVERY mirror in the group — sequentially
# (concurrent tasks are banned on a request path), on every edge-cache miss. A
# claim link changes about never, so a short per-isolate memo keeps a growing
# mirror fleet from turning one poll into dozens of round-trips. Bounded by the
# fleet, with a hard cap as a backstop.
_MIRROR_OWNER_USER_MEMO = {}
MIRROR_OWNER_USER_MEMO_TTL_MS = 5 * 60 * 1000
MIRROR_OWNER_USER_MEMO_MAX = 512


async def _mirror_owner_user(env, node_name, now):
    # "" when the node has no account row or no linked user — memoized too, so
    # an unlinked node is not re-resolved on every poll.
    cached = _MIRROR_OWNER_USER_MEMO.get(node_name)
    if cached is not None and now - cached[1] < MIRROR_OWNER_USER_MEMO_TTL_MS:
        return cached[0]
    try:
        _, node_rec = await _account_row(env, node_name)
    except Exception:
        return ""  # transient read error: retry next request, do not memoize
    if not node_rec:
        owner_user = ""
    elif _account_kind(node_rec) == "user":
        owner_user = node_name
    else:
        owner_user = str(node_rec.get("owner") or "").strip()
    if len(_MIRROR_OWNER_USER_MEMO) >= MIRROR_OWNER_USER_MEMO_MAX:
        _MIRROR_OWNER_USER_MEMO.clear()
    _MIRROR_OWNER_USER_MEMO[node_name] = (owner_user, now)
    return owner_user


async def _mirror_owner_users(env, node_names, now):
    """Resolve a bounded mirror roster in two indexed D1 reads.

    ``_account_row`` intentionally checks ``users`` before ``nodes``. Preserve
    that precedence while avoiding two sequential reads for every mirror in a
    public snapshot. Blind indexes are computed locally; each table lookup is
    chunked below D1's 100-bind ceiling. Transient failures are not memoized.
    """
    names = sorted({
        clean_string(name, MAX_NODE_NAME).lower()
        for name in node_names or []
        if valid_node_name(clean_string(name, MAX_NODE_NAME).lower())
    })
    resolved = {}
    missing = []
    for name in names:
        cached = _MIRROR_OWNER_USER_MEMO.get(name)
        if cached is not None and now - cached[1] < MIRROR_OWNER_USER_MEMO_TTL_MS:
            resolved[name] = cached[0]
        else:
            missing.append(name)
    if not missing:
        return resolved

    bi_to_name = {}
    for name in missing:
        bi_to_name[await blind_index(env, name)] = name
    records = {}
    try:
        bis = sorted(bi_to_name)
        for offset in range(0, len(bis), 80):
            chunk = bis[offset:offset + 80]
            rows = await d1_all(
                env,
                "SELECT user_bi AS name_bi,data FROM users WHERE user_bi IN (%s)"
                % ",".join("?" for _ in chunk),
                *chunk,
            )
            for row in rows or []:
                name = bi_to_name.get(str(row.get("name_bi") or ""))
                if name:
                    records[name] = await decrypt_row(env, row.get("data"))
        unresolved_bis = [
            name_bi for name_bi, name in bi_to_name.items()
            if name not in records
        ]
        for offset in range(0, len(unresolved_bis), 80):
            chunk = unresolved_bis[offset:offset + 80]
            rows = await d1_all(
                env,
                "SELECT node_bi AS name_bi,data FROM nodes WHERE node_bi IN (%s)"
                % ",".join("?" for _ in chunk),
                *chunk,
            )
            for row in rows or []:
                name = bi_to_name.get(str(row.get("name_bi") or ""))
                if name:
                    records[name] = await decrypt_row(env, row.get("data"))
    except Exception:
        # Preserve the original fail-soft presentation contract. A later
        # snapshot retries unresolved rows instead of memoizing a D1 outage.
        return resolved

    for name in missing:
        rec = records.get(name)
        if not rec:
            owner_user = ""
        elif _account_kind(rec) == "user":
            owner_user = name
        else:
            owner_user = str(rec.get("owner") or "").strip()
        if len(_MIRROR_OWNER_USER_MEMO) >= MIRROR_OWNER_USER_MEMO_MAX:
            _MIRROR_OWNER_USER_MEMO.clear()
        _MIRROR_OWNER_USER_MEMO[name] = (owner_user, now)
        resolved[name] = owner_user
    return resolved


async def _bounded_repo_state_history(env, keys):
    """Read at most 100 newest pins for each of at most four repo keys.

    Each UNION arm owns its ORDER BY/LIMIT so the composite key/time index can
    stop after STATE_PIN_HISTORY entries for that key. A global LIMIT or a
    Python slice would bound only returned rows while D1 could still scan every
    historical pin, which is the Free-plan failure this helper prevents.
    """
    selected = []
    seen = set()
    for value in keys or []:
        key = str(value or "")
        if not key or key in seen:
            continue
        seen.add(key)
        selected.append(key)
        if len(selected) >= REPO_STATE_HISTORY_KEY_LIMIT:
            break
    if not selected:
        return {}

    arm = (
        "SELECT key_bi,state_hash FROM ("
        "SELECT key_bi,state_hash,ts FROM repo_state_history "
        "WHERE key_bi=? ORDER BY ts DESC LIMIT ?)"
    )
    params = []
    for key in selected:
        params.extend((key, STATE_PIN_HISTORY))
    rows = await d1_all(env, " UNION ALL ".join(
        arm for _ in selected), *params)

    history = {}
    for row in rows or []:
        key = str(row.get("key_bi") or "")
        if key in seen and len(history.get(key, ())) < STATE_PIN_HISTORY:
            history.setdefault(key, []).append(row.get("state_hash"))
    return history


async def repo_mirrors_handler(env, request, owner, repo):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    privacy_reader = globals().get("_repo_is_private")
    if (callable(privacy_reader)
            and await privacy_reader(env, owner, repo)):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    # Recover the public organization identity after the internal node rewrite.
    public_owner = str(owner or "").strip().lower()
    public_repo = str(repo or "").strip().lower()
    try:
        original_match = REPO_API_PREFIX_RE.match(
            urlparse(str(getattr(request, "url", "") or "")).path)
        requested_owner = safe_segment(
            original_match.group(1)) if original_match else ""
        requested_repo = safe_segment(
            original_match.group(2)) if original_match else ""
        if (
            requested_owner
            and requested_repo == public_repo
            and requested_owner != public_owner
            and await _org_repo_node(
                env, requested_owner, requested_repo) == public_owner
        ):
            public_owner = requested_owner
    except Exception:
        pass
    # Collapse bursts from the repo page and desktop mirror panel.
    cache_key = ("https://forkmesh.internal/api/repo/%s/%s/mirrors"
                 % (quote(public_owner), quote(public_repo)))
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached
    now = int(Date.now())
    # Reuse the per-isolate catalog memo instead of decrypting every row here.
    catalog_rows = [
        row
        for row in await _decrypted_public_catalog(env, now)
        if not row.get("is_private")
        and clean_string(
            (row.get("data") or {}).get("machineName")
            or (row.get("data") or {}).get("owner"), MAX_NODE_NAME).lower()
        not in STATUS_RETIRED_MIRRORS
        and not _is_blocked_catalog_identity(
            env,
            (row.get("data") or {}).get("owner"),
            (row.get("data") or {}).get("name"),
        )
    ]

    # Map the fresh signed HTTPS leases onto this catalog group once.
    endpoint_rows = await d1_all(
        env,
        """SELECT node_bi,node_name,base_url,mirror_url,issued_at,checked_at,
                  latency_ms,region,healthy,integrity,abuse_blocked,forkmesh_verified_at,
                  forkmesh_operations_json,forkmesh_active
             FROM mirror_https_endpoints""",
    )
    endpoint_by_node = {
        clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower(): row
        for row in endpoint_rows or []
        if valid_node_name(
            clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower())
    }
    reachable_seen = {
        node_name: int(row.get("checked_at") or now)
        for node_name, row in endpoint_by_node.items()
        if (
            int(row.get("checked_at") or 0)
            >= now - HTTPS_MIRROR_STATUS_FRESH_MS
            and (
                # Older rows/tests predate signed endpoint attestation. The
                # database migration backfills every security column
                # together, so an entirely absent set is a legacy fresh
                # presence row; a partially populated row must still satisfy
                # every modern integrity gate.
                not any(
                    key in row
                    for key in (
                        "forkmesh_verified_at", "healthy",
                        "forkmesh_active", "integrity", "abuse_blocked",
                    )
                )
                or (
                    int(row.get("forkmesh_verified_at") or 0)
                    >= now - HTTPS_MIRROR_STATUS_FRESH_MS
                    and bool(int(row.get("healthy") or 0))
                    and bool(int(row.get("forkmesh_active") or 0))
                    and str(row.get("integrity") or "") == "ok"
                    and not bool(int(row.get("abuse_blocked") or 0))
                )
            )
        )
    }
    reachable_nodes = set(reachable_seen)
    routing_verified_nodes = {
        node_name
        for node_name, row in endpoint_by_node.items()
        if (
            int(row.get("checked_at") or 0)
            >= now - HTTPS_MIRROR_STATUS_FRESH_MS
            and int(row.get("forkmesh_verified_at") or 0)
            >= now - HTTPS_MIRROR_STATUS_FRESH_MS
            and bool(int(row.get("healthy") or 0))
            and bool(int(row.get("forkmesh_active") or 0))
            and str(row.get("integrity") or "") == "ok"
            and not bool(int(row.get("abuse_blocked") or 0))
        )
    }
    # Resolve once and scope every remaining read to this mirror group.
    selection = repo_mirror_group_selection(owner, repo, catalog_rows)
    if selection is None:
        return json_response({"error": "not_found"}, status=404)
    group_target, group_members, group_public_rows = selection
    group_keys = repo_mirror_group_keys(group_members)
    # A direct check is stored against the canonical repository blind index,
    # but the same logical repository can be viewed through any catalog alias.
    # Read only this already-bounded mirror group's keys and keep the newest
    # verdict for each node. The URL comparison at projection time prevents a
    # replacement origin from inheriting an old verification badge.
    direct_integrity_by_node_bi = {}
    for offset in range(0, len(group_keys), 80):
        key_batch = group_keys[offset:offset + 80]
        direct_rows = await d1_all(
            env,
            """SELECT node_bi,mirror_url,registration_issued_at,reachable,
                      integrity,refs_sha256,checked_at,latency_ms,status_code,reason
                 FROM mirror_repository_integrity
                WHERE repo_bi IN (%s)"""
            % ",".join("?" for _ in key_batch),
            *key_batch,
        )
        for direct_row in direct_rows or []:
            node_bi = str(direct_row.get("node_bi") or "")
            previous = direct_integrity_by_node_bi.get(node_bi)
            if node_bi and (
                previous is None
                or int(direct_row.get("checked_at") or 0)
                > int(previous.get("checked_at") or 0)
            ):
                direct_integrity_by_node_bi[node_bi] = direct_row
    presence = {}
    for row in group_members:
        record = row.get("data") or {}
        node_name = clean_string(
            record.get("machineName") or record.get("owner", ""),
            MAX_NODE_NAME,
        ).lower()
        key = str(row.get("key_bi") or "")
        if key and node_name in reachable_seen:
            presence[key] = reachable_seen[node_name]
    first_hosted = {}
    for offset in range(0, len(group_keys), 80):
        key_batch = group_keys[offset:offset + 80]
        first_rows = await d1_all(
            env,
            "SELECT repo_bi, ts FROM repo_first_hosted"
            " WHERE repo_bi IN (%s)" % ",".join("?" for _ in key_batch),
            *key_batch)
        for r in first_rows or []:
            if r.get("repo_bi"):
                first_hosted[str(r.get("repo_bi"))] = int(r.get("ts") or 0)
    # Load recent owner-attested state pins for the clone integrity verdict.
    linked_row = await d1_first(
        env,
        "SELECT 1 AS linked FROM org_repos "
        "WHERE node_owner=? AND repo=? LIMIT 1",
        str(owner or "").strip().lower(),
        str(repo or "").strip().lower(),
    )
    group_target_key = str(group_target.get("key_bi") or "")
    linked_canonical = bool(
        linked_row
        and str((group_target.get("data") or {}).get("source") or "")
        .strip().lower() == "remote-clone"
    )
    if linked_canonical:
        # build_repo_mirrors_payload consumes only the explicitly appointed
        # remote target's history in canonical-link mode.
        history_keys = [group_target_key] if group_target_key else []
    else:
        history_keys = repo_mirror_pin_history_keys(
            group_members,
            group_public_rows,
            group_target_key,
        )
    history = await _bounded_repo_state_history(env, history_keys)
    payload = build_repo_mirrors_payload(
        owner,
        repo,
        catalog_rows,
        presence,
        first_hosted,
        now,
        HOST_PRESENCE_STALE_MS,
        5 * 1000,
        history,
        linked_canonical=bool(linked_row),
        reachable_nodes=reachable_nodes,
        routing_verified_nodes=routing_verified_nodes,
        selection=selection,
    )
    if payload is None:
        return json_response({"error": "not_found"}, status=404)
    payload["owner"] = public_owner
    payload["repo"] = public_repo

    # The public organization route can be backed by a mirror generation whose
    # historical root no longer groups with the working-copy publication. The
    # source was consequently reduced to a three-field banner while every
    # replica got a full node row. Find the source machine by its signed
    # machineName (falling back to its catalog owner) and carry the same bounded
    # facts in sourceOfTruth. It remains outside routing and clone-availability
    # decisions when its root differs; this is display/observability data only.
    source_row = None
    source_fallback = None
    for candidate in catalog_rows:
        record = candidate.get("data") or {}
        if (
            str(record.get("name") or "").strip().lower() != public_repo
            or str(record.get("source") or "local-node").strip().lower()
            != "local-node"
        ):
            continue
        machine = str(record.get("machineName") or "").strip().lower()
        publisher = str(record.get("owner") or "").strip().lower()
        if machine == public_owner:
            source_row = candidate
            break
        if publisher == public_owner:
            source_fallback = candidate
    source_row = source_row or source_fallback
    source_of_truth = {
        "owner": public_owner,
        "repo": public_repo,
        "kind": "working-copy",
        "isSourceOfTruth": True,
        "referenceForMirrors": False,
    }
    if source_row is not None:
        source_payload = build_repo_mirrors_payload(
            str((source_row.get("data") or {}).get("owner") or public_owner),
            public_repo,
            catalog_rows,
            presence,
            first_hosted,
            now,
            HOST_PRESENCE_STALE_MS,
            5 * 1000,
            history,
            selection=(source_row, [source_row], catalog_rows),
        )
        source_nodes = (source_payload or {}).get("mirrors") or []
        if source_nodes:
            source_of_truth.update(source_nodes[0])
            source_of_truth["owner"] = public_owner
            source_of_truth["repo"] = public_repo
            source_of_truth["kind"] = "working-copy"
            source_of_truth["isSourceOfTruth"] = True
            source_of_truth["referenceForMirrors"] = (
                repo_mirror_group_key(source_row.get("data") or {})
                == payload.get("groupKey")
            )
            # Being the authority does not imply that the browser/clone router
            # can reach this desktop directly.
            source_of_truth["cloneAvailable"] = False
    payload["sourceOfTruth"] = source_of_truth
    # Where the repository has reached, in the shared state model every
    # client renders (www/docs/sync-status.md).
    payload["syncStatus"] = mirrors_payload_status(payload)
    # Overlay router-counted traffic on the legacy publisher tallies.
    serve_counts = {}
    try:
        # A logical repository can be reached through several public owners:
        # its organization URL plus each mirror's catalog URL. The router
        # deliberately stamps the owner that appeared in the routed request,
        # so filtering counters to only the currently requested owner hides
        # real traffic served through every other alias (and made a healthy
        # mirror look idle in the Mirrors table). Aggregate the bounded set of
        # aliases that this already-verified mirror group exposes, while still
        # excluding unrelated repositories that merely share its name.
        serve_owners = {
            str(public_owner or "").strip().lower(),
            str(owner or "").strip().lower(),
        }
        serve_owners.update(
            str(mirror.get("node") or "").strip().lower()
            for mirror in payload.get("mirrors", [])
        )
        serve_owners.discard("")
        owner_placeholders = ",".join("?" for _ in serve_owners)
        count_rows = await d1_all(
            env,
            "SELECT node_name,SUM(clones) AS clones,"
            " SUM(website) AS website FROM mirror_serve_counters"
            " WHERE repo=? AND owner IN (%s) GROUP BY node_name"
            % owner_placeholders,
            str(repo or "").strip().lower(),
            *sorted(serve_owners),
        )
        for row in count_rows:
            name = str(row.get("node_name") or "").strip().lower()
            if name:
                serve_counts[name] = (
                    max(0, int(row.get("clones") or 0)),
                    max(0, int(row.get("website") or 0)),
                )
    except Exception:
        serve_counts = {}
    # Owner column: a headless mirror's catalog record carries no ownerUser of
    # its own, but the node account may be claim-linked to a user (adhoc #53:
    # the node record's `owner` field names the linked user). Resolve that link
    # here so every surface — web repo page and the desktop Mirror nodes panel —
    # shows the human owner without each publisher having to know it.
    mirrors = payload.get("mirrors", [])
    owner_users = await _mirror_owner_users(
        env,
        [
            str(mirror.get("node") or "").strip().lower()
            for mirror in mirrors
            if not mirror.get("ownerUser")
        ],
        now,
    )
    for mirror in mirrors:
        node_name = str(mirror.get("node") or "").strip().lower()
        # The router counts for every node it routes to, so each served node
        # gets a concrete figure: counted-so-far (zero included) plus whatever
        # positive legacy tally the node still publishes. Keeping the record's
        # -1 "never advertised" sentinel when no counter row existed yet left
        # nodes that predate the counters — the SSH-fed headless mirrors — as a
        # permanent em-dash even though the router was already counting them.
        counted = serve_counts.get(node_name, (0, 0))
        legacy_clones = mirror.get("clonesServed")
        legacy_website = mirror.get("websiteServed")
        mirror["clonesServed"] = (
            legacy_clones if isinstance(legacy_clones, int)
            and legacy_clones > 0 else 0) + counted[0]
        mirror["websiteServed"] = (
            legacy_website if isinstance(legacy_website, int)
            and legacy_website > 0 else 0) + counted[1]
        endpoint = endpoint_by_node.get(node_name) or {}
        try:
            operations = json.loads(
                str(endpoint.get("forkmesh_operations_json") or "[]"))
        except Exception:
            operations = []
        if not isinstance(operations, list):
            operations = []
        mirror_origin = str(endpoint.get("mirror_url") or "")
        mirror_url = (
            https_routing.direct_repository_url(
                mirror_origin, public_owner, public_repo)
            if mirror_origin else ""
        )
        if mirror_origin:
            direct_fields = _mirror_direct_integrity_fields(
                node_name,
                mirror_origin,
                public_owner,
                public_repo,
                direct_integrity_by_node_bi.get(
                    str(endpoint.get("node_bi") or "")),
                registration_issued_at=int(endpoint.get("issued_at") or 0),
            )
        else:
            direct_fields = {
                "directVerified": False,
                "directReachable": False,
                "directIntegrity": "unknown",
                "directRefsSha256": "",
                "directCheckedAt": 0,
                "directLatencyMs": 0,
                "directStatus": 0,
                "directReason": "mirror_url_not_registered",
            }
        # `node` and `mirrorUrl` already come from the signed catalog/endpoint
        # merge above. Only overlay the repository-scoped check metadata here.
        direct_fields.pop("node", None)
        direct_fields.pop("mirrorUrl", None)
        mirror.update({
            "endpoint": str(endpoint.get("base_url") or ""),
            "checkedAt": int(endpoint.get("checked_at") or 0),
            "latencyMs": max(0, int(endpoint.get("latency_ms") or 0)),
            "region": clean_string(endpoint.get("region", ""), 40),
            "endpointHealthy": bool(int(endpoint.get("healthy") or 0)),
            "endpointIntegrity": str(
                endpoint.get("integrity") or "unknown"),
            "endpointFresh": bool(node_name in reachable_seen),
            "abuseBlocked": bool(int(endpoint.get("abuse_blocked") or 0)),
            "operations": [
                clean_string(value, 40)
                for value in operations[:32]
                if isinstance(value, str)
            ],
            **direct_fields,
        })
        if mirror_url:
            mirror["mirrorUrl"] = mirror_url
        if mirror.get("ownerUser") or not node_name:
            continue
        owner_user = owner_users.get(node_name, "")
        if owner_user:
            mirror["ownerUser"] = owner_user
    # Availability proof and risk (www/docs/availability-proof.md). Computed
    # last because it reads the signed endpoint receipts and direct clone
    # probes overlaid above; the report reproduces from this same payload.
    payload["availability"] = mirrors_payload_availability(payload)
    # Node cabinets and the repository Mirrors panel poll while visible. Keep a
    # tiny shared edge window to collapse bursts without leaving an integrity
    # transition or completed sync stuck on screen for ten seconds.
    response = json_response(payload, cache_seconds=3)
    await edge_cache_put(cache_key, response)
    return response


# --- Release download counts -------------------------------------------------

async def record_release_download(env, repo_bi, sha256, ua=""):
    """Log one completed release-asset download. Best-effort; never raises —
    called fire-and-forget from the streaming DO response, so a D1 hiccup must
    never fail or delay the download itself."""
    try:
        await ensure_schema(env)
        await d1_run(
            env,
            "INSERT INTO release_downloads (repo_bi, sha256, ts, ua) VALUES (?, ?, ?, ?)",
            repo_bi, sha256, int(Date.now()), ua,
        )
    except Exception:
        pass


async def release_download_counts(env, repo_bi):
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT sha256, COUNT(*) AS n FROM release_downloads "
        "WHERE repo_bi=? GROUP BY sha256",
        repo_bi,
    )
    return {str(r.get("sha256")): int(r.get("n") or 0) for r in rows if r.get("sha256")}


async def release_downloads_handler(env, request, owner, repo):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    repo_bi = await blind_index(env, owner + "/" + repo)
    counts = await release_download_counts(env, repo_bi)
    return json_response({"ok": True, "counts": counts})


# --- Public waitlist (waitlist table) ---------------------------------------

def _waitlist_normalize_email(value):
    email = str(value or "").strip().lower()
    if len(email) > 254 or not _WAITLIST_EMAIL_RE.fullmatch(email):
        return ""
    return email


async def waitlist_handler(env, request):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if not isinstance(data, dict):
        return json_response({"error": "invalid_json"}, status=400)
    email = _waitlist_normalize_email(data.get("email", ""))
    if not email:
        return json_response({"error": "valid_email_required"}, status=400)
    source = clean_string(data.get("source", "features"), MAX_WAITLIST_FIELD)
    path = clean_string(data.get("path", ""), MAX_WAITLIST_FIELD)
    user_agent = clean_string(request.headers.get("user-agent") or "", 512)
    await d1_run(
        env,
        """INSERT OR IGNORE INTO waitlist
           (email, created_at, source, path, user_agent)
           VALUES (?,?,?,?,?)""",
        email, int(Date.now()), source, path, user_agent,
    )
    # Attribution funnel: managed-plan interest. The email survives only as
    # its blind index inside the event metadata, which is what lets the
    # admin console later mark the discovery call accepted on this session.
    try:
        await _attribution.emit_from_request(
            env, request, "managed_waitlist_submitted",
            {"source": source, "email_bi": await blind_index(env, email)})
    except Exception:
        pass
    return json_response({"ok": True}, status=201)


# --- Accounts (users/nodes tables) — name + solana + password + TOTP --------

def _account_kind(rec):
    rec = rec or {}
    kind = clean_string(rec.get("kind", ""), 16).strip().lower()
    if kind in ("user", "node"):
        return kind
    return "user" if rec.get("pass_hash") else "node"


def _is_public_roster_member(rec):
    # The one predicate for "counts as a member" everywhere the site shows a
    # member figure (site-wide chat badge, World campfire HUD, accounts
    # directory). Keeping this in one place is the fix for adhoc #1617: the
    # chat badge and the World roster used to apply different filters over
    # the same `users` table and could disagree by a few accounts.
    return bool(rec) and (
        _account_kind(rec) == "user"
        and rec.get("status") == "active"
        and not rec.get("profile_private"))


def _account_has_legacy_wallet_key(rec):
    # Compatibility detector only. A historical account blob can still contain
    # a donation wallet seed until the offline migration scrubs it. No active
    # Worker write may copy that seed into a new ciphertext.
    return isinstance(rec, dict) and bool(rec.get("donation_secret"))


async def _mirror_account_identity_tables(env, name_bi, rec, email_bi=None,
                                          ip_bi=None, is_admin=None,
                                          touch_seen=False):
    # Authoritative store for account records: the physical users/nodes tables
    # (migration 0025). The legacy accounts table these once mirrored was
    # dropped by migration 0042; old clients keep using /api/accounts/* but
    # every record lives here now, keyed by blind_index(name) on both tables.
    if _account_has_legacy_wallet_key(rec):
        raise RuntimeError("legacy_custody_migration_required")
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    if not name:
        return
    kind = _account_kind(rec)
    now = int(Date.now())
    if kind == "user":
        if email_bi is None and rec.get("email"):
            email_bi = await blind_index(env, clean_string(rec.get("email", ""), 254).lower())
        if js_nullish(ip_bi):
            ip_bi = ""
        # Only the blind index of the id is stored, matching how email is
        # handled -- no plaintext Discord identifier lands in a column. A
        # record that carries no discordId leaves any existing link alone (see
        # the COALESCE below), so an ordinary profile save cannot unlink an
        # account that the sync tool linked.
        discord_bi = None
        discord_id = _clean_discord_id(rec.get("discordId", ""))
        if discord_id:
            discord_bi = await blind_index(env, discord_id)
        enc_user = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT INTO users (user_bi, data, email_bi, username, is_admin,
                                  ip_bi, discord_bi)
               VALUES (?,?,?,?,?,?,?)
               ON CONFLICT(user_bi) DO UPDATE SET
                 data=excluded.data,
                 email_bi=COALESCE(excluded.email_bi, users.email_bi),
                 username=excluded.username,
                 is_admin=CASE WHEN ? THEN excluded.is_admin ELSE users.is_admin END,
                 ip_bi=COALESCE(NULLIF(excluded.ip_bi, ''), users.ip_bi),
                 discord_bi=COALESCE(excluded.discord_bi, users.discord_bi)""",
            name_bi, enc_user, email_bi, name,
            int(is_admin or 0), ip_bi, discord_bi,
            1 if is_admin is not None else 0)
        if discord_id:
            # A link is a verified account-integration event. The public
            # roster still derives the sleeve mark from discord_bi for links
            # created before badges existed; this persists it for new links.
            try:
                await _award_badge(env, name, name_bi, "discord")
            except Exception:
                pass
    else:
        await d1_run(env, "DELETE FROM users WHERE user_bi=?", name_bi)

    pubkey = clean_string(rec.get("pubkey", ""), 120)
    if pubkey or kind == "node":
        # A node-kind record without a pubkey is a keyless reservation (name
        # parked before the key binds at finalize); it must still persist here
        # now that the nodes table is the only store for node records.
        owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
        if not owner and kind == "user":
            owner = name
        owner_bi = await blind_index(env, owner) if owner else None
        enc_node = await encrypt_row(env, rec)
        last_seen = now if touch_seen else 0
        await d1_run(
            env,
            """INSERT INTO nodes (node_bi, user_bi, pubkey, data, name, last_seen)
               VALUES (?,?,?,?,?,?)
               ON CONFLICT(node_bi) DO UPDATE SET
                 user_bi=excluded.user_bi, pubkey=excluded.pubkey,
                 data=excluded.data, name=excluded.name,
                 last_seen=CASE WHEN ? THEN
                   MAX(nodes.last_seen, excluded.last_seen)
                   ELSE nodes.last_seen END""",
            name_bi, owner_bi, pubkey, enc_node, name, last_seen,
            1 if touch_seen else 0)
    else:
        await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", name_bi)


async def touch_registered_node(env, name_bi, rec=None):
    # A real node activity signal (registration/finalize, signed heartbeat,
    # desktop login, or host WebSocket connect). Plain account reads repair the
    # users/nodes mirror but deliberately do NOT refresh this timestamp; otherwise
    # merely browsing stale profiles would keep abandoned nodes alive forever.
    if not name_bi:
        return
    if (rec and not _account_has_legacy_wallet_key(rec)
            and clean_string(rec.get("pubkey", ""), 120)
            and name_bi not in _MIRRORED_ACCOUNT_BIS):
        # First touch this isolate: full mirror repair (also stamps last_seen).
        await _mirror_account_identity_tables(
            env, name_bi, rec, touch_seen=True)
        if len(_MIRRORED_ACCOUNT_BIS) < 10000:
            _MIRRORED_ACCOUNT_BIS.add(name_bi)
        return
    # Mirror already repaired this isolate (or no rec): the 1-statement
    # last_seen stamp is all a heartbeat/connect needs — the full mirror
    # rewrite (2 encrypts + 2 upserts) on every beat helped melt the free
    # plan on 2026-07-11.
    await d1_run(
        env, "UPDATE nodes SET last_seen=? WHERE node_bi=?",
        int(Date.now()), name_bi)


async def _account_identity_rec_by_bi(env, name_bi):
    # Authoritative-store lookup by blind_index(name): user_bi and node_bi are
    # both blind_index(name), so one key resolves either table. Returns the
    # decrypted record, or None.
    if not name_bi:
        return None
    row = await d1_first(env, "SELECT data FROM users WHERE user_bi=?", name_bi)
    if not row:
        row = await d1_first(env, "SELECT data FROM nodes WHERE node_bi=?", name_bi)
    if not row:
        return None
    return await decrypt_row(env, row.get("data"))


# name_bis whose users/nodes rows this isolate already refreshed via
# touch_registered_node's full rewrite. The rewrite costs 1-2 encrypt_row +
# 2 upserts — repeating it on every activity signal was a top contributor
# to the 2026-07-11 free-plan CPU overload, so after the first touch a
# heartbeat only stamps last_seen. Write paths call
# _mirror_account_identity_tables directly (via _save_account), so a stale
# entry here can never mask a real update; a recycled isolate simply
# rewrites once more.
_MIRRORED_ACCOUNT_BIS = set()


async def _account_row(env, name):
    name_bi = await blind_index(env, name)
    return name_bi, await _account_identity_rec_by_bi(env, name_bi)


async def _owner_pubkey(env, owner):
    _, rec = await _account_row(env, owner)
    return rec.get("pubkey", "") if rec else ""


async def _account_row_by_pubkey(env, pubkey):
    node = await d1_first(env, "SELECT node_bi, data FROM nodes WHERE pubkey=?", pubkey)
    if node:
        rec = await decrypt_row(env, node.get("data"))
        if rec:
            return node.get("node_bi"), rec
    return None, None


async def _resolve_claimable_node(env, raw_id):
    # A claim-node "node ID" may be the account's chosen name (the common
    # case) or its Ed25519 public key, which the desktop app's own profile
    # card labels "Node ID" (issue #351). Returns (node_bi, node_rec,
    # node_name) or (None, None, "") when neither resolves.
    candidate = (raw_id or "").strip()
    name = candidate.lower()
    if valid_node_name(name):
        node_bi, node_rec = await _account_row(env, name)
        if node_rec:
            return node_bi, node_rec, name
    if valid_node_pubkey(candidate):
        node_bi, node_rec = await _account_row_by_pubkey(env, candidate)
        if node_rec:
            return node_bi, node_rec, node_rec.get("name", "")
    return None, None, ""


def _ts_ok(ts):
    try:
        return abs(int(Date.now()) - int(ts)) <= LOGIN_MAX_SKEW_MS
    except (TypeError, ValueError):
        return False


async def verify_view_token(env, owner, repo, ts, sig):
    # Only the owner account's key holder can browse/clone a private repo.
    if not owner or not repo or not sig or not _ts_ok(ts):
        return False
    pubkey = await _owner_pubkey(env, owner)
    if not pubkey:
        return False
    canonical = ("forkmesh-view-v1\n" + owner + "\n" + repo + "\n" + str(ts)).encode()
    return await ed25519_verify(pubkey, sig, canonical)


async def verify_push_token(env, owner, repo, ts, sig):
    # Write gate for git push over the relay (issue #358): only the owner
    # account's registered key may run receive-pack against the served mirror
    # (collaborator keys are a later extension). It uses a fresh timestamp and
    # Ed25519 over an explicit canonical string with a distinct prefix. This
    # timestamp-signed binding is deliberately the
    # simplest thing that stays in the existing trust model (no server-side nonce
    # state); the freshness window is the short-lived element.
    if not owner or not repo or not sig or not _ts_ok(ts):
        return False
    pubkey = await _owner_pubkey(env, owner)
    if not pubkey:
        return False
    canonical = ("forkmesh-push-v1\n" + owner + "\n" + repo + "\n" + str(ts)).encode()
    return await ed25519_verify(pubkey, sig, canonical)


async def _basic_auth_push_ok(env, owner, repo, request):
    # git supplies the push token in HTTP Basic auth (password="<ts>.<sig>"),
    # from the push URL or a credential helper. The username selects whose key
    # signed it; only the owner may push for now (collaborator keys later).
    header = request.headers.get("authorization") or ""
    if not header.lower().startswith("basic "):
        return False
    try:
        decoded = base64.b64decode(header[6:].strip()).decode("utf-8", "replace")
    except Exception:
        return False
    username, _, password = decoded.partition(":")
    ts, _, sig = password.partition(".")
    if not ts or not sig:
        return False
    if username and username != owner:
        # A non-owner username selects the org-team path (issue #388): the
        # pusher signs with their OWN key and must hold write+ permission on
        # the repo through an organization it is linked under.
        return await verify_org_push_token(env, username, owner, repo, ts, sig)
    return await verify_push_token(env, owner, repo, ts, sig)


async def verify_catalog_view_token(env, viewer, ts, sig):
    # Listing gate: lets a logged-in owner additionally see their OWN private repos
    # in the catalog, which is otherwise public-only. Not bound to a single repo
    # (it authorizes a listing, not one clone) and uses a distinct canonical string
    # so a per-repo forkmesh-view-v1 token can't be replayed as a listing token and
    # vice versa. Returns the viewer's account name on success, "" otherwise — an
    # unknown/garbled viewer simply falls back to the public-only catalog.
    if not viewer or not sig or not _ts_ok(ts):
        return ""
    pubkey = await _owner_pubkey(env, viewer)
    if not pubkey:
        return ""
    canonical = ("forkmesh-catalog-view-v1\n" + viewer + "\n" + str(ts)).encode()
    if await ed25519_verify(pubkey, sig, canonical):
        return viewer
    return ""


async def _repo_shared_with(env, owner, repo, grantee):
    # True when the owner has shared `owner/repo` with the `grantee` account
    # (issue #9). repo_bi is keyed the same way as repositories.key_bi so it joins
    # a private repo to its collaborator rows. Best-effort: any error => not shared
    # (fail closed; a transient DB hiccup must never grant access it shouldn't).
    if not owner or not repo or not grantee:
        return False
    try:
        await ensure_schema(env)
        repo_bi = await blind_index(env, owner + "/" + repo)
        grantee_bi = await blind_index(env, grantee)
        row = await d1_first(
            env,
            "SELECT 1 AS one FROM repo_shares WHERE repo_bi=? AND grantee_bi=?",
            repo_bi, grantee_bi)
        return bool(row)
    except Exception:
        return False


async def verify_share_view_token(env, viewer, owner, repo, ts, sig):
    # Read gate for a private repo shared with a DIFFERENT account (issue #9). The
    # grantee signs with their OWN key — the owner never hands out its key — and
    # access is granted only while the owner keeps an active repo_shares row for
    # them. Distinct canonical prefix so an owner forkmesh-view-v1 token, a host
    # token, or a catalog-listing token can never be replayed here, and vice versa.
    if not viewer or not owner or not repo or not sig or not _ts_ok(ts):
        return False
    if viewer == owner:
        return False  # the owner authenticates via verify_view_token, not here
    pubkey = await _owner_pubkey(env, viewer)
    if not pubkey:
        return False
    canonical = ("forkmesh-share-view-v1\n" + viewer + "\n" + owner + "\n" +
                 repo + "\n" + str(ts)).encode()
    if not await ed25519_verify(pubkey, sig, canonical):
        return False
    return await _repo_shared_with(env, owner, repo, viewer)


# "Not publicly served" is the answer the open web asks for most, and the one
# that cannot change between two requests a second apart: crawlers, stale links
# and polling clients walk /api/repo/<owner>/<repo>/... for names this relay
# has never held, and every one of those probes paid a blind index plus a D1
# read before its 404 (adhoc #1642). Only the CLOSED answer is memoized, so a
# public repository is never served from a cached verdict; publishing clears
# the entry inline for same-isolate read-your-writes, and the TTL is short
# enough that a publish from another isolate is visible within one page load.
# Per-isolate and bounded, mirroring _ORG_ALIAS_MEMO.
_REPO_CLOSED_MEMO = {}
REPO_CLOSED_MEMO_TTL_MS = 5 * 1000
REPO_CLOSED_MEMO_MAX = 512


def _forget_repo_closed(owner, repo):
    """Drop a memoized "not publicly served" verdict after a catalog write."""
    _REPO_CLOSED_MEMO.pop(
        str(owner or "").strip().lower() + "/"
        + str(repo or "").strip().lower(), None)


async def _repo_is_private(env, owner, repo):
    # Anonymous serving is permitted only by an explicit public catalog row.
    # Missing/malformed records and database failures fail closed. This makes a
    # private repository indistinguishable from an unpublished repository to
    # unauthenticated callers and prevents an outage from becoming a data leak.
    #
    # The memo above rides in front of that read. It is resolved through
    # globals() like the optional helpers below, so the AST-extraction test
    # harnesses — which lift this function alone into a bare namespace — simply
    # run uncached, exactly as they did before.
    memo = globals().get("_REPO_CLOSED_MEMO")
    key = (str(owner or "").strip().lower() + "/"
           + str(repo or "").strip().lower())
    now = 0
    if memo is not None:
        now = int(Date.now())
        closed_at = memo.get(key)
        if (closed_at is not None
                and now - closed_at
                < globals().get("REPO_CLOSED_MEMO_TTL_MS", 5000)):
            return True

    async def resolve():
        await ensure_schema(env)
        key_bi = await blind_index(env, owner + "/" + repo)
        row = await d1_first(
            env,
            "SELECT is_private, data FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row:
            hosted_resolver = globals().get(
                "_hosted_repository_import_route")
            hosted_route = (
                await hosted_resolver(env, owner, repo)
                if callable(hosted_resolver) else None)
            if hosted_route and tuple(hosted_route) != (owner, repo):
                return await _repo_is_private(
                    env, hosted_route[0], hosted_route[1])
            return True
        if int(row.get("is_private", 1) or 0) != 0:
            return True
        # Migration 0011 historically defaulted existing rows to public.
        # Validate that the signed encrypted record itself explicitly says
        # public before serving; an old row with missing/garbled visibility is
        # hidden until its owner republishes it under the v2 catalog contract.
        decryptor = globals().get("decrypt_row")
        if callable(decryptor):
            record = await decryptor(env, row.get("data"))
            return not record or record.get("visibility") != "public"
        # Isolated compatibility harnesses may omit decrypt_row. Production
        # always has it, so this fallback cannot reopen the deployed boundary.
        return False

    try:
        closed = await resolve()
    except Exception:
        return True
    if memo is not None:
        if closed:
            if len(memo) >= globals().get("REPO_CLOSED_MEMO_MAX", 512):
                memo.clear()
            memo[key] = now
        else:
            memo.pop(key, None)
    return closed


async def _repository_access_context(
        env, request, owner, repo, viewer=""):
    """Resolve a repository only after applying its normal read boundary.

    Public records must be explicitly public in both the plaintext routing flag
    and the encrypted catalog record. Private/malformed records are gated by
    blind-index owner/share checks before decryption. Missing and unauthorized
    callers both receive ``None`` so named control endpoints cannot become
    repository-existence or decryption oracles.
    """
    try:
        await ensure_schema(env)
        owner = safe_segment(owner)
        repo = safe_segment(repo)
        if not owner or not repo:
            return None
        repo_bi = await blind_index(env, owner + "/" + repo)
        row = await d1_first(
            env,
            "SELECT owner_bi, is_private, data FROM repositories "
            "WHERE key_bi=?",
            repo_bi,
        )
        if not row:
            return None
        plaintext_value = row.get("is_private")
        try:
            plaintext_private = (
                plaintext_value is None
                or str(plaintext_value).strip() == ""
                or int(plaintext_value) != 0
            )
        except (TypeError, ValueError):
            plaintext_private = True

        actor = clean_string(viewer, MAX_NODE_NAME).strip().lower()
        if not actor:
            actor = await _authed_account_name(env, request)
        authorized = False

        async def authorize_private():
            if actor and (
                await _account_owns_node(env, actor, owner)
                or await _repo_shared_with(env, owner, repo, actor)
            ):
                return True
            return await _basic_auth_view_ok(env, owner, repo, request)

        # owner_bi is a non-reversible blind index. Check it before decrypting a
        # plaintext-private row so a corrupt/mismatched row remains invisible.
        if plaintext_private:
            expected_owner_bi = await blind_index(env, owner)
            if str(row.get("owner_bi") or "") != str(expected_owner_bi):
                return None
            authorized = await authorize_private()
            if not authorized:
                return None

        record = await decrypt_row(env, row.get("data"))
        if not _catalog_record_matches_identity(record, owner, repo):
            return None
        signed_public = record.get("visibility") == "public"
        explicit_public = signed_public and not plaintext_private
        if not explicit_public:
            if not authorized:
                authorized = await authorize_private()
            if not authorized:
                return None
        return {
            "repoBi": repo_bi,
            "visibility": "public" if explicit_public else "private",
            "record": record,
            "viewer": actor,
        }
    except Exception:
        return None


async def _basic_auth_view_ok(env, owner, repo, request):
    # Git smart-HTTP carries the view token in HTTP Basic auth (password=
    # "<ts>.<sig>"), which git supplies from the clone URL or a credential helper.
    # The username selects whose key signed the token: the owner itself
    # (forkmesh-view-v1) or a collaborator the repo was shared with, who signs
    # with their OWN key (forkmesh-share-view-v1, issue #9).
    header = request.headers.get("authorization") or ""
    if not header.lower().startswith("basic "):
        return False
    try:
        decoded = base64.b64decode(header[6:].strip()).decode("utf-8", "replace")
    except Exception:
        return False
    username, _, password = decoded.partition(":")
    ts, _, sig = password.partition(".")
    if not ts or not sig:
        return False
    if username and username != owner:
        return await verify_share_view_token(env, username, owner, repo, ts, sig)
    return await verify_view_token(env, owner, repo, ts, sig)


def _basic_auth_challenge():
    return Response(
        "Authentication required.",
        status=401,
        headers={"WWW-Authenticate": 'Basic realm="forkmesh"'},
    )


async def _save_account(env, name_bi, rec, email_bi=None, ip_bi=None):
    # Persist the encrypted record into the users/nodes tables; pass email_bi to
    # (re)index for email login and ip_bi to (re)index the signup IP for
    # duplicate detection. Both are only written when supplied, so a caller that
    # doesn't have them in hand never clobbers a
    # value set at finalize. is_admin is never written here, so a value set
    # directly in the DB survives ordinary account updates.
    await _mirror_account_identity_tables(
        env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi)


async def _save_account_full(env, name_bi, rec, email_bi=None, ip_bi=None,
                             is_admin=0):
    await _mirror_account_identity_tables(
        env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi,
        is_admin=is_admin)


async def _move_repo_shares(env, old_repo_bi, new_repo_bi, new_owner, repo):
    rows = await d1_all(
        env, "SELECT grantee_bi, data, ts FROM repo_shares WHERE repo_bi=?",
        old_repo_bi)
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        rec["owner"] = new_owner
        rec["repo"] = repo
        enc = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT OR REPLACE INTO repo_shares
               (repo_bi, grantee_bi, data, ts) VALUES (?,?,?,?)""",
            new_repo_bi, row.get("grantee_bi"), enc, row.get("ts", 0))
    await d1_run(env, "DELETE FROM repo_shares WHERE repo_bi=?", old_repo_bi)


async def _move_bounties_namespace(env, old_owner, new_owner, repo,
                                   apply_changes=True):
    rows = await d1_all(env, "SELECT bounty_bi, data FROM issue_bounty")
    moves = []
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        if (rec.get("owner") != old_owner or rec.get("repo") != repo):
            continue
        # Namespace migration re-encrypts the whole record. Refuse to do that
        # while a historical escrow key is still present; the offline custody
        # migration must export, reconcile, and scrub it first.
        if rec.get("secret") or not rec.get("legacy_custody_migrated_at"):
            return "legacy_custody_migration_required"
        try:
            number = int(rec.get("number", 0))
        except (TypeError, ValueError):
            number = 0
        if number <= 0:
            continue
        new_bi = await _bounty_bi(env, new_owner, repo, number,
                                  rec.get("kind", ""))
        old_bi = row.get("bounty_bi")
        if new_bi != old_bi:
            existing = await d1_first(
                env, "SELECT bounty_bi FROM issue_bounty WHERE bounty_bi=?",
                new_bi)
            if existing:
                return "repo_namespace_conflict"
        moves.append((old_bi, new_bi, rec))
    if not apply_changes:
        return ""
    for old_bi, new_bi, rec in moves:
        rec["owner"] = new_owner
        rec["repo"] = repo
        enc = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT INTO issue_bounty (bounty_bi, data) VALUES (?,?)
               ON CONFLICT(bounty_bi) DO UPDATE SET data=excluded.data""",
            new_bi, enc)
        if new_bi != old_bi:
            await d1_run(
                env, "DELETE FROM issue_bounty WHERE bounty_bi=?", old_bi)
    return ""


async def _move_chat_history_namespace(env, old_owner, new_owner, repo):
    old_prefix = "repo:" + old_owner + "/" + repo + ":room:"
    new_prefix = "repo:" + new_owner + "/" + repo + ":room:"
    rows = await d1_all(
        env,
        "SELECT room_key, msg_id, ts, body FROM chat_history WHERE room_key LIKE ?",
        old_prefix + "%")
    for row in rows:
        old_key = row.get("room_key", "")
        new_key = new_prefix + old_key[len(old_prefix):]
        await d1_run(
            env,
            """INSERT OR REPLACE INTO chat_history
               (room_key, msg_id, ts, body) VALUES (?,?,?,?)""",
            new_key, row.get("msg_id"), row.get("ts", 0), row.get("body", ""))
        await d1_run(
            env,
            "DELETE FROM chat_history WHERE room_key=? AND msg_id=?",
            old_key, row.get("msg_id"))


async def _delete_chat_channel_memberships(env, member_bi):
    rows = await d1_all(
        env,
        "SELECT m.channel_id,c.key_version "
        "FROM chat_channel_members m JOIN chat_channels c "
        "ON c.channel_id=m.channel_id WHERE m.member_bi=?",
        member_bi,
    )
    if not rows:
        return
    await d1_run(
        env, "DELETE FROM chat_channel_members WHERE member_bi=?", member_bi)
    for row in rows:
        await _revoke_chat_channel_room(
            env,
            row.get("channel_id", ""),
            int(row.get("key_version") or 1),
        )
        await _revoke_office_channel_room(
            env,
            row.get("channel_id", ""),
            int(row.get("key_version") or 1),
        )


async def _delete_chat_channel_invites(env, creator_bi):
    await d1_run(
        env,
        "DELETE FROM chat_channel_invites WHERE created_by_bi=?",
        creator_bi,
    )


async def _delete_chat_direct_conversations(env, participant_bi):
    rows = await d1_all(
        env,
        "SELECT c.conversation_id,c.key_version "
        "FROM chat_direct_participants p "
        "JOIN chat_direct_conversations c "
        "ON c.conversation_id=p.conversation_id "
        "WHERE p.participant_bi=?",
        participant_bi,
    )
    for row in rows:
        conversation_id = str(row.get("conversation_id") or "")
        key_version = int(row.get("key_version") or 1)
        if not conversation_id:
            continue
        await _revoke_chat_direct_room(
            env, conversation_id, key_version)
        await d1_run(
            env,
            "DELETE FROM chat_direct_participants WHERE conversation_id=?",
            conversation_id,
        )
        await d1_run(
            env,
            "DELETE FROM chat_direct_conversations WHERE conversation_id=?",
            conversation_id,
        )
        await d1_run(
            env,
            "DELETE FROM chat_history WHERE room_key=?",
            "chat-direct:" + conversation_id + ":v" + str(key_version),
        )
        await chat_direct_media_api.delete_conversation(
            _ChatDirectMessagesRuntime(env), conversation_id)


async def _move_chat_channel_memberships(
        env, old_member_bi, new_member_bi, new_name):
    if old_member_bi == new_member_bi:
        return
    await _delete_chat_channel_memberships(env, new_member_bi)
    sealed = await encrypt_row(env, {"username": new_name})
    await d1_run(
        env,
        "UPDATE chat_channel_members SET member_bi=?,data=? "
        "WHERE member_bi=?",
        new_member_bi,
        sealed,
        old_member_bi,
    )
    await d1_run(
        env,
        "UPDATE chat_channel_members SET invited_by_bi=? "
        "WHERE invited_by_bi=?",
        new_member_bi,
        old_member_bi,
    )


async def _move_repo_namespace(env, old_owner_bi, old_owner, new_owner_bi,
                               new_owner, apply_changes=True):
    rows = await d1_all(
        env, "SELECT key_bi, data, is_private FROM repositories WHERE owner_bi=?",
        old_owner_bi)
    moves = []
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        if (rec.get("owner", "").lower() != old_owner.lower()):
            continue
        repo = clean_string(rec.get("name", ""), MAX_REPO_SEGMENT)
        if not repo:
            continue
        old_repo_bi = row.get("key_bi")
        new_repo_bi = await blind_index(env, new_owner + "/" + repo)
        if new_repo_bi != old_repo_bi:
            existing = await d1_first(
                env, "SELECT key_bi FROM repositories WHERE key_bi=?",
                new_repo_bi)
            if existing:
                return "repo_namespace_conflict"
        bounty_error = await _move_bounties_namespace(
            env, old_owner, new_owner, repo, apply_changes=False)
        if bounty_error:
            return bounty_error
        moves.append((row, rec, repo, old_repo_bi, new_repo_bi))
    if not apply_changes:
        return ""

    for row, rec, repo, old_repo_bi, new_repo_bi in moves:
        rec["owner"] = new_owner
        enc = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT INTO repositories (key_bi, owner_bi, data, is_private)
               VALUES (?,?,?,?)
               ON CONFLICT(key_bi) DO UPDATE SET
                 owner_bi=excluded.owner_bi, data=excluded.data,
                 is_private=excluded.is_private""",
            new_repo_bi, new_owner_bi, enc, int(row.get("is_private") or 0))
        # The new namespace is exactly the name this isolate has been answering
        # "not publicly served" for, right up until this write.
        forget_closed = globals().get("_forget_repo_closed")
        if callable(forget_closed):
            forget_closed(new_owner, repo)
        await _contribution_move_repo_namespace(
            env,
            old_repo_bi,
            new_repo_bi,
            old_owner_bi,
            new_owner_bi,
            new_owner,
            repo,
            rec,
        )
        await _move_repo_shares(env, old_repo_bi, new_repo_bi, new_owner, repo)
        # Carry the attested pin history to the new namespace so mirrors of a
        # renamed source keep clearing the integrity gate without waiting for
        # fresh publishes to rebuild it.
        try:
            await d1_run(
                env, "UPDATE repo_state_history SET key_bi=? WHERE key_bi=?",
                new_repo_bi, old_repo_bi)
        except Exception:
            pass
        await d1_run(
            env, "UPDATE issue_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE pull_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE discussion_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE host_presence SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE clone_rr SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE repo_first_hosted SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        # A registered webhook is the owner's integration with a third party
        # (a CI provider does not re-register itself because the account was
        # renamed), so it follows the repository into the new namespace along
        # with anything still queued for it.
        for _webhook_table in (
                "repo_webhooks", "repo_webhook_seeds",
                "repo_webhook_sequence", "repo_webhook_outbox",
                "repo_webhook_deliveries", "repo_provider_mirrors",
                "repo_provider_mirror_links",
                "repo_provider_mirror_outbox"):
            try:
                await d1_run(
                    env,
                    "UPDATE " + _webhook_table
                    + " SET repo_bi=? WHERE repo_bi=?",
                    new_repo_bi, old_repo_bi)
            except Exception:
                pass
        await _move_bounties_namespace(env, old_owner, new_owner, repo)
        await _move_chat_history_namespace(env, old_owner, new_owner, repo)
        await d1_run(
            env,
            "UPDATE funds_received SET key=?, name=? WHERE scope='project' AND key=?",
            new_owner + "/" + repo, new_owner + "/" + repo,
            old_owner + "/" + repo)
        if new_repo_bi != old_repo_bi:
            await d1_run(
                env, "DELETE FROM repositories WHERE key_bi=?", old_repo_bi)
    return ""


async def _rename_account_namespace(env, name_bi, rec, new_name):
    old_name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    new_name = clean_string(new_name, MAX_NODE_NAME).lower()
    if not valid_node_name(new_name):
        return name_bi, rec, "invalid_node_name"
    if new_name == old_name:
        return name_bi, rec, "node_name_unchanged"
    moderation_error = await username_moderation_error(env, new_name)
    if moderation_error:
        return name_bi, rec, moderation_error

    new_name_bi, target = await _account_row(env, new_name)
    quarantined = await d1_first(
        env,
        "SELECT 1 AS reserved FROM quarantined_users "
        "WHERE user_bi=? AND status<>'restored' LIMIT 1",
        new_name_bi,
    )
    if quarantined:
        return name_bi, rec, "node_name_taken"
    if target and (target.get("status") == "active" or
                   target.get("donation_confirmed") or
                   _donation_in_progress(target)):
        return name_bi, rec, "node_name_taken"

    account_row = await d1_first(
        env, "SELECT data, email_bi, ip_bi, is_admin FROM users WHERE user_bi=?",
        name_bi)
    if not account_row:
        return name_bi, rec, "invalid_credentials"

    move_error = await _move_repo_namespace(
        env, name_bi, old_name, new_name_bi, new_name, apply_changes=False)
    if move_error:
        return name_bi, rec, move_error

    include_flagship = await _account_has_flagship_catalog_repo(env, name_bi)
    await invalidate_public_catalog_snapshots(
        env, include_flagship=include_flagship)

    next_rec = dict(rec)
    next_rec["name"] = new_name
    # Re-key the existing user row before refreshing its mirrors.  Inserting
    # the destination first cannot work for email-backed accounts: the source
    # row still owns the same value under idx_users_email, so every ordinary
    # rename trips the unique email constraint against itself.  D1 batches are
    # transactional, which also makes replacing an abandoned destination row
    # and moving the live row one atomic identity change.
    enc_user = await encrypt_row(env, next_rec)
    await _contribution_run_batch(env, [
        ("DELETE FROM users WHERE user_bi=?", (new_name_bi,)),
        ("UPDATE users SET user_bi=?,data=?,username=? WHERE user_bi=?",
         (new_name_bi, enc_user, new_name, name_bi)),
    ])
    await _save_account_full(
        env, new_name_bi, next_rec,
        email_bi=account_row.get("email_bi"),
        ip_bi=account_row.get("ip_bi"),
        is_admin=account_row.get("is_admin", 0),
    )
    move_error = await _move_repo_namespace(
        env, name_bi, old_name, new_name_bi, new_name)
    if move_error:
        return name_bi, rec, move_error
    await _contribution_retarget_linked_nodes(
        env, name_bi, old_name, new_name_bi, new_name)
    await _move_chat_channel_memberships(
        env, name_bi, new_name_bi, new_name)
    await _delete_chat_channel_invites(env, name_bi)
    # A username move changes the participant blind index and pair identity.
    # Close old DM rooms instead of leaving orphaned membership or silently
    # merging conversations under a different account identity.
    await _delete_chat_direct_conversations(env, name_bi)
    await d1_run(
        env, "UPDATE account_presence SET name_bi=? WHERE name_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE pending_verifications SET name_bi=? WHERE name_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE notifications SET recipient_bi=? WHERE recipient_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE profile_follows SET follower_bi=?, follower_name=? WHERE follower_bi=?",
        new_name_bi, new_name, name_bi)
    await d1_run(
        env, "UPDATE profile_follows SET target_bi=?, target_name=? WHERE target_bi=?",
        new_name_bi, new_name, name_bi)
    await d1_run(
        env, "UPDATE catalog_rate SET owner_bi=? WHERE owner_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env,
        "UPDATE profile_contribution_days SET subject_user_bi=? "
        "WHERE subject_user_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env,
        "UPDATE profile_contribution_languages SET owner_user_bi=? "
        "WHERE owner_user_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env,
        "UPDATE profile_contribution_projects SET owner_user_bi=? "
        "WHERE owner_user_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE account_devices SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE account_ssh_keys SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE account_sessions SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await patreon_account_renamed(env, name_bi, new_name_bi)
    await d1_run(
        env, "UPDATE plan_trials SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    # Ads follow the account; the sealed owner name is what a reviewer reads,
    # so it is re-sealed rather than left pointing at the old username.
    await d1_run(
        env, "UPDATE ad_network_ads SET account_bi=?,owner_sealed=? "
        "WHERE account_bi=?",
        new_name_bi, await encrypt_row(env, {"name": new_name}), name_bi)
    await d1_run(
        env, "UPDATE ad_network_reports SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE ad_network_reviews SET reviewer_bi=? "
        "WHERE reviewer_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE role_grants SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(env, "DELETE FROM users WHERE user_bi=?", name_bi)
    await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", name_bi)
    await purge_catalog_related_caches()
    await schedule_public_catalog_republish(
        env, include_flagship=include_flagship)
    return new_name_bi, next_rec, ""


async def _delete_bounties_namespace(env, owner, repo):
    rows = await d1_all(env, "SELECT bounty_bi, data FROM issue_bounty")
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        if rec.get("owner") == owner and rec.get("repo") == repo:
            await d1_run(
                env, "DELETE FROM issue_bounty WHERE bounty_bi=?",
                row.get("bounty_bi"))


# A repository deleted from the website stays deleted. The owner's node keeps
# the local mirror and republishes its catalog record on every heartbeat, so
# without a tombstone the row reappeared within a minute and the web delete
# looked like it had silently done nothing (adhoc #91). The tombstone refuses
# automatic republishes; an explicit user-initiated publish from the desktop
# clears it, so the owner can always share the repo again.
REPO_DELETE_TOMBSTONE_TTL_MS = 90 * 24 * 60 * 60 * 1000


async def _repo_delete_tombstone_active(env, repo_bi):
    try:
        row = await d1_first(
            env,
            "SELECT repo_bi FROM repo_deletions WHERE repo_bi=? AND "
            "expires_at>?",
            repo_bi, int(Date.now()))
    except Exception:
        # An unreadable tombstone table must never block publishing; the
        # website delete degrades to its old behaviour instead.
        return False
    return bool(row)


async def _record_repo_delete_tombstone(env, repo_bi, owner_bi):
    now = int(Date.now())
    await d1_run(env, "DELETE FROM repo_deletions WHERE expires_at<=?", now)
    await d1_run(
        env,
        "INSERT INTO repo_deletions (repo_bi, owner_bi, deleted_at, "
        "expires_at) VALUES (?,?,?,?) ON CONFLICT(repo_bi) DO UPDATE SET "
        "owner_bi=excluded.owner_bi, deleted_at=excluded.deleted_at, "
        "expires_at=excluded.expires_at",
        repo_bi, owner_bi, now, now + REPO_DELETE_TOMBSTONE_TTL_MS)


async def _clear_repo_delete_tombstone(env, repo_bi):
    try:
        await d1_run(env, "DELETE FROM repo_deletions WHERE repo_bi=?", repo_bi)
    except Exception:
        pass


# The rest of the repository-scoped tables keyed on the repository's own
# blind index (the same value as repositories.key_bi). One entry per table
# instead of one statement each: a repo-scoped table missing from here keeps
# a deleted repository alive in that table, which is exactly what the admin
# purge exists to prevent (adhoc #196).
_REPO_SCOPED_TABLES = (
    ("about_inbox", "repo_bi"),
    ("branch_op_inbox", "repo_bi"),
    ("branch_op_results", "repo_bi"),
    ("inbox_drain_log", "repo_bi"),
    ("issue_seq", "repo_bi"),
    ("private_mirror_routes", "repo_bi"),
    ("pull_batch_sent", "repo_bi"),
    ("pull_submission_receipts", "repo_bi"),
    ("release_downloads", "repo_bi"),
    ("repo_media", "repo_bi"),
    ("repo_merge_jobs", "repo_bi"),
    ("repo_privacy_policy", "repo_bi"),
    ("repo_remote_forks", "repo_bi"),
    ("repo_security_scan_leases", "repo_bi"),
    ("repo_stars", "repo_bi"),
    ("repo_state_history", "key_bi"),
    ("repo_views", "repo_bi"),
    ("repo_view_totals", "repo_bi"),
    ("repo_terms_flags", "repo_bi"),
    ("repo_webhooks", "repo_bi"),
    ("repo_webhook_seeds", "repo_bi"),
    ("repo_webhook_sequence", "repo_bi"),
    ("repo_webhook_outbox", "repo_bi"),
    ("repo_webhook_deliveries", "repo_bi"),
    ("repo_provider_mirrors", "repo_bi"),
    ("repo_provider_mirror_links", "repo_bi"),
    ("repo_provider_mirror_outbox", "repo_bi"),
    ("world_fediverse_mentions", "repo_bi"),
    ("security_advisories", "repo_bi"),
    ("security_advisory_members", "repo_bi"),
    ("security_advisory_comments", "repo_bi"),
    ("security_advisory_credits", "repo_bi"),
    ("security_advisory_settings", "repo_bi"),
    ("repository_fork_jobs", "source_repo_bi"),
    ("repository_fork_jobs", "target_repo_bi"),
)


async def _delete_repo_scoped_state(env, repo_bi):
    # Invalidate the per-isolate agent-snapshot digest: a re-published repo
    # gets the same deterministic repo_bi back, and a memoized digest would
    # otherwise make the desktop's identical re-push a silent no-op forever
    # (empty repo_agents while the desktop believes its sessions published).
    _AGENT_PUSH_DIGESTS.pop(repo_bi, None)
    # One batch, not one await per table: see d1_run_batch.
    await d1_run_batch(env, _repo_scoped_state_statements(repo_bi))


def _repo_scoped_state_statements(repo_bi):
    statements = [
        ("DELETE FROM repo_device_mirrors WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM repo_source_authorities WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM profile_contribution_days WHERE source_repo_bi=?",
         (repo_bi,)),
        ("DELETE FROM profile_contribution_languages WHERE source_repo_bi=?",
         (repo_bi,)),
        ("DELETE FROM profile_contribution_receipts WHERE source_repo_bi=?",
         (repo_bi,)),
        ("DELETE FROM profile_contribution_projects WHERE source_repo_bi=?",
         (repo_bi,)),
        ("DELETE FROM repo_shares WHERE repo_bi=?", (repo_bi,)),
        # Both directions: the repository disappearing is neither a fork of
        # anything nor something anyone can still be shown as having forked.
        ("DELETE FROM repo_forks WHERE fork_bi=? OR parent_bi=?",
         (repo_bi, repo_bi)),
        ("DELETE FROM issue_inbox WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM pull_inbox WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM discussion_inbox WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM host_presence WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM clone_rr WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM repo_first_hosted WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM mirror_repository_integrity WHERE repo_bi=?",
         (repo_bi,)),
        ("DELETE FROM repo_agents WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM repo_security_scans WHERE repo_bi=?", (repo_bi,)),
        ("DELETE FROM repo_security_scan_reviews WHERE repo_bi=?",
         (repo_bi,)),
        ("DELETE FROM agent_prompts WHERE repo_bi=?", (repo_bi,)),
    ]
    for table, column in _REPO_SCOPED_TABLES:
        # Table and column are literals from the tuple above, never input.
        statements.append(
            ("DELETE FROM " + table + " WHERE " + column + "=?", (repo_bi,)))
    return statements


async def _delete_repo_named_state(env, owner, repo):
    """Repo-scoped rows that are not keyed on the repository's key_bi.

    The settings tables key on their own domain-separated blind index, the
    repository's fediverse actor keys on its handle, and the clone/note/org
    tables key on the plaintext owner and name. A delete that skips these
    leaves the repository alive everywhere except the catalog: its actor still
    answers, its stars and clone history still count, and an org alias still
    routes to a repository nobody can reach (adhoc #196).

    Deliberately not purged: contributor_reward_estimates and the sensitive
    audit log. Those are payment and moderation evidence about people, not
    state belonging to the repository, and a delete must not erase them.
    """
    owner = clean_string(owner, MAX_NODE_NAME).lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).lower()
    if not owner or not repo:
        return
    key = owner + "/" + repo
    statements = []
    for prefix, table in (("ap-repo-settings:", "ap_repo_settings"),
                          ("repo-alert-settings:", "repo_alert_settings"),
                          ("repo-feature-settings:", "repo_feature_settings")):
        statements.append((
            "DELETE FROM " + table + " WHERE repo_bi=?",
            (await blind_index(env, prefix + key),)))
    # The repository's own fediverse actor, its followers and the notes it
    # published. Inbound ap_comments key on a per-thread context blind index
    # that cannot be enumerated from here, so they age out with their thread.
    actor_bi = await blind_index(
        env, "ap-actor:repo:" + owner + "." + repo)
    for table in ("ap_actors", "ap_followers", "ap_objects"):
        statements.append(
            ("DELETE FROM " + table + " WHERE actor_bi=?", (actor_bi,)))
    for table in ("attribution_clone_snapshots", "product_clone_daily"):
        statements.append((
            "DELETE FROM " + table + " WHERE owner=? AND repo=?",
            (owner, repo)))
    # notes.py lowercases the owner of a link but not the repository, so this
    # is the one repo-keyed table that can hold a mixed-case name.
    statements.append((
        "DELETE FROM note_links WHERE owner=? AND repo=? COLLATE NOCASE",
        (owner, repo)))
    statements.append((
        "DELETE FROM org_repos WHERE repo=? AND node_owner=?", (repo, owner)))
    await d1_run_batch(env, statements)


async def _delete_repo_namespace(env, owner_bi, owner):
    rows = await d1_all(
        env, "SELECT key_bi, data FROM repositories WHERE owner_bi=?",
        owner_bi)
    owner = clean_string(owner, MAX_NODE_NAME).lower()
    for row in rows:
        repo_bi = row.get("key_bi")
        rec = await decrypt_row(env, row.get("data", "")) or {}
        repo = clean_string(rec.get("name", ""), MAX_REPO_SEGMENT)
        if repo_bi:
            await _delete_repo_scoped_state(env, repo_bi)
            await d1_run(env, "DELETE FROM repositories WHERE key_bi=?", repo_bi)
        if owner and repo:
            await _delete_repo_named_state(env, owner, repo)
            await _delete_bounties_namespace(env, owner, repo)
            await d1_run(
                env, "DELETE FROM chat_history WHERE room_key LIKE ?",
                "repo:" + owner + "/" + repo + ":room:%")
            await d1_run(
                env,
                "DELETE FROM funds_received WHERE scope='project' AND key=?",
                owner + "/" + repo)
    await d1_run(env, "DELETE FROM catalog_rate WHERE owner_bi=?", owner_bi)
    # The account itself is going away, so its website-delete tombstones have
    # nothing left to protect — keeping them would only block a re-registered
    # account of the same name from publishing the same repo names.
    await d1_run(env, "DELETE FROM repo_deletions WHERE owner_bi=?", owner_bi)
    await purge_catalog_related_caches()


async def _delete_account_namespace(env, name_bi, rec):
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    include_flagship = await _account_has_flagship_catalog_repo(env, name_bi)
    await invalidate_public_catalog_snapshots(
        env, include_flagship=include_flagship)
    email = clean_string(rec.get("email", ""), 254).strip().lower()
    await _contribution_retarget_linked_nodes(
        env, name_bi, name, None, "")
    await _delete_repo_namespace(env, name_bi, name)
    await d1_run(env, "DELETE FROM repo_shares WHERE grantee_bi=?", name_bi)
    await d1_run(env, "DELETE FROM account_presence WHERE name_bi=?", name_bi)
    await d1_run(env, "DELETE FROM pending_verifications WHERE name_bi=?", name_bi)
    referral = await d1_first(
        env,
        "SELECT referrer_bi,decision FROM referral_attributions "
        "WHERE referred_bi=?",
        name_bi,
    )
    await d1_run(
        env, "DELETE FROM referral_attributions WHERE referred_bi=?", name_bi)
    if referral and referral.get("decision") == "credited":
        # A verified account that is later deleted no longer counts as a live
        # conversion. Removing its credit also prevents verify/delete/recreate
        # loops from gaming the public leaderboard.
        await d1_run(
            env,
            "UPDATE referral_stats SET signups=MAX(0,signups-1),last_ts=? "
            "WHERE referrer_bi=?",
            int(Date.now()), referral.get("referrer_bi", ""),
        )
    # If this account was the referrer, its public counter and every conversion
    # attributed to a now-absent identity must disappear together.
    await d1_run(
        env, "DELETE FROM referral_attributions WHERE referrer_bi=?", name_bi)
    await d1_run(
        env, "DELETE FROM referral_click_seen WHERE referrer_bi=?", name_bi)
    await d1_run(env, "DELETE FROM referral_stats WHERE referrer_bi=?", name_bi)
    await d1_run(env, "DELETE FROM notifications WHERE recipient_bi=?", name_bi)
    await d1_run(env, "DELETE FROM profile_follows WHERE follower_bi=? OR target_bi=?", name_bi, name_bi)
    await d1_run(env, "DELETE FROM login_attempts WHERE id_bi=?", name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_days WHERE subject_user_bi=? OR "
        "source_repo_bi IN (SELECT source_repo_bi FROM "
        "profile_contribution_projects WHERE owner_user_bi=?)",
        name_bi, name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_languages WHERE owner_user_bi=? OR "
        "source_repo_bi IN (SELECT source_repo_bi FROM "
        "profile_contribution_projects WHERE owner_user_bi=?)",
        name_bi, name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_receipts WHERE source_repo_bi IN "
        "(SELECT source_repo_bi FROM profile_contribution_projects "
        "WHERE owner_user_bi=?)",
        name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_projects WHERE owner_user_bi=?",
        name_bi)
    await d1_run(
        env, "DELETE FROM account_devices WHERE account_bi=?", name_bi)
    await d1_run(
        env, "DELETE FROM account_ssh_keys WHERE account_bi=?", name_bi)
    await d1_run(
        env, "DELETE FROM account_sessions WHERE account_bi=?", name_bi)
    await d1_run(
        env, "DELETE FROM email_footers WHERE owner_bi=?", name_bi)
    await patreon_account_deleted(env, name_bi)
    # Account-scoped packages (Calorie Counter) keep a private diary per
    # account; it goes with the account.
    await plugin_data.purge_account(_PluginPurgeRuntime(env), name_bi, name)
    # Click counters and reports hang off the ad id, so they go before the
    # account's ads do in the loop below.
    for table in ("ad_network_daily_stats", "ad_network_reports"):
        await d1_run(
            env, "DELETE FROM " + table + " WHERE ad_id IN "
            "(SELECT ad_id FROM ad_network_ads WHERE account_bi=?)", name_bi)
    # Remove every account-keyed auxiliary row as well as the primary identity.
    await d1_run(
        env,
        "DELETE FROM world_floor_note_replies WHERE note_id IN "
        "(SELECT note_id FROM world_floor_notes WHERE account_bi=?)",
        name_bi)
    # These tables contain no independently owned resource that should survive
    # a complete account deletion.
    for table in (
            "repo_stars",
            "repo_forks",
            "feedback_email_sends",
            "role_grants",
            "plan_trials",
            "ad_network_reports",
            "ad_network_ads",
            "owner_encryption_keys",
            "world_inactive_presence",
            "world_media_roles",
            "world_user_activity",
            "account_activity_days",
            "badge_awards",
            "world_office_attendance",
            "world_office_marketing_proofs",
            "world_qa_reviews",
            "world_floor_note_replies",
            "world_floor_notes",
            "world_lobby_links",
            "org_team_collaborators",
            "world_office_marketing_checkins",
            "organization_task_checkins",
    ):
        await d1_run(
            env, "DELETE FROM " + table + " WHERE account_bi=?", name_bi)
    await _delete_chat_channel_memberships(env, name_bi)
    await _delete_chat_channel_invites(env, name_bi)
    await _delete_chat_direct_conversations(env, name_bi)
    if email:
        email_bi = await blind_index(env, email)
        await d1_run(env, "DELETE FROM login_attempts WHERE id_bi=?", email_bi)
    await d1_run(env, "DELETE FROM users WHERE user_bi=?", name_bi)
    await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", name_bi)
    # Sequential, like purge_catalog_related_caches itself (issue #555): a few
    # single-digit-millisecond cache deletes, versus a gather that can wedge
    # the isolate — see the no-concurrent-tasks rule at the top of this module.
    await purge_catalog_related_caches()
    await schedule_public_catalog_republish(
        env, include_flagship=include_flagship)
    for cache_key in (
        ACCOUNT_LOOKUP_CACHE_PREFIX + quote(name),
        USERS_DIRECTORY_CACHE_KEY,
        USERS_WORLD_CACHE_KEY,
        CHAT_ACTIVITY_CACHE_KEY,
    ):
        try:
            await edge_cache_delete(cache_key)
        except Exception:
            pass


def _owned_nodes(rec):
    nodes = rec.get("nodes")
    if not isinstance(nodes, list):
        return []
    return [n for n in nodes if isinstance(n, str) and n]


async def _account_owns_node(env, actor, node_name):
    """True when the logged-in account `actor` may act AS the repo owner
    `node_name`. A repo's owner is a NODE account, but the human logs in with
    the linked USER account (adhoc #53 claim/link), whose name differs — so an
    owner-gated web action must resolve that link, not string-compare names.

    Ownership is recorded on both sides by _link_node_to_user: the node record
    carries `owner` = <user name>, and the user record's `nodes` list carries
    the node name. Either side is accepted (tolerate one being stale)."""
    actor = str(actor or "").strip().lower()
    node_name = str(node_name or "").strip().lower()
    if not actor or not node_name:
        return False
    if actor == node_name:
        return True
    _, node_rec = await _account_row(env, node_name)
    if node_rec and str(node_rec.get("owner", "")).strip().lower() == actor:
        return True
    _, actor_rec = await _account_row(env, actor)
    if actor_rec and node_name in {
            n.strip().lower() for n in _owned_nodes(actor_rec)}:
        return True
    return False


def _clean_profile_timezone(raw):
    value = clean_string(raw, MAX_PROFILE_TIMEZONE).strip()
    if not value:
        return ""
    if not re.match(r"^[A-Za-z0-9_./+-]{1,80}$", value):
        return ""
    return value


def _profile_owner_names_from_rec(name, rec):
    names = [name] if valid_node_name(name) else []
    if rec:
        for node in _owned_nodes(rec):
            clean = clean_string(node, MAX_NODE_NAME).lower()
            if valid_node_name(clean) and clean not in names:
                names.append(clean)
    return names


async def _profile_catalog_owner_names(env, name):
    name = clean_string(name, MAX_NODE_NAME).lower()
    _, rec = await _account_row(env, name) if name else ("", None)
    return _profile_owner_names_from_rec(name, rec)


async def _account_mirror_count(env, name, rec=None):
    if rec is None:
        owners = await _profile_catalog_owner_names(env, name)
    else:
        owners = _profile_owner_names_from_rec(
            clean_string(name, MAX_NODE_NAME).lower(), rec)
    owner_bis = []
    for owner in owners:
        owner_bi = await blind_index(env, owner)
        if owner_bi not in owner_bis:
            owner_bis.append(owner_bi)
    if not owner_bis:
        return 0
    rows = await d1_all(
        env,
        "SELECT data FROM repositories WHERE is_private=0 "
        "AND owner_bi IN (%s)" % ",".join("?" * len(owner_bis)),
        *owner_bis,
    )
    total = 0
    for row in rows or []:
        record = await decrypt_row(env, row.get("data"))
        if record and record.get("visibility") == "public":
            total += 1
    return total


async def _account_social_counts(env, name, viewer_name="", rec=None):
    name = clean_string(name, MAX_NODE_NAME).lower()
    if not valid_node_name(name):
        return {
            "followers": 0,
            "following": 0,
            "mirrorCount": 0,
            "isFollowing": False,
        }
    target_bi = await blind_index(env, name)
    viewer = clean_string(viewer_name, MAX_NODE_NAME).lower()
    viewer_bi = ""
    if valid_node_name(viewer) and viewer != name:
        viewer_bi = await blind_index(env, viewer)
    row = await d1_first(
        env,
        "SELECT (SELECT COUNT(*) FROM profile_follows WHERE target_bi=?) "
        "AS followers,"
        "(SELECT COUNT(*) FROM profile_follows WHERE follower_bi=?) "
        "AS following,"
        "(SELECT COUNT(*) FROM profile_follows "
        "WHERE follower_bi=? AND target_bi=?) AS is_following",
        target_bi, target_bi, viewer_bi, target_bi) or {}
    return {
        "followers": int(row.get("followers", 0) or 0),
        "following": int(row.get("following", 0) or 0),
        "mirrorCount": await _account_mirror_count(env, name, rec),
        "isFollowing": bool(viewer_bi and int(
            row.get("is_following", 0) or 0)),
    }


async def _account_is_following(env, name, viewer_name):
    name = clean_string(name, MAX_NODE_NAME).lower()
    viewer = clean_string(viewer_name, MAX_NODE_NAME).lower()
    if not (valid_node_name(name) and valid_node_name(viewer)) or (
            viewer == name):
        return False
    row = await d1_first(
        env,
        "SELECT 1 AS yes FROM profile_follows "
        "WHERE follower_bi=? AND target_bi=?",
        await blind_index(env, viewer), await blind_index(env, name))
    return bool(row)


def _profile_txt_value(name):
    return PROFILE_TXT_PREFIX + clean_string(name, MAX_NODE_NAME).lower()


def _profile_link_domain(url):
    parsed = urlparse(url)
    host = (parsed.hostname or "").strip().lower().rstrip(".")
    return host if DOMAIN_NAME_RE.match(host) else ""


def _clean_profile_url(raw):
    value = clean_string(raw, MAX_PROFILE_LINK_URL).strip()
    if not value:
        return ""
    parsed = urlparse(value)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return ""
    host = (parsed.hostname or "").strip().lower().rstrip(".")
    if not DOMAIN_NAME_RE.match(host):
        return ""
    return parsed.geturl()


def _clean_mastodon_handle(raw):
    value = clean_string(raw, 120).strip()
    if not value:
        return ""
    if not MASTODON_HANDLE_RE.match(value):
        return ""
    if not value.startswith("@"):
        value = "@" + value
    return value


# A Discord user id ("snowflake"). Kept local to the account code rather than
# reusing the connector's copy 10k lines away: that region gets pulled into
# lazy modules as entry.py grows, and account persistence must not depend on
# whichever side of the split it lands on.
_ACCOUNT_DISCORD_ID_RE = re.compile(r"^[0-9]{17,20}$")


def _clean_discord_id(raw):
    value = clean_string(raw, 20).strip()
    return value if _ACCOUNT_DISCORD_ID_RE.match(value) else ""


async def _account_name_for_discord(env, discord_id):
    """The ForkMesh username linked to a Discord user id, or "".

    Reverse lookup over the blind index, the same shape as finding an account
    by email. Never guesses: an unlinked id resolves to "" so a caller credits
    nobody rather than the wrong person.
    """
    discord_id = _clean_discord_id(discord_id)
    if not discord_id:
        return ""
    try:
        row = await d1_first(
            env, "SELECT username FROM users WHERE discord_bi=?",
            await blind_index(env, discord_id))
    except Exception:
        return ""  # column predates migration 0148
    return clean_string((row or {}).get("username", ""), MAX_NODE_NAME).lower()


def _mastodon_url(handle):
    if not handle:
        return ""
    clean = handle[1:] if handle.startswith("@") else handle
    if "@" not in clean:
        return ""
    user, domain = clean.split("@", 1)
    if not user or not DOMAIN_NAME_RE.match(domain):
        return ""
    return "https://" + domain + "/@" + quote(user)


def _profile_links_public(rec):
    links = rec.get("profile_links")
    if not isinstance(links, list):
        return []
    out = []
    for link in links[:MAX_PROFILE_LINKS]:
        if not isinstance(link, dict):
            continue
        url = _clean_profile_url(link.get("url", ""))
        if not url:
            continue
        domain = _profile_link_domain(url)
        out.append({
            "label": clean_string(link.get("label", ""), MAX_PROFILE_LINK_LABEL),
            "url": url,
            "domain": domain,
            "verified": bool(link.get("verified")),
            "verifiedAt": int(link.get("verified_at", 0) or 0),
            "txtName": domain,
            "txtValue": _profile_txt_value(rec.get("name", "")),
        })
    return out


def _account_public_email(rec):
    """The address this account chose to publish on its profile, or "".

    Publishing is opt-in (``profile_email_public``) and can only ever surface
    the one address the account has confirmed: a record whose address is not
    verified — or was changed and is verifying again — stays private no matter
    what the stored flag says.
    """
    if not rec.get("profile_email_public") or not rec.get("email_verified"):
        return ""
    return clean_string(rec.get("email", ""), 254).strip()


def _account_profile_fields(rec):
    bio = clean_string(rec.get("profile_bio", ""), MAX_PROFILE_BIO).strip()
    about = clean_string(
        rec.get("profile_about", "") or rec.get("profile_readme", ""),
        MAX_PROFILE_ABOUT,
    )
    readme = clean_string(rec.get("profile_readme", ""), MAX_PROFILE_README)
    location = clean_string(
        rec.get("profile_location", ""), MAX_PROFILE_LOCATION).strip()
    timezone = _clean_profile_timezone(rec.get("profile_timezone", ""))
    mastodon = _clean_mastodon_handle(rec.get("mastodon", ""))
    return {
        "profileBio": bio,
        "profileAbout": about,
        "profileReadme": readme,
        "profileLocation": location,
        "profileTimezone": timezone,
        "profilePrivate": bool(rec.get("profile_private")),
        "followersPublic": bool(rec.get("profile_followers_public")),
        "publicEmail": _account_public_email(rec),
        "mastodon": mastodon,
        "mastodonUrl": _mastodon_url(mastodon),
        "profileLinks": _profile_links_public(rec),
        "userStatus": _public_user_status(rec),
    }


async def _dns_txt_has_profile_token(domain, token):
    domain = clean_string(domain, 253).strip().lower().rstrip(".")
    if not DOMAIN_NAME_RE.match(domain) or not token:
        return False
    from js import fetch as js_fetch
    url = "https://cloudflare-dns.com/dns-query?name=" + quote(domain) + "&type=TXT"
    try:
        resp = await js_fetch(url, to_js({
            "method": "GET",
            "headers": {"accept": "application/dns-json"},
        }))
        if int(getattr(resp, "status", 0)) != 200:
            return False
        data = json.loads(await resp.text())
    except Exception:
        return False
    answers = data.get("Answer") if isinstance(data, dict) else None
    if not isinstance(answers, list):
        return False
    wanted = token.lower()
    for answer in answers:
        if not isinstance(answer, dict):
            continue
        text = str(answer.get("data", "") or "").replace('" "', "").replace('"', "")
        if wanted in text.lower():
            return True
    return False


async def _clean_profile_links(env, rec, raw_links):
    if raw_links is None:
        return None, None
    if not isinstance(raw_links, list):
        return None, "bad_profile_links"
    prev = {}
    for link in rec.get("profile_links") or []:
        if isinstance(link, dict) and link.get("url"):
            prev[link.get("url")] = link
    token = _profile_txt_value(rec.get("name", ""))
    out = []
    seen = set()
    for item in raw_links[:MAX_PROFILE_LINKS]:
        if not isinstance(item, dict):
            return None, "bad_profile_links"
        url = _clean_profile_url(item.get("url", ""))
        label = clean_string(item.get("label", ""), MAX_PROFILE_LINK_LABEL).strip()
        if not url and not label:
            continue
        if not url:
            return None, "bad_profile_link_url"
        if url in seen:
            continue
        seen.add(url)
        domain = _profile_link_domain(url)
        prior = prev.get(url) or {}
        verified = bool(prior.get("verified"))
        verified_at = int(prior.get("verified_at", 0) or 0)
        if not verified and await _dns_txt_has_profile_token(domain, token):
            verified = True
            verified_at = int(Date.now())
        out.append({
            "label": label,
            "url": url,
            "domain": domain,
            "verified": verified,
            "verified_at": verified_at,
        })
    return out, None


async def _account_public_payload(
        env, rec, session_token=None, session_device_label="",
        session_client_ip="", session_device_bi=""):
    name = rec.get("name", "")
    solana = (rec.get("solana") or "").strip()
    has_payout = bool(solana and SOLANA_RE.match(solana))
    is_admin = await _is_admin(env, name)
    social = await _account_social_counts(env, name)
    payload = {
        "ok": True,
        "nodeName": name,
        "nameCase": account_names.display_name(rec, name),
        "email": rec.get("email", ""),
        "status": rec.get("status", "active"),
        "pubkey": rec.get("pubkey", ""),
        "emailVerified": bool(rec.get("email_verified")),
        "isAdmin": is_admin,
        "solana": solana if has_payout else "",
        "hasPayoutAddress": has_payout,
        "payoutCustody": "external-self-custodial-public-address",
        "payoutNotice": (
            "ForkMesh stores only the optional public payout address. Wallet "
            "keys, transaction approval, and user-owned funds remain with the "
            "external wallet owner; reward selection and payment are not "
            "guaranteed."
        ),
        "sessionToken": (
            session_token
            if session_token is not None
            else await _account_session_token(
                env, name, session_device_label, session_client_ip,
                session_device_bi)
        ),
        "avatarPng": rec.get("avatar_png", ""),
        "avatarUpdatedAt": rec.get("avatar_updated_at", 0),
        "createdAt": rec.get("created_at", 0),
        "kind": _account_kind(rec),
        "owner": rec.get("owner", ""),
        "nodes": _owned_nodes(rec),
        "emailNotifications": rec.get("email_notifications") is not False,
        "notificationPreferences": notification_email_preferences(rec),
        "notificationDelivery": notification_delivery_mode(rec),
        "notificationPauseUntil": ping_pause_until(rec),
        "chatRetention": _account_chat_retention(rec),
        "social": social,
    }
    payload.update(social)
    payload.update(ping_settings_payload(rec, is_admin))
    payload.update(_account_profile_fields(rec))
    payload.update(await _referral_public_summary(
        env, await blind_index(env, name)))
    payload.update(_account_world_client_fields(rec))
    if is_admin:
        admin_path = _admin_path(env)
        if admin_path:
            payload["adminUrl"] = "/" + admin_path + "?admin=" + quote(name)
    return payload


def _world_public_total_active_ms(value):
    """Return a coarse, bounded public duration without activity timestamps."""
    try:
        total = int(value or 0)
    except (TypeError, ValueError):
        total = 0
    total = max(0, min(WORLD_USER_ACTIVITY_MAX_TOTAL_MS, total))
    return (
        total // WORLD_USER_ACTIVITY_PUBLIC_BUCKET_MS
    ) * WORLD_USER_ACTIVITY_PUBLIC_BUCKET_MS


def _world_public_total_steps(value):
    """Return an exact bounded aggregate without exposing movement samples."""
    try:
        total = int(value or 0)
    except (TypeError, ValueError):
        total = 0
    return max(0, min(WORLD_USER_STEP_MAX_TOTAL, total))


def _world_public_office_visits(value):
    """Return a bounded aggregate count without publishing visit timestamps."""
    try:
        total = int(value or 0)
    except (TypeError, ValueError):
        total = 0
    return max(0, min(999, total))


def _account_world_client_fields(rec):
    """The coarse country/browser/OS the account last chose to publish.

    Stored by /api/world/client so an away member's campfire bench figure —
    which has no live presence frame to read — still shows the same three
    coarse values their avatar wore while they were here.
    """
    return world_protocol.clean_client_profile(
        (rec or {}).get("world_country", ""),
        (rec or {}).get("world_browser", ""),
        (rec or {}).get("world_os", ""),
    )


WORLD_PUBLIC_LAST_EMAIL_BUCKET_MS = 60 * 60 * 1000


def _account_public_last_email(rec):
    """The last account email's coarse age and delivery outcome.

    World paints "LAST EMAIL 2D AGO · DELIVERED" on every member badge, so the
    stamp rides the public directory rather than only the owner's own
    authenticated read. The send time is rounded down to the hour, and the
    address, the email kind and the running send count stay behind
    /api/accounts/sessions.
    """
    try:
        ts = int((rec or {}).get("last_email_ts") or 0)
    except (TypeError, ValueError):
        ts = 0
    if ts <= 0:
        return {"lastEmailAt": 0, "lastEmailStatus": ""}
    return {
        "lastEmailAt": (
            (ts // WORLD_PUBLIC_LAST_EMAIL_BUCKET_MS)
            * WORLD_PUBLIC_LAST_EMAIL_BUCKET_MS
        ),
        "lastEmailStatus": (
            ACCOUNT_EMAIL_STATUS_DELIVERED if (rec or {}).get("last_email_ok")
            else ACCOUNT_EMAIL_STATUS_FAILED
        ),
    }


def _contribution_tally(value):
    """Coerce one contributor_activity column into a non-negative count.

    The directory LEFT JOINs that table, so an account that has never opened
    an issue or pushed a commit has no row at all and every tally column
    arrives as SQL NULL — i.e. Python None, which int() rejects. Swallowing
    that here keeps a contributor-less account from 500-ing the whole
    directory read (and with it chat's roster and the World campfire).
    """
    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError):
        return 0


def _account_chat_user_payload(rec, total_active_ms=0, activity_bucket="",
                              issues=0, pulls=0, commits=0, discussions=0,
                              total_steps=0, office_visits=0,
                              discord_linked=False, achievement_badges=()):
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    solana = (rec.get("solana") or "").strip()
    mastodon = _clean_mastodon_handle(rec.get("mastodon", ""))
    issue_total = _contribution_tally(issues)
    pull_total = _contribution_tally(pulls)
    commit_total = _contribution_tally(commits)
    discussion_total = _contribution_tally(discussions)
    # These are the five small marks the World can safely wear on an avatar's
    # sleeve. Issue/PR/discussion history predates badge_awards, so derive
    # those three from the existing public aggregates as well as honoring
    # their durable award rows. This makes the visual recognition complete for
    # established contributors instead of starting from this deployment.
    wearable_badges = set()
    if issue_total:
        wearable_badges.add("qa")
    if pull_total:
        wearable_badges.add("coder")
    if discussion_total:
        wearable_badges.add("poster")
    if discord_linked:
        wearable_badges.add("discord")
    for value in achievement_badges or ():
        slug = str(value or "").strip().lower()
        if slug in ("qa", "coder", "discord", "poster", "chat"):
            wearable_badges.add(slug)
    ordered_wearable_badges = [
        slug for slug in ("qa", "coder", "discord", "poster", "chat")
        if slug in wearable_badges
    ]
    return {
        "name": name,
        "status": rec.get("status", "active"),
        "avatarPng": rec.get("avatar_png", ""),
        "avatarUpdatedAt": rec.get("avatar_updated_at", 0),
        # Public boolean only; the email address itself never enters the
        # directory or World. It drives the verified pin on the avatar front.
        "emailVerified": bool(rec.get("email_verified")),
        "createdAt": rec.get("created_at", 0),
        "kind": "user",
        "nodes": _owned_nodes(rec),
        # Lifetime contribution tallies, one per kind — the columns the Qt
        # admin Users page shows next to each account.
        "issues": issue_total,
        "pulls": pull_total,
        "commits": commit_total,
        "discussions": discussion_total,
        # Public, bounded recognition data for the World avatar's right-arm
        # patches. It carries neither Discord identifiers nor chat content.
        "achievementBadges": ordered_wearable_badges,
        # Payout addresses are public profile data, but never pass through a
        # malformed value from a stored record.
        "solana": solana if SOLANA_RE.match(solana) else "",
        # Aggregate-only and rounded down to whole minutes. The public
        # directory deliberately exposes neither a last-seen timestamp nor the
        # current activity interval used by an authenticated World tab.
        "totalActiveMs": _world_public_total_active_ms(total_active_ms),
        # Whole aggregate only. The World relay discards every movement sample
        # after converting it, so this count cannot reveal where someone went.
        "totalSteps": _world_public_total_steps(total_steps),
        # Attendance is already a public Office surface. The directory carries
        # only its bounded lifetime count so the Members Circle can recognize
        # participation without publishing another visit time or floor.
        "officeVisits": _world_public_office_visits(office_visits),
        # The bench figure's chest activity light: a coarse recency
        # bucket the caller already derived from the raw touch timestamp, so
        # this function never sees (or could leak) that timestamp itself.
        "activityBucket": activity_bucket,
        # This is already an explicitly public profile field. Carrying it in
        # the public directory lets aggregate surfaces link ranked users to the
        # Mastodon identity they chose without one account lookup per row.
        "mastodon": mastodon,
        "mastodonUrl": _mastodon_url(mastodon),
        **_account_public_last_email(rec),
        **_account_world_client_fields(rec),
        "userStatus": _public_user_status(rec),
    }


