def _donation_expiry_fields(rec, now):
    try:
        created = int(rec.get("donation_created_at") or rec.get("created_at") or now)
    except (TypeError, ValueError):
        created = now
    try:
        expires = int(rec.get("donation_expires_at") or
                      created + DONATION_ADDRESS_TTL_MS)
    except (TypeError, ValueError):
        expires = created + DONATION_ADDRESS_TTL_MS
    try:
        delete_after = int(rec.get("donation_delete_after") or
                           expires + DONATION_ADDRESS_DELETE_GRACE_MS)
    except (TypeError, ValueError):
        delete_after = expires + DONATION_ADDRESS_DELETE_GRACE_MS
    return created, expires, delete_after


def _account_session_secret(env):
    return (str(getattr(env, "ADMIN_PASS", "") or "") + "|" +
            str(getattr(env, "DATA_KEY", "") or "")).encode()


ACCOUNT_SESSION_COOKIE = "forkmesh_account"
ACCOUNT_SESSION_TOKEN_RE = re.compile(
    r"^v2\.([A-Za-z0-9_-]{24,64})\.([A-Za-z0-9_-]{32,96})$")
ACCOUNT_SESSION_TOUCH_MS = 5 * 60 * 1000
ACCOUNT_SESSION_MAX_ACTIVE = 20
# A website login lasts five years (leap days included) unless it is signed out
# here or revoked from Settings, which can sign out every device at once. It
# used to share the admin cookie's twelve hours, so a visitor who came back the
# next day saw the landing page's cached "signed in" marker flip to signed out
# the moment the header re-checked it. The admin page cookie stays short-lived.
ACCOUNT_SESSION_TTL_MS = (5 * 365 + 1) * 24 * 60 * 60 * 1000


def _account_session_token_digest(env, token):
    return hmac.new(
        _account_session_secret(env),
        ("forkmesh-account-session-token-v2\n" + str(token or "")).encode(),
        "sha256",
    ).hexdigest()


async def _account_session_token(env, name, device_label="", client_ip="",
                                 device_bi=""):
    """Mint one random, server-revocable session; D1 stores no bearer token.

    device_bi is the account_devices row a key-bound (desktop/mobile node)
    login proved possession of; revoking that device revokes this session.
    """
    name = clean_string(name or "", MAX_NODE_NAME).lower()
    if not valid_node_name(name):
        return ""
    await ensure_schema(env)
    now = int(Date.now())
    account_bi = await blind_index(env, name)
    session_id = _b64url_encode(_random_bytes(24))
    secret = _b64url_encode(_random_bytes(32))
    token = "v2." + session_id + "." + secret
    expires = now + ACCOUNT_SESSION_TTL_MS
    await d1_run(
        env,
        "DELETE FROM account_sessions WHERE expires_at<=? OR "
        "(revoked_at>0 AND revoked_at<=?)",
        now,
        now - 24 * 60 * 60 * 1000,
    )
    # Bound stolen-device persistence and table growth. Retain only the most
    # recently used sessions for this account before adding the next one: with
    # multi-year sessions, age of sign-in says nothing about whether a browser
    # is still in use, so a burst of new logins elsewhere must not evict it.
    await d1_run(
        env,
        "DELETE FROM account_sessions WHERE session_id IN ("
        "SELECT session_id FROM account_sessions WHERE account_bi=? "
        "ORDER BY last_seen_at DESC,created_at DESC LIMIT -1 OFFSET ?)",
        account_bi,
        ACCOUNT_SESSION_MAX_ACTIVE - 1,
    )
    await d1_run(
        env,
        "INSERT INTO account_sessions "
        "(session_id,account_bi,token_digest,created_at,last_seen_at,"
        "expires_at,revoked_at,device_label,client_ip,device_bi) "
        "VALUES (?,?,?,?,?,?,0,?,?,?)",
        session_id,
        account_bi,
        _account_session_token_digest(env, token),
        now,
        now,
        expires,
        clean_string(device_label or "", 80),
        clean_string(client_ip or "", 64),
        clean_string(device_bi or "", 128),
    )
    return token


def _account_session_cookie(token):
    # Browsers clamp a cookie's lifetime (Chromium to 400 days), so the session
    # API re-issues this on every cookie-authenticated read; see
    # _account_sessions.
    token = clean_string(token or "", 512).strip()
    return (
        ACCOUNT_SESSION_COOKIE + "=" + token
        + "; Path=/; Max-Age=%d; HttpOnly; Secure; SameSite=Strict"
        % int(ACCOUNT_SESSION_TTL_MS / 1000)
    )


def _clear_account_session_cookie():
    return (
        ACCOUNT_SESSION_COOKIE
        + "=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict"
    )


PORTABLE_SESSION_COOKIE = "forkmesh_portable"
# A grant lives twelve hours and the dashboard asks for a fresh one every four,
# so a younger cookie is left alone instead of being re-signed on every read.
PORTABLE_SESSION_REISSUE_MS = 4 * 60 * 60 * 1000


def _portable_session_cookie_domain(env, request):
    """Return a configured shared parent only when it owns this request host.

    The production default lets ``app.forkmesh.com`` issue a cookie to the
    direct ``mirrorNN.forkmesh.com`` origins. Self-hosters must opt into their
    own parent; a mismatched setting is ignored so it cannot create a cookie
    for an unrelated domain.
    """
    configured = clean_string(
        getattr(env, "PORTABLE_SESSION_COOKIE_DOMAIN", "") or "", 253
    ).strip().lower().lstrip(".")
    try:
        hostname = str(urlparse(request.url).hostname or "").lower().rstrip(".")
    except Exception:
        hostname = ""
    if not configured and (
        hostname == "forkmesh.com" or hostname.endswith(".forkmesh.com")
    ):
        configured = "forkmesh.com"
    if (
        not configured
        or not re.fullmatch(
            r"[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?"
            r"(?:\.[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?)+",
            configured,
        )
        or not (hostname == configured or hostname.endswith("." + configured))
    ):
        return ""
    return "." + configured


async def _portable_session_token(env, session_token, rec):
    """Sign a D1-session-bound identity grant; never copy its bearer token."""
    match = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
        clean_string(session_token or "", 512).strip()
    )
    name = clean_string((rec or {}).get("name", ""), MAX_NODE_NAME).lower()
    if not match or not valid_node_name(name):
        return "", 0
    session_id = match.group(1)
    account_bi = await blind_index(env, name)
    row = await d1_first_primary(
        env,
        "SELECT expires_at,revoked_at FROM account_sessions "
        "WHERE session_id=? AND account_bi=?",
        session_id,
        account_bi,
    )
    now = int(Date.now())
    expires_at = int((row or {}).get("expires_at") or 0)
    if (
        not row
        or int(row.get("revoked_at") or 0)
        or expires_at <= now
    ):
        return "", 0
    public_key = _https_mirror_router_public_key(env)
    signing_seed = _https_mirror_router_seed(env)
    if not public_key or not signing_seed:
        return "", 0
    claim = portable_sessions.build_claim(
        account_id=account_bi,
        account_name=name,
        session_id=session_id,
        grant_id=_b64url_encode(_random_bytes(18)),
        issued_at=now,
        expires_at=min(
            expires_at,
            now + int(portable_sessions.SESSION_MAX_LIFETIME_MS),
        ),
    )
    encoded = portable_sessions.encode_claim(claim)
    signature = await ed25519_sign(
        public_key,
        signing_seed,
        portable_sessions.signing_message(encoded),
    )
    if not signature:
        return "", 0
    try:
        return portable_sessions.assemble_token(encoded, signature), claim["exp"]
    except Exception:
        return "", 0


def _portable_session_cookie(token, domain, expires_at, now):
    max_age = max(0, int((int(expires_at) - int(now)) / 1000))
    return (
        PORTABLE_SESSION_COOKIE + "=" + clean_string(token or "", 2048)
        + "; Path=/; Domain=" + domain
        + "; Max-Age=%d; HttpOnly; Secure; SameSite=Strict" % max_age
    )


def _clear_portable_session_cookie(domain):
    return (
        PORTABLE_SESSION_COOKIE
        + "=; Path=/; Domain=" + domain
        + "; Max-Age=0; HttpOnly; Secure; SameSite=Strict"
    )


def _append_set_cookie(response, value):
    if not value:
        return response
    headers = response.headers
    # Cloudflare's native Headers object exposes append(), while a Response
    # that has crossed the Python Worker compatibility boundary can expose an
    # http.client.HTTPMessage instead.  The latter preserves repeated
    # Set-Cookie fields through add_header().  Account-session refreshes are a
    # hot desktop path, so assuming only the JavaScript shape here turned each
    # desktop start into a 500 and painted /status red.
    append = getattr(headers, "append", None)
    if callable(append):
        append("Set-Cookie", value)
        return response
    add_header = getattr(headers, "add_header", None)
    if callable(add_header):
        add_header("Set-Cookie", value)
        return response
    raise TypeError("response headers cannot append Set-Cookie")


def _portable_session_cookie_current(request, session_token, rec, now):
    """True when the browser already holds a young grant for this session.

    The session listing is read on every load and focus of every signed-in
    surface, and each read used to pay a primary D1 read, a blind index and an
    Ed25519 signature to replace a twelve-hour grant minted minutes earlier.
    The presented cookie is only trusted to decide that nothing new is owed —
    a forged one costs its sender their own mirror sign-in and nothing else —
    so the signature is left for the mirror to verify.
    """
    try:
        presented = portable_sessions.cookie_value(
            request.headers.get("cookie") or "", PORTABLE_SESSION_COOKIE)
        framed = portable_sessions.SESSION_TOKEN_RE.fullmatch(presented or "")
        session = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
            clean_string(session_token or "", 512).strip())
        if not framed or not session:
            return False
        encoded = framed.group(1)
        claim = portable_sessions.validate_claim(
            json.loads(
                portable_sessions._b64url_decode(encoded).decode("utf-8")),
            now_ms=now)
        return (
            claim["sid"] == session.group(1)
            and claim["name"] == clean_string(
                (rec or {}).get("name", ""), MAX_NODE_NAME).lower()
            and 0 <= now - claim["iat"] < PORTABLE_SESSION_REISSUE_MS
        )
    except Exception:
        return False


async def _append_portable_session_cookie(
        env, request, response, session_token, rec, reuse_current=False):
    domain = _portable_session_cookie_domain(env, request)
    if not domain:
        return response
    if reuse_current and _portable_session_cookie_current(
            request, session_token, rec, int(Date.now())):
        response.headers["X-ForkMesh-Portable-Session"] = "current"
        return response
    token, expires_at = await _portable_session_token(
        env, session_token, rec
    )
    if token:
        _append_set_cookie(
            response,
            _portable_session_cookie(
                token, domain, expires_at, int(Date.now())
            ),
        )
        response.headers["X-ForkMesh-Portable-Session"] = "issued"
    else:
        # A 200 from the account-session listing does not prove that a portable
        # grant was signed. Let the browser retry instead of remembering a
        # false success when signing material or the primary row is transient.
        response.headers["X-ForkMesh-Portable-Session"] = "unavailable"
    return response


async def _account_mirror_handoff(env, request):
    """POST a signed account grant to an official mirror without URL leakage.

    A background parent-domain cookie remains the fast path, but browsers can
    reject or partition that cookie without exposing the result to JavaScript.
    Direct mirror links pass through this no-store page so the destination can
    establish its own HttpOnly cookie before rendering the repository. The
    grant appears only in the form body, never a URL, referrer, or localStorage.
    """
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET"})
    params = parse_qs(urlparse(request.url).query)
    destination = clean_string(params.get("to", [""])[0], 2048).strip()
    try:
        parsed = urlparse(destination)
        hostname = str(parsed.hostname or "").lower().rstrip(".")
        destination_port = parsed.port
    except Exception:
        parsed = None
        hostname = ""
        destination_port = None
    if (
        parsed is None
        or parsed.scheme != "https"
        or parsed.username
        or parsed.password
        or destination_port not in (None, 443)
        or not re.fullmatch(r"mirror[0-9]+\.forkmesh\.com", hostname)
        or not parsed.path.startswith("/")
        or parsed.path.startswith("//")
        or parsed.fragment
    ):
        return json_response(
            {"error": "invalid_mirror_destination"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    segments = [piece for piece in parsed.path.split("/") if piece]
    try:
        valid_repo_path = (
            len(segments) >= 2
            and valid_node_name(segments[0])
            and safe_segment(segments[1]) == segments[1]
        )
    except Exception:
        valid_repo_path = False
    if not valid_repo_path:
        return json_response(
            {"error": "invalid_mirror_destination"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")

    session_token, _cookie_auth = _request_account_session_token(request, {})
    _account_bi, rec, session_id = await _account_session_lookup(
        env, session_token, touch=True)
    if not rec or not session_id:
        return json_response(
            {"error": await _account_session_invalid_error(
                env, session_token)},
            status=401,
            cache_control="no-store, max-age=0, must-revalidate")
    grant, _expires_at = await _portable_session_token(
        env, session_token, rec)
    if not grant:
        return json_response(
            {"error": "portable_session_unavailable"}, status=503,
            cache_control="no-store, max-age=0, must-revalidate")

    origin = "https://" + hostname
    next_path = parsed.path + (("?" + parsed.query) if parsed.query else "")
    nonce = _b64url_encode(_random_bytes(18))
    form_action = origin + "/api/accounts/session-handoff"
    body = (
        "<!doctype html><html><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width\">"
        "<title>Opening mirror</title></head>"
        "<body><form id=\"handoff\" method=\"post\" action=\""
        + _html_escape(form_action) + "\">"
        "<input type=\"hidden\" name=\"grant\" value=\""
        + _html_escape(grant) + "\">"
        "<input type=\"hidden\" name=\"next\" value=\""
        + _html_escape(next_path) + "\">"
        "<noscript><button type=\"submit\">Open mirror</button></noscript>"
        "</form><script nonce=\"" + nonce
        + "\">document.getElementById('handoff').submit()</script>"
        "</body></html>"
    )
    return Response(body, status=200, headers={
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store, max-age=0, must-revalidate",
        "content-security-policy": (
            "default-src 'none'; base-uri 'none'; frame-ancestors 'none'; "
            "form-action " + origin + "; script-src 'nonce-" + nonce + "'"
        ),
        "referrer-policy": "no-referrer",
        "x-content-type-options": "nosniff",
    })


async def _account_session_response(env, request, payload, status=200):
    """Issue the controller cookie and a separately signed mirror grant."""
    response = json_response(
        payload,
        status=status,
        extra_headers={
            "Set-Cookie": _account_session_cookie(payload["sessionToken"])
        },
        cache_control="no-store, max-age=0, must-revalidate",
    )
    return await _append_portable_session_cookie(
        env, request, response, payload.get("sessionToken", ""), payload
    )


def _clear_all_account_cookies(env, request, response):
    domain = _portable_session_cookie_domain(env, request)
    if domain:
        _append_set_cookie(response, _clear_portable_session_cookie(domain))
    return response


_CORS_CANONICAL_FRONTEND_ORIGINS = (
    "https://forkmesh.com",
    "https://www.forkmesh.com",
    "https://app.forkmesh.com",
    "https://world.forkmesh.com",
)
_CORS_ORIGIN_ENV_NAMES = (
    "PUBLIC_BASE_URL",
    "API_ORIGIN",
    "APP_ORIGIN",
    "WWW_ORIGIN",
    "WORLD_ORIGIN",
)
_CORS_METHODS = ("GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS")
_CORS_DEFAULT_HEADERS = ("accept", "authorization", "content-type")
_CORS_EXPOSE_HEADERS = (
    "etag",
    "link",
    "location",
    "retry-after",
    "x-forkmesh-worker",
    "x-forkmesh-public-snapshot",
    "x-forkmesh-snapshot-generated-at",
    "x-forkmesh-snapshot-fingerprint",
    "x-request-id",
    "x-ratelimit-limit",
    "x-ratelimit-remaining",
    "x-ratelimit-reset",
)
_CORS_HEADER_TOKEN_RE = re.compile(r"^[!#$%&'*+.^_`|~0-9A-Za-z-]+$")

_BROWSER_CSP = (
    "default-src 'self'; base-uri 'self'; object-src 'none'; "
    "frame-ancestors {frame_ancestors}; form-action 'self'; "
    "script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net "
    "https://static.cloudflareinsights.com; style-src 'self' 'unsafe-inline'; "
    "img-src 'self' data: blob: https:; font-src 'self' data:; "
    "connect-src 'self' https: wss:; media-src 'self' blob: https:; "
    "frame-src 'self' https:; worker-src 'self' blob:; manifest-src 'self'; "
    "upgrade-insecure-requests"
)
_BROWSER_SECURITY_HEADERS = {
    "strict-transport-security": "max-age=31536000; includeSubDomains",
    "referrer-policy": "strict-origin-when-cross-origin",
    "permissions-policy": (
        "camera=(), geolocation=(), payment=(), usb=(), serial=(), "
        "browsing-topics=(), microphone=(self), clipboard-write=(self)"
    ),
    "x-content-type-options": "nosniff",
    "cross-origin-opener-policy": "same-origin",
}


_DEVICE_PAGE_PERMISSIONS = (
    "camera=(self), geolocation=(), payment=(), usb=(), serial=(), "
    "browsing-topics=(), microphone=(self), clipboard-write=(self)"
)
_DEVICE_PAGE_MEDIA_SRC = "media-src 'self' blob: https: mediastream:"


def _plugin_device_page(path):
    if not path.startswith("/dashboard/"):
        return ()
    try:
        from plugin_registry import PLUGIN_DEVICE_PAGES
    except Exception:
        return ()
    return tuple(PLUGIN_DEVICE_PAGES.get(path) or ())


_TURNSTILE_CHALLENGE_ORIGIN = "https://challenges.cloudflare.com"
_TURNSTILE_PAGE_PATHS = frozenset({
    "/signup", "/forgot-password", "/forgot-password.html",
})


def _apply_browser_security_headers(response, pathname):
    headers = getattr(response, "headers", None)
    if headers is None:
        return response
    content_type = str(headers.get("content-type") or "").lower()
    if "text/html" not in content_type:
        return response
    path = str(pathname or "/")
    frameable = (
        path in ("/chat", "/chat.html")
        or path.startswith("/dashboard/chat")
        or re.fullmatch(r"/[^/]+/[^/]+/(?:issues|pulls)/[^/]+", path)
    )
    csp = _BROWSER_CSP.format(
        frame_ancestors="'self'" if frameable else "'none'"
    )
    if path in _TURNSTILE_PAGE_PATHS:
        # Only the pages that render the Turnstile widget may load its script
        # and frame (turnstile.py); every other page keeps the base policy.
        csp = csp.replace(
            "script-src 'self'",
            "script-src 'self' " + _TURNSTILE_CHALLENGE_ORIGIN, 1,
        ).replace(
            "frame-src 'self'",
            "frame-src 'self' " + _TURNSTILE_CHALLENGE_ORIGIN, 1,
        )
    devices = _plugin_device_page(path)
    if devices:
        csp = csp.replace(
            "media-src 'self' blob: https:", _DEVICE_PAGE_MEDIA_SRC, 1)
    values = {
        **_BROWSER_SECURITY_HEADERS,
        "content-security-policy": csp,
        "x-frame-options": "SAMEORIGIN" if frameable else "DENY",
    }
    if "camera" in devices:
        values["permissions-policy"] = _DEVICE_PAGE_PERMISSIONS
    existing_csp = headers.get("content-security-policy")
    if existing_csp is not None and str(existing_csp).strip() and type(
            existing_csp).__name__ not in ("JsNull", "JsUndefined"):
        values.pop("content-security-policy")
    for name, value in values.items():
        try:
            headers.set(name, value)
        except AttributeError:
            headers[name] = value
    return response


def _private_console_headers(response):
    headers = getattr(response, "headers", None)
    if headers is None:
        return response
    for name, value in (("cache-control", "no-store"),
                        ("x-robots-tag", "noindex, nofollow"),
                        ("referrer-policy", "no-referrer")):
        try:
            headers.set(name, value)
        except AttributeError:
            headers[name] = value
    return response


def _normalized_http_origin(value):
    try:
        parsed = urlparse(str(value or "").strip())
    except Exception:
        return ""
    if (
        parsed.scheme not in ("http", "https")
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
        or parsed.path not in ("", "/")
        or parsed.query
        or parsed.fragment
    ):
        return ""
    hostname = parsed.hostname.lower().rstrip(".")
    if parsed.scheme == "http" and hostname not in (
            "localhost", "127.0.0.1", "::1"):
        return ""
    try:
        port = parsed.port
    except ValueError:
        return ""
    default_port = 443 if parsed.scheme == "https" else 80
    host = "[" + hostname + "]" if ":" in hostname else hostname
    return (
        parsed.scheme + "://" + host
        + ((":" + str(port)) if port and port != default_port else "")
    )


def _request_origin(request):
    try:
        return _normalized_http_origin(request.headers.get("origin") or "")
    except Exception:
        return ""


def _request_target_origin(request):
    try:
        parsed = urlparse(request.url)
        port = parsed.port
    except Exception:
        return ""
    host = str(parsed.hostname or "").lower().rstrip(".")
    if not host or parsed.scheme not in ("http", "https"):
        return ""
    formatted_host = "[" + host + "]" if ":" in host else host
    default_port = 443 if parsed.scheme == "https" else 80
    return (
        parsed.scheme + "://" + formatted_host
        + ((":" + str(port)) if port and port != default_port else "")
    )


def _request_same_origin(request):
    try:
        target = urlparse(request.url)
        origin = urlparse(request.headers.get("origin") or "")
    except Exception:
        return False
    if (
        origin.scheme not in ("http", "https")
        or not origin.hostname
        or origin.username is not None
        or origin.password is not None
        or origin.path not in ("", "/")
        or origin.query
        or origin.fragment
    ):
        return False
    try:
        target_port = target.port or (
            443 if target.scheme == "https" else 80)
        origin_port = origin.port or (
            443 if origin.scheme == "https" else 80)
    except ValueError:
        return False
    return bool(
        origin.scheme == target.scheme
        and origin.hostname.lower().rstrip(".")
            == str(target.hostname or "").lower().rstrip(".")
        and origin_port == target_port
    )


def _cors_allowed_origins(env, request=None):
    single_site = str(
        getattr(env, "SINGLE_WORKER_SITE", "") or ""
    ).strip().lower() in ("1", "true", "yes", "on")
    origins = set() if single_site else set(_CORS_CANONICAL_FRONTEND_ORIGINS)
    for name in _CORS_ORIGIN_ENV_NAMES:
        value = _normalized_http_origin(getattr(env, name, "") or "")
        if value:
            origins.add(value)
    configured = str(
        getattr(env, "CORS_ALLOWED_ORIGINS", "") or ""
    ).replace("\n", ",")
    for value in configured.split(","):
        value = _normalized_http_origin(value)
        if value:
            origins.add(value)
    target = _request_target_origin(request) if request is not None else ""
    if target:
        origins.add(target)
    return origins


def _request_origin_allowed(env, request):
    origin = _request_origin(request)
    return bool(
        origin
        and (
            origin == _request_target_origin(request)
            or origin in _cors_allowed_origins(env, request)
        )
    )


def _merge_vary(value, *names):
    values = []
    seen = set()
    for item in str(value or "").split(",") + list(names):
        item = str(item or "").strip()
        lowered = item.lower()
        if item and lowered not in seen:
            values.append(item)
            seen.add(lowered)
    return ", ".join(values)


def _cors_headers(env, request, preflight=False):
    origin = _request_origin(request)
    if not origin or not _request_origin_allowed(env, request):
        return {}
    headers = {
        "access-control-allow-origin": origin,
        "access-control-allow-credentials": "true",
        "access-control-expose-headers": ", ".join(_CORS_EXPOSE_HEADERS),
        "vary": "Origin",
    }
    if not preflight:
        return headers
    requested = str(
        request.headers.get("access-control-request-headers") or "")
    requested_headers = []
    for value in requested.split(","):
        value = value.strip().lower()
        if not value:
            continue
        if not _CORS_HEADER_TOKEN_RE.fullmatch(value):
            return {}
        if value not in requested_headers:
            requested_headers.append(value)
    allowed_headers = list(_CORS_DEFAULT_HEADERS)
    for value in requested_headers:
        if value not in allowed_headers:
            allowed_headers.append(value)
    headers.update({
        "access-control-allow-methods": ", ".join(_CORS_METHODS),
        "access-control-allow-headers": ", ".join(allowed_headers),
        "access-control-max-age": "86400",
        "vary": _merge_vary(
            headers["vary"],
            "Access-Control-Request-Method",
            "Access-Control-Request-Headers",
        ),
    })
    if str(request.headers.get(
            "access-control-request-private-network") or "").lower() == (
            "true"):
        headers["access-control-allow-private-network"] = "true"
    return headers


def _open_pull_cors_headers(request, path, preflight=False):
    if not _request_origin(request) or not REPO_PULLS_RE.match(
            str(path or "")):
        return {}
    headers = {"access-control-allow-origin": "*", "vary": "Origin"}
    if not preflight:
        return headers
    if str(request.headers.get("access-control-request-method") or "") \
            .upper() != "POST":
        return {}
    headers.update({
        "access-control-allow-methods": "POST, OPTIONS",
        "access-control-allow-headers": "accept, content-type",
        "access-control-max-age": "86400",
    })
    return headers


def _api_cors_preflight_response(env, request, path):
    if (
        method_name(request) != "OPTIONS"
        or not (path == "/api" or str(path or "").startswith("/api/"))
        or not request.headers.get("access-control-request-method")
    ):
        return None
    headers = (_cors_headers(env, request, preflight=True)
               or _open_pull_cors_headers(request, path, preflight=True))
    if not headers:
        return json_response(
            {"error": "origin_not_allowed"}, status=403,
            cache_control="no-store")
    requested_method = str(
        request.headers.get("access-control-request-method") or "").upper()
    if requested_method not in _CORS_METHODS:
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store", extra_headers=headers)
    return Response(None, status=204, headers=headers)


def _api_cors_response(env, request, response, path):
    if not (path == "/api" or str(path or "").startswith("/api/")):
        return response
    headers = _cors_headers(env, request) or (
        _open_pull_cors_headers(request, path)
        if method_name(request) == "POST" else {})
    if not headers:
        return response
    try:
        status = int(getattr(response, "status", 200) or 200)
    except Exception:
        status = 200
    if status == 101:
        return response
    wrapped = response
    if not hasattr(wrapped, "js_object"):
        wrapped = Response(response)
    current_headers = [
        (str(name).lower(), value) for name, value in wrapped.headers.items()
    ]
    existing_vary = ", ".join(
        str(value) for name, value in current_headers if name == "vary")
    headers["vary"] = _merge_vary(
        existing_vary, headers["vary"])
    replaced = set(headers)
    current_headers = [
        (name, value) for name, value in current_headers
        if name not in replaced
    ]
    current_headers.extend(headers.items())
    return Response(
        wrapped.body,
        status=status,
        status_text=str(getattr(wrapped, "status_text", "") or ""),
        headers=current_headers,
    )


def _request_account_session_token(request, payload=None):
    payload = payload if isinstance(payload, dict) else {}
    token = clean_string(payload.get("sessionToken", ""), 512).strip()
    if not token:
        auth = request.headers.get("authorization") or ""
        if auth.lower().startswith("bearer "):
            token = clean_string(auth[7:], 512).strip()
    # Browser localStorage retains only this non-secret marker. Cookie auth is
    # selected explicitly rather than trying to validate it as a bearer.
    if token == "cookie":
        token = ""
    cookie_auth = not token
    if cookie_auth:
        token = clean_string(
            _cookie_value(request, ACCOUNT_SESSION_COOKIE), 512
        ).strip()
    return token, cookie_auth


def _request_account_session_id(request, payload=None):
    """Return the opaque id carried by this request's account-session token.

    Callers must first validate the token through ``_account_session_record``.
    Parsing the already-validated request again avoids a second D1 lookup while
    still binding a short-lived Office ticket to the exact revocable session.
    """
    try:
        token, _cookie_auth = _request_account_session_token(request, payload)
    except Exception:
        return ""
    match = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
        clean_string(token or "", 512).strip())
    return match.group(1) if match else ""


async def _account_session_lookup(env, token, touch=True):
    match = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
        clean_string(token or "", 512).strip())
    if not match:
        return "", None, ""
    session_id = match.group(1)
    # A session minted by a key-bound login carries its account_devices row;
    # the LEFT JOIN lets a device revoked from the web close that session on
    # the very next request without a second round trip.
    row = await d1_first_primary(
        env,
        "SELECT s.account_bi,s.token_digest,s.last_seen_at,s.expires_at,"
        "s.revoked_at,s.device_bi,"
        "d.enabled AS device_enabled,d.revoked_at AS device_revoked_at "
        "FROM account_sessions AS s "
        "LEFT JOIN account_devices AS d ON d.device_bi=s.device_bi "
        "WHERE s.session_id=?",
        session_id,
    )
    now = int(Date.now())
    if (
        not row
        or int(row.get("revoked_at") or 0)
        or int(row.get("expires_at") or 0) <= now
        or not hmac.compare_digest(
            str(row.get("token_digest") or ""),
            _account_session_token_digest(env, token),
        )
    ):
        return "", None, ""
    if str(row.get("device_bi") or "") and (
            int(row.get("device_revoked_at") or 0)
            or not int(row.get("device_enabled") or 0)):
        # The node key this session was minted from was revoked (or purged)
        # in the web registry: the session dies with it. See
        # _account_session_invalid_error for the distinguishing error code.
        return "", None, ""
    account_bi = str(row.get("account_bi") or "")
    account_row = await d1_first_primary(
        env, "SELECT data FROM users WHERE user_bi=?", account_bi)
    rec = await decrypt_row(env, (account_row or {}).get("data", ""))
    if not rec or rec.get("status") != "active" or _account_kind(rec) != "user":
        return "", None, ""
    caller = globals().get("_D1_QUERY_CALLER")
    if caller is not None:
        caller.note_session(rec.get("name"), session_id)
    if (
        touch
        and now - int(row.get("last_seen_at") or 0)
        >= ACCOUNT_SESSION_TOUCH_MS
        and not _read_only(env)
    ):
        # The touch also lifts a session minted under the old twelve-hour
        # lifetime to the full account lifetime from its sign-in, so a browser
        # that is signed in today stays signed in without logging in again.
        await d1_run(
            env,
            "UPDATE account_sessions SET last_seen_at=?,"
            "expires_at=MAX(expires_at,created_at+?) "
            "WHERE session_id=? AND revoked_at=0",
            now,
            ACCOUNT_SESSION_TTL_MS,
            session_id,
        )
    return account_bi, rec, session_id


ACCOUNT_SESSION_MEMO_MS = 5 * 1000
ACCOUNT_SESSION_MEMO_MAX = 1024
_ACCOUNT_SESSION_MEMO = {}
_ACCOUNT_SESSION_MEMO_EPOCH = [0]


def _account_session_memo_forget():
    _ACCOUNT_SESSION_MEMO_EPOCH[0] += 1
    _ACCOUNT_SESSION_MEMO.clear()


def _account_session_memo_store(memo, key, value, epoch):
    if epoch != _ACCOUNT_SESSION_MEMO_EPOCH[0]:
        return
    if len(memo) >= ACCOUNT_SESSION_MEMO_MAX:
        memo.clear()
    memo[key] = value


def _session_device_revoked(row):
    """True when a session's bound device row is revoked, disabled or gone."""
    device_bi = str((row or {}).get("device_bi") or "")
    if not device_bi:
        return False
    try:
        device_revoked_at = int(row.get("device_revoked_at") or 0)
    except (TypeError, ValueError):
        device_revoked_at = 0
    try:
        device_enabled = int(row.get("device_enabled") or 0)
    except (TypeError, ValueError):
        device_enabled = 0
    return bool(device_revoked_at) or not device_enabled


async def _account_session_invalid_error(env, token):
    """Error code for a session token that failed ``_account_session_lookup``.

    ``device_revoked`` lets a node that was signed out from the web registry
    tell that case apart from an expired or logged-out session and rotate its
    key; everything else stays the generic ``invalid_session``.
    """
    match = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
        clean_string(token or "", 512).strip())
    if not match:
        return "invalid_session"
    try:
        row = await d1_first(
            env,
            "SELECT s.device_bi,"
            "d.enabled AS device_enabled,d.revoked_at AS device_revoked_at "
            "FROM account_sessions AS s "
            "LEFT JOIN account_devices AS d ON d.device_bi=s.device_bi "
            "WHERE s.session_id=?",
            match.group(1),
        )
    except Exception:
        return "invalid_session"
    if row and _session_device_revoked(row):
        return "device_revoked"
    return "invalid_session"


async def _account_session_device_bi(env, session_id):
    """The account_devices row the given session was minted from ('' if none)."""
    session_id = clean_string(session_id or "", 64)
    if not session_id:
        return ""
    row = await d1_first(
        env,
        "SELECT device_bi FROM account_sessions WHERE session_id=?",
        session_id,
    )
    return clean_string((row or {}).get("device_bi", ""), 128)


async def _account_session_token_name(env, token):
    _, rec, _ = await _account_session_lookup(env, token)
    return clean_string(
        (rec or {}).get("name", ""), MAX_NODE_NAME).lower()


async def _account_revoke_device_sessions(env, account_bi, device_bi):
    """Revoke every session a key-bound login of this device minted."""
    device_bi = clean_string(device_bi or "", 128)
    if not account_bi or not device_bi:
        return
    await d1_run(
        env,
        "UPDATE account_sessions SET revoked_at=? "
        "WHERE account_bi=? AND device_bi=? AND revoked_at=0",
        int(Date.now()),
        account_bi,
        device_bi,
    )


async def _account_revoke_sessions(env, account_bi, session_id=""):
    now = int(Date.now())
    if session_id:
        await d1_run(
            env,
            "UPDATE account_sessions SET revoked_at=? "
            "WHERE account_bi=? AND session_id=? AND revoked_at=0",
            now,
            account_bi,
            session_id,
        )
    else:
        await d1_run(
            env,
            "UPDATE account_sessions SET revoked_at=? "
            "WHERE account_bi=? AND revoked_at=0",
            now,
            account_bi,
        )


# Signup hands out a session immediately so the new account can finish setting
# itself up, but an address nobody has confirmed does not buy the product yet:
# every state-changing call an unverified session authorizes is refused (issue
# #592 — a "Continue to dashboard" button walked a never-verified signup
# straight into the authenticated app, so bulk automated signups reached the
# write APIs). Reads stay open so the pending-verification screen can render,
# and the account-lifecycle endpoints that must keep working while unverified
# (resend the link, edit nothing but the address, delete the account) opt out
# with allow_unverified.
UNVERIFIED_SAFE_METHODS = ("GET", "HEAD", "OPTIONS")
UNVERIFIED_EMAIL_ERROR = "email_not_verified"
# The pending-verification screen an unverified caller is sent to.
VERIFY_PENDING_PATH = "/verify-pending"
# The only POST /api/accounts/profile keys an unverified account may send: the
# identifying/auth fields plus "let me out" and "send the link again". Anything
# else on that body is a profile edit and is refused until confirmation.
UNVERIFIED_PROFILE_FIELDS = frozenset({
    "nodeName", "identifier", "email", "sessionToken", "password", "totp",
    "deleteAccount", "disableAccount", "resendVerification",
})


def _account_email_unverified(rec):
    """True when this record is a web account with an unconfirmed address.

    Key-bound nodes authenticate by signature and usually carry no address at
    all, so only ``kind == "user"`` records are held back, and a record with no
    address on file has nothing to confirm.
    """
    if not isinstance(rec, dict):
        return False
    if _account_kind(rec) != "user":
        return False
    if rec.get("email_verified"):
        return False
    return bool(clean_string(rec.get("email", ""), 254).strip())


def _email_not_verified_response():
    return json_response(
        {
            "error": UNVERIFIED_EMAIL_ERROR,
            "message": (
                "Confirm your email address to finish setting up this "
                "account. Open the link we sent you, or request a new one."
            ),
            "verifyUrl": VERIFY_PENDING_PATH,
        },
        status=403,
        cache_control="no-store, max-age=0, must-revalidate",
    )


async def _account_session_record(env, request, data=None,
                                  allow_unverified=False):
    payload = data if isinstance(data, dict) else {}
    token, cookie_auth = _request_account_session_token(request, payload)
    if (
        cookie_auth
        and method_name(request) not in ("GET", "HEAD", "OPTIONS")
        and not _request_origin_allowed(env, request)
    ):
        return "", None
    if not cookie_auth and str(token or "").startswith("fmat_"):
        return await apps_gated_session(env, request, token)
    if (getattr(env, "HOST_BACKGROUND", None) is not None
            and method_name(request) in ("GET", "HEAD")):
        name_bi, rec, _ = await _account_session_lookup_memo(env, token)
    else:
        name_bi, rec, _ = await _account_session_lookup(env, token)
    if not name_bi or not rec:
        return "", None
    # Raised rather than returned so the ~70 call sites keep their two-value
    # contract and none of them can forget the check; _fetch_inner turns it
    # into the one 403 the clients read (same shape as the existing
    # legacy_custody_migration_required escape).
    if (
        not allow_unverified
        and method_name(request) not in UNVERIFIED_SAFE_METHODS
        and _account_email_unverified(rec)
    ):
        raise RuntimeError(UNVERIFIED_EMAIL_ERROR)
    return name_bi, rec


async def _authed_account_name(env, request, data=None):
    # The account name proven by a valid session token — the POST-body
    # `sessionToken` field or an `Authorization: Bearer` header — lowercased, or
    # "" when there is no valid session. Endpoints that act on a per-account
    # resource (notifications, the poll digest, repo metadata) use this so they
    # authorize on a signed session, never on a self-asserted `node`/`ownerAccount`
    # string a caller can set to anyone's name.
    _, rec = await _account_session_record(env, request, data)
    return (rec.get("name", "") if rec else "").strip().lower()


# Legacy reservations may still carry an unexpired historical deposit record.
# This helper recognizes only that migration-era state; new signup is free.
def _donation_in_progress(rec):
    if not rec.get("donation_address") or rec.get("donation_confirmed"):
        return False
    _, expires, _ = _donation_expiry_fields(rec, Date.now())
    return Date.now() < expires


def _transient_client_address(request):
    """Read an address transiently for an endpoint-specific blind index."""
    try:
        headers = request.headers
    except Exception:
        return ""
    value = (headers.get("cf-connecting-ip") or "").strip()
    if not value:
        forwarded = (headers.get("x-forwarded-for") or "").strip()
        value = forwarded.split(",")[0].strip() if forwarded else ""
    return value[:64]


def _generalized_client_category(request):
    """Reduce a user agent to a non-identifying category."""
    try:
        ua = str(request.headers.get("user-agent") or "").lower()
    except Exception:
        ua = ""
    if any(marker in ua for marker in (
            "bot", "crawler", "spider", "curl/", "wget/", "scanner")):
        return "automated-client"
    if "mobile" in ua:
        return "mobile-browser"
    if any(marker in ua for marker in (
            "mozilla/", "chrome/", "safari/", "firefox/", "edg/")):
        return "browser"
    return "other-client" if ua else ""


def _account_session_client_ip(request):
    """Canonicalize the edge-observed sign-in address for session management.

    Only Cloudflare's edge-set header is accepted; X-Forwarded-For is client
    controlled and is intentionally ignored. The value is stored against the
    session row and returned exclusively to the account that owns it, so the
    owner can tell an unfamiliar device apart before revoking it.
    """
    try:
        raw = str(request.headers.get("cf-connecting-ip") or "")
    except Exception:
        return ""
    try:
        return str(ipaddress.ip_address(raw.strip().strip("[]")[:64]))[:64]
    except (ValueError, TypeError):
        return ""


def _account_session_device_label(request, desktop=False):
    """Return a coarse owner-visible label without retaining a raw user agent."""
    if desktop:
        return "Desktop node"
    return {
        "mobile-browser": "Mobile browser",
        "browser": "Web browser",
        "automated-client": "Automated client",
        "other-client": "Other client",
    }.get(_generalized_client_category(request), "Unknown device")


def _status_update_signature(env, generated_at):
    canonical = (
        "forkmesh-status-update-v1\n%d" % int(generated_at)
    ).encode()
    return hmac.new(
        _account_session_secret(env), canonical, "sha256").hexdigest()


async def _world_broadcast_status_update(env, generated_at):
    """Ring live status consumers after an atomic snapshot publication."""
    generated_at = int(generated_at)
    world_id = env.FORKMESH_WORLD.idFromName("town-square-v1")
    world_object = env.FORKMESH_WORLD.get(world_id)
    payload = {"generatedAt": generated_at}
    control_request = JsRequest.new(
        "https://forkmesh.internal/api/status/push",
        to_js({
            "method": "POST",
            "headers": {
                "content-type": "application/json",
                "x-forkmesh-status-control": _status_update_signature(
                    env, generated_at),
            },
            "body": json.dumps(payload, separators=(",", ":")),
        }),
    )
    response = await world_object.fetch(control_request)
    return int(getattr(response, "status", 0) or 0) == 200


# A brand-new member is announced live to everyone who already has a socket
# open — the 3D World and the shared #general room (website chat pages, the
# World's embedded chat panel, and desktop nodes all hold that one room).
# The announcement is signed by the outer Worker, so a browser socket can
# never forge a welcome, and it is short-lived: a signature captured off the
# wire is useless once NEW_MEMBER_ANNOUNCE_MAX_AGE_MS has passed.
NEW_MEMBER_ANNOUNCE_MAX_AGE_MS = 60 * 1000


def _new_member_signature(env, name, at):
    canonical = (
        "forkmesh-new-member-v1\n%s\n%d" % (name, int(at))
    ).encode()
    return hmac.new(
        _account_session_secret(env), canonical, "sha256").hexdigest()


async def _broadcast_new_member(env, name):
    """Tell every live World and #general socket that an account just joined.

    Best effort by construction: signup must never fail because a Durable
    Object was unreachable, so every leg is guarded and the return value only
    reports whether at least one room accepted the announcement.
    """
    handle = clean_string(name, MAX_NODE_NAME).strip().lower()
    if not valid_node_name(handle):
        return False
    announced_at = int(Date.now())
    body = json.dumps(
        {"name": handle, "at": announced_at}, separators=(",", ":"))
    signature = _new_member_signature(env, handle, announced_at)
    delivered = False
    for binding_name, object_name, url in (
        ("FORKMESH_WORLD", "town-square-v1",
         "https://forkmesh.internal/api/world/new-member"),
        ("FORKMESH_MAINNODE_ROOM", PUBLIC_WORLD_GENERAL_ROOM_KEY,
         "https://forkmesh.internal/api/chat/new-member"),
    ):
        try:
            binding = getattr(env, binding_name)
            room = binding.get(binding.idFromName(object_name))
            response = await room.fetch(JsRequest.new(url, to_js({
                "method": "POST",
                "headers": {
                    "content-type": "application/json",
                    "x-forkmesh-new-member": signature,
                },
                "body": body,
            })))
            if int(getattr(response, "status", 0) or 0) == 200:
                delivered = True
        except Exception:
            continue
    return delivered


def _new_member_announcement(env, data, signature, now):
    """Shared verifier for both rooms: returns the handle, or "" when unsigned.

    The frame carries one fact — a public account name — and it is only worth
    anything for a minute, so a replayed capture cannot re-run the party.
    """
    if not isinstance(data, dict):
        return ""
    name = clean_string(data.get("name", ""), MAX_NODE_NAME).strip().lower()
    try:
        announced_at = int(data.get("at") or 0)
    except (TypeError, ValueError):
        return ""
    if (
        not valid_node_name(name)
        or abs(int(now) - announced_at) > NEW_MEMBER_ANNOUNCE_MAX_AGE_MS
    ):
        return ""
    if not hmac.compare_digest(
            str(signature or ""),
            _new_member_signature(env, name, announced_at)):
        return ""
    return name


# The desktop's Nodes page deletes a node from the app, and the ordinary launch
# path is authenticateSilently() — keys, no session token at all (adhoc #63
# family). Without this the button would answer not_admin to the very operator
# who owns the mesh. The proof names the exact node it removes, so a captured
# signature can only ever re-delete that same node inside the skew window, and
# _is_admin still gates the caller exactly as it does a session-token one.
WORLD_NODE_DELETE_PROOF = "forkmesh-world-node-delete-v1"


# Password-based users may be created only after the browser has loaded the
# canonical /signup page. The page response mints a short-lived, HttpOnly,
# server-recorded claim; this endpoint checks it before parsing attacker input
# and consumes it atomically immediately before the account write. Origin or
# Referer headers alone are not authorization and are deliberately not trusted.
ACCOUNT_SIGNUP_INTENT_COOKIE = "forkmesh_signup_intent"
ACCOUNT_SIGNUP_INTENT_TTL_MS = 15 * 60 * 1000
ACCOUNT_SIGNUP_INTENT_FUTURE_SKEW_MS = 5 * 1000
ADMIN_SIGNUP_REFERRAL_CODE_CONTEXT = "admin-signup-referral-code-v1:"


def _admin_signup_referral_code_default(env):
    """Initial persisted mode for a relay that has no settings row yet."""
    return str(
        getattr(env, "SIGNUP_REFERRAL_CODE_MODE", "") or ""
    ).strip().lower() in ("1", "true", "yes", "on", "enabled")


def _admin_signup_referral_code_normalize(value):
    compact = re.sub(
        r"[\s-]+", "", clean_string(value or "", 64).strip().upper())
    if not re.fullmatch(r"FM[A-Z2-7]{16}", compact):
        return ""
    return "FM-" + "-".join(
        compact[index:index + 4] for index in range(2, len(compact), 4))


def _new_admin_signup_referral_code():
    raw = base64.b32encode(_random_bytes(10)).decode("ascii").rstrip("=")
    return _admin_signup_referral_code_normalize("FM" + raw)


async def _admin_signup_referral_code_bi(env, code):
    normalized = _admin_signup_referral_code_normalize(code)
    if not normalized:
        return ""
    return await blind_index(
        env, ADMIN_SIGNUP_REFERRAL_CODE_CONTEXT + normalized)


async def _ensure_admin_signup_referral_code(env):
    """Return the encrypted singleton, creating or repairing it if needed."""
    row = await d1_first_primary(
        env,
        "SELECT code_bi,data,enabled,generation,created_at,updated_at,last_used_at "
        "FROM admin_signup_referral_code WHERE id=1",
    )
    if not row:
        now = int(Date.now())
        code = _new_admin_signup_referral_code()
        code_bi = await _admin_signup_referral_code_bi(env, code)
        sealed = await encrypt_row(env, {"code": code})
        await d1_run(
            env,
            "INSERT OR IGNORE INTO admin_signup_referral_code "
            "(id,code_bi,data,enabled,generation,created_at,updated_at) "
            "VALUES (1,?,?,?,1,?,?)",
            code_bi, sealed,
            1 if _admin_signup_referral_code_default(env) else 0,
            now, now,
        )
        row = await d1_first_primary(
            env,
            "SELECT code_bi,data,enabled,generation,created_at,updated_at,last_used_at "
            "FROM admin_signup_referral_code WHERE id=1",
        )
    protected = await decrypt_row(env, (row or {}).get("data", "")) or {}
    code = _admin_signup_referral_code_normalize(protected.get("code", ""))
    expected_bi = await _admin_signup_referral_code_bi(env, code)
    if row and code and hmac.compare_digest(
            str(row.get("code_bi") or ""), expected_bi):
        return row, code

    # A corrupt legacy/manual row must fail closed for signup but should not
    # permanently strand the administrators. Replace only the exact row we
    # inspected so a concurrent healthy rotation always wins.
    now = int(Date.now())
    code = _new_admin_signup_referral_code()
    code_bi = await _admin_signup_referral_code_bi(env, code)
    sealed = await encrypt_row(env, {"code": code})
    previous_bi = str((row or {}).get("code_bi") or "")
    repaired = await d1_first(
        env,
        "UPDATE admin_signup_referral_code SET code_bi=?,data=?,"
        "generation=generation+1,updated_at=? WHERE id=1 AND code_bi=? "
        "RETURNING code_bi,data,enabled,generation,created_at,updated_at,last_used_at",
        code_bi, sealed, now, previous_bi,
    )
    if repaired:
        return repaired, code
    row = await d1_first_primary(
        env,
        "SELECT code_bi,data,enabled,generation,created_at,updated_at,last_used_at "
        "FROM admin_signup_referral_code WHERE id=1",
    )
    protected = await decrypt_row(env, (row or {}).get("data", "")) or {}
    code = _admin_signup_referral_code_normalize(protected.get("code", ""))
    expected_bi = await _admin_signup_referral_code_bi(env, code)
    if not row or not code or not hmac.compare_digest(
            str(row.get("code_bi") or ""), expected_bi):
        raise RuntimeError("admin signup referral code unavailable")
    return row, code


async def _admin_signup_referral_code_mode(env):
    """Return the administrator-controlled, persisted signup-gate mode."""
    row, _code = await _ensure_admin_signup_referral_code(env)
    return int(row.get("enabled") or 0) == 1


async def _set_admin_signup_referral_code_mode(env, enabled):
    """Persist the administrator's signup-gate choice."""
    await _ensure_admin_signup_referral_code(env)
    value = 1 if enabled else 0
    await d1_run(
        env,
        "UPDATE admin_signup_referral_code SET enabled=?,updated_at=? "
        "WHERE id=1",
        value, int(Date.now()),
    )
    return bool(value)


async def _admin_signup_referral_code_state(env):
    row, code = await _ensure_admin_signup_referral_code(env)
    enabled = int(row.get("enabled") or 0) == 1
    return {
        "enabled": enabled,
        "code": code if enabled else "",
        "generation": max(1, int(row.get("generation") or 1)),
        "updatedAt": max(0, int(row.get("updated_at") or 0)),
        "lastUsedAt": max(0, int(row.get("last_used_at") or 0)),
    }


async def _admin_signup_referral_code_matches(env, supplied):
    if not await _admin_signup_referral_code_mode(env):
        return True
    supplied_bi = await _admin_signup_referral_code_bi(env, supplied)
    if not supplied_bi:
        return False
    row = await d1_first_primary(
        env,
        "SELECT code_bi FROM admin_signup_referral_code "
        "WHERE id=1 AND code_bi=?",
        supplied_bi,
    )
    return bool(row)


async def _rotate_admin_signup_referral_code(env, supplied, account_bi):
    """Consume the matching generation and install a fresh display code."""
    if not await _admin_signup_referral_code_mode(env):
        return 0
    supplied_bi = await _admin_signup_referral_code_bi(env, supplied)
    if not supplied_bi:
        return -1
    next_code = _new_admin_signup_referral_code()
    next_bi = await _admin_signup_referral_code_bi(env, next_code)
    sealed = await encrypt_row(env, {"code": next_code})
    now = int(Date.now())
    rotated = await d1_first(
        env,
        "UPDATE admin_signup_referral_code SET code_bi=?,data=?,"
        "generation=generation+1,updated_at=?,last_used_at=?,"
        "last_used_by_bi=? WHERE id=1 AND code_bi=? RETURNING generation",
        next_bi, sealed, now, now, account_bi, supplied_bi,
    )
    if not rotated:
        return -1
    return max(1, int(rotated.get("generation") or 1)) - 1


def _account_signup_intent_signature(env, claim_id, issued_at, expires_at):
    canonical = (
        "forkmesh-account-signup-intent-v1\n" + claim_id + "\n"
        + str(int(issued_at)) + "\n" + str(int(expires_at))
    ).encode()
    key = (_require_data_secret(env) + ":account-signup-intent-v1").encode()
    return hmac.new(key, canonical, "sha256").hexdigest()


def _account_signup_intent_value(env, claim_id, issued_at, expires_at):
    signature = _account_signup_intent_signature(
        env, claim_id, issued_at, expires_at)
    return ".".join((claim_id, str(issued_at), str(expires_at), signature))


def _account_signup_intent_claim(env, request, now=None):
    value = clean_string(
        _cookie_value(request, ACCOUNT_SIGNUP_INTENT_COOKIE), 256).strip()
    parts = value.split(".")
    if len(parts) != 4:
        return None
    claim_id, issued_raw, expires_raw, signature = parts
    if (not re.fullmatch(r"[0-9a-f]{36}", claim_id)
            or not issued_raw.isdigit() or not expires_raw.isdigit()
            or not re.fullmatch(r"[0-9a-f]{64}", signature)):
        return None
    try:
        issued_at = int(issued_raw)
        expires_at = int(expires_raw)
        now = int(Date.now() if now is None else now)
    except (TypeError, ValueError, OverflowError):
        return None
    if (issued_at <= 0 or issued_at > now + ACCOUNT_SIGNUP_INTENT_FUTURE_SKEW_MS
            or expires_at <= now
            or expires_at - issued_at != ACCOUNT_SIGNUP_INTENT_TTL_MS):
        return None
    expected = _account_signup_intent_signature(
        env, claim_id, issued_at, expires_at)
    if not hmac.compare_digest(signature, expected):
        return None
    return {
        "claimId": claim_id,
        "issuedAt": issued_at,
        "expiresAt": expires_at,
    }


def _account_signup_intent_cookie(env, claim_id, issued_at, expires_at,
                                  secure=True):
    value = _account_signup_intent_value(
        env, claim_id, issued_at, expires_at)
    cookie = (
        ACCOUNT_SIGNUP_INTENT_COOKIE + "=" + value
        + "; Path=/api/accounts/signup; Max-Age=%d; HttpOnly; SameSite=Strict"
        % int(ACCOUNT_SIGNUP_INTENT_TTL_MS / 1000)
    )
    return cookie + ("; Secure" if secure else "")


async def _issue_account_signup_intent(env):
    now = int(Date.now())
    expires_at = now + ACCOUNT_SIGNUP_INTENT_TTL_MS
    claim_id = _random_bytes(18).hex()
    email_field_name = "contact_" + _random_bytes(9).hex()
    await d1_run(
        env,
        "INSERT INTO account_signup_intents "
        "(claim_id,issued_at,expires_at,email_field_name) VALUES (?,?,?,?)",
        claim_id, now, expires_at, email_field_name,
    )
    # Expired claims contain no user data, but pruning them here bounds the
    # table even when visitors abandon the form without submitting it.
    await d1_run(
        env,
        "DELETE FROM account_signup_intents WHERE expires_at<?",
        now - ACCOUNT_SIGNUP_INTENT_TTL_MS,
    )
    return claim_id, now, expires_at, email_field_name


async def _account_signup_intent_available(env, claim):
    if not claim:
        return False
    row = await d1_first(
        env,
        "SELECT claim_id,email_field_name FROM account_signup_intents "
        "WHERE claim_id=? AND issued_at=? AND expires_at=? "
        "AND consumed_at=0 AND expires_at>=?",
        claim["claimId"], claim["issuedAt"], claim["expiresAt"],
        int(Date.now()),
    )
    return row


async def _consume_account_signup_intent(env, claim, account_bi):
    if not claim:
        return False
    claimed = await d1_first(
        env,
        "UPDATE account_signup_intents SET consumed_at=?,account_bi=? "
        "WHERE claim_id=? AND issued_at=? AND expires_at=? "
        "AND consumed_at=0 AND expires_at>=? RETURNING claim_id",
        int(Date.now()), account_bi, claim["claimId"], claim["issuedAt"],
        claim["expiresAt"], int(Date.now()),
    )
    return bool(claimed)


def _signup_page_required_response():
    return json_response(
        {"error": "signup_page_required", "signupUrl": "/signup"},
        status=403,
        cache_control="no-store, max-age=0, must-revalidate",
    )


SIGNUP_INTENT_PATH = "/api/accounts/signup/intent"


async def _account_signup_intent_renew(env, request):
    no_store = "no-store, max-age=0, must-revalidate"
    if not _request_origin_allowed(env, request):
        return json_response(
            {"error": "origin_not_allowed"}, status=403,
            cache_control=no_store)
    claim_id, issued_at, expires_at, email_field_name = (
        await _issue_account_signup_intent(env))
    url = urlparse(request.url)
    return json_response(
        {
            "emailField": email_field_name,
            "challengeCdata": _turnstile.signup_cdata(claim_id),
        },
        cache_control=no_store,
        extra_headers={"set-cookie": _account_signup_intent_cookie(
            env, claim_id, issued_at, expires_at,
            secure=(url.scheme == "https"))},
    )


def _signup_page_target(query):
    """Canonical /signup URL for a redirect, minus bot-challenge parameters.

    The edge interstitial that fronts this page replays the visitor's original
    navigation as a form POST to /signup?__cf_chl_f_tk=..., so those throwaway
    parameters must not survive into the address bar (or into a second replay).
    Everything else — notably the ?ref= / ?rid= referral attribution pair — is
    kept byte-for-byte so a referred visitor still earns their referrer credit.
    """
    kept = [
        pair for pair in str(query or "").split("&")
        if pair and not pair.split("=", 1)[0].startswith("__cf_chl")
    ]
    return "/signup" + ("?" + "&".join(kept) if kept else "")


# Cloudflare Turnstile (turnstile.py): Next's stand-in for production's zone
# WAF challenge on /signup*, which cannot apply to DNS-only Next hostnames.
_turnstile = _LazyModule("turnstile")


async def _turnstile_gate(env, request, data, action, challenge_url,
                          cdata="", log_path="", outcome=None):
    """None when the request carries a valid Turnstile token, else a refusal.

    Fails closed: a missing secret on a VPS, a siteverify timeout or an
    unexpected answer refuse with 503 turnstile_unavailable.
    """
    token = ""
    if isinstance(data, dict):
        token = data.get(_turnstile.TOKEN_FIELD, "")
    code, detail = await _turnstile.verify(
        env, token, action, remoteip=_account_session_client_ip(request),
        cdata=cdata)
    if not code:
        return None
    if isinstance(outcome, dict):
        outcome["code"] = code
        outcome["detail"] = detail
    status = _turnstile.STATUS.get(code, 403)
    if log_path:
        await log_blocked_signup(env, request, log_path, status, code)
    return json_response(
        _turnstile.refusal_payload(code, challenge_url), status=status,
        cache_control="no-store, max-age=0, must-revalidate")


async def _signup_backup_gate(env, request, data, cdata, outcome):
    code, detail = _turnstile.verify_backup(
        env, data.get(_turnstile.BACKUP_FIELD), cdata)
    if code:
        outcome["code"] = code
        outcome["detail"] = detail
        return json_response(
            _turnstile.refusal_payload(code, "/signup"),
            status=_turnstile.STATUS.get(code, 403),
            cache_control="no-store, max-age=0, must-revalidate")
    signup_ip = _transient_client_address(request)
    budgets = [(SIGNUP_BACKUP_RATE_KEY, SIGNUP_BACKUP_MAX_PER_WINDOW)]
    if signup_ip:
        budgets.insert(0, (await blind_index(
            env, SIGNUP_BACKUP_RATE_KEY + "\n" + signup_ip),
            SIGNUP_BACKUP_MAX_PER_IP))
    for key, limit in budgets:
        throttled = await signup_rate_check(env, key, limit)
        if throttled is not None:
            outcome["code"] = "rate_limited"
            outcome["detail"] = "backup_check"
            await log_blocked_signup(
                env, request, SIGNUP_PATH, 429, "rate_limited")
            return throttled
    return None


# Simple web signup: create an active account from node name + email + password.
# Solana payout details are intentionally handled later from the dashboard profile.
async def _account_signup(env, request):
    signup_claim = _account_signup_intent_claim(env, request)
    signup_intent = await _account_signup_intent_available(
        env, signup_claim)
    if not signup_intent:
        await log_blocked_signup(env, request, SIGNUP_PATH, 403,
                                 "signup_page_required")
        return await _signup_refused(
            env, "signup_page_required", 403, claim=signup_claim,
            response=_signup_page_required_response())
    try:
        data = await bounded_json_request(request)
    except Exception:
        return await _signup_refused(
            env, "invalid_json", 400, claim=signup_claim)
    # `email` is a hidden honeypot. The visible input's randomized name exists
    # only in the server-side intent row and in this one rendered page. A basic
    # bot that submits the conventional field receives a success-shaped answer
    # while no account is created and its one-use claim is burned.
    if clean_string(data.get("email", ""), 254).strip():
        await _consume_account_signup_intent(env, signup_claim, "")
        return json_response(
            {"ok": True, "accepted": True}, status=201,
            cache_control="no-store, max-age=0, must-revalidate",
        )
    # Human check before any account lookup: the token must come from the
    # widget on the very page view that minted this signup claim (cdata).
    turnstile_outcome = {}
    signup_cdata = _turnstile.signup_cdata(signup_claim.get("claimId", ""))
    backup_proof = data.get(_turnstile.BACKUP_FIELD)
    if backup_proof:
        refused = await _signup_backup_gate(
            env, request, data, signup_cdata, turnstile_outcome)
    else:
        refused = await _turnstile_gate(
            env, request, data, _turnstile.ACTION_SIGNUP, "/signup",
            cdata=signup_cdata, log_path=SIGNUP_PATH,
            outcome=turnstile_outcome)
    if refused is not None:
        return await _signup_refused(
            env, turnstile_outcome.get("code") or "turnstile_failed", 403,
            claim=signup_claim, response=refused,
            name=data.get("nodeName", ""),
            detail=turnstile_outcome.get("detail", ""))
    # Attribution funnel: the first real submission from this browser
    # session is the "started" step (deduped per session; never blocks).
    await _attribution.emit_from_request(
        env, request, "signup_started", {"path": "/signup"}, dedupe=True)
    signup_referral_code = _admin_signup_referral_code_normalize(
        data.get("signupReferralCode", ""))
    if not await _admin_signup_referral_code_matches(
            env, signup_referral_code):
        await log_blocked_signup(env, request, SIGNUP_PATH, 403,
                                 "invalid_signup_referral_code")
        return await _signup_refused(
            env, "invalid_signup_referral_code", 403, claim=signup_claim,
            name=data.get("nodeName", ""))
    email_field_name = clean_string(
        signup_intent.get("email_field_name", ""), 64).strip()
    if not re.fullmatch(r"contact_[0-9a-f]{18}", email_field_name):
        await log_blocked_signup(env, request, SIGNUP_PATH, 403,
                                 "signup_page_required")
        return await _signup_refused(
            env, "signup_page_required", 403, claim=signup_claim,
            response=_signup_page_required_response())
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    email = clean_string(
        data.get(email_field_name, ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    if not valid_node_name(name):
        return await _signup_refused(
            env, "invalid_node_name", 400, claim=signup_claim, name=name)
    if not valid_account_email(email):
        return await _signup_refused(
            env, "valid_email_required", 400, claim=signup_claim, name=name)
    if len(password) < 8:
        return await _signup_refused(
            env, "password_too_short", 400, claim=signup_claim, name=name)
    # Same org-namespace guard as _account_reserve (issue #388).
    _, org_holder = await _org_row(env, name)
    if org_holder:
        return await _signup_refused(
            env, "node_name_taken", 409, claim=signup_claim, name=name)

    name_bi, existing = await _account_row(env, name)
    if existing and (existing.get("status") == "active" or
                     existing.get("donation_confirmed") or
                     _donation_in_progress(existing)):
        return await _signup_refused(
            env, "node_name_taken", 409, claim=signup_claim, name=name)

    email_bi = await blind_index(env, email)
    quarantined = await d1_first(
        env,
        "SELECT 1 AS reserved FROM quarantined_users "
        "WHERE status<>'restored' AND (user_bi=? OR email_bi=?) LIMIT 1",
        name_bi, email_bi,
    )
    if quarantined:
        await log_blocked_signup(env, request, SIGNUP_PATH, 409,
                                 "account_pending_verification")
        return await _signup_refused(
            env, "account_pending_verification", 409, claim=signup_claim,
            name=name)
    dup = await d1_first(
        env, "SELECT user_bi AS name_bi FROM users WHERE email_bi=?", email_bi)
    if dup and dup.get("name_bi") != name_bi:
        return await _signup_refused(
            env, "email_taken", 409, claim=signup_claim, name=name)

    # Per-IP account-creation throttle (checked only once the name/email are
    # otherwise creatable, so a rejected duplicate doesn't burn the quota).
    signup_ip = _transient_client_address(request)
    throttled = await signup_rate_check(
        env, await blind_index(env, signup_ip) if signup_ip else None)
    if throttled is not None:
        await log_blocked_signup(env, request, SIGNUP_PATH, 429, "rate_limited")
        return await _signup_refused(
            env, "rate_limited", 429, claim=signup_claim, name=name,
            response=throttled)
    moderation_error = await username_moderation_error(env, name)
    if moderation_error:
        await log_blocked_signup(env, request, SIGNUP_PATH, 400,
                                 moderation_error)
        return await _signup_refused(
            env, moderation_error, 400, claim=signup_claim, name=name)

    # The atomic one-time transition is the final gate before any account data
    # is written. Concurrent replays of the same browser request cannot both
    # pass this UPDATE.
    if not await _consume_account_signup_intent(env, signup_claim, name_bi):
        return await _signup_refused(
            env, "signup_page_required", 403, claim=signup_claim, name=name,
            response=_signup_page_required_response())
    signup_code_generation = await _rotate_admin_signup_referral_code(
        env, signup_referral_code, name_bi)
    if signup_code_generation < 0:
        return await _signup_refused(
            env, "invalid_signup_referral_code", 403, claim=signup_claim,
            name=name)

    salt, phash = await hash_password(password)
    rec = existing or {}
    rec.update({
        "name": name,
        "email": email,
        "kind": "user",
        "pass_salt": salt,
        "pass_hash": phash,
    })
    account_names.apply_case(rec, account_names.clean_case(
        name, clean_string(data.get("nodeName", ""), MAX_NODE_NAME)))
    rec["status"] = "active"
    rec["email_verified"] = bool(rec.get("email_verified", False))
    # A reservation already carries created_at, but it is not a joined user
    # until signup promotes it to active. The duplicate-active guard above
    # makes this transition the one reliable signal for a welcome.
    is_new_member = not existing or existing.get("status") != "active"
    rec.setdefault("created_at", int(Date.now()))
    signup_meta = _signup_metadata(request)
    if backup_proof:
        signup_meta["challenge"] = "backup:" + (
            _turnstile.backup_reason(backup_proof) or "unknown")
    if signup_code_generation:
        signup_meta["adminReferralCodeGeneration"] = signup_code_generation
    signup_meta.update(await _capture_referral_source(
        env, name, data.get("ref", ""), data.get("referralToken", "")))
    old_signup = rec.get("signup")
    if isinstance(old_signup, dict) and old_signup.get("at"):
        signup_meta["at"] = int(old_signup.get("at") or signup_meta["at"])
    # Replace any legacy unbounded values with the canonical bounded signup
    # evidence returned only through the is_admin directory variant.
    rec["signup"] = signup_meta
    if data.get("marketingEmail") is True:
        marketing_email.apply_consent(rec, True, "signup", int(Date.now()))
    ip_bi = await blind_index(env, signup_ip) if signup_ip else None
    await _save_account(env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi)
    await _record_signup_origin(env, name_bi, rec)
    # Attribution: join the account to its browser session — or record it
    # under first_utm_source='unknown' when there is none — and emit the
    # funnel step. UTM values are never copied onto the account record;
    # reporting joins through the session. Best effort: a D1 hiccup here
    # must never fail an otherwise good signup.
    try:
        attribution_session = await _attribution.link_user(
            env, request, name_bi, SIGNUP_PATH)
        await _attribution.emit(
            env, attribution_session, "signup_completed",
            {"newMember": bool(is_new_member)})
    except Exception:
        pass
    if rec.get("email") and not rec["email_verified"]:
        sent = await _send_verification_email(env, request, name, rec["email"], rec=rec)
        if not sent:
            await _enqueue_verification(env, name_bi, name, rec["email"])
    # Drop the cached chat roster/activity so open chat pages and header badges
    # pick up the new account on their next poll instead of a TTL later.
    memos_clear = globals().get("_users_directory_memos_clear")
    if callable(memos_clear):
        memos_clear()
    await _users_directory_cache_forget()
    await edge_cache_delete(CHAT_ACTIVITY_CACHE_KEY)
    # Record the referrer; qualification and credit happen later.
    referral_state = await _record_referral_signup(
        env, name, data.get("ref", ""), request, signup_ip, ip_bi,
        data.get("referralToken", ""))
    if referral_state == "quarantined":
        return await _signup_refused(
            env, "account_pending_verification", 403, claim=signup_claim,
            name=name)
    # Somebody who followed a participant's hackathon invite link and then
    # created an account is in the hackathon: making them press Join again
    # on arrival would lose exactly the people that invite page earned. Best
    # effort -- campaign bookkeeping must never fail an otherwise good
    # signup.
    try:
        # rec["signup"]["referrer"] is the referrer _capture_referral_source
        # proved from the signed one-time click claim, not a name the
        # browser asserted.
        await _hackathon.on_signup(
            env, name, name_bi,
            (rec.get("signup") or {}).get("referrer", ""))
    except Exception:
        pass
    # Fireworks in every open World and chat client, plus a "say hello" link
    # back to #general. A relay hiccup must never fail an otherwise good
    # signup, so the announcement is best effort.
    if is_new_member:
        try:
            await _broadcast_new_member(env, name)
        except Exception:
            pass
        try:
            await chat_channels_api.post_welcome(
                _ChatChannelsRuntime(env, request), name)
        except Exception:
            pass
    # "Founding Member" badge: this account's row is already saved above, so
    # counting now tells whether it landed inside the first 100 real signups.
    user_count = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM users "
        "WHERE email_bi IS NOT NULL AND email_bi <> ''")
    if user_count and int(user_count.get("c") or 0) <= FIRST_100_USERS_LIMIT:
        await _award_badge(env, name, name_bi, "first_100_users")
    payload = await _account_public_payload(
        env, rec,
        session_device_label=_account_session_device_label(request),
        session_client_ip=_account_session_client_ip(request))
    return await _account_session_response(
        env, request, payload, status=201
    )


async def _account_password_record(env, data):
    identifier = clean_string(
        data.get("nodeName", "") or data.get("identifier", "") or
        data.get("email", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    if not identifier or not password:
        return "", None, "invalid_credentials"
    name_bi = ""
    rec = None
    if "@" in identifier:
        email_bi = await blind_index(env, identifier)
        row = await d1_first(
            env, "SELECT user_bi AS name_bi, data FROM users WHERE email_bi=?",
            email_bi)
        if row:
            name_bi = row.get("name_bi", "")
            rec = await decrypt_row(env, row.get("data"))
    elif valid_node_name(identifier):
        name_bi, rec = await _account_row(env, identifier)
    if not rec or rec.get("status") != "active" or not rec.get("pass_hash"):
        return "", None, "invalid_credentials"
    if not await verify_password(password, rec.get("pass_salt", ""), rec.get("pass_hash", "")):
        return "", None, "invalid_credentials"
    if _account_kind(rec) != "user":
        return "", None, "not_a_user"
    if not name_bi:
        name_bi = await blind_index(env, rec.get("name", ""))
    return name_bi, rec, ""


async def _account_follow(env, request, target_name, method):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    follower_bi, follower_rec = await _account_session_record(env, request, data)
    if not follower_rec:
        return json_response({"error": "invalid_session"}, status=401)

    target = clean_string(target_name, MAX_NODE_NAME).lower()
    if not valid_node_name(target):
        return json_response({"error": "not_found"}, status=404)
    # Any active, non-private account is followable — node accounts included,
    # matching the fediverse layer (_ap_user_federates) and the public
    # user-or-org page, which both treat the node name as a public identity.
    target_bi, target_rec = await _account_row(env, target)
    if (not target_rec or target_rec.get("status") != "active" or
            bool(target_rec.get("profile_private"))):
        return json_response({"error": "not_found"}, status=404)

    follower = clean_string(follower_rec.get("name", ""), MAX_NODE_NAME).lower()
    if follower == target:
        return json_response({"error": "cannot_follow_self"}, status=400)

    if method == "POST":
        await d1_run(
            env,
            """INSERT OR IGNORE INTO profile_follows
               (follower_bi, target_bi, follower_name, target_name, created_at)
               VALUES (?,?,?,?,?)""",
            follower_bi, target_bi, follower, target, int(Date.now()))
    else:
        await d1_run(
            env,
            "DELETE FROM profile_follows WHERE follower_bi=? AND target_bi=?",
            follower_bi, target_bi)

    for purge_name in (target, follower):
        await edge_cache_delete(ACCOUNT_LOOKUP_CACHE_PREFIX + quote(purge_name))
    social = await _account_social_counts(env, target, follower, target_rec)
    return json_response({"ok": True, "name": target, **social})


# Claim a public node name. This route is exclusively for a desktop/headless
# node, which must bind the reservation to its Ed25519 identity. Password-based
# users go through /signup and can never use reserve/finalize as an alternate
# account-creation path. Legacy confirmed-deposit flags are honored only to
# avoid reclaiming old names.
async def _account_reserve(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    pubkey = clean_string(data.get("pubkey", ""), 120)
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(name):
        return json_response({"error": "invalid_node_name"}, status=400)
    if not valid_node_pubkey(pubkey):
        return json_response(
            {"error": "desktop_node_proof_required"}, status=403)
    # Org names share the /<name>/<repo> URL namespace (issue #388): a name an
    # organization holds can never become a node name, or the org-alias URL
    # rewrite would be ambiguous.
    _, org_holder = await _org_row(env, name)
    if org_holder:
        return json_response({"error": "node_name_taken"}, status=409)

    name_bi, existing = await _account_row(env, name)
    quarantined = await d1_first(
        env,
        "SELECT 1 AS reserved FROM quarantined_users "
        "WHERE user_bi=? AND status<>'restored' LIMIT 1",
        name_bi,
    )
    if quarantined:
        return json_response({"error": "node_name_taken"}, status=409)
    if existing:
        ex_pub = existing.get("pubkey", "")
        if existing.get("status") == "active" or existing.get("donation_confirmed"):
            return json_response({"error": "node_name_taken"}, status=409)
        held_by_other = bool(ex_pub) and (not pubkey or ex_pub != pubkey)
        # A reservation bound to a different key only blocks the name while its
        # migration-era expiry window is still live. Otherwise it is abandoned,
        # so a fresh install can reclaim the name.
        if held_by_other and _donation_in_progress(existing):
            return json_response({"error": "node_name_taken"}, status=409)
        if held_by_other:
            # Reclaiming an abandoned reservation: drop the previous holder's
            # stale state so the new owner starts a clean, key-bound signup.
            existing = None
        # else: a stale/own reservation — allow re-reserving it (idempotent).

    if not _ts_ok(ts):
        return json_response({"error": "stale_request"}, status=401)
    canonical = ("forkmesh-reserve-v1\n" + name + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    # `existing` survives above only for an idempotent re-reserve of a name this
    # key already holds; a fresh claim (including a reclaimed abandoned name)
    # cleared it to None and gets the full first-claim check.
    if existing:
        moderation_error = established_username_moderation_error(name)
    else:
        moderation_error = await username_moderation_error(env, name)
    if moderation_error:
        await log_blocked_signup(
            env, request, NODE_RESERVE_PATH, 400, moderation_error)
        return json_response({"error": moderation_error}, status=400)
    # Node registrations are not behind the web signup's Turnstile check:
    # desktop and headless installers have no browser, and the Ed25519 proof
    # above already binds the claim to a node key. A fresh name claim instead
    # spends a per-IP budget (its own bucket, so a web signup and a desktop
    # install from one address do not starve each other); idempotent
    # re-reserves of a name this key already holds are free.
    if not existing:
        reserve_ip = _transient_client_address(request)
        throttled = await signup_rate_check(
            env, await blind_index(
                env, "node-reserve-v1\n" + reserve_ip) if reserve_ip else None)
        if throttled is not None:
            await log_blocked_signup(
                env, request, NODE_RESERVE_PATH, 429, "rate_limited")
            return throttled

    rec = existing or {}
    rec.update({
        "name": name,
        "kind": "node",
        "status": "reserved",
        "created_at": int(rec.get("created_at") or Date.now()),
        "pubkey": pubkey,
    })
    await _save_account(env, name_bi, rec)
    try:
        await touch_registered_node(env, name_bi, rec)
    except Exception:
        pass
    return json_response(
        {"ok": True, "nodeName": name, "status": "reserved"}, status=201)


# Legacy step-2 helpers remain below as unreachable migration documentation.
# The live endpoint returns 410: signup is free, and reward/fund transfers are
# unsigned plans completed by an explicitly configured owner-device signer.


def _amount_sol(lamports):
    return "%.9f" % (int(lamports) / LAMPORTS_PER_SOL)


# --- Custodial deposit signing ----------------------------------------------
# These rebuild the write path used by temporary per-purchase deposit
# addresses. They are reachable only from the deposit sweep, which is gated on
# _custodial_deposits_enabled(); the direct wallet-to-pool path never touches
# them and never puts a key on the Worker.
def _base58_decode(value):
    n = 0
    for ch in str(value or ""):
        if ch not in BASE58_INDEX:
            return b""
        n = n * 58 + BASE58_INDEX[ch]
    raw = n.to_bytes((n.bit_length() + 7) // 8, "big") if n else b""
    pad = 0
    for ch in str(value or ""):
        if ch == "1":
            pad += 1
        else:
            break
    return b"\x00" * pad + raw


def _shortvec(n):
    out = bytearray()
    while True:
        elem = n & 0x7F
        n >>= 7
        if n:
            elem |= 0x80
        out.append(elem)
        if not n:
            return bytes(out)


def _solana_transfer_message(from_addr, transfers, blockhash):
    account_addrs = [from_addr]
    for to_addr, _lamports in transfers:
        if to_addr not in account_addrs:
            account_addrs.append(to_addr)
    if SOLANA_SYSTEM_PROGRAM not in account_addrs:
        account_addrs.append(SOLANA_SYSTEM_PROGRAM)
    program_idx = account_addrs.index(SOLANA_SYSTEM_PROGRAM)
    out = bytearray()
    out += bytes([1, 0, 1])
    out += _shortvec(len(account_addrs))
    for addr in account_addrs:
        raw = _base58_decode(addr)
        if len(raw) != 32:
            return b""
        out += raw
    blockhash_raw = _base58_decode(blockhash)
    if len(blockhash_raw) != 32:
        return b""
    out += blockhash_raw
    out += _shortvec(len(transfers))
    for to_addr, lamports in transfers:
        data = struct.pack("<IQ", 2, int(lamports))
        out += bytes([program_idx])
        out += _shortvec(2) + bytes([0, account_addrs.index(to_addr)])
        out += _shortvec(len(data)) + data
    return bytes(out)


async def _solana_sign_message(from_addr, seed_b64url, message):
    pub = _base58_decode(from_addr)
    if len(pub) != 32 or not seed_b64url or not message:
        return b""
    try:
        jwk = {
            "kty": "OKP", "crv": "Ed25519", "x": _b64url_encode(pub),
            "d": seed_b64url, "ext": True, "key_ops": ["sign"],
        }
        key = await js_crypto.subtle.importKey(
            "jwk", to_js(jwk), to_js({"name": "Ed25519"}), False,
            _to_js(["sign"]),
        )
        sig = await js_crypto.subtle.sign(
            to_js({"name": "Ed25519"}), key,
            Uint8Array.new(_to_js(bytes(message))))
        return bytes(Uint8Array.new(sig).to_py())
    except Exception:
        return b""


async def _solana_latest_blockhash(env):
    resp = await _solana_rpc(env, "getLatestBlockhash", [])
    if not isinstance(resp, dict):
        return ""
    try:
        return str(resp["result"]["value"]["blockhash"] or "")
    except Exception:
        return ""


async def _solana_send_transaction(env, tx_bytes):
    encoded = base64.b64encode(tx_bytes).decode()
    resp = await _solana_rpc_write(
        env, "sendTransaction",
        [encoded, {"encoding": "base64", "skipPreflight": False}],
    )
    if not isinstance(resp, dict):
        return ""
    result = resp.get("result")
    return str(result or "") if result else ""


async def _solana_send_transfers(env, from_addr, seed_b64url, transfers):
    transfers = [(to, int(lamports)) for to, lamports in transfers
                 if SOLANA_RE.match(to or "") and int(lamports) > 0]
    if not transfers:
        return ""
    blockhash = await _solana_latest_blockhash(env)
    if not blockhash:
        return ""
    message = _solana_transfer_message(from_addr, transfers, blockhash)
    sig = await _solana_sign_message(from_addr, seed_b64url, message)
    if len(sig) != 64:
        return ""
    tx = _shortvec(1) + sig + message
    return await _solana_send_transaction(env, tx)


async def _new_solana_keypair():
    """Generate a fresh per-purchase deposit keypair.

    A Solana address is an Ed25519 public key. The 32-byte seed (the JWK "d"
    field) is what the sweep later signs with, so it is stored encrypted and
    deleted as soon as the sweep succeeds.
    """
    pair = await js_crypto.subtle.generateKey(
        to_js({"name": "Ed25519"}), True, _to_js(["sign", "verify"]))
    pub_raw = await js_crypto.subtle.exportKey("raw", pair.publicKey)
    pub = bytes(Uint8Array.new(pub_raw).to_py())
    jwk = await js_crypto.subtle.exportKey("jwk", pair.privateKey)
    seed_b64url = str(getattr(jwk, "d", "") or "")
    if len(pub) != 32 or not seed_b64url:
        return None, None
    return _base58_encode(pub), seed_b64url


def _solana_pay_uri(address, amount_lamports, reference="", message="Join ForkMesh"):
    uri = ("solana:" + address +
           "?amount=" + _amount_sol(amount_lamports))
    if reference:
        uri += "&reference=" + reference
    uri += ("&label=" + quote("ForkMesh") +
            "&message=" + quote(message))
    return uri


# --- Low-level balance check ------------------------------------------------
# Returns the address balance in lamports, or None if the RPC call failed (so
# callers can distinguish "zero balance" from "couldn't check"). This is the
# lowest-level on-chain read available: a single getBalance, no transaction
# history scan or third-party indexer.
async def _solana_balance_lamports(env, address):
    if not address or not SOLANA_RE.match(address):
        return None
    resp = await _solana_rpc(env, "getBalance", [address])
    if not isinstance(resp, dict):
        return None
    result = resp.get("result")
    if not isinstance(result, dict):
        return None
    try:
        return int(result.get("value"))
    except (TypeError, ValueError):
        return None


# --- Shared display-balance cache -------------------------------------------
# Every uncached getBalance is a public-RPC subrequest, and the surfaces that
# merely *show* an amount — the network payout table, the wallet leaderboard,
# an avatar's chest chip, the community pool card, the desktop rail chip —
# re-render orders of magnitude more often than a balance actually moves. One
# 20s-cached /network/stats rebuild used to spend one subrequest per listed
# wallet, per colo, all day; that is what made a single public endpoint the
# busiest thing the Worker talks to.
#
# So every display read goes through one hourly cache in D1 (wallet_balances,
# the table the leaderboard already keeps): an address costs at most one
# subrequest an hour no matter how many pages, colos or nodes ask for it.
#
# Someone who wants the number *now* presses the refresh button each of those
# surfaces carries, which forces a live read — floored at one per address per
# minute, so a held-down button still cannot become a flood.
#
# Money-gating reads deliberately do NOT come through here. Deposit sweeps,
# world-element purchases, bounty funding, signup donations and reward
# distribution keep calling _solana_balance_lamports directly, because an
# hour-old number must never authorize a transfer.
SOLANA_DISPLAY_BALANCE_TTL_MS = 60 * 60 * 1000
SOLANA_DISPLAY_BALANCE_FORCE_MIN_MS = 60 * 1000
# A page listing many wallets must not turn one refresh press into an unbounded
# burst of subrequests: the rest of the list keeps its stored reading and comes
# forward on the next press.
SOLANA_DISPLAY_REFRESH_MAX_PER_REQUEST = 8


# Honouring a refresh press means skipping the edge-cached copy, so the whole
# aggregate behind it is rebuilt — which is not free on the Free plan even when
# the balance reads themselves are floored. Bound how often any one isolate will
# do that per surface, so a held-down (or scripted) button falls back to the
# cached response instead of re-running the rebuild. scope -> last honoured ms.
_BALANCE_REFRESH_CLAIMS = {}


def _wants_balance_refresh(request, scope=""):
    """True when the caller pressed a manual "refresh balance" button.

    Pass ``scope`` on an endpoint whose refresh path skips an edge-cached
    response; the press is then also floored per isolate, not just per address.
    """
    try:
        params = parse_qs(urlparse(request.url).query)
    except Exception:
        return False
    asked = str(params.get("refresh", [""])[0] or "").strip().lower() in (
        "1", "true", "yes")
    if not asked or not scope:
        return asked
    now = int(Date.now())
    if now - int(_BALANCE_REFRESH_CLAIMS.get(scope, 0)) < (
            SOLANA_DISPLAY_BALANCE_FORCE_MIN_MS):
        return False
    if len(_BALANCE_REFRESH_CLAIMS) > 500:
        _BALANCE_REFRESH_CLAIMS.clear()
    _BALANCE_REFRESH_CLAIMS[scope] = now
    return True


async def _stored_wallet_balances(env):
    """Every stored reading keyed by address.

    One query covers a whole page render; the table is bounded by
    WALLET_BALANCE_RETAIN_ROWS, so this stays a single small read.
    """
    stored = {}
    try:
        rows = await d1_all(
            env, "SELECT wallet, lamports, checked_at FROM wallet_balances")
    except Exception:
        return stored
    for row in rows or []:
        wallet = str(row.get("wallet") or "")
        if wallet:
            stored[wallet] = (int(row.get("lamports") or 0),
                              int(row.get("checked_at") or 0))
    return stored


async def _store_wallet_balance(env, address, lamports, checked_at, name=""):
    """Record one reading. An empty name keeps whatever name is already there,
    so a nameless display read never blanks the leaderboard's label."""
    try:
        await d1_run(
            env,
            "INSERT INTO wallet_balances (wallet, name, lamports, checked_at) "
            "VALUES (?,?,?,?) ON CONFLICT(wallet) DO UPDATE SET "
            "name=CASE WHEN excluded.name<>'' THEN excluded.name "
            "ELSE wallet_balances.name END,"
            "lamports=excluded.lamports,checked_at=excluded.checked_at",
            address, name, int(lamports), int(checked_at))
    except Exception:
        pass


async def _display_balance_lamports(env, address, force=False, stored=None,
                                    name="", budget=None, reader=None):
    """Balance for a display surface: at most one live read per address/hour.

    Returns ``(lamports_or_None, checked_at_ms)``. ``lamports`` is None only
    when no reading has ever succeeded for the address — a stale reading always
    beats a blank, and ``checked_at`` lets the caller show the number's age.

    Pass ``stored`` (from _stored_wallet_balances) to price a whole list off one
    query, and ``budget`` — a one-key dict — to share
    SOLANA_DISPLAY_REFRESH_MAX_PER_REQUEST across that list. ``reader`` swaps in
    a different live read (the community pool needs its network-pinned one).
    """
    if not address or not SOLANA_RE.match(address):
        return None, 0
    now = int(Date.now())
    if stored is None:
        row = await d1_first(
            env,
            "SELECT lamports, checked_at FROM wallet_balances WHERE wallet=?",
            address) or {}
        lamports = int(row.get("lamports") or 0)
        checked_at = int(row.get("checked_at") or 0)
    else:
        lamports, checked_at = stored.get(address, (0, 0))
    # A forced read still honours a short floor; an unforced one waits the hour.
    floor = (SOLANA_DISPLAY_BALANCE_FORCE_MIN_MS if force
             else SOLANA_DISPLAY_BALANCE_TTL_MS)
    if checked_at and now - checked_at < floor:
        return lamports, checked_at
    if isinstance(budget, dict):
        if int(budget.get("left") or 0) <= 0:
            return (lamports, checked_at) if checked_at else (None, 0)
        budget["left"] = int(budget["left"]) - 1
    try:
        fresh = await (reader or _solana_balance_lamports)(env, address)
    except Exception:
        fresh = None
    if fresh is None:
        # The RPC could not answer: keep serving the last good reading rather
        # than publishing an unchecked address as zero.
        return (lamports, checked_at) if checked_at else (None, 0)
    await _store_wallet_balance(env, address, fresh, now, name)
    if isinstance(stored, dict):
        stored[address] = (int(fresh), now)
    return int(fresh), now


async def _account_donation_address(env, request):
    del env, request
    return json_response({
        "error": "legacy_custody_disabled",
        "notice": (
            "ForkMesh signup is free. The Worker no longer creates or holds "
            "deposit-wallet keys."
        ),
        "custody": "self-custodial-only",
    }, status=410, cache_control="no-store")


# Read-only compatibility view for a historical deposit. It projects public
# status and may read the public on-chain balance, but never rewrites the row,
# inspects its retained key field, signs, or broadcasts.
async def _account_donation_status(env, request):
    if not _is_main_relay(env):
        return await _federated_donation_status(env, request)
    params = parse_qs(urlparse(request.url).query)
    name = clean_string(params.get("nodeName", [""])[0], MAX_NODE_NAME).lower()
    _, rec = await _account_row(env, name)
    if not rec:
        return json_response({"error": "no_such_account"}, status=404)
    addr = rec.get("donation_address", "")
    if not addr:
        return json_response({"error": "no_donation_address"}, status=400)
    required = int(rec.get("donation_required_lamports", MIN_JOIN_LAMPORTS))
    now = int(Date.now())
    _, expires_at, delete_at = _donation_expiry_fields(rec, now)
    already_confirmed = bool(rec.get("donation_confirmed"))
    balance = await _solana_balance_lamports(env, addr)
    checking = balance is None
    received = (
        int(rec.get("donation_received_lamports", 0) or 0)
        if checking else int(balance)
    )
    paid = already_confirmed or (received >= required and required > 0)
    expired = not paid and received == 0 and now >= expires_at
    return json_response({
        "ok": True, "paid": paid, "checking": checking,
        "receivedLamports": received, "requiredLamports": required,
        "expired": expired, "hidden": expired, "canRenew": expired,
        "expiresAt": expires_at, "deleteAt": delete_at,
        "status": "legacy_custody_frozen",
        "custody": "migration-required",
        "completedTransfer": rec.get("donation_sweep_sig", ""),
        "notice": (
            "This is a read-only historical status. The Worker cannot access "
            "the retained wallet for signing or move its funds."
        ),
    }, cache_control="no-store")


async def _record_signup_origin(env, name_bi, rec):
    """Stamp users.signup_origin from the signup marker (migration 0175).

    Only the referral and organic rules can apply at signup time; anything
    they cannot prove stays 'unknown', which is also the column default. A
    database behind the migration lacks the column, so this never fails the
    signup that just succeeded.
    """
    origin = classify_signup_origin(rec)
    if origin == "unknown":
        return
    try:
        await d1_run(
            env, "UPDATE users SET signup_origin=? WHERE user_bi=?",
            origin, name_bi)
    except Exception:
        pass


def _signup_metadata(request):
    # users.data is encrypted at rest. Keep bounded signup evidence there for
    # automatic referral enforcement and the cryptographically authenticated
    # is_admin Users page; ordinary profile/directory payloads never include it.
    # users.ip_bi remains the indexed one-way equality token.
    return {
        "ip": _transient_client_address(request),
        "userAgent": _referral_user_agent(request),
        "country": world_request_country(request),
        "clientCategory": _generalized_client_category(request),
        "at": int(Date.now()),
    }


# Step 3: after a confirmed donation, set the email + password that unlock
# universal (any-surface) login. Email + password hash are stored encrypted.
_account_finalize = _route_handlers.export("_account_finalize")


async def _account_profile(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    public_profile_fields = {
        "avatarPng", "profileBio", "profileAbout", "profileReadme",
        "profileLocation", "profileTimezone", "profilePrivate",
        "followersPublic", "publicEmail", "mastodon",
        "profileLinks", "nodeName", "email", "identifier", "sessionToken",
        "nameCase",
        # The dashboard always sends a (usually empty) `password` field even on
        # pages with no password input. Whitelist it so a session-authed
        # public-profile save doesn't get shunted into the credentials branch
        # and rejected with invalid_credentials. Privileged writes still carry
        # a non-whitelisted key (solana, deleteAccount, …) and stay on the
        # password-verified path.
        "password",
    }
    # This handler owns the moves an unverified account must still be able to
    # make (resend the link, delete the account), and it has a second,
    # password-authenticated entry below that never touches the session gate —
    # so it opts out here and enforces the field-level rule itself.
    session_bi, session_rec = await _account_session_record(
        env, request, data, allow_unverified=True)
    if session_rec and not (set(data.keys()) - public_profile_fields):
        name_bi = session_bi
        rec = session_rec
    else:
        identifier = clean_string(
            data.get("nodeName", "") or data.get("identifier", "") or
            data.get("email", ""), 254).strip().lower()
        password = (data.get("password", "") or "")[:256]
        if not identifier or not password:
            return json_response({"error": "invalid_credentials"}, status=401)
        attempt_keys = await _login_attempt_keys(env, request, identifier)

        name_bi = ""
        rec = None
        if "@" in identifier:
            email_bi = await blind_index(env, identifier)
            row = await d1_first(
                env, "SELECT user_bi AS name_bi, data FROM users WHERE email_bi=?",
                email_bi)
            if row:
                name_bi = row.get("name_bi", "")
                rec = await decrypt_row(env, row.get("data"))
        elif valid_node_name(identifier):
            name_bi, rec = await _account_row(env, identifier)
        if not rec or rec.get("status") != "active" or not rec.get("pass_hash"):
            return await _login_failure_response(
                env, attempt_keys, "invalid_credentials")
        if not await verify_password(password, rec.get("pass_salt", ""), rec.get("pass_hash", "")):
            return await _login_failure_response(
                env, attempt_keys, "invalid_credentials")
        if not name_bi:
            name_bi = await blind_index(env, rec.get("name", ""))
        if (rec.get("totp_enrolled") and not (session_rec and session_bi == name_bi)
                and not await _account_totp_ok(
                    env, rec, clean_string(data.get("totp", ""), 10))):
            return await _login_failure_response(env, attempt_keys, "bad_totp")
        for attempt_key in attempt_keys:
            await _login_clear(env, attempt_key)

    # An unverified account may only leave (delete/disable) or ask for the
    # confirmation link again. Everything else here is public profile surface —
    # bio, avatar, links — i.e. exactly what a bulk fake signup would want, so
    # it stays shut until the address is confirmed. Knowing the password is no
    # bypass: this runs after both entry paths have resolved `rec`.
    if _account_email_unverified(rec) and (
            set(data.keys()) - UNVERIFIED_PROFILE_FIELDS):
        return _email_not_verified_response()

    if data.get("deleteAccount") or data.get("disableAccount"):
        await _delete_account_namespace(env, name_bi, rec)
        return json_response({"ok": True, "accountDeleted": True})

    changed = False
    # The Person actor doc only ever surfaces the bio and the profile-private
    # federation gate (_ap_build_actor_doc), so remember just those: the
    # Update(Person) broadcast below must not fire for payout/avatar/
    # notification tweaks — every no-op broadcast fans out one delivery per
    # follower server and pulls a rel=me refetch storm back at us.
    fed_before = (rec.get("profile_bio", ""), bool(rec.get("profile_private")),
                  bool(rec.get("profile_followers_public")))
    if "solana" in data:
        solana = clean_string(data.get("solana", ""), 64).strip()
        if solana and not SOLANA_RE.match(solana):
            return json_response({"error": "bad_solana"}, status=400)
        if solana:
            if rec.get("solana") != solana:
                rec["solana"] = solana
                changed = True
        elif rec.get("solana"):
            rec.pop("solana", None)
            changed = True

    if "avatarPng" in data:
        avatar_png, avatar_error = clean_avatar_png(data.get("avatarPng", ""))
        if avatar_error:
            status = 413 if avatar_error == "avatar_too_large" else 400
            return json_response({"error": avatar_error}, status=status)
        if avatar_png:
            if rec.get("avatar_png") != avatar_png:
                rec["avatar_png"] = avatar_png
                rec["avatar_updated_at"] = int(Date.now())
                changed = True
        elif rec.get("avatar_png"):
            rec.pop("avatar_png", None)
            rec["avatar_updated_at"] = int(Date.now())
            changed = True

    if "profileBio" in data:
        bio = clean_string(data.get("profileBio", ""), MAX_PROFILE_BIO).strip()
        if rec.get("profile_bio", "") != bio:
            if bio:
                rec["profile_bio"] = bio
            else:
                rec.pop("profile_bio", None)
            changed = True

    if "profileAbout" in data:
        raw_about = data.get("profileAbout", "")
        if len(str(raw_about or "").encode("utf-8")) > MAX_PROFILE_ABOUT:
            return json_response({"error": "profile_about_too_large"}, status=413)
        about = clean_string(raw_about, MAX_PROFILE_ABOUT).replace("\r\n", "\n")
        if rec.get("profile_about", "") != about:
            if about:
                rec["profile_about"] = about
            else:
                rec.pop("profile_about", None)
            changed = True

    if "profileReadme" in data:
        raw_readme = data.get("profileReadme", "")
        if len(str(raw_readme or "").encode("utf-8")) > MAX_PROFILE_README:
            return json_response({"error": "profile_readme_too_large"}, status=413)
        readme = clean_string(raw_readme, MAX_PROFILE_README).replace("\r\n", "\n")
        if rec.get("profile_readme", "") != readme:
            if readme:
                rec["profile_readme"] = readme
            else:
                rec.pop("profile_readme", None)
            changed = True

    if "profileLocation" in data:
        location = clean_string(
            data.get("profileLocation", ""), MAX_PROFILE_LOCATION).strip()
        if rec.get("profile_location", "") != location:
            if location:
                rec["profile_location"] = location
            else:
                rec.pop("profile_location", None)
            changed = True

    if "profileTimezone" in data:
        raw_timezone = clean_string(
            data.get("profileTimezone", ""), MAX_PROFILE_TIMEZONE).strip()
        timezone = _clean_profile_timezone(raw_timezone)
        if raw_timezone and not timezone:
            return json_response({"error": "bad_profile_timezone"}, status=400)
        if rec.get("profile_timezone", "") != timezone:
            if timezone:
                rec["profile_timezone"] = timezone
            else:
                rec.pop("profile_timezone", None)
            changed = True

    if "nameCase" in data:
        case_changed, case_error = account_names.apply_case(
            rec, clean_string(data.get("nameCase", ""), MAX_NODE_NAME))
        if case_error:
            return json_response({"error": case_error}, status=400)
        if case_changed:
            account_names.forget(rec.get("name", ""))
            changed = True

    if "profilePrivate" in data:
        profile_private = bool(data.get("profilePrivate"))
        if bool(rec.get("profile_private")) != profile_private:
            if profile_private:
                rec["profile_private"] = True
            else:
                rec.pop("profile_private", None)
            changed = True

    if "followersPublic" in data:
        followers_public = bool(data.get("followersPublic"))
        if bool(rec.get("profile_followers_public")) != followers_public:
            if followers_public:
                rec["profile_followers_public"] = True
            else:
                rec.pop("profile_followers_public", None)
            changed = True

    if "publicEmail" in data:
        # The Public email dropdown offers exactly the addresses this account
        # has confirmed (today: the single account address) plus "don't show".
        # Anything else — somebody else's address, or this account's own
        # unconfirmed one — is refused rather than quietly published, so the
        # stored flag can only ever mean "publish the verified address".
        wanted = clean_string(data.get("publicEmail", ""), 254).strip().lower()
        account_email = clean_string(rec.get("email", ""), 254).strip().lower()
        if wanted and (
                wanted != account_email or not rec.get("email_verified")):
            return json_response({"error": "bad_public_email"}, status=400)
        if bool(rec.get("profile_email_public")) != bool(wanted):
            if wanted:
                rec["profile_email_public"] = True
            else:
                rec.pop("profile_email_public", None)
            changed = True

    if "mastodon" in data:
        raw_mastodon = clean_string(data.get("mastodon", ""), 120).strip()
        mastodon = _clean_mastodon_handle(raw_mastodon)
        if raw_mastodon and not mastodon:
            return json_response({"error": "bad_mastodon"}, status=400)
        if rec.get("mastodon", "") != mastodon:
            if mastodon:
                rec["mastodon"] = mastodon
            else:
                rec.pop("mastodon", None)
            changed = True

    if "profileLinks" in data:
        links, link_error = await _clean_profile_links(
            env, rec, data.get("profileLinks"))
        if link_error:
            return json_response({"error": link_error}, status=400)
        if rec.get("profile_links", []) != links:
            if links:
                rec["profile_links"] = links
            else:
                rec.pop("profile_links", None)
            changed = True

    if "emailNotifications" in data:
        email_notifications = bool(data.get("emailNotifications"))
        if bool(rec.get("email_notifications", True)) != email_notifications:
            if email_notifications:
                rec.pop("email_notifications", None)
            else:
                rec["email_notifications"] = False
            changed = True

    if "notificationPreferences" in data:
        prefs = _clean_notification_preferences(
            data.get("notificationPreferences"), rec)
        if rec.get("notification_preferences", {}) != prefs:
            rec["notification_preferences"] = prefs
            changed = True

    if "notificationDelivery" in data:
        if _apply_notification_delivery(rec, data.get("notificationDelivery")):
            changed = True

    if "notificationPauseUntil" in data:
        if _apply_ping_pause(rec, data.get("notificationPauseUntil")):
            changed = True

    if "pingMutedKinds" in data:
        if _apply_ping_muted_kinds(rec, data.get("pingMutedKinds")):
            changed = True

    if "notificationQuietHours" in data:
        if _apply_ping_quiet_hours(rec, data.get("notificationQuietHours")):
            changed = True

    verification_sent = False
    verification_queued = False
    verification_refusal = None
    if data.get("resendVerification") and rec.get("email") and not rec.get("email_verified"):
        verification_refusal = await _verification_resend_refusal(
            env, clean_string(rec.get("name", ""), MAX_NODE_NAME).strip().lower(),
            rec, int(Date.now()))
        if verification_refusal is None:
            verification_sent = await _send_verification_email(env, request, rec.get("name", ""), rec.get("email", ""), rec=rec)
            if not verification_sent:
                await _enqueue_verification(env, name_bi, rec.get("name", ""), rec.get("email", ""))
                verification_queued = True

    new_name = clean_string(data.get("newNodeName", ""), MAX_NODE_NAME).lower()
    renamed = False
    if new_name:
        if not rec.get("email_verified"):
            return json_response({"error": "email_not_verified"}, status=403)
        name_bi, rec, rename_error = await _rename_account_namespace(env, name_bi, rec, new_name)
        if rename_error:
            status = 400
            if rename_error in ("node_name_taken", "repo_namespace_conflict"):
                status = 409
            elif rename_error == "invalid_credentials":
                status = 401
            return json_response({"error": rename_error}, status=status)
        changed = False
        renamed = True

    if changed:
        try:
            await _save_account(env, name_bi, rec)
        except Exception as error:
            # Keep the unique index race-free while returning a controlled
            # conflict for historical duplicate data.
            if "UNIQUE constraint failed: users.email_bi" in str(error):
                return json_response({"error": "email_taken"}, status=409)
            raise
        # Public-profile and chat-directory caches carry avatar/profile/device
        # metadata. Purge them on every profile edit; in particular, a privacy
        # opt-out must stop new public reads immediately in this colo.
        profile_name = clean_string(
            rec.get("name", ""), MAX_NODE_NAME).lower()
        # Sequential — see the no-concurrent-tasks rule at the top of this
        # module; two cache deletes never justify a second task.
        for cache_key in (
            ACCOUNT_LOOKUP_CACHE_PREFIX + quote(profile_name),
            USERS_DIRECTORY_CACHE_KEY,
            USERS_WORLD_CACHE_KEY,
        ):
            try:
                await edge_cache_delete(cache_key)
            except Exception:
                pass
        # Fediverse followers of this profile get an Update(Person) so bio
        # changes propagate to remote servers immediately — but only when a
        # federated field actually changed (see fed_before above).
        fed_after = (rec.get("profile_bio", ""),
                     bool(rec.get("profile_private")),
                     bool(rec.get("profile_followers_public")))
        if fed_after != fed_before:
            await _best_effort_inbox_side_effect(_ap_broadcast_actor_update(
                env, request, AP_ACTOR_USER,
                clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()))
    current_token, _ = _request_account_session_token(request, data)
    payload = await _account_public_payload(
        env, rec, current_token if current_token else None)
    payload["verificationSent"] = bool(verification_sent)
    payload["verificationQueued"] = bool(verification_queued)
    if verification_refusal:
        payload["verificationError"] = verification_refusal["error"]
        payload["verificationRetryAfterMs"] = verification_refusal["retryAfterMs"]
    payload["nodeNameChanged"] = bool(renamed)
    return await _account_session_response(env, request, payload)


# --- Users vs nodes: claiming & linking (adhoc #53) --------------------------
#
# Two ways a user (an account with login credentials) becomes the owner of a
# node (a key-bound-only account, e.g. a headless mirror registration):
#
#  1. Website claim: the user enters the node's ID (its account name) on the
#     dashboard. The worker parks a short confirmation code on the node's
#     record; the node learns of it in its next signed heartbeat reply and
#     shows the code on the machine itself. Typing that code back into the
#     website proves the user can see the node, and the records are linked.
#
#  2. Installer link code: a hosts/SSH install prints a code on the fresh
#     machine and hands it to the launched daemon, which presents it when it
#     registers. The desktop app that drove the install offers the same code
#     signed by its own key; whichever side reaches the worker first parks its
#     half in link_codes and the second side completes the link. The new node
#     is attached to the USER behind the installing account (the account
#     itself when it is a user, else that node's own recorded owner).


def _generate_confirm_code():
    return "%06d" % (int.from_bytes(_random_bytes(4), "big") % 1000000)


def _claim_pending(rec, now):
    pending = rec.get("claim_pending")
    if not isinstance(pending, dict):
        return None
    try:
        expires = int(pending.get("expires") or 0)
    except (TypeError, ValueError):
        return None
    if now >= expires or not pending.get("user") or not pending.get("code"):
        return None
    return pending


def _transfer_pending(rec, now):
    pending = rec.get("ownership_transfer_pending")
    if not isinstance(pending, dict):
        return None
    try:
        expires = int(pending.get("expires") or 0)
    except (TypeError, ValueError):
        return None
    if now >= expires or not pending.get("admin"):
        return None
    return pending


async def _resolve_user_by_password(env, data):
    # Web-auth gate for the claim endpoints, matching _account_profile: a
    # state-changing dashboard action re-proves the password on each request
    # (the static site keeps no server-side session). Returns (name_bi, rec)
    # for an active credentialed account, else (None, None).
    identifier = clean_string(
        data.get("identifier", "") or data.get("email", "") or
        data.get("user", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    if not identifier or not password:
        return None, None
    name_bi, rec = "", None
    if "@" in identifier:
        email_bi = await blind_index(env, identifier)
        row = await d1_first(
            env, "SELECT user_bi AS name_bi, data FROM users WHERE email_bi=?",
            email_bi)
        if row:
            name_bi = row.get("name_bi", "")
            rec = await decrypt_row(env, row.get("data"))
    elif valid_node_name(identifier):
        name_bi, rec = await _account_row(env, identifier)
    if not rec or rec.get("status") != "active" or not rec.get("pass_hash"):
        return None, None
    if not await verify_password(password, rec.get("pass_salt", ""),
                                 rec.get("pass_hash", "")):
        return None, None
    if not name_bi:
        name_bi = await blind_index(env, rec.get("name", ""))
    return name_bi, rec


async def _link_node_to_user(env, node_name, node_bi, node_rec, user_name):
    # The one place ownership is written: node.owner = user and the node joins
    # the user's nodes list. The user's record is loaded fresh so a stale
    # caller copy can't clobber it. When the node was already owned (the
    # browser link-grant flow may re-home a node), it leaves the previous
    # owner's nodes list so the fleet views stay truthful.
    prev_owner = node_rec.get("owner") or ""
    node_rec["owner"] = user_name
    node_rec.pop("claim_pending", None)
    node_rec.pop("ownership_transfer_pending", None)
    await _save_account(env, node_bi, node_rec)
    if prev_owner and prev_owner != user_name:
        prev_bi, prev_rec = await _account_row(env, prev_owner)
        if prev_rec is not None:
            prev_rec["nodes"] = [n for n in _owned_nodes(prev_rec)
                                 if n != node_name]
            await _save_account(env, prev_bi, prev_rec)
    user_bi, user_rec = await _account_row(env, user_name)
    if user_rec is not None:
        nodes = _owned_nodes(user_rec)
        was_operator = bool(nodes)
        if node_name not in nodes:
            nodes.append(node_name)
        user_rec["nodes"] = nodes
        await _save_account(env, user_bi, user_rec)
        if not was_operator:
            # "Mirror Operator" badge: this is the account's first node, the
            # real event that makes it a mirror operator.
            await _award_badge(env, user_name, user_bi, "mirror_operator")


async def _account_claim_node(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    _, user_rec = await _resolve_user_by_password(env, data)
    if not user_rec:
        return json_response({"error": "invalid_credentials"}, status=401)
    user_name = user_rec.get("name", "")
    raw_id = clean_string(data.get("nodeId", "") or data.get("nodeName", ""),
                          MAX_NODE_NAME)
    if not (valid_node_name(raw_id.strip().lower()) or valid_node_pubkey(raw_id)):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec, node_id = await _resolve_claimable_node(env, raw_id)
    if node_id == user_name:
        return json_response({"error": "cannot_claim_self"}, status=400)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    if _account_kind(node_rec) != "node":
        # An account that can log in is a user in its own right, not claimable.
        return json_response({"error": "not_a_node"}, status=403)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "alreadyLinked": True,
                              "nodeId": node_id})
    if node_rec.get("owner"):
        return json_response({"error": "node_already_owned"}, status=409)
    now = int(Date.now())
    node_rec["claim_pending"] = {
        "user": user_name,
        "code": _generate_confirm_code(),
        "expires": now + CLAIM_CODE_TTL_MS,
        "attempts": 0,
    }
    await _save_account(env, node_bi, node_rec)
    # The code itself is deliberately NOT returned: it only ever travels
    # worker -> node (heartbeat reply) -> the person standing at both screens.
    return json_response({"ok": True, "pending": True, "nodeId": node_id,
                          "expiresAt": now + CLAIM_CODE_TTL_MS}, status=201)


async def _account_claim_confirm(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    _, user_rec = await _resolve_user_by_password(env, data)
    if not user_rec:
        return json_response({"error": "invalid_credentials"}, status=401)
    user_name = user_rec.get("name", "")
    raw_id = clean_string(data.get("nodeId", "") or data.get("nodeName", ""),
                          MAX_NODE_NAME)
    code = clean_string(data.get("code", ""), 16).strip()
    if not (valid_node_name(raw_id.strip().lower()) or valid_node_pubkey(raw_id)):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec, node_id = await _resolve_claimable_node(env, raw_id)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "linked": True, "nodeId": node_id,
                              "nodes": _owned_nodes(user_rec)})
    pending = _claim_pending(node_rec, int(Date.now()))
    if not pending or pending.get("user") != user_name:
        return json_response({"error": "no_pending_claim"}, status=404)
    if not code or code != pending.get("code"):
        # A 6-digit code must not be guessable within its TTL: a few misses
        # invalidate the claim entirely (restart it from the dashboard).
        attempts = int(pending.get("attempts") or 0) + 1
        if attempts >= CLAIM_CODE_MAX_ATTEMPTS:
            node_rec.pop("claim_pending", None)
        else:
            pending["attempts"] = attempts
            node_rec["claim_pending"] = pending
        await _save_account(env, node_bi, node_rec)
        return json_response({"error": "bad_code"}, status=401)
    await _link_node_to_user(env, node_id, node_bi, node_rec, user_name)
    _, fresh_user = await _account_row(env, user_name)
    return json_response({"ok": True, "linked": True, "nodeId": node_id,
                          "nodes": _owned_nodes(fresh_user or user_rec)})


async def _parked_link_code_user(env, code):
    # Peek at the installing user parked on a live link code without redeeming
    # or burning it, so a caller can treat the code as evidence of who is
    # driving this install before it decides to act on that evidence. Returns
    # "" when the code is malformed, unknown, expired, or holds a node half.
    if not LINK_CODE_RE.match(clean_string(code or "", 16).strip()):
        return ""
    code_bi = await blind_index(env, "link:" + code)
    row = await d1_first(
        env, "SELECT data, ts FROM link_codes WHERE code_bi=?", code_bi)
    if not row:
        return ""
    try:
        if int(Date.now()) - int(row.get("ts") or 0) > LINK_CODE_TTL_MS:
            return ""
    except (TypeError, ValueError):
        return ""
    parked = await decrypt_row(env, row.get("data")) or {}
    user = parked.get("user") or ""
    return user if isinstance(user, str) else ""


def _link_code_rotation_allowed(node_rec, user, pubkey):
    if not (pubkey and valid_node_pubkey(pubkey)) or \
            pubkey == (node_rec or {}).get("pubkey", ""):
        return True
    owner = clean_string((node_rec or {}).get("owner", "") or "",
                         MAX_NODE_NAME).strip().lower()
    return bool(owner) and owner == clean_string(
        user or "", MAX_NODE_NAME).strip().lower()


async def _redeem_or_park_link_code(env, code, node=None, user=None, pubkey=None):
    # Order-independent rendezvous for installer link codes: called with node=
    # from the fresh node's registration and with user= from the installing
    # desktop's signed offer. When the opposite half is already parked (and
    # fresh), complete the link and burn the code; otherwise park this half.
    # Returns {"linked": True, "node": ..., "user": ...} when the link
    # completed now, else {"linked": False}.
    code_bi = await blind_index(env, "link:" + code)
    now = int(Date.now())
    row = await d1_first(
        env, "SELECT data, ts FROM link_codes WHERE code_bi=?", code_bi)
    other = None
    if row:
        try:
            fresh = now - int(row.get("ts") or 0) <= LINK_CODE_TTL_MS
        except (TypeError, ValueError):
            fresh = False
        other = await decrypt_row(env, row.get("data")) if fresh else None
    if node and other and other.get("user"):
        node_bi, node_rec = await _account_row(env, node)
        if (node_rec is not None and not _link_code_rotation_allowed(
                node_rec, other["user"], pubkey)):
            return {"linked": False, "error": "not_node_owner"}
        if node_rec is not None and _account_kind(node_rec) == "node":
            if pubkey and valid_node_pubkey(pubkey):
                node_rec["pubkey"] = pubkey
            await _link_node_to_user(env, node, node_bi, node_rec,
                                     other["user"])
        await d1_run(env, "DELETE FROM link_codes WHERE code_bi=?", code_bi)
        return {"linked": True, "node": node, "user": other["user"]}
    if user and other and other.get("node"):
        node_name = other["node"]
        other_pubkey = other.get("pubkey", "")
        node_bi, node_rec = await _account_row(env, node_name)
        if (node_rec is not None and not _link_code_rotation_allowed(
                node_rec, user, other_pubkey)):
            return {"linked": False, "error": "not_node_owner"}
        if node_rec is not None and _account_kind(node_rec) == "node":
            if other_pubkey and valid_node_pubkey(other_pubkey):
                node_rec["pubkey"] = other_pubkey
            await _link_node_to_user(env, node_name, node_bi, node_rec, user)
        await d1_run(env, "DELETE FROM link_codes WHERE code_bi=?", code_bi)
        return {"linked": True, "node": node_name, "user": user}
    parked = {"node": node} if node else {"user": user}
    if node and pubkey and valid_node_pubkey(pubkey):
        parked["pubkey"] = pubkey
    encrypted = await encrypt_row(env, parked)
    await d1_run(
        env,
        "INSERT INTO link_codes (code_bi, data, ts) VALUES (?,?,?) "
        "ON CONFLICT(code_bi) DO UPDATE SET data=excluded.data, ts=excluded.ts",
        code_bi, encrypted, now)
    return {"linked": False}


async def _account_reclaim_node(env, request):
    # Fresh host reinstall with a reused node name: the account may already be
    # active and bound to the previous local Ed25519 key, so reserve/finalize
    # cannot run. Pair the installer link code with a signature from the new key;
    # once the installing user's signed offer is present, re-home this node to
    # that user and rotate the node account's hosting key.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    pubkey = clean_string(data.get("pubkey", ""), 120)
    code = clean_string(data.get("linkCode", "") or data.get("code", ""), 16).strip()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if (not valid_node_name(name) or not valid_node_pubkey(pubkey) or
            not LINK_CODE_RE.match(code)):
        return json_response({"error": "invalid_request"}, status=400)
    if not _ts_ok(ts):
        return json_response({"error": "stale_request"}, status=401)
    canonical = ("forkmesh-reclaim-node-v1\n" + name + "\n" + pubkey + "\n" +
                 code + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)

    _, node_rec = await _account_row(env, name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    if _account_kind(node_rec) != "node":
        return json_response({"error": "not_a_node"}, status=403)

    result = await _redeem_or_park_link_code(
        env, code, node=name, pubkey=pubkey)
    if result.get("error"):
        return json_response({"error": result["error"]}, status=403)
    if result.get("linked"):
        return json_response({"ok": True, "linked": True,
                              "node": result.get("node", name),
                              "user": result.get("user", "")})
    return json_response({"ok": True, "linked": False, "pending": True,
                          "node": name}, status=202)


async def _account_link_node(env, request):
    # The installing desktop's half of the installer link-code flow: the code
    # printed by install.sh on the fresh machine, offered here signed by the
    # installing account's own key.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    code = clean_string(data.get("code", ""), 16).strip()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(name) or not LINK_CODE_RE.match(code):
        return json_response({"error": "invalid_request"}, status=400)
    _, rec = await _account_row(env, name)
    if not rec or rec.get("status") != "active":
        return json_response({"error": "no_such_account"}, status=404)
    pubkey = rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    canonical = ("forkmesh-link-v1\n" + name + "\n" + code + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    user = name if _account_kind(rec) == "user" else (rec.get("owner") or "")
    if not user:
        return json_response({"error": "no_user_account"}, status=403)
    result = await _redeem_or_park_link_code(env, code, user=user)
    if result.get("error"):
        return json_response({"error": result["error"]}, status=403)
    if result.get("linked"):
        return json_response({"ok": True, "linked": True,
                              "node": result.get("node", ""), "user": user})
    return json_response({"ok": True, "linked": False, "pending": True,
                          "user": user}, status=202)


async def _account_link_install(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    _, rec = await _account_session_record(env, request, data)
    if not rec:
        return json_response({"error": "unauthorized"}, status=401)
    name = rec.get("name", "")
    user = name if _account_kind(rec) == "user" else (rec.get("owner") or "")
    if not user:
        return json_response({"error": "no_user_account"}, status=403)
    now = int(Date.now())
    throttle_bi = await blind_index(env, "link-install:" + user)
    last = await d1_first(
        env, "SELECT ts FROM link_codes WHERE code_bi=?", throttle_bi)
    try:
        elapsed = now - int((last or {}).get("ts") or 0)
    except (TypeError, ValueError):
        elapsed = LINK_INSTALL_COOLDOWN_MS
    if last and 0 <= elapsed < LINK_INSTALL_COOLDOWN_MS:
        retry_ms = LINK_INSTALL_COOLDOWN_MS - elapsed
        return json_response(
            {"error": "rate_limited", "retryAfterMs": retry_ms}, status=429,
            extra_headers={"Retry-After": str(max(1, (retry_ms + 999) // 1000))})
    await d1_run(
        env,
        "INSERT INTO link_codes (code_bi, data, ts) VALUES (?,?,?) "
        "ON CONFLICT(code_bi) DO UPDATE SET data=excluded.data, ts=excluded.ts",
        throttle_bi, await encrypt_row(env, {}), now)
    for _ in range(8):
        code = _generate_confirm_code()
        code_bi = await blind_index(env, "link:" + code)
        taken = await d1_first(
            env, "SELECT ts FROM link_codes WHERE code_bi=?", code_bi)
        if taken:
            continue
        await _redeem_or_park_link_code(env, code, user=user)
        return json_response({"ok": True, "code": code, "user": user,
                              "expiresAt": now + LINK_CODE_TTL_MS},
                             status=201)
    return json_response({"error": "unavailable"}, status=503)


async def _account_link_self(env, request):
    # A node links ITSELF to a user account, driven from that node's own desktop
    # app ("Log in as a user" in the node profile). The request proves BOTH
    # secrets at once: control of the node's key (Ed25519 signature) and the
    # user's credentials (identifier + password), so the link completes
    # immediately with no confirmation code — holding both IS the authorization.
    # This is the in-app counterpart to the website's claim-node/claim-confirm
    # code flow, which only proves the password and needs the on-node code to
    # prove the claimer can see the machine.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node_name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(node_name):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec = await _account_row(env, node_name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    pubkey = node_rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    identifier = clean_string(
        data.get("identifier", "") or data.get("email", "") or
        data.get("user", ""), 254).strip().lower()
    canonical = ("forkmesh-link-self-v1\n" + node_name + "\n" + identifier +
                 "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    # Only now spend a password verification (the node signature gates it).
    _, user_rec = await _resolve_user_by_password(env, data)
    if not user_rec:
        return json_response({"error": "invalid_credentials"}, status=401)
    user_name = user_rec.get("name", "")
    if node_name == user_name:
        return json_response({"error": "cannot_link_self"}, status=400)
    if _account_kind(node_rec) != "node":
        # An account that can log in is a user in its own right, not linkable.
        return json_response({"error": "not_a_node"}, status=403)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "linked": True, "alreadyLinked": True,
                              "nodeId": node_name, "user": user_name,
                              "nodes": _owned_nodes(user_rec)})
    if node_rec.get("owner"):
        return json_response({"error": "node_already_owned"}, status=409)
    await _link_node_to_user(env, node_name, node_bi, node_rec, user_name)
    _, fresh_user = await _account_row(env, user_name)
    return json_response({"ok": True, "linked": True, "nodeId": node_name,
                          "user": user_name,
                          "nodes": _owned_nodes(fresh_user or user_rec)})


def _link_grant_fresh(ts):
    try:
        age = int(Date.now()) - int(ts)
    except (TypeError, ValueError):
        return False
    return -LINK_GRANT_MAX_FUTURE_MS <= age <= LINK_GRANT_MAX_AGE_MS


async def _link_grant_acceptor(env, request, data, node_name, grant_sig):
    accept_sig = clean_string(data.get("acceptSig", ""), 200)
    if accept_sig:
        user = clean_string(data.get("user", ""), MAX_NODE_NAME).strip().lower()
        accept_ts = clean_string(data.get("acceptTs", ""), 20)
        if not valid_node_name(user):
            return "", "", "invalid_request"
        if not _ts_ok(accept_ts):
            return "", "", "accept_expired"
        canonical = ("forkmesh-link-accept-v1\n" + node_name + "\n" + user +
                     "\n" + grant_sig + "\n" + accept_ts).encode()
        if not await _verify_owner_signature(env, user, accept_sig, canonical):
            return "", "", "bad_accept_signature"
        return user, "signature", ""
    token, _cookie_auth = _request_account_session_token(request, data)
    if str(token or "").startswith("fmat_"):
        return "", "", "session_required"
    user = await _authed_account_name(env, request, data)
    if not user:
        return "", "", "session_required"
    return user, "session", ""


async def _account_link_grant(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node_name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    named = clean_string(data.get("user", ""), MAX_NODE_NAME).strip().lower()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    nonce = clean_string(data.get("nonce", ""), 64).strip()
    if not valid_node_name(node_name) or (named and not valid_node_name(named)):
        return json_response({"error": "invalid_request"}, status=400)
    if nonce and (not named or not LINK_GRANT_NONCE_RE.match(nonce)):
        return json_response({"error": "invalid_request"}, status=400)
    node_bi, node_rec = await _account_row(env, node_name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    pubkey = node_rec.get("pubkey", "")
    if not pubkey or not ts:
        return json_response({"error": "unauthorized"}, status=401)
    if nonce:
        grant_version = "v2"
        canonical = ("forkmesh-link-grant-v2\n" + node_name + "\n" + named +
                     "\n" + ts + "\n" + nonce).encode()
        grant_key = "grant2:" + node_name + ":" + nonce
    else:
        grant_version = "v1"
        canonical = ("forkmesh-link-grant-v1\n" + node_name + "\n" + ts).encode()
        grant_key = "grant:" + node_name + ":" + ts + ":" + signature
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    previous = node_rec.get("owner") or ""

    async def refuse(error, status, actor=""):
        await _audit_sensitive_action(
            env, actor, "node.link_grant", "node", node_name, "denied",
            {"reason": error, "grant": grant_version, "named": named,
             "from": previous})
        return json_response({"error": error}, status=status)

    if not _link_grant_fresh(ts):
        return await refuse("grant_expired", 401)
    user_name, via, error = await _link_grant_acceptor(
        env, request, data, node_name, signature)
    if error:
        return await refuse(error, 400 if error == "invalid_request" else 401)
    if named and named != user_name:
        return await refuse("grant_user_mismatch", 403, user_name)
    if node_name == user_name:
        return json_response({"ok": True, "linked": True, "alreadyLinked": True,
                              "selfAccount": True, "nodeId": node_name,
                              "user": user_name,
                              "nodes": _owned_nodes(node_rec)})
    _, user_rec = await _account_row(env, user_name)
    if not user_rec or user_rec.get("status") != "active":
        return await refuse("no_such_user", 404, user_name)
    if _account_kind(user_rec) != "user":
        return await refuse("not_a_user", 403, user_name)
    if previous == user_name:
        return json_response({"ok": True, "linked": True, "alreadyLinked": True,
                              "nodeId": node_name, "user": user_name,
                              "nodes": _owned_nodes(user_rec)})
    grant_bi = await blind_index(env, grant_key)
    row = await d1_first(
        env, "SELECT data, ts FROM link_codes WHERE code_bi=?", grant_bi)
    if row:
        return await refuse("grant_used", 409, user_name)
    encrypted = await encrypt_row(env, {"grant": node_name})
    await d1_run(
        env,
        "INSERT INTO link_codes (code_bi, data, ts) VALUES (?,?,?) "
        "ON CONFLICT(code_bi) DO UPDATE SET data=excluded.data, ts=excluded.ts",
        grant_bi, encrypted, int(Date.now()))
    await _link_node_to_user(env, node_name, node_bi, node_rec, user_name)
    await _audit_sensitive_action(
        env, user_name, "node.link_grant", "node", node_name, "success",
        {"grant": grant_version, "via": via, "from": previous,
         "to": user_name})
    _, fresh_user = await _account_row(env, user_name)
    return json_response({"ok": True, "linked": True, "nodeId": node_name,
                          "user": user_name,
                          "nodes": _owned_nodes(fresh_user or user_rec)})


async def _login_locked_until(env, id_bi):
    # Returns the lock-expiry ms if the identifier is currently locked, else 0.
    row = await d1_first(
        env, "SELECT locked_until FROM login_attempts WHERE id_bi=?", id_bi)
    if not row:
        return 0
    try:
        locked = int(row.get("locked_until") or 0)
    except (TypeError, ValueError):
        return 0
    return locked if locked > int(Date.now()) else 0


async def _login_record_fail(env, id_bi):
    # Atomically increment/reset one source or source+identifier budget. The
    # returned lock applies only to subsequent *failed* attempts; correct
    # credentials are always verified and can clear the budget, preventing an
    # attacker from locking a known victim out by name alone.
    now = int(Date.now())
    row = await d1_first(
        env,
        "INSERT INTO login_attempts (id_bi, fails, first_fail_ts, locked_until) "
        "VALUES (?,1,?,0) ON CONFLICT(id_bi) DO UPDATE SET "
        "fails=CASE WHEN ?-login_attempts.first_fail_ts>? "
        "THEN 1 ELSE login_attempts.fails+1 END,"
        "first_fail_ts=CASE WHEN ?-login_attempts.first_fail_ts>? "
        "THEN ? ELSE login_attempts.first_fail_ts END,"
        "locked_until=CASE WHEN "
        "(CASE WHEN ?-login_attempts.first_fail_ts>? "
        "THEN 1 ELSE login_attempts.fails+1 END)>=? "
        "THEN ? ELSE 0 END "
        "RETURNING fails,first_fail_ts,locked_until",
        id_bi,
        now,
        now,
        LOGIN_FAIL_WINDOW_MS,
        now,
        LOGIN_FAIL_WINDOW_MS,
        now,
        now,
        LOGIN_FAIL_WINDOW_MS,
        LOGIN_MAX_FAILS,
        now + LOGIN_LOCKOUT_MS,
    )
    return {
        "fails": int((row or {}).get("fails") or 1),
        "lockedUntil": int((row or {}).get("locked_until") or 0),
    }


async def _login_attempt_keys(env, request, identifier):
    source = _transient_client_address(request)
    source_bi = await blind_index(env, source) if source else ""
    keys = []
    if source_bi:
        keys.append(await blind_index(
            env, "login-source:" + source_bi))
        keys.append(await blind_index(
            env, "login-pair:" + source_bi + ":" + identifier))
    else:
        # Local/self-hosted requests without edge address metadata retain a
        # bounded identifier budget, but valid credentials still bypass it.
        keys.append(await blind_index(env, "login-local:" + identifier))
    return keys


async def _login_failure_response(env, attempt_keys, error):
    locked_until = 0
    highest_fail_count = 0
    for attempt_key in attempt_keys:
        result = await _login_record_fail(env, attempt_key)
        if isinstance(result, dict):
            locked_until = max(
                locked_until, int(result.get("lockedUntil") or 0))
            highest_fail_count = max(
                highest_fail_count, int(result.get("fails") or 0))
        else:
            # Compatibility with an older/local rate-limit adapter.
            locked_until = max(locked_until, int(result or 0))
    now = int(Date.now())
    if locked_until > now:
        retry_ms = max(1000, locked_until - now)
    elif highest_fail_count >= 3:
        # Progressive source/pair backoff starts before the hard ceiling. This
        # response is emitted only after credentials have failed verification;
        # a subsequent correct password is still checked immediately.
        retry_ms = min(
            60 * 1000,
            1000 * (2 ** min(6, highest_fail_count - 3)),
        )
    else:
        retry_ms = 0
    if retry_ms:
        return json_response(
            {"error": "too_many_attempts", "retryAfterMs": retry_ms},
            status=429,
            extra_headers={
                "Retry-After": str(max(1, (retry_ms + 999) // 1000))
            },
        )
    return json_response({"error": error}, status=401)


async def _login_clear(env, id_bi):
    await d1_run(env, "DELETE FROM login_attempts WHERE id_bi=?", id_bi)


async def _account_totp_ok(env, rec, code):
    name = clean_string((rec or {}).get("name", ""), MAX_NODE_NAME).lower()
    key = await blind_index(env, "login-totp:" + name)
    if await _login_locked_until(env, key):
        return False
    if await totp_verify((rec or {}).get("totp_secret", ""), code):
        await _login_clear(env, key)
        return True
    await _login_record_fail(env, key)
    return False


DESKTOP_NODE_CAPABILITIES = "browse,comment,submit_issue,submit_pr,host_repo,mirror_repo,publish_repo,owner_sign"
# A mobile node authors, publishes and signs as the owner but never hosts or
# mirrors (www/docs/mobile/mobile-node-contract.md section 2).
MOBILE_NODE_CAPABILITIES = "browse,comment,submit_issue,submit_pr,publish_repo,owner_sign"
CLIENT_CAPABILITIES = "browse,comment,submit_issue,submit_pr"
BROWSER_CONTROL_CAPABILITIES = "desktop_control"
BROWSER_CONTROL_DEVICE_KIND = "browser_control"
BROWSER_CONTROL_BIND_PROOF = "forkmesh-browser-control-v1"
BROWSER_CONTROL_MAX_DEVICES = 20
ACCOUNT_DEVICE_KINDS = ("desktop_node", "mobile_node", "browser_control")
CONTRIBUTION_KEY_PROOF_CAPABILITY = "contribution_key_proof"


def _device_bind_canonical(account, pubkey, timestamp):
    account = account.strip().lower() if isinstance(account, str) else ""
    if not valid_node_name(account) or not valid_node_pubkey(pubkey):
        raise ValueError("invalid device bind identity")
    if (not isinstance(timestamp, str) or not timestamp.isdigit()
            or len(timestamp) > 16 or str(int(timestamp)) != timestamp):
        raise ValueError("invalid device bind timestamp")
    return (
        "forkmesh-device-bind-v1\n" + account + "\n" + pubkey + "\n"
        + timestamp
    ).encode()


async def _device_proven_user_bis(env, pubkey):
    rows = await d1_all(
        env,
        """WITH proven_device_users(user_bi) AS (
               SELECT COALESCE(NULLIF(user_bi, ''), node_bi)
                 FROM nodes WHERE pubkey=?
               UNION ALL
               SELECT COALESCE(NULLIF(owner_node.user_bi, ''),
                               account_devices.account_bi)
                 FROM account_devices
                LEFT JOIN nodes AS owner_node
                   ON owner_node.node_bi=account_devices.account_bi
                WHERE account_devices.pubkey=?
                  AND instr(',' || account_devices.capabilities || ',',
                            ',contribution_key_proof,') > 0
             )
             SELECT DISTINCT user_bi FROM proven_device_users
              WHERE user_bi IS NOT NULL AND user_bi != ''""",
        pubkey, pubkey,
    )
    return {row.get("user_bi") for row in rows if row.get("user_bi")}


async def _device_retire_unproven_claims(env, account_bi, pubkey):
    await d1_run(
        env,
        "DELETE FROM account_devices WHERE pubkey=? AND account_bi!=? "
        "AND instr(',' || capabilities || ',', "
        "',contribution_key_proof,')=0",
        pubkey, account_bi,
    )


async def _register_account_device(
        env, account_bi, pubkey, kind="desktop_node", label="",
        proof_verified=False, target_user_bi=None):
    if not account_bi or not pubkey:
        return None
    device_bi = await blind_index(env, account_bi + ":" + pubkey)
    now = int(Date.now())
    if kind == "desktop_node":
        capabilities = DESKTOP_NODE_CAPABILITIES
    elif kind == "mobile_node":
        capabilities = MOBILE_NODE_CAPABILITIES
    elif kind == "browser_control":
        capabilities = BROWSER_CONTROL_CAPABILITIES
    else:
        capabilities = CLIENT_CAPABILITIES
    if proof_verified:
        capabilities += "," + CONTRIBUTION_KEY_PROOF_CAPABILITY
    base_args = (
        device_bi, account_bi, pubkey, kind, label, capabilities, now, now)
    if proof_verified:
        target_user_bi = target_user_bi or account_bi
        await d1_run(
            env,
            """INSERT INTO account_devices
                 (device_bi, account_bi, pubkey, kind, label, capabilities,
                  enabled, created_at, last_seen, revoked_at)
                 SELECT ?, ?, ?, ?, ?, ?, 1, ?, ?, 0
                  WHERE NOT EXISTS (
                    SELECT 1 FROM nodes
                     WHERE pubkey=?
                       AND COALESCE(NULLIF(user_bi, ''), node_bi) != ?)
                    AND NOT EXISTS (
                    SELECT 1 FROM account_devices AS proven_claim
                    LEFT JOIN nodes AS claim_owner
                      ON claim_owner.node_bi=proven_claim.account_bi
                     WHERE proven_claim.pubkey=?
                       AND instr(',' || proven_claim.capabilities || ',',
                                 ',contribution_key_proof,') > 0
                       AND COALESCE(NULLIF(claim_owner.user_bi, ''),
                                    proven_claim.account_bi) != ?)
                 /* atomic_device_proof_claim */
                 ON CONFLICT(device_bi) DO UPDATE SET
                   last_seen=excluded.last_seen,
                   capabilities=excluded.capabilities,
                   enabled=CASE WHEN account_devices.revoked_at=0
                                THEN 1 ELSE account_devices.enabled END""",
            *base_args, pubkey, target_user_bi, pubkey, target_user_bi,
        )
    else:
        await d1_run(
            env,
            """INSERT INTO account_devices
                 (device_bi, account_bi, pubkey, kind, label, capabilities,
                  enabled, created_at, last_seen, revoked_at)
                 VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, 0)
                 ON CONFLICT(device_bi) DO UPDATE SET
                   last_seen=excluded.last_seen,
                   capabilities=excluded.capabilities,
                   enabled=CASE WHEN account_devices.revoked_at=0
                                THEN 1 ELSE account_devices.enabled END""",
            *base_args,
        )
    return {"id": device_bi[:16], "kind": kind, "pubkey": pubkey,
            "capabilities": capabilities.split(",")}


async def _account_device_for_pubkey(env, account_bi, pubkey):
    if not account_bi or not pubkey:
        return None
    row = await d1_first(
        env,
        """SELECT device_bi, pubkey, kind, label, capabilities, enabled, last_seen, revoked_at
             FROM account_devices WHERE account_bi=? AND pubkey=?""",
        account_bi, pubkey,
    )
    return row


async def _account_devices_list(env, account_bi):
    rows = await d1_all(
        env,
        """SELECT device_bi, pubkey, kind, label, capabilities, enabled, last_seen, revoked_at,
                  created_at
             FROM account_devices WHERE account_bi=? ORDER BY created_at ASC""",
        account_bi,
    )
    out = []
    for row in rows:
        caps = clean_string(row.get("capabilities", ""), 512)
        out.append({
            "id": clean_string(row.get("device_bi", ""), 128)[:16],
            "deviceBi": clean_string(row.get("device_bi", ""), 128),
            "pubkey": clean_string(row.get("pubkey", ""), 120),
            "kind": clean_string(row.get("kind", ""), 40),
            "label": clean_string(row.get("label", ""), 120),
            "capabilities": [c for c in caps.split(",") if c],
            "enabled": bool(row.get("enabled")) and not bool(row.get("revoked_at")),
            "lastSeen": int(row.get("last_seen") or 0),
            "createdAt": int(row.get("created_at") or 0),
            "revokedAt": int(row.get("revoked_at") or 0),
        })
    return out


def _account_device_public(device, current_device_bi=""):
    """Owner-facing projection of one account_devices row (no pubkey)."""
    device_bi = str(device.get("deviceBi") or "")
    return {
        "id": device.get("id", ""),
        "kind": device.get("kind", ""),
        "label": device.get("label", ""),
        "capabilities": list(device.get("capabilities") or []),
        "enabled": bool(device.get("enabled")),
        "lastSeen": int(device.get("lastSeen") or 0),
        "createdAt": int(device.get("createdAt") or 0),
        "revokedAt": int(device.get("revokedAt") or 0),
        "current": bool(current_device_bi) and device_bi == current_device_bi,
    }


def _with_session_capabilities(payload, *, session_kind, device_kind="", key_matched=False,
                               desktop_capable=False, capabilities=None):
    caps = capabilities or (DESKTOP_NODE_CAPABILITIES.split(",") if desktop_capable else CLIENT_CAPABILITIES.split(","))
    payload["sessionKind"] = session_kind
    payload["deviceKind"] = device_kind
    payload["deviceKeyMatched"] = bool(key_matched)
    payload["desktopCapable"] = bool(desktop_capable)
    payload["capabilities"] = caps
    payload["canHost"] = "host_repo" in caps
    payload["canPublish"] = "publish_repo" in caps
    payload["canOwnerSign"] = "owner_sign" in caps
    return payload


def _is_local_demo_request(request):
    try:
        parsed = urlparse(request.url)
        return (
            parsed.scheme in ("http", "https")
            and parsed.hostname in ("localhost", "127.0.0.1", "::1")
        )
    except Exception:
        return False


async def _ensure_local_demo_account(
        env, request, identifier, password):
    # Local `wrangler dev` only. On a VPS host (ForkMesh Next) the Host header
    # is attacker-influenced, so a known-password admin must never be minted.
    if str(getattr(env, "FORKMESH_PLATFORM", "") or "").strip().lower() == "vps":
        return
    if (
        not _is_local_demo_request(request)
        or identifier != LOCAL_DEMO_EMAIL
        or password != LOCAL_DEMO_PASSWORD
    ):
        return
    email_bi = await blind_index(env, LOCAL_DEMO_EMAIL)
    name_bi = await blind_index(env, LOCAL_DEMO_NAME)
    row = await d1_first(
        env,
        "SELECT user_bi,data,is_admin FROM users WHERE email_bi=?",
        email_bi,
    )
    if row and row.get("user_bi") != name_bi:
        return
    record = await decrypt_row(env, row.get("data")) if row else None
    valid = bool(
        record
        and record.get("name") == LOCAL_DEMO_NAME
        and record.get("status") == "active"
        and record.get("pass_hash")
        and await verify_password(
            LOCAL_DEMO_PASSWORD,
            record.get("pass_salt", ""),
            record.get("pass_hash", ""),
        )
    )
    if valid:
        if not bool(int(row.get("is_admin") or 0)):
            await d1_run(
                env,
                "UPDATE users SET is_admin=1 WHERE user_bi=?",
                name_bi,
            )
        return
    salt, password_hash = await hash_password(LOCAL_DEMO_PASSWORD)
    await _save_account_full(
        env,
        name_bi,
        {
            "name": LOCAL_DEMO_NAME,
            "email": LOCAL_DEMO_EMAIL,
            "kind": "user",
            "status": "active",
            "pass_salt": salt,
            "pass_hash": password_hash,
            "email_verified": True,
            "created_at": int(Date.now()),
        },
        email_bi=email_bi,
        ip_bi=to_js(None),
        is_admin=1,
    )


async def _account_admin_totp_enrollment(env, attempt_keys, rec, totp):
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    if not name or not await _is_admin_flag(env, name):
        return None
    name_bi = await blind_index(env, name)
    secret = clean_string(rec.get("totp_pending_secret", ""), 64)
    if secret and totp:
        if not await totp_verify(secret, totp):
            return await _login_failure_response(
                env, attempt_keys, "bad_totp")
        rec["totp_secret"] = secret
        rec["totp_enrolled"] = True
        rec["totp_enrolled_at"] = int(Date.now())
        rec.pop("totp_pending_secret", None)
        await _save_account(env, name_bi, rec)
        try:
            await _audit_sensitive_action(
                env, name, "account.totp_enroll", "account", name,
                "success", {"reason": "admin_required"})
        except Exception:
            pass
        return None
    if not secret:
        secret = gen_totp_secret()
        rec["totp_pending_secret"] = secret
        await _save_account(env, name_bi, rec)
    return json_response({
        "error": "totp_setup_required",
        "totpSecret": secret,
        "otpauthUri": _totp_otpauth_uri(name, secret, instance_name(env)),
    }, status=401, cache_control="no-store")


async def _account_login(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)

    # Log in by email or node name (the "universal access" credential).
    identifier = clean_string(
        data.get("nodeName", "") or data.get("identifier", "") or
        data.get("email", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    totp = clean_string(data.get("totp", ""), 10)
    pubkey = clean_string(data.get("pubkey", ""), 120)
    device_ts = clean_string(data.get("deviceTs", ""), 20)
    device_sig = clean_string(data.get("deviceSig", ""), 200)
    # Which kind of node the supplied pubkey belongs to. Absent means the
    # legacy desktop path; "mobile_node" binds a phone key with the reduced
    # MOBILE_NODE_CAPABILITIES and never becomes the account's primary key
    # (www/docs/mobile/mobile-node-contract.md section 3).
    requested_device_kind = clean_string(data.get("deviceKind", ""), 40)
    if requested_device_kind not in ("", "desktop_node", "mobile_node"):
        return json_response({"error": "invalid_device_kind"}, status=400)
    mobile_bind = requested_device_kind == "mobile_node"

    await _ensure_local_demo_account(
        env, request, identifier, password)

    # Failed attempts consume atomic source and source+identifier budgets. They
    # never block verification of correct credentials, so an attacker cannot
    # lock a known victim out merely by submitting their identifier.
    id_bi = await blind_index(env, identifier) if identifier else ""
    if not id_bi:
        return json_response({"error": "invalid_credentials"}, status=401)
    attempt_keys = await _login_attempt_keys(env, request, identifier)

    rec = None
    if "@" in identifier:
        email_bi = await blind_index(env, identifier)
        row = await d1_first(
            env, "SELECT data FROM users WHERE email_bi=?", email_bi)
        if row:
            rec = await decrypt_row(env, row["data"])
    elif valid_node_name(identifier):
        _, rec = await _account_row(env, identifier)

    if rec is not None and rec.get("status") != "active":
        if rec.get("pass_hash") and await verify_password(
                password, rec.get("pass_salt", ""), rec.get("pass_hash", "")):
            for attempt_key in attempt_keys:
                await _login_clear(env, attempt_key)
            return json_response({"error": "account_disabled"}, status=403)

    ok = (rec is not None and rec.get("status") == "active" and
          rec.get("pass_hash") and
          await verify_password(password, rec.get("pass_salt", ""),
                                rec.get("pass_hash", "")))
    if not ok:
        return await _login_failure_response(
            env, attempt_keys, "invalid_credentials")
    # TOTP is enforced for accounts that enrolled it and for every is_admin
    # account. A bad code counts toward the lockout but the password was
    # already correct, so the distinct error doesn't aid account enumeration.
    if rec.get("totp_enrolled"):
        if not await _account_totp_ok(env, rec, totp):
            return await _login_failure_response(
                env, attempt_keys, "bad_totp")
    else:
        enrollment = await _account_admin_totp_enrollment(
            env, attempt_keys, rec, totp)
        if enrollment is not None:
            return enrollment
    for attempt_key in attempt_keys:
        await _login_clear(env, attempt_key)
    marker = str(getattr(env, "INSTANCE_LOGIN_MARKER", "") or "")
    if marker.startswith("/var/lib/forkmesh-instance/") and \
            await _is_admin_flag(env, rec.get("name", "")):
        try:
            from pathlib import Path as _MarkerPath
            _MarkerPath(marker).touch(exist_ok=True)
        except OSError:
            pass

    # Multi-device account model: password/TOTP authenticates the human account;
    # a supplied pubkey identifies/registers this particular desktop node. Any
    # number of desktop nodes may be enabled for the same account. The legacy
    # accounts.pubkey remains as the primary/first desktop key for compatibility,
    # but a different registered desktop key is no longer a login failure.
    name_bi = await blind_index(env, rec.get("name", ""))
    device = None
    desktop_capable = False
    device_kind = ""
    if pubkey:
        account_name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        try:
            device_canonical = _device_bind_canonical(
                account_name, pubkey, device_ts)
        except ValueError:
            device_canonical = b""
        if (not device_canonical or not device_sig or not _ts_ok(device_ts)
                or not await ed25519_verify(
                    pubkey, device_sig, device_canonical)):
            return json_response(
                {"error": "device_proof_required"}, status=401)
        owner_row = await d1_first(
            env, "SELECT user_bi FROM nodes WHERE node_bi=?", name_bi)
        target_user_bi = (owner_row or {}).get("user_bi") or name_bi
        device_label = clean_string(data.get("deviceLabel", ""), 120)
        bind_kind = "mobile_node" if mobile_bind else "desktop_node"
        existing_device = await _account_device_for_pubkey(
            env, name_bi, pubkey)
        existing_caps = clean_string(
            (existing_device or {}).get("capabilities", ""), 512).split(",")
        reusable_device = bool(
            existing_device
            and clean_string(existing_device.get("kind", ""), 40)
                == bind_kind
            and int(existing_device.get("enabled") or 0)
            and not int(existing_device.get("revoked_at") or 0)
            and CONTRIBUTION_KEY_PROOF_CAPABILITY in existing_caps
        )
        # A proof-bearing enabled row for this exact account/key pair is an
        # already-completed bind, not a new ownership claim. In particular,
        # do not let a stale legacy nodes/account_devices projection turn a
        # logout + same-account login into a false cross-account conflict.
        # Reusing the row grants nothing new: owner-signed endpoints already
        # accept this same enabled row through _owner_signing_pubkeys().
        if reusable_device:
            now = int(Date.now())
            await d1_run(
                env,
                "UPDATE account_devices SET last_seen=?, "
                "label=CASE WHEN ?!='' THEN ? ELSE label END "
                "WHERE device_bi=? AND account_bi=? AND enabled=1 "
                "AND revoked_at=0",
                now, device_label, device_label,
                existing_device.get("device_bi", ""), name_bi,
            )
            device = dict(existing_device)
            device["last_seen"] = now
            if device_label:
                device["label"] = device_label
            device_is_new = False
        else:
            # A revoked mobile row is permanent (its upsert keeps enabled=0),
            # so a phone signed out from the web must rotate its key rather
            # than receive a session that dies on its next request. Preserve
            # the legacy desktop password-only result below for now.
            if mobile_bind and existing_device and (
                    int(existing_device.get("revoked_at") or 0)
                    or not int(existing_device.get("enabled") or 0)):
                return json_response(
                    {"error": "device_revoked"}, status=401)
            proven_users = await _device_proven_user_bis(env, pubkey)
            if any(user_bi != target_user_bi for user_bi in proven_users):
                return json_response(
                    {"error": "device_key_conflict"}, status=409)
            await _device_retire_unproven_claims(env, name_bi, pubkey)
            device_is_new = existing_device is None
            await _register_account_device(
                env, name_bi, pubkey, bind_kind, device_label,
                proof_verified=True, target_user_bi=target_user_bi)
            device = await _account_device_for_pubkey(env, name_bi, pubkey)
            final_proven_users = await _device_proven_user_bis(env, pubkey)
            device_caps = clean_string(
                (device or {}).get("capabilities", ""), 512).split(",")
            if (not device
                    or CONTRIBUTION_KEY_PROOF_CAPABILITY not in device_caps
                    or target_user_bi not in final_proven_users
                    or any(user_bi != target_user_bi
                           for user_bi in final_proven_users)):
                return json_response(
                    {"error": "device_key_conflict"}, status=409)
        device_bi = clean_string(device.get("device_bi", ""), 128)
        if mobile_bind:
            return await _account_login_mobile_node_response(
                env, request, rec, device, device_bi, device_label,
                device_is_new)
        if not rec.get("pubkey"):
            rec["pubkey"] = pubkey
            await _save_account(env, name_bi, rec)
        try:
            await touch_registered_node(env, name_bi, rec)
        except Exception:
            pass
        # Recheck delayed referral eligibility.
        finalize_referral = globals().get("_finalize_referral_signup")
        if callable(finalize_referral):
            referral_result = await finalize_referral(env, name_bi)
            if referral_result == "quarantined":
                return json_response(
                    {"error": "account_pending_verification"}, status=403)
        caps = device.get("capabilities", DESKTOP_NODE_CAPABILITIES) if device else DESKTOP_NODE_CAPABILITIES
        if isinstance(caps, str):
            caps = [c for c in caps.split(",") if c]
        enabled = bool(device.get("enabled", True)) and not bool(device.get("revoked_at", 0)) if device else True
        device_kind = device.get("kind", "desktop_node") if device else "desktop_node"
        desktop_capable = (
            device_kind == "desktop_node"
            and enabled
            and "owner_sign" in caps
        )
        session_caps = caps if desktop_capable else CLIENT_CAPABILITIES.split(",")
        payload = await _account_public_payload(
            env, rec,
            session_device_label=_account_session_device_label(
                request, desktop=True),
            session_client_ip=_account_session_client_ip(request),
            session_device_bi=device_bi)
        payload = _with_session_capabilities(
            payload, session_kind="desktop_node", device_kind=device_kind,
            key_matched=True, desktop_capable=desktop_capable,
            capabilities=session_caps)
        return await _account_session_response(env, request, payload)

    payload = await _account_public_payload(
        env, rec,
        session_device_label=_account_session_device_label(request),
        session_client_ip=_account_session_client_ip(request))
    payload = _with_session_capabilities(
        payload, session_kind="account", device_kind="web_or_mobile",
        key_matched=False, desktop_capable=False)
    return await _account_session_response(env, request, payload)


async def _account_login_mobile_node_response(
        env, request, rec, device, device_bi, device_label, device_is_new):
    """Finish a verified ``deviceKind: mobile_node`` login.

    The phone key is already registered (proof verified, conflicts rejected)
    by the caller. Unlike a desktop bind this never promotes the key to the
    account's primary ``rec["pubkey"]``, never touches the hosting node row and
    never counts as ``desktopCapable``: the session carries the device row's
    own (mobile) capabilities and is tied to that row so a web-side revoke
    closes it. Binding a brand-new row is audited and pinged best-effort.
    """
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    name_bi = await blind_index(env, name)
    caps = device.get("capabilities", MOBILE_NODE_CAPABILITIES)
    if isinstance(caps, str):
        caps = [c for c in caps.split(",") if c]
    if device_is_new:
        try:
            await _audit_sensitive_action(
                env, name, "account.device_bind", "account_device",
                device_bi[:16], "success",
                {"kind": "mobile_node", "label": device_label})
        except Exception:
            pass
        try:
            await enqueue_notification(
                env, name, "device_added", "New mobile node added",
                body=("New mobile node added: "
                      + (device_label or "mobile node")
                      + ". If this was not you, revoke it from your "
                      "account settings."),
                href="/dashboard/settings",
                source="device_added",
                dedupe="device_added:" + device_bi[:16],
            )
        except Exception:
            pass
    payload = await _account_public_payload(
        env, rec,
        session_device_label="Mobile node",
        session_client_ip=_account_session_client_ip(request),
        session_device_bi=device_bi)
    payload = _with_session_capabilities(
        payload, session_kind="mobile_node", device_kind="mobile_node",
        key_matched=True, desktop_capable=False, capabilities=caps)
    payload["deviceId"] = device_bi[:16]
    try:
        payload["devices"] = [
            _account_device_public(item, device_bi)
            for item in await _account_devices_list(env, name_bi)
        ]
    except Exception:
        payload["devices"] = []
    return await _account_session_response(env, request, payload)


ACCOUNT_DEVICE_ID_RE = re.compile(r"[0-9a-fA-F]{8,64}")


async def _account_sudo_reauth(env, request, rec, data):
    """Re-verify the account password (+ TOTP when enrolled) inside a session.

    Destructive registry actions (revoking a node key) demand this "sudo" step
    so a hijacked web session alone cannot cut the owner's own nodes loose.
    Returns None on success, otherwise the response to send. Failures count
    against the same per-source login budget as a bad password at login, so
    the endpoint cannot be used as an unthrottled password oracle; a correct
    password is never blocked by that budget (same contract as login).
    """
    password = data.get("password", "") if isinstance(data, dict) else ""
    password = password[:256] if isinstance(password, str) else ""
    totp = clean_string((data or {}).get("totp", ""), 10)
    actor = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    attempt_keys = await _login_attempt_keys(env, request, actor)
    ok = bool(
        password
        and rec.get("pass_hash")
        and await verify_password(
            password, rec.get("pass_salt", ""), rec.get("pass_hash", "")))
    if ok and rec.get("totp_enrolled"):
        ok = await _account_totp_ok(env, rec, totp)
    if not ok:
        return await _login_failure_response(
            env, attempt_keys, "reauth_required")
    return None


async def _account_devices(env, request, target_device_id="", action=""):
    """Owner-only node registry: list, revoke one, or revoke all devices.

    GET    /api/accounts/devices             -> {"devices": [...]}
    DELETE /api/accounts/devices/{id}        -> sudo; revoke one device
    POST   /api/accounts/devices/revoke-all  -> sudo; revoke all but caller's

    ``id`` is the 16-hex-character prefix of the account_devices blind index
    that every other surface exposes. Revoking sets ``revoked_at`` (permanent —
    the login upsert never re-enables a revoked row, so the node must bind a
    new key) and revokes every session that device's logins minted; the
    caller's own session is reported in ``currentRevoked`` and its cookie
    cleared. See www/docs/mobile/mobile-node-contract.md section 4.
    """
    method = method_name(request)
    data = {}
    if method in ("POST", "DELETE"):
        try:
            data = await bounded_json_request(request)
        except Exception:
            data = {}
        if not isinstance(data, dict):
            data = {}
    token, cookie_auth = _request_account_session_token(request, data)
    if (
        cookie_auth
        and method != "GET"
        and not _request_origin_allowed(env, request)
    ):
        token = ""
    account_bi, rec, current_session_id = await _account_session_lookup(
        env, token, touch=method == "GET")
    if not account_bi or not rec or not current_session_id:
        return json_response(
            {"error": await _account_session_invalid_error(env, token)},
            status=401,
            cache_control="no-store, max-age=0, must-revalidate")

    now = int(Date.now())
    actor = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    current_device_bi = await _account_session_device_bi(
        env, current_session_id)

    if method == "GET" and not target_device_id and not action:
        devices = [
            _account_device_public(device, current_device_bi)
            for device in await _account_devices_list(env, account_bi)
        ]
        response = json_response(
            {
                "ok": True,
                "devices": devices,
                "currentDeviceId": current_device_bi[:16],
                "privacyNotice": (
                    "Only you can see this list. Each row is a node key bound "
                    "to your account by one of your own logins; public keys "
                    "are never returned here."
                ),
            },
            cache_control="no-store, max-age=0, must-revalidate",
        )
        return await _append_portable_session_cookie(
            env, request, response, token, rec, reuse_current=True
        )

    if action == "revoke-all":
        if method != "POST":
            return json_response(
                {"error": "method_not_allowed"}, status=405,
                cache_control="no-store, max-age=0, must-revalidate",
                extra_headers={"allow": "POST"})
    elif method != "DELETE":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET, DELETE"})

    denied = await _account_sudo_reauth(env, request, rec, data)
    if denied is not None:
        return denied

    if action == "revoke-all":
        raw_kinds = data.get("kinds")
        kinds = []
        if isinstance(raw_kinds, list):
            kinds = [
                clean_string(kind, 40) for kind in raw_kinds[:8]
                if clean_string(kind, 40) in ACCOUNT_DEVICE_KINDS
            ]
        targets = []
        for device in await _account_devices_list(env, account_bi):
            device_bi = str(device.get("deviceBi") or "")
            if not device_bi or device_bi == current_device_bi:
                continue
            if int(device.get("revokedAt") or 0):
                continue
            if kinds and device.get("kind") not in kinds:
                continue
            targets.append(device_bi)
        for device_bi in targets:
            await d1_run(
                env,
                "UPDATE account_devices SET revoked_at=?, enabled=0 "
                "WHERE account_bi=? AND device_bi=? AND revoked_at=0",
                now, account_bi, device_bi,
            )
        if kinds:
            # A filtered sign-out closes only the sessions those node keys
            # opened; browser sessions stay up.
            for device_bi in targets:
                await _account_revoke_device_sessions(
                    env, account_bi, device_bi)
        else:
            await d1_run(
                env,
                "UPDATE account_sessions SET revoked_at=? "
                "WHERE account_bi=? AND session_id<>? AND revoked_at=0",
                now, account_bi, current_session_id,
            )
        await _audit_sensitive_action(
            env, actor, "account.device_revoke_all", "account_device",
            "all-other-devices", "success",
            {"revokedDevices": len(targets), "kinds": ",".join(kinds),
             "sessions": "devices" if kinds else "all-other"})
        return json_response(
            {"ok": True, "revokedDevices": len(targets),
             "currentRevoked": False},
            cache_control="no-store, max-age=0, must-revalidate",
        )

    target_device_id = clean_string(target_device_id, 64).strip().lower()
    if not ACCOUNT_DEVICE_ID_RE.fullmatch(target_device_id):
        return json_response(
            {"error": "invalid_device_id"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    row = await d1_first(
        env,
        "SELECT device_bi, kind, label, enabled, revoked_at "
        "FROM account_devices "
        "WHERE account_bi=? AND substr(device_bi, 1, ?)=? LIMIT 1",
        account_bi, len(target_device_id), target_device_id,
    )
    device_bi = clean_string((row or {}).get("device_bi", ""), 128)
    if not row or not device_bi:
        return json_response(
            {"error": "device_not_found"}, status=404,
            cache_control="no-store, max-age=0, must-revalidate")
    await d1_run(
        env,
        "UPDATE account_devices SET revoked_at=?, enabled=0 "
        "WHERE account_bi=? AND device_bi=? AND revoked_at=0",
        now, account_bi, device_bi,
    )
    await _account_revoke_device_sessions(env, account_bi, device_bi)
    revoke_current = bool(current_device_bi) and device_bi == current_device_bi
    await _audit_sensitive_action(
        env, actor, "account.device_revoke", "account_device",
        device_bi[:16], "success",
        {"kind": clean_string(row.get("kind", ""), 40),
         "label": clean_string(row.get("label", ""), 120),
         "current": revoke_current})
    headers = (
        {"Set-Cookie": _clear_account_session_cookie()}
        if revoke_current else None
    )
    response = json_response(
        {"ok": True, "currentRevoked": revoke_current},
        extra_headers=headers,
        cache_control="no-store, max-age=0, must-revalidate",
    )
    return (
        _clear_all_account_cookies(env, request, response)
        if revoke_current else response
    )


ACCOUNT_DEVICE_CHECK_PROOF = "forkmesh-device-check-v1"


async def _account_device_check_signed(env, data, pubkey):
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).strip().lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    if not node or not sig or not pubkey or not _ts_ok(ts):
        return "", None
    canonical = (ACCOUNT_DEVICE_CHECK_PROOF + "\n" + node + "\n" + pubkey +
                 "\n" + str(ts)).encode()
    return await _signed_account_session(env, node, sig, canonical)


async def _account_device_check(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    token, cookie_auth = _request_account_session_token(request, data)
    if cookie_auth and not _request_origin_allowed(env, request):
        token = ""
    account_bi, rec, current_session_id = await _account_session_lookup(
        env, token, touch=False)
    pubkey = clean_string(data.get("pubkey", ""), 120).strip()
    if not account_bi or not rec or not current_session_id:
        account_bi, rec = await _account_device_check_signed(env, data, pubkey)
    if not account_bi or not rec:
        return json_response(
            {"error": await _account_session_invalid_error(env, token)},
            status=401,
            cache_control="no-store, max-age=0, must-revalidate")
    if not valid_node_pubkey(pubkey):
        return json_response(
            {"error": "invalid_pubkey"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    owned = (pubkey in await _account_signing_pubkeys(env, account_bi, rec)
             or pubkey in await _account_browser_control_pubkeys(
                 env, account_bi))
    return json_response(
        {"ok": True, "owned": owned,
         "nodeName": clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()},
        cache_control="no-store, max-age=0, must-revalidate")


async def _account_browser_control_pubkeys(env, account_bi):
    return [
        device.get("pubkey") or ""
        for device in await _account_devices_list(env, account_bi)
        if device.get("kind") == "browser_control"
        and device.get("enabled")
        and "desktop_control" in (device.get("capabilities") or [])
        and device.get("pubkey")
    ]


async def _account_desktops(env, account_bi, record):
    account = clean_string((record or {}).get("name", ""), MAX_NODE_NAME).lower()
    desktops = {}
    for device in await _account_devices_list(env, account_bi):
        pub = device.get("pubkey") or ""
        if (pub and device.get("enabled")
                and device.get("kind") == "desktop_node"
                and "owner_sign" in (device.get("capabilities") or [])):
            node = clean_string(device.get("label", ""), MAX_NODE_NAME)
            node = node.strip().lower()
            desktops[pub] = {
                "key": pub,
                "node": node if valid_node_name(node) else account,
                "lastSeen": int(device.get("lastSeen") or 0),
            }
    owner_pub = (record or {}).get("pubkey", "")
    if owner_pub and owner_pub not in desktops:
        desktops[owner_pub] = {"key": owner_pub, "node": account, "lastSeen": 0}
    return sorted(desktops.values(), key=lambda item: -item["lastSeen"])


async def _account_desktops_handler(env, request):
    no_store = "no-store, max-age=0, must-revalidate"
    token, _cookie_auth = _request_account_session_token(request, {})
    account_bi, rec, current_session_id = await _account_session_lookup(
        env, token, touch=True)
    if not account_bi or not rec or not current_session_id:
        return json_response(
            {"error": await _account_session_invalid_error(env, token)},
            status=401, cache_control=no_store)
    desktops = await _account_desktops(env, account_bi, rec)
    return json_response(
        {"ok": True,
         "account": clean_string(rec.get("name", ""), MAX_NODE_NAME).lower(),
         "desktops": [{"key": item["key"], "node": item["node"],
                       "lastSeen": item["lastSeen"]} for item in desktops]},
        cache_control=no_store)


async def _account_browser_control_bind(env, request):
    no_store = "no-store, max-age=0, must-revalidate"
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    token, cookie_auth = _request_account_session_token(request, data)
    if cookie_auth and not _request_origin_allowed(env, request):
        token = ""
    account_bi, rec, current_session_id = await _account_session_lookup(
        env, token, touch=False)
    if not account_bi or not rec or not current_session_id:
        return json_response(
            {"error": await _account_session_invalid_error(env, token)},
            status=401, cache_control=no_store)
    account = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    pubkey = clean_string(data.get("pubkey", ""), 120).strip()
    ts = clean_string(str(data.get("ts", "")), 20)
    sig = clean_string(data.get("sig", ""), 200)
    if not valid_node_pubkey(pubkey) or not valid_node_name(account):
        return json_response(
            {"error": "invalid_pubkey"}, status=400, cache_control=no_store)
    if not _ts_ok(ts):
        return json_response(
            {"error": "stale_request"}, status=401, cache_control=no_store)
    canonical = (BROWSER_CONTROL_BIND_PROOF + "\n" + account + "\n" +
                 pubkey + "\n" + ts).encode()
    if not sig or not await ed25519_verify(pubkey, sig, canonical):
        return json_response(
            {"error": "invalid_signature"}, status=401,
            cache_control=no_store)
    if pubkey == (rec.get("pubkey") or ""):
        return json_response(
            {"error": "device_key_conflict"}, status=409,
            cache_control=no_store)
    existing = await _account_device_for_pubkey(env, account_bi, pubkey)
    if existing:
        if clean_string(existing.get("kind", ""), 40) != "browser_control":
            return json_response(
                {"error": "device_key_conflict"}, status=409,
                cache_control=no_store)
        if (int(existing.get("revoked_at") or 0)
                or not int(existing.get("enabled") or 0)):
            return json_response(
                {"error": "device_revoked"}, status=401,
                cache_control=no_store)
    label = clean_string(data.get("label", ""), 120).strip() or "Web browser"
    device = await _register_account_device(
        env, account_bi, pubkey, "browser_control", label)
    now = int(Date.now())
    browsers = [
        device_row for device_row in await _account_devices_list(
            env, account_bi)
        if device_row.get("kind") == "browser_control"
        and device_row.get("enabled")
        and device_row.get("pubkey") != pubkey
    ]
    browsers.sort(key=lambda row: int(row.get("lastSeen") or 0))
    while len(browsers) >= BROWSER_CONTROL_MAX_DEVICES:
        oldest = browsers.pop(0)
        await d1_run(
            env,
            "UPDATE account_devices SET revoked_at=?, enabled=0 "
            "WHERE account_bi=? AND device_bi=? AND revoked_at=0",
            now, account_bi, oldest.get("deviceBi", ""),
        )
    if not existing:
        await _audit_sensitive_action(
            env, account, "account.browser_control_bind", "account_device",
            (device or {}).get("id", ""), "success", {"label": label})
    desktops = await _account_desktops(env, account_bi, rec)
    return json_response(
        {"ok": True, "account": account,
         "deviceId": (device or {}).get("id", ""),
         "desktopKeys": [item["key"] for item in desktops],
         "desktops": [{"key": item["key"], "node": item["node"]}
                      for item in desktops]},
        cache_control=no_store)


async def _account_rotate(env, request):
    """Rotate an active account's bound Ed25519 key after old-key approval.

    The desktop client may omit nodeName in its rotation record; in that case
    the relay resolves the account by oldPubkey, or treats an already-finished
    newPubkey binding plus prev_pubkeys entry as an idempotent retry.
    """
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)

    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    old_pubkey = clean_string(data.get("oldPubkey", ""), 120)
    new_pubkey = clean_string(data.get("newPubkey", ""), 120)
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("signature") or data.get("sig", ""), 200)

    if name:
        if not valid_node_name(name):
            return json_response({"error": "invalid_node_id"}, status=400)
    if not valid_node_pubkey(old_pubkey) or not valid_node_pubkey(new_pubkey):
        return json_response({"error": "invalid_pubkey"}, status=400)
    if not _ts_ok(ts):
        return json_response({"error": "stale_request"}, status=401)
    canonical = ("forkmesh-rotate-v1\n" + old_pubkey + "\n" +
                 new_pubkey + "\n" + str(ts)).encode()

    if name:
        name_bi, rec = await _account_row(env, name)
    else:
        name_bi, rec = await _account_row_by_pubkey(env, old_pubkey)
        if not rec:
            _, next_rec = await _account_row_by_pubkey(env, new_pubkey)
            next_name = clean_string(
                (next_rec or {}).get("name", ""), MAX_NODE_NAME).lower()
            next_current_pubkey = clean_string(
                (next_rec or {}).get("pubkey", ""), 120)
            next_prev_pubkeys = (next_rec or {}).get("prev_pubkeys")
            if (next_rec and next_rec.get("status") == "active" and
                    next_current_pubkey == new_pubkey and
                    isinstance(next_prev_pubkeys, list) and
                    old_pubkey in next_prev_pubkeys):
                if not valid_node_name(next_name):
                    return json_response({"error": "invalid_node_id"}, status=400)
                if not await ed25519_verify(old_pubkey, signature, canonical):
                    return json_response({"error": "bad_signature"}, status=401)
                return json_response(
                    {"ok": True, "nodeName": next_name, "pubkey": new_pubkey})
        if rec:
            name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
            if not valid_node_name(name):
                return json_response({"error": "invalid_node_id"}, status=400)
    if not rec or rec.get("status") != "active":
        return json_response({"error": "no_account"}, status=404)

    current_pubkey = clean_string(rec.get("pubkey", ""), 120)
    if current_pubkey == new_pubkey:
        return json_response({"ok": True, "nodeName": name, "pubkey": new_pubkey})
    if current_pubkey != old_pubkey:
        return json_response({"error": "not_bound"}, status=403)

    if not await ed25519_verify(old_pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)

    existing_bi, _ = await _account_row_by_pubkey(env, new_pubkey)
    if existing_bi and existing_bi != name_bi:
        return json_response({"error": "pubkey_taken"}, status=409)

    prev_pubkeys = rec.get("prev_pubkeys")
    if not isinstance(prev_pubkeys, list):
        prev_pubkeys = []
    if old_pubkey not in prev_pubkeys:
        prev_pubkeys.append(old_pubkey)
    rec["pubkey"] = new_pubkey
    rec["prev_pubkeys"] = prev_pubkeys
    rec["rotated_at"] = int(Date.now())
    await _save_account(env, name_bi, rec)
    # A primary key can also appear in the device registry (for example after
    # a password-bound desktop login).  Leaving that row enabled would make
    # the old key eligible through _owner_signing_pubkeys even though the
    # account record now names its successor.  Rotation is a revocation event,
    # not merely a change of preferred key: past records retain their embedded
    # public key and signature for historical verification, while this key can
    # never authorize a newly accepted event again.
    d1_update = globals().get("d1_run")
    if callable(d1_update):
        await d1_update(
            env,
            "UPDATE account_devices SET revoked_at=?, enabled=0 "
            "WHERE account_bi=? AND pubkey=? AND revoked_at=0",
            int(Date.now()), name_bi, old_pubkey,
        )
    await _account_revoke_sessions(env, name_bi)
    return json_response({"ok": True, "nodeName": name, "pubkey": new_pubkey})


async def _account_logout(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    token, _ = _request_account_session_token(request, data)
    account_bi, _rec, session_id = await _account_session_lookup(
        env, token, touch=False)
    if account_bi and session_id:
        await _account_revoke_sessions(env, account_bi, session_id)
    response = json_response(
        {"ok": True},
        extra_headers={"Set-Cookie": _clear_account_session_cookie()},
        cache_control="no-store, max-age=0, must-revalidate",
    )
    return _clear_all_account_cookies(env, request, response)


async def _account_last_seen(env, account_bi, floor_ts=0):
    """Newest activity stamp across this account's devices and nodes.

    Session stamps are already in hand from the listing read, so they come in as
    floor_ts; the devices/nodes maxima share one statement to keep the account
    screen off the multi-query path that overloaded the free plan.
    """
    floor_ts = int(floor_ts or 0)
    row = await d1_first(
        env,
        "SELECT MAX(seen) AS seen FROM ("
        "SELECT COALESCE(MAX(last_seen),0) AS seen FROM account_devices "
        "WHERE account_bi=? UNION ALL "
        "SELECT COALESCE(MAX(last_seen),0) FROM nodes WHERE user_bi=?)",
        account_bi, account_bi,
    )
    try:
        return max(floor_ts, int((row or {}).get("seen") or 0))
    except (TypeError, ValueError):
        return floor_ts


async def _account_sessions(env, request, target_session_id=""):
    """List or revoke this account's own sessions.

    The listing is strictly self-scoped: it is reachable only with a live
    session token for the account whose rows it returns, so the sign-in address
    on each row is visible to that owner alone.
    """
    method = method_name(request)
    token, cookie_auth = _request_account_session_token(request, {})
    if (
        cookie_auth
        and method == "DELETE"
        and not _request_origin_allowed(env, request)
    ):
        token = ""
    account_bi, rec, current_session_id = await _account_session_lookup(
        env, token, touch=method == "GET")
    if not account_bi or not rec or not current_session_id:
        # "device_revoked" when the token belongs to a node key that was
        # revoked from the registry, so that node can rotate its key instead
        # of retrying; "invalid_session" otherwise.
        return json_response(
            {"error": await _account_session_invalid_error(env, token)},
            status=401,
            cache_control="no-store, max-age=0, must-revalidate")

    now = int(Date.now())
    actor = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    if method == "GET" and not target_session_id:
        rows = await d1_all(
            env,
            "SELECT session_id,created_at,last_seen_at,expires_at,"
            "device_label,client_ip "
            "FROM account_sessions WHERE account_bi=? AND revoked_at=0 "
            "AND expires_at>? ORDER BY last_seen_at DESC,created_at DESC "
            "LIMIT ?",
            account_bi, now, ACCOUNT_SESSION_MAX_ACTIVE,
        )
        sessions = []
        for row in rows or []:
            session_id = clean_string(row.get("session_id", ""), 64)
            if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", session_id):
                continue
            sessions.append({
                "id": session_id,
                "deviceLabel": (
                    clean_string(row.get("device_label", ""), 80)
                    or "Unknown device"
                ),
                "ipAddress": clean_string(row.get("client_ip", ""), 64),
                "createdAt": int(row.get("created_at") or 0),
                "lastSeenAt": int(row.get("last_seen_at") or 0),
                "expiresAt": int(row.get("expires_at") or 0),
                "current": session_id == current_session_id,
            })
        response = json_response(
            {
                "ok": True,
                "sessions": sessions,
                # Account-level activity for the settings screen: when this
                # account was last active anywhere (sessions, linked devices,
                # nodes) and when it was last emailed, with the send outcome.
                # The small identity projection also lets another trusted
                # ForkMesh frontend origin restore its non-secret local
                # ``sessionToken: "cookie"`` marker from the HttpOnly cookie.
                # Never return the cookie token itself here.
                "account": {
                    "nodeName": actor,
                    "status": clean_string(
                        rec.get("status", "active"), 32),
                    "emailVerified": bool(rec.get("email_verified")),
                    "kind": "user",
                    "lastSeenAt": await _account_last_seen(
                        env, account_bi,
                        max([s["lastSeenAt"] for s in sessions] or [0])),
                    **_account_email_activity(rec),
                },
                "privacyNotice": (
                    "Only you can see this list. Each row shows a broad device "
                    "category, the address the sign-in came from, and session "
                    "timestamps. Raw user agents are never stored, and no "
                    "other account can read these rows."
                ),
            },
            # Every signed-in surface (App, WWW, World) reads this on load and
            # focus, so it is where the long-lived cookie is renewed before a
            # browser's own cookie-lifetime cap can drop it.
            extra_headers=(
                {"Set-Cookie": _account_session_cookie(token)}
                if cookie_auth else None
            ),
            cache_control="no-store, max-age=0, must-revalidate",
        )
        return await _append_portable_session_cookie(
            env, request, response, token, rec, reuse_current=True
        )

    if method != "DELETE":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET, DELETE"})

    target_session_id = clean_string(target_session_id, 64).strip()
    revoke_current = False
    if target_session_id == "others":
        await d1_run(
            env,
            "UPDATE account_sessions SET revoked_at=? "
            "WHERE account_bi=? AND session_id<>? AND revoked_at=0",
            now, account_bi, current_session_id,
        )
        audit_target = "all-other-devices"
        audit_scope = "others"
    elif target_session_id == "all":
        # "Log out everywhere" also drops the calling device, so a lost or
        # shared browser can be cleared in one action.
        await _account_revoke_sessions(env, account_bi)
        revoke_current = True
        audit_target = "all-devices"
        audit_scope = "all"
    else:
        if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", target_session_id):
            return json_response(
                {"error": "invalid_session_id"}, status=400,
                cache_control="no-store, max-age=0, must-revalidate")
        owned = await d1_first(
            env,
            "SELECT session_id FROM account_sessions "
            "WHERE account_bi=? AND session_id=? AND revoked_at=0 "
            "AND expires_at>?",
            account_bi, target_session_id, now,
        )
        if not owned:
            return json_response(
                {"error": "session_not_found"}, status=404,
                cache_control="no-store, max-age=0, must-revalidate")
        await _account_revoke_sessions(
            env, account_bi, target_session_id)
        revoke_current = target_session_id == current_session_id
        audit_target = target_session_id
        audit_scope = "current" if revoke_current else "device"

    await _audit_sensitive_action(
        env, actor, "account.session_revoke", "account_session",
        audit_target, "success", {"scope": audit_scope})
    headers = (
        {"Set-Cookie": _clear_account_session_cookie()}
        if revoke_current else None
    )
    response = json_response(
        {"ok": True, "currentRevoked": revoke_current},
        extra_headers=headers,
        cache_control="no-store, max-age=0, must-revalidate",
    )
    return (
        _clear_all_account_cookies(env, request, response)
        if revoke_current else response
    )


async def _account_admin_session(env, request):
    # Re-mint the HttpOnly `forkmesh_admin` page cookie from a still-valid
    # account session token, so an admin the app already treats as logged in
    # (localStorage session + 30-day forkmesh_session marker) doesn't have to
    # retype their password just to open the admin dashboard. The 12h admin
    # cookie is set only by _account_login and lapses long before the login
    # session does, which is why the admin page used to bounce a logged-in
    # admin back to /login (adhoc #163). The session token — issued only to an
    # already-authenticated caller and refreshed on every account poll — proves
    # identity here; is_admin gates the grant, so this never escalates.
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    token, cookie_auth = _request_account_session_token(request, data)
    if cookie_auth and not _request_origin_allowed(env, request):
        token = ""
    name = await _account_session_token_name(env, token)
    if not name or not await _is_admin(env, name):
        return json_response(
            {"error": "not_admin"},
            status=403,
            extra_headers={"Set-Cookie": _clear_account_session_cookie()},
            cache_control="no-store, max-age=0, must-revalidate",
        )
    admin_path = _admin_path(env)
    admin_url = ("/" + admin_path + "?admin=" + quote(name)) if admin_path else ""
    return json_response(
        {"ok": True, "nodeName": name, "adminUrl": admin_url},
        extra_headers={"Set-Cookie": _account_session_cookie(token)},
        cache_control="no-store, max-age=0, must-revalidate",
    )


def _random_bytes(n):
    return bytes(js_crypto.getRandomValues(Uint8Array.new(n)).to_py())


# A running node calls this on an interval to stay eligible for the reward
# split. Signed with the account's key so only the key holder can mark its node
# online; optionally updates the payout Solana address.
async def _account_heartbeat(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    solana = clean_string(data.get("solana", ""), 64)
    avatar_png, avatar_error = clean_avatar_png(data.get("avatarPng", ""))
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if avatar_error:
        status = 413 if avatar_error == "avatar_too_large" else 400
        return json_response({"error": avatar_error}, status=status)
    name_bi, rec = await _account_row(env, name)
    if not rec or rec.get("status") != "active":
        return json_response({"ok": True, "online": False})
    pubkey = rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    try:
        signature_version = int(data.get("signatureVersion", 1) or 1)
    except (TypeError, ValueError):
        signature_version = 0
    wallet_mutation = bool(
        solana and SOLANA_RE.match(solana)
        and rec.get("solana") != solana)
    if wallet_mutation and signature_version != 2:
        return json_response({
            "error": "wallet_binding_signature_required",
            "requiredSignatureVersion": 2,
        }, status=426)
    canonical = (
        ("forkmesh-heartbeat-v2\n" + name + "\n" + solana + "\n" + ts)
        if signature_version == 2
        else ("forkmesh-heartbeat-v1\n" + name + "\n" + ts)
    ).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)

    # Issue #346: the node itself is the only thing that knows when its local
    # Claude Code usage window refilled after running out, so it rides this
    # already-signed heartbeat to ask for a notification (opt-in on the
    # desktop side). Not part of the signed canonical string, same as solana/
    # avatarPng above — worst case a stale replay re-flags a notification the
    # recipient already has, not a forgeable action on someone else's account.
    credits_kind = clean_string(data.get("creditsRefilled", ""), 10)
    if credits_kind in ("5h", "weekly"):
        window = "5-hour" if credits_kind == "5h" else "weekly"
        await enqueue_notification(
            env, name, "credits_refilled",
            "Claude Code credits refilled",
            body=("Your " + window + " usage window has reset — Claude Code "
                  "credits are available again."),
            source="credits_refilled",
            dedupe="credits_refilled:" + credits_kind,
        )

    # Nodes can update the email preferences for the user account that owns
    # them. A linked owner controls all owned-node digest behavior from one
    # account record; unowned nodes update themselves.
    prefs_bi = name_bi
    prefs_rec = rec
    owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
    if owner:
        owner_bi, owner_rec = await _account_row(env, owner)
        if owner_rec and owner_rec.get("status") == "active":
            prefs_bi = owner_bi
            prefs_rec = owner_rec
    prefs_changed = False
    if "emailNotifications" in data:
        email_notifications = bool(data.get("emailNotifications"))
        if bool(prefs_rec.get("email_notifications", True)) != email_notifications:
            if email_notifications:
                prefs_rec.pop("email_notifications", None)
            else:
                prefs_rec["email_notifications"] = False
            prefs_changed = True
    if "notificationPreferences" in data:
        cleaner = globals().get("_clean_notification_preferences")
        if callable(cleaner):
            prefs = cleaner(data.get("notificationPreferences"), prefs_rec)
        elif isinstance(data.get("notificationPreferences"), dict):
            prefs = dict(data.get("notificationPreferences"))
        else:
            prefs = dict(prefs_rec.get("notification_preferences") or {})
        if prefs_rec.get("notification_preferences", {}) != prefs:
            prefs_rec["notification_preferences"] = prefs
            prefs_changed = True
    if "notificationDelivery" in data:
        applier = globals().get("_apply_notification_delivery")
        if callable(applier) and applier(
                prefs_rec, data.get("notificationDelivery")):
            prefs_changed = True
    # The desktop pushes a pause only on the beat after the user set one — it
    # is not restated every minute like the two settings above — so a pause
    # started in the browser is not overwritten by the next heartbeat.
    if "notificationPauseUntil" in data:
        pause_applier = globals().get("_apply_ping_pause")
        if callable(pause_applier) and pause_applier(
                prefs_rec, data.get("notificationPauseUntil")):
            prefs_changed = True
    # Like the pause, the desktop sends these only on the beat after the user
    # changed one, so a switch flipped in the browser is not overwritten.
    if "pingMutedKinds" in data:
        muted_applier = globals().get("_apply_ping_muted_kinds")
        if callable(muted_applier) and muted_applier(
                prefs_rec, data.get("pingMutedKinds")):
            prefs_changed = True
    if "notificationQuietHours" in data:
        quiet_applier = globals().get("_apply_ping_quiet_hours")
        if callable(quiet_applier) and quiet_applier(
                prefs_rec, data.get("notificationQuietHours")):
            prefs_changed = True
    if prefs_changed:
        await _save_account(env, prefs_bi, prefs_rec)
        if prefs_bi == name_bi:
            rec = prefs_rec

    # Keep the payout address current if the node sent a valid one.
    if wallet_mutation:
        rec["solana"] = solana
        await _save_account(env, name_bi, rec)
        await _audit_sensitive_action(
            env, name, "wallet.payout_address_bind", "account", name,
            "success", {"signatureVersion": signature_version})
    if avatar_png and rec.get("avatar_png") != avatar_png:
        rec["avatar_png"] = avatar_png
        rec["avatar_updated_at"] = int(Date.now())
        await _save_account(env, name_bi, rec)

    await d1_run(
        env,
        "INSERT INTO account_presence (name_bi, ts) VALUES (?, ?) "
        "ON CONFLICT(name_bi) DO UPDATE SET ts=excluded.ts",
        name_bi, int(Date.now()),
    )
    try:
        await touch_registered_node(env, name_bi, rec)
    except Exception:
        pass

    # Report this node's payout-wallet balance in the heartbeat reply so the
    # client doesn't have to poll Solana itself. We track the last public balance
    # seen; an increase means an incoming transfer arrived. This user-owned
    # balance is display metadata and never gates reward eligibility.
    wallet = rec.get("solana", "")
    balance_lamports = None
    balance_increased = False
    # Throttle the external Solana RPC to once per wallet per hour: one
    # subrequest on EVERY 60s heartbeat from every node was pure overhead, and
    # at fleet scale it was the single biggest source of public-RPC traffic.
    now_ms = int(Date.now())
    # Keyed by account+wallet: accounts sharing a payout wallet must each
    # keep their own balance-change baseline.
    probe_key = str(name_bi) + ":" + wallet
    last_probe = _HEARTBEAT_BALANCE_PROBES.get(probe_key, 0)
    if (wallet and SOLANA_RE.match(wallet)
            and now_ms - last_probe >= HEARTBEAT_SOLANA_BALANCE_MIN_MS):
        _HEARTBEAT_BALANCE_PROBES[probe_key] = now_ms
        if len(_HEARTBEAT_BALANCE_PROBES) > 5000:
            _HEARTBEAT_BALANCE_PROBES.clear()
        try:
            # No asyncio.wait_for: _solana_rpc_call already bounds every RPC
            # attempt with a native AbortSignal.timeout, and cancelling a
            # JS-backed await from Python leaves the task pending forever —
            # the wedge described at the top of this module, here on the
            # per-node heartbeat path.
            balance_lamports, _ = await _display_balance_lamports(
                env, wallet, name=name)
        except Exception:
            balance_lamports = None
        if balance_lamports is not None:
            prev = rec.get("last_balance_lamports")
            if isinstance(prev, int) and balance_lamports > prev:
                balance_increased = True
            if prev != balance_lamports:
                rec["last_balance_lamports"] = balance_lamports
                await _save_account(env, name_bi, rec)

    prefs_reader = globals().get("notification_email_preferences")
    if callable(prefs_reader):
        notification_preferences = prefs_reader(prefs_rec)
    else:
        notification_preferences = dict(
            prefs_rec.get("notification_preferences") or {})
    delivery_reader = globals().get("notification_delivery_mode")
    if callable(delivery_reader):
        notification_delivery = delivery_reader(prefs_rec)
    else:
        notification_delivery = (
            prefs_rec.get("notification_delivery") or "digest")
    pause_reader = globals().get("ping_pause_until")
    ping_pause = (pause_reader(prefs_rec) if callable(pause_reader)
                  else int(prefs_rec.get("notification_pause_until") or 0))
    muted_reader = globals().get("ping_muted_kinds")
    quiet_reader = globals().get("ping_quiet_hours")
    quiet_until_reader = globals().get("ping_quiet_until")
    # A desktop heartbeat is signed by the machine node, while administrator
    # status belongs to its owning user after the users/nodes split. Checking
    # only `name` leaves an admin's linked desktop looking like a non-admin and
    # keeps admin-only app navigation (including Users) hidden. Standalone
    # legacy user-clients still fall back to their own name.
    admin_account = owner or name
    is_admin = await _is_admin(env, admin_account)
    response = {"ok": True, "online": True,
                "hasPayoutAddress": bool(rec.get("solana")),
                "payoutCustody": "external-self-custodial-public-address",
                "payoutNotice": (
                    "The heartbeat shares a public payout address and optional "
                    "public balance only. ForkMesh holds no wallet key or user "
                    "funds, and balance never gates reward eligibility."
                ),
                "isAdmin": is_admin,
                "emailNotifications": prefs_rec.get("email_notifications") is not False,
                "notificationPreferences": notification_preferences,
                "notificationDelivery": notification_delivery,
                # Authoritative, so a pause set on any other surface reaches
                # this node on its next beat.
                "notificationPauseUntil": ping_pause}
    if callable(muted_reader):
        response["pingMutedKinds"] = muted_reader(prefs_rec)
    if callable(quiet_reader):
        response["notificationQuietHours"] = quiet_reader(prefs_rec)
    if callable(quiet_until_reader):
        response["notificationQuietUntil"] = quiet_until_reader(prefs_rec)
    if balance_lamports is not None:
        response["balanceLamports"] = balance_lamports
        response["balanceFundsState"] = "user-owned-external-wallet"
        response["balanceIncreased"] = balance_increased
    # A freshly launched federated instance's join request rides back on the
    # admin's own signed heartbeat (adhoc #97), the same rail as the claim /
    # ownership payloads below: the desktop shows a red dot over the relay
    # favicon plus an Approve button. Count only — relay details are fetched on
    # demand through the signed admin-relays endpoint when the admin clicks.
    if is_admin and _is_main_relay(env):
        try:
            pending_row = await d1_first(
                env, "SELECT COUNT(*) AS n FROM relays WHERE status='pending'")
            response["pendingRelays"] = int((pending_row or {}).get("n") or 0)
        except Exception:
            pass
    # A pending website claim (adhoc #53) rides back on the signed heartbeat:
    # only the node's key holder ever sees the confirmation code, and the node
    # shows it on its own screen for the claiming user to type into the site.
    # Expired claims are cleaned off the record here.
    claim = _claim_pending(rec, int(Date.now()))
    if claim:
        response["claim"] = {"user": claim.get("user", ""),
                             "code": claim.get("code", "")}
    elif rec.get("claim_pending"):
        rec.pop("claim_pending", None)
        await _save_account(env, name_bi, rec)
    # An admin-initiated ownership takeover (adhoc #141) rides back the same
    # way: only the node's own signed heartbeat carries it, so only whoever is
    # actually logged into that machine ever sees the prompt.
    transfer = _transfer_pending(rec, int(Date.now()))
    if transfer:
        response["ownershipTransfer"] = {"admin": transfer.get("admin", "")}
    elif rec.get("ownership_transfer_pending"):
        rec.pop("ownership_transfer_pending", None)
        await _save_account(env, name_bi, rec)
    # Accepted peer mirror requests (issue #385) ride back on this node's own
    # signed heartbeat, the same rail as claim/ownership above: the desktop node
    # clones each repo it agreed to mirror. It reports the ids it has acted on in
    # `mirrorRequestsAck` (not part of the signed canonical, like creditsRefilled)
    # so an accepted request stops being redelivered once the node has it.
    ack_ids = data.get("mirrorRequestsAck")
    if isinstance(ack_ids, list) and rec.get("mirror_requests"):
        remaining = ack_mirror_requests(rec.get("mirror_requests"), ack_ids)
        if remaining != rec.get("mirror_requests"):
            rec["mirror_requests"] = remaining
            await _save_account(env, name_bi, rec)
    if rec.get("mirror_requests"):
        pending_mirrors = accepted_mirror_requests(rec.get("mirror_requests"))
        if pending_mirrors:
            response["mirrorRequests"] = pending_mirrors
    return json_response(response)


async def _mirroring_owners(env):
    # Set of owner names that actually mirror a repo for another node, used to
    # keep single-repo-only nodes out of reward consideration (issue #94). Best
    # effort: on any read error return None so callers keep their prior behaviour
    # (fail open) rather than starving every node of its share.
    try:
        rows = await d1_all(
            env, "SELECT data FROM repositories WHERE is_private = 0")
    except Exception:
        return None
    records = []
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data"))
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        records.append(rec)
    return mirroring_owner_set(records)


async def _online_payout_addresses(env):
    # Deduplicated payout addresses of currently-online, active accounts that
    # actually mirror a repo for another node. A node hosting only its own
    # un-mirrored repos adds no redundancy, so it is left out of consideration
    # (issue #94). Stale presence rows self-heal here so the table stays bounded.
    cutoff = int(Date.now()) - ACCOUNT_PRESENCE_STALE_MS
    try:
        await d1_run(env, "DELETE FROM account_presence WHERE ts < ?", cutoff)
    except Exception:
        pass
    mirroring = await _mirroring_owners(env)
    rows = await d1_all(
        env, "SELECT name_bi FROM account_presence WHERE ts >= ? ORDER BY ts DESC",
        cutoff,
    )
    seen = set()
    addresses = []
    for r in rows:
        row = await d1_first(
            env, "SELECT name, data FROM nodes WHERE node_bi=?", r["name_bi"])
        if not row:
            continue
        rec = await decrypt_row(env, row["data"])
        if not rec or rec.get("status") != "active":
            continue
        owner = clean_string(row.get("name") or rec.get("name", ""), MAX_NODE_NAME)
        # Only nodes that mirror a repo shared with another node earn a share.
        if mirroring is not None and owner.lower() not in mirroring:
            continue
        solana = (rec.get("solana") or "").strip()
        if not solana or not SOLANA_RE.match(solana) or solana in seen:
            continue
        seen.add(solana)
        addresses.append(solana)
    # Federated rewards intentionally do not use this historical address-only
    # helper. They enter both randomized and instant plans exclusively through
    # _eligible_reward_snapshot's signed, fresh attestation path.
    return addresses


# --- Community reward-pool address (issue #308) ------------------------------
# A public configured address may receive voluntary contributions. The Worker
# reads its balance and prepares unsigned distribution intents; the instance
# owner's self-custodial desktop signer alone can authorize a transfer.
REWARD_CLUSTER_GENESIS_HASHES = {
    "mainnet-beta": "5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d",
    "devnet": "EtWTRABZaYq6iMfeYKouRu166VU2xqa1wcaWoxPkrZBG",
    "testnet": "4uhcVJyU9pJkvQyS88uRDiswHXSCkY3zQawwpjk2NsNY",
}
REWARD_CANONICAL_RPC_HOSTS = {
    "api.mainnet-beta.solana.com": "mainnet-beta",
    "api.devnet.solana.com": "devnet",
    "api.testnet.solana.com": "testnet",
}


def _reward_network(env):
    value = clean_string(
        getattr(env, "COMMUNITY_REWARD_NETWORK", "mainnet-beta"), 32
    ).strip().lower()
    return value if value in REWARD_CLUSTER_GENESIS_HASHES else ""


def _reward_rpc_url(env):
    raw = clean_string(
        getattr(env, "COMMUNITY_REWARD_RPC_URL", ""), 500).strip()
    try:
        parsed = urlparse(raw)
    except Exception:
        return ""
    if (
        parsed.scheme.lower() != "https"
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
    ):
        return ""
    network = _reward_network(env)
    canonical_network = REWARD_CANONICAL_RPC_HOSTS.get(
        parsed.hostname.lower().rstrip("."))
    if not network or (
        canonical_network is not None and canonical_network != network
    ):
        return ""
    return raw


class _RewardRpcEnvironment:
    """Narrow view that keeps the reward test network separate from legacy RPCs."""

    def __init__(self, env):
        self.SOLANA_NETWORK = _reward_network(env)
        self.SOLANA_RPC_URL = _reward_rpc_url(env)


async def _reward_solana_rpc(env, method, params):
    if not _reward_network(env) or not _reward_rpc_url(env):
        return None
    return await _solana_rpc(_RewardRpcEnvironment(env), method, params)


# Per-isolate memo of the reward-pool network proof. The proof is two Solana
# RPC round trips (getGenesisHash + getAccountInfo) whose answers are stable
# configuration facts — a cluster's genesis hash is immutable and the funded
# pool account does not stop existing — yet it used to run on EVERY
# /api/accounts/central-fund view. Public RPC endpoints rate-limit, so each
# transient 429/timeout surfaced as a 503 on the page (2026-07-24 error-log
# burst). A verified (network, rpc_url, address) triple is trusted for the
# fresh TTL without touching the RPC, and kept as a stale fallback when a
# re-proof attempt fails, bounded so a truly dead RPC still fails closed.
_REWARD_POOL_VERIFY_MEMO = {"key": None, "ts": 0, "read": 0}
REWARD_POOL_VERIFY_FRESH_MS = 60 * 60 * 1000
REWARD_POOL_VERIFY_STALE_MAX_MS = 24 * 60 * 60 * 1000
# The proof belongs to the fleet, not to one isolate. Cloudflare recycles
# isolates constantly, so a memo that only lives in memory means the FIRST
# view on every fresh isolate still pays both RPC round trips — and answers
# 503 whenever a rate limit eats either one. That is how a crawler hitting
# /api/accounts/central-fund got a 503 (adhoc #176, cpu 2ms / wall 988ms: no
# work, just a public RPC that did not answer) off a pool that was configured
# and funded the whole time. One schema_meta row carries the same
# (network, rpc_url, address) triple and its proof time across isolates under
# these same windows, the way wallet_balances already carries the displayed
# balance. It only decides whether the configured address may be shown — the
# address itself comes from env, and every path that signs still reads the
# live balance first — and a disqualifying ANSWER deletes it, so failing
# closed still propagates fleet-wide.
REWARD_POOL_VERIFY_STATE_KEY = "reward_pool_verified"
# Consulting that row is itself a D1 read, so an RPC outage must not turn
# every view into one: an isolate re-reads it at most this often.
REWARD_POOL_VERIFY_SHARE_RECHECK_MS = 60 * 1000


async def _stored_reward_pool_proof(env):
    """The fleet's ``(triple, proved_at_ms)`` proof, or None. Never raises."""
    try:
        row = await d1_first(
            env, "SELECT v FROM schema_meta WHERE k=?",
            REWARD_POOL_VERIFY_STATE_KEY)
        stored = json.loads(str((row or {}).get("v") or "{}"))
        key = stored.get("key")
        proved_at = int(stored.get("ts") or 0)
    except Exception:
        return None
    if not isinstance(key, list) or len(key) != 3 or proved_at <= 0:
        return None
    return tuple(str(part) for part in key), proved_at


async def _remember_reward_pool_proof(env, memo_key, now):
    # Best effort: losing the shared copy only costs the next cold isolate the
    # two RPC round trips it would have spent before this row existed.
    try:
        await d1_run(
            env,
            "INSERT INTO schema_meta(k,v) VALUES (?,?) "
            "ON CONFLICT(k) DO UPDATE SET v=excluded.v",
            REWARD_POOL_VERIFY_STATE_KEY,
            json.dumps({"key": list(memo_key), "ts": int(now)}),
        )
    except Exception:
        pass


async def _forget_reward_pool_proof(env):
    try:
        await d1_run(
            env, "DELETE FROM schema_meta WHERE k=?",
            REWARD_POOL_VERIFY_STATE_KEY)
    except Exception:
        pass


async def _reward_pool_network_verified(env, address):
    """Prove the RPC cluster and configured public pool account fail closed."""
    network = _reward_network(env)
    rpc_url = _reward_rpc_url(env)
    if (
        not network
        or not rpc_url
        or not address
        or not SOLANA_RE.match(address)
    ):
        return False
    memo_key = (network, rpc_url, address)
    now = int(Date.now())
    memo = _REWARD_POOL_VERIFY_MEMO
    proved_at = int(memo["ts"] or 0) if memo["key"] == memo_key else 0
    if proved_at and now - proved_at < REWARD_POOL_VERIFY_FRESH_MS:
        return True
    if now - int(memo.get("read") or 0) >= REWARD_POOL_VERIFY_SHARE_RECHECK_MS:
        memo["read"] = now
        shared = await _stored_reward_pool_proof(env)
        if shared and shared[0] == memo_key and shared[1] > proved_at:
            # Another isolate already proved this exact configuration. Adopt
            # its proof time rather than extending the window with ours.
            proved_at = shared[1]
            memo["key"] = memo_key
            memo["ts"] = proved_at
            if now - proved_at < REWARD_POOL_VERIFY_FRESH_MS:
                return True
    genesis = await _reward_solana_rpc(env, "getGenesisHash", [])
    if (
        not isinstance(genesis, dict)
        or not hmac.compare_digest(
            str(genesis.get("result") or ""),
            REWARD_CLUSTER_GENESIS_HASHES[network],
        )
    ):
        # A wrong-cluster ANSWER is disqualifying and clears the fallback; a
        # missing answer (rate limit, timeout → None) is transient and may
        # still serve from the bounded stale window.
        if isinstance(genesis, dict):
            memo["key"] = None
            await _forget_reward_pool_proof(env)
            return False
        return bool(
            proved_at and now - proved_at < REWARD_POOL_VERIFY_STALE_MAX_MS)
    account = await _reward_solana_rpc(
        env,
        "getAccountInfo",
        [address, {"encoding": "base64", "commitment": "finalized"}],
    )
    if not isinstance(account, dict):
        return bool(
            proved_at and now - proved_at < REWARD_POOL_VERIFY_STALE_MAX_MS)
    result = account.get("result")
    verified = bool(
        isinstance(result, dict)
        and isinstance(result.get("value"), dict)
    )
    if verified:
        memo["key"] = memo_key
        memo["ts"] = now
        await _remember_reward_pool_proof(env, memo_key, now)
    else:
        memo["key"] = None
        await _forget_reward_pool_proof(env)
    return verified


async def _reward_balance_lamports(env, address):
    if not address or not SOLANA_RE.match(address):
        return None
    response = await _reward_solana_rpc(env, "getBalance", [address])
    if not isinstance(response, dict):
        return None
    result = response.get("result")
    if not isinstance(result, dict):
        return None
    try:
        return int(result.get("value"))
    except (TypeError, ValueError):
        return None


async def _reward_public_entropy(env):
    response = await _reward_solana_rpc(
        env, "getLatestBlockhash", [{"commitment": "finalized"}])
    if not isinstance(response, dict):
        return ""
    try:
        return clean_string(
            response["result"]["value"]["blockhash"], 120).strip()
    except Exception:
        return ""


def _reward_config(env):
    return {
        "intervalMs": reward_policy.bounded_int(
            getattr(env, "REWARD_INTERVAL_MS", ""),
            CENTRAL_FUND_DISTRIBUTION_INTERVAL_MS,
            15 * 60 * 1000,
            24 * 60 * 60 * 1000,
        ),
        "jitterMs": reward_policy.bounded_int(
            getattr(env, "REWARD_JITTER_MAX_MS", ""),
            REWARD_DEFAULT_JITTER_MS,
            0,
            12 * 60 * 60 * 1000,
        ),
        "amountLamports": reward_policy.bounded_int(
            getattr(env, "REWARD_AMOUNT_LAMPORTS", ""),
            REWARD_DEFAULT_AMOUNT_LAMPORTS,
            1_000,
            10 * LAMPORTS_PER_SOL,
        ),
        "minimumUptimeMs": reward_policy.bounded_int(
            getattr(env, "REWARD_MIN_UPTIME_MS", ""),
            REWARD_DEFAULT_MIN_UPTIME_MS,
            0,
            30 * 24 * 60 * 60 * 1000,
        ),
        "minimumContributionUnits": reward_policy.bounded_int(
            getattr(env, "REWARD_MIN_CONTRIBUTION_UNITS", ""),
            0,
            0,
            1_000_000,
        ),
        "healthFreshMs": reward_policy.bounded_int(
            getattr(env, "REWARD_HEALTH_FRESH_MS", ""),
            REWARD_ENDPOINT_FRESH_MS,
            60 * 1000,
            60 * 60 * 1000,
        ),
    }


def _reward_explorer_url(network, signature="", address=""):
    base = "https://explorer.solana.com/"
    if signature:
        base += "tx/" + quote(signature)
    elif address:
        base += "address/" + quote(address)
    suffix = "" if network == "mainnet-beta" else "?cluster=" + quote(network)
    return base + suffix


async def _write_reward_observations(env, observations):
    """Upsert bounded eligibility observations without one query per node."""
    for offset in range(0, len(observations), 16):
        chunk = observations[offset:offset + 16]
        if not chunk:
            continue
        values = ",".join("(?,?,?,?,?)" for _item in chunk)
        await d1_run(
            env,
            "INSERT INTO reward_node_observations "
            "(node_bi,first_verified_at,last_verified_at,"
            "consecutive_checks,contribution_units) VALUES " + values + " "
            "ON CONFLICT(node_bi) DO UPDATE SET "
            "first_verified_at=excluded.first_verified_at,"
            "last_verified_at=excluded.last_verified_at,"
            "consecutive_checks=excluded.consecutive_checks,"
            "contribution_units=MAX("
            "reward_node_observations.contribution_units,"
            "excluded.contribution_units)",
            *(value for item in chunk for value in item),
        )


async def _eligible_reward_snapshot(env, now=None):
    """Build eligibility from server-observed, signed HTTPS health facts."""
    now = int(now if now is not None else Date.now())
    config = _reward_config(env)
    cutoff = now - config["healthFreshMs"]
    expected_refs = await _https_mirror_expected_forkmesh_refs(env)
    rows = await d1_all(
        env,
        "SELECT e.node_bi, e.node_name, e.base_url, e.public_key, e.checked_at, "
        "e.healthy, e.integrity, e.abuse_blocked, "
        "e.forkmesh_verified_at, e.forkmesh_refs_sha256, "
        "e.forkmesh_operations_sha256, e.forkmesh_operations_json, "
        "e.forkmesh_active, e.registration_sig, e.issued_at, "
        "e.health_sig, e.health_message, p.ts AS presence_ts, "
        "n.data, n.pubkey AS node_pubkey, "
        "o.first_verified_at, o.last_verified_at, "
        "o.consecutive_checks, o.contribution_units "
        "FROM mirror_https_endpoints e "
        "JOIN account_presence p ON p.name_bi=e.node_bi "
        "JOIN nodes n ON n.node_bi=e.node_bi "
        "LEFT JOIN reward_node_observations o ON o.node_bi=e.node_bi "
        "WHERE p.ts>=? AND e.checked_at>=? "
        "AND e.forkmesh_verified_at>=? "
        "ORDER BY e.node_name ASC LIMIT 50",
        now - ACCOUNT_PRESENCE_STALE_MS, cutoff, cutoff,
    )
    decoded_rows = []
    allowed_identity_keys = {}
    for row in rows or []:
        node_bi = str(row.get("node_bi") or "")
        record = await decrypt_row(env, row.get("data"))
        if not node_bi or not record or record.get("status") != "active":
            continue
        decoded_rows.append((row, record))
        keys = allowed_identity_keys.setdefault(node_bi, set())
        for value in (row.get("node_pubkey"), record.get("pubkey")):
            key = clean_string(value or "", 160).strip()
            if key:
                keys.add(key)
    node_bis = sorted(allowed_identity_keys)
    if node_bis:
        device_rows = await d1_all(
            env,
            "SELECT account_bi,pubkey,capabilities FROM account_devices "
            "WHERE account_bi IN (SELECT CAST(value AS TEXT) "
            "FROM json_each(?)) AND enabled=1 AND revoked_at=0",
            json.dumps(node_bis, separators=(",", ":")),
        )
        for device in device_rows or []:
            capabilities = {
                value for value in clean_string(
                    device.get("capabilities") or "", 512).split(",")
                if value
            }
            if "owner_sign" not in capabilities:
                continue
            account_bi = str(device.get("account_bi") or "")
            public_key = clean_string(
                device.get("pubkey") or "", 160).strip()
            if account_bi in allowed_identity_keys and public_key:
                allowed_identity_keys[account_bi].add(public_key)
    candidates = []
    observations = []
    for row, record in decoded_rows:
        node_bi = str(row.get("node_bi") or "")
        last_verified = int(row.get("last_verified_at") or 0)
        if last_verified and now - last_verified <= REWARD_OBSERVATION_GAP_MS:
            first_verified = int(row.get("first_verified_at") or now)
            consecutive = int(row.get("consecutive_checks") or 0) + 1
        else:
            first_verified = now
            consecutive = 1
        contribution_units = max(
            0, int(row.get("contribution_units") or 0))
        observations.append((
            node_bi, first_verified, now, consecutive, contribution_units))
        node_name = clean_string(
            row.get("node_name") or record.get("name"), MAX_NODE_NAME
        ).strip().lower()
        owner = clean_string(
            record.get("owner") or node_name, MAX_NODE_NAME).strip().lower()
        operator_id = await blind_index(env, "reward-operator:" + owner)
        public_key = clean_string(row.get("public_key"), 160).strip()
        refs_hash = clean_string(
            row.get("forkmesh_refs_sha256"), 64).lower()
        operations_hash = clean_string(
            row.get("forkmesh_operations_sha256"), 64).lower()
        try:
            operations = json.loads(
                str(row.get("forkmesh_operations_json") or "[]"))
        except Exception:
            operations = []
        normalized_operations_hash = https_routing.operations_sha256(operations)
        required_operations_ok = bool(
            normalized_operations_hash
            and hmac.compare_digest(
                normalized_operations_hash, operations_hash)
            and HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS.issubset(
                set(operations))
        )
        signed_attestation = await _verified_federated_reward_attestation(
            env,
            {
                "name": node_name,
                "operator": owner,
                "wallet": str(record.get("solana") or "").strip(),
                "publicKey": public_key,
                "baseUrl": row.get("base_url"),
                "registrationSignature": row.get("registration_sig"),
                "registrationIssuedAt": row.get("issued_at"),
                "healthMessage": row.get("health_message"),
                "healthSignature": row.get("health_sig"),
                "checkedAt": row.get("checked_at"),
                "healthy": True,
                "integrity": "ok",
                "mirrorsForkMesh": True,
                "requiredOperationsVerified": required_operations_ok,
                "abuseFlagged": False,
                "forkmeshVerifiedAt": row.get("forkmesh_verified_at"),
                "refsSha256": refs_hash,
                "operationsSha256": operations_hash,
            },
            now,
            expected_refs,
            config["healthFreshMs"],
        )
        endpoint_ok = bool(
            signed_attestation
            and public_key in allowed_identity_keys.get(node_bi, set())
            and required_operations_ok
            and not int(row.get("abuse_blocked") or 0)
        )
        candidates.append({
            "nodeId": node_name,
            "operatorId": operator_id,
            "deviceId": hashlib.sha256(public_key.encode()).hexdigest(),
            "walletAddress": str(record.get("solana") or "").strip(),
            "attestationSourceApproved": True,
            "identitySignatureVerified": endpoint_ok,
            "healthAttestationSignatureVerified": endpoint_ok,
            "healthAttestationFresh": bool(
                int(row.get("checked_at") or 0) >= cutoff
                and int(row.get("forkmesh_verified_at") or 0) >= cutoff),
            "online": (
                int(row.get("presence_ts") or 0)
                >= now - ACCOUNT_PRESENCE_STALE_MS
            ),
            "healthy": endpoint_ok,
            "mirrorsForkMesh": bool(int(
                row.get("forkmesh_active") or 0)),
            "integrity": (
                "signed-manifest-verified" if endpoint_ok else "unknown"
            ),
            "abuseFlagged": bool(int(row.get("abuse_blocked") or 0)),
            "observedUptimeMs": max(0, now - first_verified),
            "contributionUnits": contribution_units,
            "healthCheckedAt": int(row.get("checked_at") or 0),
            "attestationId": hashlib.sha256(
                (
                    node_bi + "\0" + refs_hash + "\0"
                    + operations_hash + "\0"
                    + str(row.get("forkmesh_verified_at") or 0)
                ).encode()
            ).hexdigest(),
        })
    await _write_reward_observations(env, observations)
    if _is_main_relay(env):
        federated_rows = await d1_all(
            env,
            "SELECT fp.*,r.label AS relay_label "
            "FROM federated_presence fp "
            "JOIN relays r ON r.relay_bi=fp.relay_bi "
            "WHERE r.status='approved' AND fp.ts>=? "
            "AND fp.checked_at>=? AND fp.forkmesh_verified_at>=? "
            "AND fp.healthy=1 AND fp.integrity='ok' "
            "AND fp.forkmesh_active=1 AND fp.abuse_blocked=0 "
            "ORDER BY fp.relay_bi,fp.name LIMIT 50",
            now - ACCOUNT_PRESENCE_STALE_MS, cutoff, cutoff,
        )
        for row in federated_rows or []:
            item = await _verified_federated_reward_attestation(
                env,
                {
                    "name": row.get("name"),
                    "operator": row.get("name"),
                    "wallet": row.get("wallet"),
                    "publicKey": row.get("public_key"),
                    "baseUrl": row.get("base_url"),
                    "registrationSignature": row.get("registration_sig"),
                    "registrationIssuedAt": row.get(
                        "registration_issued_at"),
                    "healthMessage": row.get("health_message"),
                    "healthSignature": row.get("health_sig"),
                    "checkedAt": row.get("checked_at"),
                    "healthy": bool(int(row.get("healthy") or 0)),
                    "integrity": row.get("integrity"),
                    "mirrorsForkMesh": bool(
                        int(row.get("forkmesh_active") or 0)),
                    "forkmeshVerifiedAt": row.get(
                        "forkmesh_verified_at"),
                    "refsSha256": row.get("forkmesh_refs_sha256"),
                    "operationsSha256": row.get(
                        "forkmesh_operations_sha256"),
                    "requiredOperationsVerified": True,
                    "abuseFlagged": bool(
                        int(row.get("abuse_blocked") or 0)),
                },
                now,
                expected_refs,
                config["healthFreshMs"],
            )
            operator_id = str(row.get("operator_id") or "")
            device_id = str(row.get("device_id") or "")
            attestation_id = str(row.get("attestation_id") or "")
            relay_bi = str(row.get("relay_bi") or "")
            if (
                not item
                or not operator_id
                or not hmac.compare_digest(
                    device_id, item.get("deviceId") or "")
                or not re.fullmatch(r"[0-9a-f]{64}", attestation_id)
                or not relay_bi
            ):
                continue
            candidates.append({
                "nodeId": (
                    "relay-" + relay_bi[:16] + "-"
                    + item["name"]),
                "operatorId": operator_id,
                "deviceId": device_id,
                "walletAddress": item["wallet"],
                "attestationSourceApproved": True,
                "identitySignatureVerified": True,
                "healthAttestationSignatureVerified": True,
                "healthAttestationFresh": True,
                "online": int(row.get("ts") or 0) >= (
                    now - ACCOUNT_PRESENCE_STALE_MS),
                "healthy": True,
                "mirrorsForkMesh": True,
                "integrity": "signed-manifest-verified",
                "abuseFlagged": False,
                "observedUptimeMs": max(
                    0, now - int(row.get("first_verified_at") or now)),
                "contributionUnits": 0,
                "healthCheckedAt": item["checkedAt"],
                "attestationId": attestation_id,
                "relayLabel": clean_string(
                    row.get("relay_label") or "relay", 80),
            })
    snapshot = reward_policy.eligibility_snapshot(
        candidates,
        minimum_uptime_ms=config["minimumUptimeMs"],
        minimum_contribution_units=config["minimumContributionUnits"],
    )
    snapshot["generatedAt"] = now
    snapshot["source"] = (
        "signed HTTPS identity + fresh Cloudflare health check + "
        "forkmesh/forkmesh refs integrity proof + server-observed presence; "
        "approved federated relays additionally preserve and forward the "
        "original node-signed registration and health messages"
    )
    if _is_main_relay(env):
        snapshot.setdefault("limitations", []).append(
            "An approved federated relay attests that it performed the "
            "network challenge. Relay approval is a revocable trust boundary, "
            "not proof of personhood or universal node trust."
        )
    return snapshot


def _reward_pool_address(env):
    """Resolve the public reward destination without loading wallet material.

    COMMUNITY_REWARD_POOL_ADDRESS is the explicit modern override. Existing
    ForkMesh deployments historically supplied the same public destination as
    TREASURY_SOLANA_ADDRESS, so that name remains a compatibility fallback.
    A non-empty explicit override fails closed later if it is invalid instead
    of silently sending contributors to a different configured address.
    """
    primary = clean_string(
        getattr(env, "COMMUNITY_REWARD_POOL_ADDRESS", ""), 80).strip()
    if primary:
        return primary
    return clean_string(
        getattr(env, "TREASURY_SOLANA_ADDRESS", ""), 80).strip()


async def _central_fund_record(env):
    # The pool address is public configuration. Its private key lives in the
    # instance owner's local signer and is never generated, uploaded or loaded
    # by Cloudflare.
    address = _reward_pool_address(env)
    if (
        not SOLANA_RE.match(address)
        or not await _reward_pool_network_verified(env, address)
    ):
        return None
    signer_account = clean_string(
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", ""),
        MAX_NODE_NAME,
    ).strip().lower()
    return {
        "address": address,
        "signer_account": signer_account,
        "custody": "external-local-signer",
        "network": _reward_network(env),
    }


async def _save_central_fund(env, rec):
    # Compatibility symbol: central-fund state is now derived from public
    # configuration + append-only signing intents, never an encrypted key row.
    del env, rec
    return False


async def _central_fund_public(env, refresh=False):
    # Public contribution payload: configured address, selected-network balance,
    # direct contribution choices, and independently verifiable finalized history.
    rec = await _central_fund_record(env)
    if not rec:
        return None
    addr = rec.get("address", "")
    network = rec.get("network", "mainnet-beta")
    # Display only — the distribution paths below read the live balance
    # themselves before they will sign anything.
    balance, balance_checked_at = await _display_balance_lamports(
        env, addr, force=refresh, reader=_reward_balance_lamports)
    latest = await d1_first(
        env,
        "SELECT intent_id, status, created_at, tx_signature, completed_at "
        "FROM chain_intents WHERE kind IN "
        "('community_reward_random','community_reward_instant_distribution') "
        "ORDER BY created_at DESC LIMIT 1",
    )
    latest_round = await d1_first(
        env,
        "SELECT round_id,status,interval_start,scheduled_at,execute_after,"
        "schedule_entropy,snapshot_data,selection_data,intent_id,"
        "completed_at FROM reward_rounds "
        "ORDER BY interval_start DESC LIMIT 1",
    )
    round_public = None
    if latest_round:
        try:
            round_snapshot = json.loads(
                str(latest_round.get("snapshot_data") or "{}"))
        except Exception:
            round_snapshot = {}
        try:
            round_selection = json.loads(
                str(latest_round.get("selection_data") or "{}"))
        except Exception:
            round_selection = {}
        rejection_counts = {}
        for rejected in round_snapshot.get("rejected") or []:
            reason = clean_string(
                (rejected or {}).get("reason"), 80).strip()
            if reason:
                rejection_counts[reason] = (
                    int(rejection_counts.get(reason) or 0) + 1)
        candidate = (
            round_selection.get("candidate")
            if isinstance(round_selection, dict) else {}
        ) or {}
        round_public = {
            "roundId": str(latest_round.get("round_id") or ""),
            "status": str(latest_round.get("status") or ""),
            "intervalStart": int(
                latest_round.get("interval_start") or 0),
            "scheduledAt": int(latest_round.get("scheduled_at") or 0),
            "executeAfter": int(latest_round.get("execute_after") or 0),
            "scheduleEntropy": str(
                latest_round.get("schedule_entropy") or ""),
            "scheduleEntropySource": (
                network + "-finalized-solana-blockhash"
            ),
            "snapshotHash": str(
                round_snapshot.get("snapshotHash") or ""),
            "eligibleCount": len(round_snapshot.get("eligible") or []),
            "rejectionCounts": rejection_counts,
            "policy": round_snapshot.get("policy") or {},
            "limitations": round_snapshot.get("limitations") or [],
            "selection": ({
                "algorithm": str(
                    round_selection.get("algorithm") or ""),
                "selectedIndex": int(
                    round_selection.get("selectedIndex") or 0),
                "eligibleCount": int(
                    round_selection.get("eligibleCount") or 0),
                "snapshotHash": str(
                    round_selection.get("snapshotHash") or ""),
                "entropySource": str(
                    round_selection.get("entropySource") or ""),
                "publicEntropy": str(
                    round_selection.get("publicEntropy") or ""),
                "selectedNodeId": str(candidate.get("nodeId") or ""),
                "selectedWalletAddress": str(
                    candidate.get("walletAddress") or ""),
            } if round_selection else None),
            "intentId": str(latest_round.get("intent_id") or ""),
            "completedAt": int(latest_round.get("completed_at") or 0),
        }
    completed = await d1_all(
        env,
        "SELECT intent_id, kind, status, data, created_at, tx_signature, "
        "completed_at FROM chain_intents WHERE kind IN "
        "('community_reward_random','community_reward_instant_distribution') "
        "AND status='completed' ORDER BY completed_at DESC LIMIT 20",
    )
    transactions = []
    for row in completed or []:
        try:
            plan = json.loads(str(row.get("data") or "{}"))
        except Exception:
            plan = {}
        for transfer in (plan.get("transfers") or [])[:200]:
            if not isinstance(transfer, dict):
                continue
            transactions.append({
                "eventId": (
                    str(row.get("intent_id") or "") + ":"
                    + str(len(transactions))
                ),
                "type": (
                    "instant-all-nodes"
                    if row.get("kind")
                    == "community_reward_instant_distribution"
                    else "randomized-node-reward"
                ),
                "recipient": str(transfer.get("address") or ""),
                "recipientNode": str(
                    transfer.get("nodeId")
                    or (plan.get("selection") or {}).get("selectedNodeId")
                    or ""
                ),
                "lamports": int(transfer.get("lamports") or 0),
                "amountSol": _amount_sol(
                    int(transfer.get("lamports") or 0)),
                "status": "completed-on-chain",
                "transactionSignature": str(
                    row.get("tx_signature") or ""),
                "completedAt": int(row.get("completed_at") or 0),
                "explorerUrl": _reward_explorer_url(
                    network, signature=str(row.get("tx_signature") or "")),
            })
    contribution_rows = await d1_all(
        env,
        "SELECT contribution_id, mode, amount_lamports, status, "
        "tx_signature, confirmed_at, distribution_intent_id "
        "FROM reward_contributions "
        "WHERE status NOT IN ('prepared','expired') "
        "ORDER BY confirmed_at DESC LIMIT 20",
    )
    contributions = [{
        "contributionId": str(row.get("contribution_id") or ""),
        "mode": str(row.get("mode") or ""),
        "amountLamports": int(row.get("amount_lamports") or 0),
        "amountSol": _amount_sol(int(row.get("amount_lamports") or 0)),
        "status": str(row.get("status") or ""),
        "transactionSignature": str(row.get("tx_signature") or ""),
        "confirmedAt": int(row.get("confirmed_at") or 0),
        "distributionIntentId": str(
            row.get("distribution_intent_id") or ""),
        "explorerUrl": _reward_explorer_url(
            network, signature=str(row.get("tx_signature") or "")),
    } for row in contribution_rows or []]
    config = _reward_config(env)
    return {
        "address": addr,
        "network": network,
        "uri": _solana_pay_uri(
            addr, 0, message="ForkMesh voluntary trickle-pool contribution"),
        "explorerUrl": _reward_explorer_url(network, address=addr),
        "balanceLamports": balance if balance is not None else 0,
        "balanceSol": _amount_sol(balance or 0),
        "balanceCheckedAt": balance_checked_at,
        "distributionIntervalMs": config["intervalMs"],
        "rewardAmountLamports": config["amountLamports"],
        "randomJitterMaxMs": config["jitterMs"],
        "custody": "external-local-signer",
        "privateKeyLocation": "instance-owner-device",
        "privateKeyStoredByWorker": False,
        "fundStates": {
            "userOwnedFunds": (
                "Remain in each contributor or recipient's self-custodial "
                "wallet until that wallet signs a transaction."
            ),
            "communityFundedPool": (
                "The public on-chain address and balance shown above."
            ),
            "pendingRewards": (
                "Ledger allocations only; funds remain in the public source "
                "wallet for at most 24 hours."
            ),
            "completedOnChainTransfers": (
                "Finalized signatures linked in the event history."
            ),
        },
        "contributionOptions": [
            {
                "mode": "trickle",
                "label": "Add to the randomized funding pool",
                "effect": (
                    "A direct wallet-to-pool transfer remains available for "
                    "configurable randomized eligible-node rewards."
                ),
            },
            {
                "mode": "instant_all_nodes",
                "label": "Distribute this contribution to all eligible nodes",
                "effect": (
                    "After the incoming transfer is finalized, the local pool "
                    "owner receives one reviewed unsigned all-node intent."
                ),
            },
        ],
        "contributionEndpoint": "/api/rewards/contributions",
        "programParticipation": {
            "type": "voluntary-community-support",
            "userWalletSignatureRequired": True,
            "forkMeshSignsContributorTransfer": False,
            "ownershipInterestGranted": False,
            "financialReturnPromised": False,
        },
        "transactions": transactions[:40],
        "contributions": contributions,
        "latestRound": round_public,
        "notice": (
            "Non-custodial: ForkMesh does not hold or control user funds and "
            "never receives a private key. The private pool signing key remains "
            "only on the instance owner's device. Voluntary contributions and "
            "community rewards are incentives, not investments, and do not "
            "guarantee a return."
        ),
        "latestIntent": ({
            "intentId": str(latest.get("intent_id") or ""),
            "status": str(latest.get("status") or ""),
            "createdAt": int(latest.get("created_at") or 0),
            "transactionSignature": str(
                latest.get("tx_signature") or ""),
            "completedAt": int(latest.get("completed_at") or 0),
        } if latest else None),
    }


async def _distribute_central_fund(env):
    # Cron first commits an auditable jittered round, then (after that public
    # time) freezes fresh eligibility and uses a finalized Solana blockhash to
    # select exactly one node. It only writes an unsigned plan.
    if not _is_main_relay(env):
        return False
    rec = await _central_fund_record(env)
    if not rec:
        return False
    now = int(Date.now())
    config = _reward_config(env)
    # Expired unsigned work cannot stall later rounds indefinitely.
    await d1_run(
        env,
        "UPDATE chain_intents SET status='expired' "
        "WHERE kind='community_reward_random' "
        "AND status IN ('pending_signature','submitted') "
        "AND expires_at>0 AND expires_at<=?",
        now,
    )
    await d1_run(
        env,
        "UPDATE reward_rounds SET status='expired' "
        "WHERE status='awaiting_signature' AND intent_id IN "
        "(SELECT intent_id FROM chain_intents WHERE status='expired')",
    )
    pending = await d1_first(
        env,
        "SELECT intent_id FROM chain_intents "
        "WHERE kind='community_reward_random' "
        "AND status IN ('pending_signature','submitted') "
        "AND (expires_at=0 OR expires_at>?) LIMIT 1",
        now,
    )
    if pending:
        return False
    initial_snapshot = None
    round_row = await d1_first(
        env,
        "SELECT * FROM reward_rounds WHERE status='scheduled' "
        "ORDER BY execute_after ASC LIMIT 1",
    )
    if not round_row:
        interval_start = now - (now % config["intervalMs"])
        round_id = (
            _reward_network(env) + ":" + str(interval_start)
        )
        existing = await d1_first(
            env, "SELECT * FROM reward_rounds WHERE round_id=?", round_id)
        if existing:
            return False
        schedule_entropy = await _reward_public_entropy(env)
        if not schedule_entropy:
            return False
        initial_snapshot = await _eligible_reward_snapshot(env, now)
        if not initial_snapshot.get("eligible"):
            return False
        offset = reward_policy.schedule_offset_ms(
            round_id=round_id,
            public_entropy=schedule_entropy,
            jitter_window_ms=min(
                config["jitterMs"], max(0, config["intervalMs"] - 1)),
        )
        execute_after = interval_start + offset
        await d1_run(
            env,
            "INSERT INTO reward_rounds "
            "(round_id,status,interval_start,scheduled_at,execute_after,"
            "schedule_entropy,snapshot_data) "
            "VALUES (?,'scheduled',?,?,?,?,?)",
            round_id, interval_start, now, execute_after,
            schedule_entropy,
            json.dumps(
                initial_snapshot, sort_keys=True, separators=(",", ":")),
        )
        await _audit_sensitive_action(
            env, "", "reward.round_schedule", "reward_round", round_id,
            "requested", {
                "executeAfter": execute_after,
                "eligibleCount": len(initial_snapshot.get("eligible") or []),
                "snapshotHash": initial_snapshot.get("snapshotHash", ""),
                "entropySource": (
                    _reward_network(env)
                    + "-finalized-solana-blockhash"
                ),
            })
        if execute_after > now:
            return True
        round_row = {
            "round_id": round_id,
            "execute_after": execute_after,
        }
    if int(round_row.get("execute_after") or 0) > now:
        return False

    # A zero-jitter round is eligible immediately. Reuse the snapshot that
    # authorized that round instead of rebuilding the full signed fleet view
    # twice in one cron phase.
    snapshot = initial_snapshot or await _eligible_reward_snapshot(env, now)
    selection_entropy = await _reward_public_entropy(env)
    selection = reward_policy.select_candidate(
        snapshot,
        round_id=str(round_row.get("round_id") or ""),
        public_entropy=selection_entropy,
        entropy_source=(
            _reward_network(env) + "-finalized-solana-blockhash"),
    )
    if not selection:
        return False
    from_addr = rec.get("address", "")
    if not SOLANA_RE.match(from_addr or ""):
        return False
    balance = await _reward_balance_lamports(env, from_addr)
    if balance is None:
        return False
    amount = config["amountLamports"]
    if int(balance) < amount + REWARD_POOL_FEE_RESERVE_LAMPORTS:
        return False
    selected = selection.get("candidate") or {}
    destination = str(selected.get("walletAddress") or "")
    if not SOLANA_RE.match(destination) or destination == from_addr:
        return False
    intent_id = _random_bytes(16).hex()
    plan = {
        "v": 2,
        "network": _reward_network(env),
        "sourceAddress": from_addr,
        "custody": {
            "forkMeshHoldsUserKeys": False,
            "fundsRemainInSourceWalletUntilSigned": True,
        },
        "signing": {
            "required": True,
            "performed": False,
            "method": "external-local-qt",
        },
        "transfers": [{
            "address": destination,
            "lamports": amount,
            "nodeId": str(selected.get("nodeId") or ""),
        }],
        "eligibility": snapshot,
        "selection": dict(selection, selectedNodeId=str(
            selected.get("nodeId") or "")),
        "policy": "randomized-eligible-mirror-v2",
        "generatedAt": now,
        "notice": (
            "Voluntary community incentive; not an investment and no "
            "financial return is promised."
        ),
    }
    await d1_run(
        env,
        "INSERT INTO chain_intents "
        "(intent_id, kind, source_address, signer_account, status, data, "
        "created_at, expires_at) VALUES (?,?,?,?,'pending_signature',?,?,?)",
        intent_id, "community_reward_random", from_addr,
        rec.get("signer_account", ""),
        json.dumps(plan, sort_keys=True, separators=(",", ":")),
        now, now + 4 * 60 * 60 * 1000,
    )
    await d1_run(
        env,
        "UPDATE reward_rounds SET status='awaiting_signature', "
        "selection_data=?, intent_id=? WHERE round_id=? "
        "AND status='scheduled'",
        json.dumps(selection, sort_keys=True, separators=(",", ":")),
        intent_id, round_row.get("round_id"),
    )
    await _audit_sensitive_action(
        env, "", "reward.intent_create", "chain_intent", intent_id,
        "requested", {
            "kind": "community_reward_random",
            "roundId": round_row.get("round_id"),
            "selectedNodeId": selected.get("nodeId", ""),
            "eligibleCount": selection.get("eligibleCount", 0),
            "snapshotHash": selection.get("snapshotHash", ""),
            "lamports": amount,
        })
    return True


async def _solana_contribution_details(env, signature, *, pool_address,
                                       reference_address, amount_lamports):
    """Validate one finalized, referenced System transfer into the pool."""
    if (not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{64,120}",
                         str(signature or ""))
            or not SOLANA_RE.match(pool_address or "")
            or not SOLANA_RE.match(reference_address or "")
            or int(amount_lamports or 0) <= 0):
        return False
    response = await _reward_solana_rpc(
        env,
        "getTransaction",
        [signature, {
            "encoding": "jsonParsed",
            "commitment": "finalized",
            "maxSupportedTransactionVersion": 0,
        }],
    )
    if not isinstance(response, dict):
        return None
    result = response.get("result")
    if result is None:
        return None
    if not isinstance(result, dict):
        return False
    meta = result.get("meta")
    transaction = result.get("transaction")
    if (not isinstance(meta, dict) or meta.get("err") is not None
            or not isinstance(transaction, dict)
            or signature not in (transaction.get("signatures") or [])):
        return False
    message = transaction.get("message")
    if not isinstance(message, dict):
        return False
    account_keys = []
    for key in message.get("accountKeys") or []:
        if isinstance(key, dict):
            account_keys.append(str(key.get("pubkey") or ""))
        else:
            account_keys.append(str(key or ""))
    # The per-intent Solana Pay reference prevents one public transaction from
    # being claimed under a different contribution choice.
    if reference_address not in account_keys:
        return False
    actual = []
    for instruction in message.get("instructions") or []:
        if not isinstance(instruction, dict):
            return False
        if str(instruction.get("program") or "").lower() != "system":
            return False
        parsed = instruction.get("parsed")
        if (not isinstance(parsed, dict)
                or parsed.get("type") != "transfer"):
            return False
        info = parsed.get("info")
        if not isinstance(info, dict):
            return False
        try:
            lamports = int(info.get("lamports") or 0)
        except (TypeError, ValueError):
            return False
        actual.append({
            "sourceAddress": str(info.get("source") or ""),
            "destinationAddress": str(info.get("destination") or ""),
            "lamports": lamports,
        })
    if len(actual) != 1:
        return False
    transfer = actual[0]
    if (not SOLANA_RE.match(transfer["sourceAddress"])
            or transfer["sourceAddress"] == pool_address
            or transfer["destinationAddress"] != pool_address
            or transfer["lamports"] != int(amount_lamports)):
        return False
    return transfer


async def _create_instant_distribution_intent(env, contribution):
    """Turn one finalized contribution into a size-safe unsigned intent batch."""
    contribution = contribution or {}
    if contribution.get("distribution_intent_id"):
        rows = await d1_all(
            env,
            "SELECT intent_id FROM reward_contribution_intents "
            "WHERE contribution_id=? ORDER BY chunk_index ASC",
            contribution.get("contribution_id"),
        )
        return [
            str(row.get("intent_id") or "")
            for row in rows or []
            if row.get("intent_id")
        ]
    rec = await _central_fund_record(env)
    if not rec or not rec.get("signer_account"):
        return []
    now = int(Date.now())
    snapshot = await _eligible_reward_snapshot(env, now)
    eligible = list(snapshot.get("eligible") or [])
    if not eligible:
        return []
    total = int(contribution.get("amount_lamports") or 0)
    chunk_count = (
        len(eligible) + REWARD_TRANSFERS_PER_INTENT - 1
    ) // REWARD_TRANSFERS_PER_INTENT
    fee_reserve = REWARD_POOL_FEE_RESERVE_LAMPORTS * chunk_count
    distributable = total - fee_reserve
    per_node = distributable // len(eligible) if eligible else 0
    if per_node <= 0:
        return []
    balance = await _reward_balance_lamports(env, rec.get("address"))
    required = per_node * len(eligible) + fee_reserve
    if balance is None or int(balance) < required:
        return []
    transfers = [{
        "address": item["walletAddress"],
        "lamports": per_node,
        "nodeId": item["nodeId"],
    } for item in eligible]
    contribution_id = str(contribution.get("contribution_id") or "")
    eligibility_summary = {
        "snapshotHash": snapshot.get("snapshotHash", ""),
        "eligibleCount": len(eligible),
        "rejected": snapshot.get("rejected", []),
        "policy": snapshot.get("policy", {}),
        "limitations": snapshot.get("limitations", []),
        "source": snapshot.get("source", ""),
    }
    chain_rows = []
    link_rows = []
    intent_ids = []
    for chunk_index in range(chunk_count):
        intent_id = _random_bytes(16).hex()
        intent_ids.append(intent_id)
        start = chunk_index * REWARD_TRANSFERS_PER_INTENT
        chunk = transfers[start:start + REWARD_TRANSFERS_PER_INTENT]
        plan = {
            "v": 2,
            "network": rec.get("network", "mainnet-beta"),
            "sourceAddress": rec.get("address", ""),
            "custody": {
                "forkMeshHoldsUserKeys": False,
                "fundsRemainInSourceWalletUntilSigned": True,
            },
            "signing": {
                "required": True,
                "performed": False,
                "method": "external-local-qt",
            },
            "transfers": chunk,
            "eligibility": eligibility_summary,
            "policy": "instant-all-eligible-mirrors-v1",
            "contributionId": contribution_id,
            "contributionLamports": total,
            "distributedLamports": per_node * len(eligible),
            "retainedForNetworkFeesAndRemainder": (
                total - per_node * len(eligible)
            ),
            "batch": {
                "chunkIndex": chunk_index,
                "chunkCount": chunk_count,
                "maximumTransfersPerTransaction": (
                    REWARD_TRANSFERS_PER_INTENT
                ),
            },
            "generatedAt": now,
            "notice": (
                "Voluntary community incentive; not an investment and no "
                "financial return is promised."
            ),
        }
        chain_rows.append((
            intent_id,
            "community_reward_instant_distribution",
            rec.get("address", ""),
            rec.get("signer_account", ""),
            json.dumps(plan, sort_keys=True, separators=(",", ":")),
            now,
            now + 4 * 60 * 60 * 1000,
        ))
        link_rows.append((
            contribution_id, intent_id, chunk_index, chunk_count,
        ))
    # D1 counts every statement in a batch against the invocation query cap.
    # At the supported 100-node eligibility ceiling, thirteen intent chunks
    # still fit under the 100-bind limit when grouped this way (91 + 52 binds),
    # reducing what used to be 27 statements to three.
    statements = [(
        "INSERT INTO chain_intents "
        "(intent_id,kind,source_address,signer_account,status,data,"
        "created_at,expires_at) VALUES "
        + ",".join("(?,?,?,?,'pending_signature',?,?,?)"
                   for _row in chain_rows),
        tuple(value for row in chain_rows for value in row),
    ), (
        "INSERT INTO reward_contribution_intents "
        "(contribution_id,intent_id,chunk_index,chunk_count,status) VALUES "
        + ",".join("(?,?,?,?,'pending_signature')" for _row in link_rows),
        tuple(value for row in link_rows for value in row),
    ), (
        "UPDATE reward_contributions "
        "SET status='awaiting_distribution', distribution_intent_id=? "
        "WHERE contribution_id=? AND distribution_intent_id=''",
        (intent_ids[0], contribution_id),
    )]
    await _contribution_run_batch(env, statements)
    await _audit_sensitive_action(
        env, "", "reward.instant_intent_create",
        "reward_contribution", contribution_id,
        "requested", {
            "contributionId": contribution_id,
            "eligibleCount": len(eligible),
            "snapshotHash": snapshot.get("snapshotHash", ""),
            "distributedLamports": per_node * len(eligible),
            "intentCount": chunk_count,
            "maximumTransfersPerIntent": REWARD_TRANSFERS_PER_INTENT,
        })
    return intent_ids


async def _finalize_reward_contribution(env, row, signature, details):
    now = int(Date.now())
    mode = str(row.get("mode") or "")
    status = (
        "confirmed_waiting_for_nodes"
        if mode == "instant_all_nodes"
        else "confirmed_in_pool"
    )
    await d1_run(
        env,
        "UPDATE reward_contributions SET status=?, tx_signature=?, "
        "source_address=?, confirmed_at=? WHERE contribution_id=? "
        "AND status IN ('prepared','awaiting_finality')",
        status, signature, details.get("sourceAddress", ""), now,
        row.get("contribution_id"),
    )
    row = dict(row)
    row.update({
        "status": status,
        "tx_signature": signature,
        "source_address": details.get("sourceAddress", ""),
        "confirmed_at": now,
    })
    if mode == "instant_all_nodes":
        intent_ids = await _create_instant_distribution_intent(env, row)
        if intent_ids:
            row["status"] = "awaiting_distribution"
            row["distribution_intent_id"] = intent_ids[0]
            row["distribution_intent_ids"] = intent_ids
    await _audit_sensitive_action(
        env, "", "reward.contribution_confirm", "reward_contribution",
        str(row.get("contribution_id") or ""), "success", {
            "mode": mode,
            "lamports": int(row.get("amount_lamports") or 0),
            "transactionSignature": signature,
        })
    return row


async def _process_waiting_reward_contributions(env):
    rows = await d1_all(
        env,
        "SELECT * FROM reward_contributions "
        "WHERE mode='instant_all_nodes' "
        "AND status='confirmed_waiting_for_nodes' "
        "AND distribution_intent_id='' "
        "ORDER BY confirmed_at ASC LIMIT 1",
    )
    created = 0
    for row in rows or []:
        if await _create_instant_distribution_intent(env, row):
            created += 1
    return created


async def verify_submitted_reward_contributions(env):
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE reward_contributions SET status='expired' "
        "WHERE status='prepared' AND expires_at<=?",
        now,
    )
    rows = await d1_all(
        env,
        "SELECT * FROM reward_contributions "
        "WHERE status='awaiting_finality' "
        "ORDER BY created_at ASC LIMIT 1",
    )
    rec = await _central_fund_record(env)
    if not rec:
        return
    for row in rows or []:
        details = await _solana_contribution_details(
            env, row.get("tx_signature"),
            pool_address=rec.get("address", ""),
            reference_address=row.get("reference_address", ""),
            amount_lamports=int(row.get("amount_lamports") or 0),
        )
        if isinstance(details, dict):
            await _finalize_reward_contribution(
                env, row, row.get("tx_signature"), details)
        elif details is False:
            await d1_run(
                env,
                "UPDATE reward_contributions SET status='rejected' "
                "WHERE contribution_id=? AND status='awaiting_finality'",
                row.get("contribution_id"),
            )
        # One contribution finality/distribution action per invocation keeps
        # the signed eligibility build, Solana check, audit, and intent write
        # within the phase's hard subrequest budget.
        return
    await _process_waiting_reward_contributions(env)


async def reward_contributions_handler(env, request):
    """Prepare/confirm voluntary direct-to-pool Solana Pay transfers."""
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    rec = await _central_fund_record(env)
    if not rec:
        return json_response(
            {"error": "community_pool_not_configured"}, status=503)
    action = clean_string(data.get("action", "prepare"), 20).lower()
    now = int(Date.now())
    if action == "prepare":
        mode = clean_string(data.get("mode", ""), 32).lower()
        try:
            amount = int(data.get("amountLamports") or 0)
        except (TypeError, ValueError):
            amount = 0
        if mode not in ("trickle", "instant_all_nodes"):
            return json_response(
                {"error": "invalid_contribution_mode"}, status=400)
        if not (
            REWARD_CONTRIBUTION_MIN_LAMPORTS
            <= amount
            <= REWARD_CONTRIBUTION_MAX_LAMPORTS
        ):
            return json_response({
                "error": "invalid_contribution_amount",
                "minimumLamports": REWARD_CONTRIBUTION_MIN_LAMPORTS,
                "maximumLamports": REWARD_CONTRIBUTION_MAX_LAMPORTS,
            }, status=400)
        recent = await d1_first(
            env,
            "SELECT COUNT(*) AS c FROM reward_contributions "
            "WHERE created_at>=?",
            now - REWARD_CONTRIBUTION_EXPIRES_MS,
        )
        if int((recent or {}).get("c") or 0) >= 1000:
            return json_response(
                {"error": "contribution_queue_busy"}, status=429)
        contribution_id = _random_bytes(16).hex()
        reference = _base58_encode(_random_bytes(32))
        expires_at = now + REWARD_CONTRIBUTION_EXPIRES_MS
        await d1_run(
            env,
            "INSERT INTO reward_contributions "
            "(contribution_id,mode,amount_lamports,reference_address,"
            "status,created_at,expires_at) "
            "VALUES (?,?,?,?,'prepared',?,?)",
            contribution_id, mode, amount, reference, now, expires_at,
        )
        return json_response({
            "ok": True,
            "contributionId": contribution_id,
            "mode": mode,
            "amountLamports": amount,
            "amountSol": _amount_sol(amount),
            "poolAddress": rec.get("address", ""),
            "network": rec.get("network", "mainnet-beta"),
            "referenceAddress": reference,
            "expiresAt": expires_at,
            "uri": _solana_pay_uri(
                rec.get("address", ""), amount, reference=reference,
                message=(
                    "ForkMesh instant eligible-node contribution"
                    if mode == "instant_all_nodes"
                    else "ForkMesh randomized reward-pool contribution"
                ),
            ),
            "custody": "direct-self-custodial-wallet-to-public-pool",
            "programParticipation": "voluntary-community-support",
            "userWalletSignatureRequired": True,
            "forkMeshSignsContributorTransfer": False,
            "ownershipInterestGranted": False,
            "financialReturnPromised": False,
            "notice": (
                "ForkMesh never receives your wallet key. Your wallet signs "
                "a direct public transfer; this is a voluntary community "
                "incentive, not an investment or guaranteed return."
            ),
        }, status=201, cache_control="no-store")
    if action != "confirm":
        return json_response({"error": "invalid_action"}, status=400)
    contribution_id = security_control.normalize_incident_id(
        data.get("contributionId"))
    signature = clean_string(
        data.get("transactionSignature", ""), 120).strip()
    if (not contribution_id
            or not re.fullmatch(
                r"[1-9A-HJ-NP-Za-km-z]{64,120}", signature)):
        return json_response(
            {"error": "invalid_contribution_confirmation"}, status=400)
    row = await d1_first(
        env,
        "SELECT * FROM reward_contributions WHERE contribution_id=?",
        contribution_id,
    )
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if row.get("status") in (
            "confirmed_in_pool", "confirmed_waiting_for_nodes",
            "awaiting_distribution", "distributed"):
        if row.get("tx_signature") != signature:
            return json_response(
                {"error": "contribution_already_confirmed"}, status=409)
        return json_response({
            "ok": True,
            "status": row.get("status"),
            "distributionIntentId": str(
                row.get("distribution_intent_id") or ""),
            "custody": "public-community-pool",
            "fundsLocation": "public-community-pool",
            "notice": (
                "The wallet-signed contribution is already confirmed in the "
                "public community pool. ForkMesh retained no contributor key; "
                "any distribution still requires the external local signer "
                "and final on-chain verification."
            ),
        }, cache_control="no-store")
    if int(row.get("expires_at") or 0) <= now:
        await d1_run(
            env,
            "UPDATE reward_contributions SET status='expired' "
            "WHERE contribution_id=? AND status='prepared'",
            contribution_id,
        )
        return json_response({"error": "contribution_expired"}, status=410)
    replay = await d1_first(
        env,
        "SELECT contribution_id FROM reward_contributions "
        "WHERE tx_signature=? AND contribution_id<>?",
        signature, contribution_id,
    )
    if replay:
        return json_response({"error": "transaction_replay"}, status=409)
    details = await _solana_contribution_details(
        env, signature,
        pool_address=rec.get("address", ""),
        reference_address=row.get("reference_address", ""),
        amount_lamports=int(row.get("amount_lamports") or 0),
    )
    if details is False:
        return json_response(
            {"error": "contribution_transaction_mismatch"}, status=409)
    if details is None:
        await d1_run(
            env,
            "UPDATE reward_contributions "
            "SET status='awaiting_finality', tx_signature=? "
            "WHERE contribution_id=? AND status='prepared'",
            signature, contribution_id,
        )
        return json_response({
            "ok": True,
            "status": "awaiting_finality",
            "custody": "direct-self-custodial-wallet-to-public-pool",
            "fundsLocation": "awaiting-finalized-public-transfer",
            "notice": (
                "Non-custodial: ForkMesh retained no wallet key. No "
                "distribution occurs until the direct public transfer's "
                "finality is verified."
            ),
        }, status=202, cache_control="no-store")
    completed = await _finalize_reward_contribution(
        env, row, signature, details)
    return json_response({
        "ok": True,
        "status": completed.get("status"),
        "distributionIntentId": str(
            completed.get("distribution_intent_id") or ""),
        "distributionIntentIds": list(
            completed.get("distribution_intent_ids") or []),
        "transactionSignature": signature,
        "explorerUrl": _reward_explorer_url(
            rec.get("network", "mainnet-beta"), signature=signature),
        "custody": "public-community-pool",
        "fundsLocation": "public-community-pool",
        "notice": (
            "The direct wallet-signed contribution is finalized in the public "
            "community pool. ForkMesh retained no contributor key. A prepared "
            "distribution is not complete until its separate finalized "
            "on-chain transfer is verified."
        ),
    }, cache_control="no-store")


WORLD_ELEMENT_STORE_BODY_MAX_BYTES = 8 * 1024
WORLD_ELEMENT_PURCHASE_RE = re.compile(r"[0-9a-f]{32}")


def _world_element_library(rec, now=0):
    return world_element_store.clean_owned(
        (rec or {}).get("world_elements"), now)


async def _create_element_store_split_intent(env, purchase):
    """Write the unsigned intent paying one purchase's mirror-node half.

    The treasury half needs no transfer: it is already in the pool address the
    buyer's wallet paid. Only the mirror half moves, and only after the
    instance owner's local signer reviews and signs this plan.
    """
    purchase = purchase or {}
    if purchase.get("distribution_intent_id"):
        return [str(purchase.get("distribution_intent_id"))]
    rec = await _central_fund_record(env)
    if not rec or not rec.get("signer_account"):
        return []
    now = int(Date.now())
    snapshot = await _eligible_reward_snapshot(env, now)
    eligible = list(snapshot.get("eligible") or [])
    if not eligible:
        return []
    mirror_total = int(purchase.get("mirror_lamports") or 0)
    chunk_count = (
        len(eligible) + REWARD_TRANSFERS_PER_INTENT - 1
    ) // REWARD_TRANSFERS_PER_INTENT
    fee_reserve = REWARD_POOL_FEE_RESERVE_LAMPORTS * chunk_count
    per_node = (mirror_total - fee_reserve) // len(eligible)
    if per_node <= 0:
        return []
    balance = await _reward_balance_lamports(env, rec.get("address"))
    if balance is None or int(balance) < per_node * len(eligible) + fee_reserve:
        return []
    transfers = [{
        "address": item["walletAddress"],
        "lamports": per_node,
        "nodeId": item["nodeId"],
    } for item in eligible]
    purchase_id = str(purchase.get("purchase_id") or "")
    statements = []
    intent_ids = []
    for chunk_index in range(chunk_count):
        intent_id = _random_bytes(16).hex()
        intent_ids.append(intent_id)
        start = chunk_index * REWARD_TRANSFERS_PER_INTENT
        plan = {
            "v": 2,
            "network": rec.get("network", "mainnet-beta"),
            "sourceAddress": rec.get("address", ""),
            "custody": {
                "forkMeshHoldsUserKeys": False,
                "fundsRemainInSourceWalletUntilSigned": True,
            },
            "signing": {
                "required": True,
                "performed": False,
                "method": "external-local-qt",
            },
            "transfers": transfers[start:start + REWARD_TRANSFERS_PER_INTENT],
            "eligibility": {
                "snapshotHash": snapshot.get("snapshotHash", ""),
                "eligibleCount": len(eligible),
                "rejected": snapshot.get("rejected", []),
                "policy": snapshot.get("policy", {}),
                "limitations": snapshot.get("limitations", []),
                "source": snapshot.get("source", ""),
            },
            "policy": "element-store-half-to-eligible-mirrors-v1",
            "purchaseId": purchase_id,
            "elementId": str(purchase.get("element_id") or ""),
            "purchaseLamports": int(purchase.get("amount_lamports") or 0),
            "treasuryRetainedLamports": int(
                purchase.get("treasury_lamports") or 0),
            "mirrorShareLamports": mirror_total,
            "distributedLamports": per_node * len(eligible),
            "retainedForNetworkFeesAndRemainder": (
                mirror_total - per_node * len(eligible)
            ),
            "split": world_element_store.split_policy_public(),
            "batch": {
                "chunkIndex": chunk_index,
                "chunkCount": chunk_count,
                "maximumTransfersPerTransaction": REWARD_TRANSFERS_PER_INTENT,
            },
            "generatedAt": now,
            "notice": (
                "Half of a voluntary world-element purchase, shared between "
                "online eligible mirror nodes. Not an investment and no "
                "financial return is promised."
            ),
        }
        statements.append((
            "INSERT INTO chain_intents "
            "(intent_id,kind,source_address,signer_account,status,data,"
            "created_at,expires_at) "
            "VALUES (?,?,?,?,'pending_signature',?,?,?)",
            (
                intent_id,
                "world_element_store_mirror_split",
                rec.get("address", ""),
                rec.get("signer_account", ""),
                json.dumps(plan, sort_keys=True, separators=(",", ":")),
                now,
                now + 4 * 60 * 60 * 1000,
            ),
        ))
    statements.append((
        "UPDATE world_element_purchases "
        "SET status='awaiting_distribution', distribution_intent_id=? "
        "WHERE purchase_id=? AND distribution_intent_id=''",
        (intent_ids[0], purchase_id),
    ))
    await _contribution_run_batch(env, statements)
    await _audit_sensitive_action(
        env, "", "world.element_store_split_intent",
        "world_element_purchase", purchase_id, "requested", {
            "elementId": str(purchase.get("element_id") or ""),
            "eligibleCount": len(eligible),
            "snapshotHash": snapshot.get("snapshotHash", ""),
            "mirrorShareLamports": mirror_total,
            "distributedLamports": per_node * len(eligible),
            "intentCount": chunk_count,
        })
    return intent_ids


async def _grant_purchased_element(env, account_bi, rec, row, signature,
                                   details):
    """Record the finalized purchase and add the element to the account."""
    now = int(Date.now())
    element_id = str(row.get("element_id") or "")
    item = world_element_store.element(element_id)
    await d1_run(
        env,
        "UPDATE world_element_purchases SET status='confirmed', "
        "tx_signature=?, source_address=?, confirmed_at=? "
        "WHERE purchase_id=? AND status IN ('prepared','awaiting_finality')",
        signature, details.get("sourceAddress", ""), now,
        row.get("purchase_id"),
    )
    owned = _world_element_library(rec, now)
    previous = owned.get(element_id) or {}
    owned[element_id] = {
        "params": world_element_store.clean_params(
            item, previous.get("params")),
        "placement": world_element_store.clean_placement(
            previous.get("placement")),
        "enabled": True,
        "purchaseId": str(row.get("purchase_id") or ""),
        "transactionSignature": signature,
        "purchasedAt": now,
        "updatedAt": now,
    }
    rec["world_elements"] = owned
    await _save_account(env, account_bi, rec)
    row = dict(row)
    row.update({
        "status": "confirmed",
        "tx_signature": signature,
        "source_address": details.get("sourceAddress", ""),
        "confirmed_at": now,
    })
    # Only the direct path owes an unsigned mirror-distribution intent. A
    # custodial deposit pays the mirror half in its own sweep transaction, so
    # creating an intent here would pay that half a second time.
    if str(row.get("method") or "direct") != "deposit":
        intent_ids = await _create_element_store_split_intent(env, row)
        if intent_ids:
            row["status"] = "awaiting_distribution"
            row["distribution_intent_id"] = intent_ids[0]
    await _audit_sensitive_action(
        env, "", "world.element_purchase_confirm", "world_element_purchase",
        str(row.get("purchase_id") or ""), "success", {
            "elementId": element_id,
            "lamports": int(row.get("amount_lamports") or 0),
            "treasuryLamports": int(row.get("treasury_lamports") or 0),
            "mirrorLamports": int(row.get("mirror_lamports") or 0),
            "transactionSignature": signature,
        })
    return row, owned


def _deposit_treasury_address(env):
    """Public treasury address that receives the custodial deposit's half."""
    address = clean_string(
        getattr(env, "TREASURY_SOLANA_ADDRESS", "")
        or getattr(env, "COMMUNITY_REWARD_POOL_ADDRESS", ""),
        64,
    ).strip()
    return address if SOLANA_RE.match(address) else ""


def _custodial_deposits_enabled(env):
    """Whether the Worker may mint and sweep temporary deposit addresses.

    Off unless a treasury is configured to sweep into, and killable outright
    with CUSTODIAL_DEPOSITS=0. When this is off the store still sells elements
    through the direct wallet-to-pool path, which puts no key on the Worker.
    """
    flag = str(getattr(env, "CUSTODIAL_DEPOSITS", "") or "").strip().lower()
    if flag in ("0", "false", "off", "no"):
        return False
    return bool(_deposit_treasury_address(env))


async def _online_mirror_payout_addresses(env, exclude=""):
    """Payout addresses of online, functioning, eligible mirror nodes."""
    snapshot = await _eligible_reward_snapshot(env, int(Date.now()))
    seen = set()
    addresses = []
    for item in snapshot.get("eligible") or []:
        address = str(item.get("walletAddress") or "").strip()
        if (not SOLANA_RE.match(address) or address in seen
                or address == exclude):
            continue
        seen.add(address)
        addresses.append(address)
        if len(addresses) >= MAX_SWEEP_PAYEES:
            break
    return addresses


def _deposit_sweep_plan(transferable, treasury, payees):
    """Split a swept deposit 50/50 between treasury and online mirrors.

    Integer division keeps the remainder with the treasury, so the transfers
    can never total more than what was actually received.
    """
    treasury_lamports = int(transferable)
    transfers = []
    if payees:
        half = (int(transferable) * DEPOSIT_TREASURY_SPLIT_NUMERATOR
                // DEPOSIT_TREASURY_SPLIT_DENOMINATOR)
        per_node = (int(transferable) - half) // len(payees)
        if per_node > 0:
            transfers = [(payee, per_node) for payee in payees]
            treasury_lamports = int(transferable) - per_node * len(payees)
    transfers.insert(0, (treasury, treasury_lamports))
    merged = []
    by_addr = {}
    for addr, lamports in transfers:
        if addr in by_addr:
            by_addr[addr] += int(lamports)
        else:
            by_addr[addr] = int(lamports)
            merged.append(addr)
    return [(addr, by_addr[addr]) for addr in merged if by_addr[addr] > 0]


async def _sweep_element_deposit(env, row, balance=None):
    """Send a confirmed deposit on to the treasury and online mirror nodes.

    Idempotent: once a signature is stored the deposit is never sent again.
    The signing seed is destroyed as soon as the sweep confirms, so a swept
    purchase leaves no key on the Worker.
    """
    purchase_id = str(row.get("purchase_id") or "")
    if row.get("sweep_signature"):
        return str(row.get("sweep_signature"))
    # Two concurrent pollers can both reach here, because D1 gives no atomic
    # compare-and-swap to claim the sweep with. The chain settles it instead:
    # same signer, transfers and blockhash produce a byte-identical
    # transaction, which the cluster deduplicates by signature; if the
    # blockhash has rolled, the second attempt spends an already-emptied
    # account and is rejected for insufficient funds. Either way the deposit
    # cannot be sent twice.
    from_addr = str(row.get("deposit_address") or "")
    stored = str(row.get("deposit_secret") or "")
    if not SOLANA_RE.match(from_addr) or not stored:
        return ""
    treasury = _deposit_treasury_address(env)
    if not treasury:
        await _record_sweep_error(env, purchase_id, "treasury_not_configured")
        return ""
    secret = await decrypt_row(env, stored)
    seed = (secret or {}).get("seed") if isinstance(secret, dict) else ""
    if not seed:
        await _record_sweep_error(env, purchase_id, "deposit_key_unreadable")
        return ""
    if balance is None:
        balance = await _solana_balance_lamports(env, from_addr)
    if balance is None:
        await _record_sweep_error(env, purchase_id, "balance_unavailable")
        return ""
    transferable = int(balance) - SOLANA_SWEEP_FEE_RESERVE_LAMPORTS
    if transferable <= 0:
        await _record_sweep_error(env, purchase_id, "balance_too_low_for_fee")
        return ""
    payees = await _online_mirror_payout_addresses(env, exclude=from_addr)
    transfers = _deposit_sweep_plan(transferable, treasury, payees)
    signature = await _solana_send_transfers(env, from_addr, seed, transfers)
    if not signature:
        await _record_sweep_error(env, purchase_id, "send_transaction_failed")
        return ""
    now = int(Date.now())
    # Clearing deposit_secret is the point of the whole flow: the Worker holds
    # a key only for the window between minting the address and sweeping it.
    await d1_run(
        env,
        "UPDATE world_element_purchases SET sweep_signature=?, sweep_at=?, "
        "sweep_lamports=?, sweep_error='', deposit_secret='' WHERE purchase_id=? "
        "AND sweep_signature=''",
        signature, now, transferable, purchase_id,
    )
    await _audit_sensitive_action(
        env, "", "world.element_deposit_sweep", "world_element_purchase",
        purchase_id, "success", {
            "sweepLamports": transferable,
            "treasuryLamports": next(
                (l for a, l in transfers if a == treasury), 0),
            "mirrorPayees": len(payees),
            "transactionSignature": signature,
        })
    return signature


async def _record_sweep_error(env, purchase_id, message):
    await d1_run(
        env,
        "UPDATE world_element_purchases SET sweep_error=? WHERE purchase_id=?",
        message, purchase_id,
    )


async def sweep_pending_element_deposits(env):
    """Cron: retry sweeps whose first attempt could not complete."""
    if not _custodial_deposits_enabled(env):
        return 0
    rows = await d1_all(
        env,
        "SELECT * FROM world_element_purchases WHERE method='deposit' "
        "AND deposit_secret<>'' AND sweep_signature='' "
        "AND status IN ('confirmed','awaiting_distribution') "
        "ORDER BY confirmed_at ASC LIMIT 1",
    )
    swept = 0
    for row in rows or []:
        if await _sweep_element_deposit(env, row):
            swept += 1
    return swept


async def _element_deposit_status(env, request, data, account_bi, rec, now):
    """Poll a temporary deposit address; grant and sweep once it is funded."""
    purchase_id = clean_string(data.get("purchaseId", ""), 32).lower()
    if not WORLD_ELEMENT_PURCHASE_RE.fullmatch(purchase_id):
        return json_response({"error": "invalid_purchase"}, status=400)
    row = await d1_first(
        env,
        "SELECT * FROM world_element_purchases WHERE purchase_id=?",
        purchase_id,
    )
    if (not row or str(row.get("account_bi") or "") != account_bi
            or str(row.get("method") or "") != "deposit"):
        return json_response({"error": "not_found"}, status=404)
    element_id = str(row.get("element_id") or "")
    required = int(row.get("amount_lamports") or 0)
    address = str(row.get("deposit_address") or "")
    status = str(row.get("status") or "")
    if status in ("confirmed", "awaiting_distribution"):
        return json_response({
            "ok": True,
            "status": status,
            "elementId": element_id,
            "depositAddress": address,
            "sweepSignature": str(row.get("sweep_signature") or ""),
            "owned": _world_element_library(rec, now),
        }, cache_control="no-store")
    if int(row.get("expires_at") or 0) <= now and status == "prepared":
        # An unfunded deposit expires, but the address is left readable so a
        # late payment can still be reconciled by the operator.
        await d1_run(
            env,
            "UPDATE world_element_purchases SET status='expired' "
            "WHERE purchase_id=? AND status='prepared'",
            purchase_id,
        )
        return json_response({"error": "purchase_expired"}, status=410)
    balance = await _solana_balance_lamports(env, address)
    if balance is None:
        return json_response({
            "ok": True, "status": "balance_unavailable",
            "depositAddress": address, "requiredLamports": required,
        }, status=202, cache_control="no-store")
    if int(balance) < required:
        return json_response({
            "ok": True,
            "status": "awaiting_payment",
            "depositAddress": address,
            "requiredLamports": required,
            "receivedLamports": int(balance),
            "receivedSol": _amount_sol(int(balance)),
        }, status=202, cache_control="no-store")
    row, owned = await _grant_purchased_element(
        env, account_bi, rec, row, "", {"sourceAddress": ""})
    signature = await _sweep_element_deposit(env, row, balance=balance)
    return json_response({
        "ok": True,
        "status": row.get("status"),
        "elementId": element_id,
        "depositAddress": address,
        "receivedLamports": int(balance),
        "sweepSignature": signature,
        "sweepPending": not signature,
        "owned": owned,
        "notice": world_element_store.custody_notice("deposit"),
    }, cache_control="no-store")


def _chain_intent_public(row, include_plan=False):
    row = row or {}
    result = {
        "intentId": str(row.get("intent_id") or ""),
        "kind": str(row.get("kind") or ""),
        "sourceAddress": str(row.get("source_address") or ""),
        "status": str(row.get("status") or ""),
        "createdAt": int(row.get("created_at") or 0),
        "expiresAt": int(row.get("expires_at") or 0),
        "transactionSignature": str(row.get("tx_signature") or ""),
        "completedAt": int(row.get("completed_at") or 0),
        "custody": "external-local-signer",
    }
    if include_plan:
        try:
            plan = json.loads(str(row.get("data") or "{}"))
        except Exception:
            plan = {}
        result["plan"] = plan if isinstance(plan, dict) else {}
    return result


_solana_transaction_matches_plan = _route_handlers.export("_solana_transaction_matches_plan")


async def _mark_chain_intent_failed(env, row, status):
    """Propagate a rejected/expired chunk to its public contribution batch."""
    if (row or {}).get("kind") == "microjob_payout":
        # Nothing was transferred, so the work is still owed: put the claims
        # back in the approved pool for the next batch rather than stranding
        # them in "queued" behind a plan that will never be signed.
        await d1_run(
            env,
            "UPDATE microjob_claims SET status='approved',intent_id='',"
            "updated_at=? WHERE intent_id=? AND status='queued'",
            int(Date.now()), row.get("intent_id"),
        )
        return
    if (row or {}).get("kind") != "community_reward_instant_distribution":
        return
    normalized = status if status in ("rejected", "expired") else "rejected"
    await d1_run(
        env,
        "UPDATE reward_contribution_intents SET status=? "
        "WHERE intent_id=?",
        normalized, row.get("intent_id"),
    )
    link = await d1_first(
        env,
        "SELECT contribution_id FROM reward_contribution_intents "
        "WHERE intent_id=?",
        row.get("intent_id"),
    )
    if link:
        await d1_run(
            env,
            "UPDATE reward_contributions SET status='distribution_failed' "
            "WHERE contribution_id=? "
            "AND status='awaiting_distribution'",
            link.get("contribution_id"),
        )


async def _complete_chain_intent(env, row, signature):
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE chain_intents SET status='completed', tx_signature=?, "
        "completed_at=? WHERE intent_id=? "
        "AND status IN ('pending_signature','submitted')",
        signature, now, row.get("intent_id"),
    )
    try:
        plan = json.loads(str(row.get("data") or "{}"))
    except Exception:
        plan = {}
    if row.get("kind") in (
            "community_reward_random",
            "community_reward_instant_distribution"):
        for transfer in plan.get("transfers") or []:
            address = str(transfer.get("address") or "")
            try:
                lamports = int(transfer.get("lamports") or 0)
            except (TypeError, ValueError):
                lamports = 0
            if SOLANA_RE.match(address) and lamports > 0:
                await _record_funds_received(
                    env, "mainnode", address, "", lamports)
        if row.get("kind") == "community_reward_random":
            await d1_run(
                env,
                "UPDATE reward_rounds SET status='completed', completed_at=? "
                "WHERE intent_id=? AND status='awaiting_signature'",
                now, row.get("intent_id"),
            )
        else:
            await d1_run(
                env,
                "UPDATE reward_contribution_intents SET status='completed' "
                "WHERE intent_id=?",
                row.get("intent_id"),
            )
            link = await d1_first(
                env,
                "SELECT contribution_id FROM reward_contribution_intents "
                "WHERE intent_id=?",
                row.get("intent_id"),
            )
            if link:
                remaining = await d1_first(
                    env,
                    "SELECT COUNT(*) AS c FROM reward_contribution_intents "
                    "WHERE contribution_id=? AND status<>'completed'",
                    link.get("contribution_id"),
                )
                if int((remaining or {}).get("c") or 0) == 0:
                    await d1_run(
                        env,
                        "UPDATE reward_contributions "
                        "SET status='distributed' "
                        "WHERE contribution_id=? "
                        "AND status='awaiting_distribution'",
                        link.get("contribution_id"),
                    )
    if row.get("kind") == "pending_reward":
        await d1_run(
            env,
            "UPDATE pending_rewards SET status='completed', tx_signature=? "
            "WHERE intent_id=? AND status='ready'",
            signature, row.get("intent_id"),
        )
    if row.get("kind") == "microjob_payout":
        # A finalized transfer matched the exact public plan, so every claim
        # batched into it is paid. The public signature is kept on the claim so
        # the contributor can verify their own payout on-chain.
        await d1_run(
            env,
            "UPDATE microjob_claims SET status='paid', tx_signature=?, "
            "updated_at=? WHERE intent_id=? AND status='queued'",
            signature, now, row.get("intent_id"),
        )
        for transfer in plan.get("transfers") or []:
            address = str(transfer.get("address") or "")
            try:
                lamports = int(transfer.get("lamports") or 0)
            except (TypeError, ValueError):
                lamports = 0
            if SOLANA_RE.match(address) and lamports > 0:
                await _record_funds_received(
                    env, "mainnode", address, "", lamports)


async def reward_signing_jobs_handler(env, request):
    """Local-signer queue: public transfer plans in, signature receipt out."""
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        signer = clean_string(
            params.get("signer", [""])[0], MAX_NODE_NAME).strip().lower()
        ts = clean_string(params.get("ts", [""])[0], 20)
        sig = clean_string(params.get("sig", [""])[0], 200)
        canonical = (
            "forkmesh-reward-jobs-v1\n" + signer + "\n" + ts
        ).encode()
        configured = (
            getattr(env, "REWARD_SIGNER_ACCOUNT", "")
            or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
            or ""
        ).strip().lower()
        if (not configured or signer != configured or not _ts_ok(ts)
                or not await _verify_owner_signature(
                    env, signer, sig, canonical)):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env,
            "SELECT * FROM chain_intents WHERE signer_account=? "
            "AND status IN ('pending_signature','submitted') "
            "ORDER BY created_at ASC LIMIT 50",
            signer,
        )
        return json_response({
            "ok": True,
            "jobs": [_chain_intent_public(row, include_plan=True)
                     for row in rows or []],
            "custody": "external-local-signer",
            "notice": (
                "Sign only after the local client validates source, network, "
                "amount limits and every System Program transfer."
            ),
        }, cache_control="no-store")

    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    signer = clean_string(
        data.get("signer", ""), MAX_NODE_NAME).strip().lower()
    intent_id = security_control.normalize_incident_id(data.get("intentId"))
    tx_signature = clean_string(data.get("transactionSignature", ""), 120)
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    configured = (
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
        or ""
    ).strip().lower()
    canonical = (
        "forkmesh-reward-submit-v1\n" + signer + "\n" + intent_id +
        "\n" + tx_signature + "\n" + ts
    ).encode()
    if (not configured or signer != configured or not intent_id
            or not tx_signature or not _ts_ok(ts)
            or not await _verify_owner_signature(env, signer, sig, canonical)):
        return json_response({"error": "unauthorized"}, status=401)
    row = await d1_first(
        env,
        "SELECT * FROM chain_intents WHERE intent_id=? "
        "AND signer_account=?",
        intent_id, signer,
    )
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if row.get("status") == "completed":
        if row.get("tx_signature") != tx_signature:
            return json_response({"error": "intent_already_completed"},
                                 status=409)
        return json_response({
            "ok": True,
            "job": _chain_intent_public(row),
            "custody": "external-local-signer",
            "notice": (
                "The completed state reflects a finalized transfer matching "
                "the exact public plan. ForkMesh never received the local pool "
                "private key."
            ),
        }, cache_control="no-store")
    if row.get("status") not in ("pending_signature", "submitted"):
        return json_response(
            {"error": "intent_not_signable",
             "status": str(row.get("status") or "")},
            status=409,
            cache_control="no-store",
        )
    now = int(Date.now())
    if int(row.get("expires_at") or 0) <= now:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='expired' "
            "WHERE intent_id=? AND status IN "
            "('pending_signature','submitted')",
            intent_id,
        )
        await _mark_chain_intent_failed(env, row, "expired")
        return json_response(
            {"error": "intent_expired"}, status=410,
            cache_control="no-store",
        )
    existing_signature = str(row.get("tx_signature") or "")
    if (row.get("status") == "submitted" and existing_signature
            and existing_signature != tx_signature):
        return json_response(
            {"error": "intent_signature_mismatch"}, status=409,
            cache_control="no-store",
        )
    replay = await d1_first(
        env,
        "SELECT intent_id FROM chain_intents WHERE tx_signature=? "
        "AND intent_id<>?",
        tx_signature, intent_id,
    )
    if replay:
        return json_response({"error": "transaction_replay"}, status=409)
    try:
        plan = json.loads(str(row.get("data") or "{}"))
    except Exception:
        plan = {}
    matches = await _solana_transaction_matches_plan(
        env, tx_signature, plan)
    if matches is False:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='rejected', tx_signature=? "
            "WHERE intent_id=?",
            tx_signature, intent_id,
        )
        await _mark_chain_intent_failed(env, row, "rejected")
        await _audit_sensitive_action(
            env, signer, "reward.intent_reject", "chain_intent", intent_id,
            "denied", {"reason": "transaction_plan_mismatch"})
        return json_response(
            {"error": "transaction_plan_mismatch"}, status=409)
    if matches is None:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='submitted', tx_signature=? "
            "WHERE intent_id=? AND status='pending_signature'",
            tx_signature, intent_id,
        )
        await _audit_sensitive_action(
            env, signer, "reward.intent_submit", "chain_intent", intent_id,
            "requested", {"verification": "pending_finality"})
        return json_response({
            "ok": True,
            "status": "submitted",
            "verification": "pending_finality",
            "custody": "external-local-signer",
            "fundsState": "pending-finality",
            "notice": (
                "Submission is not a completed transfer. The pool private key "
                "remained on the owner device, and completion requires a "
                "finalized transaction matching the exact public plan."
            ),
        }, status=202, cache_control="no-store")
    await _complete_chain_intent(env, row, tx_signature)
    await _audit_sensitive_action(
        env, signer, "reward.intent_complete", "chain_intent", intent_id,
        "success", {"verification": "finalized_exact_plan"})
    row["status"] = "completed"
    row["tx_signature"] = tx_signature
    row["completed_at"] = int(Date.now())
    return json_response({
        "ok": True,
        "job": _chain_intent_public(row),
        "custody": "external-local-signer",
        "notice": (
            "The completed state reflects a finalized transfer matching the "
            "exact public plan. ForkMesh never received the local pool private "
            "key."
        ),
    }, cache_control="no-store")


