async def verify_submitted_chain_intents(env):
    await ensure_schema(env)
    now = int(Date.now())
    expired = await d1_all(
        env,
        "SELECT * FROM chain_intents "
        "WHERE kind='community_reward_instant_distribution' "
        "AND status IN ('pending_signature','submitted') "
        "AND expires_at>0 AND expires_at<=? LIMIT 3",
        now,
    )
    for row in expired or []:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='expired' "
            "WHERE intent_id=? "
            "AND status IN ('pending_signature','submitted')",
            row.get("intent_id"),
        )
        await _mark_chain_intent_failed(env, row, "expired")
    rows = await d1_all(
        env,
        "SELECT * FROM chain_intents WHERE status='submitted' "
        "ORDER BY created_at ASC LIMIT 1",
    )
    for row in rows or []:
        try:
            plan = json.loads(str(row.get("data") or "{}"))
        except Exception:
            plan = {}
        matches = await _solana_transaction_matches_plan(
            env, row.get("tx_signature"), plan)
        if matches is True:
            await _complete_chain_intent(
                env, row, row.get("tx_signature"))
        elif matches is False:
            await d1_run(
                env,
                "UPDATE chain_intents SET status='rejected' "
                "WHERE intent_id=?",
                row.get("intent_id"),
            )
            await _mark_chain_intent_failed(env, row, "rejected")


pending_reward_award_handler = _route_handlers.export("pending_reward_award_handler")


async def pending_rewards_handler(env, request):
    """Owner ledger for walletless rewards; funds stay in the source wallet."""
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    account_bi, rec = await _account_session_record(env, request, data)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401)
    now = int(Date.now())
    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT reward_id, source_address, amount_lamports, "
            "wallet_address, status, created_at, expires_at, intent_id, "
            "tx_signature FROM pending_rewards WHERE recipient_bi=? "
            "ORDER BY created_at DESC LIMIT 100",
            account_bi,
        )
        rewards = [{
            "rewardId": str(row.get("reward_id") or ""),
            "sourceAddress": str(row.get("source_address") or ""),
            "amountLamports": int(row.get("amount_lamports") or 0),
            "walletAddress": str(row.get("wallet_address") or ""),
            "status": str(row.get("status") or ""),
            "createdAt": int(row.get("created_at") or 0),
            "expiresAt": int(row.get("expires_at") or 0),
            "intentId": str(row.get("intent_id") or ""),
            "transactionSignature": str(row.get("tx_signature") or ""),
            "fundsLocation": (
                "external-source-wallet"
                if row.get("status") != "completed"
                else "completed-on-chain-transfer"),
        } for row in rows or []]
        return json_response({
            "ok": True,
            "rewards": rewards,
            "custody": "external-local-signer",
            "notice": (
                "A pending reward is a temporary ledger allocation. ForkMesh "
                "does not create a wallet or hold funds for you."
            ),
        }, cache_control="no-store")

    reward_id = security_control.normalize_incident_id(data.get("rewardId"))
    wallet = clean_string(data.get("walletAddress", ""), 64).strip()
    if not reward_id or not SOLANA_RE.match(wallet):
        return json_response({"error": "invalid_reward_claim"}, status=400)
    row = await d1_first(
        env,
        "SELECT * FROM pending_rewards WHERE reward_id=? "
        "AND recipient_bi=?",
        reward_id, account_bi,
    )
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if row.get("status") == "completed":
        return json_response({
            "ok": True, "status": "completed",
            "transactionSignature": str(row.get("tx_signature") or ""),
            "fundsLocation": "completed-on-chain-transfer",
            "custody": "external-self-custodial-recipient",
            "notice": (
                "This reward is complete only because its finalized public "
                "transaction was verified. ForkMesh did not create or retain "
                "a wallet or private key for the recipient."
            ),
        }, cache_control="no-store")
    if row.get("status") != "pending_wallet":
        return json_response({"error": "reward_not_claimable"}, status=409)
    if int(row.get("expires_at") or 0) <= now:
        await d1_run(
            env,
            "UPDATE pending_rewards SET status='expired' "
            "WHERE reward_id=? AND status='pending_wallet'",
            reward_id,
        )
        return json_response({
            "error": "reward_expired",
            "fundsLocation": "external-source-wallet",
            "custody": "ledger-allocation-only",
            "notice": (
                "The ledger allocation expired without a transfer. No wallet "
                "was created, and the funds remain in the external source "
                "wallet."
            ),
        }, status=410, cache_control="no-store")
    signer = (
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
        or ""
    ).strip().lower()
    if not signer:
        return json_response(
            {"error": "external_signer_not_configured"}, status=503)
    intent_id = _random_bytes(16).hex()
    plan = {
        "v": 2,
        "network": _reward_network(env),
        "sourceAddress": str(row.get("source_address") or ""),
        "custody": {
            "forkMeshHoldsUserKeys": False,
            "fundsRemainInSourceWalletUntilSigned": True,
        },
        "signing": {
            "required": True,
            "performed": False,
            "method": "external-local-qt",
        },
        "transfers": [{
            "address": wallet,
            "lamports": int(row.get("amount_lamports") or 0),
        }],
        "policy": "pending-reward-claim-v1",
        "rewardId": reward_id,
        "generatedAt": now,
    }
    await d1_run(
        env,
        "INSERT INTO chain_intents "
        "(intent_id, kind, source_address, signer_account, status, data, "
        "created_at, expires_at) VALUES "
        "(?,?,?,?,'pending_signature',?,?,?)",
        intent_id, "pending_reward", row.get("source_address"), signer,
        json.dumps(plan, sort_keys=True, separators=(",", ":")),
        now, int(row.get("expires_at") or 0),
    )
    await d1_run(
        env,
        "UPDATE pending_rewards SET wallet_address=?, status='ready', "
        "intent_id=? WHERE reward_id=? AND recipient_bi=? "
        "AND status='pending_wallet'",
        wallet, intent_id, reward_id, account_bi,
    )
    await _audit_sensitive_action(
        env, actor, "reward.wallet_claim", "pending_reward", reward_id,
        "requested", {"intentId": intent_id})
    return json_response({
        "ok": True,
        "status": "ready",
        "intentId": intent_id,
        "custody": "external-local-signer",
        "fundsLocation": "external-source-wallet",
        "notice": (
            "Ready means an unsigned plan is awaiting explicit approval by the "
            "external local signer. Funds remain in the source wallet until a "
            "matching transfer is signed and finalized."
        ),
    }, status=202, cache_control="no-store")


async def expire_pending_rewards(env):
    await ensure_schema(env)
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE pending_rewards SET status='expired', wallet_address='' "
        "WHERE status='pending_wallet' AND expires_at<=?",
        now,
    )
    # A signing plan not completed before the allocation deadline expires too;
    # the source wallet never sent funds, so this releases the reservation.
    await d1_run(
        env,
        "UPDATE chain_intents SET status='expired' "
        "WHERE kind='pending_reward' "
        "AND status IN ('pending_signature','submitted') "
        "AND expires_at>0 AND expires_at<=?",
        now,
    )
    await d1_run(
        env,
        "UPDATE pending_rewards SET status='expired', wallet_address='' "
        "WHERE status='ready' AND expires_at<=? "
        "AND intent_id IN (SELECT intent_id FROM chain_intents "
        "WHERE status='expired')",
        now,
    )


# --- Disabled legacy issue-bounty storage -----------------------------------
# Worker-created escrow wallets and automatic payouts are frozen. These helpers
# remain solely to read/migrate historical records; new bounty funding must use
# an external self-custodial wallet and a reviewed program or multisig.


async def _bounty_bi(env, owner, repo, number, kind=""):
    # kind "" is an issue bounty (key "<owner>/<repo>#<number>", unchanged);
    # kind "pr" is a per-pull-request bounty (key "…#pr-<number>"), so an issue
    # and a pull request that happen to share a number never collide.
    prefix = (kind + "-") if kind else ""
    return await blind_index(
        env, owner + "/" + repo + "#" + prefix + str(int(number)))


async def _load_bounty(env, bounty_bi):
    row = await d1_first(
        env, "SELECT data FROM issue_bounty WHERE bounty_bi=?", bounty_bi)
    if not row:
        return None
    return await decrypt_row(env, row.get("data", ""))


def _bounty_public(rec):
    # Never leak the deposit key; only payout-safe fields go back to clients.
    legacy_frozen = (
        rec.get("status") != "paid"
        and not bool(rec.get("legacy_custody_migrated_at"))
    )
    return {
        "address": rec.get("address", ""),
        "amountUsd": rec.get("amount_usd", 0),
        "requiredLamports": rec.get("required_lamports", 0),
        "amountSol": _amount_sol(rec.get("required_lamports", 0)),
        "receivedLamports": rec.get("received_lamports", 0),
        "confirmed": bool(rec.get("confirmed")),
        "status": "legacy_frozen" if legacy_frozen
                  else rec.get("status", "open"),
        "custody": (
            "migration-required" if legacy_frozen
            else "completed-on-chain" if rec.get("status") == "paid"
            else "external-self-custodial"),
        "nonCustodialNotice": (
            "New Worker-held escrow is disabled. A legacy escrow can move "
            "only through the operator's offline migration."
        ),
        "featureState": "migration-only",
        "fundsLocation": "historical-external-address",
        "payee": rec.get("payee", ""),
        "payoutSig": rec.get("payout_sig", ""),
        # Never return a payable URI for a frozen historical address.
        "uri": "",
    }


async def bounties_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    action = (data.get("action") or "create").strip()

    # A historical bounty row must not turn a private repository name into a
    # probeable status oracle. Resolve the repository and its normal owner/share
    # boundary before deriving or reading the bounty blind index; missing and
    # unauthorized private repositories deliberately share the same 404 shape.
    viewer = await _authed_account_name(env, request, data)
    if await _repository_access_context(
            env, request, owner, repo, viewer=viewer) is None:
        return _private_replica_not_found()

    if action in ("wallet", "create", "payout"):
        return json_response({
            "error": "legacy_custody_disabled",
            "custody": "external-self-custodial",
            "notice": (
                "ForkMesh no longer creates inbuilt wallets or Worker-held "
                "bounty escrow. Use a direct external-wallet payment; pooled "
                "escrow requires a reviewed Solana program or multisig."
            ),
        }, status=410, cache_control="no-store")

    try:
        number = int(data.get("number", 0))
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return json_response({"error": "number_required"}, status=400)
    # kind "" is an issue bounty; "pr" is a per-pull-request bounty (issue #347),
    # keyed separately so an issue and a PR sharing a number never collide.
    kind = clean_string(data.get("kind", ""), 8)
    if kind not in ("", "pr"):
        kind = ""
    bounty_bi = await _bounty_bi(env, owner, repo, number, kind)
    rec = await _load_bounty(env, bounty_bi)

    if rec is None:
        return json_response({"error": "no_bounty"}, status=404)

    if action == "status":
        # Public historical status only. Work on a projection so polling never
        # re-encrypts a retained key-bearing row.
        rec = dict(rec)
        if rec.get("status") != "paid" and rec.get("address"):
            balance = await _solana_balance_lamports(env, rec["address"])
            if balance is not None:
                rec["received_lamports"] = int(balance)
                required = int(rec.get("required_lamports", 0) or 0)
                if balance > 0 and balance >= required:
                    rec["confirmed"] = True
                    rec["status"] = "funded"
        return json_response(_bounty_public(rec))

    return json_response({"error": "bad_action"}, status=400)


# Cap on collaborators per repo, so one owner can't fill the table with shares.
MAX_REPO_GRANTEES = 100


async def _active_public_recipient_bundles(env, account_bis):
    """Return each account's newest valid, active public-only MirrorCrypto key.

    A repository owner needs these public halves to seal one ciphertext content
    key to the exact collaborator set.  Private halves never enter this API.
    Invalid or revoked rows are deliberately omitted so callers fail closed
    instead of publishing ciphertext to an unverified/stale recipient.
    """
    unique_bis = []
    seen = set()
    for account_bi in account_bis or []:
        account_bi = str(account_bi or "")
        if account_bi and account_bi not in seen:
            unique_bis.append(account_bi)
            seen.add(account_bi)
    if not unique_bis:
        return {}
    rows = await d1_all(
        env,
        "SELECT account_bi, key_id, public_bundle, created_at FROM "
        "owner_encryption_keys WHERE revoked_at=0 AND account_bi IN (%s) "
        "ORDER BY created_at DESC"
        % ",".join("?" for _ in unique_bis),
        *unique_bis,
    )
    bundles = {}
    for row in rows or []:
        account_bi = str(row.get("account_bi") or "")
        # ORDER BY makes the first valid row the newest for this account.  If a
        # newer malformed row exists, continue so an older *valid and active*
        # registration can still be used.
        if not account_bi or account_bi in bundles:
            continue
        try:
            public_bundle = json.loads(str(row.get("public_bundle") or ""))
        except Exception:
            continue
        valid = security_control.validate_owner_public_bundle(public_bundle)
        if not valid or valid["kid"] != str(row.get("key_id") or ""):
            continue
        bundles[account_bi] = {
            "keyId": valid["kid"],
            "publicBundle": {
                "v": valid["v"],
                "x25519": valid["x25519"],
                "mlkem768": valid["mlkem768"],
            },
            "createdAt": int(row.get("created_at") or 0),
        }
    return bundles


async def shares_handler(env, request, owner, repo):
    # Private-repo collaborator ACL (issue #9). Every operation is authorized by
    # the OWNER account's key — only the owner may grant/revoke/list who a private
    # repo is shared with. A grantee then sees the repo in their authenticated
    # catalog and clones it with their own key (verify_share_view_token); none of
    # that is gated here, only the membership list is.
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    audit_repo_target = owner + "/" + repo
    try:
        owner_pub = await _owner_pubkey(env, owner)
    except Exception:
        raise
    if not owner_pub:
        return json_response({"error": "account_required"}, status=403)

    if method == "GET":
        # List current grantees for the owner's Collaborators UI. Owner-signed so
        # the membership of a private repo isn't world-readable.
        params = parse_qs(urlparse(request.url).query)
        ts = clean_string(params.get("ts", [""])[0], 20)
        sig = clean_string(params.get("sig", [""])[0], 200)
        canonical = ("forkmesh-shares-list-v1\n" + owner + "\n" + repo + "\n" +
                     str(ts)).encode()
        if not (_ts_ok(ts) and await ed25519_verify(owner_pub, sig, canonical)):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env,
            "SELECT grantee_bi, data FROM repo_shares "
            "WHERE repo_bi=? ORDER BY ts ASC",
            repo_bi,
        )
        grantees = []
        grantee_rows = []
        for row in rows:
            rec = await decrypt_row(env, row["data"])
            if rec and rec.get("grantee"):
                grantee = clean_string(
                    rec.get("grantee", ""), MAX_NODE_NAME).lower()
                grantee_bi = str(row.get("grantee_bi") or "")
                if grantee and grantee_bi:
                    grantees.append(grantee)
                    grantee_rows.append((grantee, grantee_bi))
        bundles = await _active_public_recipient_bundles(
            env, [grantee_bi for _, grantee_bi in grantee_rows])
        recipients = []
        missing = []
        for grantee, grantee_bi in grantee_rows:
            bundle = bundles.get(grantee_bi)
            if not bundle:
                missing.append(grantee)
                continue
            recipients.append({"grantee": grantee, **bundle})
        return json_response({
            "ok": True,
            # Retain the names-only field for older owner clients.  It is still
            # behind the owner signature and never enters a public catalog.
            "grantees": grantees,
            "recipients": recipients,
            "encryptionReady": not missing,
            "missingEncryptionKeys": missing,
            "privateKeysStored": False,
        }, cache_control="no-store")

    if method in ("POST", "DELETE"):
        try:
            data = await bounded_json_request(request)
        except Exception:
            data = {}
        # DELETE is accepted as an alias for action=remove so the verb can carry
        # intent even when a client can't easily attach a body to a DELETE.
        action = "remove" if method == "DELETE" else \
            (clean_string(data.get("action", "add"), 12) or "add")
        if action not in ("add", "remove"):
            return json_response({"error": "bad_action"}, status=400)
        audit_action = (
            "repository.collaborator_revoke"
            if action == "remove" else "repository.collaborator_grant")
        grantee = clean_string(data.get("grantee", ""), MAX_NODE_NAME).lower()
        audit_target = (
            audit_repo_target + "/" + grantee
            if grantee else audit_repo_target)
        ts = clean_string(str(data.get("ts", "")), 20)
        sig = clean_string(data.get("sig", ""), 200)
        if not grantee:
            return json_response({"error": "grantee_required"}, status=400)
        if grantee == owner:
            return json_response({"error": "cannot_share_with_self"}, status=400)
        # The action is bound into the signature so an "add" token can never be
        # replayed as a "remove" (or vice versa).
        canonical = ("forkmesh-share-v1\n" + owner + "\n" + repo + "\n" +
                     grantee + "\n" + action + "\n" + str(ts)).encode()
        try:
            authorized = (
                _ts_ok(ts)
                and await ed25519_verify(owner_pub, sig, canonical))
        except Exception:
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "failed",
                {"reason": "signature_check_error"})
            raise
        if not authorized:
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "denied", {"reason": "unauthorized"})
            return json_response({"error": "unauthorized"}, status=401)
        grantee_bi = await blind_index(env, grantee)

        if action == "remove":
            try:
                await d1_run(
                    env,
                    "DELETE FROM repo_shares "
                    "WHERE repo_bi=? AND grantee_bi=?",
                    repo_bi, grantee_bi)
            except Exception:
                await _audit_sensitive_action(
                    env, owner, audit_action, "repository_collaborator",
                    audit_target, "failed", {"reason": "mutation_error"})
                raise
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "success")
            return json_response({"ok": True, "grantee": grantee, "shared": False})

        # add: the grantee must be a real account (so a token signed by their key
        # can ever verify), and the per-repo cap must not be exceeded.
        try:
            if not await _owner_pubkey(env, grantee):
                await _audit_sensitive_action(
                    env, owner, audit_action, "repository_collaborator",
                    audit_target, "denied", {"reason": "unknown_account"})
                return json_response({"error": "unknown_account"}, status=404)
            recipient_bundles = await _active_public_recipient_bundles(
                env, [grantee_bi])
            recipient = recipient_bundles.get(grantee_bi)
            if not recipient:
                # Do not create an ACL that the owner cannot immediately turn
                # into an exact encrypted recipient set.
                await _audit_sensitive_action(
                    env, owner, audit_action, "repository_collaborator",
                    audit_target, "denied",
                    {"reason": "encryption_key_required"})
                return json_response({
                    "error": "grantee_encryption_key_required",
                    "grantee": grantee,
                    "shared": False,
                }, status=409, cache_control="no-store")
            existing = await d1_first(
                env,
                "SELECT 1 AS one FROM repo_shares "
                "WHERE repo_bi=? AND grantee_bi=?",
                repo_bi, grantee_bi)
            if not existing:
                count_row = await d1_first(
                    env,
                    "SELECT COUNT(*) AS n FROM repo_shares WHERE repo_bi=?",
                    repo_bi)
                if (
                    count_row
                    and int(count_row.get("n") or 0) >= MAX_REPO_GRANTEES
                ):
                    await _audit_sensitive_action(
                        env, owner, audit_action,
                        "repository_collaborator", audit_target, "denied",
                        {"reason": "collaborator_limit"})
                    return json_response(
                        {"error": "too_many_grantees"}, status=429)
            now = int(Date.now())
            enc = await encrypt_row(
                env,
                {"grantee": grantee, "owner": owner, "repo": repo, "ts": now})
            await d1_run(
                env,
                "INSERT INTO repo_shares (repo_bi, grantee_bi, data, ts) "
                "VALUES (?,?,?,?) ON CONFLICT(repo_bi, grantee_bi) DO UPDATE SET "
                "data=excluded.data, ts=excluded.ts",
                repo_bi, grantee_bi, enc, now)
        except Exception:
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "failed", {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, owner, audit_action, "repository_collaborator",
            audit_target, "success", {"alreadyPresent": bool(existing)})
        await enqueue_notification(env, grantee, "repo_shared",
                                   owner + " shared " + owner + "/" + repo + " with you",
                                   body="You can now view and clone this private repository with your own node key.",
                                   repo=owner + "/" + repo,
                                   href=repo_web_href(owner, repo),
                                   actor=owner, source="repo_share",
                                   dedupe="share:" + owner + "/" + repo + ":" + grantee)
        return json_response({
            "ok": True,
            "grantee": grantee,
            "shared": True,
            "recipient": {"grantee": grantee, **recipient},
            "privateKeysStored": False,
        }, cache_control="no-store")

    return json_response({"error": "method_not_allowed"}, status=405)


# --- Organizations + teams (issue #388) --------------------------------------
# Users create organizations, add accounts to them, and group members into
# teams that hold one repository permission over every repo linked under the
# org. Every "may this role do this?" question is answered by the deny-by-
# default matrix in organization_rbac.py (issue #487): owners/admins
# administer the org itself and implicitly hold 'admin' repo permission,
# maintainers hold 'maintain', members/auditors hold 'read', guests hold
# nothing; team membership raises that to the team's permission, capped by the
# role's ceiling (auditors and guests stay read-only). The org name fronts the
# linked repos' URLs — the
# /<org>/<repo> git endpoints and /api/repo/<org>/<repo>/... are rewritten to
# the hosting node's namespace before routing (see org_alias_rewrite), so
# mirror nodes and clients keep operating on the canonical node namespace
# while the public URL shows the organization's name.

# Keep in sync with organization_rbac.ORG_ROLES (the module is the policy;
# this tuple is the request-validation vocabulary, strongest first).
ORG_ROLES = ("owner", "admin", "maintainer", "member", "auditor", "guest")
# Repository permission ladder, weakest to strongest (issue #388: read /
# write / maintain / admin). Tuple order IS the ranking.
TEAM_PERMISSIONS = ("read", "write", "maintain", "admin")
MAX_ORGS_PER_ACCOUNT = 10
MAX_ORG_MEMBERS = 200
MAX_ORG_TEAMS = 50
MAX_ORG_REPOS = 200
ORG_WORLD_ACCESS_VALUES = ("public", "restricted", "private")

# Org repo-alias resolution memo: "org/repo" -> (node owner or "", ts),
# per-isolate so the hot repo/git routes don't pay a D1 read per request
# (including the common negative case: the owner segment is a plain node
# name). Short TTL so a new link/unlink takes effect quickly; mutating
# handlers clear it inline for same-isolate read-your-writes.
_ORG_ALIAS_MEMO = {}
ORG_ALIAS_MEMO_TTL_MS = 30 * 1000
ORG_ALIAS_MEMO_MAX = 512

# One alias->host inbox recovery sweep per repo per isolate (_inbox_repo_key).
# Keyed by the host repo blind index and marked BEFORE the sweep runs, so a
# failing sweep costs one UPDATE per isolate rather than one per request; a
# recycled isolate retries on its own.
_ALIAS_INBOX_REKEYED = {}
ALIAS_INBOX_REKEY_MAX = 512


class _OrgAliasUnresolved(Exception):
    """An organization alias behind a durable write could not be resolved.

    Narrow on purpose: inbox handlers turn ONLY this into a retryable 503, so a
    genuine bug still surfaces as a 500 instead of masquerading as backpressure.
    """


def _org_logo_url(value):
    raw = clean_string(value or "", 500).strip()
    if not raw:
        return ""
    try:
        parsed = urlparse(raw)
    except Exception:
        return ""
    if (
        parsed.scheme != "https"
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
        or parsed.fragment
    ):
        return ""
    return parsed.geturl()


def _org_world_access(value, fallback=None):
    source = value if isinstance(value, dict) else {}
    base = {"lobby": "public", "floors": "restricted",
            "offices": "restricted"}
    if isinstance(fallback, dict):
        for field in base:
            selected = str(fallback.get(field) or "").strip().lower()
            if selected in ORG_WORLD_ACCESS_VALUES:
                base[field] = selected
    return {
        field: (
            str(source.get(field) or base.get(field) or "").strip().lower()
            if str(source.get(field) or base.get(field) or "").strip().lower()
            in ORG_WORLD_ACCESS_VALUES
            else base[field]
        )
        for field in ("lobby", "floors", "offices")
    }


def _org_world_access_allowed(level, viewer_role):
    level = str(level or "private").lower()
    role = str(viewer_role or "").lower()
    if level == "public":
        return True
    if level == "restricted":
        return _org_rbac.org_role_allows(role, "organization.world.restricted")
    return _org_rbac.org_role_allows(role, "organization.world.private")


def team_permission_rank(permission):
    # Index into TEAM_PERMISSIONS, -1 for unknown — so comparisons read as
    # rank(x) >= rank("write") and an unknown permission never qualifies.
    try:
        return TEAM_PERMISSIONS.index((permission or "").strip().lower())
    except ValueError:
        return -1


async def _org_row(env, org):
    # (org_bi, orgs row or None) for an org name. org_bi is keyed under an
    # "org:" prefix so it can never collide with an account blind index.
    org = (org or "").strip().lower()
    org_bi = await blind_index(env, "org:" + org)
    row = await d1_first(
        env, "SELECT name, data, created_at FROM orgs WHERE org_bi=?", org_bi)
    return org_bi, row


async def _org_role(env, org_bi, account):
    # The account's role in the org (one of ORG_ROLES) or "".
    if not account:
        return ""
    member_bi = await blind_index(env, account)
    row = await d1_first(
        env, "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
        org_bi, member_bi)
    return str((row or {}).get("role") or "")


async def _org_permission(env, org_bi, account):
    # The strongest repository permission `account` holds in the org: the
    # role's baseline from the authorization matrix (owner/admin => 'admin',
    # maintainer => 'maintain', member/auditor => 'read', guest => none), and
    # team membership raises it to the best team's permission, never above the
    # role's ceiling (auditors and guests stay read-only). "" for non-members
    # and for any role the matrix does not know.
    role = await _org_role(env, org_bi, account)
    best = _org_rbac.org_role_repo_permission(role)
    ceiling = _org_rbac.org_role_repo_permission_ceiling(role)
    if not role or not ceiling:
        return ""
    if best == ceiling:
        return best
    member_bi = await blind_index(env, account)
    rows = await d1_all(
        env,
        "SELECT t.permission AS permission FROM org_team_members m "
        "JOIN org_teams t ON t.org_bi = m.org_bi AND t.team = m.team "
        "WHERE m.org_bi=? AND m.member_bi=?",
        org_bi, member_bi)
    for row in rows or []:
        perm = str(row.get("permission") or "")
        if team_permission_rank(perm) > team_permission_rank(ceiling):
            perm = ceiling
        if team_permission_rank(perm) > team_permission_rank(best):
            best = perm
    return best


async def _org_write_allowed(env, owner, repo, pusher):
    # True when some org links owner/repo and the pusher holds write-or-better
    # permission there. Fail closed: any error must never grant push access.
    if not owner or not repo or not pusher:
        return False
    try:
        await ensure_schema(env)
        rows = await d1_all(
            env, "SELECT org_bi FROM org_repos WHERE node_owner=? AND repo=?",
            owner.lower(), repo.lower())
        for row in rows or []:
            perm = await _org_permission(
                env, str(row.get("org_bi") or ""), pusher)
            if team_permission_rank(perm) >= team_permission_rank("write"):
                return True
        return False
    except Exception:
        return False


async def _org_owner_of_linked_repo(env, node, repo, actor):
    if not node or not repo or not actor:
        return False
    try:
        rows = await d1_all(
            env, "SELECT org_bi FROM org_repos WHERE node_owner=? AND repo=?",
            str(node).lower(), str(repo).lower())
        for row in rows or []:
            role = await _org_role(
                env, str(row.get("org_bi") or ""), str(actor).lower())
            if role == "owner":
                return True
        return False
    except Exception:
        return False


async def _org_linked_repo_permission(env, node, repo, actor):
    if not node or not repo or not actor:
        return ""
    try:
        rows = await d1_all(
            env, "SELECT org_bi FROM org_repos WHERE node_owner=? AND repo=?",
            str(node).lower(), str(repo).lower())
        best = ""
        for row in rows or []:
            perm = await _org_permission(
                env, str(row.get("org_bi") or ""), str(actor).lower())
            if team_permission_rank(perm) > team_permission_rank(best):
                best = perm
        return best
    except Exception:
        return ""


async def _org_admin_of_linked_repo(env, node, repo, actor):
    return await _org_linked_repo_permission(
        env, node, repo, actor) == "admin"


async def _repo_admin_allowed(env, actor, node, repo):
    actor = str(actor or "").strip().lower()
    node = str(node or "").strip().lower()
    if not actor or not node or not repo:
        return False
    if await _account_owns_node(env, actor, node):
        return True
    return await _org_admin_of_linked_repo(env, node, repo, actor)


async def repo_viewer_permission_handler(env, request, owner, repo):
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store")
    await ensure_schema(env)
    actor = clean_string(
        await _authed_account_name(env, request) or "",
        MAX_NODE_NAME).strip().lower()
    permission = ""
    if actor:
        if await _account_owns_node(env, actor, owner):
            permission = "admin"
        else:
            permission = await _org_linked_repo_permission(
                env, owner, repo, actor)
    return json_response({
        "ok": True,
        "viewer": actor,
        "permission": permission,
        "viewerCanAdmin": permission == "admin",
    }, cache_control="private, no-store")


async def verify_org_push_token(env, pusher, owner, repo, ts, sig):
    # Org-team write gate for git push (issue #388): a member of an org team
    # with write+ permission on a linked repo may run receive-pack against it,
    # signing with their OWN key (the node owner never hands out its key).
    # Distinct canonical prefix so an owner push token or a share-view token
    # can never be replayed here, and vice versa. owner/repo are the CANONICAL
    # node namespace — the org alias is rewritten away before the push gate.
    if not pusher or not owner or not repo or not sig or not _ts_ok(ts):
        return False
    if pusher == owner:
        return False  # the owner authenticates via verify_push_token, not here
    pubkey = await _owner_pubkey(env, pusher)
    if not pubkey:
        return False
    canonical = ("forkmesh-org-push-v1\n" + pusher + "\n" + owner + "\n" +
                 repo + "\n" + str(ts)).encode()
    if not await ed25519_verify(pubkey, sig, canonical):
        return False
    return await _org_write_allowed(env, owner, repo, pusher)


async def _org_repo_node_strict(env, org, repo):
    # _org_repo_node without the fail-closed swallow: a lookup error PROPAGATES.
    # Routing may treat "cannot resolve" as "not an org URL", but a caller
    # choosing a durable STORAGE key must not — see _inbox_repo_key.
    org = (org or "").strip().lower()
    repo = (repo or "").strip().lower()
    if not org or not repo:
        return ""
    now = int(Date.now())
    key = org + "/" + repo
    hit = _ORG_ALIAS_MEMO.get(key)
    if hit and now - hit[1] < ORG_ALIAS_MEMO_TTL_MS:
        return hit[0]
    await ensure_schema(env)
    org_bi = await blind_index(env, "org:" + org)
    row = await d1_first(
        env, "SELECT node_owner FROM org_repos WHERE org_bi=? AND repo=?",
        org_bi, repo)
    node = str((row or {}).get("node_owner") or "").strip().lower()
    if not valid_node_name(node) or node == org:
        node = ""
    if len(_ORG_ALIAS_MEMO) >= ORG_ALIAS_MEMO_MAX:
        _ORG_ALIAS_MEMO.clear()
    _ORG_ALIAS_MEMO[key] = (node, now)
    return node


async def _org_repo_node(env, org, repo):
    # Node owner serving /<org>/<repo>, or "" when the pair is not a
    # registered alias. Fail closed on any error: "" simply means "not an org
    # URL" and the request proceeds unrewritten.
    try:
        return await _org_repo_node_strict(env, org, repo)
    except Exception:
        return ""


async def org_alias_rewrite(env, request, url):
    # Organization repo aliases (issue #388): the /<org>/<repo> git endpoints
    # and every /api/repo/<org>/<repo>/... path serve the linked node's repo
    # under the organization's name. The rewrite is worker-internal — no
    # redirect, the org name stays in the address bar and clone URL — and runs
    # before any route matching, so everything downstream (auth canonicals,
    # direct gateway routing and blind indexes) sees the canonical
    # /<node>/<repo> path exactly as if the node
    # URL had been requested. Org names can never collide with account names
    # (both creation paths reject the other namespace), so an existing node's
    # URL is never rewritten. Returns the rewritten (request, url) or None.
    match = (REPO_API_PREFIX_RE.match(url.path) or GIT_INFO_RE.match(url.path)
             or GIT_PACK_RE.match(url.path) or GIT_RECEIVE_RE.match(url.path))
    if not match:
        return None
    owner = safe_segment(match.group(1))
    repo = safe_segment(match.group(2))
    if not owner or not repo:
        return None
    node = await _org_repo_node(env, owner, repo)
    if not node:
        return None
    new_path = (url.path[:match.start(1)] + quote(node) +
                url.path[match.end(1):])
    new_url = url._replace(path=new_path).geturl()
    # Route internally with the canonical parsed URL while preserving the
    # original Request object.  Fetch's second Request constructor argument is
    # a RequestInit mapping, not another Request; passing the Worker Request
    # there aborts the Python isolate.  Downstream handlers receive owner/repo
    # from the rewritten URL, while retaining the single-use body, trusted
    # request.cf metadata, headers, and the public alias URL presented by the
    # caller.
    return request, urlparse(new_url)


class _OrganizationSuccessionRuntime:
    """Least-privilege adapter for organization-role succession.

    Deliberately absent: platform-admin checks, repository/account mutation,
    encryption-key access, wallet/reward helpers, agent state, and device
    ownership mutation. Device/node timestamps are read only to establish the
    configured owner's most recent activity.
    """

    def __init__(self, env, request=None):
        self.env = env
        self.request = request

    def method(self):
        return method_name(self.request) if self.request is not None else "GET"

    def now(self):
        return int(Date.now())

    def new_id(self):
        return _ap_uuid()

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        return json_response(
            data,
            status=status,
            cache_control=cache_control,
            extra_headers=extra_headers,
        )

    async def ensure_schema(self):
        await ensure_schema(self.env)

    async def json_body(self, limit):
        if self.request is None:
            return None, "invalid_json"
        try:
            raw_length = self.request.headers.get("content-length") or ""
            if raw_length and int(raw_length) > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = await self.request.text()
        except Exception:
            return None, "invalid_json"
        if len(str(raw or "").encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        if not str(raw or "").strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        return await _account_session_record(
            self.env, self.request,
            data if isinstance(data, dict) else {})

    async def organization(self, org):
        return await _org_row(self.env, org)

    async def org_role(self, org_bi, account):
        return await _org_role(self.env, org_bi, account)

    async def org_members(self, org_bi):
        return await d1_all(
            self.env,
            "SELECT member_bi,name,role,created_at FROM org_members "
            "WHERE org_bi=? ORDER BY created_at ASC",
            org_bi,
        )

    async def account(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return "", ""
        account_bi, rec = await _account_row(self.env, name)
        if (
            not rec
            or rec.get("status") != "active"
            or _account_kind(rec) != "user"
        ):
            return "", ""
        return str(account_bi or ""), name

    async def owner_activity(self, owner_bi, stored_at):
        # Only generalized last-seen maxima are used; no device identifier,
        # label, platform, location, user-agent, or personal payload enters
        # succession storage or responses.
        device = await d1_first(
            self.env,
            "SELECT COALESCE(MAX(last_seen),0) AS last_seen "
            "FROM account_devices WHERE account_bi=? AND enabled=1 "
            "AND revoked_at=0",
            owner_bi,
        )
        node = await d1_first(
            self.env,
            "SELECT COALESCE(MAX(last_seen),0) AS last_seen "
            "FROM nodes WHERE user_bi=?",
            owner_bi,
        )
        return max(
            int(stored_at or 0),
            int((device or {}).get("last_seen") or 0),
            int((node or {}).get("last_seen") or 0),
        )

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)

    async def batch(self, statements):
        return await _contribution_run_batch(self.env, statements)

    async def notify(self, recipient, title, body, dedupe):
        return await enqueue_notification(
            self.env,
            recipient,
            "org_succession",
            title,
            body=body,
            href="",
            source="organization_succession",
            dedupe=dedupe,
        )


async def organization_succession_handler(env, request, org, action=""):
    return await organization_succession_api.handle(
        _OrganizationSuccessionRuntime(env, request), org, action)


async def process_organization_succession_warnings(env):
    return await organization_succession_api.process_warnings(
        _OrganizationSuccessionRuntime(env), limit=3)


# --- Organization Discord connector ----------------------------------------
# The Discord API token stays exclusively in the Worker secret binding.  The
# policy module receives only the narrow operations below, so a dashboard body,
# D1 value, audit event, or future connector field cannot accidentally expose
# or reuse it as an application credential.
DISCORD_API_ORIGIN = "https://discord.com/api/v10"
DISCORD_OAUTH_API_ORIGIN = "https://discord.com/api"
DISCORD_OAUTH_AUTHORIZE_ORIGIN = "https://discord.com/oauth2/authorize"
DISCORD_OAUTH_CALLBACK_PATH = "/api/integrations/discord/callback"
DISCORD_OAUTH_TRANSACTION_COOKIE = "forkmesh_discord_oauth"
DISCORD_API_TIMEOUT_SECONDS = 8
DISCORD_API_MAX_RESPONSE_BYTES = 512 * 1024
_DISCORD_SNOWFLAKE_RE = re.compile(r"^[0-9]{17,20}$")
_DISCORD_OAUTH_TRANSACTION_RE = re.compile(r"^[a-f0-9]{64}$")
_DISCORD_GUILD_PATH_RE = re.compile(
    r"^/guilds/[0-9]{17,20}\?with_counts=true$")
_DISCORD_GUILD_CHANNELS_PATH_RE = re.compile(
    r"^/guilds/[0-9]{17,20}/channels$")
_DISCORD_GUILD_ROLES_PATH_RE = re.compile(
    r"^/guilds/[0-9]{17,20}/roles$")
_DISCORD_CHANNEL_MESSAGES_GET_PATH_RE = re.compile(
    r"^/channels/[0-9]{17,20}/messages\?limit=[1-9][0-9]?"
    r"(?:&after=[0-9]{17,20})?$")
_DISCORD_CHANNEL_MESSAGES_POST_PATH_RE = re.compile(
    r"^/channels/[0-9]{17,20}/messages$")
_DISCORD_OAUTH_TOKEN_PATH = "/oauth2/token"
_DISCORD_OAUTH_IDENTITY_PATH = "/users/@me"
_DISCORD_OAUTH_GUILDS_PATH = "/users/@me/guilds"
# One best-effort coordinator is shared by every connector request handled by
# this Worker isolate. It is intentionally not a durable cross-colo global
# limiter and carries only short-lived rate metadata plus minimized public
# channel/@everyone-role projections—never credentials, OAuth values, raw
# private catalogs, or message history.  Construct it with the first Discord
# request instead of while Cloudflare is validating Python global scope.
_discord_rate_coordinator_instance = None


def _discord_rate_coordinator():
    global _discord_rate_coordinator_instance
    if _discord_rate_coordinator_instance is None:
        _discord_rate_coordinator_instance = (
            _LazyModule("discord_rate").DiscordRateCoordinator())
    return _discord_rate_coordinator_instance


def _discord_bot_token(env):
    """Return the server-only secret without placing it in any application row."""

    return str(getattr(env, "DISCORD_BOT_TOKEN", "") or "").strip()


def _discord_oauth_config(env):
    """Read only the server-side OAuth application configuration.

    The redirect URI is fixed to the one global callback path.  It is never
    taken from a dashboard request, so an owner cannot use this connector as an
    OAuth redirector or turn a bot's global guild visibility into org consent.
    """

    client_id = _discord_snowflake(
        getattr(env, "DISCORD_CLIENT_ID", "") or "")
    client_secret = str(
        getattr(env, "DISCORD_CLIENT_SECRET", "") or "").strip()
    redirect_uri = str(
        getattr(env, "DISCORD_OAUTH_REDIRECT_URI", "") or "").strip()
    public_base_url = str(
        getattr(env, "PUBLIC_BASE_URL", "") or "https://forkmesh.com").strip()
    try:
        parsed = urlparse(redirect_uri)
        public_origin = urlparse(public_base_url)
        redirect_origin = (
            parsed.scheme, parsed.hostname, parsed.port
        ) if parsed else None
        canonical_origin = (
            public_origin.scheme, public_origin.hostname, public_origin.port
        ) if public_origin else None
    except Exception:
        parsed = None
        public_origin = None
        redirect_origin = None
        canonical_origin = None
    if not (
        client_id
        and client_secret
        and parsed
        and public_origin
        and parsed.scheme == "https"
        and parsed.hostname
        and public_origin.scheme == "https"
        and public_origin.hostname
        and redirect_origin == canonical_origin
        and public_origin.path.rstrip("/") in {"", "/"}
        and not public_origin.params
        and not public_origin.query
        and not public_origin.fragment
        and not public_origin.username
        and not public_origin.password
        and parsed.path == DISCORD_OAUTH_CALLBACK_PATH
        and not parsed.params
        and not parsed.query
        and not parsed.fragment
        and not parsed.username
        and not parsed.password
    ):
        return None
    return {
        "clientId": client_id,
        "clientSecret": client_secret,
        "redirectUri": redirect_uri,
    }


def _discord_oauth_transaction_cookie(value):
    value = str(value or "").lower()
    if not _DISCORD_OAUTH_TRANSACTION_RE.fullmatch(value):
        return ""
    return (
        DISCORD_OAUTH_TRANSACTION_COOKIE + "=" + value
        + "; Path=" + DISCORD_OAUTH_CALLBACK_PATH
        + "; Max-Age=600; HttpOnly; Secure; SameSite=Lax"
    )


def _clear_discord_oauth_transaction_cookie():
    return (
        DISCORD_OAUTH_TRANSACTION_COOKIE + "=; Path="
        + DISCORD_OAUTH_CALLBACK_PATH
        + "; Max-Age=0; HttpOnly; Secure; SameSite=Lax"
    )


def _discord_snowflake(value):
    value = str(value or "").strip()
    return value if _DISCORD_SNOWFLAKE_RE.fullmatch(value) else ""


def _discord_api_path_allowed(method, path):
    if method == "GET":
        return (
            bool(_DISCORD_GUILD_PATH_RE.fullmatch(path))
            or bool(_DISCORD_GUILD_CHANNELS_PATH_RE.fullmatch(path))
            or bool(_DISCORD_GUILD_ROLES_PATH_RE.fullmatch(path))
            or bool(_DISCORD_CHANNEL_MESSAGES_GET_PATH_RE.fullmatch(path))
        )
    return (
        method == "POST"
        and bool(_DISCORD_CHANNEL_MESSAGES_POST_PATH_RE.fullmatch(path))
    )


def _discord_rate_major(path):
    match = re.match(r"^/(guilds|channels)/([0-9]{17,20})(?:[/?]|$)", str(path or ""))
    return (match.group(1) + ":" + match.group(2)) if match else "global"


def _discord_rate_route(path):
    return re.sub(r"[0-9]{17,20}", ":id", str(path or "")).split("?", 1)[0]


async def _discord_provider_request(env, method, path, body=None):
    """Perform one fixed-shape Discord provider request inside the rate DO.

    No caller-provided origin/path/header reaches this helper.  Error bodies
    and exceptions are deliberately reduced to status + retry metadata before
    crossing the adapter boundary, because provider errors can echo request
    context and must never become a token or message-content diagnostic.
    """

    method = str(method or "").upper()
    path = str(path or "")
    if not _discord_api_path_allowed(method, path):
        return {"status": 400, "data": None, "retryAfterMs": 0}
    token = _discord_bot_token(env)
    if not token:
        return {"status": 0, "data": None, "retryAfterMs": 0}
    now = int(Date.now())
    reserved_for = _discord_rate_coordinator().reserve(path, now)
    if reserved_for:
        return {"status": 429, "data": None, "retryAfterMs": reserved_for}
    headers = {
        "accept": "application/json",
        "authorization": "Bot " + token,
        "user-agent": "ForkMesh-Discord-connector/1.0",
    }
    options = {
        "method": method,
        "headers": headers,
        # Never forward the credential across a provider redirect.
        "redirect": "manual",
    }
    if body is not None:
        if method != "POST" or not isinstance(body, dict):
            return {"status": 400, "data": None, "retryAfterMs": 0}
        headers["content-type"] = "application/json"
        options["body"] = json.dumps(body, separators=(",", ":"))
    try:
        response = await js_fetch_with_timeout(
            DISCORD_API_ORIGIN + path, options, DISCORD_API_TIMEOUT_SECONDS)
        status = int(getattr(response, "status", 0) or 0)
        try:
            announced = int(response.headers.get("content-length") or 0)
        except (AttributeError, TypeError, ValueError, OverflowError):
            announced = 0
        if announced > DISCORD_API_MAX_RESPONSE_BYTES:
            return {"status": 502, "data": None, "retryAfterMs": 0}
        try:
            raw = str(await response.text())
        except Exception:
            return {"status": 502, "data": None, "retryAfterMs": 0}
        if len(raw.encode("utf-8")) > DISCORD_API_MAX_RESPONSE_BYTES:
            return {"status": 502, "data": None, "retryAfterMs": 0}
        try:
            data = json.loads(raw) if raw else None
        except Exception:
            data = None
        # Keep only the narrow rate headers used by the shared coordinator;
        # provider response headers never reach the dashboard or audit trail.
        rate_headers = {}
        for name in (
                "x-ratelimit-bucket", "x-ratelimit-reset-after",
                "x-ratelimit-reset", "x-ratelimit-remaining",
                "x-ratelimit-global", "x-ratelimit-scope",
                "retry-after"):
            try:
                rate_headers[name] = str(response.headers.get(name) or "")
            except Exception:
                rate_headers[name] = ""
        observed_now = int(Date.now())
        coordinated_retry = _discord_rate_coordinator().observe(
            path, status, rate_headers, data, observed_now)
        retry_after = 0
        try:
            retry_after = int(float(response.headers.get("retry-after") or 0) * 1000)
        except (AttributeError, TypeError, ValueError, OverflowError):
            retry_after = 0
        if not retry_after and isinstance(data, dict):
            try:
                retry_after = int(float(data.get("retry_after") or 0) * 1000)
            except (TypeError, ValueError, OverflowError):
                retry_after = 0
        return {
            "status": max(0, min(599, status)),
            "data": data,
            "retryAfterMs": max(
                max(0, min(retry_after, 3_600_000)), coordinated_retry),
            # Internal-only metadata consumed by ForkMeshDiscordGate. The
            # outer adapter strips these fields before returning to policy.
            "rateBucket": rate_headers.get("x-ratelimit-bucket", "")[:100],
            "rateGlobal": bool(
                rate_headers.get("x-ratelimit-global")
                or rate_headers.get("x-ratelimit-scope") == "global"
                or (isinstance(data, dict) and data.get("global"))),
        }
    except Exception:
        return {"status": 0, "data": None, "retryAfterMs": 0}


async def _discord_api_request(env, method, path, body=None):
    """Route every production bot call through one global Durable Object."""

    method = str(method or "").upper()
    path = str(path or "")
    if (
        not _discord_api_path_allowed(method, path)
        or (body is not None and (method != "POST" or not isinstance(body, dict)))
    ):
        return {"status": 400, "data": None, "retryAfterMs": 0}
    try:
        gate_id = env.FORKMESH_DISCORD_GATE.idFromName("bot-rate-v1")
        gate = env.FORKMESH_DISCORD_GATE.get(gate_id)
        request = JsRequest.new(
            "https://forkmesh.internal/discord-gate/request",
            to_js({
                "method": "POST",
                "headers": {"content-type": "application/json"},
                "body": json.dumps({
                    "method": method,
                    "path": path,
                    "body": body,
                }, separators=(",", ":")),
            }),
        )
        _cron_subrequest_charge()
        response = await gate.fetch(request)
        raw = str(await response.text())
        result = json.loads(raw) if raw else {}
        if not isinstance(result, dict):
            raise ValueError("invalid Discord gate response")
        return {
            "status": max(0, min(599, int(result.get("status") or 0))),
            "data": result.get("data"),
            "retryAfterMs": max(
                0, min(3_600_000, int(result.get("retryAfterMs") or 0))),
        }
    except Exception:
        # Production and dev both bind the gate. Missing/broken bindings fail
        # closed; the stateless Worker must never bypass the global limiter.
        return {"status": 0, "data": None, "retryAfterMs": 0}


def _discord_oauth_path_allowed(method, path):
    method = str(method or "").upper()
    path = str(path or "")
    return bool(
        (method == "POST" and path == _DISCORD_OAUTH_TOKEN_PATH)
        or (method == "GET" and path in {
            _DISCORD_OAUTH_IDENTITY_PATH,
            _DISCORD_OAUTH_GUILDS_PATH,
        })
    )


async def _discord_oauth_request(env, method, path, form=None, access_token=""):
    """Call one fixed Discord OAuth path without persisting a bearer token."""

    method = str(method or "").upper()
    path = str(path or "")
    if not _discord_oauth_path_allowed(method, path):
        return {"status": 400, "data": None}
    headers = {
        "accept": "application/json",
        "user-agent": "ForkMesh-Discord-oauth/1.0",
    }
    options = {
        "method": method,
        "headers": headers,
        # OAuth bearer credentials must never cross a provider redirect.
        "redirect": "manual",
    }
    if method == "POST":
        if not isinstance(form, dict):
            return {"status": 400, "data": None}
        headers["content-type"] = "application/x-www-form-urlencoded"
        options["body"] = urlencode(form)
    else:
        token = str(access_token or "")
        if not token or len(token) > 4096 or any(
                not char.isprintable() or char.isspace() for char in token):
            return {"status": 400, "data": None}
        headers["authorization"] = "Bearer " + token
    try:
        response = await js_fetch_with_timeout(
            DISCORD_OAUTH_API_ORIGIN + path, options,
            DISCORD_API_TIMEOUT_SECONDS)
        status = int(getattr(response, "status", 0) or 0)
        try:
            announced = int(response.headers.get("content-length") or 0)
        except (AttributeError, TypeError, ValueError, OverflowError):
            announced = 0
        if announced > DISCORD_API_MAX_RESPONSE_BYTES:
            return {"status": 502, "data": None}
        try:
            raw = str(await response.text())
        except Exception:
            return {"status": 502, "data": None}
        if len(raw.encode("utf-8")) > DISCORD_API_MAX_RESPONSE_BYTES:
            return {"status": 502, "data": None}
        try:
            data = json.loads(raw) if raw else None
        except Exception:
            data = None
        return {"status": max(0, min(599, status)), "data": data}
    except Exception:
        return {"status": 0, "data": None}


