async def ad_network_handler(env, request, path):
    # The two public reads (policy, serve) carry no viewer input beyond the
    # product surface, so one edge-cached body per colo answers every visitor
    # and D1 is read once per surface per SERVE_CACHE_SECONDS. A mutation
    # drops this colo's serve entries; other colos catch up on their TTL.
    runtime = _WorldCommunityRuntime(env, request)
    method = runtime.method()
    cache_key = ad_network.edge_cache_key(
        method, path, runtime.query_params())
    if cache_key:
        cached = await edge_cache_match(cache_key)
        if cached is not None:
            return cached
    response = await ad_network.handle(runtime, path)
    status = int(getattr(response, "status", 0) or 0)
    if cache_key and status == 200:
        await edge_cache_put(cache_key, response)
    elif 200 <= status < 300:
        for stale_key in ad_network.edge_cache_purge_keys(method, path):
            await edge_cache_delete(stale_key)
    return response


orgs_handler = _route_handlers.export("orgs_handler")


# --- Desktop-signed organization management (adhoc #204) -------------------
# The desktop's Settings -> Organizations tab mirrors the website's
# organization panel, but the ordinary desktop launch is
# authenticateSilently(): it proves this install holds the account's Ed25519
# key and mints no session token at all. Without a signed form of these
# requests the whole tab would answer "sign in" to the very owner of the
# organization — the same gap ORG_TASK_LIST_PROOF closed for the Tasks board.
#
# Discipline unchanged from _org_task_signed_session: one proof prefix per
# operation, the canonical binds the resource path AND every body field that
# decides what the write does, and a signed write's body may carry nothing
# else — so a captured proof can never be replayed as a different edit. A
# signature says only WHO is asking; every handler still runs its own
# owner/admin authorization against the resolved account.
ORG_ADMIN_LIST_PROOF = "forkmesh-org-admin-list-v1"
ORG_ADMIN_CREATE_PROOF = "forkmesh-org-admin-create-v1"
ORG_ADMIN_READ_PROOF = "forkmesh-org-admin-read-v1"
ORG_ADMIN_PROFILE_PROOF = "forkmesh-org-admin-profile-v1"
ORG_ADMIN_DELETE_PROOF = "forkmesh-org-admin-delete-v1"
ORG_ADMIN_MEMBER_SET_PROOF = "forkmesh-org-admin-member-set-v1"
ORG_ADMIN_MEMBER_REMOVE_PROOF = "forkmesh-org-admin-member-remove-v1"
ORG_ADMIN_TEAM_SET_PROOF = "forkmesh-org-admin-team-set-v1"
ORG_ADMIN_TEAM_REMOVE_PROOF = "forkmesh-org-admin-team-remove-v1"
ORG_ADMIN_TEAM_MEMBER_ADD_PROOF = "forkmesh-org-admin-team-member-add-v1"
ORG_ADMIN_TEAM_MEMBER_REMOVE_PROOF = (
    "forkmesh-org-admin-team-member-remove-v1")
ORG_ADMIN_REPO_LINK_PROOF = "forkmesh-org-admin-repo-link-v1"
ORG_ADMIN_REPO_UNLINK_PROOF = "forkmesh-org-admin-repo-unlink-v1"


def _org_admin_operation(method, path):
    """(proof prefix, signed body fields) for one organization request.

    "" for anything the account key may not sign for: the world-access,
    federation, Discord, succession and bot-token subresources are deliberately
    absent, so this credential can only ever do what the desktop panel does.
    """
    if ORGS_RE.match(path):
        if method == "GET":
            return ORG_ADMIN_LIST_PROOF, ()
        if method == "POST":
            return (ORG_ADMIN_CREATE_PROOF,
                    ("name", "displayName", "description"))
        return "", ()
    if ORG_MEMBERS_RE.match(path):
        if method == "GET":
            return ORG_ADMIN_READ_PROOF, ()
        if method == "POST":
            return ORG_ADMIN_MEMBER_SET_PROOF, ("member", "role")
        if method == "DELETE":
            return ORG_ADMIN_MEMBER_REMOVE_PROOF, ("member",)
        return "", ()
    if ORG_TEAM_MEMBERS_RE.match(path):
        if method == "GET":
            return ORG_ADMIN_READ_PROOF, ()
        if method == "POST":
            return ORG_ADMIN_TEAM_MEMBER_ADD_PROOF, ("member", "external")
        if method == "DELETE":
            return ORG_ADMIN_TEAM_MEMBER_REMOVE_PROOF, ("member",)
        return "", ()
    if ORG_TEAMS_RE.match(path):
        if method == "GET":
            return ORG_ADMIN_READ_PROOF, ()
        if method == "POST":
            return ORG_ADMIN_TEAM_SET_PROOF, ("team", "permission")
        if method == "DELETE":
            return ORG_ADMIN_TEAM_REMOVE_PROOF, ("team",)
        return "", ()
    if ORG_REPOS_RE.match(path):
        if method == "GET":
            return ORG_ADMIN_READ_PROOF, ()
        if method == "POST":
            return ORG_ADMIN_REPO_LINK_PROOF, ("repo", "node")
        if method == "DELETE":
            return ORG_ADMIN_REPO_UNLINK_PROOF, ("repo",)
        return "", ()
    if ORG_RE.match(path):
        if method == "GET":
            return ORG_ADMIN_READ_PROOF, ()
        if method == "PATCH":
            return ORG_ADMIN_PROFILE_PROOF, ("displayName", "description")
        if method == "DELETE":
            return ORG_ADMIN_DELETE_PROOF, ()
        return "", ()
    return "", ()


# Longest body field bound into a canonical. Every field the panel sends is
# shorter (a description caps at 500 in the handler too), so this only bounds
# what a hostile body can make the worker hash.
ORG_ADMIN_FIELD_MAX = 500


def _org_admin_canonical_field(value):
    """One body field as it appears in the signed canonical, or None.

    The canonical is newline-delimited, so a field carrying a control
    character could shift the field boundaries and make two different writes
    hash identically ("display\\nx" + "y" reads exactly like "display" +
    "x\\ny"). Such values are simply unsignable: the desktop panel types every
    one of them into a single-line field.
    """
    if value is True:
        return "true"
    if value is False or value is None:
        return ""
    if not isinstance(value, str):
        return None
    text = value[:ORG_ADMIN_FIELD_MAX]
    return None if any(ch < " " for ch in text) else text


def _org_admin_signed_triple(request):
    """True when this URL carries a desktop node/ts/sig triple."""
    try:
        params = parse_qs(urlparse(request.url).query)
    except Exception:
        return False
    return bool(
        clean_string(params.get("node", [""])[0], MAX_NODE_NAME)
        and clean_string(params.get("ts", [""])[0], 20)
        and clean_string(params.get("sig", [""])[0], 200))


async def _org_admin_signed_session(env, request, data=None):
    """Resolve the account behind a key-signed organization request."""
    method = method_name(request)
    url = urlparse(request.url)
    proof, fields = _org_admin_operation(method, url.path)
    if not proof:
        return "", None
    params = parse_qs(url.query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    if not node or not sig or not _ts_ok(ts):
        return "", None
    body = data if isinstance(data, dict) else {}
    if method in UNVERIFIED_SAFE_METHODS:
        # A read signs the path only; a body would be unsigned payload.
        if body:
            return "", None
    elif set(body) - {"sessionToken"} != set(fields):
        return "", None
    canonical = proof + "\n" + node + "\n" + url.path + "\n"
    for name in fields:
        signed = _org_admin_canonical_field(body.get(name))
        if signed is None:
            return "", None
        canonical += signed + "\n"
    canonical += str(ts)
    # Every key the account may sign as, not just its primary pubkey: a
    # password login registers THIS machine in account_devices while
    # rec["pubkey"] keeps naming whichever install created the account (adhoc
    # #63). Same gate as the task board and the /api/sync drain.
    if not await _verify_owner_signature(env, node, sig, canonical.encode()):
        return "", None
    account_bi, record = await _account_row(env, node)
    if (
        not account_bi
        or not record
        or record.get("status") != "active"
        or _account_kind(record) != "user"
    ):
        return "", None
    # Same hold-back the website's session path applies: an account with an
    # unconfirmed address on file cannot write, however it proves itself.
    if (
        method not in UNVERIFIED_SAFE_METHODS
        and _account_email_unverified(record)
    ):
        raise RuntimeError(UNVERIFIED_EMAIL_ERROR)
    return account_bi, record


async def _org_management_session(env, request, data=None):
    """The account behind one organization request, session or key signed.

    Once a triple is on the URL it is the only credential considered: never
    fall through to the cookie, or a cross-site request could have the origin
    check waived by appending a junk signature and still authenticate as the
    victim.
    """
    if _org_admin_signed_triple(request):
        return await _org_admin_signed_session(env, request, data)
    return await _account_session_record(
        env, request, data if isinstance(data, dict) else None)


async def org_handler(env, request, org):
    # GET: public org profile (identity, counts, linked repos — the same
    # visibility as the public account lookup). DELETE: dissolve the org and
    # all its rows — org owners only.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if method == "GET":
        rec = await decrypt_row(env, row.get("data")) or {}
        members = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=?", org_bi)
        teams = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_teams WHERE org_bi=?", org_bi)
        repos = await d1_all(
            env,
            "SELECT repo, node_owner FROM org_repos WHERE org_bi=? ORDER BY repo",
            org_bi)
        _, viewer_rec = await _org_management_session(env, request)
        viewer = (viewer_rec.get("name", "") if viewer_rec else "").strip().lower()
        viewer_role = await _org_role(env, org_bi, viewer) if viewer else ""
        world_access = _org_world_access(rec.get("worldAccess"))
        floors_visible = _org_world_access_allowed(
            world_access["floors"], viewer_role)
        visible_repos = []
        for linked in (repos or []) if floors_visible else []:
            linked_repo = safe_segment(str(linked.get("repo") or ""))
            node_owner = clean_string(
                linked.get("node_owner") or "", MAX_NODE_NAME).lower()
            if not linked_repo or not node_owner:
                continue
            if await _repo_is_private(env, node_owner, linked_repo):
                allowed = bool(
                    viewer and (
                        viewer == node_owner
                        or await _account_owns_node(
                            env, viewer, node_owner)
                        or await _repo_shared_with(
                            env, node_owner, linked_repo, viewer)
                    )
                )
                if not allowed:
                    continue
            visible_repos.append({"repo": linked_repo, "node": node_owner})
        return json_response({
            "ok": True,
            "org": str(row.get("name") or ""),
            "displayName": rec.get("displayName", ""),
            "description": rec.get("description", ""),
            "logoUrl": _org_logo_url(rec.get("logoUrl", "")),
            "worldAccess": world_access,
            "worldCapabilities": {
                "lobby": _org_world_access_allowed(
                    world_access["lobby"], viewer_role),
                "floors": floors_visible,
                "offices": _org_world_access_allowed(
                    world_access["offices"], viewer_role),
            },
            "createdAt": int(row.get("created_at") or 0),
            "members": int((members or {}).get("n") or 0),
            "teams": int((teams or {}).get("n") or 0),
            "repos": visible_repos,
            "viewerRole": viewer_role,
        }, cache_control="no-store")
    if method == "PATCH":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        _, account_rec = await _org_management_session(
            env, request, data)
        account = (
            account_rec.get("name", "") if account_rec else ""
        ).strip().lower()
        role = await _org_role(env, org_bi, account) if account else ""
        if not _org_rbac.org_role_allows(
                role, "organization.settings.write"):
            return json_response({"error": "forbidden"}, status=403)
        rec = await decrypt_row(env, row.get("data")) or {}
        if "displayName" in data:
            rec["displayName"] = clean_string(
                data.get("displayName", ""), 80)
        if "description" in data:
            rec["description"] = clean_string(
                data.get("description", ""), 500)
        if "logoUrl" in data:
            logo = _org_logo_url(data.get("logoUrl", ""))
            if str(data.get("logoUrl") or "").strip() and not logo:
                return json_response({"error": "invalid_logo_url"}, status=400)
            rec["logoUrl"] = logo
        if "worldAccess" in data:
            if not isinstance(data.get("worldAccess"), dict):
                return json_response(
                    {"error": "invalid_world_access"}, status=400)
            supplied = data["worldAccess"]
            if any(
                str(supplied.get(field) or "").strip().lower()
                not in ORG_WORLD_ACCESS_VALUES
                for field in ("lobby", "floors", "offices")
            ):
                return json_response(
                    {"error": "invalid_world_access"}, status=400)
            rec["worldAccess"] = _org_world_access(
                supplied, rec.get("worldAccess"))
        await d1_run(
            env, "UPDATE orgs SET data=? WHERE org_bi=?",
            await encrypt_row(env, rec), org_bi)
        await _audit_sensitive_action(
            env, account, "organization_world_settings_update",
            "organization", str(row.get("name") or ""),
            outcome="success",
            details={
                "logoChanged": "logoUrl" in data,
                "accessChanged": "worldAccess" in data,
            })
        return json_response({
            "ok": True,
            "org": str(row.get("name") or ""),
            "logoUrl": _org_logo_url(rec.get("logoUrl", "")),
            "worldAccess": _org_world_access(rec.get("worldAccess")),
        }, cache_control="no-store")
    if method == "DELETE":
        try:
            data = await bounded_json_request(request)
        except Exception:
            data = {}
        _, account_rec = await _org_management_session(
            env, request, data)
        account = (account_rec.get("name", "") if account_rec else "").strip().lower()
        if not account:
            return json_response({"error": "invalid_session"}, status=401)
        if not _org_rbac.org_role_allows(
                await _org_role(env, org_bi, account),
                "organization.dissolve"):
            await _audit_sensitive_action(
                env, account, "organization.delete", "organization",
                str(row.get("name") or org), "denied",
                {"reason": "owner_role_required"})
            return json_response({"error": "forbidden"}, status=403)
        try:
            linked = await d1_all(
                env, "SELECT repo FROM org_repos WHERE org_bi=?", org_bi)
            for linked_repo in linked or []:
                scope = str(org).lower() + "/" + str(
                    linked_repo.get("repo") or "").lower()
                await d1_run(
                    env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
                    await _ap_digest_scope_bi(env, scope))
            await d1_run(env, "DELETE FROM org_repos WHERE org_bi=?", org_bi)
            await d1_run(
                env, "DELETE FROM org_team_members WHERE org_bi=?", org_bi)
            await d1_run(
                env, "DELETE FROM org_team_collaborators WHERE org_bi=?",
                org_bi)
            await d1_run(env, "DELETE FROM org_teams WHERE org_bi=?", org_bi)
            # Disconnect all Discord connector material before the deterministic
            # org id can ever be reused. This includes encrypted consent and
            # one-time OAuth state, so recreating an alias cannot inherit a
            # former organization's external bridge.
            await d1_run(
                env, "DELETE FROM organization_discord_connectors WHERE org_bi=?",
                org_bi)
            # The setup-task marker is the authoritative scope for the
            # connector's human-action tasks. Remove every dependent record
            # before the task rows themselves so a deleted organization cannot
            # leave orphaned check-ins, QA verdicts, replies, or attachments.
            await d1_run(
                env, "DELETE FROM organization_task_checkins WHERE task_id IN "
                "(SELECT task_id FROM organization_discord_setup_tasks "
                "WHERE org_bi=?)",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_task_qa_reviews WHERE task_id IN "
                "(SELECT task_id FROM organization_discord_setup_tasks "
                "WHERE org_bi=?)",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_task_responses WHERE task_id IN "
                "(SELECT task_id FROM organization_discord_setup_tasks "
                "WHERE org_bi=?)",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_task_attachments WHERE task_id IN "
                "(SELECT task_id FROM organization_discord_setup_tasks "
                "WHERE org_bi=?)",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_tasks WHERE task_id IN "
                "(SELECT task_id FROM organization_discord_setup_tasks "
                "WHERE org_bi=?)",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_discord_setup_tasks WHERE org_bi=?",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_discord_oauth_grants WHERE org_bi=?",
                org_bi)
            await d1_run(
                env, "DELETE FROM organization_discord_oauth_states WHERE org_bi=?",
                org_bi)
            # Package-owned organization data participates in the same delete:
            # purge rows, remove install receipts, and reverse the package
            # schema after its final organization disappears.
            await plugin_data.purge_org(_PluginPurgeRuntime(env), org_bi)
            await d1_run(env, "DELETE FROM org_members WHERE org_bi=?", org_bi)
            await d1_run(
                env, "DELETE FROM ap_org_digest_settings WHERE org_bi=?", org_bi)
            await d1_run(env, "DELETE FROM orgs WHERE org_bi=?", org_bi)
        except Exception:
            await _audit_sensitive_action(
                env, account, "organization.delete", "organization",
                str(row.get("name") or org), "failed",
                {"reason": "mutation_error"})
            raise
        _ORG_ALIAS_MEMO.clear()
        if linked:
            # Its aliases fed the anonymous catalog's logicalOwners.
            await purge_catalog_related_caches()
            await schedule_public_catalog_republish(
                env,
                include_flagship=any(
                    str(item.get("repo") or "").lower() == "forkmesh"
                    for item in linked),
            )
        await _audit_sensitive_action(
            env, account, "organization.delete", "organization",
            str(row.get("name") or org), "success",
            {"linkedRepositories": len(linked or [])})
        return json_response({"ok": True, "org": str(row.get("name") or ""),
                              "deleted": True})
    return json_response({"error": "method_not_allowed"}, status=405)


async def org_members_handler(env, request, org):
    # GET: role-gated office roster according to the organization's world
    # visibility policy. POST: add an account or change its role — this is the
    # "invite": the new member is notified, like a repo share. DELETE: remove
    # a member. Writes require an owner/admin session; only owners may grant,
    # demote, or remove owners/admins, and the last owner can never leave.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    if method == "GET":
        _, viewer_rec = await _org_management_session(env, request)
        viewer = (
            viewer_rec.get("name", "") if viewer_rec else ""
        ).strip().lower()
        viewer_role = (
            await _org_role(env, org_bi, viewer) if viewer else "")
        org_rec = await decrypt_row(env, row.get("data")) or {}
        access = _org_world_access(org_rec.get("worldAccess"))
        if not _org_world_access_allowed(
                access["offices"], viewer_role):
            return json_response({"error": "forbidden"}, status=403)
        if not _org_rbac.org_role_allows(
                viewer_role, "organization.roster.read"):
            # A public office hallway does not let an organization expose each
            # member's profile on that person's behalf. Anonymous visitors and
            # guests get an aggregate only; named office cards remain
            # insider-visible.
            count = await d1_first(
                env,
                "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=?",
                org_bi,
            )
            return json_response({
                "ok": True,
                "visibility": "public-redacted",
                "memberCount": int((count or {}).get("n") or 0),
                "members": [],
            }, cache_control="no-store")
        rows = await d1_all(
            env,
            "SELECT name, role, created_at FROM org_members WHERE org_bi=? "
            "ORDER BY created_at ASC",
            org_bi)
        # Each member's team list rides along so a roster reader never has to
        # fan out one request per team. This is the same org-internal layout
        # the per-team member listing already shows any member.
        team_rows = await d1_all(
            env,
            "SELECT name, team FROM org_team_members WHERE org_bi=? "
            "ORDER BY team ASC",
            org_bi)
        teams_by_member = {}
        for r in team_rows or []:
            teams_by_member.setdefault(
                str(r.get("name") or ""), []).append(str(r.get("team") or ""))
        hidden_members = globals().get("_org_internal_members")
        hidden = (await hidden_members(
            env, org_name, [str(r.get("name") or "") for r in rows or []])
            if callable(hidden_members) else set())
        shown_rows = [r for r in rows or []
                      if str(r.get("name") or "") not in hidden]
        name_cases = {}
        for r in shown_rows:
            member_name = str(r.get("name") or "")
            name_cases[member_name] = (
                await _account_name_case(env, member_name) or member_name)
        return json_response({"ok": True, "visibility": access["offices"],
                              "members": [
            {"name": str(r.get("name") or ""),
             "nameCase": name_cases.get(str(r.get("name") or ""), ""),
             "role": str(r.get("role") or ""),
             "since": int(r.get("created_at") or 0),
             "teams": teams_by_member.get(str(r.get("name") or ""), [])}
            for r in shown_rows]},
            cache_control="no-store")
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _org_management_session(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    member = clean_string(data.get("member", ""), MAX_NODE_NAME).lower()
    caller_role = await _org_role(env, org_bi, account)
    if not _org_rbac.org_role_allows(
            caller_role, "organization.members.manage"):
        await _audit_sensitive_action(
            env, account,
            "organization.member_remove"
            if method == "DELETE" else "organization.member_change",
            "organization_member", org_name + "/" + member, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not member:
        return json_response({"error": "member_required"}, status=400)
    member_bi = await blind_index(env, member)
    existing = await d1_first(
        env, "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
        org_bi, member_bi)
    existing_role = str((existing or {}).get("role") or "")

    if method == "DELETE":
        if not existing:
            return json_response({"error": "not_found"}, status=404)
        if not _org_rbac.org_role_can_remove(caller_role, existing_role):
            await _audit_sensitive_action(
                env, account, "organization.member_remove",
                "organization_member", org_name + "/" + member, "denied",
                {"reason": "owner_role_required",
                 "existingRole": existing_role})
            return json_response({"error": "forbidden"}, status=403)
        if existing_role == "owner" and await _org_owner_count(env, org_bi) <= 1:
            await _audit_sensitive_action(
                env, account, "organization.member_remove",
                "organization_member", org_name + "/" + member, "denied",
                {"reason": "last_owner"})
            return json_response({"error": "last_owner"}, status=400)
        try:
            await d1_run(
                env,
                "DELETE FROM org_team_members WHERE org_bi=? AND member_bi=?",
                org_bi, member_bi)
            await d1_run(
                env, "DELETE FROM org_members WHERE org_bi=? AND member_bi=?",
                org_bi, member_bi)
        except Exception:
            await _audit_sensitive_action(
                env, account, "organization.member_remove",
                "organization_member", org_name + "/" + member, "failed",
                {"reason": "mutation_error",
                 "existingRole": existing_role})
            raise
        await _audit_sensitive_action(
            env, account, "organization.member_remove",
            "organization_member", org_name + "/" + member, "success",
            {"existingRole": existing_role})
        return json_response({"ok": True, "member": member, "removed": True})

    role = clean_string(data.get("role", "member"), 12).lower() or "member"
    if role not in ORG_ROLES:
        return json_response({"error": "bad_role"}, status=400)
    # Only owners hand out (or take away) the administrative roles.
    if not _org_rbac.org_role_can_assign(caller_role, role, existing_role):
        await _audit_sensitive_action(
            env, account, "organization.role_change",
            "organization_member", org_name + "/" + member, "denied",
            {"reason": "owner_role_required", "role": role,
             "existingRole": existing_role})
        return json_response({"error": "forbidden"}, status=403)
    if (existing_role == "owner" and role != "owner" and
            await _org_owner_count(env, org_bi) <= 1):
        await _audit_sensitive_action(
            env, account, "organization.role_change",
            "organization_member", org_name + "/" + member, "denied",
            {"reason": "last_owner", "role": role,
             "existingRole": existing_role})
        return json_response({"error": "last_owner"}, status=400)
    _, member_rec = await _account_row(env, member)
    if not member_rec:
        return json_response({"error": "unknown_account"}, status=404)
    if not existing:
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=?", org_bi)
        if count_row and int(count_row.get("n") or 0) >= MAX_ORG_MEMBERS:
            return json_response({"error": "too_many_members"}, status=429)
    audit_action = (
        "organization.role_change"
        if existing else "organization.member_add")
    try:
        await d1_run(
            env,
            "INSERT INTO org_members "
            "(org_bi, member_bi, role, name, created_at) "
            "VALUES (?,?,?,?,?) ON CONFLICT(org_bi, member_bi) DO UPDATE SET "
            "role=excluded.role",
            org_bi, member_bi, role, member, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action,
            "organization_member", org_name + "/" + member, "failed",
            {"reason": "mutation_error", "role": role,
             "existingRole": existing_role})
        raise
    await _audit_sensitive_action(
        env, account, audit_action,
        "organization_member", org_name + "/" + member, "success",
        {"role": role, "existingRole": existing_role})
    if not existing:
        await enqueue_notification(
            env, member, "org_invite",
            account + " added you to the " + org_name + " organization",
            body="Your role: " + role + ".",
            actor=account, source="org",
            dedupe="org-member:" + org_name + ":" + member)
    return json_response({"ok": True, "member": member, "role": role})


async def _org_owner_count(env, org_bi):
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=? AND role='owner'",
        org_bi)
    return int((row or {}).get("n") or 0)


async def org_teams_handler(env, request, org):
    # Teams: named member subsets holding one repository permission over the
    # org's linked repos. GET lists them (org members only — the permission
    # layout is org-internal); POST creates a team or updates its permission;
    # DELETE removes a team. Writes require an owner/admin session.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    if method == "GET":
        _, viewer_rec = await _org_management_session(env, request)
        viewer = (viewer_rec.get("name", "") if viewer_rec else "").strip().lower()
        viewer_role = (
            await _org_role(env, org_bi, viewer) if viewer else "")
        org_rec = await decrypt_row(env, row.get("data")) or {}
        access = _org_world_access(org_rec.get("worldAccess"))
        if not _org_world_access_allowed(
                access["floors"], viewer_role):
            return json_response({"error": "forbidden"}, status=403)
        rows = await d1_all(
            env,
            "SELECT t.team AS team,t.permission AS permission,"
            "(SELECT COUNT(*) FROM org_team_members m "
            " WHERE m.org_bi=t.org_bi AND m.team=t.team)+"
            "(SELECT COUNT(*) FROM org_team_collaborators c "
            " WHERE c.org_bi=t.org_bi AND c.team=t.team) AS members "
            "FROM org_teams t WHERE t.org_bi=? ORDER BY t.team",
            org_bi)
        return json_response({"ok": True, "visibility": access["floors"],
                              "teams": [
            {"team": str(r.get("team") or ""),
             "permission": str(r.get("permission") or ""),
             "members": int(r.get("members") or 0)}
            for r in rows or []]}, cache_control="no-store")
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _org_management_session(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    team = clean_string(data.get("team", ""), MAX_NODE_NAME).lower()
    if not _org_rbac.org_role_allows(
            await _org_role(env, org_bi, account),
            "organization.teams.manage"):
        await _audit_sensitive_action(
            env, account,
            "organization.team_delete"
            if method == "DELETE" else "organization.team_change",
            "organization_team", org_name + "/" + team, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not valid_node_name(team):
        return json_response({"error": "invalid_team_name"}, status=400)
    if method == "DELETE":
        try:
            await d1_run(
                env, "DELETE FROM org_team_members WHERE org_bi=? AND team=?",
                org_bi, team)
            await d1_run(
                env,
                "DELETE FROM org_team_collaborators "
                "WHERE org_bi=? AND team=?",
                org_bi, team)
            await d1_run(
                env, "DELETE FROM org_teams WHERE org_bi=? AND team=?",
                org_bi, team)
        except Exception:
            await _audit_sensitive_action(
                env, account, "organization.team_delete",
                "organization_team", org_name + "/" + team, "failed",
                {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, account, "organization.team_delete",
            "organization_team", org_name + "/" + team, "success")
        return json_response({"ok": True, "team": team, "deleted": True})
    permission = clean_string(data.get("permission", "read"), 12).lower() or "read"
    if permission not in TEAM_PERMISSIONS:
        return json_response({"error": "bad_permission"}, status=400)
    existing = await d1_first(
        env, "SELECT 1 AS one FROM org_teams WHERE org_bi=? AND team=?",
        org_bi, team)
    if not existing:
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_teams WHERE org_bi=?", org_bi)
        if count_row and int(count_row.get("n") or 0) >= MAX_ORG_TEAMS:
            return json_response({"error": "too_many_teams"}, status=429)
    audit_action = (
        "organization.team_permission_change"
        if existing else "organization.team_create")
    try:
        await d1_run(
            env,
            "INSERT INTO org_teams (org_bi, team, permission, created_at) "
            "VALUES (?,?,?,?) ON CONFLICT(org_bi, team) DO UPDATE SET "
            "permission=excluded.permission",
            org_bi, team, permission, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action,
            "organization_team", org_name + "/" + team, "failed",
            {"reason": "mutation_error", "permission": permission})
        raise
    await _audit_sensitive_action(
        env, account, audit_action,
        "organization_team", org_name + "/" + team, "success",
        {"permission": permission})
    return json_response({"ok": True, "team": team, "permission": permission})


async def org_team_members_handler(env, request, org, team):
    # Who is on one team. GET is org-member visible; POST adds an EXISTING org
    # member to the team (team membership can only ever raise a member's
    # permission, never smuggle in an outsider); DELETE removes. Writes
    # require an owner/admin session.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    team = (team or "").strip().lower()
    team_row = await d1_first(
        env, "SELECT permission FROM org_teams WHERE org_bi=? AND team=?",
        org_bi, team)
    if not team_row:
        return json_response({"error": "not_found"}, status=404)
    if method == "GET":
        _, viewer_rec = await _org_management_session(env, request)
        viewer = (viewer_rec.get("name", "") if viewer_rec else "").strip().lower()
        if not viewer or not _org_rbac.org_role_allows(
                await _org_role(env, org_bi, viewer),
                "organization.roster.read"):
            return json_response({"error": "forbidden"}, status=403)
        rows = await d1_all(
            env,
            "SELECT name,created_at,0 AS external FROM org_team_members "
            "WHERE org_bi=? AND team=? UNION ALL "
            "SELECT name,created_at,1 AS external "
            "FROM org_team_collaborators WHERE org_bi=? AND team=? "
            "ORDER BY created_at ASC",
            org_bi, team, org_bi, team)
        return json_response({
            "ok": True, "team": team,
            "permission": str(team_row.get("permission") or ""),
            "members": [{"name": str(r.get("name") or ""),
                         "since": int(r.get("created_at") or 0),
                         "external": int(r.get("external") or 0) == 1}
                        for r in rows or []]})
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _org_management_session(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    member = clean_string(data.get("member", ""), MAX_NODE_NAME).lower()
    audit_action = (
        "organization.team_member_revoke"
        if method == "DELETE" else "organization.team_member_grant")
    if not _org_rbac.org_role_allows(
            await _org_role(env, org_bi, account),
            "organization.teams.manage"):
        await _audit_sensitive_action(
            env, account, audit_action, "organization_team_member",
            org_name + "/" + team + "/" + member, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not member:
        return json_response({"error": "member_required"}, status=400)
    member_bi = await blind_index(env, member)
    if method == "DELETE":
        try:
            await d1_run(
                env,
                "DELETE FROM org_team_members "
                "WHERE org_bi=? AND team=? AND member_bi=?",
                org_bi, team, member_bi)
            await d1_run(
                env,
                "DELETE FROM org_team_collaborators "
                "WHERE org_bi=? AND team=? AND account_bi=?",
                org_bi, team, member_bi)
        except Exception:
            await _audit_sensitive_action(
                env, account, audit_action, "organization_team_member",
                org_name + "/" + team + "/" + member, "failed",
                {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, account, audit_action, "organization_team_member",
            org_name + "/" + team + "/" + member, "success")
        return json_response({"ok": True, "team": team, "member": member,
                              "removed": True})
    member_role = await _org_role(env, org_bi, member)
    external = data.get("external") is True and not member_role
    if not member_role and not external:
        return json_response({
            "error": "not_a_member",
            "hint": "Set external=true to add a limited team collaborator.",
        }, status=400)
    if external:
        _, member_record = await _account_row(env, member)
        if (
            not member_record
            or member_record.get("status") != "active"
            or _account_kind(member_record) != "user"
        ):
            return json_response(
                {"error": "active_user_required"}, status=400)
    try:
        if external:
            await d1_run(
                env,
                "INSERT OR IGNORE INTO org_team_collaborators "
                "(org_bi,team,account_bi,name,added_by_bi,created_at) "
                "VALUES (?,?,?,?,?,?)",
                org_bi, team, member_bi, member,
                await blind_index(env, account), int(Date.now()))
        else:
            await d1_run(
                env,
                "INSERT OR IGNORE INTO org_team_members "
                "(org_bi, team, member_bi, name, created_at) VALUES (?,?,?,?,?)",
                org_bi, team, member_bi, member, int(Date.now()))
            await d1_run(
                env,
                "DELETE FROM org_team_collaborators "
                "WHERE org_bi=? AND team=? AND account_bi=?",
                org_bi, team, member_bi)
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action, "organization_team_member",
            org_name + "/" + team + "/" + member, "failed",
            {"reason": "mutation_error"})
        raise
    await _audit_sensitive_action(
        env, account, audit_action, "organization_team_member",
        org_name + "/" + team + "/" + member, "success")
    return json_response({"ok": True, "team": team, "member": member,
                          "external": external, "added": True})


async def org_repos_handler(env, request, org):
    # The alias map behind /<org>/<repo> URLs. GET is public routing data.
    # POST links a repo: the caller must be an org owner/admin AND the linked
    # node namespace must be the caller's own account or a node demonstrably
    # owned by that account — you can only bring your own fleet's published
    # repos under an org, so an org can never hijack another node's URL.
    # DELETE unlinks (owner/admin).
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row and method == "GET" and await d1_first(
            env, "SELECT 1 AS one FROM org_repos WHERE org_bi=? LIMIT 1",
            org_bi):
        _user_bi, user_rec = await _account_row(env, (org or "").strip().lower())
        if user_rec and _account_kind(user_rec) == "user":
            row = {"name": (org or "").strip().lower()}
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT repo, node_owner FROM org_repos WHERE org_bi=? ORDER BY repo",
            org_bi)
        # Organization aliases are public routing data only for explicitly
        # public repositories. A linked private repository is omitted unless
        # the signed-in viewer already owns it or has an explicit repo share;
        # org membership alone is not a plaintext/decryption grant.
        _, viewer_rec = await _org_management_session(env, request)
        viewer = (
            str((viewer_rec or {}).get("name") or "").strip().lower())
        visible = []
        for linked in rows or []:
            linked_repo = safe_segment(str(linked.get("repo") or ""))
            node_owner = clean_string(
                linked.get("node_owner") or "", MAX_NODE_NAME).lower()
            if not linked_repo or not node_owner:
                continue
            if await _repo_is_private(env, node_owner, linked_repo):
                allowed = bool(
                    viewer and (
                        viewer == node_owner
                        or await _account_owns_node(
                            env, viewer, node_owner)
                        or await _repo_shared_with(
                            env, node_owner, linked_repo, viewer)
                    )
                )
                if not allowed:
                    continue
            public_record = {"repo": linked_repo, "node": node_owner}
            # The gateway authorizes an organization SSH path by resolving it
            # back to this linked node before checking the allowlist. Publish
            # that stable organization URL here (rather than leaking the
            # backing-node path into the repo page) only when the backing
            # repository is explicitly enabled for SSH.
            ssh_url = _ssh_alias_repository_url(
                env, org_name, node_owner, linked_repo)
            if ssh_url:
                public_record["sshUrl"] = ssh_url
            visible.append(public_record)
        return json_response({"ok": True, "repos": visible},
                             cache_control="no-store")
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _org_management_session(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    repo = safe_segment(clean_string(data.get("repo", ""), MAX_REPO_SEGMENT))
    repo = (repo or "").lower()
    audit_action = (
        "organization.repo_unlink"
        if method == "DELETE" else "organization.repo_link")
    if not _org_rbac.org_role_allows(
            await _org_role(env, org_bi, account),
            "organization.repositories.link"):
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not repo:
        return json_response({"error": "repo_required"}, status=400)
    if method == "DELETE":
        try:
            await d1_run(
                env, "DELETE FROM org_repos WHERE org_bi=? AND repo=?",
                org_bi, repo)
            await d1_run(
                env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
                await _ap_digest_scope_bi(
                    env, str(org).lower() + "/" + repo.lower()))
        except Exception:
            await _audit_sensitive_action(
                env, account, audit_action, "organization_repository",
                org_name + "/" + repo, "failed",
                {"reason": "mutation_error"})
            raise
        _ORG_ALIAS_MEMO.clear()
        # The alias feeds the anonymous catalog's logicalOwners.
        await purge_catalog_related_caches()
        await schedule_public_catalog_republish(env, "", repo)
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "success")
        return json_response({"ok": True, "repo": repo, "linked": False})
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower() or account
    if not await _account_owns_node(env, account, node):
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "denied",
            {"reason": "not_your_node"})
        return json_response({"error": "not_your_node"}, status=403)
    key_bi = await blind_index(env, node + "/" + repo)
    published = await d1_first(
        env, "SELECT 1 AS one FROM repositories WHERE key_bi=?", key_bi)
    if not published:
        return json_response({"error": "unknown_repo"}, status=404)
    existing = await d1_first(
        env, "SELECT 1 AS one FROM org_repos WHERE org_bi=? AND repo=?",
        org_bi, repo)
    if not existing:
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_repos WHERE org_bi=?", org_bi)
        if count_row and int(count_row.get("n") or 0) >= MAX_ORG_REPOS:
            return json_response({"error": "too_many_repos"}, status=429)
    try:
        await d1_run(
            env,
            "INSERT INTO org_repos (org_bi, repo, node_owner, created_at) "
            "VALUES (?,?,?,?) ON CONFLICT(org_bi, repo) DO UPDATE SET "
            "node_owner=excluded.node_owner",
            org_bi, repo, node, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "failed",
            {"reason": "mutation_error"})
        raise
    _ORG_ALIAS_MEMO.clear()
    # The alias feeds the anonymous catalog's logicalOwners.
    await purge_catalog_related_caches()
    await schedule_public_catalog_republish(env, node, repo)
    await _audit_sensitive_action(
        env, account, audit_action, "organization_repository",
        org_name + "/" + repo, "success")
    return json_response({"ok": True, "repo": repo, "node": node,
                          "linked": True})


async def org_fediverse_handler(env, request, org):
    """Org-owner/admin controls for org-alias daily repository digests.

    This endpoint never edits the backing repository's settings. Its `enabled`
    value is an additional AND gate for aliases under this organization, and
    previews include only linked repositories that remain public.
    """
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    _, account_rec = await _account_session_record(env, request, data)
    account = str((account_rec or {}).get("name") or "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    requested_enabled = (
        data.get("enabled")
        if method == "POST" and isinstance(data.get("enabled"), bool)
        else None)
    audit_action = (
        "organization.fediverse_enable"
        if requested_enabled is True
        else "organization.fediverse_disable"
        if requested_enabled is False
        else "organization.fediverse_change")
    org_name = str(row.get("name") or org)
    if not _org_rbac.org_role_allows(
            await _org_role(env, org_bi, account),
            "organization.fediverse.manage"):
        if method == "POST":
            await _audit_sensitive_action(
                env, account, audit_action, "organization",
                org_name, "denied", {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)

    controls = await _ap_org_digest_settings_get(env, org_bi)
    if method == "POST":
        if "enabled" not in data or not isinstance(data.get("enabled"), bool):
            await _audit_sensitive_action(
                env, account, audit_action, "organization",
                org_name, "denied", {"reason": "enabled_required"})
            return json_response({"error": "enabled_required"}, status=400)
        controls = fedi_digest.normalize_controls({
            "enabled": data["enabled"], "preview": False})
        try:
            await d1_run(
                env,
                "INSERT INTO ap_org_digest_settings "
                "(org_bi, data, updated_at) VALUES (?,?,?) "
                "ON CONFLICT(org_bi) DO UPDATE SET "
                "data=excluded.data, updated_at=excluded.updated_at",
                org_bi, json.dumps(controls, separators=(",", ":")),
                int(Date.now()))
        except Exception:
            await _audit_sensitive_action(
                env, account, audit_action, "organization",
                org_name, "failed", {"reason": "settings_mutation_error"})
            raise
        await _audit_sensitive_action(
            env, account, audit_action, "organization",
            org_name, "success",
            {"enabled": bool(controls["enabled"])})
        if not controls["enabled"]:
            try:
                queued_scopes = await d1_all(
                    env,
                    "SELECT repo FROM org_repos WHERE org_bi=? "
                    "ORDER BY repo LIMIT ?",
                    org_bi, MAX_ORG_REPOS)
                for item in queued_scopes or []:
                    scope = str(org).lower() + "/" + str(
                        item.get("repo") or "").lower()
                    await d1_run(
                        env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
                        await _ap_digest_scope_bi(env, scope))
            except Exception:
                await _audit_sensitive_action(
                    env, account, "organization.fediverse_queue_purge",
                    "organization", org_name, "failed",
                    {"reason": "queue_purge_error"})
                raise
            await _audit_sensitive_action(
                env, account, "organization.fediverse_queue_purge",
                "organization", org_name, "success",
                {"linkedScopes": len(queued_scopes or [])})

    linked = await d1_all(
        env,
        "SELECT repo, node_owner FROM org_repos WHERE org_bi=? "
        "ORDER BY repo LIMIT ?",
        org_bi, MAX_ORG_REPOS)
    previews = []
    for item in linked or []:
        repo = clean_string(item.get("repo"), MAX_REPO_SEGMENT).strip()
        source_owner = clean_string(
            item.get("node_owner"), MAX_NODE_NAME).strip().lower()
        if not repo or not source_owner:
            continue
        # Organization membership is not a private-repository content grant.
        # Private links are omitted, exactly like the public org repo list.
        if await _repo_is_private(env, source_owner, repo):
            continue
        owner_settings = await _ap_repo_settings_get(
            env, source_owner, repo)
        preview = await _ap_digest_preview(
            env, str(org).lower() + "/" + repo.lower())
        preview.update({
            "repo": repo,
            "sourceOwner": source_owner,
            "ownerEnabled": bool(
                owner_settings["federate"]
                and owner_settings["broadcastEvents"]),
            "enabled": bool(
                controls["enabled"]
                and owner_settings["federate"]
                and owner_settings["broadcastEvents"]),
        })
        previews.append(preview)
    return json_response({
        "ok": True,
        "org": org_name,
        "controls": controls,
        "repos": previews,
        "ownerBoundary": (
            "Organization controls cannot override repository-owner settings."),
    }, cache_control="no-store")


# --- Admins + email-delivery follow-up --------------------------------------
# A user is "set as administrator" via the users.is_admin column in the DB
# (UPDATE users SET is_admin=1 WHERE username='<user>'). Administrators may
# review failed verification delivery and vouch for a stranded address using
# a signed override. Recipient confirmation and an administrator override are
# recorded separately, so a verified flag never overstates how it was earned.

async def _is_admin_flag(env, name):
    # Admin status lives in the users.is_admin column. Grant it directly in the
    # DB: UPDATE users SET is_admin=1 WHERE username='<user>'.
    name = (name or "").strip().lower()
    if not name:
        return False
    name_bi = await blind_index(env, name)
    try:
        row = await d1_first(
            env, "SELECT is_admin FROM users WHERE user_bi=?", name_bi)
    except Exception:
        return False  # column may predate migration 0006
    return bool(row and int(row.get("is_admin", 0) or 0))


async def _is_admin(env, name):
    if not await _is_admin_flag(env, name):
        return False
    _, rec = await _account_row(env, (name or "").strip().lower())
    return bool(rec and rec.get("totp_enrolled"))


async def _has_role(env, name, role, scope_type="platform", scope=""):
    name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
    role = security_control.normalize_role(role)
    scope_type = security_control.normalize_scope_type(scope_type)
    if not name or not role or not security_control.role_scope_allowed(
            role, scope_type):
        return False
    # Preserve the existing administrator flag as the platform-administrator
    # grant only. It does not imply moderator/security-reviewer/decryption roles.
    if (role == "platform_administrator" and scope_type == "platform"
            and await _is_admin(env, name)):
        return True
    await ensure_schema(env)
    account_bi = await blind_index(env, name)
    scope_bi = (
        await blind_index(env, scope)
        if scope_type != "platform" and scope else ""
    )
    now = int(Date.now())
    row = await d1_first(
        env,
        "SELECT 1 AS one FROM role_grants WHERE account_bi=? AND role=? "
        "AND scope_type=? AND scope_bi=? AND revoked_at=0 "
        "AND (expires_at=0 OR expires_at>?)",
        account_bi, role, scope_type, scope_bi, now,
    )
    return bool(row)


async def _audit_sensitive_action(env, actor, action, target_type="",
                                  target="", outcome="success", details=None):
    """Append a metadata-only record for a sensitive state transition."""
    await ensure_schema(env)
    actor = clean_string(actor or "", MAX_NODE_NAME).strip().lower()
    clean_action = re.sub(
        r"[^a-z0-9_.-]", "", str(action or "").strip().lower())[:100]
    clean_target_type = re.sub(
        r"[^a-z0-9_.-]", "", str(target_type or "").strip().lower())[:40]
    clean_outcome = (
        str(outcome or "unknown").strip().lower()
        if str(outcome or "").strip().lower()
        in ("success", "denied", "failed", "requested") else "unknown"
    )
    actor_bi = await blind_index(env, actor) if actor else None
    target_token = (
        await blind_index(
            env, "audit:" + clean_target_type + ":" + str(target or ""))
        if target else ""
    )
    safe_details = security_control.sanitize_audit_details(details or {})
    await d1_run(
        env,
        "INSERT INTO sensitive_audit_log "
        "(ts, actor_bi, actor_label, action, target_type, target_token, "
        "outcome, details) VALUES (?,?,?,?,?,?,?,?)",
        int(Date.now()), actor_bi, actor, clean_action, clean_target_type,
        target_token, clean_outcome,
        json.dumps(safe_details, sort_keys=True, separators=(",", ":")),
    )


async def security_roles_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    _, actor_rec = await _account_session_record(env, request, data)
    actor = (actor_rec.get("name", "") if actor_rec else "").strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401)
    is_platform_admin = await _has_role(
        env, actor, "platform_administrator")

    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        target = clean_string(
            params.get("target", [actor])[0], MAX_NODE_NAME).strip().lower()
        if target != actor and not is_platform_admin:
            return json_response({"error": "forbidden"}, status=403)
        target_bi, target_rec = await _account_row(env, target)
        if not target_rec:
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        rows = await d1_all(
            env,
            "SELECT role, scope_type, scope_bi, granted_at, expires_at "
            "FROM role_grants WHERE account_bi=? AND revoked_at=0 "
            "AND (expires_at=0 OR expires_at>?) ORDER BY granted_at DESC",
            target_bi, now,
        )
        grants = [{
            "role": security_control.normalize_role(row.get("role")),
            "scopeType": security_control.normalize_scope_type(
                row.get("scope_type")),
            # Scope identifiers are blind indexes. Only the grantee/admin sees
            # the token, and no private repository name is recoverable from it.
            "scopeToken": str(row.get("scope_bi") or ""),
            "grantedAt": int(row.get("granted_at") or 0),
            "expiresAt": int(row.get("expires_at") or 0),
        } for row in rows or [] if security_control.normalize_role(
            row.get("role"))]
        if await _is_admin_flag(env, target):
            grants.append({
                "role": "platform_administrator",
                "scopeType": "platform",
                "scopeToken": "",
                "grantedAt": 0,
                "expiresAt": 0,
                "legacyGrant": True,
            })
        return json_response({
            "ok": True,
            "target": target,
            "grants": grants,
        }, cache_control="no-store")

    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if not is_platform_admin:
        await _audit_sensitive_action(
            env, actor, "role.change", "role", "", "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    target = clean_string(data.get("target", ""), MAX_NODE_NAME).strip().lower()
    role = security_control.normalize_role(data.get("role"))
    scope_type = security_control.normalize_scope_type(
        data.get("scopeType", "platform"))
    scope = clean_string(data.get("scope", ""), 240).strip().lower()
    action = str(data.get("action") or "grant").strip().lower()
    if (not target or not role or not scope_type
            or not security_control.role_scope_allowed(role, scope_type)
            or (scope_type != "platform" and not scope)):
        return json_response({"error": "invalid_role_grant"}, status=400)
    target_bi, target_rec = await _account_row(env, target)
    if not target_rec:
        return json_response({"error": "target_not_found"}, status=404)
    scope_bi = (
        await blind_index(env, scope) if scope_type != "platform" else ""
    )
    now = int(Date.now())
    if action == "revoke":
        await d1_run(
            env,
            "UPDATE role_grants SET revoked_at=? WHERE account_bi=? "
            "AND role=? AND scope_type=? AND scope_bi=?",
            now, target_bi, role, scope_type, scope_bi,
        )
    elif action == "grant":
        try:
            expires_at = int(data.get("expiresAt") or 0)
        except (TypeError, ValueError):
            expires_at = 0
        if expires_at and expires_at <= now:
            return json_response({"error": "invalid_expiration"}, status=400)
        actor_bi = await blind_index(env, actor)
        await d1_run(
            env,
            "INSERT INTO role_grants "
            "(account_bi, role, scope_type, scope_bi, granted_by_bi, "
            "granted_at, expires_at, revoked_at) VALUES (?,?,?,?,?,?,?,0) "
            "ON CONFLICT(account_bi,role,scope_type,scope_bi) DO UPDATE SET "
            "granted_by_bi=excluded.granted_by_bi, "
            "granted_at=excluded.granted_at, "
            "expires_at=excluded.expires_at, revoked_at=0",
            target_bi, role, scope_type, scope_bi, actor_bi, now, expires_at,
        )
    else:
        return json_response({"error": "invalid_action"}, status=400)
    await _audit_sensitive_action(
        env, actor, "role." + action, "account", target, "success",
        {"role": role, "scopeType": scope_type})
    return json_response({
        "ok": True, "action": action, "target": target, "role": role,
        "scopeType": scope_type,
    }, cache_control="no-store")


async def security_audit_handler(env, request):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    _, rec = await _account_session_record(env, request)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor or not await _has_role(
            env, actor, "platform_administrator"):
        return json_response({"error": "forbidden"}, status=403)
    rows = await d1_all(
        env,
        "SELECT ts, actor_label, action, target_type, target_token, "
        "outcome, details FROM sensitive_audit_log "
        "ORDER BY id DESC LIMIT 500",
    )
    events = []
    for row in rows or []:
        try:
            details = json.loads(str(row.get("details") or "{}"))
        except Exception:
            details = {}
        events.append({
            "ts": int(row.get("ts") or 0),
            "actor": str(row.get("actor_label") or ""),
            "action": str(row.get("action") or ""),
            "targetType": str(row.get("target_type") or ""),
            "targetToken": str(row.get("target_token") or ""),
            "outcome": str(row.get("outcome") or ""),
            "details": security_control.sanitize_audit_details(details),
        })
    return json_response({"ok": True, "events": events},
                         cache_control="no-store")


async def cleanup_sensitive_audit_records(env):
    await ensure_schema(env)
    now = int(Date.now())
    await d1_run(
        env, "DELETE FROM sensitive_audit_log WHERE ts<?",
        now - SECURITY_AUDIT_RETAIN_MS)
    await d1_run(
        env, "DELETE FROM org_bot_token_usage WHERE used_at<?",
        now - SECURITY_AUDIT_RETAIN_MS)
    await d1_run(
        env, "DELETE FROM password_reset_rate WHERE window_start_ts<?",
        now - PASSWORD_RESET_ACCOUNT_WINDOW_MS)
    try:
        await prune_security_incidents(env, now)
    except Exception as error:
        if _cron_budget_exhausted():
            raise
        await log_error(env, 500, "CRON", "security/incidents/prune",
                        "Security incident retention failed: "
                        + _safe_error_text(error)[:300])
    return await purge_trashed_organization_tasks(env, now)


async def prune_security_incidents(env, now):
    return await d1_run(
        env,
        "DELETE FROM security_incidents WHERE id IN ("
        "SELECT i.id FROM security_incidents i "
        "WHERE i.created_ms<? "
        "AND (i.severity='info' OR i.created_ms<?) "
        "AND COALESCE(i.severity,'')<>'lockdown' "
        "AND NOT EXISTS (SELECT 1 FROM cluster_quarantine q "
        "WHERE instr(q.body, '\"incident\":\"' || i.id || '\"')>0) "
        "ORDER BY i.created_ms LIMIT ?)",
        now - SECURITY_INCIDENT_INFO_RETAIN_MS,
        now - SECURITY_INCIDENT_RETAIN_MS,
        SECURITY_INCIDENT_PRUNE_BATCH)


async def deliver_task_persistent_reminders(env, now=None):
    try:
        await ensure_schema(env)
        return await world_office_tasks.deliver_persistent_reminders(
            _OfficeMarketingTasksRuntime(env, None),
            int(Date.now()) if now is None else int(now),
        )
    except Exception as error:
        if _cron_budget_exhausted():
            raise
        await log_error(env, 500, "CRON", "organization/tasks/reminders",
                        "Persistent task reminder delivery failed: "
                        + _safe_error_text(error)[:300])
        return {"ok": False}


async def purge_trashed_organization_tasks(env, now=None):
    await ensure_schema(env)
    return await world_office_tasks.purge_trash(
        _OfficeMarketingTasksRuntime(env, None),
        int(Date.now()) if now is None else int(now),
    )


# --- Achievement badges (adhoc #370) -----------------------------------------
# Public recognition marks, similar in shape to org teams: a fixed catalog
# (badges.py) awarded once per account, either automatically at a real
# platform event (see the call sites of _award_badge below) or by a platform
# administrator. Awards are permanent — later losing eligibility does not
# revoke an already-earned badge.
FIRST_100_USERS_LIMIT = 100
DISTINGUISHED_CONTRIBUTOR_SWEEP_LIMIT = 25
BADGE_SWEEP_LIMIT = 25
WORLD_FIRST_HOUR_BADGE_MS = 60 * 60 * 1000
ACTIVITY_BADGE_BY_CONTRIBUTION_KIND = {
    "issues": "qa",
    "pulls": "coder",
    "discussions": "poster",
}


async def _award_contributor_badge(env, author, kind):
    """Persist the first activity badge for a real ForkMesh user.

    contributor_activity deliberately accepts signed events from external node
    identities too. Those rows are useful on repository leaderboards, but only
    a current active user account can receive a personal World badge.
    """
    slug = ACTIVITY_BADGE_BY_CONTRIBUTION_KIND.get(kind, "")
    if not slug:
        return
    try:
        name_bi, rec = await _account_row(env, author)
        if (
            not rec
            or _account_kind(rec) != "user"
            or rec.get("status") != "active"
        ):
            return
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).strip().lower()
        if name:
            await _award_badge(env, name, name_bi, slug)
    except Exception:
        # A leaderboard/account lookup failure must never reject a signed
        # issue, pull request, or discussion event.
        pass


def _d1_changed(result):
    try:
        return int(result.meta.changes) > 0
    except Exception:
        return False


async def _award_badge(env, name, name_bi, slug, granted_by="system", tier=0):
    slug = badge_catalog.normalize_badge_slug(slug)
    if not slug or not name_bi:
        return False
    tiers = badge_catalog.badge_tiers(slug)
    tier = max(0, min(int(tier or 0), len(tiers) - 1)) if tiers else 0
    await ensure_schema(env)
    now = int(Date.now())
    if not tier:
        result = await d1_run(
            env,
            "INSERT OR IGNORE INTO badge_awards "
            "(badge_slug, account_bi, name, granted_by, created_at) "
            "VALUES (?,?,?,?,?)",
            slug, name_bi, name, (granted_by or "system"), now)
    else:
        result = await d1_run(
            env,
            "INSERT OR IGNORE INTO badge_awards "
            "(badge_slug, account_bi, name, granted_by, created_at, tier, "
            "tier_at) VALUES (?,?,?,?,?,?,?)",
            slug, name_bi, name, (granted_by or "system"), now, tier, now)
    inserted = _d1_changed(result)
    upgraded = False
    if not inserted and tier:
        upgraded = _d1_changed(await d1_run(
            env,
            "UPDATE badge_awards SET tier=?, tier_at=? "
            "WHERE badge_slug=? AND account_bi=? AND tier<?",
            tier, now, slug, name_bi, tier))
    if inserted or upgraded:
        try:
            await _send_badge_email(env, name, slug, tier, upgraded)
        except Exception as error:
            print("badge email failed: %s" % _safe_error_text(error)[:160])
        try:
            await _send_badge_ping(env, name, slug, tier, upgraded)
        except Exception as error:
            print("badge ping failed: %s" % _safe_error_text(error)[:160])
    return inserted or upgraded


async def _record_badge_progress(env, name, name_bi, slug, value):
    slug = badge_catalog.normalize_badge_slug(slug)
    if not slug or not name_bi or not badge_catalog.badge_tiers(slug):
        return False
    value = max(0, int(value or 0))
    await ensure_schema(env)
    await d1_run(
        env,
        "INSERT INTO badge_progress (badge_slug, account_bi, value, "
        "updated_at) VALUES (?,?,?,?) "
        "ON CONFLICT(badge_slug, account_bi) DO UPDATE SET "
        "value=MAX(value, excluded.value), updated_at=excluded.updated_at",
        slug, name_bi, value, int(Date.now()))
    tier = badge_catalog.tier_for_value(slug, value)
    if tier < 0:
        return False
    return await _award_badge(env, name, name_bi, slug, tier=tier)


async def _active_user_account(env, name):
    name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name):
        return "", "", None
    name_bi, rec = await _account_row(env, name)
    if (
        not rec
        or _account_kind(rec) != "user"
        or rec.get("status") != "active"
    ):
        return "", "", None
    return name, name_bi, rec


async def _repo_stargazer_count(env, repo_bi, owner_bi):
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM repo_stars "
        "WHERE repo_bi=? AND account_bi<>?",
        repo_bi, owner_bi)
    return int((row or {}).get("n", 0) or 0)


async def _award_stargazer_for_repo(env, owner, repo_bi):
    try:
        name, name_bi, _ = await _active_user_account(env, owner)
        if not name:
            return False
        stars = await _repo_stargazer_count(env, repo_bi, name_bi)
        return await _record_badge_progress(
            env, name, name_bi, "stargazer", stars)
    except Exception as error:
        print("stargazer badge failed: %s" % _safe_error_text(error)[:160])
        return False


async def _award_genies_gift(env, sender, recipient, network, verified):
    if not verified or network != "mainnet":
        return False
    try:
        name, name_bi, _ = await _active_user_account(env, sender)
        if not name or name == str(recipient or "").strip().lower():
            return False
        return await _award_badge(env, name, name_bi, "genies_gift")
    except Exception as error:
        print("genies gift badge failed: %s" % _safe_error_text(error)[:160])
        return False


async def award_stargazer_badges(env):
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT r.owner_bi, u.username, COUNT(*) AS stars "
        "FROM repo_stars s "
        "JOIN repositories r ON r.key_bi=s.repo_bi "
        "JOIN users u ON u.user_bi=r.owner_bi "
        "LEFT JOIN badge_progress p ON p.account_bi=r.owner_bi "
        "AND p.badge_slug=? "
        "WHERE r.is_private=0 AND s.account_bi<>r.owner_bi "
        "GROUP BY s.repo_bi "
        "HAVING COUNT(*)>=? AND COUNT(*)>COALESCE(MAX(p.value), 0) "
        "ORDER BY stars DESC LIMIT ?",
        "stargazer", badge_catalog.badge_tiers("stargazer")[0],
        BADGE_SWEEP_LIMIT)
    awarded = []
    for row in rows or []:
        name, name_bi, _ = await _active_user_account(
            env, row.get("username") or "")
        if not name or name_bi != row.get("owner_bi"):
            continue
        if await _record_badge_progress(
                env, name, name_bi, "stargazer", row.get("stars")):
            awarded.append(name)
    return {"awarded": awarded}


async def award_genies_gift_badges(env):
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT DISTINCT t.from_bi, u.username FROM tip_notice t "
        "JOIN users u ON u.user_bi=t.from_bi "
        "LEFT JOIN badge_awards b ON b.account_bi=t.from_bi "
        "AND b.badge_slug=? "
        "WHERE b.account_bi IS NULL AND t.network='mainnet' "
        "AND t.from_bi<>t.to_bi "
        "AND (t.task_description<>'' OR EXISTS ("
        "SELECT 1 FROM contributor_reward_estimates e "
        "WHERE e.tx_signature=t.signature AND e.status='paid')) "
        "LIMIT ?",
        "genies_gift", BADGE_SWEEP_LIMIT)
    awarded = []
    for row in rows or []:
        name, name_bi, _ = await _active_user_account(
            env, row.get("username") or "")
        if not name or name_bi != row.get("from_bi"):
            continue
        if await _award_badge(env, name, name_bi, "genies_gift"):
            awarded.append(name)
    return {"awarded": awarded}


BADGE_CONTRIBUTION_SOURCES_SQL = (
    "src AS (SELECT p.source_repo_bi, p.active_generation_bi, "
    "ROW_NUMBER() OVER (PARTITION BY p.project_bi "
    "ORDER BY p.captured_at DESC, p.source_repo_bi) AS rk "
    "FROM profile_contribution_projects p "
    "JOIN repositories r ON r.key_bi=p.source_repo_bi "
    "WHERE p.is_public=1 AND r.is_private=0 "
    "AND p.active_generation_bi IS NOT NULL)")

BADGE_CONTRIBUTION_DAYS_SQL = (
    "FROM src s JOIN profile_contribution_days d "
    "ON d.source_repo_bi=s.source_repo_bi "
    "AND d.generation_bi=s.active_generation_bi WHERE s.rk=1")

BADGE_FOREIGN_MERGES_SQL = (
    "FROM badge_pull_facts f "
    "JOIN nodes an ON an.pubkey=f.author_key "
    "JOIN repositories r ON r.key_bi=f.repo_bi "
    "LEFT JOIN nodes rn ON rn.node_bi=r.owner_bi "
    "WHERE f.kind='pull' AND f.merged=1 AND f.author_key<>'' "
    "AND r.is_private=0 "
    "AND COALESCE(NULLIF(an.user_bi, ''), an.node_bi)<>"
    "COALESCE(NULLIF(rn.user_bi, ''), r.owner_bi) GROUP BY 1")

BADGE_METRIC_SQL = {
    "six_eyes": (
        BADGE_CONTRIBUTION_SOURCES_SQL + ", "
        "m AS (SELECT d.subject_user_bi AS account_bi, "
        "SUM(d.reviews) AS value " + BADGE_CONTRIBUTION_DAYS_SQL + " "
        "GROUP BY d.subject_user_bi)"),
    "brood": (
        "m AS (SELECT COALESCE(NULLIF(po.user_bi, ''), r.owner_bi) "
        "AS account_bi, COUNT(*) AS value FROM repo_forks f "
        "JOIN repositories r ON r.key_bi=f.parent_bi "
        "LEFT JOIN nodes po ON po.node_bi=r.owner_bi "
        "LEFT JOIN nodes fo ON fo.node_bi=f.account_bi "
        "WHERE r.is_private=0 "
        "AND COALESCE(NULLIF(fo.user_bi, ''), f.account_bi)<>"
        "COALESCE(NULLIF(po.user_bi, ''), r.owner_bi) GROUP BY 1)"),
    "fan_club": (
        "m AS (SELECT target_bi AS account_bi, COUNT(*) AS value "
        "FROM profile_follows WHERE follower_bi<>target_bi "
        "GROUP BY target_bi)"),
    "night_watch": (
        "m AS (SELECT COALESCE(NULLIF(n.user_bi, ''), t.node_key) "
        "AS account_bi, SUM(t.minutes)/60 AS value "
        "FROM node_uptime_totals t "
        "LEFT JOIN nodes n ON n.node_bi=t.node_key GROUP BY 1)"),
    "bug_catcher": (
        "m AS (SELECT account_bi, SUM(n) AS value FROM ("
        "SELECT account_bi, COUNT(*) AS n FROM microjob_claims "
        "WHERE job='issue_report' AND status='paid' GROUP BY account_bi "
        "UNION ALL SELECT recipient_bi, COUNT(*) "
        "FROM contributor_reward_estimates "
        "WHERE source_kind='issue' AND status='paid' "
        "GROUP BY recipient_bi) GROUP BY account_bi)"),
    "lift_off": (
        "m AS (SELECT COALESCE(NULLIF(n.user_bi, ''), r.owner_bi) "
        "AS account_bi, COUNT(*) AS value FROM ("
        "SELECT DISTINCT repo_bi, sha256, ua, ts/86400000 AS day "
        "FROM release_downloads) d "
        "JOIN repositories r ON r.key_bi=d.repo_bi "
        "LEFT JOIN nodes n ON n.node_bi=r.owner_bi "
        "WHERE r.is_private=0 GROUP BY 1)"),
    "shopkeeper": (
        "pub AS (SELECT 'forkmesh-apps' AS market, slug AS package_id, "
        "owner_bi FROM apps WHERE listing='listed' "
        "UNION SELECT marketplace_id, package_id, submitted_by_bi "
        "FROM marketplace_submissions WHERE state='published'), "
        "m AS (SELECT pub.owner_bi AS account_bi, "
        "COUNT(DISTINCT x.account_bi) AS value FROM pub "
        "JOIN marketplace_package_uses x ON x.market=pub.market "
        "AND x.package_id=pub.package_id "
        "WHERE x.account_bi<>pub.owner_bi GROUP BY pub.owner_bi)"),
    "critic": (
        "m AS (SELECT r.reviewer_bi AS account_bi, COUNT(*) AS value "
        "FROM marketplace_reviews r WHERE r.hidden=0 AND EXISTS ("
        "SELECT 1 FROM marketplace_review_votes v "
        "WHERE v.review_id=r.review_id AND v.voter_bi<>r.reviewer_bi) "
        "GROUP BY r.reviewer_bi)"),
    "bounty_hunter": (
        "m AS (SELECT account_bi, SUM(n) AS value FROM ("
        "SELECT account_bi, COUNT(*) AS n FROM microjob_claims "
        "WHERE status='paid' GROUP BY account_bi "
        "UNION ALL SELECT recipient_bi, COUNT(*) "
        "FROM contributor_reward_estimates WHERE status='paid' "
        "GROUP BY recipient_bi) GROUP BY account_bi)"),
    "web_weaver": (
        "m AS (SELECT COALESCE(NULLIF(an.user_bi, ''), an.node_bi) "
        "AS account_bi, COUNT(DISTINCT f.repo_bi || '#' || f.number) "
        "AS value " + BADGE_FOREIGN_MERGES_SQL + ")"),
    "many_webs": (
        "m AS (SELECT COALESCE(NULLIF(an.user_bi, ''), an.node_bi) "
        "AS account_bi, COUNT(DISTINCT f.repo_bi) AS value " +
        BADGE_FOREIGN_MERGES_SQL + ")"),
    "eight_hands": (
        "m AS (SELECT c.account_bi, COUNT(*) AS value "
        "FROM badge_coauthor_facts c "
        "JOIN repositories r ON r.key_bi=c.repo_bi "
        "WHERE r.is_private=0 GROUP BY c.account_bi)"),
    "oracle": (
        "m AS (SELECT COALESCE(NULLIF(an.user_bi, ''), an.node_bi) "
        "AS account_bi, COUNT(DISTINCT a.repo_bi || '#' || a.number) "
        "AS value FROM badge_answer_facts a "
        "JOIN nodes an ON an.pubkey=a.answerer_key "
        "JOIN repositories r ON r.key_bi=a.repo_bi "
        "LEFT JOIN nodes onr ON onr.pubkey=a.opener_key "
        "AND a.opener_key<>'' "
        "WHERE a.answerer_key<>'' AND a.answerer_key<>a.opener_key "
        "AND r.is_private=0 "
        "AND COALESCE(NULLIF(an.user_bi, ''), an.node_bi)<>"
        "COALESCE(NULLIF(onr.user_bi, ''), onr.node_bi, '') GROUP BY 1)"),
}

BADGE_PROGRESS_SELECT_SQL = (
    "SELECT m.account_bi, u.username, m.value FROM m "
    "JOIN users u ON u.user_bi=m.account_bi "
    "LEFT JOIN badge_progress p ON p.badge_slug=? "
    "AND p.account_bi=m.account_bi "
    "WHERE m.value>=? AND m.value>COALESCE(p.value, 0) ")


async def _record_swept_progress(env, slug, rows, key="value"):
    awarded = []
    for row in rows or []:
        name, name_bi, _ = await _active_user_account(
            env, row.get("username") or "")
        if not name or name_bi != row.get("account_bi"):
            continue
        if await _record_badge_progress(env, name, name_bi, slug,
                                        row.get(key)):
            awarded.append(name)
    return awarded


async def refresh_badge_progress(env, slug):
    await ensure_schema(env)
    await d1_run(
        env,
        "WITH " + BADGE_METRIC_SQL[slug] + " "
        "INSERT INTO badge_progress (badge_slug, account_bi, value, "
        "updated_at) SELECT ?, m.account_bi, m.value, ? FROM m "
        "JOIN users u ON u.user_bi=m.account_bi "
        "LEFT JOIN badge_progress p ON p.badge_slug=? "
        "AND p.account_bi=m.account_bi "
        "WHERE m.value>0 AND m.value<? AND m.value>COALESCE(p.value, 0) "
        "ON CONFLICT(badge_slug, account_bi) DO UPDATE SET "
        "value=MAX(value, excluded.value), updated_at=excluded.updated_at",
        slug, int(Date.now()), slug, badge_catalog.badge_tiers(slug)[0])
    return {"awarded": []}


async def award_metric_badges(env, slug):
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "WITH " + BADGE_METRIC_SQL[slug] + " " + BADGE_PROGRESS_SELECT_SQL +
        "ORDER BY m.value DESC LIMIT ?",
        slug, badge_catalog.badge_tiers(slug)[0], BADGE_SWEEP_LIMIT)
    return {"awarded": await _record_swept_progress(env, slug, rows)}


async def award_daily_spinner_badges(env):
    await ensure_schema(env)
    candidates = await d1_all(
        env,
        "WITH " + BADGE_CONTRIBUTION_SOURCES_SQL + ", "
        "m AS (SELECT d.subject_user_bi AS account_bi, "
        "COUNT(DISTINCT d.day) AS value " + BADGE_CONTRIBUTION_DAYS_SQL + " "
        "AND d.commits+d.issues+d.pulls+d.reviews>0 "
        "GROUP BY d.subject_user_bi) " + BADGE_PROGRESS_SELECT_SQL +
        "ORDER BY COALESCE(p.updated_at, 0) LIMIT ?",
        "daily_spinner", badge_catalog.badge_tiers("daily_spinner")[0],
        BADGE_SWEEP_LIMIT)
    rows = []
    for row in candidates or []:
        days = await d1_all(
            env,
            "WITH " + BADGE_CONTRIBUTION_SOURCES_SQL + " "
            "SELECT DISTINCT d.day " + BADGE_CONTRIBUTION_DAYS_SQL + " "
            "AND d.subject_user_bi=? "
            "AND d.commits+d.issues+d.pulls+d.reviews>0",
            row.get("account_bi"))
        rows.append(dict(row, streak=badge_catalog.longest_streak(
            [day.get("day") for day in days or []])))
    return {"awarded": await _record_swept_progress(
        env, "daily_spinner", rows, key="streak")}


