async def _record_web_merge_badge_fact(env, repo_bi, number, actor_bi,
                                       override_review):
    try:
        number = int(number or 0)
    except (TypeError, ValueError):
        number = 0
    if not repo_bi or not actor_bi or number < 1:
        return False
    await ensure_schema(env)
    now = int(Date.now())
    await d1_run(
        env,
        "INSERT INTO badge_pull_facts (repo_bi, kind, number, closer_bi, "
        "closed_at, merged, review_waived, updated_at) "
        "VALUES (?,'pull',?,?,?,1,?,?) "
        "ON CONFLICT(repo_bi, kind, number) DO UPDATE SET "
        "closer_bi=excluded.closer_bi, "
        "closed_at=CASE WHEN badge_pull_facts.closed_at>0 "
        "THEN badge_pull_facts.closed_at ELSE excluded.closed_at END, "
        "merged=1, review_waived=MAX(badge_pull_facts.review_waived, "
        "excluded.review_waived), updated_at=excluded.updated_at",
        repo_bi, number, actor_bi, now, 1 if override_review else 0, now)
    await d1_run(
        env, "UPDATE badge_repo_sweeps SET state_ts=0 WHERE repo_bi=?",
        repo_bi)
    return True


def _badge_record_numbers(tree):
    entries = tree.get("entries") if isinstance(tree, dict) else None
    numbers = set()
    for entry in entries if isinstance(entries, list) else []:
        name = str((entry or {}).get("name") or "") if isinstance(
            entry, dict) else ""
        if entry.get("type") == "tree" and name.isdigit() and 0 < int(
                name) <= 1_000_000_000:
            numbers.add(int(name))
    return numbers


async def _badge_record_blobs(env, owner, repo, paths, ref=""):
    if not paths:
        return {}
    query = "&".join("path=" + quote(path, safe="") for path in paths)
    if ref:
        query += "&ref=" + quote(ref, safe="")
    data = await _forkbot_repo_gateway_json(env, owner, repo, "blobs?" + query)
    blobs = data.get("blobs") if isinstance(data, dict) else None
    return blobs if isinstance(blobs, dict) else None


async def _verified_email_account(env, email):
    email = clean_string(email or "", 254).strip().lower()
    if "@" not in email:
        return ""
    row = await d1_first(
        env, "SELECT user_bi, data FROM users WHERE email_bi=?",
        await blind_index(env, email))
    if not row:
        return ""
    rec = await decrypt_row(env, row.get("data"))
    if (
        not isinstance(rec, dict)
        or rec.get("email_verified") is not True
        or clean_string(rec.get("email", ""), 254).strip().lower() != email
        or _account_kind(rec) != "user"
        or rec.get("status") != "active"
    ):
        return ""
    return str(row.get("user_bi") or "")


async def _record_coauthor_facts(env, repo_bi, number, author_key, emails):
    if not emails:
        return 0
    authors = set()
    if author_key:
        for row in await d1_all(
                env,
                "SELECT COALESCE(NULLIF(user_bi, ''), node_bi) AS account_bi "
                "FROM nodes WHERE pubkey=? AND pubkey<>''", author_key) or []:
            authors.add(str(row.get("account_bi") or ""))
    recorded = 0
    for email in emails:
        account_bi = await _verified_email_account(env, email)
        if not account_bi or account_bi in authors:
            continue
        await d1_run(
            env,
            "INSERT OR IGNORE INTO badge_coauthor_facts "
            "(repo_bi, number, account_bi, created_at) VALUES (?,?,?,?)",
            repo_bi, number, account_bi, int(Date.now()))
        recorded += 1
    return recorded


async def _sweep_repo_pull_records(env, repo_bi, owner, repo, known):
    tree = await _forkbot_repo_gateway_json(
        env, owner, repo,
        "tree?path=" + quote(".forkmesh/pulls", safe="") +
        "&ref=" + quote("forkmesh/pulls", safe=""))
    if tree is None:
        return True
    pending = []
    for number in _badge_record_numbers(tree):
        row = known.get(("pull", number))
        if row and int(row.get("opened_at") or 0) > 0 and (
                int(row.get("merged") or 0) or int(row.get("closed_at") or 0)):
            continue
        pending.append((int((row or {}).get("updated_at") or 0), number))
    pending.sort()
    complete = len(pending) <= BADGE_RECORD_BATCH
    numbers = [number for _, number in pending[:BADGE_RECORD_BATCH]]
    paths = {number: ".forkmesh/pulls/%d/pull.md" % number
             for number in numbers}
    blobs = await _badge_record_blobs(
        env, owner, repo, list(paths.values()), "forkmesh/pulls")
    if blobs is None:
        return False
    review_checks = 0
    now = int(Date.now())
    for number in numbers:
        fields = microjobs.parse_pull_frontmatter(
            _forkbot_blob_text(blobs.get(paths[number])))
        fact = badge_catalog.pull_record_fact(fields, number)
        if fact is None:
            fact = {"author_key": "", "closer_key": "", "opened_at": 0,
                    "closed_at": 0, "merged": False, "co_authors": []}
        row = known.get(("pull", number)) or {}
        reviewed = 0
        if fact["merged"] and (fact["closer_key"] or row.get("closer_bi")) \
                and not int(row.get("review_waived") or 0):
            if review_checks >= BADGE_RECORD_REVIEW_CHECKS:
                complete = False
                continue
            review_checks += 1
            listing = await _forkbot_repo_gateway_json(
                env, owner, repo,
                "tree?path=" + quote(".forkmesh/pulls/%d" % number, safe="") +
                "&ref=" + quote("forkmesh/pulls", safe=""))
            if listing is None:
                complete = False
                continue
            reviewed = 1 if badge_catalog.has_review_file(
                listing.get("entries")) else 0
        await d1_run(
            env, BADGE_RECORD_UPSERT_SQL, repo_bi, "pull", number,
            fact["author_key"], fact["closer_key"], fact["opened_at"],
            fact["closed_at"], 1 if fact["merged"] else 0, reviewed, now)
        if fact["merged"] and fact["opened_at"]:
            await _record_coauthor_facts(
                env, repo_bi, number, fact["author_key"], fact["co_authors"])
    return complete


async def _sweep_repo_issue_records(env, repo_bi, owner, repo, known):
    tree = await _forkbot_repo_gateway_json(
        env, owner, repo,
        "tree?path=" + quote(".forkmesh/issues/closed", safe=""))
    if tree is None:
        return False
    pending = sorted(number for number in _badge_record_numbers(tree)
                     if ("issue", number) not in known)
    complete = len(pending) <= BADGE_RECORD_BATCH
    numbers = pending[:BADGE_RECORD_BATCH]
    paths = {number: ".forkmesh/issues/closed/%d/issue-%d.json" % (
        number, number) for number in numbers}
    blobs = await _badge_record_blobs(env, owner, repo, list(paths.values()))
    if blobs is None:
        return False
    now = int(Date.now())
    for number in numbers:
        try:
            record = json.loads(
                _forkbot_blob_text(blobs.get(paths[number])) or "null")
        except Exception:
            record = None
        fact = badge_catalog.issue_record_fact(record) or {
            "author_key": "", "closer_key": "", "opened_at": 0,
            "closed_at": 0}
        await d1_run(
            env, BADGE_RECORD_UPSERT_SQL, repo_bi, "issue", number,
            fact["author_key"], fact["closer_key"], fact["opened_at"],
            fact["closed_at"], 0, 0, now)
    return complete


async def _sweep_repo_discussion_answers(env, repo_bi, owner, repo):
    tree = await _forkbot_repo_gateway_json(
        env, owner, repo,
        "tree?path=" + quote(".forkmesh/discussions", safe=""))
    if tree is None:
        return False
    entries = tree.get("entries") if isinstance(tree, dict) else None
    oids = {}
    for entry in entries if isinstance(entries, list) else []:
        name = str((entry or {}).get("name") or "") if isinstance(
            entry, dict) else ""
        if (entry.get("type") == "tree" and name.isdigit()
                and 0 < int(name) <= 1_000_000_000):
            oids[int(name)] = str(entry.get("oid") or "")
    if not oids:
        return True
    known = {}
    for row in await d1_all(
            env,
            "SELECT number, dir_oid, updated_at FROM badge_answer_facts "
            "WHERE repo_bi=?", repo_bi) or []:
        known[int(row.get("number") or 0)] = row
    pending = sorted(
        (int((known.get(number) or {}).get("updated_at") or 0), number)
        for number, oid in oids.items()
        if not oid or str((known.get(number) or {}).get("dir_oid")) != oid)
    limit = BADGE_RECORD_BATCH // 2
    complete = len(pending) <= limit
    numbers = [number for _, number in pending[:limit]]
    paths = []
    for number in numbers:
        paths.append(".forkmesh/discussions/%d/discussion.md" % number)
        paths.append(".forkmesh/discussions/%d/answer.md" % number)
    blobs = await _badge_record_blobs(env, owner, repo, paths)
    if blobs is None:
        return False
    now = int(Date.now())
    for number in numbers:
        opened = microjobs.parse_pull_frontmatter(_forkbot_blob_text(
            blobs.get(".forkmesh/discussions/%d/discussion.md" % number)))
        if not opened:
            complete = False
            continue
        answer = microjobs.parse_pull_frontmatter(_forkbot_blob_text(
            blobs.get(".forkmesh/discussions/%d/answer.md" % number)))
        fact = badge_catalog.answer_record_fact(opened, answer)
        await d1_run(
            env,
            "INSERT INTO badge_answer_facts (repo_bi, number, dir_oid, "
            "opener_key, answerer_key, marked_at, updated_at) "
            "VALUES (?,?,?,?,?,?,?) ON CONFLICT(repo_bi, number) DO UPDATE "
            "SET dir_oid=excluded.dir_oid, opener_key=excluded.opener_key, "
            "answerer_key=excluded.answerer_key, "
            "marked_at=excluded.marked_at, updated_at=excluded.updated_at",
            repo_bi, number, oids[number], fact["opener_key"],
            fact["answerer_key"], fact["marked_at"], now)
    return complete


async def sweep_badge_records(env):
    await ensure_schema(env)
    repos = await d1_all(
        env, BADGE_RECORD_REPOS_SQL, BADGE_RECORD_REPOS_PER_RUN)
    swept = []
    for row in repos or []:
        repo_bi = str(row.get("key_bi") or "")
        record = await decrypt_row(env, row.get("data"))
        owner = str((record or {}).get("owner") or "") if isinstance(
            record, dict) else ""
        repo = str((record or {}).get("repo") or "") if isinstance(
            record, dict) else ""
        complete = False
        if owner and repo:
            known = {}
            for fact in await d1_all(
                    env,
                    "SELECT kind, number, opened_at, closed_at, merged, "
                    "closer_bi, review_waived, updated_at "
                    "FROM badge_pull_facts WHERE repo_bi=?", repo_bi) or []:
                known[(fact.get("kind"), int(fact.get("number") or 0))] = fact
            pulls = await _sweep_repo_pull_records(
                env, repo_bi, owner, repo, known)
            issues = await _sweep_repo_issue_records(
                env, repo_bi, owner, repo, known)
            answers = await _sweep_repo_discussion_answers(
                env, repo_bi, owner, repo)
            complete = pulls and issues and answers
        state_ts = int(row.get("state_ts") or 0) if complete else 0
        await d1_run(
            env,
            "INSERT INTO badge_repo_sweeps (repo_bi, state_ts, swept_at) "
            "VALUES (?,?,?) ON CONFLICT(repo_bi) DO UPDATE SET "
            "state_ts=CASE WHEN excluded.state_ts>0 THEN excluded.state_ts "
            "ELSE badge_repo_sweeps.state_ts END, swept_at=excluded.swept_at",
            repo_bi, state_ts, int(Date.now()))
        if complete:
            swept.append(owner + "/" + repo)
    return {"awarded": swept}


async def run_badge_sweep(env):
    out = {}
    sweeps = [
        ("records", sweep_badge_records),
        ("distinguished_contributor", award_distinguished_contributor_badges),
        ("stargazer", award_stargazer_badges),
        ("genies_gift", award_genies_gift_badges),
        ("daily_spinner", award_daily_spinner_badges),
    ]
    for slug in BADGE_METRIC_SQL:
        sweeps.append(
            (slug, lambda env, slug=slug: award_metric_badges(env, slug)))
        sweeps.append(
            ("progress:" + slug,
             lambda env, slug=slug: refresh_badge_progress(env, slug)))
    for slug in BADGE_FACT_SQL:
        sweeps.append(
            (slug, lambda env, slug=slug: award_fact_badges(env, slug)))
    for key, sweep in sweeps:
        try:
            out[key] = (await sweep(env)).get("awarded", [])
        except Exception as error:
            print("badge sweep %s failed: %s" % (
                key, _safe_error_text(error)[:160]))
            out[key] = []
    return out


def badge_ping(slug, tier=0, upgraded=False):
    info = badge_catalog.badge_definition(slug)
    if not info:
        return None
    tiered = bool(badge_catalog.badge_tiers(slug))
    level = badge_catalog.tier_name(tier) if tiered else ""
    label = level.capitalize() if tiered and tier else ""
    if upgraded and label:
        title = "Your %s badge is now %s" % (info["name"], label)
    else:
        title = "You earned the %s badge" % (
            (label + " " + info["name"]) if label else info["name"])
    return {
        "title": title,
        "body": info["description"],
        "href": "/dashboard/achievements",
        "source": "badge:" + badge_catalog.normalize_badge_slug(slug),
        "dedupe": "badge:%s:%s" % (badge_catalog.normalize_badge_slug(slug),
                                   level or "earned"),
        "meta": {"celebrate": "badge",
                 "badge": badge_catalog.normalize_badge_slug(slug),
                 "badgeName": info["name"], "tier": level},
    }


async def _send_badge_ping(env, name, slug, tier=0, upgraded=False):
    ping = badge_ping(slug, tier, upgraded)
    if not ping:
        return False
    return await enqueue_notification(
        env, name, "badge", ping["title"], body=ping["body"],
        href=ping["href"], source=ping["source"], dedupe=ping["dedupe"],
        meta=ping["meta"])


async def _send_badge_email(env, name, slug, tier=0, upgraded=False):
    info = badge_catalog.badge_definition(slug)
    name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
    if not info or not valid_node_name(name):
        return False
    _, rec = await _account_row(env, name)
    email = ((rec or {}).get("email", "") or "").strip()
    if (
        not rec
        or _account_kind(rec) != "user"
        or rec.get("status") != "active"
        or not email
        or not rec.get("email_verified")
        or rec.get("email_notifications") is False
    ):
        return False
    origin = _ap_origin(env)
    profile_url = (
        origin + "/dashboard/profile" if rec.get("profile_private")
        else "%s/@%s" % (origin, quote(name)))
    tier_label = (
        badge_catalog.tier_name(tier).capitalize()
        if tier and badge_catalog.badge_tiers(slug) else "")
    badge_name = (
        tier_label + " " + info["name"] if tier_label else info["name"])
    subject = (
        "Your %s badge is now %s on ForkMesh" % (info["name"], tier_label)
        if upgraded and tier_label
        else "You earned the %s badge on ForkMesh" % badge_name)
    text = (
        "Hi " + name + ",\n\n"
        "You just earned the " + info["icon"] + " " + badge_name +
        " badge on ForkMesh.\n\n" + info["description"] + "\n\n"
        "It now shows on your profile:\n" + profile_url + "\n\n"
        "Thank you for being part of ForkMesh.\n\n"
        "You are getting this because a badge was added to your ForkMesh "
        "account. Turn off email notifications in your settings to stop "
        "these emails.")
    intro = (
        "Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
        _html_escape(name) + "</strong>, you just earned the "
        "<strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
        _html_escape(badge_name) + "</strong> badge.")
    body_html = (
        "<p class=\"fm-text\" style=\"margin:0 0 18px;font-size:40px;"
        "line-height:1\">" + _html_escape(info["icon"]) + "</p>"
        "<p class=\"fm-text\" style=\"margin:0 0 18px;color:#d4d4d8;"
        "font-size:14px\">" + _html_escape(info["description"]) + "</p>"
        "<p class=\"fm-text\" style=\"margin:0;color:#d4d4d8;"
        "font-size:14px\">It now shows on your ForkMesh profile. Thank you "
        "for being part of ForkMesh.</p>")
    footer_html = (
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;"
        "font-size:12px\">You are getting this because a badge was added to "
        "your ForkMesh account. Turn off email notifications in your settings "
        "to stop these emails.</p>")
    html = _forkmesh_email_card_html(
        "You earned a badge", intro, body_html, footer_html,
        action_label="View your profile", action_url=profile_url)
    sent = await _send_email(env, email, subject, text, html,
                             email_kind="badge")
    if sent:
        await _record_account_email(env, name, "badge", True)
    return sent


async def award_distinguished_contributor_badges(env):
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT c.author_bi,u.username,c.issues,c.pulls,c.discussions "
        "FROM contributor_activity c "
        "JOIN users u ON u.user_bi=c.author_bi "
        "LEFT JOIN badge_awards b ON b.account_bi=c.author_bi "
        "AND b.badge_slug=? "
        "WHERE b.account_bi IS NULL "
        "AND c.issues+c.pulls+c.discussions>=? "
        "ORDER BY c.total DESC LIMIT ?",
        "distinguished_contributor",
        badge_catalog.DISTINGUISHED_CONTRIBUTOR_MIN,
        DISTINGUISHED_CONTRIBUTOR_SWEEP_LIMIT)
    awarded = []
    for row in rows or []:
        if not badge_catalog.distinguished_contributor_earned(row):
            continue
        name = clean_string(row.get("username") or "", MAX_NODE_NAME)
        name = name.strip().lower()
        if not valid_node_name(name):
            continue
        name_bi, rec = await _account_row(env, name)
        if (
            not rec
            or name_bi != row.get("author_bi")
            or _account_kind(rec) != "user"
            or rec.get("status") != "active"
        ):
            continue
        if await _award_badge(env, name, name_bi,
                              "distinguished_contributor"):
            awarded.append(name)
    return {"awarded": awarded}


async def chat_badge_activity_handler(env, request):
    """Record one authenticated person's first successful chat send.

    Chat frames remain encrypted in the room relay, so the browser calls this
    tiny session-gated companion only after it has handed its own message to an
    open WebSocket. The endpoint stores no message text, room, or timestamp
    beyond the ordinary badge award, and INSERT OR IGNORE makes retries safe.
    """
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    account_bi, rec = await _account_session_record(env, request, data)
    if (
        not account_bi
        or not rec
        or _account_kind(rec) != "user"
        or rec.get("status") != "active"
    ):
        return json_response({"error": "invalid_session"}, status=401)
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).strip().lower()
    if not name:
        return json_response({"error": "invalid_session"}, status=401)
    await _award_badge(env, name, account_bi, "chat")
    # The roster backs every World avatar; clearing its short edge copy lets a
    # person see their new sleeve mark on the next refresh rather than waiting
    # for the normal 30-second directory TTL.
    try:
        memos_clear = globals().get("_users_directory_memos_clear")
        if callable(memos_clear):
            memos_clear()
        await _users_directory_cache_forget()
    except Exception:
        pass
    return json_response(
        {"ok": True, "badge": "chat"},
        cache_control="no-store, max-age=0, must-revalidate")


async def _account_badges(env, name_bi):
    rows = await d1_all(
        env,
        "SELECT a.badge_slug, a.granted_by, a.created_at, a.tier, a.tier_at, "
        "p.value AS progress FROM badge_awards a "
        "LEFT JOIN badge_progress p ON p.badge_slug=a.badge_slug "
        "AND p.account_bi=a.account_bi "
        "WHERE a.account_bi=? ORDER BY a.created_at", name_bi)
    out = []
    for row in rows or []:
        slug = str(row.get("badge_slug") or "")
        info = badge_catalog.badge_definition(slug)
        if not info:
            continue
        granted_by = str(row.get("granted_by") or "system")
        entry = {
            "slug": slug,
            "name": info["name"],
            "description": info["description"],
            "icon": info["icon"],
            "grantedBy": "system" if granted_by == "system" else "admin",
            "awardedAt": int(row.get("created_at") or 0),
        }
        summary = badge_catalog.tier_summary(
            slug, row.get("tier"), row.get("progress"))
        if summary:
            summary["tierAt"] = int(
                row.get("tier_at") or row.get("created_at") or 0)
            entry.update(summary)
        out.append(entry)
    return out


async def _account_badge_progress(env, name_bi, earned):
    rows = await d1_all(
        env,
        "SELECT badge_slug, value FROM badge_progress WHERE account_bi=?",
        name_bi)
    out = []
    for row in rows or []:
        slug = badge_catalog.normalize_badge_slug(row.get("badge_slug"))
        tiers = badge_catalog.badge_tiers(slug)
        if not slug or not tiers or slug in earned:
            continue
        try:
            value = max(0, int(row.get("value") or 0))
        except (TypeError, ValueError):
            continue
        out.append({
            "slug": slug,
            "progress": value,
            "unit": badge_catalog.BADGE_DEFINITIONS[slug].get("unit", ""),
            "nextTier": badge_catalog.tier_name(0),
            "nextThreshold": tiers[0],
        })
    return out


async def badges_catalog_handler(env, request):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    return json_response(
        {"ok": True, "badges": badge_catalog.public_catalog()},
        cache_seconds=3600)


async def account_badges_handler(env, request, raw_name):
    # GET: the badges one account has earned (public — same visibility as the
    # public account lookup). POST/DELETE: a platform administrator grants or
    # revokes one badge.
    await ensure_schema(env)
    name = clean_string(raw_name or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name):
        return json_response({"error": "invalid_account"}, status=400)
    name_bi, rec = await _account_row(env, name)
    method = method_name(request)
    if not rec:
        if method == "GET" and (await _org_row(env, name))[1]:
            return json_response(
                {"ok": True, "account": name, "kind": "organization",
                 "badges": [], "progress": []},
                cache_seconds=30)
        return json_response({"error": "not_found"}, status=404)
    if method == "GET":
        badges = await _account_badges(env, name_bi)
        earned = {badge["slug"] for badge in badges}
        return json_response(
            {"ok": True, "account": name, "badges": badges,
             "progress": await _account_badge_progress(env, name_bi, earned)},
            cache_seconds=30)
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, actor_rec = await _account_session_record(env, request, data)
    actor = (actor_rec.get("name", "") if actor_rec else "").strip().lower()
    audit_action = "badge.grant" if method == "POST" else "badge.revoke"
    if not actor or not await _has_role(env, actor, "platform_administrator"):
        await _audit_sensitive_action(
            env, actor, audit_action, "account_badge", name, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    slug = badge_catalog.normalize_badge_slug(data.get("slug", ""))
    if not slug:
        return json_response({"error": "invalid_badge"}, status=400)
    if method == "DELETE":
        await d1_run(
            env, "DELETE FROM badge_awards WHERE badge_slug=? AND account_bi=?",
            slug, name_bi)
        await _audit_sensitive_action(
            env, actor, audit_action, "account_badge", name + "/" + slug,
            "success")
        return json_response(
            {"ok": True, "account": name, "slug": slug, "revoked": True})
    await _award_badge(env, name, name_bi, slug, granted_by=actor)
    await _audit_sensitive_action(
        env, actor, audit_action, "account_badge", name + "/" + slug,
        "success")
    return json_response(
        {"ok": True, "account": name, "slug": slug, "granted": True},
        status=201)


async def _admin_authorized(env, node, ts, sig, canonical):
    # The requesting admin proves control of their node's key, and the account
    # must have is_admin set. Returns the admin's record on success, else None.
    node = (node or "").strip().lower()
    if not await _is_admin_flag(env, node) or not _ts_ok(ts):
        return None
    _, rec = await _account_row(env, node)
    if (not rec or rec.get("status") != "active"
            or not rec.get("totp_enrolled")):
        return None
    pubkey = rec.get("pubkey", "")
    if not pubkey or not await ed25519_verify(pubkey, sig, canonical):
        return None
    return rec


async def _enqueue_verification(env, name_bi, name, email):
    blob = await encrypt_row(
        env, {"name": name, "email": email, "joinedAt": int(Date.now())})
    await d1_run(
        env,
        "INSERT INTO pending_verifications (name_bi, data) VALUES (?,?) "
        "ON CONFLICT(name_bi) DO UPDATE SET data=excluded.data",
        name_bi, blob,
    )


async def _admin_pending(env, request):
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    canonical = ("forkmesh-admin-pending-v1\n" + node + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    rows = await d1_all(env, "SELECT data FROM pending_verifications")
    pending = [rec for rec in
               [await decrypt_row(env, r["data"]) for r in rows] if rec]
    pending.sort(key=lambda x: x.get("joinedAt", 0))
    return json_response({"ok": True, "pending": pending})


async def _admin_verify_email(env, request):
    # The pending queue exists because delivery can be unconfigured or simply
    # never arrive, which strands an otherwise real member mid-signup. A proven
    # administrator closes that out here. The record keeps who vouched and how,
    # so an override is never mistaken for a mailbox the recipient confirmed.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    target = clean_string(data.get("target", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    canonical = ("forkmesh-admin-verify-email-v1\n" + node + "\n" + target +
                 "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    if not valid_node_name(target):
        return json_response({"error": "invalid_account"}, status=400)
    target_bi, rec = await _account_row(env, target)
    if (
            not rec or rec.get("status") != "active"
            or _account_kind(rec) != "user"):
        await _audit_sensitive_action(
            env, node, "admin.email_verify", "account", target, "denied",
            {"reason": "no_such_user"})
        return json_response({"error": "no_such_user"}, status=404)
    if not clean_string(rec.get("email", ""), 254).strip():
        await _audit_sensitive_action(
            env, node, "admin.email_verify", "account", target, "denied",
            {"reason": "account_has_no_email"})
        return json_response({"error": "account_has_no_email"}, status=409)
    already = rec.get("email_verified") is True
    if not already:
        rec["email_verified"] = True
        rec["email_verified_at"] = int(Date.now())
        # Deliberately not "recipient_link_post": nobody proved control of the
        # mailbox on this path, an administrator vouched for it.
        rec["email_verification_method"] = "admin_override"
        rec["email_verified_by"] = node
        await _save_account(env, target_bi, rec)
        # Referral credit still runs its own maturity, device, burst, and risk
        # gates -- verification only unblocks the decision, it does not force
        # the payout.
        await _finalize_referral_signup(env, target_bi)
        try:
            await _hackathon.on_email_verified(env, target_bi, target)
        except Exception:
            pass
    await d1_run(
        env, "DELETE FROM pending_verifications WHERE name_bi=?", target_bi)
    await _audit_sensitive_action(
        env, node, "admin.email_verify", "account", target, "success",
        {"method": "admin_override", "alreadyVerified": already})
    return json_response(
        {"ok": True, "target": target, "emailVerified": True,
         "alreadyVerified": already},
        cache_control="no-store, max-age=0, must-revalidate")


async def _admin_delete_unverified_account(env, request, raw_target):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    _, actor_rec = await _account_session_record(env, request, data)
    actor = clean_string(
        (actor_rec or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
    target = clean_string(raw_target, MAX_NODE_NAME).strip().lower()
    if not actor_rec:
        return json_response({"error": "unauthorized"}, status=401)
    if not await _has_role(env, actor, "platform_administrator"):
        await _audit_sensitive_action(
            env, actor, "admin.unverified_account_delete", "account",
            target, "denied", {"reason": "admin_required"})
        return json_response({"error": "forbidden"}, status=403)
    if not valid_node_name(target):
        return json_response({"error": "invalid_account"}, status=400)
    if target == actor:
        await _audit_sensitive_action(
            env, actor, "admin.unverified_account_delete", "account",
            target, "denied", {"reason": "self_delete_forbidden"})
        return json_response({"error": "self_delete_forbidden"}, status=409)

    target_bi, target_rec = await _account_row(env, target)
    if (
            not target_rec or target_rec.get("status") != "active"
            or _account_kind(target_rec) != "user"):
        return json_response({"error": "no_such_user"}, status=404)
    if target_rec.get("email_verified") is True:
        return json_response({"error": "email_already_verified"}, status=409)
    if not clean_string(target_rec.get("email", ""), 254).strip():
        return json_response({"error": "account_has_no_email"}, status=409)
    # Never let the convenience gesture erase another administrator. Revoking
    # an administrator remains an explicit security-control-plane operation.
    if await _is_admin_flag(env, target):
        await _audit_sensitive_action(
            env, actor, "admin.unverified_account_delete", "account",
            target, "denied", {"reason": "target_is_admin"})
        return json_response({"error": "target_is_admin"}, status=409)

    try:
        await _delete_account_namespace(env, target_bi, target_rec)
    except Exception:
        await _audit_sensitive_action(
            env, actor, "admin.unverified_account_delete", "account",
            target, "failed", {})
        raise
    await _audit_sensitive_action(
        env, actor, "admin.unverified_account_delete", "account",
        target, "success", {})
    return json_response(
        {"ok": True, "target": target, "accountDeleted": True},
        cache_control="no-store, max-age=0, must-revalidate",
    )


# --- Transactional email (Mailtrap) -----------------------------------------
# Signup confirmation goes out through Mailtrap's HTTP sending API. The token is
# a Worker secret (MAILTRAP_API_TOKEN, pushed from .env.production by deploy.sh).
# When it's unset the sender is a no-op, so a fork without an email provider
# still works — callers fall back to the admin verification queue.
MAILTRAP_SEND_URL = "https://send.api.mailtrap.io/api/send"
FORKMESH_SITE_URL = "https://forkmesh.com/"


def instance_name(env):
    name = " ".join(str(getattr(env, "INSTANCE_NAME", "") or "").split())[:60]
    return name or "ForkMesh"


def instance_branded(env):
    return instance_name(env) != "ForkMesh"


def instance_site_url(env):
    if not instance_branded(env):
        return FORKMESH_SITE_URL
    base = str(getattr(env, "PUBLIC_BASE_URL", "") or getattr(
        env, "APP_ORIGIN", "") or "").strip().rstrip("/")
    return (base + "/") if base.startswith("https://") else FORKMESH_SITE_URL


def instance_logo_path(env):
    path = str(getattr(env, "INSTANCE_LOGO", "") or "").strip()
    return path[1:] if re.fullmatch(
        r"/instance-logo\.(?:png|jpg|webp|svg)", path) else ""


def instance_logo_url(env):
    path = instance_logo_path(env)
    if path:
        return "/" + path
    return "" if instance_branded(env) else "/assets/logo-96.png"


def _instance_brand_email(env, text, html):
    if not instance_branded(env):
        return text, html
    name = instance_name(env)
    site = instance_site_url(env)
    logo = instance_logo_path(env) or "assets/logo-96.png"
    text = text.replace("Open ForkMesh: " + FORKMESH_SITE_URL,
                        "Open " + name + ": " + site)
    text = instance_features.rename(env, text)
    credit = instance_features.powered_by(env)
    if credit:
        text += "\n\nPowered by ForkMesh"
    if html:
        escaped = _html_escape(name)
        html = (html
                .replace("https://app.forkmesh.com/assets/logo-96.png",
                         site + logo)
                .replace("alt=\"ForkMesh\"", "alt=\"" + escaped + "\"")
                .replace(">Open ForkMesh</a>", ">Open " + escaped + "</a>")
                .replace(">ForkMesh &middot; ", ">" + escaped + " &middot; ")
                .replace("https://app.forkmesh.com/dashboard/settings",
                         _html_escape(site) + "dashboard/settings")
                .replace("href=\"" + FORKMESH_SITE_URL + "\"",
                         "href=\"" + _html_escape(site) + "\""))
        html = instance_features.rename(env, html, escaped)
        footer = ("<p data-instance-powered-by style=\"margin:18px 0 0;"
                  "color:#71717a;font-size:12px\">Powered by <a href=\""
                  "https://forkmesh.com/\" style=\"color:#71717a\">"
                  "ForkMesh</a></p>")
        closing = "</div></div></body></html>"
        if credit:
            html = (html.replace(closing, footer + closing, 1)
                    if closing in html else html + footer)
    return text, html
MAILTRAP_EMAIL_CATEGORIES = {
    "account": "Account notification",
    "verification": "Welcome verification",
    "password_reset": "Password reset",
    "password_change": "Password change",
    "tip": "Tip notification",
    "badge": "Badge awarded",
    "feedback": "Onboarding feedback",
    "notifications": "Notification digest",
    "general_chat": "General chat digest",
    "channel_unread": "Unread channel reminder",
    "direct_unread": "Unread direct message reminder",
    # Kept for mail this account received while memberships were sold on the
    # site; nothing writes this kind any more.
    "polar_membership": "Billing membership",
    "cron_watchdog": "Operational cron alert",
    "status_alert": "Operational status alert",
    "security_report": "Security report",
    "admin_test": "Administrator test",
    "marketing": "Product updates and offers",
    "task": "Task activity",
}


def _mailtrap_email_category(email_kind):
    kind = clean_string(email_kind or "account", 40).strip().lower()
    return MAILTRAP_EMAIL_CATEGORIES.get(kind, "Account notification")


async def _mailtrap_account_for_email(env, email):
    try:
        email_bi = await blind_index(
            env, clean_string(email or "", 254).strip().lower())
        if not email_bi:
            return ""
        row = await d1_first(
            env, "SELECT user_bi FROM users WHERE email_bi=? LIMIT 1",
            email_bi)
        return str((row or {}).get("user_bi") or "")
    except Exception:
        return ""


async def _record_mailtrap_send(
        env, send_id, account_bi, kind, accepted, status="",
        message_id=""):
    if not send_id or not account_bi:
        return
    now = int(Date.now())
    try:
        await d1_run(
            env,
            "INSERT INTO mailtrap_email_sends "
            "(send_id,account_bi,kind,sent_at,accepted,status,status_at,"
            "message_id) VALUES(?,?,?,?,?,?,?,?)",
            send_id,
            account_bi,
            clean_string(kind or "account", 40),
            now,
            1 if accepted else 0,
            clean_string(status or (
                "accepted" if accepted else "failed"), 40),
            now,
            clean_string(message_id or "", 160),
        )
    except Exception:
        pass


def _mail_log_error_text(body):
    if isinstance(body, dict):
        errors = body.get("errors") or body.get("error") or body.get("message")
        if isinstance(errors, list):
            return "; ".join(str(item) for item in errors[:3])
        if errors:
            return str(errors)
    return ""


def _mailtrap_response_message_id(body):
    """Read the sending API's own handle for a message it just accepted.

    Until this was stored, ``message_id`` could only ever be filled in by an
    inbound webhook, so a message whose webhook was dropped had no durable
    handle left to reconcile against.
    """
    identifiers = body.get("message_ids") if isinstance(body, dict) else None
    if not isinstance(identifiers, list):
        return ""
    for identifier in identifiers:
        identifier = clean_string(identifier or "", 160).strip()
        if identifier:
            return identifier
    return ""


async def _mail_budget_execute(env, sql, *args):
    result = await d1_run(env, sql, *args)
    try:
        return int(result.meta.changes)
    except Exception:
        return 0


async def _mail_budget_spend(env, email_kind):
    try:
        return await mail_budget.spend(
            lambda sql, *args: _mail_budget_execute(env, sql, *args),
            env, email_kind, int(Date.now()))
    except Exception as error:
        allowed = mail_budget.is_account_kind(email_kind)
        print("mail budget unavailable: kind %s %s: %s" % (
            clean_string(email_kind or "account", 40),
            "sent" if allowed else "held", _safe_error_text(error)[:160]))
        return allowed


async def _mail_provider_held(env):
    try:
        return await mail_budget.provider_held(
            lambda sql, *args: _mail_budget_execute(env, sql, *args),
            int(Date.now()))
    except Exception:
        return False


async def _mail_provider_hold(env, hold_ms):
    try:
        await mail_budget.hold_provider(
            lambda sql, *args: _mail_budget_execute(env, sql, *args),
            int(Date.now()) + int(hold_ms))
    except Exception:
        pass


async def _mail_log_note(env, kind, to_email, subject, result, status=0,
                         error="", message_id="", sender="", via="", node="",
                         body="", budget="", body_html=""):
    try:
        return await mail_log.enqueue(env, mail_log.note(
            kind, to_email, subject, result, status=status, error=error,
            at=int(Date.now()), message_id=message_id, sender=sender,
            via=via, node=node, body=body, budget=budget,
            body_html=body_html))
    except Exception:
        return False


async def _mail_budget_text(env, email_kind):
    if smtp_mail.enabled(env):
        return ""
    try:
        return await mail_budget.usage(
            lambda sql, *args: d1_all(env, sql, *args), env,
            email_kind, int(Date.now()))
    except Exception:
        return "unavailable"


async def _mail_suppressed(env, recipient_bi, kind):
    row = await d1_first(
        env, "SELECT reason FROM mail_suppressions WHERE recipient_bi=?",
        recipient_bi)
    reason = str((row or {}).get("reason") or "")
    if mail_budget.is_marketing_kind(kind):
        return reason
    if reason == "marketing_unsubscribe":
        return ""
    if reason == "unsubscribe" and kind not in mail_tracking.UNSUBSCRIBE_KINDS:
        return ""
    return reason


async def _mail_tracked_html(env, send_id, html, footer=False):
    base = (getattr(env, "API_ORIGIN", "") or "https://app.forkmesh.com").rstrip("/")
    tok = mail_tracking.token(
        send_id, await blind_index(env, "mail-track:" + send_id))
    if footer:
        return (mail_activity.add_footer(
            html or "", "%s/api/mail/t/l/%s.png" % (base, tok)),
            "%s/api/mail/t/u/%s" % (base, tok))
    signatures = {}
    for match in mail_tracking.HREF_RE.finditer(html or ""):
        target = mail_tracking.href_target(match.group(2))
        if target and target not in signatures:
            signatures[target] = await blind_index(
                env, "mail-click:%s:%s" % (send_id, target))
    html = mail_tracking.rewrite_links(html or "", lambda target: (
        mail_tracking.tracked_link(base, tok, mail_tracking.safe_target(target),
                                signatures[mail_tracking.safe_target(target)])
        if mail_tracking.safe_target(target) in signatures else target))
    return (mail_tracking.add_pixel(html, "%s/api/mail/t/o/%s.gif" % (base, tok)),
            "%s/api/mail/t/u/%s" % (base, tok))


async def _record_email_send(env, send_id, email_kind, to_email, subject,
                             ref="", recipient="", message_id="", sender="",
                             variables=None, body="", body_html=""):
    try:
        await mail_activity.sent(
            env, send_id, clean_string(email_kind or "account", 40),
            to_email, subject, int(Date.now()), ref=ref,
            recipient=recipient, message_id=message_id, sender=sender,
            variables=variables, body=body, body_html=body_html)
    except Exception as error:
        print("mail activity not recorded: %s" % type(error).__name__)


async def _send_email_smtp(env, sender, sender_name, to_email, subject,
                           text, html, email_kind, log, send_id="", ref="",
                           recipient=""):
    kind = clean_string(email_kind or "account", 40)
    send_id = send_id or _ap_uuid()
    recipient_bi = await blind_index(
        env, clean_string(to_email or "", 254).strip().lower())
    try:
        reason = await _mail_suppressed(env, recipient_bi, kind)
    except Exception:
        reason = ""
    if reason:
        await log("suppressed", error="recipient suppressed (%s)" % reason,
                  budget=await _mail_budget_text(env, email_kind))
        return False
    headers = {}
    try:
        if kind in mail_tracking.UNSUBSCRIBE_KINDS:
            html, unsubscribe = await _mail_tracked_html(env, send_id, html)
            headers["List-Unsubscribe"] = "<%s>" % unsubscribe
            headers["List-Unsubscribe-Post"] = "List-Unsubscribe=One-Click"
    except Exception as error:
        print("mail tracking skipped: %s" % _safe_error_text(error)[:120])
    try:
        message_id = await smtp_mail.send(env, smtp_mail.build(
            sender, sender_name, to_email, subject, text, html, kind,
            headers=headers))
    except Exception as error:
        print("smtp send failed: kind %s: %s" % (
            kind, _safe_error_text(error)[:200]))
        await log("failed", error=type(error).__name__)
        return False
    account_bi = await _mailtrap_account_for_email(env, to_email)
    try:
        await d1_run(
            env, "INSERT INTO mail_sends(send_id,message_id,kind,account_bi,"
            "recipient_bi,sent_at,status,status_at) "
            "VALUES(?,?,?,?,?,?,'accepted',?)",
            send_id, message_id.strip("<>"), kind, account_bi, recipient_bi,
            int(Date.now()), int(Date.now()))
        await prune_mail_records(env, int(Date.now()))
    except Exception:
        pass
    await _record_mailtrap_send(
        env, send_id, account_bi, kind, True, message_id=message_id.strip("<>"))
    await _record_email_send(env, send_id, kind, to_email, subject, ref,
                             recipient, message_id.strip("<>"),
                             body=text, body_html=html)
    await log("accepted", message_id=message_id.strip("<>"))
    return True


async def _send_email(env, to_email, subject, text, html=None,
                      from_email=None, from_name=None, email_kind="account",
                      send_id="", ref="", recipient=""):
    provider = mail_providers.provider(env, smtp_mail.enabled(env))
    via_smtp = provider == "smtp"
    token = "" if via_smtp else mail_providers.api_key(env, provider)
    if not to_email:
        return False
    sender = (from_email or getattr(env, "MAIL_SENDER", "")
              or getattr(env, "MAILTRAP_SENDER", "")
              or "no-reply@forkmesh.com").strip()
    via = "postfix" if via_smtp else provider if token else ""
    node = smtp_mail.node() if via_smtp else ""
    body, body_html = text, html

    async def log(result, **extra):
        return await _mail_log_note(
            env, email_kind, to_email, subject, result, sender=sender,
            via=via, node=node, body=body, body_html=body_html, **extra)

    if not (token or via_smtp):
        await log("failed", error="no mail transport configured")
        return False
    if not mail_budget.deliverable(to_email, env):
        print("mail skipped: kind %s: recipient domain receives no mail" % (
            clean_string(email_kind or "account", 40)))
        await log("suppressed", error="recipient domain receives no mail",
                  budget=await _mail_budget_text(env, email_kind))
        return False
    if not via_smtp and await _mail_provider_held(env):
        print("mail skipped: kind %s: mail provider daily limit, waiting for "
              "its reset" % (clean_string(email_kind or "account", 40)))
        await log("suppressed", error="mail provider daily limit",
                  budget=await _mail_budget_text(env, email_kind))
        return False
    if not via_smtp and not await _mail_budget_spend(env, email_kind):
        print("mail skipped: kind %s: daily mail budget spent" % (
            clean_string(email_kind or "account", 40)))
        await log("suppressed", error="daily mail budget spent",
                  budget=await _mail_budget_text(env, email_kind))
        return False
    sender_name = (from_name or getattr(env, "MAIL_SENDER_NAME", "")
                   or getattr(env, "MAILTRAP_SENDER_NAME", "")
                   or instance_name(env)).strip()
    text = str(text or "").rstrip()
    if "Open ForkMesh: " + FORKMESH_SITE_URL not in text:
        text += "\n\nOpen ForkMesh: " + FORKMESH_SITE_URL
    if not html:
        html = _forkmesh_email_card_html(
            _html_escape(subject or "ForkMesh"),
            "A message from ForkMesh.",
            "<div class=\"fm-text\" style=\"white-space:pre-wrap;color:#24292f;"
            "font-size:14px\">" + _html_escape(text) + "</div>",
        )
    elif "data-forkmesh-site-action" not in html:
        action_html = _forkmesh_email_action_html(
            "Open ForkMesh", FORKMESH_SITE_URL)
        closing = "</div></div></body></html>"
        html = (
            html.replace(closing, action_html + closing, 1)
            if closing in html else html + action_html
        )
    html = _light_email_fragment(html)
    subject = instance_features.rename(env, subject)
    text, html = _instance_brand_email(env, text, html)
    if via_smtp:
        return await _send_email_smtp(env, sender, sender_name, to_email,
                                      subject, text, html, email_kind, log,
                                      send_id=send_id, ref=ref,
                                      recipient=recipient)
    account_bi = await _mailtrap_account_for_email(env, to_email)
    send_id = send_id or _ap_uuid()
    message = {
        "sender": sender,
        "senderName": sender_name,
        "to": to_email,
        "subject": subject,
        "text": text,
        "html": html,
        "category": _mailtrap_email_category(email_kind),
        "bulk": mail_budget.is_marketing_kind(email_kind),
    }
    if send_id:
        message["variables"] = {
            "forkmesh_send_id": send_id,
            "forkmesh_account_bi": account_bi,
            "forkmesh_kind": clean_string(email_kind or "account", 40),
        }
    url, headers, request_body = mail_providers.build_request(
        env, provider, message)
    try:
        resp = await js_fetch_with_timeout(
            url,
            {
                "method": "POST",
                "headers": headers,
                "body": request_body,
            },
            CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
        )
        accepted = 200 <= int(getattr(resp, "status", 0)) < 300
        message_id = ""
        if not accepted:
            try:
                detail = clean_string(str(await resp.text()), 300)
            except Exception:
                detail = ""
            hold_ms = mail_budget.provider_limit_hold_ms(detail)
            if hold_ms:
                await _mail_provider_hold(env, hold_ms)
                print("mail held: kind %s: mail provider daily limit reached; "
                      "next send in %ds" % (
                          clean_string(email_kind or "account", 40),
                          hold_ms // 1000))
            else:
                print("%s send rejected: status %s kind %s: %s" % (
                    provider, int(getattr(resp, "status", 0) or 0),
                    clean_string(email_kind or "account", 40), detail))
            await log("rejected", status=int(getattr(resp, "status", 0) or 0),
                      error=detail)
        if accepted:
            try:
                message_id = mail_providers.message_id(
                    provider, resp.headers, str(await resp.text()))
            except Exception:
                message_id = ""
        if accepted:
            await _record_email_send(env, send_id, email_kind, to_email,
                                     subject, ref, recipient, message_id,
                                     body=body, body_html=body_html)
            await log("accepted", message_id=message_id)
        await _record_mailtrap_send(
            env, send_id, account_bi, email_kind, accepted,
            message_id=message_id)
        return accepted
    except Exception as error:
        print("%s send failed: kind %s: %s" % (
            provider, clean_string(email_kind or "account", 40),
            _safe_error_text(error)[:200]))
        await log("failed", error=type(error).__name__)
        await _record_mailtrap_send(
            env, send_id, account_bi, email_kind, False)
        return False


MAILTRAP_WEBHOOK_EVENTS = {
    "delivery",
    "open",
    "click",
    "unsubscribe",
    "spam",
    "soft bounce",
    "bounce",
    "suspension",
    "reject",
}


def _mailtrap_webhook_payload(raw):
    raw = str(raw or "").strip()
    if not raw:
        return None
    try:
        parsed = json.loads(raw)
        if isinstance(parsed, dict):
            parsed = parsed.get("events", [parsed])
        return parsed if isinstance(parsed, list) else None
    except Exception:
        events = []
        for line in raw.splitlines():
            try:
                event = json.loads(line)
            except Exception:
                return None
            if not isinstance(event, dict):
                return None
            events.append(event)
        return events


mailtrap_webhook_handler = _route_handlers.export("mailtrap_webhook_handler")
mail_tracking_handler = _route_handlers.export("mail_tracking_handler")
mail_footer_handler = _route_handlers.export("mail_footer_handler")
mail_footer_image_handler = _route_handlers.export(
    "mail_footer_image_handler")
record_core_mail_event = _route_handlers.export("record_core_mail_event")
prune_mail_records = _route_handlers.export("prune_mail_records")


# --- Account email activity ---------------------------------------------------
#
# Every account-directed send stamps the recipient's own (encrypted) record with
# when the mail went out, a coarse kind, and whether the provider accepted it,
# so the account screen can answer "when were they last emailed, and did it
# land?" without a second log table. Subject and body are never stored here, and
# the stamp is private to the account: it rides the authenticated sessions read,
# not the public profile lookup.
#
# The stamp also carries a running total plus a short bounded history of the
# most recent sends. That history is what the "send it again" verification
# button rate-limits itself against — a send that the provider rejected still
# counts, so a failing mail provider can't be hammered from the dashboard.

ACCOUNT_EMAIL_STATUS_DELIVERED = "delivered"
ACCOUNT_EMAIL_STATUS_FAILED = "failed"
ACCOUNT_EMAIL_HISTORY = 12


def _stamp_account_email(rec, kind, ok, now=None):
    """Stamp the last account-directed email onto an already-loaded record."""
    if not isinstance(rec, dict):
        return rec
    ts = int(now if now is not None else Date.now())
    kind = clean_string(kind or "", 40)
    rec["last_email_ts"] = ts
    rec["last_email_kind"] = kind
    rec["last_email_ok"] = bool(ok)
    try:
        rec["email_send_count"] = int(rec.get("email_send_count") or 0) + 1
    except (TypeError, ValueError):
        rec["email_send_count"] = 1
    history = [item for item in (rec.get("email_sends") or [])
               if isinstance(item, dict)]
    history.append({"ts": ts, "kind": kind, "ok": bool(ok)})
    rec["email_sends"] = history[-ACCOUNT_EMAIL_HISTORY:]
    return rec


def _account_email_sends(rec, kind="", since=0):
    """Bounded send history off a record, newest last, optionally narrowed."""
    kind = clean_string(kind or "", 40)
    sends = []
    for item in ((rec or {}).get("email_sends") or []):
        if not isinstance(item, dict):
            continue
        try:
            ts = int(item.get("ts") or 0)
        except (TypeError, ValueError):
            continue
        if ts <= 0 or ts < int(since or 0):
            continue
        if kind and clean_string(item.get("kind", ""), 40) != kind:
            continue
        sends.append({"ts": ts,
                      "kind": clean_string(item.get("kind", ""), 40),
                      "ok": bool(item.get("ok"))})
    sends.sort(key=lambda item: item["ts"])
    return sends


async def _record_account_email(env, name, kind, ok, fields=None):
    """Load, stamp, and persist the record for a send addressed by node name."""
    name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name):
        return
    try:
        name_bi, rec = await _account_row(env, name)
        if not name_bi or not rec:
            return
        if fields:
            rec.update(fields)
        await _save_account(env, name_bi, _stamp_account_email(rec, kind, ok))
    except Exception:
        pass
    await _notify_admins_account_email(env, name, kind, ok)


async def _notify_admins_account_email(env, name, kind, ok):
    """Ping every platform administrator when transactional mail goes out.

    Only the account-directed sends that route through _record_account_email —
    verification links and password resets — are pinged. They are the ones an
    administrator may have to follow up by hand (a rejected verification lands
    in the manual queue). Cron digest mail is still counted on the recipient's
    record but never pinged, so an hourly digest run over every account cannot
    fan out into a notification storm.
    """
    try:
        kind = clean_string(kind or "", 40)
        label = ACCOUNT_EMAIL_PING_LABELS.get(kind)
        if not label:
            return
        rows = await d1_all(
            env, "SELECT data FROM users WHERE is_admin=1 LIMIT 20")
        ts = int(Date.now())
        body = (label + " email delivered to the mail provider for " + name
                if ok else
                label + " email was rejected by the mail provider for " + name
                + ". It is queued for manual follow-up.")
        for row in rows or []:
            try:
                record = await decrypt_row(env, row.get("data", "")) or {}
            except Exception:
                continue
            admin = clean_string(
                record.get("name", ""), MAX_NODE_NAME).strip().lower()
            if not valid_node_name(admin):
                continue
            await enqueue_notification(
                env, admin, "account_email_sent",
                label + " email sent to " + name,
                body=body,
                href="/dashboard/settings",
                actor=name,
                source="account-email",
                dedupe="account-email:" + name + ":" + kind + ":" + str(ts),
                ts=ts,
                meta={"emailKind": kind, "delivered": bool(ok),
                      "account": name})
    except Exception:
        pass


def _account_email_activity(rec):
    """Public shape of the last-email stamp for the account screen."""
    try:
        ts = int((rec or {}).get("last_email_ts") or 0)
    except (TypeError, ValueError):
        ts = 0
    try:
        count = int((rec or {}).get("email_send_count") or 0)
    except (TypeError, ValueError):
        count = 0
    if ts <= 0:
        return {"lastEmailAt": 0, "lastEmailStatus": "", "lastEmailKind": "",
                "emailSendCount": max(0, count)}
    return {
        "lastEmailAt": ts,
        "lastEmailStatus": (
            ACCOUNT_EMAIL_STATUS_DELIVERED if rec.get("last_email_ok")
            else ACCOUNT_EMAIL_STATUS_FAILED),
        "lastEmailKind": clean_string(rec.get("last_email_kind", ""), 40),
        # Older records predate the counter; one stamped send is the floor.
        "emailSendCount": max(1, count),
    }


# --- External GitHub/GitLab/Codeberg metadata imports -----------------------
#
# Provider imports live in a separate D1 namespace from the mirror catalog.
# repository_imports.py owns the provider-neutral policy/service layer; these
# small adapters supply Worker HTTP, account authorization, and mirror proof.

async def _repository_provider_fetch(env, provider, path, token=""):
    from js import fetch as js_fetch
    repository_import = _repository_import_module()
    if provider not in repository_import.PROVIDERS:
        return {"status": 400, "data": {}, "headers": {}}
    if (not isinstance(path, str) or not path.startswith("/")
            or len(path) > 2000 or "\r" in path or "\n" in path):
        return {"status": 400, "data": {}, "headers": {}}
    headers = {
        "accept": "application/json",
        "user-agent": instance_features.user_agent(
            "ForkMesh-repository-metadata/1.0", "repository-metadata"),
    }
    if provider == "github":
        headers["accept"] = "application/vnd.github+json"
        headers["x-github-api-version"] = "2026-03-10"
        if token:
            headers["authorization"] = "Bearer " + token
    elif provider == "codeberg":
        # Codeberg runs Forgejo's Gitea-compatible API. Its access token is
        # request-scoped exactly like the other provider credentials and is
        # never persisted or forwarded across a redirect.
        if token:
            headers["authorization"] = "token " + token
    elif token:
        # GitLab personal/project access tokens are scoped request credentials.
        # They are never included in a record, log, exception, or D1 write.
        headers["private-token"] = token
    url = repository_import.provider_api_origin(provider) + path
    try:
        response = await js_fetch(
            url, to_js({"method": "GET", "headers": headers,
                        # Never forward a request-scoped provider credential
                        # across an HTTP redirect. Metadata endpoints are
                        # canonical; a moved repository can be re-imported
                        # from its new canonical web URL.
                        "redirect": "manual"}))
        status = int(getattr(response, "status", 0) or 0)
        response_headers = {}
        for name in (
                "x-ratelimit-limit", "x-ratelimit-remaining",
                "x-ratelimit-reset", "ratelimit-limit",
                "ratelimit-remaining", "ratelimit-reset", "retry-after",
                "content-length", "link", "x-next-page", "x-page",
                "x-per-page", "x-total", "x-total-pages"):
            try:
                value = response.headers.get(name)
            except Exception:
                value = None
            if value is not None:
                response_headers[name] = str(value)
        try:
            announced = int(response_headers.get("content-length") or 0)
        except (TypeError, ValueError):
            announced = 0
        if announced > repository_import.MAX_PROVIDER_BODY:
            return {
                "status": 502, "data": {}, "headers": response_headers,
                "error": "provider_response_too_large",
            }
        text = str(await response.text())
        if len(text.encode("utf-8")) > repository_import.MAX_PROVIDER_BODY:
            return {
                "status": 502, "data": {}, "headers": response_headers,
                "error": "provider_response_too_large",
            }
        try:
            data = json.loads(text) if text else {}
        except Exception:
            data = {}
        return {
            "status": status,
            "data": data,
            "headers": response_headers,
        }
    except Exception:
        # Never include exception text: a provider/runtime failure can echo
        # request headers, including the one-use authorization token.
        return {"status": 502, "data": {}, "headers": {}}


async def _repository_import_operator_eligible(env, actor, node):
    """True when `actor` may volunteer `node` to mirror an external import.

    The volunteered name must be a node-kind account the actor owns. A user
    account "owns" itself in _account_owns_node, but a web-only user has no
    process that could ever serve the mirror, so accepting its own name here
    recorded a request nothing would fulfil (issue #680). Rejecting it lets
    the web app show the desktop handoff instead."""
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if not actor or not node:
        return False
    try:
        _, account = await _account_row(env, actor)
        if not account or account.get("status") != "active":
            return False
        node_rec = account if node == actor else (
            await _account_row(env, node))[1]
        if not node_rec or _account_kind(node_rec) != "node":
            return False
        return await _account_owns_node(env, actor, node)
    except Exception:
        return False


async def _repository_import_moderator(env, actor):
    try:
        return bool(
            await _has_role(env, actor, "platform_administrator")
            or await _has_role(env, actor, "moderator"))
    except Exception:
        return False


async def _repository_import_target_owner(env, actor, target):
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    target = clean_string(target, MAX_NODE_NAME).strip().lower() or actor
    if not actor or not target:
        return None
    if target == actor:
        return {
            "name": actor,
            "kind": "user",
            "ownerBi": await blind_index(env, actor),
        }
    org_bi, row = await _org_row(env, target)
    if not row or not _org_rbac.org_role_allows(
            await _org_role(env, org_bi, actor),
            "organization.repositories.import"):
        return None
    return {
        "name": str(row.get("name") or target).lower(),
        "kind": "organization",
        "ownerBi": org_bi,
    }


async def _repository_import_can_manage_owner(env, actor, owner_bi):
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    owner_bi = str(owner_bi or "")
    if not actor or not owner_bi:
        return False
    actor_bi = await blind_index(env, actor)
    if hmac.compare_digest(actor_bi, owner_bi):
        return True
    row = await d1_first(
        env,
        "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
        owner_bi, actor_bi,
    )
    return _org_rbac.org_role_allows(
        (row or {}).get("role"), "organization.repositories.import")


async def _repository_import_managed_owner_bis(env, actor):
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    if not actor:
        return []
    actor_bi = await blind_index(env, actor)
    rows = await d1_all(
        env,
        "SELECT org_bi FROM org_members WHERE member_bi=? "
        "AND role IN ('owner','admin') ORDER BY org_bi LIMIT 199",
        actor_bi,
    )
    return [actor_bi] + [
        str(row.get("org_bi") or "") for row in rows or []
        if str(row.get("org_bi") or "")
    ]


async def _repository_import_mirror_status(
        env, actor, external_record, target_status, data):
    owner = clean_string(
        data.get("mirrorOwner") or actor, MAX_NODE_NAME).strip().lower()
    name = safe_segment(clean_string(
        data.get("mirrorName") or external_record.get("name"),
        MAX_REPO_SEGMENT))
    if not owner or not name:
        return {"verified": False}
    try:
        if owner != actor and not await _account_owns_node(env, actor, owner):
            return {"verified": False}
        repo_bi = await blind_index(env, owner + "/" + name)
        row = await d1_first(
            env,
            "SELECT is_private, data FROM repositories WHERE key_bi=?",
            repo_bi,
        )
        if not row:
            return {"verified": False}
        # Linking a public external stub to a private catalog entry would make
        # the public status disclose that the private repo exists. Do not trust
        # the historical plaintext flag by itself: migration 0011 defaulted
        # old/ambiguous rows to public.
        catalog_record = await decrypt_row(env, row.get("data"))
        visibility = (catalog_record or {}).get("visibility")
        if visibility not in ("public", "private"):
            return {"verified": False}
        if (visibility == "private") != bool(external_record.get("isPrivate")):
            return {"verified": False}
        cutoff = int(Date.now()) - HOST_PRESENCE_STALE_MS
        live = await d1_first(
            env,
            "SELECT 1 AS one FROM host_presence WHERE repo_bi=? AND ts>=?",
            repo_bi, cutoff,
        )
        return {
            "verified": True,
            "owner": owner,
            "name": name,
            "live": bool(live),
        }
    except Exception:
        return {"verified": False}


async def _repository_invitation_token(
        env, import_id, invitation_id, email):
    canonical = (
        "forkmesh-contributor-invitation-v1\n" + str(import_id) + "\n"
        + str(invitation_id) + "\n" + str(email).strip().lower()
    ).encode()
    return hmac.new(
        _account_session_secret(env), canonical, "sha256").hexdigest()


async def _repository_import_audit(
        env, actor, action, target_type, target, outcome, details):
    await _audit_sensitive_action(
        env, actor, action, target_type, target, outcome, details)


async def _repository_migration_sign(env, state_hash):
    """Authenticate a canonical migration state without a provider secret.

    This relay receipt does not impersonate source-provider signatures.  Its
    stable HMAC proves that the same ForkMesh deployment produced the report;
    the source ids and payload hashes under that receipt remain exportable for
    later adapter reconciliation.
    """
    canonical = (
        "forkmesh-repository-migration-state-v1\n" + str(state_hash or "")
    ).encode()
    return {
        "algorithm": "hmac-sha256",
        "keyId": "forkmesh-relay-migration-v1",
        "signature": hmac.new(
            _account_session_secret(env), canonical, "sha256").hexdigest(),
    }


async def _repository_migration_report_sign(env, message):
    """Sign a migration report so it can be verified without a secret.

    Reports use the relay's Ed25519 router key, whose public half is published
    as ``routerPublicKey``. A deployment without that key falls back to the
    relay HMAC, and the report names the algorithm it actually got.
    """
    public_key = _https_mirror_router_public_key(env)
    signing_seed = _https_mirror_router_seed(env)
    if public_key and signing_seed:
        signature = await ed25519_sign(public_key, signing_seed, bytes(message))
        if signature:
            return {
                "algorithm": "ed25519",
                "keyId": "forkmesh-mirror-router",
                "publicKey": public_key,
                "signature": signature,
            }
    return {
        "algorithm": "hmac-sha256",
        "keyId": "forkmesh-relay-migration-report-v1",
        "signature": hmac.new(
            _account_session_secret(env), bytes(message), "sha256").hexdigest(),
    }


def _repository_import_service():
    repository_import = _repository_import_module()
