# Preservation-first crisis onboarding (www/docs/crisis-preservation.md). A plan
# is a pure function of its query, so it is public and edge-cacheable. The
# assessment and drill read owner-only migration reports, so they run in
# tools/forkmesh_crisis_preservation.py and never send a report here.
async def crisis_preservation_plan_handler(env, request):
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    params = parse_qs(urlparse(request.url).query)
    query = {key: values[0] for key, values in params.items() if values}
    if not query.get("scenario"):
        return json_response(crisis_preservation.catalog(), cache_seconds=300)
    try:
        plan = crisis_preservation.build_plan(query)
    except crisis_preservation.PlanRequestError as exc:
        return json_response(
            {"error": exc.code, "detail": exc.detail}, status=400)
    return json_response(plan, cache_seconds=300)


EMAIL_VERIFICATION_TOKEN_TTL_MS = 72 * 60 * 60 * 1000
EMAIL_VERIFICATION_FUTURE_SKEW_MS = 5 * 60 * 1000
EMAIL_VERIFICATION_TTL_HOURS = EMAIL_VERIFICATION_TOKEN_TTL_MS // 3600000
EMAIL_VERIFY_LINK_TOKEN_RE = re.compile(r"^[A-Za-z0-9_-]{51}$")


def _email_verify_link_token(issued_at, mac):
    raw = int(issued_at).to_bytes(6, "big") + bytes(mac)[:32]
    return base64.urlsafe_b64encode(raw).decode().rstrip("=")


def _email_verify_link_parts(token):
    token = str(token or "")
    if not EMAIL_VERIFY_LINK_TOKEN_RE.match(token):
        return 0, ""
    try:
        raw = base64.urlsafe_b64decode(token + "=")
    except (ValueError, TypeError):
        return 0, ""
    if len(raw) != 38:
        return 0, ""
    return int.from_bytes(raw[:6], "big"), raw[6:].hex()


def _email_verify_masked(email):
    local, _, domain = str(email or "").partition("@")
    if not local or not domain:
        return ""
    return local[:1] + "•••@" + domain


def _email_verification_issued_at(value, now=None):
    try:
        issued_at = int(value or 0)
        now = int(Date.now() if now is None else now)
    except (TypeError, ValueError, OverflowError):
        return 0
    if (issued_at <= 0
            or issued_at > now + EMAIL_VERIFICATION_FUTURE_SKEW_MS
            or now - issued_at > EMAIL_VERIFICATION_TOKEN_TTL_MS):
        return 0
    return issued_at


async def _email_verify_mac(env, prefix, name, email, issued_at):
    key = await _hmac_key(env)
    msg = (prefix + "\n" + (name or "") + "\n"
           + (email or "") + "\n" + str(int(issued_at or 0))).encode()
    sig = await js_crypto.subtle.sign(
        "HMAC", key, Uint8Array.new(_to_js(bytes(msg))))
    return bytes(Uint8Array.new(sig).to_py())


async def _email_verify_token(env, name, email, issued_at):
    return (await _email_verify_mac(
        env, "forkmesh-email-verify-v2", name, email, issued_at)).hex()[:32]


async def _email_verify_link(env, name, email, issued_at):
    return _email_verify_link_token(issued_at, await _email_verify_mac(
        env, "forkmesh-email-verify-v3", name, email, issued_at))


async def _email_verify_link_valid(env, name, email, params):
    token = clean_string(params.get("token", [""])[0], 64)
    if not token:
        return 0
    if params.get("issuedAt"):
        issued_at = _email_verification_issued_at(params["issuedAt"][0])
        expected = (await _email_verify_token(env, name, email, issued_at)
                    if issued_at else "")
        return issued_at if expected and hmac.compare_digest(
            token, expected) else 0
    issued_at, mac_hex = _email_verify_link_parts(token)
    issued_at = _email_verification_issued_at(issued_at)
    if not issued_at:
        return 0
    expected = (await _email_verify_mac(
        env, "forkmesh-email-verify-v3", name, email, issued_at)).hex()
    return issued_at if hmac.compare_digest(mac_hex, expected) else 0


def _public_base_url(env, request=None):
    base = (getattr(env, "PUBLIC_BASE_URL", "") or "").strip().rstrip("/")
    if base:
        return base
    try:
        u = urlparse(request.url)
        if u.scheme and u.netloc:
            return u.scheme + "://" + u.netloc
    except Exception:
        pass
    return ""


async def _send_verification_email(env, request, name, email, rec=None):
    issued_at = int(Date.now())
    token = await _email_verify_link(env, name, email, issued_at)
    link = (_public_base_url(env, request) +
            "/api/accounts/verify-email?node=" + quote(name)
            + "&token=" + token)
    link_terms = (
        "The link works for " + str(EMAIL_VERIFICATION_TTL_HOURS)
        + " hours. Requesting a new email cancels this link, and ForkMesh "
        "never asks for your password on the confirmation page.")
    docs_url = "https://forkmesh.com/docs"
    blogs_url = "https://forkmesh.com/blogs"
    feedback_email = "founders@forkmesh.com"
    display_name = name or "there"
    safe_name = _html_escape(display_name)
    safe_link = _html_escape(link)
    subject = "Welcome to ForkMesh, " + display_name
    text = ("Hi " + display_name + ",\n\n"
            "Welcome to ForkMesh, " + display_name + ". Confirm your email to finish setting up your "
            "account:\n" + link + "\n\n"
            "Opening the link shows a confirmation page. Your address is only "
            "verified after you press Confirm email on that page. "
            + link_terms + "\n\n"
            "Next steps:\n"
            "- Read the docs: " + docs_url + "\n"
            "- Browse product notes and guides: " + blogs_url + "\n\n"
            "What was confusing, missing, or most useful as you got started? "
            "Send feedback to " + feedback_email + ".\n\n"
            "If you did not create this account, you can ignore this email.")
    intro = ("Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" + safe_name +
              "</strong>, open the confirmation page and press Confirm email "
              "to finish setting up your account.")
    body_html = (
        "<p style=\"margin:0 0 22px\"><a href=\"" + safe_link + "\" "
        "style=\"display:inline-block;background:#4ade80;color:#052e16;"
        "text-decoration:none;border-radius:8px;padding:10px 14px;"
        "font-size:14px;font-weight:800\">Confirm your email</a></p>"
        "<div class=\"fm-border\" style=\"border-top:1px solid #313134;padding-top:18px;"
        "margin-top:4px\">"
        "<p class=\"fm-strong\" style=\"margin:0 0 10px;color:#f5f5f5;font-size:15px;"
        "font-weight:700\">Next steps</p>"
        "<p class=\"fm-text\" style=\"margin:0 0 8px;color:#d4d4d8;font-size:14px\">Read the "
        "<a href=\"" + docs_url + "\" class=\"fm-link\" style=\"color:#4ade80;"
        "text-decoration:none\">ForkMesh docs</a>.</p>"
        "<p class=\"fm-text\" style=\"margin:0 0 18px;color:#d4d4d8;font-size:14px\">Browse "
        "<a href=\"" + blogs_url + "\" class=\"fm-link\" style=\"color:#4ade80;"
        "text-decoration:none\">product notes and guides</a>.</p>"
        "<p class=\"fm-muted\" style=\"margin:0;color:#a3a3a3;font-size:14px\">What was confusing, "
        "missing, or most useful as you got started? Send feedback to "
        "<a href=\"mailto:" + feedback_email + "\" class=\"fm-link\" style=\"color:#4ade80;"
        "text-decoration:none\">" + feedback_email + "</a>.</p>"
        "</div>")
    footer_html = (
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">"
        + _html_escape(link_terms) + "</p>"
        "<p class=\"fm-muted\" style=\"margin:8px 0 0;color:#8a8a93;font-size:12px\">If you did "
        "not create this account, you can ignore this email.</p>")
    html = _forkmesh_email_card_html(
        "Welcome to ForkMesh, " + safe_name, intro, body_html, footer_html)
    ok = await _send_email(
        env, email, subject, text, html, email_kind="verification")
    fields = {"email_verify_issued_at": issued_at} if ok else None
    if ok and isinstance(rec, dict):
        rec.update(fields)
    await _record_account_email(env, name, "verification", ok, fields)
    return ok


# --- "Send it again" for an unverified email ---------------------------------
#
# The profile POST is the privileged write path, so it demands the account
# password — reasonable for a payout address, pure friction for re-sending a
# confirmation link, and accounts were staying unverified because of it. This
# endpoint takes the signed-in session and nothing else. The account's own send
# history (see _stamp_account_email) is what bounds the retry rate: a queued
# send counts exactly like a delivered one, so a failing provider cannot be
# hammered from the dashboard.

VERIFICATION_RESEND_COOLDOWN_MS = 60 * 1000
VERIFICATION_RESEND_WINDOW_MS = 24 * 60 * 60 * 1000
VERIFICATION_RESEND_WINDOW_LIMIT = 5


async def _verification_resend_refusal(env, name, rec, now):
    recent = _account_email_sends(
        rec, kind="verification", since=now - VERIFICATION_RESEND_WINDOW_MS)
    if recent and now - recent[-1]["ts"] < VERIFICATION_RESEND_COOLDOWN_MS:
        return {"error": "resend_too_soon",
                "retryAfterMs": (VERIFICATION_RESEND_COOLDOWN_MS
                                 - (now - recent[-1]["ts"]))}
    if len(recent) >= VERIFICATION_RESEND_WINDOW_LIMIT:
        return {"error": "resend_limit_reached",
                "retryAfterMs": max(
                    0, VERIFICATION_RESEND_WINDOW_MS - (now - recent[0]["ts"]))}
    slot = int(now) // VERIFICATION_RESEND_COOLDOWN_MS
    try:
        key = await blind_index(
            env, "verification-resend:" + name + "\n" + str(slot))
        result = await d1_run(
            env,
            "INSERT OR IGNORE INTO notification_email_sends "
            "(send_bi, created_at) VALUES (?,?)",
            key, int(now))
        claimed = int(result.meta.changes) > 0
    except Exception:
        claimed = False
    if not claimed:
        return {"error": "resend_too_soon",
                "retryAfterMs": (VERIFICATION_RESEND_COOLDOWN_MS
                                 - int(now) % VERIFICATION_RESEND_COOLDOWN_MS)}
    return None


async def _account_resend_verification(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    # Being unverified is the whole precondition for this endpoint, so it is
    # the one write an unverified session is always allowed to make.
    name_bi, rec = await _account_session_record(
        env, request, data, allow_unverified=True)
    if not name_bi or not rec:
        return json_response({"error": "unauthorized"}, status=401)
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).strip().lower()
    email = clean_string(rec.get("email", ""), 254).strip()
    if not valid_node_name(name) or "@" not in email:
        return json_response({"error": "no_email"}, status=400)
    if rec.get("email_verified"):
        return json_response({"error": "already_verified"}, status=409)

    now = int(Date.now())
    refusal = await _verification_resend_refusal(env, name, rec, now)
    if refusal:
        return json_response(
            refusal, status=429,
            cache_control="no-store, max-age=0, must-revalidate")
    recent = _account_email_sends(
        rec, kind="verification", since=now - VERIFICATION_RESEND_WINDOW_MS)

    sent = await _send_verification_email(env, request, name, email)
    if not sent:
        await _enqueue_verification(env, name_bi, name, email)
    # _send_verification_email already stamped (and pinged the admins about) a
    # freshly loaded copy of this record. Mirror the stamp onto the stale copy
    # held here purely to shape the response — it is never saved, so the
    # persisted counter stays authoritative.
    payload = {
        "ok": True,
        "verificationSent": bool(sent),
        "verificationQueued": not sent,
        "cooldownMs": VERIFICATION_RESEND_COOLDOWN_MS,
        "remaining": max(0, VERIFICATION_RESEND_WINDOW_LIMIT - len(recent) - 1),
    }
    payload.update(_account_email_activity(
        _stamp_account_email(rec, "verification", sent, now)))
    return json_response(
        payload, cache_control="no-store, max-age=0, must-revalidate")


ADMIN_TEST_EMAIL_COOLDOWN_MS = 60 * 1000


async def _account_admin_test_email(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    name_bi, rec = await _account_session_record(env, request, data)
    if not name_bi or not rec:
        return json_response({"error": "unauthorized"}, status=401)
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name) or not await _is_admin(env, name):
        return json_response({"error": "forbidden"}, status=403)
    email = clean_string(rec.get("email", ""), 254).strip()
    if "@" not in email:
        return json_response({"error": "no_email"}, status=400)
    now = int(Date.now())
    recent = _account_email_sends(
        rec, kind="admin_test", since=now - ADMIN_TEST_EMAIL_COOLDOWN_MS)
    if recent:
        return json_response(
            {"error": "resend_too_soon",
             "retryAfterMs": ADMIN_TEST_EMAIL_COOLDOWN_MS - (
                 now - recent[-1]["ts"])},
            status=429, cache_control="no-store, max-age=0, must-revalidate")
    configured = bool(
        (getattr(env, "MAILTRAP_API_TOKEN", "") or "").strip()
        or smtp_mail.enabled(env))
    subject = "ForkMesh test email"
    text = ("This is a test email you requested from ForkMesh settings as "
            + name + ". If you can read it, outgoing mail reaches you.")
    html = _forkmesh_email_card_html(
        subject,
        "Requested from ForkMesh settings by <strong>"
        + _html_escape(name) + "</strong>.",
        "<p class=\"fm-text\" style=\"margin:0;color:#d4d4d8;font-size:14px\">"
        "If you can read this, outgoing mail reaches you.</p>")
    sent = bool(configured and await _send_email(
        env, email, subject, text, html, email_kind="admin_test"))
    await _record_account_email(env, name, "admin_test", sent)
    payload = {"ok": True, "sent": sent, "configured": configured,
               "email": email}
    payload.update(_account_email_activity(
        _stamp_account_email(rec, "admin_test", sent, now)))
    return json_response(
        payload, cache_control="no-store, max-age=0, must-revalidate")


# --- Member-to-member tip notices --------------------------------------------
#
# A member tips another member by signing a SOL transfer on their own machine
# with a key that lives only in their desktop's local encrypted vault, and
# broadcasting it straight to a Solana RPC. ForkMesh is not a party to the
# transfer and this endpoint is deliberately incapable of becoming one: it
# accepts a *public receipt* (chain signature, amount, recipient) after the
# fact and does exactly two things with it — record it, and tell the recipient
# their tip is on the way.
#
# What that means for trust: the caller asserts the amount, so the email says
# what the sender claims and links the signature on an explorer for the
# recipient to check. The signature is the primary key, so a replayed notice
# can never mail anyone twice, and a sender is capped per day.

TIP_NOTICE_DAILY_LIMIT = 25
TIP_NOTICE_WINDOW_MS = 24 * 60 * 60 * 1000
TIP_NOTICE_MAX_LAMPORTS = 1000 * 1000000000  # 1000 SOL; a receipt, not a limit
TIP_SIGNATURE_RE = re.compile(r"^[1-9A-HJ-NP-Za-km-z]{64,88}$")
TIP_NETWORKS = ("mainnet", "devnet", "testnet")


def _format_sol(lamports):
    whole, fraction = divmod(int(lamports), 1000000000)
    text = ("%09d" % fraction).rstrip("0")
    return "%d.%s SOL" % (whole, text or "0")


def _tip_explorer_url(signature, network):
    suffix = "" if network == "mainnet" else "?cluster=" + network
    return "https://explorer.solana.com/tx/" + quote(signature) + suffix


async def _send_tip_email(env, request, sender, recipient, email, lamports,
                          signature, network, task_description="",
                          output_url=""):
    amount = _format_sol(lamports)
    explorer = _tip_explorer_url(signature, network)
    safe_sender = _html_escape(sender)
    safe_recipient = _html_escape(recipient or "there")
    work_payment = bool(task_description and output_url)
    subject = (
        "%s paid you for work on ForkMesh" % sender if work_payment
        else "%s sent you a tip on ForkMesh" % sender)
    text = ("Hi " + (recipient or "there") + ",\n\n"
            + sender + (" has paid you " if work_payment else
                        " has sent you a tip of ") + amount + " to the public "
            "payout address on your ForkMesh profile. It is on its way now — "
            "Solana transfers usually settle within a minute.\n\n" +
            (("Task: " + task_description + "\nWork product: " + output_url
              + "\n\n") if work_payment else "") +
            "Confirm it on-chain:\n" + explorer + "\n\n"
            "ForkMesh did not hold or move these funds: " + sender + " signed "
            "the transfer with their own wallet key and broadcast it directly. "
            "The amount above is what they reported, so check the explorer "
            "link for the authoritative figure.\n\n"
            "You can change or remove your payout address any time from your "
            "ForkMesh profile.")
    intro = ("Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
             safe_recipient + "</strong>, <strong class=\"fm-strong\" "
             "style=\"color:#f5f5f5\">" + safe_sender + "</strong> sent you a " +
             ("payment of " if work_payment else "tip of ") +
             "<strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
             _html_escape(amount) + "</strong>.")
    body_html = (
        "<p class=\"fm-text\" style=\"margin:0 0 18px;color:#d4d4d8;font-size:14px\">"
        "It is on its way to the public payout address on your ForkMesh "
        "profile. Solana transfers usually settle within a minute.</p>" +
        (("<p class=\"fm-text\" style=\"margin:0 0 18px;color:#d4d4d8;"
          "font-size:14px\"><strong>Task:</strong> "
          + _html_escape(task_description) + "<br><strong>Work product:</strong> "
          "<a href=\"" + _html_escape(output_url) + "\">"
          + _html_escape(output_url) + "</a></p>") if work_payment else "") +
        "<div class=\"fm-border\" style=\"border-top:1px solid #313134;"
        "padding-top:18px;margin-top:22px\">"
        "<p class=\"fm-muted\" style=\"margin:0;color:#a3a3a3;font-size:14px\">"
        "ForkMesh did not hold or move these funds — " + safe_sender +
        " signed the transfer with their own wallet key and broadcast it "
        "directly. The amount above is what they reported, so the explorer "
        "link is the authoritative figure.</p></div>")
    footer_html = (
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">"
        "You are getting this because your ForkMesh profile lists a public "
        "payout address. Remove it from your profile to stop these emails.</p>")
    html = _forkmesh_email_card_html(
        ("You have a work payment" if work_payment
         else "You have a tip on the way"), intro, body_html, footer_html,
        action_label="Confirm it on-chain", action_url=explorer)
    del request
    return await _send_email(env, email, subject, text, html,
                             email_kind="tip")


# A desktop signs a reward payout with a wallet on its own disk, broadcasts it
# itself, and only then reports which chain signature paid which reward. That
# report is the one thing here that needs the *account* — and a desktop that
# authenticated silently holds keys and no session token (see
# ACCOUNT_ALERT_LIST_PROOF for the same gap on the Pings page). On this surface
# that gap costs money: the transfer lands, the report comes back unauthorized,
# and the desktop then holds every later payout behind a receipt it can never
# clear, because an unreported signature cannot be told apart from a transfer
# that never happened.
#
# The proof binds the whole payout — recipient, amount, chain signature and
# reward id — so it authorizes exactly one notice about one transfer and is not
# replayable as a notice about any other. Re-sending the same one is already a
# no-op: tip_notice is keyed by signature.
TIP_NOTICE_PROOF = "forkmesh-account-tip-notice-v1"
TIP_WORK_PAYMENT_PROOF = "forkmesh-account-tip-work-payment-v2"
TIP_NOTICE_PATH_RE = re.compile(r"^/api/accounts/tip-notice/?$")
TIP_TASK_DESCRIPTION_MAX = 360
TIP_OUTPUT_URL_MAX = 1000
TIP_PRICE_MAX_AGE_MS = 60 * 60 * 1000


def _tip_work_payment_context(data, lamports=0, now=None):
    """Validate and canonicalize optional public work-payment context."""
    task = clean_string(
        data.get("taskDescription", ""), TIP_TASK_DESCRIPTION_MAX
    ).strip()
    output_url = clean_string(
        data.get("outputUrl", ""), TIP_OUTPUT_URL_MAX
    ).strip()
    entered_currency = clean_string(
        data.get("enteredCurrency", "SOL"), 3
    ).strip().upper()
    source_address = clean_string(
        data.get("fromAddress", ""), 80
    ).strip()
    try:
        entered_usd_micros = int(data.get("enteredUsdMicros") or 0)
        sol_usd_price_micros = int(data.get("solUsdPriceMicros") or 0)
        price_observed_at = int(data.get("priceObservedAt") or 0)
    except (TypeError, ValueError, OverflowError):
        return None
    if any(value < 0 or value > 9_223_372_036_854_775_807 for value in (
            entered_usd_micros, sol_usd_price_micros,
            price_observed_at)):
        return None
    if not task and not output_url:
        return {
            "task": "", "output_url": "", "currency": "SOL",
            "usd_micros": 0, "price_micros": 0, "price_observed_at": 0,
            "source_address": source_address,
        }
    if not task or not output_url or entered_currency not in ("SOL", "USD"):
        return None
    try:
        parsed_output = urlparse(output_url)
    except Exception:
        return None
    if (parsed_output.scheme not in ("https", "http")
            or not parsed_output.hostname or parsed_output.username
            or parsed_output.password):
        return None
    if not SOLANA_RE.match(source_address):
        return None
    if entered_currency == "USD":
        if (entered_usd_micros <= 0 or sol_usd_price_micros <= 0
                or price_observed_at <= 0):
            return None
        observed_now = int(Date.now()) if now is None else int(now)
        if abs(observed_now - price_observed_at) > TIP_PRICE_MAX_AGE_MS:
            return None
        expected = (
            entered_usd_micros * 1_000_000_000
            + sol_usd_price_micros // 2
        ) // sol_usd_price_micros
        if expected <= 0 or abs(expected - int(lamports or 0)) > 1:
            return None
    elif (entered_usd_micros or sol_usd_price_micros
          or price_observed_at):
        return None
    return {
        "task": task,
        "output_url": output_url,
        "currency": entered_currency,
        "usd_micros": entered_usd_micros,
        "price_micros": sol_usd_price_micros,
        "price_observed_at": price_observed_at,
        "source_address": source_address,
    }


async def _tip_notice_signed_session(env, request, data=None):
    """Resolve the account behind a key-signed payout notice.

    As narrow as _genie_credential_signed_session: one proof, one path, POST
    only. The triple lives in the query string, never the body, so it is read
    on the same terms as every other signed fallback here.

    The signer is named as what it is: `user`, the account whose key signed
    the payout. An account is a person; the machine the proof was made on is
    one of that person's nodes and has no part in it. So the query does not
    call the signer a node, and a triple sent under that name is not read.
    """
    if method_name(request) != "POST" or not isinstance(data, dict):
        return "", None
    url = urlparse(request.url)
    if not TIP_NOTICE_PATH_RE.match(url.path):
        return "", None
    params = parse_qs(url.query)
    user = clean_string(params.get("user", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    if not user or not sig or not _ts_ok(ts):
        return "", None
    recipient = clean_string(data.get("toNodeName", ""), MAX_NODE_NAME).lower()
    signature = clean_string(data.get("signature", ""), 96).strip()
    reward_id = clean_string(data.get("rewardId", ""), 96).strip().lower()
    source_address = clean_string(data.get("fromAddress", ""), 80).strip()
    try:
        lamports = int(data.get("lamports", 0))
    except (TypeError, ValueError):
        return "", None
    if not recipient or not signature:
        return "", None
    if data.get("taskDescription") or data.get("outputUrl"):
        context = _tip_work_payment_context(data, lamports)
        if context is None:
            return "", None
    else:
        context = {
            "task": "", "output_url": "", "currency": "SOL",
            "usd_micros": 0, "price_micros": 0, "price_observed_at": 0,
            "source_address": source_address,
        }
    if context["task"]:
        canonical = "\n".join([
            TIP_WORK_PAYMENT_PROOF, user, str(ts), recipient, str(lamports),
            signature, reward_id, context["task"], context["output_url"],
            context["currency"], str(context["usd_micros"]),
            str(context["price_micros"]), str(context["price_observed_at"]),
            context["source_address"],
        ]).encode()
    else:
        canonical = "\n".join([
            TIP_NOTICE_PROOF, user, str(ts), recipient, str(lamports),
            signature, reward_id,
        ]).encode()
    # The same durable desktop identity the other signed fallbacks accept: an
    # account_devices key, never promoted to the account's primary pubkey.
    if not await _verify_owner_signature(env, user, sig, canonical):
        return "", None
    account_bi, record = await _account_row(env, user)
    if (
        not account_bi
        or not record
        or record.get("status") != "active"
        or _account_kind(record) != "user"
    ):
        return "", None
    return account_bi, record


async def _account_tip_notice(env, request):
    """Record a locally-signed member tip and email its recipient."""
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, sender_rec = await _account_session_record(env, request, data)
    if not sender_rec:
        # Only ever a fallback, and only for a fully signed payout: a browser
        # session is still the ordinary way in, and nothing below is reached
        # without one credential or the other.
        _, sender_rec = await _tip_notice_signed_session(env, request, data)
    sender = (sender_rec.get("name", "") if sender_rec else "").strip().lower()
    if not sender:
        return json_response({"error": "unauthorized"}, status=401,
                             cache_control="no-store")

    recipient = clean_string(data.get("toNodeName", ""), MAX_NODE_NAME).lower()
    signature = clean_string(data.get("signature", ""), 96).strip()
    network = clean_string(data.get("network", "mainnet"), 16).strip().lower()
    reward_id = clean_string(data.get("rewardId", ""), 96).strip().lower()
    source_address = clean_string(data.get("fromAddress", ""), 80).strip()
    try:
        lamports = int(data.get("lamports", 0))
    except (TypeError, ValueError):
        lamports = 0
    if (not valid_node_name(recipient)
            or not TIP_SIGNATURE_RE.match(signature)
            or network not in TIP_NETWORKS
            or lamports <= 0 or lamports > TIP_NOTICE_MAX_LAMPORTS):
        return json_response({"error": "invalid_tip_notice"}, status=400,
                             cache_control="no-store")
    if data.get("taskDescription") or data.get("outputUrl"):
        context = _tip_work_payment_context(data, lamports)
        if context is None:
            return json_response(
                {"error": "invalid_payment_context"}, status=400,
                cache_control="no-store")
    else:
        context = {
            "task": "", "output_url": "", "currency": "SOL",
            "usd_micros": 0, "price_micros": 0, "price_observed_at": 0,
            "source_address": source_address,
        }
    _, rec = await _account_row(env, recipient)
    if not rec or rec.get("status") not in (None, "", "active"):
        return json_response({"error": "no_such_account"}, status=404,
                             cache_control="no-store")
    # The email tells the recipient a transfer is heading for the payout
    # address on their profile. If they never published one, that sentence is
    # false and the transfer went somewhere the caller chose — refuse rather
    # than relay a claim we cannot square with the account's own record.
    if not SOLANA_RE.match((rec.get("solana") or "").strip()):
        return json_response({"error": "no_payout_address"}, status=409,
                             cache_control="no-store")
    destination_address = (rec.get("solana") or "").strip()

    # Contextual Ledger payments are authoritative records of completed work,
    # not sender assertions. Confirm the exact finalized System transfer before
    # publishing any task or work-product link beside it.
    if context["task"]:
        matches = await _solana_transaction_matches_plan(env, signature, {
            "network": "mainnet-beta" if network == "mainnet" else network,
            "sourceAddress": context["source_address"],
            "transfers": [{
                "address": destination_address,
                "lamports": lamports,
            }],
        })
        if matches is None:
            return json_response({
                "ok": True,
                "status": "submitted",
                "verification": "pending_finality",
            }, status=202, cache_control="no-store")
        if matches is False:
            return json_response(
                {"error": "payment_transaction_mismatch"}, status=409,
                cache_control="no-store")

    reward = None
    if reward_id:
        reward, reward_response = await contributor_reward_payment(
            env, sender, recipient, signature, network, reward_id,
            source_address, lamports, destination_address)
        if reward_response is not None:
            return reward_response

    now = int(Date.now())
    sender_bi = await blind_index(env, sender)
    recipient_bi = await blind_index(env, recipient)

    # An already-recorded signature is a replay (or a retry after the email
    # succeeded): answer 200 so the desktop stops retrying, but send nothing.
    existing = await d1_first(
        env, "SELECT emailed FROM tip_notice WHERE signature=?", signature)
    if existing:
        return json_response({"ok": True, "duplicate": True,
                              "emailed": bool(existing.get("emailed"))},
                             cache_control="no-store")

    recent = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM tip_notice WHERE from_bi=? AND ts >= ?",
        sender_bi, now - TIP_NOTICE_WINDOW_MS)
    if int((recent or {}).get("n", 0)) >= TIP_NOTICE_DAILY_LIMIT:
        return json_response(
            {"error": "rate_limited", "limit": TIP_NOTICE_DAILY_LIMIT},
            status=429, cache_control="no-store")

    # Claim the row before mailing, so a crash mid-send cannot double-send.
    if context["task"]:
        await d1_run(
            env,
            """INSERT INTO tip_notice
                 (signature,from_bi,to_bi,lamports,network,ts,emailed,
                  task_description,output_url,entered_currency,
                  entered_usd_micros,sol_usd_price_micros,price_observed_at)
               VALUES (?,?,?,?,?,?,0,?,?,?,?,?,?)""",
            signature, sender_bi, recipient_bi, lamports, network, now,
            context["task"], context["output_url"], context["currency"],
            context["usd_micros"], context["price_micros"],
            context["price_observed_at"])
    else:
        # Keep the legacy six-argument receipt write for old clients and for
        # mixed-version test/deploy environments; the new columns have safe
        # defaults and contextual payments use the explicit write above.
        await d1_run(
            env,
            """INSERT INTO tip_notice
                 (signature, from_bi, to_bi, lamports, network, ts, emailed)
               VALUES (?,?,?,?,?,?,0)""",
            signature, sender_bi, recipient_bi, lamports, network, now)

    await _award_genies_gift(
        env, sender, recipient, network,
        bool(context["task"]) or reward is not None)

    email = (rec.get("email", "") or "").strip()
    wants_email = (
        bool(email) and bool(rec.get("email_verified"))
        and rec.get("email_notifications") is not False
        and notification_email_enabled(rec, "tip_sent"))
    emailed = False
    if wants_email:
        emailed = await _send_tip_email(
            env, request, sender, recipient, email, lamports, signature,
            network, context["task"], context["output_url"])
        if emailed:
            await d1_run(
                env, "UPDATE tip_notice SET emailed=1 WHERE signature=?",
                signature)
            await _record_account_email(env, recipient, "tip", True)

    await enqueue_notification(
        env, recipient, "tip_sent",
        ("%s paid you for completed work" % sender
         if context["task"] else "%s sent you a tip" % sender),
        body=(
            "%s for %s" % (_format_sol(lamports), context["task"])
            if context["task"] else
            "%s is on the way to your payout address." % _format_sol(lamports)
        ),
        href=(context["output_url"] or _tip_explorer_url(signature, network)),
        actor=sender, source="tip:" + signature,
        dedupe="tip:" + signature, ts=now)

    response = {"ok": True, "emailed": emailed,
                "notified": True,
                "rewardId": reward_id,
                "rewardStatus": "paid" if reward else "",
                "amount": _format_sol(lamports),
                "taskDescription": context["task"],
                "outputUrl": context["output_url"],
                "custody": "self-custodial-sender-signed"}
    if reward and "sourceBalanceLamports" in reward:
        response["sourceBalanceLamports"] = reward["sourceBalanceLamports"]
        response["sourceBalanceCheckedAt"] = reward.get(
            "sourceBalanceCheckedAt", 0)
    return json_response(response, cache_control="no-store")


# --- "How are we doing?" founder feedback email -------------------------------
#
# Sent ONCE per user account, ~24h after signup, from founders@forkmesh.com so
# a plain reply lands with the founders. The feedback_email_sends row is both
# the once-only guard and the admin-visible send log; it is claimed BEFORE the
# send (and released on a definite failure) so a crash can never double-send.
# Existing accounts older than 24h are naturally back-filled by the same
# eligibility rule on the first runs after deploy.

FEEDBACK_EMAIL_DELAY_MS = 24 * 60 * 60 * 1000
FEEDBACK_EMAIL_BATCH = 4            # attempts/tick, including provider failure
FEEDBACK_EMAIL_SCAN = 200           # accounts examined per tick
FEEDBACK_EMAIL_FROM = "founders@forkmesh.com"
FEEDBACK_EMAIL_FROM_NAME = "ForkMesh Founders"


