async def _send_feedback_emails(env):
    if instance_branded(env):
        return 0
    now = int(Date.now())
    # Users with no send row yet; the LEFT JOIN keeps re-scans cheap as the
    # sent set grows. Eligibility (user kind, active, verified email, 24h old)
    # lives in the encrypted record, so decrypt a bounded batch per tick.
    rows = await d1_all(
        env,
        "SELECT u.user_bi AS name_bi, u.data FROM users u"
        " LEFT JOIN feedback_email_sends f ON f.account_bi = u.user_bi"
        " WHERE f.account_bi IS NULL LIMIT ?",
        FEEDBACK_EMAIL_SCAN)
    sent = 0
    attempted = 0
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data"))
        if not rec or rec.get("status") != "active":
            continue
        if _account_kind(rec) != "user":
            continue
        email = clean_string(rec.get("email", "") or "", 254).strip()
        if not email or not rec.get("email_verified"):
            continue
        try:
            created = int(rec.get("created_at") or 0)
        except (TypeError, ValueError):
            continue
        if not created or now - created < FEEDBACK_EMAIL_DELAY_MS:
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        if not name:
            continue
        if not mail_budget.deliverable(email, env):
            await d1_run(
                env,
                "INSERT OR IGNORE INTO feedback_email_sends"
                " (account_bi, name, sent_at) VALUES (?,?,?)",
                row.get("name_bi"), name, now)
            continue
        if attempted >= FEEDBACK_EMAIL_BATCH:
            break
        attempted += 1
        # Claim first so a crash mid-send can never double-send; release the
        # claim on a definite send failure so the next tick retries.
        await d1_run(
            env,
            "INSERT OR IGNORE INTO feedback_email_sends"
            " (account_bi, name, sent_at) VALUES (?,?,?)",
            row.get("name_bi"), name, now)
        subject, text, html = _feedback_email_content(name)
        ok = await _send_email(env, email, subject, text, html,
                               from_email=FEEDBACK_EMAIL_FROM,
                               from_name=FEEDBACK_EMAIL_FROM_NAME,
                               email_kind="feedback")
        await _save_account(
            env, row.get("name_bi"),
            _stamp_account_email(rec, "feedback", ok, now))
        if ok:
            sent += 1
        else:
            await d1_run(
                env, "DELETE FROM feedback_email_sends WHERE account_bi=?",
                row.get("name_bi"))
    return sent


async def _password_reset_token(env, name, email, pass_hash, expires):
    # Stateless, deterministic reset token bound to (name, email, current
    # password hash, expiry). Only the server can compute it (keyed by DATA_KEY
    # via the blind-index HMAC key, with its own domain-separation prefix), so a
    # valid token in the link proves the recipient controls the mailbox — no
    # token column needed. Binding the *current* pass_hash makes the link
    # single-use: once the password changes the token no longer verifies. The
    # expiry (also carried in the link) bounds how long a leaked link is usable.
    key = await _hmac_key(env)
    msg = ("forkmesh-password-reset-v1\n" + (name or "") + "\n" + (email or "") +
           "\n" + (pass_hash or "") + "\n" + str(expires)).encode()
    sig = await js_crypto.subtle.sign(
        "HMAC", key, Uint8Array.new(_to_js(bytes(msg))))
    return bytes(Uint8Array.new(sig).to_py()).hex()[:32]


async def _send_password_reset_email(env, request, name, email, pass_hash):
    expires = int(Date.now()) + PASSWORD_RESET_TTL_MS
    token = await _password_reset_token(env, name, email, pass_hash, expires)
    link = (_public_base_url(env, request) +
            "/reset-password?node=" + quote(name) +
            "&exp=" + str(expires) + "&token=" + token)
    subject = "Reset your ForkMesh password"
    text = ("A password reset was requested for your ForkMesh node \"" + name +
            "\".\n\nOpen this link to choose a new password:\n" + link +
            "\n\nThis link expires in 1 hour. If you didn't request a reset, "
            "you can ignore this email — your password won't change.")
    safe_name = _html_escape(name or "")
    safe_link = _html_escape(link)
    intro = ("A password reset was requested for your ForkMesh node "
              "<strong class=\"fm-strong\" style=\"color:#f5f5f5\">" + safe_name + "</strong>.")
    body_html = (
        "<p style=\"margin:0 0 22px\"><a href=\"" + safe_link + "\" "
        "style=\"display:inline-block;background:#4ade80;color:#052e16;"
        "text-decoration:none;border-radius:8px;padding:10px 14px;"
        "font-size:14px;font-weight:800\">Choose a new password</a></p>")
    footer_html = (
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">This link "
        "expires in 1 hour. If you didn't request a reset, you can ignore this email — your "
        "password won't change.</p>")
    html = _forkmesh_email_card_html("Reset your password", intro, body_html, footer_html)
    ok = await _send_email(
        env, email, subject, text, html, email_kind="password_reset")
    await _record_account_email(env, name, "password_reset", ok)
    return ok


_password_reset = _LazyModule("password_reset")


_account_forgot_password = _password_reset.export(
    "_account_forgot_password")
_account_forgot_password_challenge = _password_reset.export(
    "_account_forgot_password_challenge")
# The signed-in counterpart of that emailed flow: change the password from
# Settings, with no sign-out and no email round trip (issue #648).
_account_change_password = _password_reset.export(
    "_account_change_password")


# Step 2 of a password reset: the emailed link posts back the node name, expiry,
# token and a new password. The token is recomputed from the account's current
# pass_hash + the expiry, so a stale/used/tampered link fails, and the new
# password is PBKDF2-hashed and stored.
async def _account_reset_password(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(
        data.get("node", "") or data.get("nodeName", ""), MAX_NODE_NAME).lower()
    token = clean_string(data.get("token", ""), 64)
    password = (data.get("password", "") or "")[:256]
    try:
        expires = int(data.get("exp", 0))
    except (TypeError, ValueError):
        expires = 0
    if len(password) < 8:
        return json_response({"error": "password_too_short"}, status=400)
    if not name or not token or not expires:
        return json_response({"error": "invalid_reset_token"}, status=400)
    if int(Date.now()) > expires:
        return json_response({"error": "reset_link_expired"}, status=400)
    name_bi, rec = await _account_row(env, name)
    if (not rec or rec.get("status") != "active" or not rec.get("email") or
            not rec.get("pass_hash")):
        return json_response({"error": "invalid_reset_token"}, status=400)
    expected = await _password_reset_token(
        env, name, rec.get("email", ""), rec.get("pass_hash", ""), expires)
    if not hmac.compare_digest(token, expected):
        return json_response({"error": "invalid_reset_token"}, status=400)
    salt, phash = await hash_password(password)
    rec["pass_salt"] = salt
    rec["pass_hash"] = phash
    await _save_account(env, name_bi, rec)
    await _account_revoke_sessions(env, name_bi)
    # A successful reset also lifts any brute-force lockout so the user can log in
    # right away, whether they log in by node name or by email.
    await _login_clear(env, name_bi)
    if rec.get("email"):
        await _login_clear(env, await blind_index(env, rec.get("email", "")))
    return json_response({"ok": True})


def _verify_email_page(message, status):
    # This intentionally contains no script or automatic request. Email
    # scanners may load the GET page, but only a person's form POST changes
    # account state.
    body = ("<!doctype html><meta charset=utf-8>"
            "<meta name=\"color-scheme\" content=\"light dark\">"
            "<title>ForkMesh email</title>"
            "<body style=\"font-family:system-ui,sans-serif;max-width:32rem;"
            "margin:4rem auto;padding:0 1rem;line-height:1.5\">" + message +
            "</body>")
    return Response(body, status=status,
                    headers={
                        "content-type": "text/html; charset=utf-8",
                        "cache-control": "no-store, max-age=0",
                        "referrer-policy": "no-referrer",
                        "x-content-type-options": "nosniff",
                        "content-security-policy": (
                            "default-src 'none'; style-src 'unsafe-inline'; "
                            "form-action 'self'; base-uri 'none'; "
                            "frame-ancestors 'none'"),
                    })


async def _verify_email(env, request):
    method = method_name(request)
    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
    elif method == "POST":
        try:
            raw = await request.text()
        except Exception:
            raw = ""
        if len(raw.encode("utf-8")) > 2048:
            return _verify_email_page(
                "<h1>Verification request invalid</h1>", 400)
        params = parse_qs(raw)
    else:
        return _verify_email_page(
            "<h1>Method not allowed</h1>", 405)
    name = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    name_bi, rec = await _account_row(env, name)
    email = (rec or {}).get("email", "")
    issued_at = (await _email_verify_link_valid(env, name, email, params)
                 if email else 0)
    if issued_at:
        safe_name = _html_escape(name)
        safe_email = _html_escape(_email_verify_masked(email))
        if rec.get("email_verified"):
            return _verify_email_page(
                "<h1>Email already confirmed</h1><p>The address for <strong>"
                + safe_name + "</strong> is already verified. This link "
                "cannot change anything. <a href=\"/login\">Log in</a>.</p>",
                200)
        latest = int(rec.get("email_verify_issued_at") or 0)
        if latest and issued_at != latest:
            return _verify_email_page(
                "<h1>This link was replaced</h1><p>A newer confirmation "
                "email was sent to " + safe_email + " after this one, so "
                "this link no longer works. Open the most recent email from "
                "ForkMesh, or <a href=\"/login\">log in</a> to send a new "
                "one.</p>", 410)
        if method == "GET":
            token = clean_string(params.get("token", [""])[0], 64)
            hidden = ("<input type=\"hidden\" name=\"issuedAt\" value=\""
                      + str(issued_at) + "\">"
                      if params.get("issuedAt") else "")
            return _verify_email_page(
                "<h1>Confirm your email</h1>"
                "<p>Press the button to verify <strong>" + safe_email
                + "</strong> for the ForkMesh account <strong>"
                + safe_name + "</strong>.</p>"
                "<form method=\"post\" action=\"/api/accounts/verify-email\">"
                "<input type=\"hidden\" name=\"node\" value=\""
                + safe_name + "\">" + hidden +
                "<input type=\"hidden\" name=\"token\" value=\""
                + _html_escape(token) + "\">"
                "<button type=\"submit\" style=\"font:inherit;padding:.65rem 1rem;"
                "cursor:pointer\">Confirm email</button></form>"
                "<p><small>No account change occurs until this button is "
                "pressed.</small></p>"
                "<p><small>This link was sent only to " + safe_email
                + ", works once, and expires "
                + str(EMAIL_VERIFICATION_TTL_HOURS) + " hours after it was "
                "sent. ForkMesh never asks for your password here.</small></p>",
                200)
        rec["email_verified"] = True
        rec["email_verified_at"] = int(Date.now())
        rec["email_verification_method"] = "recipient_link_post"
        rec.pop("email_verify_issued_at", None)
        await _save_account(env, name_bi, rec)
        await _finalize_referral_signup(env, name_bi)
        try:
            await _hackathon.on_email_verified(env, name_bi, name)
        except Exception:
            pass
        await d1_run(
            env, "DELETE FROM pending_verifications WHERE name_bi=?", name_bi)
        return _verify_email_page(
            "<h1>Email confirmed</h1><p>" + safe_email + " is now the "
            "verified address for <strong>" + safe_name + "</strong>. This "
            "link is now used up. You can close this tab and "
            "<a href=\"/login\">log in</a>.</p>",
            200)
    return _verify_email_page(
        "<h1>Verification link invalid</h1><p>This confirmation link is invalid "
        "or has expired. Try logging in; if your email still shows unverified, "
        "request a new verification email.</p>", 400)


# --- Relay federation -------------------------------------------------------
# Relays exchange signed presence/availability metadata. Historical donation
# proxy endpoints are hard-frozen and require offline custody migration; no
# relay-to-relay request creates a wallet, moves funds, or exposes a seed.

FEDERATION_CANON = "forkmesh-federation-v1"
FEDERATION_NODES_MAX_BYTES = 2 * 1024 * 1024
FEDERATED_HEALTH_MESSAGE_MAX_BYTES = 2048
WORLD_RELAY_HEALTH_FRESH_MS = 10 * 60 * 1000


def _main_relay_url(env):
    return (getattr(env, "MAIN_RELAY_URL", "") or "").strip().rstrip("/")


def _is_main_relay(env):
    return not _main_relay_url(env)


async def _new_ed25519_identity():
    # Fresh Ed25519 keypair as (raw pubkey base64url, seed base64url) — the same
    # base64url-raw shape the desktop identity and ed25519_verify use.
    pair = await js_crypto.subtle.generateKey(
        to_js({"name": "Ed25519"}), True, _to_js(["sign", "verify"]))
    pub_raw = await js_crypto.subtle.exportKey("raw", pair.publicKey)
    pub = bytes(Uint8Array.new(pub_raw).to_py())
    jwk = await js_crypto.subtle.exportKey("jwk", pair.privateKey)
    seed = str(getattr(jwk, "d", "") or "")
    if len(pub) != 32 or not seed:
        return None
    return {"pubkey": _b64url_encode(pub), "seed": seed}


async def ed25519_sign(pubkey_b64url, seed_b64url, data_bytes):
    # Sign relay-federation metadata with the relay's non-wallet identity key.
    # This key cannot authorize a Solana transaction and is domain-separated
    # from every wallet/reward flow.
    try:
        jwk = {"kty": "OKP", "crv": "Ed25519", "x": pubkey_b64url,
               "d": seed_b64url, "ext": True, "key_ops": ["sign"]}
        key = await js_crypto.subtle.importKey(
            "jwk", to_js(jwk), to_js({"name": "Ed25519"}), False, _to_js(["sign"]))
        sig = await js_crypto.subtle.sign(
            to_js({"name": "Ed25519"}), key,
            Uint8Array.new(_to_js(bytes(data_bytes))))
        return _b64url_encode(bytes(Uint8Array.new(sig).to_py()))
    except Exception:
        return ""


async def _relay_identity(env):
    # This (federated) relay's own signing identity, auto-generated once and kept
    # in D1 so the operator needs no key management — only MAIN_RELAY_URL.
    row = await d1_first(env, "SELECT data FROM relay_self WHERE id=1")
    if row:
        ident = await decrypt_row(env, row.get("data"))
        if ident and ident.get("pubkey") and ident.get("seed"):
            return ident
    ident = await _new_ed25519_identity()
    if not ident:
        return None
    await d1_run(
        env,
        "INSERT INTO relay_self (id, data) VALUES (1, ?) "
        "ON CONFLICT(id) DO UPDATE SET data=excluded.data",
        await encrypt_row(env, ident))
    return ident


_federation = _LazyModule("federation")
_federation_canonical = _federation.export("_federation_canonical")
_federation_register = _federation.export("_federation_register")
_federation_announce = _federation.export("_federation_announce")
_federation_donation_address = _federation.export("_federation_donation_address")
_federation_donation_status = _federation.export("_federation_donation_status")
_federation_nodes = _federation.export("_federation_nodes")
federation_handler = _federation.export("federation_handler")
_federation_treasury_address = _federation.export("_federation_treasury_address")
_federation_central_fund = _federation.export("_federation_central_fund")
_federation_report_nodes = _federation.export("_federation_report_nodes")
_federation_cron = _federation.export("_federation_cron")


async def _relay_sign_headers(env, body_str):
    ident = await _relay_identity(env)
    if not ident:
        return None
    ts = str(int(Date.now()))
    body_hash = await sha256_hex(body_str)
    sig = await ed25519_sign(
        ident["pubkey"], ident["seed"],
        _federation_canonical(ident["pubkey"], ts, body_hash))
    if not sig:
        return None
    return {"content-type": "application/json", "X-Relay-Pubkey": ident["pubkey"],
            "X-Relay-Ts": ts, "X-Relay-Sig": sig}


async def _call_main_relay(env, path, body_dict):
    base = _main_relay_url(env)
    if not base:
        return None
    body_str = json.dumps(body_dict)
    headers = await _relay_sign_headers(env, body_str)
    if not headers:
        return None

    async def _post(target_path):
        try:
            resp = await js_fetch_with_timeout(
                base + target_path,
                {"method": "POST", "headers": headers, "body": body_str},
                CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
            )
            text = await resp.text()
            data = json.loads(text) if text else {}
            if not isinstance(data, dict):
                return None
            data["_status"] = int(getattr(resp, "status", 0))
            return data
        except Exception:
            return None

    # Callers still pass the legacy /api/federation/* names; prefer the
    # canonical /api/relay-mesh/* route and fall back once for a main relay
    # that hasn't been redeployed with the alias yet.
    reply = await _post(path.replace("/api/federation/", "/api/relay-mesh/", 1))
    if reply is None or reply.get("_status") == 404:
        reply = await _post(path)
    return reply


async def _verify_relay_sig(env, request, body_str):
    # Verify a relay->main request's Ed25519 signature (no approval check).
    pubkey = (request.headers.get("x-relay-pubkey") or "").strip()
    ts = (request.headers.get("x-relay-ts") or "").strip()
    sig = (request.headers.get("x-relay-sig") or "").strip()
    if not pubkey or not sig or not _ts_ok(ts):
        return None
    body_hash = await sha256_hex(body_str or "")
    if not await ed25519_verify(
            pubkey, sig, _federation_canonical(pubkey, ts, body_hash)):
        return None
    return pubkey


async def _relay_authorized(env, request, body_str):
    # As _verify_relay_sig, but also require the relay to be approved. Returns the
    # relay's blind index on success, else None.
    pubkey = await _verify_relay_sig(env, request, body_str)
    if not pubkey:
        return None
    relay_bi = await blind_index(env, pubkey)
    row = await d1_first(
        env, "SELECT status FROM relays WHERE relay_bi=?", relay_bi)
    if not row or row.get("status") != "approved":
        return None
    return relay_bi


