def _ap_origin(env, request=None):
    """Return the public federation origin without loading the AP subsystem.

    Public HTML profile routes need this value before their first D1 read. It
    used to lazy-import the full federation handler module on every cold
    isolate, even for an ordinary browser request, which could consume the
    Worker's CPU allowance before the profile shell was returned.
    """
    base = (getattr(env, "PUBLIC_BASE_URL", "") or "").strip().rstrip("/")
    if base.startswith("https://") or base.startswith("http://"):
        return base
    if request is not None:
        try:
            host = urlparse(request.url).netloc
            if host:
                hostname = host.split(":", 1)[0].lower().rstrip(".")
                if hostname in (
                        "app.forkmesh.com", "forkmesh.com",
                        "world.forkmesh.com"):
                    return "https://forkmesh.com"
                return "https://" + host
        except Exception:
            pass
    return "https://forkmesh.com"


def _ap_domain_of(origin):
    return origin.split("://", 1)[-1]


def _wants_activity_json(accept_header):
    """Cheap HTML-route content negotiation before ActivityPub is imported."""
    accept = (accept_header or "").lower()
    return (
        "application/activity+json" in accept
        or "application/ld+json" in accept
    )


