async def _repo_features_bi(env, owner, repo):
    owner = str(owner or "").strip().lower()
    repo = str(repo or "").strip().lower()
    node = await _org_repo_node(env, owner, repo)
    return await blind_index(
        env, "repo-feature-settings:%s/%s" % (node or owner, repo))


async def _repo_features_get(env, owner, repo):
    row = await d1_first(
        env, "SELECT data FROM repo_feature_settings WHERE repo_bi=?",
        await _repo_features_bi(env, owner, repo))
    features = dict(REPO_FEATURE_DEFAULTS)
    try:
        stored = json.loads((row or {}).get("data") or "{}")
    except ValueError:
        stored = {}
    if isinstance(stored, dict):
        for key in REPO_FEATURE_DEFAULTS:
            if key in stored:
                features[key] = bool(stored[key])
    return features


async def _repo_feature_off(env, owner, repo, feature):
    try:
        features = await _repo_features_get(env, owner, repo)
    except Exception:
        return None
    if features.get(feature, True):
        return None
    return json_response(
        {"error": "feature_disabled", "feature": feature}, status=403)
























async def _ap_process_digest_queues(env, limit=AP_DIGEST_CRON_BATCH):
    """Cron: publish a bounded batch of due, non-empty daily digests."""
    if not await _ap_enabled(env):
        return 0
    now = int(Date.now())
    rows = await d1_all(
        env,
        "SELECT scope_bi, next_ts, last_published_at, data "
        "FROM ap_digest_queues WHERE next_ts<=? "
        "ORDER BY next_ts ASC LIMIT ?",
        now, max(1, min(int(limit), AP_DIGEST_CRON_BATCH)))
    published = 0
    for row in rows or []:
        if await _ap_publish_digest_row(env, row):
            published += 1
    return published


# The unauthenticated ActivityPub read endpoints (webfinger, nodeinfo, actor
# docs, collections, objects) are what fediverse servers and crawlers hammer
# in bursts — every server that sees a federated post resolves the actor and
# its collections, and each of those hits used to reach D1. Under a burst
# that pressure is what pushed the free-plan worker/D1 into "Too many
# requests" (issue #416, round two of adhoc #9). They already sent public
# max-age headers, but dynamic Worker responses are never edge-cached
# implicitly, so store them in the colo cache explicitly: a burst collapses
# to one origin computation per colo per TTL. Keyed by the canonical public
# URL; only successful (200) documents are stored.







# NodeInfo usage counts, cached per isolate. Every fediverse server that hears
# about this instance polls /nodeinfo/2.1, and each hit ran two COUNT(*) table
# scans — pure statistics that don't need to be fresher than the cache TTL,
# and one of the first things to fall over when D1 is under pressure.
_NODEINFO_CACHE = {"ts": 0, "users": 0, "posts": 0}
NODEINFO_CACHE_TTL_MS = 10 * 60 * 1000
















# --- Outbound HTTP: signed fetch, remote actors, delivery ---------------------













# --- Outbound publishing -------------------------------------------------------



# --- Inbound: the shared/actor inbox --------------------------------------------































# --- Client-facing endpoints ----------------------------------------------------

async def repo_media_handler(env, request, owner, repo, media_kind):
    # Owner-uploaded repo branding, served publicly (it is the repo's fediverse
    # avatar/header, fetched by every remote server). Same visibility gate as
    # the actor itself.
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    # Privacy is checked before edge cache lookup: a once-public logo must not
    # remain observable for the cache TTL after its repository becomes private.
    if await _repo_is_private(env, owner, repo):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    # The repo actor's avatar/header: every remote server resolving the actor
    # fetches both images, so a federated post fans out into a burst here.
    # Key includes the ?v=<updated_at> buster from the actor document, so a
    # branding change starts a fresh entry immediately.
    parts = urlparse(request.url)
    cache_key = (_ap_origin(env, request) + parts.path
                 + (("?" + parts.query) if parts.query else ""))
    cached = await edge_cache_match_media(cache_key, "image/png")
    if cached is not None:
        return cached
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env, "SELECT data FROM repo_media WHERE repo_bi=? AND kind=?",
        repo_bi, media_kind)
    rec = await decrypt_row(env, row.get("data")) if row else None
    png_b64 = (rec or {}).get("png", "")
    if not png_b64:
        return json_response({"error": "not_found"}, status=404)
    try:
        raw = base64.b64decode(png_b64)
    except Exception:
        return json_response({"error": "not_found"}, status=404)
    # The actor document busts caches via ?v=<updated_at>, so long edge/browser
    # caching here is safe. Uint8Array.new copies into a JS-owned buffer — a
    # bare _to_js(bytes) view into WASM memory read off the GIL (edge-cache
    # put / client stream, after this returns) crashes the isolate.
    resp = JsResponse.new(Uint8Array.new(_to_js(bytes(raw))), to_js({
        "status": 200,
        "headers": {
            "content-type": "image/png",
            "cache-control": "public, max-age=86400",
        },
    }))
    await edge_cache_put(cache_key, resp)
    return resp


def _repository_social_version(record):
    """Return a public card/page cache token tied to repository state.

    ``stateHash`` authenticates the complete advertised refs set and therefore
    changes for main, tags, or the pull-metadata branch. Older publishers may
    only carry the checked-out commit; that remains a useful state-bound
    fallback. A Worker build revision is deliberately not used: deploying
    unrelated frontend code must not decide whether a repository preview is
    current.
    """
    source = record if isinstance(record, dict) else {}
    state_hash = clean_string(
        source.get("stateHash", ""), 64).strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", state_hash):
        return state_hash
    commit = clean_string(source.get("commit", ""), 64).strip().lower()
    if re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit):
        return commit
    return ""


REPO_CARD_READ_ORIGIN = "https://forkmesh.internal"
REPO_CARD_COUNTS_TTL_MS = 5 * 60 * 1000
REPO_CARD_COUNTS_MAX = 256
_repo_card_counts_memo = {}


async def _repo_card_read(env, owner, repo, operation, query=None,
                          context_cache=None):
    url = "%s/api/repo/%s/%s/%s" % (
        REPO_CARD_READ_ORIGIN, quote(owner, safe=""), quote(repo, safe=""),
        operation)
    if query:
        url += "?" + urlencode(query)
    try:
        response = await _routed_repository_read(
            env, url, operation, context_cache=context_cache)
        if int(getattr(response, "status", 0) or 0) != 200:
            return None
        value = json.loads(str(await response.text()) or "null")
    except Exception:
        return None
    if not isinstance(value, dict) or value.get("ok") is False:
        return None
    return value


async def _repo_card_counts(env, owner, repo):
    key = (str(owner).lower(), str(repo).lower())
    now_ms = int(time.time() * 1000)
    hit = _repo_card_counts_memo.get(key)
    if hit and 0 <= now_ms - hit[0] < REPO_CARD_COUNTS_TTL_MS:
        return dict(hit[1])
    context_cache = {}
    branches, issues, listing = await asyncio.gather(
        _repo_card_read(env, owner, repo, "branches",
                        context_cache=context_cache),
        _repo_card_read(env, owner, repo, "tree",
                        {"path": og_card.ISSUES_OPEN_PATH},
                        context_cache=context_cache),
        _repo_card_read(env, owner, repo, "tree", {"path": ".forkmesh"},
                        context_cache=context_cache))
    contributors = None
    if og_card.has_roster(listing):
        blobs = await _repo_card_read(
            env, owner, repo, "blobs", {"path": og_card.ROSTER_PATH},
            context_cache=context_cache)
        blob = ((blobs or {}).get("blobs") or {}).get(og_card.ROSTER_PATH)
        if isinstance(blob, dict) and not blob.get("truncated") \
                and blob.get("encoding") != "base64":
            contributors = og_card.roster_count(str(blob.get("content") or ""))
    if contributors is None:
        contributors = og_card.stats_contributor_count(
            await _repo_card_read(env, owner, repo, "stats",
                                  context_cache=context_cache),
            instance_name(env))
    counts = {
        "issues": og_card.open_issue_count(issues),
        "branches": og_card.branch_count(branches),
        "contributors": contributors,
    }
    if len(_repo_card_counts_memo) >= REPO_CARD_COUNTS_MAX:
        _repo_card_counts_memo.clear()
    _repo_card_counts_memo[key] = (now_ms, dict(counts))
    return counts


async def _repo_card_accent(env):
    if not instance_branded(env):
        return ""
    try:
        row = await d1_first(
            env, "SELECT doc FROM instance_settings WHERE k='theme'")
        theme = instance_theme.parse((row or {}).get("doc") or "")
    except Exception:
        return ""
    tokens = theme.get("dark") or theme.get("light") or {}
    return str(tokens.get("accent") or tokens.get("primary") or "")


async def repo_card_handler(env, request, owner, repo):
    # instead of a full-bleed logo. Public — same visibility gate as the page
    # it previews — and edge-cached so link-preview fetch bursts after a share
    # cost one render per colo per TTL.
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    # Check the signed catalog record before cache: privacy changes must revoke
    # cached social previews immediately rather than waiting for their TTL.
    if await _repo_is_private(env, owner, repo):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    parts = urlparse(request.url)
    # Organization aliases are rewritten to their backing node before this
    # handler is dispatched, but the original Request URL deliberately stays
    # untouched.  Keep that public identity on the rendered card while using
    # ``owner`` below for every visibility/catalog/media lookup.  Otherwise an
    # unfurl of /forkmesh/forkmesh would advertise mirror2/forkmesh even though
    # the page, canonical URL and clone URL all belong to the organization.
    display_owner = owner
    display_repo = repo
    public_match = REPO_CARD_RE.match(parts.path)
    if public_match:
        candidate_owner = safe_segment(public_match.group(1))
        candidate_repo = safe_segment(public_match.group(2))
        if candidate_owner and candidate_repo == repo:
            if candidate_owner == owner:
                display_owner = candidate_owner
            elif await _org_repo_node(
                    env, candidate_owner, candidate_repo) == owner:
                display_owner = candidate_owner
            display_repo = candidate_repo
    card_version = parse_qs(parts.query).get("v", [""])[0]
    if not re.fullmatch(r"[A-Za-z0-9._-]{1,80}", card_version):
        card_version = ""
    counts = await _repo_card_counts(env, owner, repo)
    cache_key = _ap_origin(env, request) + parts.path
    if card_version:
        cache_key += "?v=" + quote(card_version, safe="") + "&"
    else:
        cache_key += "?"
    cache_key += "n=" + og_card.counts_token(counts)
    cached = await edge_cache_match_media(cache_key, "image/png")
    if cached is not None:
        return cached
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    rec = (await decrypt_row(env, row.get("data"))) or {}
    stars_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM repo_stars WHERE repo_bi=?", repo_bi)
    followers = 0
    if await _ap_enabled(env):
        handle = ap.repo_handle(
            str(display_owner).lower(), str(display_repo).lower())
        actor_bi = await _ap_actor_bi(env, AP_ACTOR_REPO, handle)
        follow_row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        followers = (follow_row or {}).get("c", 0) or 0
    # Mirror count the way the network page groups them: catalog records that
    # share this repo's root commit (memoized decrypted catalog, so this full
    # pass doesn't re-decrypt per request).
    mirrors = 0
    try:
        now_ms = int(time.time() * 1000)
        for entry in await _decrypted_public_catalog(env, now_ms):
            if repo_mirror_same_group(rec, entry.get("data")):
                mirrors += 1
    except Exception:
        mirrors = 0
    info = {
        "owner": display_owner,
        "repo": display_repo,
        "description": rec.get("description", ""),
        "branch": rec.get("branch", ""),
        "host": urlparse(_ap_origin(env, request)).netloc or "forkmesh.com",
        "site": instance_name(env),
        "stars": (stars_row or {}).get("n", 0) or 0,
        "mirrors": max(1, mirrors),
        "issues": rec.get("issueCount", "")
        if counts.get("issues") is None else counts["issues"],
        "pulls": rec.get("pullCount", ""),
        "commits": rec.get("commitCount", ""),
        "branches": rec.get("branchCount", "")
        if counts.get("branches") is None else counts["branches"],
        "contributors": counts.get("contributors") or 0,
        "sizeBytes": rec.get("sizeBytes", 0),
        "updatedAt": rec.get("updatedAt", ""),
        "followers": followers,
        "accent": await _repo_card_accent(env),
    }
    png = og_card.render_repo_card(info, time.time())
    # Stats drift, so keep the browser TTL modest; preview crawlers cache the
    # rendered card on their side anyway. Uint8Array.new copies into a JS-owned
    # buffer — a bare _to_js(bytes) view into WASM memory read off the GIL
    # (edge-cache put / client stream, after this returns) crashes the isolate.
    resp = JsResponse.new(Uint8Array.new(_to_js(bytes(png))), to_js({
        "status": 200,
        "headers": {
            "content-type": "image/png",
            "cache-control": "public, max-age=3600",
        },
    }))
    await edge_cache_put(cache_key, resp)
    return resp


async def _public_repo_owner(env, request, owner, repo, pattern):
    """Owner name a public per-repository preference must be keyed on.

    The router rewrites an organization path to its backing node before a repo
    handler runs. Stars and fork edges are public-repository facts, so they
    retain the untouched verified organization identity instead of silently
    splitting forkmesh/forkmesh's counts across its backing user's namespace.
    `pattern` is the route regex whose first two groups are owner and repo.
    """
    public_owner = str(owner or "").strip().lower()
    try:
        original_match = pattern.match(
            urlparse(str(getattr(request, "url", "") or "")).path)
        requested_owner = safe_segment(
            original_match.group(1)) if original_match else ""
        requested_repo = safe_segment(
            original_match.group(2)) if original_match else ""
        if (
            requested_owner
            and requested_repo == str(repo or "").strip().lower()
            and requested_owner != public_owner
            and await _org_repo_node(
                env, requested_owner, requested_repo) == public_owner
        ):
            return requested_owner
    except Exception:
        pass
    return public_owner


async def _index_repo_fork_edge(env, record, prior, account_bi, repo_bi):
    """Keep repo_forks in step with a repository's published `forkedFrom`.

    Runs on every catalog write that changed a record beyond volatile
    telemetry. The edge is keyed on the fork, so a repository that stops
    declaring a parent - or goes private, which removes it from public
    discovery - drops its row instead of leaving a phantom entry on the
    parent's fork list. Most repositories are not forks and never were, so
    that case costs no D1 write at all. Best-effort otherwise: the fork list is
    a public convenience and must never fail an otherwise valid owner-signed
    publication.
    """
    try:
        record = record or {}
        parent = clean_string(record.get("forkedFrom", ""), 130).strip().lower()
        was_fork = bool(clean_string((prior or {}).get("forkedFrom", ""), 130))
        if not parent and not was_fork:
            return
        fork_owner = clean_string(record.get("owner", ""), MAX_REPO_SEGMENT)
        fork_name = clean_string(record.get("name", ""), MAX_REPO_SEGMENT)
        if (
            not parent
            or not fork_owner
            or not fork_name
            or record.get("visibility") != "public"
        ):
            await d1_run(
                env, "DELETE FROM repo_forks WHERE fork_bi=?", repo_bi)
            return
        parent_bi = await blind_index(env, parent)
        if parent_bi == repo_bi:
            return
        await d1_run(
            env,
            "INSERT INTO repo_forks (parent_bi, fork_bi, account_bi, "
            "fork_owner, fork_name, created_at) VALUES (?,?,?,?,?,?) "
            "ON CONFLICT(parent_bi, fork_bi) DO UPDATE SET "
            "account_bi=excluded.account_bi, fork_owner=excluded.fork_owner, "
            "fork_name=excluded.fork_name",
            parent_bi, repo_bi, account_bi, fork_owner, fork_name,
            int(Date.now()))
        # A repository can be re-pointed at a different upstream; drop the edge
        # it used to declare so it is never listed under two parents at once.
        await d1_run(
            env, "DELETE FROM repo_forks WHERE fork_bi=? AND parent_bi!=?",
            repo_bi, parent_bi)
    except Exception:
        pass


# Same bound as the followers list (_account_follow_handler): each row
# costs one account read for its portrait, so keep the popover's page
# small. The `count` beside it is always the true total.
REPO_FORKS_LIST_LIMIT = 24

# A website fork is an asynchronous control-plane job for one of the caller's
# linked headless mirrors. Jobs deliberately have no expiry: the whole point is
# that both the source and target may be offline when the browser submits one.
# The bounds cap outstanding work while completed rows remain as the
# idempotency record for GitHub-style "one fork with this name" behavior.
WEB_FORK_PENDING_PER_ACCOUNT = 20
WEB_FORK_JOB_BATCH = 20
WEB_FORK_REQUEST_ID_RE = re.compile(r"^[0-9a-f]{36}$")


def _web_fork_job_response(record, status="pending", request_id=""):
    """Return the bounded, public status shape for one encrypted fork job."""
    source_owner = safe_segment(clean_string(
        (record or {}).get("sourceOwner", ""), MAX_NODE_NAME).lower())
    source_name = safe_segment(clean_string(
        (record or {}).get("sourceName", ""), MAX_REPO_SEGMENT).lower())
    target_owner = safe_segment(clean_string(
        (record or {}).get("targetOwner", ""), MAX_NODE_NAME).lower())
    target_name = safe_segment(clean_string(
        (record or {}).get("targetName", ""), MAX_REPO_SEGMENT).lower())
    if not all((source_owner, source_name, target_owner, target_name)):
        return None
    return {
        "requestId": clean_string(request_id, 40),
        "sourceOwner": source_owner,
        "sourceName": source_name,
        "owner": target_owner,
        "name": target_name,
        "forkedFrom": source_owner + "/" + source_name,
        "status": "completed" if status == "completed" else "pending",
        "url": "/" + quote(target_owner) + "/" + quote(target_name),
        "createdAt": int((record or {}).get("createdAt", 0) or 0),
    }


async def _web_fork_eligible_nodes(env, actor, account):
    """Linked active nodes that have published the headless capability.

    A stale/offline catalog row is intentionally sufficient. Requiring a live
    endpoint here would make an offline mirror unable to receive the durable
    job it is supposed to pick up after it reconnects.
    """
    actor = safe_segment(clean_string(actor, MAX_NODE_NAME).lower())
    candidates = []
    if actor and _account_kind(account or {}) == "node":
        candidates.append(actor)
    for value in _owned_nodes(account or {}):
        node = safe_segment(clean_string(value, MAX_NODE_NAME).lower())
        if node and node not in candidates:
            candidates.append(node)
    candidates = candidates[:50]
    if not candidates:
        return []

    active = []
    for node in candidates:
        _, node_record = await _account_row(env, node)
        if (
            node_record
            and node_record.get("status") == "active"
            and _account_kind(node_record) == "node"
        ):
            active.append(node)
    if not active:
        return []

    by_bi = {}
    for node in active:
        by_bi[await blind_index(env, node)] = node
    marks = ",".join("?" for _ in by_bi)
    rows = await d1_all(
        env,
        "SELECT owner_bi,data FROM repositories WHERE owner_bi IN ("
        + marks + ")",
        *by_bi.keys(),
    )
    headless = set()
    for row in rows or []:
        node = by_bi.get(str(row.get("owner_bi") or ""))
        if not node:
            continue
        catalog = await decrypt_row(env, row.get("data"))
        if (
            isinstance(catalog, dict)
            and clean_string(catalog.get("runtimeMode", ""), 12).lower()
            == "headless"
        ):
            headless.add(node)
    return [node for node in active if node in headless]


async def _web_fork_create(env, request, source_owner, source_name):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    actor_bi, account = await _account_session_record(env, request, data)
    actor = safe_segment(clean_string(
        (account or {}).get("name", ""), MAX_NODE_NAME).lower())
    if not actor_bi or not account or not actor:
        return json_response({"error": "unauthorized"}, status=401)

    eligible = await _web_fork_eligible_nodes(env, actor, account)
    requested = safe_segment(clean_string(
        data.get("targetNode", ""), MAX_NODE_NAME).lower())
    if requested:
        if requested not in eligible:
            return json_response({
                "error": "headless_mirror_required",
                "message": (
                    "Choose a linked managed mirror that has published its "
                    "headless capability. It may be offline when you fork."
                ),
            }, status=409, cache_control="no-store")
        eligible = [requested]
    if not eligible:
        return json_response({
            "error": "headless_mirror_required",
            "message": (
                "Link a managed mirror to this account before creating a "
                "website fork. The mirror does not need to be online now."
            ),
        }, status=409, cache_control="no-store")

    source_owner = safe_segment(clean_string(
        source_owner, MAX_NODE_NAME).lower())
    source_name = safe_segment(clean_string(
        source_name, MAX_REPO_SEGMENT).lower())
    if not re.fullmatch(r"[A-Za-z0-9._-]{1,80}", source_name or ""):
        return json_response({
            "error": "unsupported_fork_name",
            "message": "This repository name cannot be hosted by a managed mirror.",
        }, status=422, cache_control="no-store")
    source_repo_bi = await blind_index(
        env, source_owner + "/" + source_name)

    targets = []
    target_by_bi = {}
    for node in eligible:
        target_bi = await blind_index(env, node + "/" + source_name)
        targets.append((node, target_bi))
        target_by_bi[target_bi] = node
    marks = ",".join("?" for _ in targets)
    catalog_rows = await d1_all(
        env,
        "SELECT key_bi,data FROM repositories WHERE key_bi IN (" + marks + ")",
        *(target_bi for _, target_bi in targets),
    )
    occupied = set()
    parent = source_owner + "/" + source_name
    for row in catalog_rows or []:
        target_bi = str(row.get("key_bi") or "")
        occupied.add(target_bi)
        catalog = await decrypt_row(env, row.get("data"))
        if (
            isinstance(catalog, dict)
            and clean_string(catalog.get("forkedFrom", ""), 170).lower()
            == parent
        ):
            existing = _web_fork_job_response({
                "sourceOwner": source_owner,
                "sourceName": source_name,
                "targetOwner": target_by_bi.get(target_bi, ""),
                "targetName": source_name,
                "createdAt": int(Date.now()),
            }, "completed")
            return json_response(
                {"ok": True, "created": True, "queued": False,
                 "fork": existing},
                cache_control="no-store")

    job_rows = await d1_all(
        env,
        "SELECT request_id,target_repo_bi,actor_bi,source_repo_bi,data,status "
        "FROM repository_fork_jobs WHERE target_repo_bi IN (" + marks + ")",
        *(target_bi for _, target_bi in targets),
    )
    for row in job_rows or []:
        target_bi = str(row.get("target_repo_bi") or "")
        occupied.add(target_bi)
        if (
            str(row.get("actor_bi") or "") != actor_bi
            or str(row.get("source_repo_bi") or "") != source_repo_bi
        ):
            continue
        job = await decrypt_row(env, row.get("data"))
        response = _web_fork_job_response(
            job, str(row.get("status") or "pending"),
            str(row.get("request_id") or ""))
        if response:
            pending = response["status"] == "pending"
            return json_response(
                {"ok": True, "created": not pending, "queued": pending,
                 "fork": response},
                status=202 if pending else 200, cache_control="no-store")

    pending_row = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM repository_fork_jobs "
        "WHERE actor_bi=? AND status='pending'",
        actor_bi,
    )
    if int((pending_row or {}).get("n", 0) or 0) >= WEB_FORK_PENDING_PER_ACCOUNT:
        return json_response({
            "error": "too_many_pending_forks",
            "message": "Wait for one of your pending forks to finish.",
        }, status=429, cache_control="no-store")

    chosen = next(
        ((node, target_bi) for node, target_bi in targets
         if target_bi not in occupied),
        None,
    )
    if not chosen:
        return json_response({
            "error": "fork_name_taken",
            "message": (
                "Each eligible mirror already has a repository with this name."
            ),
        }, status=409, cache_control="no-store")
    target_node, target_repo_bi = chosen
    target_node_bi = await blind_index(env, target_node)
    request_id = _random_bytes(18).hex()
    now = int(Date.now())
    origin = _ap_origin(env, request).rstrip("/")
    job = {
        "requestId": request_id,
        "sourceOwner": source_owner,
        "sourceName": source_name,
        "sourceUrl": origin + "/" + quote(source_owner) + "/" + quote(source_name),
        "targetOwner": target_node,
        "targetName": source_name,
        "requestedBy": actor,
        "createdAt": now,
    }
    sealed = await encrypt_row(env, job)
    try:
        await d1_run(
            env,
            "INSERT INTO repository_fork_jobs "
            "(request_id,target_node_bi,target_repo_bi,source_repo_bi,actor_bi,"
            "data,status,created_at,updated_at,completed_at) "
            "VALUES (?,?,?,?,?,?,'pending',?,?,0)",
            request_id, target_node_bi, target_repo_bi, source_repo_bi,
            actor_bi, sealed, now, now,
        )
    except Exception:
        # A concurrent double-click can win the UNIQUE(target_repo_bi) race.
        # Return that exact durable job when it belongs to this caller/source;
        # propagate unrelated D1 failures rather than disguising an outage as
        # a successful fork.
        row = await d1_first(
            env,
            "SELECT request_id,actor_bi,source_repo_bi,data,status "
            "FROM repository_fork_jobs WHERE target_repo_bi=?",
            target_repo_bi,
        )
        if not row or row.get("actor_bi") != actor_bi or (
                row.get("source_repo_bi") != source_repo_bi):
            raise
        existing = _web_fork_job_response(
            await decrypt_row(env, row.get("data")),
            str(row.get("status") or "pending"),
            str(row.get("request_id") or ""))
        if not existing:
            raise
        pending = existing["status"] == "pending"
        return json_response(
            {"ok": True, "created": not pending, "queued": pending,
             "fork": existing},
            status=202 if pending else 200, cache_control="no-store")

    # Payload-free wake-up only. If the node is offline (or this best-effort
    # push is lost), startup/manual catch-up and the daemon's bounded safety
    # check read the same durable row later.
    await notify_repo_host(
        env, target_node, source_name, "forks")
    response = _web_fork_job_response(job, "pending", request_id)
    return json_response(
        {"ok": True, "created": False, "queued": True, "fork": response},
        status=202, cache_control="no-store")


async def repository_fork_jobs_handler(env, request):
    """Signed headless-mirror drain/ack for durable website fork jobs."""
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "DELETE"):
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store", extra_headers={"allow": "GET, DELETE"})
    params = parse_qs(urlparse(request.url).query)
    owner = safe_segment(clean_string(
        params.get("owner", [""])[0], MAX_NODE_NAME).lower())
    if not owner or not await _authorized_owner_signing_key(
            env, request, owner):
        return json_response(
            {"error": "unauthorized"}, status=401,
            cache_control="no-store")
    target_node_bi = await blind_index(env, owner)

    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT request_id,data,created_at FROM repository_fork_jobs "
            "WHERE target_node_bi=? AND status='pending' "
            "ORDER BY created_at ASC LIMIT ?",
            target_node_bi, WEB_FORK_JOB_BATCH,
        )
        pending = []
        for row in rows or []:
            request_id = clean_string(row.get("request_id", ""), 40)
            job = await decrypt_row(env, row.get("data"))
            response = _web_fork_job_response(job, "pending", request_id)
            source_url = clean_string(
                (job or {}).get("sourceUrl", "")
                if isinstance(job, dict) else "", 2048).strip()
            if (
                response
                and WEB_FORK_REQUEST_ID_RE.fullmatch(request_id)
                and response.get("owner") == owner
                and source_url
            ):
                response["sourceUrl"] = source_url
                pending.append(response)
        return json_response(
            {"ok": True, "pending": pending}, cache_control="no-store")

    raw_ids = clean_string(params.get("ids", [""])[0], 1000)
    ids = []
    for value in raw_ids.split(","):
        value = value.strip().lower()
        if WEB_FORK_REQUEST_ID_RE.fullmatch(value) and value not in ids:
            ids.append(value)
        if len(ids) >= WEB_FORK_JOB_BATCH:
            break
    if not ids:
        return json_response(
            {"error": "ids_required"}, status=400,
            cache_control="no-store")
    marks = ",".join("?" for _ in ids)
    rows = await d1_all(
        env,
        "SELECT request_id FROM repository_fork_jobs "
        "WHERE target_node_bi=? AND status='pending' "
        "AND request_id IN (" + marks + ")",
        target_node_bi, *ids,
    )
    acknowledged = {
        str(row.get("request_id") or "") for row in rows or []
    }
    if acknowledged:
        now = int(Date.now())
        ack_ids = sorted(acknowledged)
        ack_marks = ",".join("?" for _ in ack_ids)
        await d1_run(
            env,
            "UPDATE repository_fork_jobs SET status='completed',updated_at=?,"
            "completed_at=? WHERE target_node_bi=? AND status='pending' "
            "AND request_id IN (" + ack_marks + ")",
            now, now, target_node_bi, *ack_ids,
        )
    return json_response({
        "ok": True,
        "acknowledged": sorted(acknowledged),
    }, cache_control="no-store")


async def repo_forks_handler(env, request, owner, repo):
    # GET lists the repositories forked from this one. POST records a durable
    # request for a linked managed mirror; the public list still changes only
    # when that node creates the bare fork and publishes its own signed
    # `forkedFrom` catalog record (see _index_repo_fork_edge).
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            extra_headers={"allow": "GET, POST"})
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    public_owner = await _public_repo_owner(
        env, request, owner, repo, REPO_FORKS_RE)
    if method == "POST":
        hosted = await hosted_fork_create(
            env, request, owner, public_owner, repo)
        if hosted is not None:
            return hosted
        return await _web_fork_create(
            env, request, public_owner, repo)
    repo_bi = await blind_index(env, public_owner + "/" + repo)
    rows = await d1_all(
        env,
        "SELECT fork_owner, fork_name, created_at FROM repo_forks "
        "WHERE parent_bi=? ORDER BY created_at DESC LIMIT ?",
        repo_bi, REPO_FORKS_LIST_LIMIT)
    forks = []
    profile_origin = _ap_origin(env, request)
    for row in rows or []:
        fork_owner = safe_segment(row.get("fork_owner") or "")
        fork_name = safe_segment(row.get("fork_name") or "")
        if not fork_owner or not fork_name:
            continue
        entry = {
            "owner": fork_owner,
            "name": fork_name,
            "url": "/" + quote(fork_owner) + "/" + quote(fork_name),
            "createdAt": int(row.get("created_at") or 0),
        }
        # Avatar/profile link only when the fork's owner is a live user
        # account; organization-owned forks simply carry no portrait.
        try:
            _, account = await _account_row(env, fork_owner)
            if account and account.get("status") == "active" and not bool(
                    account.get("profile_private")):
                entry["avatarPng"] = account.get("avatar_png", "")
                entry["profileUrl"] = (
                    profile_origin + "/@" + quote(fork_owner))
        except Exception:
            pass
        forks.append(entry)
    count_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM repo_forks WHERE parent_bi=?", repo_bi)
    return json_response({
        "ok": True,
        "count": int((count_row or {}).get("n", 0) or 0),
        "forks": forks,
    })


async def repo_star_handler(env, request, owner, repo):
    # Star/unstar a repo. A star is a plain per-account preference (not signed
    # by the owner's key), so it lives in its own repo_stars table - the same
    # trust model as profile_follows - rather than inside the owner-signed
    # catalog record. GET is public (count + the caller's own state, if a
    # session is supplied); POST/DELETE require a logged-in session, same as
    # ACCOUNT_FOLLOW_RE.
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    public_owner = await _public_repo_owner(
        env, request, owner, repo, REPO_STAR_RE)
    repo_bi = await blind_index(env, public_owner + "/" + repo)

    if method == "GET":
        viewer_bi, viewer_rec = await _account_session_record(env, request)
        starred = False
        if viewer_rec:
            row = await d1_first(
                env,
                "SELECT 1 AS yes FROM repo_stars WHERE repo_bi=? AND account_bi=?",
                repo_bi, viewer_bi)
            starred = bool(row)
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM repo_stars WHERE repo_bi=?", repo_bi)
        return json_response({
            "ok": True,
            "count": int((count_row or {}).get("n", 0) or 0),
            "starred": starred,
        })

    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    account_bi, account_rec = await _account_session_record(env, request, data)
    if not account_rec:
        return json_response({"error": "invalid_session"}, status=401)

    if method == "POST":
        await d1_run(
            env,
            "INSERT OR IGNORE INTO repo_stars (repo_bi, account_bi, created_at) "
            "VALUES (?,?,?)",
            repo_bi, account_bi, int(Date.now()))
        starred = True
        await _award_stargazer_for_repo(env, public_owner, repo_bi)
    else:
        await d1_run(
            env, "DELETE FROM repo_stars WHERE repo_bi=? AND account_bi=?",
            repo_bi, account_bi)
        starred = False

    count_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM repo_stars WHERE repo_bi=?", repo_bi)
    if public_owner == "forkmesh" and repo == "forkmesh":
        try:
            await notify_repo_mirrors(
                env, public_owner, repo, "replica")
        except BaseException:
            pass
    return json_response({
        "ok": True,
        "count": int((count_row or {}).get("n", 0) or 0),
        "starred": starred,
    })


REPO_VIEW_WINDOW_MS = 24 * 60 * 60 * 1000
REPO_VIEW_LOOKUP_LIMIT = 200
REPO_VIEW_LOOKUP_CHUNK = 50


def _repo_view_totals(row):
    row = row or {}
    return {
        "views": int(row.get("views") or 0),
        "viewers": int(row.get("viewers") or 0),
        "lastViewedAt": int(row.get("last_viewed_at") or 0),
    }


async def _repo_viewer_key(env, request, data, repo_key):
    try:
        account_bi, account_rec = await _account_session_record(
            env, request, data)
    except Exception:
        account_bi, account_rec = "", None
    if account_rec and account_bi:
        subject = "account\n%s" % account_bi
    else:
        try:
            address = world_visitor_metrics.canonical_edge_address(
                request.headers.get("cf-connecting-ip") or "")
            agent = str(request.headers.get("user-agent") or "")[:2048]
        except Exception:
            return ""
        if not address:
            return ""
        subject = "visitor\n%s\n%s" % (
            address, world_visitor_metrics.generalized_user_agent(agent))
    digest = await blind_index(
        env, "repo-view-v1\n%s\n%s" % (repo_key, subject))
    return str(digest or "")[:64]


async def _record_repo_view(env, repo_bi, viewer_key):
    now = int(Date.now())
    seen = await d1_first(
        env,
        "SELECT counted_at FROM repo_views WHERE repo_bi=? AND viewer_key=?",
        repo_bi, viewer_key)
    first = not seen
    counted = first or (
        now - int((seen or {}).get("counted_at") or 0)
        >= REPO_VIEW_WINDOW_MS)
    await d1_run(
        env,
        "INSERT INTO repo_views "
        "(repo_bi,viewer_key,first_at,last_at,counted_at,hits) "
        "VALUES (?,?,?,?,?,1) "
        "ON CONFLICT(repo_bi,viewer_key) DO UPDATE SET "
        "last_at=excluded.last_at,hits=repo_views.hits+1,"
        "counted_at=MAX(repo_views.counted_at,excluded.counted_at)",
        repo_bi, viewer_key, now, now, now if counted else 0)
    if counted:
        await d1_run(
            env,
            "INSERT INTO repo_view_totals "
            "(repo_bi,views,viewers,last_viewed_at) VALUES (?,1,?,?) "
            "ON CONFLICT(repo_bi) DO UPDATE SET "
            "views=repo_view_totals.views+1,"
            "viewers=repo_view_totals.viewers+excluded.viewers,"
            "last_viewed_at=MAX(repo_view_totals.last_viewed_at,"
            "excluded.last_viewed_at)",
            repo_bi, 1 if first else 0, now)
    return counted


async def repo_view_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    public_owner = await _public_repo_owner(
        env, request, owner, repo, REPO_VIEW_RE)
    repo_key = (public_owner + "/" + repo).lower()
    repo_bi = await blind_index(env, repo_key)
    counted = False
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            data = {}
        viewer_key = await _repo_viewer_key(env, request, data, repo_key)
        if viewer_key:
            counted = await _record_repo_view(env, repo_bi, viewer_key)
    row = await d1_first(
        env,
        "SELECT views,viewers,last_viewed_at FROM repo_view_totals "
        "WHERE repo_bi=?",
        repo_bi)
    return json_response(
        {"ok": True, "counted": counted, **_repo_view_totals(row)},
        cache_control="no-store, max-age=0")


def _repo_view_lookup_keys(values):
    keys = []
    for value in values if isinstance(values, list) else []:
        parts = str(value or "").strip().lower().split("/")
        if len(parts) != 2:
            continue
        owner, name = safe_segment(parts[0]), safe_segment(parts[1])
        if not owner or not name:
            continue
        key = owner + "/" + name
        if key not in keys:
            keys.append(key)
        if len(keys) >= REPO_VIEW_LOOKUP_LIMIT:
            break
    return keys


async def repo_views_lookup_handler(env, request):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    keys = _repo_view_lookup_keys(
        data.get("repos") if isinstance(data, dict) else None)
    by_bi = {}
    for key in keys:
        by_bi[str(await blind_index(env, key))] = key
    views = {}
    repo_bis = list(by_bi)
    for start in range(0, len(repo_bis), REPO_VIEW_LOOKUP_CHUNK):
        chunk = repo_bis[start:start + REPO_VIEW_LOOKUP_CHUNK]
        rows = await d1_all(
            env,
            "SELECT t.repo_bi,t.views,t.viewers,t.last_viewed_at "
            "FROM repo_view_totals t "
            "LEFT JOIN repositories r ON r.key_bi=t.repo_bi "
            "WHERE t.repo_bi IN (%s) AND COALESCE(r.is_private,0)=0"
            % ",".join("?" * len(chunk)),
            *chunk)
        for row in rows or []:
            key = by_bi.get(str(row.get("repo_bi") or ""))
            if key:
                views[key] = _repo_view_totals(row)
    return json_response(
        {"ok": True, "views": views},
        cache_control="no-store, max-age=0")


# Ciphertext -> decrypted reply, memoized per isolate exactly like
# _CATALOG_ROW_DECRYPT_MEMO (see its comment for the reasoning). A thread read
# decrypts up to FEDI_COMMENT_ROW_LIMIT rows, and every one is Pyodide CPU
# (base64 + a JS-boundary AES-GCM crossing per row) charged to a single
# request. Every open issue/pull view polls this endpoint, so a busy thread
# replayed that whole pass per poll and tipped the request over the Workers CPU
# limit — a 503 "Error 1102: Worker exceeded resource limits" on GET
# .../fedi-comments, the same family as the info/refs overloads. A reply row's
# blob is rewritten with a fresh IV on every lifecycle update, so an unchanged
# blob is byte-identical and its previous plaintext is still valid. Records are
# shared read-only by the projection below and must not be mutated.
_FEDI_COMMENT_DECRYPT_MEMO = {}
FEDI_COMMENT_DECRYPT_MEMO_MAX = 2048
FEDI_COMMENT_ROW_LIMIT = 200
FEDI_COMMENTS_CACHE_TTL = 30


async def fedi_comments_handler(env, request, owner, repo):
    # Remote fediverse replies for one thread, shown alongside (never inside)
    # the Ed25519-signed event log. Public data — same visibility as the
    # thread itself — so the only gate is repo privacy.
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    params = parse_qs(urlparse(request.url).query)
    kind = clean_string(params.get("kind", [""])[0], 20).lower()
    ref = clean_string(
        params.get("number", [""])[0] or params.get("ref", [""])[0], 80)
    if kind not in AP_FEDI_KINDS or not ref:
        return json_response({"error": "kind_and_ref_required"}, status=400)
    # Collapse the poll burst to one origin computation per colo per TTL: the
    # privacy gate above already ran (a 404 is never cached), and the body
    # below is public data keyed entirely by the thread it belongs to.
    cache_key = (
        "https://forkmesh.internal/api/repo/%s/%s/fedi-comments?kind=%s&ref=%s"
        % (quote(owner), quote(repo), kind, quote(ref, safe="")))
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached
    context_bi = await blind_index(
        env, "ap-context:" + ap.context_key(owner, repo, kind, ref))
    rows = await d1_all(
        env,
        "SELECT data, ts, lifecycle FROM ap_comments WHERE context_bi=?"
        " ORDER BY ts ASC LIMIT %d" % FEDI_COMMENT_ROW_LIMIT,
        context_bi)
    normalized_records = {}
    legacy_comments = []
    fresh = {}
    # Resolve the AES key once for the whole pass instead of per row. Empty
    # threads (the common poll) skip it, and a placeholder/missing DATA_KEY
    # stays a per-row decrypt failure rather than becoming a 500 here.
    data_key = None
    if rows:
        try:
            data_key = await _data_key(env)
        except Exception:
            data_key = None
    for row in rows or []:
        blob = str(row.get("data") or "")
        rec = _FEDI_COMMENT_DECRYPT_MEMO.get(blob)
        if rec is None:
            rec = await decrypt_row(env, blob, key=data_key)
            if rec:
                fresh[blob] = rec
        if not rec:
            continue
        source_instance = (
            rec.get("sourceInstance", "")
            or urlparse(rec.get("remoteId", "")).hostname
            or urlparse(rec.get("remoteUrl", "")).hostname
            or "")
        if source_instance and await _ap_domain_blocked(
                env, source_instance):
            continue
        if rec.get("schema") == ap_threads.THREAD_SCHEMA \
                and rec.get("remoteId"):
            normalized_records[rec["remoteId"]] = rec
            continue
        # Pre-0065 rows remain readable and explicitly non-native while normal
        # ActivityPub redelivery gradually upgrades them to lifecycle records.
        legacy_comments.append({
            "author": rec.get("author", ""),
            "authorName": rec.get("authorName", ""),
            "authorUrl": rec.get("authorUrl", ""),
            "body": rec.get("content", ""),
            "url": rec.get("remoteUrl", ""),
            "ts": int(rec.get("ts", 0) or row.get("ts", 0) or 0),
            "federated": True,
            "nativeEvent": False,
            "lifecycle": "active",
            "depth": 0,
            "sourceInstance": source_instance,
            "sourceSoftware": "activitypub",
            "provenance": {
                "source": "activitypub",
                "instance": source_instance,
                "backlink": rec.get("remoteUrl", ""),
                "nativeEvent": False,
                "nativeEventId": "",
                "separationNotice": (
                    "Remote ActivityPub reply; not part of ForkMesh's signed "
                    "native event log."),
            },
        })
    # Threads share one isolate-wide memo, so a read merges its newly decrypted
    # rows rather than rebuilding from the rows just seen — rebuilding would
    # evict every other thread's plaintext on each read. Only fresh decrypts
    # count toward the cap, so a fully memoized thread never triggers a clear;
    # clearing wholesale keeps the memo bounded without a per-entry eviction
    # scan (the next read of a live thread simply refills it).
    if fresh:
        if len(_FEDI_COMMENT_DECRYPT_MEMO) + len(fresh) > \
                FEDI_COMMENT_DECRYPT_MEMO_MAX:
            _FEDI_COMMENT_DECRYPT_MEMO.clear()
        _FEDI_COMMENT_DECRYPT_MEMO.update(fresh)
    comments = legacy_comments + ap_threads.thread_projection(
        normalized_records)
    comments.sort(key=lambda item: (
        int(item.get("ts", 0) or 0),
        str(item.get("published", "")),
        str(item.get("remoteId", ""))))
    resp = json_response({"ok": True, "comments": comments},
                         cache_seconds=FEDI_COMMENTS_CACHE_TTL)
    await edge_cache_put(cache_key, resp)
    return resp




async def _authorize_repo_owner_web(env, request, owner, repo, data):
    """True when the caller may manage this repo's fediverse presence from the
    web: the repo owner proven by their session token, or the owner's desktop
    node proving its Ed25519 key —
    the same trust gate as the About editor / ap-publish, with a distinct
    canonical so a signed token can't be replayed onto another endpoint."""
    actor = await _authed_account_name(env, request, data)
    if actor and await _repo_admin_allowed(env, actor, owner, repo):
        return True
    if data.get("ownerSig") and data.get("ts"):
        ts = str(data.get("ts", "") or "")
        owner_pub = await _owner_pubkey(env, owner)
        canonical = ("forkmesh-ap-posts-v1\n" + owner + "\n" + repo +
                     "\n" + ts).encode()
        if owner_pub and _ts_ok(ts) and await ed25519_verify(
                owner_pub, str(data.get("ownerSig", "") or ""), canonical):
            return True
    return False






# --- Admin: fediverse configuration ------------------------------------------
# Same signed-admin gate as the relay allowlist: the admin proves control of
# their node key and carries is_admin. GET returns the switch + blocklist +
# live stats; POST flips the switch or (un)blocks a remote domain. Blocking a
# domain also purges its followers, cached actors and queued deliveries.

async def _admin_ap_settings(env, request):
    await ensure_schema(env)
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    canonical = ("forkmesh-admin-ap-v1\n" + node + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    settings = await _ap_settings(env, fresh=True)
    stats = {}
    for label, table in (("actors", "ap_actors"),
                         ("followers", "ap_followers"),
                         ("remoteActors", "ap_remote_actors"),
                         ("objects", "ap_objects"),
                         ("comments", "ap_comments"),
                         ("queuedDeliveries", "ap_outbox")):
        row = await d1_first(env, "SELECT COUNT(*) AS c FROM " + table)
        stats[label] = (row or {}).get("c", 0) or 0
    return json_response({
        "ok": True,
        "enabled": settings["enabled"],
        "blockedDomains": sorted(settings["blocked"]),
        "stats": stats,
    })


async def _admin_ap_update(env, request):
    await ensure_schema(env)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    action = clean_string(data.get("action", ""), 20)
    domain = clean_string(data.get("domain", ""), 253).lower()
    if action not in ("enable", "disable", "block", "unblock"):
        return json_response({"error": "bad_action"}, status=400)
    canonical = ("forkmesh-admin-ap-update-v1\n" + node + "\n" + action +
                 "\n" + domain + "\n" + ts).encode()
    audit_target_type = (
        "activitypub_domain"
        if action in ("block", "unblock") else "activitypub")
    audit_target = domain if audit_target_type == "activitypub_domain" else "global"
    if not await _admin_authorized(env, node, ts, sig, canonical):
        await _audit_sensitive_action(
            # `node` is only a claimed identity until the signature verifies;
            # do not attribute a denied request to an account an attacker named.
            env, "", "admin.activitypub_" + action,
            audit_target_type, audit_target, "denied",
            {"reason": "unauthorized", "claimedActorPresent": bool(node)})
        return json_response({"error": "unauthorized"}, status=401)
    now = int(Date.now())
    if action in ("block", "unblock") and not ap.valid_domain(domain):
        await _audit_sensitive_action(
            env, node, "admin.activitypub_" + action,
            audit_target_type, audit_target, "denied",
            {"reason": "invalid_domain"})
        return json_response({"error": "invalid_domain"}, status=400)
    try:
        if action in ("enable", "disable"):
            await d1_run(
                env,
                "INSERT INTO ap_settings (k, v) VALUES ('enabled', ?)"
                " ON CONFLICT(k) DO UPDATE SET v=excluded.v",
                "1" if action == "enable" else "0")
        elif action == "block":
            await d1_run(
                env,
                "INSERT OR IGNORE INTO ap_blocked_domains (domain, added_by,"
                " added_at) VALUES (?,?,?)",
                domain, node, now)
            # Purge existing state from the blocked server. valid_domain
            # limits the charset to [a-z0-9.-], so the LIKE patterns cannot
            # contain SQL wildcards beyond the ones we add.
            for pattern in ("https://" + domain + "/%",
                            "https://%." + domain + "/%"):
                await d1_run(
                    env, "DELETE FROM ap_followers WHERE follower_id LIKE ?",
                    pattern)
                await d1_run(
                    env,
                    "DELETE FROM ap_remote_actors WHERE actor_id LIKE ?",
                    pattern)
                await d1_run(
                    env, "DELETE FROM ap_outbox WHERE inbox LIKE ?", pattern)
        else:
            await d1_run(
                env, "DELETE FROM ap_blocked_domains WHERE domain=?", domain)
    except Exception:
        await _audit_sensitive_action(
            env, node, "admin.activitypub_" + action,
            audit_target_type, audit_target, "failed",
            {"reason": "mutation_error"})
        raise
    await _audit_sensitive_action(
        env, node, "admin.activitypub_" + action,
        audit_target_type, audit_target, "success")
    settings = await _ap_settings(env, fresh=True)
    return json_response({
        "ok": True,
        "enabled": settings["enabled"],
        "blockedDomains": sorted(settings["blocked"]),
    })


async def _owner_signing_pubkeys(env, owner):
    # Every Ed25519 pubkey allowed to sign as this owner's desktop node: the
    # account's primary pubkey plus any still-enabled device key that carries
    # the owner_sign capability. A reinstalled or key-rotated node stores its
    # new keypair in account_devices (login upserts it) but login only sets the
    # primary rec["pubkey"] when it is empty, so it is never promoted. A drain
    # gate that trusted ONLY the primary therefore silently 401'd that node on
    # every GET /api/sync — its issues/PRs/commits/agent-prompts/about edits and
    # chat state stopped reaching it, with no visible error (the node just backs
    # off). The device keys are already stored and account-bound (added only
    # through an authenticated login/claim), so reusing them is the durable node
    # identity the account should keep signing with.
    account_bi, record = await _account_row(env, owner)
    return await _account_signing_pubkeys(env, account_bi, record)


async def _account_signing_pubkeys(env, account_bi, record):
    """The same keys for an account whose identity record is already open.

    Callers that have just read the record must not read it again: an account
    record carries the member's avatar inside the encrypted blob, so opening
    one is the single most expensive thing a signed request does (the largest
    users row in production is 435 KB of ciphertext).
    """
    keys = []
    owner_pub = (record or {}).get("pubkey", "")
    if owner_pub:
        keys.append(owner_pub)
    for device in await _account_devices_list(env, account_bi):
        pub = device.get("pubkey") or ""
        # enabled == active and not revoked (see _account_devices_list); revoking
        # a device in settings closes it out of the drain gate immediately.
        if (pub and pub not in keys and device.get("enabled")
                and "owner_sign" in (device.get("capabilities") or [])):
            keys.append(pub)
    return keys


async def _claimed_node_signing_pubkeys(env, node):
    """Return keys allowed to act as one claimed desktop/headless node."""
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return []
    keys = list(await _owner_signing_pubkeys(env, node))
    node_bi = await blind_index(env, node)
    row = await d1_first(
        env,
        "SELECT pubkey FROM nodes WHERE node_bi=? AND user_bi IS NOT NULL",
        node_bi,
    )
    public_key = clean_string((row or {}).get("pubkey", ""), 120).strip()
    if valid_node_pubkey(public_key) and public_key not in keys:
        keys.append(public_key)
    return keys


async def _catalog_publication_key(env, owner, maintainer):
    """Return an account-bound key allowed to sign one catalog publication.

    Catalog publication follows the same durable desktop-node identity policy
    as sync and HTTPS mirror registration. The account must still exist (the
    caller checks that separately), while a reinstalled or headless node may
    publish with its enabled, non-revoked ``owner_sign`` device key without
    replacing the account's primary key.
    """
    maintainer = clean_string(maintainer, 120).strip()
    if not valid_node_pubkey(maintainer):
        return ""
    allowed = await _owner_signing_pubkeys(env, owner)
    return maintainer if maintainer in allowed else ""


async def _verify_owner_signature(env, owner, sig, canonical):
    for pub in await _owner_signing_pubkeys(env, owner):
        if await ed25519_verify(pub, sig, canonical):
            return True
    return False


async def _signed_account_session(env, node, sig, canonical):
    """Resolve one account-key-signed request, opening the account once.

    Verifying the signature and then reading the signer's record used to
    decrypt the same row twice, and an account record carries the member's
    avatar inside the encrypted blob: the largest users row in production is
    435 KB of ciphertext, so opening one twice is most of what a signed
    desktop request costs, and package API reads answered 1102 for it.
    """
    account_bi, record = await _account_row(env, node)
    if (
        not account_bi
        or not record
        or record.get("status") != "active"
        or _account_kind(record) != "user"
    ):
        return "", None
    for pub in await _account_signing_pubkeys(env, account_bi, record):
        if await ed25519_verify(pub, sig, canonical):
            return account_bi, record
    return "", None


async def _authorized_owner_signing_key(env, request, owner):
    if not owner:
        return ""
    params = parse_qs(urlparse(request.url).query)
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not ts or not sig:
        return ""
    try:
        skew = abs(int(Date.now()) - int(ts))
    except (TypeError, ValueError):
        return ""
    if skew > LOGIN_MAX_SKEW_MS:
        return ""
    canonical = ("forkmesh-issues-pull-v1\n" + owner + "\n" + ts).encode()
    for public_key in await _owner_signing_pubkeys(env, owner):
        if await ed25519_verify(public_key, sig, canonical):
            return public_key
    return ""


async def _authorized_agent_node_signing_key(env, request, node):
    """Owner proof from the exact node an agent job is queued for.

    A desktop signs with its account keys. A managed mirror node has no
    desktop: it signs with the node key its owner claimed, which is the same
    key its catalog publications and endpoint leases already prove. Both are
    bound to the owning account, so either may claim and report that node's
    agent jobs.
    """
    if not node:
        return ""
    params = parse_qs(urlparse(request.url).query)
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not ts or not sig:
        return ""
    try:
        skew = abs(int(Date.now()) - int(ts))
    except (TypeError, ValueError):
        return ""
    if skew > LOGIN_MAX_SKEW_MS:
        return ""
    canonical = ("forkmesh-issues-pull-v1\n" + node + "\n" + ts).encode()
    for public_key in await _claimed_node_signing_pubkeys(env, node):
        if await ed25519_verify(public_key, sig, canonical):
            return public_key
    return ""


async def _authorized_agent_claimant_key(env, request, node, repo):
    key = await _authorized_agent_node_signing_key(env, request, node)
    if key:
        return key
    params = parse_qs(urlparse(request.url).query)
    signer = clean_string(
        params.get("owner", [""])[0], MAX_NODE_NAME).strip().lower()
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(signer) or signer == node:
        return ""
    if not (
        await _account_owns_node(env, signer, node)
        or await _org_owner_of_linked_repo(env, node, repo, signer)
    ):
        return ""
    return await _authorized_owner_signing_key(env, request, signer)


async def _authorize_owner(env, request, owner):
    return bool(await _authorized_owner_signing_key(
        env, request, owner))


async def _authorized_repo_inbox_signing_key(env, request, owner, repo):
    """Authorize a repository inbox drain without losing organization context.

    Organization repository URLs are rewritten to their backing node before
    route matching, while the original Worker Request deliberately retains the
    public alias URL.  A desktop organization administrator signs that public
    owner name (the one stored in its RepositoryRecord), not the backing mirror
    node name.  Accept that proof only when the alias is still linked to this
    exact public repository and the signer is a current org owner/admin.

    Private repositories deliberately stay on the direct owner-key path:
    organization membership alone is never a plaintext/private-inbox grant.
    """
    direct_key = await _authorized_owner_signing_key(
        env, request, owner)
    if direct_key:
        return direct_key
    try:
        original_url = urlparse(request.url)
        match = REPO_API_PREFIX_RE.match(original_url.path)
    except Exception:
        return ""
    if not match:
        return ""
    alias_owner = (safe_segment(match.group(1)) or "").lower()
    alias_repo = (safe_segment(match.group(2)) or "").lower()
    owner_l = str(owner or "").strip().lower()
    repo_l = str(repo or "").strip().lower()
    if (
        not alias_owner
        or alias_owner == owner_l
        or alias_repo != repo_l
        or await _repo_is_private(env, owner_l, repo_l)
    ):
        return ""

    # Re-check the durable link instead of trusting the short-lived alias memo:
    # revoking/unlinking an organization must revoke drain authority at once.
    org_bi, org_row = await _org_row(env, alias_owner)
    if not org_row:
        return ""
    linked = await d1_first(
        env,
        "SELECT 1 AS ok FROM org_repos "
        "WHERE org_bi=? AND repo=? AND node_owner=?",
        org_bi, repo_l, owner_l,
    )
    if not linked:
        return ""

    params = parse_qs(original_url.query)
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not ts or not sig:
        return ""
    try:
        skew = abs(int(Date.now()) - int(ts))
    except (TypeError, ValueError):
        return ""
    if skew > LOGIN_MAX_SKEW_MS:
        return ""
    canonical = (
        "forkmesh-issues-pull-v1\n" + alias_owner + "\n" + ts
    ).encode()
    members = await d1_all(
        env,
        "SELECT name,role FROM org_members "
        "WHERE org_bi=? AND role IN ('owner','admin') "
        "ORDER BY name LIMIT ?",
        org_bi, MAX_ORG_MEMBERS,
    )
    for member in members or []:
        if str(member.get("role") or "") not in ("owner", "admin"):
            continue
        account = clean_string(
            member.get("name") or "", MAX_NODE_NAME
        ).strip().lower()
        if not valid_node_name(account):
            continue
        for public_key in await _owner_signing_pubkeys(env, account):
            if await ed25519_verify(public_key, sig, canonical):
                return public_key
    return ""


async def _authorize_repo_inbox_owner(env, request, owner, repo):
    return bool(await _authorized_repo_inbox_signing_key(
        env, request, owner, repo))


async def _authorize_owner_account(env, owner, data, request=None,
                                   allow_admin=True):
    # Authorize the caller as the repo owner (or a network admin) via their
    # logged-in account SESSION — not a self-asserted name. Used for the website
    # agents tab (adhoc #225). This gate protects immediate, unreviewed side
    # effects: queuing a prompt into a running coding agent on the owner's
    # machine, and reading an agent's transcript / session list. The earlier
    # version trusted data["ownerAccount"] verbatim, so anyone who knew a public
    # owner/repo name could drive those owner-only actions (agent hijack / private
    # data disclosure). The sessionToken (POST body or bearer) must now resolve to
    # the owner account itself or a network admin.
    # Returns (True, None) on success, or (False, error_json_response) on failure.
    _, rec = await _account_session_record(env, request, data)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor:
        return False, json_response({"error": "not_authorized"}, status=403)
    owns_node = await _account_owns_node(env, actor, owner)
    if not owns_node and not (allow_admin and await _is_admin(env, actor)):
        return False, json_response({"error": "not_authorized"}, status=403)
    return True, None


async def _authorize_issue_manager(env, owner, data, request=None):
    """Authorize personal-repo owners plus organization owners/admins."""
    ok, err = await _authorize_owner_account(env, owner, data, request)
    if ok:
        return True, None
    _, rec = await _account_session_record(env, request, data)
    actor = clean_string(
        rec.get("name", "") if rec else "", MAX_NODE_NAME
    ).strip().lower()
    if not actor:
        return False, err
    org_bi, org = await _org_row(
        env, clean_string(owner, MAX_NODE_NAME).lower()
    )
    role = await _org_role(env, org_bi, actor) if org else ""
    if _org_rbac.org_role_allows(role, "organization.issues.manage"):
        return True, None
    return False, err


async def _authorize_issue_self_claim(env, data, request, event):
    """Authorize a signed-in visitor claiming (or releasing) an issue themselves.

    The browser signature proves the event was not tampered with; it says
    nothing about who signed it, because a web key is generated per browser.
    The account session is what binds the event to a person, so the name inside
    the claim must be that session's own account. Anything else — an empty
    session, or a claim naming somebody else — is refused with the same
    "not_authorized" the structural events use.
    """
    _, rec = await _account_session_record(env, request, data)
    actor = clean_string(
        rec.get("name", "") if rec else "", MAX_NODE_NAME
    ).strip().lower()
    claimed = clean_string(
        event.get("assignee", "") or "", MAX_NODE_NAME
    ).strip().lower()
    if not actor or not claimed or actor != claimed:
        return False, json_response({"error": "not_authorized"}, status=403)
    return True, None


async def _inbox_author_over_quota(env, table, repo_bi, submitter_bi):
    # True when this submitter already holds MAX_PENDING_PER_AUTHOR un-merged rows
    # in this repo's inbox (table is a fixed literal, safe to interpolate).
    if not submitter_bi:
        return False
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM " + table +
        " WHERE repo_bi=? AND submitter_bi=?",
        repo_bi, submitter_bi,
    )
    return bool(row and (row.get("c", 0) or 0) >= MAX_PENDING_PER_AUTHOR)


async def _best_effort_inbox_side_effect(awaitable):
    # Inbox acceptance is the durable D1 insert. Notification/subscription
    # fan-out is useful, but it must not turn an accepted web submission into 500.
    try:
        await awaitable
    except Exception:
        pass


def _notification_trim_due(recipient_bi, now):
    """True at most once per recipient per NOTIFICATION_TRIM_INTERVAL_MS.

    The cap only needs enforcing eventually: a burst of inserts between two
    trims overshoots MAX_NOTIFICATIONS_PER_RECIPIENT by that burst and the
    next trim removes the excess. Harnesses that do not define the memo (or
    define it as None) trim on every insert, the historical behaviour.
    """
    memo = globals().get("_NOTIFICATION_TRIM_MEMO")
    if not isinstance(memo, dict):
        return True
    interval = int(globals().get("NOTIFICATION_TRIM_INTERVAL_MS", 0) or 0)
    last = int(memo.get(recipient_bi) or 0)
    if last and 0 <= int(now) - last < interval:
        return False
    if len(memo) >= int(globals().get("NOTIFICATION_TRIM_MEMO_MAX", 512) or 512):
        memo.clear()
    memo[recipient_bi] = int(now)
    return True


async def enqueue_notification(env, recipient, kind, title, body="", repo="",
                               href="", actor="", source="", dedupe="",
                               ts=0, meta=None, push=True, force=False,
                               receipt=None):
    # Account-scoped notification index. It intentionally stores only an encrypted
    # payload plus blind indexes/read state; the canonical event stays in repo git
    # files or a signed inbox table.
    await ensure_schema(env)
    recipient = clean_string(recipient, MAX_NODE_NAME).lower()
    actor = clean_string(actor, MAX_NODE_NAME).lower()
    if not valid_node_name(recipient) or kind not in NOTIFICATION_KINDS:
        return False
    if actor and actor == recipient:
        return False
    now = int(ts or Date.now())
    # Ping settings (#347): a kind the recipient switched off is not filed;
    # inside a pause or quiet hours it is filed but raises no phone banner.
    paused = False
    delivery_settings = globals().get("_ping_delivery_settings")
    if callable(delivery_settings):
        muted, paused = await delivery_settings(env, recipient, int(Date.now()))
        if kind == "security_alert" or force:
            # Intrusion alerts (docs/IDS.md) always ring: a Pings setting
            # cannot mute them and quiet hours do not hold the phone banner.
            muted, paused = set(), False
        if kind in muted:
            return False
    public_href = globals().get("_repo_public_href")
    if callable(public_href):
        href = await public_href(env, href)
    payload = notification_payload(
        kind, title, body=body, repo=repo, href=href, actor=actor,
        source=source, ts=now, meta=meta)
    recipient_bi = await blind_index(env, recipient)
    dedupe_value = dedupe or (kind + ":" + recipient + ":" + source + ":" +
                              repo + ":" + str(now))
    dedupe_bi = await blind_index(env, "notification:" + recipient + ":" + dedupe_value)
    content_bi = await blind_index(env, "notification-content:" + json.dumps(
        {key: value for key, value in payload.items()
         if key not in ("ts", "readAt")},
        sort_keys=True, separators=(",", ":"), default=str))
    await d1_run(
        env,
        """INSERT INTO notifications
             (dedupe_bi, recipient_bi, ts, read_at, data, content_bi)
           VALUES (?,?,?,?,?,?)
           ON CONFLICT(dedupe_bi) DO UPDATE SET
             recipient_bi=excluded.recipient_bi,
             ts=CASE WHEN notifications.content_bi=excluded.content_bi
                     THEN notifications.ts ELSE excluded.ts END,
             data=CASE WHEN notifications.content_bi=excluded.content_bi
                       THEN notifications.data ELSE excluded.data END,
             content_bi=excluded.content_bi""",
        dedupe_bi, recipient_bi, now, 0, await encrypt_row(env, payload),
        content_bi,
    )
    cutoff = now - NOTIFICATION_RETAIN_MS
    await d1_run(
        env,
        "DELETE FROM notifications WHERE recipient_bi=? AND ts < ?",
        recipient_bi, cutoff,
    )
    trim_due = globals().get("_notification_trim_due")
    if not callable(trim_due) or trim_due(recipient_bi, now):
        await d1_run(
            env,
            """DELETE FROM notifications
               WHERE recipient_bi=? AND ts < COALESCE((
                 SELECT ts FROM notifications
                 WHERE recipient_bi=? ORDER BY ts DESC LIMIT 1 OFFSET ?
               ), 0)""",
            recipient_bi, recipient_bi, MAX_NOTIFICATIONS_PER_RECIPIENT - 1,
        )
    # This row is the only thing that moves the recipient's unread ping count,
    # so it is also the only thing that needs to wake their clients. Desktop
    # and browser both read the inbox once on open and then sit on this push.
    push_record = dict(payload)
    push_record["id"] = dedupe_bi
    push_record["ts"] = now
    if paused or not push:
        # The socket frame still moves the bell; with no record to describe,
        # push_account_apns sends no banner. `push=False` is a caller folding
        # this row into a banner the phone already showed (notify_code_push's
        # storm guard): the inbox is current, the phone is not buzzed again.
        push_record = None
    phones = await notify_account_event(env, recipient, "pings", push_record)
    if isinstance(receipt, dict):
        receipt["id"] = dedupe_bi
        receipt["phones"] = phones if isinstance(phones, int) else 0
    # Same idea for email, one rail over: ring the instant-delivery doorbell and
    # let the consumer do the sending. Deliberately not an inline _send_email —
    # this runs inside request handlers and fans out over a thread's whole
    # subscriber list, so an external mail round-trip per recipient would land
    # on the user waiting for their comment to post.
    await _queue_instant_notification(env, recipient, now)
    emit_ping = globals().get("apps_emit_ping")
    if emit_ping is not None:
        await emit_ping(env, recipient, title, href, source)
    return True


async def _promote_hosted_repository_import(env, catalog_record):
    """Link one verified mirror catalog to its public provider import."""
    repository_import = _repository_import_module()
    mirror_owner = clean_string(
        catalog_record.get("owner"), MAX_NODE_NAME).lower()
    repository_name = safe_segment(clean_string(
        catalog_record.get("name"), MAX_REPO_SEGMENT))
    # mirror2 and mirror3 ran the original Codeberg import burst and have both
    # been retired; any node may carry an imported catalog now, so gate on the
    # record itself rather than a hard-coded pair of node names.
    if not mirror_owner or not repository_name:
        return False
    # Every provider ForkMesh imports from is hosted the same way, so a GitHub
    # or GitLab import stops depending on its provider exactly like a Codeberg
    # one (issue #679). The hosted sweep on the mirror decides what to clone;
    # this only links what it published back to the import entry.
    rows = await d1_all(
        env,
        "SELECT id, data FROM repository_imports "
        "WHERE provider IN ('github','gitlab','codeberg') AND is_private=0 "
        "AND status NOT IN ('actively_mirrored','archived') "
        "ORDER BY updated_at DESC LIMIT ?",
        repository_import.MAX_PUBLIC_IMPORTS,
    )
    catalog_branch = clean_string(catalog_record.get("branch"), 120).strip()
    candidates = []
    for row in rows or []:
        record = await decrypt_row(env, row.get("data"))
        if (
                not isinstance(record, dict)
                or clean_string(record.get("name"), 100).casefold()
                != repository_name.casefold()):
            continue
        target_owner = clean_string(
            record.get("targetOwner"), MAX_NODE_NAME).lower()
        if not valid_node_name(target_owner):
            continue
        candidates.append((row, record, target_owner))
    # One repository name can be imported from more than one provider, and a
    # catalog record carries no import id to match on. Prefer a candidate whose
    # own default branch is the branch this mirror published before falling
    # back to the most recently updated entry.
    def branch_rank(candidate):
        metadata = candidate[1].get("metadata")
        metadata = metadata if isinstance(metadata, dict) else {}
        default_branch = clean_string(
            metadata.get("defaultBranch"), 120).strip()
        if not catalog_branch or default_branch == catalog_branch:
            return 0
        return 1

    for row, record, target_owner in sorted(candidates, key=branch_rank):
        provider_label = {
            "github": "GitHub",
            "gitlab": "GitLab",
            "codeberg": "Codeberg",
        }.get(clean_string(record.get("provider"), 40).lower(), "provider")
        now = int(Date.now())
        record["status"] = "actively_mirrored"
        record["statusLabel"] = "Actively mirrored"
        record["mirrored"] = True
        record["sourceCodeFetched"] = True
        record["mirror"] = {
            "owner": mirror_owner,
            "name": repository_name,
            "live": True,
        }
        record["mirrorNotice"] = (
            "The full Git repository is hosted and served by ForkMesh.")
        record["updatedAt"] = now
        await d1_run(
            env,
            "UPDATE repository_imports SET status=?, data=?, updated_at=? "
            "WHERE id=?",
            "actively_mirrored", await encrypt_row(env, record), now,
            str(row.get("id") or ""),
        )
        await enqueue_notification(
            env,
            target_owner,
            "repository_hosted",
            repository_name + " is now fully hosted by ForkMesh",
            body=(
                "The " + provider_label + " import is synced, cloneable "
                "through ForkMesh, and available as a size map in the "
                "World."),
            repo=target_owner + "/" + repository_name,
            href="/" + target_owner + "/" + repository_name,
            actor=mirror_owner,
            source="repository_import",
            dedupe="repository-hosted:" + str(row.get("id") or ""),
            ts=now,
            meta={"importId": str(row.get("id") or "")},
        )
        return True
    return False


async def notify_mentions(env, owner, repo, actor, title, body, href, source,
                          number=0):
    # number is optional (0 = not a numbered item, e.g. a brand-new PR before
    # the owner assigns it) so every existing call site keeps working
    # unchanged; callers that DO know the number pass it as a keyword so the
    # digest email can show "#N" instead of just a bare title.
    for name in notification_mentions(title, body):
        await enqueue_notification(
            env, name, "mention", "You were mentioned in " + owner + "/" + repo,
            body=(title or body or "Open the repository item to read the mention."),
            repo=owner + "/" + repo, href=href, actor=actor, source=source,
            dedupe="mention:" + owner + "/" + repo + ":" + source + ":" + name +
                   ":" + clean_string(actor, 80) + ":" + clean_string(title, 80) +
                   ":" + clean_string(body, 80),
            meta={"number": number} if number else {},
        )


def _thread_key(owner, repo, source, number):
    try:
        n = int(number or 0)
    except (TypeError, ValueError):
        n = 0
    return ("thread:" + (owner or "") + "/" + (repo or "") + ":" +
            (source or "") + ":" + str(n))


async def subscribe_thread(env, owner, repo, source, number, subscriber,
                           muted=False):
    # Record (or mute) one node's subscription to an issue/PR thread. Auto-called
    # for anyone who comments so they hear about later replies; the signed
    # subscribe endpoint calls it too. An explicit mute is sticky: a later
    # auto-subscribe won't silently re-enable a thread the user muted.
    subscriber = clean_string(subscriber, MAX_NODE_NAME).lower()
    if not valid_node_name(subscriber):
        return False
    try:
        number = int(number or 0)
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        # A brand-new submission has no durable number yet (the owner assigns it on
        # drain), so its thread key would collide with every other new item.
        return False
    await ensure_schema(env)
    thread_bi = await blind_index(env, _thread_key(owner, repo, source, number))
    subscriber_bi = await blind_index(env, subscriber)
    if not muted:
        existing = await d1_first(
            env,
            "SELECT data FROM thread_subscriptions "
            "WHERE thread_bi=? AND subscriber_bi=?",
            thread_bi, subscriber_bi)
        if existing:
            rec = await decrypt_row(env, existing.get("data", ""))
            if rec and rec.get("muted"):
                return False  # keep an explicit unsubscribe
            return True  # already subscribed
    await d1_run(
        env,
        "INSERT INTO thread_subscriptions (thread_bi, subscriber_bi, ts, data) "
        "VALUES (?,?,?,?) ON CONFLICT(thread_bi, subscriber_bi) DO UPDATE SET "
        "ts=excluded.ts, data=excluded.data",
        thread_bi, subscriber_bi, int(Date.now()),
        await encrypt_row(env, {"node": subscriber, "muted": bool(muted)}),
    )
    return True


async def notify_subscribers(env, owner, repo, source, number, actor, title,
                             body, href):
    # Fan a new comment out to everyone following the thread, minus the commenter
    # and anyone already covered by an @mention on this same event (so a mentioned
    # subscriber gets one notification, not two).
    try:
        number = int(number or 0)
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return
    await ensure_schema(env)
    thread_bi = await blind_index(env, _thread_key(owner, repo, source, number))
    rows = await d1_all(
        env, "SELECT data FROM thread_subscriptions WHERE thread_bi=?", thread_bi)
    if not rows:
        return
    mentioned = set(notification_mentions(title, body))
    snippet = clean_string(body or title, 80)
    # Say what was actually written. The ping (and the phone banner built from
    # it) used to read "New activity in owner/repo" over the issue title, so
    # a follower learned that *something* happened and had to open the app to
    # find out what.
    headline = {
        "issue": "New comment",
        "pull": "New pull request comment",
        "discussion": "New discussion reply",
    }.get(source, "New reply")
    text = "\n\n".join(
        part for part in (clean_string(title),
                          clean_string(body, NOTIFICATION_BODY_MAX)) if part)
    for row in rows:
        rec = await decrypt_row(env, row.get("data", ""))
        if not rec or rec.get("muted"):
            continue
        name = clean_string(rec.get("node", ""), MAX_NODE_NAME).lower()
        if not valid_node_name(name) or name == actor or name in mentioned:
            continue
        await enqueue_notification(
            env, name, "subscribed", headline + " in " + owner + "/" + repo,
            body=(text or "There's a new reply on a thread you follow."),
            repo=owner + "/" + repo, href=href, actor=actor, source=source,
            dedupe="subscribed:" + owner + "/" + repo + ":" + source + ":" +
                   str(number) + ":" + name + ":" + clean_string(actor, 80) +
                   ":" + snippet,
            meta={"number": number, "source": source},
        )


async def notify_pending_inbox(env, owner, repo, source, actor, title, number=0,
                               public_owner="", opened=False, text=""):
    # owner is the account whose inbox holds the item and who receives this
    # ping. public_owner is the name the submission was made under when an
    # organization alias fronts the repo, and the two differ only then. Name
    # the public repo in the ping: it is what every other surface for the same
    # submission shows — the confirmation the submitter reads, the web URL, the
    # href below — and naming the backing node instead made the dashboard Feed
    # contradict ForkBot's confirmation for one action (issue #650). The
    # hosting node still matters to this recipient, who owns it, so it goes in
    # the body and meta rather than being dropped. The dedupe key stays on the
    # owning account: it is delivery identity, not display, and re-keying it
    # would split an alias repo's pending pings from their earlier duplicates.
    #
    # opened marks the event that CREATES an issue or pull request (issue
    # #714). It gets its own ping kind and wording — "New issue in …", "New
    # pull request in …" — so a new item is not lost among the comment and
    # edit pings the same inbox raises, and it also reaches the owners, admins
    # and maintainers of an organization fronting the repo, who triage it but
    # do not own the hosting node. Every other inbox event stays a plain
    # pending_inbox ping to the hosting account; that includes pull request
    # comments, which used to be sent as "Pull request submitted". A comment
    # is not re-fanned to the organization here on purpose: notify_subscribers
    # below already reaches everyone following the thread, and a maintainer
    # who ever replied is auto-subscribed, so a second fan-out would file two
    # near-identical "New comment in …" rows for the same reply (adhoc #295).
    #
    # text is what the submitter actually wrote — the issue description, the
    # comment. It goes in the body under the title, so the inbox row and the
    # phone banner built from it show the message itself; a comment used to
    # arrive as "Issue submitted" over "A signed item is waiting in your
    # desktop inbox." because a comment carries no title of its own.
    text = clean_string(text, NOTIFICATION_BODY_MAX)
    host_owner = clean_string(owner, MAX_NODE_NAME).lower()
    public = clean_string(public_owner, MAX_NODE_NAME).lower() or host_owner
    opened = bool(opened) and source in PING_OPENED_KINDS
    if opened:
        kind = PING_OPENED_KINDS[source]
        label = {"issue": "New issue", "pull": "New pull request"}[source]
        joiner = " in "
    elif text:
        kind = "pending_inbox"
        label = {
            "pull": "New pull request comment",
            "discussion": "New discussion reply",
        }.get(source, "New comment")
        joiner = " in "
    else:
        kind = "pending_inbox"
        label = {
            "issue": "Issue submitted",
            "pull": "Pull request activity",
            "discussion": "Discussion submitted",
        }.get(source, "Pending inbox item")
        joiner = " for "
    slug = public + "/" + repo
    href = repo_web_href(public, repo)
    segment = NOTIFICATION_ITEM_URL_SEGMENTS.get(source, "")
    if opened and segment and int(number or 0) > 0:
        href += "/" + segment + "/" + str(int(number))
    body = ("\n\n".join(part for part in (clean_string(title), text) if part)
            or "A signed item is waiting in your desktop inbox.")
    host_body = body
    if public != host_owner:
        note = " (hosted on your " + host_owner + " node)"
        # notification_payload clips the body at NOTIFICATION_BODY_MAX. Trim
        # the message, not the note: the note is the part that reconciles the
        # two names.
        host_body = clean_string(body, NOTIFICATION_BODY_MAX - len(note)) + note
    dedupe = ("pending:" + host_owner + "/" + repo + ":" + source + ":" +
              clean_string(actor, 120) + ":" + str(number) + ":" +
              clean_string(title, 120))
    if text:
        # Two comments from one person on one issue are two pings. Without the
        # text in the key the second overwrote the first — keeping its read
        # state — so the push for it found no unread row to show.
        dedupe += ":" + clean_string(text, 80)
    meta = {"number": number, "source": source, "hostOwner": host_owner}
    maintainers = (await _org_repo_maintainers(env, host_owner, repo)
                   if opened else [])
    if not await _node_owner_among(env, host_owner, maintainers):
        await enqueue_notification(
            env, owner, kind, label + joiner + slug,
            body=host_body,
            repo=slug, href=href,
            actor=actor, source=source,
            dedupe=dedupe,
            meta=meta,
        )
    if not opened:
        return
    for maintainer in maintainers:
        if maintainer == host_owner:
            continue
        await enqueue_notification(
            env, maintainer, kind, label + joiner + slug,
            body=body,
            repo=slug, href=href,
            actor=actor, source=source,
            dedupe=dedupe,
            meta=meta,
        )


async def _node_owner_among(env, host, accounts):
    if not accounts:
        return False
    _, rec = await _account_row(env, host)
    owner = clean_string((rec or {}).get("owner", ""), MAX_NODE_NAME).lower()
    return bool(owner) and owner != host and owner in accounts


async def _org_fanout_recipients(env, host, repo):
    maintainers = await _org_repo_maintainers(env, host, repo)
    recipients = [] if await _node_owner_among(env, host, maintainers) else [host]
    for maintainer in maintainers:
        if maintainer not in recipients and maintainer != host:
            recipients.append(maintainer)
    return recipients


async def _org_repo_maintainers(env, host_owner, repo):
    """Accounts that run an organization fronting host_owner/repo.

    Owners, admins and maintainers of every organization linking the repo —
    the roles whose baseline repository permission is maintain or better, so
    the people expected to triage what lands in it. Plain members, auditors
    and guests are left out: an organization's whole roster would otherwise
    hear about every issue in every linked repository. Best effort; a lookup
    error means only the hosting account is pinged, as before issue #714.
    """
    host_owner = clean_string(host_owner, MAX_NODE_NAME).lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).lower()
    if not host_owner or not repo:
        return []
    try:
        await ensure_schema(env)
        rows = await d1_all(
            env,
            "SELECT m.name AS name, m.role AS role FROM org_repos r "
            "JOIN org_members m ON m.org_bi = r.org_bi "
            "WHERE r.node_owner=? AND r.repo=?",
            host_owner, repo)
    except Exception:
        return []
    found = set()
    for row in rows or []:
        permission = _org_rbac.org_role_repo_permission(row.get("role"))
        if team_permission_rank(permission) < team_permission_rank("maintain"):
            continue
        name = clean_string(row.get("name") or "", MAX_NODE_NAME).strip().lower()
        if valid_node_name(name):
            found.add(name)
    return sorted(found)[:PING_OPENED_MAX_ORG_RECIPIENTS]


async def notify_issue_assignees(env, owner, repo, assignees, actor, title, number=0):
    for assignee in sorted({clean_string(a, MAX_NODE_NAME).lower() for a in (assignees or [])}):
        if not valid_node_name(assignee):
            continue
        await enqueue_notification(
            env, assignee, "issue_assigned",
            "Issue assigned in " + owner + "/" + repo,
            body=title or "You were assigned to an issue.",
            repo=owner + "/" + repo,
            href=repo_web_href(owner, repo),
            actor=actor, source="issue_assigned",
            dedupe="issue-assigned:" + owner + "/" + repo + ":" + str(number) +
                   ":" + assignee,
            meta={"number": number},
        )


async def notify_bounty_event(env, rec, kind):
    owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
    repo = clean_string(rec.get("repo", ""), MAX_REPO_SEGMENT)
    if not owner or not repo:
        return
    number = int(rec.get("number", 0) or 0)
    title = "Bounty funded" if kind == "bounty_funded" else "Bounty paid"
    await enqueue_notification(
        env, owner, kind, title + " on " + owner + "/" + repo,
        body=("Issue #" + str(number) + " bounty is " +
              ("funded." if kind == "bounty_funded" else "paid.")),
        repo=owner + "/" + repo,
        href=repo_web_href(owner, repo),
        source="bounty", dedupe=kind + ":" + owner + "/" + repo + ":" + str(number),
        meta={"number": number, "status": rec.get("status", "")},
    )


async def notify_repo_activity(env, owner, repo, event, body="", actor="",
                               key="", meta=None):
    """Ping the people who run a repository that something moved inside it.

    notify_pending_inbox above covers what a person filed — an issue, a pull
    request, a comment. This covers the rest of the activity this relay can
    actually observe: a push that moved refs, a merged pull request. Until
    adhoc #295 those raised an outbound webhook and nothing else, so the most
    common thing that happens to a repository was the one thing its owner's
    inbox never mentioned.

    Audience is the hosting account plus the owners, admins and maintainers of
    any organization fronting the repository — the same people a new issue
    reaches, for the same reason.

    ``key`` is what makes the event distinct, normally the commit or refs
    digest it moved to. Republishing an unchanged state collapses onto the
    existing row instead of banner-ing every device again, while a genuinely
    new push carries a new digest and so raises a new ping.

    ``actor`` is only passed where the relay genuinely knows who acted (a
    merge names its merger). A push does not: a node publishes the refs state
    it now advertises, there is no receive-pack here and no pusher identity to
    read, so a push ping carries no actor and therefore also reaches the
    account that owns the node — which is the point, since that account is
    usually reading it on a different device than the one that pushed.
    """
    owner = clean_string(owner, MAX_NODE_NAME).lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT)
    label = REPO_ACTIVITY_LABELS.get(event)
    if not valid_node_name(owner) or not repo or not label:
        return
    slug = owner + "/" + repo
    title = label[0] + " in " + slug
    text = clean_string(body, NOTIFICATION_BODY_MAX) or label[1]
    href = repo_web_href(owner, repo)
    dedupe = ("repo-activity:" + slug + ":" + event + ":" +
              clean_string(key, 80))
    payload_meta = dict(meta or {})
    payload_meta["event"] = event
    for recipient in await _org_fanout_recipients(env, owner, repo):
        await enqueue_notification(
            env, recipient, "repo_activity", title,
            body=text, repo=slug, href=href,
            actor=actor, source="repo_activity",
            dedupe=dedupe, meta=payload_meta,
        )


def code_push_ping_text(owner, repo, branch="", commits=0, subject="",
                        commit="", pusher="", refs_digest=""):
    """(title, body, href) for one code-push ping. Pure; see notify_code_push.

    title  "Pushed to alice/atlas"
    body   "alice-laptop: 3 commits on main — Fix relay retries"
    href   "/alice/atlas/commits/main" — the commits tab at the branch, which
           the web repo page and the phone's NotificationDeepLink both open.

    Only what the observation carried is said: a push whose commit count is
    unknown says "new commits", one with no subject names the short sha, and
    a push that moved a branch or tag other than the default one (the catalog
    digest does not say which) says exactly that.
    """
    slug = owner + "/" + repo
    title = "Pushed to " + slug
    who = clean_string(pusher, 120).strip() or owner
    branch = clean_string(branch, 120).strip()
    try:
        commits = int(commits or 0)
    except (TypeError, ValueError):
        commits = 0
    href = repo_web_href(owner, repo) + "/commits"
    if branch:
        href += "/" + quote(branch, safe="")
        count = ("1 commit" if commits == 1 else
                 (str(commits) + " commits") if commits > 1 else "new commits")
        tail = (clean_string(subject, 120).strip().splitlines() or [""])[0]
        if not tail:
            sha = clean_string(commit, 64).strip().lower()
            tail = sha[:7]
        body = who + ": " + count + " on " + branch
        if tail:
            body += " — " + tail
    else:
        body = who + ": a branch or tag was updated"
        digest = clean_string(refs_digest, 64).strip().lower()
        if digest:
            body += " (refs " + digest[:12] + ")"
    return title, clean_string(body, NOTIFICATION_BODY_MAX), href


def code_push_merge(pending_meta, commits):
    """Commit count after folding a push into a still-unread ping.

    Counts add up while both are known; an unknown count on either side makes
    the total unknown ("new commits") rather than a number that undercounts.
    """
    pending_meta = pending_meta if isinstance(pending_meta, dict) else {}
    try:
        before = int(pending_meta.get("commits", 0) or 0)
    except (TypeError, ValueError):
        before = 0
    try:
        commits = int(commits or 0)
    except (TypeError, ValueError):
        commits = 0
    if before > 0 and commits > 0:
        return before + commits
    return 0


def code_push_slot_keys(slug, branch_key, now):
    """Dedupe keys of the current and previous storm window for one branch."""
    slot = int(now) // CODE_PUSH_WINDOW_MS
    base = "code-push:" + slug + ":" + branch_key + ":w"
    return base + str(slot), base + str(slot - 1)


async def _org_repo_readers(env, host_owner, repo):
    """Members of every organization linking host_owner/repo who can read it.

    Code pushes reach further than new issues (_org_repo_maintainers): every
    role whose baseline repository permission is read or better — owners,
    admins, maintainers, members and auditors. Guests have no baseline access
    and are left out. Best effort; a lookup error means only the hosting
    account is pinged.
    """
    host_owner = clean_string(host_owner, MAX_NODE_NAME).lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).lower()
    if not host_owner or not repo:
        return []
    try:
        await ensure_schema(env)
        rows = await d1_all(
            env,
            "SELECT m.name AS name, m.role AS role FROM org_repos r "
            "JOIN org_members m ON m.org_bi = r.org_bi "
            "WHERE r.node_owner=? AND r.repo=?",
            host_owner, repo)
    except Exception:
        return []
    found = set()
    for row in rows or []:
        permission = _org_rbac.org_role_repo_permission(row.get("role"))
        if (not permission or team_permission_rank(permission)
                < team_permission_rank("read")):
            continue
        name = clean_string(row.get("name") or "", MAX_NODE_NAME).strip().lower()
        if valid_node_name(name):
            found.add(name)
    return sorted(found)[:CODE_PUSH_MAX_ORG_RECIPIENTS]


async def _code_push_pending(env, recipient, keys):
    """{dedupe key: (ts, read_at, meta)} for this recipient's window rows."""
    recipient_bi = await blind_index(env, recipient)
    by_bi = {}
    for key in keys:
        by_bi[await blind_index(env, "notification:" + recipient + ":" + key)] = key
    rows = await d1_all(
        env,
        "SELECT dedupe_bi, ts, read_at, data FROM notifications "
        "WHERE recipient_bi=? AND dedupe_bi IN (?,?)",
        recipient_bi, *list(by_bi)[:2])
    found = {}
    for row in rows or []:
        key = by_bi.get(str(row.get("dedupe_bi") or ""))
        if not key:
            continue
        record = await decrypt_row(env, row.get("data", ""))
        meta = record.get("meta") if isinstance(record, dict) else None
        found[key] = (int(row.get("ts") or 0), int(row.get("read_at") or 0),
                      meta if isinstance(meta, dict) else {})
    return found


async def notify_code_push(env, owner, repo, branch="", commit="",
                           commits=0, subject="", pusher="", key="",
                           refs_digest="", pusher_account="", meta=None):
    """Ping everyone who should hear that code was pushed to a repository.

    Called from the two places a push becomes observable to this relay — an
    owner-signed catalog publication whose refs moved (catalog_routes) and a
    hosted repository's receive-pack pin (hosted_git) — and from nowhere
    else, so one push files one ping per recipient. A mirror's echo of the
    same state is not a push (catalog_push_observed), and `key` (the new tip
    or refs digest) is remembered on the ping so a re-observed state is never
    counted twice.

    Recipients: the hosting account, always — including for its own pushes,
    which is the point: the owner is usually reading this on a phone while a
    desktop or an agent does the pushing — plus every member of an
    organization fronting the repository with read access or better. A
    member who is themself the identified pusher (`pusher_account`, known for
    hosted pushes) is not told about their own push. There is no
    local "watch" relation to add: stars are blind-indexed per account and
    carry no names, and repository followers are fediverse actors.

    Storm guard, per recipient and repository branch (the default branch by
    name; other refs share one key): a ping banners the phone only when no
    code-push ping for that branch was bannered in the last
    CODE_PUSH_WINDOW_MS. Within the window a push folds into that ping while
    it is still unread — commit counts add up, the text names the newest tip,
    and the row moves to the top of the inbox without buzzing again. If the
    recipient already read it, the push is filed as its own unread row, still
    without a banner. Nothing is lost; the phone buzzes at most once a minute
    per branch.

    Every recipient's "Code pushes" switch (the code_push kind) is honoured
    by enqueue_notification, for the inbox and the phone alike.
    """
    owner = clean_string(owner, MAX_NODE_NAME).lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT)
    if not valid_node_name(owner) or not repo:
        return 0
    slug = owner + "/" + repo
    branch = clean_string(branch, 120).strip()
    branch_key = branch or CODE_PUSH_OTHER_REFS
    key = clean_string(key, 80).strip().lower()
    pusher_account = clean_string(pusher_account, MAX_NODE_NAME).lower()
    try:
        commits = max(0, int(commits or 0))
    except (TypeError, ValueError):
        commits = 0
    recipients = [owner]
    for reader in await _org_repo_readers(env, owner, repo):
        if reader not in recipients:
            recipients.append(reader)
    delivery_settings = globals().get("_ping_delivery_settings")
    filed = 0
    for recipient in recipients:
        if recipient != owner and recipient == pusher_account:
            continue
        now = int(Date.now())
        if callable(delivery_settings):
            try:
                muted, _paused = await delivery_settings(env, recipient, now)
            except Exception:
                muted = ()
            if "code_push" in muted:
                continue
        current_key, previous_key = code_push_slot_keys(slug, branch_key, now)
        try:
            pending = await _code_push_pending(
                env, recipient, (current_key, previous_key))
        except Exception:
            pending = {}
        window = None
        for slot_key in (current_key, previous_key):
            ts, read_at, pending_meta = pending.get(slot_key, (0, 0, {}))
            try:
                first_at = int(pending_meta.get("firstAt") or ts or 0)
            except (TypeError, ValueError):
                first_at = ts
            if first_at and now - first_at < CODE_PUSH_WINDOW_MS:
                window = (slot_key, read_at, pending_meta, first_at)
                break
        row_meta = dict(meta or {})
        row_meta.update({"branch": branch, "commit": commit,
                         "refsDigest": refs_digest, "lastKey": key,
                         "pusher": pusher, "event": "code.push"})
        if window is None:
            dedupe, push, total, pushes = current_key, True, commits, 1
            row_meta["firstAt"] = now
        else:
            slot_key, read_at, pending_meta, first_at = window
            if key and pending_meta.get("lastKey") == key:
                continue  # the same state observed again: already counted
            push = False
            if read_at:
                dedupe, total, pushes = slot_key + ":" + (key or str(now)), \
                    commits, 1
                row_meta["firstAt"] = first_at
            else:
                dedupe = slot_key
                total = code_push_merge(pending_meta, commits)
                try:
                    pushes = int(pending_meta.get("pushes", 1) or 1) + 1
                except (TypeError, ValueError):
                    pushes = 2
                row_meta["firstAt"] = first_at
        row_meta["commits"] = total
        row_meta["pushes"] = pushes
        title, body, href = code_push_ping_text(
            owner, repo, branch=branch, commits=total, subject=subject,
            commit=commit, pusher=pusher, refs_digest=refs_digest)
        if await enqueue_notification(
                env, recipient, "code_push", title,
                body=body, repo=slug, href=href,
                source="code_push", dedupe=dedupe, meta=row_meta,
                push=push):
            filed += 1
    return filed


async def notify_release_published(env, owner, repo, release):
    tag = clean_string((release or {}).get("tag", ""), 128)
    actor = clean_string((release or {}).get("created_by", ""), MAX_NODE_NAME).lower()
    title = "Release " + (tag or "published") + " published"
    body = (release or {}).get("name", "") or ("Release " + tag + " is live.")
    dedupe = "release:" + owner + "/" + repo + ":" + tag
    ts = int((release or {}).get("published_at", 0) or 0)
    # The organization that fronts the repository hears about a cut release
    # for the same reason it hears about a new issue (adhoc #295): the people
    # who run it are the people who answer for what shipped.
    host = clean_string(owner, MAX_NODE_NAME).lower()
    for recipient in await _org_fanout_recipients(env, host, repo):
        await enqueue_notification(
            env, recipient, "release_published", title,
            body=body,
            repo=owner + "/" + repo,
            href=repo_web_href(owner, repo),
            actor=actor, source="release",
            dedupe=dedupe,
            ts=ts,
            meta={"tag": tag},
        )


async def _repo_notification_target(env, repo_bi):
    row = await d1_first(env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
    if not row:
        return "", ""
    rec = await decrypt_row(env, row.get("data", ""))
    if not rec:
        return "", ""
    return (clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower(),
            clean_string(rec.get("name", ""), MAX_REPO_SEGMENT))


async def notify_host_status(env, repo_bi, kind):
    owner, repo = await _repo_notification_target(env, repo_bi)
    if not owner or not repo:
        return
    title = "Host online" if kind == "host_online" else "Host offline"
    await enqueue_notification(
        env, owner, kind, title + " for " + owner + "/" + repo,
        body=("A desktop host is reachable." if kind == "host_online"
              else "No live host has checked in recently."),
        repo=owner + "/" + repo,
        href=repo_web_href(owner, repo),
        source="host", dedupe=kind + ":" + repo_bi,
    )


async def notify_stale_hosts_offline(env, cutoff):
    rows = await d1_all(
        env,
        "SELECT repo_bi FROM host_presence WHERE ts < ? "
        "GROUP BY repo_bi ORDER BY MIN(ts) LIMIT 2",
        cutoff,
    )
    notified = []
    for row in rows:
        repo_bi = row.get("repo_bi")
        if repo_bi:
            await notify_host_status(env, repo_bi, "host_offline")
            notified.append(repo_bi)
    return notified


async def notifications_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
        if not valid_node_name(node):
            return json_response({"error": "node_required"}, status=400)
        # A notification inbox is private to its owner: only the account itself,
        # proven by its session token (bearer header on this GET) or by an
        # account-key signature on the URL (the desktop Alerts page), may read it.
        if await _alert_inbox_account_name(env, request) != node:
            return json_response({"error": "unauthorized"}, status=401)
        if params.get("settings", [""])[0] == "1":
            # The Pings settings page's read (#347): every switch, the quiet
            # hours and the kind catalog, without paging the inbox.
            _, settings_rec = await _account_row(env, node)
            is_admin = await _is_admin(env, node)
            payload = dict({"ok": True},
                           **ping_settings_payload(settings_rec or {}, is_admin))
            if is_admin:
                payload["statusMonitorAlerts"] = (
                    await status_monitor_alert_rows(env))
            return json_response(payload)
        try:
            limit = int(params.get("limit", ["40"])[0])
        except (TypeError, ValueError):
            limit = 40
        limit = max(1, min(limit, MAX_NOTIFICATIONS_FETCH))
        try:
            offset = int(params.get("offset", ["0"])[0])
        except (TypeError, ValueError):
            offset = 0
        offset = max(0, min(offset, MAX_NOTIFICATIONS_PER_RECIPIENT))
        recipient_bi = await blind_index(env, node)
        rows = await d1_all(
            env,
            """SELECT dedupe_bi, ts, read_at, data FROM notifications
               WHERE recipient_bi=? ORDER BY ts DESC, dedupe_bi DESC
               LIMIT ? OFFSET ?""",
            recipient_bi, limit, offset,
        )
        # One SUM over every notification the recipient holds read them all
        # on each poll. Unread walks only the unread range of
        # idx_notifications_unread, and a short page already knows the total.
        unread_row = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM notifications "
            "WHERE recipient_bi=? AND read_at=0",
            recipient_bi,
        )
        unread = int((unread_row or {}).get("n") or 0)
        if len(rows) < limit and (rows or offset == 0):
            total = offset + len(rows)
        else:
            total_row = await d1_first(
                env,
                "SELECT COUNT(*) AS n FROM notifications WHERE recipient_bi=?",
                recipient_bi,
            )
            total = int((total_row or {}).get("n") or 0)
        items = []
        # Derive the AES key once for the whole page instead of per row: each
        # derivation is its own async WebCrypto round trip, and this endpoint is
        # polled often enough that N sequential round trips (one per notification)
        # measurably drags out the request.
        row_key = await _data_key(env) if rows else None
        for row in rows:
            rec = await decrypt_row(env, row.get("data", ""), key=row_key)
            if not rec:
                continue
            read_at = int(row.get("read_at") or 0)
            rec["id"] = row.get("dedupe_bi", "")
            rec["readAt"] = read_at
            rec["ts"] = int(row.get("ts") or rec.get("ts") or 0)
            items.append(rec)
        _, pause_rec = await _account_row(env, node)
        quiet_reader = globals().get("ping_quiet_until")
        return json_response({
            "ok": True,
            "notifications": items,
            "unread": unread,
            "total": total,
            "limit": limit,
            "offset": offset,
            "pauseUntil": ping_pause_until(pause_rec),
            "quietUntil": (quiet_reader(pause_rec)
                           if callable(quiet_reader) else 0),
        })

    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
        if not valid_node_name(node):
            return json_response({"error": "node_required"}, status=400)
        # Marking notifications read mutates the owner's inbox: same gate as the
        # GET (token from the POST body or an Authorization: Bearer header, or
        # the account-key read proof signed onto the URL).
        if await _alert_inbox_account_name(env, request, data) != node:
            return json_response({"error": "unauthorized"}, status=401)
        # Pausing and the Pings settings page (#347) are a different
        # capability from marking read, and the gate above accepts either a
        # session token or an account-key signature. ACCOUNT_ALERT_READ_PROOF
        # binds nothing but the node, so honouring either on the signed path
        # would let a captured mark-read POST be replayed as a mute. Browsers
        # hold a session; the desktop has its own signed rail for this (the
        # heartbeat).
        ping_settings = data.get("pingSettings")
        if (isinstance(ping_settings, dict) or "pauseUntil" in data) and \
                await _authed_account_name(env, request, data) != node:
            return json_response({"error": "unauthorized"}, status=401)
        if isinstance(ping_settings, dict):
            name_bi, account = await _account_row(env, node)
            if not name_bi or not account:
                return json_response({"error": "unauthorized"}, status=401)
            is_admin = await _is_admin(env, node)
            monitor_alerts = ping_settings.get("statusMonitorAlerts")
            if monitor_alerts is not None and not is_admin:
                return json_response({"error": "forbidden"}, status=403)
            if _apply_ping_settings(account, ping_settings):
                await _save_account(env, name_bi, account)
                if ping_settings.get("marketingEmail") is True:
                    await marketing_email_clear_unsubscribe(env, account)
            payload = dict({"ok": True},
                           **ping_settings_payload(account, is_admin))
            if is_admin:
                await _save_status_monitor_alerts(env, monitor_alerts, node)
                payload["statusMonitorAlerts"] = (
                    await status_monitor_alert_rows(env))
            return json_response(payload)
        if "pauseUntil" in data:
            name_bi, account = await _account_row(env, node)
            if not name_bi or not account:
                return json_response({"error": "unauthorized"}, status=401)
            if _apply_ping_pause(account, data.get("pauseUntil")):
                await _save_account(env, name_bi, account)
            return json_response({"ok": True,
                                  "pauseUntil": ping_pause_until(account)})
        recipient_bi = await blind_index(env, node)
        now = int(Date.now())
        if data.get("all"):
            await d1_run(
                env, "UPDATE notifications SET read_at=? WHERE recipient_bi=?",
                now, recipient_bi)
            return json_response({"ok": True})
        ids = data.get("ids") if isinstance(data.get("ids"), list) else []
        for item_id in ids[:MAX_NOTIFICATIONS_FETCH]:
            item_id = clean_string(item_id, 160)
            if item_id:
                await d1_run(
                    env,
                    "UPDATE notifications SET read_at=? WHERE recipient_bi=? AND dedupe_bi=?",
                    now, recipient_bi, item_id)
        return json_response({"ok": True})

    if method == "DELETE":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
        clear_all = data.get("all") is True
        item_id = clean_string(data.get("id", ""), 160).lower()
        if not valid_node_name(node) or (
                not clear_all and not re.fullmatch(r"[a-f0-9]{64}", item_id)):
            return json_response({"error": "bad_request"}, status=400)
        # A notification can only be removed from the authenticated owner's
        # own encrypted inbox. The opaque id is still scoped by recipient_bi,
        # so an id copied from another account cannot delete anything. The
        # desktop, which holds keys and no session token, signs either the id
        # or the explicit all-inbox operation with distinct proofs.
        if await _alert_inbox_account_name(
                env, request, data,
                resource=("all" if clear_all else item_id)) != node:
            return json_response({"error": "unauthorized"}, status=401)
        recipient_bi = await blind_index(env, node)
        if clear_all:
            await d1_run(
                env, "DELETE FROM notifications WHERE recipient_bi=?",
                recipient_bi)
        else:
            await d1_run(
                env,
                "DELETE FROM notifications "
                "WHERE recipient_bi=? AND dedupe_bi=?",
                recipient_bi,
                item_id,
            )
        await notify_account_event(env, node, "pings")
        return json_response({"ok": True})

    return json_response(
        {"error": "method_not_allowed"},
        status=405,
        extra_headers={"allow": "GET, POST, DELETE"},
    )


async def mirror_requests_handler(env, request):
    # Peer mirror requests (issue #385): a repo owner asks another node to
    # mirror their repo, the target's holder accepts or rejects, and on accept
    # that node starts mirroring. The request is parked as a bounded list on the
    # TARGET account record (heartbeat-delivered, like claim/ownership-transfer);
    # accepted entries ride back on the target node's signed heartbeat so its
    # desktop clones the repo. All actions are session-gated (the dashboard
    # login), exactly like the notification inbox this feeds.
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    action = clean_string(data.get("action", "create"), 20) or "create"
    actor = await _authed_account_name(env, request, data)
    if not valid_node_name(actor):
        return json_response({"error": "unauthorized"}, status=401)
    now = int(Date.now())

    if action == "create":
        target = clean_string(data.get("target", ""), MAX_NODE_NAME).lower()
        owner = clean_string(data.get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string(data.get("repo", ""), MAX_REPO_SEGMENT).strip()
        if not valid_node_name(target) or not valid_node_name(owner) or not repo:
            return json_response({"error": "bad_request"}, status=400)
        # "Ask a node to mirror YOUR repo": only the repo owner (proven by the
        # session, not a self-asserted body field) may send the request.
        if owner != actor:
            return json_response({"error": "forbidden"}, status=403)
        if target == owner:
            return json_response({"error": "self_target"}, status=400)
        if await _repo_is_private(env, owner, repo):
            # Mirroring is a public-repo affair (the /mirrors payload and clone
            # fallback are public-only); private repos need a share token flow.
            return json_response({"error": "private_repo"}, status=400)
        key_bi = await blind_index(env, owner + "/" + repo)
        repo_row = await d1_first(
            env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
        if not repo_row:
            return json_response({"error": "repo_not_found"}, status=404)
        target_bi, target_rec = await _account_row(env, target)
        if not target_rec or target_rec.get("status") != "active":
            return json_response({"error": "target_not_found"}, status=404)
        req_id = mirror_request_id(owner, repo, target)
        entry = {"id": req_id, "requester": owner, "owner": owner, "repo": repo,
                 "status": "pending", "ts": now}
        target_rec["mirror_requests"] = add_mirror_request(
            target_rec.get("mirror_requests"), entry)
        await _save_account(env, target_bi, target_rec)
        await enqueue_notification(
            env, target, "mirror_request", "Mirror request from " + owner,
            body=(owner + " asked your node to mirror " + owner + "/" + repo +
                  ". Accept to start mirroring it."),
            repo=owner + "/" + repo, href=repo_web_href(owner, repo),
            actor=owner, source="mirror_request",
            dedupe="mirror_request:" + req_id,
            meta={"requestId": req_id, "owner": owner, "repo": repo,
                  "requester": owner, "state": "pending"})
        return json_response({"ok": True, "requestId": req_id, "status": "pending"})

    if action in ("accept", "reject"):
        req_id = clean_string(data.get("requestId", ""), 200).strip().lower()
        if not req_id:
            return json_response({"error": "bad_request"}, status=400)
        target_bi, target_rec = await _account_row(env, actor)
        if not target_rec:
            return json_response({"error": "unauthorized"}, status=401)
        existing = find_mirror_request(target_rec.get("mirror_requests"), req_id)
        if not existing:
            return json_response({"error": "not_found"}, status=404)
        status = "accepted" if action == "accept" else "rejected"
        updated_list, updated = set_mirror_request_status(
            target_rec.get("mirror_requests"), req_id, status, ts=now)
        target_rec["mirror_requests"] = updated_list
        await _save_account(env, target_bi, target_rec)
        owner = clean_string((updated or {}).get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string((updated or {}).get("repo", ""), MAX_REPO_SEGMENT).strip()
        requester = clean_string(
            (updated or {}).get("requester", ""), MAX_NODE_NAME).lower()
        # Let the requester know the outcome (recipient != actor is guaranteed:
        # a request never targets its own owner).
        if requester and owner and repo:
            verb = "accepted" if action == "accept" else "declined"
            tail = (" — their node will start mirroring it shortly."
                    if action == "accept" else ".")
            await enqueue_notification(
                env, requester, "mirror_request",
                actor + " " + verb + " your mirror request",
                body=(actor + " " + verb + " your request to mirror " +
                      owner + "/" + repo + tail),
                repo=owner + "/" + repo, href=repo_web_href(owner, repo),
                actor=actor, source="mirror_request",
                dedupe="mirror_request_reply:" + req_id + ":" + status,
                meta={"requestId": req_id, "owner": owner, "repo": repo,
                      "state": status})
        return json_response({"ok": True, "status": status})

    return json_response({"error": "bad_action"}, status=400)


async def subscribe_handler(env, request, owner, repo):
    # Signed subscribe/unsubscribe for one issue or PR thread (issue #361). The
    # request is signed with the node's own Ed25519 key — the same proof of
    # control as a heartbeat — so only the account holder can watch or mute a
    # thread on their own behalf.
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    action = clean_string(data.get("action", "set"), 20)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    source = clean_string(data.get("source", ""), 20)
    if source not in ("issue", "pull"):
        return json_response({"error": "bad_source"}, status=400)
    try:
        number = int(data.get("number", 0))
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return json_response({"error": "bad_number"}, status=400)
    subscribed = bool(data.get("subscribed", True))
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(node):
        return json_response({"error": "unauthorized"}, status=401)
    _, rec = await _account_row(env, node)
    pubkey = rec.get("pubkey", "") if rec else ""
    _, session_rec = await _account_session_record(env, request, data)
    session_actor = clean_string(
        session_rec.get("name", "") if session_rec else "", MAX_NODE_NAME
    ).lower()
    session_authorized = bool(session_actor and session_actor == node)
    if not session_authorized:
        if action == "status":
            return json_response({"error": "unauthorized"}, status=401)
        if not pubkey or not _ts_ok(ts):
            return json_response({"error": "unauthorized"}, status=401)
        canonical = ("forkmesh-subscribe-v1\n" + owner + "/" + repo + "\n" + source +
                     "\n" + str(number) + "\n" + ("1" if subscribed else "0") +
                     "\n" + ts).encode()
        if not await ed25519_verify(pubkey, signature, canonical):
            return json_response({"error": "bad_signature"}, status=401)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        viewers = {
            node,
            clean_string((rec or {}).get("owner", ""), MAX_NODE_NAME).lower(),
        }
        viewers.discard("")
        allowed = False
        for viewer in viewers:
            if (viewer == str(owner).lower()
                    or await _account_owns_node(env, viewer, owner)):
                allowed = True
                break
        if not allowed:
            repo_bi = await blind_index(env, owner + "/" + repo)
            for viewer in viewers:
                grantee_bi = await blind_index(env, viewer)
                shared = await d1_first(
                    env,
                    "SELECT 1 AS one FROM repo_shares "
                    "WHERE repo_bi=? AND grantee_bi=?",
                    repo_bi, grantee_bi,
                )
                if shared:
                    allowed = True
                    break
        if not allowed:
            return json_response({"error": "not_found"}, status=404)
    if action == "status":
        thread_bi = await blind_index(
            env, _thread_key(owner, repo, source, number)
        )
        subscriber_bi = await blind_index(env, node)
        row = await d1_first(
            env,
            "SELECT data FROM thread_subscriptions "
            "WHERE thread_bi=? AND subscriber_bi=?",
            thread_bi, subscriber_bi,
        )
        subscription = await decrypt_row(env, row.get("data", "")) if row else None
        return json_response({
            "ok": True,
            "subscribed": bool(subscription and not subscription.get("muted")),
        })
    if action != "set":
        return json_response({"error": "bad_action"}, status=400)
    await subscribe_thread(env, owner, repo, source, number, node,
                           muted=not subscribed)
    return json_response({"ok": True, "subscribed": subscribed})


def _notification_queue(env):
    """The instant-delivery queue binding, or None when it is not configured.

    Absent binding is a supported deployment, not an error — see
    NOTIFICATION_QUEUE_BINDING. Callers fall back to the cron rail.
    """
    queue = getattr(env, NOTIFICATION_QUEUE_BINDING, None)
    if queue is None or js_nullish(queue):
        return None
    return queue


async def _queue_instant_notification(env, recipient, ts):
    """Ring the instant-delivery doorbell for one recipient. Never raises.

    The message names an account and nothing else: the notification payload
    stays encrypted in D1 and the consumer re-reads it there, so queue storage
    never holds notification content. It is also sent for *every* ping rather
    than only for instant recipients, because the delivery mode lives in the
    encrypted account record and this is the hot write path — deciding here
    would cost a decrypt per notification. The consumer, which is off the
    request path, makes that call instead.
    """
    queue = _notification_queue(env)
    if queue is None:
        return False
    now = int(ts or Date.now())
    last = _NOTIFICATION_QUEUE_MEMO.get(recipient, 0)
    if last and now - last < NOTIFICATION_QUEUE_COALESCE_MS:
        return False
    _NOTIFICATION_QUEUE_MEMO[recipient] = now
    if len(_NOTIFICATION_QUEUE_MEMO) > NOTIFICATION_QUEUE_MEMO_MAX:
        cutoff = now - NOTIFICATION_QUEUE_COALESCE_MS
        for stale in [key for key, seen in _NOTIFICATION_QUEUE_MEMO.items()
                      if seen < cutoff]:
            _NOTIFICATION_QUEUE_MEMO.pop(stale, None)
    try:
        _cron_subrequest_charge()
        # A JSON string, not a JS object: the body crosses the Python/JS
        # boundary in both directions and a plain string has no PyProxy
        # lifetime to get wrong (see git_bytes_response for the shape of that
        # failure).
        await queue.send(json.dumps({
            "recipient": recipient,
            "ts": now,
        }))
        return True
    except Exception:
        return False


async def _notification_email_recipient(env, recipient_bi):
    """Resolve (record, email-preference record, address) for a recipient.

    The address is "" whenever nothing may be sent — unknown or inactive
    account, unverified address, an explicit opt-out, or a live pause — so
    callers gate on it rather than repeating the checks.
    """
    acct = await d1_first(
        env, "SELECT data FROM users WHERE user_bi=?", recipient_bi)
    if not acct:
        acct = await d1_first(
            env, "SELECT data FROM nodes WHERE node_bi=?", recipient_bi)
    if not acct:
        return None, None, ""
    rec = await decrypt_row(env, acct.get("data", ""))
    if not rec or rec.get("status") != "active":
        return None, None, ""
    # Use the node owner's email if the node has an owner; otherwise use the node's email.
    email_rec = rec
    owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
    if owner:
        _, owner_rec = await _account_row(env, owner)
        if owner_rec and owner_rec.get("status") == "active":
            email_rec = owner_rec
    email = clean_string(email_rec.get("email", ""), 254).strip()
    if not email or not email_rec.get("email_verified"):
        return rec, email_rec, ""
    if email_rec.get("email_notifications") is False:
        return rec, email_rec, ""  # explicit opt-out
    if pings_paused(email_rec):
        return rec, email_rec, ""  # snoozed: still filed, just not mailed
    return rec, email_rec, email


async def _notification_email_items(env, rows, email_rec, last):
    """Decrypt one slice into the payloads this recipient wants emailed.

    Returns (items, newest). ``newest`` spans every row read, including the
    ones the per-kind preferences dropped, so a recipient who wants none of
    what arrived still advances their watermark instead of re-reading it.
    """
    items = []
    newest = last
    prefs = notification_email_preferences(email_rec)
    for row in rows or []:
        row_ts = int(row.get("ts") or 0)
        newest = max(newest, row_ts)
        payload = await decrypt_row(env, row.get("data", ""))
        if not payload:
            continue
        payload = dict(payload, id=row.get("dedupe_bi") or "")
        kind = clean_string(payload.get("kind", ""), 40)
        if not prefs.get(kind, False):
            continue
        if clean_string(payload.get("source", ""), 80) in NOTIFICATION_EMAIL_SKIP_SOURCES:
            continue
        items.append(payload)
    return items, newest


async def _skip_paused_notification_emails(env, recipient_bi, rec, now):
    """Carry a paused account's watermark over the pings it will never be sent.

    Pausing means "stop mailing me", not "mail me all of it at once later": if
    the watermark stood still for the whole quiet period, the first pass after
    the deadline would deliver every ping the pause was meant to spare — a week
    of mail in one burst. The rows themselves are left unread, so the inbox and
    the bell badge still hold the backlog to be read in the app.

    Reads only the newest row at or below `now` (the same query shape the
    digest slice uses, one row deep) because the watermark is a high-water mark
    and nothing between it and that row is going to be sent.
    """
    last = int(rec.get("last_digest_ts", 0) or 0)
    rows = await d1_all(
        env,
        "SELECT ts, data FROM notifications "
        "WHERE recipient_bi=? AND read_at=0 AND ts>? AND ts<=? "
        "ORDER BY ts DESC LIMIT ?",
        recipient_bi, last, now, 1)
    newest = int((rows[0] if rows else {}).get("ts") or 0)
    if newest > last:
        rec["last_digest_ts"] = newest
        rec["last_immediate_ts"] = max(
            _notification_immediate_watermark(rec), newest)
        await _save_account(env, recipient_bi, rec)


def _notification_pull_key(payload):
    if (clean_string(payload.get("source", ""), 80) != "pull"
            or clean_string(payload.get("kind", ""), 40)
            not in NOTIFICATION_PULL_STATE_KINDS):
        return None
    meta = payload.get("meta")
    try:
        number = int((meta if isinstance(meta, dict) else {}).get("number") or 0)
    except (TypeError, ValueError):
        return None
    owner, _, repo = clean_string(
        payload.get("repo", ""), 180).lower().strip().partition("/")
    if number <= 0 or not owner or not repo:
        return None
    return owner, repo, number


async def _notification_pull_settled(env, owner, repo, number):
    try:
        data = await _forkbot_repo_gateway_json(
            env, owner, repo, "blob?path=" + quote(
                ".forkmesh/pulls/%d/pull.md" % int(number), safe=""))
        fields = (microjobs.parse_pull_frontmatter(_forkbot_blob_text(data))
                  if data else {})
    except Exception:
        return False
    status = clean_string(fields.get("status", ""), 40).strip().lower()
    return bool(status) and status != "open"


async def _notification_email_stale(env, payload, now, reads):
    if not notification_email_immediate(payload):
        return False
    if int(payload.get("ts") or 0) < now - NOTIFICATION_IMMEDIATE_FRESH_MS:
        return True
    key = _notification_pull_key(payload)
    if key is None:
        return False
    if key not in reads:
        if len(reads) >= NOTIFICATION_PULL_STATE_MAX_READS:
            return None
        reads[key] = await _notification_pull_settled(env, *key)
    return reads[key]


async def _deliver_instant_notifications(env, recipient_bi, rec, email_rec,
                                         email, now, cutoff=None):
    """Send one email per unread ping for an instant-delivery recipient.

    Shared by the queue consumer (the fast path) and the cron (its backstop).
    Both rails advance the same last_digest_ts watermark and neither reads
    below it, which is what makes running both safe: whichever gets there first
    leaves nothing for the other to re-send. They are kept off each other's
    rows as well — with a queue configured the cron's cutoff stops at the
    quarantine, so it only ever reads the backlog the queue did not deliver.

    Known, accepted race: the watermark is a read-modify-write on a record both
    rails load independently, so a backstop pass that started before a consumer
    pass finished can save the older value and cost one duplicate email. It
    needs a stale undelivered ping *and* a new one landing in the same instant
    on the same account, and the fix (re-read plus merge the record before every
    save) costs a read and a decrypt on each send, which is not worth paying on
    the common path for a rare duplicate.

    Reads oldest-first so a burst larger than one slice leaves the watermark
    contiguous — newest-first would advance past the older pings and drop them
    for good.
    """
    last = int(rec.get("last_digest_ts", 0) or 0)
    rows = await d1_all(
        env,
        "SELECT dedupe_bi, ts, data FROM notifications "
        "WHERE recipient_bi=? AND read_at=0 AND ts>? AND ts<=? "
        "ORDER BY ts ASC LIMIT ?",
        recipient_bi, last, now if cutoff is None else cutoff,
        NOTIFICATION_INSTANT_MAX_ITEMS)
    items, newest = await _notification_email_items(env, rows, email_rec, last)
    already = _notification_immediate_watermark(rec)
    items = [item for item in items
             if not (notification_email_immediate(item)
                     and int(item.get("ts") or 0) <= already)]
    reads = {}
    items = [item for item in items
             if await _notification_email_stale(env, item, now, reads)
             is not True]
    if not items:
        if newest > last:
            rec["last_digest_ts"] = newest
            rec["last_immediate_ts"] = max(already, newest)
            await _save_account(env, recipient_bi, rec)
        return 0
    # The watermark only advances past what actually left, and a failed send
    # stops the run so the remainder is retried whole rather than skipped.
    sent = await _send_notification_emails_singly(
        env, rec, email_rec, email, items, now)
    delivered = last
    for item in items[:sent]:
        delivered = max(delivered, int(item.get("ts") or 0))
    if delivered > last:
        rec["last_digest_ts"] = delivered
        rec["last_immediate_ts"] = max(already, delivered)
    await _save_account(env, recipient_bi, rec)
    return sent


async def _send_notification_emails_singly(env, rec, email_rec, email, items,
                                           now):
    # Greet whoever owns the mailbox, not the node the rows are indexed
    # against — same reasoning as the digest (issue #652). email_rec is already
    # that account, or the record itself when the node owns its own address.
    greeting = clean_string(email_rec.get("name", ""), MAX_NODE_NAME).lower()
    # Resolved once for the whole slice rather than per email: the lookups are
    # per distinct repo/actor and this slice is usually one ping about one
    # repository, so a burst costs the same as a single send.
    identity = await _notification_digest_identity(env, items)
    base_url = _public_base_url(env) or FORKMESH_SITE_URL.rstrip("/")
    sent = 0
    for item in items:
        claim = await _claim_notification_email(env, email, item, now)
        if not claim:
            sent += 1
            continue
        subject, text, html = _notification_instant_email(
            greeting, item, identity=identity, base_url=base_url)
        ok = await _send_email(env, email, subject, text, html,
                               email_kind="notifications")
        _stamp_account_email(rec, "notifications", ok, now)
        if not ok:
            await _release_notification_emails(env, [claim])
            break
        sent += 1
    return sent


async def _notification_email_send_key(env, email, item):
    item = item if isinstance(item, dict) else {}
    ident = clean_string(item.get("id", ""), 128) or (
        "title:" + clean_string(item.get("title", ""), 160))
    return await blind_index(env, "notification-email:" + "\n".join((
        clean_string(email, 254).strip().lower(),
        clean_string(item.get("kind", ""), 40),
        clean_string(item.get("repo", ""), 180).lower(),
        ident,
        str(int(item.get("ts") or 0)),
    )))


async def _claim_notification_email(env, email, item, now):
    key = await _notification_email_send_key(env, email, item)
    try:
        result = await d1_run(
            env,
            "INSERT OR IGNORE INTO notification_email_sends "
            "(send_bi, created_at) VALUES (?,?)",
            key, int(now))
    except Exception:
        return key
    try:
        return key if int(result.meta.changes) > 0 else ""
    except Exception:
        return key


async def _release_notification_emails(env, keys):
    for key in keys or []:
        try:
            await d1_run(
                env,
                "DELETE FROM notification_email_sends WHERE send_bi=?", key)
        except Exception:
            pass


async def prune_notification_email_sends(env):
    await ensure_schema(env)
    await d1_run(
        env,
        "DELETE FROM notification_email_sends WHERE created_at < ?",
        int(Date.now()) - NOTIFICATION_EMAIL_SEND_RETAIN_MS)


async def _deliver_immediate_notifications(env, recipient_bi, rec, email_rec,
                                           email, now, cutoff=None):
    last = _notification_immediate_watermark(rec)
    rows = await d1_all(
        env,
        "SELECT dedupe_bi, ts, data FROM notifications "
        "WHERE recipient_bi=? AND read_at=0 AND ts>? AND ts<=? "
        "ORDER BY ts ASC LIMIT ?",
        recipient_bi, last, now if cutoff is None else cutoff,
        NOTIFICATION_IMMEDIATE_SCAN)
    prefs = notification_email_preferences(email_rec)
    scanned = []
    items = []
    reads = {}
    for row in rows or []:
        payload = await decrypt_row(env, row.get("data", ""))
        if isinstance(payload, dict):
            payload = dict(payload, id=row.get("dedupe_bi") or "")
        wanted = (isinstance(payload, dict)
                  and prefs.get(clean_string(payload.get("kind", ""), 40),
                                False)
                  and notification_email_immediate(payload))
        if wanted and len(items) >= NOTIFICATION_INSTANT_MAX_ITEMS:
            break
        if wanted:
            stale = await _notification_email_stale(env, payload, now, reads)
            if stale is None:
                break
            wanted = not stale
        if wanted:
            items.append(payload)
        scanned.append((int(row.get("ts") or 0), bool(wanted)))
    sent = 0
    if items:
        sent = await _send_notification_emails_singly(
            env, rec, email_rec, email, items, now)
    reach = last
    remaining = sent
    for row_ts, wanted in scanned:
        if wanted:
            if not remaining:
                break
            remaining -= 1
        reach = max(reach, row_ts)
    if items or rec.get("last_immediate_ts") != reach:
        rec["last_immediate_ts"] = reach
        await _save_account(env, recipient_bi, rec)
    return sent


async def _notification_public_repo(env, slug):
    """Public owner/repo for one stored notification slug.

    An organization alias is a real address: the Worker rewrites
    /<org>/<repo> and every /api/repo/<org>/<repo>/... path onto the serving
    node, so naming the organization keeps the email pointing at the same
    place the site does while never printing the mirror that publishes the
    bytes. A repo no organization links keeps its /<node>/<repo> route, which
    is its only real address — rewriting that one to the owning user account
    would print an identity that does not resolve (adhoc #132).
    """
    owner, _, name = (slug or "").partition("/")
    owner = clean_string(owner, MAX_NODE_NAME).lower().strip()
    name = clean_string(name, MAX_REPO_SEGMENT).lower().strip()
    if not owner or not name:
        return ""
    row = await d1_first(
        env,
        "SELECT o.name AS name FROM org_repos r "
        "JOIN orgs o ON o.org_bi=r.org_bi "
        "WHERE r.node_owner=? AND r.repo=? ORDER BY o.name LIMIT 1",
        owner, name)
    org = clean_string((row or {}).get("name", ""), MAX_NODE_NAME).lower()
    if valid_node_name(org) and org != owner:
        return org + "/" + name
    # A ping outlives the node that served it: notifications are retained for
    # ninety days, and a mirror retired inside that window has already been
    # unlinked from its organization, so the reverse lookup above finds
    # nothing for it. Ask the other way round — which organization publishes
    # a repo by this name — and accept the answer only when it is
    # unambiguous, so a legacy backlog item resolves instead of re-leaking a
    # decommissioned mirror.
    if owner in STATUS_RETIRED_MIRRORS:
        rows = await d1_all(
            env,
            "SELECT o.name AS name FROM org_repos r "
            "JOIN orgs o ON o.org_bi=r.org_bi WHERE r.repo=? LIMIT 2",
            name)
        names = {
            clean_string(row.get("name", ""), MAX_NODE_NAME).lower()
            for row in rows or []
        }
        names = {value for value in names if valid_node_name(value)}
        if len(names) == 1:
            return names.pop() + "/" + name
    return ""


async def _notification_digest_identity(env, items, avatar_max_b64=0):
    """Resolve the database-backed halves of one digest's rendering.

    Two lookups the pure renderer cannot do: the public slug fronting each
    stored repo, and the actor portraits. Both are per distinct value and
    bounded by NOTIFICATION_DIGEST_MAX_LOOKUPS. Failures are swallowed per
    value — an unresolvable name simply renders as stored, which is what the
    digest did before any of this existed, and the cron must never raise.

    `avatar_max_b64` overrides how large a portrait may be before it is
    dropped. Mail and a lock screen want different answers — a phone renders
    a crisp thumbnail where Gmail would clip the whole message — so the
    caller names its own ceiling and the default stays the email one.
    """
    repos = {}
    avatars = {}
    for item in items or []:
        slug = clean_string(
            (item or {}).get("repo", ""), 180).lower().strip()
        if (slug and slug not in repos
                and len(repos) < NOTIFICATION_DIGEST_MAX_LOOKUPS):
            try:
                repos[slug] = await _notification_public_repo(env, slug)
            except Exception:
                repos[slug] = ""
        actor = clean_string(
            (item or {}).get("actor", ""), MAX_NODE_NAME).lower().strip()
        if (actor and actor not in avatars
                and len(avatars) < NOTIFICATION_DIGEST_MAX_LOOKUPS):
            avatars[actor] = await _notification_actor_avatar(
                env, actor, max_b64=avatar_max_b64)
    return {"repos": repos, "avatars": avatars}


async def _notification_actor_avatar(env, actor, max_b64=0):
    """Base64 PNG portrait for an actor, or "" when there is nothing to show.

    Deliberately bounded before it is returned: an oversized portrait would
    push the digest past the size where mail clients clip it, and the byline
    renders the actor's name whether or not an image comes back.
    """
    if not valid_node_name(actor):
        return ""
    try:
        _, rec = await _account_row(env, actor)
    except Exception:
        return ""
    if not rec or rec.get("status") != "active":
        return ""
    avatar = clean_string(rec.get("avatar_png", ""), MAX_AVATAR_B64).strip()
    if len(avatar) > (int(max_b64 or 0) or NOTIFICATION_EMAIL_AVATAR_MAX_B64):
        return ""
    return avatar if avatar and AVATAR_B64_RE.match(avatar) else ""


async def send_notification_digests(env, include_general_chat=True):
    # Cron: roll each recipient's unread notifications into a single email so a
    # reply reaches people who don't have the app open (issue #361). Only the main
    # relay sends mail; recipients need a verified email and must not have opted
    # out. Best-effort — never raise from the cron.
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    max_age_cut = now - NOTIFICATION_DIGEST_MIN_AGE_MS
    recips = await d1_all(
        env,
        "SELECT DISTINCT recipient_bi FROM notifications "
        "WHERE read_at=0 AND ts<=? LIMIT ?",
        max_age_cut, NOTIFICATION_DIGEST_MAX_RECIPIENTS)
    # With the queue configured it owns the fresh window, and this phase is
    # purely its backstop: everything still unread once it is past the
    # quarantine is, by definition, what the queue failed to deliver — and the
    # digest query above already selects exactly that. Without the queue the
    # cron is the whole instant rail, so it also has to look *inside* the
    # quarantine window, which is what this second slice is for. It is
    # deliberately a superset of the digest query rather than a disjoint
    # cohort: the delivery mode lives in the encrypted account record, not in
    # anything notifications can be indexed on. The two lists are merged on
    # recipient_bi and each recipient is handled once, under whichever mode
    # their own record asks for; a digest recipient picked up here falls
    # through to the digest rules, which no-op while their pings are fresh.
    instant_recips = []
    if _notification_queue(env) is None:
        instant_recips = await d1_all(
            env,
            "SELECT DISTINCT recipient_bi FROM notifications "
            "WHERE read_at=0 AND ts<=? LIMIT ?",
            now, NOTIFICATION_INSTANT_MAX_RECIPIENTS)
    ordered_recipients = []
    seen_recipients = set()
    for recip in list(recips or []) + list(instant_recips or []):
        candidate_bi = (recip or {}).get("recipient_bi")
        if not candidate_bi or candidate_bi in seen_recipients:
            continue
        seen_recipients.add(candidate_bi)
        ordered_recipients.append(candidate_bi)
    for recipient_bi in ordered_recipients:
        rec, email_rec, email = await _notification_email_recipient(
            env, recipient_bi)
        # Paused accounts resolve to no address above, so this is the one place
        # that still has to act on them: the cron is what keeps their watermark
        # moving through the quiet period.
        if rec is not None and pings_paused(email_rec, now):
            await _skip_paused_notification_emails(env, recipient_bi, rec, now)
            continue
        if not email:
            continue
        if notification_delivery_mode(email_rec) == "instant":
            # Backstop only when the queue is carrying the fresh window: the
            # cutoff stays at the quarantine so this phase can never race the
            # consumer over a ping the consumer is already sending. Without the
            # queue it opens up to now and this is the whole instant rail.
            await _deliver_instant_notifications(
                env, recipient_bi, rec, email_rec, email, now,
                cutoff=(now if _notification_queue(env) is None
                        else max_age_cut))
            continue
        await _deliver_immediate_notifications(
            env, recipient_bi, rec, email_rec, email, now,
            cutoff=(now if _notification_queue(env) is None
                    else max_age_cut))
        last = int(rec.get("last_digest_ts", 0) or 0)
        if last and now - last < NOTIFICATION_DIGEST_INTERVAL_MS:
            continue
        rows = await d1_all(
            env,
            "SELECT dedupe_bi, ts, data FROM notifications "
            "WHERE recipient_bi=? AND read_at=0 AND ts>? AND ts<=? "
            "ORDER BY ts DESC LIMIT ?",
            recipient_bi, last, max_age_cut, NOTIFICATION_DIGEST_MAX_ITEMS)
        items, newest = await _notification_email_items(
            env, rows, email_rec, last)
        items = [item for item in items
                 if not notification_email_immediate(item)]
        claims = []
        unsent = []
        for item in items:
            claim = await _claim_notification_email(env, email, item, now)
            if claim:
                claims.append(claim)
                unsent.append(item)
        items = unsent
        if not items:
            if newest > last:
                rec["last_digest_ts"] = newest
                await _save_account(env, recipient_bi, rec)
            continue
        # Greet whoever owns the mailbox this is going to. Notifications are
        # indexed against the NODE that holds them, but a node with an owner
        # sends to the owner's address — greeting the node alias there names a
        # machine at a human (issue #652). email_rec is already that account
        # (or the record itself when the node owns its own address).
        greeting = clean_string(
            email_rec.get("name", ""), MAX_NODE_NAME).lower()
        identity = await _notification_digest_identity(env, items)
        subject, text, html = _notification_digest_email(
            greeting, items, identity=identity,
            base_url=_public_base_url(env) or FORKMESH_SITE_URL.rstrip("/"))
        ok = await _send_email(
            env, email, subject, text, html, email_kind="notifications")
        if ok:
            rec["last_digest_ts"] = newest
        else:
            await _release_notification_emails(env, claims)
        _stamp_account_email(rec, "notifications", ok, now)
        await _save_account(env, recipient_bi, rec)
    if include_general_chat:
        await send_general_chat_digests(env)


def _queue_batch_messages(batch):
    """Python list of one batch's messages, tolerant of the JS array proxy."""
    messages = getattr(batch, "messages", None)
    if messages is None or js_nullish(messages):
        return []
    try:
        count = int(messages.length)
    except (TypeError, ValueError, AttributeError):
        try:
            return list(messages)
        except TypeError:
            return []
    return [messages[index] for index in range(count)]


def _queue_message_recipient(message):
    """The account name one instant-delivery doorbell names, or ""."""
    body = getattr(message, "body", None)
    if body is None or js_nullish(body):
        return ""
    try:
        data = json.loads(str(body))
    except (TypeError, ValueError):
        return ""
    if not isinstance(data, dict):
        return ""
    recipient = clean_string(data.get("recipient", ""), MAX_NODE_NAME).lower()
    return recipient if valid_node_name(recipient) else ""


async def process_notification_queue(env, batch):
    """Queue consumer: send instant notification email as the ping lands.

    Messages are acked implicitly by returning normally, and nothing here
    retries. That is deliberate rather than lazy: a retry re-runs the whole
    batch, and the only failure worth re-running is a send that did not happen
    — which the watermark already leaves pending for the cron backstop a few
    minutes later. Raising instead would buy faster recovery at the cost of
    re-delivering the batch's *successful* recipients on every attempt.
    """
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    # One thread's fan-out puts many messages in a batch, often naming the same
    # recipient more than once. Collapse them: the delivery below reads from
    # the watermark, so a second pass for the same account would find nothing
    # and still cost a decrypt.
    recipients = []
    seen = set()
    for message in _queue_batch_messages(batch):
        recipient = _queue_message_recipient(message)
        if not recipient or recipient in seen:
            continue
        seen.add(recipient)
        recipients.append(recipient)
        if len(recipients) >= NOTIFICATION_QUEUE_MAX_RECIPIENTS:
            break
    for recipient in recipients:
        try:
            recipient_bi = await blind_index(env, recipient)
            rec, email_rec, email = await _notification_email_recipient(
                env, recipient_bi)
            if not email:
                continue
            # The producer doorbells every ping, not only instant ones, so this
            # is where a digest recipient is filtered out — their mail stays
            # with the cron rollup.
            if notification_delivery_mode(email_rec) != "instant":
                await _deliver_immediate_notifications(
                    env, recipient_bi, rec, email_rec, email, now)
                continue
            await _deliver_instant_notifications(
                env, recipient_bi, rec, email_rec, email, now)
        except Exception:
            # One recipient's failure must not cost the rest of the batch its
            # delivery; the cron backstop re-reads whatever did not send.
            pass


async def _general_chat_encrypted_message_count(env, since_ts, until_ts):
    await ensure_schema(env)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM chat_history "
        "WHERE room_key=? AND ts>? AND ts<=?",
        FLAGSHIP_ROOM_KEY, int(since_ts or 0), int(until_ts or 0),
    )
    return int((row or {}).get("c") or 0)


async def send_general_chat_digests(env):
    # The #general room history is retained as encrypted frames. The daily email
    # intentionally reports only a count since the recipient's last digest; it
    # never decrypts or embeds message text.
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    # Recipients come from the authoritative users table (accounts is legacy and
    # is drained as records migrate); it only holds user-kind records, exactly
    # the population eligible for this digest.
    rows = await d1_all(
        env,
        "SELECT user_bi AS name_bi, data FROM users ORDER BY username LIMIT ?",
        GENERAL_CHAT_EMAIL_MAX_RECIPIENTS,
    )
    for row in rows or []:
        name_bi = row.get("name_bi")
        if not name_bi:
            continue
        rec = await decrypt_row(env, row.get("data", ""))
        if not rec or rec.get("status") != "active" or _account_kind(rec) != "user":
            continue
        email = clean_string(rec.get("email", ""), 254).strip()
        if not email or not rec.get("email_verified"):
            continue
        if rec.get("email_notifications") is False:
            continue
        if pings_paused(rec, now):
            # Stamped rather than skipped, so the day spent paused is a day
            # this rollup covered and not a backlog waiting at the deadline.
            rec["last_general_chat_digest_ts"] = now
            await _save_account(env, name_bi, rec)
            continue
        if not notification_email_enabled(rec, "general_chat"):
            continue
        last = int(rec.get("last_general_chat_digest_ts", 0) or 0)
        if last and now - last < GENERAL_CHAT_EMAIL_INTERVAL_MS:
            continue
        since = max(last, now - GENERAL_CHAT_EMAIL_LOOKBACK_MS)
        count = await _general_chat_encrypted_message_count(env, since, now)
        if count <= 0:
            rec["last_general_chat_digest_ts"] = now
            await _save_account(env, name_bi, rec)
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        subject, text, html = _general_chat_digest_email(name, count)
        ok = await _send_email(
            env, email, subject, text, html, email_kind="general_chat")
        if ok:
            rec["last_general_chat_digest_ts"] = now
        _stamp_account_email(rec, "general_chat", ok, now)
        await _save_account(env, name_bi, rec)


def _light_email_fragment(fragment):
    """Normalize legacy dark inline fragments into one high-contrast theme."""
    rendered = str(fragment or "")
    for old, new in (
        ("#090909", "#f6f8fa"),
        ("#0f0f11", "#f6f8fa"),
        ("#141416", "#ffffff"),
        ("#313134", "#d0d7de"),
        ("#f5f5f5", "#24292f"),
        ("#d4d4d8", "#24292f"),
        ("#a3a3a3", "#57606a"),
        ("#8a8a93", "#57606a"),
        ("#4ade80", "#1f883d"),
        ("#052e16", "#ffffff"),
    ):
        rendered = rendered.replace(old, new)
    return rendered


