def _clean_issue_attachment_data(value):
    """Validate the base64 image bytes a no-write-access node ships alongside a
    signed issue/comment "open"/"comment" event (see MAX_ISSUE_ATTACHMENT_BYTES).
    Returns (cleaned_list, error); cleaned_list entries are {"name","data"} with
    data re-encoded from the decoded bytes so nothing but valid base64 survives."""
    if not isinstance(value, list):
        return [], None
    if len(value) > MAX_ISSUE_ATTACHMENTS:
        return [], "too_many_attachments"
    cleaned = []
    for entry in value:
        if not isinstance(entry, dict):
            return [], "bad_attachment"
        name = entry.get("name", "")
        if not isinstance(name, str) or not ISSUE_ATTACHMENT_NAME_RE.match(name):
            return [], "bad_attachment"
        data = entry.get("data", "")
        if not isinstance(data, str) or len(data) > 4 * (
                (MAX_ISSUE_ATTACHMENT_BYTES + 2) // 3):
            return [], "attachment_too_large"
        try:
            raw = base64.b64decode(data, validate=True)
        except Exception:
            return [], "bad_attachment"
        if len(raw) > MAX_ISSUE_ATTACHMENT_BYTES:
            return [], "attachment_too_large"
        cleaned.append({"name": name, "data": base64.b64encode(raw).decode()})
    return cleaned, None


async def _log_inbox_drain(env, repo_bi, kind, count):
    # Audit trail for inbox acks (adhoc #97): one row per non-empty drain so a
    # "web-filed item vanished but never synced" report is traceable. Content-free
    # (blind-indexed repo, a count) and best-effort — never fail the ack over it.
    if count <= 0:
        return
    try:
        await d1_run(
            env,
            "INSERT INTO inbox_drain_log (ts, repo_bi, kind, count) VALUES (?,?,?,?)",
            int(Date.now()), repo_bi, kind, int(count))
    except Exception:
        pass


def _drain_ids_from_request(request):
    # ?ids=1,2,3 on an inbox-drain DELETE: the node acks exactly the rows it
    # merged, so a submission inserted after the node's read survives to the
    # next sync instead of being swept away undelivered (adhoc #97).
    params = parse_qs(urlparse(request.url).query)
    raw = params.get("ids", [""])[0]
    ids = []
    for part in raw.split(","):
        part = part.strip()
        if not part:
            continue
        try:
            ids.append(int(part))
        except (TypeError, ValueError):
            continue
    return ids


async def _authorized_mirror_issue_signing_key(env, request, owner, repo):
    """Authorize one fresh direct-HTTPS node that mirrors this public repo.

    The caller signs with the account-bound key registered for its endpoint.
    Repository membership comes from the same owner-pinned public mirror group
    used by direct reads, so merely being an online ForkMesh node is not enough.
    Intake deliberately requires fresh endpoint health and integrity rather
    than the clone router's exact full-ref generation: active agent branches can
    move between otherwise healthy peers, and collaboration rows must land on
    any available group mirror instead of waiting for every auxiliary ref to be
    byte-identical. The mirror's signed post-merge attestation pins the state it
    actually materialized before the row is acknowledged.
    """
    if await _repo_is_private(env, owner, repo):
        return "", ""
    params = parse_qs(urlparse(request.url).query)
    signer = safe_segment(params.get("owner", [""])[0])
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not signer or not ts or not sig:
        return "", ""
    try:
        if abs(int(Date.now()) - int(ts)) > LOGIN_MAX_SKEW_MS:
            return "", ""
    except (TypeError, ValueError):
        return "", ""
    try:
        original = REPO_API_PREFIX_RE.match(urlparse(request.url).path)
        public_owner = (
            safe_segment(original.group(1)) if original else owner)
        public_repo = (
            safe_segment(original.group(2)) if original else repo)
        backing_owner = str(owner or "").strip().lower()
        if (
            str(public_owner or "").lower() != backing_owner
            and str(public_repo or "").lower()
            == str(repo or "").strip().lower()
            and await _org_repo_node(env, public_owner, public_repo)
            == backing_owner
        ):
            public_owner, public_repo = backing_owner, repo
        flagship_owner = (
            await _org_repo_node(env, "forkmesh", "forkmesh")
            or "forkmesh"
        )
        flagship_intake = bool(
            public_repo == "forkmesh"
            and public_owner in ("forkmesh", flagship_owner)
        )
        context = await _https_mirror_public_context(
            env, public_owner, public_repo)
    except Exception:
        context = None
        flagship_intake = False
    if not context and not flagship_intake:
        return "", ""
    # Membership comes from the signed catalog's mirror group, while freshness
    # and state integrity come from the exact endpoint row below. Requiring the
    # catalog record itself to carry the same current pin as the endpoint made
    # intake race every successful sync: the fresh endpoint challenge passed,
    # but its asynchronous catalog publication lagged by one generation and
    # the relay returned 401. A node outside the group is still rejected, and a
        # group member cannot drain without a fresh identity-bound health proof
        # and an integrity-clean repository endpoint.
    allowed_nodes = {
        str(value or "").strip().lower()
        for value in (context or {}).get("groupNodes", set())
    }
    now = int(Date.now())
    rows = await d1_all(
        env,
        """SELECT node_name,public_key FROM mirror_https_endpoints
            WHERE checked_at>=? AND healthy=1
              AND integrity='ok' AND abuse_blocked=0""",
        now - HTTPS_MIRROR_STATUS_FRESH_MS,
    )
    canonical = (
        "forkmesh-issues-pull-v1\n" + signer + "\n" + ts
    ).encode()
    for row in rows or []:
        node = clean_string(
            row.get("node_name", ""), MAX_NODE_NAME).strip().lower()
        public_key = clean_string(row.get("public_key", ""), 160).strip()
        if (
            (not flagship_intake and node not in allowed_nodes)
            or not valid_node_pubkey(public_key)
            or public_key not in await _claimed_node_signing_pubkeys(env, node)
        ):
            continue
        if await ed25519_verify(public_key, sig, canonical):
            return public_key, node
    return "", ""


async def _collaboration_source_online(env, owner, repo):
    """Return whether the canonical repository device has a fresh endpoint.

    Mirror intake is failover, not a race with the source of truth.  A web
    submission wakes both kinds of node, and without this preference whichever
    GET reached D1 first leased and permanently drained the row.  That let one
    mirror create the authoritative collaboration commit while an online source
    missed the submission entirely.  Use the same signed endpoint-health facts
    as public routing; on lookup failure stay available and let a mirror intake.

    Liveness comes from the freshness window, not from trusting the source
    forever: a wedged or killed node stops renewing its signed health lease, so
    `checked_at` goes stale within HTTPS_MIRROR_STATUS_FRESH_MS and mirrors
    resume intake on their own.  That bound is why deferring here cannot strand
    a submission the way an unbounded "source owns it" rule would.
    """
    try:
        context = await _https_mirror_public_context(env, owner, repo)
        source_node = clean_string(
            (context or {}).get("sourceNode", ""), MAX_NODE_NAME
        ).strip().lower()
        if not valid_node_name(source_node):
            return False
        row = await d1_first(
            env,
            "SELECT 1 AS online FROM mirror_https_endpoints "
            "WHERE lower(node_name)=? AND checked_at>=? AND healthy=1 "
            "AND integrity='ok' AND abuse_blocked=0 LIMIT 1",
            source_node,
            int(Date.now()) - HTTPS_MIRROR_STATUS_FRESH_MS,
        )
        return bool(row and row.get("online"))
    except Exception:
        return False


async def _deferred_mirror_intake(env, owner, repo, signing_key, mirror_node):
    """Response telling an authorized mirror to stand down, else None.

    Deliberately a 200 with nothing pending rather than a 403: the desktop
    treats a rejected mirror drain as a misconfiguration, logging "the relay
    rejected this node's signed mirror issue intake" and slowing retries to
    hours.  Standing down is the normal, healthy state whenever the source of
    truth is up, so it must read as an empty queue, not as a refusal.
    """
    if not signing_key or not await _collaboration_source_online(
            env, owner, repo):
        return None
    return json_response({
        "ok": True,
        "pending": [],
        "mirrorIntake": True,
        "mirror": mirror_node,
        "sourceOnline": True,
    })


async def _leased_inbox_page(env, table, repo_bi, claimant_bi="",
                             mirror_only=False):
    """Read one bounded page of inbox rows as ``(rows, more_waiting)``.

    Bounded twice over — row count and total encrypted payload — because a
    queue costs far more than any single submission cap suggests (see
    INBOX_DRAIN_MAX_ROWS). The id/LENGTH pass is what keeps the bound honest:
    selecting ``data`` and trimming afterwards would already have pulled the
    whole backlog into the isolate, which is the allocation that killed it. A
    page always carries at least one row, so a head bigger than the byte
    budget can never stall the queue behind it.
    """
    if table not in ("issue_inbox", "pull_inbox", "discussion_inbox"):
        return [], False
    where = "repo_bi=?"
    params = [repo_bi]
    if claimant_bi:
        where += " AND claimed_by_bi=?"
        params.append(claimant_bi)
    if mirror_only:
        where += " AND mirrored_at=0"
    # One row over the cap is what tells the caller more is waiting.
    sized = await d1_all(
        env,
        "SELECT id, LENGTH(data) AS n FROM %s WHERE %s "
        "ORDER BY id ASC LIMIT ?" % (table, where),
        *params, INBOX_DRAIN_MAX_ROWS + 1,
    )
    ids = []
    used = 0
    for row in sized[:INBOX_DRAIN_MAX_ROWS]:
        row_bytes = int(row.get("n") or 0)
        if ids and used + row_bytes > INBOX_DRAIN_MAX_BYTES:
            break
        ids.append(row.get("id"))
        used += row_bytes
    if not ids:
        return [], False
    marks = ",".join("?" for _ in ids)
    rows = await d1_all(
        env,
        "SELECT id, data FROM %s WHERE %s AND id IN (%s) ORDER BY id ASC"
        % (table, where, marks),
        *params, *ids,
    )
    return rows, len(sized) > len(ids)


async def _claim_issue_inbox(
        env, repo_bi, signing_key, mirror_only=False):
    """Lease every currently available row to one authorized desktop device.

    The UPDATE predicate makes competing drains converge on one winner per row:
    once one device writes its opaque claimant index, another device cannot
    overwrite it until the bounded lease expires.
    """
    if not signing_key:
        return ""
    claimant_bi = await blind_index(
        env, "issue-inbox-claim:" + signing_key)
    now = int(Date.now())
    mirror_clause = " AND mirrored_at=0" if mirror_only else ""
    await d1_run(
        env,
        "UPDATE issue_inbox SET claimed_by_bi=?, claim_expires_at=? "
        "WHERE repo_bi=? AND (claimed_by_bi='' OR claim_expires_at<=? "
        "OR claimed_by_bi=?)" + mirror_clause,
        claimant_bi, now + ISSUE_INBOX_CLAIM_TTL_MS, repo_bi, now,
        claimant_bi,
    )
    return claimant_bi


async def _drain_issue_inbox_on_mirror(
        env, request, repo_bi, claimant_bi, mirror_node):
    """Drain the exact leased rows an online mirror has merged into the repo.

    A mirror merge is authoritative: the submission is committed to the served
    branch and propagates across the mirror mesh (and back into the source's
    working copy when that node returns), so the row is deleted outright — the
    queue drains whenever ANY approved mirror is online, with no pending copy
    retained for the source-of-truth node. The claim predicate keeps competing
    mirrors converging on one winner per row.
    """
    ids = _drain_ids_from_request(request)
    if not ids or not claimant_bi or not mirror_node:
        return 0
    marks = ",".join("?" for _ in ids)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=? "
        "AND id IN (%s) AND claimed_by_bi=?" % marks,
        repo_bi, *ids, claimant_bi,
    )
    count = int((row or {}).get("c") or 0)
    if count:
        await d1_run(
            env,
            "DELETE FROM issue_inbox WHERE repo_bi=? "
            "AND id IN (%s) AND claimed_by_bi=?" % marks,
            repo_bi, *ids, claimant_bi,
        )
        await _log_inbox_drain(env, repo_bi, "issues", count)
    return count


async def _claim_collaboration_inbox_on_mirror(
        env, table, repo_bi, signing_key):
    """Lease unmaterialized PR/discussion rows to one approved mirror."""
    if table not in ("pull_inbox", "discussion_inbox") or not signing_key:
        return ""
    claimant_bi = await blind_index(
        env, "collaboration-inbox-claim:" + table + ":" + signing_key)
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE %s SET claimed_by_bi=?, claim_expires_at=? "
        "WHERE repo_bi=? AND mirrored_at=0 AND "
        "(claimed_by_bi='' OR claim_expires_at<=? OR claimed_by_bi=?)" % table,
        claimant_bi, now + ISSUE_INBOX_CLAIM_TTL_MS, repo_bi, now,
        claimant_bi,
    )
    return claimant_bi


async def _drain_collaboration_inbox_on_mirror(
        env, request, table, repo_bi, claimant_bi, mirror_node):
    """Drain exact leased PR/discussion rows once a mirror commits them.

    Same semantics as _drain_issue_inbox_on_mirror: the mirror's merge is the
    real merge, so the acknowledged rows leave the queue instead of waiting as
    "pending" for the source-of-truth node to come online.
    """
    if table not in ("pull_inbox", "discussion_inbox"):
        return 0
    ids = _drain_ids_from_request(request)
    if not ids or not claimant_bi or not mirror_node:
        return 0
    marks = ",".join("?" for _ in ids)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM %s WHERE repo_bi=? "
        "AND id IN (%s) AND claimed_by_bi=?" % (table, marks),
        repo_bi, *ids, claimant_bi,
    )
    count = int((row or {}).get("c") or 0)
    if count:
        await d1_run(
            env,
            "DELETE FROM %s WHERE repo_bi=? "
            "AND id IN (%s) AND claimed_by_bi=?" % (table, marks),
            repo_bi, *ids, claimant_bi,
        )
        await _log_inbox_drain(
            env, repo_bi,
            "pulls" if table == "pull_inbox" else "discussions", count)
    return count


async def _release_inbox_claim(env, table, repo_bi, claimant_bi):
    """Drop this node's lease on the rows it read but did not ack.

    A claim exists to stop two drains applying the same submission twice; it is
    not meant to reserve a queue. Once a node has answered with its ack, its
    cycle is over: whatever it left behind (a row that landed mid-drain, or one
    it could not apply) should be available to the account's OTHER node — or to
    an approved mirror — immediately, instead of sitting invisible for the rest
    of ISSUE_INBOX_CLAIM_TTL_MS. Releasing here rather than shortening the TTL
    keeps the desktop's read->apply->ack window as long as it is today, so a
    slow desktop drain can never have its lease expire underneath it and see
    its own claim-scoped DELETE silently remove nothing.

    Single-node accounts are unaffected: the next GET re-claims the same rows
    (the claim predicate takes `claimed_by_bi=''`).
    """
    if table not in ("issue_inbox", "pull_inbox", "discussion_inbox"):
        return
    if not claimant_bi or not repo_bi:
        return
    await d1_run(
        env,
        "UPDATE %s SET claimed_by_bi='', claim_expires_at=0 "
        "WHERE repo_bi=? AND claimed_by_bi=?" % table,
        repo_bi, claimant_bi,
    )


async def _record_mirror_attested_state(env, request, owner, repo, mirror_node):
    """Admit the refs state an intake mirror serves after merging submissions.

    A mirror that just committed web submissions onto the branch it serves now
    advertises a refs fingerprint the source never attested, and
    clone_state_pins would drop it (and every peer that converges on it) from
    the read fan-out while the source is offline. A drain ack therefore
    carries the mirror's fresh self-attestation — state/stateTs/stateSig over
    the same forkmesh-repostate-v1 canonical it signs on its own catalog
    publishes — and after the signature and freshness checks the digest joins
    the repo's accepted pin history exactly like a source publish would. Only
    callers that already passed _authorized_mirror_issue_signing_key reach
    this, so the grant stays bounded to the repo's approved, healthy mirror
    group. Best-effort: a malformed attestation never fails the drain that
    carried it.
    """
    try:
        params = parse_qs(urlparse(request.url).query)
        digest = clean_string(
            params.get("state", [""])[0], 64).strip().lower()
        ts = params.get("stateTs", [""])[0]
        sig = params.get("stateSig", [""])[0]
        if not re.fullmatch(r"[0-9a-f]{64}", digest) or not ts or not sig:
            return False
        try:
            if abs(int(Date.now()) - int(ts)) > LOGIN_MAX_SKEW_MS:
                return False
        except (TypeError, ValueError):
            return False
        canonical = (
            "forkmesh-repostate-v1\n" + mirror_node + "\n" + repo + "\n"
            + digest + "\n" + ts
        ).encode()
        verified = False
        for public_key in await _claimed_node_signing_pubkeys(env, mirror_node):
            if await ed25519_verify(public_key, sig, canonical):
                verified = True
                break
        if not verified:
            return False
        # Drain routes arrive under the public organization alias
        # (/api/repo/forkmesh/forkmesh/...), but every consumer of this
        # history — clone_state_pins and _https_mirror_accepted_forkmesh_refs
        # — reads it under the backing node's namespace. Writing under the
        # alias dead-letters the attestation: recorded, yet invisible to
        # acceptance, so the fleet lived on the two-endpoint quorum alone and
        # one diverged intake took serving down (2026-08-19).
        host_owner = clean_string(
            await _org_repo_node(env, owner, repo) or "", MAX_NODE_NAME)
        key_bi = await blind_index(env, (host_owner or owner) + "/" + repo)
        await d1_run(
            env,
            "INSERT INTO repo_state_history (key_bi, state_hash, ts) "
            "VALUES (?,?,?) ON CONFLICT(key_bi, state_hash) "
            "DO UPDATE SET ts=excluded.ts",
            key_bi, digest, int(Date.now()),
        )
        await d1_run(
            env,
            "DELETE FROM repo_state_history WHERE key_bi=? "
            "AND state_hash NOT IN (SELECT state_hash FROM "
            "repo_state_history WHERE key_bi=? ORDER BY ts DESC LIMIT ?)",
            key_bi, key_bi, STATE_PIN_HISTORY,
        )
        return True
    except Exception:
        return False


async def _rekey_alias_inbox(env, alias_owner, host_owner, repo, repo_bi):
    """Move issue/pull/discussion inbox rows off an organization alias's blind
    index and onto the backing node's key, where every drain actually reads.

    Same recovery as _forkbot_rekey_alias_inbox, across all three queues: no
    drain path ever looks at the alias key, so a row written there is stranded.
    Idempotent (the alias key ends up empty) and best-effort — a hiccup here
    must never fail the submission that triggered it. The stored items carry no
    owner binding, so re-keying them is a pure routing fix."""
    if not host_owner or host_owner == alias_owner:
        return
    try:
        alias_bi = await blind_index(env, alias_owner + "/" + repo)
        if not alias_bi or alias_bi == repo_bi:
            return
        for table in ("issue_inbox", "pull_inbox", "discussion_inbox"):
            await d1_run(
                env,
                "UPDATE %s SET repo_bi=? WHERE repo_bi=?" % table,
                repo_bi, alias_bi)
    except Exception:
        pass


def _event_signing_repo_keys(request, owner, repo):
    url = str(getattr(request, "url", "") or "")
    original = REPO_API_PREFIX_RE.match(urlparse(url).path)
    public_owner = safe_segment(unquote(original.group(1))) if original else ""
    return event_signing_repo_keys((public_owner, repo), (owner, repo))


async def _inbox_repo_key(env, request, owner, repo):
    """Resolve the drain key, failing retryably on an unresolved org alias."""
    original = REPO_API_PREFIX_RE.match(urlparse(request.url).path)
    public_owner = str(
        safe_segment(original.group(1)) if original else "").lower()
    owner_l = str(owner or "").lower()
    if public_owner and public_owner != owner_l:
        # The rewrite already resolved this alias; `owner` is the backing node.
        # Both names are in hand here, which makes this the one cheap place to
        # sweep rows an earlier unrewritten request stranded on the alias key.
        repo_bi = await blind_index(env, owner + "/" + repo)
        await _recover_alias_inbox_once(
            env, public_owner, owner_l, repo, repo_bi)
        return repo_bi
    # Unrewritten: either a plain node URL (resolves to "", the common case and
    # a per-isolate memo hit) or an alias the rewrite failed to resolve.
    try:
        node = await _org_repo_node_strict(env, owner, repo)
    except Exception as exc:
        raise _OrgAliasUnresolved(str(exc))
    host_owner = node or owner
    repo_bi = await blind_index(env, host_owner + "/" + repo)
    if node:
        await _recover_alias_inbox_once(env, owner_l, node, repo, repo_bi)
    return repo_bi


async def _recover_alias_inbox_once(env, alias_owner, host_owner, repo,
                                    repo_bi):
    """Run at most one alias->host inbox sweep per repo per isolate."""
    if not alias_owner or not host_owner or alias_owner == host_owner:
        return
    if not repo_bi or repo_bi in _ALIAS_INBOX_REKEYED:
        return
    if len(_ALIAS_INBOX_REKEYED) >= ALIAS_INBOX_REKEY_MAX:
        _ALIAS_INBOX_REKEYED.clear()
    _ALIAS_INBOX_REKEYED[repo_bi] = True
    await _rekey_alias_inbox(env, alias_owner, host_owner, repo, repo_bi)


async def _drain_issue_inbox(env, request, repo_bi, claimant_bi=""):
    """Ack (delete) the exact issue-inbox rows named by ?ids=, returning how many
    were removed, and record the drain in inbox_drain_log. Rows the node did not
    ack (including a submission that arrived after it read the queue) are left
    for the next sync; a request with no ids removes nothing (adhoc #97)."""
    ids = _drain_ids_from_request(request)
    if not ids:
        return 0
    marks = ",".join("?" for _ in ids)
    claim_clause = " AND claimed_by_bi=?" if claimant_bi else ""
    args = (repo_bi, *ids, *([claimant_bi] if claimant_bi else []))
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=? "
        "AND id IN (%s)" % marks + claim_clause,
        *args)
    removed = int(row.get("c", 0)) if row else 0
    if claimant_bi:
        await d1_run(
            env,
            "DELETE FROM issue_inbox WHERE repo_bi=? AND id IN (%s) "
            "AND claimed_by_bi=?" % marks,
            *args)
    else:
        await d1_run(
            env,
            "DELETE FROM issue_inbox WHERE repo_bi=? AND id IN (%s)" % marks,
            repo_bi, *ids)
    await _log_inbox_drain(env, repo_bi, "issues", removed)
    return removed


async def _confirm_fediverse_issue_materializations(env, request):
    """Apply bounded owner-node confirmations carried by a signed inbox ack."""
    values = parse_qs(urlparse(request.url).query).get("materialized", [""])
    raw = values[0] if values else ""
    runtime = _WorldCommunityRuntime(env, request)
    confirmed = 0
    for value in str(raw or "").split(",")[:MAX_PENDING_PER_AUTHOR]:
        mention_id, separator, number_text = value.partition(":")
        if (
            not separator
            or not re.fullmatch(r"[a-f0-9]{32}", mention_id)
        ):
            continue
        try:
            number = int(number_text)
        except (TypeError, ValueError):
            continue
        if number <= 0:
            continue
        if await fediverse_mentions_api.confirm_materialized(
            runtime, mention_id, number
        ):
            confirmed += 1
    return confirmed


async def _queued_issue_inbox_event(env, repo_bi, submitter_bi, event):
    """The pending inbox item already holding this exact signed event, if any.

    Only the submitter's own rows can match, and _inbox_author_over_quota caps
    those at MAX_PENDING_PER_AUTHOR, so the scan stays small. A lookup failure
    answers None: the submission proceeds exactly as it did before the check.
    """
    sig = str(event.get("sig", "") or "")
    if not submitter_bi or not sig:
        return None
    try:
        rows = await d1_all(
            env,
            "SELECT data FROM issue_inbox WHERE repo_bi=? AND submitter_bi=? "
            "ORDER BY id DESC LIMIT ?",
            repo_bi, submitter_bi, MAX_PENDING_PER_AUTHOR,
        )
        for row in rows or []:
            rec = await decrypt_row(env, row.get("data"))
            queued = rec.get("event") if isinstance(rec, dict) else None
            if isinstance(queued, dict) and queued.get("sig") == sig:
                return rec
    except Exception:
        return None
    return None


async def _accept_issue_submission(env, request, owner, repo, repo_bi, data,
                                   repo_keys, actions_job=False):
    event = data.get("event")
    if not isinstance(event, dict):
        return json_response({"error": "event_required"}, status=400)
    event_type = clean_string(event.get("type", ""), 32)
    try:
        number = int(data.get("number", 0))
    except (TypeError, ValueError):
        number = 0
    if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
        return json_response({"error": "issue_too_large"}, status=413)
    if not await verify_issue_event(number, event, repo_keys):
        return json_response({"error": "bad_signature"}, status=401)
    if actions_job:
        event["authorVerified"] = True
    else:
        refused = await _bind_session_author(env, request, data, event)
        if refused is not None:
            return refused
    submitter_bi = await blind_index(env, event.get("author", ""))
    # Clients replay the SAME signed event when an attempt dropped its
    # response (issue #698: an accepted issue whose side effects outlived
    # the connection). Answer that replay with the row it already made
    # instead of reserving a second number and queuing the event twice —
    # otherwise the submitter is sent to a number that never materializes.
    queued = await _queued_issue_inbox_event(
        env, repo_bi, submitter_bi, event)
    if queued is not None:
        return json_response(
            {"ok": True, "number": queued.get("number", number)},
            status=201)
    signed_number = number
    if event_type == "open":
        reserved = await _forkbot_next_issue_number(
            env, repo_bi, owner, repo, "issue")
        # A desktop submission may already carry a usable proposal. A web
        # open is signed against 0 and needs the relay reservation so the
        # response can link directly to the issue it just accepted.
        if reserved > 0:
            number = reserved
        elif number <= 0:
            return json_response(
                {"error": "number_unavailable"}, status=503)
    # Match the Qt client's write boundary: visitors can open, comment and
    # vote, while edits to repository-owned issue state require the source
    # node owner (or a network admin). A browser signature proves event
    # integrity, not repository authority, so structural actions also carry
    # and validate the logged-in account session.
    owner_event_types = {
        "edit", "title", "status", "labels", "milestone", "dates",
        "priority", "progress", "bounty", "assignees", "agent", "delete",
    }
    if event_type in owner_event_types and not actions_job:
        ok, err = await _authorize_issue_manager(env, owner, data, request)
        if not ok:
            return err
    # Self-assignment (issue #570) is the one assignment a public
    # contributor may make: a "claim" names exactly one account and moves
    # only that name on or off the list, so it needs no repository
    # authority — only proof that the caller IS the account being claimed.
    if event_type == "claim" and not actions_job:
        ok, err = await _authorize_issue_self_claim(env, data, request, event)
        if not ok:
            return err
    # Screenshots the submitter had no working tree to copy in ride along as
    # base64 bytes, named to match the signed event's attachments list.
    attachment_data, attach_err = _clean_issue_attachment_data(
        data.get("attachmentData"))
    if attach_err:
        status = 413 if attach_err in (
            "too_many_attachments", "attachment_too_large") else 400
        return json_response({"error": attach_err}, status=status)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi
    )
    if count and count.get("c", 0) >= MAX_PENDING_ISSUES:
        return json_response({"error": "inbox_full"}, status=429)
    if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
        return json_response({"error": "author_quota"}, status=429)
    # Issue-level metadata for a new issue (labels/milestone/priority/
    # assignees). Not signature-bound; the owner applies it on merge. Bounded
    # to keep a submission small and the lists sane.
    meta_in = data.get("meta")
    meta = {}
    if isinstance(meta_in, dict):
        labels = meta_in.get("labels")
        assignees = meta_in.get("assignees")
        try:
            priority = int(meta_in.get("priority", 0))
        except (TypeError, ValueError):
            priority = 0
        # "wantsAgent" makes the owner's node start a coding agent on this
        # issue automatically once merged — unlike the other meta fields
        # above, that's an immediate, unreviewed side effect, so it's only
        # honored when the request comes from a privileged account: the repo
        # owner, or an admin acting on the owner's behalf (adhoc #225).
        wants_agent = False
        agent_model = ""
        agent_provider = ""
        if meta_in.get("wantsAgent"):
            ok, err = await _authorize_owner_account(env, owner, data, request)
            if not ok:
                return err
            wants_agent = True
            # Optional model choice (e.g. "opus"/"sonnet"/"haiku"/"fable" or a
            # full model id) for the agent the desktop node auto-starts on this
            # issue; empty leaves the provider's own default. Only meaningful
            # alongside wantsAgent, so it's not parsed otherwise.
            agent_model = clean_string(meta_in.get("model", ""), 60)
            # Optional agent-provider choice from the web dropdown (adhoc #234);
            # only a known provider is honored, else the node picks its default.
            provider_in = clean_string(meta_in.get("provider", ""), 40)
            if provider_in in (
                    "claude-code", "claude-api", "openai", "local-llama"):
                agent_provider = provider_in
        meta = {
            "labels": [clean_string(x, 60) for x in (labels or [])][:20]
            if isinstance(labels, list) else [],
            "milestone": clean_string(meta_in.get("milestone", ""), 120),
            "project": clean_string(meta_in.get("project", ""), 120),
            "priority": priority if 0 <= priority <= 99 else 0,
            "assignees": [clean_string(x, 60) for x in (assignees or [])][:20]
            if isinstance(assignees, list) else [],
            "wantsAgent": wants_agent,
            "model": agent_model,
            "provider": agent_provider,
        }
    item = {
        "number": number,
        "signedNumber": signed_number,
        "titleIfNew": clean_string(data.get("titleIfNew", ""), 240),
        "event": event,
        "meta": meta,
        "attachmentData": attachment_data,
        "submitter": clean_string(event.get("author", ""), 120),
        "submittedAt": int(Date.now()),
    }
    await d1_run(
        env,
        "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
        repo_bi, await encrypt_row(env, item), submitter_bi,
    )
    await _record_contributor(
        env, event.get("author", ""), "issues",
        event.get("authorName", ""))
    actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
    await _best_effort_inbox_side_effect(
        notify_pending_inbox(
            env, owner, repo, "issue", actor, item.get("titleIfNew", ""),
            number, opened=event_type == "open",
            text=(event.get("body", "")
                  if event_type in ("open", "comment") else "")))
    await _best_effort_inbox_side_effect(
        notify_mentions(
            env, owner, repo, actor, item.get("titleIfNew", ""),
            event.get("body", ""), repo_web_href(owner, repo), "issue",
            number=number))
    assignees = list(meta.get("assignees", [])) if isinstance(meta, dict) else []
    if isinstance(event.get("assignees"), list):
        assignees.extend(event.get("assignees"))
    if event_type == "claim" and event.get("claimState") == "assigned":
        claimed = clean_string(
            event.get("assignee", "") or "", MAX_NODE_NAME).strip().lower()
        if claimed and claimed != actor:
            assignees.append(claimed)
    await _best_effort_inbox_side_effect(
        notify_issue_assignees(
            env, owner, repo, assignees, actor, item.get("titleIfNew", ""),
            number))
    # Subscriptions (issue #361): tell everyone already following this issue
    # about the new activity, then auto-subscribe the commenter so they hear
    # about later replies. Both no-op for a brand-new issue (number 0).
    await _best_effort_inbox_side_effect(
        notify_subscribers(
            env, owner, repo, "issue", number, actor,
            item.get("titleIfNew", ""), event.get("body", ""),
            repo_web_href(owner, repo)))
    await _best_effort_inbox_side_effect(
        subscribe_thread(env, owner, repo, "issue", number, actor))
    if event_type == "comment" or (
            event_type == "status"
            and event.get("status") == "closed"):
        await _best_effort_inbox_side_effect(
            notify_account_event(env, owner, "issues"))
    await notify_repo_host(env, owner, repo, "issues")
    # An accepted inbox row is the durable boundary. The source wake is
    # one small call and stays inline for the fast materialization path;
    # the full mirror group fan-out is persisted by a doorbell so it never
    # makes a web submitter wait behind every connected mirror.
    await schedule_repo_mirror_wake(env, owner, repo, "issues")
    if event.get("type") in ("open", "comment"):
        emit_app = globals().get("apps_emit_repo_event")
        if emit_app is not None:
            await emit_app(
                env, owner, repo,
                "issue.opened" if event.get("type") == "open"
                else "issue.comment",
                {"number": number, "title": item.get("titleIfNew", ""),
                 "author": actor, "body": str(event.get("body", ""))[:2000]},
                source_actor=actor)
    # Fediverse: announce content events (opens/comments — never labels or
    # status flips) to any followers of the repo/author actors.
    if event.get("type") in ("open", "comment"):
        await _best_effort_inbox_side_effect(_ap_publish_repo_event(
            env, request, owner, repo, "issue", event.get("type"),
            number, item.get("titleIfNew", ""), event.get("body", ""),
            event.get("authorName", "")))
    await _best_effort_inbox_side_effect(_queue_issue_actions(
        env, owner, repo, number, event, item, actions_job))
    return json_response({"ok": True, "number": number}, status=201)


async def _queue_issue_actions(env, owner, repo, number, event, item,
                               actions_job=False):
    if actions_job or not str(
            getattr(env, "ACTIONS_INSTANCE_RUNNER", "") or "").strip():
        return []
    import actions_job_api
    actions_job_api._bind_runtime(globals())
    return await actions_job_api.queue_issue_event(
        env, owner, repo, number, event, item)


async def issues_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    try:
        repo_bi = await _inbox_repo_key(env, request, owner, repo)
    except _OrgAliasUnresolved:
        return json_response({"error": "alias_unresolved"}, status=503)
    if method == "POST":
        disabled = await _repo_feature_off(env, owner, repo, "issues")
        if disabled is not None:
            return disabled
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        return await _accept_issue_submission(
            env, request, owner, repo, repo_bi, data,
            _event_signing_repo_keys(request, owner, repo))

    if method == "GET":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        mirror_node = ""
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
        else:
            signing_key = await _authorized_repo_inbox_signing_key(
                env, request, owner, repo)
        if not signing_key:
            return json_response({"error": "unauthorized"}, status=401)
        claimant_bi = await _claim_issue_inbox(
            env, repo_bi, signing_key, mirror_only=mirror_intake)
        rows, more = await _leased_inbox_page(
            env, "issue_inbox", repo_bi, claimant_bi,
            mirror_only=mirror_intake)
        pending = []
        for r in rows:
            rec = await decrypt_row(env, r["data"])
            if rec:
                # The row id lets the node ack exactly what it merged so a
                # submission that lands mid-drain isn't swept away undelivered
                # (adhoc #97) — the "stayed pending, then vanished, never synced"
                # bug. A DELETE must name the ids to remove; without them the
                # drain removes nothing.
                rec["id"] = r.get("id")
                pending.append(rec)
        return json_response({
            "ok": True,
            "pending": pending,
            # A page, not the backlog: acknowledge these ids and poll again.
            "more": more,
            "mirrorIntake": mirror_intake,
            "mirror": mirror_node,
        })

    if method == "DELETE":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        mirror_node = ""
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
        else:
            signing_key = await _authorized_repo_inbox_signing_key(
                env, request, owner, repo)
        if not signing_key:
            return json_response({"error": "unauthorized"}, status=401)
        claimant_bi = await blind_index(
            env, "issue-inbox-claim:" + signing_key)
        if mirror_intake:
            drained = await _drain_issue_inbox_on_mirror(
                env, request, repo_bi, claimant_bi, mirror_node)
            if drained:
                await _record_mirror_attested_state(
                    env, request, owner, repo, mirror_node)
            return json_response({
                "ok": True,
                "drained": drained,
                "materialized": drained,
                "retainedForSource": False,
            })
        materialized = await _confirm_fediverse_issue_materializations(
            env, request)
        removed = await _drain_issue_inbox(
            env, request, repo_bi, claimant_bi)
        await _release_inbox_claim(
            env, "issue_inbox", repo_bi, claimant_bi)
        return json_response({
            "ok": True,
            "drained": removed,
            "materialized": materialized,
        })

    return json_response({"error": "method_not_allowed"}, status=405)


async def _record_pull_review(env, request, data, owner, repo, number, event):
    try:
        token, _cookie = _request_account_session_token(
            request, data if isinstance(data, dict) else {})
        if str(token or "").startswith("fmat_"):
            return
        _, reviewer_record = await _account_session_record(env, request, data)
        reviewer = clean_string(
            (reviewer_record or {}).get("name", ""), MAX_NODE_NAME
        ).strip().lower()
        if reviewer:
            await _branch_protection.record_review(
                env, owner, repo, number, reviewer,
                str(event.get("state") or ""))
    except Exception:
        pass


async def _bind_session_author(env, request, data, record, session=None):
    if not isinstance(record, dict):
        return None
    if session is None:
        try:
            _, rec = await _account_session_record(
                env, request, data, allow_unverified=True)
        except Exception:
            rec = None
        session = (rec or {}).get("name", "") if rec else ""
    session = clean_string(session or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(session):
        session = ""
    author = str(record.get("author", "") or "").strip()
    bound = ""
    if valid_node_pubkey(author):
        bound = clean_string(
            await _git_push_account_for_pubkey(env, author) or "",
            MAX_NODE_NAME).strip().lower()
    if session and bound and bound != session:
        return json_response({"error": "author_mismatch"}, status=403)
    name = session or bound
    record["authorName"] = name
    record["authorVerified"] = bool(name)
    return None


PULL_LIFECYCLE_RECORD_REFS = (
    "forkmesh/pull/{}", "refs/pr/{}/metadata", "forkmesh/pulls")
PULL_LIFECYCLE_FINAL_STATUSES = frozenset({"merged", "closed-merged", "deleted"})


async def _pull_lifecycle_record(env, owner, repo, number):
    for ref in PULL_LIFECYCLE_RECORD_REFS:
        try:
            data = await _forkbot_repo_gateway_json(
                env, owner, repo, "blob?path=%s&ref=%s" % (
                    quote(".forkmesh/pulls/%d/pull.md" % int(number), safe=""),
                    quote(ref.format(int(number)), safe="")))
            fields = microjobs.parse_pull_frontmatter(
                _forkbot_blob_text(data) if data else "")
        except Exception:
            fields = {}
        if str(fields.get("number") or "").strip() == str(int(number)):
            return fields
    return {}


async def _authorize_pull_lifecycle(env, owner, repo, number, data, request,
                                    event):
    record = await _pull_lifecycle_record(env, owner, repo, number)
    if not record:
        return False, json_response(
            {"error": "pull_unavailable"}, status=503), ""
    status = str(record.get("status") or "open").strip().lower()
    if status in PULL_LIFECYCLE_FINAL_STATUSES:
        return False, json_response({"error": "pull_final"}, status=409), ""
    _, rec = await _account_session_record(env, request, data)
    actor = clean_string(
        rec.get("name", "") if rec else "", MAX_NODE_NAME
    ).strip().lower()
    manager, _ = await _authorize_issue_manager(env, owner, data, request)
    if manager:
        return True, None, actor
    pull_key = str(record.get("author") or "").strip()
    if pull_key and str(event.get("author") or "").strip() == pull_key:
        return True, None, actor
    if actor:
        pull_name = clean_string(
            record.get("authorName") or "", MAX_NODE_NAME).strip().lower()
        if pull_name and pull_name == actor:
            return True, None, actor
        if pull_key and valid_node_pubkey(pull_key):
            owner_name = clean_string(
                await _git_push_account_for_pubkey(env, pull_key) or "",
                MAX_NODE_NAME).strip().lower()
            if owner_name and owner_name == actor:
                return True, None, actor
    return False, json_response({"error": "not_authorized"}, status=403), ""


async def pulls_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    try:
        repo_bi = await _inbox_repo_key(env, request, owner, repo)
    except _OrgAliasUnresolved:
        return json_response({"error": "alias_unresolved"}, status=503)
    if method == "POST":
        disabled = await _repo_feature_off(env, owner, repo, "pulls")
        if disabled is not None:
            return disabled
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        # A submission is either a whole new PR ("pull") or a signed conversation
        # event ("event" + "number") — a comment or review on an existing PR.
        event = data.get("event")
        branch = data.get("branch")
        if isinstance(event, dict) and branch is not None:
            if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
                return json_response({"error": "event_too_large"}, status=413)
            if not await verify_branch_comment_event(
                    branch, event,
                    _event_signing_repo_keys(request, owner, repo)):
                return json_response({"error": "bad_signature"}, status=401)
            refused = await _bind_session_author(env, request, data, event)
            if refused is not None:
                return refused
            count = await d1_first(
                env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
            )
            if count and count.get("c", 0) >= MAX_PENDING_PULLS:
                return json_response({"error": "inbox_full"}, status=429)
            submitter_bi = await blind_index(env, event.get("author", ""))
            if await _inbox_author_over_quota(
                    env, "pull_inbox", repo_bi, submitter_bi):
                return json_response({"error": "author_quota"}, status=429)
            item = {
                "number": 0,
                "branch": branch,
                "event": event,
                "submitter": clean_string(event.get("author", ""), 120),
                "submittedAt": int(Date.now()),
            }
            await d1_run(
                env,
                "INSERT INTO pull_inbox (repo_bi, data, submitter_bi) "
                "VALUES (?,?,?)",
                repo_bi, await encrypt_row(env, item), submitter_bi,
            )
            await _record_contributor(
                env, event.get("author", ""), "pulls",
                event.get("authorName", ""))
            await notify_repo_host(env, owner, repo, "pulls")
            await notify_repo_mirrors(env, owner, repo, "pulls")
            return json_response({"ok": True}, status=201)
        if isinstance(event, dict):
            try:
                number = int(data.get("number", 0))
            except (TypeError, ValueError):
                number = 0
            if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
                return json_response({"error": "event_too_large"}, status=413)
            if not await verify_pull_comment_event(
                    number, event,
                    _event_signing_repo_keys(request, owner, repo)):
                return json_response({"error": "bad_signature"}, status=401)
            if event.get("type") in ("status", "delete"):
                allowed, refusal, _lifecycle_actor = (
                    await _authorize_pull_lifecycle(
                        env, owner, repo, number, data, request, event))
                if not allowed:
                    return refusal
            refused = await _bind_session_author(env, request, data, event)
            if refused is not None:
                return refused
            count = await d1_first(
                env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
            )
            if count and count.get("c", 0) >= MAX_PENDING_PULLS:
                return json_response({"error": "inbox_full"}, status=429)
            submitter_bi = await blind_index(env, event.get("author", ""))
            if await _inbox_author_over_quota(
                    env, "pull_inbox", repo_bi, submitter_bi):
                return json_response({"error": "author_quota"}, status=429)
            item = {
                "number": number,
                "event": event,
                "submitter": clean_string(event.get("author", ""), 120),
                "submittedAt": int(Date.now()),
            }
            await d1_run(
                env,
                "INSERT INTO pull_inbox (repo_bi, data, submitter_bi) "
                "VALUES (?,?,?)",
                repo_bi, await encrypt_row(env, item), submitter_bi,
            )
            await _record_contributor(
                env, event.get("author", ""), "pulls",
                event.get("authorName", ""))
            if event.get("type") == "review":
                await _record_pull_review(
                    env, request, data, owner, repo, number, event)
            actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
            await notify_pending_inbox(env, owner, repo, "pull", actor, "", number,
                                       text=event.get("body", ""))
            await notify_mentions(env, owner, repo, actor, "Pull request comment", event.get("body", ""),
                                  repo_web_href(owner, repo), "pull", number=number)
            # Subscriptions (issue #361): fan the comment out to the PR's
            # followers, then auto-subscribe the commenter.
            await notify_subscribers(env, owner, repo, "pull", number, actor,
                                     "", event.get("body", ""),
                                     repo_web_href(owner, repo))
            await subscribe_thread(env, owner, repo, "pull", number, actor)
            await notify_repo_host(env, owner, repo, "pulls")
            await notify_repo_mirrors(env, owner, repo, "pulls")
            emit_app = globals().get("apps_emit_repo_event")
            if emit_app is not None:
                await emit_app(
                    env, owner, repo, "pull.comment",
                    {"number": number, "author": actor,
                     "kind": str(event.get("type") or "comment"),
                     "body": str(event.get("body", ""))[:2000]},
                    source_actor=actor)
            if event.get("type") in ("comment", "review"):
                await _best_effort_inbox_side_effect(_ap_publish_repo_event(
                    env, request, owner, repo, "pull", event.get("type"),
                    number, "", event.get("body", ""),
                    event.get("authorName", "")))
            return json_response({"ok": True}, status=201)
        pull = data.get("pull")
        if not isinstance(pull, dict):
            return json_response({"error": "pull_required"}, status=400)
        signed_fields = ("title", "base", "head", "patch", "commits")
        if any(
                field in pull and not isinstance(pull.get(field), str)
                for field in signed_fields):
            return json_response({"error": "pull_invalid"}, status=400)
        description = (
            pull.get("description")
            if "description" in pull else pull.get("body", ""))
        if not isinstance(description, str):
            return json_response({"error": "pull_invalid"}, status=400)
        if len(description.encode("utf-8")) > MAX_ISSUE_BYTES:
            return json_response(
                {"error": "description_too_large"}, status=413)
        # `description` is the native Qt wire name. Normalize legacy browser
        # `body` submissions before encrypting the inbox item so either kind of
        # sender drains into the same lossless PullRequest representation.
        pull["description"] = description
        pull.pop("body", None)
        pull_bytes = len((pull.get("patch", "") or "").encode("utf-8")) + len(
            (pull.get("commits", "") or "").encode("utf-8"))
        if pull_bytes > MAX_PULL_BYTES:
            return json_response({"error": "pull_too_large"}, status=413)
        if not await verify_pull_event(
                pull, _event_signing_repo_keys(request, owner, repo)):
            return json_response({"error": "bad_signature"}, status=401)
        refused = await _bind_session_author(env, request, data, pull)
        if refused is not None:
            return refused
        submission_bi = await blind_index(
            env, "pull-submission:" + pull.get("author", "") + ":" +
            pull.get("sig", ""))
        receipt = await d1_first(
            env,
            "SELECT data FROM pull_submission_receipts "
            "WHERE repo_bi=? AND submission_bi=?",
            repo_bi, submission_bi)
        existing_receipt = {}
        existing_number = 0
        if receipt:
            stored_receipt = await decrypt_row(env, receipt.get("data"))
            try:
                existing_number = int((stored_receipt or {}).get("number", 0))
            except (TypeError, ValueError):
                existing_number = 0
            existing_receipt = stored_receipt or {}
            if existing_number > 0 and existing_receipt.get("queued"):
                return json_response(
                    {"ok": True, "number": existing_number,
                     "duplicate": True}, status=201)
        number = existing_number if existing_number > 0 else \
            await _forkbot_next_issue_number(env, repo_bi, owner, repo, "pull")
        if number <= 0:
            return json_response(
                {"error": "number_unavailable"}, status=503)
        # PullStore's signed canonical deliberately excludes the local record
        # number. Add the reserved slot only after signature verification so
        # every online mirror receives the same collision-safe proposal.
        pull["number"] = number
        if not existing_number:
            count = await d1_first(
                env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
            )
            if count and count.get("c", 0) >= MAX_PENDING_PULLS:
                return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, pull.get("author", ""))
        if (not existing_number and
                await _inbox_author_over_quota(env, "pull_inbox", repo_bi,
                                                submitter_bi)):
            return json_response({"error": "author_quota"}, status=429)
        item = {
            "number": number,
            "pull": pull,
            "submitter": clean_string(pull.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        if not existing_number:
            await d1_run(
                env,
                "INSERT OR IGNORE INTO pull_submission_receipts "
                "(repo_bi, submission_bi, data) VALUES (?,?,?)",
                repo_bi, submission_bi,
                await encrypt_row(env, {"number": number, "queued": False}),
            )
        receipt = await d1_first(
            env,
            "SELECT data FROM pull_submission_receipts "
            "WHERE repo_bi=? AND submission_bi=?",
            repo_bi, submission_bi)
        stored_receipt = await decrypt_row(env, receipt.get("data")) if receipt else {}
        try:
            receipt_number = int((stored_receipt or {}).get("number", 0))
        except (TypeError, ValueError):
            receipt_number = 0
        if receipt_number <= 0:
            return json_response({"error": "receipt_unavailable"}, status=503)
        if receipt_number != number:
            number = receipt_number
            existing_number = receipt_number
            pull["number"] = number
            item["number"] = number
            item["pull"] = pull
        await d1_run(
            env,
            "INSERT OR IGNORE INTO pull_inbox "
            "(repo_bi, data, submitter_bi, submission_bi) VALUES (?,?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi, submission_bi,
        )
        await d1_run(
            env,
            "UPDATE pull_submission_receipts SET data=? "
            "WHERE repo_bi=? AND submission_bi=?",
            await encrypt_row(env, {"number": number, "queued": True}),
            repo_bi, submission_bi,
        )
        if existing_number:
            return json_response(
                {"ok": True, "number": number, "duplicate": True}, status=201)
        await _record_contributor(
            env, pull.get("author", ""), "pulls",
            pull.get("authorName", ""))
        actor = clean_string(pull.get("authorName", "") or pull.get("author", ""), MAX_NODE_NAME).lower()
        title = clean_string(pull.get("title", "") or pull.get("subject", ""), 240)
        await notify_pending_inbox(
            env, owner, repo, "pull", actor, title, number, opened=True)
        await notify_mentions(env, owner, repo, actor, title, description,
                              repo_web_href(owner, repo), "pull", number=number)
        await notify_repo_host(env, owner, repo, "pulls")
        await notify_repo_mirrors(env, owner, repo, "pulls")
        emit_app = globals().get("apps_emit_repo_event")
        if emit_app is not None:
            await emit_app(
                env, owner, repo, "pull.opened",
                {"number": number, "title": title, "author": actor,
                 "body": str(description or "")[:2000]}, source_actor=actor)
        # Badge (adhoc #44): render the PR's visual fingerprint from the
        # signed patch and attach it to the federated note as its lead image.
        # Best-effort — a badge failure must never block the submission.
        badge = None
        try:
            stats = patch_file_stats(pull.get("patch", "") or "")
            if stats:
                png = pull_badge_png(
                    title, clean_string(
                        pull.get("authorName", "") or pull.get("author", ""),
                        MAX_NODE_NAME), stats)
                badge = {"mediaType": "image/png",
                         "data": base64.b64encode(png).decode("ascii")}
        except Exception:
            badge = None
        await _best_effort_inbox_side_effect(_ap_publish_repo_event(
            env, request, owner, repo, "pull", "open", number, title,
            description, pull.get("authorName", ""),
            extra_images=[badge] if badge else None))
        # Attribution funnel: a submitted pull is the contribution step. It
        # arrives from a node, not a browser, so it is joined through the
        # session linked at signup; an unknown author records nothing. The
        # hook is optional at runtime (like _forget_repo_closed) so the
        # handler stays loadable in a bare namespace.
        attribution = globals().get("_attribution")
        actor_bi = await blind_index(env, actor) if actor else ""
        if actor_bi and attribution is not None:
            await attribution.emit_for_user(
                env, actor_bi, "contribution_made",
                {"repo": owner + "/" + repo, "number": number})
        # Hackathon builder points for the same event. The ledger key makes
        # one pull pay once however often this path runs.
        hackathon = globals().get("_hackathon")
        if actor_bi and hackathon is not None:
            try:
                await hackathon.on_pull_accepted(
                    env, actor_bi, "%s/%s#%s" % (owner, repo, number))
            except Exception:
                pass
        return json_response({"ok": True, "number": number}, status=201)

    if method == "GET":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        mirror_node = ""
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
            claimant_bi = await _claim_collaboration_inbox_on_mirror(
                env, "pull_inbox", repo_bi, signing_key)
            if not claimant_bi:
                return json_response({"error": "unauthorized"}, status=401)
            rows, more = await _leased_inbox_page(
                env, "pull_inbox", repo_bi, claimant_bi, mirror_only=True)
        else:
            signing_key = await _authorized_repo_inbox_signing_key(
                env, request, owner, repo)
            claimant_bi = await _claim_collaboration_inbox_on_mirror(
                env, "pull_inbox", repo_bi, signing_key)
            if not claimant_bi:
                return json_response({"error": "unauthorized"}, status=401)
            rows, more = await _leased_inbox_page(
                env, "pull_inbox", repo_bi, claimant_bi)
        pending = []
        for row in rows:
            rec = await decrypt_row(env, row["data"])
            if rec:
                rec["id"] = row.get("id")
                pending.append(rec)
        return json_response({
            "ok": True,
            "pending": pending,
            # A page, not the backlog: acknowledge these ids and poll again.
            "more": more,
            "mirrorIntake": mirror_intake,
            "mirror": mirror_node,
        })

    if method == "DELETE":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
            claimant_bi = await blind_index(
                env, "collaboration-inbox-claim:pull_inbox:" + signing_key
            ) if signing_key else ""
            if not claimant_bi:
                return json_response({"error": "unauthorized"}, status=401)
            drained = await _drain_collaboration_inbox_on_mirror(
                env, request, "pull_inbox", repo_bi, claimant_bi,
                mirror_node)
            if drained:
                await _record_mirror_attested_state(
                    env, request, owner, repo, mirror_node)
            return json_response({
                "ok": True,
                "drained": drained,
                "materialized": drained,
                "retainedForSource": False,
            })
        signing_key = await _authorized_repo_inbox_signing_key(
            env, request, owner, repo)
        claimant_bi = await blind_index(
            env, "collaboration-inbox-claim:pull_inbox:" + signing_key
        ) if signing_key else ""
        if not claimant_bi:
            return json_response({"error": "unauthorized"}, status=401)
        drained = await _drain_collaboration_inbox_on_mirror(
            env, request, "pull_inbox", repo_bi, claimant_bi, "source")
        await _release_inbox_claim(
            env, "pull_inbox", repo_bi, claimant_bi)
        return json_response({"ok": True, "drained": drained})

    return json_response({"error": "method_not_allowed"}, status=405)


async def _discussion_answer_by_owner(env, request, data, owner, repo):
    try:
        ok, _ = await _authorize_owner_account(
            env, owner, data, request, allow_admin=False)
        if ok:
            return True
        _, rec = await _account_session_record(env, request, data)
        actor = clean_string(
            (rec or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
        return await _org_owner_of_linked_repo(env, owner, repo, actor)
    except Exception:
        return False


async def discussions_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    try:
        repo_bi = await _inbox_repo_key(env, request, owner, repo)
    except _OrgAliasUnresolved:
        return json_response({"error": "alias_unresolved"}, status=503)
    if method == "POST":
        disabled = await _repo_feature_off(env, owner, repo, "discussions")
        if disabled is not None:
            return disabled
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        event = data.get("event")
        if not isinstance(event, dict):
            return json_response({"error": "event_required"}, status=400)
        try:
            number = int(data.get("number", 0))
        except (TypeError, ValueError):
            number = 0
        if event.get("type", "") == "open":
            number = 0
        if len(discussion_event_content(event).encode("utf-8")) > MAX_DISCUSSION_BYTES:
            return json_response({"error": "discussion_too_large"}, status=413)
        if not await verify_discussion_event(
                number, event,
                _event_signing_repo_keys(request, owner, repo)):
            return json_response({"error": "bad_signature"}, status=401)
        refused = await _bind_session_author(env, request, data, event)
        if refused is not None:
            return refused
        count = await d1_first(
            env, "SELECT COUNT(*) AS c FROM discussion_inbox WHERE repo_bi=?", repo_bi
        )
        if count and count.get("c", 0) >= MAX_PENDING_DISCUSSIONS:
            return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, event.get("author", ""))
        if await _inbox_author_over_quota(
                env, "discussion_inbox", repo_bi, submitter_bi):
            return json_response({"error": "author_quota"}, status=429)
        item = {
            "number": number,
            "titleIfNew": clean_string(data.get("titleIfNew", ""), 240),
            "event": event,
            "submitter": clean_string(event.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        if event.get("type") == "answer" and await _discussion_answer_by_owner(
                env, request, data, owner, repo):
            item["meta"] = {"ownerApproved": True}
        await d1_run(
            env,
            "INSERT INTO discussion_inbox (repo_bi, data, submitter_bi) "
            "VALUES (?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi,
        )
        actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
        title = item.get("titleIfNew", "") or "Discussion update"
        await notify_pending_inbox(env, owner, repo, "discussion", actor, title, number)
        await notify_mentions(env, owner, repo, actor, title, event.get("body", ""),
                              repo_web_href(owner, repo), "discussion", number=number)
        await notify_repo_host(env, owner, repo, "discussions")
        await notify_repo_mirrors(env, owner, repo, "discussions")
        if event.get("type") == "open":
            await provider_mirror_note_event(
                env, owner, repo, "discussion.opened",
                {"number": 0, "title": item.get("titleIfNew", ""),
                 "author": actor, "body": str(event.get("body", ""))})
        if event.get("type") in ("open", "comment"):
            await _best_effort_inbox_side_effect(_ap_publish_repo_event(
                env, request, owner, repo, "discussion", event.get("type"),
                number, item.get("titleIfNew", ""), event.get("body", ""),
                event.get("authorName", "")))
        if event.get("type") in ("open", "comment"):
            await _record_contributor(
                env, event.get("author", ""), "discussions",
                event.get("authorName", ""))
        return json_response({"ok": True}, status=201)

    if method == "GET":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        mirror_node = ""
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
            deferred = await _deferred_mirror_intake(
                env, owner, repo, signing_key, mirror_node)
            if deferred:
                return deferred
            claimant_bi = await _claim_collaboration_inbox_on_mirror(
                env, "discussion_inbox", repo_bi, signing_key)
            if not claimant_bi:
                return json_response({"error": "unauthorized"}, status=401)
            rows, more = await _leased_inbox_page(
                env, "discussion_inbox", repo_bi, claimant_bi,
                mirror_only=True)
        else:
            signing_key = await _authorized_repo_inbox_signing_key(
                env, request, owner, repo)
            # Lease the rows to THIS signing key before handing them over, the
            # same shape pulls_handler already uses. Without a lease the ack
            # below has nothing to scope its DELETE to, which is how the drain
            # ended up blanket-deleting the repo's whole discussion queue.
            claimant_bi = await _claim_collaboration_inbox_on_mirror(
                env, "discussion_inbox", repo_bi, signing_key)
            if not claimant_bi:
                return json_response({"error": "unauthorized"}, status=401)
            rows, more = await _leased_inbox_page(
                env, "discussion_inbox", repo_bi, claimant_bi)
        pending = []
        for row in rows:
            rec = await decrypt_row(env, row["data"])
            if rec:
                rec["id"] = row.get("id")
                pending.append(rec)
        return json_response({
            "ok": True,
            "pending": pending,
            # A page, not the backlog: acknowledge these ids and poll again.
            "more": more,
            "mirrorIntake": mirror_intake,
            "mirror": mirror_node,
        })

    if method == "DELETE":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
            claimant_bi = await blind_index(
                env,
                "collaboration-inbox-claim:discussion_inbox:" + signing_key,
            ) if signing_key else ""
            if not claimant_bi:
                return json_response({"error": "unauthorized"}, status=401)
            drained = await _drain_collaboration_inbox_on_mirror(
                env, request, "discussion_inbox", repo_bi, claimant_bi,
                mirror_node)
            if drained:
                await _record_mirror_attested_state(
                    env, request, owner, repo, mirror_node)
            return json_response({
                "ok": True,
                "drained": drained,
                "materialized": drained,
                "retainedForSource": False,
            })
        # Source ack. Historically this branch called an undefined
        # `_authorize_repo_inbox_signing_key` and then blanket-deleted every
        # row for the repo: the NameError made the ack a 500 (so the queue
        # never drained at all), and the delete it guarded would have destroyed
        # submissions that landed mid-drain. Both are replaced by the exact
        # leased, id-scoped shape pulls_handler uses — the desktop already
        # sends `?ids=` here (MainWindow::applyDiscussionsInboxPayload), so an
        # ack with no ids removes nothing, same as issues/pulls (adhoc #97).
        signing_key = await _authorized_repo_inbox_signing_key(
            env, request, owner, repo)
        claimant_bi = await blind_index(
            env, "collaboration-inbox-claim:discussion_inbox:" + signing_key
        ) if signing_key else ""
        if not claimant_bi:
            return json_response({"error": "unauthorized"}, status=401)
        drained = await _drain_collaboration_inbox_on_mirror(
            env, request, "discussion_inbox", repo_bi, claimant_bi, "source")
        await _release_inbox_claim(
            env, "discussion_inbox", repo_bi, claimant_bi)
        return json_response({"ok": True, "drained": drained})

    return json_response({"error": "method_not_allowed"}, status=405)


async def repo_pending_counts_handler(env, request, owner, repo):
    # GET /api/repo/{owner}/{repo}/pending — content-free tallies of inbox
    # items still waiting for the owner node's next sync, so the website can
    # badge the Issues/Pulls/Discussions tabs with "N pending".
    # Public: the counts reveal only submission volume (submissions come from
    # the public anyway); the items themselves stay encrypted and owner-gated
    # behind the per-topic GET routes. One UNION round trip, edge-cacheable
    # briefly so repeated page views don't re-hit D1.
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    # Submission volume is still repository metadata. Private and unpublished
    # names return the same response and never expose whether inbox rows exist.
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    # The whole fleet polls these badges (plus every open repo page), so a
    # colo answers from its edge cache for ten minutes and a polling burst
    # collapses to one D1 UNION per colo per TTL. Ten minutes (not 30s)
    # because this was still the largest request group on the API traffic
    # chart at ~900/hour; a badge that lags a drain by minutes is fine,
    # since the drain itself is not instantaneous. Only the public 200 is cached — the
    # private/unpublished 404 above stays uncached and instant to reverse.
    pending_cache_key = (
        "https://edge-cache.forkmesh.internal/repo-pending/"
        + quote(owner) + "/" + quote(repo))
    cached = await edge_cache_match(pending_cache_key)
    if cached is not None:
        return cached
    await ensure_schema(env)
    # Count the SAME key the drains read (see _inbox_repo_key), or an aliased
    # repo's badge sticks at "N pending" forever against a queue the owner node
    # is never shown. Read-only resolution: no rekey from a public cached GET.
    repo_bi = await blind_index(
        env, (await _ap_org_alias_owner(env, owner, repo)) + "/" + repo)
    rows = await d1_all(
        env,
        "SELECT 'issues' AS k, COUNT(*) AS c FROM issue_inbox "
        "WHERE repo_bi=? AND mirrored_at=0 "
        "UNION ALL SELECT 'pulls', COUNT(*) FROM pull_inbox "
        "WHERE repo_bi=? AND mirrored_at=0 "
        "UNION ALL SELECT 'discussions', COUNT(*) FROM discussion_inbox "
        "WHERE repo_bi=? AND mirrored_at=0",
        repo_bi, repo_bi, repo_bi,
    )
    counts = {str(r.get("k") or ""): int(r.get("c") or 0) for r in rows or []}
    resp = json_response({
        "ok": True,
        "pending": {
            "issues": counts.get("issues", 0),
            "pulls": counts.get("pulls", 0),
            "discussions": counts.get("discussions", 0),
        },
    }, cache_control="public, max-age=600")
    await edge_cache_put(pending_cache_key, resp)
    return resp


