ORG_AGENT_MAX_SESSIONS = 50
ORG_AGENT_MAX_HISTORY = 80
ORG_AGENT_JOB_LEASE_MS = 2 * 60 * 1000


def _org_agent_error(
    code, message, status, *, retryable=False, required_action="",
    provider="", target_node="", degraded=False,
):
    payload = {
        "ok": False,
        "error": clean_string(code, 80),
        "message": clean_string(message, 500),
        "retryable": bool(retryable),
    }
    if required_action:
        payload["requiredAction"] = clean_string(required_action, 80)
    if provider:
        payload["provider"] = clean_string(provider, 40)
    if target_node:
        payload["targetNode"] = clean_string(target_node, MAX_NODE_NAME)
    return json_response(
        payload,
        status=status,
        cache_control="no-store",
        extra_headers=EXPECTED_DEGRADED_HEADERS if degraded else None,
    )


async def _org_agent_member_context(
        env, request, org, repo, data=None, owner_scope=False,
        signed_account=None, own_session=False):
    org = clean_string(org, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(org) or not safe_segment(repo):
        return None, _org_agent_error(
            "not_found",
            "The requested organization or repository was not found.",
            404,
        )
    if owner_scope:
        # A desktop that authenticated silently holds the account's key and no
        # session token. `signed_account` is what its user/ts/sig triple
        # resolved to, and once a triple is on the URL it is the only
        # credential considered: the handler waived the origin check for it, so
        # falling through to the cookie would let a cross-site request append a
        # junk signature and still act as the victim.
        if signed_account is not None:
            account_bi, account = signed_account
        else:
            account_bi, account = await _account_session_record(
                env, request, data if isinstance(data, dict) else None)
        actor = clean_string(
            (account or {}).get("name"), MAX_NODE_NAME).strip().lower()
        if not account_bi or not actor:
            return None, _org_agent_error(
                "invalid_session",
                "Sign in again before queueing an agent on an owned node.",
                401,
                required_action="sign_in",
            )
        owns_node = (
            await _account_owns_node(env, actor, org)
            or await _org_owner_of_linked_repo(env, org, repo, actor))
        if not owns_node and not own_session:
            return None, _org_agent_error(
                "forbidden",
                "Only this repository's owner can start agents on its nodes.",
                403,
                required_action="use_owner_account",
            )
        owned_nodes = set(await _profile_catalog_owner_names(env, actor))
        if owns_node:
            owned_nodes.add(org)
        return {
            "org": org,
            "orgBi": str(account_bi),
            "repo": repo,
            "nodeOwner": org,
            "accountBi": str(account_bi),
            "actor": actor,
            "role": "owner",
            "engineeringAccess": True,
            "accessBasis": "owner_nodes" if owns_node else "own_session",
            "scope": "owner",
            "ownedNodes": sorted(owned_nodes),
        }, None
    org_bi, org_row = await _org_row(env, org)
    if not org_row:
        return None, _org_agent_error(
            "not_found",
            "The requested organization or repository was not found.",
            404,
        )
    if signed_account is not None:
        account_bi, account = signed_account
    else:
        account_bi, account = await _account_session_record(
            env, request, data if isinstance(data, dict) else None)
    actor = clean_string(
        (account or {}).get("name"), MAX_NODE_NAME).strip().lower()
    if not account_bi or not actor:
        return None, _org_agent_error(
            "invalid_session",
            "Sign in again before queueing an organization agent.",
            401,
            required_action="sign_in",
        )
    role = await _org_role(env, org_bi, actor)
    # Reads (listing sessions, following a transcript) are open to every
    # insider role; queueing or steering an agent is a write that auditors
    # and guests never hold. Deny-by-default: an unknown role gets neither.
    if not _org_rbac.org_role_allows(
            role,
            "organization.agents.read" if method_name(request) == "GET"
            else "organization.agents.queue"):
        return None, _org_agent_error(
            "forbidden",
            "You must be a member of this organization to view agent work.",
            403,
            required_action="join_organization",
        )
    # Any team this organization uses as its Engineering team counts, exactly as
    # it does at the elevator: matching the single slug "engineering" locked out
    # members of a team named platform/developers/backend who already hold the
    # Engineering floor, so they saw none of the agent task work (adhoc #1668).
    is_engineering = bool(await _org_floor_team_rows(
        env, org_bi, "engineering", member_bi=str(account_bi)))
    if not is_engineering:
        response = _org_agent_error(
            "engineering_team_required",
            (
                "Only members of the Engineering team can view or queue "
                "repository agents. Organization owners must explicitly join "
                "Engineering before this encrypted workspace is decrypted."
            ),
            403,
            required_action="join_engineering_team",
        )
        return None, response
    linked = await d1_first(
        env,
        "SELECT node_owner FROM org_repos WHERE org_bi=? AND repo=?",
        org_bi, repo,
    )
    node_owner = clean_string(
        (linked or {}).get("node_owner"), MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node_owner):
        return None, _org_agent_error(
            "repository_not_linked",
            (
                "This repository is not linked to the organization. Link it "
                "to an owned desktop before queueing an agent."
            ),
            404,
            required_action="link_repository",
        )
    return {
        "org": org,
        "orgBi": org_bi,
        "repo": repo,
        "nodeOwner": node_owner,
        "accountBi": str(account_bi),
        "actor": actor,
        "role": role,
        "engineeringAccess": is_engineering,
        "accessBasis": "engineering_team",
        "scope": "organization",
    }, None


async def _org_agent_owner_targets(env, context):
    """Agent-capable copies of this repository owned by the signed-in actor.

    Owner commands are durable, so an owned desktop or managed node remains
    selectable while offline.  The catalog capability record is only the first
    gate: the chosen node must still prove ownership while claiming and must
    pass its local provider/login checks and tool-free safety preflight before
    execution.
    """
    if context.get("scope") != "owner":
        return []
    now = int(Date.now())
    rows = await _decrypted_public_catalog(env, now)
    records = [
        row.get("data") or {}
        for row in rows or []
        if not row.get("is_private")
    ]
    target = next((
        record for record in records
        if (
            str(record.get("owner") or "").strip().lower()
            == context["nodeOwner"]
            and str(record.get("name") or "").strip().lower()
            == context["repo"]
        )
    ), None)
    if not isinstance(target, dict):
        return []
    by_node = {}
    owned_nodes = {
        str(node or "").strip().lower()
        for node in context.get("ownedNodes", [])
    }
    for record in records:
        if not repo_mirror_same_group(target, record):
            continue
        node = (
            str(record.get("machineName") or "").strip()
            or str(record.get("owner") or "").strip()
        ).lower()
        if not valid_node_name(node):
            continue
        runtime = str(record.get("runtimeMode") or "").strip().lower()
        if runtime not in ("desktop", "headless"):
            continue
        if node not in owned_nodes:
            continue
        providers = sorted({
            str(value or "").strip().lower()
            for value in (
                record.get("agentProviders")
                if isinstance(record.get("agentProviders"), list) else []
            )
            if str(value or "").strip().lower() in ORG_AGENT_PROVIDERS
        })
        if not providers:
            continue
        try:
            seen_at = int(
                record.get("updatedAt") or record.get("lastSync") or 0)
        except (TypeError, ValueError):
            seen_at = 0
        candidate = {
            "node": node,
            "providers": providers,
            "online": bool(seen_at and now - seen_at <= 10 * 60 * 1000),
            "lastSeenAt": max(0, seen_at),
            "source": node == context["nodeOwner"],
            "runtimeMode": runtime,
        }
        current = by_node.get(node)
        if not current or candidate["lastSeenAt"] > current["lastSeenAt"]:
            by_node[node] = candidate
    pool_target = await _org_agent_pool_target(env, context, now)
    if pool_target and pool_target["node"] not in by_node:
        by_node[pool_target["node"]] = pool_target
    for personal in await _org_agent_personal_targets(env, context, now):
        if personal["node"] not in by_node:
            by_node[personal["node"]] = personal
    return sorted(
        by_node.values(),
        key=lambda item: (
            0 if item["online"] else 1,
            0 if item["source"] else 1,
            -item["lastSeenAt"],
            item["node"],
        ),
    )


def _org_agent_runner_status(row, owner, now):
    try:
        owners = json.loads(str(row.get("allowed_owners") or "[]"))
        availability = json.loads(str(row.get("data") or "{}"))
    except ValueError:
        return None
    if not isinstance(owners, list) or not isinstance(availability, dict):
        return None
    if owner not in {str(item or "").strip().lower() for item in owners}:
        return None
    import runner_auth
    name = str(row.get("name") or "").strip().lower()
    try:
        last_seen = int(row.get("last_seen_at") or 0)
    except (TypeError, ValueError):
        last_seen = 0
    ready = [
        provider for provider in ORG_AGENT_PROVIDERS
        if isinstance(availability.get(provider), dict)
        and availability[provider].get("loginState") == "available"
    ]
    blocked = [
        provider for provider in runner_auth.needs_login(availability)
        if provider in ORG_AGENT_PROVIDERS
    ]
    installed = [
        provider for provider in ORG_AGENT_PROVIDERS
        if isinstance(availability.get(provider), dict)
        and availability[provider].get("binaryFound") is not False
    ]
    return {
        "name": name,
        "scope": str(row.get("scope") or "pool"),
        "online": bool(last_seen and now - last_seen <= 10 * 60 * 1000),
        "lastSeenAt": max(0, last_seen),
        "ready": ready,
        "needsLogin": blocked,
        "signIn": [
            provider for provider in installed
            if provider not in ready and provider not in blocked
        ],
    }


def _org_agent_pool_node(env, context):
    node = str(context.get("nodeOwner") or "").strip().lower()
    owner = str(context.get("actor") or "").strip().lower()
    pool = {
        item.strip().lower()
        for item in str(
            getattr(env, "RUNNER_POOL_TARGET_NODES", "") or "").split(",")
        if item.strip()
    }
    if not node or not owner or node not in pool or not valid_node_name(node):
        return "", "", pool
    return node, owner, pool


async def _org_agent_pool_target(env, context, now):
    node, owner, pool = _org_agent_pool_node(env, context)
    if not node:
        return None
    try:
        rows = await d1_all(
            env,
            "SELECT n.name,n.scope,n.allowed_owners,n.last_seen_at,a.data "
            "FROM runner_nodes n LEFT JOIN runner_availability a "
            "ON a.runner=n.name WHERE n.status='active' AND n.scope='pool'",
        )
    except Exception:
        return None
    providers = set()
    seen_at = 0
    any_seen = 0
    runners = []
    statuses = []
    needs_login = {}
    for row in rows or []:
        status = _org_agent_runner_status(row, owner, now)
        if status is None:
            continue
        runner_name = status["name"]
        named = valid_node_name(runner_name)
        if named:
            statuses.append(status)
            for provider in status["needsLogin"]:
                needs_login.setdefault(provider, []).append(runner_name)
        any_seen = max(any_seen, status["lastSeenAt"])
        if not status["ready"]:
            continue
        providers.update(status["ready"])
        seen_at = max(seen_at, status["lastSeenAt"])
        if named and runner_name not in pool:
            runners.append((-status["lastSeenAt"], runner_name))
    for provider in list(needs_login):
        if provider in providers:
            del needs_login[provider]
        else:
            needs_login[provider] = sorted(set(needs_login[provider]))
    if not providers and not statuses:
        return None
    if not providers:
        seen_at = any_seen
    statuses.sort(key=lambda item: (
        0 if item["ready"] else 1, -item["lastSeenAt"], item["name"]))
    return {
        "node": min(runners)[1] if runners else node,
        "queueNode": node,
        "runner": (
            min(runners)[1] if runners
            else statuses[0]["name"] if statuses else ""),
        "runners": statuses,
        "providers": sorted(providers),
        "needsLogin": needs_login,
        "online": bool(seen_at and now - seen_at <= 10 * 60 * 1000),
        "lastSeenAt": max(0, seen_at),
        "source": True,
        "runtimeMode": "runner-pool",
    }


async def _org_agent_personal_targets(env, context, now):
    node, owner, pool = _org_agent_pool_node(env, context)
    if not node:
        return []
    try:
        rows = await d1_all(
            env,
            "SELECT n.name,n.scope,n.allowed_owners,n.last_seen_at,a.data "
            "FROM runner_nodes n LEFT JOIN runner_availability a "
            "ON a.runner=n.name WHERE n.status='active' "
            "AND n.scope='personal' AND n.registered_by=?",
            owner,
        )
    except Exception:
        return []
    targets = []
    for row in rows or []:
        status = _org_agent_runner_status(row, owner, now)
        if status is None:
            continue
        name = status["name"]
        if not valid_node_name(name) or name in pool:
            continue
        targets.append({
            "node": name,
            "queueNode": node,
            "runner": name,
            "runnerPin": name,
            "runners": [status],
            "providers": list(status["ready"]),
            "needsLogin": {
                provider: [name] for provider in status["needsLogin"]},
            "online": status["online"],
            "lastSeenAt": status["lastSeenAt"],
            "source": True,
            "runtimeMode": "runner-pool",
        })
    return targets


async def _org_agent_session_targets(env, context):
    """Return the exact nodes this member may select for a new session."""

    if context.get("scope") == "owner":
        return await _org_agent_owner_targets(env, context)
    now = int(Date.now())
    rows = await _decrypted_public_catalog(env, now)
    records = [
        row.get("data") or {}
        for row in rows or []
        if not row.get("is_private")
    ]
    source_node = context["nodeOwner"].lower()
    target = next((
        record for record in records
        if (
            str(record.get("owner") or "").strip().lower() == source_node
            and str(record.get("name") or "").strip().lower()
            == context["repo"].lower()
        )
    ), None)
    if not isinstance(target, dict):
        return []
    source_owned = await _account_owns_node(
        env, context["actor"], source_node)
    platform_admin = await _is_admin(env, context["actor"])
    by_node = {}

    def add_target(node, provider, *, online=True, source=False):
        node = str(node or "").strip().lower()
        if not valid_node_name(node):
            return
        item = by_node.setdefault(node, {
            "node": node,
            "providers": [],
            "online": bool(online),
            "source": bool(source),
        })
        if provider not in item["providers"]:
            item["providers"].append(provider)
            item["providers"].sort()

    for provider in ORG_AGENT_PROVIDERS:
        # Owners may address their linked desktop durably; a platform admin
        # may address it only while its signed capability lease is fresh. The
        # policy helper remains the source of truth for both cases.
        source_decision = agent_provider_target_decision(
            records,
            target,
            source_node,
            provider,
            now,
            10 * 60 * 1000,
            preferred_node=source_node,
            org_owner=context["role"] == "owner",
            source_owned=source_owned,
            platform_admin=platform_admin,
        )
        if source_decision.get("ok"):
            add_target(
                source_node,
                provider,
                online=source_decision.get("targetOnline") is True,
                source=True,
            )
        # The organization-owner policy deliberately pins work to the linked
        # desktop. Other Engineering members may choose any fresh same-repo
        # mirror that advertises the selected provider.
        if context["role"] == "owner":
            continue
        for node in agent_provider_mirror_candidates(
            records, target, source_node, provider, now, 10 * 60 * 1000,
        ):
            add_target(node, provider)
    return sorted(
        by_node.values(),
        key=lambda item: (
            0 if item["online"] else 1,
            0 if item["source"] else 1,
            item["node"],
        ),
    )


async def _org_agent_target_mirror(
    env, context, provider, preferred_node="",
):
    if context.get("scope") == "owner":
        targets = await _org_agent_owner_targets(env, context)
        preferred = clean_string(
            preferred_node, MAX_NODE_NAME).strip().lower()
        capable = [
            item for item in targets
            if provider in item.get("providers", [])
        ]
        if preferred:
            chosen = next(
                (item for item in capable if item["node"] == preferred), None)
            chosen = chosen or next(
                (item for item in capable
                 if item.get("queueNode") == preferred), None)
            if not chosen:
                import runner_auth
                blocked = runner_auth.submit_block([
                    item for item in targets
                    if preferred in (item.get("node"), item.get("queueNode"))
                ], provider)
                if blocked:
                    return blocked
                return {
                    "ok": False,
                    "error": "preferred_target_ineligible",
                    "message": (
                        "Select an agent-capable repository node owned by your "
                        "account that serves this repository."
                    ),
                    "requiredAction": "select_owned_agent_node",
                    "provider": provider,
                    "targetNode": preferred,
                }
        else:
            chosen = next((item for item in capable if item["online"]), None)
            chosen = chosen or (capable[0] if capable else None)
        if not chosen:
            import runner_auth
            blocked = runner_auth.submit_block(targets, provider)
            if blocked:
                return blocked
            return {
                "ok": False,
                "error": (
                    "repository_not_published"
                    if not targets else "provider_not_advertised"
                ),
                "message": (
                    "Open an owned ForkMesh node that serves this "
                    "repository, install the selected provider, complete its "
                    "CLI login, and wait for the node to publish its capability."
                ),
                "requiredAction": "publish_owned_agent_node",
                "provider": provider,
                "targetNode": preferred,
            }
        decision = {
            "ok": True,
            "targetNode": chosen.get("queueNode") or chosen["node"],
            "targetOnline": chosen["online"],
            "queueState": (
                "ready_for_claim" if chosen["online"]
                else "waiting_for_desktop"
            ),
            "route": "owner_node",
        }
        if chosen.get("runtimeMode") == "runner-pool":
            decision["route"] = "runner_pool"
            decision["runnerNode"] = chosen["node"]
            if chosen.get("runnerPin"):
                decision["runnerPin"] = chosen["runnerPin"]
            decision["runnerOwner"] = str(
                context.get("actor") or "").strip().lower()
        return decision
    now = int(Date.now())
    rows = await _decrypted_public_catalog(env, now)
    records = [
        row.get("data") or {}
        for row in rows or []
        if not row.get("is_private")
    ]
    target = next((
        record for record in records
        if (
            str(record.get("owner") or "").strip().lower()
            == context["nodeOwner"].lower()
            and str(record.get("name") or "").strip().lower()
            == context["repo"].lower()
        )
    ), None)
    source_node = context["nodeOwner"].lower()
    return agent_provider_target_decision(
        records,
        target,
        source_node,
        provider,
        now,
        10 * 60 * 1000,
        preferred_node=clean_string(
            preferred_node, MAX_NODE_NAME).strip().lower(),
        org_owner=context["role"] == "owner",
        source_owned=await _account_owns_node(
            env, context["actor"], source_node),
        platform_admin=await _is_admin(env, context["actor"]),
    )


def _org_agent_info_projection(value):
    value = value if isinstance(value, dict) else {}
    text_fields = {
        "owner": MAX_NODE_NAME,
        "repository": MAX_REPO_SEGMENT,
        "provider": 40,
        "model": 120,
        "mode": 80,
        "strength": 32,
        "status": 32,
        "branchName": 240,
        "baseRef": 64,
        "baseBranch": 240,
        "lastError": 1000,
    }
    output = {
        key: clean_string(value.get(key), maximum)
        for key, maximum in text_fields.items()
    }
    for key in (
        "issueNumber", "prNumber", "promptTokens", "completionTokens",
        "totalTokens", "contextTokens", "contextWindow", "maxOutputTokens",
        "estimatedCredits", "numTurns", "durationMs", "createdAt",
        "startedAt", "finishedAt", "mergedAt",
    ):
        try:
            number = int(value.get(key) or 0)
        except (TypeError, ValueError):
            number = 0
        output[key] = max(0, min(number, 2 ** 53 - 1))
    try:
        cost = float(value.get("costUsd") or 0)
    except (TypeError, ValueError):
        cost = 0
    output["costUsd"] = max(0, min(cost, 1_000_000))
    output["createPr"] = value.get("createPr") is True
    output["merged"] = value.get("merged") is True
    return output


def _org_agent_availability_projection(value):
    # No report yet (the job is still waiting for a node) is not a missing
    # runtime: an empty object keeps binaryFound absent rather than False.
    if not isinstance(value, dict) or not isinstance(
            value.get("binaryFound"), bool):
        return {}
    login_state = clean_string(value.get("loginState"), 20).lower()
    if login_state not in ("available", "missing", "unknown"):
        login_state = "unknown"
    return {
        "provider": clean_string(value.get("provider"), 40),
        "binaryFound": value.get("binaryFound") is True,
        "loginState": login_state,
        "message": clean_string(value.get("message"), 400),
        "credentialSource": clean_string(
            value.get("credentialSource"), 60),
    }


_org_agent_session_projection = _route_handlers.export("_org_agent_session_projection")


async def _org_agent_session_row(env, context, session_id):
    row = await d1_first(
        env,
        "SELECT session_id,org_bi,repo,target_node,provider,status,data,"
        "created_at,updated_at,completed_at FROM org_agent_sessions "
        "WHERE session_id=? AND org_bi=? AND repo=?",
        session_id, context["orgBi"], context["repo"],
    )
    if not row:
        return None, None
    record = await decrypt_row(env, row.get("data"))
    if (
        not isinstance(record, dict)
        or str(record.get("org") or "").lower() != context["org"]
        or str(record.get("repo") or "").lower() != context["repo"]
        or str(record.get("scope") or "organization")
            != context.get("scope", "organization")
    ):
        return None, None
    return row, record


