async def repo_org_agent_jobs_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) != "GET":
        return _org_agent_error(
            "method_not_allowed",
            "Use GET to claim the next organization-agent job.",
            405,
        )
    # Which device is asking, not merely whether somebody may: a session moved
    # into the cloud is queued into this same account's namespace, so without
    # the exact signer the desk that gave the session up would claim its own
    # handoff back on its very next poll and the move would be a no-op.
    claimant_key = await _authorized_agent_node_signing_key(
        env, request, owner)
    if not claimant_key:
        return _org_agent_error(
            "unauthorized",
            (
                "This node could not prove current ownership by its account. "
                "Re-link it to the account and try again."
            ),
            401,
            required_action="relink_desktop",
        )
    owner = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE org_agent_jobs SET status='queued',lease_id='',updated_at=? "
        "WHERE target_node=? AND repo=? AND status='leased' AND updated_at<?",
        now, owner, repo, now - ORG_AGENT_JOB_LEASE_MS,
    )
    jobs = []
    # Lease one FIFO item at a time. A second poll cannot pass the NOT EXISTS
    # guard while the first job is in its bounded preflight lease, and the
    # post-update read verifies the conditional queued->leased CAS before the
    # job is exposed. The client asks again immediately after reporting a
    # result, so this is backpressure, not an admission cap.
    # Jobs this claimant must not take (its own cloud handoffs). They stay
    # queued for another node; passing over them must not stall the FIFO.
    passed_over = []
    for _attempt in range(8):
        skip_clause = (
            " AND queued.id NOT IN (%s)" % ",".join("?" * len(passed_over))
            if passed_over else ""
        )
        row = await d1_first(
            env,
            "SELECT id,session_id,data FROM org_agent_jobs queued "
            "WHERE queued.target_node=? AND queued.repo=? "
            "AND queued.status='queued'" + skip_clause + " AND NOT EXISTS ("
            "SELECT 1 FROM org_agent_jobs active "
            "WHERE active.target_node=? AND active.repo=? "
            "AND active.status='leased') "
            "ORDER BY queued.id LIMIT 1",
            owner, repo, *passed_over, owner, repo,
        )
        if not row:
            break
        job_id = int(row.get("id") or 0)
        try:
            record = await decrypt_row(env, row.get("data"))
        except Exception:
            record = None
        if not job_id or not isinstance(record, dict):
            if job_id:
                await d1_run(
                    env,
                    "UPDATE org_agent_jobs SET status='failed',updated_at=? "
                    "WHERE id=? AND target_node=? AND status='queued'",
                    now, job_id, owner,
                )
            continue
        if record.get("fromKey") and record.get("fromKey") == claimant_key:
            # This is the device that moved the session into the cloud. Leave
            # the job queued and look past it, so another node can take it.
            passed_over.append(job_id)
            continue
        lease_id = _ap_uuid()
        await d1_run(
            env,
            "UPDATE org_agent_jobs SET status='leased',lease_id=?,updated_at=? "
            "WHERE id=? AND target_node=? AND status='queued'",
            lease_id, now, job_id, owner,
        )
        claimed = await d1_first(
            env,
            "SELECT id FROM org_agent_jobs WHERE id=? AND target_node=? "
            "AND repo=? AND status='leased' AND lease_id=?",
            job_id, owner, repo, lease_id,
        )
        if not claimed:
            break
        jobs.append({
            "jobId": job_id,
            "leaseId": lease_id,
            **record,
        })
        break
    return json_response({
        "ok": True,
        "jobs": jobs,
        "securityGate": "not-required",
    }, cache_control="no-store")


async def _agent_job_queued_by_signer(env, request, node, repo, row,
                                      organization):
    params = parse_qs(urlparse(request.url).query)
    signer = clean_string(
        params.get("owner", [""])[0], MAX_NODE_NAME).strip().lower()
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if (
        not valid_node_name(signer)
        or signer != organization
        or signer == node
    ):
        return False
    if str((row or {}).get("org_bi") or "") != str(
            await blind_index(env, signer)):
        return False
    if not (
        await _account_owns_node(env, signer, node)
        or await _org_owner_of_linked_repo(env, node, repo, signer)
    ):
        return False
    return bool(await _authorized_owner_signing_key(env, request, signer))


async def repo_owner_agent_session_claim_handler(
    env, request, owner, repo, session_id,
):
    """Hand one named queued session to the device asking for it.

    The FIFO drain above is a node taking whatever work is next. This is the
    other half of the same queue, read from the person's end: the desktop's
    Agents list shows the runs queued from the website, and "Continue on this
    desktop" claims *that* row -- the one being looked at -- however far down
    the queue it sits and whichever of the account's nodes it was aimed at.
    That last part is the point of the endpoint: the usual reason to take a
    run over by hand is that the mirror it was queued for is not claiming it.

    The job belongs to the account, not to the node named on it, so the claim
    is authorized exactly like the drain (the account's key, or the node key
    its owner claimed) and then checked against the account inside the
    encrypted job record. A granted claim re-targets the job and its session
    at that account namespace, which is where the claimant reports results
    from; without that the run could never report, because the result route
    matches the lease by target node.
    """
    await ensure_schema(env)
    if method_name(request) != "POST":
        return _org_agent_error(
            "method_not_allowed",
            "Use POST to continue a queued agent session on this device.",
            405,
        )
    if not await _authorized_agent_claimant_key(env, request, owner, repo):
        return _org_agent_error(
            "unauthorized",
            (
                "This node could not prove current ownership by its account. "
                "Re-link it to the account and try again."
            ),
            401,
            required_action="relink_desktop",
        )
    owner = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    session_id = clean_string(session_id, 64).strip()
    now = int(Date.now())
    # A lease a node took and never reported on holds no claim once it has
    # expired; the drain releases those for the queue it polls, so release this
    # one session's rather than refuse the row the person actually asked for.
    # Scoped to the session id, which is unique, so an account's claim never
    # touches another account's repository of the same name.
    await d1_run(
        env,
        "UPDATE org_agent_jobs SET status='queued',lease_id='',updated_at=? "
        "WHERE session_id=? AND repo=? AND status='leased' AND updated_at<?",
        now, session_id, repo, now - ORG_AGENT_JOB_LEASE_MS,
    )
    row = await d1_first(
        env,
        "SELECT id,session_id,org_bi,target_node,data FROM org_agent_jobs "
        "WHERE session_id=? AND repo=? AND status='queued' "
        "ORDER BY id LIMIT 1",
        session_id, repo,
    )
    if not row:
        return _org_agent_error(
            "job_not_queued",
            (
                "This session is not waiting for a node any more. Another "
                "device may have started it already."
            ),
            409,
            required_action="refresh_agent_queue",
            target_node=owner,
        )
    job_id = int(row.get("id") or 0)
    try:
        record = await decrypt_row(env, row.get("data"))
    except Exception:
        record = None
    if not job_id or not isinstance(record, dict):
        # Left queued deliberately: which account owns this row is exactly what
        # could not be read, and the owner's own drain is what fails it.
        return _org_agent_error(
            "invalid_job_state",
            (
                "The queued job behind this session could not be read, so it "
                "was not started here."
            ),
            409,
            required_action="refresh_agent_queue",
            target_node=owner,
        )
    # The claimant proved the account named in the URL. The job record says
    # which account queued it, so this is the gate that keeps one account's
    # device from taking another's work off a node name it happens to know.
    # An organization's session names the organization here, not an account,
    # so it is refused too: a member's job is placed by that organization's
    # governance on the node it chose, and no desktop takes it over by hand.
    organization = str(record.get("organization") or "").strip().lower()
    if organization != owner and not await _agent_job_queued_by_signer(
            env, request, owner, repo, row, organization):
        return _org_agent_error(
            "forbidden",
            "This agent session was not queued by this account.",
            403,
            required_action="use_owner_account",
            target_node=owner,
        )
    lease_id = _ap_uuid()
    await d1_run(
        env,
        "UPDATE org_agent_jobs SET status='leased',lease_id=?,target_node=?,"
        "updated_at=? WHERE id=? AND status='queued'",
        lease_id, owner, now, job_id,
    )
    claimed = await d1_first(
        env,
        "SELECT id FROM org_agent_jobs WHERE id=? AND target_node=? "
        "AND repo=? AND status='leased' AND lease_id=?",
        job_id, owner, repo, lease_id,
    )
    if not claimed:
        return _org_agent_error(
            "job_already_claimed",
            "Another device claimed this session first.",
            409,
            retryable=True,
            required_action="refresh_agent_queue",
            target_node=owner,
        )
    # The session follows its job: the website's row must name the namespace
    # the run now reports from, or it would keep pointing at a node that is
    # no longer doing the work.
    await d1_run(
        env,
        "UPDATE org_agent_sessions SET target_node=?,updated_at=? "
        "WHERE session_id=? AND org_bi=?",
        owner, now, row["session_id"], row["org_bi"],
    )
    return json_response({
        "ok": True,
        "job": {
            "jobId": job_id,
            "leaseId": lease_id,
            **record,
        },
        "securityGate": "not-required",
    }, cache_control="no-store")


repo_org_agent_job_result_handler = _route_handlers.export("repo_org_agent_job_result_handler")


repo_org_agent_job_stream_handler = _route_handlers.export(
    "repo_org_agent_job_stream_handler")


org_agent_bot_stream_handler = _route_handlers.export(
    "org_agent_bot_stream_handler")


repo_org_agent_job_attachment_handler = _route_handlers.export(
    "repo_org_agent_job_attachment_handler")


# --- Error log + admin dashboard -------------------------------------------

def _sentry_dsn_parts(dsn):
    dsn = str(dsn or "").strip()
    if not dsn:
        return None
    try:
        parsed = urlparse(dsn)
    except Exception:
        return None
    if parsed.scheme not in ("http", "https"):
        return None
    public_key = parsed.username or ""
    host = parsed.hostname or ""
    if parsed.port:
        host += ":" + str(parsed.port)
    path_parts = [p for p in (parsed.path or "").split("/") if p]
    if not public_key or not host or not path_parts:
        return None
    project_id = path_parts[-1]
    path_prefix = "/" + "/".join(path_parts[:-1]) if len(path_parts) > 1 else ""
    return {
        "dsn": dsn,
        "endpoint": "%s://%s%s/api/%s/envelope/" % (
            parsed.scheme, host, path_prefix, project_id),
        "auth": (
            "Sentry sentry_version=7, sentry_key=%s, sentry_client=%s" %
            (public_key, SENTRY_CLIENT)
        ),
    }


def _sentry_event_id():
    try:
        rnd = js_crypto.getRandomValues(Uint8Array.new(16))
        return "".join("%02x" % int(rnd[i]) for i in range(16))
    except Exception:
        return ("%032x" % int(Date.now()))[-32:]


def _sentry_header(request, name):
    try:
        return str(request.headers.get(name) or "")
    except Exception:
        return ""


def _sentry_safe_url(request):
    try:
        raw = str(getattr(request, "url", "") or "")
        parsed = urlparse(raw)
        if parsed.scheme and parsed.netloc:
            return parsed.scheme + "://" + parsed.netloc + (parsed.path or "/")
        return raw.split("?", 1)[0][:2000]
    except Exception:
        return ""


def _sentry_host(request):
    try:
        parsed = urlparse(str(getattr(request, "url", "") or ""))
        if parsed.netloc:
            return parsed.netloc[:255]
    except Exception:
        pass
    return _sentry_header(request, "host")[:255]


def _sentry_request_payload(request, privacy_safe_path=""):
    if request is None:
        return None
    headers = {}
    # Browser/OS and content-negotiation fingerprints are unnecessary for
    # diagnosing a Worker failure. Keep only the service host and Cloudflare's
    # incident correlation id; authorization, cookies, IP-derived values,
    # referrers and user-agent never enter the Sentry envelope.
    for name in ("host", "cf-ray"):
        value = _sentry_header(request, name)
        if value:
            headers[name] = value
    if "host" not in headers:
        host = _sentry_host(request)
        if host:
            headers["host"] = host
    safe_url = _sentry_safe_url(request)
    privacy_safe_path = str(privacy_safe_path or "").strip()
    if privacy_safe_path:
        # The event's transaction path has already passed through
        # _privacy_safe_log_path. Reuse that projection in request.url too;
        # otherwise Sentry would receive the raw private repository name even
        # though the top-level transaction was correctly redacted.
        try:
            parsed = urlparse(safe_url)
            if parsed.scheme and parsed.netloc:
                safe_url = (
                    parsed.scheme + "://" + parsed.netloc
                    + (privacy_safe_path
                       if privacy_safe_path.startswith("/")
                       else "/" + privacy_safe_path)
                )
            else:
                safe_url = privacy_safe_path
        except Exception:
            safe_url = privacy_safe_path
    return {
        "url": safe_url,
        "method": method_name(request),
        "headers": headers,
    }


def _sentry_cloudflare_context(request, ray="", error_code="", service="forkmesh"):
    ctx = {
        "service": str(service or "forkmesh"),
        "worker": str(service or "forkmesh"),
    }
    if error_code:
        ctx["error_code"] = str(error_code)
    ray = str(ray or "")
    if ray:
        ctx["ray_id"] = ray
        ctx["ray"] = ray
    if ray and "-" in ray:
        ctx["colo"] = ray.rsplit("-", 1)[-1]
    cf = getattr(request, "cf", None) if request is not None else None
    if cf is not None:
        # A coarse edge colo and transport versions are enough to diagnose
        # region/protocol faults. Country, timezone, client RTT, cipher and
        # request-priority details add fingerprinting value without enough
        # operational value, so they are deliberately excluded.
        for key in ("colo", "httpProtocol", "tlsVersion"):
            try:
                value = getattr(cf, key)
            except Exception:
                value = None
            if value is not None:
                ctx[key] = str(value)[:120]
    return ctx


def _sentry_environment(env):
    for name in ("SENTRY_ENVIRONMENT", "ENVIRONMENT", "WORKER_ENV", "ENV"):
        try:
            value = getattr(env, name)
        except Exception:
            value = None
        if value:
            return str(value)[:120]
    return ""


def _sentry_stack_frames(error):
    tb = getattr(error, "__traceback__", None)
    if tb is None:
        return []
    frames = []
    try:
        extracted = traceback.extract_tb(tb)
    except Exception:
        return []
    for frame in extracted[-50:]:
        item = {
            "filename": frame.filename,
            "function": frame.name,
            "lineno": frame.lineno,
        }
        if frame.line:
            item["context_line"] = frame.line
        frames.append(item)
    return frames


def _sentry_event_payload(env, status, method, path, message, ray="",
                          request=None, error=None, cloudflare_error_code="",
                          service="forkmesh"):
    text = _privacy_safe_error_text(path, message)
    cf_context = _sentry_cloudflare_context(
        request, ray, cloudflare_error_code, service)
    tags = {
        "runtime": "cloudflare-python-worker",
        "method": str(method or ""),
        "status": str(status or ""),
        "service": str(service or "forkmesh"),
        "worker": str(service or "forkmesh"),
    }
    if cloudflare_error_code:
        tags["cloudflare.error_code"] = str(cloudflare_error_code)
    if ray:
        tags["cloudflare.ray_id"] = str(ray)
    if cf_context.get("colo"):
        tags["cloudflare.colo"] = str(cf_context.get("colo"))
    host = _sentry_host(request)
    if host:
        tags["host"] = host
    event = {
        "event_id": _sentry_event_id(),
        "timestamp": int(Date.now()) / 1000,
        "platform": "python",
        "logger": "forkmesh.app",
        "level": "error" if int(status or 0) >= 500 else "warning",
        "message": text[:1000] or ("HTTP " + str(status)),
        "transaction": str(path or ""),
        "server_name": str(getattr(env, "NODE_NAME", "") or "cloudflare-worker"),
        "release": _build_rev(env),
        "tags": tags,
        "contexts": {
            "cloudflare": cf_context,
            "runtime": {
                "name": "Cloudflare Python Workers",
                "service": str(service or "forkmesh"),
            },
        },
        "extra": {"error_log_message": text[:8000]},
    }
    environment = _sentry_environment(env)
    if environment:
        event["environment"] = environment
    req = _sentry_request_payload(request, path)
    if req:
        event["request"] = req
    if error is not None:
        exception = {
            "type": type(error).__name__,
            "value": (
                "Repository-route exception details redacted."
                if _privacy_redacted_log_path(path)
                else _safe_error_text(error)[:1000]
            ),
        }
        frames = _sentry_stack_frames(error)
        if frames:
            exception["stacktrace"] = {"frames": frames}
        event["exception"] = {"values": [exception]}
    return event


async def capture_sentry_error(env, status, method, path, message, ray="",
                               request=None, error=None,
                               cloudflare_error_code="", service="forkmesh"):
    """Send one Sentry event with vanilla Python + Worker fetch. Best-effort."""
    try:
        parts = _sentry_dsn_parts(getattr(env, "SENTRY_DSN", ""))
        if not parts:
            return False
        event = _sentry_event_payload(
            env, status, method, path, message, ray, request, error,
            cloudflare_error_code, service)
        envelope = (
            json.dumps({"event_id": event["event_id"], "dsn": parts["dsn"]}) +
            "\n" + json.dumps({"type": "event"}) +
            "\n" + json.dumps(event) + "\n"
        )
        resp = await js_fetch_with_timeout(
            parts["endpoint"],
            {
                "method": "POST",
                "headers": {
                    "content-type": "application/x-sentry-envelope",
                    "x-sentry-auth": parts["auth"],
                },
                "body": envelope,
            },
            CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
        )
        return 200 <= int(getattr(resp, "status", 0)) < 300
    except Exception:
        return False


def _sentry_int_env(env, name, default, minimum=1, maximum=1440):
    try:
        raw = getattr(env, name)
    except Exception:
        raw = None
    try:
        value = int(str(raw or "").strip())
    except Exception:
        value = int(default)
    if value < minimum:
        return int(minimum)
    if value > maximum:
        return int(maximum)
    return value


def _sentry_cron_monitor_slug(env):
    for name in ("SENTRY_CRON_MONITOR_SLUG", "SENTRY_MONITOR_SLUG"):
        try:
            value = getattr(env, name)
        except Exception:
            value = None
        value = str(value or "").strip()
        if value:
            return value[:200]
    return SENTRY_CRON_MONITOR_SLUG


def _scheduled_cron_expression(controller):
    for name in ("cron", "schedule"):
        try:
            value = getattr(controller, name)
        except Exception:
            value = None
        value = str(value or "").strip()
        if value:
            return value[:120]
    return "* * * * *"


def _sentry_cron_monitor_config(env, cron):
    cron = str(cron or "").strip() or "* * * * *"
    try:
        timezone = str(getattr(env, "SENTRY_CRON_TIMEZONE", "") or "UTC")
    except Exception:
        timezone = "UTC"
    return {
        "schedule": {"type": "crontab", "value": cron[:120]},
        "checkin_margin": _sentry_int_env(
            env, "SENTRY_CRON_CHECKIN_MARGIN_MINUTES",
            SENTRY_CRON_CHECKIN_MARGIN_MINUTES),
        "max_runtime": _sentry_int_env(
            env, "SENTRY_CRON_MAX_RUNTIME_MINUTES",
            SENTRY_CRON_MAX_RUNTIME_MINUTES),
        "timezone": timezone[:120] or "UTC",
    }


async def capture_sentry_cron_check_in(env, status, check_in_id="",
                                       cron="", duration=None):
    """Send a Sentry Cron Monitoring check-in. Best-effort."""
    try:
        parts = _sentry_dsn_parts(getattr(env, "SENTRY_DSN", ""))
        if not parts:
            return False
        status = str(status or "").strip().lower()
        if status not in ("in_progress", "ok", "error"):
            return False
        check_in_id = str(check_in_id or "").strip() or _sentry_event_id()
        cron = str(cron or "").strip() or "* * * * *"
        payload = {
            "check_in_id": check_in_id[:64],
            "monitor_slug": _sentry_cron_monitor_slug(env),
            "status": status,
            "monitor_config": _sentry_cron_monitor_config(env, cron),
        }
        environment = _sentry_environment(env)
        if environment:
            payload["environment"] = environment
        release = _build_rev(env)
        if release:
            payload["release"] = release
        if duration is not None:
            try:
                payload["duration"] = max(0.0, float(duration))
            except Exception:
                pass
        envelope = (
            json.dumps({"event_id": check_in_id[:32], "dsn": parts["dsn"]}) +
            "\n" + json.dumps({"type": "check_in"}) +
            "\n" + json.dumps(payload) + "\n"
        )
        resp = await js_fetch_with_timeout(
            parts["endpoint"],
            {
                "method": "POST",
                "headers": {
                    "content-type": "application/x-sentry-envelope",
                    "x-sentry-auth": parts["auth"],
                },
                "body": envelope,
            },
            CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
        )
        return 200 <= int(getattr(resp, "status", 0)) < 300
    except Exception:
        return False


# _fire_and_forget/_consume_background_task lived here: they wrapped
# asyncio.ensure_future so a detached task's exception was observed rather than
# reaching the loop's default handler. Nothing called them, and a detached task
# is now banned outright — see the no-concurrent-tasks rule at the top of this
# module. Telemetry that used to want a background task (Sentry captures, error
# rows) is awaited inline inside its own try/except instead.


async def _error_log_actor(env, request):
    """Account name the failing request itself proved, or "" when anonymous.

    Never trusts a caller-supplied `node`/`owner` string: only a valid account
    session names a user here. A request without a session token costs nothing
    (_account_session_lookup rejects the token shape before any D1 read), so an
    anonymous error storm does not gain a per-error lookup. Best-effort —
    error logging must never become a new error.
    """
    if request is None:
        return ""
    try:
        # Attribution only, and it rides the error path: an unverified caller
        # should still be named on the error its refused write produced.
        _, rec = await _account_session_record(
            env, request, allow_unverified=True)
        return clean_string(
            (rec or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
    except Exception:
        return ""


async def _notify_new_error_group(env, status, method, path, message):
    """Ping the platform administrators the first time an error group appears.

    The admin error view groups by (status, method, path, message), so the
    first row of a group is the event worth reading — "something new is
    broken" — while later repeats are noise. Best-effort and admin-only: this
    rides the error path, so it must never raise and stays one bounded read
    plus one bounded insert per administrator (adhoc #77).
    """
    rows = await d1_all(
        env, "SELECT data FROM users WHERE is_admin=1 LIMIT 20")
    if not rows:
        return
    source = _admin_error_source(method, path)
    title = "New %s error group (%s)" % (source.lower(), status)
    # notification_payload keeps 500 characters of body, and a truncated
    # crash report loses exactly the tail that explains the crash (heap,
    # context losses, GPU). Spend the whole allowance on the message.
    body = "%s %s — %s" % (
        str(method or "?"), str(path or "?"), str(message or "")[:460])
    for row in rows:
        try:
            record = await decrypt_row(env, row.get("data", "")) or {}
        except Exception:
            continue
        name = clean_string(record.get("name", ""), MAX_NODE_NAME).lower()
        if not valid_node_name(name):
            continue
        await enqueue_notification(
            env, name, "error_group", title, body=body,
            href=_admin_path_rules.notification_href(
                env, "?table=error_log"), source="error_log",
            dedupe="error-group:%s:%s:%s:%s" % (
                status, str(method or "")[:16], str(path or "")[:120],
                str(message or "")[:160]),
            meta={"status": int(status), "method": str(method or ""),
                  "path": str(path or "")[:200], "errorSource": source},
        )


async def _write_error_log(env, status, method, path, message, ray="",
                           actor="", only_new_group=False, notify=True):
    if _read_only(env):
        return
    try:
        message = _privacy_safe_error_text(path, message)
        await ensure_schema(env)
        # Is this the first row of its group? Read before the insert, so the
        # row we are about to write cannot answer its own question.
        known_group = await d1_first(
            env,
            """SELECT 1 AS hit FROM error_log
               WHERE status=? AND method=? AND path=? AND message=? LIMIT 1""",
            int(status), str(method or ""), str(path or ""),
            str(message or "")[:1000],
        )
        # A caller whose rows a visitor can provoke on demand keeps only the
        # one row that raised the ping. Repeats would otherwise let anyone who
        # can trip a refusal roll the whole operational log out of its bound.
        if known_group and only_new_group:
            return
        inserted = await d1_run(
            env,
            """INSERT INTO error_log
                 (ts, status, method, path, message, ray, actor)
               VALUES (?,?,?,?,?,?,?)""",
            int(Date.now()), int(status), str(method or ""), str(path or ""),
            str(message or "")[:1000], str(ray or ""),
            clean_string(actor or "", MAX_NODE_NAME).strip().lower(),
        )
        # Keep only the most-recent MAX_ERROR_LOG rows so the table is bounded.
        # ids only grow, so every id at or below new id - MAX_ERROR_LOG is out
        # of bound: a primary-key range that reads only the rows it deletes,
        # where the NOT IN form walked the whole table on every insert.
        try:
            last_id = int(inserted.meta.last_row_id)
        except Exception:
            last_id = 0
        if last_id > MAX_ERROR_LOG:
            await d1_run(
                env, "DELETE FROM error_log WHERE id <= ?",
                last_id - MAX_ERROR_LOG,
            )
        elif last_id <= 0:
            await d1_run(
                env,
                """DELETE FROM error_log WHERE id NOT IN
                   (SELECT id FROM error_log ORDER BY id DESC LIMIT ?)""",
                MAX_ERROR_LOG,
            )
        # Last, so a notification that cannot be delivered never costs the log
        # its record or its bound.
        if notify and not known_group:
            await _notify_new_error_group(env, status, method, path, message)
    except Exception:
        pass


def _sanitize_client_error_text(value, maximum):
    """Keep debugging shape while stripping URLs, routes, ids and secrets."""
    text = "".join(
        character if character >= " " and character != "\x7f" else " "
        for character in str(value or "")
    )
    text = re.sub(
        r"\b(?:authorization|bearer|password|passwd|secret|token|"
        r"api[_-]?key)\b\s*[:=]?\s*[^\s,;]+",
        "[redacted-secret]",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b",
        "[redacted-email]",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"\b[A-Za-z0-9_-]{32,}\b", "[redacted-id]", text)
    text = re.sub(r"\bhttps?://[^\s)]+", "[redacted-url]", text)
    text = re.sub(
        r"/(?:[A-Za-z0-9._~%-]+/)+[A-Za-z0-9._~%-]+"
        r"(?:[?#][^\s]*)?",
        "/[redacted-path]",
        text,
    )
    return " ".join(text.split()).strip()[:maximum]


def _client_error_is_injected_only(stack):
    """True when every reported frame came from an extension or injected code.

    Browser extensions run inside the page, so their uncaught exceptions reach
    this collector looking like ours. Redaction keeps enough shape to tell them
    apart: a frame this site served still leaves a [redacted-url] or a
    /[redacted-path], while injected code leaves only "<anonymous>" or an
    extension scheme. Reporters are cached in browsers for a long time, so the
    same filter has to hold here and not only in analytics.js.
    """
    text = _sanitize_client_error_text(stack, 700)
    if not text:
        return False
    # Redaction rewrites an extension URL's path the same way it rewrites ours,
    # so retire those frames before reading what is left as first-party.
    text, extension_frames = re.subn(
        r"\b(?:[a-z][a-z0-9-]*-extension|iabjs):"
        r"(?:/\[redacted-path\]|[^\s)]*)",
        " ",
        text,
        flags=re.IGNORECASE,
    )
    if "[redacted-url]" in text or "[redacted-path]" in text:
        return False
    return bool(extension_frames) or "<anonymous>" in text


def _client_error_is_non_actionable(payload):
    """True for browser diagnostics that contain no fixable app failure."""
    if not isinstance(payload, dict):
        return False
    message = _sanitize_client_error_text(payload.get("message"), 300)
    # "Object Not Found Matching Id:N, MethodName:update, ParamCount:N" is
    # Microsoft's SafeLinks/Outlook link scanner failing inside its own
    # injected script when it opens a page; no ForkMesh code is on the stack.
    return bool(re.fullmatch(
        r"(?:script error\.?|resizeobserver loop (?:limit exceeded|"
        r"completed with undelivered notifications)\.?|"
        r"object not found matching id:\s*\d+,\s*methodname:\s*\w+,"
        r"\s*paramcount:\s*\d+|"
        r"invalid call to runtime\.sendmessage\(\)\. tab not found\.?)",
        message,
        flags=re.IGNORECASE,
    ))


def _client_error_fields(payload):
    if not isinstance(payload, dict):
        return None
    surface = str(payload.get("surface") or "").strip().lower()
    kind = str(payload.get("kind") or "").strip().lower()
    if surface not in CLIENT_ERROR_SURFACES or kind not in CLIENT_ERROR_KINDS:
        return None
    # Crash reports carry a full diagnostic line (device, renderer, resident
    # scene, memory); 500 characters cut it off mid-reading. The detail below
    # still fits the 1000-character error_log column.
    message = _sanitize_client_error_text(payload.get("message"), 900)
    if not message:
        message = "Unspecified browser exception"
    stack = _sanitize_client_error_text(payload.get("stack"), 700)
    source_value = re.split(
        r"[?#]", str(payload.get("source") or ""), maxsplit=1)[0]
    source = re.sub(
        r"[^A-Za-z0-9._-]+", "",
        source_value.rsplit("/", 1)[-1],
    )[:80]
    try:
        line = max(0, min(10_000_000, int(payload.get("line") or 0)))
        column = max(0, min(10_000_000, int(payload.get("column") or 0)))
    except (TypeError, ValueError):
        line = column = 0
    detail = "client %s [%s] %s" % (kind, surface, message)
    if source:
        detail += " (%s:%d:%d)" % (source, line, column)
    if stack:
        detail += " | " + stack
    return surface, detail[:1000]


async def client_error_handler(env, request):
    """Store redacted uncaught browser errors without trusting client paths."""
    if method_name(request) != "POST":
        return json_response(
            {"error": "method_not_allowed"},
            status=405,
            extra_headers={"allow": "POST"},
        )
    if not _request_origin_allowed(env, request):
        return json_response({"error": "origin_not_allowed"}, status=403)
    try:
        payload = await bounded_json_request(request, CLIENT_ERROR_MAX_BODY)
    except RequestBodyTooLarge:
        return json_response({"error": "payload_too_large"}, status=413)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    fields = _client_error_fields(payload)
    if not fields:
        return json_response({"error": "invalid_client_error"}, status=400)
    if (_client_error_is_non_actionable(payload)
            or _client_error_is_injected_only(payload.get("stack"))):
        # Accepted, deliberately not stored: nothing here is ours to fix.
        return json_response(
            {"ok": True, "stored": False},
            status=202,
            cache_control="no-store",
        )
    surface, detail = fields
    now = int(Date.now())
    client_address = _transient_client_address(request)
    try:
        client_hash = await blind_index(
            env, "client-error:" + (client_address or "unknown"))
    except Exception:
        client_hash = "unknown"
    source_key = "client:" + str(client_hash)[:32]
    try:
        await ensure_schema(env)
        per_client = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM error_log "
            "WHERE ts>=? AND method='JS' AND ray=?",
            now - CLIENT_ERROR_RATE_WINDOW_MS,
            source_key,
        )
        global_rate = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM error_log "
            "WHERE ts>=? AND method='JS'",
            now - CLIENT_ERROR_RATE_WINDOW_MS,
        )
        duplicate = await d1_first(
            env,
            "SELECT 1 AS one FROM error_log "
            "WHERE ts>=? AND method='JS' AND path=? AND message=? AND ray=? "
            "LIMIT 1",
            now - CLIENT_ERROR_RATE_WINDOW_MS,
            "/client-error/" + surface,
            detail,
            source_key,
        )
        if (
            duplicate
            or int((per_client or {}).get("n") or 0)
            >= CLIENT_ERROR_RATE_PER_CLIENT
            or int((global_rate or {}).get("n") or 0)
            >= CLIENT_ERROR_RATE_GLOBAL
        ):
            return json_response(
                {"ok": True, "stored": False},
                status=202,
                cache_control="no-store",
            )
        try:
            actor = await _error_log_actor(env, request)
        except BaseException:
            actor = ""
        await _write_error_log(
            env,
            520,
            "JS",
            "/client-error/" + surface,
            detail,
            source_key,
            actor,
            notify=str(payload.get("kind") or "").strip().lower() != "discard",
        )
    except Exception:
        # Error reporting must never become a new user-visible error.
        return json_response(
            {"ok": True, "stored": False},
            status=202,
            cache_control="no-store",
        )
    return json_response(
        {"ok": True, "stored": True},
        status=202,
        cache_control="no-store",
    )


def _desktop_error_fields(payload):
    """Validate one desktop report and fold it into a single error_log line."""
    if not isinstance(payload, dict):
        return None
    surface = str(payload.get("surface") or "").strip().lower()
    kind = str(payload.get("kind") or "").strip().lower()
    if surface not in DESKTOP_ERROR_SURFACES or kind not in DESKTOP_ERROR_KINDS:
        return None
    # The dialog title is the operator's own name for the failing operation
    # ("Sync inbox"), which is most of the triage value in one short string.
    title = _sanitize_client_error_text(payload.get("title"), 120)
    message = _sanitize_client_error_text(payload.get("message"), 700)
    if not message:
        return None
    # adhoc #1654: a stored report comes back wearing the stamp this route puts
    # on it once the desktop echoes the "new error group" ping it raised. The
    # admin view groups on the exact message, so the quoted copy never matches
    # the group it quotes: it opens a second one, which pings again, each round
    # quoting the last. The desktop holds these back now, but a node that has
    # not updated must not be able to restart the loop from out here.
    if re.search(r"desktop (?:dialog|notice|toast) \[(?:app|headless)\]", message,
                 flags=re.IGNORECASE):
        return None
    detail = "desktop %s [%s] %s" % (kind, surface, message)
    if title:
        detail = "desktop %s [%s] %s — %s" % (kind, surface, title, message)
    return surface, detail[:1000]


def _expected_desktop_probe_noise(surface, detail):
    """Recognize false site-outage reports emitted by older desktop builds."""
    text = str(detail or "").lower()
    if surface != "app" or " is down" not in text:
        return False
    # A desktop that aborted its own probe (restart, superseded check) observed
    # nothing about the site or its status page.
    if (("the site on " in text or "the /status page on " in text)
            and "from this desktop: operation canceled" in text):
        return True
    if "the site on " not in text:
        return False
    return (
        "returned http 308 to this desktop" in text
        or "server received frame(s) on a half-closed stream" in text
    )


async def desktop_error_handler(env, request):
    """Record a signed desktop client's user-visible failure in error_log.

    The client already deduplicates and rate-limits its own reports, and it
    holds a report back entirely while the relay is in a 429 cooldown; the
    bounds here exist because a client is a client — one broken or hostile node
    must not be able to displace Worker errors or grow D1.
    """
    if method_name(request) != "POST":
        return json_response(
            {"error": "method_not_allowed"},
            status=405,
            extra_headers={"allow": "POST"},
        )
    try:
        payload = await bounded_json_request(request, DESKTOP_ERROR_MAX_BODY)
    except RequestBodyTooLarge:
        return json_response({"error": "payload_too_large"}, status=413)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    fields = _desktop_error_fields(payload)
    if not fields:
        return json_response({"error": "invalid_desktop_error"}, status=400)
    # Same signed owner/ts/sig proof as GET /api/sync, checked before any
    # bounded-row read: an unsigned report is refused, never stored anonymously.
    params = parse_qs(urlparse(request.url).query)
    owner = safe_segment(params.get("owner", [""])[0])
    if not owner or not await _authorize_owner(env, request, owner):
        return json_response({"error": "unauthorized"}, status=401)
    surface, detail = fields
    # Older desktops interpreted an unconsumed canonical redirect or a Qt
    # HTTP/2 connection teardown as proof that the public site was down.  Both
    # are local probe artifacts, not operational errors; accept the signed
    # report so the client settles its queue, but do not store or page on it.
    if _expected_desktop_probe_noise(surface, detail):
        return json_response(
            {"ok": True, "stored": False, "expected": True},
            status=202,
            cache_control="no-store",
        )
    now = int(Date.now())
    try:
        owner_hash = await blind_index(env, "desktop-error:" + owner)
    except Exception:
        owner_hash = "unknown"
    source_key = "app:" + str(owner_hash)[:32]
    path = "/desktop-error/" + surface
    try:
        await ensure_schema(env)
        per_owner = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM error_log "
            "WHERE ts>=? AND method='APP' AND ray=?",
            now - DESKTOP_ERROR_RATE_WINDOW_MS,
            source_key,
        )
        global_rate = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM error_log "
            "WHERE ts>=? AND method='APP'",
            now - DESKTOP_ERROR_RATE_WINDOW_MS,
        )
        duplicate = await d1_first(
            env,
            "SELECT 1 AS one FROM error_log "
            "WHERE ts>=? AND method='APP' AND path=? AND message=? AND ray=? "
            "LIMIT 1",
            now - DESKTOP_ERROR_RATE_WINDOW_MS,
            path,
            detail,
            source_key,
        )
        if (
            duplicate
            or int((per_owner or {}).get("n") or 0)
            >= DESKTOP_ERROR_RATE_PER_OWNER
            or int((global_rate or {}).get("n") or 0)
            >= DESKTOP_ERROR_RATE_GLOBAL
        ):
            return json_response(
                {"ok": True, "stored": False},
                status=202,
                cache_control="no-store",
            )
        # 521 rather than the browser collector's 520: the status is part of the
        # group key and of the ping title, so a desktop failure reads apart from
        # a browser one without any per-row lookup. The account is the proven
        # signer, so the admin "related users" column names the node's owner.
        await _write_error_log(
            env,
            521,
            "APP",
            path,
            detail,
            source_key,
            owner,
        )
    except Exception:
        # Error reporting must never become a new user-visible error.
        return json_response(
            {"ok": True, "stored": False},
            status=202,
            cache_control="no-store",
        )
    return json_response(
        {"ok": True, "stored": True},
        status=202,
        cache_control="no-store",
    )


def _privacy_redacted_log_path(path):
    path = str(path or "")
    return (
        path in (
            "/private-or-unpublished-repository",
            "/repository-route-redacted",
            "/api/private-replicas/[opaque]",
        )
        or path.startswith("/private-or-unpublished-repository/")
        or path.startswith("/repository-route-redacted/")
    )


def _privacy_safe_error_text(path, message):
    """Remove exception/detail text when the route identity was redacted."""
    if _privacy_redacted_log_path(path):
        # Two fixed, worker-authored message shapes carry no route identity
        # (no path, no exception text) and are the only diagnostic signal a
        # redacted row has — blanket-redacting them made every private-route
        # 5xx indistinguishable from every other.
        text = str(message or "")
        if (
            text.startswith("response status ")
            and len(text) == len("response status ") + 3
            and text[-3:].isdigit()
        ):
            return text
        if text.startswith("d1 unavailable: "):
            lowered = text.lower()
            kind = next(
                (marker for marker in (
                    "overload", "too many", "internal error",
                    "network connection lost")
                 if marker in lowered),
                "other")
            return ("d1 unavailable (" + kind
                    + "): Repository-route error details redacted.")
        return "Repository-route error details redacted."
    return str(message or "")


def _privacy_redacted_route_kind(path):
    """An identity-free route-family tag for a redacted repository path.

    Owner/repo (and any deeper user-named path parts) are dropped entirely —
    what survives is only WHICH fixed route family failed: the git protocol
    step, a release blob, the browser page, or the /api/repo sub-route's fixed
    name (issues/tree/star/…). Without this, every redacted 5xx collapsed
    into one indistinguishable bucket and recurring failures could not even
    be told apart by endpoint (2026-07-24 error-log entries)."""
    if GIT_INFO_RE.match(path):
        return "[git-info-refs]"
    if GIT_PACK_RE.match(path):
        return "[git-upload-pack]"
    if GIT_RECEIVE_RE.match(path):
        return "[git-receive-pack]"
    if RELEASE_BLOB_RE.match(path):
        return "[release-blob]"
    api = REPO_API_PREFIX_RE.match(path)
    if api:
        rest = path[api.end(2):].strip("/")
        route = safe_segment(rest.split("/", 1)[0]) if rest else ""
        # The first segment after /api/repo/<o>/<r>/ is a fixed route name
        # from the worker's own routing table, never user data; anything
        # unrecognizably long is a probe and collapses to a generic tag.
        if route and len(route) <= 32:
            return "[api:" + route + "]"
        return "[api]"
    return "[page]"


async def _privacy_safe_log_path(env, path):
    """Redact names from private, missing, or visibility-unknown repo routes."""
    path = str(path or "")
    if not path.startswith("/"):
        return path
    # Opaque ids are identity-free and not sufficient authorization, so their
    # presence in unavoidable edge request logs does not reveal a repository.
    # Application/Sentry logs do not need the locator at all: redact it there to
    # avoid turning an error report into a reusable private-route hint.
    if path == "/api/private-replicas" or path.startswith(
            "/api/private-replicas/"):
        return "/api/private-replicas/[opaque]"
    if path.startswith("/api/chat/channels/"):
        return "/api/chat/channels/[opaque]"
    if path.startswith("/api/chat/invites/"):
        return "/api/chat/invites/[token]"
    if path.startswith("/api/chat/direct-messages/"):
        return "/api/chat/direct-messages/[opaque]"
    match = REPO_API_PREFIX_RE.match(path)
    if not match:
        for pattern in (
                GIT_INFO_RE, GIT_PACK_RE, GIT_RECEIVE_RE,
                RELEASE_BLOB_RE):
            match = pattern.match(path)
            if match:
                break
    owner = ""
    repo = ""
    if match:
        owner = safe_segment(match.group(1))
        repo = safe_segment(match.group(2))
    elif looks_like_repo_route(path):
        # Browser repository pages (/owner/repo and their tab/tree/blob deep
        # links) are repository routes too. Never let an exception log become
        # a name-existence oracle for a private or unpublished path.
        parts = [part for part in path.split("/") if part]
        owner = safe_segment(unquote(parts[0])) if len(parts) >= 2 else ""
        repo = safe_segment(unquote(parts[1])) if len(parts) >= 2 else ""
    else:
        return path
    if not owner or not repo:
        return "/repository-route-redacted/" + _privacy_redacted_route_kind(
            path)
    if await _repo_is_private(env, owner, repo):
        return ("/private-or-unpublished-repository/"
                + _privacy_redacted_route_kind(path))
    return path


async def capture_worker_exception(env, request, url, error):
    """Capture the Python exception that Cloudflare will surface as Error 1101."""
    try:
        ray = _sentry_header(request, "cf-ray")
    except BaseException:
        ray = ""
    try:
        method = method_name(request)
    except BaseException:
        method = "GET"
    try:
        path = getattr(url, "path", "") or _sentry_safe_url(request)
    except BaseException:
        path = ""
    try:
        path = await _privacy_safe_log_path(env, path)
    except BaseException:
        path = "/repository-route-redacted"
    try:
        message = repr(error) + "\n" + traceback.format_exc()
    except BaseException:
        message = _safe_error_text(error)
    try:
        await capture_sentry_error(
            env, 500, method, path, message, ray,
            request=request,
            error=error,
            cloudflare_error_code="1101",
            service="forkmesh",
        )
    except BaseException:
        pass
    # Naming the affected account is a nice-to-have; it must never be able to
    # cost the log row itself, so it resolves in its own guard.
    try:
        actor = await _error_log_actor(env, request)
    except BaseException:
        actor = ""
    try:
        await _write_error_log(env, 500, method, path, message, ray, actor)
    except BaseException:
        pass


def _html_escape(value):
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


