def _is_tunnel_content_path(path):
    """Host-tunnel content routes whose 502/503/504s mean 'that node is
    offline', not 'the worker failed': release blobs, repo browse, git
    clone/push. Room paths are deliberately NOT included — a room 5xx is the
    worker's own Durable Object failing, which must stay visible."""
    path = str(path or "")
    return bool(
        RELEASE_BLOB_RE.match(path) or REPO_HOST_RE.match(path) or
        GIT_INFO_RE.match(path) or GIT_PACK_RE.match(path) or
        GIT_RECEIVE_RE.match(path))


# Marks a 5xx/501 the worker produced ON PURPOSE for an expected, already-
# degraded condition: a Durable Object abort that log_durable_object_abort has
# already added to its minute aggregate, a fail-closed not-implemented answer,
# or an upstream dependency being unavailable. The outer fetch's generic 5xx
# logger skips marked responses — without this every DO abort would also add a
# vague "response status 503" error row/Sentry event, and deliberate degraded
# answers would bury real bugs.
EXPECTED_DEGRADED_HEADER = "x-forkmesh-expected-degraded"
EXPECTED_DEGRADED_HEADERS = {EXPECTED_DEGRADED_HEADER: "1"}


def _response_is_expected_degraded(response):
    try:
        js_obj = getattr(response, "js_object", None) or response
        return bool(js_obj.headers.get(EXPECTED_DEGRADED_HEADER))
    except Exception:
        return False


MAINTENANCE_TRUE_VALUES = ("1", "true", "yes", "on")
READ_ONLY_RETRY_AFTER_SECONDS = 120
MAINTENANCE_SOCKET_CLOSE_CODE = 1012
_SQL_LEADING_COMMENTS_RE = re.compile(
    r"(?:\s+|--[^\n]*(?:\n|$)|/\*.*?\*/)*", re.S)
_SQL_WRITE_VERB_RE = re.compile(
    r"(?:INSERT|UPDATE|DELETE|REPLACE|CREATE|ALTER|DROP)\b", re.I)
_SQL_QUOTED_RE = re.compile(r"'(?:[^']|'')*'|\"(?:[^\"]|\"\")*\"", re.S)
_SQL_CTE_WRITE_RE = re.compile(
    r"\b(?:INSERT|UPDATE|DELETE|REPLACE\s+INTO|CREATE|ALTER|DROP)\b", re.I)


class ReadOnlyModeError(Exception):
    pass


def _env_flag(env, name):
    try:
        value = getattr(env, name, None)
        if value is None or js_nullish(value):
            return False
        return str(value).strip().lower() in MAINTENANCE_TRUE_VALUES
    except BaseException:
        return False


def _decommissioned(env):
    return _env_flag(env, "FORKMESH_DECOMMISSIONED")


def _read_only(env):
    return _env_flag(env, "FORKMESH_READ_ONLY") or _decommissioned(env)


def _sql_is_write(sql):
    text = str(sql or "")
    text = text[_SQL_LEADING_COMMENTS_RE.match(text).end():]
    if _SQL_WRITE_VERB_RE.match(text):
        return True
    if re.match(r"WITH\b", text, re.I):
        return bool(_SQL_CTE_WRITE_RE.search(_SQL_QUOTED_RE.sub("''", text)))
    return False


def _d1_write_guard(env, sql):
    if _read_only(env) and _sql_is_write(sql):
        raise ReadOnlyModeError("read_only")


def _read_only_response():
    return json_response(
        {"error": "read_only", "retryAfter": READ_ONLY_RETRY_AFTER_SECONDS},
        status=503,
        cache_control="no-store",
        extra_headers={
            **EXPECTED_DEGRADED_HEADERS,
            "Retry-After": str(READ_ONLY_RETRY_AFTER_SECONDS),
            "x-forkmesh-worker": "app",
        },
    )


def _decommissioned_response():
    return json_response(
        {"error": "decommissioned"},
        status=503,
        cache_control="no-store",
        extra_headers={**EXPECTED_DEGRADED_HEADERS, "x-forkmesh-worker": "app"},
    )


def _read_only_request_allowed(request):
    try:
        if str(request.headers.get("upgrade") or ""):
            return False
    except BaseException:
        return False
    method = method_name(request)
    if method in ("GET", "HEAD", "OPTIONS"):
        try:
            query = str(JsURL.new(str(request.url)).search or "")
        except BaseException:
            return False
        return "git-receive-pack" not in query
    return bool(_git_clone_http_request(request))


def _maintenance_gate_response(env, request):
    if _decommissioned(env):
        return _decommissioned_response()
    if not _read_only(env) or _read_only_request_allowed(request):
        return None
    try:
        path = str(JsURL.new(str(request.url)).pathname or "").rstrip("/")
    except BaseException:
        path = ""
    if path == "/api/attribution/capture":
        return Response(None, status=204, headers={"cache-control": "no-store"})
    return _read_only_response()


async def _maintenance_stop_alarm(durable_object):
    try:
        await durable_object.ctx.storage.deleteAlarm()
    except BaseException:
        pass


def _maintenance_socket_closed(env, ws):
    if not _read_only(env):
        return False
    try:
        ws.close(MAINTENANCE_SOCKET_CLOSE_CODE, "service restart")
    except Exception:
        pass
    return True


async def log_error(env, status, method, path, message, ray="", request=None,
                    error=None):
    """Record a 5xx / unhandled error. Best-effort: never raises."""
    privacy_filter = globals().get("_privacy_safe_log_path")
    if callable(privacy_filter):
        path = await privacy_filter(env, path)
    await capture_sentry_error(
        env, status, method, path, message, ray, request=request, error=error)
    try:
        actor = await _error_log_actor(env, request)
    except BaseException:
        actor = ""
    await _write_error_log(env, status, method, path, message, ray, actor)


# Account creation refused for a reason the visitor cannot correct. Every one
# of these is a deliberate 4xx, so nothing raises, nothing reaches log_error,
# and nothing reaches the admin error view — which is how a username filter
# refusing clean names could run for days looking exactly like "nobody signed
# up this week" (adhoc #70). Ordinary form validation is deliberately absent:
# a taken name, a short password or a malformed email is the visitor's to fix,
# and pinging on those would bury the signal that matters.
BLOCKING_SIGNUP_REFUSALS = frozenset({
    "account_pending_verification",
    "inappropriate_node_name",
    "invalid_signup_referral_code",
    "rate_limited",
    "signup_page_required",
    # The Turnstile secret is missing or siteverify is down: nobody can sign
    # up until an operator looks. (A bot without a token is not logged.)
    "turnstile_unavailable",
})
# The three routes that create an account: the web form, and the two halves of
# a desktop/headless node claiming its name. Logged as the grouping path, so
# "the website cannot sign anyone up" and "no node can finish installing" stay
# separate error groups with their own pings.
SIGNUP_PATH = "/api/accounts/signup"
NODE_RESERVE_PATH = "/api/accounts/reserve"
NODE_FINALIZE_PATH = "/api/accounts/finalize"


async def log_blocked_signup(env, request, path, status, reason):
    """Record an account creation that got stuck, so administrators get pinged.

    These rows share the error log's (status, method, path, message) grouping,
    so a reason that keeps firing costs one ping and then stays quiet, while a
    new way for signup to break always announces itself. The SIGNUP method
    marks the rows apart from the 5xx faults around them. Best-effort: a
    refusal that is already being answered must never fail a second time.
    """
    if reason not in BLOCKING_SIGNUP_REFUSALS:
        return
    try:
        ray = request.headers.get("cf-ray") or ""
    except BaseException:
        ray = ""
    await _write_error_log(
        env, int(status), "SIGNUP", str(path or ""),
        "Account creation blocked: " + str(reason or "")[:80], ray, "",
        only_new_group=True)


SIGNUP_PROBLEM_PATH = "/api/accounts/signup/problem"
SIGNUP_BROWSER_PROBLEMS = frozenset({
    "challenge_backup_failed",
    "challenge_error",
    "challenge_stale",
    "challenge_not_rendered",
    "challenge_render_failed",
    "challenge_token_missing",
    "challenge_unavailable",
    "network_error",
    "signup_page_renew_failed",
    "unexpected_response",
})
SIGNUP_FAILURE_WINDOW_MS = 60 * 60 * 1000
SIGNUP_FAILURE_PINGS_PER_WINDOW = 60
_signup_failure_pinged = {}


def _signup_failure_already_pinged(key, now):
    for seen, at in list(_signup_failure_pinged.items()):
        if now - at >= SIGNUP_FAILURE_WINDOW_MS:
            _signup_failure_pinged.pop(seen, None)
    if (key in _signup_failure_pinged
            or len(_signup_failure_pinged) >= SIGNUP_FAILURE_PINGS_PER_WINDOW):
        return True
    _signup_failure_pinged[key] = now
    return False


async def ping_signup_failure(env, reason, status, claim=None, name="",
                              detail="", source="server"):
    try:
        reason = re.sub(r"[^a-z0-9_]", "", str(reason or "").lower())[:60]
        reason = reason or "unknown"
        detail = re.sub(r"[^A-Za-z0-9_.:-]", "", str(detail or ""))[:40]
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            name = ""
        now = int(Date.now())
        claim_id = (claim or {}).get("claimId", "") if isinstance(
            claim, dict) else ""
        bucket = claim_id or "window-%d" % (now // SIGNUP_FAILURE_WINDOW_MS)
        key = "%s:%s:%s" % (bucket, source, reason)
        if _signup_failure_already_pinged(key, now):
            return
        who = "@" + name if name else "a visitor"
        if source == "browser":
            body = "The signup page in %s's browser failed: %s" % (who, reason)
        else:
            body = "Signup refused %s: %s (HTTP %d)" % (who, reason, int(status))
        if detail:
            body += " [" + detail + "]"
        title = "Signup failed: " + reason
        rows = await d1_all(
            env, "SELECT data FROM users WHERE is_admin=1 LIMIT 20")
        for row in rows or []:
            try:
                record = await decrypt_row(env, row.get("data", "")) or {}
            except Exception:
                continue
            admin = clean_string(
                record.get("name", ""), MAX_NODE_NAME).strip().lower()
            if not valid_node_name(admin):
                continue
            await enqueue_notification(
                env, admin, "operational_alert", title, body=body,
                href=_admin_path_rules.notification_href(
                    env, "?table=users"), source="signup",
                dedupe="signup-failure:" + key, ts=now,
                meta={"key": "signup-failure", "reason": reason,
                      "status": int(status), "source": source,
                      "account": name})
    except Exception:
        pass


async def _signup_refused(env, reason, status, claim=None, name="",
                          response=None, detail=""):
    if response is None:
        response = json_response(
            {"error": reason}, status=status,
            cache_control="no-store, max-age=0, must-revalidate")
    try:
        status = int(getattr(response, "status", status) or status)
    except (TypeError, ValueError):
        pass
    await ping_signup_failure(env, reason, status, claim=claim, name=name,
                              detail=detail)
    return response


async def _account_signup_problem(env, request):
    no_store = "no-store"
    if not _request_origin_allowed(env, request):
        return json_response(
            {"error": "origin_not_allowed"}, status=403,
            cache_control=no_store)
    claim = _account_signup_intent_claim(env, request)
    if not claim:
        return json_response(
            {"error": "signup_page_required"}, status=403,
            cache_control=no_store)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response(
            {"error": "invalid_json"}, status=400, cache_control=no_store)
    problem = data.get("problem") if isinstance(data, dict) else ""
    if problem not in SIGNUP_BROWSER_PROBLEMS:
        return json_response(
            {"error": "bad_request"}, status=400, cache_control=no_store)
    await ping_signup_failure(
        env, problem, 0, claim=claim, name=data.get("nodeName", ""),
        detail=data.get("detail", ""), source="browser")
    return json_response({"ok": True}, status=202, cache_control=no_store)


async def log_durable_object_abort(env, request, path, error):
    """Aggregate a Durable Object fetch the platform killed mid-request.

    On the free tier Cloudflare aborts long-running Durable Object requests
    with AbortError("Exceeded allowed duration in Durable Objects free
    tier."); a co-located DO blowing the isolate's limits surfaces instead as
    a generic AbortError("internal error; reference = …"). Both are transient
    and already handled by the caller (retry, then a marked 503). Fold them
    into one content-free row per minute so /status retains the realtime and
    plan-limit signals without filling error_log with one row per reconnecting
    user. We deliberately do not send Sentry events or retain paths, actors,
    exception text, or CF-Ray ids for this expected platform condition.
    """
    del request, path
    if _read_only(env):
        return
    try:
        now = int(Date.now())
        minute_ts = (now // STATUS_SAMPLE_WINDOW_MS) * STATUS_SAMPLE_WINDOW_MS
        duration_abort = (
            1 if "Exceeded allowed duration" in _safe_error_text(error) else 0)
        await ensure_schema(env)
        await d1_run(
            env,
            "INSERT INTO durable_object_abort_minute "
            "(minute_ts,aborts,duration_aborts,updated_at) VALUES (?,1,?,?) "
            "ON CONFLICT(minute_ts) DO UPDATE SET "
            "aborts=durable_object_abort_minute.aborts+1, "
            "duration_aborts=durable_object_abort_minute.duration_aborts+"
            "excluded.duration_aborts, updated_at=excluded.updated_at",
            minute_ts, duration_abort, now,
        )
    except BaseException:
        # Optional operational telemetry must never replace the already-safe
        # retryable response with a Worker exception.
        pass


def _error_chain(error, depth=8):
    seen = []
    while error is not None and len(seen) < depth and error not in seen:
        seen.append(error)
        error = error.__cause__ or error.__context__
    return seen


def _is_client_disconnect(error):
    return any(
        type(item).__name__ == "ClientDisconnected"
        or (isinstance(item, ConnectionResetError)
            and str(item) == "client disconnected")
        for item in _error_chain(error))


def _is_too_many_fields(error):
    return any(
        isinstance(item, ValueError)
        and "Max number of fields exceeded" in str(item)
        for item in _error_chain(error))


def _is_d1_platform_error(error):
    """Is this D1 itself failing, rather than our query being wrong?

    Only the platform's own fault envelope counts. A bad statement (no such
    table, constraint violation, syntax error) is our bug and must keep
    surfacing as a 500 with a Sentry stack trace.
    """
    text = _safe_error_text(error).lower()
    if "d1_error" not in text:
        return False
    return bool(
        _is_transient_d1_error(error)
        or any(marker in text for marker in _D1_SUSTAINED_MARKERS))


async def log_d1_unavailable(env, request, path, error):
    """Record a request D1 failed to serve without a Sentry event or a ping.

    _d1_read has already replayed the query once, so reaching here means the
    database — not the worker — is down or overloaded. Keep the D1 error_log
    row (its raw text lets /status separate database outages from code bugs),
    but raise no Sentry event and answer 503 so clients back off instead of
    retrying into it. Best-effort: _write_error_log never raises.
    """
    privacy_filter = globals().get("_privacy_safe_log_path")
    try:
        safe_path = (
            await privacy_filter(env, path)
            if callable(privacy_filter) else path
        )
    except BaseException:
        safe_path = "/repository-route-redacted"
    try:
        actor = await _error_log_actor(env, request)
    except BaseException:
        actor = ""
    try:
        ray = request.headers.get("cf-ray") or ""
    except BaseException:
        ray = ""
    await _write_error_log(
        env, 503, method_name(request), safe_path,
        "d1 unavailable: " + _safe_error_text(error)[:400], ray, actor,
        notify=False)


async def log_cron_error(env, path, message, error=None, failures=None):
    try:
        if failures is not None:
            failures.append(str(message or "")[:1000])
    except Exception:
        pass
    await log_error(
        env, 500, "scheduled", path, message, "", error=error)


def _safe_error_text(error):
    """Best-effort extraction of a readable error body from Python + JS errors."""
    if error is None:
        return ""
    try:
        message = str(error)
        if message and message != "[object Object]":
            return message
    except Exception:
        pass
    try:
        parts = []
        for key in ("name", "message", "code", "stack"):
            try:
                value = getattr(error, key)
            except Exception:
                continue
            if value is not None:
                parts.append(str(key) + ":" + str(value))
        if parts:
            return "; ".join(parts)
    except Exception:
        pass
    try:
        return repr(error)
    except Exception:
        return "[unrenderable error]"


# Ordered install funnel: every step the installer reports, in the order it runs.
# Used both to validate incoming events and to render the admin funnel in order.
INSTALL_DIAG_STEPS = (
    "start",    # installer launched
    "mirror",   # resolved an online mirror to clone from
    "deps",     # build prerequisites present / installed
    "fetch",    # repository cloned or updated
    "build",    # cmake configure + build
    "install",  # binary installed to ~/.local/bin
    "launch",   # first launch (or intentionally skipped)
    "done",     # whole install finished
)


# Known component labels for private vulnerability reports. Restricting the
# set prevents arbitrary strings from appearing in notification emails.
SECURITY_REPORT_COMPONENTS = frozenset({
    "identity",     # Ed25519 keys, signing
    "relay",        # Cloudflare relay / Durable Objects
    "mirroring",    # bare-git mirror fetch/serve
    "chat",         # encrypted relay chat
    "donations",    # Solana custody / sweep
    "website",      # forkmesh.com frontend / dashboard
    "client",       # desktop Qt node
    "other",        # anything else
})


def _sanitize_diag_field(value, max_length=64):
    # Coarse, non-identifying tokens only (platform/pm/distro/version/detail).
    # Strip to a safe charset so a crafted POST can't smuggle markup or control
    # characters into the admin HTML, and clamp the length.
    if not isinstance(value, str):
        value = "" if value is None else str(value)
    cleaned = "".join(
        c for c in value if c.isalnum() or c in " ._:+-,/()"
    ).strip()
    return cleaned[:max_length]


def _sanitize_feedback_text(value, max_length, allow_newlines=False):
    if not isinstance(value, str):
        value = "" if value is None else str(value)
    allowed = []
    for c in value:
        if c == "\t":
            allowed.append(c)
        elif allow_newlines and c == "\n":
            allowed.append(c)
        elif c >= " " and c != "\x7f":
            allowed.append(c)
    return "".join(allowed).strip()[:max_length]


def _feedback_fields(payload):
    """Normalize a bounded website feedback payload into stored columns."""
    if not isinstance(payload, dict):
        return None
    source = _sanitize_feedback_text(payload.get("source"), 32).lower()
    vote = _sanitize_feedback_text(payload.get("vote"), 16).lower()
    if source not in FEEDBACK_SOURCES or vote not in FEEDBACK_VOTES:
        return None
    if source in FEEDBACK_NOTE_PATHS:
        if vote != "feedback":
            return None
        message = _sanitize_feedback_text(
            payload.get("message"), FEEDBACK_MAX_MESSAGE,
            allow_newlines=True)
        if not message:
            return None
        return source, vote, FEEDBACK_NOTE_PATHS[source], message
    if vote not in ("like", "dislike"):
        return None
    # Feedback is a docs-only feature. Never accept an arbitrary URL, query,
    # private repository path, or search value into this plaintext metrics
    # column. Preserve only a bounded, anchor-like section id.
    raw_path = _sanitize_feedback_text(payload.get("path"), FEEDBACK_MAX_PATH)
    without_query = raw_path.split("?", 1)[0]
    base, separator, fragment = without_query.partition("#")
    path = "/docs/"
    if base.rstrip("/") == "/docs" and separator:
        fragment = fragment[:80]
        if fragment and all(
                char.isalnum() or char in "_-" for char in fragment):
            path += "#" + fragment
    message = ""
    if vote == "dislike":
        message = _sanitize_feedback_text(
            payload.get("message"), FEEDBACK_MAX_MESSAGE, allow_newlines=True)
    return source, vote, path, message


async def _enqueue_world_feedback_pings(env, message, now, dedupe,
                                        source="world"):
    """Best-effort admin Pings for one recorded lobby-kiosk submission."""
    rows = await d1_all(
        env, "SELECT data FROM users WHERE is_admin=1 LIMIT 20")
    for row in rows or []:
        try:
            record = await decrypt_row(env, row.get("data", "")) or {}
        except Exception:
            continue
        admin = clean_string(
            record.get("name", ""), MAX_NODE_NAME).strip().lower()
        if not valid_node_name(admin):
            continue
        try:
            await enqueue_notification(
                env, admin, "pending_inbox",
                "New website feedback" if source == "web"
                else "New World feedback",
                body=clean_string(message, 500),
                href=_admin_path_rules.notification_href(env),
                source="world-feedback",
                dedupe="world-feedback:" + dedupe, ts=now,
                meta={"feedbackSource": source},
            )
        except Exception:
            continue


def _install_diag_fields(payload):
    """Normalize a posted install-diag event into stored columns, or None.

    Pure (no I/O) so it can be unit-tested. Rejects anything outside the known
    step set; clamps/sanitizes every other field. Returns
    (run, step, ok, os, arch, pm, distro, version, detail) on success.
    """
    if not isinstance(payload, dict):
        return None
    step = payload.get("step")
    if step not in INSTALL_DIAG_STEPS:
        return None
    run = _sanitize_diag_field(payload.get("run"), 64)
    if not run:
        return None
    ok = 1 if payload.get("ok") in (1, True, "1", "true", "True") else 0
    return (
        run,
        step,
        ok,
        _sanitize_diag_field(payload.get("os"), 32),
        _sanitize_diag_field(payload.get("arch"), 32),
        _sanitize_diag_field(payload.get("pm"), 32),
        _sanitize_diag_field(payload.get("distro"), 32),
        _sanitize_diag_field(payload.get("version"), 48),
        _sanitize_diag_field(payload.get("detail"), 200),
    )


# A successful installer run ("done" step, ok) is celebrated: the World runs
# its firework show for this long (same window as a federated instance joining)
# and every platform admin gets one Ping per run.
WORLD_INSTALL_CELEBRATION_MS = 10 * 60 * 1000
MAX_WORLD_INSTALL_CELEBRATIONS = 8


async def _enqueue_install_celebration_pings(env, fields, now):
    """Best-effort admin Pings for one completed installer run."""
    run, _step, _ok, os_name, arch = fields[:5]
    platform = " · ".join(p for p in (os_name, arch) if p) or "unknown platform"
    rows = await d1_all(
        env, "SELECT data FROM users WHERE is_admin=1 LIMIT 20")
    for row in rows or []:
        try:
            record = await decrypt_row(env, row.get("data", "")) or {}
        except Exception:
            continue
        admin = clean_string(
            record.get("name", ""), MAX_NODE_NAME).strip().lower()
        if not valid_node_name(admin):
            continue
        await enqueue_notification(
            env, admin, "operational_alert",
            "New ForkMesh desktop installed \U0001F386",
            body=("Someone just installed the ForkMesh desktop with the "
                  "one-line installer (" + platform + "). The World is "
                  "running its firework show."),
            href="/world/", source="installer",
            dedupe="install-celebration:" + run,
            ts=now,
            meta={"platform": platform},
        )


async def install_diag_handler(env, request):
    # Anonymous, unauthenticated install telemetry from install.sh. Best-effort:
    # never errors out the caller (the installer fires these fire-and-forget). We
    # deliberately do not read or store the client IP / CF-Ray — see SCHEMA note.
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        payload = await bounded_json_request(request)
    except Exception:
        payload = None
    fields = _install_diag_fields(payload)
    if not fields:
        # Swallow malformed input rather than 4xx-ing the installer's background
        # curl; nothing actionable for the client to do.
        return json_response({"ok": True}, cache_control="no-store")
    try:
        await ensure_schema(env)
        await d1_run(
            env,
            """INSERT INTO install_diag
               (ts, run, step, ok, os, arch, pm, distro, version, detail)
               VALUES (?,?,?,?,?,?,?,?,?,?)""",
            int(Date.now()), *fields,
        )
        # Bound the table so this open endpoint can't grow D1 without limit.
        await d1_run(
            env,
            """DELETE FROM install_diag WHERE id NOT IN
               (SELECT id FROM install_diag ORDER BY id DESC LIMIT ?)""",
            MAX_INSTALL_DIAG,
        )
        if fields[1] == "done" and fields[2] == 1:
            # Whole install finished: Ping the admins; the World picks the run
            # up from /api/world/installs and starts its firework show.
            await _enqueue_install_celebration_pings(
                env, fields, int(Date.now()))
    except Exception:
        pass
    return json_response({"ok": True}, cache_control="no-store")


_marketplace_runtime = _LazyModule("marketplace_runtime")
_MarketplaceGovernanceRuntime = _marketplace_runtime.export("_MarketplaceGovernanceRuntime")
# Account-based Market star ratings and required improvement reviews
# (docs/MARKETPLACE_RATINGS.md): a pure route module plus its narrow adapter.
_MarketplaceReviewsRuntime = _marketplace_runtime.export("_MarketplaceReviewsRuntime")
marketplace_reviews = _LazyModule("marketplace_reviews")


def _marketplace_identifier(value, maximum=96):
    if not isinstance(value, str):
        return ""
    value = value.strip().lower()
    return value if len(value) <= maximum and re.fullmatch(
        r"[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*", value) else ""


def _package_install_events(payload):
    """Normalize a posted package-install report into rows, or None.

    Pure (no I/O) so it can be unit-tested. Returns
    ``(run, [(market, pkg, installed), ...])`` with identifiers validated,
    deduplicated and ordered, or None when the payload has no usable event.
    Clients that predate federated catalogs default to the first-party market.
    """
    if not isinstance(payload, dict):
        return None
    run = _sanitize_diag_field(payload.get("run"), 64)
    if not run:
        return None
    reported = payload.get("packages")
    if not isinstance(reported, list):
        return None
    states = {}
    for event in reported[:MAX_PACKAGE_INSTALL_EVENTS]:
        if not isinstance(event, dict):
            continue
        market = _marketplace_identifier(event.get("market") or "forkmesh")
        pkg = _marketplace_identifier(event.get("id"))
        if not market or not pkg:
            continue
        states[(market, pkg)] = 1 if event.get("installed") in (
            1, True, "1", "true", "True") else 0
    if not states:
        return None
    return run, [(*key, installed) for key, installed in sorted(states.items())]


async def package_install_counts(env):
    """Per-package active installs and cumulative downloads."""
    rows = await d1_all(
        env,
        "SELECT market, pkg, SUM(installed) AS installs, "
        "SUM(downloads) AS downloads FROM package_installs "
        "GROUP BY market, pkg",
    )
    counts = {}
    for row in rows or []:
        market = _marketplace_identifier(row.get("market"))
        pkg = clean_string(row.get("pkg"), 64)
        if not market or not pkg:
            continue
        counts.setdefault(market, {})[pkg] = {
            "installs": max(0, int(row.get("installs") or 0)),
            "downloads": max(0, int(row.get("downloads") or 0)),
        }
    return counts


PACKAGE_MEMBER_INSTALL_SQL = (
    ("accounts",
     "SELECT package AS pkg, COUNT(*) AS n FROM account_package_installs "
     "WHERE installed=1 GROUP BY package"),
    ("organizations",
     "SELECT plugin AS pkg, COUNT(*) AS n FROM org_plugin_installs "
     "GROUP BY plugin"),
)


def _merge_member_installs(counts, members):
    first = counts.setdefault("forkmesh", {})
    for field, rows in members.items():
        for row in rows or []:
            pkg = _marketplace_identifier(row.get("pkg"))
            if not pkg:
                continue
            entry = first.setdefault(pkg, {"installs": 0, "downloads": 0})
            entry[field] = max(0, int(row.get("n") or 0))
    for entry in first.values():
        for field, _ in PACKAGE_MEMBER_INSTALL_SQL:
            entry.setdefault(field, 0)
    return counts


async def package_member_installs(env):
    members = {}
    for field, sql in PACKAGE_MEMBER_INSTALL_SQL:
        try:
            members[field] = await d1_all(env, sql)
        except Exception:
            members[field] = []
    return members


async def package_installs_handler(env, request):
    """Marketplace install counts: GET reads them, POST reports them.

    Same privacy shape as install_diag — a rotating random client run id and
    the package id, with no account, IP address, or hostname stored. A removal
    clears the run's current state so it stops counting toward "installs", while
    "downloads" stays monotonic.
    """
    method = method_name(request)
    if method == "GET":
        await ensure_schema(env)
        counts = _merge_member_installs(
            await package_install_counts(env),
            await package_member_installs(env))
        return json_response({
            "ok": True,
            "packages": counts.get("forkmesh", {}),
            "marketplaces": counts,
            "observedAt": int(Date.now()),
            "privacy": (
                "Anonymous package counts only: a rotating per-client id and "
                "the package id, plus how many accounts and organizations have "
                "each package installed, as totals. "
                "No accounts, IP addresses, or hostnames are stored or exposed."
            ),
        }, cache_control="public, max-age=300",
           extra_headers={"x-content-type-options": "nosniff"})
    if method != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store",
            extra_headers={"allow": "GET, POST"})
    try:
        payload = await bounded_json_request(request, max_bytes=8 * 1024)
    except Exception:
        payload = None
    parsed = _package_install_events(payload)
    if not parsed:
        # Swallow malformed input rather than 4xx-ing a fire-and-forget report.
        return json_response({"ok": True}, cache_control="no-store")
    run, events = parsed
    try:
        await ensure_schema(env)
        now = int(Date.now())
        for market, pkg, installed in events:
            # Clients re-send their whole package set, so the cumulative
            # counter may only move on an actual not-installed -> installed
            # transition; SQLite evaluates the SET expressions against the row
            # as it was before the update, so package_installs.installed here
            # is the previous state. A removal just clears the current state,
            # which is why "downloads" never goes backwards and a repeated
            # report of an unchanged state is a no-op.
            await d1_run(
                env,
                """INSERT INTO package_installs
                   (run, market, pkg, ts, installed, downloads) VALUES (?,?,?,?,?,?)
                   ON CONFLICT(run, market, pkg) DO UPDATE SET
                     ts=excluded.ts,
                     downloads=package_installs.downloads
                               + CASE WHEN excluded.installed=1
                                       AND package_installs.installed=0
                                      THEN 1 ELSE 0 END,
                     installed=excluded.installed""",
                run, market, pkg, now, installed, installed,
            )
        # Bound the table so this open endpoint can't grow D1 without limit.
        await d1_run(
            env,
            """DELETE FROM package_installs WHERE rowid NOT IN
               (SELECT rowid FROM package_installs ORDER BY ts DESC LIMIT ?)""",
            MAX_PACKAGE_INSTALL_ROWS,
        )
    except Exception:
        pass
    return json_response({"ok": True}, cache_control="no-store")


async def package_rating_counts(env):
    """Per-package public rating aggregates, without exposing individual votes."""
    rows = await d1_all(
        env,
        "SELECT market, pkg, COUNT(*) AS ratings, AVG(rating) AS average "
        "FROM package_ratings GROUP BY market, pkg",
    )
    counts = {}
    for row in rows or []:
        market = _marketplace_identifier(row.get("market"))
        pkg = _marketplace_identifier(row.get("pkg"))
        ratings = max(0, int(row.get("ratings") or 0))
        if not market or not pkg or not ratings:
            continue
        average = max(1.0, min(5.0, float(row.get("average") or 0)))
        counts.setdefault(market, {})[pkg] = {
            "ratings": ratings,
            "average": round(average, 1),
        }
    return counts


async def package_ratings_handler(env, request):
    """Legacy anonymous Market rating aggregates; writes are retired (410)."""
    method = method_name(request)
    if method == "GET":
        await ensure_schema(env)
        counts = await package_rating_counts(env)
        return json_response({
            "ok": True,
            "packages": counts.get("forkmesh", {}),
            "marketplaces": counts,
            "observedAt": int(Date.now()),
            "privacy": (
                "Anonymous package ratings only: an opaque browser id and the "
                "package id. No accounts, IP addresses, or hostnames are stored "
                "or exposed. Changing a rating replaces the previous rating."
            ),
        }, cache_control="public, max-age=300",
           extra_headers={"x-content-type-options": "nosniff"})
    if method != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store",
            extra_headers={"allow": "GET, POST"})
    # Anonymous per-browser writes are retired: a Market rating now belongs
    # to a signed-in, email-verified account, and anything under five stars
    # must carry an improvement review (app/src/marketplace_reviews.py,
    # docs/MARKETPLACE_RATINGS.md). The rows already stored stay readable.
    return json_response({
        "ok": False,
        "error": "account_rating_required",
        "message": (
            "Sign in to rate this package. Ratings under five stars need a "
            "short review of what to improve."),
        "ratingsApi": "/api/market/reviews/{market}/{package}",
    }, status=410, cache_control="no-store",
       extra_headers={"x-content-type-options": "nosniff"})


async def feedback_handler(env, request):
    # Anonymous docs and lobby-kiosk feedback. This is intentionally
    # unauthenticated; the body is capped before JSON parsing and the table is
    # pruned after inserts so this open endpoint cannot grow D1 without limit.
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        raw = await request.text()
    except Exception:
        raw = ""
    if len(raw) > FEEDBACK_MAX_BODY:
        return json_response({"error": "payload_too_large"}, status=413,
                             cache_control="no-store")
    try:
        payload = json.loads(raw) if raw else None
    except Exception:
        payload = None
    fields = _feedback_fields(payload)
    if not fields:
        return json_response({"error": "invalid_feedback"}, status=400,
                             cache_control="no-store")

    source, vote, path, message = fields
    ip = _transient_client_address(request)
    # Retain only a broad category, never the browser's raw user-agent string.
    user_agent = _generalized_client_category(request)
    now = int(Date.now())
    try:
        await ensure_schema(env)
        ip_hash = await blind_index(env, ip) if ip else ""
        await d1_run(
            env,
            """INSERT INTO feedback (ts, source, vote, path, message, ip_hash, user_agent)
               VALUES (?,?,?,?,?,?,?)""",
            now, source, vote, path, message, ip_hash, user_agent,
        )
    except Exception:
        # The kiosk promises that "sent" means a durable record exists. Keep
        # the visitor's form open on storage failure so they can retry.
        return json_response({"error": "feedback_unavailable"}, status=503,
                             cache_control="no-store")

    try:
        await d1_run(
            env,
            """DELETE FROM feedback WHERE id NOT IN
               (SELECT id FROM feedback ORDER BY id DESC LIMIT ?)""",
            MAX_FEEDBACK,
        )
    except Exception:
        pass
    if source in FEEDBACK_NOTE_PATHS:
        # Include the time, message and one-way client index in the notification
        # identity. No raw address or browser fingerprint enters the Ping.
        dedupe = hashlib.sha256(
            (str(now) + "\n" + message + "\n" + ip_hash).encode("utf-8")
        ).hexdigest()[:24]
        try:
            await _enqueue_world_feedback_pings(
                env, message, now, dedupe, source)
        except Exception:
            # The feedback row is canonical. A broken push/email rail must not
            # make the recorded submission appear to have failed.
            pass
    return json_response({"ok": True}, cache_control="no-store")


def _validate_security_report(payload):
    """Validate and sanitize a vulnerability report payload. Pure (no I/O).

    Returns a normalized dict on success, or None if the payload is invalid.
    Accepted fields:
      title     (required, 1-200 chars)
      body      (required, 1-16 384 chars — the vulnerability description)
      component (required, one of SECURITY_REPORT_COMPONENTS)
      contact   (optional, max 254 chars — e.g. an email or handle)
    """
    if not isinstance(payload, dict):
        return None
    title = (payload.get("title") or "").strip()[:200]
    if not title:
        return None
    body = (payload.get("body") or "").strip()[:16384]
    if not body:
        return None
    component = (payload.get("component") or "").strip().lower()
    if component not in SECURITY_REPORT_COMPONENTS:
        return None
    contact = (payload.get("contact") or "").strip()[:254]
    return {"title": title, "body": body, "component": component, "contact": contact}


async def security_report_handler(env, request):
    """Accept a private vulnerability report via POST /api/security/report.

    Unauthenticated: anyone can submit a report. The payload is AES-GCM
    encrypted before storage so only the operator (with DATA_KEY) can read it.
    An email is sent to SECURITY_EMAIL (or security@forkmesh.com) if configured.
    Always returns 200 {"ok": true} to avoid leaking internal state to probers.
    """
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        payload = await bounded_json_request(request)
    except Exception:
        payload = None
    report = _validate_security_report(payload)
    if not report:
        return json_response({"error": "invalid_report"}, status=400)
    try:
        await ensure_schema(env)
        encrypted = await encrypt_row(env, {
            "title": report["title"],
            "body": report["body"],
            "component": report["component"],
            "contact": report["contact"],
            "ts": int(Date.now()),
        })
        await d1_run(
            env,
            "INSERT INTO security_reports (ts, data) VALUES (?, ?)",
            int(Date.now()), encrypted,
        )
        await d1_run(
            env,
            """DELETE FROM security_reports WHERE id NOT IN
               (SELECT id FROM security_reports ORDER BY id DESC LIMIT ?)""",
            MAX_SECURITY_REPORTS,
        )
    except Exception:
        pass
    # Best-effort email notification to the security team.
    try:
        dest = (getattr(env, "SECURITY_EMAIL", "") or "security@forkmesh.com").strip()
        contact_line = ("Contact: " + report["contact"] + "\n") if report["contact"] else ""
        subject = "[ForkMesh Security] " + report["title"]
        text = (
            "A private vulnerability report was submitted via forkmesh.com.\n\n"
            "Component: " + report["component"] + "\n"
            + contact_line +
            "\n" + report["body"]
        )
        await _send_email(
            env, dest, subject, text, email_kind="security_report")
    except Exception:
        pass
    return json_response({"ok": True}, cache_control="no-store")


async def _security_scan_owner_authorization(env, request, owner):
    """Return the normal repository-owner auth mode, or an empty string."""

    if await _authorize_owner(env, request, owner):
        return "owner_signature"
    ok, _ = await _authorize_owner_account(
        env, owner, {}, request, allow_admin=False)
    return "owner_session" if ok else ""


async def _security_scan_repository_row(env, owner, repo):
    """Resolve an existing repository without putting its name in scan storage."""

    await ensure_schema(env)
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env,
        "SELECT is_private FROM repositories WHERE key_bi=?",
        repo_bi,
    )
    return repo_bi, row


SECURITY_SCAN_DAILY_MS = 24 * 60 * 60 * 1000
SECURITY_SCAN_LEASE_MS = 20 * 60 * 1000
SECURITY_SCAN_LEASE_TOKEN_RE = re.compile(r"^[A-Za-z0-9_-]{43}$")


async def _security_scan_catalog_record(env, owner, repo):
    await ensure_schema(env)
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env,
        "SELECT is_private,data FROM repositories WHERE key_bi=?",
        repo_bi,
    )
    if not row:
        return repo_bi, None
    try:
        record = await decrypt_row(env, row.get("data"))
    except Exception:
        return repo_bi, None
    if (
        not isinstance(record, dict)
        or str(record.get("owner") or "").lower() != owner.lower()
        or str(record.get("name") or "").lower() != repo.lower()
        or record.get("visibility") not in ("public", "private")
    ):
        return repo_bi, None
    return repo_bi, record


async def _security_scan_lease_authorization(env, request, repo_bi):
    authorization = str(request.headers.get("authorization") or "")
    if not authorization.startswith("Bearer "):
        return None
    token = authorization[7:].strip()
    if not SECURITY_SCAN_LEASE_TOKEN_RE.fullmatch(token):
        return None
    token_bi = await blind_index(env, "security-scan-lease:" + token)
    row = await d1_first(
        env,
        "SELECT lease_token_bi,status,expires_at,data "
        "FROM repo_security_scan_leases WHERE repo_bi=?",
        repo_bi,
    )
    if (
        not row
        or row.get("status") != "leased"
        or int(row.get("expires_at") or 0) <= int(Date.now())
        or not hmac.compare_digest(
            str(row.get("lease_token_bi") or ""), token_bi)
    ):
        return None
    try:
        data = await decrypt_row(env, row.get("data"))
    except Exception:
        return None
    if (
        not isinstance(data, dict)
        or not re.fullmatch(r"[0-9a-f]{40}", str(data.get("commit") or ""))
    ):
        return None
    return {"tokenBi": token_bi, "commit": data["commit"]}


repository_security_scan_lease_handler = _route_handlers.export("repository_security_scan_lease_handler")


async def _security_scan_review_overlays(env, repo_bi, scan_ids):
    scan_ids = [
        str(value or "").lower()
        for value in scan_ids
        if security_scan_ingest.valid_scan_id(value)
    ][:security_scan_ingest.MAX_HISTORY_RESPONSE]
    if not scan_ids:
        return []
    rows = await d1_all(
        env,
        "SELECT scan_id, finding_id, reviewed_at, data "
        "FROM repo_security_scan_reviews WHERE repo_bi=? AND scan_id IN ("
        + ",".join("?" for _ in scan_ids) + ")",
        repo_bi,
        *scan_ids,
    )
    overlays = []
    for row in rows or []:
        try:
            saved = await decrypt_row(env, row.get("data"))
        except Exception:
            continue
        status = security_scan_ingest.normalize_finding_status(
            (saved or {}).get("status"))
        finding_id = str(row.get("finding_id") or "").lower()
        scan_id = str(row.get("scan_id") or "").lower()
        if (
            scan_id not in scan_ids
            or not security_scan_ingest.valid_finding_id(finding_id)
            or not status
        ):
            continue
        overlays.append({
            "scanId": scan_id,
            "findingId": finding_id,
            "status": status,
            "reviewedAt": int(row.get("reviewed_at") or 0),
        })
    return overlays


async def _security_scan_reviewer_authorization(
        env, request, owner, repo, data=None):
    actor = await _authed_account_name(env, request, data)
    owner_auth = await _security_scan_owner_authorization(
        env, request, owner)
    reviewer = bool(
        actor and (
            await _has_role(env, actor, "security_reviewer")
            or await _has_role(
                env, actor, "security_reviewer", "repository",
                owner + "/" + repo)
        )
    )
    if owner_auth:
        return actor or owner, "owner"
    if reviewer:
        return actor, "security_reviewer"
    return actor, ""


async def repository_security_scan_queue_handler(env, request):
    """Retired central fan-out endpoint; native repository leases replaced it."""
    del env, request
    return json_response({
        "error": "central_scan_queue_retired",
        "nativePath": (
            "/api/repo/{owner}/{repo}/security-scans/lease"),
        "notice": (
            "Daily scans are leased to authenticated mirror nodes. "
            "No central catalog credential or repository-enumeration queue "
            "exists."
        ),
    }, status=410, cache_control="no-store")


async def repository_security_scans_handler(
        env, request, owner, repo, action):
    """Ingest and read bounded, redacted per-repository security scans.

    A native mirror scanner authenticates with a short-lived, repository- and
    commit-bound lease. An owner may instead use the existing signed owner
    query/session for a manual scan. Authentication happens before the ingest
    body is read.

    Public repositories expose only the compact clipboard. Rich artifacts and
    every view of a private repository require normal owner authorization;
    unauthorized private/missing repositories both return the same 404 shape.
    """

    method = method_name(request)
    repository_name = owner + "/" + repo

    if action == "lease":
        return await repository_security_scan_lease_handler(
            env, request, owner, repo)

    if action == "ingest":
        if method != "POST":
            return json_response(
                {"error": "method_not_allowed"},
                status=405,
                cache_control="no-store",
                extra_headers={"allow": "POST"},
            )
        # Never redirect a credential-bearing request from HTTP: a redirect can
        # replay Authorization to a different origin. Production publishing is
        # HTTPS-only and fails closed before reading either the header or body.
        if urlparse(request.url).scheme.lower() != "https":
            return json_response(
                {"error": "https_required"},
                status=400,
                cache_control="no-store",
            )
        preliminary_repo_bi = await blind_index(
            env, owner + "/" + repo)
        lease = await _security_scan_lease_authorization(
            env, request, preliminary_repo_bi)
        auth_mode = "native_mirror_lease" if lease else (
            await _security_scan_owner_authorization(env, request, owner))
        if not auth_mode:
            return json_response(
                {"error": "unauthorized"},
                status=401,
                cache_control="no-store",
                extra_headers={"www-authenticate": "Bearer"},
            )

        # Resolve visibility before reading the artifact body. A guessed private
        # name and a missing repository retain the same 404.
        try:
            repo_bi, repo_row = await _security_scan_repository_row(
                env, owner, repo)
            if not repo_row:
                return json_response(
                    {"error": "not_found"},
                    status=404,
                    cache_control="no-store",
                )
            is_private = await _repo_is_private(env, owner, repo)
        except Exception:
            return json_response(
                {"error": "temporarily_unavailable"},
                status=503,
                cache_control="no-store",
            )
        content_type = (
            request.headers.get("content-type") or "").split(";", 1)[0].strip()
        if content_type.lower() != "application/json":
            return json_response(
                {"error": "content_type_required"},
                status=415,
                cache_control="no-store",
            )
        try:
            announced = int(request.headers.get("content-length") or 0)
        except (TypeError, ValueError):
            announced = 0
        if announced > security_scan_ingest.MAX_INGEST_BYTES:
            return json_response(
                {"error": "payload_too_large"},
                status=413,
                cache_control="no-store",
            )
        try:
            raw = await request.text()
        except Exception:
            raw = ""
        if len(raw.encode("utf-8")) > security_scan_ingest.MAX_INGEST_BYTES:
            return json_response(
                {"error": "payload_too_large"},
                status=413,
                cache_control="no-store",
            )
        try:
            payload = json.loads(raw)
            envelope = security_scan_ingest.validate_ingest_envelope(
                payload, expected_repository=repository_name)
        except (json.JSONDecodeError, security_scan_ingest.ScanEnvelopeError):
            return json_response(
                {"error": "invalid_security_scan"},
                status=400,
                cache_control="no-store",
            )
        if lease and not hmac.compare_digest(
            str(envelope["rich"]["repository"]["commit"] or "").lower(),
            lease["commit"],
        ):
            return json_response(
                {"error": "leased_commit_mismatch"},
                status=409,
                cache_control="no-store",
            )

        try:
            async def run(sql, *args):
                return await d1_run(env, sql, *args)

            async def encrypt(value):
                return await encrypt_row(env, value)

            scan_id = await security_scan_ingest.store_scan(
                run,
                encrypt,
                repo_bi,
                envelope,
                int(Date.now()),
            )
            if lease:
                await d1_run(
                    env,
                    "UPDATE repo_security_scan_leases SET "
                    "lease_token_bi='',status='completed',expires_at=0,"
                    "next_attempt_at=0,completed_scan_id=?,updated_at=? "
                    "WHERE repo_bi=? AND lease_token_bi=? AND status='leased'",
                    scan_id, int(Date.now()), repo_bi, lease["tokenBi"],
                )
            # The audit contains no report, repository path, commit, finding,
            # token, or request body. target is converted to a blind token by
            # _audit_sensitive_action.
            await _audit_sensitive_action(
                env,
                owner,
                "repository.security_scan_ingest",
                "repository",
                repository_name,
                "success",
                {
                    "status": envelope["rich"]["status"],
                    "authMode": auth_mode,
                    "historyLimit":
                        security_scan_ingest.MAX_HISTORY_PER_REPOSITORY,
                },
            )
        except Exception:
            # Do not log the request, bearer token, response body, or artifact.
            # The native runner retains its local artifact and retries temporary
            # failures, while the deterministic scan id makes re-ingest safe.
            return json_response(
                {"error": "temporarily_unavailable"},
                status=503,
                cache_control="no-store",
            )
        return json_response(
            {
                "ok": True,
                "stored": True,
                "scanId": scan_id,
                "status": envelope["rich"]["status"],
            },
            status=202,
            cache_control="no-store",
        )

    if action == "triage":
        if method not in ("GET", "PATCH"):
            return json_response(
                {"error": "method_not_allowed"},
                status=405,
                cache_control="no-store",
                extra_headers={"allow": "GET, PATCH"},
            )
        data = {}
        if method == "PATCH":
            try:
                data = await bounded_json_request(request)
            except Exception:
                return json_response(
                    {"error": "invalid_json"},
                    status=400,
                    cache_control="no-store",
                )
        try:
            repo_bi, repo_row = await _security_scan_repository_row(
                env, owner, repo)
        except Exception:
            return json_response(
                {"error": "temporarily_unavailable"},
                status=503,
                cache_control="no-store",
            )
        if not repo_row:
            return json_response(
                {"error": "not_found"}, status=404, cache_control="no-store")
        actor, review_role = await _security_scan_reviewer_authorization(
            env, request, owner, repo, data)
        is_private = await _repo_is_private(env, owner, repo)
        if not review_role:
            if actor:
                await _audit_sensitive_action(
                    env, actor, "repository.security_scan_triage",
                    "repository", repository_name, "denied",
                    {"reason": "review_role_required"})
            return json_response(
                {"error": "not_found" if is_private else "forbidden"},
                status=404 if is_private else 403,
                cache_control="no-store",
            )

        params = parse_qs(urlparse(request.url).query)
        requested_scan_id = str(
            data.get("scanId")
            if method == "PATCH"
            else params.get("scanId", [""])[0]
        ).strip().lower()
        if requested_scan_id and not security_scan_ingest.valid_scan_id(
                requested_scan_id):
            return json_response(
                {"error": "invalid_scan_id"},
                status=400,
                cache_control="no-store",
            )

        async def all_rows(sql, *args):
            return await d1_all(env, sql, *args)

        async def decrypt(value):
            return await decrypt_row(env, value)

        records = await security_scan_ingest.load_scans(
            all_rows,
            decrypt,
            repo_bi,
            repository_name,
            security_scan_ingest.MAX_HISTORY_RESPONSE,
        )
        record = next(
            (
                item for item in records
                if not requested_scan_id
                or item.get("scanId") == requested_scan_id
            ),
            None,
        )
        if not record:
            return json_response(
                {"error": "not_found"}, status=404, cache_control="no-store")

        if method == "PATCH":
            finding_id = str(data.get("findingId") or "").strip().lower()
            status = security_scan_ingest.normalize_finding_status(
                data.get("status"))
            if (
                not security_scan_ingest.valid_finding_id(finding_id)
                or not status
            ):
                return json_response(
                    {"error": "invalid_finding_review"},
                    status=400,
                    cache_control="no-store",
                )
            findings = record["envelope"]["rich"]["findings"]
            if not any(
                    str(item.get("id") or "").lower() == finding_id
                    for item in findings):
                return json_response(
                    {"error": "not_found"},
                    status=404,
                    cache_control="no-store",
                )
            now = int(Date.now())
            reviewer_bi = await blind_index(env, actor)
            note = clean_string(data.get("note", ""), 500)
            encrypted = await encrypt_row(env, {
                "status": status,
                "note": note,
                "reviewedAt": now,
                "reviewRole": review_role,
            })
            await d1_run(
                env,
                "INSERT INTO repo_security_scan_reviews "
                "(repo_bi, scan_id, finding_id, reviewer_bi, reviewed_at, "
                "data) VALUES (?,?,?,?,?,?) "
                "ON CONFLICT(repo_bi,scan_id,finding_id) DO UPDATE SET "
                "reviewer_bi=excluded.reviewer_bi, "
                "reviewed_at=excluded.reviewed_at, data=excluded.data",
                repo_bi, record["scanId"], finding_id, reviewer_bi, now,
                encrypted,
            )
            await _audit_sensitive_action(
                env, actor, "repository.security_scan_triage",
                "repository", repository_name, "success",
                {
                    "status": status,
                    "reviewRole": review_role,
                    "scanIdPrefix": record["scanId"][:12],
                    "findingId": finding_id,
                },
            )

        overlays = await _security_scan_review_overlays(
            env, repo_bi, [record["scanId"]])
        reviewed = security_scan_ingest.apply_review_overlays(
            record, overlays)
        rich = reviewed["envelope"]["rich"]
        clipboard = reviewed["envelope"]["clipboard"]
        return json_response({
            "ok": True,
            "repository": repository_name,
            "canReview": True,
            "reviewRole": review_role,
            "scanId": reviewed["scanId"],
            "commitHash": rich["repository"]["commit"],
            "reviewStatus": clipboard["reviewStatus"],
            "falsePositiveStatus": clipboard["falsePositiveStatus"],
            "findings": [{
                "id": item["id"],
                "category": item["category"],
                "severity": item["severity"],
                "ruleId": item["ruleId"],
                "path": item["path"],
                "line": item["line"],
                "summary": item["summary"],
                "recommendation": item["recommendation"],
                "falsePositiveStatus": item["falsePositiveStatus"],
            } for item in rich["findings"]],
        }, cache_control="no-store")

    if action not in ("latest", "history"):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    if method != "GET":
        return json_response(
            {"error": "method_not_allowed"},
            status=405,
            cache_control="no-store",
            extra_headers={"allow": "GET"},
        )

    try:
        repo_bi, repo_row = await _security_scan_repository_row(
            env, owner, repo)
    except Exception:
        return json_response(
            {"error": "temporarily_unavailable"},
            status=503,
            cache_control="no-store",
        )
    if not repo_row:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")

    owner_auth = await _security_scan_owner_authorization(env, request, owner)
    # Migration 0011 defaulted historical rows to is_private=0. The signed,
    # encrypted catalog record is the authority; missing/malformed visibility
    # therefore fails closed just like every other repository read surface.
    is_private = await _repo_is_private(env, owner, repo)
    if is_private and not owner_auth:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")

    params = parse_qs(urlparse(request.url).query)
    detail = params.get("detail", ["clipboard"])[0]
    if detail not in ("clipboard", "rich"):
        return json_response(
            {"error": "invalid_detail"}, status=400, cache_control="no-store")
    include_rich = detail == "rich"
    if include_rich and not owner_auth:
        return json_response(
            {"error": "owner_authorization_required"},
            status=403,
            cache_control="no-store",
        )
    requested_limit = (
        1 if action == "latest" else
        security_scan_ingest.history_limit(
            params.get("limit", ["10"])[0]))

    async def all_rows(sql, *args):
        return await d1_all(env, sql, *args)

    async def decrypt(value):
        return await decrypt_row(env, value)

    try:
        records = await security_scan_ingest.load_scans(
            all_rows,
            decrypt,
            repo_bi,
            repository_name,
            requested_limit,
        )
        overlays = await _security_scan_review_overlays(
            env, repo_bi, [record.get("scanId") for record in records])
        records = [
            security_scan_ingest.apply_review_overlays(record, overlays)
            for record in records
        ]
    except Exception:
        return json_response(
            {"error": "temporarily_unavailable"},
            status=503,
            cache_control="no-store",
        )
    if not records:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")

    visibility = "owner_redacted" if include_rich else "public_clipboard"
    result = {
        "ok": True,
        "repository": repository_name,
        "visibility": visibility,
    }
    if action == "latest":
        result["latest"] = security_scan_ingest.scan_projection(
            records[0], include_rich=include_rich)
    else:
        result["history"] = [
            security_scan_ingest.scan_projection(
                record, include_rich=include_rich)
            for record in records
        ]
        result["count"] = len(records)
    return json_response(result, cache_control="no-store")


def _admin_path(env):
    # Dynamic, secret admin URL segment. Set ADMIN_PATH in Cloudflare vars.
    if instance_features.branded(env):
        return _admin_path_rules.private_segment(env)
    return str(getattr(env, "ADMIN_PATH", "") or "").strip("/")


async def admin_stats(env):
    # Cheap snapshot for the dashboard so the operator can watch whether Durable
    # Object load is under control: live hosts/clients (the things that hold a DO
    # open) plus catalog size and recent error volume. All from D1 + one count.
    await ensure_schema(env)
    cutoff = int(Date.now()) - HOST_PRESENCE_STALE_MS
    try:
        await d1_run(env, "DELETE FROM host_presence WHERE ts < ?", cutoff)
    except Exception:
        pass
    async def compute():
        repo_count = await _repositories_count(env)
        host_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM host_presence WHERE ts >= ?",
            cutoff,
        )
        day_ago = int(Date.now()) - 24 * 60 * 60 * 1000
        err_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM error_log WHERE ts >= ?", day_ago,
        )
        err_total_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM error_log")
        # Installs started in the last 24h = distinct anonymous runs that
        # reported the opening "start" step. Best-effort; the table may not
        # exist on a fresh DB. The unary + keeps the planner off the run
        # index, which walked every install_diag row to count DISTINCT, and
        # on the ts range instead.
        try:
            inst_row = await d1_first(
                env,
                "SELECT COUNT(DISTINCT +run) AS n FROM install_diag "
                "WHERE step='start' AND ts >= ?",
                day_ago,
            )
        except Exception:
            inst_row = None
        return {
            "repos": int(repo_count or 0),
            "hosts": int((host_row or {}).get("n", 0) or 0),
            "clients": await _flagship_client_count(env),
            "installs_24h": int((inst_row or {}).get("n", 0) or 0),
            "errors_24h": int((err_row or {}).get("n", 0) or 0),
            "errors_total": int((err_total_row or {}).get("n", 0) or 0),
        }

    # Every admin page view paid these counts; one colo-wide copy serves the
    # console for the read guard's TTL.
    shared = globals().get("d1_shared_read")
    return await (shared(env, "admin-stats", compute) if shared else compute())


async def install_diag_summary(env):
    # Aggregate the anonymous install events into an install funnel plus coarse
    # platform / package-manager / distro breakdowns, over the retained window.
    # All counts are over DISTINCT runs so one chatty install counts once.
    await ensure_schema(env)
    since = int(Date.now()) - INSTALL_DIAG_RETAIN_MS
    funnel_rows = await d1_all(
        env,
        """SELECT step,
                  COUNT(DISTINCT run) AS runs,
                  COUNT(DISTINCT CASE WHEN ok=1 THEN run END) AS ok_runs,
                  COUNT(DISTINCT CASE WHEN ok=0 THEN run END) AS fail_runs
             FROM install_diag WHERE ts >= ? GROUP BY step""",
        since,
    )
    by_step = {str(r.get("step", "")): r for r in funnel_rows}
    funnel = []
    for step in INSTALL_DIAG_STEPS:
        r = by_step.get(step) or {}
        funnel.append({
            "step": step,
            "runs": int(r.get("runs", 0) or 0),
            "ok": int(r.get("ok_runs", 0) or 0),
            "failed": int(r.get("fail_runs", 0) or 0),
        })
    total_row = await d1_first(
        env, "SELECT COUNT(DISTINCT run) AS n FROM install_diag WHERE ts >= ?",
        since,
    )
    done_row = await d1_first(
        env,
        "SELECT COUNT(DISTINCT run) AS n FROM install_diag "
        "WHERE step='done' AND ok=1 AND ts >= ?",
        since,
    )

    async def _breakdown(expr):
        return await d1_all(
            env,
            "SELECT COALESCE(NULLIF(%s,''),'(unknown)') AS k, "
            "COUNT(DISTINCT run) AS runs FROM install_diag WHERE ts >= ? "
            "GROUP BY k ORDER BY runs DESC LIMIT 20" % expr,
            since,
        )

    platforms = await _breakdown("os || ' ' || arch")
    managers = await _breakdown("pm")
    distros = await _breakdown("distro")
    return {
        "total": int((total_row or {}).get("n", 0) or 0),
        "completed": int((done_row or {}).get("n", 0) or 0),
        "funnel": funnel,
        "platforms": [(str(r.get("k", "")), int(r.get("runs", 0) or 0)) for r in platforms],
        "managers": [(str(r.get("k", "")), int(r.get("runs", 0) or 0)) for r in managers],
        "distros": [(str(r.get("k", "")), int(r.get("runs", 0) or 0)) for r in distros],
    }


def _admin_csrf_token(env):
    # A deterministic CSRF token derived from at-rest secrets. It is only rendered
    # inside the admin HTML after the requester names an is_admin account, so a
    # cross-site forged POST cannot include it without first loading the page.
    secret = (str(getattr(env, "ADMIN_PASS", "") or "") + "|" +
              str(getattr(env, "DATA_KEY", "") or "")).encode()
    return hmac.new(secret, b"forkmesh-admin-csrf-v1", "sha256").hexdigest()


def _admin_csrf_ok(env, form):
    submitted = (form.get("csrf", [""]) or [""])[0]
    return bool(submitted) and hmac.compare_digest(
        submitted, _admin_csrf_token(env))


ADMIN_SESSION_COOKIE = "forkmesh_admin"


def _admin_session_secret(env):
    return (str(getattr(env, "ADMIN_PASS", "") or "") + "|" +
            str(getattr(env, "DATA_KEY", "") or "")).encode()


def _admin_session_signature(env, admin, expires):
    canonical = ("forkmesh-admin-session-v1\n" + admin + "\n" +
                 str(expires)).encode()
    return hmac.new(_admin_session_secret(env), canonical, "sha256").hexdigest()


def _admin_session_cookie(env, admin):
    admin = clean_string(admin or "", MAX_NODE_NAME).lower()
    expires = int(Date.now()) + ADMIN_SESSION_TTL_MS
    sig = _admin_session_signature(env, admin, expires)
    return (
        ADMIN_SESSION_COOKIE + "=" + admin + "." + str(expires) + "." + sig +
        "; Path=/; Max-Age=%d; HttpOnly; Secure; SameSite=Lax"
        % int(ADMIN_SESSION_TTL_MS / 1000)
    )


def _clear_admin_session_cookie():
    return (ADMIN_SESSION_COOKIE +
            "=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax")


def _cookie_value(request, name):
    header = request.headers.get("cookie") or ""
    for part in header.split(";"):
        key, sep, value = part.strip().partition("=")
        if sep and key == name:
            return value
    return ""


def _admin_session_valid(env, request, admin):
    token = _cookie_value(request, ADMIN_SESSION_COOKIE)
    parts = token.split(".")
    if len(parts) != 3:
        return False
    token_admin, expires, sig = parts
    if not hmac.compare_digest(token_admin, admin):
        return False
    try:
        expires_ms = int(expires)
    except (TypeError, ValueError):
        return False
    if expires_ms < int(Date.now()):
        return False
    expected = _admin_session_signature(env, admin, expires_ms)
    return hmac.compare_digest(sig, expected)


def _admin_cookie_name(request):
    # The signed admin cookie embeds the admin name as its first segment;
    # _admin_session_valid verifies the HMAC actually binds that name.
    return clean_string(
        _cookie_value(request, ADMIN_SESSION_COOKIE).split(".")[0],
        MAX_NODE_NAME).lower()


async def _check_admin_page_auth(env, request):
    # The same revocable HttpOnly account session used by browser APIs protects
    # this page. Platform-admin status is checked live, so logout, password
    # reset, account disable and role removal take effect immediately. The
    # historical stateless admin cookie is deliberately not accepted.
    token = _cookie_value(request, ACCOUNT_SESSION_COOKIE)
    _, rec, _ = await _account_session_lookup(env, token)
    admin = clean_string(
        (rec or {}).get("name", ""), MAX_NODE_NAME).lower()
    return bool(admin and await _is_admin(env, admin))


async def _account_cookie_name(env, request):
    token = _cookie_value(request, ACCOUNT_SESSION_COOKIE)
    return await _account_session_token_name(env, token)


def _admin_query(admin):
    admin = clean_string(admin or "", MAX_NODE_NAME).lower()
    return "admin=" + quote(admin) if admin else ""


def _admin_href(admin_query, **params):
    parts = [admin_query] if admin_query else []
    for key, value in params.items():
        if value is None or value == "":
            continue
        parts.append(quote(str(key)) + "=" + quote(str(value)))
    return "?" + "&amp;".join(parts)


