async def _admin_set_password(env, name, password):
    # Reset a user account's login password. The is_admin-gated admin page
    # supplies a node name and a new password; we PBKDF2-hash it and overwrite
    # pass_salt / pass_hash on the encrypted account record, leaving
    # email/solana/etc intact.
    name = clean_string(name or "", MAX_NODE_NAME).lower()
    if not name:
        return "Set password failed: a node name is required."
    if len(password or "") < 8:
        return "Set password failed: password must be at least 8 characters."
    password = password[:256]
    name_bi, rec = await _account_row(env, name)
    if not rec:
        return "Set password failed: no account named '%s'." % name
    salt, phash = await hash_password(password)
    rec["pass_salt"] = salt
    rec["pass_hash"] = phash
    rec.setdefault("status", "active")
    await _save_account(env, name_bi, rec)
    await _account_revoke_sessions(env, name_bi)
    return "Password updated for '%s'. The user can log in with it now." % name


async def _admin_resend_verification(env, request, name):
    # Re-send the email-confirmation link for a user account from the admin page.
    # Mirrors the self-service resendVerification path in the account-update
    # endpoint: send via Mailtrap when configured, otherwise fall back to the
    # pending_verifications queue for manual admin verification.
    name = clean_string(name or "", MAX_NODE_NAME).lower()
    if not name:
        return "Resend verify email failed: a node name is required."
    name_bi, rec = await _account_row(env, name)
    if not rec:
        return "Resend verify email failed: no account named '%s'." % name
    email = rec.get("email", "")
    if not email:
        return "Resend verify email failed: '%s' has no email on file." % name
    if rec.get("email_verified"):
        return "'%s' is already verified; no email sent." % name
    sent = await _send_verification_email(env, request, name, email)
    if sent:
        return "Verification email re-sent to %s for '%s'." % (email, name)
    await _enqueue_verification(env, name_bi, name, email)
    return ("Email is not configured; queued '%s' for manual verification "
            "instead." % name)


async def _admin_console_request_ownership(env, target, owner):
    # Operator-console counterpart to _admin_request_ownership: the operator is
    # already authenticated via Basic Auth + CSRF for this whole page, so no
    # node-key signature is needed here. Still only PARKS a pending marker —
    # the transfer completes only once the target node's own signed heartbeat
    # decision (approve/deny) comes back, same as the signed API path.
    target = clean_string(target or "", MAX_NODE_NAME).strip().lower()
    owner = clean_string(owner or "", MAX_NODE_NAME).strip().lower()
    if not target or not owner:
        return "Ownership request failed: both a node and a new owner are required."
    if not valid_node_name(owner):
        return "Ownership request failed: '%s' is not a valid account name." % owner
    owner_bi, owner_rec = await _account_row(env, owner)
    if not owner_rec or owner_rec.get("status") != "active":
        return "Ownership request failed: no active account named '%s'." % owner
    ok, result = await _park_ownership_transfer(env, target, owner)
    if not ok:
        return "Ownership request failed for '%s': %s." % (target, result)
    if result.get("alreadyOwned"):
        return "'%s' is already owned by '%s'." % (target, owner)
    return ("Ownership transfer requested: '%s' now needs to approve/deny from "
            "its own client before '%s' takes ownership." % (target, owner))


async def _admin_error_create_bot_task(env, form, requester):
    """Create an organization task assigned to Bot from an error-log entry."""
    raw_id = form.get("error_id", [""])[0]
    rowid = int(raw_id) if str(raw_id).isdigit() else 0
    if rowid > 0:
        row = await d1_first(
            env,
            "SELECT status,method,path,message,actor FROM error_log "
            "WHERE rowid=?",
            rowid,
        )
        if not row:
            return "Create bot task failed: that error row is gone.", {}
        status = str(row.get("status") or "")
        method = str(row.get("method") or "").upper()
        path = str(row.get("path") or "")
        message = str(row.get("message") or "")
        users = str(row.get("actor") or "").strip().lower() or "anonymous"
        occurrences = 1
    else:
        status = str(form.get("group_status", [""])[0])[:12]
        method = str(form.get("group_method", [""])[0])[:12].upper()
        path = str(form.get("group_path", [""])[0])[:2000]
        message = str(form.get("group_message", [""])[0])[:1000]
        users = clean_string(form.get("group_users", [""])[0], 300) or "—"
        if not status or not method:
            return "Create bot task failed: invalid error group.", {}
        count_row = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM error_log "
            "WHERE CAST(status AS TEXT)=? AND UPPER(method)=? "
            "AND path=? AND message=?",
            status, method, path, message,
        )
        occurrences = int((count_row or {}).get("n") or 0)
    summary = " ".join(str(message or "").split())
    title = "Investigate %s %s %s" % (
        status or "error", method or "—", path or "—")
    if summary:
        title = title + " — " + summary
    # source != "forkbot" skips _forkbot_attributed_body's chat footer, so the
    # attribution the merged issue needs is written here.
    filed_by = clean_string(requester or "", MAX_NODE_NAME).strip().lower()
    body = (
        "Filed from the platform administration error log%s.\n\n"
        "- Status: %s\n"
        "- Method: %s\n"
        "- Path: %s\n"
        "- Related user(s): %s\n"
        "- Logged occurrences: %d\n\n"
        "Message:\n\n%s\n"
    ) % (
        (" by @" + filed_by) if filed_by else "",
        status or "—", method or "—", path or "—", users,
        occurrences, str(message or "—"),
    )
    # Content stays out of the audit trail; this bounded digest still tells
    # two tasks filed for different errors apart.
    details = {
        "occurrences": occurrences,
        "errorDigest": hashlib.sha256(
            (status + "\n" + method + "\n" + path + "\n" + message)
            .encode("utf-8")
        ).hexdigest(),
    }
    org_name = clean_string(
        getattr(env, "OFFICE_MARKETING_ORG", "") or "forkmesh",
        MAX_NODE_NAME,
    ).strip().lower()
    org_bi, org_row = await _org_row(env, org_name)
    role = await _org_role(env, org_bi, requester)
    if not org_row or not _org_rbac.org_role_allows(
            role, "organization.tasks.administer"):
        return (
            "Send to task failed: the administrator is not an organization "
            "owner or admin.",
            details,
        )
    task_id = _ap_uuid()
    now = int(Date.now())
    requester_bi = await blind_index(env, requester)
    try:
        status_number = int(status)
    except (TypeError, ValueError):
        status_number = 0
    priority = 5 if status_number >= 500 else 15 if status_number >= 400 else 25
    sealed = await encrypt_row(env, {
        "kind": "task",
        "title": title[:160],
        "details": body[:4000],
        "attachments": [],
        "completionNote": "",
        "assignee": "agent",
        "createdBy": clean_string(requester, MAX_NODE_NAME).strip().lower(),
        "parentTaskId": "",
        "bountyRequest": None,
        "repository": FLAGSHIP_MONITOR_ID,
        "howToTest": (
            "Reproduce %s %s and verify the error no longer appears in the "
            "administration error list." % (method or "request", path or "path")
        )[:720],
        "qaReviewer": "",
        "agent": None,
    })
    await d1_run(
        env,
        "INSERT INTO organization_tasks "
        "(task_id,org_bi,department,team,destination,assignee_kind,status,"
        "assignee_bi,data,created_by_bi,created_at,updated_at,elapsed_ms,"
        "started_at,next_checkin_at,qa_requested_at,agent_session_id,priority) "
        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        task_id, org_bi, "engineering", "", "agent", "agent", "idle", "",
        sealed, requester_bi, now, now, 0, 0, 0, 0, "", priority,
    )
    details["taskId"] = task_id
    details["priority"] = priority
    return (
        "Task %s added to the organization task list and assigned to Bot."
        % task_id,
        details,
    )


async def _admin_disburse(env):
    del env
    return (
        "Legacy Worker-held deposit sweeps are disabled. Export D1 and run the "
        "offline custody migration after reconciling every on-chain balance; "
        "the web admin cannot access or use retained wallet seeds."
    )


# --- Direct HTTPS mirror discovery, health, and masked routing --------------
#
# Repository bytes use ordinary HTTPS between this edge router and an
# independently operated mirror. D1 retains only signed endpoint identity and
# health metadata. The desktop host WebSocket remains a control/update channel;
# public browse, clone, and release reads below never fall back to it.

HTTPS_MIRROR_ENDPOINT_PATH = "/api/mirrors/https"
HTTPS_MIRROR_PRIVATE_ROUTE_PATH = "/api/mirrors/private"
HTTPS_MIRROR_ROUTER_READINESS_CHALLENGE = (
    b"forkmesh-mirror-router-readiness-v1\nmainnode")
HTTPS_MIRROR_MANIFEST_MAX_BYTES = 128 * 1024
HTTPS_MIRROR_ENDPOINT_FAST_RENEW_MS = 5 * 60 * 1000
# Mirror renewals are primary; cron checks one oldest active lease per minute.
HTTPS_MIRROR_HEALTH_BATCH = 1
HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS = 20
# Git upload-pack uses this only until the selected mirror returns response
# headers. The established response body deliberately outlives this window;
# its 30-minute host-inactivity guard lives beside the mirror Git process.
HTTPS_MIRROR_GIT_INITIAL_RESPONSE_TIMEOUT_SECONDS = 20
HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS = 6
# The largest request body the Worker materializes in Python. A receive-pack
# body above it (or of unannounced length) is streamed to the mirror gateway
# untouched; see _https_mirror_push_proxy. Buffering more would sit three
# copies of the pack (JS body, Python bytes, JS-owned upstream body) inside the
# 128 MB isolate next to the interpreter itself.
HTTPS_MIRROR_BODY_MAX_BYTES = 8 * 1024 * 1024
# A streamed push only answers once the whole pack has crossed the Worker and
# the gateway's receive-pack (fsck, index-pack) has finished, so the wait for
# its response headers is bounded by upload time plus the gateway's own
# size-scaled receive-pack deadline rather than the 20-second read window.
HTTPS_MIRROR_PUSH_RESPONSE_TIMEOUT_SECONDS = 10 * 60
HTTPS_MIRROR_MERGE_BODY_MAX_BYTES = 8 * 1024
HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES = 16 * 1024
HTTPS_MIRROR_ACTIONS_RESULT_MAX_BYTES = 256 * 1024
HTTPS_MIRROR_ACTIONS_RUN_LIMIT = 20
HTTPS_MIRROR_ACTIONS_LOG_TAIL_MAX_BYTES = 16 * 1024
HTTPS_MIRROR_ACTIONS_LEASE_MAX_MS = 15 * 60 * 1000
HTTPS_MIRROR_ACTIONS_CLOCK_SKEW_MS = 60 * 1000
HTTPS_MIRROR_MERGE_REQUEST_RE = re.compile(r"^[A-Za-z0-9_-]{12,80}$")
HTTPS_MIRROR_MERGE_JOB_RETENTION_MS = 7 * 24 * 60 * 60 * 1000
# A published mutation result may carry the executing mirror's node-signed
# attestation of the refs it serves right after the change (the same
# forkmesh-repostate-v1 canonical the collaboration drains sign). Bounded
# shapes only; the signature itself is verified against the selected
# endpoint's registered node key before anything is pinned.
HTTPS_MIRROR_MERGE_ATTESTATION_SIG_RE = re.compile(r"^[A-Za-z0-9_-]{86}$")
HTTPS_MIRROR_MERGE_ATTESTATION_MAX_SKEW_MS = 5 * 60 * 1000
HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT = 256
HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT = 10_000
HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH = 512
HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS = frozenset({
    "git-info-refs", "git-upload-pack", "tree", "blob", "raw",
})
HTTPS_MIRROR_RETRY_STATUSES = frozenset({
    401, 403, 404, 408, 425, 429, 500, 502, 503, 504,
})
# A health endpoint's timeout/rate-limit/server failure is inconclusive: keep a
# prior signed lease until its normal freshness deadline. Authentication and
# missing-route responses are definitive for this public control endpoint and
# therefore still fail closed immediately.
HTTPS_MIRROR_HEALTH_TRANSIENT_STATUSES = frozenset({
    # Cloudflare returns 530 with error 1033 while a named-tunnel connector is
    # briefly reconnecting. That is a transport outage, not evidence that the
    # node's signed repository identity or integrity proof became invalid.
    408, 425, 429, 500, 502, 503, 504, 530,
})
HTTPS_MIRROR_REPO_PROOF_TTL_MS = 60 * 1000
# A failed proof (unreachable endpoint, lagging refs, bad signature) is
# remembered per isolate for a short window too. Only valid proofs used to be
# memoized, so every request that rotated onto a lagging or unresponsive
# endpoint re-ran its probe (up to the full control-fetch timeout) before
# moving on: one such endpoint at the front of the rotation was enough to pin
# the ingress object's wall clock for the life of the failure. The window is
# short so a mirror that catches up is back in rotation within seconds.
HTTPS_MIRROR_REPO_PROOF_FAILURE_TTL_MS = 20 * 1000
HTTPS_MIRROR_REPO_PROOF_MEMO_MAX = 500
# A node whose registration the verifier just left pending (its refs lag the
# accepted pin, its tunnel is mid-restart) retries its lease on a seven-second
# timer. Each retry used to re-run the whole verification -- DNS, manifest,
# signed health probe and their D1 writes -- inside the ingress object, and a
# fleet stuck pending for hours kept that object busy with nothing else. Hold
# the pending verdict for an unchanged identity instead; the next verification
# happens once the hold lapses, so acceptance is delayed by at most the hold.
HTTPS_MIRROR_REGISTRATION_PENDING_HOLD_MS = 45 * 1000
_HTTPS_MIRROR_REGISTRATION_PENDING_MEMO = {}
HTTPS_MIRROR_REPO_PROOF_EDGE_PREFIX = (
    "https://forkmesh.internal/mirror-repository-proof/v1/"
)
_HTTPS_MIRROR_REPO_PROOF_MEMO = {}
# A public website check is bounded to one real origin probe per repo/node in
# this window. This both makes the button useful as a fresh check and prevents
# an anonymous page visitor from turning a registered mirror into a fetch loop.
HTTPS_MIRROR_DIRECT_CHECK_COOLDOWN_MS = 30 * 1000
# Never outlive the decrypted public-catalog privacy envelope. Deep internal
# probes additionally pass a request-scoped cache so their own sequential
# reads reuse one decision without extending cross-request visibility.
HTTPS_MIRROR_PUBLIC_CONTEXT_TTL_MS = PUBLIC_CATALOG_MEMO_TTL_MS
HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO_MAX = 256
_HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO = {}


def _https_mirror_public_context_copy(context):
    """Return a caller-owned copy of one cached routing decision."""
    if not isinstance(context, dict):
        return None
    copied = dict(context)
    for key in ("nodes", "groupNodes", "currentNodes", "pins", "currentPins"):
        copied[key] = set(context.get(key, set()))
    return copied


def _https_mirror_public_context_cache_get(owner, repo, now):
    key = (str(owner or ""), str(repo or ""))
    cached = _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO.get(key)
    if not cached:
        return None
    age = int(now) - int(cached.get("checkedAt") or 0)
    if age < 0 or age > HTTPS_MIRROR_PUBLIC_CONTEXT_TTL_MS:
        _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO.pop(key, None)
        return None
    return _https_mirror_public_context_copy(cached.get("context"))


def _https_mirror_public_context_cache_put(owner, repo, context, now):
    copied = _https_mirror_public_context_copy(context)
    if copied is None:
        return None
    key = (str(owner or ""), str(repo or ""))
    if (
        key not in _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO
        and len(_HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO)
        >= HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO_MAX
    ):
        oldest = min(
            _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO,
            key=lambda item: int(
                _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO[item].get("checkedAt") or 0),
        )
        _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO.pop(oldest, None)
    _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO[key] = {
        "checkedAt": int(now),
        "context": copied,
    }
    return _https_mirror_public_context_copy(copied)


def _https_mirror_public_context_cache_clear():
    """Forget this isolate's routing decisions; re-check the catalog counter.

    Called after state-pin admissions, lease renewals and every catalog
    mutation. Only the last of those changes the repositories table, and it
    also bumps catalog_rev (_bump_catalog_rev / the republish doorbell). So
    the decrypted catalog rows stay put here and only the rev probe is
    forgotten: the next catalog read re-reads the one-row counter and
    rescans solely when it moved. Wiping the rows on every clear was the
    2026-09-13 D1 bill — ~4.5k full catalog rescans a day, most of them
    after pin admissions that never touched a repository row.
    """
    _HTTPS_MIRROR_PUBLIC_CONTEXT_MEMO.clear()
    catalog_memo = globals().get("_PUBLIC_CATALOG_MEMO")
    if isinstance(catalog_memo, dict):
        catalog_memo.update({"ts": 0, "refresh_ts": 0})
    rev_probe = globals().get("_CATALOG_REV_PROBE")
    if isinstance(rev_probe, dict):
        rev_probe.update({"ts": 0, "rev": None})
    count_memo = globals().get("_REPOSITORIES_COUNT_MEMO")
    if isinstance(count_memo, dict):
        count_memo.update({"ts": 0})


def _catalog_memos_mark_stale():
    """This isolate just changed the repositories table: rescan next time.

    Keeps the stale rows so concurrent callers still get the single-flight
    behaviour of _decrypted_public_catalog, but drops the rev they were read
    under so the next reader cannot renew them without a scan.
    """
    _https_mirror_public_context_cache_clear()
    catalog_memo = globals().get("_PUBLIC_CATALOG_MEMO")
    if isinstance(catalog_memo, dict):
        catalog_memo.update({"ts": 0, "refresh_ts": 0, "rev": None, "scan_ts": 0})
    count_memo = globals().get("_REPOSITORIES_COUNT_MEMO")
    if isinstance(count_memo, dict):
        count_memo.update({"ts": 0, "count": None, "rev": None})
    decrypted_memo = globals().get("_CATALOG_ROW_DECRYPT_MEMO")
    if isinstance(decrypted_memo, dict):
        decrypted_memo.clear()


def _https_mirror_router_public_key(env):
    value = clean_string(
        getattr(env, "MIRROR_ROUTER_PUBLIC_KEY", ""), 120).strip()
    return value if valid_node_pubkey(value) else ""


def _https_mirror_router_seed(env):
    # This is a Cloudflare Worker secret, never a D1 field, response value,
    # log field, endpoint argument, or node/wallet credential.
    value = clean_string(
        getattr(env, "MIRROR_ROUTER_SIGNING_SEED", ""), 120).strip()
    return value if re.fullmatch(r"[A-Za-z0-9_-]{43}", value) else ""


async def _https_mirror_router_identity_status(env):
    public_key = _https_mirror_router_public_key(env)
    signing_seed = _https_mirror_router_seed(env)
    if not public_key or not signing_seed:
        return public_key, False
    try:
        signature = await ed25519_sign(
            public_key,
            signing_seed,
            HTTPS_MIRROR_ROUTER_READINESS_CHALLENGE,
        )
        ready = bool(
            signature
            and await ed25519_verify(
                public_key,
                signature,
                HTTPS_MIRROR_ROUTER_READINESS_CHALLENGE,
            )
        )
    except Exception:
        ready = False
    return public_key, ready


def _https_mirror_registration_payload(data):
    if not isinstance(data, dict):
        return None
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).strip().lower()
    base_url = https_routing.normalize_base_url(data.get("baseUrl"))
    mirror_supplied = "mirrorUrl" in data
    mirror_url = (
        https_routing.normalize_base_url(data.get("mirrorUrl"))
        if mirror_supplied else ""
    )
    if mirror_supplied and not mirror_url:
        return None
    public_key = clean_string(data.get("publicKey", ""), 120).strip()
    signature = clean_string(data.get("signature", ""), 200).strip()
    try:
        issued_at = int(data.get("issuedAt") or 0)
    except (TypeError, ValueError):
        return None
    message = https_routing.registration_message(
        node, base_url, public_key, issued_at, mirror_url)
    if (
        not message
        or not valid_node_pubkey(public_key)
        or not re.fullmatch(r"[A-Za-z0-9_-]{86}", signature)
    ):
        return None
    return {
        "node": node,
        "baseUrl": base_url,
        "mirrorUrl": mirror_url,
        "publicKey": public_key,
        "issuedAt": issued_at,
        "signature": signature,
        "message": message,
    }


def _https_mirror_endpoint_renewal_state(existing, registration, now):
    """Classify a verified renewal without trusting its volatile signature."""
    if not isinstance(existing, dict):
        return "changed"
    same_identity = bool(
        str(existing.get("base_url") or "") == registration["baseUrl"]
        and str(existing.get("mirror_url") or "")
        == str(registration.get("mirrorUrl") or "")
        and str(existing.get("public_key") or "")
        == registration["publicKey"]
    )
    if not same_identity:
        return "changed"
    try:
        checked_age = int(now) - int(existing.get("checked_at") or 0)
        verified_age = int(now) - int(
            existing.get("forkmesh_verified_at") or 0)
    except (TypeError, ValueError):
        return "stale"
    fresh = bool(
        0 <= checked_age <= HTTPS_MIRROR_ENDPOINT_FAST_RENEW_MS
        and 0 <= verified_age <= HTTPS_MIRROR_ENDPOINT_FAST_RENEW_MS
        # A lease held through an inadmissible proof was checked after it
        # was last verified; only a real challenge renews it.
        and checked_age >= verified_age
        and int(existing.get("healthy") or 0) == 1
        and str(existing.get("integrity") or "") == "ok"
        and int(existing.get("abuse_blocked") or 0) == 0
        and int(existing.get("forkmesh_active") or 0) == 1
    )
    return "fresh" if fresh else "stale"


async def _https_mirror_fetch_text(
        url, max_bytes, timeout_seconds, accept="application/json"):
    """Fetch a bounded control document without forwarding caller metadata.

    ``_https_mirror_fetch_text.last_error`` names the exception that made the
    most recent call answer ``(0, "")``; the registration path returns it to
    the node so a rejection body says whether its manifest was unreachable.
    """
    _https_mirror_fetch_text.last_error = ""
    try:
        response = await js_fetch_with_timeout(
            url,
            {
                "method": "GET",
                "headers": {
                    "accept": accept,
                    "user-agent": "ForkMesh-HTTPS-router/1.0",
                },
                "redirect": "manual",
            },
            timeout_seconds,
        )
        status = int(getattr(response, "status", 0) or 0)
        try:
            announced = int(response.headers.get("content-length") or 0)
        except Exception:
            announced = 0
        if announced > max_bytes:
            return status, ""
        text = str(await response.text())
        if len(text.encode("utf-8")) > max_bytes:
            return status, ""
        return status, text
    except Exception as exc:
        detail = type(exc).__name__ + ": " + str(exc)
        _https_mirror_fetch_text.last_error = "".join(
            ch if ch.isprintable() else " " for ch in detail)[:120]
        return 0, ""


_CLOUDFLARE_EDGE_RANGES_MEMO = {"checkedAt": 0, "documents": ()}
_HTTPS_MIRROR_EDGE_DNS_MEMO = {}
_HTTPS_MIRROR_PUBLIC_DNS_MEMO = {}
CLOUDFLARE_EDGE_RANGES_TTL_MS = 24 * 60 * 60 * 1000
HTTPS_MIRROR_EDGE_DNS_TTL_MS = 2 * 60 * 1000


async def _cloudflare_edge_range_documents():
    """Fetch Cloudflare's official bounded IP-range documents."""
    now = int(Date.now())
    cached = _CLOUDFLARE_EDGE_RANGES_MEMO
    documents = cached.get("documents") or ()
    if (
        len(documents) == 2
        and now - int(cached.get("checkedAt") or 0)
        <= CLOUDFLARE_EDGE_RANGES_TTL_MS
    ):
        return documents
    fetched = []
    for url in (
            "https://www.cloudflare.com/ips-v4",
            "https://www.cloudflare.com/ips-v6"):
        status, text = await _https_mirror_fetch_text(
            url, 16 * 1024, HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS)
        if status != 200 or not text:
            return ()
        fetched.append(text)
    documents = tuple(fetched)
    # Validate the documents before caching them. A minimal synthetic DNS
    # answer is enough to exercise strict CIDR parsing without trusting it as a
    # real endpoint decision.
    try:
        first_network = str(documents[0]).split()[0]
        probe = str(ipaddress.ip_network(first_network, strict=True).network_address)
    except (IndexError, ValueError):
        return ()
    if not https_routing.cloudflare_proxied_dns_answers(
            [{"Status": 0, "Answer": [{"type": 1, "data": probe}]}],
            documents):
        return ()
    cached["checkedAt"] = now
    cached["documents"] = documents
    return documents


async def _https_mirror_cloudflare_dns_ok(base_url):
    """Independently verify that an endpoint resolves to Cloudflare's edge.

    ``None`` means the independent verifier itself was temporarily unavailable
    (DoH/range-document timeout or malformed upstream response).  Callers that
    establish a new endpoint still treat that as a rejection.  The recurring
    health check can distinguish it from a definitive non-Cloudflare answer and
    let an existing signed lease expire naturally instead of flickering offline
    on one control-plane timeout.
    """
    normalized = https_routing.normalize_base_url(base_url)
    try:
        hostname = urlparse(normalized).hostname or ""
    except Exception:
        hostname = ""
    if not hostname:
        return False
    now = int(Date.now())
    memo = _HTTPS_MIRROR_EDGE_DNS_MEMO.get(hostname)
    if (
        memo
        and now - int(memo.get("checkedAt") or 0)
        <= HTTPS_MIRROR_EDGE_DNS_TTL_MS
    ):
        return bool(memo.get("ok"))
    cidr_documents = await _cloudflare_edge_range_documents()
    if not cidr_documents:
        return None
    payloads = []
    for record_type in ("A", "AAAA"):
        target = (
            "https://cloudflare-dns.com/dns-query?name="
            + quote(hostname)
            + "&type="
            + record_type
        )
        status, text = await _https_mirror_fetch_text(
            target,
            HTTPS_MIRROR_MANIFEST_MAX_BYTES,
            HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
            "application/dns-json",
        )
        if status != 200 or not text:
            return None
        try:
            payloads.append(json.loads(text))
        except Exception:
            return None
    ok = https_routing.cloudflare_proxied_dns_answers(
        payloads, cidr_documents)
    _HTTPS_MIRROR_EDGE_DNS_MEMO[hostname] = {
        "checkedAt": now,
        "ok": bool(ok),
    }
    return bool(ok)


async def _https_mirror_public_dns_ok(base_url):
    """Verify that a direct mirror resolves only to public addresses."""
    normalized = https_routing.normalize_base_url(base_url)
    try:
        hostname = urlparse(normalized).hostname or ""
    except Exception:
        hostname = ""
    if not hostname:
        return False
    try:
        address = ipaddress.ip_address(hostname)
    except ValueError:
        address = None
    if address is not None:
        return bool(address.is_global)
    now = int(Date.now())
    memo = _HTTPS_MIRROR_PUBLIC_DNS_MEMO.get(hostname)
    if (
        memo
        and now - int(memo.get("checkedAt") or 0)
        <= HTTPS_MIRROR_EDGE_DNS_TTL_MS
    ):
        return bool(memo.get("ok"))
    payloads = []
    for record_type in ("A", "AAAA"):
        target = (
            "https://cloudflare-dns.com/dns-query?name="
            + quote(hostname)
            + "&type="
            + record_type
        )
        status, text = await _https_mirror_fetch_text(
            target,
            HTTPS_MIRROR_MANIFEST_MAX_BYTES,
            HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
            "application/dns-json",
        )
        if status != 200 or not text:
            return None
        try:
            payloads.append(json.loads(text))
        except Exception:
            return None
    ok = https_routing.public_dns_answers(payloads)
    _HTTPS_MIRROR_PUBLIC_DNS_MEMO[hostname] = {
        "checkedAt": now,
        "ok": bool(ok),
    }
    return bool(ok)


# Why the last registration from a node failed its manifest check, keyed by
# node name. The rejection body carries it back to that node, whose daemon
# journals the body verbatim — the only place an operator can see it.
_HTTPS_MIRROR_MANIFEST_REJECTIONS = {}


def _https_mirror_manifest_rejection(node):
    return _HTTPS_MIRROR_MANIFEST_REJECTIONS.get(str(node or ""), "unknown")


async def _https_mirror_manifest_ok(registration, direct=False):
    node = str(registration.get("node") or "")

    def reject(reason):
        if len(_HTTPS_MIRROR_MANIFEST_REJECTIONS) > 256:
            _HTTPS_MIRROR_MANIFEST_REJECTIONS.clear()
        _HTTPS_MIRROR_MANIFEST_REJECTIONS[node] = reason
        return False

    status, text = await _https_mirror_fetch_text(
        registration["baseUrl"] + "/forkmesh-mirror.json",
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    if status != 200 or not text:
        detail = getattr(_https_mirror_fetch_text, "last_error", "") or ""
        return reject(
            "fetch:%d%s%s" % (
                int(status or 0),
                "" if text or status != 200 else ":empty",
                (":" + detail) if detail else ""))
    try:
        manifest = json.loads(text)
    except Exception:
        return reject("json")
    validator = (
        https_routing.validate_direct_manifest
        if direct else https_routing.validate_tunnel_manifest
    )
    checked = validator(
        manifest,
        registration["baseUrl"],
        registration["node"],
        registration["publicKey"],
    )
    if not checked:
        return reject("shape:" + ("direct" if direct else "tunnel"))
    if not await ed25519_verify(
            registration["publicKey"],
            checked["signature"],
            checked["payload"]):
        return reject("signature")
    _HTTPS_MIRROR_MANIFEST_REJECTIONS.pop(node, None)
    return True


async def _https_mirror_direct_health_ok(registration):
    """Prove that an advertised public Git origin belongs to this node."""
    now = int(Date.now())
    nonce = _b64url_encode(_random_bytes(18))
    target = (
        registration["mirrorUrl"] + "/health?nonce=" + quote(nonce)
        + "&issuedAt=" + str(now)
    )
    status, text = await _https_mirror_fetch_text(
        target,
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    try:
        data = json.loads(text) if text else {}
        challenge = data.get("challenge")
        message = https_routing.health_challenge(
            registration["node"], nonce, now)
        return bool(
            status == 200
            and data.get("ok") is True
            and data.get("integrity") == "ok"
            and data.get("node") == registration["node"]
            and data.get("publicKey") == registration["publicKey"]
            and data.get("transport") == "direct-https"
            and isinstance(challenge, dict)
            and challenge.get("messageType") == "forkmesh-https-health-v1"
            and challenge.get("nonce") == nonce
            and int(challenge.get("issuedAt") or 0) == now
            and challenge.get("algorithm") == "Ed25519"
            and challenge.get("encoding") == "base64url-no-padding"
            and challenge.get("messageSha256")
            == hashlib.sha256(message.encode("utf-8")).hexdigest()
            and await ed25519_verify(
                registration["publicKey"],
                str(challenge.get("signature") or ""),
                message.encode("utf-8"),
            )
        )
    except Exception:
        return False


async def _https_mirror_node_organizations(env, node):
    """Public organization aliases linked to this endpoint's node."""
    try:
        rows = await d1_all(
            env,
            """SELECT DISTINCT o.name AS name
                 FROM org_repos r JOIN orgs o ON o.org_bi=r.org_bi
                WHERE r.node_owner=? ORDER BY o.name LIMIT 100""",
            node,
        )
        return [
            clean_string(row.get("name", ""), MAX_NODE_NAME).lower()
            for row in rows or []
            if valid_node_name(
                clean_string(row.get("name", ""), MAX_NODE_NAME).lower())
        ]
    except Exception:
        return []


async def https_mirror_endpoint_handler(env, request):
    """Register/update an account-bound, signed Cloudflare Tunnel endpoint."""
    method = method_name(request)
    router_key = _https_mirror_router_public_key(env)
    if method == "GET":
        # Endpoint rows and repository membership are deliberately not listed.
        return json_response({
            "ok": bool(router_key),
            "protocol": "forkmesh-masked-proxy-v1",
            "registration": "forkmesh-https-endpoint-v1",
            "directRegistration": "forkmesh-https-endpoint-v2",
            "directGitProtocol": "git-smart-http-v1",
            "routerPublicKey": router_key,
            "nonCustodial": True,
            "repositoryBytesInD1": False,
        }, status=200 if router_key else 503,
           cache_control="no-store")
    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        announced = int(request.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        raw = str(await request.text())
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if len(raw.encode("utf-8")) > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        data = json.loads(raw)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    registration = _https_mirror_registration_payload(data)
    if not registration or not _ts_ok(registration["issuedAt"]):
        return json_response({"error": "invalid_registration"}, status=400)
    await ensure_schema(env)

    # The manifest cannot self-assert a new identity: its key must already be
    # bound either to the claimed, named node record or to that account as its
    # primary/enabled owner-sign device. Headless mirrors are linked to their
    # human owner in ``nodes`` and do not create a separate user account, so
    # consulting only account signing keys permanently rejected newly linked
    # VPS mirrors even though their exact node key was already authenticated.
    allowed_keys = await _claimed_node_signing_pubkeys(
        env, registration["node"])
    if (
        registration["publicKey"] not in allowed_keys
        or not await ed25519_verify(
            registration["publicKey"],
            registration["signature"],
            registration["message"].encode("utf-8"),
        )
    ):
        return json_response({"error": "unauthorized"}, status=401)
    existing = await d1_first(
        env,
        """SELECT base_url,mirror_url,public_key,registration_sig,issued_at,
                  checked_at,forkmesh_verified_at,healthy,integrity,
                  abuse_blocked,forkmesh_active,forkmesh_refs_sha256
             FROM mirror_https_endpoints WHERE node_name=?""",
        registration["node"],
    )
    if existing:
        old_issued = int(existing.get("issued_at") or 0)
        same = bool(
            existing.get("base_url") == registration["baseUrl"]
            and str(existing.get("mirror_url") or "")
            == registration["mirrorUrl"]
            and existing.get("public_key") == registration["publicKey"]
            and existing.get("registration_sig") == registration["signature"])
        if registration["issuedAt"] < old_issued or (
                registration["issuedAt"] == old_issued and not same):
            return json_response(
                {"error": "stale_registration"}, status=409)
    mirror_url = registration["mirrorUrl"]
    now = int(Date.now())
    identity = (
        registration["baseUrl"], mirror_url, registration["publicKey"])

    async def registration_response(health_active):
        return json_response({
            "ok": True,
            "node": registration["node"],
            "baseUrl": registration["baseUrl"],
            **({"mirrorUrl": mirror_url} if mirror_url else {}),
            "routerPublicKey": router_key,
            "organizations": await _https_mirror_node_organizations(
                env, registration["node"]),
            "health": "active" if health_active else "pending",
            "repositoryBytesInD1": False,
        }, status=201, cache_control="no-store")

    held = _HTTPS_MIRROR_REGISTRATION_PENDING_MEMO.get(registration["node"])
    if (
        held
        and held.get("identity") == identity
        and 0 <= now - int(held.get("at") or 0)
        <= HTTPS_MIRROR_REGISTRATION_PENDING_HOLD_MS
    ):
        return await registration_response(False)
    # A tunnel-free direct origin (baseUrl == mirrorUrl) is validated against
    # public DNS and its self-signed direct manifest; every other shape keeps
    # the Cloudflare-proxied control-endpoint requirement. An advertised
    # mirrorUrl must also answer the signed direct health probe.
    direct_only = bool(mirror_url) and registration["baseUrl"] == mirror_url
    if not direct_only and not await _https_mirror_cloudflare_dns_ok(
            registration["baseUrl"]):
        return json_response(
            {"error": "cloudflare_proxied_dns_required"}, status=400)
    if mirror_url and not await _https_mirror_public_dns_ok(mirror_url):
        return json_response(
            {"error": "public_https_dns_required"}, status=400)
    if not await _https_mirror_manifest_ok(registration, direct=direct_only):
        return json_response({
            "error": "invalid_manifest",
            "reason": _https_mirror_manifest_rejection(registration["node"]),
        }, status=400)
    if mirror_url and not await _https_mirror_direct_health_ok(registration):
        return json_response(
            {"error": "unreachable_mirror_url"}, status=400)

    renewal_state = _https_mirror_endpoint_renewal_state(
        existing, registration, now)

    # A freshly challenged, unchanged identity already owns a valid route
    # lease only while its authenticated catalog still names the generation
    # that lease proved. A repository sync publishes its signed catalog before
    # renewing the endpoint; if that generation advanced, challenge the live
    # gateway now. Keeping the old five-minute fast lease in that case made all
    # mirrors serve new bytes while routing still expected old proofs, causing
    # a repeatable fleet-wide 503 window after every main-branch update.
    if renewal_state == "fresh":
        published_refs = await _https_mirror_published_forkmesh_refs(
            env, registration["node"])
        leased_refs = clean_string(
            (existing or {}).get("forkmesh_refs_sha256", ""), 64,
        ).strip().lower()
        if (
            published_refs is None
            or not published_refs
            or (
                re.fullmatch(r"[0-9a-f]{64}", leased_refs)
                and hmac.compare_digest(published_refs, leased_refs)
            )
        ):
            _HTTPS_MIRROR_REGISTRATION_PENDING_MEMO.pop(
                registration["node"], None)
            return await registration_response(True)
        renewal_state = "stale"

    # Snapshot the accepted state set before resetting this endpoint's lease.
    # Two independently signed pending proofs can form the quorum that admits
    # a new fleet state. Clearing this row first reduced that quorum back to
    # one on every renewal and left both honest nodes stuck in `pending` until
    # the slow background sweep happened to challenge one of them.
    accepted_before_registration = (
        await _https_mirror_accepted_forkmesh_refs(env))

    if renewal_state == "changed":
        node_bi = await blind_index(env, registration["node"])
        region = world_request_country(request)
        await d1_run(
            env,
            """INSERT INTO mirror_https_endpoints
             (node_bi,node_name,base_url,mirror_url,public_key,
              registration_sig,issued_at,
              checked_at,latency_ms,region,healthy,integrity,abuse_blocked,
              health_sig,forkmesh_verified_at,forkmesh_refs_sha256,
              forkmesh_operations_sha256,forkmesh_operations_json,
              forkmesh_active,health_message,
              updated_at)
             VALUES (?,?,?,?,?,?,?,0,0,?,0,'unknown',0,'',0,'','','[]',0,'',?)
             ON CONFLICT(node_bi) DO UPDATE SET
               node_name=excluded.node_name,base_url=excluded.base_url,
               mirror_url=excluded.mirror_url,
               public_key=excluded.public_key,
               registration_sig=excluded.registration_sig,
               issued_at=excluded.issued_at,region=excluded.region,
               healthy=0,integrity='unknown',health_sig='',
               forkmesh_verified_at=0,forkmesh_refs_sha256='',
               forkmesh_operations_sha256='',forkmesh_operations_json='[]',
               forkmesh_active=0,
               health_message='',
               updated_at=excluded.updated_at""",
            node_bi,
            registration["node"],
            registration["baseUrl"],
            registration["mirrorUrl"],
            registration["publicKey"],
            registration["signature"],
            registration["issuedAt"],
            region,
            now,
        )
        try:
            _, node_rec = await _account_row(env, registration["node"])
            await touch_registered_node(env, node_bi, node_rec)
        except Exception:
            pass
    # An identity change resets the endpoint to pending before this challenge;
    # an unchanged but aging identity is challenged in place. Either path lets
    # an independent mirror renew its short lease without relying on the cron
    # or pretending to be the organization's canonical catalog publisher.
    # The verifier still requires Cloudflare-proxied DNS, the registered key,
    # and an accepted repository pin, so acceptance here grants no new trust.
    health_active = await _https_mirror_refresh_registered_health(
        env,
        registration["node"],
        accepted_refs=(
            accepted_before_registration
            if accepted_before_registration else None),
    )
    if not health_active:
        # The challenge above may have stored the first fresh proof from a
        # newly rotated account-owned successor, or completed a two-node
        # quorum. Rebuild the accepted set from that proof and retry once in
        # this same registration request. Otherwise a perfectly healthy
        # replacement remains pending until a later cron turn and can create a
        # fleet-wide 503 window when the old machine has already disappeared.
        refreshed_refs = await _https_mirror_accepted_forkmesh_refs(env)
        if (
            refreshed_refs
            and refreshed_refs != accepted_before_registration
        ):
            health_active = await _https_mirror_refresh_registered_health(
                env, registration["node"], accepted_refs=refreshed_refs)
    if health_active:
        _HTTPS_MIRROR_REGISTRATION_PENDING_MEMO.pop(registration["node"], None)
    else:
        if len(_HTTPS_MIRROR_REGISTRATION_PENDING_MEMO) >= 500:
            _HTTPS_MIRROR_REGISTRATION_PENDING_MEMO.clear()
        _HTTPS_MIRROR_REGISTRATION_PENDING_MEMO[registration["node"]] = {
            "at": int(Date.now()), "identity": identity}
    return await registration_response(health_active)


def _https_mirror_private_route_payload(data):
    """Validate one owner-signed opaque private-replica binding."""
    if not isinstance(data, dict):
        return None
    owner = clean_string(data.get("owner", ""), MAX_NODE_NAME).strip().lower()
    repo = clean_string(data.get("repository", ""), MAX_REPO_SEGMENT).strip()
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).strip().lower()
    opaque_id = clean_string(data.get("opaqueId", ""), 64).strip().lower()
    replica_sha256 = clean_string(
        data.get("replicaSha256", ""), 64).strip().lower()
    signature = clean_string(data.get("signature", ""), 200).strip()
    active = data.get("active")
    try:
        key_epoch = int(data.get("keyEpoch") or 0)
        issued_at = int(data.get("issuedAt") or 0)
    except (TypeError, ValueError):
        return None
    message = https_routing.private_route_message(
        owner, repo, node, opaque_id, replica_sha256, key_epoch, active,
        issued_at)
    if (
        not message
        or not re.fullmatch(r"[A-Za-z0-9_-]{86}", signature)
    ):
        return None
    return {
        "owner": owner,
        "repo": repo,
        "node": node,
        "opaqueId": opaque_id,
        "replicaSha256": replica_sha256,
        "keyEpoch": key_epoch,
        "active": active,
        "issuedAt": issued_at,
        "signature": signature,
        "message": message,
    }


async def _https_mirror_private_record(env, owner, repo):
    """Return an exact private catalog row without ever listing private rows."""
    owner = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip()
    if not valid_node_name(owner) or not safe_segment(repo):
        return None
    try:
        repo_bi = await blind_index(env, owner + "/" + repo)
        row = await d1_first(
            env,
            "SELECT is_private,data FROM repositories WHERE key_bi=?",
            repo_bi,
        )
        if not row or int(row.get("is_private", 0) or 0) != 1:
            return None
        record = await decrypt_row(env, row.get("data"))
        if (
            not record
            or record.get("visibility") != "private"
            or str(record.get("owner") or "").lower() != owner
            or str(record.get("name") or "") != repo
            or record.get("mirrorEncryption") != "owner-sealed-v1"
            or int(record.get("keyEpoch") or 0) < 1
        ):
            return None
        return {
            "repoBi": repo_bi,
            "keyEpoch": int(record["keyEpoch"]),
            "owner": owner,
            "repo": repo,
        }
    except Exception:
        return None


async def _https_mirror_private_access_record(env, opaque_id):
    """Resolve one opaque access id to exactly one encrypted private record.

    The random id is the only repository locator accepted on the client-facing
    private transport.  It is not sufficient authorization: after this exact
    lookup, the caller must still prove owner/share access using HTTP Basic.
    Multiple active bindings may legitimately use the same id for mirrors of
    the same repository, but an id that maps to more than one repository fails
    closed instead of becoming an ambiguity or existence oracle.
    """
    opaque_id = clean_string(opaque_id, 64).strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", opaque_id):
        return None
    try:
        await ensure_schema(env)
        routes = await d1_all(
            env,
            """SELECT DISTINCT repo_bi,key_epoch
                 FROM private_mirror_routes
                WHERE opaque_replica_id=? AND active=1""",
            opaque_id,
        )
        repo_bis = {
            str(route.get("repo_bi") or "")
            for route in routes or []
            if route.get("repo_bi")
        }
        if len(repo_bis) != 1:
            return None
        repo_bi = next(iter(repo_bis))
        row = await d1_first(
            env,
            "SELECT is_private,data FROM repositories WHERE key_bi=?",
            repo_bi,
        )
        if not row or int(row.get("is_private", 0) or 0) != 1:
            return None
        record = await decrypt_row(env, row.get("data"))
        owner = clean_string(
            (record or {}).get("owner", ""), MAX_NODE_NAME).strip().lower()
        repo = clean_string(
            (record or {}).get("name", ""), MAX_REPO_SEGMENT).strip()
        try:
            key_epoch = int((record or {}).get("keyEpoch") or 0)
        except (TypeError, ValueError):
            return None
        if (
            not record
            or record.get("visibility") != "private"
            or record.get("mirrorEncryption") != "owner-sealed-v1"
            or not valid_node_name(owner)
            or not safe_segment(repo)
            or key_epoch < 1
            or not any(
                int(route.get("key_epoch") or 0) == key_epoch
                for route in routes or []
            )
            or not hmac.compare_digest(
                repo_bi, await blind_index(env, owner + "/" + repo))
        ):
            return None
        return {
            "repoBi": repo_bi,
            "keyEpoch": key_epoch,
            "owner": owner,
            "repo": repo,
        }
    except Exception:
        return None


async def _https_mirror_private_catalog_access_id(
        env, repo_bi, key_epoch):
    """Return one current opaque locator for an already-authorized catalog row."""
    try:
        row = await d1_first(
            env,
            """SELECT opaque_replica_id
                 FROM private_mirror_routes
                WHERE repo_bi=? AND active=1 AND key_epoch=?
                ORDER BY updated_at DESC LIMIT 1""",
            repo_bi, int(key_epoch),
        )
        opaque_id = clean_string(
            (row or {}).get("opaque_replica_id", ""), 64).strip().lower()
        if re.fullmatch(r"[0-9a-f]{64}", opaque_id):
            return opaque_id
    except Exception:
        pass
    return ""


async def https_mirror_private_route_handler(env, request):
    """Create, rotate, or revoke a blind-indexed private ciphertext route."""
    method = method_name(request)
    if method == "GET":
        # This endpoint deliberately has no list operation.
        return json_response({
            "ok": True,
            "protocol": "forkmesh-private-route-v1",
            "transport": "owner-sealed-opaque-archive-v1",
            "repositoryBytesInD1": False,
            "privateRoutesListed": False,
        }, cache_control="public, max-age=300")
    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        announced = int(request.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        raw = str(await request.text())
    except Exception:
        return json_response({"error": "not_found"}, status=404)
    if len(raw.encode("utf-8")) > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        binding = _https_mirror_private_route_payload(json.loads(raw))
    except Exception:
        binding = None
    if not binding or not _ts_ok(binding["issuedAt"]):
        return json_response({"error": "not_found"}, status=404)
    await ensure_schema(env)
    private_record = await _https_mirror_private_record(
        env, binding["owner"], binding["repo"])
    owner_key = await _owner_pubkey(env, binding["owner"])
    if (
        not private_record
        or not owner_key
        or private_record["keyEpoch"] != binding["keyEpoch"]
        or not await ed25519_verify(
            owner_key,
            binding["signature"],
            binding["message"].encode("utf-8"),
        )
    ):
        return json_response({"error": "not_found"}, status=404)
    endpoint = await d1_first(
        env,
        "SELECT node_bi FROM mirror_https_endpoints WHERE node_name=?",
        binding["node"],
    )
    if not endpoint:
        return json_response({"error": "not_found"}, status=404)
    node_bi = str(endpoint.get("node_bi") or "")
    binding_bi = await blind_index(
        env,
        "private-route:" + binding["owner"] + "/" + binding["repo"]
        + ":" + binding["node"],
    )
    existing = await d1_first(
        env,
        """SELECT issued_at,owner_sig,active,opaque_replica_id,
                  replica_sha256,key_epoch
             FROM private_mirror_routes WHERE binding_bi=?""",
        binding_bi,
    )
    if existing:
        old_issued = int(existing.get("issued_at") or 0)
        same = bool(
            old_issued == binding["issuedAt"]
            and existing.get("owner_sig") == binding["signature"]
            and bool(existing.get("active")) == binding["active"]
            and existing.get("opaque_replica_id") == binding["opaqueId"]
            and existing.get("replica_sha256") == binding["replicaSha256"]
            and int(existing.get("key_epoch") or 0) == binding["keyEpoch"])
        if binding["issuedAt"] < old_issued or (
                binding["issuedAt"] == old_issued and not same):
            return json_response({"error": "stale_registration"}, status=409)
    collision = await d1_first(
        env,
        """SELECT binding_bi FROM private_mirror_routes
            WHERE opaque_replica_id=? AND repo_bi<>? LIMIT 1""",
        binding["opaqueId"], private_record["repoBi"],
    )
    if collision:
        return json_response({"error": "route_conflict"}, status=409)
    now = int(Date.now())
    await d1_run(
        env,
        """INSERT INTO private_mirror_routes
             (binding_bi,repo_bi,node_bi,opaque_replica_id,replica_sha256,
              key_epoch,owner_sig,issued_at,active,updated_at)
             VALUES (?,?,?,?,?,?,?,?,?,?)
             ON CONFLICT(binding_bi) DO UPDATE SET
               node_bi=excluded.node_bi,
               opaque_replica_id=excluded.opaque_replica_id,
               replica_sha256=excluded.replica_sha256,
               key_epoch=excluded.key_epoch,owner_sig=excluded.owner_sig,
               issued_at=excluded.issued_at,active=excluded.active,
               updated_at=excluded.updated_at""",
        binding_bi,
        private_record["repoBi"],
        node_bi,
        binding["opaqueId"],
        binding["replicaSha256"],
        binding["keyEpoch"],
        binding["signature"],
        binding["issuedAt"],
        1 if binding["active"] else 0,
        now,
    )
    return json_response({
        "ok": True,
        "active": binding["active"],
        "keyEpoch": binding["keyEpoch"],
        "privateAccessId": (
            binding["opaqueId"] if binding["active"] else ""),
        "accessPath": (
            "/api/private-replicas/" + binding["opaqueId"]
            if binding["active"] else ""),
        "repositoryBytesInD1": False,
    }, status=201, cache_control="no-store")


async def _https_mirror_expected_forkmesh_refs(env):
    """Owner-attested refs digest for the public flagship repository.

    ``forkmesh`` may be an organization namespace rather than an account.  In
    that case its public URL is backed by a linked node's catalog row; resolve
    that alias for the state pin while health challenges continue to name the
    stable public ``forkmesh/forkmesh`` gateway alias.
    """
    try:
        owner = await _org_repo_node(env, "forkmesh", "forkmesh") or (
            _instance_flagship_node(env))
        key_bi = await blind_index(env, owner + "/forkmesh")
        row = await d1_first(
            env,
            "SELECT data,is_private FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row or int(row.get("is_private", 1) or 0) != 0:
            return ""
        record = await decrypt_row(env, row.get("data"))
        digest = clean_string((record or {}).get("stateHash", ""), 64).lower()
        if (
            not record
            or record.get("visibility") != "public"
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            return ""
        return digest
    except Exception:
        return ""


async def _https_mirror_published_forkmesh_refs(env, node):
    """Return one mirror's authenticated catalog generation.

    ``None`` means the lookup itself failed; an empty string means the node has
    no valid public flagship publication. Endpoint renewal uses this only to
    decide whether an existing signed health lease must be challenged again.
    It never admits the catalog claim as a routing proof by itself.
    """
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return ""
    try:
        key_bi = await blind_index(env, node + "/forkmesh")
        row = await d1_first(
            env,
            "SELECT data,is_private FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row or int(row.get("is_private", 1) or 0) != 0:
            return ""
        record = await decrypt_row(env, row.get("data"))
        digest = clean_string((record or {}).get("stateHash", ""), 64).lower()
        if (
            not record
            or str(record.get("owner") or "").strip().lower() != node
            or str(record.get("name") or "").strip().lower() != "forkmesh"
            or record.get("visibility") != "public"
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            return ""
        return digest
    except Exception:
        return None


def _mirror_origin_is_this_app(env, request, origin):
    try:
        target = (urlparse(origin).hostname or "").lower()
        own = {(urlparse(str(request.url)).hostname or "").lower()}
    except Exception:
        return False
    for name in ("APP_ORIGIN", "PUBLIC_BASE_URL"):
        try:
            own.add((urlparse(str(getattr(env, name, "") or "")).hostname
                     or "").lower())
        except Exception:
            pass
    own.discard("")
    return bool(target) and target in own


def _instance_solo_flagship_node(env):
    node = clean_string(getattr(env, "INSTANCE_FLAGSHIP_NODE", "") or "",
                        MAX_NODE_NAME).strip().lower()
    return node if valid_node_name(node) else ""


def _instance_flagship_node(env):
    node = clean_string(getattr(env, "INSTANCE_FLAGSHIP_NODE", "") or "",
                        MAX_NODE_NAME).strip().lower()
    return node if valid_node_name(node) else "forkmesh"


def _https_mirror_deployed_flagship_refs(env, owner="forkmesh", repo="forkmesh"):
    """Exact routing generation compiled into the current production deploy."""
    if (
        str(owner or "").strip().lower() != "forkmesh"
        or str(repo or "").strip().lower() != "forkmesh"
    ):
        return frozenset()
    deployed = clean_string(
        getattr(env, "FLAGSHIP_ROUTING_REFS_SHA256", ""), 64,
    ).strip().lower()
    return (
        frozenset({deployed})
        if re.fullmatch(r"[0-9a-f]{64}", deployed)
        else frozenset()
    )


def _https_mirror_flagship_recovery_node(env):
    """Return the explicitly configured flagship trust-anchor node.

    The desktop source catalog can be offline for long periods while its
    managed headless fleet continues following the canonical main branch. The
    configured identity anchors recovery to its durable owning account; the
    recovery proof selector below then follows that account's newest valid
    replacement without trusting unrelated registered mirrors.
    """
    node = clean_string(
        getattr(env, "FLAGSHIP_RECOVERY_NODE", ""), MAX_NODE_NAME,
    ).strip().lower()
    return node if valid_node_name(node) else ""


async def _https_mirror_flagship_recovery_refs(env, quorum):
    """Select one fresh successor owned by the configured trust anchor.

    Managed headless machines are replaced over time. Pinning recovery to the
    literal machine name made that normal rotation an availability deadline:
    once the named VPS disappeared, one new state could not be admitted until
    two independently syncing replacements happened to expose the exact same
    generation. The configured node remains the trust anchor, but its durable
    account binding is the authority. Among that account's fresh, group-scoped
    proofs, the newest endpoint registration is the single deterministic
    successor. A different account, an endpoint outside this repository group,
    or a stale/invalid proof never enters ``nodeDigests`` and cannot be chosen.
    """
    anchor = _https_mirror_flagship_recovery_node(env)
    node_digests = (quorum or {}).get("nodeDigests") or {}
    if not anchor:
        return frozenset()

    def exact_digest(node):
        digest = clean_string(node_digests.get(node, ""), 64).strip().lower()
        return digest if re.fullmatch(r"[0-9a-f]{64}", digest) else ""

    # Key-bound legacy nodes have no human owner. Preserve the previous exact
    # identity behavior for them instead of silently widening their authority.
    try:
        anchor_bi = await blind_index(env, anchor)
        anchor_row = await d1_first(
            env, "SELECT user_bi FROM nodes WHERE node_bi=?", anchor_bi)
        owner_bi = str((anchor_row or {}).get("user_bi") or "").strip()
    except Exception:
        owner_bi = ""
    if not owner_bi:
        digest = exact_digest(anchor)
        return frozenset({digest}) if digest else frozenset()

    try:
        rows = await d1_all(
            env,
            """SELECT e.node_name,e.issued_at
                 FROM mirror_https_endpoints e
                 JOIN nodes n ON n.node_bi=e.node_bi
                WHERE n.user_bi=?""",
            owner_bi,
        )
    except Exception:
        # A D1 ownership lookup failure must not grant a new machine recovery
        # authority. The configured identity can still recover exactly as it
        # did before this handoff mechanism existed.
        digest = exact_digest(anchor)
        return frozenset({digest}) if digest else frozenset()

    candidates = []
    for row in rows or []:
        node = clean_string(
            row.get("node_name", ""), MAX_NODE_NAME).strip().lower()
        digest = exact_digest(node)
        if not digest:
            continue
        try:
            issued_at = int(row.get("issued_at") or 0)
        except (TypeError, ValueError):
            issued_at = 0
        candidates.append((issued_at, node, digest))
    if not candidates:
        digest = exact_digest(anchor)
        return frozenset({digest}) if digest else frozenset()
    _, _, digest = max(candidates)
    return frozenset({digest})


async def _https_mirror_flagship_quorum(env, allowed_nodes=None, now=None):
    """Return fresh repository states independently attested by two mirrors.

    The organization alias still has a durable catalog row for permissions and
    repository identity, but that row must not make its hosting machine the
    fleet's availability authority.  A new flagship state therefore joins the
    accepted set once two distinct, healthy group endpoints return matching
    node-signed repository proofs.  One compromised or divergent mirror cannot
    repin the route by itself, while removing the former catalog host leaves
    the remaining agreeing mirrors able to advance normally.
    """
    try:
        now = int(now if now is not None else Date.now())
        allowed = (
            {
                clean_string(node, MAX_NODE_NAME).strip().lower()
                for node in allowed_nodes
                if valid_node_name(
                    clean_string(node, MAX_NODE_NAME).strip().lower())
            }
            if allowed_nodes is not None else None
        )
        rows = await d1_all(
            env,
            """SELECT node_name,checked_at,forkmesh_refs_sha256,
                      forkmesh_operations_json
                 FROM mirror_https_endpoints
                WHERE healthy=1 AND integrity='ok' AND abuse_blocked=0
                  AND checked_at>=?""",
            now - https_routing.ENDPOINT_STALE_MS,
        )
        by_digest = {}
        node_digest = {}
        for row in rows or []:
            node = clean_string(
                row.get("node_name", ""), MAX_NODE_NAME).strip().lower()
            digest = clean_string(
                row.get("forkmesh_refs_sha256", ""), 64).strip().lower()
            try:
                operations = set(json.loads(
                    str(row.get("forkmesh_operations_json") or "[]")))
            except Exception:
                operations = set()
            if (
                not valid_node_name(node)
                or (allowed is not None and node not in allowed)
                or not re.fullmatch(r"[0-9a-f]{64}", digest)
                or not HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS.issubset(
                    operations)
            ):
                continue
            by_digest.setdefault(digest, set()).add(node)
            node_digest[node] = digest
        solo = _instance_solo_flagship_node(env)
        pins = frozenset(
            digest for digest, nodes in by_digest.items()
            if len(nodes) >= 2 or (solo and solo in nodes))
        return {
            "pins": pins,
            "nodes": frozenset(
                node for digest in pins for node in by_digest[digest]),
            "nodeDigests": node_digest,
        }
    except Exception:
        return {"pins": frozenset(), "nodes": frozenset(), "nodeDigests": {}}


_HTTPS_MIRROR_STATE_PIN_MEMO = {"entries": {}}
HTTPS_MIRROR_STATE_PIN_MEMO_MAX_AGE_MS = 10 * 60 * 1000
HTTPS_MIRROR_STATE_PIN_MEMO_MAX_KEYS = 64


async def _https_mirror_state_history_pins(env, key_bi):
    """Recent source-attested state digests for one repository.

    The mirror-health cron asks every minute. History rows only appear or
    move when a signed attestation lands (INSERT ... ON CONFLICT DO UPDATE SET
    ts, followed by the bounded prune), so the newest ts — one indexed row via
    idx_repo_state_history_key_ts — fingerprints the whole list; an unchanged
    value reuses the previous digests instead of re-reading STATE_PIN_HISTORY
    rows. The max age bounds any staleness a same-ts rewrite could hide.
    """
    # One slot per repository: the single-slot memo this replaced was
    # evicted every time the mirror fleet alternated between two repos, so
    # the full STATE_PIN_HISTORY read ran ~1.6k times a day for nothing.
    entries = _HTTPS_MIRROR_STATE_PIN_MEMO.setdefault("entries", {})
    now = int(Date.now())
    newest = await d1_first(
        env,
        "SELECT MAX(ts) AS ts FROM repo_state_history WHERE key_bi=?",
        key_bi,
    )
    max_ts = (newest or {}).get("ts")
    memo = entries.get(key_bi)
    if (
        max_ts is not None
        and memo is not None
        and memo["max_ts"] == max_ts
        and 0 <= now - int(memo["ts"] or 0)
        < HTTPS_MIRROR_STATE_PIN_MEMO_MAX_AGE_MS
    ):
        return memo["pins"]
    history = await d1_all(
        env,
        "SELECT state_hash FROM repo_state_history WHERE key_bi=? "
        "ORDER BY ts DESC LIMIT ?",
        key_bi,
        STATE_PIN_HISTORY,
    )
    pins = set()
    for item in history or []:
        digest = clean_string(
            item.get("state_hash", ""), 64).strip().lower()
        if re.fullmatch(r"[0-9a-f]{64}", digest):
            pins.add(digest)
    if len(entries) >= int(
            globals().get("HTTPS_MIRROR_STATE_PIN_MEMO_MAX_KEYS", 64) or 64):
        entries.clear()
    entries[key_bi] = {"max_ts": max_ts, "ts": now, "pins": frozenset(pins)}
    return entries[key_bi]["pins"]


async def _https_mirror_accepted_forkmesh_refs(env):
    """Current and recent source-attested states accepted during convergence.

    The source publication and a mirror refresh cannot commit atomically across
    independent machines.  Keep the direct-HTTPS lease valid while a healthy
    mirror still serves a recent state that the source genuinely signed; an
    unknown state remains rejected by the health challenge.

    A production deploy also pins the exact default-branch-and-tags digest it
    was built from. Repository catalog publication is intentionally separate
    from code deployment and can lag while issue/agent work creates other
    signed revisions. The deploy pin keeps the one mirror serving the deployed
    canonical revision eligible without admitting those divergent revisions.
    """
    pins = set(_https_mirror_deployed_flagship_refs(env))
    try:
        owner = await _org_repo_node(env, "forkmesh", "forkmesh") or (
            _instance_flagship_node(env))
        key_bi = await blind_index(env, owner + "/forkmesh")
        row = await d1_first(
            env,
            "SELECT data,is_private FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row or int(row.get("is_private", 1) or 0) != 0:
            return frozenset(pins)
        record = await decrypt_row(env, row.get("data"))
        if not record or record.get("visibility") != "public":
            return frozenset(pins)
        current = clean_string(record.get("stateHash", ""), 64).lower()
        if re.fullmatch(r"[0-9a-f]{64}", current):
            pins.add(current)
        pins.update(await _https_mirror_state_history_pins(env, key_bi))
        # Keep legacy signed states while the independent group advances.
        try:
            catalog_rows = await _decrypted_public_catalog(
                env, int(Date.now()))
            target = record
            group_nodes = set()
            for catalog_row in catalog_rows or []:
                candidate = (catalog_row or {}).get("data") or {}
                if not repo_mirror_same_group(target, candidate):
                    continue
                node = clean_string(
                    candidate.get("machineName")
                    or candidate.get("owner", ""),
                    MAX_NODE_NAME,
                ).strip().lower()
                if valid_node_name(node):
                    group_nodes.add(node)
            quorum = await _https_mirror_flagship_quorum(env, group_nodes)
            pins.update(quorum.get("pins", ()))
            pins.update(await _https_mirror_flagship_recovery_refs(
                env, quorum))
            if await _admission_override_active(env, key_bi):
                pins.update(quorum["nodeDigests"].values())
        except Exception:
            pass
        return frozenset(pins)
    except Exception:
        # The deployment pin is independent of D1 and remains usable during a
        # catalog read hiccup; endpoint identity, freshness, signed proof, and
        # exact digest comparison are still enforced by the health verifier.
        return frozenset(pins)


def _https_mirror_refs_match(refs_digest, accepted_refs):
    """Compare a proof with a bounded set of exact source-signed ref states."""
    digest = str(refs_digest or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        return False
    candidates = (
        (accepted_refs,)
        if isinstance(accepted_refs, str)
        else (accepted_refs or ())
    )
    return any(
        re.fullmatch(r"[0-9a-f]{64}", str(item or "").strip().lower())
        and hmac.compare_digest(digest, str(item).strip().lower())
        for item in candidates
    )


async def _https_mirror_refresh_registered_health(
        env, node, accepted_refs=None):
    """Best-effort activation for one exact registered endpoint.

    The endpoint row is already account-bound and signature-verified by the
    registration handler. Health is nevertheless established only by a fresh
    node-signed challenge whose repository digest matches the canonical public
    state pin.
    """
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return False
    try:
        row = await d1_first(
            env,
            """SELECT node_bi,node_name,base_url,mirror_url,public_key
                 FROM mirror_https_endpoints WHERE node_name=?""",
            node,
        )
        if not row:
            return False
        accepted = (
            frozenset(accepted_refs)
            if accepted_refs is not None
            else await _https_mirror_accepted_forkmesh_refs(env)
        )
        if not accepted:
            return False
        return bool(await _https_mirror_health_one(env, row, accepted))
    except Exception:
        # Registration remains safely pending. A transient control-plane fetch
        # failure must not roll back its authenticated endpoint record.
        return False


async def _https_mirror_refresh_catalog_publisher_health(env, record):
    """Best-effort activation for one signed public flagship publication.

    Catalog authorization already binds ``record["owner"]`` and its maintainer
    signature to an active account. This lookup stays scoped to that exact node;
    ``_https_mirror_health_one`` then independently rechecks its bound signing
    key, Cloudflare-proxied DNS, and fresh node-signed repository proof.
    """
    if (
        not isinstance(record, dict)
        or record.get("visibility") != "public"
        or clean_string(record.get("name", ""), MAX_REPO_SEGMENT).lower()
        != "forkmesh"
    ):
        return False
    node = clean_string(
        record.get("owner", ""), MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return False
    try:
        canonical_node = clean_string(
            await _org_repo_node(env, "forkmesh", "forkmesh"),
            MAX_NODE_NAME,
        ).strip().lower()
        canonical_node = canonical_node or "forkmesh"
        if node != canonical_node:
            return False
        return bool(await _https_mirror_refresh_registered_health(env, node))
    except Exception:
        # Publication is already authorized and durable. Health remains pending
        # or is cleared by the verifier; a control-plane fetch/storage failure
        # must not turn that successful catalog write into an error response.
        return False


async def _https_mirror_mark_failed(env, row, now):
    await d1_run(
        env,
        """UPDATE mirror_https_endpoints
              SET checked_at=?,healthy=0,integrity='failed',health_sig='',
                  forkmesh_verified_at=0,forkmesh_refs_sha256='',
                  forkmesh_operations_sha256='',
                  forkmesh_operations_json='[]',forkmesh_active=0,
                  health_message='',updated_at=?
            WHERE node_bi=?""",
        now, now, row.get("node_bi"),
    )


async def _https_mirror_mark_transient(env, row, now):
    # Record only the attempt time.  checked_at/forkmesh_verified_at remain the
    # last successful signed proof, so routing naturally stops at the normal
    # freshness deadline if the outage persists.  Keeping updated_at separate
    # also lets oldest-attempt-first scheduling rotate past this endpoint.
    await d1_run(
        env,
        """UPDATE mirror_https_endpoints
              SET updated_at=?
            WHERE node_bi=?""",
        now, row.get("node_bi"),
    )


async def _https_mirror_hold_lease(
        env, row, now, latency, *, signature, message, refs_digest,
        operations_digest, operations):
    """Keep an unexpired lease through one valid but inadmissible proof.

    False means no live lease: the caller records the proof as inactive.
    forkmesh_verified_at never advances here, so a mirror that stays
    unavailable or divergent still drops out at the freshness deadline.
    """
    lease = await d1_first(
        env,
        """SELECT forkmesh_active,forkmesh_verified_at
             FROM mirror_https_endpoints WHERE node_bi=?""",
        row.get("node_bi"),
    )
    try:
        verified_age = int(now) - int(
            (lease or {}).get("forkmesh_verified_at") or 0)
        held = bool(
            int((lease or {}).get("forkmesh_active") or 0) == 1
            and 0 <= verified_age <= HTTPS_MIRROR_STATUS_FRESH_MS
        )
    except (TypeError, ValueError):
        held = False
    if not held:
        return False
    if refs_digest:
        # Publish the digest now served: two endpoints naming it form the
        # quorum that admits it, and the next challenge renews this lease.
        await d1_run(
            env,
            """UPDATE mirror_https_endpoints
                  SET checked_at=?,latency_ms=?,healthy=1,integrity='ok',
                      health_sig=?,forkmesh_refs_sha256=?,
                      forkmesh_operations_sha256=?,
                      forkmesh_operations_json=?,health_message=?,
                      updated_at=?
                WHERE node_bi=?""",
            now,
            latency,
            signature,
            refs_digest,
            operations_digest,
            json.dumps(operations, separators=(",", ":")),
            message,
            now,
            row.get("node_bi"),
        )
    else:
        # Mid-generation, nothing to publish: record only the attempt.
        await _https_mirror_mark_transient(env, row, now)
    await d1_run(
        env, "UPDATE nodes SET last_seen=? WHERE node_bi=?",
        now, row.get("node_bi"))
    return True


async def _https_mirror_health_one(env, row, accepted_forkmesh_refs):
    """Verify one fresh node-signed health and forkmesh/forkmesh proof."""
    now = int(Date.now())
    node = clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower()
    public_key = clean_string(row.get("public_key", ""), 120)
    base_url = https_routing.normalize_base_url(row.get("base_url"))
    mirror_url = https_routing.normalize_base_url(row.get("mirror_url"))
    if (
        not valid_node_name(node)
        or not valid_node_pubkey(public_key)
        or not base_url
        or public_key not in await _claimed_node_signing_pubkeys(env, node)
    ):
        await _https_mirror_mark_failed(env, row, now)
        return False
    dns_ok = await (
        _https_mirror_public_dns_ok(base_url)
        if mirror_url == base_url
        else _https_mirror_cloudflare_dns_ok(base_url)
    )
    if dns_ok is None:
        await _https_mirror_mark_transient(env, row, now)
        return False
    if not dns_ok:
        await _https_mirror_mark_failed(env, row, now)
        return False
    nonce = _b64url_encode(_random_bytes(18))
    target = (
        base_url + "/health?nonce=" + quote(nonce)
        + "&issuedAt=" + str(now)
        + "&owner=forkmesh&repo=forkmesh"
    )
    started = int(Date.now())
    status, text = await _https_mirror_fetch_text(
        target,
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    latency = max(0, min(60_000, int(Date.now()) - started))
    if status == 0 or status in HTTPS_MIRROR_HEALTH_TRANSIENT_STATUSES:
        await _https_mirror_mark_transient(env, row, now)
        return False
    try:
        data = json.loads(text) if text else {}
    except Exception:
        data = {}
    try:
        proof = data.get("repositoryProof")
        challenge = data.get("challenge")
        operations = proof.get("operations")
        operations_digest = https_routing.operations_sha256(operations)
        available = proof.get("available") is True
        proof_integrity = str(proof.get("integrity") or "").lower()
        refs_digest = str(proof.get("refsSha256") or "").lower()
        claimed_operations_digest = str(
            proof.get("operationsSha256") or "").lower()
        message = https_routing.repository_health_challenge(
            node,
            nonce,
            now,
            proof.get("owner"),
            proof.get("repository"),
            available,
            proof_integrity,
            refs_digest,
            claimed_operations_digest,
        )
        signature = str(challenge.get("signature") or "")
        valid = bool(
            isinstance(data, dict)
            and data.get("node") == node
            and data.get("publicKey") == public_key
            and data.get("transport") == "direct-https"
            and isinstance(proof, dict)
            and proof.get("owner") == "forkmesh"
            and proof.get("repository") == "forkmesh"
            and isinstance(challenge, dict)
            and challenge.get("messageType")
            == "forkmesh-https-health-repository-v1"
            and challenge.get("nonce") == nonce
            and int(challenge.get("issuedAt") or 0) == now
            and challenge.get("algorithm") == "Ed25519"
            and challenge.get("encoding") == "base64url-no-padding"
            and message
            and challenge.get("messageSha256")
            == hashlib.sha256(message.encode("utf-8")).hexdigest()
            and operations_digest
            and operations_digest == claimed_operations_digest
            and await ed25519_verify(
                public_key, signature, message.encode("utf-8"))
        )
    except Exception:
        valid = False
        signature = ""
        operations = []
        operations_digest = ""
        available = False
        proof_integrity = "unavailable"
        refs_digest = ""
    if not valid:
        await _https_mirror_mark_failed(env, row, now)
        return False
    general_healthy = bool(
        status == 200
        and data.get("ok") is True
        and data.get("integrity") == "ok"
    )
    forkmesh_active = bool(
        general_healthy
        and available
        and proof_integrity == "ok"
        and _https_mirror_refs_match(
            refs_digest, accepted_forkmesh_refs)
        and HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS.issubset(
            set(operations))
    )
    if general_healthy and not forkmesh_active:
        # A merge reaches every mirror at once. Until its gateway adopts the
        # new refs the signed proof says "unavailable", then names a digest
        # the pins have not admitted yet, right when each mirror re-registers
        # and is challenged. Revoking here zeroed every lease together and
        # turned git_hosting red after each merge. Such a proof neither renews
        # nor revokes: an unexpired lease runs to its freshness deadline, as
        # it already does through a transient fetch failure.
        if await _https_mirror_hold_lease(
                env, row, now, latency,
                signature=signature,
                message=message,
                refs_digest=refs_digest if (
                    available and proof_integrity == "ok") else "",
                operations_digest=operations_digest,
                operations=operations):
            return False
    verified_at = now if forkmesh_active else 0
    await d1_run(
        env,
        """UPDATE mirror_https_endpoints
              SET checked_at=?,latency_ms=?,healthy=?,integrity=?,
                  health_sig=?,forkmesh_verified_at=?,
                  forkmesh_refs_sha256=?,forkmesh_operations_sha256=?,
                  forkmesh_operations_json=?,
                  forkmesh_active=?,health_message=?,updated_at=?
            WHERE node_bi=?""",
        now,
        latency,
        1 if general_healthy else 0,
        "ok" if general_healthy else "degraded",
        signature,
        verified_at,
        refs_digest if available else "",
        operations_digest if available else "",
        json.dumps(
            operations if available else [],
            separators=(",", ":"),
        ),
        1 if forkmesh_active else 0,
        message if valid else "",
        now,
        row.get("node_bi"),
    )
    if general_healthy:
        # A fresh identity-bound challenge is a real node activity signal.
        await d1_run(
            env, "UPDATE nodes SET last_seen=? WHERE node_bi=?",
            now, row.get("node_bi"))
    # Callers that renew a public routing lease need to know whether this exact
    # repository is eligible for rotation, not merely whether the node's
    # generic health endpoint answered.
    return forkmesh_active


async def https_mirror_health_cron(env):
    """Challenge recently answering endpoints; no repository bytes enter D1."""
    await ensure_schema(env)
    cutoff = int(Date.now()) - HTTPS_MIRROR_STATUS_FRESH_MS
    recovery_node = _https_mirror_flagship_recovery_node(env)
    # Rotate fresh inactive proofs through the same one-endpoint budget as
    # active leases. A commit can briefly outrun the catalog/quorum pin and
    # deactivate one honest mirror while peers remain active; an active-only
    # query never revisited that node. Oldest-attempt ordering keeps a
    # persistently divergent endpoint from starving lease renewal, while the
    # designated recovery node gets the first chance to establish a new fleet
    # generation when it is inactive.
    #
    # Every healthy, recently answering endpoint is a candidate. Requiring an
    # inactive row to carry a digest dropped a mirror challenged between
    # gateway generations (an "unavailable" proof stores none) from the
    # rotation until it re-registered minutes later.
    candidates_sql = """SELECT node_bi,node_name,base_url,mirror_url,public_key
            FROM mirror_https_endpoints
            WHERE healthy=1 AND integrity='ok' AND abuse_blocked=0
              AND checked_at>=?
            ORDER BY
              CASE WHEN forkmesh_active=0 AND node_name=? THEN 0 ELSE 1 END,
              CASE WHEN updated_at > checked_at
                   THEN updated_at ELSE checked_at END ASC,
              node_name ASC
            LIMIT ?"""
    rows = await d1_all(
        env,
        candidates_sql,
        cutoff,
        recovery_node,
        HTTPS_MIRROR_HEALTH_BATCH,
    )
    accepted = await _https_mirror_accepted_forkmesh_refs(env)
    # A missing canonical state pin is a control-plane read failure, not proof
    # that every independent mirror became invalid simultaneously.  Preserve
    # their existing leases; the next minute retries the bounded batch.
    if not accepted:
        return
    if not rows:
        return
    # Keep the alarm runner on one Python task. Python fan-out/timeout wrappers
    # create nested Pyodide tasks which can poison a later scheduled wrapper
    # with "Cannot enter into task" after the invocation has already ended.
    # Oldest-first ordering plus the bounded batch still rotates every endpoint.
    probed = set()
    behind = []
    for row in rows:
        probed.add(str(row.get("node_name") or ""))
        try:
            active = await _https_mirror_health_one(env, row, accepted)
            # The challenge may have advanced the account-owned successor or
            # completed a two-node quorum. Rebuild the bounded accepted set and
            # challenge once more so machine rotation cannot leave the new
            # canonical endpoint inactive until a later alarm.
            if not active:
                refreshed = await _https_mirror_accepted_forkmesh_refs(env)
                if refreshed and refreshed != accepted:
                    active = await _https_mirror_health_one(
                        env, row, refreshed)
                    if active:
                        accepted = refreshed
            if not active:
                behind.append(row)
        except BaseException:
            # A verifier/runtime exception must not leave the same oldest row
            # at the front forever. Advance only its attempt timestamp: the
            # prior checked_at/proof is untouched and therefore expires at the
            # normal routing lease, so this cannot portray a failed probe as
            # healthy. Best-effort because a canceled invocation may reject
            # any further I/O; the next tick will retry safely in that case.
            try:
                await _https_mirror_mark_transient(
                    env, row, int(Date.now()))
            except BaseException:
                pass
            continue
    if not behind:
        return
    # A probed endpoint was ahead of the accepted pins: a commit landed and the
    # fleet moved with it. Challenge one more endpoint in this tick. Two
    # agreeing signed proofs are the quorum that admits the new generation, so
    # the fleet stays active across a commit instead of each mirror aging out
    # one tick at a time (the git_hosting red minutes of 2026-09-14). A tick
    # whose probe was admitted never reaches this query.
    more = await d1_all(
        env,
        candidates_sql,
        cutoff,
        recovery_node,
        HTTPS_MIRROR_HEALTH_BATCH + len(probed),
    )
    for row in more or []:
        if str(row.get("node_name") or "") in probed:
            continue
        try:
            active = await _https_mirror_health_one(env, row, accepted)
            if not active:
                refreshed = await _https_mirror_accepted_forkmesh_refs(env)
                if refreshed and refreshed != accepted:
                    active = await _https_mirror_health_one(
                        env, row, refreshed)
                    if active:
                        # The new generation also admits the endpoints this
                        # tick already found behind.
                        for earlier in behind:
                            try:
                                await _https_mirror_health_one(
                                    env, earlier, refreshed)
                            except BaseException:
                                pass
        except BaseException:
            try:
                await _https_mirror_mark_transient(
                    env, row, int(Date.now()))
            except BaseException:
                pass
        break



async def _https_mirror_private_candidates(
        env, private_record, preferred_region):
    """Resolve only active, current-epoch opaque routes after authorization."""
    rows = await d1_all(
        env,
        """SELECT r.opaque_replica_id,r.replica_sha256,r.key_epoch,
                  e.node_name,e.base_url,e.public_key,e.registration_sig,
                  e.issued_at,e.checked_at,e.latency_ms,e.region,e.healthy,
                  e.integrity,e.abuse_blocked
             FROM private_mirror_routes r
             JOIN mirror_https_endpoints e ON e.node_bi=r.node_bi
            WHERE r.repo_bi=? AND r.active=1 AND r.key_epoch=?""",
        private_record["repoBi"], private_record["keyEpoch"],
    )
    route_by_node = {}
    records = []
    for row in rows or []:
        node = clean_string(
            row.get("node_name", ""), MAX_NODE_NAME).strip().lower()
        opaque_id = clean_string(
            row.get("opaque_replica_id", ""), 64).strip().lower()
        digest = clean_string(
            row.get("replica_sha256", ""), 64).strip().lower()
        if (
            not valid_node_name(node)
            or not re.fullmatch(r"[0-9a-f]{64}", opaque_id)
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            continue
        projected = _https_mirror_endpoint_projection(row)
        records.append(projected)
        route_by_node[node] = {
            "opaqueId": opaque_id,
            "replicaSha256": digest,
            "keyEpoch": int(row.get("key_epoch") or 0),
        }
    cursor_row = await d1_first(
        env, "SELECT cursor FROM edge_route_cursor WHERE repo_bi=?",
        private_record["repoBi"])
    selected = https_routing.select_endpoints(
        records,
        int(Date.now()),
        preferred_region=preferred_region,
        cursor=int((cursor_row or {}).get("cursor") or 0),
    )
    for endpoint in selected:
        endpoint.update(route_by_node.get(endpoint["node"], {}))
    return [
        endpoint for endpoint in selected
        if endpoint.get("opaqueId") and endpoint.get("replicaSha256")
    ]


async def _https_mirror_private_request_authorized(
        env, request, private_record):
    """Verify owner/share Basic auth after the opaque route was resolved.

    Private read credentials are never accepted from a URL or query string and
    are never forwarded to a mirror.  Repository identity comes only from the
    encrypted record selected by the random opaque id.
    """
    if not private_record:
        return False
    return await _basic_auth_view_ok(
        env,
        private_record.get("owner", ""),
        private_record.get("repo", ""),
        request,
    )


def _private_replica_not_found():
    """One cache-safe denial shape for unknown, inactive, and unauthorized ids."""
    return json_response(
        {"error": "not_found"}, status=404,
        cache_control="no-store, max-age=0, must-revalidate")


GIT_ERROR_HELP_URL = "https://forkmesh.com/docs/git-errors/"
GIT_ERROR_MESSAGES = {
    "not_found": "ForkMesh has no public repository at this address. "
                 "Check the owner and repository name.",
    "mirror_unavailable": "ForkMesh could not reach a mirror of this "
                          "repository just now. Try again in a minute.",
    "push_unavailable": "ForkMesh could not reach the node that accepts "
                        "pushes for this repository. Try again in a minute.",
    "push_unauthorized": "Pushing over HTTPS needs your ForkMesh account "
                         "name and the repository's push credential.",
    "authentication_required": "This repository is private. Sign in with "
                               "your ForkMesh account name and the "
                               "repository's credential.",
    "method_not_allowed": "This Git address does not accept that request.",
}
GIT_ERROR_KEPT_HEADERS = (
    "cache-control", "retry-after", "www-authenticate",
    EXPECTED_DEGRADED_HEADER, "x-forkmesh-served-by",
)


async def _git_error_as_text(response, env=None):
    try:
        status = int(getattr(response, "status", 0) or 0)
        content_type = str(response.headers.get("content-type") or "")
    except Exception:
        return response
    if status < 400 or "json" not in content_type.lower():
        return response
    try:
        payload = json.loads(str(await response.text()))
    except Exception:
        payload = None
    if not isinstance(payload, dict):
        payload = {}
    code = clean_string(str(payload.get("error") or ""), 80)
    message = (
        clean_string(str(payload.get("message") or payload.get("hint") or ""),
                     400)
        or GIT_ERROR_MESSAGES.get(code)
        or "ForkMesh answered HTTP %d%s." % (
            status, " (%s)" % code if code else ""))
    headers = {"content-type": "text/plain; charset=utf-8"}
    for name in GIT_ERROR_KEPT_HEADERS:
        try:
            value = response.headers.get(name)
        except Exception:
            value = None
        if not js_nullish(value):
            headers[name] = str(value)
    if env is not None and instance_features.branded(env):
        return Response(instance_features.rename(env, message) + "\n",
                        status=status, headers=headers)
    return Response(
        "%s\nHelp: %s\n" % (message, GIT_ERROR_HELP_URL),
        status=status, headers=headers)


# The retired repository tunnel answers a fixed, content-free body: it depends
# on no owner, repository, or viewer, so one client can safely reuse it. The
# route is gone permanently, and `no-store` only guaranteed that every stale
# client re-asked the Worker on every retry — a per-second poll from one old
# page billed two invocations (Worker plus ingress object) forever. A long
# max-age lets the client answer itself instead.
REPOSITORY_SOCKET_RETIRED_PAYLOAD = {
    "error": "repository_socket_transport_retired",
    "httpsMirrorRequired": True,
    "socketFallback": False,
}
REPOSITORY_SOCKET_RETIRED_CACHE_CONTROL = "public, max-age=86400"


def _repository_socket_retired():
    """The one 410 for the retired `/host` repository socket transport."""
    return json_response(
        REPOSITORY_SOCKET_RETIRED_PAYLOAD, status=410,
        cache_control=REPOSITORY_SOCKET_RETIRED_CACHE_CONTROL)


def _retired_repository_socket_path(path):
    """Whether ``path`` is the retired ``/api/repo/<owner>/<repo>/host``.

    The same shape REPO_HOST_RE matches for the ``host`` action, spelled
    without a regex so the stateless fast path can answer a retired route
    without pulling the lazy url-pattern module into a cold isolate.
    """
    value = str(path or "")
    if not value.startswith("/api/repo/") or not value.endswith("/host"):
        return False
    middle = value[len("/api/repo/"):-len("/host")]
    owner, separator, repo = middle.partition("/")
    return bool(owner) and bool(separator) and bool(repo) and "/" not in repo


async def _https_mirror_private_access_handler(
        env, request, url, opaque_id):
    """Authorize and serve an identity-free private-replica request."""
    # A query would put credentials or repository hints into intermediary and
    # platform logs. Even harmless-looking query parameters are rejected so
    # there is exactly one supported private client request shape.
    if method_name(request) not in ("GET", "HEAD") or url.query:
        return _private_replica_not_found()
    private_record = await _https_mirror_private_access_record(env, opaque_id)
    if (
        private_record is None
        or not await _https_mirror_private_request_authorized(
            env, request, private_record)
    ):
        return _private_replica_not_found()
    return await _https_mirror_private_proxy(env, request, private_record)


async def _https_mirror_private_proxy(env, request, private_record):
    """Stream an authorized owner-sealed archive; never request plaintext."""
    method = method_name(request)
    if method not in ("GET", "HEAD"):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    if private_record is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    if not router_public_key or not router_seed:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    candidates = await _https_mirror_private_candidates(
        env, private_record, world_request_country(request))
    if not candidates:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    for endpoint in candidates:
        target = https_routing.masked_private_replica_url(
            endpoint["baseUrl"], endpoint["opaqueId"])
        parsed_target = urlparse(target)
        signed_path = parsed_target.path
        request_id = _b64url_encode(_random_bytes(18))
        issued_at = int(Date.now())
        body_digest = https_routing.empty_body_sha256()
        message = https_routing.request_message(
            endpoint["node"], method, signed_path, body_digest, request_id,
            issued_at)
        signature = await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if not target or not message or not signature:
            continue
        headers = {
            "X-ForkMesh-Node": endpoint["node"],
            "X-ForkMesh-Request-Id": request_id,
            "X-ForkMesh-Issued-At": str(issued_at),
            "X-ForkMesh-Body-Sha256": body_digest,
            "X-ForkMesh-Signature": signature,
        }
        try:
            # Native AbortSignal timeout, not asyncio.wait_for — the private
            # replica read rides the same clone path whose wedges this rule
            # exists for (see the top of this module).
            upstream = await js_fetch_with_timeout(
                target,
                {
                    "method": method,
                    "headers": headers,
                    "redirect": "manual",
                },
                HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
            )
            status = int(getattr(upstream, "status", 0) or 0)
        except Exception:
            upstream = None
            status = 0
        if upstream is None or status != 200:
            continue
        try:
            content_type = str(
                upstream.headers.get("content-type") or "").split(";", 1)[0]
            etag = str(upstream.headers.get("etag") or "")
            announced = int(upstream.headers.get("content-length") or 0)
        except Exception:
            continue
        expected_etag = '"sha256-' + endpoint["replicaSha256"] + '"'
        if (
            content_type
            != "application/vnd.forkmesh.private-replica+json"
            or not hmac.compare_digest(etag, expected_etag)
            or announced <= 0
            or announced > 2 * 1024 * 1024 * 1024
        ):
            continue
        raw_headers = {}
        for name in (
            "content-type", "content-length", "etag", "content-disposition",
        ):
            try:
                value = upstream.headers.get(name)
            except Exception:
                value = None
            # A header the endpoint omitted arrives as JS null, which is not
            # None and stringifies to "jsnull" — see _https_mirror_proxy.
            if not js_nullish(value):
                raw_headers[name] = str(value)
        response_headers = https_routing.response_headers(raw_headers)
        response_headers["cache-control"] = (
            "no-store, max-age=0, must-revalidate")
        await _https_mirror_route_advance(
            env, private_record, endpoint["node"], "private-replica")
        return JsResponse.new(
            upstream.body,
            to_js({"status": 200, "headers": response_headers}),
        )
    return json_response(
        {"error": "mirror_unavailable"}, status=503,
        cache_control="no-store",
        extra_headers=EXPECTED_DEGRADED_HEADERS)


async def _hosted_repository_import_route(env, owner, repo):
    """Resolve one public logical import name to its physical mirror catalog."""
    repository_import = _repository_import_module()
    owner_l = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo_l = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(owner_l) or not safe_segment(repo_l):
        return None
    rows = await d1_all(
        env,
        "SELECT data FROM repository_imports "
        "WHERE is_private=0 AND status='actively_mirrored' "
        "ORDER BY updated_at DESC LIMIT ?",
        repository_import.MAX_PUBLIC_IMPORTS,
    )
    for row in rows or []:
        record = await decrypt_row(env, row.get("data"))
        if not isinstance(record, dict):
            continue
        target_owner = clean_string(
            record.get("targetOwner"), MAX_NODE_NAME).strip().lower()
        name = clean_string(
            record.get("name"), MAX_REPO_SEGMENT).strip().lower()
        if target_owner != owner_l or name != repo_l:
            continue
        mirror = record.get("mirror") or {}
        mirror_owner = clean_string(
            mirror.get("owner"), MAX_NODE_NAME).strip().lower()
        mirror_name = clean_string(
            mirror.get("name"), MAX_REPO_SEGMENT).strip()
        # Any node that published the hosted copy may serve it. The original
        # burst ran on mirror2/mirror3, both retired since; pinning their names
        # here meant a newly hosted import resolved to nothing and the entry
        # kept sending people back to its provider (issue #679). The caller
        # still has to find this owner/name in the public catalog, so an
        # unpublished or blocked pair cannot be routed to.
        if valid_node_name(mirror_owner) and safe_segment(mirror_name):
            return mirror_owner, mirror_name
    return None


# A source-authorized, KV-TTL override breaks pin deadlocks only on the 503 path.
ADMISSION_OVERRIDE_PREFIX = "admission-override:"
ADMISSION_OVERRIDE_DEFAULT_TTL = 30 * 60
ADMISSION_OVERRIDE_MAX_TTL = 6 * 60 * 60


async def _admission_override_active(env, repo_bi):
    repo_bi = str(repo_bi or "")
    if not repo_bi:
        return False
    namespace = getattr(env, "REPOSITORY_METADATA", None)
    if namespace is None:
        return False
    try:
        _cron_subrequest_charge()
        raw = await namespace.get(ADMISSION_OVERRIDE_PREFIX + repo_bi)
    except Exception:
        return False
    return raw is not None


async def _admission_override_set(env, repo_bi, ttl_seconds):
    repo_bi = str(repo_bi or "")
    namespace = getattr(env, "REPOSITORY_METADATA", None)
    if namespace is None or not repo_bi:
        return 0
    try:
        ttl = int(ttl_seconds if ttl_seconds is not None
                  else ADMISSION_OVERRIDE_DEFAULT_TTL)
    except (TypeError, ValueError):
        ttl = ADMISSION_OVERRIDE_DEFAULT_TTL
    ttl = max(60, min(ttl, ADMISSION_OVERRIDE_MAX_TTL))
    try:
        await namespace.put(
            ADMISSION_OVERRIDE_PREFIX + repo_bi,
            str(int(Date.now())),
            to_js({"expirationTtl": ttl}),
        )
    except Exception:
        return 0
    return ttl


async def _admin_set_admission_override(env, request):
    # Signed source-of-truth override: an admin proves control of their node key
    # (the same auth as every other admin mutation) and opens a bounded window
    # during which the group's mirrors are admitted at their advertised states,
    # so a repo deadlocked out of the pin window recovers instead of staying
    # unavailable. The window auto-expires via the KV TTL.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    owner = clean_string(data.get("owner", ""), MAX_NODE_NAME).lower()
    repo = clean_string(data.get("repo", ""), MAX_REPO_SEGMENT).strip().lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(owner) or not safe_segment(repo):
        return json_response({"error": "invalid_repo"}, status=400)
    canonical = ("forkmesh-admission-override-v1\n" + node + "\n"
                 + owner + "/" + repo + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    repo_bi = await blind_index(env, owner + "/" + repo)
    ttl = await _admission_override_set(env, repo_bi, data.get("ttlSeconds"))
    await _audit_sensitive_action(
        env, node, "admin.admission_override", "repository",
        owner + "/" + repo, "success" if ttl else "error",
        {"ttlSeconds": ttl})
    return json_response(
        {"ok": bool(ttl), "repo": owner + "/" + repo, "ttlSeconds": ttl})


def _https_mirror_history_keys(
        members, primary_key="", linked_canonical=False):
    """Select the bounded authority-priority history keys routing consumes."""
    primary_key = str(primary_key or "")
    if linked_canonical:
        return [primary_key] if primary_key else []
    return repo_mirror_pin_history_keys(members, members, primary_key)


class _HttpsMirrorContextUnavailable(Exception):
    """The routing snapshot could not be built for an existing repository.

    Distinct from "no such public repository", which stays a plain ``None``.
    Collapsing the two made a transient fault inside the builder -- a D1
    hiccup, a catalog decrypt failure, a maintenance phase reaching its
    subrequest ceiling -- answer 404 not_found for a repository that plainly
    exists, and every consumer then reported the repository, not the relay.
    The installer status row is the visible case: it read that 404 as "the
    mirror answered, the file is gone" and published "Installer release
    metadata is unavailable: release.json" for files that were being served
    the whole time.
    """


async def _https_mirror_public_context(env, owner, repo):
    """Return canonical public repo identity and integrity-approved node set.

    Raises ``_HttpsMirrorContextUnavailable`` when the snapshot could not be
    built. Returns ``None`` only when this is not a routable public repo.
    """
    owner_l = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo_l = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(owner_l) or not safe_segment(repo_l):
        return None
    try:
        now = int(Date.now())
        cached = _https_mirror_public_context_cache_get(
            owner_l, repo_l, now)
        if cached is not None:
            return cached
        await ensure_schema(env)
        rows = [
            row for row in await _decrypted_public_catalog(env, now)
            if (
                not row.get("is_private")
                and (row.get("data") or {}).get("visibility") == "public"
                and not _is_blocked_catalog_identity(
                    env,
                    (row.get("data") or {}).get("owner"),
                    (row.get("data") or {}).get("name"),
                )
            )
        ]
        target_row = None
        for row in rows:
            record = row.get("data") or {}
            if (
                str(record.get("owner") or "").lower() == owner_l
                and str(record.get("name") or "").lower() == repo_l
            ):
                target_row = row
                break
        if not target_row:
            hosted_route = await _hosted_repository_import_route(
                env, owner_l, repo_l)
            if hosted_route:
                hosted_owner, hosted_repo = hosted_route
                for row in rows:
                    record = row.get("data") or {}
                    if (
                            str(record.get("owner") or "").lower()
                            == hosted_owner
                            and str(record.get("name") or "").lower()
                            == hosted_repo.lower()):
                        target_row = row
                        break
            if not target_row:
                return None
        # Secondary devices are not catalog authorities, but their signed refs
        # may still serve once they match the authority's pin. Fold them into
        # this routing decision as effective remote clones without allowing
        # their self-attestations to create a trusted pin.
        device_rows = await d1_all(
            env,
            "SELECT node_id,data FROM repo_device_mirrors WHERE repo_bi=?",
            target_row.get("key_bi"),
        )
        for device_row in device_rows or []:
            device_record = await decrypt_row(env, device_row.get("data"))
            if not isinstance(device_record, dict):
                continue
            device_record["reportedSource"] = device_record.get("source")
            device_record["source"] = "remote-clone"
            rows.append({
                "key_bi": target_row.get("key_bi"),
                "data": device_record,
            })
        target = target_row["data"]
        members = [
            row for row in rows
            if repo_mirror_same_group(target, row.get("data") or {})
        ]
        # In linked-canonical mode only the explicitly linked target's history
        # is consumed below. Resolve that before the history read rather than
        # scanning histories that cannot affect the routing decision.
        linked_target = await d1_first(
            env,
            "SELECT 1 AS linked FROM org_repos "
            "WHERE node_owner=? AND repo=? LIMIT 1",
            owner_l,
            repo_l,
        )
        # One deterministic, bind-safe history read is enough to preserve the
        # routing pin window. A malformed or unexpectedly wide catalog group
        # must not turn one deep status probe into unbounded D1 subrequests.
        group_keys = _https_mirror_history_keys(
            members,
            target_row.get("key_bi"),
            linked_canonical=bool(linked_target),
        )
        history = await _bounded_repo_state_history(env, group_keys)
        # Explicit organization links supply the canonical signed pin window.
        catalog_group_nodes = set()
        for row in members:
            record = row.get("data") or {}
            node = clean_string(
                record.get("machineName") or record.get("owner", ""),
                MAX_NODE_NAME,
            ).strip().lower()
            if valid_node_name(node):
                catalog_group_nodes.add(node)
        quorum = {
            "pins": frozenset(),
            "nodes": frozenset(),
            "nodeDigests": {},
        }
        if linked_target:
            pins = set()
            current_pins = set()
            target_state = clean_string(
                target.get("stateHash", ""), 64).lower()
            if re.fullmatch(r"[0-9a-f]{64}", target_state):
                pins.add(target_state)
                current_pins.add(target_state)
            for state in history.get(
                    str(target_row.get("key_bi") or ""), []):
                state = clean_string(state, 64).lower()
                if re.fullmatch(r"[0-9a-f]{64}", state):
                    pins.add(state)
            # The linked row establishes the stable organization identity, not
            # a preferred endpoint. Two fresh, independently signed matching
            # group proofs may advance the flagship state even when that row's
            # original host (historically mirror2) has been removed.
            quorum = await _https_mirror_flagship_quorum(
                env, catalog_group_nodes)
            pins.update(quorum.get("pins", ()))
            current_pins.update(quorum.get("pins", ()))
            # The configured headless trust anchor's account is a narrowly
            # scoped dynamic authority for this flagship group. The selected
            # successor's endpoint identity, required operations, freshness,
            # and repository proof were all validated while building
            # ``quorum``; unrelated peers remain outside both pin sets.
            recovery_pins = await _https_mirror_flagship_recovery_refs(
                env, quorum)
            pins.update(recovery_pins)
            current_pins.update(recovery_pins)
            # Catalog publication and application deployment are separate.
            # For the public flagship only, admit the exact default-branch and
            # tags generation compiled into this Worker. This is the same pin
            # the health verifier uses, so an endpoint cannot be "healthy" yet
            # still disappear from bypass-cache Git and installer routing.
            deployed_pins = _https_mirror_deployed_flagship_refs(
                env, owner_l, repo_l)
            pins.update(deployed_pins)
            current_pins.update(deployed_pins)
            pins = pins or None
        else:
            pins = clone_state_pins(
                target, target_row.get("key_bi"), members, history)
            current_pins = set()
            for row in members:
                record = row.get("data") or {}
                state = clean_string(
                    record.get("stateHash", ""), 64).lower()
                if (
                    str(record.get("source") or "local-node")
                    == "local-node"
                    and re.fullmatch(r"[0-9a-f]{64}", state)
                ):
                    current_pins.add(state)
        # Direct routing never uses the legacy unpinned fail-open behavior. An
        # owner must publish an authenticated refs digest before a remote
        # endpoint can advertise or resolve that repository.
        if not pins:
            return None
        allowed = set()
        group_nodes = set()
        group_mirrors = set()
        allowed_mirrors = set()
        current_nodes = set()
        source = None
        for row in members:
            record = row.get("data") or {}
            node = clean_string(
                record.get("machineName") or record.get("owner", ""),
                MAX_NODE_NAME).lower()
            state = clean_string(record.get("stateHash", ""), 64).lower()
            if not valid_node_name(node):
                continue
            is_mirror = (
                str(record.get("source") or "local-node") != "local-node")
            group_nodes.add(node)
            if is_mirror:
                group_mirrors.add(node)
            endpoint_state = quorum.get("nodeDigests", {}).get(node, "")
            if pins and state not in pins and endpoint_state not in pins:
                continue
            allowed.add(node)
            if is_mirror:
                allowed_mirrors.add(node)
            if state in current_pins or endpoint_state in current_pins:
                current_nodes.add(node)
            if source is None and not is_mirror:
                source = record
        if (
            not linked_target and group_mirrors
            and (not allowed_mirrors or not source
                 or target.get("source") == "remote-clone")
        ):
            # Two fresh integrity-approved peers may recover a group abandoned
            # by its source; one divergent peer cannot move the route alone.
            quorum = await _https_mirror_flagship_quorum(env, group_nodes)
            quorum_pins = set(quorum.get("pins", ()))
            # The signed endpoint proof covers the flagship repository, so for
            # every OTHER repo its digest can never match this group's state
            # and the recovery above finds nothing — which is why an ordinary
            # user's repo stayed dark for good once its desktop stopped
            # publishing. Two independently published catalog records agreeing
            # on a state is the same two-distinct-nodes evidence, and it is
            # available for every repo. Widening pins does not by itself let a
            # divergent endpoint serve: _https_mirror_repository_proof still
            # requires the live signed refs digest to be one of these pins.
            quorum_pins |= peer_quorum_pins(target, members)
            if quorum_pins:
                pins = set(pins) | quorum_pins
                current_pins = set(current_pins) | quorum_pins
                for row in members:
                    record = row.get("data") or {}
                    node = clean_string(
                        record.get("machineName") or record.get("owner", ""),
                        MAX_NODE_NAME).lower()
                    if node not in group_nodes:
                        continue
                    state = clean_string(
                        record.get("stateHash", ""), 64).lower()
                    endpoint_state = quorum.get(
                        "nodeDigests", {}).get(node, "")
                    if state in pins or endpoint_state in pins:
                        allowed.add(node)
                        current_nodes.add(node)
        endpoint_digests = quorum["nodeDigests"]
        # "No eligible serving endpoint" means no admitted node is live on a
        # state these pins accept — not merely that no admitted node is live.
        # An endpoint whose signed digest is outside the pin set cannot serve
        # (_https_mirror_repository_proof refuses it), so a group of admitted
        # but divergent endpoints is exactly the stuck case the operator
        # override exists to reopen, and must not read as recovered.
        servable = {
            node for node, digest in endpoint_digests.items()
            if node in allowed and digest in pins
        }
        if not allowed or (endpoint_digests and not servable):
            if pins and await _admission_override_active(
                    env, target_row.get("key_bi")):
                pins.update(admission_override_pins(members),
                            endpoint_digests.values())
                current_pins.update(endpoint_digests.values())
            else:
                if not allowed:
                    return None
            for row in members:
                record = row.get("data") or {}
                node = clean_string(
                    record.get("machineName") or record.get("owner", ""),
                    MAX_NODE_NAME).lower()
                if not valid_node_name(node):
                    continue
                state = clean_string(record.get("stateHash", ""), 64).lower()
                endpoint_state = endpoint_digests.get(node, "")
                if state in pins or endpoint_state in pins:
                    allowed.add(node)
                    if endpoint_state in current_pins:
                        current_nodes.add(node)
                    if (
                        source is None
                        and str(record.get("source") or "local-node")
                        == "local-node"
                    ):
                        source = record
            if not allowed:
                return None
        canonical = source or target
        canonical_owner = clean_string(
            canonical.get("owner", ""), MAX_NODE_NAME).lower()
        canonical_repo = clean_string(
            canonical.get("name", ""), MAX_REPO_SEGMENT)
        if (
            not valid_node_name(canonical_owner)
            or not safe_segment(canonical_repo)
        ):
            return None
        repo_bi = await blind_index(
            env, canonical_owner + "/" + canonical_repo.lower())
        source_state = clean_string(
            canonical.get("stateHash", ""), 64).strip().lower()
        if not re.fullmatch(r"[0-9a-f]{64}", source_state):
            source_state = ""
        # An organization owner's web merge (executed by one mirror while the
        # source is offline) defines the repository's current generation
        # until the source publishes again: admit and prefer every member
        # already serving it so the rest of the fleet can fetch it from them.
        override_state = await _owner_merge_pin_state(
            env, repo_bi, source_state)
        if override_state:
            pins = set(pins)
            pins.add(override_state)
            current_pins = set(current_pins)
            current_pins.add(override_state)
            endpoint_digests = quorum.get("nodeDigests", {})
            for row in members:
                record = row.get("data") or {}
                node = clean_string(
                    record.get("machineName") or record.get("owner", ""),
                    MAX_NODE_NAME).lower()
                if not valid_node_name(node):
                    continue
                state = clean_string(record.get("stateHash", ""), 64).lower()
                if (
                    state == override_state
                    or endpoint_digests.get(node, "") == override_state
                ):
                    allowed.add(node)
                    current_nodes.add(node)
        hosted_nodes_of = globals().get("hosted_core_nodes")
        if target.get("source") == "hosted-web" and callable(hosted_nodes_of):
            # A ForkMesh-hosted repository is served by the core nodes, which
            # publish no catalog record of their own (docs/HOSTED_REPOS.md).
            # Each is still admitted only by its signed repository proof.
            hosted_nodes = set(hosted_nodes_of(env))
            if hosted_nodes:
                allowed = set(allowed) | hosted_nodes
                current_nodes = set(current_nodes) | hosted_nodes
                group_nodes = set(group_nodes) | hosted_nodes
        context = {
            "owner": canonical_owner,
            "repo": canonical_repo,
            # The canonical local-node record is the only collaboration writer
            # while its signed endpoint health is fresh.  Consumers must not
            # infer this from the first eligible routing node: mirrors can be
            # fresher than the source and participate in the same cursor ring.
            "sourceNode": clean_string(
                canonical.get("machineName") or canonical.get("owner", ""),
                MAX_NODE_NAME,
            ).strip().lower(),
            "nodes": allowed,
            # Every node publishing a record in this mirror group, including
            # the ones the state-pin gate currently excludes from serving.
            # Routing must keep using "nodes"; this set exists so an operator
            # diagnostic can tell "not a mirror of this repository" apart from
            # "a mirror that is behind the signed pin window".
            "groupNodes": group_nodes,
            # Ordinary reads prefer the newest source generation. Recent
            # signed generations remain available strictly as failover while
            # their nodes converge.
            "currentNodes": current_nodes,
            "pins": set(pins),
            # KV entries are addressed only by the current source-attested
            # refs state. Historical pins may serve as temporary failover but
            # can never populate a current-generation immutable cache entry.
            "currentPins": set(current_pins),
            # Organization aliases identify a logical repository. They never
            # nominate their linked catalog host as a traffic endpoint: every
            # fresh integrity-approved member participates in one cursor ring.
            "roundRobinAll": bool(linked_target),
            "repoBi": repo_bi,
            # The source-of-truth record's own attested refs state, recorded
            # with an owner-authorized mutation job so the relay can tell a
            # still-offline source apart from one that has since published.
            "sourceState": source_state,
            # The refs state an owner's web merge made current, if any.
            "ownerMergeState": override_state,
        }
        return _https_mirror_public_context_cache_put(
            owner_l, repo_l, context, now)
    except _HttpsMirrorContextUnavailable:
        raise
    except Exception:
        raise _HttpsMirrorContextUnavailable()


def _https_mirror_endpoint_projection(row):
    return {
        "node": row.get("node_name"),
        "baseUrl": row.get("base_url"),
        "mirrorUrl": row.get("mirror_url"),
        "publicKey": row.get("public_key"),
        "signature": row.get("registration_sig"),
        "issuedAt": row.get("issued_at"),
        "checkedAt": row.get("checked_at"),
        "latencyMs": row.get("latency_ms"),
        "region": row.get("region"),
        "healthy": bool(row.get("healthy")),
        "integrity": row.get("integrity"),
        "abuseBlocked": bool(row.get("abuse_blocked")),
        "refsSha256": row.get("forkmesh_refs_sha256"),
    }


def _https_mirror_advertised_operation_nodes(rows, operation):
    """Group nodes whose last signed advertisement carried this operation.

    The health phase challenges every endpoint for forkmesh/forkmesh, so the
    stored set names one repository. It is therefore only ever a routing
    preference: the per-repository signed proof the caller runs next is what
    admits a node for the operation it is about to route.
    """
    nodes = set()
    if not operation:
        return nodes
    for row in rows or []:
        node = str(row.get("node_name") or "").strip().lower()
        if not node:
            continue
        try:
            operations = json.loads(
                str(row.get("forkmesh_operations_json") or "[]"))
        except Exception:
            operations = []
        if isinstance(operations, list) and operation in operations:
            nodes.add(node)
    return nodes


MAX_AVOIDED_MIRROR_NODES = 4


def _https_mirror_avoided_nodes(value):
    avoided = []
    for part in str(value or "").lower().split(","):
        name = part.strip()
        if name and valid_node_name(name) and name not in avoided:
            avoided.append(name)
        if len(avoided) == MAX_AVOIDED_MIRROR_NODES:
            break
    return frozenset(avoided)


def _https_mirror_record_avoided(record, avoided):
    node = str(record.get("node") or "").strip().lower()
    if node in avoided:
        return True
    for key in ("baseUrl", "mirrorUrl"):
        host = (urlparse(str(record.get(key) or "")).hostname or "").lower()
        if host and host.split(".", 1)[0] in avoided:
            return True
    return False


async def _https_mirror_candidates(
        env, context, preferred_region, sticky="", avoid_node="",
        operation=""):
    rows = await d1_all(
        env,
        """SELECT node_name,base_url,mirror_url,public_key,
                  registration_sig,issued_at,
                  checked_at,latency_ms,region,healthy,integrity,abuse_blocked,
                  forkmesh_refs_sha256,forkmesh_operations_json
             FROM mirror_https_endpoints""",
    )
    rows = [
        row for row in rows or []
        if str(row.get("node_name") or "").lower() in context["nodes"]
    ]
    records = [_https_mirror_endpoint_projection(row) for row in rows]
    # A mirror reconciling through the public relay must not be routed back to
    # its own stale endpoint. Git sends this bounded hint on both advertisement
    # and upload-pack requests; ordinary clients omit it. Filtering before the
    # cursor ring preserves normal randomized balancing and lets a lagging node
    # deterministically reach another current peer.
    avoided = _https_mirror_avoided_nodes(avoid_node)
    if avoided:
        records = [
            record for record in records
            if not _https_mirror_record_avoided(record, avoided)
        ]
    # Selection does not need a globally serialized D1 counter. A random
    # rotation distributes independent reads while the clone's upload-pack is
    # still pinned to its advertisement below. The retired cursor cost one D1
    # read plus one D1 write on virtually every uncached repository request.
    cursor = int.from_bytes(_random_bytes(4), "big")
    now = int(Date.now())
    sticky = str(sticky or "").strip().lower()
    # Endpoints this request is already committed to, held inside the bounded
    # failover window instead of being rotated through it. The clone pin and an
    # in-flight merge job's recorded node are addressed by name, and a mirror
    # that advertises no merge executor can never answer a pull mutation: a
    # random read rotation over a group larger than the window left an owner
    # reading "no online mirror can merge this pull request" while the one
    # capable mirror was healthy and current.
    prefer = {sticky} if sticky else set()
    if (operation in https_routing.MERGE_EXECUTOR_OPERATIONS
            or operation == "git-receive-pack"):
        prefer |= _https_mirror_advertised_operation_nodes(rows, operation)
    if context.get("roundRobinAll"):
        # One ring over the complete live group. The cursor is reduced modulo
        # the current member count by select_endpoints, so adding or removing a
        # mirror cannot strand the route or require a cursor reset.
        selected = https_routing.select_endpoints(
            records, now,
            preferred_region=preferred_region, cursor=cursor, prefer=prefer)
    else:
        current_nodes = {
            str(node or "").lower()
            for node in context.get("currentNodes", set())
        }
        # Catalog identities can nominate one preferred current host even when
        # several healthy endpoints carry the exact same signed refs digest.
        current_nodes = https_routing.equivalent_current_endpoint_nodes(
            records, current_nodes, context.get("currentPins", set())
        )
        current_records = [
            record for record in records
            if str(record.get("node") or "").lower() in current_nodes
        ]
        historical_records = [
            record for record in records
            if str(record.get("node") or "").lower() not in current_nodes
        ]
        selected = https_routing.select_endpoints(
            current_records, now,
            preferred_region=preferred_region, cursor=cursor, prefer=prefer)
        selected.extend(https_routing.select_endpoints(
            historical_records, now,
            preferred_region=preferred_region, cursor=cursor, prefer=prefer))
        selected = https_routing.cap_failover(selected, prefer=prefer)
    if sticky:
        selected.sort(key=lambda item: 0 if item["node"] == sticky else 1)
    return selected


async def _https_mirror_request_candidates(
        env, context, preferred_region, sticky="", monitoring=False,
        context_cache=None, avoid_node="", operation=""):
    """Reuse one fresh candidate decision only inside an explicit probe suite.

    Flagship and installer probes make several sequential reads of the same
    public repository. Rebuilding the endpoint ring for every read repeated the
    same two D1 queries. Their caller-owned context dictionary lasts for just
    that probe invocation, so it can safely share one snapshot without making
    ordinary visitor requests or the next probe reuse stale endpoint health.
    """
    region = str(preferred_region or "").strip().upper()
    sticky = str(sticky or "").strip().lower()
    avoid_node = str(avoid_node or "").strip().lower()
    cache_key = (
        "https-mirror-candidates-v1",
        str(context.get("repoBi") or ""),
        str(context.get("routeOwner") or context.get("owner") or "").lower(),
        str(context.get("repo") or "").lower(),
        region,
        sticky,
        avoid_node,
        operation,
    )
    if monitoring and isinstance(context_cache, dict):
        cached = context_cache.get(cache_key)
        if isinstance(cached, tuple):
            return [dict(endpoint) for endpoint in cached]
    candidates = await _https_mirror_candidates(
        env, context, region, sticky=sticky, avoid_node=avoid_node,
        operation=operation)
    if monitoring and isinstance(context_cache, dict):
        context_cache[cache_key] = tuple(
            dict(endpoint) for endpoint in candidates)
    return candidates


async def _https_mirror_mark_transient_failure(env, node):
    """Remove a transport-failing endpoint until the health cron rechecks it."""
    try:
        await d1_run(
            env,
            """UPDATE mirror_https_endpoints
                  SET healthy=0,checked_at=0,updated_at=?
                WHERE node_name=?""",
            int(Date.now()), node,
        )
    except Exception:
        pass


async def _https_mirror_record_request_rejection(
        env, endpoint, status, monitoring=False):
    """Quarantine definitive visitor auth failures, never monitor failures."""
    if monitoring or int(status or 0) not in (401, 403):
        return False
    try:
        await d1_run(
            env,
            """UPDATE mirror_https_endpoints
                  SET healthy=0,integrity='failed',
                      forkmesh_active=0,updated_at=?
                WHERE node_name=?""",
            int(Date.now()), endpoint["node"])
        return True
    except Exception:
        return False


async def _https_mirror_clone_pin(env, context):
    row = await d1_first(
        env,
        "SELECT owner,ts FROM clone_sticky WHERE repo_bi=?",
        context["repoBi"],
    )
    if (
        row
        and int(Date.now()) - int(row.get("ts") or 0) <= CLONE_STICKY_MS
    ):
        return clean_string(row.get("owner", ""), MAX_NODE_NAME).lower()
    return ""


def _utc_day_key(timestamp_ms):
    """YYYY-MM-DD of a millisecond timestamp in UTC, the dashboard's timezone."""
    return time.strftime("%Y-%m-%d", time.gmtime(int(timestamp_ms) // 1000))


async def repo_traffic_handler(env, request, owner, repo):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    owner = str(owner or "").strip().lower()
    repo = str(repo or "").strip().lower()
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404,
                             cache_control="no-store")
    now = int(Date.now())
    start = _utc_day_key(now - 29 * 24 * 60 * 60 * 1000)
    today = _utc_day_key(now)
    rows = await d1_all(
        env,
        "SELECT day,SUM(clones) AS clones FROM product_clone_daily "
        "WHERE owner=? AND repo=? AND day>=? AND day<=? "
        "GROUP BY day ORDER BY day",
        owner, repo, start, today,
    )
    counts = {
        str(row.get("day") or ""): max(0, int(row.get("clones") or 0))
        for row in rows or []
    }
    days = []
    for offset in range(30):
        day = _utc_day_key(now - (29 - offset) * 24 * 60 * 60 * 1000)
        days.append({"day": day, "clones": counts.get(day, 0)})
    return json_response({
        "ok": True,
        "owner": owner,
        "repo": repo,
        "days": days,
        "totalClones": sum(day["clones"] for day in days),
    }, cache_control="public, max-age=60")


async def _https_mirror_route_advance(env, context, served_node, operation):
    now = int(Date.now())
    # A Git clone has two requests. Preserve only the state it actually needs:
    # upload-pack must return to the endpoint that served info/refs. Ordinary
    # browse/release reads use stateless candidate rotation and write no cursor.
    if operation == "git-info-refs":
        await d1_run(
            env,
            """INSERT INTO clone_sticky(repo_bi,owner,ts) VALUES (?,?,?)
                 ON CONFLICT(repo_bi) DO UPDATE SET
                   owner=excluded.owner,ts=excluded.ts""",
            context["repoBi"], served_node, now,
        )
    # Count upload-pack once per clone; other operations are website reads.
    if operation == "git-info-refs":
        return
    try:
        await world_note_mirror_traffic(env, served_node)
    except Exception:
        pass
    field = "clones" if operation == "git-upload-pack" else "website"
    try:
        await d1_run(
            env,
            """INSERT INTO mirror_serve_counters(
                   node_name,owner,repo,{field},updated_at)
                 VALUES (?,?,?,1,?)
                 ON CONFLICT(node_name,owner,repo) DO UPDATE SET
                   {field}=mirror_serve_counters.{field}+1,
                   updated_at=excluded.updated_at""".format(field=field),
            str(served_node or "").strip().lower(),
            str(context["owner"] or "").strip().lower(),
            str(context["repo"] or "").strip().lower(),
            now,
        )
    except Exception:
        # Best-effort display counter; a D1 hiccup must never fail the read
        # that was just served.
        pass
    if field != "clones":
        return
    # Per-day bucket for the internal product dashboard (migration 0175). The
    # counters above are cumulative, so they cannot answer "clones in the last
    # 30 days". Same rule as above: a D1 hiccup never fails the served read.
    try:
        await d1_run(
            env,
            """INSERT INTO product_clone_daily(day,owner,repo,clones)
                 VALUES (?,?,?,1)
                 ON CONFLICT(day,owner,repo) DO UPDATE SET
                   clones=product_clone_daily.clones+1""",
            _utc_day_key(now),
            str(context["owner"] or "").strip().lower(),
            str(context["repo"] or "").strip().lower(),
        )
    except Exception:
        pass


# Routed operations whose node-side query allowlist includes `ref`. Kept beside
# the query builder so the two never drift: an operation missing from this set
# receives no `ref`, which is exactly what its gateway route accepts.
HTTPS_MIRROR_REF_OPERATIONS = frozenset({
    "tree", "blobs", "blob", "raw", "history", "search", "stats", "sizes",
})


def _repository_read_path(value):
    """Canonicalize one repository-relative read path.

    ``.``, ``./src``, ``/src``, ``src/`` and ``src//main`` all name the same
    directory, but the gateway resolves a path literally and rejects every
    spelling except the canonical one, which reaches the visitor as a routing
    failure: ``tree?path=.`` answered 503 ``mirror_unavailable`` while healthy
    mirrors served ``tree?path=`` (issue #628).  The outage fallback could not
    rescue it either — repository_metadata_cache_key admits only the canonical
    spelling, so that request could neither be served from the attested
    snapshot nor fill it.  Dropping empty and ``.`` segments gives one
    directory one address on both paths.

    ``..`` segments are deliberately preserved rather than resolved: traversal
    must keep failing closed at the gateway, which rejects the segment
    outright, instead of being quietly rewritten into a real path here.
    """
    return "/".join(
        segment for segment in str(value or "").split("/")
        if segment not in ("", ".")
    )


def _https_mirror_request_query(url, operation, release_sha=""):
    params = parse_qs(url.query, keep_blank_values=True)
    if operation == "git-info-refs":
        return {"service": "git-upload-pack"}
    if operation == "release-blob":
        return {"sha256": release_sha}
    output = {}
    if operation == "blobs":
        paths = params.get("path", [])[:MAX_BLOB_BATCH]
        if paths:
            output["path"] = [_repository_read_path(path) for path in paths]
    elif operation == "search":
        query = params.get("q", params.get("path", [""]))[0]
        if query:
            output["path"] = query
    elif operation in ("compare", "merge-preview"):
        keys = ("base", "head")
        if operation == "compare":
            keys += ("cherry", "limit")
        if operation == "merge-preview":
            keys += ("rules", "pull", "orgRules")
        for key in keys:
            if params.get(key):
                output[key] = params[key][0]
    elif operation in ("tree", "blob", "raw", "commit", "history"):
        if params.get("path"):
            output["path"] = _repository_read_path(params["path"][0])
    # Only operations that resolve a ref accept one. compare/merge-preview
    # resolve both endpoints from base/head, and `commit` addresses one object
    # by path, so forwarding the browser's ambient branch selection to them is
    # an unknown parameter the node rejects outright.
    if params.get("ref") and operation in HTTPS_MIRROR_REF_OPERATIONS:
        output["ref"] = params["ref"][0]
    return output


async def _https_mirror_repository_proof(
        env, endpoint, context, operation, origin="", force_refresh=False,
        details=None, retry_failed=False):
    """Require a fresh signed refs/operation proof for this public repo."""
    now = int(Date.now())
    if isinstance(details, dict):
        details.clear()
        details.update({
            "checkedAt": now,
            "status": 0,
            "integrity": "unknown",
            "refsSha256": "",
            "reason": "repository_proof_failed",
        })
    proof_origin = https_routing.normalize_base_url(
        origin or endpoint.get("baseUrl"))
    if not proof_origin:
        if isinstance(details, dict):
            details["reason"] = "mirror_url_invalid"
        return False
    if origin and await _https_mirror_public_dns_ok(proof_origin) is not True:
        if isinstance(details, dict):
            details["reason"] = "mirror_dns_unavailable"
        return False
    route_owner = context.get("routeOwner") or context["owner"]
    pins_key = ",".join(sorted(context["pins"]))
    memo_key = (
        endpoint["node"], proof_origin, route_owner, context["repo"],
        pins_key)
    memo = _HTTPS_MIRROR_REPO_PROOF_MEMO.get(memo_key)
    if memo and memo.get("failed"):
        if (
            not force_refresh
            and not retry_failed
            and now - memo["checkedAt"]
            <= HTTPS_MIRROR_REPO_PROOF_FAILURE_TTL_MS
        ):
            if isinstance(details, dict) and memo.get("reason"):
                # Replay the held verdict so a caller can still tell a signed
                # refs lag from an unreachable or unsigned endpoint.
                details.update({
                    "integrity": memo.get("integrity", "unknown"),
                    "refsSha256": memo.get("refsSha256", ""),
                    "reason": memo["reason"],
                    "signed": bool(memo.get("signed")),
                    "operations": sorted(memo.get("operations", ())),
                })
            return False
    elif (
        not force_refresh
        and memo
        and now - memo["checkedAt"] <= HTTPS_MIRROR_REPO_PROOF_TTL_MS
    ):
        endpoint["refsSha256"] = memo.get("refsSha256", "")
        operation_available = operation in memo["operations"]
        if isinstance(details, dict):
            details.update({
                "integrity": "ok",
                "signed": True,
                "operations": sorted(memo["operations"]),
                "refsSha256": endpoint["refsSha256"],
                "reason": (
                    "verified" if operation_available
                    else "git_operation_unavailable"
                ),
            })
        return operation_available
    edge_cache_key = https_routing.repository_proof_cache_key(
        endpoint, context, HTTPS_MIRROR_REPO_PROOF_EDGE_PREFIX,
        proof_origin if origin else "")
    if not force_refresh:
        cached = await https_routing.repository_proof_cache_get(
            js_caches.default, edge_cache_key, now, context["pins"],
            HTTPS_MIRROR_REPO_PROOF_TTL_MS)
        if cached is not None:
            if (
                len(_HTTPS_MIRROR_REPO_PROOF_MEMO)
                >= HTTPS_MIRROR_REPO_PROOF_MEMO_MAX
            ):
                _HTTPS_MIRROR_REPO_PROOF_MEMO.clear()
            _HTTPS_MIRROR_REPO_PROOF_MEMO[memo_key] = cached
            endpoint["refsSha256"] = cached["refsSha256"]
            operation_available = operation in cached["operations"]
            if isinstance(details, dict):
                details.update({
                    "integrity": "ok",
                    "signed": True,
                    "operations": sorted(cached["operations"]),
                    "refsSha256": endpoint["refsSha256"],
                    "reason": (
                        "verified" if operation_available
                        else "git_operation_unavailable"
                    ),
                })
            return operation_available
    nonce = _b64url_encode(_random_bytes(18))
    target = (
        proof_origin + "/health?nonce=" + quote(nonce)
        + "&issuedAt=" + str(now)
        + "&owner=" + quote(route_owner)
        + "&repo=" + quote(context["repo"])
    )
    status, text = await _https_mirror_fetch_text(
        target,
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    if isinstance(details, dict):
        details["status"] = int(status or 0)
    signed = False
    reason = "repository_response_invalid"
    proof_integrity = "unknown"
    integrity_verified = False
    try:
        data = json.loads(text) if text else {}
        proof = data.get("repositoryProof")
        challenge = data.get("challenge")
        operations = proof.get("operations")
        operations_digest = https_routing.operations_sha256(operations)
        available = proof.get("available") is True
        proof_integrity = str(proof.get("integrity") or "").lower()
        refs_digest = str(proof.get("refsSha256") or "").lower()
        claimed_operations_digest = str(
            proof.get("operationsSha256") or "").lower()
        message = https_routing.repository_health_challenge(
            endpoint["node"],
            nonce,
            now,
            proof.get("owner"),
            proof.get("repository"),
            available,
            proof_integrity,
            refs_digest,
            claimed_operations_digest,
        )
        signed = bool(
            isinstance(data, dict)
            and data.get("node") == endpoint["node"]
            and data.get("publicKey") == endpoint["publicKey"]
            and data.get("transport") == "direct-https"
            and isinstance(proof, dict)
            and proof.get("owner") == route_owner
            and proof.get("repository") == context["repo"]
            and operations_digest
            and operations_digest == claimed_operations_digest
            and isinstance(challenge, dict)
            and challenge.get("messageType")
            == "forkmesh-https-health-repository-v1"
            and challenge.get("nonce") == nonce
            and int(challenge.get("issuedAt") or 0) == now
            and challenge.get("algorithm") == "Ed25519"
            and challenge.get("encoding") == "base64url-no-padding"
            and message
            and challenge.get("messageSha256")
            == hashlib.sha256(message.encode("utf-8")).hexdigest()
            and await ed25519_verify(
                endpoint["publicKey"],
                str(challenge.get("signature") or ""),
                message.encode("utf-8"),
            )
        )
        endpoint_healthy = bool(
            status == 200
            and data.get("ok") is True
            and data.get("integrity") == "ok"
        )
        refs_match = refs_digest in context["pins"]
        operation_available = operation in set(operations or [])
        integrity_verified = bool(
            signed
            and endpoint_healthy
            and available
            and proof_integrity == "ok"
            and refs_match
        )
        if not signed:
            reason = "repository_signature_invalid"
        elif not endpoint_healthy:
            reason = "mirror_unhealthy"
        elif not available:
            reason = "repository_unavailable"
        elif proof_integrity != "ok":
            reason = "repository_integrity_failed"
        elif not refs_match:
            reason = "refs_mismatch"
        elif not operation_available:
            reason = "git_operation_unavailable"
        else:
            reason = "verified"
        if isinstance(details, dict):
            details.update({
                "integrity": "ok" if integrity_verified else (
                    "failed" if (
                        signed and (
                            proof_integrity != "ok" or not refs_match
                        )
                        or status == 200 and not signed
                    ) else "unknown"
                ),
                "refsSha256": refs_digest if signed else "",
                "reason": reason,
                "signed": bool(signed),
                "operations": sorted(
                    str(item) for item in (
                        operations if isinstance(operations, list) else [])),
            })
    except Exception:
        integrity_verified = False
        signed = False
        reason = "repository_response_invalid"
        operations = []
        refs_digest = ""
        if isinstance(details, dict):
            details["reason"] = "repository_response_invalid"
    if len(_HTTPS_MIRROR_REPO_PROOF_MEMO) >= HTTPS_MIRROR_REPO_PROOF_MEMO_MAX:
        _HTTPS_MIRROR_REPO_PROOF_MEMO.clear()
    # An endpoint that answered with an authentic, healthy, pin-matching proof
    # is not a failed endpoint just because it does not advertise the exact
    # operation this caller asked for. Holding that verdict as a failure denied
    # the node every other operation it does serve for the whole failure
    # window: one owner merge attempt against read-only mirrors used to take
    # them out of ordinary read routing for the next twenty seconds.
    if not integrity_verified:
        # Per-isolate only: the edge cache keeps holding the last valid proof
        # so a transient failure never evicts a good routing answer globally.
        held_signed = bool(signed)
        _HTTPS_MIRROR_REPO_PROOF_MEMO[memo_key] = {
            "checkedAt": now,
            "operations": (
                frozenset(str(item) for item in operations)
                if held_signed and isinstance(operations, list)
                else frozenset()),
            "refsSha256": refs_digest if held_signed else "",
            "failed": True,
            "reason": reason,
            "signed": held_signed,
            "integrity": "failed" if held_signed else "unknown",
        }
        return False
    _HTTPS_MIRROR_REPO_PROOF_MEMO[memo_key] = {
        "checkedAt": now,
        "operations": frozenset(operations),
        "refsSha256": refs_digest,
    }
    await https_routing.repository_proof_cache_put(
        js_caches.default, JsResponse, to_js, edge_cache_key, now,
        refs_digest, operations, HTTPS_MIRROR_REPO_PROOF_TTL_MS)
    endpoint["refsSha256"] = refs_digest
    return operation in set(operations)


async def _mirror_reachability_failure_reason(
        env, endpoint, context, admitted, now, default):
    """Explain why one exact mirror did not serve README.md.

    Only consulted after the probe request has already failed, so the extra
    manifest read costs nothing on the healthy path. Ordered from the operator
    action furthest upstream (finish syncing) to the narrowest (the node
    answered but not with a README).
    """
    if not admitted:
        return "state_pin_not_admitted"
    try:
        if not await _https_mirror_repository_proof(
                env, endpoint, context, "blob"):
            return "repository_proof_failed"
    except Exception:
        return "repository_proof_failed"
    if not https_routing.endpoint_eligible(endpoint, now):
        return "endpoint_stale"
    return default


def _mirror_direct_integrity_fields(
        node, mirror_origin, owner, repo, record=None, cached=False,
        registration_issued_at=0):
    """Project one stored check only while it describes the current URL."""
    current_origin = https_routing.normalize_base_url(mirror_origin)
    stored_origin = https_routing.normalize_base_url(
        (record or {}).get("mirror_url"))
    try:
        current_registration = int(registration_issued_at or 0)
        stored_registration = int(
            (record or {}).get("registration_issued_at") or 0)
    except (TypeError, ValueError, OverflowError):
        current_registration = 0
        stored_registration = 0
    applies = bool(
        record is not None
        and current_origin
        and current_registration > 0
        and current_registration == stored_registration
        and hmac.compare_digest(current_origin, stored_origin)
    )
    integrity = str(
        (record or {}).get("integrity") or "unknown").lower()
    if integrity not in {"unknown", "ok", "failed"}:
        integrity = "unknown"
    reachable = bool(int((record or {}).get("reachable") or 0)) if applies else False
    refs_digest = clean_string(
        (record or {}).get("refs_sha256", ""), 64).lower()
    if not re.fullmatch(r"[0-9a-f]{64}", refs_digest):
        refs_digest = ""
    fields = {
        "node": clean_string(node, MAX_NODE_NAME).strip().lower(),
        "mirrorUrl": https_routing.direct_repository_url(
            current_origin, owner, repo),
        "dashboardUrl": https_routing.direct_repository_page_url(
            current_origin, owner, repo),
        "directVerified": bool(applies and integrity == "ok" and reachable),
        "directReachable": reachable,
        "directIntegrity": integrity if applies else "unknown",
        "directRefsSha256": refs_digest if applies else "",
        "directCheckedAt": (
            max(0, int((record or {}).get("checked_at") or 0))
            if applies else 0
        ),
        "directLatencyMs": (
            max(0, min(int((record or {}).get("latency_ms") or 0), 60_000))
            if applies else 0
        ),
        "directStatus": (
            max(0, min(int((record or {}).get("status_code") or 0), 599))
            if applies else 0
        ),
        "directReason": clean_string(
            (record or {}).get("reason", "unchecked") if applies
            else "mirror_url_not_registered" if not current_origin
            else "unchecked",
            80,
        ),
    }
    if cached:
        fields["directCached"] = True
    return fields


async def _https_mirror_check_direct_repository(env, endpoint, context):
    """Verify the registered origin, signed refs, and exact Smart HTTP URL."""
    started = int(Date.now())
    origin = https_routing.normalize_base_url(endpoint.get("mirrorUrl"))
    result = {
        "mirror_url": origin,
        "registration_issued_at": max(
            0, int(endpoint.get("issuedAt") or 0)),
        "reachable": 0,
        "integrity": "unknown",
        "refs_sha256": "",
        "checked_at": started,
        "latency_ms": 0,
        "status_code": 0,
        "reason": "mirror_url_not_registered",
    }
    if not origin:
        return result
    if endpoint.get("abuseBlocked"):
        result["reason"] = "endpoint_blocked"
        return result

    details = {}
    try:
        proof_ok = await _https_mirror_repository_proof(
            env,
            endpoint,
            context,
            "git-info-refs",
            origin=origin,
            force_refresh=True,
            details=details,
        )
    except Exception:
        proof_ok = False
        details = {"reason": "repository_proof_request_failed"}
    result["integrity"] = str(
        details.get("integrity") or "unknown")
    result["refs_sha256"] = clean_string(
        details.get("refsSha256", ""), 64).lower()
    result["status_code"] = max(
        0, min(int(details.get("status") or 0), 599))
    result["reason"] = clean_string(
        details.get("reason", "repository_proof_failed"), 80)
    if not proof_ok:
        result["checked_at"] = int(Date.now())
        result["latency_ms"] = max(
            0, min(result["checked_at"] - started, 60_000))
        return result

    target = https_routing.direct_git_target_url(
        origin,
        context.get("routeOwner") or context["owner"],
        context["repo"],
        "git-info-refs",
        {"service": "git-upload-pack"},
    )
    if not target:
        result["reason"] = "git_url_invalid"
        return result
    try:
        upstream = await js_fetch_with_timeout(
            target,
            {
                "method": "HEAD",
                "headers": {"Accept": (
                    "application/x-git-upload-pack-advertisement")},
                "redirect": "manual",
            },
            HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
        )
        status = int(getattr(upstream, "status", 0) or 0)
        content_type = str(
            upstream.headers.get("content-type") or ""
        ).split(";", 1)[0].strip().lower()
        result["status_code"] = max(0, min(status, 599))
        if status != 200:
            result["reason"] = "git_endpoint_http_error"
        elif content_type != "application/x-git-upload-pack-advertisement":
            result["reason"] = "git_endpoint_content_type_invalid"
        else:
            result["reachable"] = 1
            result["reason"] = "verified"
    except Exception:
        result["reason"] = "git_endpoint_unreachable"
        result["status_code"] = 0
    result["checked_at"] = int(Date.now())
    result["latency_ms"] = max(
        0, min(result["checked_at"] - started, 60_000))
    return result


async def repo_mirror_reachability_handler(
        env, request, owner, repo, requested_node):
    """Probe one named mirror without failover; return metadata, never README."""
    request_method = method_name(request)
    if request_method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    node = clean_string(
        requested_node, MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return json_response({"error": "not_found"}, status=404)
    try:
        context = await _https_mirror_public_context(env, owner, repo)
    except _HttpsMirrorContextUnavailable:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    if context is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    admitted = node in context.get("nodes", set())
    if not admitted and node not in context.get("groupNodes", set()):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")

    # Preserve a D1-confirmed organization alias in the exact mirror proof.
    try:
        original_url = urlparse(str(getattr(request, "url", "") or ""))
        original_match = REPO_MIRROR_REACHABILITY_RE.match(original_url.path)
        route_owner = (
            safe_segment(original_match.group(1)) if original_match else "")
        route_repo = (
            safe_segment(original_match.group(2)) if original_match else "")
        if (
            route_owner
            and route_repo.lower() == repo.lower()
            and route_owner != owner
            and await _org_repo_node(env, route_owner, route_repo) == owner
        ):
            context = dict(context)
            context["routeOwner"] = route_owner
    except Exception:
        pass

    row = await d1_first(
        env,
        """SELECT node_bi,node_name,base_url,mirror_url,public_key,
                  registration_sig,issued_at,
                  checked_at,latency_ms,region,healthy,integrity,abuse_blocked
             FROM mirror_https_endpoints WHERE node_name=?""",
        node,
    )
    endpoint = _https_mirror_endpoint_projection(row or {})
    now = int(Date.now())
    endpoint_registered = bool(
        row and str(endpoint.get("baseUrl") or "").strip())

    if request_method == "POST":
        mirror_origin = https_routing.normalize_base_url(
            endpoint.get("mirrorUrl"))
        existing = None
        if row and context.get("repoBi") and row.get("node_bi"):
            existing = await d1_first(
                env,
                """SELECT mirror_url,registration_issued_at,reachable,
                          integrity,refs_sha256,checked_at,latency_ms,
                          status_code,reason
                     FROM mirror_repository_integrity
                    WHERE repo_bi=? AND node_bi=?""",
                context["repoBi"],
                row["node_bi"],
            )
        existing_origin = https_routing.normalize_base_url(
            (existing or {}).get("mirror_url"))
        existing_age = now - int((existing or {}).get("checked_at") or 0)
        existing_registration = int(
            (existing or {}).get("registration_issued_at") or 0)
        current_registration = int(endpoint.get("issuedAt") or 0)
        if (
            existing
            and hmac.compare_digest(mirror_origin, existing_origin)
            and current_registration > 0
            and existing_registration == current_registration
            and 0 <= existing_age <= HTTPS_MIRROR_DIRECT_CHECK_COOLDOWN_MS
        ):
            fields = _mirror_direct_integrity_fields(
                node,
                mirror_origin,
                context.get("routeOwner") or context["owner"],
                context["repo"],
                existing,
                cached=True,
                registration_issued_at=current_registration,
            )
        else:
            check = await _https_mirror_check_direct_repository(
                env, endpoint, context)
            if row and context.get("repoBi") and row.get("node_bi"):
                await d1_run(
                    env,
                    """INSERT INTO mirror_repository_integrity
                       (repo_bi,node_bi,mirror_url,registration_issued_at,
                        reachable,integrity,refs_sha256,checked_at,latency_ms,
                        status_code,reason)
                       VALUES (?,?,?,?,?,?,?,?,?,?,?)
                       ON CONFLICT(repo_bi,node_bi) DO UPDATE SET
                         mirror_url=excluded.mirror_url,
                         registration_issued_at=excluded.registration_issued_at,
                         reachable=excluded.reachable,
                         integrity=excluded.integrity,
                         refs_sha256=excluded.refs_sha256,
                         checked_at=excluded.checked_at,
                         latency_ms=excluded.latency_ms,
                         status_code=excluded.status_code,
                         reason=excluded.reason""",
                    context["repoBi"],
                    row["node_bi"],
                    check["mirror_url"],
                    check["registration_issued_at"],
                    check["reachable"],
                    check["integrity"],
                    check["refs_sha256"],
                    check["checked_at"],
                    check["latency_ms"],
                    check["status_code"],
                    check["reason"],
                )
            fields = _mirror_direct_integrity_fields(
                node,
                mirror_origin,
                context.get("routeOwner") or context["owner"],
                context["repo"],
                check,
                registration_issued_at=current_registration,
            )
            await edge_cache_delete(
                "https://forkmesh.internal/api/repo/%s/%s/mirrors"
                % (
                    quote(context.get("routeOwner") or owner),
                    quote(context["repo"]),
                )
            )
        fields.update({
            "ok": True,
            "endpointRegistered": endpoint_registered,
            "directUrlRegistered": bool(mirror_origin),
            "admitted": bool(admitted),
        })
        return json_response(
            fields,
            cache_control="no-store, max-age=0, must-revalidate",
        )

    def result(reachable, reason, status=0, latency=0):
        return json_response({
            "ok": True,
            "node": node,
            "reachable": bool(reachable),
            "readmeLoaded": bool(reachable),
            "path": "README.md",
            "status": int(status or 0),
            "latencyMs": max(0, min(int(latency or 0), 60_000)),
            "checkedAt": now,
            # State the probe ran against, so the operator table can separate
            # "nothing to probe" and "behind the pin window" from a mirror that
            # was asked for README.md and failed to serve it.
            "endpointRegistered": endpoint_registered,
            "admitted": bool(admitted),
            "reason": clean_string(reason, 80),
        }, cache_control="no-store, max-age=0, must-revalidate")

    # No registered endpoint means there is no direct route to this node at
    # all; nothing can be measured. Everything else gets a real request.
    if not endpoint_registered:
        return result(False, "endpoint_not_registered")
    if endpoint.get("abuseBlocked"):
        return result(False, "endpoint_blocked")
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    target = https_routing.masked_target_url(
        endpoint["baseUrl"], context.get("routeOwner") or context["owner"],
        context["repo"], "blob", {"path": "README.md"})
    parsed_target = urlparse(target) if target else None
    signed_path = (
        parsed_target.path
        + (("?" + parsed_target.query) if parsed_target.query else "")
        if parsed_target else ""
    )
    request_id = _b64url_encode(_random_bytes(18))
    issued_at = int(Date.now())
    body_digest = https_routing.empty_body_sha256()
    message = https_routing.request_message(
        node, "GET", signed_path, body_digest, request_id, issued_at)
    signature = (
        await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if router_public_key and router_seed and message else "")
    if not target or not signature:
        return result(False, "router_unavailable")
    headers = {
        "X-ForkMesh-Node": node,
        "X-ForkMesh-Request-Id": request_id,
        "X-ForkMesh-Issued-At": str(issued_at),
        "X-ForkMesh-Body-Sha256": body_digest,
        "X-ForkMesh-Signature": signature,
    }
    started = int(Date.now())
    try:
        upstream = await js_fetch_with_timeout(
            target,
            {"method": "GET", "headers": headers, "redirect": "manual"},
            HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
        )
        status = int(getattr(upstream, "status", 0) or 0)
        latency = int(Date.now()) - started
        announced = int(upstream.headers.get("content-length") or 0)
        if announced > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
            return result(False, "readme_response_too_large", status, latency)
        raw = str(await upstream.text())
        if len(raw.encode("utf-8")) > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
            return result(False, "readme_response_too_large", status, latency)
        value = json.loads(raw) if raw else {}
        loaded = bool(
            status == 200
            and isinstance(value, dict)
            and value.get("ok") is True
            and isinstance(value.get("content"), str)
        )
        if loaded:
            return result(True, "readme_loaded", status, latency)
        return result(
            False,
            await _mirror_reachability_failure_reason(
                env, endpoint, context, admitted, now, "readme_unavailable"),
            status, latency)
    except Exception:
        return result(
            False,
            await _mirror_reachability_failure_reason(
                env, endpoint, context, admitted, now, "request_failed"),
            0, int(Date.now()) - started)


# Both authenticated pull mutations share one request envelope, one durable job
# table, and one signed proxy. Only the wire type, the routed node operation,
# the terminal status, the object ids that status publishes, and the audited
# action name differ, so they are described as data here rather than duplicated
# as a second near-identical handler.
HTTPS_MIRROR_PULL_MUTATIONS = {
    "merge": {
        "wireType": "forkmesh.pull-merge-v1",
        "operation": "merge-pull",
        "terminal": "merged",
        "after": ("baseAfter", "pullsAfter"),
        "action": "repository.pull_merge",
        # Merging is the only mutation with an independent-review gate, so it
        # is the only one an owner can ask to merge without.
        "override": True,
        "failures": frozenset({
            "checks_required", "merge_conflict", "pull_not_found",
            "pull_not_open", "review_required", "rules_required",
            "stale_base", "stale_head", "stale_pull_metadata",
            "unsupported_pull",
        }),
    },
    "update": {
        "wireType": "forkmesh.pull-update-v1",
        "operation": "update-pull-branch",
        "terminal": "updated",
        "after": ("headAfter",),
        "action": "repository.pull_update",
        "failures": frozenset({
            "already_current", "merge_conflict", "pull_not_found",
            "pull_not_open", "stale_base", "stale_head",
            "stale_pull_metadata", "unsupported_pull",
        }),
    },
    "branch-merge": {
        "wireType": "forkmesh.branch-merge-v1",
        "operation": "merge-agent-branch",
        "terminal": "merged",
        "branch": True,
        "before": ("baseBefore", "head"),
        "after": ("baseAfter",),
        "action": "repository.agent_branch_merge",
        "failures": frozenset({
            "already_merged", "branch_not_found", "merge_conflict",
            "stale_base", "stale_head", "unsupported_branch",
        }),
    },
    "branch-delete": {
        "wireType": "forkmesh.branch-delete-v1",
        "operation": "delete-agent-branch",
        "terminal": "deleted",
        "branch": True,
        "before": ("head",),
        "after": (),
        "action": "repository.agent_branch_delete",
        "failures": frozenset({
            "branch_not_found", "not_merged", "stale_base", "stale_head",
            "unsupported_branch",
        }),
    },
}


def _https_mirror_merge_body(raw, pull_number, mutation="merge"):
    """Validate the small account request before any node sees it."""
    profile = HTTPS_MIRROR_PULL_MUTATIONS[mutation]
    if not isinstance(raw, str) or not raw or (
            len(raw.encode("utf-8")) > HTTPS_MIRROR_MERGE_BODY_MAX_BYTES):
        return None

    def reject_duplicates(pairs):
        output = {}
        for key, value in pairs:
            if key in output:
                raise ValueError("duplicate")
            output[key] = value
        return output

    try:
        value = json.loads(raw, object_pairs_hook=reject_duplicates)
    except Exception:
        return None
    required = {
        "schemaVersion", "type", "pullNumber", "requestId",
        "expectedBaseOid", "expectedHeadOid", "expectedPullsOid",
    }
    # Waiving the independent-review gate is a merge-only option, and only a
    # repository owner reaches the handler that forwards it at all.
    optional = {"sessionToken"} | (
        {"overrideReview", "deleteHead", "deployApproval"} if profile.get("override")
        else set())
    override_review = value.get("overrideReview", False) if isinstance(
        value, dict) else False
    delete_head = value.get("deleteHead", False) if isinstance(
        value, dict) else False
    if (
        not isinstance(value, dict)
        or not required.issubset(value)
        or set(value) - required - optional
        or value.get("schemaVersion") != 1
        or value.get("type") != profile["wireType"]
        or not isinstance(override_review, bool)
        or not isinstance(delete_head, bool)
    ):
        return None
    try:
        number = int(value.get("pullNumber"))
    except (TypeError, ValueError, OverflowError):
        return None
    request_id = clean_string(value.get("requestId", ""), 80).strip()
    oids = {
        field: clean_string(value.get(field, ""), 64).strip().lower()
        for field in (
            "expectedBaseOid", "expectedHeadOid", "expectedPullsOid")
    }
    if (
        number != int(pull_number)
        or not HTTPS_MIRROR_MERGE_REQUEST_RE.fullmatch(request_id)
        or any(
            not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid)
            for oid in oids.values()
        )
        or len({len(oid) for oid in oids.values()}) != 1
    ):
        return None
    return {
        "schemaVersion": 1,
        "type": profile["wireType"],
        "pullNumber": number,
        "requestId": request_id,
        **oids,
        # Absent unless waived, so a mirror that predates the waiver keeps
        # receiving exactly the request shape it already accepts.
        **({"overrideReview": True} if override_review else {}),
        **({"deleteHead": True} if delete_head else {}),
        **({
            "sessionToken": clean_string(
                value.get("sessionToken", ""), 512).strip()
        } if value.get("sessionToken") else {}),
        **({"deployApproval": value["deployApproval"]}
           if isinstance(value.get("deployApproval"), dict) else {}),
    }


def _https_mirror_merge_result(value, request, mutation="merge"):
    """Return a bounded node result or None; no origin data is projected."""
    profile = HTTPS_MIRROR_PULL_MUTATIONS[mutation]
    if not isinstance(value, dict):
        return None
    request_id = str(value.get("requestId") or "")
    status = str(value.get("status") or "")
    if request_id != request["requestId"]:
        return None
    if status == "processing":
        if value.get("ok") is not True:
            return None
        return {
            "ok": True,
            "status": "processing",
            "requestId": request_id,
        }
    if status == "failed":
        error = str(value.get("error") or "")
        if error not in profile["failures"]:
            return None
        return {
            "ok": False,
            "status": "failed",
            "requestId": request_id,
            "error": error,
        }
    if (
        status != profile["terminal"]
        or value.get("ok") is not True
        or value.get("published") is not True
    ):
        return None
    output = {
        "ok": True,
        "status": profile["terminal"],
        "requestId": request_id,
        "published": True,
    }
    expected = {
        "baseBefore": request.get("expectedBaseOid", ""),
        "head": request["expectedHeadOid"],
        "pullsBefore": request.get("expectedPullsOid", ""),
    }
    for field in profile.get(
            "before", ("baseBefore", "head", "pullsBefore")) + profile["after"]:
        oid = str(value.get(field) or "").strip().lower()
        if (
            not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid)
            or (field in expected and not hmac.compare_digest(
                oid, expected[field]))
        ):
            return None
        output[field] = oid
    if profile.get("branch"):
        if (
            str(value.get("branch") or "") != request.get("branch")
            or str(value.get("base") or "") != request.get("base")
        ):
            return None
        output["branch"] = request["branch"]
        output["base"] = request["base"]
        output["branchDeleted"] = value.get("branchDeleted") is True
    # The mirror's self-attested post-mutation refs state travels with the
    # published result. It is optional and shape-checked here only; the
    # handler verifies the node signature before admitting the pin, and a
    # result without it is still a valid merge receipt.
    state = str(value.get("state") or "").strip().lower()
    state_ts = str(value.get("stateTs") or "").strip()
    state_sig = str(value.get("stateSig") or "").strip()
    if (
        re.fullmatch(r"[0-9a-f]{64}", state)
        and re.fullmatch(r"[1-9][0-9]{0,18}", state_ts)
        and HTTPS_MIRROR_MERGE_ATTESTATION_SIG_RE.fullmatch(state_sig)
    ):
        output["state"] = state
        output["stateTs"] = state_ts
        output["stateSig"] = state_sig
    # The relay's own routing provenance (see _owner_merge_pin_state): the
    # source's attested state at the time the job was recorded.
    source_state = str(value.get("sourceState") or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", source_state):
        output["sourceState"] = source_state
    return output


async def _https_mirror_merge_proxy(
        env, endpoint, context, request, mutation="merge"):
    """Submit/poll one job on its permanently selected signed mirror.

    The node must still present a signed, healthy proof for this repository,
    but its refs may run ahead of the relay's pin set: selection admitted it
    on a pin or on two agreeing signed digests, and running the job is itself
    what moves those refs. Held to the pin, a finished merge polled as
    merge_status_pending until the health cron re-proved two peers.
    """
    profile = HTTPS_MIRROR_PULL_MUTATIONS[mutation]
    proof_details = {}
    if not await _https_mirror_repository_proof(
            env, endpoint, context, profile["operation"],
            details=proof_details) and not https_routing.signed_refs_lag(
                profile["operation"], proof_details):
        return 0, None
    body = json.dumps(
        request, sort_keys=True, separators=(",", ":")).encode("utf-8")
    target = https_routing.masked_target_url(
        endpoint["baseUrl"], context.get("routeOwner") or context["owner"],
        context["repo"], profile["operation"])
    parsed_target = urlparse(target)
    signed_path = parsed_target.path
    request_id = _b64url_encode(_random_bytes(18))
    issued_at = int(Date.now())
    body_digest = hashlib.sha256(body).hexdigest()
    message = https_routing.request_message(
        endpoint["node"], "POST", signed_path, body_digest, request_id,
        issued_at)
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    signature = (
        await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if target and message and router_public_key and router_seed else "")
    if not signature:
        return 0, None
    headers = {
        "Content-Type": "application/json",
        "X-ForkMesh-Node": endpoint["node"],
        "X-ForkMesh-Request-Id": request_id,
        "X-ForkMesh-Issued-At": str(issued_at),
        "X-ForkMesh-Body-Sha256": body_digest,
        "X-ForkMesh-Signature": signature,
    }
    try:
        # Native AbortSignal timeout, not asyncio.wait_for — see the
        # no-concurrent-tasks rule at the top of this module.
        upstream = await js_fetch_with_timeout(
            target,
            {
                "method": "POST",
                "headers": headers,
                "body": Uint8Array.new(_to_js(body)),
                "redirect": "manual",
            },
            HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
        )
        status = int(getattr(upstream, "status", 0) or 0)
        announced = int(upstream.headers.get("content-length") or 0)
        if announced > HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES:
            return 0, None
        raw = str(await upstream.text())
        if len(raw.encode("utf-8")) > HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES:
            return 0, None
        value = json.loads(raw)
    except Exception:
        return 0, None
    checked = _https_mirror_merge_result(value, request, mutation)
    if (
        checked is None
        or status not in (200, 202, 404, 409)
        or (checked["status"] == "processing" and status != 202)
        or (checked["status"] == profile["terminal"] and status != 200)
        or (checked["status"] == "failed" and status not in (404, 409))
    ):
        return 0, None
    return status, checked


def _https_mirror_actions_result(value, expected_node, now):
    """Validate and reduce one owner-authorized, already-redacted run summary."""
    if isinstance(value, dict) and "schemaVersion" in value:
        return _repository_actions._https_mirror_actions_result_v2(
            value, expected_node, now)
    required = {"ok", "node", "updatedAt", "expiresAt", "runs"}
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("ok") is not True
        or value.get("node") != expected_node
        or isinstance(value.get("updatedAt"), bool)
        or isinstance(value.get("expiresAt"), bool)
    ):
        return None
    try:
        updated_at = int(value.get("updatedAt"))
        expires_at = int(value.get("expiresAt"))
    except (TypeError, ValueError, OverflowError):
        return None
    if (
        updated_at < now - HTTPS_MIRROR_ACTIONS_LEASE_MAX_MS
        or updated_at > now + HTTPS_MIRROR_ACTIONS_CLOCK_SKEW_MS
        or expires_at <= now
        or expires_at <= updated_at
        or expires_at - updated_at > HTTPS_MIRROR_ACTIONS_LEASE_MAX_MS
    ):
        return None
    runs = value.get("runs")
    if (
        not isinstance(runs, list)
        or len(runs) > HTTPS_MIRROR_ACTIONS_RUN_LIMIT
    ):
        return None
    statuses = {
        "awaiting-approval", "queued", "running", "success", "failed",
        "rejected", "cancelled", "skipped",
    }
    fields = {
        "id", "workflow", "commit", "ref", "status",
        "createdAt", "startedAt", "finishedAt", "logTail",
    }
    output_runs = []
    for item in runs:
        if not isinstance(item, dict) or set(item) != fields:
            return None
        if any(
            isinstance(item.get(field), bool)
            for field in ("id", "createdAt", "startedAt", "finishedAt")
        ):
            return None
        try:
            run_id = int(item.get("id"))
            created_at = int(item.get("createdAt"))
            started_at = int(item.get("startedAt"))
            finished_at = int(item.get("finishedAt"))
        except (TypeError, ValueError, OverflowError):
            return None
        workflow = str(item.get("workflow") or "").strip()
        commit = str(item.get("commit") or "").strip().lower()
        ref = str(item.get("ref") or "").strip()
        status_value = str(item.get("status") or "")
        log_tail = str(item.get("logTail") or "")
        if (
            not 1 <= run_id <= 2147483647
            or not 1 <= len(workflow) <= 160
            or any(char in workflow for char in ("\x00", "\r", "\n"))
            or not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit)
            or not 1 <= len(ref) <= 160
            or any(char in ref for char in ("\x00", "\r", "\n"))
            or status_value not in statuses
            or min(created_at, started_at, finished_at) < 0
            or max(created_at, started_at, finished_at)
                > now + HTTPS_MIRROR_ACTIONS_CLOCK_SKEW_MS
            or len(log_tail.encode("utf-8"))
                > HTTPS_MIRROR_ACTIONS_LOG_TAIL_MAX_BYTES
            or "\x00" in log_tail
        ):
            return None
        output_runs.append({
            "id": run_id,
            "workflow": workflow,
            "commit": commit,
            "ref": ref,
            "status": status_value,
            "createdAt": created_at,
            "startedAt": started_at,
            "finishedAt": finished_at,
            "logTail": log_tail,
        })
    return {
        "ok": True,
        "node": expected_node,
        "updatedAt": updated_at,
        "expiresAt": expires_at,
        "runs": output_runs,
    }


async def _https_mirror_actions_proxy(env, endpoint, context):
    """Read one bounded summary through an attested operation-specific route."""
    if not await _https_mirror_repository_proof(
            env, endpoint, context, "actions-status"):
        return None
    target = https_routing.masked_target_url(
        endpoint["baseUrl"], context["owner"], context["repo"],
        "actions-status")
    parsed_target = urlparse(target)
    request_id = _b64url_encode(_random_bytes(18))
    issued_at = int(Date.now())
    body_digest = hashlib.sha256(b"").hexdigest()
    message = https_routing.request_message(
        endpoint["node"], "GET", parsed_target.path, body_digest, request_id,
        issued_at)
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    signature = (
        await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if target and message and router_public_key and router_seed else "")
    if not signature:
        return None
    headers = {
        "X-ForkMesh-Node": endpoint["node"],
        "X-ForkMesh-Request-Id": request_id,
        "X-ForkMesh-Issued-At": str(issued_at),
        "X-ForkMesh-Body-Sha256": body_digest,
        "X-ForkMesh-Signature": signature,
    }
    try:
        # Native AbortSignal timeout, not asyncio.wait_for — see the
        # no-concurrent-tasks rule at the top of this module.
        upstream = await js_fetch_with_timeout(
            target,
            {"method": "GET", "headers": headers, "redirect": "manual"},
            HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
        )
        if int(getattr(upstream, "status", 0) or 0) != 200:
            return None
        announced = int(upstream.headers.get("content-length") or 0)
        if announced > HTTPS_MIRROR_ACTIONS_RESULT_MAX_BYTES:
            return None
        raw = str(await upstream.text())
        if len(raw.encode("utf-8")) > HTTPS_MIRROR_ACTIONS_RESULT_MAX_BYTES:
            return None
        value = json.loads(raw)
    except Exception:
        return None
    return _https_mirror_actions_result(
        value, endpoint["node"], int(Date.now()))


HTTPS_MIRROR_BRANCH_TRASH_MAX_BYTES = 2 * 1024 * 1024
HTTPS_MIRROR_BRANCH_TRASH_MAX_ENTRIES = 5000
BRANCH_TRASH_BRANCH_RE = re.compile(
    r"^[A-Za-z0-9][A-Za-z0-9._/-]{0,199}$")


def _https_mirror_branch_trash_result(value, expected_node):
    if (
        not isinstance(value, dict)
        or set(value) != {"ok", "node", "entries", "truncated"}
        or value.get("ok") is not True
        or value.get("node") != expected_node
        or not isinstance(value.get("truncated"), bool)
        or not isinstance(value.get("entries"), list)
        or len(value["entries"]) > HTTPS_MIRROR_BRANCH_TRASH_MAX_ENTRIES
    ):
        return None
    entries = []
    for item in value["entries"]:
        if not isinstance(item, dict) or set(item) != {"branch", "oid"}:
            return None
        branch, oid = item.get("branch"), item.get("oid")
        if (
            not isinstance(branch, str) or not isinstance(oid, str)
            or not BRANCH_TRASH_BRANCH_RE.fullmatch(branch)
            or ".." in branch or "//" in branch
            or branch.endswith((".", "/", ".lock"))
            or not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid)
        ):
            return None
        entries.append({"branch": branch, "oid": oid})
    return {"entries": entries, "truncated": value["truncated"]}


