async def _runner_actions_snapshot(env, context):
    try:
        import runner_actions
        import runner_leases
        runner_leases._bind_runtime(globals())
        return await runner_actions.snapshot(
            runner_leases.WorkerRuntime(env, None), context["owner"],
            context["repo"])
    except Exception:
        return None


async def repository_actions_status_handler(env, request, owner, repo):
    """Return private redacted executor state to the owner or org writer."""
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    if str(getattr(env, "ACTIONS_INSTANCE_RUNNER", "") or "").strip():
        return await repository_actions_instance_status_handler(
            env, request, owner, repo)
    try:
        context = await _https_mirror_public_context(env, owner, repo)
    except _HttpsMirrorContextUnavailable:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    if context is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    _, actor_record = await _account_session_record(env, request)
    actor = clean_string(
        (actor_record or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
    if not actor:
        return json_response(
            {"error": "invalid_session"}, status=401,
            cache_control="no-store")
    try:
        authorized = bool(
            actor == context["owner"]
            or await _account_owns_node(env, actor, context["owner"])
            or await _org_write_allowed(
                env, context["owner"], context["repo"], actor)
        )
    except Exception:
        authorized = False
    target = context["owner"] + "/" + context["repo"]
    if not authorized:
        await _audit_sensitive_action(
            env, actor, "repository.actions_status", "repository", target,
            "denied", {})
        return json_response(
            {"error": "forbidden"}, status=403,
            cache_control="no-store")
    candidates = await _https_mirror_candidates(
        env, context, world_request_country(request))
    for candidate in candidates:
        result = await _https_mirror_actions_proxy(
            env, candidate, context)
        if result is not None:
            # Memoized by the proxy's own proof of this node a moment ago.
            result["controlAvailable"] = await _https_mirror_repository_proof(
                env, candidate, context, "actions-control")
            await _audit_sensitive_action(
                env, actor, "repository.actions_status", "repository",
                target, "success", {"node": candidate["node"]})
            return json_response(
                result,
                cache_control="private, no-store, max-age=0, must-revalidate")
    runner_runs = await _runner_actions_snapshot(env, context)
    if runner_runs is not None:
        await _audit_sensitive_action(
            env, actor, "repository.actions_status", "repository",
            target, "success", {"node": runner_runs["node"]})
        return json_response(
            runner_runs,
            cache_control="private, no-store, max-age=0, must-revalidate")
    # An attested executor being temporarily offline is application state, not
    # a broken HTTP route. Return a bounded empty snapshot so authorized World
    # clients can keep the cabinet UI quiet and retry on their normal cadence
    # without generating a repeating 503 in every visitor's console.
    return json_response(
        {
            "ok": False,
            "state": "unavailable",
            "runs": [],
            "retryable": True,
        },
        cache_control="private, no-store, max-age=0, must-revalidate")


