async def _organization_owner_can_merge_repo(
        env, request, canonical_owner, repo, actor):
    """Require the signed-in actor to own the org alias in the original URL.

    The internal router has already rewritten /api/repo/<org>/<repo> to the
    backing node namespace. Merge-via-mirror is intentionally narrower than
    ordinary team write access until group merge policy exists: direct node
    URLs, organization admins, maintainers, and writers all fail closed.
    """
    if not actor:
        return False
    try:
        original = urlparse(request.url)
        match = REPO_API_PREFIX_RE.match(original.path)
    except Exception:
        return False
    if not match:
        return False
    alias_owner = (safe_segment(match.group(1)) or "").strip().lower()
    alias_repo = (safe_segment(match.group(2)) or "").strip().lower()
    canonical_owner = str(canonical_owner or "").strip().lower()
    repo = str(repo or "").strip().lower()
    if (
        not alias_owner
        or alias_owner == canonical_owner
        or alias_repo != repo
    ):
        return False
    org_bi, org_row = await _org_row(env, alias_owner)
    if not org_row:
        return False
    linked = await d1_first(
        env,
        "SELECT 1 AS ok FROM org_repos "
        "WHERE org_bi=? AND repo=? AND node_owner=?",
        org_bi, repo, canonical_owner,
    )
    if not linked:
        return False
    return await _org_role(env, org_bi, actor) == "owner"


async def _admit_owner_merge_state(env, context, endpoint, result):
    """Pin the refs state a mirror serves after an owner-authorized mutation.

    An organization owner merged (or updated) a pull request through this
    mirror while the repository's source-of-truth desktop may be offline. The
    mirror now serves refs the source never attested, so without this step
    clone_state_pins would drop it — and every peer converging on it — from
    the read fan-out, and the fleet could never pick the merge up through the
    pinned relay route. The owner's permission is what authorizes the new
    state: verify the mirror's fresh node-signed forkmesh-repostate-v1
    attestation against the registered endpoint key (the same identity that
    signed the health proof that selected it), then admit the digest into the
    repository's pin history exactly like a source publish would. Routing
    preference for the new generation comes from the durable merge job row
    (see _owner_merge_pin_state). Returns the admitted digest or "".
    """
    try:
        state = str((result or {}).get("state") or "").strip().lower()
        ts = str((result or {}).get("stateTs") or "").strip()
        sig = str((result or {}).get("stateSig") or "").strip()
        node = clean_string(
            (endpoint or {}).get("node", ""), MAX_NODE_NAME).strip().lower()
        if (
            not re.fullmatch(r"[0-9a-f]{64}", state)
            or not ts or not sig or not valid_node_name(node)
        ):
            return ""
        try:
            if abs(int(Date.now()) - int(ts)) > (
                    HTTPS_MIRROR_MERGE_ATTESTATION_MAX_SKEW_MS):
                return ""
        except (TypeError, ValueError):
            return ""
        canonical = (
            "forkmesh-repostate-v1\n" + node + "\n" + context["repo"] + "\n"
            + state + "\n" + ts
        ).encode()
        keys = []
        endpoint_key = clean_string(
            (endpoint or {}).get("publicKey", ""), 120).strip()
        if endpoint_key:
            keys.append(endpoint_key)
        for public_key in await _claimed_node_signing_pubkeys(env, node):
            if public_key not in keys:
                keys.append(public_key)
        verified = False
        for public_key in keys:
            if await ed25519_verify(public_key, sig, canonical):
                verified = True
                break
        if not verified:
            return ""
        key_bi = context["repoBi"]
        await d1_run(
            env,
            "INSERT INTO repo_state_history (key_bi, state_hash, ts) "
            "VALUES (?,?,?) ON CONFLICT(key_bi, state_hash) "
            "DO UPDATE SET ts=excluded.ts",
            key_bi, state, int(Date.now()),
        )
        await d1_run(
            env,
            "DELETE FROM repo_state_history WHERE key_bi=? "
            "AND state_hash NOT IN (SELECT state_hash FROM "
            "repo_state_history WHERE key_bi=? ORDER BY ts DESC LIMIT ?)",
            key_bi, key_bi, STATE_PIN_HISTORY,
        )
        # This isolate's cached routing decision predates the pin.
        _https_mirror_public_context_cache_clear()
        return state
    except Exception:
        return ""


async def _owner_merge_pin_state(env, repo_bi, source_state):
    """Return the refs digest an owner-authorized mutation made current.

    The newest succeeded merge/update job for the repository carries the
    mirror-attested post-mutation state (admitted into the pin history by
    _admit_owner_merge_state) and the source's attested state at the moment
    the job ran. While the source-of-truth record still shows that same
    state — it has not published anything since, typically because it is
    offline — the owner's merge defines the repository's current generation:
    routing prefers mirrors serving it, the relay's commit event points the
    rest of the fleet at it, and the source converges from the mesh when it
    returns. Any later source publication (converged or diverged) supersedes
    the override automatically, and the job row's bounded retention bounds it
    in time. Returns "" when no override applies.
    """
    source_state = str(source_state or "").strip().lower()
    if not repo_bi or not re.fullmatch(r"[0-9a-f]{64}", source_state):
        return ""
    try:
        row = await d1_first(
            env,
            """SELECT result FROM repo_merge_jobs
                WHERE repo_bi=? AND status='succeeded' AND expires_at>?
                ORDER BY updated_at DESC LIMIT 1""",
            repo_bi, int(Date.now()),
        )
        if not row:
            return ""
        result = json.loads(str(row.get("result") or ""))
        state = str(result.get("state") or "").strip().lower()
        recorded_source = str(result.get("sourceState") or "").strip().lower()
        if (
            result.get("published") is not True
            or not re.fullmatch(r"[0-9a-f]{64}", state)
            or not re.fullmatch(r"[0-9a-f]{64}", recorded_source)
            or not hmac.compare_digest(recorded_source, source_state)
            or hmac.compare_digest(state, source_state)
        ):
            return ""
        return state
    except Exception:
        return ""


def _https_mirror_merge_response(value, mutation="merge"):
    status = str((value or {}).get("status") or "")
    if status == "processing":
        code = 202
    elif status == HTTPS_MIRROR_PULL_MUTATIONS[mutation]["terminal"]:
        code = 200
    elif (value or {}).get("error") == "pull_not_found":
        code = 404
    else:
        code = 409
    # The mirror's attestation and the relay's routing provenance are pin
    # bookkeeping, not part of the account-facing receipt.
    public = {
        key: item for key, item in (value or {}).items()
        if key not in ("state", "stateTs", "stateSig", "sourceState")
    }
    return json_response(
        public, status=code,
        cache_control="no-store, max-age=0, must-revalidate")


async def _repo_merge_jobs_make_room(env, repo_bi, now):
    """Expire bounded batches and enforce hard per-repo/global row ceilings.

    Terminal rows are oldest-first eviction candidates when a ceiling is
    reached. In-flight rows are never evicted merely to admit another request;
    the caller fails closed with 429 instead.
    """
    await d1_run(
        env,
        """DELETE FROM repo_merge_jobs WHERE request_id IN (
               SELECT request_id FROM repo_merge_jobs
                WHERE expires_at<=?
                ORDER BY expires_at ASC
                LIMIT %d)""" % HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH,
        int(now),
    )

    async def counts():
        row = await d1_first(
            env,
            """SELECT COUNT(*) AS total,
                      COALESCE(SUM(CASE WHEN repo_bi=? THEN 1 ELSE 0 END),0)
                        AS repo_count
                 FROM repo_merge_jobs""",
            repo_bi,
        )
        return (
            int((row or {}).get("total") or 0),
            int((row or {}).get("repo_count") or 0),
        )

    total, repo_count = await counts()
    if repo_count >= HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT:
        remove = min(
            HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH,
            repo_count - HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT + 1,
        )
        await d1_run(
            env,
            """DELETE FROM repo_merge_jobs WHERE request_id IN (
                   SELECT request_id FROM repo_merge_jobs
                    WHERE repo_bi=? AND status IN ('succeeded','failed')
                    ORDER BY updated_at ASC
                    LIMIT ?)""",
            repo_bi, remove,
        )
        total, repo_count = await counts()
    if total >= HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT:
        remove = min(
            HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH,
            total - HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT + 1,
        )
        await d1_run(
            env,
            """DELETE FROM repo_merge_jobs WHERE request_id IN (
                   SELECT request_id FROM repo_merge_jobs
                    WHERE status IN ('succeeded','failed')
                    ORDER BY updated_at ASC
                    LIMIT ?)""",
            remove,
        )
        total, repo_count = await counts()
    return (
        repo_count < HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT
        and total < HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT
    )


