async def _https_mirror_proxy(
        env, request, owner, repo, operation, release_sha="", bypass_cache=False,
        monitoring=False, context_cache=None, retry_failed_proofs=False):
    """Stream a public read through healthy endpoints under the original URL."""
    context_key = (
        clean_string(owner, MAX_NODE_NAME).strip().lower(),
        clean_string(repo, MAX_REPO_SEGMENT).strip().lower(),
    )
    context = None
    if isinstance(context_cache, dict):
        context = _https_mirror_public_context_copy(
            context_cache.get(context_key))
    if context is None:
        try:
            context = await _https_mirror_public_context(env, owner, repo)
        except _HttpsMirrorContextUnavailable:
            # This Worker could not build its own routing snapshot. Degraded
            # is the honest answer; not_found would tell every caller the
            # repository is gone, which is what published a served file as
            # missing on the installer status row.
            return json_response(
                {"error": "mirror_unavailable"}, status=503,
                cache_control="no-store",
                extra_headers=EXPECTED_DEGRADED_HEADERS)
        if context is not None and isinstance(context_cache, dict):
            context_cache[context_key] = _https_mirror_public_context_copy(
                context)
    if context is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    # org_alias_rewrite gives access checks and pin selection the canonical
    # backing node. Repository bytes must still be requested from the gateway
    # under the untouched public organization identity. The rewrite preserves
    # request.url, so recover only an alias that D1 verifies maps to that node.
    try:
        original_path = _git_request_path(request)
        original_match = (
            GIT_INFO_RE.match(original_path)
            or GIT_PACK_RE.match(original_path)
            or RELEASE_BLOB_RE.match(original_path)
            or REPO_HOST_RE.match(original_path)
        )
        route_owner = (
            safe_segment(original_match.group(1)) if original_match else "")
        route_repo = (
            safe_segment(original_match.group(2)) if original_match else "")
        if (
            route_owner
            and route_repo.lower() == repo.lower()
            and route_owner != owner
            and await _org_repo_node(
                env, route_owner, route_repo) == owner
        ):
            context = dict(context)
            context["routeOwner"] = route_owner
            context["repoBi"] = await blind_index(
                env, route_owner + "/" + route_repo)
    except Exception:
        pass
    method = method_name(request)
    if operation == "git-upload-pack" and method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if operation != "git-upload-pack" and method not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    git_protocol = ""
    if operation in ("git-info-refs", "git-upload-pack"):
        git_protocol = str(
            request.headers.get("git-protocol") or ""
        ).strip().lower()
        if git_protocol not in ("", "version=1", "version=2"):
            return json_response(
                {
                    "error": "unsupported_git_protocol",
                    "hint": "Use Git protocol version 0, 1, or 2.",
                },
                status=400,
                cache_control="no-store",
            )
    query = _https_mirror_request_query(
        urlparse(request.url), operation, release_sha=release_sha)
    bypass_cache = bool(
        bypass_cache or request_bypasses_repository_metadata_cache(request)
    )
    metadata_cache_key = (
        repository_metadata_cache_key(
            context, operation, query, now=int(Date.now()))
        if method == "GET" else ""
    )
    metadata_fallback_key = (
        repository_metadata_cache_key(
            context, operation, query, fallback=True)
        if method == "GET" else ""
    )
    cached_metadata = (
        await repository_metadata_cache_get(env, metadata_cache_key)
        if not bypass_cache else None)
    if cached_metadata is not None:
        return cached_metadata

    async def cached_metadata_after_outage():
        # no-cache means "try a live mirror first", not "erase the last
        # attested view when every mirror has a transient routing failure".
        # Monitoring must remain live-only so it can never mistake a cache hit
        # for a healthy endpoint. The cache key includes the repository's
        # current signed refs digest and the requested immutable ref, so this
        # fallback cannot cross repository state.
        if monitoring or not metadata_cache_key:
            return None
        current = await repository_metadata_cache_get(
            env, metadata_cache_key)
        if current is not None:
            return current
        if (
            metadata_fallback_key
            and metadata_fallback_key != metadata_cache_key
        ):
            return await repository_metadata_cache_get(
                env, metadata_fallback_key)
        return None
    body = b""
    if method == "POST":
        try:
            announced = int(request.headers.get("content-length") or 0)
        except Exception:
            announced = 0
        if announced > HTTPS_MIRROR_BODY_MAX_BYTES:
            return Response("request too large", status=413)
        try:
            body = bytes(await request.bytes())
        except Exception:
            return Response("invalid request body", status=400)
        if len(body) > HTTPS_MIRROR_BODY_MAX_BYTES:
            return Response("request too large", status=413)
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    if not router_public_key or not router_seed:
        cached_metadata = await cached_metadata_after_outage()
        if cached_metadata is not None:
            return cached_metadata
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    sticky = (
        await _https_mirror_clone_pin(env, context)
        if operation == "git-upload-pack" else "")
    avoid_node = (
        clean_string(
            request.headers.get("x-forkmesh-avoid-node") or "",
            (MAX_NODE_NAME + 1) * 4,
        ).strip().lower()
        if operation in ("git-info-refs", "git-upload-pack") else ""
    )
    candidates = await _https_mirror_request_candidates(
        env, context, world_request_country(request), sticky=sticky,
        monitoring=monitoring, context_cache=context_cache,
        avoid_node=avoid_node)
    # A deep probe performs several sequential reads through one caller-owned
    # routing snapshot. If an endpoint times out on the first read, retrying it
    # for every tree/blob request can spend the probe's entire invocation on
    # the same dead mirror before a result is persisted. Quarantine only within
    # this explicit probe suite: visitor routing remains unchanged and the
    # signed mirror-health phase still exclusively owns shared eligibility.
    probe_quarantine = None
    if monitoring and isinstance(context_cache, dict):
        quarantine_key = (
            "https-mirror-probe-quarantine-v1",
            str(context.get("repoBi") or ""),
            str(context.get("routeOwner") or context.get("owner") or "")
            .lower(),
            str(context.get("repo") or "").lower(),
        )
        probe_quarantine = context_cache.get(quarantine_key)
        if not isinstance(probe_quarantine, set):
            probe_quarantine = set()
            context_cache[quarantine_key] = probe_quarantine
        candidates = [
            endpoint for endpoint in candidates
            if str(endpoint.get("node") or "").lower()
            not in probe_quarantine
        ]
    if not candidates:
        cached_metadata = await cached_metadata_after_outage()
        if cached_metadata is not None:
            return cached_metadata
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    # If every reachable endpoint says 404, preserve that repository answer;
    # Git transport still receives a retryable degraded response.
    attempted = 0
    absent = 0
    # Signed refs digests this request saw ahead of the pin set, by node.
    lagging_refs_quorum = {}
    # The endpoints behind those digests, so an upload-pack that reaches the
    # quorum on a later candidate still returns to its advertising node.
    lagging_refs_endpoints = {}
    pending = list(candidates)
    while pending:
        endpoint = pending.pop(0)
        mirror_origin = (
            https_routing.normalize_base_url(endpoint.get("mirrorUrl"))
            if endpoint.get("mirrorUrl") else ""
        )
        if (
            not monitoring
            and mirror_origin
            and not _mirror_origin_is_this_app(env, request, mirror_origin)
            and operation in {"git-info-refs", "git-upload-pack"}
            and await _https_mirror_repository_proof(
                env, endpoint, context, operation, origin=mirror_origin)
        ):
            direct_target = https_routing.direct_git_target_url(
                mirror_origin,
                context.get("routeOwner") or context["owner"],
                context["repo"],
                operation,
                query,
            )
            if direct_target:
                if operation == "git-info-refs":
                    if not monitoring:
                        await _https_mirror_route_advance(
                            env, context, endpoint["node"], operation)
                return Response(None, status=307, headers={
                    "Location": direct_target,
                    "Cache-Control": "no-store",
                    "X-ForkMesh-Served-By": endpoint["node"],
                    "X-ForkMesh-Transport": "direct-mirror",
                })
        proof_details = {}
        if not await _https_mirror_repository_proof(
                env, endpoint, context, operation,
                retry_failed=retry_failed_proofs, details=proof_details):
            lagging_digest = str(
                proof_details.get("refsSha256") or "").lower()
            lagging_refs_endpoints.setdefault(lagging_digest, {})[
                str(endpoint.get("node") or "").lower()] = endpoint
            admit_actions_push = globals().get("_actions_push_admitted")
            if not https_routing.mismatch_is_servable(
                    operation, endpoint.get("node"), proof_details,
                    lagging_refs_quorum) and not (
                        not monitoring and callable(admit_actions_push)
                        and await admit_actions_push(
                            env, context, endpoint, operation,
                            proof_details)):
                if probe_quarantine is not None:
                    probe_quarantine.add(
                        str(endpoint.get("node") or "").lower())
                continue
            advertised_by = (
                lagging_refs_endpoints[lagging_digest].pop(sticky, None)
                if operation == "git-upload-pack" and sticky else None)
            if advertised_by is not None and advertised_by is not endpoint:
                # Tried once; this candidate stays next in line behind it.
                pending.insert(0, endpoint)
                endpoint = advertised_by
        target = https_routing.masked_target_url(
            endpoint["baseUrl"],
            context.get("routeOwner") or context["owner"],
            context["repo"],
            operation,
            query,
        )
        parsed_target = urlparse(target)
        signed_path = parsed_target.path + (
            ("?" + parsed_target.query) if parsed_target.query else "")
        body_digest = hashlib.sha256(body).hexdigest()
        request_id = _b64url_encode(_random_bytes(18))
        issued_at = int(Date.now())
        message = https_routing.request_message(
            endpoint["node"],
            method,
            signed_path,
            body_digest,
            request_id,
            issued_at,
        )
        signature = await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if not target or not message or not signature:
            continue
        headers = {
            "X-ForkMesh-Node": endpoint["node"],
            "X-ForkMesh-Request-Id": request_id,
            "X-ForkMesh-Issued-At": str(issued_at),
            "X-ForkMesh-Body-Sha256": body_digest,
            "X-ForkMesh-Signature": signature,
        }
        if git_protocol:
            # Git-Protocol is a bounded stock-Git negotiation hint, not an
            # authorization input. The request capability still binds the
            # exact method, path, body digest, node, request id, and time; the
            # gateway independently accepts only version=1 or version=2.
            headers["Git-Protocol"] = git_protocol
        if operation == "git-upload-pack":
            headers["Content-Type"] = (
                "application/x-git-upload-pack-request")
            encoding = request.headers.get("content-encoding")
            if encoding:
                headers["Content-Encoding"] = encoding
        init = {
            "method": method,
            "headers": headers,
            "redirect": "manual",
        }
        if method == "POST":
            init["body"] = Uint8Array.new(_to_js(body))
        try:
            if operation == "git-upload-pack":
                upstream = await js_fetch_until_response(
                    target, init,
                    HTTPS_MIRROR_GIT_INITIAL_RESPONSE_TIMEOUT_SECONDS)
            else:
                upstream = await js_fetch_with_timeout(
                    target, init, HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS)
            status = int(getattr(upstream, "status", 0) or 0)
        except Exception:
            status = 0
            upstream = None
        if upstream is not None:
            attempted += 1
            if status == 404:
                absent += 1
        if (
            upstream is None
            or status in HTTPS_MIRROR_RETRY_STATUSES
            or 500 <= status <= 599
        ):
            if upstream is not None:
                await _discard_response_body(upstream)
            # Monitoring suites quarantine retry failures only for this request.
            if probe_quarantine is not None:
                probe_quarantine.add(
                    str(endpoint.get("node") or "").lower())
            # Only signed health owns shared endpoint state; transient request
            # failures remain local, while visitor auth rejection stays hard.
            await _https_mirror_record_request_rejection(
                env, endpoint, status, monitoring=monitoring)
            continue
        raw_headers = {}
        for name in (
            "content-type", "content-length", "content-range",
            "accept-ranges", "etag", "last-modified", "cache-control",
            "content-disposition",
        ):
            try:
                value = upstream.headers.get(name)
            except Exception:
                value = None
            # `Headers.get` answers JS null for a header the endpoint never
            # sent, and that is not None: it stringifies to the literal
            # "jsnull". Copying it verbatim shipped `etag: jsnull` (and, for a
            # gateway that omits it, `content-disposition: jsnull`) to the
            # browser on every routed read, release downloads included.
            if not js_nullish(value):
                raw_headers[name] = str(value)
        response_headers = https_routing.response_headers(raw_headers)
        if operation == "release-blob":
            filename_values = parse_qs(
                urlparse(request.url).query, keep_blank_values=True
            ).get("filename", [])
            disposition = release_download_content_disposition(
                filename_values[0] if len(filename_values) == 1 else "")
            if disposition:
                # The mirror proves the bytes by digest.  Preserve the asset
                # name selected from release.json at the public edge so the
                # gateway's content-addressed storage name cannot override it.
                response_headers["content-disposition"] = disposition
        # A public node name is safe operational provenance (it is already
        # listed on the repository's Mirrors tab). Attach it only to the live
        # upstream response that this request actually selected. Edge-held
        # metadata responses are rebuilt by repository_metadata_cache_get
        # without this header, so a cache hit can never falsely claim that a
        # particular mirror just served it.
        response_headers["X-ForkMesh-Served-By"] = endpoint["node"]
        if not monitoring:
            await _https_mirror_route_advance(
                env, context, endpoint["node"], operation)
        if (
            not monitoring
            and str(endpoint.get("refsSha256") or "").lower()
            in context.get("currentPins", set())
        ):
            for cache_key in (
                    metadata_cache_key, metadata_fallback_key):
                await repository_metadata_cache_put(
                    env, cache_key, upstream, status)
        # The private endpoint origin remains masked. The public node identity
        # above is bounded routing provenance; repository bytes still stream
        # without being materialized by the Worker.
        return JsResponse.new(
            upstream.body,
            to_js({"status": status, "headers": response_headers}),
        )
    if (
        attempted
        and absent == attempted
        and operation not in ("git-info-refs", "git-upload-pack")
    ):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    cached_metadata = await cached_metadata_after_outage()
    if cached_metadata is not None:
        return cached_metadata
    return json_response(
        {"error": "mirror_unavailable"}, status=503,
        cache_control="no-store",
        extra_headers=EXPECTED_DEGRADED_HEADERS)


GIT_PUSH_SIGNATURE_PREFIX = "forkmesh-git-push-v1"


def _git_push_signature_message(owner, repo, method, ts, body_sha256):
    """Canonical device-signed authorization for one HTTPS push request.

    Signed by a mobile/desktop device key (or an org member's account key)
    over ``forkmesh-git-push-v1\\n{owner}\\n{repo}\\n{method}\\n{ts}\\n
    {sha256hex(body)}``; the empty advertisement GET signs the sha256 of the
    empty byte string (www/docs/mobile/mobile-node-contract.md section 7).
    """
    owner = str(owner or "").strip().lower()
    repo = str(repo or "").strip()
    method = str(method or "").strip().upper()
    ts = str(ts or "").strip()
    body_sha256 = str(body_sha256 or "").strip().lower()
    if (
        not valid_node_name(owner)
        or not safe_segment(repo)
        or method not in ("GET", "POST")
        or not ts.isdigit()
        or len(ts) > 16
        or not re.fullmatch(r"[0-9a-f]{64}", body_sha256)
    ):
        return b""
    return "\n".join((
        GIT_PUSH_SIGNATURE_PREFIX, owner, repo, method, ts, body_sha256,
    )).encode("utf-8")


async def _git_push_account_for_pubkey(env, pubkey):
    """Resolve the account name a signing pubkey belongs to, or "".

    An account's primary key resolves through the nodes table; an enabled,
    non-revoked device key resolves through its account_devices row back to
    the account record it was bound under. Fail closed on any error.
    """
    if not pubkey:
        return ""
    try:
        _, rec = await _account_row_by_pubkey(env, pubkey)
        name = str((rec or {}).get("name") or "").strip().lower()
        if valid_node_name(name):
            return name
        device = await d1_first(
            env,
            "SELECT account_bi FROM account_devices "
            "WHERE pubkey=? AND enabled=1 AND revoked_at=0",
            pubkey,
        )
        account_bi = (device or {}).get("account_bi")
        if not account_bi:
            return ""
        node = await d1_first(
            env, "SELECT data FROM nodes WHERE node_bi=?", account_bi)
        rec = (
            await decrypt_row(env, node.get("data")) if node else None)
        name = str((rec or {}).get("name") or "").strip().lower()
        return name if valid_node_name(name) else ""
    except Exception:
        return ""


async def _git_push_authorize(
        env, owner, repo, method, body_sha256, pubkey, ts, sig,
        alias_owner=""):
    """Return the authorized pushing account name, or "" (fail closed).

    ``body_sha256`` is the digest the device signed: computed here for a
    buffered body, or claimed in ``X-ForkMesh-Body-Sha256`` for a pack the
    Worker streams without holding, in which case the mirror gateway checks
    the bytes it receives against that same digest before running git.

    Authorized when the presented key is the owner account's primary key, an
    enabled owner_sign device key that also carries publish_repo, or the
    primary/device key of an account holding org write permission on a linked
    repository (the SSH broker's permission shape). Every explicit decision
    on a presented signature is audited as git.push_authorize.
    """
    audit_target = owner + "/" + repo
    details = {"operation": "git-receive-pack", "method": method}

    async def denied(actor):
        await _audit_sensitive_action(
            env, actor or owner, "git.push_authorize", "repository",
            audit_target, "denied", details)
        return ""

    if not valid_node_pubkey(pubkey):
        return await denied("")
    try:
        skew = abs(int(Date.now()) - int(ts))
    except (TypeError, ValueError):
        return await denied("")
    if skew > LOGIN_MAX_SKEW_MS:
        return await denied("")
    signed = False
    for signed_owner in [owner] + ([alias_owner] if alias_owner else []):
        message = _git_push_signature_message(
            signed_owner, repo, method, ts, body_sha256)
        if message and await ed25519_verify(pubkey, sig, message):
            signed = True
            break
    if not signed:
        return await denied("")
    signing_keys = await _owner_signing_pubkeys(env, owner)
    if pubkey in signing_keys:
        allowed = bool(
            pubkey and pubkey == await _owner_pubkey(env, owner))
        if not allowed:
            device = await _account_device_for_pubkey(
                env, await blind_index(env, owner), pubkey)
            capabilities = [
                item for item in clean_string(
                    (device or {}).get("capabilities", ""), 512).split(",")
                if item
            ]
            allowed = bool(
                device
                and device.get("enabled")
                and not device.get("revoked_at")
                and "publish_repo" in capabilities
            )
        if allowed:
            await _audit_sensitive_action(
                env, owner, "git.push_authorize", "repository",
                audit_target, "success", details)
            return owner
    account = await _git_push_account_for_pubkey(env, pubkey)
    if (
        account
        and account != owner
        and await _org_write_allowed(env, owner, repo, account)
    ):
        await _audit_sensitive_action(
            env, account, "git.push_authorize", "repository",
            audit_target, "success", details)
        return account
    return await denied(account)


async def _hosted_git_write_endpoint(env):
    """Resolve the configured writable-origin endpoint for first pushes.

    HOSTED_GIT_WRITE_NODE names a registered mirror node; its base URL is
    read from the same mirror_https_endpoints registration/health store every
    routed read uses. Unset or unresolvable fails closed to None.
    """
    node = clean_string(
        getattr(env, "HOSTED_GIT_WRITE_NODE", "") or "", MAX_NODE_NAME
    ).strip().lower()
    if not valid_node_name(node):
        return None
    try:
        row = await d1_first(
            env,
            """SELECT node_name,base_url,public_key,registration_sig,
                      issued_at,checked_at,latency_ms,region,healthy,
                      integrity,abuse_blocked,forkmesh_refs_sha256
                 FROM mirror_https_endpoints WHERE node_name=?""",
            node,
        )
    except Exception:
        return None
    if not row:
        return None
    endpoint = _https_mirror_endpoint_projection(row)
    if not https_routing.normalize_base_url(endpoint.get("baseUrl")):
        return None
    return endpoint


def _git_request_path(request):
    try:
        path = urlparse(str(request.url)).path
    except Exception:
        return ""
    setting = repo_short_urls.cached(int(Date.now())) or {}
    if setting.get("short"):
        hit = repo_short_urls.rewrite(path, setting.get("owner"))
        if hit is not None and not hit[1]:
            return hit[0]
    return path


async def _repo_short_setting_row(env):
    now = int(Date.now())
    setting = repo_short_urls.cached(now)
    if setting is not None:
        return setting
    try:
        row = await d1_first(
            env, "SELECT doc FROM instance_settings WHERE k=?",
            repo_short_urls.SETTING_KEY)
    except Exception:
        row = None
    return repo_short_urls.remember(
        repo_short_urls.parse((row or {}).get("doc") or ""), now)


async def _repo_name_is_account(env, name, internal_ok=False):
    name = str(name or "").lower()
    if not repo_short_urls.OWNER_RE.fullmatch(name):
        return False
    try:
        if (await _org_row(env, name))[1]:
            return True
        account = (await _account_row(env, name))[1]
        if internal_ok and account and _account_kind(account) == "node":
            return False
        return bool(account)
    except Exception:
        return True


async def _org_internal_members(env, org, names):
    setting = await _repo_short_setting_row(env)
    if not repo_short_urls.canonical_owner(setting) or \
            repo_short_urls.canonical_owner(setting) != str(org or "").lower():
        return set()
    hidden = set()
    for name in names:
        try:
            account = (await _account_row(env, name))[1]
        except Exception:
            continue
        if account and _account_kind(account) == "node":
            hidden.add(name)
    return hidden


async def _repo_canonical_path(env, path, query="", public_only=True):
    setting = await _repo_short_setting_row(env)
    owner = repo_short_urls.canonical_owner(setting)
    parts = [p for p in str(path or "").split("/") if p]
    if not owner or len(parts) < 2:
        return None
    first = unquote(parts[0]).lower()
    if first != owner:
        name = unquote(parts[1])
        if not repo_short_urls.OWNER_RE.fullmatch(first):
            return None
        if await _org_repo_node(env, owner, name) != first:
            return None
        if public_only and await _repo_is_private(env, first, name):
            return None
        path = "/" + "/".join([quote(owner, safe="")] + parts[1:])
    hit = repo_short_urls.canonical_redirect(path, query, setting)
    if hit is None or await _repo_name_is_account(env, hit[1], True):
        return None
    return hit[0]


async def _short_repo_board(env, rows):
    shown = []
    for row in rows:
        owner, _, name = str(row.get("name") or "").partition("/")
        if owner and name and "/" not in name:
            try:
                path = await _repo_canonical_path(
                    env, "/%s/%s" % (quote(owner, safe=""), quote(name, safe="")))
            except Exception:
                path = None
            if path and path.count("/") == 1:
                row = dict(row, name=unquote(path[1:]))
        shown.append(row)
    return shown


async def _repo_public_path(env, owner, name):
    path = "/%s/%s" % (quote(str(owner or ""), safe=""),
                       quote(str(name or ""), safe=""))
    return await _repo_canonical_path(env, path, public_only=False) or path


async def _repo_public_href(env, href):
    href = str(href or "")
    if not href.startswith("/") or href.startswith("//"):
        return href
    path, _, query = href.partition("?")
    try:
        return await _repo_canonical_path(
            env, path, query, public_only=False) or href
    except Exception:
        return href


async def _repo_short_links(env, owner):
    now = int(Date.now())
    links = repo_short_urls.cached_keep(owner, now)
    if links is not None:
        return links
    rows = {}
    try:
        org_bi = await blind_index(env, "org:" + owner)
        for row in await d1_all(
                env, "SELECT repo, node_owner FROM org_repos WHERE org_bi=?",
                org_bi) or []:
            name = str(row.get("repo") or "")
            creator = str(row.get("node_owner") or "").lower()
            if name:
                rows[name] = (creator, await _repo_is_private(
                    env, creator or owner, name))
        owner_bi = await blind_index(env, owner)
        for row in await d1_all(
                env, "SELECT data FROM repositories WHERE owner_bi=?",
                owner_bi) or []:
            rec = await decrypt_row(env, row.get("data"))
            if rec and rec.get("name"):
                rows.setdefault(str(rec["name"]), (
                    "", rec.get("visibility") != "public"))
        taken = []
        for name in repo_short_urls.owner_candidates(rows, owner):
            if await _repo_name_is_account(env, name, True):
                taken.append(name)
    except Exception:
        return None
    return repo_short_urls.remember_keep(
        owner, repo_short_urls.links_doc(rows, owner, taken), now)


async def _repo_clone_url(env, origin, owner, name):
    path = await _repo_public_path(env, owner, name)
    return origin + path + (".git" if path.count("/") == 1 else "")


async def _git_push_alias_owner(env, request, owner, repo):
    path = _git_request_path(request)
    if not path:
        return ""
    match = GIT_INFO_RE.match(path) or GIT_RECEIVE_RE.match(path)
    if not match:
        return ""
    alias = (safe_segment(match.group(1)) or "").strip().lower()
    alias_repo = (safe_segment(match.group(2)) or "").strip().lower()
    if (
        not alias
        or alias == str(owner or "").strip().lower()
        or alias_repo != str(repo or "").strip().lower()
    ):
        return ""
    node = await _org_repo_node(env, alias, alias_repo)
    return alias if node and node == str(owner or "").strip().lower() else ""


async def _core_push_permitted(env, owner, repo, account):
    owner = str(owner or "").strip().lower()
    repo = str(repo or "").strip().lower()
    account = str(account or "").strip().lower()
    if not owner or not repo or not account:
        return False
    try:
        rows = await d1_all(
            env, "SELECT org_bi FROM org_repos WHERE node_owner=? AND repo=?",
            owner, repo)
        if rows:
            for row in rows:
                role = await _org_role(
                    env, str(row.get("org_bi") or ""), account)
                if role == "owner":
                    return True
            return False
        return account != owner and await _account_owns_node(
            env, account, owner)
    except Exception:
        return False


def _ref_updates_from(upstream):
    try:
        raw = upstream.headers.get("x-forkmesh-ref-updates")
    except Exception:
        return {"total": 0, "updates": []}
    if js_nullish(raw) or not raw:
        return {"total": 0, "updates": []}
    try:
        value = json.loads(str(raw)[:16384])
    except Exception:
        return {"total": 0, "updates": []}
    updates = []
    for item in (value.get("updates") if isinstance(value, dict) else None) or []:
        if not isinstance(item, dict):
            continue
        ref = clean_string(item.get("ref", ""), 200)
        old = clean_string(item.get("old", ""), 64).lower()
        new = clean_string(item.get("new", ""), 64).lower()
        if (
            not ref.startswith(("refs/heads/", "refs/tags/"))
            or not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", old)
            or not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", new)
        ):
            continue
        try:
            commits = max(0, int(item.get("commits") or 0))
        except (TypeError, ValueError):
            commits = 0
        updates.append(
            {"ref": ref, "old": old, "new": new, "commits": commits})
    try:
        total = max(len(updates), int(value.get("total") or 0))
    except (TypeError, ValueError, AttributeError):
        total = len(updates)
    actions = isinstance(value, dict) and value.get("actions") is True
    return {"total": total, "updates": updates, "actions": actions}


def _core_push_nodes(env):
    core_nodes_of = (globals().get("hosted_core_owners")
                     or globals().get("hosted_core_nodes"))
    if not callable(core_nodes_of):
        return set()
    return {
        str(node or "").strip().lower()
        for node in (core_nodes_of(env) or [])
    }


async def _admit_core_push_state(env, owner, repo, endpoint, alias=""):
    try:
        context = await _https_mirror_public_context(env, owner, repo)
    except Exception:
        return ""
    if not context or not context.get("repoBi"):
        return ""
    state = ""
    try:
        state = await _record_core_push_state(env, context, endpoint, alias)
    except Exception:
        state = ""
    if state:
        try:
            await record_hosted_push_state(
                env, context["owner"], context["repo"], endpoint,
                state=state, notify=False)
        except Exception:
            pass
    generation = int(Date.now()) if state else 0
    try:
        scheduled = await schedule_repo_mirror_wake(
            env, context["owner"], context["repo"], "commits", state,
            generation)
        if not scheduled:
            await notify_repo_mirrors(
                env, context["owner"], context["repo"], "commits", state,
                generation)
    except Exception:
        pass
    return state


async def _actions_push_admitted(env, context, endpoint, operation, details):
    if operation == "git-receive-pack":
        return False
    lagging = https_routing.signed_refs_lag(operation, details)
    node = str((endpoint or {}).get("node") or "").strip().lower()
    owner = str(context.get("owner") or "").strip().lower()
    cores = _core_push_nodes(env)
    if not lagging or not node or node not in cores or owner not in cores:
        return False
    try:
        import runner_actions
        import runner_leases
        runner_leases._bind_runtime(globals())
        if not await runner_actions.pushing(
                runner_leases.WorkerRuntime(env, None), owner,
                context["repo"], node):
            return False
    except Exception:
        return False
    try:
        state = await _admit_core_push_state(
            env, owner, context["repo"], endpoint,
            alias=str(context.get("routeOwner") or ""))
    except Exception:
        return False
    return bool(state)


async def _record_core_push_state(env, context, endpoint, alias):
    details = {}
    proof_context = dict(context)
    proof_context["pins"] = frozenset()
    if alias:
        proof_context["routeOwner"] = alias
    try:
        await _https_mirror_repository_proof(
            env, endpoint, proof_context, "git-upload-pack",
            force_refresh=True, details=details)
    except Exception:
        return ""
    state = clean_string(details.get("refsSha256", ""), 64).strip().lower()
    if (
        details.get("reason") not in ("verified", "refs_mismatch")
        or not details.get("signed")
        or not re.fullmatch(r"[0-9a-f]{64}", state)
    ):
        return ""
    key_bi = context["repoBi"]
    await d1_run(
        env,
        "INSERT INTO repo_state_history (key_bi, state_hash, ts) "
        "VALUES (?,?,?) ON CONFLICT(key_bi, state_hash) "
        "DO UPDATE SET ts=excluded.ts",
        key_bi, state, int(Date.now()),
    )
    await d1_run(
        env,
        "DELETE FROM repo_state_history WHERE key_bi=? "
        "AND state_hash NOT IN (SELECT state_hash FROM "
        "repo_state_history WHERE key_bi=? ORDER BY ts DESC LIMIT ?)",
        key_bi, key_bi, STATE_PIN_HISTORY,
    )
    _https_mirror_public_context_cache_clear()
    return state


async def _https_mirror_push_candidates(
        env, request, owner, repo, core_allowed=False, alias=None):
    """Endpoints allowed to accept receive-pack for owner/repo, best first.

    Healthy routed endpoints qualify only when their fresh signed repository
    proof advertises the git-receive-pack operation. A repository without any
    such endpoint (the first push of a new repository) falls back to the
    configured HOSTED_GIT_WRITE_NODE origin, whose gateway independently
    enforces its writable-owner allowlist. A repository the core nodes host
    (HOSTED_GIT_CORE_NODES) goes to its last pusher, else its rendezvous-first
    live core.
    """
    # Resolved through globals() so the AST-extraction harnesses, which lift
    # this function into a bare namespace, keep running without it.
    hosted_candidates = globals().get("hosted_push_candidates")
    hosted = (
        await hosted_candidates(env, owner, repo)
        if callable(hosted_candidates) else None)
    if hosted is not None:
        return hosted
    candidates = []
    try:
        context = await _https_mirror_public_context(env, owner, repo)
    except Exception:
        context = None
    if context is not None:
        if alias is None:
            alias = await _git_push_alias_owner(env, request, owner, repo)
        if alias:
            context = dict(context)
            context["routeOwner"] = alias
            context["repoBi"] = await blind_index(env, alias + "/" + repo)
        for endpoint in await _https_mirror_request_candidates(
                env, context, world_request_country(request),
                operation="git-receive-pack"):
            try:
                if await _https_mirror_repository_proof(
                        env, endpoint, context, "git-receive-pack"):
                    candidates.append(endpoint)
            except Exception:
                continue
    core_nodes = _core_push_nodes(env)
    if core_nodes and not core_allowed:
        candidates = [
            endpoint for endpoint in candidates
            if str(endpoint.get("node") or "").strip().lower()
            not in core_nodes
        ]
    write_endpoint = await _hosted_git_write_endpoint(env)
    if write_endpoint is not None and all(
        endpoint.get("node") != write_endpoint.get("node")
        for endpoint in candidates
    ):
        candidates.append(write_endpoint)
    return candidates


def _git_push_basic_challenge():
    """Refuse an unauthorized push, and tell git how to authenticate.

    A signing client (desktop/mobile node) ignores this header and retries
    with signed device headers; a stock git reads it and supplies the account
    name plus the hosted push credential the website issued, which is the
    only way plain `git push` can reach a web-created repository (#676).
    """
    return json_response(
        {"error": "push_unauthorized"}, status=401,
        cache_control="no-store",
        extra_headers={"WWW-Authenticate": 'Basic realm="forkmesh"'})


def _https_mirror_request_body_stream(request):
    """The inbound request's JS ReadableStream, or None when it has no body.

    Handing this stream to the upstream fetch lets a Git pack of any size the
    edge accepts cross the Worker without a Python copy; it is single-use.
    """
    stream = getattr(request, "body", None)
    if js_nullish(stream):
        return None
    return stream


async def _https_mirror_push_proxy(env, request, owner, repo, is_info):
    """Authorize and stream one signed HTTPS receive-pack request.

    Same masked-proxy shape as public reads: the Worker verifies the device
    signature, signs a per-request forkmesh-masked-proxy-v1 capability bound
    to method and the /v1/repositories/{owner}/{repo}/git-receive-pack
    target, and streams without materializing repository bytes in D1.
    """
    method = method_name(request)
    if (is_info and method != "GET") or (not is_info and method != "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    headers = getattr(request, "headers", None)
    pubkey = clean_string(
        headers.get("x-forkmesh-pubkey") if headers else "", 120).strip()
    ts = clean_string(
        headers.get("x-forkmesh-ts") if headers else "", 20).strip()
    sig = clean_string(
        headers.get("x-forkmesh-sig") if headers else "", 200).strip()
    authorization = clean_string(
        headers.get("authorization") if headers else "", 600).strip()
    signed_headers = bool(pubkey and ts and sig)
    # A stock `git push` cannot sign each request's body, so a web-created
    # hosted repository authenticates with the Basic credential its owner's
    # browser session minted instead (issue #676). Everything else is still
    # refused: unsigned crawler/probe traffic is expected, deliberately
    # unaudited, and answered before its body is consumed.
    if not signed_headers and not has_hosted_push_credential(authorization):
        return _git_push_basic_challenge()
    body = b""
    body_stream = None
    body_digest = hashlib.sha256(b"").hexdigest()
    if method == "POST":
        # A pack the Worker can hold is buffered and the capability binds its
        # digest. Anything larger is streamed through untouched: a stock git
        # sends any push over http.postBuffer (1 MiB) chunked with no length,
        # and a repository of any real size does not fit a Pyodide isolate.
        # A signing device that states the digest it signed lets the gateway
        # check the streamed bytes against it; a Basic credential cannot, so
        # its streamed pack rides the fixed streamed-body capability instead.
        claimed_digest = ""
        if signed_headers:
            claimed_digest = clean_string(
                headers.get("x-forkmesh-body-sha256") or "", 64,
            ).strip().lower()
            if claimed_digest and not re.fullmatch(
                    r"[0-9a-f]{64}", claimed_digest):
                return Response("invalid body digest", status=400)
        try:
            announced = int(request.headers.get("content-length") or 0)
        except Exception:
            announced = 0
        if claimed_digest:
            body_stream = _https_mirror_request_body_stream(request)
            body_digest = claimed_digest
        elif signed_headers or 0 < announced <= HTTPS_MIRROR_BODY_MAX_BYTES:
            # A device signature without a stated digest covers bytes the
            # Worker must hold to verify, so that push stays bounded here.
            if announced > HTTPS_MIRROR_BODY_MAX_BYTES:
                return json_response(
                    {"error": "push_too_large"}, status=413,
                    cache_control="no-store")
            try:
                body = bytes(await request.bytes())
            except Exception:
                return Response("invalid request body", status=400)
            if len(body) > HTTPS_MIRROR_BODY_MAX_BYTES:
                return json_response(
                    {"error": "push_too_large"}, status=413,
                    cache_control="no-store")
            body_digest = hashlib.sha256(body).hexdigest()
        else:
            body_stream = _https_mirror_request_body_stream(request)
            if body_stream is not None:
                body_digest = https_routing.STREAMED_REQUEST_BODY_SHA256
    alias_owner = await _git_push_alias_owner(env, request, owner, repo)
    push_prefix = ""
    if signed_headers:
        account = await _git_push_authorize(
            env, owner, repo, method, body_digest, pubkey, ts, sig,
            alias_owner=alias_owner)
    else:
        account, push_prefix = await verify_hosted_push_access(
            env, owner, repo, authorization, method, alias=alias_owner)
    if not account:
        return _git_push_basic_challenge()
    core_held = str(owner or "").strip().lower() in _core_push_nodes(env)
    if core_held and not push_prefix and not await _core_push_permitted(
            env, owner, repo, account):
        await _audit_sensitive_action(
            env, account, "git.push_authorize", "repository",
            owner + "/" + repo, "denied",
            {"operation": "git-receive-pack", "method": method,
             "reason": "organization_owner_required"})
        return json_response(
            {"error": "push_forbidden",
             "message": "Only an owner of the repository's organization "
                        "may push to it."},
            status=403, cache_control="no-store")
    hosted_limit = globals().get("hosted_push_limit")
    limited = (
        await hosted_limit(env, request, owner, repo, method)
        if callable(hosted_limit) else None)
    if limited is not None:
        return limited
    upstream, endpoint = await _https_mirror_push_send(
        env, request, owner, repo, account, method, body, body_stream,
        body_digest, is_info=is_info, alias_owner=alias_owner,
        core_held=core_held,
        credential="key" if signed_headers else (
            "contributor" if push_prefix else "session"),
        encoding=request.headers.get("content-encoding"),
        push_prefix=push_prefix)
    if upstream is None:
        return json_response(
            {"error": "push_unavailable"}, status=503,
            cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    raw_headers = {}
    for name in (
        "content-type", "content-length", "cache-control",
    ):
        try:
            value = upstream.headers.get(name)
        except Exception:
            value = None
        if value is not None:
            raw_headers[name] = str(value)
    response_headers = https_routing.response_headers(raw_headers)
    response_headers["X-ForkMesh-Served-By"] = endpoint["node"]
    return JsResponse.new(
        upstream.body,
        to_js({"status": int(getattr(upstream, "status", 0) or 0),
               "headers": response_headers}),
    )


async def _https_mirror_push_send(
        env, request, owner, repo, account, method, body, body_stream,
        body_digest, is_info=False, alias_owner="", core_held=False,
        credential="session", encoding=None, push_prefix=""):
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    if not router_public_key or not router_seed:
        return None, None
    candidates = await _https_mirror_push_candidates(
        env, request, owner, repo, core_allowed=core_held,
        alias=alias_owner)
    if not candidates:
        return None, None
    tag_moves = (
        await core_push_pending_tag_moves(env, owner, repo, account)
        if core_held and method == "POST" and not push_prefix else {})
    query = {"service": "git-receive-pack"} if is_info else None
    if tag_moves:
        query = {"tagMoves": " ".join(
            ref + ":" + target for ref, target in sorted(tag_moves.items()))}
    if method == "POST":
        protected, protection_problem = (
            await _branch_protection.push_protection(
                env, alias_owner or owner, repo))
        if protection_problem:
            return None, None
        if protected:
            query = dict(query or {}, protect=" ".join(protected))
        if push_prefix:
            query = dict(query or {}, pushPrefix=push_prefix)
    for endpoint in candidates:
        if body_stream is not None and endpoint is not candidates[0]:
            # A streamed pack is consumed by its first upstream attempt; the
            # client (git) retries a failed push, the Worker cannot.
            break
        target = https_routing.masked_target_url(
            endpoint["baseUrl"], alias_owner or owner, repo,
            "git-receive-pack", query)
        parsed_target = urlparse(target)
        signed_path = parsed_target.path + (
            ("?" + parsed_target.query) if parsed_target.query else "")
        request_id = _b64url_encode(_random_bytes(18))
        issued_at = int(Date.now())
        message = https_routing.request_message(
            endpoint["node"],
            method,
            signed_path,
            body_digest,
            request_id,
            issued_at,
        )
        signature = await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if not target or not message or not signature:
            continue
        proxy_headers = {
            "X-ForkMesh-Node": endpoint["node"],
            "X-ForkMesh-Request-Id": request_id,
            "X-ForkMesh-Issued-At": str(issued_at),
            "X-ForkMesh-Body-Sha256": body_digest,
            "X-ForkMesh-Signature": signature,
        }
        if method == "POST":
            proxy_headers["Content-Type"] = (
                "application/x-git-receive-pack-request")
            if encoding:
                proxy_headers["Content-Encoding"] = encoding
        init = {
            "method": method,
            "headers": proxy_headers,
            "redirect": "manual",
        }
        if method == "POST":
            init["body"] = (
                body_stream if body_stream is not None
                else Uint8Array.new(_to_js(body)))
        try:
            upstream = await js_fetch_until_response(
                target, init,
                HTTPS_MIRROR_PUSH_RESPONSE_TIMEOUT_SECONDS
                if method == "POST"
                else HTTPS_MIRROR_GIT_INITIAL_RESPONSE_TIMEOUT_SECONDS)
            status = int(getattr(upstream, "status", 0) or 0)
        except Exception:
            status = 0
            upstream = None
        if (
            upstream is None
            or status in HTTPS_MIRROR_RETRY_STATUSES
            or 500 <= status <= 599
        ):
            continue
        if method == "POST" and status == 200:
            # A repository ForkMesh hosts has no node of its own to publish
            # the refs attestation a public read is routed against, so the
            # push that just moved its refs is where that pin is recorded —
            # from the hosting node's freshly signed proof, never from the
            # pusher's word (issue #676). Records published by a real node
            # are left alone, and a failure only delays the pin.
            try:
                await record_hosted_push_state(
                    env, owner, repo, endpoint, pusher=account)
            except Exception:
                pass
            state = ""
            core_push = core_held and str(
                endpoint.get("node") or "").strip().lower() in _core_push_nodes(
                    env)
            if core_push:
                try:
                    state = await _admit_core_push_state(
                        env, owner, repo, endpoint, alias=alias_owner)
                except Exception:
                    state = ""
            try:
                await record_accepted_push(
                    env, owner, repo, endpoint, account,
                    _ref_updates_from(upstream), core=core_push,
                    state=state, tag_moves=tag_moves,
                    credential=credential, contributor=bool(push_prefix))
            except Exception:
                pass
        return upstream, endpoint
    return None, None


def _cron_due_phases(minute_slot):
    """Return the exact bounded maintenance invocations due for one minute."""
    minute = int(minute_slot)
    phases = [
        "status-sample",
        "status-alert-pings",
        # One oldest lease per minute keeps the ten-minute signed-proof window
        # valid for a multi-mirror fleet even when a node misses its primary
        # four-minute renewal. Running one endpoint only every five minutes
        # made three healthy mirrors age out together after an ordinary sync.
        "mirror-health",
        "mail-log",
        "self-deploy-pings",
        "actions-schedule",
    ]
    # Preserve one-minute sampling and low-latency in-product Pings, but do not
    # wake provider/network work 1,440 times a day when its public freshness
    # contract is already measured in minutes. Stagger the two slow phases so
    # they never extend the same Durable Object event.
    if minute % 5 == 0:
        phases.append("status-alert-email")
    # The public bodies have multi-minute freshness envelopes. Stagger their
    # expensive builds while keeping sampling and in-product alerts on the
    # minute: status at residue 0, mirrors at residue 1, and a quiet slot at
    # residue 2. Catalog mutations additionally republish the mirror
    # roster and the slow projections below within seconds through the
    # snapshot-republish doorbell (schedule_public_catalog_republish); these
    # slots stay as the freshness floor for liveness drift the doorbell never
    # sees (endpoint health, behind counts, online history) and as the safety
    # net for a lost doorbell, so their cadence is unchanged.
    frequent_residue = minute % PUBLIC_SNAPSHOT_FREQUENT_CADENCE_MINUTES
    if frequent_residue == 0:
        phases.append("snapshot-status")
    elif frequent_residue == 1:
        phases.append("snapshot-mirrors")
    # Completed hour/day aggregation is absolute and idempotent. Refresh the
    # newest buckets throughout the documented five-minute late-arrival window,
    # then use minute 30 to backfill one older missing bucket if needed.
    if minute % 60 < 5 or minute % 60 == 30:
        phases.append("status-compact")
    phases.extend((
        "probe-flagship", "probe-release-platforms"))
    # Free-plan allowance sampler: one GraphQL read, threshold Pings.
    if minute % 10 == 6:
        phases.append("usage-budget")
    # Discord bug channel: one page read, then at most one report carried all
    # the way to a filed issue and a reply. Ten minutes is the deliberate
    # cadence — a reporter waits at most that long for an answer, and a burst
    # never competes with the per-minute status work for the phase budget.
    if minute % 10 == 4:
        phases.append("discord-bugs")
    # Slow anonymous projections are independently staggered every five
    # minutes so their catalog scans never need to share one Cron tick.
    slow_residue = minute % PUBLIC_SNAPSHOT_SLOW_CADENCE_MINUTES
    if slow_residue == 2:
        phases.append("snapshot-catalog")
    if slow_residue == 4:
        phases.extend(("snapshot-network", "ledger-backfill"))
    if minute % 10 == 0:
        phases.append("online-sample")
    if minute % 5 == 0:
        phases.append("ap-outbox")
    elif minute % 5 == 1:
        phases.extend((
            "reward-chain", "reward-contributions", "reward-sweeps",
            "direct-unread-email"))
    elif minute % 5 == 2:
        phases.append("federation")
    elif minute % 5 == 3:
        phases.extend((
            "notification-digest", "chat-digest", "channel-unread-email"))
    elif minute % 5 == 4:
        phases.append("webhook-outbox")
        phases.append("app-events")
        phases.append("provider-mirror")
    if minute % 10 == 8:
        phases.append("ap-digest")
    if minute % 20 == 12:
        phases.append("ap-profiles")
    if (
        minute % WORLD_SATELLITE_REFRESH_CRON_MINUTES
        == WORLD_SATELLITE_REFRESH_CRON_OFFSET
    ):
        phases.append("world-satellites")
    if minute % 15 == 4:
        phases.append("stale-nodes")
    elif minute % 15 == 9:
        phases.append("blocked-catalog")
    elif minute % 15 == 14:
        phases.append("central-fund")
    elif minute % 15 == 11:
        phases.append("instance-health")
    # Once per six hours, not hourly: the candidate anti-join walks every users
    # row (signup time lives inside the encrypted record, so SQL cannot narrow
    # it), and a "24h after signup" mail that lands 24-30h after signup instead
    # of 24-25h costs nothing.
    if minute % 360 == 22:
        phases.append("feedback-email")
    if minute % 10 == 9:
        phases.append("marketing-email")
    if minute % 5 == 3:
        phases.append("workflow-schedules")
    hourly = minute % 60
    if hourly == 7:
        phases.append("microjob-payouts")
    elif hourly == 17:
        phases.append("referrer-prune")
    elif hourly == 37:
        phases.append("chat-prune")
    elif hourly == 42:
        phases.append("org-succession")
    elif hourly == 47:
        phases.append("account-device-prune")
    elif hourly == 52:
        phases.extend((
            "sensitive-cleanup", "expire-rewards", "world-media-cleanup"))
    elif hourly == 27:
        # Bounce-rule flagging, 24h IP-digest purge and session retention.
        phases.append("attribution-maintenance")
    elif hourly == 57:
        phases.append("badge-sweep")
    elif hourly == 32:
        phases.append("instance-announce")
    # Once a day, copy the cumulative per-repository clone counters into a
    # dated snapshot; the acquisition dashboard reads per-day clones as the
    # delta between snapshots instead of touching the clone path itself.
    if minute % 1440 == 5:
        phases.append("attribution-clone-snapshot")
    if minute % 5 == 0:
        phases.append("probe-bans")
    return tuple(phases)


async def _run_cron_phase(env, phase, minute_slot):
    """Run exactly one maintenance slice inside its own DO invocation."""
    minute = int(minute_slot)
    if phase == "status-sample":
        return await record_status_sample(
            env, source="runner", allow_deep_probes=False,
            deliver_alerts=False, run_compaction=False)
    if phase == "status-compact":
        return await record_status_compaction(env)
    if phase == "status-alert-pings":
        # Both are bounded per-minute notification scans. Keeping reminders in
        # this phase avoids another Durable Object invocation every minute.
        # The finally keeps calendar delivery independent of an operational
        # status probe failure while preserving that failure for cron retry.
        try:
            return await record_status_alerts(env, delivery_channel="ping")
        finally:
            try:
                await deliver_calendar_reminders(env)
            finally:
                try:
                    await deliver_plugin_reminders(env)
                finally:
                    await deliver_task_persistent_reminders(env)
    if phase == "status-alert-email":
        return await record_status_alerts(env, delivery_channel="email")
    if phase == "snapshot-status":
        return await _publish_public_snapshot_group(
            env, public_snapshots.SNAPSHOT_STATUS_PATHS, int(Date.now()))
    if phase == "snapshot-mirrors":
        return await _publish_public_snapshot_group(
            env, ("/api/repo/forkmesh/forkmesh/mirrors",), int(Date.now()))
    if phase == "snapshot-catalog":
        return await _publish_public_snapshot_group(
            env, ("/api/repositories",), int(Date.now()))
    if phase == "snapshot-network":
        return await _publish_public_snapshot_group(
            env, ("/api/network/overview",), int(Date.now()))
    if phase == "ledger-backfill":
        return await ledger_backfill_cron(env)
    if phase == "mirror-health":
        return await https_mirror_health_cron(env)
    if phase == "probe-flagship":
        return await _flagship_repository_status(
            env, int(Date.now()), allow_probe=True, force_probe=True)
    if phase == "probe-release-platforms":
        return await _probe_release_platforms(env, int(Date.now()))
    if phase == "usage-budget":
        return await record_usage_budget_sample(env)
    if phase == "discord-bugs":
        return await watch_discord_bug_reports(env)
    if phase == "online-sample":
        return await record_online_sample(env)
    if phase == "world-satellites":
        return await refresh_world_satellite_snapshot(env, int(Date.now()))
    if phase == "reward-chain":
        return await verify_submitted_chain_intents(env)
    if phase == "reward-contributions":
        return await verify_submitted_reward_contributions(env)
    if phase == "reward-sweeps":
        return await sweep_pending_element_deposits(env)
    if phase == "ap-outbox":
        await ensure_schema(env)
        return await _ap_drain_outbox(env, AP_CRON_DELIVERIES)
    if phase == "webhook-outbox":
        await ensure_schema(env)
        return await drain_repo_webhook_outbox(
            env, REPO_WEBHOOK_CRON_DELIVERIES)
    if phase == "app-events":
        return await apps_drain_events(env, APPS_EVENT_CRON_DELIVERIES)
    if phase == "provider-mirror":
        await ensure_schema(env)
        return await provider_mirror_run_cron(
            env, PROVIDER_MIRROR_CRON_DELIVERIES)
    if phase == "self-deploy-pings":
        return await _deploy_approvals.announce(env)
    if phase == "mail-log":
        return await mail_log.drain(
            env, lambda channel_id, key_version, plain: _chat_channel_deliver(
                env, channel_id, key_version, plain))
    if phase == "ap-digest":
        await ensure_schema(env)
        return await _ap_process_digest_queues(env, AP_DIGEST_CRON_BATCH)
    if phase == "ap-profiles":
        await ensure_schema(env)
        return await _ap_refresh_follower_profiles(
            env, AP_PROFILE_REFRESH_BATCH,
            (minute // 20) % AP_PROFILE_REFRESH_WINDOWS)
    if phase == "federation":
        await ensure_schema(env)
        return await _federation_cron(env)
    if phase == "notification-digest":
        return await send_notification_digests(
            env, include_general_chat=False)
    if phase == "chat-digest":
        return await send_general_chat_digests(env)
    if phase == "channel-unread-email":
        return await send_channel_unread_reminders(env)
    if phase == "direct-unread-email":
        return await send_direct_unread_reminders(env)
    if phase == "stale-nodes":
        return await purge_stale_registered_nodes(env, force=True)
    if phase == "blocked-catalog":
        return await purge_blocked_catalog(env)
    if phase == "central-fund":
        await ensure_schema(env)
        return await _distribute_central_fund(env)
    if phase == "instance-health":
        return await _instance_directory_admin.health_cron(env)
    if phase == "instance-announce":
        return await _instance_console.announce_cron(env)
    if phase == "chat-prune":
        await chat_history_prune_expired(env)
        return await chat_direct_media_api.sweep(
            _ChatDirectMessagesRuntime(env))
    if phase == "account-device-prune":
        await ensure_schema(env)
        return await purge_stale_account_devices(env)
    if phase == "probe-bans":
        return await _probe_ban.sweep(env)
    if phase == "referrer-prune":
        # Both bounded referrer tables age out on the same sweep: the site
        # board's long tail, and the blog read-dedupe rows whose window has
        # long since closed.
        await prune_site_referrers(env)
        await prune_notification_email_sends(env)
        return await prune_blog_post_view_seen(env)
    if phase == "microjob-payouts":
        # Batch approved microjob claims into one public unsigned plan. The
        # owner's desktop client picks it up from the existing signing-jobs
        # queue, so a contributor is paid without anybody chasing an approval.
        return await queue_microjob_payouts(env)
    if phase == "org-succession":
        return await process_organization_succession_warnings(env)
    if phase == "sensitive-cleanup":
        return await cleanup_sensitive_audit_records(env)
    if phase == "expire-rewards":
        return await expire_pending_rewards(env)
    if phase == "world-media-cleanup":
        return await cleanup_world_media_records(env)
    if phase == "feedback-email":
        return await _send_feedback_emails(env)
    if phase == "marketing-email":
        return await send_marketing_emails(env)
    if phase == "watchdog-completion":
        return await _cron_watchdog_completion(env)
    if phase == "attribution-maintenance":
        return await _attribution.maintenance(env)
    if phase == "attribution-clone-snapshot":
        return await _attribution.snapshot_clone_counts(env)
    if phase == "badge-sweep":
        return await run_badge_sweep(env)
    if phase == "workflow-schedules":
        return await run_due_workflow_schedules(env)
    if phase == "actions-schedule":
        return await _actions_schedule_cron(env, minute)
    raise ValueError("unknown cron phase")


async def _actions_schedule_cron(env, minute_slot):
    if not str(getattr(env, "ACTIONS_INSTANCE_RUNNER", "") or "").strip():
        return 0
    await ensure_schema(env)
    import actions_cron
    import runner_leases
    runner_leases._bind_runtime(globals())
    return await actions_cron.run(
        runner_leases.WorkerRuntime(env, None), minute_slot)


def _cron_tick_phase_order(minute_slot):
    """Every phase this minute owes, dependency-ordered head first.

    The status chain leads, the independent phases follow in schedule order,
    and the completion heartbeat is last so it rides along in whichever
    invocation finishes the tick instead of costing one of its own.
    """
    due = tuple(_cron_due_phases(minute_slot))
    chain = tuple(phase for phase in CRON_STATUS_CHAIN if phase in due)
    independent = tuple(
        phase for phase in due if phase not in CRON_STATUS_CHAIN)
    return chain + independent + (CRON_WATCHDOG_PHASE,), len(chain)


def _cron_tick_detail(ran, failed, skipped):
    """One bounded JSON body describing a tick, small enough for the row."""
    detail = {
        "ran": {
            phase: value for phase, value in list(ran.items())[
                :CRON_BATCH_MAX_PHASES]
        },
        "failed": {
            phase: clean_string(str(value), 160)
            for phase, value in list(failed.items())[:CRON_BATCH_MAX_PHASES]
        },
        "skipped": sorted(skipped)[:CRON_BATCH_MAX_PHASES],
    }
    encoded = json.dumps(detail, separators=(",", ":"))
    if len(encoded) <= CRON_TICK_DETAIL_MAX_CHARS:
        return encoded
    # Names still answer "what ran this minute"; the measurements are the part
    # a pathological tick can make unbounded.
    return json.dumps({
        "ran": sorted(ran)[:CRON_BATCH_MAX_PHASES],
        "failed": sorted(failed)[:CRON_BATCH_MAX_PHASES],
        "skipped": sorted(skipped)[:CRON_BATCH_MAX_PHASES],
        "truncated": True,
    }, separators=(",", ":"))


async def _cron_tick_record(
        env, minute_slot, started_at, batches, ran, failed, skipped,
        subrequests):
    """Persist one bounded row for this tick without ever failing it.

    This row is the only account of the maintenance loop that outlives a
    Durable Object isolate: what ran, in how many alarm invocations, at what
    subrequest cost, and what did not. Losing it must never turn a healthy
    tick red, so every failure here is swallowed.
    """
    now = int(Date.now())
    try:
        await d1_run(
            env,
            "INSERT INTO cron_tick "
            "(slot, ts, batches, phases, failures, subrequests, ms, data) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(slot) DO UPDATE SET ts=excluded.ts, "
            "batches=excluded.batches, phases=excluded.phases, "
            "failures=excluded.failures, subrequests=excluded.subrequests, "
            "ms=excluded.ms, data=excluded.data",
            int(minute_slot), now, int(batches), len(ran), len(failed),
            int(subrequests), max(0, now - int(started_at)),
            _cron_tick_detail(ran, failed, skipped),
        )
        if int(minute_slot) % 30 == 0:
            await d1_run(
                env, "DELETE FROM cron_tick WHERE ts<?",
                now - CRON_TICK_RETAIN_MS)
    except BaseException:
        return


def _package_api_http_request(path):
    """True for the Marketplace package family: lifecycle plus package APIs.

    A package Worker API request carries a signed desktop proof, opens the
    signer's account record, gates the organization and the install, and only
    then reads its own rows. That fixed cost does not fit the stateless
    Pyodide allowance -- reading one record through a package API answered
    1102 on 2026-09-13 -- while the family is small enough (a few hundred
    requests a week) to own one ingress object outright. The prefixes come
    from the generated registry, so core source still names no package.
    """
    normalized = str(path or "").rstrip("/") or "/"
    if normalized == "/api/plugins" or normalized.startswith("/api/plugins/"):
        return True
    try:
        prefixes = plugin_api_prefixes()
    except BaseException:
        return False
    for prefix in prefixes:
        if prefix and (normalized == prefix
                       or normalized.startswith(prefix + "/")):
            return True
    return False


def _app_ingress_shard(request):
    """One of sixteen fixed ingress objects; never mint attacker-keyed IDs."""
    try:
        path = str(JsURL.new(str(request.url)).pathname or "")
    except BaseException:
        path = ""
    if _git_clone_http_request(request, path):
        # Keep both requests in one Smart HTTP clone on the same object, but
        # spread unrelated repositories across sixteen fixed objects.  The
        # bounded, eager hash avoids importing the lazy URL routing table in
        # the stateless dispatcher and never creates attacker-named objects.
        parts = path.split("/", 3)
        repository_path = "/".join(parts[:3])
        value = 0
        for character in repository_path[:256]:
            value = ((value * 33) ^ ord(character)) & 15
        return "0123456789abcdef"[value]
    # The stateless Python request has a much smaller CPU allowance than an
    # ingress object. Keep each known hot family on a stable object so its
    # signature/catalog work cannot exhaust and poison the outer isolate.
    stable = {
        "/api/ledger": "a",
        "/api/mainnode": "b",
        "/api/sync": "c",
        # Mirror bundle reads and private task projection both have bounded
        # but non-trivial D1/serialization work. Give each one fixed ingress
        # ownership so a burst cannot fan out across all sixteen Python
        # isolates or contaminate chat/account traffic after one CPU abort.
        "/api/mirror-replica": "2",
        "/api/tasks": "3",
        "/api/status": "e",
        "/api/status/world": "e",
        # These live projections and signed desktop routes were the remaining
        # sources of stateless CPU-limit failures. Keep each traffic family on
        # its own bounded object: a slow catalog read must not poison account,
        # chat, or error-report work in the same Python isolate.
        "/api/repositories": "f",
        "/api/chat/activity": "7",
        "/api/chat/channels": "7",
        "/api/desktop-errors": "8",
        "/api/network/stats": "9",
    }.get(path.rstrip("/") or "/")
    normalized = path.rstrip("/") or "/"
    if normalized == "/api/tasks" or normalized.startswith("/api/tasks/"):
        stable = "3"
    if normalized == "/signup" or normalized.startswith("/api/accounts/"):
        stable = "6"
    # A dashboard refresh reads every selected Discord channel. Each read
    # performs policy checks plus provider calls through ForkMeshDiscordGate;
    # letting those outer requests enter the stateless Pyodide isolate
    # together produced the 1102/"request hung" cascade recorded on
    # 2026-09-01. Keep the whole bounded connector family on one ingress
    # object. The provider gate remains the authority for Discord rate limits.
    if re.fullmatch(
            r"/api/orgs/[^/]+/discord(?:/(?:messages|oauth/start))?/?",
            path):
        stable = "4"
    if _repository_projection_http_request(request, path):
        stable = "5"
    if re.fullmatch(
            r"/api/chat/(?:channels|direct-messages)/[0-9a-f]{32}/"
            r"room-access/?", path):
        stable = "d"
    # The founder-only product dashboard builds one report per rendered view:
    # it drains the users and repositories tables and AES-GCM decrypts every
    # row. That is a full plaintext megabyte today, mostly avatar images
    # carried inside the account records, and it does not fit the stateless
    # 10 ms allowance -- GET /product-analysis?view=users answered 503/1102 at
    # 462 ms CPU on 2026-09-10, and the other report views failed
    # intermittently beside it. It is also the only surface that needs that
    # much CPU, so give it a private ingress object: the report gets the
    # Durable Object budget, and a slow load can never poison account, chat or
    # clone work sharing an isolate.
    if (normalized == PRODUCT_ANALYSIS_PATH
            or normalized.startswith(PRODUCT_ANALYSIS_PATH + "/")):
        stable = "1"
    # Installs, uninstall exports, and every package-owned API read share the
    # last unassigned object; only mirror requests carrying no usable cf-ray
    # land there as well. Package code is the one family the core does not
    # own, so keeping it off every other family's isolate also keeps a slow
    # package away from accounts, chat, and clones.
    if _package_api_http_request(normalized):
        stable = "0"
    if stable:
        return stable
    try:
        value = str(request.headers.get("cf-ray") or "").lower()
    except BaseException:
        value = ""
    shard = value[:1]
    return (
        shard
        if len(shard) == 1 and shard in "0123456789abcdef"
        else "0"
    )


async def _app_ingress_request(env, request, purpose="v1"):
    """Run bounded App work in one of the fixed existing DO objects."""
    prefix = (
        APP_GIT_INGRESS_NAME_PREFIX
        if purpose == APP_INGRESS_GIT_READ_PURPOSE
        else APP_INGRESS_NAME_PREFIX
    )
    object_id = env.FORKMESH_CRON_RUNNER.idFromName(
        prefix + _app_ingress_shard(request))
    ingress = env.FORKMESH_CRON_RUNNER.get(object_id)
    # Python Workers wraps the inbound JS Request. Clone its native object so
    # every header, conditional, Cookie, Upgrade, and streaming body crosses
    # the DO boundary without buffering it through Python/WASM.
    forwarded = JsRequest.new(
        getattr(request, "js_object", request))
    forwarded.headers.set(
        "x-forkmesh-internal-ingress", str(purpose or ""))
    return await ingress.fetch(forwarded)


async def _app_ingress_authorization(env, request, purpose, log_path):
    """Bound an idempotent node/socket authorization hop during DO resets."""
    last_error = None
    for _attempt in range(2):
        try:
            return await _app_ingress_request(env, request, purpose)
        except BaseException as error:
            last_error = error
    await log_durable_object_abort(env, request, log_path, last_error)
    return json_response(
        {"error": "authorization_unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS,
    )


def _mirror_node_http_request(request):
    """Keep bursty mirror synchronization out of the stateless Pyodide loop."""
    try:
        user_agent = str(request.headers.get("user-agent") or "")
    except BaseException:
        user_agent = ""
    return user_agent.startswith("ForkMesh-Mirror-")


def _repository_projection_http_request(request, path=None):
    """Identify bursty repository metadata reads that need ingress CPU."""
    if method_name(request) not in ("GET", "HEAD"):
        return False
    if path is None:
        try:
            path = str(JsURL.new(str(request.url)).pathname or "")
        except BaseException:
            return False
    normalized = str(path or "").rstrip("/") or "/"
    return bool(
        normalized == "/api/repository-forks"
        or re.fullmatch(
            r"/api/repo/[^/]+/[^/]+/"
            r"(?:issues|pulls|discussions|pending|logo|raw|star|forks|about"
            # The desktop mirror panel (adhoc #2150): on an edge-cache miss
            # this projection decrypts the catalog memo, reads endpoint,
            # integrity, first-hosted, org-link, state-history and serve
            # counter rows and assembles the payload — far past the 10 ms
            # stateless Free-plan envelope, which surfaced as a 1101.
            r"|mirrors|mirrors/[^/]+/reachability)",
            normalized,
        )
    )


def _git_clone_http_request(request, path=None):
    """Recognize public Smart HTTP reads without loading the route module."""
    try:
        target = JsURL.new(str(request.url))
        if path is None:
            path = str(target.pathname or "")
        search = str(target.search or "")
    except BaseException:
        return False
    method = method_name(request)
    if re.fullmatch(r"/[^/]+/[^/]+/git-upload-pack", str(path or "")):
        return method == "POST"
    return bool(
        method in ("GET", "HEAD")
        and search == "?service=git-upload-pack"
        and re.fullmatch(r"/[^/]+/[^/]+/info/refs", str(path or ""))
    )


def _serialized_http_request(request):
    """True for public dynamic reads whose bursts can re-enter Pyodide."""
    try:
        target = JsURL.new(str(request.url))
        path = str(target.pathname or "")
        has_query = bool(str(target.search or ""))
    except BaseException:
        return False
    normalized = path.rstrip("/") or "/"
    return bool(
        normalized in {
            "/api/ledger", "/api/mainnode", "/api/sync",
            "/api/mirror-replica", "/api/tasks",
            "/api/status", "/api/status/world",
            "/api/chat/activity", "/api/chat/channels",
            "/api/desktop-errors", "/api/network/stats",
        }
        # Login/signup/session bursts perform password, cookie and D1 work.
        # Keeping the whole bounded account family on one ingress shard avoids
        # re-entering the outer 10 ms Pyodide isolate during a page load.
        or normalized == "/api/tasks"
        or normalized.startswith("/api/tasks/")
        or normalized == "/signup"
        or normalized.startswith("/api/accounts/")
        # Selected-channel refreshes fan out from one browser action. Serialize
        # their outer policy/crypto work as well as their inner provider calls,
        # or concurrent Worker isolates can exhaust Pyodide before the Discord
        # rate gate has a chance to coordinate them.
        or re.fullmatch(
            r"/api/orgs/[^/]+/discord(?:/(?:messages|oauth/start))?/?",
            path)
        # Query-free anonymous catalog reads are D1 snapshots and repository
        # writes must not cross a replay boundary. Only the signed/viewer GET
        # projection that performs live private-catalog work needs the larger
        # ingress CPU envelope.
        or (
            normalized == "/api/repositories"
            and method_name(request) in ("GET", "HEAD")
            and has_query
        )
        # The desktop opens these private projections together. Running their
        # signature and D1 work directly produced a three-request 1102 burst,
        # then poisoned unrelated requests waiting on healthy ingress objects.
        or _repository_projection_http_request(request, path)
        or re.fullmatch(
            r"/api/chat/(?:channels|direct-messages)/[0-9a-f]{32}/"
            r"room-access/?", path)
        # Every /product-analysis method needs the ingress envelope, not just
        # the report views: the login POST hashes and compares credentials and
        # the theme POST re-signs the session cookie. Serializing the whole
        # route keeps its shard the only place that pays for it.
        or normalized == PRODUCT_ANALYSIS_PATH
        or normalized.startswith(PRODUCT_ANALYSIS_PATH + "/")
        # Package lifecycle and package Worker APIs: signed desktop proofs,
        # organization gating, and a plugin's own schema replay, none of which
        # fits the stateless allowance.
        or _package_api_http_request(normalized)
    )


async def _app_ingress_fetch(env, request):
    """Run ordinary HTTP in the stateless Worker request that received it.

    Routing every request through a Durable Object made the whole HTTP API
    depend on the account-wide Free-plan duration allowance. Once that shared
    allowance was exhausted, all sixteen ingress shards immediately rejected
    every request and the otherwise healthy origin returned only 503. HTTP
    request events already have their own bounded Worker execution context;
    keep Durable Objects for the stateful coordinators and hibernating sockets
    that actually require them.

    Repository writes remain direct so streamed Git bodies never cross a
    replay boundary. The explicitly serialized account writes cross ingress
    exactly once and fail closed there; they are never replayed or retried in
    the outer Worker.
    """
    git_clone = _git_clone_http_request(request)
    serialized = _serialized_http_request(request)
    if _mirror_node_http_request(request) or serialized or git_clone:
        try:
            return await _app_ingress_request(
                env, request,
                APP_INGRESS_GIT_READ_PURPOSE
                if git_clone else APP_INGRESS_HTTP_PURPOSE)
        except BaseException:
            # When the account-wide DO allowance is unavailable, fail this
            # background synchronization request closed and let the node's
            # normal retry/backoff recover it. Running a burst of signature
            # and catalog work directly can exhaust the stateless Python CPU
            # budget and poison unrelated /status and browser requests with
            # Pyodide NoGil errors.
            # Cloudflare's tail record does not include response headers, so
            # give the desktop monitor a privacy-safe marker that distinguishes
            # this deliberate backpressure response from an unhandled 503.
            print("forkmesh_expected_degraded_response")
            return json_response(
                {"error": (
                    "mirror_sync_temporarily_unavailable"
                    if _mirror_node_http_request(request) else
                    "git_temporarily_unavailable"
                    if git_clone else "service_temporarily_unavailable"
                )},
                status=503,
                extra_headers={
                    "retry-after": "30",
                    **EXPECTED_DEGRADED_HEADERS,
                },
            )
    return await AppRuntime._fetch_inner(_AppIngressRouter(env), request)


async def _node_events_direct_fetch(env, request):
    """Authorize in a short DO call, then hand 101 to the final hibernating DO."""
    authorized = await _app_ingress_authorization(
        env, request, APP_INGRESS_NODE_AUTH_PURPOSE,
        "/api/nodes/events/authorization")
    if int(getattr(authorized, "status", 500) or 500) != 204:
        return authorized
    object_name = str(
        authorized.headers.get("x-forkmesh-authorized-object") or "")
    if not object_name:
        owner = safe_segment(
            authorized.headers.get("x-forkmesh-authorized-owner") or "")
        object_name = _node_events_do_name(owner) if owner else ""
    if not NODE_EVENTS_OBJECT_RE.fullmatch(object_name):
        return json_response(
            {"error": "authorization_unavailable"}, status=503,
            extra_headers=EXPECTED_DEGRADED_HEADERS,
        )
    node_id = env.FORKMESH_NODES.idFromName(object_name)
    last_error = None
    for _attempt in range(2):
        try:
            # Preserve the established node tunnel boundary: only the
            # explicit handshake/control allowlist crosses into the owner DO,
            # never Cookie, Origin, CF metadata, or arbitrary client headers.
            forwarded = await durable_object_request(request)
            return await env.FORKMESH_NODES.get(node_id).fetch(forwarded)
        except Exception as error:
            last_error = error
    await log_durable_object_abort(
        env, request, "/api/nodes/events", last_error)
    return json_response(
        {"error": "unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS,
    )


_WEBSOCKET_HANDOFF_BINDINGS = frozenset({
    "FORKMESH_MAINNODE_ROOM",
    "FORKMESH_WORLD",
    "FORKMESH_OFFICE_ROOM",
    "FORKMESH_NOTE_ROOM",
    "FORKMESH_ORG_OFFICE",
})
_WEBSOCKET_HANDOFF_HEADERS = (
    "upgrade",
    "connection",
    "sec-websocket-version",
    "sec-websocket-key",
    "sec-websocket-protocol",
    "x-forkmesh-country",
    "x-forkmesh-world-claim",
    "x-forkmesh-world-ip-token",
    "x-forkmesh-world-agent-token",
    "x-forkmesh-world-private-ip",
    "x-forkmesh-world-private-agent",
    "x-forkmesh-office-claim",
    "x-forkmesh-org-office-claim",
)
_WEBSOCKET_HANDOFF_HEADERS_BY_BINDING = {
    "FORKMESH_MAINNODE_ROOM": _WEBSOCKET_HANDOFF_HEADERS[:5],
    "FORKMESH_NOTE_ROOM": _WEBSOCKET_HANDOFF_HEADERS[:5],
    "FORKMESH_WORLD": (
        *_WEBSOCKET_HANDOFF_HEADERS[:5],
        "x-forkmesh-country",
        "x-forkmesh-world-claim",
        "x-forkmesh-world-ip-token",
        "x-forkmesh-world-agent-token",
        "x-forkmesh-world-private-ip",
        "x-forkmesh-world-private-agent",
    ),
    "FORKMESH_OFFICE_ROOM": (
        *_WEBSOCKET_HANDOFF_HEADERS[:5],
        "x-forkmesh-office-claim",
    ),
    "FORKMESH_ORG_OFFICE": (
        *_WEBSOCKET_HANDOFF_HEADERS[:4],
        "x-forkmesh-org-office-claim",
    ),
}
_WEBSOCKET_HANDOFF_PREFIX = "x-forkmesh-handoff-header-"


def _public_websocket_path(path):
    """Whether a public Upgrade path can legitimately produce a 101."""
    value = str(path or "")
    return bool(
        value in (
            "/api/status/ws", "/api/status/ws/",
            "/api/world/ws", "/api/world/ws/",
            "/api/world/office/general/ws",
            "/api/world/office/general/ws/",
            "/api/office/ws",
        )
        or OFFICE_CHANNEL_WS_RE.fullmatch(value)
        or CHAT_CHANNEL_WS_RE.fullmatch(value)
        or CHAT_DIRECT_MESSAGE_WS_RE.fullmatch(value)
        or re.fullmatch(r"/api/notes/[0-9a-f]{32}/ws/?", value)
        or (
            (REPO_ROOM_RE.fullmatch(value) or ROOM_RE.fullmatch(value))
            and value.endswith("/ws")
        )
    )


def _websocket_handoff_response(binding_name, object_name, forwarded):
    """Describe one already-authorized final DO request without opening it."""
    binding = str(binding_name or "")
    object_value = str(object_name or "")
    target_url = str(getattr(forwarded, "url", "") or "")
    # Organization aliases are authorized against a canonical backing owner,
    # while the established Request object still carries the public alias URL.
    # Make the captured room target canonical as well so the final object's
    # name, retained-history key, and request path cannot disagree.
    if binding == "FORKMESH_MAINNODE_ROOM" and target_url:
        try:
            target_parts = urlparse(target_url)
            public_room = REPO_ROOM_RE.fullmatch(target_parts.path)
            if public_room and target_parts.path.endswith("/ws"):
                repo = safe_segment(public_room.group(2))
                room = safe_segment(public_room.group(3), MAX_ROOM_NAME)
                tail = "/" + str(repo or "") + ":room:" + str(room or "")
                canonical_owner = (
                    object_value[len("repo:"):-len(tail)]
                    if repo and room and object_value.startswith("repo:")
                    and object_value.endswith(tail)
                    else ""
                )
                canonical_owner = safe_segment(canonical_owner)
                if not canonical_owner:
                    raise ValueError("invalid canonical room")
                target_url = target_parts._replace(path=(
                    "/api/repo/" + quote(canonical_owner, safe="")
                    + "/" + quote(repo, safe="") + "/rooms/"
                    + quote(room, safe="") + "/ws"
                )).geturl()
        except BaseException:
            target_url = ""
    if (
        binding not in _WEBSOCKET_HANDOFF_BINDINGS
        or not object_value
        or len(object_value) > 300
        or not re.fullmatch(r"[A-Za-z0-9:./_-]+", object_value)
        or not target_url
        or len(target_url) > 4096
    ):
        return json_response(
            {"error": "websocket_handoff_invalid"}, status=503,
            extra_headers=EXPECTED_DEGRADED_HEADERS,
        )
    headers = {
        "cache-control": "no-store",
        "x-forkmesh-websocket-handoff": "v1",
        "x-forkmesh-handoff-binding": binding,
        "x-forkmesh-handoff-object": object_value,
        "x-forkmesh-handoff-url": target_url,
    }
    for name in _WEBSOCKET_HANDOFF_HEADERS_BY_BINDING[binding]:
        try:
            value = str(forwarded.headers.get(name) or "")
        except BaseException:
            value = ""
        if value and len(value) <= 2048:
            headers[_WEBSOCKET_HANDOFF_PREFIX + name] = value
    return Response(None, status=204, headers=headers)


class _WebSocketHandoffStub:
    def __init__(self, binding_name, object_name):
        self.binding_name = binding_name
        self.object_name = object_name

    async def fetch(self, request):
        return _websocket_handoff_response(
            self.binding_name, self.object_name, request)


class _WebSocketHandoffNamespace:
    def __init__(self, binding_name):
        self.binding_name = binding_name

    @staticmethod
    def idFromName(name):
        return str(name or "")

    def get(self, object_id):
        return _WebSocketHandoffStub(
            self.binding_name, str(object_id or ""))


class _WebSocketHandoffEnv:
    """Delegate every binding except the four possible final socket DOs."""

    def __init__(self, env):
        self._env = env

    def __getattr__(self, name):
        if name in _WEBSOCKET_HANDOFF_BINDINGS:
            return _WebSocketHandoffNamespace(name)
        return getattr(self._env, name)


async def _websocket_handoff_authorization(env, request):
    """Run the existing route authorization but capture its final DO fetch."""
    try:
        parsed = urlparse(request.url)
    except BaseException:
        return json_response({"error": "not_found"}, status=404)
    if (
        method_name(request) != "GET"
        or str(request.headers.get("upgrade") or "").lower() != "websocket"
        or not _public_websocket_path(parsed.path)
    ):
        return json_response({"error": "not_found"}, status=404)
    try:
        router = _AppIngressRouter(_WebSocketHandoffEnv(env))
        return await AppRuntime._route(router, request, parsed)
    except BaseException:
        return json_response(
            {"error": "websocket_authorization_unavailable"}, status=503,
            extra_headers=EXPECTED_DEGRADED_HEADERS,
        )


def _validated_websocket_handoff(env, request, response):
    """Return a strictly allowlisted final descriptor, else None."""
    try:
        if (
            int(getattr(response, "status", 0) or 0) != 204
            or str(response.headers.get(
                "x-forkmesh-websocket-handoff") or "") != "v1"
        ):
            return None
        binding_name = str(response.headers.get(
            "x-forkmesh-handoff-binding") or "")
        object_name = str(response.headers.get(
            "x-forkmesh-handoff-object") or "")
        target_url = str(response.headers.get(
            "x-forkmesh-handoff-url") or "")
        if (
            binding_name not in _WEBSOCKET_HANDOFF_BINDINGS
            or len(object_name) > 300
            or not re.fullmatch(r"[A-Za-z0-9:./_-]+", object_name)
            or len(target_url) > 4096
        ):
            return None
        target = urlparse(target_url)
        source = urlparse(request.url)
        if (
            target.scheme not in ("http", "https")
            or target.fragment
            or not target.hostname
            or not (
                target.netloc == source.netloc
                or (
                    target.scheme == "https"
                    and target.netloc == "forkmesh.internal"
                )
            )
        ):
            return None

        query = parse_qs(target.query, keep_blank_values=False)
        source_path = source.path
        source_office_channel = OFFICE_CHANNEL_WS_RE.fullmatch(source_path)
        source_chat_channel = CHAT_CHANNEL_WS_RE.fullmatch(source_path)
        source_chat_direct = CHAT_DIRECT_MESSAGE_WS_RE.fullmatch(source_path)
        source_note = re.fullmatch(
            r"/api/notes/([0-9a-f]{32})/ws/?", source_path)
        source_repo_room = REPO_ROOM_RE.fullmatch(source_path)
        source_compat_room = ROOM_RE.fullmatch(source_path)

        # Bind the descriptor to the exact public route that was authorized.
        # Shape validation alone is insufficient: a corrupt or confused
        # ingress response for World must never hand the socket to a valid
        # Note or private-chat object.
        if source_path in ("/api/status/ws", "/api/status/ws/"):
            valid_target = bool(
                binding_name == "FORKMESH_WORLD"
                and object_name == "town-square-v1"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target.path in ("/api/status/ws", "/api/status/ws/")
                and not query
            )
        elif source_path in ("/api/world/ws", "/api/world/ws/"):
            valid_target = bool(
                binding_name == "FORKMESH_WORLD"
                and object_name == "town-square-v1"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target.path in ("/api/world/ws", "/api/world/ws/")
                and not query
            )
        elif source_path in (
                "/api/world/office/general/ws",
                "/api/world/office/general/ws/"):
            valid_target = bool(
                binding_name == "FORKMESH_OFFICE_ROOM"
                and object_name == "office:world-general:v1"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target.path
                    == "/api/world/office/world-general/v1/ws"
                and not query
            )
        elif source_path == "/api/office/ws":
            org_object = re.fullmatch(
                r"office:org:([0-9a-f]{64}):v1", object_name)
            valid_target = bool(
                binding_name == "FORKMESH_ORG_OFFICE"
                and org_object
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target.path == "/api/office/org/"
                    + org_object.group(1) + "/v1/ws"
                and not query
            )
        elif source_office_channel:
            channel_id = source_office_channel.group(1)
            channel_object = re.fullmatch(
                r"office:chat-channel:" + channel_id
                + r":v([1-9][0-9]*)",
                object_name,
            )
            channel_path = re.fullmatch(
                r"/api/world/office/" + channel_id
                + r"/v([1-9][0-9]*)/ws",
                target.path,
            )
            valid_target = bool(
                binding_name == "FORKMESH_OFFICE_ROOM"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and not query
                and channel_object
                and channel_path
                and channel_object.group(1) == channel_path.group(1)
            )
        elif source_chat_channel or source_chat_direct:
            opaque_id = (
                source_chat_channel.group(1)
                if source_chat_channel else source_chat_direct.group(1)
            )
            family = "channels" if source_chat_channel else "direct-messages"
            object_prefix = (
                "chat-channel:" if source_chat_channel else "chat-direct:"
            )
            target_path = re.fullmatch(
                r"/api/chat/" + family + "/" + opaque_id
                + r"/v([1-9][0-9]*)/ws",
                target.path,
            )
            target_object = re.fullmatch(
                re.escape(object_prefix + opaque_id) + r":v([1-9][0-9]*)",
                object_name,
            )
            accounts = query.get("account") or []
            valid_target = bool(
                binding_name == "FORKMESH_MAINNODE_ROOM"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target_path
                and target_object
                and target_path.group(1) == target_object.group(1)
                and len(accounts) == 1
                and re.fullmatch(r"[0-9a-f]{64}", accounts[0])
                and set(query) == {"account"}
            )
        elif source_note:
            roles = query.get("role") or []
            actors = query.get("actor") or []
            actor = actors[0] if len(actors) == 1 else ""
            valid_target = bool(
                binding_name == "FORKMESH_NOTE_ROOM"
                and target.scheme == "https"
                and target.netloc == "forkmesh.internal"
                and target.path
                    == "/api/notes/" + source_note.group(1) + "/ws"
                and object_name == "note:" + source_note.group(1)
                and len(roles) == 1
                and roles[0] in ("owner", "editor", "viewer")
                and actor
                and clean_string(actor, MAX_NODE_NAME) == actor
                and not any(
                    ord(character) < 32 or ord(character) == 127
                    for character in actor
                )
                and set(query) == {"role", "actor"}
            )
        elif source_repo_room:
            source_repo = safe_segment(source_repo_room.group(2))
            source_room = safe_segment(
                source_repo_room.group(3), MAX_ROOM_NAME)
            canonical_path = REPO_ROOM_RE.fullmatch(target.path)
            canonical_owner = (
                safe_segment(canonical_path.group(1))
                if canonical_path else ""
            )
            canonical_repo = (
                safe_segment(canonical_path.group(2))
                if canonical_path else ""
            )
            canonical_room = (
                safe_segment(canonical_path.group(3), MAX_ROOM_NAME)
                if canonical_path else ""
            )
            valid_target = bool(
                binding_name == "FORKMESH_MAINNODE_ROOM"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target.query == source.query
                and target.path.endswith("/ws")
                and source_repo
                and source_room
                and canonical_owner
                and canonical_repo == source_repo
                and canonical_room == source_room
                and object_name == (
                    "repo:" + canonical_owner + "/" + canonical_repo
                    + ":room:" + canonical_room
                )
            )
        elif source_compat_room:
            room = room_key_from_path(source_path)
            valid_target = bool(
                binding_name == "FORKMESH_MAINNODE_ROOM"
                and target.scheme == source.scheme
                and target.netloc == source.netloc
                and target.path == source_path
                and target.query == source.query
                and room
                and room.get("key") == object_name
            )
        else:
            valid_target = False
        if not valid_target:
            return None

        final_headers = {}
        for name in _WEBSOCKET_HANDOFF_HEADERS_BY_BINDING[binding_name]:
            value = str(response.headers.get(
                _WEBSOCKET_HANDOFF_PREFIX + name) or "")
            if value:
                if len(value) > 2048:
                    return None
                final_headers[name] = value
        if str(final_headers.get("upgrade") or "").lower() != "websocket":
            return None
        trusted_names = {
            name for name in final_headers
            if name.startswith("x-forkmesh-")
        }
        if binding_name == "FORKMESH_WORLD":
            if "x-forkmesh-office-claim" in trusted_names:
                return None
        elif binding_name == "FORKMESH_OFFICE_ROOM":
            if (
                "x-forkmesh-office-claim" not in trusted_names
                or any(
                    name.startswith("x-forkmesh-world-")
                    for name in trusted_names
                )
            ):
                return None
        elif binding_name == "FORKMESH_ORG_OFFICE":
            if trusted_names != {"x-forkmesh-org-office-claim"}:
                return None
        elif trusted_names:
            return None
        return binding_name, object_name, target_url, final_headers
    except BaseException:
        return None


async def _websocket_direct_fetch(env, request):
    """Authorize in ingress, then connect directly to the final socket DO."""
    authorized = await _app_ingress_authorization(
        env, request, APP_INGRESS_WEBSOCKET_AUTH_PURPOSE,
        "/websocket-authorization")
    status = int(getattr(authorized, "status", 500) or 500)
    if status != 204:
        return authorized
    descriptor = _validated_websocket_handoff(
        env, request, authorized)
    if descriptor is None:
        return json_response(
            {"error": "websocket_handoff_invalid"}, status=503,
            extra_headers=EXPECTED_DEGRADED_HEADERS,
        )
    binding_name, object_name, target_url, headers = descriptor
    binding = getattr(env, binding_name)
    object_id = binding.idFromName(object_name)
    last_error = None
    for _attempt in range(2):
        try:
            forwarded = JsRequest.new(
                target_url,
                to_js({"method": "GET", "headers": headers}),
            )
            return await binding.get(object_id).fetch(forwarded)
        except Exception as error:
            last_error = error
    try:
        path = urlparse(request.url).path
    except BaseException:
        path = "/"
    await log_durable_object_abort(env, request, path, last_error)
    return json_response(
        {"error": "unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS,
    )


# Cloudflare executes global imports while creating the Python deployment
# snapshot. Keep the core dispatcher there: importing it on the first request
# can overrun that request's CPU slice, abort the Pyodide task, and leave the
# isolate rejecting unrelated follow-up requests. Optional route domains used
# by AppRuntime remain behind their own _LazyModule boundaries above.
import app_runtime as _app_runtime_module
_app_runtime_module._bind_runtime(globals())
AppRuntime = _app_runtime_module.Default


class Default(WorkerEntrypoint):
    """Supported Python Worker entrypoint with request-local route state.

    Global handlers invoke the deprecated Python bridge concurrently.  The
    bridge can reuse a PyProxy after its GIL scope has ended, causing a
    ``NoGilError`` before the route gets a chance to answer.  Keep the runtime
    entrypoint object deliberately thin, and create the existing route
    receiver for each event so request-local ``env``/``ctx`` state never leaks
    between invocations.
    """

    def _runtime(self):
        worker = AppRuntime()
        worker.env = self.env
        return worker

    async def fetch(self, request):
        return await self._runtime().fetch(request)

    async def scheduled(self, controller, env, ctx):
        return await self._runtime().scheduled(controller, env, ctx)

    async def queue(self, batch, env, ctx):
        return await self._runtime().queue(batch, env, ctx)


async def chat_history_recent(env, room_key):
    # A bounded tail of retained (encrypted) messages for a joining room,
    # oldest first. Do not read/replay the full 16 MiB retention allowance
    # before returning a WebSocket 101: that made busy-room handshakes exceed
    # the Durable Object request-duration limit and drove reconnect storms.
    await ensure_schema(env)
    cutoff = int(Date.now()) - CHAT_HISTORY_RETAIN_MS
    # The innermost SELECT stops at the message ceiling through the
    # (room_key, ts) index, so the window functions run over at most
    # CHAT_HISTORY_REPLAY_MAX_MESSAGES rows instead of the whole retained
    # room (~400-1000 rows per join on the busy rooms).
    rows = await d1_all(
        env,
        "SELECT body FROM ("
        "SELECT body,ts,msg_id,"
        "ROW_NUMBER() OVER (ORDER BY ts DESC,msg_id DESC) AS replay_position,"
        "SUM(length(body)) OVER (ORDER BY ts DESC,msg_id DESC) AS replay_bytes "
        "FROM (SELECT body,ts,msg_id FROM chat_history "
        "WHERE room_key=? AND ts>=? AND acked_at=0 "
        "ORDER BY ts DESC,msg_id DESC LIMIT ?)"
        ") WHERE replay_position<=? AND replay_bytes<=? "
        "ORDER BY ts ASC,msg_id ASC",
        room_key, cutoff,
        CHAT_HISTORY_REPLAY_MAX_MESSAGES,
        CHAT_HISTORY_REPLAY_MAX_MESSAGES,
        CHAT_HISTORY_REPLAY_MAX_BYTES,
    )
    return [str(r["body"]) for r in rows]


def chat_history_replay_body(body):
    """Mark a stored cipher as backlog without changing its encrypted payload."""
    source = str(body)
    try:
        envelope = json.loads(source)
    except (TypeError, ValueError):
        return source
    if not isinstance(envelope, dict) or envelope.get("kind") != "cipher":
        return source
    replay = dict(envelope)
    replay["historyReplay"] = True
    return json.dumps(replay, separators=(",", ":"))


async def chat_room_audience(env, channel_id, direct_id, sender_bi,
                             live_accounts):
    if direct_id:
        rows = await d1_all(
            env,
            "SELECT participant_bi FROM chat_direct_participants "
            "WHERE conversation_id=?",
            direct_id,
        )
        audience = {
            str(row.get("participant_bi") or "") for row in rows or []
        }
    elif channel_id:
        channel = await d1_first(
            env,
            "SELECT data,created_by_bi FROM chat_channels WHERE channel_id=?",
            channel_id,
        )
        if not channel:
            return None
        record = await decrypt_row(env, channel.get("data"))
        if not isinstance(record, dict):
            return None
        creator = str(channel.get("created_by_bi") or "")
        if record.get("kind") == "notices":
            audience = {creator}
        elif record.get("visibility") == "public":
            audience = {str(account or "") for account in live_accounts}
        else:
            members = await d1_all(
                env,
                "SELECT member_bi FROM chat_channel_members "
                "WHERE channel_id=?",
                channel_id,
            )
            audience = {creator} | {
                str(member.get("member_bi") or "")
                for member in members or []
            }
    else:
        return None
    audience.discard("")
    audience.discard(str(sender_bi or ""))
    return audience


_CHAT_RECIPIENT_NAMES = {}


async def chat_recipient_names(env, audience):
    names = []
    for account_bi in sorted(audience)[:CHAT_RECIPIENT_NAMES_MAX]:
        name = _CHAT_RECIPIENT_NAMES.get(account_bi)
        if name is None:
            try:
                rec = await _account_identity_rec_by_bi(env, account_bi)
            except Exception:
                rec = None
            name = str((rec or {}).get("name") or "").strip().lower()
            if not name:
                continue
            if len(_CHAT_RECIPIENT_NAMES) < CHAT_RECIPIENT_NAME_CACHE_MAX:
                _CHAT_RECIPIENT_NAMES[account_bi] = name
        names.append(name)
    return sorted(set(names))


async def chat_room_recipients(env, channel_id, direct_id, sender_bi,
                               live_accounts):
    audience = await chat_room_audience(
        env, channel_id, direct_id, sender_bi, live_accounts)
    if audience is None:
        return None
    return len(audience), await chat_recipient_names(env, audience)


def chat_recipients_fields(recipients):
    count, names = recipients
    fields = {"recipients": int(count)}
    if names:
        fields["recipientNames"] = list(names)
    return fields


def chat_recipients_ack(ref, recipients):
    return json.dumps({
        "kind": "forkmesh-recipients",
        "v": 1,
        "ref": str(ref),
        **chat_recipients_fields(recipients),
    }, separators=(",", ":"))


def chat_stamp_recipients(envelope, recipients):
    stamped = dict(envelope)
    stamped.update(chat_recipients_fields(recipients))
    return json.dumps(stamped, separators=(",", ":"))


def chat_direct_retained_id(ref, account_bi, notify):
    return (
        str(ref) + ":" + str(account_bi)[:16] + (":n" if notify else ""))


def chat_live_budget_frame():
    return json.dumps({
        "kind": "forkmesh-live",
        "v": 1,
        "perWindow": ROOM_LIVE_MAX_PER_WINDOW,
        "windowMs": ROOM_MSG_WINDOW_MS,
    }, separators=(",", ":"))


def chat_live_envelope(message):
    if '"live"' not in message or len(message) > ROOM_LIVE_MAX_BYTES:
        return None
    try:
        envelope = json.loads(message)
    except Exception:
        return None
    if (
        not isinstance(envelope, dict)
        or envelope.get("kind") != "cipher"
        or envelope.get("live") is not True
        or "persist" in envelope
        or "notify" in envelope
        or "resend" in envelope
    ):
        return None
    return envelope


def chat_direct_receipt_envelope(message):
    if len(message) > ROOM_RECEIPT_MAX_BYTES or (
            '"forkmesh-received"' not in message
            and '"forkmesh-superseded"' not in message):
        return None
    try:
        envelope = json.loads(message)
    except Exception:
        return None
    if not isinstance(envelope, dict) or envelope.get("kind") not in (
            "forkmesh-received", "forkmesh-superseded"):
        return None
    return envelope


def chat_server_copies_frame(stored):
    return json.dumps({
        "kind": "forkmesh-server-copies",
        "v": 1,
        "stored": max(0, int(stored)),
    }, separators=(",", ":"))


async def chat_direct_server_copies(env, room_key):
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS stored FROM chat_history "
        "WHERE room_key=? AND ts>=? AND acked_at=0 AND msg_id LIKE ?",
        room_key, int(Date.now()) - CHAT_HISTORY_RETAIN_MS, "%:n",
    )
    return int((row or {}).get("stored") or 0)


def chat_direct_refs(refs):
    if not isinstance(refs, list):
        return []
    return [
        ref for ref in dict.fromkeys(
            value for value in refs if isinstance(value, str))
        if re.fullmatch(r"[0-9a-f]{40}", ref)
    ][:CHAT_DIRECT_RECEIVED_REFS_MAX]


def chat_direct_delivered_frame(refs):
    return json.dumps({
        "kind": "forkmesh-delivered",
        "v": 1,
        "refs": list(refs),
    }, separators=(",", ":"))


def chat_direct_media_frame(media_id, state):
    media_id = str(media_id or "").strip().lower()
    state = str(state or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", media_id) or state not in (
            "opened", "expired", "withdrawn"):
        return ""
    return json.dumps({
        "kind": "forkmesh-media",
        "v": 1,
        "id": media_id,
        "state": state,
    }, separators=(",", ":"))


def chat_direct_read_frame():
    return json.dumps({
        "kind": "forkmesh-read",
        "v": 1,
    }, separators=(",", ":"))


async def chat_direct_received(env, room_key, account_bi, refs):
    refs = chat_direct_refs(refs)
    if not room_key or not refs:
        return False
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE chat_history SET acked_at=? WHERE room_key=? AND acked_at=0 "
        "AND substr(msg_id,41,1)=':' AND substr(msg_id,42,16)<>? "
        "AND substr(msg_id,1,40) IN (" + ",".join("?" * len(refs)) + ")",
        now, room_key, str(account_bi)[:16], *refs,
    )
    await chat_direct_acked_prune(env, room_key, now)
    return True


async def chat_direct_acked_prune(env, room_key, now):
    await d1_run(
        env,
        "DELETE FROM chat_history WHERE room_key=? AND acked_at>0 "
        "AND acked_at<=?",
        room_key, int(now) - CHAT_DIRECT_ACKED_GRACE_MS,
    )
    row = await d1_first(
        env,
        "SELECT MIN(acked_at) AS first FROM chat_history "
        "WHERE room_key=? AND acked_at>0",
        room_key,
    )
    return int((row or {}).get("first") or 0)


async def chat_direct_superseded(env, room_key, account_bi, refs):
    refs = chat_direct_refs(refs)
    if not room_key or not refs:
        return False
    await d1_run(
        env,
        "DELETE FROM chat_history WHERE room_key=? "
        "AND substr(msg_id,41,1)=':' AND substr(msg_id,42,16)=? "
        "AND substr(msg_id,1,40) IN (" + ",".join("?" * len(refs)) + ")",
        room_key, str(account_bi)[:16], *refs,
    )
    return True


async def chat_history_since(env, room_key, since_ts=0):
    # The same retained (encrypted) frames chat_history_recent replays to a
    # joining socket, but stamped with their store time and filtered to what
    # landed after `since_ts`, so an HTTP client can poll a room incrementally.
    await ensure_schema(env)
    try:
        since = int(since_ts or 0)
    except (TypeError, ValueError):
        since = 0
    cutoff = max(since, int(Date.now()) - CHAT_HISTORY_RETAIN_MS)
    rows = await d1_all(
        env,
        "SELECT ts,body FROM chat_history WHERE room_key=? AND ts>? "
        "AND acked_at=0 ORDER BY ts ASC, msg_id ASC LIMIT ?",
        room_key, cutoff, CHAT_HISTORY_MAX_PER_ROOM,
    )
    return [
        {"ts": int(r["ts"]), "body": str(r["body"])}
        for r in rows
    ]


async def chat_history_store(env, room_key, msg_id, ts, body):
    await ensure_schema(env)
    await d1_run(
        env,
        "INSERT INTO chat_history (room_key, msg_id, ts, body) VALUES (?, ?, ?, ?) "
        "ON CONFLICT(room_key, msg_id) DO NOTHING",
        room_key, msg_id, ts, body,
    )
    await _chat_history_prune_bounds(env, room_key)


def _chat_history_prune_due(room_key):
    """Run the windowed bounds prune on the first store per room per isolate
    and then every CHAT_HISTORY_PRUNE_EVERY_STORES stores. The prune scans
    the whole retained room (a window over every row) so running it on every
    message cost ~800 rows read per store on the busy rooms; the caps are
    still enforced within that many messages. Harnesses without the memo
    prune on every store."""
    memo = globals().get("_CHAT_HISTORY_PRUNE_MEMO")
    if not isinstance(memo, dict):
        return True
    every = int(globals().get("CHAT_HISTORY_PRUNE_EVERY_STORES", 1) or 1)
    count = int(memo.get(room_key) or 0)
    memo[room_key] = (count + 1) % max(1, every)
    return count == 0


async def _chat_history_prune_bounds(env, room_key):
    due = globals().get("_chat_history_prune_due")
    if callable(due) and not due(room_key):
        return
    # Enforce count and aggregate-byte limits in one deterministic statement.
    # The body is an ASCII JSON envelope, so SQLite length(body) equals its UTF-8
    # storage bytes. Window totals are newest-first; any older overflow rows are
    # deleted without decrypting their contents.
    await d1_run(
        env,
        "DELETE FROM chat_history WHERE room_key=? AND msg_id IN ("
        "SELECT msg_id FROM ("
        "SELECT msg_id,"
        "ROW_NUMBER() OVER (ORDER BY ts DESC,msg_id DESC) AS row_number,"
        "SUM(length(body)) OVER (ORDER BY ts DESC,msg_id DESC) AS retained_bytes "
        "FROM chat_history WHERE room_key=? AND acked_at=0"
        ") WHERE row_number>? OR retained_bytes>?)",
        room_key,
        room_key,
        CHAT_HISTORY_MAX_PER_ROOM,
        CHAT_HISTORY_MAX_BYTES_PER_ROOM,
    )


async def chat_history_prune(env, room_key):
    # Drop anything past the retention window, then enforce count and aggregate
    # encrypted-byte limits before replaying the room.
    cutoff = int(Date.now()) - CHAT_HISTORY_RETAIN_MS
    await d1_run(env, "DELETE FROM chat_history WHERE room_key=? AND ts<?",
                 room_key, cutoff)
    await _chat_history_prune_bounds(env, room_key)


async def chat_history_prune_expired(env):
    # chat_history_prune() above only runs when a client joins that specific
    # room, so a room nobody reconnects to would otherwise retain messages
    # past the 7-day window forever. Sweep every room's expired rows on the
    # per-minute cron (adhoc #49) so retention is enforced regardless of
    # traffic.
    await ensure_schema(env)
    now = int(Date.now())
    await d1_run(env, "DELETE FROM chat_history WHERE ts<?",
                 now - CHAT_HISTORY_RETAIN_MS)
    await d1_run(
        env, "DELETE FROM chat_history WHERE acked_at>0 AND acked_at<=?",
        now - CHAT_DIRECT_ACKED_GRACE_MS)


class ForkMeshDiscordGate(DurableObject):
    """One production-wide Discord bot rate gate.

    The singleton persists only bounded expiry/bucket metadata. Bot
    credentials, message bodies, channel catalogs, and provider responses are
    never written to Durable Object storage.
    """

    traffic_binding = "FORKMESH_DISCORD_GATE"
    _MAX_KEYS = 256
    _RESERVATION_MS = (DISCORD_API_TIMEOUT_SECONDS * 1000) + 1_000

    async def _state(self, now):
        value = await self.ctx.storage.get("rate_state")
        try:
            state = json.loads(str(value or "{}"))
        except Exception:
            state = {}
        state = state if isinstance(state, dict) else {}
        state = {
            "globalUntil": max(0, int(state.get("globalUntil") or 0)),
            "routes": dict(state.get("routes") or {}),
            "buckets": dict(state.get("buckets") or {}),
            "routeBuckets": dict(state.get("routeBuckets") or {}),
        }
        for group in ("routes", "buckets"):
            state[group] = {
                str(key)[:220]: max(0, int(until or 0))
                for key, until in list(state[group].items())[:self._MAX_KEYS]
                if int(until or 0) > now
            }
        state["routeBuckets"] = {
            str(key)[:220]: str(bucket)[:100]
            for key, bucket in list(
                state["routeBuckets"].items())[:self._MAX_KEYS]
            if str(bucket or "")
        }
        return state

    @staticmethod
    def _wait_ms(state, route_key, major, now):
        waits = [
            int(state.get("globalUntil") or 0) - now,
            int(state["routes"].get(route_key) or 0) - now,
        ]
        bucket = str(state["routeBuckets"].get(route_key) or "")
        if bucket:
            waits.append(
                int(state["buckets"].get(bucket + "|" + major) or 0) - now)
        return max(0, min(3_600_000, max(waits)))

    async def fetch(self, request):
        if _decommissioned(self.env):
            return _decommissioned_response()
        if (
            str(getattr(request, "method", "GET")).upper() != "POST"
            or urlparse(request.url).path != "/discord-gate/request"
        ):
            return json_response({"error": "not_found"}, status=404)
        try:
            raw = str(await request.text())
            if len(raw.encode("utf-8")) > 8 * 1024:
                raise ValueError("request too large")
            payload = json.loads(raw)
        except Exception:
            return json_response({
                "status": 400, "data": None, "retryAfterMs": 0,
            }, cache_control="no-store")
        if not isinstance(payload, dict) or set(payload) - {
                "method", "path", "body"}:
            return json_response({
                "status": 400, "data": None, "retryAfterMs": 0,
            }, cache_control="no-store")
        method = str(payload.get("method") or "").upper()
        path = str(payload.get("path") or "")
        body = payload.get("body")
        if (
            not _discord_api_path_allowed(method, path)
            or (body is not None
                and (method != "POST" or not isinstance(body, dict)))
        ):
            return json_response({
                "status": 400, "data": None, "retryAfterMs": 0,
            }, cache_control="no-store")

        now = int(Date.now())
        major = _discord_rate_major(path)
        route_key = _discord_rate_route(path) + "|" + major
        state = await self._state(now)
        wait_ms = self._wait_ms(state, route_key, major, now)
        if wait_ms:
            return json_response({
                "status": 429, "data": None, "retryAfterMs": wait_ms,
            }, cache_control="no-store")

        # Reserve before the outbound await. This closes the first-request
        # race even when concurrent invocations arrive before Discord has
        # advertised a bucket id.
        state["routes"][route_key] = now + self._RESERVATION_MS
        await self.ctx.storage.put(
            "rate_state", json.dumps(state, separators=(",", ":")))
        result = await _discord_provider_request(
            self.env, method, path, body)
        observed_at = int(Date.now())
        # Another route may have completed during our provider await. Reload
        # before merging this observation so disjoint bucket metadata cannot
        # overwrite one another.
        state = await self._state(observed_at)
        state["routes"].pop(route_key, None)
        retry_ms = max(
            0, min(3_600_000, int(result.get("retryAfterMs") or 0)))
        bucket = str(result.get("rateBucket") or "")[:100]
        if bucket:
            state["routeBuckets"][route_key] = bucket
        if retry_ms:
            until = observed_at + retry_ms
            if result.get("rateGlobal"):
                state["globalUntil"] = max(state["globalUntil"], until)
            elif bucket:
                bucket_key = bucket + "|" + major
                state["buckets"][bucket_key] = max(
                    int(state["buckets"].get(bucket_key) or 0), until)
            else:
                state["routes"][route_key] = max(
                    int(state["routes"].get(route_key) or 0), until)
        await self.ctx.storage.put(
            "rate_state", json.dumps(state, separators=(",", ":")))
        public_result = {
            "status": max(0, min(599, int(result.get("status") or 0))),
            "data": result.get("data"),
            "retryAfterMs": retry_ms,
        }
        # Aggregate byte/message counters only; the capacity row never sees
        # the request body or provider response.
        durable_object_traffic_note(
            self,
            bytes_in=len(raw.encode("utf-8")),
            bytes_out=len(json.dumps(public_result).encode("utf-8")),
            messages=1,
        )
        await durable_object_traffic_flush(self)
        return json_response(public_result, cache_control="no-store")


class ForkMeshCronWatchdog(DurableObject):
    """Alarm-backed observer for successful every-minute cron completions.

    A failed maintenance loop cannot report its own failure. This singleton
    Durable Object receives a heartbeat only at the end of a completed tick
    and moves its alarm three minutes forward.
    When that independent alarm expires it sends one outage email; the first
    later completion sends one recovery email. Durable Object event
    serialization also keeps the transition and email deduplication races out
    of the stateless Python Worker isolate.
    """

    traffic_binding = "FORKMESH_CRON_WATCHDOG"

    async def fetch(self, request):
        if _read_only(self.env):
            await _maintenance_stop_alarm(self)
            return _decommissioned_response() if _decommissioned(
                self.env) else _read_only_response()
        if urlparse(request.url).path != "/cron-watchdog/completed":
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        outage_started_at = int(
            await self.ctx.storage.get("outage_started_at") or 0)
        notified_state = str(
            await self.ctx.storage.get("notified_state") or "")

        # Only send "recovered" if recipients previously received "outage".
        # If the provider is temporarily unavailable, leave the state intact;
        # the next minute's completion heartbeat retries without duplicating a
        # successful transition.
        if outage_started_at and notified_state == "down":
            if await _send_cron_watchdog_email(
                    self.env, True, outage_started_at, now):
                await self.ctx.storage.put("outage_started_at", 0)
                await self.ctx.storage.put("notified_state", "up")
        elif outage_started_at:
            await self.ctx.storage.put("outage_started_at", 0)
            await self.ctx.storage.put("notified_state", "up")

        await self.ctx.storage.put("last_completion_at", now)
        await self.ctx.storage.setAlarm(now + CRON_WATCHDOG_GRACE_MS)
        # This is an internal liveness heartbeat, not relayed user traffic.
        # Its own Durable Object storage is the metric; mirroring every minute
        # into D1 would spend 1,440 Free-plan writes/day for no capacity signal.
        return json_response({"ok": True})

    async def alarm(self, alarm_info=None):
        if _read_only(self.env):
            await _maintenance_stop_alarm(self)
            return
        now = int(Date.now())
        last_completion_at = int(
            await self.ctx.storage.get("last_completion_at") or 0)
        if not last_completion_at:
            return
        deadline = last_completion_at + CRON_WATCHDOG_GRACE_MS
        if now < deadline:
            # A heartbeat raced an already-dispatched alarm. Keep the newer
            # deadline instead of manufacturing an outage.
            await self.ctx.storage.setAlarm(deadline)
            return
        if await _status_deploy_semaphore_active(self.env, now):
            # A Worker rollout can interrupt the cron runner long enough to
            # trip this independent watchdog. Keep observing, but do not turn
            # expected deployment handoff time into an incident. The shared
            # semaphore also includes the bounded post-activation grace.
            await self.ctx.storage.setAlarm(
                now + CRON_WATCHDOG_GRACE_MS)
            return

        outage_started_at = int(
            await self.ctx.storage.get("outage_started_at") or 0)
        if not outage_started_at:
            outage_started_at = deadline
            await self.ctx.storage.put(
                "outage_started_at", outage_started_at)
        notified_state = str(
            await self.ctx.storage.get("notified_state") or "")
        if notified_state != "down":
            delivered = await _send_cron_watchdog_email(
                self.env, False, outage_started_at, now)
            if delivered:
                await self.ctx.storage.put("notified_state", "down")
                return
        # Retry an unavailable email provider/admin-recipient lookup without
        # depending on the still-failing maintenance runner.
        await self.ctx.storage.setAlarm(now + CRON_WATCHDOG_RETRY_MS)


class _AppIngressRouter:
    """Bind AppRuntime's established handler methods to one ingress DO event."""

    _inside_app_ingress = True

    def __init__(self, env):
        self.env = env

    def __getattr__(self, name):
        descriptor = AppRuntime.__dict__.get(name)
        if descriptor is None:
            raise AttributeError(name)
        if isinstance(descriptor, staticmethod):
            return descriptor.__get__(None, AppRuntime)
        if isinstance(descriptor, classmethod):
            return descriptor.__get__(AppRuntime, AppRuntime)
        if hasattr(descriptor, "__get__"):
            return descriptor.__get__(self, type(self))
        return descriptor


class ForkMeshCronRunner(DurableObject):
    """Serialized maintenance coordinator plus the fetch-only ingress objects.

    The singleton scheduled-runner-v1 receives each Cron Trigger doorbell,
    and its alarm runs every due phase of the minute itself (see the inline
    tick notes beside CRON_TICK_STATE_KEY). When one invocation's subrequest
    budget cannot hold the next phase, the object persists its progress and
    re-arms its alarm for "now", so the tick continues in a fresh invocation
    on the same object instead of fanning out to other objects that would be
    billed alongside a waiting coordinator. The singleton
    snapshot-republish-v1 object is the event-driven doorbell for the catalog
    snapshots: mutations ring it, and its alarm republishes the affected paths
    (schedule_public_catalog_republish). mirror-wake-v1 uses the same durable
    handoff pattern for commit and collaboration mirror notifications, keeping
    accepted writes off that potentially many-node fan-out.
    """

    traffic_binding = "FORKMESH_CRON_RUNNER"

    def _object_name(self):
        object_id = getattr(self.ctx, "id", None)
        return str(getattr(object_id, "name", "") or "")

    async def _load_json_state(self, key):
        raw = await self.ctx.storage.get(key)
        if hasattr(raw, "to_py"):
            raw = raw.to_py()
        if isinstance(raw, dict):
            return dict(raw)
        try:
            parsed = json.loads(str(raw or "{}"))
        except Exception:
            parsed = {}
        return parsed if isinstance(parsed, dict) else {}

    @staticmethod
    def _phase_reserve(phase, costs):
        """Budget to hold back before starting one phase.

        A phase this object has never measured reserves the whole cap, so it
        can only ever lead an invocation: an unmeasured phase keeps exactly
        the isolation a per-phase object gave it, and the cost it then
        records lets the next minute pack it beside its neighbours. Measured
        costs are high-water marks, never averages, so a phase whose work
        grows widens its own reserve before it can crowd anything else out.
        """
        try:
            observed = int(costs[phase])
        except (KeyError, TypeError, ValueError, OverflowError):
            return CRON_BATCH_SUBREQUEST_CAP
        return min(
            CRON_BATCH_SUBREQUEST_CAP,
            max(1, observed) + CRON_BATCH_RESERVE_HEADROOM)

    async def _run_tick_slice(self, state):
        """Run as much of one tick as this invocation's budget holds.

        ``state`` is the persisted tick: the phases still pending, what ran,
        failed and was skipped so far, and the phase a previous invocation
        had started when it stopped. Progress is written before every phase
        so an interrupted invocation is recognised on resume: a phase that
        was started and never finished is reported incomplete unless it is
        replay-safe or D1-deduplicated, exactly as before. Returns True when
        phases remain for a further invocation.
        """
        minute_slot = int(state["slot"])
        pending = [str(phase) for phase in (state.get("pending") or ())]
        chain = frozenset(str(phase) for phase in (state.get("chain") or ()))
        ran = state.setdefault("ran", {})
        failed = state.setdefault("failed", {})
        skipped = list(state.get("skipped") or ())
        failures = list(state.get("failures") or ())
        chain_failed = bool(state.get("chainFailed"))
        interrupted = str(state.get("started") or "")
        state["invocations"] = int(state.get("invocations") or 0) + 1
        deadline_at = int(state.get("startedAt") or 0) + CRON_DISPATCH_TIMEOUT_MS
        costs = await self._load_json_state(CRON_TICK_COST_KEY)
        costs_changed = False
        attempted = 0
        reserved = 0
        more = False
        deadline_hit = False
        variable, token, budget = _cron_d1_budget_start()
        try:
            while pending:
                phase = pending[0]
                in_chain = phase in chain
                if (
                    (chain_failed and in_chain)
                    or (phase == CRON_WATCHDOG_PHASE
                        and (failed or failures))
                ):
                    # A broken chain stops where it broke, and the tick's
                    # own success signal is withheld whenever anything in
                    # the tick went wrong.
                    skipped.append(phase)
                    pending.pop(0)
                    continue
                if (
                    phase == interrupted
                    and phase not in CRON_PHASE_REPLAY_SAFE
                    and phase not in CRON_PHASE_D1_DEDUPED
                ):
                    # Started by an invocation that never finished: it may
                    # have been interrupted mid-write, so do not replay it.
                    failed[phase] = "phase_incomplete"
                    failures.append(phase + ": phase_incomplete")
                    chain_failed = chain_failed or in_chain
                    pending.pop(0)
                    continue
                if attempted and int(Date.now()) >= deadline_at:
                    deadline_hit = True
                    break
                used_before = int(budget.get("used") or 0)
                reserve = self._phase_reserve(phase, costs)
                if attempted and (
                        reserved + reserve > CRON_BATCH_SUBREQUEST_CAP
                        or CRON_PHASE_D1_QUERY_LIMIT - used_before < reserve):
                    # The rest needs a budget this invocation no longer has:
                    # either the reserves no longer pack under the cap (an
                    # unmeasured phase reserves all of it, so it only ever
                    # leads an invocation) or something already overran its
                    # measured cost.
                    more = True
                    break
                reserved += reserve
                state["started"] = phase
                state["pending"] = list(pending)
                state["skipped"] = skipped
                state["failures"] = failures
                state["chainFailed"] = chain_failed
                await self.ctx.storage.put(
                    CRON_TICK_STATE_KEY,
                    json.dumps(state, separators=(",", ":")))
                phase_started = int(Date.now())
                error = await self._run_claimed_phase(
                    phase, minute_slot, budget)
                cost = max(0, int(budget.get("used") or 0) - used_before)
                attempted += 1
                pending.pop(0)
                # A phase that burned budget before failing still widens its
                # own reserve; the mark is the high water, not an average.
                if cost > int(costs.get(phase) or 0):
                    costs[phase] = min(cost, CRON_BATCH_SUBREQUEST_CAP)
                    costs_changed = True
                if error is None and budget.get("exhausted"):
                    # A broad maintenance helper may swallow the guard's
                    # exception. Fail closed on the flag it left behind.
                    error = RuntimeError(
                        "cron phase subrequest budget exhausted")
                if error is not None:
                    detail = _safe_error_text(error)[:240]
                    failed[phase] = detail
                    failures.append(phase + ": " + detail)
                    chain_failed = chain_failed or in_chain
                    if budget.get("exhausted"):
                        # This invocation's budget is spent. The rest of the
                        # tick continues with a fresh one.
                        more = bool(pending)
                        break
                    continue
                ran[phase] = {
                    "ms": max(0, int(Date.now()) - phase_started),
                    "sub": cost,
                }
        finally:
            _cron_d1_budget_stop(variable, token)
        state["started"] = ""
        state["subrequests"] = (
            int(state.get("subrequests") or 0)
            + int(budget.get("used") or 0))
        if more and int(state["invocations"]) >= CRON_BATCH_MAX_OBJECTS:
            failures.append("invocation cap exhausted")
            more = False
        if deadline_hit:
            failures.append("dispatch deadline exhausted")
        if pending and not more:
            failures.append("undispatched: " + ",".join(sorted(pending)[:8]))
            for phase in pending:
                failed.setdefault(str(phase), "undispatched")
            pending = []
        state["pending"] = pending
        state["skipped"] = skipped
        state["failures"] = failures
        state["chainFailed"] = chain_failed
        if costs_changed:
            # Written only when a high-water mark actually moved, which after
            # the first few minutes of a new release is almost never.
            await self.ctx.storage.put(
                CRON_TICK_COST_KEY,
                json.dumps(costs, separators=(",", ":")))
        return more

    async def _run_claimed_phase(self, phase, minute_slot, budget):
        """Run one phase and return its error, or None.

        A replay-safe phase gets one immediate second attempt; an exhausted
        budget is never retried, because the retry cannot finish either.
        """
        try:
            await _run_cron_phase(self.env, phase, minute_slot)
            return None
        except BaseException as error:
            if (
                phase not in CRON_PHASE_REPLAY_SAFE
                or bool(budget.get("exhausted"))
            ):
                return error
        try:
            await js_scheduler.wait(CRON_PHASE_RETRY_DELAY_MS)
            await _run_cron_phase(self.env, phase, minute_slot)
            return None
        except BaseException as error:
            return error

    async def _coordinator_fetch(self, path):
        if path == "/cron-runner/kick":
            now = int(Date.now())
            if bool(await self.ctx.storage.get("retired_v2")):
                await self.ctx.storage.put("retired_v2", False)
            # The doorbell is a safety net for a lost alarm chain. A tick
            # continuation already armed for sooner than this must not be
            # pushed back by it.
            existing = None
            get_alarm = getattr(self.ctx.storage, "getAlarm", None)
            if callable(get_alarm):
                try:
                    existing = await get_alarm()
                except BaseException:
                    existing = None
            if js_nullish(existing) or int(existing) > now + CRON_RUNNER_KICK_DELAY_MS:
                await self.ctx.storage.setAlarm(
                    now + CRON_RUNNER_KICK_DELAY_MS)
            return json_response({"ok": True, "mode": "serialized-alarm"})
        if path == "/cron-runner/retire":
            if not bool(await self.ctx.storage.get("retired_v2")):
                await self.ctx.storage.put("retired_v2", True)
                delete_alarm = getattr(self.ctx.storage, "deleteAlarm", None)
                if callable(delete_alarm):
                    await delete_alarm()
            return json_response({"ok": True, "retired": True})
        return json_response({"error": "not_found"}, status=404)

    async def _mirror_wake_fetch(self, parsed):
        """Doorbell: coalesce one repository's mirror notification."""
        if parsed.path != MIRROR_WAKE_PATH:
            return json_response({"error": "not_found"}, status=404)
        params = parse_qs(parsed.query)
        owner = (safe_segment((params.get("owner") or [""])[0]) or "").lower()
        repo = safe_segment((params.get("repo") or [""])[0])
        topic = clean_string((params.get("topic") or [""])[0], 40)
        state = clean_string((params.get("state") or [""])[0], 64)
        try:
            generation = max(0, int(
                (params.get("generation") or ["0"])[0] or 0))
        except (TypeError, ValueError, OverflowError):
            generation = 0
        if (
            not owner or not repo
            or topic not in ("issues", "pulls", "discussions", "commits")
            or (state and not re.fullmatch(r"[0-9a-f]{64}", state))
        ):
            return json_response({"error": "invalid_mirror_wake"}, status=400)
        pending = await self._load_json_state(MIRROR_WAKE_REQUESTED_PREFIX)
        key = owner + "/" + repo + "/" + topic
        now = int(Date.now())
        if key not in pending and len(pending) >= 128:
            oldest = min(
                pending,
                key=lambda value: int(
                    (pending.get(value) or {}).get("requestedAt") or 0),
            )
            pending.pop(oldest, None)
        pending[key] = {
            "owner": owner, "repo": repo, "topic": topic,
            "state": state, "generation": generation, "requestedAt": now,
        }
        await self.ctx.storage.put(
            MIRROR_WAKE_REQUESTED_PREFIX,
            json.dumps(pending, separators=(",", ":")),
        )
        alarm_at = await self._republish_arm(now + MIRROR_WAKE_LEAD_MS)
        return json_response(
            {"ok": True, "alarmAt": alarm_at}, status=202)

    async def _mirror_wake_alarm(self):
        """Fan out one queued collaboration wake, then promptly continue."""
        if getattr(self, "_mirror_wake_active", False):
            return
        self._mirror_wake_active = True
        try:
            pending = await self._load_json_state(MIRROR_WAKE_REQUESTED_PREFIX)
            if not pending:
                return
            key = min(
                pending,
                key=lambda value: int(
                    (pending.get(value) or {}).get("requestedAt") or 0),
            )
            item = pending.get(key)
            if not isinstance(item, dict):
                pending.pop(key, None)
                await self.ctx.storage.put(
                    MIRROR_WAKE_REQUESTED_PREFIX,
                    json.dumps(pending, separators=(",", ":")),
                )
                if pending:
                    await self._republish_arm(int(Date.now()))
                return
            now = int(Date.now())
            try:
                ready_at = max(0, int(item.get("requestedAt") or 0))
            except (TypeError, ValueError, OverflowError):
                ready_at = 0
            if ready_at > now:
                await self._republish_arm(ready_at)
                return
            delivered = await notify_repo_mirrors(
                self.env, item.get("owner", ""), item.get("repo", ""),
                item.get("topic", ""), item.get("state", ""),
                item.get("generation", 0))
            if delivered is False:
                # Keep the exact latest item durable. Alarms exist only while
                # a real accepted write is awaiting delivery, so this bounded
                # error retry cannot become a steady-state poll.
                current = await self._load_json_state(
                    MIRROR_WAKE_REQUESTED_PREFIX)
                if current.get(key) == item:
                    retry = dict(item)
                    retry["requestedAt"] = now + MIRROR_WAKE_RETRY_MS
                    current[key] = retry
                    await self.ctx.storage.put(
                        MIRROR_WAKE_REQUESTED_PREFIX,
                        json.dumps(current, separators=(",", ":")),
                    )
                if current:
                    next_at = min(
                        max(0, int(
                            (value or {}).get("requestedAt") or 0))
                        for value in current.values()
                        if isinstance(value, dict)
                    )
                    await self._republish_arm(max(now, next_at))
                return
            # A doorbell can arrive while the fan-out is running. Delete only
            # the exact record we delivered, leaving its newer replacement
            # queued for the next alarm.
            current = await self._load_json_state(MIRROR_WAKE_REQUESTED_PREFIX)
            if current.get(key) == item:
                current.pop(key, None)
                await self.ctx.storage.put(
                    MIRROR_WAKE_REQUESTED_PREFIX,
                    json.dumps(current, separators=(",", ":")),
                )
            if current:
                await self._republish_arm(int(Date.now()))
        finally:
            self._mirror_wake_active = False

    async def _republish_stamp(self, key):
        """One millisecond stamp from this object's storage (0 when unset)."""
        raw = await self.ctx.storage.get(key)
        if js_nullish(raw):
            return 0
        try:
            return max(0, int(raw))
        except (TypeError, ValueError, OverflowError):
            return 0

    async def _republish_arm(self, target):
        """Move the alarm earlier, never later."""
        target = int(target)
        get_alarm = getattr(self.ctx.storage, "getAlarm", None)
        current = await get_alarm() if callable(get_alarm) else None
        if not js_nullish(current):
            try:
                current = int(current)
            except (TypeError, ValueError, OverflowError):
                current = None
        else:
            current = None
        if current is None or current > target:
            await self.ctx.storage.setAlarm(target)
            return target
        return current

    async def _republish_fetch(self, parsed):
        """Doorbell: record the affected paths and arm the coalescing alarm.

        Only storage work happens here, so the mutating request that rang the
        bell waits a few milliseconds, not for a catalog scan. Stamps are
        per-path keys and always rewritten: the alarm's finalize compares the
        stamp with the generation it just built, so a doorbell that lands
        while a build is reading D1 keeps that path pending instead of being
        folded into a generation that may have missed its mutation.
        """
        if parsed.path != SNAPSHOT_REPUBLISH_PATH:
            return json_response({"error": "not_found"}, status=404)
        params = parse_qs(parsed.query)
        requested = str((params.get("paths") or [""])[0]).split(",")
        paths = [
            path for path in SNAPSHOT_REPUBLISH_DOORBELL_PATHS
            if path in requested]
        if not paths:
            return json_response({"error": "invalid_paths"}, status=400)
        now = int(Date.now())
        target = None
        for path in paths:
            await self.ctx.storage.put(
                SNAPSHOT_REPUBLISH_REQUESTED_PREFIX + path, now)
            published_at = await self._republish_stamp(
                SNAPSHOT_REPUBLISH_PUBLISHED_PREFIX + path)
            ready_at = _republish_ready_at(now, published_at, path)
            target = ready_at if target is None else min(target, ready_at)
        alarm_at = await self._republish_arm(target)
        return json_response(
            {"ok": True, "paths": paths, "alarmAt": alarm_at}, status=202)

    async def _republish_alarm(self):
        """Rebuild at most one pending catalog-family snapshot, then re-arm.

        One build per invocation keeps every catalog scan inside its own
        subrequest budget, exactly like the staggered Cron phases; further
        pending paths re-fire the alarm immediately. A path is pending while
        its requested stamp is newer than its published stamp, ready once both
        the lead delay and the per-path minimum interval have elapsed, and
        skipped (or deferred) when the served row already reflects the
        mutation (or is a privacy-transition barrier).
        """
        if getattr(self, "_republish_active", False):
            return
        self._republish_active = True
        try:
            now = int(Date.now())
            stamps = {}
            deferred_until = {}
            built = False
            for path in SNAPSHOT_REPUBLISH_DOORBELL_PATHS:
                requested_key = SNAPSHOT_REPUBLISH_REQUESTED_PREFIX + path
                published_key = SNAPSHOT_REPUBLISH_PUBLISHED_PREFIX + path
                requested_at = await self._republish_stamp(requested_key)
                published_at = await self._republish_stamp(published_key)
                stamps[path] = (requested_at, published_at)
                if (
                    built
                    or requested_at <= published_at
                    or now < _republish_ready_at(
                        requested_at, published_at, path)
                ):
                    continue
                verdict, deadline = await _republish_row_verdict(
                    self.env, path, requested_at, now)
                if verdict == "reflected":
                    await self.ctx.storage.put(published_key, int(deadline))
                    stamps[path] = (requested_at, int(deadline))
                    continue
                if verdict == "tombstone":
                    deferred_until[path] = (
                        int(deadline) + SNAPSHOT_REPUBLISH_LEAD_MS)
                    continue
                generated_at = int(Date.now())
                await _republish_publish_path(self.env, path, generated_at)
                # Success or logged failure, the stamp throttles the next
                # attempt; the Cron cadence remains the safety net.
                for published_path in _republish_group(path):
                    await self.ctx.storage.put(
                        SNAPSHOT_REPUBLISH_PUBLISHED_PREFIX + published_path,
                        generated_at)
                built = True
            next_at = None
            for path in SNAPSHOT_REPUBLISH_DOORBELL_PATHS:
                requested_at, published_at = stamps.get(path, (0, 0))
                if built:
                    # Doorbells may have landed while the build was reading
                    # D1; a stamp newer than the build keeps its path pending.
                    requested_at = await self._republish_stamp(
                        SNAPSHOT_REPUBLISH_REQUESTED_PREFIX + path)
                    published_at = await self._republish_stamp(
                        SNAPSHOT_REPUBLISH_PUBLISHED_PREFIX + path)
                if requested_at <= published_at:
                    continue
                candidate = max(
                    _republish_ready_at(requested_at, published_at, path),
                    deferred_until.get(path, 0),
                )
                next_at = (
                    candidate if next_at is None else min(next_at, candidate))
            if next_at is not None:
                # A doorbell that rang during the build may already have
                # armed an earlier alarm; never move it later.
                await self._republish_arm(max(int(next_at), now))
        finally:
            self._republish_active = False

    async def fetch(self, request):
        parsed = urlparse(request.url)
        object_name = self._object_name()
        app_ingress = (
            object_name.startswith(APP_INGRESS_NAME_PREFIX)
            and len(object_name) == len(APP_INGRESS_NAME_PREFIX) + 1
            and object_name[-1] in "0123456789abcdef"
        )
        git_ingress = (
            object_name.startswith(APP_GIT_INGRESS_NAME_PREFIX)
            and len(object_name) == len(APP_GIT_INGRESS_NAME_PREFIX) + 1
            and object_name[-1] in "0123456789abcdef"
        )
        if app_ingress or git_ingress:
            purpose = str(request.headers.get(
                "x-forkmesh-internal-ingress") or "")
            if git_ingress:
                if purpose != APP_INGRESS_GIT_READ_PURPOSE:
                    return json_response({"error": "not_found"}, status=404)

                async def handle_git_read():
                    return await AppRuntime._fetch_inner(
                        _AppIngressRouter(self.env), request)

                # Python's Pyodide bridge cannot safely re-enter one isolate
                # while a prior async handler is suspended.  Durable Objects
                # may normally interleave fetches at awaits, so explicitly
                # retain the input gate until routing has returned the native
                # streaming response. blockConcurrencyWhile has a 30-second
                # platform bound; an exception resets this disposable object
                # and the outer dispatcher returns marked retryable pressure.
                return await self.ctx.blockConcurrencyWhile(handle_git_read)
            if purpose == APP_INGRESS_NODE_AUTH_PURPOSE:
                object_name, rejection = await _node_events_object(
                    self.env, request)
                if rejection is not None:
                    return rejection
                authorized_headers = {
                    "x-forkmesh-authorized-object": object_name}
                if object_name.startswith("nodes:"):
                    authorized_headers["x-forkmesh-authorized-owner"] = \
                        object_name[len("nodes:"):]
                return Response(None, status=204, headers=authorized_headers)
            if purpose == APP_INGRESS_WEBSOCKET_AUTH_PURPOSE:
                return await _websocket_handoff_authorization(
                    self.env, request)
            if purpose != APP_INGRESS_HTTP_PURPOSE:
                return json_response({"error": "not_found"}, status=404)
            return await AppRuntime._fetch_inner(
                _AppIngressRouter(self.env), request)
        if _read_only(self.env):
            return _decommissioned_response() if _decommissioned(
                self.env) else _read_only_response()
        if object_name == SNAPSHOT_REPUBLISH_NAME:
            return await self._republish_fetch(parsed)
        if object_name == MIRROR_WAKE_NAME:
            return await self._mirror_wake_fetch(parsed)
        if object_name == CRON_RUNNER_NAME:
            return await self._coordinator_fetch(parsed.path)
        return json_response({"error": "not_found"}, status=404)

    async def alarm(self, alarm_info=None):
        if _read_only(self.env):
            await _maintenance_stop_alarm(self)
            return
        if self._object_name() == SNAPSHOT_REPUBLISH_NAME:
            return await self._republish_alarm()
        if self._object_name() == MIRROR_WAKE_NAME:
            return await self._mirror_wake_alarm()
        if self._object_name() != CRON_RUNNER_NAME:
            return
        return await self._coordinator_alarm()

    async def _coordinator_alarm(self):
        """One alarm invocation of the inline tick: start it or resume it."""
        if getattr(self, "_coordinator_active", False):
            return
        self._coordinator_active = True
        try:
            if bool(await self.ctx.storage.get("retired_v2")):
                return
            now = int(Date.now())
            minute_slot = now // CRON_RUNNER_INTERVAL_MS
            next_alarm = (
                (minute_slot + 1) * CRON_RUNNER_INTERVAL_MS
                + CRON_RUNNER_ALARM_OFFSET_MS
            )
            state = await self._load_json_state(CRON_TICK_STATE_KEY)
            try:
                state_slot = int(state.get("slot"))
            except (TypeError, ValueError, OverflowError):
                state_slot = -1
            resuming = (
                state_slot == minute_slot
                and not state.get("completedAt")
                and bool(state.get("pending"))
            )
            if not resuming:
                # Persist the successor before invoking any Python
                # maintenance, so a tick that dies mid-flight still has a
                # next minute.
                await self.ctx.storage.setAlarm(next_alarm)
                # A /retire request may have interleaved with the first
                # storage await. Recheck after arming so it can never leave a
                # stale alarm.
                if bool(await self.ctx.storage.get("retired_v2")):
                    delete_alarm = getattr(
                        self.ctx.storage, "deleteAlarm", None)
                    if callable(delete_alarm):
                        await delete_alarm()
                    return
                completed_slot = int(
                    await self.ctx.storage.get("last_completed_slot") or -1)
                if completed_slot >= minute_slot:
                    return
                if state_slot == minute_slot and state.get("completedAt"):
                    # Finished, but the checkpoint below could not be
                    # written. Do not run the minute twice.
                    return
                ordered, _chain_length = _cron_tick_phase_order(minute_slot)
                state = {
                    "slot": minute_slot,
                    "pending": list(ordered),
                    "chain": [
                        phase for phase in CRON_STATUS_CHAIN
                        if phase in ordered],
                    "startedAt": now,
                    "invocations": 0,
                    "ran": {},
                    "failed": {},
                    "skipped": [],
                    "failures": [],
                    "subrequests": 0,
                    "started": "",
                }
                # These keys are observability checkpoints, not the durable
                # work itself. A code-update handoff can reject a storage RPC
                # after the successor alarm is already armed; letting that
                # exception escape marks an otherwise successful alarm as a
                # DO error. The phases are slot-idempotent, so checkpoint
                # writes are deliberately best-effort while the tick state
                # and setAlarm above remain strict.
                await self._best_effort_storage_put(
                    "last_started_slot", minute_slot)
            more = await self._run_tick_slice(state)
            if more:
                # Continue in a fresh invocation, with a fresh subrequest
                # budget, on this same object. Storage first, then the alarm:
                # a lost alarm is re-armed by the next doorbell, a lost state
                # would replay the slot.
                await self.ctx.storage.put(
                    CRON_TICK_STATE_KEY,
                    json.dumps(state, separators=(",", ":")))
                await self.ctx.storage.setAlarm(int(Date.now()))
                return
            failures = list(state.get("failures") or ())
            await _cron_tick_record(
                self.env, minute_slot, int(state.get("startedAt") or now),
                int(state.get("invocations") or 0),
                dict(state.get("ran") or {}), dict(state.get("failed") or {}),
                list(state.get("skipped") or ()),
                int(state.get("subrequests") or 0))
            state["completedAt"] = int(Date.now())
            state["pending"] = []
            await self._best_effort_storage_put(
                CRON_TICK_STATE_KEY,
                json.dumps(state, separators=(",", ":")))
            if resuming:
                # The continuation alarm has fired; restore the cadence.
                await self.ctx.storage.setAlarm(next_alarm)
            if failures:
                await self._best_effort_storage_put(
                    "last_failure",
                    ("cron phase failures: " + "; ".join(failures[:8]))[:1000])
                await self._best_effort_storage_put(
                    "last_failure_at", int(Date.now()))
                return
            await self._best_effort_storage_put(
                "last_completed_slot", minute_slot)
            await self._best_effort_storage_put(
                "last_completed_at", int(Date.now()))
            await self._best_effort_storage_put("last_failure", "")
        finally:
            self._coordinator_active = False

    async def _best_effort_storage_put(self, key, value):
        try:
            await self.ctx.storage.put(key, value)
        except BaseException:
            return False
        return True
import world_durable_objects as _world_durable_objects_module
