class ForkMeshNoteRoom(DurableObject):
    """Hibernatable, transient presence/cursor fanout for one persisted note."""

    traffic_binding = "FORKMESH_NOTE_ROOM"
    _MAX_CLIENTS = 64
    _MAX_FRAME = 600 * 1024

    async def fetch(self, request):
        if method_name(request) == "POST":
            try:
                body = await request.text()
                frame = json.loads(body)
            except Exception:
                return json_response({"error": "invalid_event"}, status=400)
            if not isinstance(frame, dict) or frame.get("type") not in (
                    "note-updated", "note-deleted", "access-changed",
                    "note-activity"):
                return json_response({"error": "invalid_event"}, status=400)
            payload = json.dumps(frame, separators=(",", ":"))
            for peer in self._peers():
                try:
                    peer.send(payload)
                except Exception:
                    pass
                if frame.get("type") in ("note-deleted", "access-changed"):
                    try:
                        peer.close(1008, "note access changed")
                    except Exception:
                        pass
            return json_response({"ok": True})

        upgrade = str(request.headers.get("upgrade") or "").lower()
        if upgrade != "websocket":
            return json_response({"error": "websocket_required"}, status=426)
        if len(self._peers()) >= self._MAX_CLIENTS:
            return json_response({"error": "room_full"}, status=429)
        client, server = WebSocketPair.new().object_values()
        self.ctx.acceptWebSocket(server, to_js(["note"]))
        params = parse_qs(urlparse(request.url).query)
        role = str(params.get("role", [""])[0])
        actor = clean_string(params.get("actor", [""])[0], MAX_NODE_NAME)
        server.serializeAttachment(to_js({
            "id": new_socket_id(), "start": int(Date.now()), "count": 0,
            "role": role if role in ("owner", "editor", "viewer") else "viewer",
            "actor": actor}))
        return JsResponse.new(None, to_js({"status": 101, "webSocket": client}))

    def _peers(self):
        try:
            return list(self.ctx.getWebSockets("note"))
        except Exception:
            return []

    async def webSocketMessage(self, ws, message):
        if _maintenance_socket_closed(self.env, ws):
            return
        if not isinstance(message, str) or len(message.encode("utf-8")) > self._MAX_FRAME:
            try:
                ws.close(1009, "frame too large")
            except Exception:
                pass
            return
        try:
            frame = json.loads(message)
        except Exception:
            return
        if not isinstance(frame, dict) or frame.get("type") not in (
                "presence", "cursor", "draft"):
            return
        if frame.get("type") == "draft" and _ws_attr(ws, "role", "viewer") not in (
                "owner", "editor"):
            return
        try:
            line = max(0, min(1000000, int(frame.get("line") or 0)))
            column = max(0, min(1000000, int(frame.get("column") or 0)))
        except (TypeError, ValueError, OverflowError):
            line, column = 0, 0
        safe_frame = {
            "type": frame["type"],
            "clientId": str(frame.get("clientId") or "")[:64],
            "name": _ws_attr(ws, "actor", ""),
            "line": line,
            "column": column,
        }
        if frame["type"] == "draft":
            safe_frame["title"] = clean_string(
                frame.get("title") or "Untitled note", 200)
            safe_frame["markdown"] = str(
                frame.get("markdown") or "").replace("\x00", "")[:512 * 1024]
            try:
                safe_frame["baseVersion"] = max(
                    1, int(frame.get("baseVersion") or 1))
            except (TypeError, ValueError, OverflowError):
                safe_frame["baseVersion"] = 1
        payload = json.dumps(safe_frame, separators=(",", ":"))
        for peer in self._peers():
            if peer is ws:
                continue
            try:
                peer.send(payload)
            except Exception:
                pass

    async def webSocketClose(self, ws, _code, _reason, _clean):
        try:
            ws.close(1000, "closed")
        except Exception:
            pass

    async def webSocketError(self, ws, _error):
        try:
            ws.close(1011, "error")
        except Exception:
            pass


class ForkMeshRoom(DurableObject):
    # Encrypted chat relay on the WebSocket Hibernation API. Sockets are accepted
    # via ctx.acceptWebSocket and serviced by the webSocketMessage/Close handlers
    # below, so the Durable Object is evicted from memory while a room is idle and
    # bills ~no duration. Connection state lives in the runtime
    # (ctx.getWebSockets("chat")), never in instance attributes — those would not
    # survive eviction. The read-only "observer" count socket was retired: the
    # live count is now served over HTTP via the cached /api/network/stats.
    traffic_binding = "FORKMESH_MAINNODE_ROOM"

    async def fetch(self, request):
        parsed_url = urlparse(request.url)
        path = parsed_url.path
        if (
            path.rstrip("/") == "/api/chat/agent-guestbook"
            and method_name(request) == "POST"
        ):
            return await self._agent_guestbook(request)
        private_path = (
            CHAT_CHANNEL_DO_RE.match(path)
            or CHAT_DIRECT_MESSAGE_DO_RE.match(path)
        )
        if (
            private_path
            and private_path.group(3) == "revoke"
            and method_name(request) == "POST"
        ):
            self._close_all_chat_sockets(1008, "room access revoked")
            return json_response({"ok": True})
        if (
            private_path
            and private_path.group(3) == "read"
            and method_name(request) == "POST"
        ):
            reader = parse_qs(
                parsed_url.query, keep_blank_values=False
            ).get("account") or [""]
            self._send_to_other_accounts(
                reader[0], chat_direct_read_frame())
            await durable_object_traffic_flush(self)
            return json_response({"ok": True})
        if (
            private_path
            and private_path.group(3) == "delivered"
            and method_name(request) == "POST"
        ):
            query = parse_qs(parsed_url.query, keep_blank_values=False)
            refs = chat_direct_refs(query.get("ref") or [])
            if not refs:
                return json_response({"error": "invalid_ref"}, status=400)
            self._send_to_other_accounts(
                (query.get("account") or [""])[0],
                chat_direct_delivered_frame(refs))
            await durable_object_traffic_flush(self)
            return json_response({"ok": True})
        if (
            private_path
            and private_path.group(3) == "media"
            and method_name(request) == "POST"
        ):
            query = parse_qs(parsed_url.query, keep_blank_values=False)
            frame = chat_direct_media_frame(
                (query.get("id") or [""])[0],
                (query.get("state") or [""])[0])
            if not frame:
                return json_response({"error": "invalid_media"}, status=400)
            self._send_to_other_accounts(
                (query.get("account") or [""])[0], frame)
            await durable_object_traffic_flush(self)
            return json_response({"ok": True})
        if (
            private_path
            and private_path.group(3) == "webhook"
            and method_name(request) == "POST"
        ):
            return await self._channel_webhook(request, private_path)

        if path.rstrip("/") == "/api/chat/new-member":
            return await self._new_member(request)

        upgrade = request.headers.get("upgrade")
        is_websocket = bool(upgrade) and upgrade.lower() == "websocket"

        if not is_websocket:
            # One-shot snapshot of the live client count (used by network_stats).
            return json_response({"ok": True, "clients": self._client_count()})

        if path.endswith("/clients"):
            return json_response({"error": "observers_removed"}, status=410)

        if self._client_count() >= MAX_CONNECTIONS:
            return json_response({"error": "room_full"}, status=429)

        # The room key identifies this room across hibernation; stash it on the
        # socket so webSocketMessage can scope retained history to this room.
        account_values = parse_qs(
            parsed_url.query, keep_blank_values=False
        ).get("account") or []
        account_bi = account_values[0] if len(account_values) == 1 else ""
        info = room_key_from_path(path, account_bi)
        room_key = info["key"] if info else None

        client, server = WebSocketPair.new().object_values()
        self.ctx.acceptWebSocket(server, to_js(["chat"]))
        server.serializeAttachment(to_js({
            "id": new_socket_id(), "room": room_key,
            "channel_id": (info or {}).get("channel_id", ""),
            "channel_version": (info or {}).get("channel_version", 0),
            "direct_id": (info or {}).get("direct_id", ""),
            "direct_version": (info or {}).get("direct_version", 0),
            "account_bi": (info or {}).get("account_bi", ""),
            "last": int(Date.now()),
        }))

        # Replay retained (still-encrypted) history to the joining client so new
        # users see some recent backlog even when no peer is online to send it.
        if room_key:
            try:
                for body in await chat_history_recent(self.env, room_key):
                    replay_body = chat_history_replay_body(body)
                    try:
                        server.send(replay_body)
                    except Exception:
                        pass
                    else:
                        durable_object_traffic_note(
                            self,
                            bytes_out=len(replay_body.encode("utf-8")),
                        )
            except Exception:
                pass
            try:
                history_end = json.dumps({
                    "kind": "forkmesh-history-end",
                    "v": 1,
                }, separators=(",", ":"))
                server.send(history_end)
            except Exception:
                pass
            else:
                durable_object_traffic_note(
                    self, bytes_out=len(history_end.encode("utf-8")))
            if (info or {}).get("direct_id"):
                await self._announce_server_copies(server, only=server)
                live_budget = chat_live_budget_frame()
                try:
                    server.send(live_budget)
                except Exception:
                    pass
                else:
                    durable_object_traffic_note(
                        self, bytes_out=len(live_budget.encode("utf-8")))
            await durable_object_traffic_flush(self)

        return JsResponse.new(None, to_js({"status": 101, "webSocket": client}))

    async def _agent_guestbook(self, request):
        """Broadcast one App-authenticated cipher into public World #general."""
        try:
            body = await request.text()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not body or len(body.encode("utf-8")) > CHAT_HISTORY_MAX_BODY:
            return json_response({"error": "invalid_payload"}, status=400)
        supplied = str(
            request.headers.get("x-forkmesh-agent-guestbook") or "")
        expected = hmac.new(
            (_require_data_secret(self.env)
             + ":agent-guestbook-delivery-v1").encode(),
            body.encode(),
            "sha256",
        ).hexdigest()
        if not hmac.compare_digest(supplied, expected):
            return json_response({"error": "unauthorized"}, status=401)
        try:
            envelope = json.loads(body)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not (
            isinstance(envelope, dict)
            and envelope.get("kind") == "cipher"
            and envelope.get("v") == 1
            and envelope.get("persist") is True
        ):
            return json_response({"error": "invalid_payload"}, status=400)
        if not await self._retention_ingress_admitted(len(body.encode("utf-8"))):
            return json_response({"error": "rate_limited"}, status=429)

        retained_at = int(Date.now())
        msg_id = (await sha256_hex(body))[:40]
        await chat_history_store(
            self.env, PUBLIC_WORLD_GENERAL_ROOM_KEY, msg_id, retained_at, body)
        try:
            await push_chat_room_apns(self.env, PUBLIC_WORLD_GENERAL_ROOM_KEY)
        except Exception:
            pass
        frame_bytes = len(body.encode("utf-8"))
        delivered = 0
        for peer in self._live_chat_sockets(close_stale=True):
            try:
                peer.send(body)
            except Exception:
                continue
            delivered += 1
            durable_object_traffic_note(self, bytes_out=frame_bytes)
        durable_object_traffic_note(
            self, bytes_in=frame_bytes, messages=1)
        await durable_object_traffic_flush(self)
        return json_response({"ok": True, "delivered": delivered})

    async def _channel_webhook(self, request, match):
        """Broadcast and retain one Worker-authenticated webhook cipher."""
        try:
            body = await request.text()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not body or len(body.encode("utf-8")) > CHAT_HISTORY_MAX_BODY:
            return json_response({"error": "invalid_payload"}, status=400)
        supplied = str(
            request.headers.get("x-forkmesh-chat-webhook") or "")
        expected = hmac.new(
            (_require_data_secret(self.env)
             + ":chat-webhook-delivery-v1").encode(),
            body.encode(),
            "sha256",
        ).hexdigest()
        if not hmac.compare_digest(supplied, expected):
            return json_response({"error": "unauthorized"}, status=401)
        try:
            envelope = json.loads(body)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not (
            isinstance(envelope, dict)
            and envelope.get("kind") == "cipher"
            and envelope.get("v") == 1
            and envelope.get("persist") is True
        ):
            return json_response({"error": "invalid_payload"}, status=400)
        if not await self._retention_ingress_admitted(len(body.encode("utf-8"))):
            return json_response({"error": "rate_limited"}, status=429)

        room_key = (
            "chat-channel:" + match.group(1) + ":v" + match.group(2))
        envelope.pop("historyReplay", None)
        envelope.pop("recipients", None)
        envelope.pop("recipientNames", None)
        body = json.dumps(envelope, separators=(",", ":"))
        msg_id = (await sha256_hex(body))[:40]
        peers = self._live_chat_sockets(close_stale=True)
        try:
            recipients = await chat_room_recipients(
                self.env, match.group(1), "", "",
                [_ws_attr(peer, "account_bi", "") for peer in peers])
        except Exception:
            recipients = None
        if recipients is not None:
            body = chat_stamp_recipients(envelope, recipients)
        await chat_history_store(
            self.env, room_key, msg_id, int(Date.now()), body)
        frame_bytes = len(body.encode("utf-8"))
        delivered = 0
        for peer in peers:
            try:
                peer.send(body)
            except Exception:
                continue
            delivered += 1
            durable_object_traffic_note(self, bytes_out=frame_bytes)
        durable_object_traffic_note(
            self, bytes_in=frame_bytes, messages=1)
        await durable_object_traffic_flush(self)
        return json_response({"ok": True, "delivered": delivered})

    async def _new_member(self, request):
        """Relay a signed "someone just joined ForkMesh" notice to the room.

        This is the one frame the relay itself originates. Clients only ever
        send encrypted "cipher" envelopes and webSocketMessage drops anything
        else, so no peer can forge a welcome; the outer Worker's HMAC and the
        one-minute freshness window keep a captured frame from being replayed.
        The notice is live-only — it is never handed to _maybe_retain, so it
        does not become part of the room's replayed history.
        """
        if method_name(request) != "POST":
            return json_response({"error": "method_not_allowed"}, status=405)
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        try:
            signature = str(
                request.headers.get("x-forkmesh-new-member") or "")
        except Exception:
            signature = ""
        name = _new_member_announcement(
            self.env, data, signature, int(Date.now()))
        if not name:
            return json_response({"error": "unauthorized"}, status=401)
        frame = json.dumps(
            {"kind": "forkmesh-new-member", "v": 1, "name": name},
            separators=(",", ":"))
        frame_bytes = len(frame.encode("utf-8"))
        delivered = 0
        for peer in self._live_chat_sockets(close_stale=True):
            try:
                peer.send(frame)
            except Exception:
                continue
            delivered += 1
            durable_object_traffic_note(self, bytes_out=frame_bytes)
        await durable_object_traffic_flush(self)
        return json_response({"ok": True, "delivered": delivered})

    def _client_count(self):
        try:
            return len(self._live_chat_sockets(close_stale=True))
        except Exception:
            return 0

    def _live_chat_sockets(self, close_stale=False):
        now = int(Date.now())
        sockets = []
        try:
            peers = self.ctx.getWebSockets("chat")
        except Exception:
            return sockets
        for peer in peers:
            try:
                last = int(_ws_attr(peer, "last", 0) or 0)
            except (TypeError, ValueError):
                last = 0
            if not last or now - last > ROOM_CLIENT_STALE_MS:
                if close_stale:
                    self._safe_close(peer, 1001, "stale")
                continue
            sockets.append(peer)
        return sockets

    def _rate_ok(self, ws):
        # Per-socket token bucket kept in the hibernation attachment: at most
        # ROOM_MSG_MAX_PER_WINDOW frames per ROOM_MSG_WINDOW_MS. Returns False when
        # the sender is over budget (the frame should be dropped).
        now = int(Date.now())
        try:
            start = int(_ws_attr(ws, "rl_start", 0) or 0)
            count = int(_ws_attr(ws, "rl_count", 0) or 0)
        except (TypeError, ValueError):
            start, count = 0, 0
        if now - start >= ROOM_MSG_WINDOW_MS:
            start, count = now, 0
        count += 1
        self._write_attachment(ws, last=now, rl_start=start, rl_count=count)
        return count <= ROOM_MSG_MAX_PER_WINDOW

    def _write_attachment(self, ws, **changes):
        values = {
            "id": _ws_attr(ws, "id"), "room": _ws_attr(ws, "room"),
            "channel_id": _ws_attr(ws, "channel_id", ""),
            "channel_version": _ws_attr(ws, "channel_version", 0),
            "direct_id": _ws_attr(ws, "direct_id", ""),
            "direct_version": _ws_attr(ws, "direct_version", 0),
            "account_bi": _ws_attr(ws, "account_bi", ""),
        }
        for name in ("last", "rl_start", "rl_count", "lv_start", "lv_count",
                     "lv_checked", "rc_start", "rc_count"):
            value = _ws_attr(ws, name)
            if value is not None:
                values[name] = value
        values.update(changes)
        try:
            ws.serializeAttachment(to_js(values))
        except Exception:
            pass

    def _live_rate_ok(self, ws):
        now = int(Date.now())
        try:
            start = int(_ws_attr(ws, "lv_start", 0) or 0)
            count = int(_ws_attr(ws, "lv_count", 0) or 0)
        except (TypeError, ValueError):
            start, count = 0, 0
        if now - start >= ROOM_MSG_WINDOW_MS:
            start, count = now, 0
        count += 1
        self._write_attachment(ws, last=now, lv_start=start, lv_count=count)
        return count <= ROOM_LIVE_MAX_PER_WINDOW

    def _receipt_rate_ok(self, ws):
        now = int(Date.now())
        try:
            start = int(_ws_attr(ws, "rc_start", 0) or 0)
            count = int(_ws_attr(ws, "rc_count", 0) or 0)
        except (TypeError, ValueError):
            start, count = 0, 0
        if now - start >= ROOM_MSG_WINDOW_MS:
            start, count = now, 0
        count += 1
        self._write_attachment(ws, last=now, rc_start=start, rc_count=count)
        return count <= ROOM_RECEIPT_MAX_PER_WINDOW

    async def _live_access_current(self, ws):
        now = int(Date.now())
        try:
            checked = int(_ws_attr(ws, "lv_checked", 0) or 0)
        except (TypeError, ValueError):
            checked = 0
        if checked and 0 <= now - checked < ROOM_LIVE_ACCESS_RECHECK_MS:
            return True
        if not await self._private_room_current(ws):
            return False
        self._write_attachment(ws, lv_checked=now)
        return True

    async def _relay_live(self, ws, envelope):
        if not self._live_rate_ok(ws):
            return
        if not await self._live_access_current(ws):
            self._close_all_chat_sockets(1008, "room access revoked")
            return
        message = json.dumps(
            {
                key: value for key, value in envelope.items()
                if key not in (
                    "historyReplay", "recipients", "recipientNames", "ref")
            },
            separators=(",", ":"))
        frame_bytes = len(message.encode("utf-8"))
        durable_object_traffic_note(self, bytes_in=frame_bytes, messages=1)
        sender_id = _ws_attr(ws, "id")
        for peer in self._live_chat_sockets(close_stale=True):
            if _ws_attr(peer, "id") == sender_id:
                continue
            try:
                peer.send(message)
            except Exception:
                pass
            else:
                durable_object_traffic_note(self, bytes_out=frame_bytes)
        await durable_object_traffic_flush(self)

    async def webSocketMessage(self, ws, message):
        if _maintenance_socket_closed(self.env, ws):
            return
        if not isinstance(message, str):
            self._safe_close(ws, 1003, "text frames only")
            return
        if len(message.encode("utf-8")) > MAX_TEXT_BYTES:
            self._safe_close(ws, 1009, "message too large")
            return
        live = chat_live_envelope(message) if self._direct_account(ws) else None
        if live is not None:
            await self._relay_live(ws, live)
            return
        receipt = (
            chat_direct_receipt_envelope(message)
            if self._direct_account(ws) else None)
        if receipt is not None:
            if not self._receipt_rate_ok(ws):
                return
            if not await self._private_room_current(ws):
                self._close_all_chat_sockets(1008, "room access revoked")
                return
            durable_object_traffic_note(
                self, bytes_in=len(message.encode("utf-8")))
            await self._direct_received(
                ws, receipt,
                superseded=receipt.get("kind") == "forkmesh-superseded")
            return
        # Drop frames from a socket that is flooding (don't relay or retain them).
        if not self._rate_ok(ws):
            return
        if not await self._private_room_current(ws):
            self._close_all_chat_sockets(1008, "room access revoked")
            return
        # Replay markers are server-owned transport metadata. Chat clients send
        # only encrypted envelopes; dropping plaintext controls and stripping a
        # forged replay bit prevents a peer from flushing another reader's
        # backlog or disguising a live message as retained history.
        try:
            envelope = json.loads(message)
        except Exception:
            return
        if (
            isinstance(envelope, dict)
            and envelope.get("kind") == "forkmesh-received"
        ):
            durable_object_traffic_note(
                self, bytes_in=len(message.encode("utf-8")))
            await self._direct_received(ws, envelope)
            return
        if (
            isinstance(envelope, dict)
            and envelope.get("kind") == "forkmesh-superseded"
        ):
            durable_object_traffic_note(
                self, bytes_in=len(message.encode("utf-8")))
            await self._direct_received(ws, envelope, superseded=True)
            return
        if (
            not isinstance(envelope, dict)
            or envelope.get("kind") != "cipher"
        ):
            return
        if (
            "historyReplay" in envelope
            or "recipients" in envelope
            or "recipientNames" in envelope
            or "ref" in envelope
        ):
            envelope = dict(envelope)
            envelope.pop("historyReplay", None)
            envelope.pop("recipients", None)
            envelope.pop("recipientNames", None)
            envelope.pop("ref", None)
            message = json.dumps(envelope, separators=(",", ":"))
        durable_object_traffic_note(
            self, bytes_in=len(message.encode("utf-8")), messages=1)
        ref = (await sha256_hex(message))[:40]
        sender_id = _ws_attr(ws, "id")
        peers = [
            peer for peer in self._live_chat_sockets(close_stale=True)
            if _ws_attr(peer, "id") != sender_id
        ]
        recipients = None
        direct_account = ""
        if envelope.get("persist") is True:
            recipients = await self._recipients(ws, peers)
            direct_account = self._direct_account(ws)
        if direct_account:
            envelope = dict(envelope)
            envelope["ref"] = ref
            message = json.dumps(envelope, separators=(",", ":"))
        if recipients is not None:
            message = chat_stamp_recipients(envelope, recipients)
        direct_stored = ""
        if direct_account:
            direct_stored = await self._retain_direct(
                ws, message, chat_direct_retained_id(
                    ref, direct_account, envelope.get("notify") is True))
            if direct_stored:
                await self._announce_server_copies(ws)
        frame_bytes = len(message.encode("utf-8"))
        for peer in peers:
            try:
                peer.send(message)
            except Exception:
                pass
            else:
                durable_object_traffic_note(self, bytes_out=frame_bytes)
        if recipients is not None:
            ack = chat_recipients_ack(ref, recipients)
            try:
                ws.send(ack)
            except Exception:
                pass
            else:
                durable_object_traffic_note(
                    self, bytes_out=len(ack.encode("utf-8")))
        await durable_object_traffic_flush(self)

        # Retain durable conversation messages (still encrypted) for late joiners.
        if direct_stored:
            await self._maybe_retain(ws, message, direct_stored, stored=True)
        elif not direct_account:
            await self._maybe_retain(ws, message, ref)

    def _direct_account(self, ws):
        direct_id = str(_ws_attr(ws, "direct_id", "") or "")
        account_bi = str(_ws_attr(ws, "account_bi", "") or "")
        if (
            re.fullmatch(r"[0-9a-f]{32}", direct_id)
            and re.fullmatch(r"[0-9a-f]{64}", account_bi)
        ):
            return account_bi
        return ""

    async def _retain_direct(self, ws, message, msg_id):
        room_key = _ws_attr(ws, "room")
        message_bytes = len(message.encode("utf-8"))
        if not room_key or message_bytes > CHAT_HISTORY_MAX_BODY:
            return ""
        if not await self._retention_ingress_admitted(message_bytes):
            return ""
        try:
            await chat_history_store(
                self.env, room_key, msg_id, int(Date.now()), message)
        except Exception:
            return ""
        return msg_id

    async def _direct_received(self, ws, envelope, superseded=False):
        account_bi = self._direct_account(ws)
        refs = envelope.get("refs")
        if not account_bi or not isinstance(refs, list):
            return
        remove = chat_direct_superseded if superseded else chat_direct_received
        try:
            removed = await remove(
                self.env, _ws_attr(ws, "room"), account_bi, refs)
        except Exception:
            return
        if removed and not superseded:
            self._send_to_other_accounts(
                account_bi, chat_direct_delivered_frame(
                    chat_direct_refs(refs)))
            await self._schedule_acked_prune(_ws_attr(ws, "room"))
        if removed:
            await self._announce_server_copies(ws)
            await durable_object_traffic_flush(self)

    async def _schedule_acked_prune(self, room_key, first=0):
        if not room_key:
            return
        target = (
            int(first or Date.now()) + CHAT_DIRECT_ACKED_GRACE_MS + 1000)
        try:
            await self.ctx.storage.put(CHAT_DIRECT_ACKED_ROOM_KEY, room_key)
            current = await self.ctx.storage.getAlarm()
            if current is None or int(current) > target:
                await self.ctx.storage.setAlarm(target)
        except Exception:
            pass

    async def alarm(self, alarm_info=None):
        try:
            room_key = await self.ctx.storage.get(CHAT_DIRECT_ACKED_ROOM_KEY)
        except Exception:
            return
        room_key = str(room_key or "")
        if not room_key:
            return
        first = await chat_direct_acked_prune(
            self.env, room_key, int(Date.now()))
        if first:
            await self._schedule_acked_prune(room_key, first)

    def _send_to_other_accounts(self, account_bi, frame):
        frame_bytes = len(frame.encode("utf-8"))
        for peer in self._live_chat_sockets():
            peer_account = str(_ws_attr(peer, "account_bi", "") or "")
            if not peer_account or peer_account == str(account_bi or ""):
                continue
            try:
                peer.send(frame)
            except Exception:
                continue
            durable_object_traffic_note(self, bytes_out=frame_bytes)

    async def _announce_server_copies(self, ws, only=None):
        try:
            stored = await chat_direct_server_copies(
                self.env, _ws_attr(ws, "room"))
        except Exception:
            return
        frame = chat_server_copies_frame(stored)
        frame_bytes = len(frame.encode("utf-8"))
        targets = [only] if only is not None else self._live_chat_sockets()
        for peer in targets:
            try:
                peer.send(frame)
            except Exception:
                continue
            durable_object_traffic_note(self, bytes_out=frame_bytes)

    async def _recipients(self, ws, peers):
        channel_id = str(_ws_attr(ws, "channel_id", "") or "")
        direct_id = str(_ws_attr(ws, "direct_id", "") or "")
        if not channel_id and not direct_id:
            return None
        try:
            return await chat_room_recipients(
                self.env,
                channel_id,
                direct_id,
                str(_ws_attr(ws, "account_bi", "") or ""),
                [_ws_attr(peer, "account_bi", "") for peer in peers],
            )
        except Exception:
            return None

    async def _maybe_retain(self, ws, message, msg_id="", stored=False):
        room_key = _ws_attr(ws, "room")
        if not room_key:
            return
        message_bytes = len(message.encode("utf-8"))
        if message_bytes > CHAT_HISTORY_MAX_BODY:
            return  # don't retain very large frames (e.g. file transfers)
        try:
            envelope = json.loads(message)
        except Exception:
            return
        if not (
            isinstance(envelope, dict)
            and envelope.get("persist") is True
        ):
            return
        if not stored and not await self._retention_ingress_admitted(
                message_bytes):
            return
        try:
            # The message id lives inside the ciphertext, so key retention on a
            # hash of the opaque frame (dedupes accidental re-relays).
            msg_id = msg_id or (await sha256_hex(message))[:40]
            if not stored:
                await chat_history_store(self.env, room_key, msg_id,
                                         int(Date.now()), message)
            direct_id = str(_ws_attr(ws, "direct_id", "") or "")
            account_bi = str(_ws_attr(ws, "account_bi", "") or "")
            if (
                re.fullmatch(r"[0-9a-f]{32}", direct_id)
                and re.fullmatch(r"[0-9a-f]{64}", account_bi)
            ):
                if (
                    envelope.get("notify") is True
                    and envelope.get("resend") is not True
                ):
                    await _chat_direct_message_retained(
                        self.env, direct_id, account_bi, int(Date.now()),
                        ref=msg_id[:40],
                        key_version=int(
                            _ws_attr(ws, "direct_version", 0) or 0),
                        frame=message)
            elif not direct_id and envelope.get("notify") is True:
                # A direct message names its recipient above. Every other
                # message wakes the room's audience instead. The relay only
                # sees ciphertext and clients also retain edits, reactions
                # and key advertisements, so the sender marks the frames a
                # person would want to hear about with a plaintext `notify`.
                channel_id = str(_ws_attr(ws, "channel_id", "") or "")
                if channel_id:
                    try:
                        await chat_channel_mark_read(
                            self.env, channel_id,
                            [account_bi] + [
                                _ws_attr(peer, "account_bi", "")
                                for peer in self._live_chat_sockets()],
                            int(Date.now()))
                    except Exception:
                        pass
                await push_chat_room_apns(
                    self.env, room_key,
                    channel_id=str(_ws_attr(ws, "channel_id", "") or ""),
                    sender_bi=account_bi, ref=msg_id[:40],
                    key_version=int(
                        _ws_attr(ws, "channel_version", 0) or 0))
        except Exception:
            pass

    async def _private_room_current(self, ws):
        direct_id = _ws_attr(ws, "direct_id", "")
        if direct_id:
            try:
                direct_version = int(
                    _ws_attr(ws, "direct_version", 0) or 0)
                account_bi = str(_ws_attr(ws, "account_bi", "") or "")
                if not re.fullmatch(r"[0-9a-f]{64}", account_bi):
                    return False
                await ensure_schema(self.env)
                conversation = await d1_first(
                    self.env,
                    "SELECT data,key_version "
                    "FROM chat_direct_conversations "
                    "WHERE conversation_id=?",
                    direct_id,
                )
                if (
                    not conversation
                    or int(conversation.get("key_version") or 0)
                        != direct_version
                ):
                    return False
                record = await decrypt_row(
                    self.env, conversation.get("data"))
                if not isinstance(record, dict):
                    return False
                account = await d1_first(
                    self.env,
                    "SELECT data,is_admin FROM users WHERE user_bi=?",
                    account_bi,
                )
                if not account:
                    return False
                account_record = await decrypt_row(
                    self.env, account.get("data"))
                if (
                    not account_record
                    or account_record.get("status") != "active"
                    or _account_kind(account_record) != "user"
                ):
                    return False
                participant = await d1_first(
                    self.env,
                    "SELECT 1 AS allowed FROM chat_direct_participants "
                    "WHERE conversation_id=? AND participant_bi=?",
                    direct_id,
                    account_bi,
                )
                return bool(participant)
            except Exception:
                return False

        channel_id = _ws_attr(ws, "channel_id", "")
        if not channel_id:
            return True
        try:
            channel_version = int(_ws_attr(ws, "channel_version", 0) or 0)
            account_bi = str(_ws_attr(ws, "account_bi", "") or "")
            if not re.fullmatch(r"[0-9a-f]{64}", account_bi):
                return False
            await ensure_schema(self.env)
            channel = await d1_first(
                self.env,
                "SELECT data,created_by_bi,key_version FROM chat_channels "
                "WHERE channel_id=?",
                channel_id,
            )
            if (
                not channel
                or int(channel.get("key_version") or 0) != channel_version
            ):
                return False
            channel_record = await decrypt_row(
                self.env, channel.get("data"))
            if not isinstance(channel_record, dict):
                return False
            account = await d1_first(
                self.env,
                "SELECT data,is_admin FROM users WHERE user_bi=?",
                account_bi,
            )
            if not account:
                return False
            account_record = await decrypt_row(
                self.env, account.get("data"))
            if (
                not account_record
                or account_record.get("status") != "active"
                or _account_kind(account_record) != "user"
            ):
                return False
            if hmac.compare_digest(
                str(channel.get("created_by_bi") or ""), account_bi
            ):
                return True
            if channel_record.get("kind") == "notices":
                return False
            if channel_record.get("visibility") == "public":
                return True
            membership = await d1_first(
                self.env,
                "SELECT 1 AS allowed FROM chat_channel_members "
                "WHERE channel_id=? AND member_bi=?",
                channel_id,
                account_bi,
            )
            return bool(membership)
        except Exception:
            return False

    async def _retention_ingress_admitted(self, message_bytes):
        now = int(Date.now())
        try:
            state = await self.ctx.storage.get("chat_history_ingress")
        except Exception:
            return False
        if hasattr(state, "to_py"):
            state = state.to_py()
        if not isinstance(state, dict):
            state = {}
        try:
            start = int(state.get("start") or 0)
            used = int(state.get("bytes") or 0)
        except (TypeError, ValueError):
            start = 0
            used = 0
        if now - start >= CHAT_HISTORY_INGRESS_WINDOW_MS:
            start = now
            used = 0
        if message_bytes < 0 or (
            used + message_bytes > CHAT_HISTORY_INGRESS_MAX_BYTES
        ):
            try:
                await self.ctx.storage.put(
                    "chat_history_ingress",
                    to_js({"start": start, "bytes": used}),
                )
            except Exception:
                pass
            return False
        try:
            await self.ctx.storage.put(
                "chat_history_ingress",
                to_js({"start": start, "bytes": used + message_bytes}),
            )
        except Exception:
            return False
        return True

    def _close_all_chat_sockets(self, code, reason):
        try:
            peers = self.ctx.getWebSockets("chat")
        except Exception:
            peers = []
        for peer in peers:
            self._safe_close(peer, code, reason)

    async def webSocketClose(self, ws, code, reason, was_clean):
        self._safe_close(ws, 1000, "")
        await durable_object_traffic_flush(self, force=True)

    async def webSocketError(self, ws, error):
        return

    # Hibernation events may be dispatched under either naming convention.
    web_socket_message = webSocketMessage
    web_socket_close = webSocketClose
    web_socket_error = webSocketError

    def _safe_close(self, ws, code, reason):
        try:
            ws.close(code, reason)
        except Exception:
            pass


class ForkMeshNodes(DurableObject):
    # Per-owner push channel for desktop/headless nodes, on the WebSocket
    # Hibernation API like ForkMeshRoom: sockets are accepted via
    # ctx.acceptWebSocket(["node"]) and the live set is read back from
    # ctx.getWebSockets("node"), so an idle-but-connected fleet bills ~no
    # duration. Connection state lives only in the runtime/socket attachments;
    # the one exception is a bounded latest commit target per repository,
    # retained in storage so offline nodes receive it when they reconnect.
    #
    # Relay -> node event notifications stay payload-free:
    # {"type":"event","topic","repo"} means "reconcile this repository or
    # inbox now" instead of waiting out a safety pass. Bounded replies to
    # independently signed node writes go only to the socket that sent them.
    # Repository bytes never touch this socket.
    #
    # Node -> relay is {"type":"ping"} keepalives plus the small key-signed
    # writes named in NODE_FRAME_ACCEPTS. Those are transport only: the frame
    # carries the same node/ts/sig proof the HTTPS route demands and is handed
    # to the very same handler, so holding this socket grants no authority the
    # sender did not already have — the relay cannot forge one, and a frame
    # reaches exactly the rows its signer could have written to over HTTPS.
    #
    # The one frame that crosses BETWEEN sockets is {"type":"terminal"}: the
    # website streams a provider login terminal from the account's own node
    # (node_terminal.py). Both halves of that stream already authenticated as
    # this owner to reach this object — a browser with an event ticket, a node
    # with its signed drain token — so the relay only validates the frame's
    # shape and hands it to the sockets of the opposite role. It keeps no copy
    # and mints no frame of its own, and the node, not the relay, decides
    # whether to run anything.
    traffic_binding = "FORKMESH_NODES"

    async def fetch(self, request):
        parsed_url = urlparse(request.url)
        path = parsed_url.path
        upgrade = request.headers.get("upgrade")
        is_websocket = bool(upgrade) and upgrade.lower() == "websocket"

        if not is_websocket:
            if path in (_agent_live_relay.PUBLISH_PATH,
                        _agent_live_relay.WATCH_PATH):
                return await _agent_live_relay.handle(self, request, path)
            if path.endswith("/notify"):
                # Internal-only (node_events_handler forwards only WebSocket
                # upgrades, so this action is unreachable from the public
                # router): fan one event frame out to every live node socket.
                query = parse_qs(parsed_url.query)
                frame_data = {
                    "type": "event",
                    "topic": clean_string(query.get("topic", [""])[0], 40),
                    "repo": clean_string(query.get("repo", [""])[0], 200),
                }
                if frame_data["topic"] == "direct-messages":
                    frame_data.update(_account_event_direct_fields(query))
                # A source-signed refs digest lets a headless mirror tell
                # "fetch succeeded" from "the selected peer was stale". It
                # remains only a convergence target; repository bytes and
                # write authority never use this channel.
                target_state = clean_string(
                    query.get("state", [""])[0], 64).strip().lower()
                if re.fullmatch(r"[0-9a-f]{64}", target_state):
                    frame_data["state"] = target_state
                try:
                    generation = max(0, int(
                        query.get("generation", ["0"])[0] or 0))
                except (TypeError, ValueError, OverflowError):
                    generation = 0
                if frame_data["topic"] == "commits" and target_state:
                    # Timestamp frames that predate the generation-aware
                    # sender too. The node uses this value only to discard an
                    # older replay; the signed refs digest remains the actual
                    # convergence target.
                    frame_data["generation"] = generation or int(Date.now())
                    try:
                        changed = await remember_node_commit_event(
                            self, frame_data)
                    except Exception:
                        # Do not acknowledge a commit doorbell until its latest
                        # generation is durable. The alarm owner will retry it;
                        # the catalog write that created it remains accepted.
                        return json_response(
                            {"error": "commit_replay_unavailable"}, status=503)
                    if not changed:
                        # A retry or out-of-order doorbell has already been
                        # retained. Acknowledge it without waking live nodes a
                        # second time; reconnect replay still has the newest
                        # accepted target.
                        return json_response({
                            "ok": True, "delivered": 0, "coalesced": True,
                        })
                frame = json.dumps(frame_data)
                delivered = 0
                frame_bytes = len(frame.encode("utf-8"))
                for peer in self._live_node_sockets(close_stale=True):
                    try:
                        peer.send(frame)
                        delivered += 1
                    except Exception:
                        pass
                    else:
                        durable_object_traffic_note(
                            self, bytes_out=frame_bytes, messages=1)
                await durable_object_traffic_flush(self)
                return json_response({"ok": True, "delivered": delivered})
            # One-shot snapshot of the live socket counts (internal
            # diagnostics, and the question the terminal relay asks before it
            # accepts a browser onto a machine's object). `nodes` stays the
            # role-blind total it has always been; `agents` counts the node
            # side alone, because a tab holds a socket here too.
            live = self._live_node_sockets()
            return json_response({
                "ok": True,
                "nodes": len(live),
                "agents": sum(
                    1 for peer in live
                    if str(_ws_attr(peer, "role", "node") or "node") == "node"
                ),
            })

        watching = "watch" in parse_qs(parsed_url.query)
        if len(self._live_node_sockets(close_stale=True)) >= (
                NODE_WATCH_MAX_SOCKETS if watching else NODE_EVENT_MAX_SOCKETS):
            return json_response({"error": "too_many_nodes"}, status=429)

        client, server = WebSocketPair.new().object_values()
        self._arm_keepalive_auto_response()
        self.ctx.acceptWebSocket(server, to_js(["node"]))
        # node_events_handler proved this account before selecting the object,
        # and the two ways it can do that are exactly the two roles: a browser
        # presents ?ticket= from /api/accounts/event-ticket, a node its signed
        # ?owner=&ts=&sig= drain token. Recording which one arrived is what
        # lets a terminal frame reach the opposite side of one account's own
        # stream; both roles are the same authenticated owner either way.
        role = "watch" if watching else "browser" if parse_qs(
            parsed_url.query).get("ticket", [""])[0] else "node"
        server.serializeAttachment(to_js({
            "id": new_socket_id(), "last": int(Date.now()), "role": role,
        }))
        # Capability handshake, not a grant: it only tells the node which
        # writes this relay knows how to take off the socket. A node that never
        # sees its frame named keeps using the signed HTTPS route.
        hello = json.dumps({
            "type": "hello",
            "accepts": [] if watching else list(NODE_FRAME_ACCEPTS),
            "relays": [] if watching else list(NODE_FRAME_RELAYS),
            "role": role,
            "controlBudget": {
                "windowMs": NODE_CONTROL_MSG_WINDOW_MS,
                "max": NODE_CONTROL_MSG_MAX_PER_WINDOW,
            },
        }, separators=(",", ":"))
        # Deliberately unmetered, like the 101 itself: accepting a socket must
        # stay free of D1 writes, or a fleet reconnecting after a relay deploy
        # would bill one row per node just to say hello.
        try:
            server.send(hello)
        except Exception:
            pass
        await replay_node_commit_events(self, server)
        return JsResponse.new(None, to_js({"status": 101, "webSocket": client}))

    def _arm_keepalive_auto_response(self):
        """Let the runtime answer keepalives without waking this object."""
        try:
            # Resolved lazily: a runtime without the class must not turn a
            # module-level import into a failed Worker start-up.
            pair_class = __import__("js").WebSocketRequestResponsePair
            self.ctx.setWebSocketAutoResponse(pair_class.new(
                NODE_SOCKET_KEEPALIVE_PING, NODE_SOCKET_KEEPALIVE_PONG))
        except Exception:
            # An older runtime without the API simply keeps waking for pings.
            pass

    @staticmethod
    def _socket_last_seen(peer):
        """Newest of the attachment clock and the runtime's keepalive stamp.

        Auto-answered pings never reach webSocketMessage, so the attachment
        alone would age a perfectly live node into a stale close.
        """
        try:
            last = int(_ws_attr(peer, "last", 0) or 0)
        except (TypeError, ValueError):
            last = 0
        try:
            stamp = peer.getAutoResponseTimestamp()
            if not js_nullish(stamp):
                last = max(last, int(stamp.getTime()))
        except Exception:
            pass
        return last

    def _live_node_sockets(self, close_stale=False, role=""):
        # `role` selects one side of this account's own peers for the terminal
        # relay. Event fan-out and the socket cap stay role-blind: a browser
        # tab receives the same payload-free topics a node does. A socket
        # accepted before roles existed reads as a node, which is what every
        # pre-terminal connection was.
        now = int(Date.now())
        sockets = []
        try:
            peers = self.ctx.getWebSockets("node")
        except Exception:
            return sockets
        for peer in peers:
            last = self._socket_last_seen(peer)
            if not last or now - last > NODE_SOCKET_STALE_MS:
                if close_stale:
                    self._safe_close(peer, 1001, "stale")
                continue
            if role and str(_ws_attr(peer, "role", "node") or "node") != role:
                continue
            sockets.append(peer)
        return sockets

    def _relay_terminal(self, ws, frame):
        """Hand one validated terminal frame to this account's other side.

        The relay is a wire here, not a party: it forwards to every live
        socket of the opposite role and keeps nothing. Addressing is the
        frame's own `node` and `session` — a node ignores a frame naming
        another machine, a tab ignores a session it did not open — because
        this object cannot tell which of an account's nodes holds which
        socket, and inventing that mapping would only be a second, weaker
        copy of the identity the node already proves for itself.
        """
        role = str(_ws_attr(ws, "role", "node") or "node")
        forwarded = normalize_terminal_frame(frame, role)
        if not forwarded:
            return
        payload = json.dumps(forwarded, separators=(",", ":"))
        payload_bytes = len(payload.encode("utf-8"))
        target = "node" if role == "browser" else "browser"
        for peer in self._live_node_sockets(role=target):
            try:
                peer.send(payload)
            except Exception:
                pass
            else:
                durable_object_traffic_note(
                    self, bytes_out=payload_bytes, messages=1)

    def _relay_control(self, ws, frame):
        """Hand one validated control frame to this account's other side.

        Same wire as _relay_terminal: forwarded to every live socket of the
        opposite role and never kept. The payload is sealed between the two
        devices (node_control.py), so the relay only checks its envelope.
        """
        role = str(_ws_attr(ws, "role", "node") or "node")
        forwarded = normalize_control_frame(frame, role)
        if not forwarded:
            return
        payload = json.dumps(forwarded, separators=(",", ":"))
        payload_bytes = len(payload.encode("utf-8"))
        target = "node" if role == "browser" else "browser"
        for peer in self._live_node_sockets(role=target):
            try:
                peer.send(payload)
            except Exception:
                pass
            else:
                durable_object_traffic_note(
                    self, bytes_out=payload_bytes, messages=1)

    async def webSocketMessage(self, ws, message):
        if _maintenance_socket_closed(self.env, ws):
            return
        # Nodes send {"type":"ping"} keepalives and the key-signed writes named
        # in NODE_FRAME_ACCEPTS; anything else is dropped (rate-limited) or the
        # socket is closed. Each accepted frame refreshes the socket's
        # staleness clock in its attachment.
        if not isinstance(message, str):
            self._safe_close(ws, 1003, "text frames only")
            return
        if len(message.encode("utf-8")) > NODE_EVENT_MAX_FRAME_BYTES:
            self._safe_close(ws, 1009, "message too large")
            return
        durable_object_traffic_note(
            self, bytes_in=len(message.encode("utf-8")), messages=1)
        now = int(Date.now())
        try:
            start = int(_ws_attr(ws, "rl_start", 0) or 0)
            count = int(_ws_attr(ws, "rl_count", 0) or 0)
        except (TypeError, ValueError):
            start, count = 0, 0
        try:
            decoded = json.loads(message)
        except Exception:
            decoded = None
        kind = decoded.get("type") if isinstance(decoded, dict) else None
        if str(_ws_attr(ws, "role", "node") or "node") == "watch" and \
                kind != "ping":
            return
        # Terminal frames are metered on their own window (see
        # NODE_TERMINAL_MSG_MAX_PER_WINDOW): a login session's keystrokes and
        # redraws must not spend the budget that keeps this socket's event
        # channel and signed writes working.
        terminal = kind == "terminal"
        terminal_start = _ws_attr(ws, "tl_start", 0)
        terminal_count = _ws_attr(ws, "tl_count", 0)
        control = kind == "control"
        control_start = _ws_attr(ws, "cl_start", 0)
        control_count = _ws_attr(ws, "cl_count", 0)
        if terminal:
            terminal_start, terminal_count, terminal_allowed = \
                terminal_rate_state(
                    now, terminal_start, terminal_count,
                    NODE_TERMINAL_MSG_WINDOW_MS,
                    NODE_TERMINAL_MSG_MAX_PER_WINDOW)
        elif control:
            # The same rolling-window arithmetic as the terminal, on counters
            # of its own.
            control_start, control_count, control_allowed = \
                terminal_rate_state(
                    now, control_start, control_count,
                    NODE_CONTROL_MSG_WINDOW_MS,
                    NODE_CONTROL_MSG_MAX_PER_WINDOW)
        else:
            if now - start >= NODE_EVENT_MSG_WINDOW_MS:
                start, count = now, 0
            count += 1
        try:
            ws.serializeAttachment(to_js({
                "id": _ws_attr(ws, "id"), "last": now,
                "role": _ws_attr(ws, "role", "node"),
                "rl_start": start, "rl_count": count,
                "tl_start": terminal_start, "tl_count": terminal_count,
                "cl_start": control_start, "cl_count": control_count,
            }))
        except Exception:
            pass
        if terminal:
            if terminal_allowed:
                self._relay_terminal(ws, decoded)
                await durable_object_traffic_flush(self)
            return
        if control:
            if control_allowed:
                self._relay_control(ws, decoded)
                await durable_object_traffic_flush(self)
            return
        await durable_object_traffic_flush(self)
        if not isinstance(decoded, dict):
            return
        if count > NODE_EVENT_MSG_MAX_PER_WINDOW:
            # Over budget: do no work. A dropped keepalive costs nothing, but a
            # node that diverted a write onto this socket is waiting on a
            # verdict and would otherwise be left believing it landed — answer
            # the refusal, which reads to the node exactly like an HTTPS 429
            # and puts the states back in its queue for the next flush.
            if kind == "agent-status":
                self._answer_agent_status(ws, False, [])
            elif kind == "heartbeat":
                self._answer_heartbeat(
                    ws, clean_string(str(decoded.get("ts") or ""), 20),
                    429, {"error": "rate_limited"})
            elif kind == "endpoint":
                self._answer_endpoint(
                    ws,
                    clean_string(str(decoded.get("issuedAt") or ""), 20),
                    429,
                    {"error": "rate_limited"},
                )
            return
        if kind == "ping":
            pong = json.dumps({"type": "pong"})
            try:
                ws.send(pong)
            except Exception:
                pass
            else:
                durable_object_traffic_note(
                    self, bytes_out=len(pong.encode("utf-8")))
        elif kind == "agent-status":
            await self._report_agent_status(ws, message)
        elif kind == "heartbeat":
            await self._report_heartbeat(ws, decoded)
        elif kind == "endpoint":
            await self._report_endpoint(ws, decoded)

    async def _report_heartbeat(self, ws, frame):
        """Apply the existing signed account heartbeat over this socket."""

        node = clean_string(
            str(frame.get("nodeName") or ""), MAX_NODE_NAME).lower()
        ts = clean_string(str(frame.get("ts") or ""), 20)
        sig = clean_string(str(frame.get("sig") or ""), 200)
        if not node or not ts or not sig:
            return
        if clean_string(str(frame.get("creditsRefilled") or ""), 10) in (
                "5h", "weekly"):
            # enqueue_notification fans a pings event back into this account's
            # object. Keep that rare write on the HTTP handler so a hibernation
            # callback never awaits a fetch back into its own Durable Object.
            self._answer_heartbeat(
                ws, ts, 409, {"error": "http_transport_required"})
            return

        # Transport does not confer authority. Pass the original node proof to
        # the same handler as POST /api/accounts/heartbeat; it re-checks the
        # active account, timestamp, signature, wallet binding and every write.
        body = dict(frame)
        body.pop("type", None)
        status, payload = 503, {"error": "unavailable"}
        try:
            response = await _account_heartbeat(
                self.env,
                JsRequest.new(
                    "https://forkmesh.internal/api/accounts/heartbeat",
                    to_js({
                        "method": "POST",
                        "headers": {"content-type": "application/json"},
                        "body": json.dumps(body, separators=(",", ":")),
                    }),
                ),
            )
            status = int(getattr(response, "status", 500) or 500)
            payload = await response.json()
            if hasattr(payload, "to_py"):
                payload = payload.to_py()
            if not isinstance(payload, dict):
                try:
                    payload = dict(payload)
                except Exception:
                    payload = {}
        except Exception:
            status, payload = 503, {"error": "unavailable"}
        self._answer_heartbeat(ws, ts, status, payload)
        await durable_object_traffic_flush(self)

    def _answer_heartbeat(self, ws, request_id, status, payload):
        # Correlate the verdict with the signed timestamp. The desktop keeps
        # optional refill/ack fields queued until this exact write succeeds.
        reply = json.dumps({
            "type": "heartbeat-result", "requestId": request_id,
            "status": int(status), "response": payload,
        }, separators=(",", ":"))
        try:
            ws.send(reply)
        except Exception:
            return
        durable_object_traffic_note(
            self, bytes_out=len(reply.encode("utf-8")))

    async def _report_endpoint(self, ws, frame):
        """Renew a signed HTTPS mirror lease over the node socket."""

        request_id = clean_string(
            str(frame.get("issuedAt") or ""), 20)
        node = clean_string(
            str(frame.get("node") or ""), MAX_NODE_NAME).lower()
        signature = clean_string(
            str(frame.get("signature") or ""), 200)
        if not request_id or not node or not signature:
            self._answer_endpoint(
                ws, request_id, 400, {"error": "invalid_registration"})
            return

        # Exactly the HTTPS handler remains the policy boundary. It verifies
        # the timestamp, node/account key, signature, endpoint identity, DNS,
        # live manifest and repository state. The WebSocket only avoids a new
        # stateless Worker request for the four-minute lease heartbeat.
        body = dict(frame)
        body.pop("type", None)
        status, payload = 503, {"error": "unavailable"}
        try:
            response = await https_mirror_endpoint_handler(
                self.env,
                JsRequest.new(
                    "https://forkmesh.internal/api/mirrors/https",
                    to_js({
                        "method": "POST",
                        "headers": {"content-type": "application/json"},
                        "body": json.dumps(body, separators=(",", ":")),
                    }),
                ),
            )
            status = int(getattr(response, "status", 500) or 500)
            payload = await response.json()
            if hasattr(payload, "to_py"):
                payload = payload.to_py()
            if not isinstance(payload, dict):
                try:
                    payload = dict(payload)
                except Exception:
                    payload = {}
        except Exception:
            status, payload = 503, {"error": "unavailable"}
        self._answer_endpoint(ws, request_id, status, payload)
        await durable_object_traffic_flush(self)

    def _answer_endpoint(self, ws, request_id, status, payload):
        reply = json.dumps({
            "type": "endpoint-result", "requestId": request_id,
            "status": int(status), "response": payload,
        }, separators=(",", ":"))
        try:
            ws.send(reply)
        except Exception:
            return
        durable_object_traffic_note(
            self, bytes_out=len(reply.encode("utf-8")))

    async def _report_agent_status(self, ws, message):
        """Apply a signed agent-status batch carried over the node socket."""

        try:
            frame = json.loads(message)
        except Exception:
            return
        if not isinstance(frame, dict):
            return
        node = clean_string(str(frame.get("node") or ""), MAX_NODE_NAME).lower()
        ts = clean_string(str(frame.get("ts") or ""), 20)
        sig = clean_string(str(frame.get("sig") or ""), 200)
        statuses = frame.get("statuses")
        if not node or not ts or not sig or not isinstance(statuses, list):
            return
        # An in-process handler call, not a subrequest: this is the whole point
        # of moving the write onto the socket.
        target = (
            "https://forkmesh.internal/api/tasks/agent-status?node="
            + quote(node, safe="") + "&ts=" + quote(ts, safe="")
            + "&sig=" + quote(sig, safe="")
        )
        body = json.dumps({"statuses": statuses}, separators=(",", ":"))
        ok, results = False, []
        try:
            response = await organization_tasks_handler(
                self.env,
                JsRequest.new(target, to_js({
                    "method": "POST",
                    "headers": {"content-type": "application/json"},
                    "body": body,
                })),
                "/api/tasks/agent-status",
            )
            status = int(getattr(response, "status", 500) or 500)
            payload = await response.json()
            if hasattr(payload, "to_py"):
                payload = payload.to_py()
            if not isinstance(payload, dict):
                # Same coercion as remote_mcp._remote_mcp_task_request: a
                # converted JS object is mapping-like without being a dict.
                try:
                    payload = dict(payload)
                except Exception:
                    payload = {}
            ok = 200 <= status < 300
            if ok:
                results = [
                    entry for entry in (payload.get("results") or [])
                    if isinstance(entry, dict)
                ]
        except Exception:
            ok, results = False, []
        # Always answer, including on refusal: the node marks these states
        # published optimistically, and an unanswered frame would leave a run
        # showing its old state on the board until something else changed.
        self._answer_agent_status(ws, ok, results)
        await durable_object_traffic_flush(self)

    def _answer_agent_status(self, ws, ok, results):
        reply = json.dumps({
            "type": "agent-status-result", "ok": bool(ok), "results": results,
        }, separators=(",", ":"))
        try:
            ws.send(reply)
        except Exception:
            return
        durable_object_traffic_note(
            self, bytes_out=len(reply.encode("utf-8")))

    async def webSocketClose(self, ws, code, reason, was_clean):
        self._safe_close(ws, 1000, "")
        await durable_object_traffic_flush(self, force=True)

    async def webSocketError(self, ws, error):
        return

    # Hibernation events may be dispatched under either naming convention.
    web_socket_message = webSocketMessage
    web_socket_close = webSocketClose
    web_socket_error = webSocketError

    def _safe_close(self, ws, code, reason):
        try:
            ws.close(code, reason)
        except Exception:
            pass
